/**
 * 负责将引擎请求适配为 ACP 会话和会话绑定的 MCP 行动。输入为 World、解析后的选项与请求；输出为已接受工具及回合记录。默认生产回退只把脱离玩家观察交给策略，显式特权驱动单列测试接口。原回合 owner 持有期限、取消和关闭；ACP 文本与 update 不提交游戏行动。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { inheritRequestAlias } from "../../../core/domain/request_delivery";
import { allowsActionFallback, resolveTurnConstraints } from "../../../game/gateway/turn-constraints";
import type { ErrorDiagnostic } from "@ai-werewolf-arena/replay-contract";
import { describeError, formatErrorDiagnostic } from "../../../utils/error_diagnostic";
import { text, type Locale } from "@ai-werewolf-arena/game-text";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionProvider, ActionRequest, ToolCall } from "../../../core/domain";
import { World } from "../../../core/domain/world";
import {
  getDefaultConfigRenderRegistry,
  getDefaultPhaseStageLocalizationRegistry,
  getDefaultRoleCatalog,
  getDefaultTargetHintRegistry,
  getDefaultToolSpecRegistry,
  type RoleCatalog,
} from "../../../game/mechanisms";
import { safeRecordLogicOp } from "../../../recording/session_recorder";
import {
  AcpSession,
  AcpSessionAuditTrace,
  AcpSessionFactory,
} from "../../integrations/acp/session";
import {
  awaitBeforeDeadline,
  awaitWithAbort,
  TurnDeadlineElapsed,
  settleWithin,
} from "../../runtime/turn_deadline";
import { AcpSessionPool } from "./session_pool";
import {
  AcpBugReport,
  AcpTurnRegistry,
  McpBridgeResult,
} from "../../integrations/acp/acp_turn_registry";
import {
  ObservationFallbackActionProvider,
  ObservationFallbackStrategy,
} from "../providers/observation-fallback";
import type { ObservedPlayerStrategy } from "../../../game/observation/player-observation";
import { AgentBugReportService } from "../reporting/bug_report_service";
import { encodePlayerVisibleEventBatch, parsePlayerVisibleEvents } from "../visible_event_protocol";
import { BuiltPlayerPrompt, PlayerRoundOutcome } from "../player/contracts";
import { PlayerPromptPolicy } from "../player/player_prompt_policy";
import { PlayerRoundRecorder } from "../../../app/player-round-recorder";
import { ScopedRequestScheduler } from "../../runtime/request_scheduler";
import { LlmObserver } from "../player/player_observer";

export interface AcpActionProviderOptions {
  /** 生产自定义选择只接收脱离的玩家观察，不获得原请求或 World。 */
  fallbackStrategy?: ObservedPlayerStrategy;
  /** 显式特权测试驱动；生产运行装配不注入，保留原请求身份和取消测试。 */
  privilegedFallbackProvider?: ActionProvider;
  sessionFactory?: AcpSessionFactory;
  sessionFactoryResolver?: (actorId: number) => AcpSessionFactory;
  boardConfig?: ReadonlyBoardConfig;
  personalityPromptResolver?: (request: ActionRequest, role?: RoleComponent) => string | undefined;
  turnTimeoutMs?: number;
  onBugReport?: (report: AcpBugReport) => void;
  maxConcurrentRequests?: number;
  trace?: boolean;
  displayLocale?: Locale;
  colorizeLogs?: boolean;
  printLlmIo?: boolean;
  printThinking?: boolean;
  roleCatalog?: RoleCatalog;
}

interface AcpTurnPromptBuild {
  prompt: string;
  userPrompt: string;
  turnId: string;
  eventCursorBefore: number;
  eventCursorAfter: number;
}

interface AcpTurnOutcome {
  action: ToolCall | null;
  reason?: string;
  requestError?: ErrorDiagnostic;
}

/**
 * 将 ACP Agent 适配为游戏 ActionProvider。
 *
 * Agent 的文本与 ACP update 仅用于可观测；只有注入的 werewolf-game MCP
 * server 的 submit_action tool 才会被返回给游戏引擎。
 */
export class AcpActionProvider implements ActionProvider {
  private readonly registry: AcpTurnRegistry;
  private readonly sessions = new AcpSessionPool((actorId) => {
    this.eventCursor.delete(actorId);
    this.sessionPromptByActor.delete(actorId);
  });
  private readonly fallbackProvider: ActionProvider;
  private readonly eventCursor = new Map<number, number>();
  private readonly sessionPromptByActor = new Map<number, string>();
  private readonly bugReportService: AgentBugReportService;
  private readonly promptPolicy: PlayerPromptPolicy;
  private readonly roundRecorder: PlayerRoundRecorder;
  private readonly pending = new Set<Promise<ToolCall | null>>();
  private readonly controllers = new Map<number, AbortController>();
  private readonly closeController = new AbortController();
  private closed = false;
  private readonly scheduler: ScopedRequestScheduler;
  private readonly observer: LlmObserver;

  constructor(
    world: World,
    private readonly options: AcpActionProviderOptions,
  ) {
    this.observer = new LlmObserver({
      transport: "acp",
      trace: options.trace ?? false,
      locale: options.displayLocale ?? world.locale,
      colorizeLogs: options.colorizeLogs,
      printLlmIo: options.printLlmIo ?? false,
      printThinking: options.printThinking ?? false,
    });
    this.scheduler = new ScopedRequestScheduler({
      defaultMaxConcurrentRequests: options.maxConcurrentRequests ?? Infinity,
      onWait: ({ request, queueDepth, active, limit }) =>
        this.observer.trace(
          `request_queue_wait player=${request.actorId} phase=${request.phase} queue_depth=${queueDepth} active=${active}/${limit}`,
        ),
    });
    const roleCatalog = options.roleCatalog ?? getDefaultRoleCatalog();
    this.bugReportService = new AgentBugReportService(world);
    this.registry = new AcpTurnRegistry(
      world,
      (report) => this.handleBugReport(report),
      roleCatalog,
    );
    const localization = getDefaultPhaseStageLocalizationRegistry();
    this.promptPolicy = new PlayerPromptPolicy(world, {
      personalityPromptResolver: options.personalityPromptResolver,
      toolSpecRegistry: getDefaultToolSpecRegistry(),
      roleCatalog,
      targetHintRegistry: getDefaultTargetHintRegistry(),
      phaseStageLocalizationRegistry: localization,
      configRenderRegistry: getDefaultConfigRenderRegistry(),
      boardConfig: options.boardConfig,
    });
    this.fallbackProvider =
      options.privilegedFallbackProvider ??
      new ObservationFallbackActionProvider(
        (request) => this.promptPolicy.buildObservation(request),
        options.fallbackStrategy ?? new ObservationFallbackStrategy(world.locale),
      );
    this.roundRecorder = new PlayerRoundRecorder(world);
  }

  get runtimeState() {
    return {
      closed: this.closed,
      turns: this.pending.size,
      registry: this.registry.snapshot,
      pool: this.sessions.snapshot,
      scheduler: this.scheduler.snapshot,
    };
  }

  getAction(request: ActionRequest): Promise<ToolCall | null> {
    if (this.closed) return Promise.reject(new Error("acp_provider_closed"));
    if (this.sessions.hasUnreclaimedResources)
      return Promise.reject(new Error("acp_resource_reclamation_failed"));
    if (this.controllers.has(request.actorId))
      return Promise.reject(new Error("acp_actor_turn_already_open"));
    const startedAt = Date.now();
    const bounded = {
      ...request,
      deadlineAtMs: Math.min(
        request.deadlineAtMs ?? Infinity,
        startedAt + (this.options.turnTimeoutMs ?? 45_000),
      ),
    };
    inheritRequestAlias(request, bounded);
    const controller = new AbortController();
    this.controllers.set(request.actorId, controller);
    const timer = setTimeout(
      () => controller.abort(new TurnDeadlineElapsed()),
      Math.max(0, bounded.deadlineAtMs - Date.now()),
    );
    let resolve!: (action: ToolCall | null) => void, reject!: (error: unknown) => void;
    const task = new Promise<ToolCall | null>((done, fail) => {
      resolve = done;
      reject = fail;
    });
    this.pending.add(task);
    void this.runScheduled(bounded, startedAt, controller.signal).then(resolve, reject);
    const cleanup = () => {
      clearTimeout(timer);
      this.controllers.delete(request.actorId);
      this.pending.delete(task);
    };
    return task.then(
      (action) => {
        cleanup();
        if (this.closed) return this.closedResult(request);
        if (
          bounded.context.action_failure_policy === "error" &&
          (controller.signal.aborted || bounded.deadlineAtMs <= Date.now())
        )
          throw new Error("action_turn_failed");
        return action;
      },
      (error) => {
        cleanup();
        throw error;
      },
    );
  }

  private async runScheduled(
    request: ActionRequest,
    startedAt: number,
    signal: AbortSignal,
  ): Promise<ToolCall | null> {
    let release: (() => void) | undefined;
    try {
      release = await this.scheduler.acquire(request, undefined, signal);
      this.observer.trace(
        `request_start player=${request.actorId} phase=${request.phase} tools=${request.allowedTools.join(",")} timeout_ms=${Math.max(0, request.deadlineAtMs! - Date.now())}`,
      );
      return await this.runTurn(request, startedAt, signal);
    } catch (error) {
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      // 排队期限已耗尽后不新启模型／会话；原 runTurn 失败／回退分支仍在原时点处理该到期请求。
      if (!release && describeError(error).code === "request_timeout")
        return this.runTurn(request, startedAt, signal);
      throw error;
    } finally {
      // 未知或失败的回收不能变成新模型空位；关闭本 provider 等待者，只有显式新 runtime 才能重新装配。
      if (this.sessions.hasUnreclaimedResources)
        this.scheduler.close(new Error("acp_resource_reclamation_failed"));
      release?.();
    }
  }

  private async runTurn(
    request: ActionRequest,
    startedAt: number,
    signal: AbortSignal,
  ): Promise<ToolCall | null> {
    if (this.closed) return this.closedResult(request);
    const deadlineAtMs = request.deadlineAtMs!;
    let session: AcpSession | undefined;
    let turn: ReturnType<AcpTurnRegistry["openTurn"]> | undefined;
    let built: AcpTurnPromptBuild | undefined;
    let auditTrace: AcpSessionAuditTrace | undefined;
    let fallbackReason = "model_declined_required_action";
    let requestError: ErrorDiagnostic | undefined;
    let actionFailureReason: string | undefined;
    try {
      if (this.sessions.isClosed || deadlineAtMs <= Date.now())
        throw new Error("acp_deadline_elapsed");
      session = await awaitWithAbort(
        this.sessions.getOrCreate(request.actorId, deadlineAtMs, () => {
          const factory =
            this.options.sessionFactoryResolver?.(request.actorId) ?? this.options.sessionFactory;
          if (!factory) throw new Error("acp_session_factory_missing");
          const initialPrompt = this.buildSessionPrompt(request);
          this.observer.prompt([{ role: "system", content: initialPrompt }], request);
          if (this.closed) throw this.closeController.signal.reason;
          this.sessionPromptByActor.set(request.actorId, initialPrompt);
          return {
            factory,
            input: { actorId: request.actorId, registry: this.registry, initialPrompt },
          };
        }),
        signal,
      );
      if (this.sessions.isClosed || deadlineAtMs <= Date.now())
        throw new Error("acp_deadline_elapsed");
      turn = this.registry.openTurn(request, session.sessionId);
      built = this.buildTurnPrompt(request, turn.turnId, true);
      this.observer.prompt([{ role: "user", content: built.prompt }], request);
      if (this.closed) return this.closedResult(request);
      const promptTask = session.prompt(built.prompt);
      const outcome = await awaitWithAbort(
        this.waitForAction(turn.action, promptTask, request),
        signal,
      );
      if (this.closed) return this.closedResult(request);
      this.registry.closeTurn(turn.sessionId);
      if (outcome.reason === "request_timeout" || outcome.reason === "deadline_skip") {
        await this.sessions.discard(request.actorId);
      } else {
        let cancelled = true;
        try {
          await awaitBeforeDeadline(
            () => session!.cancel(),
            Math.min(deadlineAtMs, Date.now() + 300),
            signal,
          );
        } catch (error) {
          if (error === this.closeController.signal.reason) return this.closedResult(request);
          cancelled = false;
          // 有界取消超时触发强制回收；真实 RPC／adapter 失败仍归本 owner，最终 close 按原规则报告。
          if (!(error instanceof TurnDeadlineElapsed)) this.sessions.noteCleanupFailure(error);
        }
        if (
          !cancelled ||
          !(await settleWithin(promptTask, Math.min(1_000, Math.max(0, deadlineAtMs - Date.now()))))
        ) {
          await this.sessions.discard(request.actorId);
        }
      }
      if (this.closed) return this.closedResult(request);
      if (signal.aborted || deadlineAtMs <= Date.now())
        throw signal.reason ?? new Error("acp_deadline_elapsed");
      auditTrace = session.takeAuditTrace?.();
      if (this.closed) return this.closedResult(request);
      if (outcome.action) {
        this.observer.trace(
          `request_ok player=${request.actorId} phase=${request.phase} action=${outcome.action.name} args=${JSON.stringify(outcome.action.args)} elapsed_ms=${Date.now() - startedAt}`,
        );
        this.recordPlayerRound(request, built, {
          action: outcome.action,
          auditTrace,
          elapsedMs: Date.now() - startedAt,
        });
        this.rejectLateDelivery(request, built, startedAt);
        return this.closed ? this.closedResult(request) : outcome.action;
      }
      if (
        outcome.reason === "model_declined_required_action" &&
        resolveTurnConstraints(request).minValidActions === 0 &&
        (request.context.action_failure_policy !== "error" || turn.outcome.rejectedActions === 0)
      ) {
        this.observer.trace(
          `request_none player=${request.actorId} phase=${request.phase} elapsed_ms=${Date.now() - startedAt}`,
        );
        this.recordPlayerRound(request, built, {
          action: null,
          auditTrace,
          elapsedMs: Date.now() - startedAt,
        });
        this.rejectLateDelivery(request, built, startedAt);
        return null;
      }
      if (request.context.action_failure_policy === "error" && turn.outcome.rejectedActions) {
        fallbackReason = turn.outcome.failureCode ?? "action_turn_failed";
        actionFailureReason = fallbackReason;
      } else fallbackReason = outcome.reason ?? fallbackReason;
      requestError = outcome.requestError ?? requestError;
    } catch (error) {
      await this.sessions.discard(request.actorId);
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      fallbackReason = "runtime_error";
      requestError = describeError(error);
      this.observer.trace(
        `request_transport_fail player=${request.actorId} phase=${request.phase} err=${formatErrorDiagnostic(error, this.observer.locale)}`,
      );
      if (this.closed) return this.closedResult(request);
      safeRecordLogicOp({
        scope: "llm_action_provider",
        op: "action_provider_error",
        actorId: request.actorId,
        phase: request.phase,
        status: "fallback",
        reason: requestError.code,
        output: { diagnostic: requestError },
      });
    } finally {
      if (turn) {
        this.registry.closeTurn(turn.sessionId);
      }
    }
    if (this.closed) return this.closedResult(request);
    built ??= this.buildTurnPrompt(request, turn?.turnId ?? "unopened", false);
    auditTrace ??= session?.takeAuditTrace?.();
    if (this.closed) return this.closedResult(request);
    let fallback: ToolCall | null;
    try {
      fallback = allowsActionFallback(request)
        ? await awaitBeforeDeadline(
            () => this.fallbackProvider.getAction(request),
            deadlineAtMs,
            this.closeController.signal,
          )
        : null;
    } catch (error) {
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      if (!(error instanceof TurnDeadlineElapsed)) throw error;
      fallback = null;
      fallbackReason = "deadline_skip";
    }
    if (this.closed) return this.closedResult(request);
    this.observer.trace(
      `request_recovered player=${request.actorId} phase=${request.phase} reason=${fallbackReason} fallback=${fallback?.name ?? "none"}`,
    );
    this.recordPlayerRound(request, built, {
      action: fallback,
      auditTrace,
      elapsedMs: Date.now() - startedAt,
      fallbackReason,
      requestError,
      actionFailureReason,
    });
    if (!this.closed && request.context.action_failure_policy === "error" && !fallback)
      throw new Error("action_turn_failed");
    return this.closed ? this.closedResult(request) : fallback;
  }

  async close(): Promise<void> {
    this.closed = true;
    this.closeController.abort(new DOMException("acp_provider_closed", "AbortError"));
    this.scheduler.close(this.closeController.signal.reason);
    this.registry.close();
    for (const controller of this.controllers.values())
      controller.abort(this.closeController.signal.reason);
    const failures: unknown[] = [];
    const closing = this.sessions.close().catch((error) => {
      failures.push(error);
    });
    const settled = await Promise.allSettled([...this.pending]);
    for (const result of settled)
      if (result.status === "rejected" && result.reason !== this.closeController.signal.reason)
        failures.push(result.reason);
    await closing;
    this.eventCursor.clear();
    this.sessionPromptByActor.clear();
    if (failures.length) throw new AggregateError(failures, "acp_provider_close_failed");
  }

  private async waitForAction(
    action: Promise<ToolCall | null>,
    promptTask: Promise<void>,
    request: ActionRequest,
  ): Promise<AcpTurnOutcome> {
    const timeoutMs = this.resolveTimeoutMs(request);
    if (timeoutMs <= 0) {
      return { action: null, reason: "deadline_skip" };
    }
    let timer: NodeJS.Timeout | undefined;
    try {
      return await Promise.race([
        action.then((value) => ({ action: value })),
        // 原竞速在 Agent 回合完成而未提交时进入回退，不继续等待整段 LLM 超时；
        // action／prompt 的原 Promise 顺序和拒绝原因保持，不把完成文本当领域提交。
        promptTask.then(
          (): AcpTurnOutcome => ({ action: null, reason: "model_declined_required_action" }),
          (error): AcpTurnOutcome => ({
            action: null,
            reason: "runtime_error",
            requestError: describeError(error),
          }),
        ),
        new Promise<AcpTurnOutcome>((resolve) => {
          timer = setTimeout(() => resolve({ action: null, reason: "request_timeout" }), timeoutMs);
        }),
      ]);
    } finally {
      if (timer) clearTimeout(timer);
    }
  }

  private resolveTimeoutMs(request: ActionRequest): number {
    const configured = this.options.turnTimeoutMs ?? 45_000;
    const remaining =
      request.deadlineAtMs === undefined
        ? configured
        : Math.max(0, request.deadlineAtMs - Date.now());
    return Math.min(configured, remaining);
  }
  private closedResult(request: ActionRequest): null {
    if (request.context.action_failure_policy === "error") throw this.closeController.signal.reason;
    return null;
  }
  private rejectLateDelivery(
    request: ActionRequest,
    built: AcpTurnPromptBuild,
    startedAt: number,
  ): void {
    if (
      request.context.action_failure_policy !== "error" ||
      (request.deadlineAtMs ?? Infinity) > Date.now()
    )
      return;
    this.recordPlayerRound(request, built, {
      action: null,
      elapsedMs: Date.now() - startedAt,
      requestError: { code: "request_timeout" },
    });
    throw new Error("action_turn_failed");
  }

  /** 创建 session 时复用 LLM provider 的既有身份、规则和板子系统提示。 */
  private buildSessionPrompt(request: ActionRequest): string {
    return this.promptPolicy.buildSystem(request, {
      supportsDebugReporting: true,
      includeToolUseInstructions: false,
    }).systemPrompt;
  }

  /** 回合提示遵循既有阶段规则、目标提示与可见事件增量结构。 */
  private buildTurnPrompt(
    request: ActionRequest,
    turnId: string,
    advanceCursor: boolean,
  ): AcpTurnPromptBuild {
    const lines: string[] = [];
    const events = parsePlayerVisibleEvents(request.context.visible_events);
    const cursor = this.eventCursor.get(request.actorId) ?? 0;
    const delta = events.filter((event) => event.seq > cursor);
    const nextCursor = events.reduce((maxSeq, event) => Math.max(maxSeq, event.seq), cursor);
    if (advanceCursor) this.eventCursor.set(request.actorId, nextCursor);
    if (delta.length) {
      lines.push(
        text(this.promptPolicy.locale, "prompt.acp.events", {
          events: encodePlayerVisibleEventBatch(delta),
        }),
      );
    }
    lines.push(text(this.promptPolicy.locale, "prompt.acp.turn", { turn: turnId }));
    const userPrompt = this.promptPolicy.buildUser(request, {
      turnId,
      allowedTools: request.allowedTools,
      actionSubmissionHint: text(this.promptPolicy.locale, "prompt.acp.submit", { turn: turnId }),
    });
    lines.push(userPrompt);
    return {
      prompt: lines.filter(Boolean).join("\n"),
      userPrompt,
      turnId,
      eventCursorBefore: cursor,
      eventCursorAfter: advanceCursor ? nextCursor : cursor,
    };
  }

  /** 将 ACP 回合映射到与直接 LLM 路径相同的玩家审计结构。 */
  private recordPlayerRound(
    request: ActionRequest,
    built: AcpTurnPromptBuild,
    input: {
      action: ToolCall | null;
      auditTrace?: AcpSessionAuditTrace;
      elapsedMs: number;
      fallbackReason?: string;
      requestError?: ErrorDiagnostic;
      actionFailureReason?: string;
    },
  ): void {
    if (this.closed) return;
    const systemPrompt =
      this.sessionPromptByActor.get(request.actorId) ?? this.buildSessionPrompt(request);
    if (this.closed) return;
    const thinkingText = this.formatAuditTrace(input.auditTrace);
    const actionArgs = input.action
      ? ((input.action.args ?? {}) as Record<string, unknown>)
      : undefined;
    const prompt: BuiltPlayerPrompt = {
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: built.userPrompt },
      ],
      systemPrompt,
      userPrompt: built.userPrompt,
      boardInfoPrompt: this.promptPolicy.buildBoardInfo(),
      isInitialRound: false,
      eventCursorBefore: built.eventCursorBefore,
      eventCursorAfter: built.eventCursorAfter,
      contextWindowStart: 0,
      contextWindowEnd: 0,
      contextWindowTotal: 0,
      turnId: built.turnId,
      auditMetadata: [
        `transport=acp_mcp;turn_id=${built.turnId};event_cursor=${built.eventCursorBefore}->${built.eventCursorAfter};elapsed_ms=${input.elapsedMs}`,
      ],
    };
    const outcome: PlayerRoundOutcome = {
      ...(thinkingText ? { thinkingText } : {}),
      actionMode: input.action ? "tool_call" : "none",
      toolCalls: input.action
        ? [
            {
              name: input.action.name,
              args: actionArgs ?? {},
              accepted: true,
              result: {
                transport: "acp_mcp",
                turn_id: built.turnId,
              },
            },
          ]
        : [],
      finalAction: input.action,
      ...(input.requestError
        ? {
            retryTrace: [
              {
                attempt: 0,
                status: "request_error",
                reason: input.requestError.code,
                diagnostic: input.requestError,
              },
            ],
          }
        : input.actionFailureReason
          ? {
              retryTrace: [
                { attempt: 0, status: "no_valid_action", reason: input.actionFailureReason },
              ],
            }
          : {}),
      ...(input.fallbackReason
        ? {
            fallback: {
              used: allowsActionFallback(request),
              reason: input.fallbackReason,
              ...(input.action
                ? { action: { name: input.action.name, args: actionArgs ?? {} } }
                : {}),
            },
          }
        : {}),
    };
    if (!this.closed) this.roundRecorder.record(request, prompt, outcome);
  }

  private formatAuditTrace(trace?: AcpSessionAuditTrace): string | undefined {
    if (!trace) return undefined;
    const thoughts = trace.thoughts.join(" ").trim().slice(0, 2_000);
    const messages = trace.messages.join(" ").trim().slice(0, 2_000);
    const lines = [
      ...(thoughts ? [`thought: ${thoughts}`] : []),
      ...(messages ? [`message: ${messages}`] : []),
    ];
    return lines.length ? lines.join("\n") : undefined;
  }

  /** ACP report_bug 与直接 LLM 路径共享落盘语义及限流规则。 */
  private handleBugReport(report: AcpBugReport): McpBridgeResult {
    const result = this.bugReportService.report(report);
    if (result.ok && result.accepted) {
      this.options.onBugReport?.(report);
      return { ok: true, accepted: true };
    }
    return result;
  }
}

/**
 * 负责模型路径失败后的原回退调用、期限等待与记录；输入为原请求、失败原因和取消信号。
 * 输出为原回退候选或 null；是否允许回退由游戏约束决定，已注入 provider 仍按原期限调用。
 * 本模块不新增时间预算、读取角色库存或提交领域动作；取消在原记录前后重检，保留失败前缀。
 */
import { text } from "@ai-werewolf-arena/game-text";
import { ActionProvider, ActionRequest, ToolCall } from "../../../core/domain";
import { safeRecordLogicOp } from "../../../recording/session_recorder";
import { LlmObserver } from "../player/player_observer";
import { allowsActionFallback, resolveTurnConstraints } from "../../../game/gateway/turn-constraints";
import { awaitBeforeDeadline } from "../../runtime/turn_deadline";

export type FallbackReason = "runtime_error" | "deadline_skip" | "model_declined_required_action";

/** 区分本政策的期限错误与注入 provider 自己抛出的错误，原错误身份保持。 */
export { TurnDeadlineElapsed as FallbackDeadlineElapsed } from "../../runtime/turn_deadline";

/** 模型不能提供合法候选时消费已装配的回退策略；不扩大请求许可。 */
export class FallbackActionPolicy {
  constructor(
    private readonly provider: ActionProvider,
    private readonly observer: LlmObserver,
  ) {}

  async resolve(
    request: ActionRequest,
    reason: FallbackReason,
    signal?: AbortSignal,
  ): Promise<ToolCall | null> {
    // 本地同步策略仍可在耗尽期限时立即返回；异步回退不获得新预算，也不能跨过关闭继续执行。
    const action = allowsActionFallback(request)
      ? await awaitBeforeDeadline(
          () => this.provider.getAction(request),
          request.deadlineAtMs,
          signal,
        )
      : null;
    const actionText = action
      ? `${action.name} ${JSON.stringify((action as any).args ?? {})}`
      : "none";
    console.log(
      `[LLM_FALLBACK] player=${request.actorId} phase=${request.phase} reason=${reason} min_valid_actions=${resolveTurnConstraints(request).minValidActions} allowedTools=${request.allowedTools.join(",")} fallback=${actionText} · ${text(this.observer.locale, "runtime.fallback")}`,
    );
    if (signal?.aborted) throw signal.reason;
    safeRecordLogicOp({
      scope: "llm_action_provider",
      op: "llm_fallback",
      actorId: request.actorId,
      phase: request.phase,
      status: action ? "fallback" : "error",
      reason,
      output: action ? { action: action.name, args: (action as any).args ?? {} } : undefined,
    });
    if (signal?.aborted) throw signal.reason;
    this.observer.trace(
      action
        ? `request_recovered player=${request.actorId} phase=${request.phase} reason=${reason} fallback=${action.name} args=${JSON.stringify((action as any).args ?? {})}`
        : `request_dropped player=${request.actorId} phase=${request.phase} reason=${reason}`,
    );
    return action;
  }
}

/**
 * 负责将引擎请求适配为 SDK 回合编排、提示会话与记录动作。输入为原 World、只读板子和模型选项；输出为工具决定或原失败结果。默认与自定义生产回退只接收脱离的 PlayerObservation，特权注入仅供显式测试。期限、取消和关闭仍归 provider，资源提交仍归领域；不把预检或策略返回当作付款。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { Locale } from "@ai-werewolf-arena/game-text";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionProvider, ActionRequest, ToolCall } from "../../../core/domain";
import { World } from "../../../core/domain/world";
import {
  ConfigRenderRegistry,
  getDefaultConfigRenderRegistry,
  getDefaultPhaseStageLocalizationRegistry,
  getDefaultRoleCatalog,
  getDefaultTargetHintRegistry,
  getDefaultToolCallRepairRegistry,
  getDefaultToolSpecRegistry,
  PhaseStageLocalizationRegistry,
  RoleCatalog,
  TargetHintRegistry,
  ToolCallRepairRegistry,
  ToolSpecRegistry,
  ToolValidationRuleRegistry,
} from "../../../game/mechanisms";
import {
  ObservationFallbackActionProvider,
  ObservationFallbackStrategy,
} from "../providers/observation-fallback";
import type { ObservedPlayerStrategy } from "../../../game/observation/player-observation";
import { ChatModelClient } from "../../integrations/llm/transport";
import { FallbackActionPolicy } from "./fallback_action_policy";
import { LlmObserver } from "../player/player_observer";
import { PlayerPromptSession } from "./player_prompt_session";
import { PlayerPromptPolicy } from "../player/player_prompt_policy";
import { PlayerRoundRecorder } from "../../../app/player-round-recorder";
import { ScopedRequestScheduler } from "../../runtime/request_scheduler";
import { SdkGameToolLoop } from "./sdk_game_tool_loop";
import { LlmTurnOrchestrator } from "./llm_turn_orchestrator";

export interface LlmActionProviderOptions {
  maxPromptEvents?: number;
  displayLocale?: Locale;
  trace?: boolean;
  /** 生产自定义选择只接收脱离的玩家观察，不获得原请求或 World。 */
  fallbackStrategy?: ObservedPlayerStrategy;
  /** 显式特权测试驱动；生产运行装配不注入，保留原请求身份和取消测试。 */
  privilegedFallbackProvider?: ActionProvider;
  llmTimeoutMs?: number;
  colorizeLogs?: boolean;
  printLlmIo?: boolean;
  printThinking?: boolean;
  clientResolver?: (request: ActionRequest, role?: RoleComponent) => ChatModelClient;
  requestConcurrencyScopeResolver?: (
    request: ActionRequest,
    role?: RoleComponent,
  ) => string | undefined;
  maxConcurrentRequestsResolver?: (
    request: ActionRequest,
    role?: RoleComponent,
  ) => number | undefined;
  personalityPromptResolver?: (request: ActionRequest, role?: RoleComponent) => string | undefined;
  toolSpecRegistry?: ToolSpecRegistry;
  roleCatalog?: RoleCatalog;
  toolCallRepairRegistry?: ToolCallRepairRegistry;
  targetHintRegistry?: TargetHintRegistry;
  phaseStageLocalizationRegistry?: PhaseStageLocalizationRegistry;
  boardConfig?: ReadonlyBoardConfig;
  configRenderRegistry?: ConfigRenderRegistry;
  maxConcurrentRequests?: number;
}

/**
 * SDK 玩家装配入口；回合、提示状态、协议和记录由具体协作者持有。
 */
export class LlmActionProvider implements ActionProvider {
  private readonly orchestrator: LlmTurnOrchestrator;

  constructor(world: World, client: ChatModelClient, options: LlmActionProviderOptions = {}) {
    const toolSpecRegistry = options.toolSpecRegistry ?? getDefaultToolSpecRegistry();
    const roleCatalog = options.roleCatalog ?? getDefaultRoleCatalog();
    const repairRegistry = options.toolCallRepairRegistry ?? getDefaultToolCallRepairRegistry();
    const targetHintRegistry = options.targetHintRegistry ?? getDefaultTargetHintRegistry();
    const localization =
      options.phaseStageLocalizationRegistry ?? getDefaultPhaseStageLocalizationRegistry();
    const configRenderer = options.configRenderRegistry ?? getDefaultConfigRenderRegistry();
    const configuredConcurrency =
      options.maxConcurrentRequests ?? this.readConcurrencyFromEnvironment();
    const observer = new LlmObserver({
      trace: options.trace ?? false,
      locale: options.displayLocale ?? world.locale,
      colorizeLogs: options.colorizeLogs,
      printLlmIo: options.printLlmIo ?? false,
      printThinking: options.printThinking ?? false,
    });
    const scheduler = new ScopedRequestScheduler({
      defaultMaxConcurrentRequests: configuredConcurrency,
      scopeResolver: options.requestConcurrencyScopeResolver,
      limitResolver: options.maxConcurrentRequestsResolver,
      onWait: ({ request, scope, queueDepth, active, limit }) => {
        observer.trace(
          `request_queue_wait player=${request.actorId} phase=${request.phase} scope=${scope} queue_depth=${queueDepth} active=${active}/${limit}`,
        );
      },
    });
    const promptPolicy = new PlayerPromptPolicy(world, {
      personalityPromptResolver: options.personalityPromptResolver,
      toolSpecRegistry,
      roleCatalog,
      targetHintRegistry,
      phaseStageLocalizationRegistry: localization,
      configRenderRegistry: configRenderer,
      boardConfig: options.boardConfig,
    });
    const promptSession = new PlayerPromptSession({
      maxPromptEvents: options.maxPromptEvents ?? 16,
      promptPolicy,
    });
    const fallback = new FallbackActionPolicy(
      options.privilegedFallbackProvider ??
        new ObservationFallbackActionProvider(
          (request) => promptPolicy.buildObservation(request),
          options.fallbackStrategy ?? new ObservationFallbackStrategy(world.locale),
        ),
      observer,
    );
    const recorder = new PlayerRoundRecorder(world);
    const sdkToolLoop = new SdkGameToolLoop(
      world,
      repairRegistry,
      promptSession,
      observer,
      toolSpecRegistry,
      new ToolValidationRuleRegistry(undefined, roleCatalog),
    );
    this.orchestrator = new LlmTurnOrchestrator({
      world,
      defaultClient: client,
      clientResolver: options.clientResolver,
      timeoutMs: options.llmTimeoutMs ?? 1200,
      promptSession,
      scheduler,
      sdkToolLoop,
      fallbackPolicy: fallback,
      recorder,
      observer,
    });
  }

  static fromModelClient(
    world: World,
    client: ChatModelClient,
    options: LlmActionProviderOptions = {},
  ): LlmActionProvider {
    return new LlmActionProvider(world, client, options);
  }

  getAction(request: ActionRequest): Promise<ToolCall | null> {
    return this.orchestrator.run(request);
  }

  close(): Promise<void> {
    return this.orchestrator.close();
  }

  get runtimeState() {
    return this.orchestrator.runtimeState;
  }

  private readConcurrencyFromEnvironment(): number {
    const value = Number(process.env.LLM_MAX_CONCURRENT_REQUESTS ?? "");
    return Number.isFinite(value) && value > 0
      ? Math.max(1, Math.floor(value))
      : Number.POSITIVE_INFINITY;
  }
}

/**
 * 负责编排单个原生 SDK 回合；输入为原引擎请求、提示会话与模型客户端，输出为候选工具、重试／回退和玩家记录。
 * 本 owner 持有控制器、截止计时器与待结束任务；最早期限覆盖排队和各次尝试，请求绑定仍由各机制检查。
 * 并发租约只在本回合收尾时释放；每轮取消不可逆，关闭单向封住本 owner，任务兑现不等于领域提交。
 * 取消／关闭仅收走本 provider 资源，不代替规则预检或领域 commit，不扩大 fallback 的原预算。
 */
import { inheritRequestAlias } from "../../../core/domain/request_delivery";
import { text } from "@ai-werewolf-arena/game-text";
import type { ErrorDiagnostic } from "@ai-werewolf-arena/replay-contract";
import { describeError, formatErrorDiagnostic } from "../../../utils/error_diagnostic";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionRequest, ToolCall } from "../../../core/domain";
import { World } from "../../../core/domain/world";
import {
  FallbackActionPolicy,
  FallbackDeadlineElapsed,
  FallbackReason,
} from "./fallback_action_policy";
import { LlmObserver } from "../player/player_observer";
import { BuiltPlayerPrompt, PlayerRoundOutcome, PlayerRetryTraceEntry } from "../player/contracts";
import { ChatMessage, ChatModelClient } from "../../integrations/llm/transport";
import { PlayerPromptSession } from "./player_prompt_session";
import { PlayerRoundRecorder } from "../../../app/player-round-recorder";
import { buildConstraintRetryPrompt } from "../player/prompt_templates";
import { ScopedRequestScheduler } from "../../runtime/request_scheduler";
import { SdkGameToolLoop } from "./sdk_game_tool_loop";
import { allowsActionFallback, resolveTurnConstraints } from "../../../game/gateway/turn-constraints";

interface LlmTurnOrchestratorOptions {
  world: World;
  defaultClient: ChatModelClient;
  clientResolver?: (request: ActionRequest, role?: RoleComponent) => ChatModelClient;
  timeoutMs: number;
  promptSession: PlayerPromptSession;
  scheduler: ScopedRequestScheduler;
  sdkToolLoop: SdkGameToolLoop;
  fallbackPolicy: FallbackActionPolicy;
  recorder: PlayerRoundRecorder;
  observer: LlmObserver;
}

interface NativeAttempt {
  action: ToolCall | null;
  failed: boolean;
  deadlineExceeded?: boolean;
  diagnostic?: ErrorDiagnostic;
  assistantText?: string;
  refusalReason?: string;
}

/** 以原尝试顺序编排原生工具回合，已付／已记录前缀不由本服务回滚。 */
export class LlmTurnOrchestrator {
  constructor(private readonly options: LlmTurnOrchestratorOptions) {}

  private readonly controllers = new Set<AbortController>();
  private readonly pending = new Set<Promise<ToolCall | null>>();
  private readonly closeController = new AbortController();
  private closed = false;

  get runtimeState() {
    return {
      closed: this.closed,
      turns: this.pending.size,
      scheduler: this.options.scheduler.snapshot,
    };
  }

  run(request: ActionRequest): Promise<ToolCall | null> {
    if (this.closed) return Promise.reject(new DOMException("llm_provider_closed", "AbortError"));
    const startedAt = Date.now();
    // 只取引擎原期限与本次启动预算的较早者；排队和重试共用它，不为每次模型调用重新计时。
    const bounded = {
      ...request,
      deadlineAtMs: Math.min(request.deadlineAtMs ?? Infinity, startedAt + this.options.timeoutMs),
    };
    // bounded 是新请求对象：按原机制路线继承绑定，不凭 actorId 或浅复制字段重建领域许可。
    inheritRequestAlias(request, bounded);
    const controller = new AbortController();
    this.controllers.add(controller);
    const timer = setTimeout(
      () => controller.abort(new Error("request_deadline_elapsed")),
      Math.max(0, bounded.deadlineAtMs - Date.now()),
    );
    let resolve!: (action: ToolCall | null) => void, reject!: (error: unknown) => void;
    const task = new Promise<ToolCall | null>((done, fail) => {
      resolve = done;
      reject = fail;
    });
    // 在 runTurn 的提示／客户端回调开始前登记任务，让同步重入的 close 也能看到这次回合。
    this.pending.add(task);
    void this.runTurn(bounded, controller.signal, startedAt).then(resolve, reject);
    const cleanup = () => {
      clearTimeout(timer);
      this.controllers.delete(controller);
      this.pending.delete(task);
    };
    return task.then(
      (action) => {
        cleanup();
        if (this.closed) return this.closedResult(request);
        if (
          bounded.context.action_failure_policy === "error" &&
          (controller.signal.aborted || bounded.deadlineAtMs <= Date.now())
        )
          throw new Error("action_turn_failed");
        return action;
      },
      (error) => {
        cleanup();
        throw error;
      },
    );
  }

  async close(): Promise<void> {
    this.closed = true;
    this.closeController.abort(new DOMException("llm_provider_closed", "AbortError"));
    // 队列先关闭，再中止运行任务；控制器保留首次中止原因，已授予租约仍走各回合 finally。
    this.options.scheduler.close(this.closeController.signal.reason);
    for (const controller of this.controllers) controller.abort(this.closeController.signal.reason);
    const settled = await Promise.allSettled([...this.pending]);
    // 已知关闭原因按同一对象识别，其它拒绝仍汇总；allSettled 不把传输失败抹成关闭成功。
    const failures = settled.flatMap((result) =>
      result.status === "rejected" && result.reason !== this.closeController.signal.reason
        ? [result.reason]
        : [],
    );
    if (failures.length) throw new AggregateError(failures, "llm_turns_failed_during_close");
  }

  private async runTurn(
    request: ActionRequest,
    signal: AbortSignal,
    startedAt: number,
  ): Promise<ToolCall | null> {
    const role = this.options.world.getComponent(request.actorId, COMPONENT.Role);
    const client = this.options.clientResolver?.(request, role) ?? this.options.defaultClient;
    const prompt = this.options.promptSession.build(request);
    this.options.observer.trace(
      `context_window player=${request.actorId} phase=${request.phase} start=${prompt.contextWindowStart} end=${prompt.contextWindowEnd} total=${prompt.contextWindowTotal}`,
    );
    let release: (() => void) | undefined;
    try {
      release = await this.options.scheduler.acquire(request, role, signal);
      if (this.closed) return this.closedResult(request);
      if (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0) {
        return this.finishWithFallback(request, prompt, "deadline_skip");
      }
      this.options.observer.trace(
        `request_start player=${request.actorId} phase=${request.phase} tools=${request.allowedTools.join(",")} timeout_ms=${this.effectiveTimeout(request.deadlineAtMs)}`,
      );
      this.options.observer.prompt(prompt.messages, request);
      const action = await this.runNative(client, request, prompt, startedAt, signal);
      if (
        !this.closed &&
        request.context.action_failure_policy === "error" &&
        (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0)
      ) {
        return this.finishWithFallback(request, prompt, "deadline_skip", {
          retryTrace: [
            {
              attempt: 0,
              status: "request_error",
              reason: "request_timeout",
              diagnostic: { code: "request_timeout" },
            },
          ],
        });
      }
      return this.closed ? this.closedResult(request) : action;
    } catch (error) {
      const diagnostic = describeError(error);
      if (this.closed && (error === this.closeController.signal.reason || error === signal.reason))
        return this.closedResult(request);
      // 原生传输失败已由 runNative 处理；回退或记录失败只传播一次，不能再次调用回退。
      if (release) throw error;
      this.options.observer.trace(
        `${diagnostic.code === "request_timeout" ? "request_timeout" : "request_transport_fail"} player=${request.actorId} phase=${request.phase} elapsed_ms=${Date.now() - startedAt} err=${formatErrorDiagnostic(error, this.options.observer.locale)}`,
      );
      return this.finishWithFallback(
        request,
        prompt,
        diagnostic.code === "request_timeout" ? "deadline_skip" : "runtime_error",
      );
    } finally {
      // 无论成功、记录／回退失败还是取消，都由取得租约的本回合释放；不在模型刚选出动作时提前放槽。
      release?.();
    }
  }

  private async runNative(
    client: ChatModelClient,
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    startedAt: number,
    signal: AbortSignal,
  ): Promise<ToolCall | null> {
    const retryTrace: PlayerRetryTraceEntry[] = [];
    // 每次尝试使用同一 bounded 请求的剩余期限；迟到结果在原检查点复核关闭／错误策略。
    const attempt = async (messages: ChatMessage[]): Promise<NativeAttempt> => {
      const timeoutMs = this.effectiveTimeout(request.deadlineAtMs);
      if (signal.aborted || timeoutMs <= 0) {
        return {
          action: null,
          failed: false,
          deadlineExceeded: true,
          diagnostic: { code: "request_timeout" },
        };
      }
      try {
        const result = await this.options.sdkToolLoop.run(
          client,
          request,
          messages,
          timeoutMs,
          prompt.turnId,
          signal,
        );
        if (
          request.context.action_failure_policy === "error" &&
          (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0)
        ) {
          return {
            action: null,
            failed: false,
            deadlineExceeded: true,
            diagnostic: { code: "request_timeout" },
          };
        }
        return {
          action: result.action,
          failed: result.failureCode !== undefined,
          refusalReason: result.failureCode,
          assistantText: result.thinkingText,
        };
      } catch (error) {
        const diagnostic = describeError(error);
        this.options.observer.trace(
          `request_sdk_attempt_fail player=${request.actorId} phase=${request.phase} err=${formatErrorDiagnostic(error, this.options.observer.locale)}`,
        );
        return { action: null, failed: true, diagnostic };
      }
    };

    const first = await attempt(prompt.messages);
    if (this.closed) return this.closedResult(request);
    if (first.deadlineExceeded)
      return this.finishWithFallback(request, prompt, "deadline_skip", {
        ...(request.context.action_failure_policy === "error"
          ? {
              retryTrace: [
                {
                  attempt: 0,
                  status: "request_error" as const,
                  reason: "request_timeout",
                  diagnostic: first.diagnostic ?? { code: "request_timeout" as const },
                },
              ],
            }
          : {}),
      });
    if (first.failed) {
      retryTrace.push({
        attempt: 0,
        status: first.refusalReason ? "no_valid_action" : "request_error",
        reason: first.refusalReason ?? first.diagnostic?.code,
        diagnostic: first.diagnostic,
        assistantText: first.assistantText,
      });
      return this.finishWithFallback(
        request,
        prompt,
        first.refusalReason ? "model_declined_required_action" : "runtime_error",
        {
          thinkingText: first.assistantText,
          retryTrace,
        },
      );
    }
    if (first.action)
      return this.finishWithAction(request, prompt, first.action, startedAt, {
        thinkingText: first.assistantText,
      });
    if (!this.requiresAction(request)) {
      this.options.observer.trace(
        `request_none player=${request.actorId} phase=${request.phase} elapsed_ms=${Date.now() - startedAt}`,
      );
      this.options.recorder.record(request, prompt, {
        actionMode: "none",
        toolCalls: [],
        thinkingText: first.assistantText,
      });
      return null;
    }

    retryTrace.push({
      attempt: 0,
      status: "no_valid_action",
      reason: "turn_constraints_no_valid_action",
      assistantText: first.assistantText,
    });
    let messages = [...prompt.messages];
    for (let attemptNumber = 1; attemptNumber <= 3; attemptNumber++) {
      const retryPrompt = buildConstraintRetryPrompt(attemptNumber, 3, this.options.world.locale);
      messages = [...messages, { role: "user", content: retryPrompt }];
      console.log(
        `[LLM_RETRY] player=${request.actorId} phase=${request.phase} attempt=${attemptNumber}/3 reason=turn_constraints_no_valid_action · ${text(this.options.observer.locale, "runtime.retry")}`,
      );
      const trace: PlayerRetryTraceEntry = {
        attempt: attemptNumber,
        status: "no_valid_action",
        reason: "turn_constraints_no_valid_action",
        retryPrompt,
      };
      retryTrace.push(trace);
      this.options.observer.prompt(messages, request);
      const result = await attempt(messages);
      if (this.closed) return this.closedResult(request);
      trace.assistantText = result.assistantText;
      if (result.deadlineExceeded) {
        trace.reason = result.diagnostic?.code;
        trace.diagnostic = result.diagnostic;
        return this.finishWithFallback(request, prompt, "deadline_skip", {
          thinkingText: result.assistantText,
          retryTrace,
        });
      }
      if (result.failed) {
        trace.status = result.refusalReason ? "no_valid_action" : "request_error";
        trace.reason = result.refusalReason ?? result.diagnostic?.code;
        trace.diagnostic = result.diagnostic;
        return this.finishWithFallback(
          request,
          prompt,
          result.refusalReason ? "model_declined_required_action" : "runtime_error",
          {
            thinkingText: result.assistantText,
            retryTrace,
          },
        );
      }
      if (result.action) {
        return this.finishWithAction(request, prompt, result.action, startedAt, {
          thinkingText: result.assistantText,
          retryTrace,
          retryAttempt: attemptNumber,
        });
      }
    }
    return this.finishWithFallback(request, prompt, "model_declined_required_action", {
      thinkingText: retryTrace.at(-1)?.assistantText,
      retryTrace,
    });
  }

  private async finishWithAction(
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    action: ToolCall,
    startedAt: number,
    extras: {
      thinkingText?: string;
      retryTrace?: PlayerRetryTraceEntry[];
      retryAttempt?: number;
    } = {},
  ): Promise<ToolCall | null> {
    if (this.closed) return this.closedResult(request);
    this.options.observer.trace(
      `${extras.retryAttempt ? "request_ok_retry" : "request_ok"} player=${request.actorId} phase=${request.phase}${extras.retryAttempt ? ` attempt=${extras.retryAttempt}/3` : ""} action=${action.name} args=${JSON.stringify((action as any).args ?? {})} elapsed_ms=${Date.now() - startedAt}`,
    );
    if (this.closed) return this.closedResult(request);
    this.options.recorder.record(request, prompt, {
      actionMode: "tool_call",
      toolCalls: this.toToolCalls(action),
      finalAction: action,
      thinkingText: extras.thinkingText,
      ...(extras.retryTrace?.length ? { retryTrace: [...extras.retryTrace] } : {}),
    });
    return this.closed ? this.closedResult(request) : action;
  }

  private async finishWithFallback(
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    reason: FallbackReason,
    extras: Pick<PlayerRoundOutcome, "thinkingText" | "retryTrace"> = {},
  ): Promise<ToolCall | null> {
    if (this.closed) return this.closedResult(request);
    let action: ToolCall | null;
    try {
      action = await this.options.fallbackPolicy.resolve(
        request,
        reason,
        this.closeController.signal,
      );
    } catch (error) {
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      if (!(error instanceof FallbackDeadlineElapsed)) throw error;
      action = null;
      reason = "deadline_skip";
    }
    if (this.closed) return this.closedResult(request);
    this.options.recorder.record(request, prompt, {
      actionMode: action ? "tool_call" : "none",
      toolCalls: this.toToolCalls(action),
      finalAction: action,
      ...extras,
      fallback: {
        used: allowsActionFallback(request),
        reason,
        ...(action ? { action: { name: action.name, args: (action as any).args ?? {} } } : {}),
      },
    });
    if (!this.closed && request.context.action_failure_policy === "error" && !action)
      throw new Error("action_turn_failed");
    return this.closed ? this.closedResult(request) : action;
  }

  private toToolCalls(action?: ToolCall | null) {
    return action
      ? [
          {
            name: action.name,
            args: ((action as any).args ?? {}) as Record<string, unknown>,
            accepted: true,
          },
        ]
      : [];
  }

  private requiresAction(request: ActionRequest): boolean {
    return resolveTurnConstraints(request).minValidActions > 0;
  }
  private closedResult(request: ActionRequest): null {
    if (request.context.action_failure_policy === "error") throw this.closeController.signal.reason;
    return null;
  }

  private effectiveTimeout(deadlineAtMs?: number): number {
    if (!deadlineAtMs) return this.options.timeoutMs;
    const remaining = deadlineAtMs - Date.now();
    return remaining <= 0 ? 0 : Math.max(1, Math.min(this.options.timeoutMs, remaining));
  }
}

/**
 * 持有 SDK 提示会话中每位玩家的追加历史、可见事件游标、回合计数和首次系统提示。
 * 输入为调用方传入的 ActionRequest 与提示政策；输出为历史窗口和本轮提示，记录指标随结果返回。
 * 请求授权与 currentness 仍归请求所有者，此处只解析可见事件并构建文本。
 * 历史只追加，窗口仅影响本次发送；本模块不选择行动、不执行工具，也不改变游戏阶段。
 */
import { text } from "@ai-werewolf-arena/game-text";
import { ActionRequest, EntityId, PlayerVisibleEvent, ToolName } from "../../../core/domain";
import { encodePlayerVisibleEvent, parsePlayerVisibleEvents } from "../visible_event_protocol";
import { BuiltPlayerPrompt } from "../player/contracts";
import { ChatMessage } from "../../integrations/llm/transport";
import { PlayerPromptPolicy } from "../player/player_prompt_policy";

export interface PlayerPromptSessionOptions {
  maxPromptEvents: number;
  promptPolicy: PlayerPromptPolicy;
}

/** 以玩家编号隔离历史与提示缓存；事件和回合使用各自的计数语义。 */
export class PlayerPromptSession {
  static readonly REPORT_BUG_TOOL: ToolName = "report_bug";

  private readonly histories = new Map<EntityId, ChatMessage[]>();
  private readonly eventCursors = new Map<EntityId, number>();
  private readonly toolTurnCounters = new Map<EntityId, number>();
  private readonly systemPrompts = new Map<EntityId, string>();

  constructor(private readonly options: PlayerPromptSessionOptions) {}

  build(request: ActionRequest): BuiltPlayerPrompt {
    const eventDelta = this.ingestVisibleEvents(request);
    const fullHistory = [...(this.histories.get(request.actorId) ?? [])];
    const contextWindow = this.selectHistoryWindow(fullHistory);
    const isInitialRound = !this.systemPrompts.has(request.actorId);
    const allowedTools = this.buildAllowedTools(request.allowedTools);
    const turnNumber = (this.toolTurnCounters.get(request.actorId) ?? 0) + 1;
    this.toolTurnCounters.set(request.actorId, turnNumber);
    const turnId = `t${turnNumber}`;

    const system = isInitialRound
      ? this.options.promptPolicy.buildSystem(request, { supportsDebugReporting: true })
      : undefined;
    // 系统提示只在首次构建后缓存；后续请求复用该文本，本轮行动与观察放在 user 提示中。
    const systemPrompt = this.systemPrompts.get(request.actorId) ?? system!.systemPrompt;
    if (isInitialRound) this.systemPrompts.set(request.actorId, systemPrompt);
    const userPrompt = this.options.promptPolicy.buildUser(request, {
      turnId,
      allowedTools,
      effectiveActionTools: allowedTools.filter(
        (tool) => tool !== PlayerPromptSession.REPORT_BUG_TOOL,
      ),
      actionSubmissionHint: text(this.options.promptPolicy.locale, "prompt.sdk.submit", {
        turn: turnId,
      }),
    });
    const currentTurnUser: ChatMessage = { role: "user", content: userPrompt };
    // 先追加本轮提示再返回。后续传输失败不回滚已经推进的历史、游标和回合计数。
    this.append(request.actorId, currentTurnUser);
    return {
      messages: [
        { role: "system", content: systemPrompt },
        ...contextWindow.history,
        currentTurnUser,
      ],
      systemPrompt,
      userPrompt,
      ...(system?.boardInfoPrompt ? { boardInfoPrompt: system.boardInfoPrompt } : {}),
      ...(system?.configPrompt ? { configPrompt: system.configPrompt } : {}),
      isInitialRound,
      eventCursorBefore: eventDelta.cursorBefore,
      eventCursorAfter: eventDelta.cursorAfter,
      contextWindowStart: contextWindow.start,
      contextWindowEnd: contextWindow.end,
      contextWindowTotal: contextWindow.total,
      turnId,
    };
  }

  appendAssistant(actorId: EntityId, content: string): void {
    this.append(actorId, { role: "assistant", content });
  }

  private append(actorId: EntityId, message: ChatMessage): void {
    const history = this.histories.get(actorId) ?? [];
    history.push(message);
    this.histories.set(actorId, history);
  }

  private ingestVisibleEvents(request: ActionRequest): {
    delta: PlayerVisibleEvent[];
    cursorBefore: number;
    cursorAfter: number;
  } {
    const events = parsePlayerVisibleEvents(request.context.visible_events);
    const cursor = this.eventCursors.get(request.actorId) ?? 0;
    if (!events.length) return { delta: [], cursorBefore: cursor, cursorAfter: cursor };
    // 只按玩家可见序号去重，保留输入事件顺序；不读取全局事件序号或补齐隐藏缺口。
    const delta = events.filter((event) => event.seq > cursor);
    for (const event of delta) {
      this.append(request.actorId, { role: "user", content: encodePlayerVisibleEvent(event) });
    }
    const nextCursor = events.reduce((max, event) => Math.max(max, event.seq), cursor);
    this.eventCursors.set(request.actorId, nextCursor);
    return { delta, cursorBefore: cursor, cursorAfter: nextCursor };
  }

  private selectHistoryWindow(fullHistory: ChatMessage[]) {
    const total = fullHistory.length;
    // 窗口按已存消息条数计算，事件、提示和回应均计入；切片不会删掉完整历史。
    const start = Math.max(0, total - Math.max(1, this.options.maxPromptEvents * 6));
    return { start, end: total, total, history: fullHistory.slice(start) };
  }

  private buildAllowedTools(allowedTools: ToolName[]): ToolName[] {
    const tools = [...allowedTools];
    if (!tools.includes(PlayerPromptSession.REPORT_BUG_TOOL)) {
      tools.push(PlayerPromptSession.REPORT_BUG_TOOL);
    }
    return tools;
  }
}

/**
 * 负责把 SDK 工具调用适配到共同 ActionTurn 选择窗口；输入为模型消息、原引擎请求与 SDK 调用。
 * 输出保留预检回执、已选候选及拒绝／模型证据，规则与 schema 接收由游戏 Gateway 拥有。
 * 计时器、abort 与 finally-close 仍属于本 loop；accepted 仅表示 selected 且 applied:false，
 * 不消耗库存、提交领域动作或订阅 settlement，失败保留原读取与记录顺序。
 */
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { ActionRequest, ToolCall } from "../../../core/domain";
import {
  getActionRequestDay,
  getActionRequestStage,
} from "../../../core/domain/action_request_context";
import { World } from "../../../core/domain/world";
import { safeRecordLogicOp } from "../../../recording/session_recorder";
import { AgentBugReportService } from "../reporting/bug_report_service";
import { gameToolProtocol } from "../game_tool_protocol";
import { ActionReception } from "../../../game/gateway/action-reception";
import { ActionTurn } from "../player/action-turn";
import {
  ToolCallRepairRegistry,
  type ToolSpecRegistry,
  getDefaultToolSpecRegistry,
  type ToolValidationRuleRegistry,
  getDefaultToolValidationRuleRegistry,
} from "../../../game/mechanisms";
import { LlmObserver } from "../player/player_observer";
import { ChatMessage, ChatModelClient } from "../../integrations/llm/transport";
import { PlayerPromptSession } from "./player_prompt_session";
import { resolveTurnConstraints } from "../../../game/gateway/turn-constraints";
import { awaitWithAbort } from "../../runtime/turn_deadline";

interface ToolLoopActionResult {
  action: ToolCall | null;
  thinkingText?: string;
  failureCode?: "turn_invalid_action_limit" | "action_turn_failed";
}

/** 原生 SDK 游戏协议适配，所有候选通过同一选择与预检 owner。 */
export class SdkGameToolLoop {
  private readonly reception: ActionReception;
  private readonly bugReports: AgentBugReportService;

  constructor(
    private readonly world: World,
    repairRegistry: ToolCallRepairRegistry,
    private readonly promptSession: PlayerPromptSession,
    private readonly observer: LlmObserver,
    toolSpecRegistry: ToolSpecRegistry = getDefaultToolSpecRegistry(),
    validationRules: ToolValidationRuleRegistry = getDefaultToolValidationRuleRegistry(),
  ) {
    this.reception = new ActionReception(world, repairRegistry, toolSpecRegistry, validationRules);
    this.bugReports = new AgentBugReportService(world, {
      onAccepted: (report, reportId) => {
        const message =
          report.message.length > 120 ? `${report.message.slice(0, 120)}...` : report.message;
        console.log(
          `[LLM_BUG] player=${report.actorId} phase=${report.phase} stage=${report.stage} severity=${report.severity} category=${report.category} report_id=${reportId} message=${message}`,
        );
      },
    });
  }

  async run(
    client: ChatModelClient,
    request: ActionRequest,
    messages: ChatMessage[],
    timeoutMs: number,
    turnId: string,
    signal?: AbortSignal,
  ): Promise<ToolLoopActionResult> {
    const controller = new AbortController();
    let timer: NodeJS.Timeout | null = null;
    const turn = new ActionTurn(this.reception, request, turnId);
    let protocolRejected = false;
    const abort = () => {
      turn.close();
      controller.abort(signal?.reason);
    };
    if (signal?.aborted) abort();
    else signal?.addEventListener("abort", abort, { once: true });
    try {
      if (controller.signal.aborted) throw controller.signal.reason;
      const constraints = resolveTurnConstraints(request);
      const protocol = gameToolProtocol(this.world.locale);
      const loop = client.runToolLoop<ToolCall>(
        messages,
        protocol.specs,
        {
          onToolCall: async (invocation) => {
            if (controller.signal.aborted) {
              return {
                toolResult: toolFailure(this.world.locale, "turn_not_open_or_session_invalid"),
              };
            }
            if (invocation.name === "get_game_schema") {
              return { toolResult: protocol.schema };
            }
            if (invocation.name === PlayerPromptSession.REPORT_BUG_TOOL) {
              const refusal = turn.authorize(invocation.args.turn_id ?? turnId, "report_bug");
              if (refusal)
                return {
                  toolResult: this.recordRefusal(
                    request,
                    invocation.name,
                    invocation.args,
                    refusal,
                  ),
                };
              return { toolResult: this.reportBug(request, invocation.args) };
            }

            let actionName = invocation.name;
            let actionArgs = invocation.args;
            if (invocation.name === "submit_action") {
              if (invocation.args.turn_id !== turnId) {
                protocolRejected = true;
                return {
                  toolResult: this.recordRefusal(
                    request,
                    invocation.name,
                    invocation.args,
                    turn.authorize(invocation.args.turn_id)!,
                  ),
                };
              }
              const receipt = turn.submit(
                turnId,
                invocation.args.action,
                invocation.args.arguments,
              );
              if (!receipt.ok)
                return {
                  toolResult: this.recordRefusal(
                    request,
                    invocation.name,
                    invocation.args,
                    receipt,
                  ),
                };
              return { toolResult: receipt, finalAction: turn.action! };
            }
            const receipt = turn.submit(turnId, actionName, actionArgs);
            if (!receipt.ok) {
              return {
                toolResult: this.recordRefusal(request, invocation.name, invocation.args, receipt),
              };
            }
            return { toolResult: receipt, finalAction: turn.action! };
          },
        },
        {
          signal: controller.signal,
          maxSteps: 8,
          toolChoice: constraints.minValidActions > 0 ? "required" : "auto",
        },
      );
      const result = await awaitWithAbort(
        Promise.race([
          loop,
          new Promise<never>((_, reject) => {
            timer = setTimeout(() => {
              turn.close();
              const error = new Error(`llm_request_timeout_${timeoutMs}ms`);
              controller.abort(error);
              reject(error);
            }, timeoutMs);
          }),
        ]),
        controller.signal,
      );
      const thinkingText = this.observer.thinkingText(
        result.assistantText ?? "",
        result.thinkingTrace ?? [],
      );
      if (result.assistantText) {
        this.promptSession.appendAssistant(request.actorId, result.assistantText);
      }
      this.observer.thinking(result.thinkingTrace ?? [], request);
      this.observer.rawResponse(result.assistantText ?? "", request);
      const failedActionInput =
        result.failedToolInvocations?.some(
          (call) => call.name !== "get_game_schema" && call.name !== "report_bug",
        ) === true;
      if (
        !turn.action &&
        request.context.action_failure_policy === "error" &&
        (turn.outcome.rejectedActions || protocolRejected || failedActionInput)
      )
        return {
          action: null,
          failureCode: turn.outcome.failureCode ?? "action_turn_failed",
          ...(thinkingText ? { thinkingText } : {}),
        };
      return {
        action: turn.action,
        ...(thinkingText ? { thinkingText } : {}),
      };
    } finally {
      turn.close();
      signal?.removeEventListener("abort", abort);
      if (timer) clearTimeout(timer);
    }
  }

  private recordRefusal(
    request: ActionRequest,
    tool: string,
    args: Record<string, unknown>,
    result: { ok: false; error: string; message: string },
  ): Record<string, unknown> {
    safeRecordLogicOp({
      scope: "llm_action_provider",
      op: "tool_call_rejected",
      actorId: request.actorId,
      phase: String(request.phase),
      status: "rejected",
      reason: result.error,
      input: {
        day: getActionRequestDay(request),
        stage: getActionRequestStage(request),
        tool,
        args,
      },
      output: result,
    });
    this.observer.trace(
      `tool_call_rejected player=${request.actorId} tool=${tool} code=${result.error}`,
    );
    return result;
  }

  private reportBug(
    request: ActionRequest,
    args: Record<string, unknown>,
  ): Record<string, unknown> {
    return this.bugReports.report({
      actorId: request.actorId,
      day: getActionRequestDay(request),
      phase: String(request.phase),
      stage: getActionRequestStage(request),
      category: args.category,
      severity: args.severity,
      message: args.message,
    });
  }
}

/**
 * 负责单个 Agent 行动选择窗口及接收回执；输入为游戏预检窄端口、原请求和提交的 turnId。
 * 输出保留脱离后的 selected、拒绝计数和 applied:false；截止在授权点检查，close 只封住本选择窗口。
 * 本 owner 只消费预检接口与 World locale，不调用 World 写方法、不消耗资源、不订阅领域 settlement，也不等待实际 commit。
 * 规则预检属于游戏 Gateway，领域完成责任仍由 reproduction 与各机制所有者持有。
 */
import { text, toolFailure } from "@ai-werewolf-arena/game-text";
import type { ActionRequest, ToolCall, ToolName } from "../../../core/domain";
import type {
  ActionPreflightPort,
  GameActionValidation,
} from "../../../game/gateway/action-reception";

/** accepted:true 只表示本次候选被选择且 applied 固定 false；拒绝字段保原回包，不是领域付款／回滚回执。 */
export type ActionReceipt =
  | { ok: true; accepted: true; applied: false; action: ToolName }
  | {
      ok: false;
      error: string;
      message: string;
      details?: string[];
      expected_turn_id?: string;
      received_turn_id?: unknown;
    };
export type ActionValidation = GameActionValidation;

/** 每个开放回合只有一个选择 owner；拒绝按原政策保留窗口，selected 本身阻止后续选择，不等于 closed 已被设置。 */
export class ActionTurn {
  // selected 与 closed 分别保候选和显式关闭；拒绝次数不等于资源消耗，严格三次门槛每次从原请求政策求值。
  private selected: ToolCall | null = null;
  private closed = false;
  private rejectedActions = 0;
  constructor(
    private readonly reception: ActionPreflightPort,
    readonly request: ActionRequest,
    readonly turnId: string,
  ) {}

  /** 每次访问克隆已选候选；克隆失败不撤回 selected，也不改变 closed 或补做领域提交。 */
  get action(): ToolCall | null {
    return this.selected ? structuredClone(this.selected) : null;
  }
  get outcome(): { rejectedActions: number; failureCode: "turn_invalid_action_limit" | null } {
    return {
      rejectedActions: this.rejectedActions,
      failureCode:
        !this.selected &&
        this.request.context.action_failure_policy === "error" &&
        this.rejectedActions >= 3
          ? "turn_invalid_action_limit"
          : null,
    };
  }

  // locale→closed/selected/期限→严格失败上限→turnId 按原顺序读取；没有计时器或新增期限数值校验。
  authorize(turnId: unknown, tool = "submit_action"): Extract<ActionReceipt, { ok: false }> | null {
    const locale = this.reception.world.locale;
    if (this.closed || this.selected || (this.request.deadlineAtMs ?? Infinity) <= Date.now()) {
      return toolFailure(locale, "turn_not_open_or_session_invalid");
    }
    if (this.outcome.failureCode) return toolFailure(locale, this.outcome.failureCode);
    if (turnId !== this.turnId) {
      return {
        ...toolFailure(locale, "turn_id_mismatch"),
        expected_turn_id: this.turnId,
        received_turn_id: typeof turnId === "string" ? turnId : null,
        message: text(locale, "tool.turn_id_mismatch_context", { turn: this.turnId, tool }),
      };
    }
    return null;
  }

  submit(turnId: unknown, name: unknown, args: unknown): ActionReceipt {
    const refusal = this.authorize(turnId);
    if (refusal) return refusal;
    if (
      typeof name !== "string" ||
      args === null ||
      typeof args !== "object" ||
      Array.isArray(args)
    ) {
      this.rejectedActions++;
      return toolFailure(this.reception.world.locale, "invalid_submit_action_arguments");
    }
    // 预检返回拒绝才计数；预检直接抛错不在这里 catch 或换成拒绝，原异常留给实际传输调用方。
    const result = this.reception.validate(this.request, name, args);
    if (!result.ok) {
      this.rejectedActions++;
      return result;
    }
    // 候选引用先保存，再读回包 action.name；后续 getter／调用方序列化失败也保已经选择的前缀。
    this.selected = result.action;
    return { ok: true, accepted: true, applied: false, action: result.action.name };
  }
  /** schema 拒绝可先于工具执行，但只由 turnId 对应的有效窗口计数；外来回合不污染当前窗口。 */
  rejectSubmissionInput(turnId: unknown): ActionReceipt {
    const refusal = this.authorize(turnId);
    if (refusal) return refusal;
    this.rejectedActions++;
    return toolFailure(this.reception.world.locale, "invalid_submit_action_arguments");
  }

  /** 只写本窗口 closed；不取消模型、关闭会话、清理候选或通知领域完成，这些仍归原调用链。 */
  close(): void {
    this.closed = true;
  }
}

/**
 * 负责定义 SDK 与 ACP 共用的提示构建结果、重试轨迹和轮次记录数据。
 * 提示／轮次编排器生产这些数据，记录器消费；此处只声明结构，不拥有会话、授权或领域提交。
 * 原始文案、工具参数与诊断保留输入含义；工具接受结果和最终游戏结算分别由各自所有者确认。
 */
import type { ErrorDiagnostic } from "@ai-werewolf-arena/replay-contract";
import { ToolCall } from "../../../core/domain";
import { ChatMessage } from "../../integrations/llm/transport";

/** 本次提示及记录定位信息；各传输自行维护历史，因此窗口指标不承诺相同实现。 */
export interface BuiltPlayerPrompt {
  /** 原提示消息数组可写；声明不复制、冻结或保证与任一传输内部历史共享同一对象。 */
  messages: ChatMessage[];
  systemPrompt: string;
  userPrompt: string;
  boardInfoPrompt?: string;
  configPrompt?: string;
  isInitialRound: boolean;
  // 玩家可见序号游标；不是 God 事件下标，也不能暴露隐藏事件的数量。
  eventCursorBefore: number;
  eventCursorAfter: number;
  // 编排器记录本次选用的历史窗口边界；SDK 历史切片使用 [start, end)。
  contextWindowStart: number;
  contextWindowEnd: number;
  contextWindowTotal: number;
  // 本轮生成、供模型回传的关联标识；字符串本身不授予引擎行动权限。
  turnId: string;
  /** 仅轮次记录的附加文本，不在此形成完整协议档案、隐藏信息过滤或运行权限。 */
  auditMetadata?: string[];
}

/** 保留每次失败／未得到有效行动的原因、诊断和原始回应，供事后审查。 */
export interface PlayerRetryTraceEntry {
  /** 编排器提供的尝试编号；字段本身不限制循环预算或证明领域尚未付款。 */
  attempt: number;
  status: "request_error" | "no_valid_action";
  reason?: string;
  diagnostic?: ErrorDiagnostic;
  retryPrompt?: string;
  assistantText?: string;
}

/** 轮次决策记录；actionMode 与 finalAction 描述返回选择，不表示已付款或生效。 */
export interface PlayerRoundOutcome {
  actionMode: "tool_call" | "none";
  toolCalls: Array<{
    id?: string;
    name: string;
    args: Record<string, unknown>;
    // 工具层接受结果；不能据此推断领域提交、资源消耗或最终效果。
    accepted?: boolean;
    result?: Record<string, unknown> | string;
  }>;
  thinkingText?: string;
  finalAction?: ToolCall | null;
  /** 回退状态由调用方填入；used 为真也可没有 action，不据此推断回退成功或已生效。 */
  fallback?: {
    used: boolean;
    reason?: string;
    action?: { name: string; args: Record<string, unknown> };
  };
  retryTrace?: PlayerRetryTraceEntry[];
}

/**
 * 将玩家提示、模型原文和工具轨迹输出到终端，按选项控制日志、思考内容及着色。
 * 输入为编排器已提供的数据；输出只有日志与诊断文本，不负责事件投影、持久化或行动判定。
 * 文案依据 locale 渲染，机器标签及模型原文保持原值；console 异常仍交给调用方处理。
 */
import { text, dictionaries, type MessageKey, type Locale } from "@ai-werewolf-arena/game-text";
import { ActionRequest } from "../../../core/domain";
import { colorize, isAnsiEnabled } from "../../../utils/ansi";
import { ChatMessage, ToolLoopStepTrace } from "../../integrations/llm/transport";

/** 仅控制日志展示；printThinking 不创建思考结果，transport 只选择原标签，locale 不改变模型原文。 */
export interface LlmObserverOptions {
  trace: boolean;
  locale?: Locale;
  colorizeLogs?: boolean;
  printLlmIo: boolean;
  printThinking: boolean;
  transport?: "llm" | "acp";
}

/** 终端观察与游戏决策分离；最近 80 条 trace 由本实例持有。 */
export class LlmObserver {
  private readonly recentEvents: string[] = [];
  private readonly colorizeLogs: boolean;

  constructor(private readonly options: LlmObserverOptions) {
    this.colorizeLogs = isAnsiEnabled(options.colorizeLogs);
  }

  get locale(): Locale {
    return this.options.locale ?? "zh-CN";
  }

  // 先记原 line 并裁到最近 80 条，再决定是否打印；装饰／console 失败不会撤回已改缓冲。
  trace(line: string): void {
    this.recentEvents.push(line);
    if (this.recentEvents.length > 80) this.recentEvents.shift();
    if (this.options.trace) console.log(this.decorate(line));
  }

  /** 原调用方负责可见数据范围；此处只按消息顺序打印，未知 role 显示原标签，不自行过滤或转交行动。 */
  prompt(messages: ChatMessage[], request: ActionRequest): void {
    if (!this.options.printLlmIo) return;
    const prefix = colorize(
      this.options.transport === "acp" ? "[ACP_IO]" : "[LLM_IO]",
      "accent",
      this.colorizeLogs,
    );
    const marker = `player=${request.actorId} phase=${request.phase}`;
    console.log(`${prefix} prompt_start ${marker} · ${text(this.locale, "runtime.prompt_start")}`);
    for (const msg of messages) {
      const roleTag = typeof msg.role === "string" ? msg.role : "unknown";
      const roleKey = `runtime.prompt_${roleTag}` as MessageKey;
      const roleLabel = Object.hasOwn(dictionaries[this.locale], roleKey)
        ? text(this.locale, roleKey)
        : roleTag;
      console.log(`${prefix} prompt_${roleTag} · ${roleLabel}: ${msg.content}`);
    }
    console.log(`${prefix} prompt_end ${marker} · ${text(this.locale, "runtime.prompt_end")}`);
  }

  /** 原回应不解析成工具；打印开关关闭则早返，日志／翻译错误保持原抛出，不变成请求校验结果。 */
  rawResponse(raw: string, request: ActionRequest): void {
    if (!this.options.printLlmIo) return;
    const prefix = colorize(
      this.options.transport === "acp" ? "[ACP_IO]" : "[LLM_IO]",
      "accent",
      this.colorizeLogs,
    );
    const marker = `player=${request.actorId} phase=${request.phase}`;
    console.log(
      `${prefix} raw_response_start ${marker} · ${text(this.locale, "runtime.raw_response_start")}`,
    );
    console.log(`${prefix} raw_response · ${text(this.locale, "runtime.raw_response")}: ${raw}`);
    console.log(
      `${prefix} raw_response_end ${marker} · ${text(this.locale, "runtime.raw_response_end")}`,
    );
  }

  /** 按原 step 和 toolCalls 顺序展示文本与原工具轨迹；不由 accepted 字段推断资源付款或隐藏信息许可。 */
  thinking(trace: ToolLoopStepTrace[], request: ActionRequest): void {
    if (!this.options.printThinking || trace.length === 0) return;
    const prefix = colorize("[THINKING]", "muted", this.colorizeLogs);
    const marker = `player=${request.actorId} phase=${request.phase}`;
    console.log(`${prefix} start ${marker} · ${text(this.locale, "runtime.thinking_start")}`);
    for (const [stepIndex, step] of trace.entries()) {
      if (step.assistantText?.trim()) {
        console.log(
          `${prefix} assistant step=${stepIndex + 1} · ${text(this.locale, "runtime.assistant_output")}: ${step.assistantText}`,
        );
      }
      for (const call of step.toolCalls) {
        console.log(
          `${prefix} ${text(this.locale, "runtime.tool_call")} | tool_call step=${stepIndex + 1} id=${call.id} name=${call.name} args=${call.rawArgs}`,
        );
        console.log(
          `${prefix} ${text(this.locale, "runtime.tool_result")} | tool_result step=${stepIndex + 1} id=${call.id} result=${call.toolResult}`,
        );
      }
    }
    console.log(`${prefix} end ${marker} · ${text(this.locale, "runtime.thinking_end")}`);
  }

  /** 诊断摘要优先采用最终文本，否则取最后一条非空步骤文本；仅摘要截断，原始日志不由此改写。 */
  thinkingText(assistantText: string, trace: ToolLoopStepTrace[]): string | null {
    const primary = assistantText.trim();
    if (primary) return primary.length > 1200 ? `${primary.slice(0, 1200)}…` : primary;
    for (let i = trace.length - 1; i >= 0; i--) {
      const text = trace[i]?.assistantText?.trim();
      if (text) return text.length > 1200 ? `${text.slice(0, 1200)}…` : text;
    }
    return null;
  }

  // 只按原首 token 查展示 key，再按包含的机器标签选颜色；没有解码事件或改变原 line 的诊断含义。
  private decorate(line: string): string {
    const prefix = this.options.transport === "acp" ? "[ACPActionProvider]" : "[LLMActionProvider]";
    const key = `runtime.trace.${line.split(" ", 1)[0]}` as MessageKey;
    if (Object.hasOwn(dictionaries[this.locale], key)) line = `${text(this.locale, key)} | ${line}`;
    if (!this.colorizeLogs) return `${prefix} ${line}`;
    if (line.includes("request_ok"))
      return `${colorize(prefix, "ok", true)} ${colorize(line, "ok", true)}`;
    if (line.includes("request_recovered") || line.includes("request_timeout")) {
      return `${colorize(prefix, "warn", true)} ${colorize(line, "warn", true)}`;
    }
    if (line.includes("request_transport_fail")) {
      return `${colorize(prefix, "error", true)} ${colorize(line, "error", true)}`;
    }
    if (line.includes("request_start")) {
      return `${colorize(prefix, "info", true)} ${colorize(line, "info", true)}`;
    }
    return `${colorize(prefix, "muted", true)} ${colorize(line, "muted", true)}`;
  }
}

/**
 * 负责 SDK／ACP 共用系统／回合模板、人设、工具协议提示与公开开局配比缓存的组织。
 * 输入为原 World、请求与提示选项；输出为模板组合文本，机制状态／阶段说明交游戏观察 owner。
 * 查询 thunk 保留每次 World／语言／Catalog／板子 getter 时点，不提前调用人设或角色 renderer。
 * 开局人数先按原顺序写入，公开配比缓存仍唯一归此；来源选择与聚合交游戏观察 owner 直接填入。
 * 查询或聚合失败保留原 size／Map 已写前缀，不回滚，也不把身份候选当作当前权限。
 * 候选仅作提示，不授予行动许可；本模块不提交资源、变更阶段或复制新的私有库存。
 */

import {
  buildPlayerStatusDirective,
  buildPlayerStageContextHint,
  resolvePlayerPromptAbility,
  playerPromptRoleSkillBrief,
  appendPlayerPromptInitialIdentity,
} from "../../../game/observation/player-prompt-directives";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { collectPlayerInitialPublicCounts } from "../../../game/observation/player-initial-public-counts";

import { renderMessage, text, type Locale } from "@ai-werewolf-arena/game-text";

import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionRequest, EntityId, Role, ToolName } from "../../../core/domain";
import { getActionRequestStage } from "../../../core/domain/action_request_context";
import { World } from "../../../core/domain/world";

import {
  ConfigRenderRegistry,
  PhaseStageLocalizationRegistry,
  RoleCatalog,
  TargetHintRegistry,
  ToolSpecRegistry,
  knownWolfTeammates,
} from "../../../game/mechanisms";

import type { PlayerObservation } from "../../../game/observation/player-observation";
import { capturePlayerObservation } from "../../../game/observation/player-observation-projector";
import { buildBoardInfoPrompt, buildSystemPrompt, buildUserPrompt } from "./prompt_templates";
import { renderTurnConstraintUserHint } from "./turn_constraints";
import { resolveTurnConstraints } from "../../../game/gateway/turn-constraints";

/** 装配对象与 registry 保原引用；人设回调收到原 request/role，不能把这个类型契约称作脱离数据或隔离沙箱。 */
export interface PlayerPromptPolicyOptions {
  personalityPromptResolver?: (request: ActionRequest, role?: RoleComponent) => string | undefined;
  toolSpecRegistry: ToolSpecRegistry;
  roleCatalog: RoleCatalog;
  targetHintRegistry: TargetHintRegistry;
  phaseStageLocalizationRegistry: PhaseStageLocalizationRegistry;
  configRenderRegistry: ConfigRenderRegistry;
  boardConfig?: ReadonlyBoardConfig;
}

/** SDK／ACP 共用提示策略；传输适配器只选择其协议提示。 */
export class PlayerPromptPolicy {
  // 这里只缓存构造时公开配比与人数，不把其当作当前存活、已觉醒或可用库存；后续展示 callback 仍晚读。
  private readonly publicRoleCounts = new Map<Role, number>();
  private readonly publicBoardSize: number;

  constructor(
    private readonly world: World,
    private readonly options: PlayerPromptPolicyOptions,
  ) {
    // size 在初发牌查询和计数之前提交；观察 owner 只填入本实例原 Map，不另建镜像。
    this.publicBoardSize = options.boardConfig?.boardSize ?? world.entityIds().length;
    collectPlayerInitialPublicCounts({
      world: () => world,
      boardConfig: () => options.boardConfig,
      role: (actorId) => this.role(actorId),
      counts: () => this.publicRoleCounts,
    });
  }

  get locale(): Locale {
    return this.world.locale;
  }

  /** 真实策略入口委托完整观察捕获，不在提示层重建库存或改变冻结时点。 */
  buildObservation(request: ActionRequest): PlayerObservation {
    return capturePlayerObservation(request, {
      world: () => this.world,
      role: (actorId) => this.role(actorId()),
      wolfTeammates: (actorId) => this.wolfTeammates(actorId()),
      catalog: () => this.options.roleCatalog,
    });
  }

  buildSystem(
    request: ActionRequest,
    options: { supportsDebugReporting: boolean; includeToolUseInstructions?: boolean },
  ) {
    // role→开局配比展示→可选板配置→模板参数依序求值；后续 renderer/回调抛错不回滚已发生副作用。
    const role = this.role(request.actorId);
    const boardInfoPrompt = this.buildBoardInfo();
    const configPrompt = this.options.boardConfig
      ? this.options.configRenderRegistry.renderBoardConfigPrompt(
          this.options.boardConfig,
          this.locale,
        )
      : undefined;
    return {
      systemPrompt: buildSystemPrompt({
        locale: this.locale,
        actorId: request.actorId,
        role: role ? this.options.roleCatalog.label(role.role, this.locale) : "unknown",
        maxPlayerId: this.world.entityIds().length,
        teammateIds: this.wolfTeammates(request.actorId),
        boardInfoPrompt,
        configPrompt,
        personalityPrompt: this.options.personalityPromptResolver?.(request, role),
        playerName: this.world.getComponent(request.actorId, COMPONENT.Identity)?.name,
        supportsDebugReporting: options.supportsDebugReporting,
        includeToolUseInstructions: options.includeToolUseInstructions,
      }),
      boardInfoPrompt,
      configPrompt,
    };
  }

  buildUser(
    request: ActionRequest,
    input: {
      turnId: string;
      allowedTools: ToolName[];
      effectiveActionTools?: ToolName[];
      actionSubmissionHint: string;
    },
  ): string {
    const role = this.role(request.actorId);
    // 解析实例只为提示与目标标签选择；min/effective tools/candidates 仍是知识，提交要走实际规则与原体复验。
    const { bound, targetRuleRole } = resolvePlayerPromptAbility(request, role);
    const constraints = resolveTurnConstraints(request);
    const stage = getActionRequestStage(request);
    return buildUserPrompt({
      locale: this.locale,
      actorId: request.actorId,
      phase: this.options.phaseStageLocalizationRegistry.phaseName(
        String(request.phase),
        this.locale,
      ),
      stage: this.options.phaseStageLocalizationRegistry.stageName(stage, this.locale),
      isSpeechTurn:
        input.allowedTools.includes("speak") || input.allowedTools.includes("speak_to_wolves"),
      stageDirective:
        bound?.activation === "black_market"
          ? text(this.locale, "action.black_market_recipient.directive")
          : bound?.activation === "lucky"
            ? text(this.locale, "action.lucky.directive")
            : (this.options.toolSpecRegistry.getStageDirective(request.allowedTools, this.locale) ??
              text(this.locale, "prompt.stage.default")),
      statusDirective: buildPlayerStatusDirective(request, role, {
        world: () => this.world,
        locale: () => this.locale,
        catalog: () => this.options.roleCatalog,
        wolfTeammates: (actorId) => this.wolfTeammates(actorId()),
      }),
      requiresAction: constraints.minValidActions > 0,
      turnConstraintHint: renderTurnConstraintUserHint(constraints, this.locale),
      allowedTools: input.allowedTools,
      effectiveActionTools: input.effectiveActionTools ?? input.allowedTools,
      toolArgHints: this.toolArgHints(input.allowedTools),
      toolUsageHints: this.options.toolSpecRegistry.getApplicableUserPromptHints(
        input.allowedTools,
        this.locale,
      ),
      stageContextHint:
        [
          buildPlayerStageContextHint(request, {
            locale: () => this.locale,
            boardConfig: () => this.options.boardConfig,
          }),
          request.context.modifier_poison_blocked === true
            ? text(this.locale, "prompt.stage.modifier_poison_blocked")
            : undefined,
          // 原 retry_notice 即便空串也优先；只有 undefined 才渲染引用，随后 filter(Boolean) 不会重新回退。
          request.context.retry_notice !== undefined
            ? request.context.retry_notice
            : request.context.retry_notice_message
              ? renderMessage(this.locale, request.context.retry_notice_message)
              : undefined,
        ]
          .filter(Boolean)
          .join(" ") || undefined,
      actionableIdsHint: this.options.targetHintRegistry.buildActionableIdsHint({
        modifierCandidates: request.context.modifier_candidates,
        modifierBonusCandidates: request.context.modifier_bonus_candidates,
        actorId: request.actorId,
        day: request.context.day,
        actorRole: targetRuleRole,
        abilityId: request.context.ability_id,
        debateTargetId: request.context.debate_target_id,
        allowedTools: input.allowedTools,
        world: this.world,
        roleCatalog: this.options.roleCatalog,
        sheriffCandidates: request.context.sheriff_candidates,
        exileCandidates: request.context.exile_candidates,
        badgeCandidates: request.context.badge_candidates,
      }),
      actionSubmissionHint: input.actionSubmissionHint,
    });
  }

  /** 静态配比先形成文本，再追加当前板子说明与初始身份知识；追加失败不撤销 此前回调，函数不返回部分文本。 */
  buildBoardInfo(): string {
    let info = buildBoardInfoPrompt({
      locale: this.locale,
      totalPlayers: this.publicBoardSize,
      roleCounts: this.publicRoleCounts,
      roleLabel: (role) => this.options.roleCatalog.label(role, this.locale),
      roleSkillBrief: (role) =>
        playerPromptRoleSkillBrief(role, {
          world: () => this.world,
          locale: () => this.locale,
          catalog: () => this.options.roleCatalog,
        }),
    });
    if (this.options.boardConfig?.pureWhite) {
      info +=
        "\n" +
        text(
          this.locale,
          this.options.boardConfig.pureWhite.eliminationPriority === "awa_wolf_priority_v1"
            ? "prompt.board.pure_white.wolf_priority"
            : "prompt.board.pure_white.good_priority",
        );
    }
    return appendPlayerPromptInitialIdentity(info, {
      world: () => this.world,
      locale: () => this.locale,
    });
  }

  private role(actorId: EntityId): RoleComponent | undefined {
    return this.world.getComponent(actorId, COMPONENT.Role);
  }

  private wolfTeammates(actorId: EntityId): EntityId[] {
    return knownWolfTeammates(this.world, actorId, this.options.roleCatalog);
  }

  /** registry 提示按输入工具顺序取得并去掉假值；文本不是工具注册、schema 校验或现场许可。 */
  private toolArgHints(allowedTools: ToolName[]): string {
    const hints = allowedTools
      .map((tool) => this.options.toolSpecRegistry.getArgHint(tool))
      .filter((hint): hint is string => Boolean(hint));
    return hints.join("; ") || text(this.locale, "common.none");
  }
}

/**
 * 负责 SDK／ACP 共用的身份、板子、行动与约束重试文本模板。输入为调用方类型化的身份、
 * 工具提示、配比 Map 和角色回调，输出按原语言／排列拼接的提示字符串。
 * locale 缺省仍为 zh-CN；原对象、数组和 Map 在原表达式位置读取，不克隆、冻结或重新统计。
 * getter、数组方法或角色回调失败保持原抛出；模板文本不授资源、当前角色或行动许可。
 * 本模块不提交行动、计算期限或实施重试次数，产品文案和消息 key 仍由原文本 owner 持有。
 */
import { Role } from "../../../core/domain";
import { text, type Locale } from "@ai-werewolf-arena/game-text";

/** 调用方提供的身份与人设文本；role 是原显示字符串，不在这里据其重新判断阵营。 */
export interface SystemPromptInput {
  locale?: Locale;
  actorId: number;
  role: string;
  maxPlayerId: number;
  /** 按原数组 join 呈现调用方队友知识，不复验其当前生命、身份或狼队行动权限。 */
  teammateIds: number[];
  boardInfoPrompt?: string;
  configPrompt?: string;
  /** 保留可选原人设；非空判断与正文插入各按原位置读取／trim，不预处理或改变产品文本。 */
  personalityPrompt?: string;
  playerName?: string;
  supportsDebugReporting?: boolean;
  includeToolUseInstructions?: boolean;
}

/** 回合展示输入，不是原 ActionRequest 或租约；阶段、目标和工具内容仍由外层策略准备。 */
export interface UserPromptInput {
  locale?: Locale;
  actorId: number;
  phase: string;
  stage: string;
  isSpeechTurn: boolean;
  stageDirective: string;
  statusDirective?: string;
  /** 仅在没有有效 turnConstraintHint 时选择原必需／可选文案，不在这里强制提交或付款。 */
  requiresAction: boolean;
  turnConstraintHint?: string;
  /** 原可写提示集合；和 effectiveActionTools 的展示不等于网关或回合当前性验证。 */
  allowedTools: string[];
  effectiveActionTools?: string[];
  toolArgHints: string;
  toolUsageHints?: string[];
  actionableIdsHint?: string;
  stageContextHint?: string;
  actionSubmissionHint?: string;
}

/** 配比数据及角色显示回调由调用方持有；模板只使用原 Map，不据 World 再发牌／统计。 */
export interface BoardInfoPromptInput {
  locale?: Locale;
  totalPlayers: number;
  roleCounts: Map<Role, number>;
  roleLabel: (role: Role) => string;
  roleSkillBrief: (role: Role) => string;
}

/** 身份、名字、队友和人设仍依原顺序拼接；工具说明与报告说明保原开关短路。 */
// 数组段落按表达式顺序求值；后段 formatter/getter 失败不返回已拼部分，也不撤销人设／回调已有副作用。
export function buildSystemPrompt(input: SystemPromptInput): string {
  const locale = input.locale ?? "zh-CN";
  return [
    text(locale, "prompt.system.identity", { actor: input.actorId, role: input.role }),
    text(locale, "prompt.system.goal"),
    text(locale, "prompt.system.language"),
    ...(input.playerName ? [text(locale, "prompt.system.name", { name: input.playerName })] : []),
    text(locale, "prompt.system.teammates", {
      teammates: input.teammateIds.join(", ") || text(locale, "common.none"),
    }),
    text(locale, "prompt.system.ids", { max: input.maxPlayerId }),
    text(locale, "prompt.system.boundaries"),
    ...(input.personalityPrompt?.trim()
      ? [text(locale, "prompt.system.personality", { personality: input.personalityPrompt.trim() })]
      : []),
    ...(input.boardInfoPrompt ? [input.boardInfoPrompt] : []),
    ...(input.configPrompt ? [input.configPrompt] : []),
    text(locale, "prompt.system.inspection"),
    text(locale, "prompt.system.events"),
    text(locale, "prompt.system.facts"),
    // 仅显式 false 关闭工具说明；报告还要求原 supportsDebugReporting，开关不注册真实工具。
    ...(input.includeToolUseInstructions !== false ? [text(locale, "prompt.system.tools")] : []),
    text(locale, "prompt.system.confidential"),
    ...(input.supportsDebugReporting && input.includeToolUseInstructions !== false
      ? [text(locale, "prompt.system.reports")]
      : []),
  ].join("\n");
}

/** 原阶段／行动／参数提示逐段读取；现有约束和提交提示优先，空值仍用原缺省文案。 */
export function buildUserPrompt(input: UserPromptInput): string {
  const locale = input.locale ?? "zh-CN";
  const none = text(locale, "common.none");
  return [
    text(locale, "prompt.user.turn", {
      actor: input.actorId,
      phase: input.phase,
      stage: input.stage,
      speech: text(locale, input.isSpeechTurn ? "prompt.user.speech" : "prompt.user.no_speech"),
      context: input.stageContextHint ? ` ${input.stageContextHint}` : "",
    }),
    text(locale, "prompt.user.rules", {
      rules: input.stageDirective,
      status: input.statusDirective ? ` ${input.statusDirective}` : "",
    }),
    text(locale, "prompt.user.actions", {
      constraint:
        input.turnConstraintHint ||
        text(locale, input.requiresAction ? "prompt.user.required" : "prompt.user.optional"),
      tools: input.allowedTools.join(", ") || none,
      // 缺失／空 effective 列表在此显示 none，不自行复制 allowedTools 或新增本夜可用工具。
      effective: input.effectiveActionTools?.join(", ") || none,
    }),
    text(locale, "prompt.user.arguments", {
      hints: input.toolArgHints,
      targets: input.actionableIdsHint ? `; ${input.actionableIdsHint}` : "",
      usage: input.toolUsageHints?.length ? ` ${input.toolUsageHints.join(" ")}` : "",
      submission: input.actionSubmissionHint || text(locale, "prompt.user.submit"),
    }),
  ].join("\n");
}

/** 按原 Role 枚举值顺序筛正配比，两个 map 各在原位置读取 Map 与 callback，不缓存结果或吞错。 */
export function buildBoardInfoPrompt(input: BoardInfoPromptInput): string {
  const locale = input.locale ?? "zh-CN";
  // 此列表只固定本次筛出的角色；显示回调和 Map 仍各在原位置读取，不保证一次一致的快照。
  const roles = Object.values(Role).filter((role) => (input.roleCounts.get(role) ?? 0) > 0);
  return [
    text(locale, "prompt.board.title"),
    text(locale, "prompt.board.size", { count: input.totalPlayers }),
    text(locale, "prompt.board.lineup", {
      lineup:
        roles.map((role) => `${input.roleLabel(role)}x${input.roleCounts.get(role)}`).join(", ") ||
        "unknown",
    }),
    text(locale, "prompt.board.skills", {
      skills:
        roles.map((role) => `${input.roleLabel(role)}: ${input.roleSkillBrief(role)}`).join("; ") ||
        "unknown",
    }),
  ].join("\n");
}

/** attempt=1／2／其余分别选原三种文案；maxRetries 只插入文本，循环预算由真实编排者执行。 */
export function buildConstraintRetryPrompt(
  attempt: number,
  maxRetries: number,
  locale: Locale = "zh-CN",
): string {
  return text(
    locale,
    attempt === 1
      ? "prompt.retry.first"
      : attempt === 2
        ? "prompt.retry.second"
        : "prompt.retry.last",
    { attempt, max: maxRetries },
  );
}

/**
 * 提供不依赖角色策略的空行动与一次性脚本驱动。输入为引擎请求和预置匹配条目，
 * 输出为空动作或首个命中的原动作；脚本命中即从本驱动队列移除，不能据此视为领域已提交。
 * 仅管理本地脚本副本，不读取 World、调用模型或推导角色权限；特权基线决策归游戏驱动。
 */
import type { ActionProvider, ActionRequest, ToolCall } from "../../../core/domain";

/**
 * Noop 行为提供器：用于测试“无人行动”场景。
 */
export class NoopActionProvider implements ActionProvider {
  /**
   * 恒定返回空动作，用于测试空行动分支。
   */
  async getAction(_request: ActionRequest): Promise<ToolCall | null> {
    return null;
  }
}

/**
 * 脚本动作匹配条目。
 */
export interface ScriptedEntry {
  match: (request: ActionRequest) => boolean;
  action: ToolCall | null;
}

/**
 * Scripted 行为提供器：按预置脚本回放动作，适合单元测试与复现 bug。
 */
export class ScriptedActionProvider implements ActionProvider {
  private readonly entries: ScriptedEntry[];

  constructor(entries: ScriptedEntry[]) {
    this.entries = [...entries];
  }

  /**
   * 按首个命中规则返回脚本动作，并移除该规则避免重复触发。
   */
  async getAction(request: ActionRequest): Promise<ToolCall | null> {
    const index = this.entries.findIndex((entry) => entry.match(request));
    if (index === -1) {
      return null;
    }

    const [entry] = this.entries.splice(index, 1);
    return entry.action;
  }
}

/**
 * 负责生产回退的受限观察决策。输入是共同 PlayerObservation 和显式语言；
 * 输出为既有工具 handler 的竞争型行动，选择首个可见候选，不读取 World 或真实阵营。
 * 固定 next() 不推进游戏 RNG；原发言模板、狼聊形式和方向奇偶政策保持。
 * 自身当前资格与已知队友分开；请求旧工具名单不能恢复已被撤销的狼聊或刀资格。
 * 投影适配器仅传脱离且冻结的 DTO，资格、库存、目标和已付款动作仍由引擎重检。
 * 这是 F01 独立策略变化；无适合的观察行动时返回 null，不伪造严格必选动作。
 */
import { text, type Locale } from "@ai-werewolf-arena/game-text";
import type { ActionProvider, ActionRequest, ToolCall } from "../../../core/domain/actions";
import type {
  ObservedPlayerStrategy,
  PlayerObservation,
} from "../../../game/observation/player-observation";
import { createObservedBotContext } from "./observed_bot/context";
import { observedToolHandlers } from "./observed_bot/handlers";

const firstCandidate = Object.freeze({ next: () => 0 });

/** 仅持有展示语言；所有选择信息必须来自传入的玩家观察。 */
export class ObservationFallbackStrategy implements ObservedPlayerStrategy {
  constructor(private readonly locale: Locale) {}

  async decide(observation: PlayerObservation): Promise<ToolCall | null> {
    const context = createObservedBotContext(observation, firstCandidate, "competitive");
    for (const handler of observedToolHandlers) {
      if (!observation.request.allowedTools.includes(handler.tool)) continue;
      // F01：旧 allowedTools 只是请求名单；失效的自身狼聊／刀资格不能被回退恢复。
      // 两项资格分别判定，拒绝一个工具后仍按原顺序寻找其它已允许的候选。
      if (
        handler.tool === "speak_to_wolves" && observation.currentWolfActions.canChat !== true
      ) continue;
      if (
        handler.tool === "kill_vote" && observation.currentWolfActions.canVoteForKill !== true
      ) continue;
      if (handler.tool === "speak") {
        return {
          name: "speak",
          args: {
            text: text(
              this.locale,
              observation.request.context.trigger === "last_words"
                ? "fallback.last_words"
                : "fallback.speech",
              { actor: observation.request.actorId },
            ),
          },
        };
      }
      if (handler.tool === "speak_to_wolves") {
        return {
          name: "speak_to_wolves",
          args: { text: text(this.locale, "fallback.wolf_chat"), end_chat: false },
        };
      }
      if (handler.tool === "choose_direction") {
        return {
          name: "choose_direction",
          args: {
            direction: observation.request.actorId % 2 === 0 ? "clockwise" : "counter_clockwise",
          },
        };
      }
      const action = handler.decide(context);
      // null 是明确不行动，undefined 才继续检查下一工具；不能混淆两者。
      if (action !== undefined) return action;
    }
    return null;
  }
}

/**
 * 可信投影与受限策略之间的适配器。投影函数可以读取领域，但策略只接收 DTO。
 * 策略 Promise 直接返回；不增加等待层、预算、观察缓存或领域提交。
 */
export class ObservationFallbackActionProvider implements ActionProvider {
  constructor(
    private readonly project: (request: ActionRequest) => PlayerObservation,
    private readonly strategy: ObservedPlayerStrategy,
  ) {}

  getAction(request: ActionRequest): Promise<ToolCall | null> {
    return this.strategy.decide(this.project(request));
  }
}

/**
 * 负责按单个玩家的具名随机流和风格执行观察策略。输入为脱离 PlayerObservation；输出为工具选择或明确无行动。
 * 只保存此玩家的 RNG，不持有 World 或其他玩家原角色；候选知识不能授予资源写权，实际合法性仍由引擎重检。
 */
import type { ToolCall, RandomDraws } from "../../../core";
import type {
  ObservedPlayerStrategy,
  PlayerObservation,
} from "../../../game/observation/player-observation";
import { createObservedBotContext, type BotStyle } from "./observed_bot/context";
import { observedToolHandlers } from "./observed_bot/handlers";
export type { BotStyle } from "./observed_bot/context";

/** 只保有该玩家的具名 RNG，不取得 World 或其他玩家角色。 */
export class ObservedBot implements ObservedPlayerStrategy {
  constructor(
    private readonly random: RandomDraws,
    private readonly style: BotStyle,
  ) {}
  async decide(observation: PlayerObservation): Promise<ToolCall | null> {
    const context = createObservedBotContext(observation, this.random, this.style);
    for (const handler of observedToolHandlers) {
      if (!observation.request.allowedTools.includes(handler.tool)) continue;
      const action = handler.decide(context);
      if (action !== undefined) return action;
    }
    throw new Error("observed_bot_action_not_supported");
  }
}

/**
 * 负责从玩家观察、具名随机流和风格建立受限策略上下文。输入为已投影候选、自己的能力与行动历史；
 * 输出为同一观察及局部选择／重复目标判断，不查询 World、真实 camp 或提交行动。
 * undefined 允许继续寻找处理器，null 表示明确不行动；原策略和随机读取顺序保持。
 */
import type { RandomDraws, ToolCall } from "../../../../core";
import type { PlayerObservation } from "../../../../game/observation/player-observation";

export type BotStyle = "active" | "conservative" | "competitive" | "random";
export type ObservedBotContext = ReturnType<typeof createObservedBotContext>;
/** undefined 继续查找；null 是明确的终态不行动。 */
export type ObservedToolHandler = (context: ObservedBotContext) => ToolCall | null | undefined;
export interface ObservedToolEntry {
  readonly tool: ToolCall["name"];
  readonly decide: ObservedToolHandler;
}

export function createObservedBotContext(
  observation: PlayerObservation,
  random: RandomDraws,
  style: BotStyle,
) {
  const { request, knownAliveIds, ownState, teammateIds } = observation;
  const actor = request.actorId;
  const others = knownAliveIds.filter((id) => id !== actor);
  const pick = (ids: number[]) =>
    ids.length ? ids[Math.floor(random.next() * ids.length)] : undefined;
  const bound = observation.abilities.find((ability) => ability.id === request.context.ability_id);
  const ownActions = observation.ownNightActions ?? [];
  const allowed = (kind: "check" | "poison" | "guard", id: number) => {
    const policy =
      bound?.activation === "lucky" ||
      bound?.activation === "black_market" ||
      observation.abilities.some(
        (ability) =>
          (ability.activation === "lucky" || ability.activation === "black_market") &&
          ability.kind ===
            (kind === "check" ? "seer_check" : kind === "guard" ? "guard" : "potion"),
      ) ||
      ownActions.some((row) => row.kind === kind && row.lucky);
    return (
      !policy ||
      !ownActions.some(
        (row) =>
          row.kind === kind &&
          row.targetId === id &&
          (row.day === request.context.day ||
            (kind === "guard" && row.day === request.context.day - 1)),
      )
    );
  };
  return {
    observation,
    request,
    knownAliveIds,
    ownState,
    teammateIds,
    actor,
    others,
    pick,
    random,
    style,
    bound,
    allowed,
  };
}

/**
 * 负责规范玩家故障报告并按日次／阶段限流去重；输入是调用方上下文和原始报告字段，输出为拒绝、丢弃或接受标识。
 * 本服务实例独占三份去重／计数集合，实际报告记录归会话记录器，角色仅用作诊断元数据。
 * 只校验类别、严重程度和消息，不复验 actor/day/phase 的游戏许可，不提交动作或修改角色资源。
 * 直接报告记录及接受回调可传播失败；已经写入的记录和本地计数保留，不承诺事务回滚。
 */
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { World } from "../../../core/domain/world";
import { safeRecordLogicOp } from "../../../recording/session_recorder";
import { getSessionRecorder } from "../../../recording/recording_context";

export type AgentBugCategory = "flow" | "rule" | "state" | "logging" | "other";
export type AgentBugSeverity = "low" | "medium" | "high" | "critical";

/** actor/day/phase/stage 由调用方给定；unknown 三字段先规范，身份元数据稍后从 World 查询。 */
export interface AgentBugReportInput {
  actorId: number;
  day: number;
  phase: string;
  stage: string;
  category: unknown;
  severity: unknown;
  message: unknown;
}

/** 无效报告是工具拒绝；已限流报告仍 ok=true，但 accepted=false 且没有新报告标识。 */
export type AgentBugReportResult =
  | { ok: false; error: string; message: string }
  | { ok: true; accepted: false; dropped: true; reason: string }
  | { ok: true; accepted: true; report_id: string };

export interface AgentBugReportServiceOptions {
  maxPerActorPerDay?: number;
  /** 记录及去重账本更新之后同步调用；回调失败不撤销已接受前缀。 */
  onAccepted?: (report: NormalizedAgentBugReport, reportId: string) => void;
}

/** 只替换类别、级别和 trim 后消息，其余上下文字段保持输入值；不代表验证了游戏状态。 */
export interface NormalizedAgentBugReport extends Omit<
  AgentBugReportInput,
  "category" | "severity" | "message"
> {
  category: AgentBugCategory;
  severity: AgentBugSeverity;
  message: string;
}

const CATEGORIES = new Set<AgentBugCategory>(["flow", "rule", "state", "logging", "other"]);
const SEVERITIES = new Set<AgentBugSeverity>(["low", "medium", "high", "critical"]);

/**
 * SDK／ACP 使用同一份报告处理实现；各实例保持自己的去重状态，不共享全局计数账本。
 */
export class AgentBugReportService {
  // 三类键分别限制 actor/day 总量、同阶段名额和规范消息；跨阶段相同消息仍占同日重复键。
  private readonly acceptedScopes = new Set<string>();
  private readonly acceptedMessages = new Set<string>();
  private readonly acceptedCountByActorDay = new Map<string, number>();
  private readonly maxPerActorPerDay: number;

  constructor(
    private readonly world: World,
    private readonly options: AgentBugReportServiceOptions = {},
  ) {
    this.maxPerActorPerDay = Math.max(1, options.maxPerActorPerDay ?? 3);
  }

  report(input: AgentBugReportInput): AgentBugReportResult {
    const parsed = this.normalize(input);
    if (!parsed.ok) {
      this.recordRejected(input, parsed.error);
      return toolFailure(this.world.locale, parsed.error);
    }
    const report = parsed.value;
    const actorDayKey = `${report.actorId}|${report.day}`;
    const scopeKey = `${actorDayKey}|${report.phase}|${report.stage}`;
    const messageKey = `${actorDayKey}|${report.category}|${report.severity}|${normalizeMessage(report.message)}`;
    const acceptedCount = this.acceptedCountByActorDay.get(actorDayKey) ?? 0;

    // 拒绝原因按总量→阶段→消息首命中；计数检查不会提前消耗后续名额。
    const droppedReason =
      acceptedCount >= this.maxPerActorPerDay
        ? "report_bug_actor_day_rate_limited"
        : this.acceptedScopes.has(scopeKey)
          ? "report_bug_scope_rate_limited"
          : this.acceptedMessages.has(messageKey)
            ? "report_bug_duplicate_message"
            : undefined;
    if (droppedReason) {
      safeRecordLogicOp({
        scope: "llm_action_provider",
        op: "report_bug_dropped",
        actorId: report.actorId,
        phase: report.phase,
        status: "fallback",
        reason: droppedReason,
        input: { day: report.day, stage: report.stage },
      });
      return { ok: true, accepted: false, dropped: true, reason: droppedReason };
    }

    // 限流通过后才查询角色并直接追加诊断记录；Camp在其原字段位置晚读，未作行动授权。
    const role = this.world.getComponent(report.actorId, COMPONENT.Role);
    const reportId =
      getSessionRecorder()?.recordDebugReport({
        timestampMs: Date.now(),
        day: report.day,
        phase: report.phase,
        stage: report.stage,
        actorId: report.actorId,
        actorRole: role?.role ?? "unknown",
        actorCamp: (role && this.world.getComponent(report.actorId, COMPONENT.Camp)?.camp) ?? "unknown",
        category: report.category,
        severity: report.severity,
        message: report.message,
      }) ?? "rb-no-recorder";

    // 记录取得标识之后再依次消费三份名额；随后日志或回调失败仍保留已消费前缀。
    this.acceptedScopes.add(scopeKey);
    this.acceptedMessages.add(messageKey);
    this.acceptedCountByActorDay.set(actorDayKey, acceptedCount + 1);
    safeRecordLogicOp({
      scope: "llm_action_provider",
      op: "report_bug_recorded",
      actorId: report.actorId,
      phase: report.phase,
      status: "ok",
      output: {
        report_id: reportId,
        category: report.category,
        severity: report.severity,
      },
    });
    this.options.onAccepted?.(report, reportId);
    return { ok: true, accepted: true, report_id: reportId };
  }

  private normalize(
    input: AgentBugReportInput,
  ): { ok: true; value: NormalizedAgentBugReport } | { ok: false; error: string } {
    // 先完成类别／级别转换和消息trim，再按类别→级别→空消息→长度返回首错误；不吞转换异常。
    const category = String(input.category ?? "") as AgentBugCategory;
    const severity = String(input.severity ?? "") as AgentBugSeverity;
    const message = typeof input.message === "string" ? input.message.trim() : "";
    if (!CATEGORIES.has(category)) return { ok: false, error: "invalid_report_bug_category" };
    if (!SEVERITIES.has(severity)) return { ok: false, error: "invalid_report_bug_severity" };
    if (!message) return { ok: false, error: "invalid_report_bug_message_empty" };
    if (message.length > 300) return { ok: false, error: "invalid_report_bug_message_too_long" };
    return { ok: true, value: { ...input, category, severity, message } };
  }

  private recordRejected(input: AgentBugReportInput, reason: string): void {
    safeRecordLogicOp({
      scope: "llm_action_provider",
      op: "report_bug_rejected",
      actorId: input.actorId,
      phase: input.phase,
      status: "rejected",
      reason,
      input: {
        args: { category: input.category, severity: input.severity, message: input.message },
      },
    });
  }
}

/** 重复键统一大小写和空白，实际记录仍保留 trim 后的原消息；不改模型发言或游戏事件。 */
function normalizeMessage(message: string): string {
  return message.toLowerCase().replace(/\s+/g, " ").trim();
}

/**
 * 负责 SDK／ACP 提示中的玩家可见事件形状整理和固定元组编码；输入来自请求上下文，输出为排序事件或 JSON 文本。
 * 可见性与受众投影归上游，增量游标和发送失败归各提示会话；本模块不读取全局事件、补发秘密或授予动作权限。
 * 解析只核基本字段，未知 type 仍保留，payload 持同引用；不是 Proxy／getter 安全边界，访问或序列化异常直接传播。
 */
import { PlayerVisibleEvent } from "../../core/domain";

/** 非数组返回空；有效的正整数 seq 后写覆盖前写，再升序返回，既不验证连续性也不补缺号。 */
export function parsePlayerVisibleEvents(value: unknown): PlayerVisibleEvent[] {
  if (!Array.isArray(value)) return [];
  const bySeq = new Map<number, PlayerVisibleEvent>();
  for (const item of value) {
    if (!item || typeof item !== "object") continue;
    const event = item as Record<string, unknown>;
    if (
      typeof event.seq !== "number" ||
      !Number.isInteger(event.seq) ||
      event.seq <= 0 ||
      typeof event.type !== "string" ||
      !event.payload ||
      typeof event.payload !== "object" ||
      Array.isArray(event.payload)
    ) {
      continue;
    }
    // 保留原payload引用；无效条目被跳过，只有后续有效同序号事件才覆盖已接受值。
    bySeq.set(event.seq, {
      seq: event.seq,
      type: event.type,
      payload: event.payload as Record<string, unknown>,
    });
  }
  return [...bySeq.values()].sort((left, right) => left.seq - right.seq);
}

/** 固定顺序为玩家局部序号、机器事件名和原payload；tuple中不附全局序号或展示文案。 */
type PlayerVisibleEventTuple = [seq: number, type: string, payload: Record<string, unknown>];

function toTuple(event: PlayerVisibleEvent): PlayerVisibleEventTuple {
  return [event.seq, event.type, event.payload];
}

/** 单事件沿原 event 外壳编码；字段与payload原文不随locale改变，也不再次过滤受众。 */
export function encodePlayerVisibleEvent(event: PlayerVisibleEvent): string {
  return JSON.stringify({ event: toTuple(event) });
}

/** 原 events 外壳按调用方顺序编码；ACP调用方负责选取增量，本函数不排序、去重或推进游标。 */
export function encodePlayerVisibleEventBatch(events: PlayerVisibleEvent[]): string {
  return JSON.stringify({ events: events.map(toTuple) });
}

/**
 * 负责把 ACP 会话提交适配到共同 ActionTurn 窗口；输入为会话绑定原请求、turnId 和协议参数。
 * 输出保留待选行动 Promise、预检回执与问题报告；规则接收消费游戏 Gateway 的同一 owner。
 * 期限由选择窗口在原时点读取，registry close 只关闭自己的窗口；ACP 接受不提交库存或 settle 领域完成。
 * 错会话／turnId 只拒绝本次输入，不消耗别的有效窗口，成功选择后按原次序移除登记与 resolve。
 */
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { ActionRequest, ToolCall } from "../../../core/domain";
