/** 十一具名槽分别关联其原组件类型；该映射不创建实例，也不把两个槽的字段合成一个对象。 */
export interface ComponentMap {
  [COMPONENT.Identity]: IdentityComponent;
  // 角色身份／私有容器与实际阵营是两个独立槽；当前阵营不再镜像到 Role。
  [COMPONENT.Role]: RoleComponent;
  [COMPONENT.Camp]: CampComponent;
  [COMPONENT.Alive]: AliveComponent;
  [COMPONENT.VotingRight]: VotingRightComponent;
  [COMPONENT.StatusMarks]: StatusMarksComponent;
  [COMPONENT.Badge]: BadgeComponent;
  [COMPONENT.Victory]: VictoryComponent;
  [COMPONENT.Lovers]: LoversComponent;
  [COMPONENT.WallNote]: WallNoteComponent;
  [COMPONENT.DebatePenalty]: DebatePenaltyComponent;
}

/** 汇总既有槽的公开字段名，供写入类型排除其它槽字段；自定义扩展名仍可由具体输入保留。 */
type ComponentFields = {
  [K in ComponentName]: keyof ComponentMap[K];
}[ComponentName];

/**
 * 保留自定义扩展字段，同时在类型上排除其它槽的公开字段。Role 与 Camp 分属独立槽，
 * role／privateState 不能装入 Camp 槽，camp 不能装入 Role 槽；展示方法已退出组件结构。
 * optional never 与最终 never 分支仅约束编译期槽关系，不执行运行 shape 检查、冻结或授权，
 * 也不把扩展对象限制为精确字段集合。
 */
export type ComponentWrite<K extends ComponentName> = K extends ComponentName
  ? ComponentMap[K] & {
      [P in Exclude<ComponentFields, keyof ComponentMap[K]>]?: never;
    }
  : never;

/**
 * 负责原生命的存活值、版本及工厂描述符。输入为初始存活值；
 * 输出保留同一组件对象，只有存活值发生变化时推进版本，以识别复活后的新生命。
 * 身份表与描述符留在运行时；机制可记录版本数字快照（如 debatePenalty.lifeVersion），
 * 该数字不携带原组件或授权，描述符查询不执行访问器。
 * 展示语言与文案绑定已交游戏观察层；领域不格式化存活信息。
 */

/**
 * 存活状态组件：标记玩家是否仍在场。
 */
export interface AliveComponent {
  alive: boolean;
}

// 身份表只关联原组件；相同席位替换组件不会继承旧生命版本。
const lifeVersions = new WeakMap<AliveComponent, number>();
const originalDescriptors = new WeakMap<AliveComponent, PropertyDescriptor>();
/** 返回工厂访问器描述符的脱离副本；检查身份不会调用 alive getter。 */
export function aliveLifeDescriptor(component: AliveComponent): PropertyDescriptor | undefined {
  const descriptor = originalDescriptors.get(component);
  return descriptor && { ...descriptor };
}
/** 查询原版本；非工厂组件返回 undefined，不能据席位号伪造原体身份。 */
export function aliveLifeVersion(component: AliveComponent): number | undefined {
  return lifeVersions.get(component);
}

/**
 * 创建存活状态组件。
 */
export function createAliveComponent(
  alive: boolean = true,
): AliveComponent {
  const component: AliveComponent = {
    get alive() {
      return alive;
    },
    set alive(value: boolean) {
      if (typeof value !== "boolean") throw new Error("alive_state_invalid");
      // 死亡和复活都会推进版本；重复写同一值不制造新的死亡资格。
      if (value !== alive) {
        alive = value;
        lifeVersions.set(component, lifeVersions.get(component)! + 1);
      }
    },

  };
  originalDescriptors.set(component, Object.getOwnPropertyDescriptor(component, "alive")!);
  lifeVersions.set(component, 0);
  return component;
}

