  poisonClaims?: readonly NightPoisonClaim[];
  guardClaims?: readonly NightGuardClaim[];
  merchantBacklashes?: readonly NightMerchantBacklash[];
  blackMarketBacklashes?: readonly NightBlackMarketBacklash[];
  mechanicalEffects?: NightMechanicalEffects;
  awakenedEffects?: NightAwakenedEffects;
}

/** 本次运行的折叠结果；集合只读，当前实体印记仍由结算器消费。 */
export interface NightDamagePlan {
  readonly awakenedShields: ReadonlySet<EntityId>;
  readonly awakenedAttacks: ReadonlySet<EntityId>;
  readonly mechanical: MechanicalDamagePlan;
  readonly claimedPoisonTargets: ReadonlySet<EntityId>;
  readonly claimedGuardTargets: ReadonlySet<EntityId>;
  readonly guarded: ReadonlySet<EntityId>;
  readonly blackBacklashes: ReadonlySet<EntityId>;
  readonly radiantBacklashes: ReadonlySet<EntityId>;
  readonly backlashTargets: ReadonlySet<EntityId>;
  readonly foxInspections: ReadonlySet<EntityId>;
  readonly inspectionSources: ReadonlyMap<EntityId, ReadonlySet<DeathCause>>;
  readonly passiveImmuneTargets: ReadonlySet<EntityId>;
}

/** 在原 resolve 时点仅求值一次，传入同一 World，保留查询方法的 receiver。 */
export function planNightDamage(
  world: NightEffectQuery,
  effects: NightDamageEffects,
): NightDamagePlan {
  const awakenedShields = new Set(
    effects.awakenedEffects?.shields
      .filter((effect) => effect.isCurrent() && livingNightLife(world, nightIntentTarget(effect, "awakened-shield", () => effects.intentNight)))
      .map((effect) => nightIntentTarget(effect, "awakened-shield", () => effects.intentNight).id),
  );
  const awakenedAttacks = new Set(
    effects.awakenedEffects?.attacks
      .filter((effect) => effect.isCurrent() && livingNightLife(world, nightIntentTarget(effect, "awakened-attack", () => effects.intentNight)))
      .map((effect) => nightIntentTarget(effect, "awakened-attack", () => effects.intentNight).id),
  );
  // 先吸收原毒，避免其进入机械反射；返回毒随后仍按目标保护独立判定。
  const mechanical = planMechanicalDamage(
    world,
    effects.mechanicalEffects,
    effects.poisonClaims,
    awakenedShields,
    () => effects.intentNight,
  );
  const claimedPoisonTargets = new Set(effects.poisonClaims?.map((claim) => nightIntentTarget(claim, "original-poison", () => effects.intentNight).id));
  const claimedGuardTargets = new Set(effects.guardClaims?.map((claim) => claim.target.id));
  // 守护仍只检查原生命与印记对象身份；不能额外调用 isCurrent 改变既有规则。
  const guarded = new Set(
    effects.guardClaims
      ?.filter(
        (claim) =>
          livingNightLife(world, claim.target) &&
          world.getComponent(claim.target.id, COMPONENT.StatusMarks) === claim.marks,
      )
      .map((claim) => claim.target.id),
  );
  const blackBacklashes = new Set(
    effects.blackMarketBacklashes
      ?.filter((effect) => effect.isCurrent() && livingNightLife(world, effect.target))
      .map((effect) => effect.target.id),
  );
  const radiantBacklashes = new Set(
    effects.radiantBacklashes
      ?.filter((effect) => effect.isCurrent() && livingNightLife(world, effect.target))
      .map((effect) => effect.target.id),
  );
  const backlashTargets = new Set(
    effects.merchantBacklashes
      ?.filter((effect) => effect.isCurrent() && livingNightLife(world, effect.target))
      .map((effect) => effect.target.id),
  );

  const foxInspections = new Set(
    effects.foxInspections
      ?.filter((claim) => claim.isCurrent() && livingNightLife(world, claim.target))
      .map((claim) => claim.target.id),
  );
  const inspectionSources = new Map<EntityId, Set<DeathCause>>();
  for (const attack of [
    ...(effects.inspectionAttacks ?? []),
    ...(effects.retaliationAttacks ?? []).map((effect) => ({
      ...effect,
      cause: DeathCause.EvilKnightReflection,
    })),
  ]) {
    if (!attack.isCurrent() || !livingNightLife(world, attack.target)) continue;
    const sources = inspectionSources.get(attack.target.id) ?? new Set<DeathCause>();
    sources.add(attack.cause);
    inspectionSources.set(attack.target.id, sources);
  }

  const passiveImmuneTargets = new Set(
    [...(effects.nightImmunities ?? []), ...(effects.radiantShelters ?? [])]
      .filter((claim) => claim.isCurrent() && livingNightLife(world, claim.target))
      .map((claim) => claim.target.id),
  );
  return {
    awakenedShields,
    awakenedAttacks,
    mechanical,
    claimedPoisonTargets,
    claimedGuardTargets,
    guarded,
    blackBacklashes,
    radiantBacklashes,
    backlashTargets,
    foxInspections,
    inspectionSources,
    passiveImmuneTargets,
  };
}

/**
 * 负责单个目标的原夜间保护判定与致死来源规则。
 * 输入为只读折叠计划、原效果查询与当前印记读者；输出保留该目标的原死因顺序。
 * 仅专用取消命令可在原同守同救分支移除 Guard／Heal，不能添加或清空印记、修改生命、
 * 发布事实或消费库存。梦境、免疫与修饰效果保持晚读取及原失败前缀。
 * 原毒／反射毒使用折叠后的 owned 因果去向；外部 legacy 保留原集合后备政策。
 * 普通狼刀、机械额外刀和觉醒额外刀保留各自的保护规则，不归并不同死因。
 */
import { DeathCause } from "./deaths";
import { StatusMark, type EntityId } from "./identity";
import type { StatusMarksComponent } from "./components/status_marks";
import { livingNightLife, nightPoisonRouteTargets, nightPoisonRoutes, type NightPoisonRoute, type NightEffectQuery, type NightLifeReadScope } from "./night_effects";
import type { NightDamageEffects, NightDamagePlan } from "./night-damage-plan";

/**
 * 仅保留本目标在原时点查询的字段；不传入毒源、守护印记或库存命令。
 * 修饰死亡保留原生命引用，但此处只能读取，不能写入 Alive。
 */
export type NightDamageTargetEffects = Readonly<
  Pick<
    NightDamageEffects,
    "wolfImmuneTargets" | "protectedTargets" | "immuneNightTargets" | "consecutiveDeaths"
  >
> & {
  readonly modifierDeaths?: readonly NightLifeReadScope[];
};

/** 在原印记处理时点解析一个目标，不提前快照效果或重查有效性。 */
export function resolveNightDamageTarget(
  world: NightEffectQuery,
  entityId: EntityId,
  effects: NightDamageTargetEffects,
  plan: NightDamagePlan,
  marks: Readonly<Pick<StatusMarksComponent, "has">> | undefined,
  cancelOrdinaryProtection: () => void,
  captureAcceptedPoison?: (routes: readonly NightPoisonRoute[]) => void,
): DeathCause[] {
  const {
    awakenedShields,
    awakenedAttacks,
    mechanical,
    claimedPoisonTargets,
    claimedGuardTargets,
    guarded,
    blackBacklashes,
    radiantBacklashes,
    backlashTargets,
    foxInspections,
    inspectionSources,
  } = plan;
  // 原追加顺序保留：查验／反击在前，随后子狐、毒、各刀及反噬；不能统一排序。
  const sources: DeathCause[] = [...(inspectionSources.get(entityId) ?? [])];
  const hasGuard =
    marks?.has(StatusMark.GuardMark) === true &&
    (!claimedGuardTargets.has(entityId) || guarded.has(entityId));
  const hasHeal = marks?.has(StatusMark.HealMark) === true;
  // 保存进入此分支时的守／救读值；取消之后不重读印记，机械与觉醒刀仍用各自保护政策。
  const effectiveHeal = hasHeal && !hasGuard;
  const hasWolfKill =
    marks?.has(StatusMark.WolfKillMark) === true && !effects.wolfImmuneTargets?.includes(entityId);
  const hasDirectPoison =
    marks?.has(StatusMark.PoisonMark) === true &&
    (!claimedPoisonTargets.has(entityId) || nightPoisonRouteTargets(mechanical, entityId, "direct"));
  const hasPoison = hasDirectPoison || nightPoisonRouteTargets(mechanical, entityId, "reflected");
  // 毒独立于普通守护／解药冲突；不能被同守同救抵消。
  const dreamProtected = effects.protectedTargets?.includes(entityId) === true;
  const mechanicalShield = mechanical.shields.has(entityId);
  const awakenedShield = awakenedShields.has(entityId);
  if (foxInspections.has(entityId) && !dreamProtected) sources.push(DeathCause.FoxInspection);
  if (hasPoison && !dreamProtected && !awakenedShield) {
    sources.push(DeathCause.Poison);
    // 只在真实毒接受点携带来源；direct 复用原已读旗标，不能另查印记或扩大源资格。
    // 已反射路由独立保留，即使同目标同时存在另一直接毒，也不合并其 cause 身份。
    captureAcceptedPoison?.(
      nightPoisonRoutes(mechanical).filter(
        (route) => route.targetId === entityId && (route.route === "reflected" || hasDirectPoison),
      ),
    );
  }

  if (hasGuard && hasHeal) {
    // 同守同救互相抵消，但若同时被狼刀命中仍会死亡。
    // 命令内保留先移除守护、再移除解药的原顺序；第二步失败不能撤销第一步。
    cancelOrdinaryProtection();
    if (hasWolfKill && !dreamProtected && !mechanicalShield && !awakenedShield) {
      sources.push(DeathCause.WolfKill);
    }
  } else {
    if (
      hasWolfKill &&
      !dreamProtected &&
      !mechanicalShield &&
      !awakenedShield &&
      !(hasGuard || hasHeal)
    ) {
      sources.push(DeathCause.WolfKill);
    }
  }
  // 机械额外刀穿过普通守护，但仍受有效解药、梦境与机械／觉醒盾保护。
  if (
    mechanical.attacks.has(entityId) &&
    !effectiveHeal &&
    !dreamProtected &&
    !mechanicalShield &&
    !awakenedShield
  ) {
    sources.push(DeathCause.MechanicalKnife);
  }
  const ordinaryProtection = hasGuard !== hasHeal;
  if (
    awakenedAttacks.has(entityId) &&
    !ordinaryProtection &&
    !dreamProtected &&
    !mechanicalShield &&
    !awakenedShield
  ) {
    sources.push(DeathCause.AwakenedHiddenKnife);
  }
  // 此处必须晚读取：此前的取消可能已经提交，getter 失败保留已生效前缀。
  const nightImmune = effects.immuneNightTargets?.includes(entityId) === true;
  if (mechanical.failures.has(entityId) && !nightImmune)
    sources.push(DeathCause.MechanicalGuardFailure);
  if (blackBacklashes.has(entityId) && !nightImmune) sources.push(DeathCause.BlackMarketBacklash);
  if (backlashTargets.has(entityId) && !dreamProtected) sources.push(DeathCause.MerchantBacklash);
  if (radiantBacklashes.has(entityId) && !dreamProtected) sources.push(DeathCause.RadiantBacklash);
  if (effects.consecutiveDeaths?.includes(entityId)) sources.push(DeathCause.Dream);

  if (
    effects.modifierDeaths?.some(
      (target) => target.id === entityId && livingNightLife(world, target),
    )
  )
    sources.push(DeathCause.Ability);
  return sources;
}

/**
 * 负责真实夜间尝试的运行时身份。输入是准备夜间生命周期时已捕获的日次；
 * 输出为独立身份与同引用的只读元数据，不根据 day+1 推断另一夜。
 * 所有者仍是原流水线及交接接收方；身份不授予能力、存活或资源权限。
 * 同一结果的元数据不可枚举，旧结果／Proxy 不读取新增属性，不进入事件或 schema2。
 */
import { types } from "node:util";
export interface NightUnit {
  readonly id: symbol;
  readonly day: number;
}
const units = new WeakSet<object>();
const results = new WeakSet<object>();
const NIGHT_UNIT = Symbol("night_unit");
type NightBound = { readonly [NIGHT_UNIT]: NightUnit };

/** 每个真实 prepare 尝试独立创建，不查询 World、时钟或游戏 RNG。 */
export function openNightUnit(day: number): NightUnit {
  const unit = Object.freeze({ id: Symbol("night"), day });
  units.add(unit);
  return unit;
}
export function isNightUnit(unit: unknown): unit is NightUnit {
  return typeof unit === "object" && unit !== null && units.has(unit);
}
/** 元数据留在同一夜间对象；品牌只保存身份，不建立另一份 World 状态。 */
export function attachNightUnit<T extends object>(result: T, unit: NightUnit | undefined): T {
  if (!isNightUnit(unit)) return result;
  Object.defineProperty(result, NIGHT_UNIT, { value: unit });
  results.add(result);
  return result;
}
/** 外部旧对象即使有同名 getter 或 Proxy，也不触发新增反射读取。 */
export function nightUnitOf(result: object): NightUnit | undefined {
  return results.has(result) && !types.isProxy(result) ? (result as NightBound)[NIGHT_UNIT] : undefined;
}

/**
 * 负责运行时夜间效果声明、原生命身份检查与机械伤害折叠。
 * 输入为原组件引用和已付效果；输出为有来源的 intent、原生命版本及保序伤害折叠。
 * 新 owned intent 消费类别／夜时点／原体因果链，旧注入对象保留原读取和接受宽度。
 * 所有者保留资源提交权限，句柄不进入序列化或玩家知识，本模块不将玩家标记为死亡。
 */
import type { DeathCause } from "./deaths";
import { COMPONENT } from "./components/names";
import { aliveLifeVersion, type AliveComponent } from "./components/alive";
import type { World } from "./world";
import type { EntityId } from "./identity";
import type { StatusMarksComponent } from "./components/status_marks";

/** 查询原生命和印记身份，不暴露组件修改命令。 */
export interface NightEffectQuery {
  getComponent(id: EntityId, name: typeof COMPONENT.Alive): Readonly<AliveComponent> | undefined;
  getComponent(id: EntityId, name: typeof COMPONENT.StatusMarks): object | undefined;
}

/** 仅供运行时的身份绑定；组件引用不进入事件或录制。 */
export interface NightLifeScope {
  readonly id: EntityId;
  readonly life: AliveComponent;
  readonly version: number;
}
/** 同一原体的只读查询视图；不复制组件，也不授予修改存活状态的权限。 */
export type NightLifeReadScope = Omit<NightLifeScope, "life"> & {
  readonly life: Readonly<AliveComponent>;
};
export interface NightPoisonClaim {
  readonly source: NightLifeScope;
  readonly target: NightLifeScope;
  readonly isCurrent?: () => boolean;
}

/**
 * 单次已付效果的运行时来源。源原体及目标句柄仅属于本夜，不进入事件或 schema2。
 * 每份效果的因果 ID 是独立 Symbol；捕获局部值只用于诊断描述，不是去重或稳定归档 ID。
 * 创建身份不读 World、时钟或 RNG，也不授予行动资格。
 */
export interface NightIntentOrigin {
  readonly family: "mechanical" | "awakened" | "witch" | "demon-witch" | "lucky" | "black-market" | "scholar-mentor";
  readonly day: number;
  readonly stage: "mechanical_skill" | "mechanical_attack" | "awakened_skill" | "awakened_attack" | "witch" | "lucky" | "black_market_recipient" | "scholar_mentor_bonus";
  readonly actorId: EntityId;
  readonly actorLife: NightLifeReadScope;
  /** 原行动目标；反射不改写它，实际反射落点另存 NightPoisonRoute。 */
  readonly requestedTargetId: EntityId | null;
  /** 创建时绑定的 effect.target.id，与 requestedTargetId 或反射落点分别表达。 */
  readonly effectiveTargetId: EntityId;
  readonly abilityId: string;
  readonly sourceVersion: number;
  readonly targetVersion: number;
  readonly sourceBody: Readonly<AliveComponent>;
  readonly targetBody: Readonly<AliveComponent>;
  /** 每份效果的独立运行时身份；description 只是诊断标签，不能用于去重。 */
  readonly causeId: symbol;
}
export type NightMechanicalIntentKind = "mechanical-shield" | "mechanical-attack" | "mechanical-failure";
export type NightAwakenedIntentKind = "awakened-shield" | "awakened-attack";
export type NightIntentKind = NightMechanicalIntentKind | NightAwakenedIntentKind | "original-poison";
export interface NightMechanicalIntent<K extends NightMechanicalIntentKind = NightMechanicalIntentKind> extends NightMechanicalEffect {
  readonly kind: K;
  readonly origin: NightIntentOrigin;
}
export interface NightAwakenedIntent<K extends NightAwakenedIntentKind = NightAwakenedIntentKind> extends NightAwakenedEffect {
  readonly kind: K;
  readonly origin: NightIntentOrigin;
}
export interface NightOriginalPoisonIntent extends NightPoisonClaim {
  readonly kind: "original-poison";
  readonly origin: NightIntentOrigin;
}
type OriginInput = Omit<NightIntentOrigin, "actorId" | "effectiveTargetId" | "causeId" | "sourceVersion" | "targetVersion" | "sourceBody" | "targetBody">;

// 只标记由本 owner 构造的对象身份，不复制 effects、不按 World 存第二份状态。
// 旧注入对象即使带有同名 getter，也不被当作新 intent 或读取其额外字段。
const ownedIntents = new WeakSet<object>();
function annotateIntent<T extends { readonly target: NightLifeScope }, K extends NightIntentKind>(
  effect: T,
  kind: K,
  origin: OriginInput,
  actorId: EntityId,
): T & Readonly<{ kind: K; origin: NightIntentOrigin }> {
  if (ownedIntents.has(effect)) throw new Error("night_effect_intent_already_owned");
  const effectiveTargetId = effect.target.id;
  const causeId = Symbol(`effect:${origin.day}:${origin.family}:${origin.stage}:${actorId}:${kind}:${origin.abilityId}:${origin.requestedTargetId}:${effectiveTargetId}`);
  const captured = Object.freeze({
    ...origin, actorId, effectiveTargetId, causeId, sourceVersion: origin.actorLife.version, targetVersion: effect.target.version,
    sourceBody: origin.actorLife.life, targetBody: effect.target.life,
  });
  // 只锁定新增协议字段，不冻结原 target/callback；整个 origin 不能被重写绕过原体校验。
  Object.defineProperties(effect, {
    kind: { value: kind, enumerable: true },
    origin: { value: captured, enumerable: true },
  });
  ownedIntents.add(effect);
  return effect as T & Readonly<{ kind: K; origin: NightIntentOrigin }>;
}
/** 机械盾、额外刀与重复守失败保持各自类别及原 owner callback。 */
export function mechanicalNightIntent<K extends NightMechanicalIntentKind>(
  kind: K, effect: NightMechanicalEffect, origin: OriginInput & { readonly family: "mechanical" },
): NightMechanicalIntent<K> {
  return annotateIntent(effect, kind, origin, effect.actorId);
}
/** 觉醒效果不因已付瓶数或首次死亡而丢失原 callback 的专有规则。 */
export function awakenedNightIntent<K extends NightAwakenedIntentKind>(
  kind: K, effect: NightAwakenedEffect, origin: OriginInput & { readonly family: "awakened" },
): NightAwakenedIntent<K> {
  return annotateIntent(effect, kind, origin, effect.actorId);
}
/** 原毒与机械返回毒是不同链路；此 factory 只标记原已付毒。 */
export function originalPoisonIntent(effect: NightPoisonClaim, origin: OriginInput): NightOriginalPoisonIntent {
  return annotateIntent(effect, "original-poison", origin, effect.source.id);
}

/**
 * 在原 target 读取点消费新协议的类别/夜时点/因果链；不替代原 current 或生命重检。
 * 旧 claim/effect 完整保留原读取行为，包括额外 kind/origin getter 从不被调用。
 * 新协议错类别/夜时点属于约束强化；拒绝时不回滚先前已付库存或事实。
 */
export function nightIntentTarget(
  effect: { readonly target: NightLifeScope }, expected: NightIntentKind, night?: () => number | undefined,
): NightLifeScope {
  if (ownedIntents.has(effect)) {
    const intent = effect as Readonly<{ kind: NightIntentKind; origin: NightIntentOrigin; target: NightLifeScope }>;
    if (intent.kind !== expected) throw new Error("night_effect_intent_kind_mismatch");
    const day = night?.();
    if (day !== undefined && intent.origin.day !== day) throw new Error("night_effect_intent_night_mismatch");
    if (!intent.origin.causeId || intent.origin.actorLife.id !== intent.origin.actorId || intent.origin.actorLife.version !== intent.origin.sourceVersion || intent.origin.actorLife.life !== intent.origin.sourceBody)
      throw new Error("night_effect_intent_source_mismatch");
    const target = intent.target;
    if (target.id !== intent.origin.effectiveTargetId || target.version !== intent.origin.targetVersion || target.life !== intent.origin.targetBody)
      throw new Error("night_effect_intent_target_mismatch");
    return target;
  }
  return effect.target;
}

/** 仅在原毒 source 读取位置校验源句柄，不新增施毒者存活或窗口规则。 */
export function nightIntentPoisonSource(claim: NightPoisonClaim): NightLifeScope {
  const source = claim.source;
  if (ownedIntents.has(claim) && source !== (claim as NightOriginalPoisonIntent).origin.actorLife)
    throw new Error("night_effect_intent_source_mismatch");
  return source;
}

/** 在原反射 actorId 读取点核对来源，旧对象仍只执行一次同一属性读取。 */
export function nightIntentMechanicalActor(effect: NightMechanicalEffect): EntityId {
  const actorId = effect.actorId;
  if (ownedIntents.has(effect) && actorId !== (effect as NightMechanicalIntent).origin.actorId)
    throw new Error("night_effect_intent_source_mismatch");
  return actorId;
}
export interface NightFoxInspectionClaim {
  readonly target: NightLifeScope;
  /** 首日警长结算前切换阶段不会撤销原目标绑定。 */
  readonly isTargetCurrent: () => boolean;
  readonly isCurrent: () => boolean;
}
export interface NightGuardClaim {
  readonly isCurrent?: () => boolean;
  readonly contribution?: object;
  readonly target: NightLifeScope;
  readonly marks: StatusMarksComponent;
}
export interface NightMerchantBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export interface NightBlackMarketBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
/** 吞噬反噬是独立攻击，不归入商人效果或梦境死亡。 */
export interface NightRadiantBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export function captureNightLife(world: World, id: EntityId): NightLifeScope | null {
  const life = world.getComponent(id, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  return life?.alive && version !== undefined ? { id, life, version } : null;
}
export function sameNightLife(world: NightEffectQuery, scope: NightLifeReadScope): boolean {
  return (
    world.getComponent(scope.id, COMPONENT.Alive) === scope.life &&
    aliveLifeVersion(scope.life) === scope.version
  );
}
export function livingNightLife(world: NightEffectQuery, scope: NightLifeReadScope): boolean {
  return sameNightLife(world, scope) && scope.life.alive;
}

/** 已提交机械效果绑定原体；库存仍由具体机制所有者持有。 */
export interface NightMechanicalEffect {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  /** 只读重检提交者的角色、状态、生命与阶段，不修改原体。 */
  readonly isCurrent: () => boolean;
}
export interface NightMechanicalEffects {
  readonly shields: readonly NightMechanicalEffect[];
  readonly attacks: readonly NightMechanicalEffect[];
  readonly failures: readonly NightMechanicalEffect[];
}
/** 觉醒守护吸收毒药；其额外狼刀按普通保护规则判定。 */
export interface NightAwakenedEffect {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  /** 已付款效果重检原所有者；行动窗口关闭不等于撤销合法已付效果。 */
  readonly isCurrent: () => boolean;
}
export interface NightAwakenedEffects {
  readonly shields: readonly NightAwakenedEffect[];
  readonly attacks: readonly NightAwakenedEffect[];
}
/** 仅全知视角的因果事实；玩家投影不得泄露施毒来源。 */
export interface NightPoisonReflection {
  readonly actorId: EntityId;
  readonly protectedTargetId: EntityId;
  readonly casterId: EntityId;
}
/** 原毒经折叠后的实际去向；反射改变目标，但保留原独立因果身份及原体链。 */
export interface NightPoisonRoute {
  readonly route: "direct" | "reflected";
  readonly origin: NightIntentOrigin;
  readonly targetId: EntityId;
  readonly target: NightLifeReadScope;
}
// 因果链属于本次伤害计划，而非另一份世界状态。非枚举 Symbol 保持原输出／归档形状。
const POISON_ROUTES = Symbol("night_poison_routes");
const NO_POISON_ROUTES: readonly NightPoisonRoute[] = Object.freeze([]);
// 只登记本 owner 的返回对象身份；外部 legacy plan／Proxy 不读取新增 Symbol。
// 路由数据仍仅存于同一计划，这个品牌不保存目标、库存或另一份世界状态。
const ownedDamagePlans = new WeakSet<object>();
export interface MechanicalDamagePlan {
  readonly shields: ReadonlySet<EntityId>;
  readonly directPoisonTargets: ReadonlySet<EntityId>;
  readonly reflectedPoisonTargets: ReadonlySet<EntityId>;
  readonly attacks: ReadonlySet<EntityId>;
  readonly failures: ReadonlySet<EntityId>;
  readonly reflections: readonly NightPoisonReflection[];
  readonly [POISON_ROUTES]?: readonly NightPoisonRoute[];
}
/** Wave／单目标结算的运行时输入；这里只读既有折叠结果，不重查资格或库存。 */
export function nightPoisonRoutes(plan: MechanicalDamagePlan): readonly NightPoisonRoute[] {
  return ownedDamagePlans.has(plan) ? plan[POISON_ROUTES] ?? NO_POISON_ROUTES : NO_POISON_ROUTES;
}
/** owned 路由参与毒的接受；旧集合仍含 owned 目标并作 OR 后备，尚未被路由完全替代。 */
export function nightPoisonRouteTargets(
  plan: MechanicalDamagePlan, targetId: EntityId, route: NightPoisonRoute["route"],
): boolean {
  return nightPoisonRoutes(plan).some((cause) => cause.route === route && cause.targetId === targetId) ||
    (route === "direct" ? plan.directPoisonTargets : plan.reflectedPoisonTargets).has(targetId);
}
function recordOwnedPoisonRoute(
  routes: NightPoisonRoute[], poison: NightPoisonClaim, route: NightPoisonRoute["route"],
  target: NightLifeScope, targetId: EntityId,
): void {
  if (ownedIntents.has(poison))
    routes.push(Object.freeze({ route, origin: (poison as NightOriginalPoisonIntent).origin, targetId, target }));
}
/** 每份原毒只折叠一次；反射毒不再送回盾内，避免递归反射。 */
export function planMechanicalDamage(
  world: NightEffectQuery,
  effects: NightMechanicalEffects | undefined,
  poisons: readonly NightPoisonClaim[] = [],
  absorbedPoisonTargets: ReadonlySet<EntityId> = new Set(),
  intentNight?: () => number | undefined,
): MechanicalDamagePlan {
  // 有效盾按贡献顺序覆盖同一目标，反射事实使用最终选中盾的行动者。
  const shields = new Map<EntityId, NightMechanicalEffect>();
  for (const shield of effects?.shields ?? []) {
    if (shield.isCurrent() && livingNightLife(world, nightIntentTarget(shield, "mechanical-shield", intentNight))) {
      shields.set(nightIntentTarget(shield, "mechanical-shield", intentNight).id, shield);
    }
  }
  const directPoisonTargets = new Set<EntityId>();
  const reflectedPoisonTargets = new Set<EntityId>();
  const reflections: NightPoisonReflection[] = [];
  const poisonRoutes: NightPoisonRoute[] = [];
  // current 回调仅显式 false 撤销已付毒；直接毒不新增源存活门禁，反射才在原位置重检源生命。
  for (const poison of poisons) {
    if (
      poison.isCurrent?.() === false ||
      !livingNightLife(world, nightIntentTarget(poison, "original-poison", intentNight)) ||
      absorbedPoisonTargets.has(nightIntentTarget(poison, "original-poison", intentNight).id)
    )
      continue;
    const shield = shields.get(nightIntentTarget(poison, "original-poison", intentNight).id);
    if (!shield) {
      const target = nightIntentTarget(poison, "original-poison", intentNight), targetId = target.id;
      directPoisonTargets.add(targetId);
      recordOwnedPoisonRoute(poisonRoutes, poison, "direct", target, targetId);
      continue;
    }
    if (livingNightLife(world, nightIntentPoisonSource(poison))) {
      const target = nightIntentPoisonSource(poison), targetId = target.id;
      reflectedPoisonTargets.add(targetId);
      recordOwnedPoisonRoute(poisonRoutes, poison, "reflected", target, targetId);
      reflections.push({
        actorId: nightIntentMechanicalActor(shield),
        protectedTargetId: nightIntentTarget(poison, "original-poison", intentNight).id,
        casterId: nightIntentPoisonSource(poison).id,
      });
    }
  }
  const attacks = new Set<EntityId>();
  const failures = new Set<EntityId>();
  for (const attack of effects?.attacks ?? []) {
    if (attack.isCurrent() && livingNightLife(world, nightIntentTarget(attack, "mechanical-attack", intentNight)))
      attacks.add(nightIntentTarget(attack, "mechanical-attack", intentNight).id);
  }
  for (const failure of effects?.failures ?? []) {
    if (failure.isCurrent() && livingNightLife(world, nightIntentTarget(failure, "mechanical-failure", intentNight)))
      failures.add(nightIntentTarget(failure, "mechanical-failure", intentNight).id);
  }
  const plan: MechanicalDamagePlan = {
    shields: new Set(shields.keys()),
    directPoisonTargets,
    reflectedPoisonTargets,
    attacks,
    failures,
    reflections,
  };
  Object.defineProperty(plan, POISON_ROUTES, { value: Object.freeze(poisonRoutes) });
  ownedDamagePlans.add(plan);
  return plan;
}

/** 有限纯白查验规则的原所有者与目标绑定。 */
export interface NightInspectionAttack {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  readonly cause: DeathCause.PureWhiteInspection | DeathCause.WolfWitchInspection;
  readonly isCurrent: () => boolean;
}

/** 恶灵骑士反击在原行动接受时付款，于夜末按原体绑定结算。 */
export interface NightRetaliationAttack {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}

/** 持续被动夜间免疫保留原生命与角色授权。 */
export interface NightImmunityClaim {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}

/**
 * 负责共用参与者的原生命、Role 与私有容器引用捕获和晚复验。输入为原 World／玩家 ID，
 * 输出保留原可写快照及当前性布尔值；不写 World、资源、阶段或领域许可。
 * 只复用原生命版本规则，Role 字段按原普通属性读取；getter／Proxy 可执行并按原时点抛错。
 * 阵营在原值位置晚读当前 Camp；不校验枚举／JSON／完整槽，不捕获阵营组件引用或冻结快照。
 */
import { COMPONENT } from "./components/names";
import type { Camp } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "./components/role";
import type { World } from "./world";
import { captureNightLife, livingNightLife, type NightLifeScope } from "./night_effects";

/** 保原可写顶层字段与组件引用；camp 是捕获的当前阵营值，可缺失；同值组件替换不撤权，也不授独立行动权限。 */
export interface OriginalParticipant {
  life: NightLifeScope;
  role: RoleComponent;
  roleId: RoleComponent["role"];
  camp: Camp | undefined;
  state: RoleComponent["privateState"];
}
/** 原生命先捕获，再查询 Role；仅两者存在才按 role→camp→privateState 读取，不复制或提前取字段。 */
export function captureOriginalParticipant(world: World, id: number): OriginalParticipant | null {
  const life = captureNightLife(world, id),
    role = world.getComponent(id, COMPONENT.Role);
  return life && role
    ? { life, role, roleId: role.role, camp: world.getComponent(id, COMPONENT.Camp)?.camp, state: role.privateState }
    : null;
}
/** 生命／版本先短路，再核同 Role 引用及原三个字段；不新增 descriptor、Camp 引用或状态内容检查。 */
export function sameOriginalParticipant(world: World, snapshot: OriginalParticipant): boolean {
  return (
    livingNightLife(world, snapshot.life) &&
    world.getComponent(snapshot.life.id, COMPONENT.Role) === snapshot.role &&
    snapshot.role.role === snapshot.roleId &&
    world.getComponent(snapshot.life.id, COMPONENT.Camp)?.camp === snapshot.camp &&
    snapshot.role.privateState === snapshot.state
  );
}

/**
 * 负责把普通自有数据复制为脱离原存储的值；输入任意值和递归限制，输出新对象／数组或原始值。
 * 拒绝 Node Proxy、访问器、符号键、非有限数、循环和超限结构；不执行字段 getter。
 * 结果只携带数据，不能重建原体身份、租约或提交权限；本函数不安装状态或修改来源对象。
 */
import { types } from "node:util";
/** seen 跟踪当前递归路径；同一非循环对象被多处引用时，各处分别复制。 */
export function snapshotPlainData(
  value: unknown,
  seen = new Set<object>(),
  depth = 0,
  arrayLimit = 256,
  errorCode = "plain_data_invalid",
): unknown {
  if (
    value === null ||
    ["string", "boolean"].includes(typeof value) ||
    (typeof value === "number" && Number.isFinite(value))
  )
    return value;
  if (!value || typeof value !== "object" || types.isProxy(value) || depth > 16 || seen.has(value))
    throw new Error(errorCode);
  const array = Array.isArray(value),
    prototype = Object.getPrototypeOf(value);
  if (prototype !== (array ? Array.prototype : Object.prototype) && prototype !== null)
    throw new Error(errorCode);
  seen.add(value);
  try {
    // 一次取得自身描述符，再递归处理 value；不用普通属性读取触发调用方访问器。
    const descriptors = Object.getOwnPropertyDescriptors(value),
      result: Record<string, unknown> = {};
    if (Reflect.ownKeys(descriptors).some((key) => typeof key !== "string"))
      throw new Error(errorCode);
    for (const [key, d] of Object.entries(descriptors)) {
      if (array && key === "length") continue;
      if (!("value" in d) || !d.enumerable) throw new Error(errorCode);
      // defineProperty 能安全承载名为 __proto__ 的数据键；对象副本字段默认不可写、不可配置。
      Object.defineProperty(result, key, {
        enumerable: true,
        value: snapshotPlainData(d.value, seen, depth + 1, arrayLimit, errorCode),
      });
    }
    if (!array) return result;
    // 数组必须稠密、只含索引且不超过限制；最终返回的新数组保持普通可写数组行为。
    const length = descriptors.length?.value;
    if (
      !Number.isSafeInteger(length) ||
      length < 0 ||
      length > arrayLimit ||
      Object.keys(result).length !== length ||
      !Array.from({ length }, (_, i) => Object.hasOwn(result, i)).every(Boolean)
    )
      throw new Error(errorCode);
    return Array.from({ length }, (_, i) => result[i]);
  } finally {
    // 无论返回还是抛错都退出当前路径，调用方传入的其它 seen 标记不在此清除。
    seen.delete(value);
  }
}

/**
 * 负责每局具名随机流；输入种子与路径，输出确定性抽样、独立子流和洗牌副本。
 * 子流只依赖原种子与名字路径，不依赖父流已抽取次数；算法标识用于严格复现，不在此改版本。
 * 元数据及路径冻结，流内部计数仍由实例拥有；抽样能力不包含派生其它流的权限。
 */
export const RANDOM_ALGORITHM = "mulberry32-fnv1a-utf16-v1" as const;
export const RANDOM_STREAM_POLICY = "named-path-v1" as const;

/** 原种子字符串、算法标识和有序路径；trim 仅检查非空，不规范化保存的名字。 */
export interface RandomMetadata {
  seed: string;
  algorithm: typeof RANDOM_ALGORITHM;
  streamPolicy: typeof RANDOM_STREAM_POLICY;
  path: readonly string[];
}

/** 完整运行流可查看复现资料和创建子流；next 每次推进该实例自己的状态。 */
export interface RandomSource {
  readonly metadata: RandomMetadata;
  next(): number;
  fork(name: string): RandomSource;
}

/** 决策方仅取得抽样入口，不取得种子、路径或派生其它流的接口。 */
export interface RandomDraws {
  next(): number;
}

/** 冻结包装对象而不复制流；每次调用仍晚读 source.next 并保原方法 receiver。 */
export function randomDraws(source: RandomSource): RandomDraws {
  return Object.freeze({ next: () => source.next() });
}

class SeededRandom implements RandomSource {
  readonly metadata: RandomMetadata;
  private state: number;

  constructor(seed: string, path: readonly string[] = []) {
    if (!seed.trim()) throw new Error("random_seed_empty");
    this.metadata = Object.freeze({
      seed,
      algorithm: RANDOM_ALGORITHM,
      streamPolicy: RANDOM_STREAM_POLICY,
      path: Object.freeze([...path]),
    });
    // 固定 JSON 数组与 UTF-16 码元参与 FNV-1a；改序列化或按码点迭代都会改变复现序列。
    const input = JSON.stringify([seed, ...path]);
    let hash = 0x811c9dc5;
    for (let index = 0; index < input.length; index++)
      hash = Math.imul(hash ^ input.charCodeAt(index), 0x01000193) >>> 0;
    this.state = hash;
  }

  /** Mulberry32 以无符号 32 位状态推进，输出落在 [0, 1)。 */
  next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let value = this.state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 0x100000000;
  }

  /** 同种子／路径／名字重复 fork 得到同序列的新实例，不消耗当前流。 */
  fork(name: string): RandomSource {
    if (!name.trim()) throw new Error("random_stream_name_empty");
    return new SeededRandom(this.metadata.seed, [...this.metadata.path, name]);
  }
}

/** 未传 seed 时才创建随机 UUID；有 seed 的调用保持显式确定性。 */
export function createRandom(seed: string = crypto.randomUUID()): RandomSource {
  return new SeededRandom(seed);
}

/** Fisher–Yates 只改新数组；由尾到头每轮抽取一次，不校验调用方自定义 next 的返回范围。 */
export function shuffled<T>(values: readonly T[], random: RandomSource): T[] {
  const result = [...values];
  for (let index = result.length - 1; index > 0; index--) {
    const target = Math.floor(random.next() * (index + 1));
    [result[index], result[target]] = [result[target], result[index]];
  }
  return result;
}

/**
 * 负责胜利条件的有序委托与覆盖结果优先选择。输入为原 World、只读条件 ID、检查点及覆盖数据；输出为首个原判定或 null。
 * 本入口不改变参数数组或封存结果，真实检查点执行与终局仍由 PhaseManager 持有。
 */
import type { VictoryCheckpoint } from "@ai-werewolf-arena/game-contract";
import { WinDecision, WinCondition } from "../model";
import { World } from "../world";

/**
 * 胜负判定注册中心抽象：由机制层实现并在装配期注入。
 */
export interface WinConditionEvaluator {
  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null;
}

/**
 * 胜负条件入口：委托机制层 WinConditionRegistry。
 */
export class ConditionRegistry {
  private readonly winRegistry: WinConditionEvaluator;

  constructor(winRegistry: WinConditionEvaluator) {
    this.winRegistry = winRegistry;
  }

  /**
   * 按指定胜负模式执行胜负判定。
   */
  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null {
    return this.winRegistry.evaluate(world, condition, checkpoint);
  }

  /**
   * 按给定顺序评估多个胜负模式，命中即返回。
   */
  evaluateMany(
    world: World,
    conditions: readonly WinCondition[],
    checkpoint?: VictoryCheckpoint,
    overrides: Partial<Record<WinCondition, WinDecision>> = {},
  ): WinDecision | null {
    for (const condition of conditions) {
      const result = overrides[condition] ?? this.evaluate(world, condition, checkpoint);
      if (result) {
        return result;
      }
    }
    return null;
  }
}

/**
 * 负责角色标签到工具列表的登记；输入角色与有序工具名，输出列表的独立浅副本。
 * 构造时给既有角色空列表，登记保持原工具顺序和重复项，不校验实际库存或请求阶段。
 * 查询是配置资料，真实工具预检、当前资格与提交仍由接收器和机制拥有。
 */
import { Role, ToolName } from "../model";

/**
 * 角色工具注册表：
 * 负责“角色 -> 可调用工具列表”的集中管理。
 */
export class RoleRegistry {
  private readonly toolMap: Map<Role, ToolName[]> = new Map();

  constructor() {
    for (const role of Object.values(Role)) {
      this.toolMap.set(role, []);
    }
  }

  /**
   * 返回登记资料副本，缺项返回新空数组；这不证明当前玩家有权调用这些工具。
   */
  getAllowedTools(role: Role): ToolName[] {
    return [...(this.toolMap.get(role) ?? [])];
  }

  /**
   * 保存传入数组的副本，覆盖同角色旧表；不合并或删除重复工具名。
   */
  registerAllowedTools(role: Role, tools: ToolName[]): void {
    this.toolMap.set(role, [...tools]);
  }
}

/**
 * 负责四种原有序协议及动态窗口协议的请求绑定与有限运行租约。输入为原请求、机制晚查询和期限别名；
 * 输出为同一 scope 引用和一次完成通知，只写本实例的请求／租约元数据，不写 World、生命或库存。
 * 各实例保独立表及稳定传播回调；同请求可多绑定，但真实窗口只打开对应一个交付 turn。
 * 原 envelope 或领域当前性观察失配永久关闭共同许可；别名自己的字段失配只退役该别名。
 * 合法期限别名共享最早绝对预算，观察到期后时钟回退也不复活。字段 pin 只保顶层原值引用，
 * 不深复制／冻结提示或 feed，不把相同 JSON、readonly 或请求字段当成领域许可。
 * Provider 返回不是付款；窗口完整付款后才 complete，状态先落再通知，晚异常不能二次结算。
 */
import type { ActionRequest } from "./actions";
import { bindRequestDeliveryGuard, registerRequestAliasPropagation, settleRequestDelivery } from "./request_delivery";

/** 仅晚读原 scope 字段／活跃表；不接受整个请求回调，字段接纳与读取次序在本 owner 中实现。 */
export interface RequestLeaseScopeQueries<Owner, Scope> {
  active(owner: Owner): Scope | undefined;
  owner(scope: Scope): Owner;
  actorId(scope: Scope): number;
  phase(): ActionRequest["phase"];
  stage(scope: Scope): ActionRequest["context"]["stage"];
}

/** 动态窗口只给出捕获值和晚领域查询；scope 是每个原请求独立的不透明对象，不由请求重建。
 * 日次／阶段不固定为首夜，明确声明的 context 字段只 pin 原值引用，不创建 World 或死亡许可。
 */
export interface RequestLeaseWindowQueries<Scope extends object> {
  actorId(scope: Scope): number;
  phase(scope: Scope): ActionRequest["phase"];
  day(scope: Scope): number;
  stage(scope: Scope): ActionRequest["context"]["stage"];
  current(scope: Scope): boolean;
}

/** current 仍调用原机制规则；不能据请求字段相同代替原体、生命和库存复验。 */
export interface RequestLeaseCurrentQueries<Owner, Scope> extends RequestLeaseScopeQueries<Owner, Scope> {
  current(scope: Scope): boolean;
}

/** 墙入口先查原作者；原 token／实例值在条件和记录构造位置各自读取，不缓存授权或复制作者。 */
export interface RequestLeaseItemQueries<Owner, Scope, Author> {
  active(owner: Owner): Scope | undefined;
  authors(scope: Scope): Pick<ReadonlyMap<number, Author>, "get">;
  token(scope: Scope): string;
  instanceId(author: Author): string;
  phase(): ActionRequest["phase"];
  stage(): ActionRequest["context"]["stage"];
  current(owner: Owner, scope: Scope, author: Author): boolean;
}

/** context 保原引用，记录不是请求 DTO；合法别名共享同一记录，不做深只读或序列化。 */
interface ScopeBinding<Scope> {
  scope: Scope;
  context: ActionRequest["context"];
}
/** context 身份和声明字段由本 owner 捕获；只保存值／引用，不序列化或深冻结整个 context。 */
interface WindowBinding<Scope> extends ScopeBinding<Scope> {
  fields: Array<{ key: string; value: unknown }>;
}
interface CurrentBinding<Scope> {
  binding: Scope;
  context: ActionRequest["context"];
}
/** 捕获墙的原 owner／作者编号与实例值；后续查询仍晚查活跃墙，不能由编号自行生成许可。 */
interface ItemBinding<Owner, Scope, Author> extends ScopeBinding<Scope> {
  author: Author;
  world: Owner;
  actorId: number;
  instanceId: string;
}

// 字段比较仍排除 deadlineAtMs；其有限未来／只能缩短的政策在比较成功后单独处理。
function sameIndexedFields(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return !(
    keys.length !== other.length ||
    keys.some((k) => !other.includes(k) || (source as any)[k] !== (target as any)[k])
  );
}
function everyIndexedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && (source as any)[k] === (target as any)[k])
  );
}
function everyReflectedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && Reflect.get(source, k) === Reflect.get(target, k))
  );
}

/** 窗口私有的运行完成端口；不持 World/付款回调，不可由 JSON 或请求字段重建。 */
export interface RequestLeaseTurn {
  current(): boolean;
  complete(): void;
  close(): void;
}
/** pin 只核顶层枚举字段及原值引用；嵌套数据/合法 getter/Proxy 不套新 schema 或深只读政策。 */
interface FieldPin { keys: string[]; values: unknown[] }
interface LeaseTurn<Owner, Binding> {
  owner: Owner;
  original: ActionRequest;
  binding: Binding;
  pin?: FieldPin;
  originalDeadline?: unknown;
  deadline: number | null;
  closed: boolean;
  settled: boolean;
  opened: boolean;
  completion: object;
  aliases: Set<ActionRequest>;
  handle?: RequestLeaseTurn;
}
interface LeaseEntry<Owner, Binding> {
  turn: LeaseTurn<Owner, Binding>;
  retired: boolean;
  deadline: unknown;
}
function pinFields(request: ActionRequest): FieldPin {
  const keys = Object.keys(request).filter((key) => key !== "deadlineAtMs");
  return { keys, values: keys.map((key) => Reflect.get(request, key)) };
}
function samePinnedFields(request: ActionRequest, pin: FieldPin): boolean {
  const keys = Object.keys(request).filter((key) => key !== "deadlineAtMs");
  return keys.length === pin.keys.length && keys.every((key) => {
    const index = pin.keys.indexOf(key);
    return index !== -1 && Object.is(Reflect.get(request, key), pin.values[index]);
  });
}

/**
 * 每实例唯一持有请求登记；类型入口开放明确协议，实际机制接线不传完整 request callback。
 * 私有构造签名限制 typed 调用，不是运行时权限屏障；接纳算法在本 owner 内完整执行。
 * 四个旧协议保原字段短路；动态窗口显式增加字段／日次查询，外围复用 F02 政策，不建立 Role 分派或第二租约。
 */
export class RequestLease<Owner, Scope, Binding> {
  private readonly records = new WeakMap<ActionRequest, LeaseEntry<Owner, Binding>>();
  private readonly propagate = (source: ActionRequest, target: ActionRequest): void => {
    this.inherit(source, target);
  };

  private constructor(
    private readonly order: number,
    private readonly bindRequest: (owner: Owner, request: ActionRequest, lease: RequestLease<Owner, Scope, Binding>) => void,
    private readonly matches: (owner: Owner, request: ActionRequest, binding: Binding) => boolean,
    private readonly bindingOwner: (binding: Binding) => Owner,
    private readonly bindingScope: (binding: Binding) => Scope,
    private readonly sameFields: (source: ActionRequest, target: ActionRequest) => boolean,
    private readonly domainCurrent: (owner: Owner, binding: Binding) => boolean,
  ) {}

  /**
   * 动态窗口按 actor→phase→context 身份→day→stage→声明字段核验，末位才调用领域 current。
   * bind 在条件通过后先登记关闭记录，再捕获声明字段和顶层 pin；getter 抛错保该记录关闭，不能重新 bind 复活。
   * contextKeys 的列表副本属于本实例；它不校验深层提示、JSON 或字段类型，也不把这些字段当真实许可。
   */
  static window<Scope extends object>(
    queries: RequestLeaseWindowQueries<Scope>,
    order: number,
    contextKeys: readonly string[] = [],
  ): RequestLease<Scope, Scope, WindowBinding<Scope>> {
    const keys = [...contextKeys];
    return new RequestLease<Scope, Scope, WindowBinding<Scope>>(
      order,
      (scope, request, lease) => {
        if (
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase(scope) &&
          request.context.day === queries.day(scope) &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, lease.entry(scope, request, { scope, context: request.context, fields: [] }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          const binding = lease.records.get(request)!.turn.binding;
          for (const key of keys) binding.fields.push({ key, value: Reflect.get(binding.context, key) });
          lease.capture(request);
        }
      },
      (scope, request, binding) =>
        request.actorId === queries.actorId(scope) &&
        request.phase === queries.phase(scope) &&
        request.context === binding.context &&
        request.context.day === queries.day(scope) &&
        request.context.stage === queries.stage(scope) &&
        binding.fields.every(({ key, value }) => Object.is(Reflect.get(request.context, key), value)),
      (binding) => binding.scope,
      (binding) => binding.scope,
      sameIndexedFields,
      (_scope, binding) => queries.current(binding.scope),
    );
  }

  /** actor→phase→day→stage；查询还先核同一活跃 scope，末位晚核机制当前性。 */
  static actorPhaseDayStage<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, ScopeBinding<Scope>> {
    return new RequestLease<Owner, Scope, ScopeBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const scope = queries.active(owner);
        if (
          scope &&
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, lease.entry(owner, request, { scope, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, binding) =>
        queries.owner(binding.scope) === owner &&
        queries.active(owner) === binding.scope &&
        request.actorId === queries.actorId(binding.scope) &&
        request.context === binding.context &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(binding.scope),
      (binding) => queries.owner(binding.scope),
      (binding) => binding.scope,
      sameIndexedFields,
      (_owner, binding) => queries.current(binding.scope),
    );
  }

  /** stage→phase→day→actor→current；查询保原 context→stage→day→phase→current 顺序和 Reflect.get 比较。 */
  static stagePhaseDayActor<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.context.stage === queries.stage(b) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.actorId === queries.actorId(b) &&
          queries.current(b)
        ) {
          lease.records.set(request, lease.entry(owner, request, { binding: b, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        request.phase === queries.phase() &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyReflectedField,
      () => true, // 原 matches 已在末位调用本族 current，不重复那一次。
    );
  }

  /** actor→phase→stage→day→current；查询的 phase 必须先于 context 身份，不重排成上一种协议。 */
  static actorPhaseStageDay<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.actorId === queries.actorId(b) &&
          request.phase === queries.phase() &&
          request.context.stage === queries.stage(b) &&
          request.context.day === 1 &&
          queries.current(b)
        ) {
          lease.records.set(request, lease.entry(owner, request, { binding: b, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.phase === queries.phase() &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyIndexedField,
      () => true,
    );
  }

  /** 原物品入口只核 token/instance；phase/day/stage 留在查询，原作者当前性在查询成功后才晚核。 */
  static item<Owner, Scope, Author>(
    queries: RequestLeaseItemQueries<Owner, Scope, Author>,
    order: number,
  ): RequestLease<Owner, Scope, ItemBinding<Owner, Scope, Author>> {
    return new RequestLease<Owner, Scope, ItemBinding<Owner, Scope, Author>>(
      order,
      (world, request, lease) => {
        const a = queries.active(world),
          author = a == null ? undefined : queries.authors(a).get(request.actorId);
        if (
          a &&
          author &&
          request.context.wall_id === queries.token(a) &&
          request.context.item_instance_id === queries.instanceId(author)
        ) {
          lease.records.set(request, lease.entry(world, request, {
            scope: a,
            world,
            actorId: request.actorId,
            instanceId: queries.instanceId(author),
            context: request.context,
            author,
          }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (world, request, binding) =>
        queries.active(world) === binding.scope &&
        request.actorId === binding.actorId &&
        request.context === binding.context &&
        request.context.wall_id === queries.token(binding.scope) &&
        request.context.item_instance_id === binding.instanceId &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(),
      (binding) => binding.world,
      (binding) => binding.scope,
      sameIndexedFields,
      (owner, binding) => queries.current(owner, binding.scope, binding.author),
    );
  }

  /** 条件与 set callee 保原位置；同对象已登记后不得重新 bind 来复活旧 turn。 */
  bind(owner: Owner, request: ActionRequest): void {
    if (this.records.has(request)) return;
    this.bindRequest(owner, request, this);
  }

  /** 只分配运行记录；原 binding/context 已在参数原位置读出。pin 在 set 与传播登记之后才读取。 */
  private entry(owner: Owner, original: ActionRequest, binding: Binding): LeaseEntry<Owner, Binding> {
    return { turn: { owner, original, binding, closed: true, settled: false, opened: false,
      completion: {}, aliases: new Set(), deadline: null }, retired: false, deadline: undefined };
  }

  private capture(request: ActionRequest): void {
    const entry = this.records.get(request)!, turn = entry.turn;
    // 捕获期间先保持关闭：新增 keys/getter 抛错保原已写记录／传播前缀，恢复字段也不重开。
    turn.pin = pinFields(request);
    entry.deadline = request.deadlineAtMs;
    turn.originalDeadline = entry.deadline;
    if (entry.deadline === undefined) turn.closed = false;
    else if (typeof entry.deadline === "number" && Number.isFinite(entry.deadline) && entry.deadline > Date.now()) {
      turn.deadline = entry.deadline;
      turn.closed = false;
    }
  }

  /** 外来 World／未登记请求先拒；alias 自身失配先隔离，不读取或毒化 original。 */
  scope(owner: Owner, request: ActionRequest): Scope | undefined {
    const entry = this.records.get(request);
    if (!entry || entry.turn.owner !== owner || entry.turn.closed || entry.retired) return;
    const turn = entry.turn;
    if (request !== turn.original) {
      try {
        if (!samePinnedFields(request, turn.pin!) || !Object.is(request.deadlineAtMs, entry.deadline)) {
          entry.retired = true;
          return;
        }
      } catch (error) {
        entry.retired = true;
        throw error;
      }
    }
    try {
      // 各协议仍按其声明的 ordered matches 查询 original；共同 context.stage 变坏会关共同 turn。
      if (!this.matches(owner, turn.original, turn.binding) ||
          !samePinnedFields(turn.original, turn.pin!) ||
          !Object.is(turn.original.deadlineAtMs, turn.originalDeadline) ||
          !this.domainCurrent(owner, turn.binding) ||
          (turn.deadline !== null && turn.deadline <= Date.now())) {
        turn.closed = true;
        return;
      }
      return this.bindingScope(turn.binding);
    } catch (error) {
      turn.closed = true;
      throw error;
    }
  }

  /**
   * 真正窗口在 create 后打开交付：各绑定实例不争写 guard。前后登记的 alias 同 guard／completion，
   * 这些引用只留本 owner 的运行集合，不挂 context。每个 Wall request 的 turn 独立于整个墙。
   */
  openDelivery(owner: Owner, request: ActionRequest): RequestLeaseTurn | undefined {
    if (!this.scope(owner, request)) return;
    const turn = this.records.get(request)!.turn;
    if (!turn.handle) turn.handle = {
      current: () => this.scope(owner, request) !== undefined,
      complete: () => this.finish(turn, true),
      close: () => this.finish(turn, false),
    };
    if (!turn.opened) {
      bindRequestDeliveryGuard(turn.original, () => this.scope(owner, turn.original) !== undefined, turn.completion);
      turn.opened = true;
      for (const alias of turn.aliases) this.bindDelivery(turn, alias);
    }
    return turn.handle;
  }

  private bindDelivery(turn: LeaseTurn<Owner, Binding>, request: ActionRequest): void {
    bindRequestDeliveryGuard(request, () => this.scope(turn.owner, request) !== undefined, turn.completion);
  }

  /** 付款结果只由真实窗口给出；不重查已被付款改变的 pending scope。先落终态再发一次通知。 */
  private finish(turn: LeaseTurn<Owner, Binding>, accepted: boolean): void {
    if (turn.settled) return;
    turn.closed = true;
    turn.settled = true;
    turn.aliases.clear();
    settleRequestDelivery(turn.completion, accepted);
  }

  /** 先核来源，再原 ordered fields，最后有限未来期限；坏目标／其 getter 异常不修改来源预算。 */
  private inherit(source: ActionRequest, target: ActionRequest): void {
    const sourceEntry = this.records.get(source);
    if (!sourceEntry || !this.scope(sourceEntry.turn.owner, source) || this.records.has(target)) return;
    if (!this.sameFields(source, target)) return;
    const turn = sourceEntry.turn;
    // 原 === 比较通过后仍须核 F02 pin（含 +0/-0 及晚 getter 原值）；非法目标不得先写记录／缩预算。
    if (!samePinnedFields(target, turn.pin!)) return;
    const deadline = target.deadlineAtMs;
    if (typeof deadline !== "number" || !Number.isFinite(deadline) || deadline <= Date.now() ||
        (turn.deadline !== null && deadline > turn.deadline)) return;
    this.records.set(target, { turn, retired: false, deadline });
    turn.deadline = deadline;
    turn.aliases.add(target);
    registerRequestAliasPropagation(target, this.order, this.propagate);
    if (turn.opened) this.bindDelivery(turn, target);
  }
}

/**
 * 负责请求对象上的交付检查、完成回调和期限别名传播。输入为机制已经绑定的原请求、
 * 当前性查询及不透明完成身份；输出为同步交付检查、一次性结算通知和有序别名绑定。
 * 元数据仅存运行时弱表，不进入模型上下文或归档。机制仍拥有权限、最早期限及单调撤权；
 * 本模块只调用已注册的规则，不以缺少交付检查或相同 JSON 字段判定请求已获授权。
 * 本模块仅写入交付弱表，不修改生命、库存或阶段；结算先删除待通知项再调用回调，异常不恢复。
 * 别名传播遇异常即停止，已完成的绑定不回滚。
 */
import type { ActionRequest } from "./actions";

type AliasPropagation = (original: ActionRequest, alias: ActionRequest) => void;
/** 原请求与别名各自登记元数据；completion 可指向同一机制窗口，不是可序列化许可。 */
interface DeliveryMetadata {
  /** 查询是否可交付；具体原体、生命版本与永久撤权由机制的查询实现负责。 */
  current?: () => boolean;
  /** 将一次 Provider 返回关联到后续领域提交或关闭，不把返回动作当成提交成功。 */
  completion?: object;
  /** 回调身份是键；同一回调重登记只更新顺序，具体别名绑定仍由该机制执行。 */
  aliases?: Map<AliasPropagation, number>;
}

/** 弱表按对象身份关联：复制请求字段不会复制当前性检查或完成身份。 */
const guards = new WeakMap<object, DeliveryMetadata>();
/** 同一完成身份同时最多保留一个待结算回调；原请求和合法别名可共享该身份。 */
const settlements = new WeakMap<object, (accepted: boolean) => void>();
/** 机制成功绑定后登记一次交付检查；保留此前已登记的别名路由。 */
export function bindRequestDeliveryGuard(
  request: object,
  isCurrent: () => boolean,
  completion?: object,
): void {
  const existing = guards.get(request);
  if (existing && "current" in existing)
    throw new Error("action_request_delivery_guard_already_bound");
  guards.set(request, { ...existing, current: isCurrent, completion });
}
/** 无登记时不额外拒绝；有检查时必须严格返回 true，不能用真值替代机制确认。 */
export function assertRequestDelivery(request: ActionRequest): void {
  const guard = guards.get(request);
  if (guard && "current" in guard && guard.current!() !== true)
    throw new Error("action_request_delivery_authority_revoked");
}
/** 登记事务请求的延后通知；无完成身份则返回 false，由调用方执行原有即时通知政策。 */
export function deferRequestDelivery(
  request: ActionRequest,
  settle: (accepted: boolean) => void,
): boolean {
  const completion = guards.get(request)?.completion;
  if (!completion) return false;
  if (settlements.has(completion)) throw new Error("action_request_delivery_already_pending");
  settlements.set(completion, settle);
  return true;
}
export function settleRequestDelivery(completion: object, accepted: boolean): void {
  const settle = settlements.get(completion);
  if (!settle) return;
  // 先消费再通知：重入或回调抛错都不会再次发送同一成功／拒绝通知，也不回滚领域前缀。
  settlements.delete(completion);
  settle(accepted);
}

/** 仅登记已成功绑定的路由；登记自身不会执行回调、校验权限或设置期限。 */
export function registerRequestAliasPropagation(
  request: object,
  order: number,
  inherit: AliasPropagation,
): void {
  let metadata = guards.get(request);
  if (!metadata) {
    metadata = {};
    guards.set(request, metadata);
  }
  (metadata.aliases ??= new Map()).set(inherit, order);
}

/** 机制自行接纳并绑定别名；按顺序调用不等于授予新行动权限。 */
export function inheritRequestAlias(original: ActionRequest, alias: ActionRequest): void {
  const routes = guards.get(original)?.aliases;
  if (!routes) return;
  // 先取路由快照再稳定排序；回调期间增删路由不改变本次名单，抛错时后续路由不执行。
  for (const [inherit] of [...routes].sort((left, right) => left[1] - right[1]))
    inherit(original, alias);
}

/** 调用方先计算最早期限；这里保留原字段展开顺序，再由已登记机制绑定新对象。 */
export function deriveBoundedRequest(original: ActionRequest, deadlineAtMs: number): ActionRequest {
  const alias = { ...original, deadlineAtMs };
  inheritRequestAlias(original, alias);
  return alias;
}

/**
 * 负责为核心层结果与阶段摘要消费者保留现有类型入口。输入为 game-contract 唯一数据定义，输出同源公共类型别名。
 * 这里不另建结果格式、不计算胜负、不渲染文案或写入状态；这些历史入口仍是兼容引用，不能当成新增裁决事实。
 */
export type {
  GameResult,
  WinDecision,
  SeerCheckResult,
  NightSummary,
  DaySummary,
  VotingSummary,
  RuntimeSnapshot,
} from "@ai-werewolf-arena/game-contract";

/**
 * 记录身份安装失败后已退休的 Role 运行授权；输入为实际组件对象，输出为永久退休标记与拒绝查询。
 * 只有具体安装 writer 在声明的核心失败边界标记，字段恢复或跨 World 复用同对象都不能清除；新对象仍须经过各自许可校验。
 * 私有集合不保存 Camp、World、库存或快照，不改组件属性；false 仅表示未被该失败政策退休，不代表可以执行行动。
 * 纯数据、已付效果的原体复验、目标身份、观察、归档和死亡清理各保原职责；正常组件变化不自动退休。
 */
import type { RoleComponent } from "./components/role";

// 用对象身份记录不可恢复的执行终态；不写公开字段，冻结的组件也能保留最初安装错误。
const retiredExecutions = new WeakSet<RoleComponent>();

/** 受信任的身份安装 writer 专用；重复退休幂等，不回滚已经完成的组件、库存或事实前缀。 */
export function retireRoleExecution(role: RoleComponent): void {
  retiredExecutions.add(role);
}

/** 仅提供拒绝条件，调用方仍须按原顺序检查生命、来源、资源、阶段及实际提交资格。 */
export function isRoleExecutionRetired(role: RoleComponent): boolean {
  return retiredExecutions.has(role);
}

/**
 * 负责黎明伤害结算：输入为当前夜间印记以及有来源的保护、查验和反击声明；
 * 输出为待结算死亡 ID、死因与仅供全知视角的反射证据，并按原顺序清理已消费印记。
 * 效果折叠和单目标政策委托具体 owner；本模块拥有取消冲突保护与清理印记的写权限。
 * 不修改 Alive 或执行死亡钩子，这两项由死亡结算负责；失败保留已经生效的清理前缀。
 */
import { COMPONENT } from "../components/names";
import { EntityId, StatusMark, type DeathSources } from "../model";
import { World } from "../world";
import { attachDamagePoisonEvidence } from "../damage-evidence";
import type { NightPoisonRoute, NightPoisonReflection } from "../night_effects";
import { resolveNightDamageTarget } from "../night-damage-target";
import { planNightDamage, type NightDamageEffects } from "../night-damage-plan";

/**
 * 黎明伤害结算结果。
 */
export interface DamageResolutionResult {
  deaths: EntityId[];
  deathSources: DeathSources;
  /** 全知视角的因果输出；不进入玩家夜间摘要或状态。 */
  poisonReflections?: readonly NightPoisonReflection[];
}

/**
 * 黎明伤害结算系统：
 * - 处理“同守同救”特殊规则
 * - 统一判定狼刀/毒药导致的死亡
 * - 结算后清空当夜印记
 * - 仅返回“待结算死亡名单”，不在此处直接改写存活状态
 */
export class DamageResolutionSystem {
  /**
   * 执行一轮夜间伤害结算并返回死亡与死因信息。
   */
  resolve(world: World, effects: NightDamageEffects = {}): DamageResolutionResult {
    const deaths: EntityId[] = [];
    const deathSources: DeathSources = {};
    // 只收集单目标政策真实接受的来源，不因折叠中存在路由就宣称致死。
    const acceptedPoison: NightPoisonRoute[] = [];
    const plan = planNightDamage(world, effects);
    const {
      awakenedAttacks,
      mechanical,
      blackBacklashes,
      radiantBacklashes,
      backlashTargets,
      foxInspections,
      inspectionSources,
      passiveImmuneTargets,
    } = plan;
    for (const entityId of world.getAliveEntityIds()) {
      const marks = world.getComponent(entityId, COMPONENT.StatusMarks);
      if (passiveImmuneTargets.has(entityId)) {
        marks?.clear();
        continue;
      }
      if (
        !marks &&
        !foxInspections.has(entityId) &&
        !inspectionSources.has(entityId) &&
        !effects.consecutiveDeaths?.includes(entityId) &&
        !mechanical.attacks.has(entityId) &&
        !awakenedAttacks.has(entityId) &&
        !mechanical.failures.has(entityId) &&
        !mechanical.reflectedPoisonTargets.has(entityId)
      ) {
        if (
          !backlashTargets.has(entityId) &&
          !blackBacklashes.has(entityId) &&
          !radiantBacklashes.has(entityId)
        )
          continue;
      }

      // 取消和最终清理分别执行，后续目标查询失败不能回滚前一目标的清理。
      const sources = resolveNightDamageTarget(
        world, entityId, effects, plan, marks,
        () => {
          marks?.remove(StatusMark.GuardMark);
          marks?.remove(StatusMark.HealMark);
        },
        (routes) => acceptedPoison.push(...routes),
      );
      if (sources.length > 0) {
        deaths.push(entityId);
        deathSources[entityId] = sources;
      }

      marks?.clear();
    }

    // 同一原结果仅带不可枚举的运行时证据；玩家摘要和归档仍读原纯数据字段。
    return attachDamagePoisonEvidence({
      deaths,
      deathSources,
      ...(mechanical.reflections.length ? { poisonReflections: mechanical.reflections } : {}),
    }, acceptedPoison);
  }
}

/**
 * 负责实体 ID、组件 Map 与原生命绑定的临时死亡行动许可。输入为既有实体／槽操作及
 * 生命周期回调，输出保持原可写组件引用、筛选结果和许可 ID。World 唯一写入自己的存储，
 * 工厂与角色所有者仍负责值和资源校验；槽推断不增加运行守卫、复制或冻结。
 * 旧任意组件类型 T 重载已退出，读写关系由具名槽约束；死亡许可仍按原生命版本与当前性撤销，ID 本身不授权。
 */
import { EntityId, Phase, Role } from "./model";
import { COMPONENT, ComponentName } from "./components/names";
import type { ComponentMap, ComponentWrite } from "./component-map";
import { AliveComponent, aliveLifeVersion } from "./components/alive";
import { RoleComponent } from "./components/role";
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";

/**
 * World 是 ECS 内存状态容器。
 * 设计目标：保持结构简单、读写明确，所有系统都基于该容器进行组件查询与变更。
 */
export class World {
  constructor(readonly locale: Locale = "zh-CN") {
    if (!isLocale(locale)) throw new Error("game_locale_invalid");
  }
  private nextId: EntityId = 1;
  private entities: Set<EntityId> = new Set();
  private stores: Map<ComponentName, Map<EntityId, unknown>> = new Map();
  private nextDeathActionId = 1;
  // 许可绑定原 Alive 对象和该对象的生命版本；复活、替换组件或失去当前性均撤销旧许可。
  private deathActions = new Map<
    EntityId,
    {
      id: number;
      tool: "shoot" | "speak" | "choose_badge_successor";
      phase: Phase;
      day: number;
      abilityId?: string;
      alive: AliveComponent;
      lifeVersion: number;
      isCurrent: () => boolean;
    }
  >();

  /** 引擎拥有的临时行动许可；ID 不授予行动。World 复核原生命与传入的当前性回调，带阶段的查询另核许可记录的 phase／day。 */
  openDeathAction(
    actorId: EntityId,
    tool: "shoot" | "speak" | "choose_badge_successor",
    phase: Phase,
    day: number,
    isCurrent: () => boolean = () => true,
    abilityId?: string,
  ): { readonly id: number; close(): void } {
    if (this.currentDeathAction(actorId)) throw new Error("death_action_already_open");
    const alive = this.getComponent(actorId, COMPONENT.Alive);
    const lifeVersion = alive && aliveLifeVersion(alive);
    if (
      !alive ||
      alive.alive !== false ||
      lifeVersion === undefined ||
      !this.getComponent(actorId, COMPONENT.Role) ||
      !Number.isSafeInteger(day) ||
      day < 1 ||
      !["shoot", "speak", "choose_badge_successor"].includes(tool) ||
      !Object.values(Phase).includes(phase) ||
      phase === Phase.GameOver ||
      (abilityId !== undefined &&
        (tool !== "shoot" ||
          typeof abilityId !== "string" ||
          !/^[a-z][a-z0-9:_-]{0,127}$/.test(abilityId) ||
          abilityId.startsWith("native:")))
    ) {
      throw new Error("death_action_invalid_actor_or_stage");
    }
    const id = this.nextDeathActionId++;
    this.deathActions.set(actorId, {
      id,
      tool,
      phase,
      day,
      abilityId,
      alive,
      lifeVersion,
      isCurrent,
    });
    return Object.freeze({
      id,
      close: () => {
        if (this.deathActions.get(actorId)?.id === id) this.deathActions.delete(actorId);
      },
    });
  }

  hasDeathAction(
    actorId: EntityId,
    tool: string,
    phase: Phase,
    day: number | undefined,
    id: number | undefined,
    abilityId?: string,
  ): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.phase === phase &&
      permit.day === day &&
      permit.abilityId === abilityId
    );
  }

  isDeathActionOpen(actorId: EntityId, tool: string, id: number, abilityId?: string): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.abilityId === abilityId
    );
  }

  private currentDeathAction(actorId: EntityId) {
    const permit = this.deathActions.get(actorId);
    if (!permit) return undefined;
    if (
      this.getComponent(actorId, COMPONENT.Alive) !== permit.alive ||
      permit.alive.alive !== false ||
      aliveLifeVersion(permit.alive) !== permit.lifeVersion ||
      !permit.isCurrent()
    ) {
      this.deathActions.delete(actorId);
      return undefined;
    }
    return permit;
  }

  get activeDeathActionCount(): number {
    for (const actorId of this.deathActions.keys()) this.currentDeathAction(actorId);
    return this.deathActions.size;
  }

  closeDeathActions(): void {
    this.deathActions.clear();
  }

  /**
   * 创建新实体并返回实体 ID。
   */
  createEntity(): EntityId {
    const id = this.nextId++;
    this.entities.add(id);
    return id;
  }

  /**
   * 判断实体是否存在。
   */
  hasEntity(entityId: EntityId): boolean {
    return this.entities.has(entityId);
  }

  /**
   * 返回当前所有实体 ID（升序）。
   */
  entityIds(): EntityId[] {
    return [...this.entities].sort((a, b) => a - b);
  }

  addComponent<K extends ComponentName, C extends ComponentWrite<NoInfer<K>>>(
    entityId: EntityId,
    name: K,
    component: C,
  ): void {
    if (!this.hasEntity(entityId)) {
      throw new Error(`Entity ${entityId} does not exist`);
    }

    // 每类组件一张表，按 entityId 索引。
    const store = this.ensureStore(name);
    store.set(entityId, component);
  }

  getComponent<K extends ComponentName>(entityId: EntityId, name: K): ComponentMap[K] | undefined {
    const store = this.stores.get(name);
    return store?.get(entityId) as ComponentMap[K] | undefined;
  }

  /**
   * 从实体上移除指定组件。
   */
  removeComponent(entityId: EntityId, name: ComponentName): void {
    const store = this.stores.get(name);
    store?.delete(entityId);
  }

  /**
   * 返回同时拥有给定组件集合的实体列表。
   */
  entitiesWith(...names: ComponentName[]): EntityId[] {
    // 只有同时拥有所有组件的实体才会被返回，用于系统筛选。
    return this.entityIds().filter((entityId) => {
      return names.every((name) => {
        const store = this.stores.get(name);
        return store?.has(entityId) ?? false;
      });
    });
  }

  /**
   * 返回当前存活实体 ID 列表。
   */
  getAliveEntityIds(): EntityId[] {
    return this.entitiesWith(COMPONENT.Alive).filter((id) => {
      const alive = this.getComponent(id, COMPONENT.Alive);
      return alive?.alive === true;
    });
  }

  /**
   * 按角色筛选实体 ID。
   */
  getEntityIdsByRole(role: Role): EntityId[] {
    return this.entitiesWith(COMPONENT.Role).filter((id) => {
      const roleComp = this.getComponent(id, COMPONENT.Role);
      return roleComp?.role === role;
    });
  }

  /**
   * 确保组件存储存在，不存在则懒加载创建。
   */
  private ensureStore(name: ComponentName): Map<EntityId, unknown> {
    let store = this.stores.get(name);
    if (!store) {
      // 延迟初始化组件存储，避免为未使用组件提前分配空间。
      store = new Map<EntityId, unknown>();
      this.stores.set(name, store);
    }
    return store;
  }
}

/**
 * 负责 mock、smoke 与规则测试的特权基线决策。输入为原 World、请求和角色目录，
 * 输出为按既定席位与角色策略选出的工具动作；可读取真实阵营，不作为玩家受限观察或生产模型回退。
 * 本模块拥有启发式选择，行动许可、付款、事实发布和最终规则结算仍由引擎及具体机制重检。
 * 无模型、网络或独立随机源；候选按原查询时点读取，异常保留已完成的读取与脚本前缀。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { scholarMentorBonusTargets } from "../mechanisms/roles/scholar_mentor/night_frame";
import { prohibitsLoversVote } from "../mechanisms/roles/cupid/relation";
import { text } from "@ai-werewolf-arena/game-text";
import { COMPONENT } from "../../core/domain/components/names";
import { RoleComponent } from "../../core/domain/components/role";
import {
  ActionProvider,
  ActionRequest,
  Camp,
  EntityId,
  Phase,
  Role,
  ToolCall,
} from "../../core/domain";
import { World } from "../../core/domain/world";
import { RoleCatalog, getDefaultRoleCatalog, wolfTeamPermissions, allNightAbilities, activeNightAbility, ROLE_INSPECTION_POLICY_ROLES } from "../mechanisms";
import { canBeExiled, canBeSheriff, canVote } from "../mechanisms/common/participation";

/**
 * 明确特权的基线机器人：仅供 mock、smoke 和规则测试驱动，不作为生产模型回退。
 */
export class BaselineBotActionProvider implements ActionProvider {
  private readonly roleCatalog: RoleCatalog;

  constructor(
    private readonly world: World,
    roleCatalog: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    this.roleCatalog = roleCatalog;
  }

  /**
   * 根据阶段与角色生成默认动作。
   */
  async getAction(request: ActionRequest): Promise<ToolCall | null> {
    if (request.allowedTools.includes("write_note"))
      return { name: "write_note", args: { text: "..." } };
    if (request.allowedTools.includes("debate_vote"))
      return { name: "debate_vote", args: { support: true } };
    const role = this.world.getComponent(request.actorId, COMPONENT.Role);
    if (!role) {
      return null;
    }

    if (request.allowedTools.includes("choose_badge_successor")) {
      const id = request.context.badge_candidates?.find((id) =>
        canBeSheriff(this.world, id, this.roleCatalog),
      );
      return { name: "choose_badge_successor", args: { target_id: id ?? null } };
    }
    if (request.allowedTools.includes("choose_direction")) {
      if (!canBeSheriff(this.world, request.actorId, this.roleCatalog)) return null;
      // 基线策略：偶数位顺时针，奇数位逆时针，保证可重复。
      return {
        name: "choose_direction",
        args: {
          direction: request.actorId % 2 === 0 ? "clockwise" : "counter_clockwise",
        },
      };
    }

    if (request.allowedTools.includes("run_for_sheriff")) {
      if (!canBeSheriff(this.world, request.actorId, this.roleCatalog)) return null;
      // 基线策略：存活玩家默认上警，避免“需至少一次行动”的回合无动作。
      return {
        name: "run_for_sheriff",
        args: { run: true },
      };
    }

    if (request.allowedTools.includes("vote_for_sheriff")) {
      if (
        !canVote(this.world, request.actorId, this.roleCatalog) ||
        request.context.sheriff_candidates?.includes(request.actorId)
      )
        return null;
      const rawCandidates = request.context.sheriff_candidates;
      const candidates = Array.isArray(rawCandidates)
        ? rawCandidates
            .map((item) => Number(item))
            .filter(
              (id) =>
                Number.isFinite(id) && id > 0 && canBeSheriff(this.world, id, this.roleCatalog),
            )
        : [];
      const preferred = candidates.find((id) => id !== request.actorId) ?? candidates[0];
      if (preferred !== undefined) {
        return {
          name: "vote_for_sheriff",
          args: { target_id: preferred, abstain: false },
        };
      }
      return {
        name: "vote_for_sheriff",
        args: { target_id: null, abstain: true },
      };
    }

    if (request.allowedTools.includes("speak")) {
      const isLastWords = request.context.trigger === "last_words";
      return {
        name: "speak",
        args: {
          text: text(this.world.locale, isLastWords ? "fallback.last_words" : "fallback.speech", {
            actor: request.actorId,
          }),
        },
      };
    }

    if (request.phase === Phase.Voting && request.allowedTools.includes("vote")) {
      if (
        !canVote(this.world, request.actorId, this.roleCatalog) ||
        request.context.exile_candidates?.includes(request.actorId)
      )
        return null;
      // 席位顺序提供确定的默认目标；角色资格与情侣禁票仍逐目标查询，不能据此绕过网关复验。
      const target =
        this.world
          .getAliveEntityIds()
          .find(
            (id) =>
              id !== request.actorId &&
              (request.context.exile_candidates === undefined ||
                request.context.exile_candidates.includes(id)) &&
              canBeExiled(this.world, id, this.roleCatalog) &&
              !prohibitsLoversVote(this.world, request.actorId, id),
          ) ?? null;
      return target !== null
        ? { name: "vote", args: { target_id: target, abstain: false } }
        : { name: "vote", args: { target_id: null, abstain: true } };
    }

    // 绑定动作使用原能力实例；没有实例、不是夜间或本夜未激活时不退回持有者原生技能。
    const bound = request.context.ability_id
      ? allNightAbilities(role).find((ability) => ability.id === request.context.ability_id)
      : undefined;
    if (
      request.context.ability_id &&
      (!bound ||
        request.phase !== Phase.Night ||
        !activeNightAbility(role, bound.kind, request.context.day, bound.id))
    )
      return null;
    const abilityRole =
      bound?.kind === "shelter"
        ? Role.RadiantCount
        : bound?.kind === "role_check"
          ? ROLE_INSPECTION_POLICY_ROLES[roleInspectionPolicy(bound.state)]
          : bound?.kind === "seer_check"
            ? Role.Seer
            : bound?.kind === "guard"
              ? Role.Guard
              : bound?.kind === "potion"
                ? Role.Witch
                : bound?.kind === "dream"
                  ? Role.Dreamer
                  : role.role;
    if (request.allowedTools.includes("bonus_action") && request.context.modifier_bonus_kind) {
      const kind = request.context.modifier_bonus_kind,
        target =
          scholarMentorBonusTargets(this.world, request.context.day, request.actorId, kind)[0] ??
          null;
      return { name: "bonus_action", args: { kind, target_id: target, abstain: target === null } };
    }
    // 角色基线钩子可使用真实 World。这是显式特权驱动，不能复用为玩家受限观察回退。
    const roleProfile = this.roleCatalog.runtime(abilityRole);
    if (roleProfile?.baselineAction) {
      const action = roleProfile.baselineAction(
        role,
        request,
        () => this.pickAliveNotSelf(request.actorId),
        (camp) => this.pickAliveByCamp(request.actorId, this.parseCamp(camp)),
        this.world.locale,
        this.world,
        () => this.world.getComponent(request.actorId, COMPONENT.Camp),
      );
      if (action?.name === "speak_to_wolves" || action?.name === "kill_vote") {
        // 钩子选择之后再按当前身份、生命和夜间权限检查；选择工具并不授予狼聊或刀权。
        const access = wolfTeamPermissions(role, this.roleCatalog, () => this.world.getComponent(request.actorId, COMPONENT.Camp), this.world);
        const permitted =
          action.name === "speak_to_wolves" ? access.canChat : access.canVoteForKill;
        if (
          !permitted ||
          request.phase !== Phase.Night ||
          !this.world.getAliveEntityIds().includes(request.actorId)
        )
          return null;
      }
      return action;
    }

    return null;
  }

  /**
   * 选择任意存活且非自己的目标。
   */
  private pickAliveNotSelf(actorId: EntityId): EntityId | null {
    const target = this.world.getAliveEntityIds().find((id) => id !== actorId);
    return target ?? null;
  }

  /**
   * 按阵营选择存活目标，找不到则回退到任意非自己目标。
   */
  private pickAliveByCamp(actorId: EntityId, camp: Camp): EntityId | null {
    const target = this.world.getAliveEntityIds().find((id) => {
      const role = this.world.getComponent(id, COMPONENT.Role);
      return id !== actorId && !!role && this.world.getComponent(id, COMPONENT.Camp)?.camp === camp;
    });
    // 若指定阵营无可选目标，兜底选任意存活非自己玩家。
    return target ?? this.pickAliveNotSelf(actorId);
  }

  private parseCamp(camp: "good" | "wolf" | "third_party"): Camp {
    if (camp === "wolf") {
      return Camp.Wolf;
    }
    if (camp === "third_party") {
      return Camp.ThirdParty;
    }
    return Camp.Good;
  }
}

/**
 * 负责从原 World 与明确阶段构造引擎行动请求。输入为演员、窗口、允许工具和中立摘要；
 * 输出固定日次、阶段、约束及玩家可见事实，完整构造之后交规则集按原顺序接线机制绑定。
 * 具体机制仍唯一持有权限、期限别名与资源提交；本工厂不计算或写 deadlineAtMs，请求数据副本不是行动许可。
 * 本工厂不渲染本地化文案、不序列化运行范围，也不据阶段字符串新增角色权限。
 */
import { bindRulesetActionRequest } from "../../rulesets/action-request-bindings";
import type { ActionRequestConstructionInput, ActionRequestConstructionPort } from "../../core/domain/actions";
import type { ActionRequest } from "@ai-werewolf-arena/game-contract/requests";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import { World } from "../../core/domain/world";
import { buildAgentVisibleEventFeed } from "./agent_visible_event_feed";
import { buildTurnConstraintContext } from "./turn_constraints_context";

/**
 * 统一创建游戏对 Agent 的行动请求。
 *
 * 该工厂统一填入原生请求的日次、细粒度 stage、玩家可见事件与结构化行动约束；
 * 调用方提供机制附加数据，运行时权限仍由具体机制保存，不混入这些公共字段。
 * 事件输出按 actorId 投影；日次取构造输入，不从 World 当前时钟重新推断。
 * 完整数据先构造再绑定原请求对象，clone／约束／投影失败时不进入规则集绑定。
 */
export class GameActionRequestFactory implements ActionRequestConstructionPort {
  constructor(
    // 保留原 World／事件数组引用；readonly 仅限制这里的类型写法，不拍摄快照或冻结输入。
    private readonly world: World,
    private readonly events: readonly GameEvent[],
    private readonly day: number,
  ) {}

  create(input: ActionRequestConstructionInput): ActionRequest {
    // 先按原顺序复制 allowedTools，再克隆机制附加 context；运行句柄不可借公共数据副本成为凭据。
    // 后面的公共字段覆盖附加数据中同名字段；不提前缓存 input getter 或吞掉 clone 的原错误。
    const request: ActionRequest = {
      phase: input.phase,
      actorId: input.actorId,
      allowedTools: [...input.allowedTools],
      ...(input.actionWindow ? { actionWindow: input.actionWindow } : {}),
      context: {
        ...structuredClone(input.context ?? {}),
        day: this.day,
        stage: input.stage,
        turn_constraints: buildTurnConstraintContext({
          requiresAction: input.requiresAction,
          allowedTools: input.allowedTools,
          summary: input.summary,
        }),
        // 等约束构造完成才复制当前事件数组并生成该演员视图，不将整份内部事件数组直接当成玩家事实。
        visible_events: buildAgentVisibleEventFeed(this.world, [...this.events], input.actorId),
      },
    };
    // 完整请求原对象交给各机制建立运行关联；ID／context／期限字段本身不能替代原对象绑定。
    // 原输入的阶段仍逐分支读取，不用已构造的 context.stage 替代后续 getter；World 也只在命中时读。
    // 绑定中抛错仍原样传播，已经建立的前面关联不由本工厂回滚。
    bindRulesetActionRequest(request, {
      stage: () => input.stage,
      world: () => this.world,
    });
    return request;
  }
}

/**
 * 负责将原事件取得安全的 Node 纯数据副本，并按玩家事件流生成局部连续 seq。
 * 输入为 World 和已提交领域事件；输出使用一次解析的事实和发表时 audience，数据不反写 canonical 事实。
 * 反射前拒绝 Proxy，保留原 descriptor、数组、循环和失败边界；家族解析归 facts owner，授权及裁剪归投影 owner。
 * 每事件只获取一次 prepared 可见性方法；身份和自定义规则仍只在原分支查询，不授予状态写权限。
 * 这里不提交行动或补发旧秘密；隐藏事件不会留下全局序号缺口。
 */
import { types } from "node:util";
import type { EntityId, GameEvent, PlayerVisibleEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../core/domain/world";
import { getDefaultAgentEventVisibilityRegistry } from "../mechanisms";
import { projectAbilitySource } from "../observation/night-ability-projection";
import { projectPreparedAgentEvent } from "../observation/agent-event-projection";
import { prepareInertAgentEvent, type InertAgentEvent } from "../observation/agent-event-facts";

/** 原 Node ingress 程序；不对浏览器 unknown Proxy 承诺零 trap。 */
function snapshotEvent(event: GameEvent): InertAgentEvent | null {
  const ancestors = new Set<object>();
  const inert = (value: unknown, depth: number): boolean => {
    // 声明中的可选字段在 JSON 编码前仍允许 undefined。
    if (
      value === undefined ||
      value === null ||
      typeof value === "string" ||
      typeof value === "boolean"
    )
      return true;
    if (typeof value === "number") return Number.isFinite(value);
    if (
      !value ||
      typeof value !== "object" ||
      depth > 32 ||
      types.isProxy(value) ||
      ancestors.has(value)
    )
      return false;
    const array = Array.isArray(value),
      proto = Object.getPrototypeOf(value);
    if (
      (array ? proto !== Array.prototype : proto !== Object.prototype && proto !== null) ||
      Object.getOwnPropertySymbols(value).length
    )
      return false;
    const fields = Object.getOwnPropertyDescriptors(value);
    if (array) {
      const length = fields.length?.value;
      if (
        !Number.isSafeInteger(length) ||
        length > 1024 ||
        Object.keys(fields).length !== length + 1 ||
        !Array.from({ length }, (_, i) => Object.hasOwn(fields, i)).every(Boolean)
      )
        return false;
    }
    ancestors.add(value);
    try {
      return Object.entries(fields).every(
        ([key, field]) =>
          (array && key === "length") ||
          (field.enumerable && Object.hasOwn(field, "value") && inert(field.value, depth + 1)),
      );
    } finally {
      ancestors.delete(value);
    }
  };
  try {
    if (!inert(event, 0)) return null;
    const copy = structuredClone(event);
    return typeof copy.type === "string" &&
      typeof copy.timestamp === "number" &&
      copy.payload !== null &&
      typeof copy.payload === "object" &&
      !Array.isArray(copy.payload)
      ? (copy as InertAgentEvent)
      : null;
  } catch {
    return null;
  }
}

/** Node 在任何事实读器前取得安全副本；解析、授权与输出都不再回读宿主原事件。 */
export function buildAgentVisibleEvent(
  world: World,
  event: GameEvent,
  actorId: EntityId,
  visibleSeq: number,
): PlayerVisibleEvent | null {
  const detached = snapshotEvent(event);
  if (!detached) return null;
  const prepared = prepareInertAgentEvent(detached);
  return projectPreparedAgentEvent(prepared, actorId, visibleSeq, {
    canView(prepared, actorId) {
      const visibility = getDefaultAgentEventVisibilityRegistry();
      return visibility.canViewPrepared(world, prepared, actorId);
    },
    projectAbilitySource(origin, disclosed) {
      return projectAbilitySource(origin(), disclosed());
    },
  });
}

/**
 * 返回只读追加的玩家事件流。seq 仅按投影后仍可见的事件递增，因此不同数量的
 * 隐藏事件不会改变玩家协议。这里不截断；Provider 使用 seq 取增量，并在送模时
 * 控制消息窗口，避免“数组截断 + 长度游标”造成新事件永久丢失。
 */
export function buildAgentVisibleEventFeed(
  world: World,
  events: GameEvent[],
  actorId: EntityId,
): PlayerVisibleEvent[] {
  const visible: PlayerVisibleEvent[] = [];
  for (let index = 0; index < events.length; index += 1) {
    const projected = buildAgentVisibleEvent(world, events[index], actorId, visible.length + 1);
    if (projected) visible.push(projected);
  }
  return visible;
}

/**
 * 负责定义白天流水线消费的中断窗口契约。输入只要求同步 create 的请求端口、行动者、配置、当前性
 * 与提交回调，输出分别为自爆选择、决斗结果或是否跳过普通发言。
 * 本契约只有窄类型视图，不拥有具体角色状态、窗口许可、付款、阶段变化或判胜；
 * 窗口返回候选或接受结果，不表示后续死亡链和终局已经完成。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type {
  ActionProvider,
  ActionWindow,
  EntityId,
  KnightDuelCommit,
  KnightDuelSelection,
  KnightDuelWindow,
  Phase,
  SelfDestructSelection,
} from "../../core/domain/model";
import type { ActionRequestConstructionPort } from "../../core/domain/actions";

/** 提交回调返回 false 则继续下一候选；无回调时只返回选择，付款与标死仍归原提交／结算路径。 */
export interface DaytimeSelfDestructOpportunity {
  execute(
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: ActionWindow,
    phase: Phase,
    isCurrent?: () => boolean,
    commit?: (choice: SelfDestructSelection) => Promise<void | boolean>,
  ): Promise<SelfDestructSelection | null>;
}

/** 回调虽在类型中可选，实际有效决斗候选缺回调仍报原错误；endsDay 来自原提交结果。 */
export interface DaytimeDuelOpportunity {
  execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: KnightDuelWindow,
    isCurrent: () => boolean,
    commit?: (choice: KnightDuelSelection) => Promise<KnightDuelCommit>,
  ): Promise<{ selection: KnightDuelSelection | null; endsDay: boolean }>;
}

/** 辩论结果只决定是否跳过原普通发言；密封票、处罚、付款与关闭仍归实际窗口及其权威。 */
export interface DaytimeDebateOpportunity {
  execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    targetId: EntityId,
    day: number,
    isCurrent: () => boolean,
  ): Promise<{ skipSpeech: boolean }>;
}

/** 三个端口仍是原窗口实例；不绑定 execute 或复制返回值，原方法接收者保持不变。 */
export interface DaytimeInterruptionComposition {
  /** 每次执行最先检查重入；不能用 isCurrent=false 绕过仍开启的辩论。 */
  assertEntry(): void;
  /** readonly 限制成员重绑定，不冻结原窗口或将执行方法与接收者分离。 */
  readonly selfDestruct: DaytimeSelfDestructOpportunity;
  readonly duel: DaytimeDuelOpportunity;
  readonly debate: DaytimeDebateOpportunity;
}

/**
 * 负责原生命死亡提交与唯一的已结算生命账本。输入是有序玩家名单、原死亡原因，以及
 * 延迟读取结算器 World、事件数组和运行状态的上下文；输出是原 Alive 修改、事实事件、
 * 待过期枪列表、继承更新及成功提交凭证。isSettledLife 仅查询，markPlayersDead 是专用死亡写命令。
 * 本所有者不收集死亡波、遗言、枪击选择或警徽决定，不切换阶段，也不执行枪的最终过期。
 * 写入与记录失败均保留原先已提交的前缀，不回滚或提前发布已结算账本条目。
 */
import {
  DeathCommitReceipt,
  committedDeathEntry,
  planDeathWave,
  type DeathCommitEntry,
  type DeathWavePlan,
} from "./death-wave";
import { getSessionRecorder } from "../../recording/recording_context";
import { isRoleId } from "@ai-werewolf-arena/game-contract";
import { aliveLifeVersion, type AliveComponent } from "../../core/domain/components/alive";
import { COMPONENT } from "../../core/domain/components/names";
import {
  DeathCause,
  Role,
  type EntityId,
  type GameEvent,
  type RuntimeSnapshot,
  type DeathSources,
} from "../../core/domain/model";
import type { World } from "../../core/domain/world";
import {
  isAnimalDreamBoard,
  commitAnimalPufferKnifeDeath,
} from "../mechanisms/roles/animal_dream/ports";
import {
  isNobleBodyBoard,
  closeServantForDeath,
} from "../mechanisms/roles/noble_secret_body/ports";
import { appendNobleContractClosure } from "../mechanisms/roles/noble_secret_body/ports";
import { recordWildChildDeathCommit } from "../mechanisms/roles/wild_child/ports";
import { firstDeathGuns } from "../mechanisms/roles/death_abilities";
import { expireLuckyAbilitiesOnDeath } from "../mechanisms/roles/abilities";
import { refreshHiddenWolfInheritance } from "../mechanisms/roles/hidden_wolf/ports";
import { refreshGargoyleInheritance } from "../mechanisms/roles/gargoyle/ports";
import { refreshMechanicalInheritance } from "../mechanisms/roles/mechanical_wolf/ports";
import { refreshAwakenedInheritance } from "../mechanisms/roles/awakened_hidden_wolf/ports";

/** 访问器由结算器传入；每次读取原 World／事件／状态，不把 readonly 声明当作运行时写权限隔离。 */
interface DeathCommitContext {
  readonly world: World;
  readonly events: GameEvent[];
  readonly state: RuntimeSnapshot;
}

export class DeathCommitter {
  // 每个序号仅记原 Alive 对象与其生命版本；复活或替换组件必须重新结算。
  private readonly settledLives = new Map<
    EntityId,
    { component: AliveComponent; version: number | undefined }
  >();

  constructor(private readonly context: DeathCommitContext) {}

  isSettledLife(id: EntityId): boolean {
    const alive = this.context.world.getComponent(id, COMPONENT.Alive),
      settled = this.settledLives.get(id);
    return (
      alive !== undefined &&
      settled?.component === alive &&
      settled.version === aliveLifeVersion(alive)
    );
  }

  /**
   * 按原名单顺序提交；账本控制首次死亡分支（事实、被动／关系提交与揭示），不替调用方过滤重复 ID。
   * 重入仍写 Alive、收集枪并检查能力到期；gunsToExpire 由外层累积，这里仅追加。
   * 追加枪波关闭继承刷新，由外层在原位置执行；异常保留已提交的玩家和事实前缀。
   */
  markPlayersDead(
    playerIds: EntityId[],
    refreshInheritance = true,
    gunsToExpire: ReturnType<typeof firstDeathGuns> = [],
    reveal = false,
    sources: DeathSources = {},
    animalScope?: object | (() => boolean),
    wave?: DeathWavePlan,
  ): DeathCommitReceipt {
    if (wave && (wave.ids !== playerIds || wave.sources !== sources))
      throw new Error("death_wave_commit_input_mismatch");
    const committedWave = wave ?? planDeathWave(playerIds, sources, "legacy");
    const entries: DeathCommitEntry[] = [];
    for (const id of playerIds) {
      const alive = this.context.world.getComponent(id, COMPONENT.Alive);
      if (!alive) {
        continue;
      }
      // 先记野孩子的活跃生命死亡，再改 Alive；不能把首次判断移到修改之后。
      const firstSettlement = !this.isSettledLife(id);
      if (firstSettlement) recordWildChildDeathCommit(this.context.world, id);
      alive.alive = false;
      if (firstSettlement && isAnimalDreamBoard(this.context.world)) {
        if (
          (sources[id] ?? []).includes(DeathCause.WolfKill) &&
          this.context.world.getComponent(id, COMPONENT.Role)?.role === Role.Pufferfish
        ) {
          commitAnimalPufferKnifeDeath(
            this.context.world,
            this.context.state.day,
            sources[id] ?? [],
            animalScope ?? (() => !this.context.state.gameOver),
          );
        }
        if ((sources[id] ?? []).includes(DeathCause.Exile))
          this.context.events.push({
            timestamp: Date.now(),
            type: "voted_out",
            payload: { target: id },
          });
        else if (
          (sources[id] ?? []).some(
            (c) => c === DeathCause.PufferRetaliation || c === DeathCause.WhiteCatExpiry,
          )
        )
          this.context.events.push({
            timestamp: Date.now(),
            type: "additional_deaths",
            payload: { deaths: [id] },
          });
      }
      if (firstSettlement && isNobleBodyBoard(this.context.world)) {
        const closed = closeServantForDeath(this.context.world, this.context.state.day, id);
        const payload = {
          policy: "awa_noble_secret_body_v1" as const,
          actorId: id,
          day: this.context.state.day,
          causes: [...(sources[id] ?? [])],
        };
        this.context.events.push({
          timestamp: Date.now(),
          type: "noble_body_death_committed",
          payload,
          audience: Object.freeze([]),
        });
        getSessionRecorder()?.recordRequiredLogicOp({
          scope: "resolution",
          op: "noble_body_death_committed",
          phase: this.context.state.phase,
          status: "ok",
          output: {
            policy: payload.policy,
            playerId: id,
            day: payload.day,
            causes: payload.causes,
          },
        });
        if (closed)
          appendNobleContractClosure(
            this.context.world,
            this.context.state.day,
            closed,
            this.context.events,
            this.context.state.phase,
          );
      }
      const role = this.context.world.getComponent(id, COMPONENT.Role)?.role;
      if (reveal && firstSettlement && isRoleId(role))
        this.context.events.push({
          timestamp: Date.now(),
          type: "player_role_revealed",
          payload: { playerId: id, role },
        });
      gunsToExpire.push(...firstDeathGuns(this.context.world, id));
      expireLuckyAbilitiesOnDeath(this.context.world, id, this.context.events);
      // 事实、记录、枪列表和能力过期均成功之后才发布账本；任何早期异常不伪造完成。
      // 此前已改 Alive 或写出部分事实也不回滚；账本缺项不表示该目标尚未产生任何副作用。
      let settled: { component: AliveComponent; version: number | undefined };
      this.settledLives.set(id, (settled = { component: alive, version: aliveLifeVersion(alive) }));
      // 凭证复用已写账本的原条目；此后失败仍不返回成功凭证，也不撤销此前死亡。
      Object.freeze(settled);
      entries.push(committedDeathEntry(committedWave, id, firstSettlement, settled));
    }
    // 整波生命提交之后按原顺序刷新继承；此处失败不能撤销已写入的生命与账本。
    if (refreshInheritance) {
      refreshHiddenWolfInheritance(this.context.world, this.context.events, this.context.state.day);
      refreshGargoyleInheritance(this.context.world, this.context.events, this.context.state.day);
      refreshMechanicalInheritance(this.context.world, this.context.state.day, this.context.events);
      refreshAwakenedInheritance(this.context.world, this.context.state.day, this.context.events);
    }
    // 命令正常返回才交出本次条目；它不证明后续遗言／死亡钩子／枪付款或最终判胜已完成。
    return new DeathCommitReceipt(committedWave, Object.freeze(entries));
  }
}

/**
 * 负责死亡波的运行时提交输入与提交凭证结构。输入为已有名单、死因、来源阶段和原生命证据；
 * 输出只读计划及与唯一生命账本同引用的凭证，不重查 World、资格、时钟或库存。
 * 计划只引用调用方已有集合，不创建第二套 seen／原因／枪库存；凭证不是死亡行动授权。
 * 发布关联留在凭证内部，绝不修改事件、原 Alive 或归档形状；失败不生成成功凭证。
 */
import { isNightUnit, type NightUnit } from "../../core/domain/night-unit";
import { isExileUnit, type ExileUnit } from "../../core/domain/exile-unit";
import { types } from "node:util";
import type { AliveComponent } from "../../core/domain/components/alive";
import {
  DeathCause,
  Phase,
  type DeathSources,
  type EntityId,
} from "@ai-werewolf-arena/game-contract";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import type { NightPoisonRoute } from "../../core/domain/night_effects";

/** 调用方先前捕获的原生命与版本，供提交证据关联；它本身不授予死亡行动。 */
export interface DeathOriginalLife {
  readonly life: Readonly<AliveComponent>;
  readonly version: number | undefined;
}

/** 执行上下文不等于每个目标的因果来源；真正 Night／Day 来源仍由原 originPhases 决定。 */
export interface DeathExecutionContext {
  readonly night?: NightUnit;
  readonly exile?: ExileUnit;
  readonly phaseRevision?: number;
}
/** 只在实际初始波／角色追加 proposal 打开时创建；逐目标提交及再次访问复用此身份。 */
export interface DeathWaveUnit {
  readonly id: symbol;
  readonly kind: "initial" | "additional" | "legacy";
  readonly day: number | undefined;
  readonly actionPhase: Phase | undefined;
  readonly execution: DeathExecutionContext | undefined;
}

export function openDeathWave(
  kind: DeathWaveUnit["kind"],
  day?: number,
  actionPhase?: Phase,
  execution?: DeathExecutionContext,
): DeathWaveUnit {
  return Object.freeze({ id: Symbol("death_wave"), kind, day, actionPhase, execution });
}

/** 来源集合可继续由结算器按原位置扩展；只读接口不冻结 live 原体或调用方数组。 */
export interface DeathWavePlan {
  readonly units: readonly DeathWaveUnit[];
  readonly previousCommits: readonly DeathCommitReceipt[];
  readonly kind: "initial" | "additional" | "revisit" | "legacy";
  readonly ids: readonly EntityId[];
  readonly sources: Readonly<Record<EntityId, readonly DeathCause[]>>;
  readonly originPhases?: ReadonlyMap<EntityId, Phase>;
  readonly originalLives?: ReadonlyMap<EntityId, DeathOriginalLife>;
  readonly poisonRoutes: readonly NightPoisonRoute[];
}

const nativeMapGet = Map.prototype.get;
const noPoisonMetadata: readonly NightPoisonRoute[] = Object.freeze([]);

function ownMetadataValue(input: object | undefined, key: string): unknown {
  if (typeof input !== "object" || input === null || types.isProxy(input)) return undefined;
  const descriptor = Object.getOwnPropertyDescriptor(input, key);
  return descriptor && "value" in descriptor ? descriptor.value : undefined;
}

/** 只读新时钟 own-data，旧同名 getter／Proxy 不因迁移多执行；身份不授予死亡资格。 */
export function deathExecutionContext(input: object | undefined): DeathExecutionContext | undefined {
  const value = ownMetadataValue(input, "execution");
  if (typeof value !== "object" || value === null || types.isProxy(value)) return undefined;
  const night = ownMetadataValue(value, "night"), exile = ownMetadataValue(value, "exile");
  const phaseRevision = ownMetadataValue(value, "phaseRevision");
  return Object.freeze({
    ...(isNightUnit(night) ? { night } : {}),
    ...(isExileUnit(exile) ? { exile } : {}),
    ...(typeof phaseRevision === "number" ? { phaseRevision } : {}),
  });
}

/** 新元数据只消费 own-data，旧同名 getter／Proxy 不属于新增读取契约。 */
export function deathWaveOriginalLives(
  input: object | undefined,
): ReadonlyMap<EntityId, DeathOriginalLife> | undefined {
  const value = ownMetadataValue(input, "originalLives");
  return typeof value === "object" && value !== null && !types.isProxy(value) && types.isMap(value)
    ? (value as ReadonlyMap<EntityId, DeathOriginalLife>)
    : undefined;
}

/** 不迭代外来 Proxy／getter 数组；只快照普通数组的 own-data 原路由引用。 */
export function deathWavePoisonMetadata(input: object | undefined): readonly NightPoisonRoute[] {
  const value = ownMetadataValue(input, "poisonRoutes");
  if (value === undefined) return noPoisonMetadata;
  const values = dataValues(value, true);
  return values === null || values === opaque
    ? noPoisonMetadata
    : Object.freeze(
        values.filter(
          (route): route is NightPoisonRoute =>
            typeof route === "object" && route !== null && !types.isProxy(route),
        ),
      );
}

/** 原 Map 只读内部条目，不查找／调用覆盖的 get 方法；opaque 容器诊断记 unknown。 */
function mapMetadataValue<T>(
  map: ReadonlyMap<EntityId, T> | undefined,
  id: EntityId,
): T | undefined {
  return map !== undefined && !types.isProxy(map) && types.isMap(map)
    ? (nativeMapGet.call(map, id) as T | undefined)
    : undefined;
}

export interface DeathSettledLife {
  readonly component: Readonly<AliveComponent>;
  readonly version: number | undefined;
}

export interface DeathCommitEntry {
  readonly id: EntityId;
  readonly firstSettlement: boolean;
  readonly originPhase: Phase | undefined;
  readonly originalLife: DeathOriginalLife | undefined;
  /** 正是 ledger.set 使用的原对象，不另行捕获生命版本。 */
  readonly settled: DeathSettledLife;
  /** 来自已接受伤害的原路由，只绑定同原体／版本及仍保留的毒死因；未知来源不伪造。 */
  readonly poisonRoutes: readonly NightPoisonRoute[];
  readonly units: readonly DeathWaveUnit[];
}

export interface DeathPublication {
  readonly event: GameEvent;
  readonly ids: readonly EntityId[];
}

/**
 * 保存调用方传入的提交条目及其发布关联；生产死亡命令正常返回才交出本次凭证，空初始波可用空条目。
 * 凭证不验证枪付款、授予行动或保证整条链成功；后续异常不能据此撤销先前已提交的死亡。
 */
export class DeathCommitReceipt {
  private readonly publications: DeathPublication[] = [];
  constructor(
    readonly wave: DeathWavePlan,
    readonly entries: readonly DeathCommitEntry[],
  ) {}

  /** 对已提交原体的只读查询；缺项不冒充死亡，也不改旧 callback 的 pending 入参。 */
  committed(id: EntityId): DeathCommitEntry | undefined {
    return this.entries.find((entry) => entry.id === id);
  }

  /** 只保留真正仍属于该死因的接受路由；外部旧结果无路由时不制造来源。 */
  poisonRoutesFor(id: EntityId): readonly NightPoisonRoute[] {
    return this.committed(id)?.poisonRoutes ?? [];
  }

  /**
   * 关联原事件而不读其载荷、Symbol 或属性描述符，兼容冻结事件和旧 Proxy。
   * 同一事件对象只保留首次传入的编号关联，重复调用不合并名单或再次发布事件。
   */
  recordPublication(event: GameEvent, ids: readonly EntityId[]): void {
    if (this.publications.some((publication) => publication.event === event)) return;
    this.publications.push(Object.freeze({ event, ids: Object.freeze([...ids]) }));
  }

  publicationLinks(): readonly DeathPublication[] {
    return Object.freeze([...this.publications]);
  }
}

/** 单位／历史凭证数组复制并冻结；名单、原因和生命映射仍引用原输入，不冻结调用方的可变集合。 */
export function planDeathWave(
  ids: readonly EntityId[],
  sources: Readonly<Record<EntityId, readonly DeathCause[]>>,
  kind: DeathWavePlan["kind"],
  originPhases?: ReadonlyMap<EntityId, Phase>,
  originalLives?: ReadonlyMap<EntityId, DeathOriginalLife>,
  poisonRoutes: readonly NightPoisonRoute[] = [],
  units: readonly DeathWaveUnit[] = [openDeathWave("legacy")],
  previousCommits: readonly DeathCommitReceipt[] = [],
): DeathWavePlan {
  return Object.freeze({
    units: Object.freeze([...units]),
    previousCommits: Object.freeze([...previousCommits]),
    kind,
    ids,
    sources,
    originPhases,
    originalLives,
    poisonRoutes,
  });
}

/**
 * 在原 ledger.set 成功之后生成证据；只消费已读原体／版本，不查询 alive 值或任何 World。
 * 来源 metadata 不授予资格：旧路由缺失／外来 getter／复活后的版本不匹配时仅记 unknown。
 */
export function committedDeathEntry(
  wave: DeathWavePlan | undefined,
  id: EntityId,
  firstSettlement: boolean,
  settled: DeathSettledLife,
): DeathCommitEntry {
  const routes: NightPoisonRoute[] = [];
  if (wave && wave.poisonRoutes.length && !types.isProxy(wave.sources)) {
    const source = Object.getOwnPropertyDescriptor(wave.sources, String(id));
    const causes = source && "value" in source ? dataValues(source.value, true) : null;
    if (causes !== opaque && causes?.includes(DeathCause.Poison)) {
      for (const route of wave.poisonRoutes) {
        if (types.isProxy(route)) continue;
        const targetId = Object.getOwnPropertyDescriptor(route, "targetId");
        const routeKind = Object.getOwnPropertyDescriptor(route, "route");
        const original = Object.getOwnPropertyDescriptor(route, "origin");
        if (
          !targetId ||
          !("value" in targetId) ||
          targetId.value !== id ||
          !routeKind ||
          !("value" in routeKind) ||
          (routeKind.value !== "direct" && routeKind.value !== "reflected") ||
          !original ||
          !("value" in original)
        )
          continue;
        const origin: unknown = original.value;
        if (typeof origin !== "object" || origin === null || types.isProxy(origin)) continue;
        // 用 origin 创建时锁定的源／目标字段，不把后来可变的 route.target scope 当权威。
        const body = Object.getOwnPropertyDescriptor(
          origin,
          routeKind.value === "direct" ? "targetBody" : "sourceBody",
        );
        const version = Object.getOwnPropertyDescriptor(
          origin,
          routeKind.value === "direct" ? "targetVersion" : "sourceVersion",
        );
        if (
          body &&
          "value" in body &&
          body.value === settled.component &&
          version &&
          "value" in version &&
          typeof version.value === "number" &&
          settled.version !== undefined &&
          (settled.version === version.value + 1 || settled.version === version.value)
        )
          routes.push(route);
      }
    }
  }
  const prior =
    wave?.previousCommits.flatMap((receipt) => receipt.committed(id)?.units ?? []) ?? [];
  return Object.freeze({
    id,
    firstSettlement,
    settled,
    originPhase: mapMetadataValue(wave?.originPhases, id),
    originalLife: mapMetadataValue(wave?.originalLives, id),
    poisonRoutes: Object.freeze(routes),
    units: Object.freeze(prior.length ? [...new Set(prior)] : [...(wave?.units ?? [])]),
  });
}

const validCauses = new Set<string>(Object.values(DeathCause));
const validPhases = new Set<string>(Object.values(Phase));
const opaque = Symbol("opaque_death_input");

/**
 * 仅预检普通 own-data：Proxy、getter、继承字段和自定义迭代器保留旧惰性读取边界。
 * 静态坏数据必须在任何 Animal／关系事实前拒绝；此检查不读取 live World 或行动权限。
 */
function dataValues(value: unknown, array: boolean): unknown[] | typeof opaque | null {
  if (typeof value !== "object" || value === null) return null;
  if (types.isProxy(value)) return opaque;
  if (array !== Array.isArray(value)) return null;
  if (
    Object.getPrototypeOf(value) !== (array ? Array.prototype : Object.prototype) &&
    (array || Object.getPrototypeOf(value) !== null)
  )
    return opaque;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (
    Reflect.ownKeys(descriptors).some(
      (key) => typeof key !== "string" || !("value" in descriptors[key]!),
    )
  )
    return opaque;
  if (array) {
    if (Object.hasOwn(descriptors, Symbol.iterator)) return opaque;
    const length = descriptors.length!.value as number;
    const values: unknown[] = [];
    for (let i = 0; i < length; i++) {
      const descriptor = descriptors[String(i)];
      if (!descriptor) return null;
      values.push(descriptor.value);
    }
    if (
      Object.keys(descriptors).some(
        (key) => key !== "length" && (!/^(0|[1-9]\d*)$/.test(key) || Number(key) >= length),
      )
    )
      return null;
    return values;
  }
  if (
    Object.keys(descriptors).some(
      (key) => !/^(0|[1-9]\d*)$/.test(key) || !Number.isSafeInteger(Number(key)),
    )
  )
    return null;
  return Object.values(descriptors).map((descriptor) => descriptor.value);
}

/** 全 proposal 预检只强化 data-only 畸形输入；合法顺序、重复 ID／原因及未知 legacy 读取不改。 */
export function preflightDeathWaveData(
  ids: readonly EntityId[],
  sources: DeathSources,
  phases?: Readonly<Record<EntityId, Phase>>,
): void {
  const roots = dataValues(ids, true);
  if (
    roots !== opaque &&
    (roots === null ||
      roots.some((id) => typeof id !== "number" || !Number.isSafeInteger(id) || id < 0))
  )
    throw new Error("death_wave_input_invalid: ids");
  const causes = dataValues(sources, false);
  if (causes !== opaque) {
    if (causes === null) throw new Error("death_wave_input_invalid: sources");
    for (const list of causes) {
      const values = dataValues(list, true);
      if (
        values !== opaque &&
        (values === null ||
          values.some((cause) => typeof cause !== "string" || !validCauses.has(cause)))
      )
        throw new Error("death_wave_input_invalid: causes");
    }
  }
  if (phases !== undefined) {
    const values = dataValues(phases, false);
    if (
      values !== opaque &&
      (values === null ||
        values.some((phase) => typeof phase !== "string" || !validPhases.has(phase)))
    )
      throw new Error("death_wave_input_invalid: phases");
  }
}

/**
 * 负责有序死亡波、角色死亡钩子、枪击选择、遗言与警徽交接。输入是待处理的死亡名单、
 * 原死因与原生命行动权限；输出是按原顺序提交的死亡、事件和内部关联凭证。实际生命修改和唯一已结算
 * 账本委托 DeathCommitter，双生、动物、婚约及狼美人关系事实归具体贡献；已提交整波在梦／遗言前交角色扩展，
 * 野孩子贡献自行核对榜样原生命。参数仍使用同一深只读规则视图，不建立第二份角色状态。
 * 初始和枪后追加关系准备归各自具名规则组合；本结算器仍在原逐目标时点登记来源阶段、标死并提交／发布双生回执。
 * 未提交预约只在已进入的原 finally 处取消，已提交回执不因后续发布失败而回滚。
 * 枪的资格归共同所有者，请求、等待与目标复验归规则组合；本结算器持同一许可数组并在原时点关闭。
 * 本模块不切换阶段或确定最终胜负；关系扩展、遗言、警徽和枪的最终过期保留原执行顺序。
 */
import { refreshWolfKnifeInheritanceAtCheckpoint } from "../../rulesets/wolf-knife-inheritance-plan";
import { AnimalDeathWavePreparation } from "../mechanisms/roles/animal_dream/ports";
import {
