export interface NightPipelineDependencies {
  readonly rulePlan?: RulePlan;
  world: World;
  toolGateway: ToolGateway;
  damageResolutionSystem: DamageResolutionSystem;
  events: GameEvent[];
  stageRegistry?: NightStageRegistry;
  random?: RandomSource;
}

export interface NightPipelineOptions {
  readonly lifecycleHandoff?: NightLifecycleHandoff;
  previousExile?: Readonly<ExileFeedback> | null;
  isCurrent?: () => boolean;
}
export type NightPipelineResult =
  | {
      interrupted: false;
      summary: NightSummary;
      damage: DamageResolutionResult;
      dreamFrame: DreamNightEffects;
      mistDelay?: boolean;
      demonSources?: object;
      retaliationAttacks?: readonly import("../../../core/domain/night_effects").NightRetaliationAttack[];
      /** 本族捕获的运行查询；不携带可替换 Map 或私有库存结构。 */
      blocksPassiveNightShot?: (targetId: EntityId) => boolean;
      inspectionAttacks?: readonly import("../../../core/domain/night_effects").NightInspectionAttack[];
      demonWolfSourceCurrent?: (targetId: number) => boolean;
      demonKnifeProtection?: DemonKnifeProtection;
      foxInspections?: readonly import("../../../core/domain/night_effects").NightFoxInspectionClaim[];
      deathLives: ReadonlyMap<EntityId, { life: AliveComponent; version: number | undefined }>;
    }
  | { interrupted: true };

/**
 * 夜间阶段流水线：
 * - 通过 NightStageRegistry 串行驱动夜间子阶段；
 * - 最后统一执行伤害结算并返回结果。
 * night_resolved 事件由 PhaseManager 按白天流程时序写入。
 */
export class NightPipeline {
  private readonly world: World;
  private readonly toolGateway: ToolGateway;
  private readonly damageResolutionSystem: DamageResolutionSystem;
  private readonly events: GameEvent[];
  private readonly stageRegistry: NightStageRegistry;
  private readonly random: RandomSource;
  #rulePlan?: RulePlan;

  constructor(dependencies: NightPipelineDependencies) {
    this.world = dependencies.world;
    this.toolGateway = dependencies.toolGateway;
    this.damageResolutionSystem = dependencies.damageResolutionSystem;
    this.events = dependencies.events;
    this.stageRegistry = dependencies.stageRegistry ?? getDefaultNightStageRegistry();
    this.random = dependencies.random ?? createRandom();
    this.#rulePlan = dependencies.rulePlan;
  }

  /**
   * 执行完整夜间流程并返回结算摘要与伤害结果。
   */
  async execute(
    config: ReadonlyBoardConfig,
    actionProvider: ActionProvider,
    day: number,
    options: NightPipelineOptions = {},
  ): Promise<NightPipelineResult> {
    assertNightSetupReady({ world: () => this.world });
    const isCurrent = options.isCurrent ?? (() => true);
    if (!isCurrent())
      return attachNobleNightReceiver({ interrupted: true }, createNobleNightAbortReceiver());
    const pipeline = this;
    const prepare = this.#rulePlan
      ? this.#rulePlan.prepareNightPipelineLifecycle.bind(this.#rulePlan)
      : prepareNightPipelineLifecycle;
    const lifecycle = prepare(
      {
        get world() { return pipeline.world; },
        get events() { return pipeline.events; },
        get random() { return pipeline.random; },
      },
      config,
      day,
      () => options.lifecycleHandoff,
    );
    config = lifecycle.config;
    const rulePlan = this.#rulePlan ??= RulePlan.compile(lifecycle.parameters);
    const {
      ownsWedding, ownsDemon, ownsNoble, ownsFragrant, ownsAnimal, ownsRadiant, ownsMist,
      animalNight, fragrantNight, nobleNight, radiantNight, mistNight,
      weddingNight,
    } = lifecycle;
    try {
      lifecycle.open(isCurrent);
      // 归属保持本次生命周期的原值；World／config只在每个具体检查点晚读，不缓存玩家名单。
      const readability = {
        world: () => this.world,
        config: () => config,
        ownsAnimal: () => ownsAnimal,
        ownsFragrant: () => ownsFragrant,
        ownsNoble: () => ownsNoble,
        ownsRadiant: () => ownsRadiant,
        ownsMist: () => ownsMist,
        ownsDemon: () => ownsDemon,
      };
      const assertReadable = () => assertNightReadable(readability);
      assertReadable();
      const nativeProvider =
        ownsAnimal ||
        ownsRadiant ||
        ownsMist ||
        ownsDemon ||
        isEvilKnightBoard(this.world) ||
        isNightmareBoard(this.world) ||
        config.magician !== undefined ||
        config.scholarMentor !== undefined
          ? {
              getAction: async (request: ActionRequest) => {
                assertReadable();
                const action = await actionProvider.getAction(request);
                assertReadable();
                return action;
              },
            }
          : actionProvider;
      if (ownsWedding) weddingNight.open(day, isCurrent);
      // 保原同步检查点：若有婚约，已完成原开夜；起始记录和阶段状态尚未建立，拒绝仍走原 finally。
      assertNightCommitAdmission({ world: () => this.world, day: () => day });
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "night_pipeline_start",
        phase: Phase.Night,
        status: "ok",
        input: {
          board_size: config.boardSize,
        },
      });

      // 摄梦关系由本族按此对象身份首次使用时建立；通用状态不保存私有数组或其镜像。
      const stageState: NightStageState = {
        wolfChatOrder: [],
        endedWolves: new Set<EntityId>(),
        wolfVotes: {},
        wolfTarget: null,
        seerChecks: [],
        poisonClaims: [],
        guardClaims: [],
        merchantBacklashes: [],
        blackMarketBacklashes: [],
        mechanicalEffects: { shields: [], attacks: [], failures: [] },
        awakenedEffects: { shields: [], attacks: [] },
      };

      const requests = new GameActionRequestFactory(this.world, this.events, day);
      const stageCtx: NightStageContext = {
        isCurrent,
        previousExile: options.previousExile ? structuredClone(options.previousExile) : null,
        world: this.world,
        get nightActors() {
          return bindNightAbilityActorQuery(this.world);
        },
        get nativeNightFailure() {
          return rulePlan.nativeNightFailure(() => this.world);
        },
        get nativeNightTargets() {
          return rulePlan.nativeNightTargets(() => this);
        },
        get nativeNightEffects() {
          return rulePlan.nativeNightEffects(() => this);
        },
        roleCatalog: this.stageRegistry.roleCatalog,
        toolGateway: this.toolGateway,
        events: this.events,
        actionProvider: nativeProvider,
        currentDay: () => day,
        // 只提供晚类读取；机制仍在各自原 new 点使用原 World／events／day 参数。
        get requestFactory() { return GameActionRequestFactory; },
        makeRequest: (
          actorId: EntityId,
          allowedTools: ActionRequest["allowedTools"],
          context: ActionRequestExtras & { stage: ActionStage; requiresAction?: boolean },
        ) => this.makeRequest(requests, actorId, allowedTools, context),
        getAliveByRole: (role: Role) => this.getAliveByRole(role),
        ensureMarks: (entityId: EntityId) => this.ensureMarks(entityId),
        pickMajorityTarget: (votes: Record<number, number>) =>
          this.pickMajorityTarget(votes, config.tieBreaker?.wolfKillVote ?? "min_id"),
        pickMistKnife: (ids: readonly EntityId[]) =>
          ids.length
            ? ids[Math.floor(this.random.fork(`day:${day}:mist-knife`).next() * ids.length)]!
            : null,
        shuffleWolves: (ids: EntityId[]) =>
          shuffled(ids, this.random.fork(`day:${day}:wolf-order`)),
        state: stageState,
      };

      // 同一运行输入只持延迟表达式；各检查点按原次序读取 World／state、婚约归属和日期。
      const knifeAdmission = {
        world: () => this.world,
        state: () => stageState,
        ownsWedding: () => ownsWedding,
        day: () => day,
      };

      for (const entry of rulePlan.nightPlan(this.stageRegistry, () => this.world).entries) {
        const stage = entry.handler;
        assertEvilKnightRosterCurrent(this.world);
        if (!isCurrent())
          return attachNightUnit(attachNobleNightReceiver({ interrupted: true }, nobleNight.receiver), lifecycle.nightUnit);
        assertReadable();
        discardStaleNightKnives(knifeAdmission);
        assertNightModifierBonusEffects({ config: () => config, stageContext: () => stageCtx });
        await stage.execute(stageCtx);
        assertNightModifierBonusEffects({ config: () => config, stageContext: () => stageCtx });
        assertEvilKnightRosterCurrent(this.world);
        assertReadable();
        if (!isCurrent())
          return attachNightUnit(attachNobleNightReceiver({ interrupted: true }, nobleNight.receiver), lifecycle.nightUnit);
        discardStaleNightKnives(knifeAdmission);
      }

      discardStaleNightKnives(knifeAdmission);
      const { demonSources, demonWolfSourceCurrent, demonKnifeProtection } = prepareNightSourceDelivery({
        ownsDemon: () => ownsDemon,
        world: () => this.world,
        day: () => day,
        claims: () => stageState,
      });
      const { dreamFrame, damage } = composeNightDamage({
        ownsRadiant: () => ownsRadiant,
        world: () => this.world,
        day: () => day,
        claims: () => stageState,
        config: () => config,
        stageContext: () => stageCtx,
        solver: () => this.damageResolutionSystem,
        aliveByRole: (role) => this.getAliveByRole(role()),
      });
      if (ownsNoble) {
        const payload = {
          policy: "awa_noble_secret_body_v1" as const,
          actorId: checkpointNobleBodyAuthority(this.world, false).bodyId,
          day,
        };
        this.events.push({
          timestamp: Date.now(),
          type: "noble_body_native_damage_committed",
          payload,
          audience: Object.freeze([]),
        });
        getSessionRecorder()?.recordRequiredLogicOp({
          scope: "resolution",
          op: "noble_body_native_damage_committed",
          phase: Phase.Night,
          status: "ok",
          output: payload,
        });
      }
      assertReadable();
      for (const reflection of damage.poisonReflections ?? [])
        this.events.push({
          timestamp: Date.now(),
          type: "mechanical_poison_reflected",
          payload: { ...reflection, day },
        });
      const mist = ownsMist
        ? mistNight.captureDamage(this.world, day, stageState.wolfTarget)
        : null;
      if (mist?.extra && livingNightLife(this.world, mist.extra)) {
        const id = mist.extra.id;
        if (!damage.deaths.includes(id)) damage.deaths.push(id);
        damage.deathSources[id] = [
          ...new Set([...(damage.deathSources[id] ?? []), DeathCause.RavenClawKnife]),
        ];
      }
      if (!mist?.delayEligible) dreamFrame.expandInitialDamage(this.world, damage);
      if (!mist?.delayEligible && !ownsNoble)
        safeRecordLogicOp({
          scope: "resolution",
          op: "night_damage_resolved",
          phase: Phase.Night,
          status: "ok",
          output: {
            deaths: damage.deaths,
            death_sources: damage.deathSources,
          },
        });

      const summary: NightSummary = {
        wolfTarget: stageState.wolfTarget,
        deaths: [...damage.deaths],
        seerChecks: stageState.seerChecks,
        interruptedBySelfDestruct: false,
      };

      const deathLives = ownsDemon
        ? originalDemonNightLives(this.world)
        : new Map(
            (mist?.delayEligible ? this.world.getAliveEntityIds() : damage.deaths).map((id) => {
              const life = this.world.getComponent(id, COMPONENT.Alive)!;
              return [id, { life, version: aliveLifeVersion(life) }] as const;
            }),
          );
      lifecycle.finishPipeline();
      return attachNightUnit(attachNobleNightReceiver(
        {
          interrupted: false,
          summary,
          damage,
          dreamFrame,
          ...(mist ? { mistDelay: mist.delayEligible } : {}),
          deathLives,
          retaliationAttacks: stageState.retaliationAttacks,
          blocksPassiveNightShot: captureEvilKnightNightShotProtection(stageState),
          inspectionAttacks: stageState.inspectionAttacks,
          foxInspections: stageState.foxInspections,
          ...(demonSources ? { demonSources, demonWolfSourceCurrent, demonKnifeProtection } : {}),
        },
        nobleNight.receiver,
      ), lifecycle.nightUnit);
    } finally {
      lifecycle.abortPipeline();
    }
  }

  private makeRequest(
    requests: GameActionRequestFactory,
    actorId: EntityId,
    allowedTools: ActionRequest["allowedTools"],
    context: ActionRequestExtras & { stage: ActionStage; requiresAction?: boolean },
  ): ActionRequest {
    const { stage, requiresAction = true, ...extraContext } = context;
    return requests.create({
      phase: Phase.Night,
      actorId,
      allowedTools,
      stage,
      requiresAction,
      summary: { key: "request.summary.night_action" },
      context: {
        ...extraContext,
        ...(isMistRavenBoard(this.world) &&
        (allowedTools.includes("kill_vote") || allowedTools.includes("speak_to_wolves"))
          ? { wolf_kill_candidates: mistKnifeTargets(this.world) ?? this.world.getAliveEntityIds() }
          : {}),
        ...((isFragrantPairBoard(this.world) &&
          (allowedTools.includes("kill_vote") || allowedTools.includes("speak_to_wolves"))) ||
        isNobleBodyBoard(this.world) ||
        isRadiantEclipseBoard(this.world) ||
        isMistRavenBoard(this.world) ||
        isScholarMentorBoard(this.world) ||
        isTimeConsortBoard(this.world) ||
        isMagicianBoard(this.world) ||
        isEvilKnightBoard(this.world) ||
        isNightmareBoard(this.world) ||
        isRedMoonBoard(this.world)
          ? { action_failure_policy: "error" as const, allow_fallback: false }
          : {}),
      },
    });
  }

  /**
   * 获取指定角色的存活玩家列表。
   */
  private getAliveByRole(role: Role): EntityId[] {
    return this.world.getAliveEntityIds().filter((id) => {
      const roleComp = this.world.getComponent(id, COMPONENT.Role);
      return roleComp?.role === role;
    });
  }

  /**
   * 获取或创建目标玩家的状态印记组件。
   */
  private ensureMarks(entityId: EntityId): StatusMarksComponent {
    let marks = this.world.getComponent(entityId, COMPONENT.StatusMarks);
    if (!marks) {
      // 标记组件按需创建，避免无状态玩家占用冗余存储。
      marks = new StatusMarksComponent();
      this.world.addComponent(entityId, COMPONENT.StatusMarks, marks);
    }
    return marks;
  }

  /**
   * 依据票数选出狼刀目标，平票按编号最小值决议。
   */
  private pickMajorityTarget(
    votes: Record<number, number>,
    strategy: TieBreakerStrategy,
  ): EntityId | null {
    const entries = Object.entries(votes);
    if (entries.length === 0) {
      return null;
    }
    entries.sort((a, b) => {
      const voteDiff = b[1] - a[1];
      if (voteDiff !== 0) {
        return voteDiff;
      }
      return Number(a[0]) - Number(b[0]);
    });
    if (entries.length >= 2 && entries[0][1] === entries[1][1]) {
      if (strategy === "no_kill") {
        return null;
      }
    }
    return Number(entries[0][0]);
  }
}

/**
 * 负责放逐投票的实际单位、候选、席位顺序及既有回合／平票／票权政策。
 * 输入为当前玩家与行动；输出为原票据和放逐结果。preVote中断不制造普通开票单位；
 * 首票前开同一单位，王子复收票与PK共用，零放逐、翻牌或映射落空仍属于已开单位。
 * 秘密之身的付款、必需发言与关闭归本族同步序列；本流水线只在原请求点 await，不额外等待未触发路径。
 * Animal复用原token且独占计数／到期政策。警长选举和狼刀维持各自流程，不合并为通用投票器。
 * 诡术师最终映射／事实／出局提案归具名同步组合；本流水线保两块之间的 Noble 等待及原关闭、票与PK。
 * 定序王子的重收票政策归具名同步组合；同一 options 局部在原点替换，后续 PK 共享严格复验闭包。
 */
import { revealSecretBodyExile } from "../../mechanisms/roles/noble_secret_body/exile-ports";
import { openExileUnit, attachExileUnit } from "../../../core/domain/exile-unit";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import {
  beginAnimalExileUnit,
  recordAnimalBallotRound,
  sealAnimalBallots,
} from "../../mechanisms/roles/animal_dream/ballot-ports";
import { runAnimalPufferChoice } from "../../mechanisms/roles/animal_dream/choice-ports";
import { prepareMappedExile, resolveMappedExile, mappedExileSummary } from "../../../rulesets/mapped-exile-resolution";
import { recollectOrderPrinceVotes } from "../../../rulesets/order-prince-revote";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { COMPONENT } from "../../../core/domain/components/names";
import { IdentityComponent } from "../../../core/domain/entities/player";
import { VotingRightComponent } from "../../../core/domain/components/voting_right";
import {
  ActionProvider,
  ActionWindow,
  EntityId,
  GameEvent,
  Phase,
  TieBreakerStrategy,
  VoteRecord,
  VotingSummary,
} from "../../../core/domain/model";
import { RoleRegistry } from "../../../core/domain/registries/role_registry";
import { ToolGateway } from "../../gateway/tool_gateway";
import { safeRecordLogicOp } from "../../../recording/session_recorder";
import { EventRegistry } from "../event_registry";
import { World } from "../../../core/domain/world";
import { GameActionRequestFactory } from "../action_request_factory";
import { SelfDestructWindow, isSelfDestructWindowEnabled } from "../../../rulesets/self-destruct-window";
import { canBeExiled, canVoteExile } from "../../mechanisms/common/participation";

/**
 * 投票流水线执行结果。
 */
export interface VotingPipelineResult {
  animalUnit?: object;
  animalRetaliation?: readonly number[];
  summary: VotingSummary;
  interrupted: boolean;
  removed: EntityId[];
  selfDestruct?: import("../../../core").SelfDestructSelection;
}

export interface VotingPipelineOptions {
  strictRequired?: boolean;
  orderPrinceRevote?: boolean;
  /** 当前日次由 PhaseManager 显式传入，不能从事件历史反推。 */
  day: number;
  isCurrent?: () => boolean;
  commitSelfDestruct?: (
    choice: import("../../../core").SelfDestructSelection,
  ) => Promise<void | boolean>;
}

export interface VotingPipelineDependencies {
  world: World;
  roleRegistry: RoleRegistry;
  toolGateway: ToolGateway;
  eventRegistry: EventRegistry;
  events: GameEvent[];
}

interface CollectedVote {
  voterId: EntityId;
  targetId: EntityId | null;
  abstain: boolean;
  fallback: boolean;
  voterLife: NonNullable<ReturnType<typeof captureNightLife>>;
  targetLife?: NonNullable<ReturnType<typeof captureNightLife>>;
}

/**
 * 放逐投票流水线：
 * 1) 在 onPreVote 窗口可触发狼人自爆中断。
 * 2) 存活且有投票权玩家依次投票，按权重计票。
 * 3) 调用 EventRegistry 处理白痴免死、警徽销毁等投后钩子。
 */
export class VotingPipeline {
  private static readonly MAX_VOTE_RETRIES = 3;
  private readonly world: World;
  private readonly selfDestructWindow: SelfDestructWindow;
  private readonly toolGateway: ToolGateway;
  private readonly eventRegistry: EventRegistry;
  private readonly events: GameEvent[];

  constructor(dependencies: VotingPipelineDependencies) {
    this.world = dependencies.world;
    this.toolGateway = dependencies.toolGateway;
    this.eventRegistry = dependencies.eventRegistry;
    this.events = dependencies.events;
    this.selfDestructWindow = new SelfDestructWindow(
      this.world,
      dependencies.roleRegistry,
      this.toolGateway,
    );
  }

  async execute(
    config: ReadonlyBoardConfig,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
  ): Promise<VotingPipelineResult> {
    let unitDay: number;
    const requests = new GameActionRequestFactory(this.world, this.events, (unitDay = options.day));
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "voting_pipeline_start",
      phase: Phase.Voting,
      status: "ok",
      input: {
        on_pre_vote_hook: config.hooks.onPreVote,
      },
    });
    if (config.hooks.onPreVote && isSelfDestructWindowEnabled(config, ActionWindow.OnPreVote)) {
      const exploded = await this.selfDestructWindow.execute(
        requests,
        actionProvider,
        ActionWindow.OnPreVote,
        Phase.Voting,
        options.isCurrent,
        options.commitSelfDestruct,
      );
      if (exploded !== null) {
        safeRecordLogicOp({
          scope: "phase_pipeline",
          op: "voting_interrupted_by_self_destruct",
          actorId: exploded.actorId,
          phase: Phase.Voting,
          status: "ok",
        });
        return {
          summary: {
            tally: {},
            target: null,
            removed:
              exploded.targetId === null
                ? [exploded.actorId]
                : [exploded.actorId, exploded.targetId],
          },
          interrupted: true,
          selfDestruct: exploded,
          removed:
            exploded.targetId === null ? [exploded.actorId] : [exploded.actorId, exploded.targetId],
        };
      }
    }

    if (options.isCurrent && !options.isCurrent())
      return { summary: { tally: {}, target: null, removed: [] }, interrupted: false, removed: [] };
    const animalUnit = config.animalDream
      ? beginAnimalExileUnit(
          this.world,
          (unitDay = options.day),
          "exile",
          () => options.isCurrent?.() !== false,
        )
      : undefined;
    // 此门禁已开启一次真实放逐；后续重新收票／PK仍消费同一个对象。
    const exileUnit = openExileUnit(unitDay, "exile", animalUnit);
    const voters = this.world
      .getAliveEntityIds()
      .filter((id) => canVoteExile(this.world, id, options.day));

    // 请求并行执行；Promise.all 保留原投票者顺序，公开票据按该顺序稳定发布。
    const voteResults = await this.collectVotes(voters, requests, actionProvider, options);
    if (options.isCurrent?.() === false)
      return attachExileUnit({ summary: { tally: {}, target: null, removed: [] }, interrupted: false, removed: [] }, exileUnit);
    let { tally, publicVotes } = this.recordVotesInSeatOrder(voteResults, options.day);
    if (animalUnit) recordAnimalBallotRound(this.world, animalUnit, 1, publicVotes);
    const revotePipeline = this;
    const revote = recollectOrderPrinceVotes({
      get config() { return config; },
      get world() { return revotePipeline.world; },
      get requests() { return requests; },
      get actionProvider() { return actionProvider; },
      get toolGateway() { return revotePipeline.toolGateway; },
      get events() { return revotePipeline.events; },
      // 同一局部在原激活点替换，初始选择和后续 PK 继续晚读它；不是第二份 options 快照。
      get options() { return options; },
      set options(next) { options = next; },
      collectVotes(voters: EntityId[]) {
        return revotePipeline.collectVotes(voters, requests, actionProvider, options);
      },
      recordVotes(votes: Array<CollectedVote | null>) {
        return revotePipeline.recordVotesInSeatOrder(votes, options.day, true);
      },
    });
    let revoteStep = revote.next();
    while (!revoteStep.done) {
      // 仅在组合交回原 choice／collect Promise 时等待；未配置或未重启没有新的尾 await。
      revoteStep = revote.next(await revoteStep.value);
    }
    if (revoteStep.value !== undefined)
      ({ tally, publicVotes } = revoteStep.value);
    const pk = config.voting?.exilePolicy === "awa_one_pk_v1";
    const maximum = Math.max(
      0,
      ...Object.entries(tally)
        .filter(([id]) => canBeExiled(this.world, Number(id)))
        .map(([, score]) => score),
    );
    const tied =
      maximum > 0
        ? Object.entries(tally)
            .filter(([id, score]) => score === maximum && canBeExiled(this.world, Number(id)))
            .map(([id]) => Number(id))
        : [];
    let round = 1;
    if (pk && tied.length > 1) {
      this.events.push({
        timestamp: Date.now(),
        type: "vote_summary",
        payload: { votes: publicVotes, tally, target: null, round: 1 },
      });
      this.events.push({
        timestamp: Date.now(),
        type: "exile_pk_started",
        payload: { candidates: tied },
      });
      for (const actorId of tied) {
        if (options.isCurrent?.() === false)
          return attachExileUnit({
            summary: { tally: {}, target: null, removed: [] },
            interrupted: false,
            removed: [],
          }, exileUnit);
        const life = captureNightLife(this.world, actorId);
        if (!life || !canBeExiled(this.world, actorId)) {
          if (options.strictRequired) throw new Error("order_prince_pk_candidate_stale");
          continue;
        }
        const request = requests.create({
          phase: Phase.Voting,
          actorId,
          allowedTools: ["speak"],
          stage: "exile_pk_speech",
          requiresAction: true,
          summary: { key: "request.summary.exile_pk" },
          context: {
            exile_candidates: tied,
            round: 2,
            max_rounds: 2,
            ...(options.strictRequired
              ? { action_failure_policy: "error", allow_fallback: false }
              : {}),
          },
        });
        const action = await actionProvider.getAction(request);
        if (options.isCurrent?.() === false)
          return attachExileUnit({
            summary: { tally: {}, target: null, removed: [] },
            interrupted: false,
            removed: [],
          }, exileUnit);
        if (
          action?.name !== "speak" ||
          !livingNightLife(this.world, life) ||
          !canBeExiled(this.world, actorId)
        ) {
          if (options.strictRequired) throw new Error("order_prince_pk_speech_missing_or_stale");
          continue;
        }
        const result = this.toolGateway.validateAndSanitize(this.world, actorId, action, {
          phase: Phase.Voting,
          day: options.day,
        });
        if (
          options.strictRequired &&
          (!result.ok || !result.sanitizedCall || !livingNightLife(this.world, life))
        )
          throw new Error("order_prince_pk_speech_invalid");
        if (result.ok && result.sanitizedCall && livingNightLife(this.world, life))
          this.events.push({
            timestamp: Date.now(),
            type: "day_speech",
            payload: { actorId, text: result.sanitizedCall.args.text },
          });
      }
      const candidates = tied.filter((id) => canBeExiled(this.world, id));
      const revoters = this.world
        .getAliveEntityIds()
        .filter((id) => !tied.includes(id) && canVoteExile(this.world, id, options.day));
      const results = await this.collectVotes(
        revoters,
        requests,
        actionProvider,
        options,
        candidates,
      );
      if (options.isCurrent?.() === false)
        return attachExileUnit({
          summary: { tally: {}, target: null, removed: [] },
          interrupted: false,
          removed: [],
        }, exileUnit);
      ({ tally, publicVotes } = this.recordVotesInSeatOrder(
        results,
        options.day,
        options.strictRequired,
      ));
      round = 2;
      if (animalUnit) recordAnimalBallotRound(this.world, animalUnit, 2, publicVotes, candidates);
    }

    const target = this.pickMajorityTarget(
      Object.fromEntries(
        Object.entries(tally).filter(([id]) => canBeExiled(this.world, Number(id))),
      ),
      pk ? "no_elimination" : (config.tieBreaker?.exileVote ?? "min_id"),
    );
    this.events.push({
      timestamp: Date.now(),
      type: "vote_summary",
      payload: {
        votes: publicVotes,
        tally,
        target,
        ...(pk ? { round } : {}),
      },
    });
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "vote_tally_resolved",
      phase: Phase.Voting,
      status: "ok",
      output: {
        tally,
        target,
      },
    });
    let animalRetaliation: readonly number[] = [];
    if (animalUnit) {
      sealAnimalBallots(this.world, animalUnit);
      animalRetaliation = await runAnimalPufferChoice(
        this.world,
        this.events,
        actionProvider,
        this.toolGateway,
        options.day,
        animalUnit,
        // 封存原票之后只提供惰性依赖；河豚在原有效 actor／scope 边界前独立构造，不能复用 requests。
        { get requestFactory() { return GameActionRequestFactory; } },
      );
    }
    if (target === null) {
      return attachExileUnit({
        summary: {
          tally,
          target: null,
          removed: [],
        },
        interrupted: false,
        removed: [],
        ...(animalUnit ? { animalUnit, animalRetaliation } : {}),
      }, exileUnit);
    }

    const thisPipeline = this;
    // 原映射先付款／发表，再取有效目标；Noble 仍在两业务块之间，不按 missed 跳过。
    const { mapped, effectiveTarget } = prepareMappedExile({
      get enabled() { return config.trickster; },
      get world() { return thisPipeline.world; },
      get day() { return options.day; },
      get events() { return thisPipeline.events; },
    }, target);
    const reveal = revealSecretBodyExile(
      {
        get enabled() { return config.nobleSecretBody; },
        get world() { return thisPipeline.world; },
        get events() { return thisPipeline.events; },
        get requests() { return requests; },
        get toolGateway() { return thisPipeline.toolGateway; },
        get day() { return options.day; },
        get isCurrent() { return options.isCurrent; },
      },
      effectiveTarget,
    );
    const revealStep = reveal.next();
    if (!revealStep.done) {
      try {
        // 只等待原 Provider；未触发翻牌的同步完成路径不进入此处。
        const action = await actionProvider.getAction(revealStep.value);
        reveal.next(action);
      } finally {
        // Provider 同步抛错／拒绝时驱动本族关闭；已完成或抛错的生成器不会再次关闭 scope。
        reveal.return(false);
      }
      return attachExileUnit({ summary: { tally, target, removed: [] }, removed: [], interrupted: false }, exileUnit);
    }
    // Noble 同步完成之后才形成出局提案；原钩子 receiver 与参数读取保持晚读。
    const removed = resolveMappedExile({
      get eventRegistry() { return thisPipeline.eventRegistry; },
      get world() { return thisPipeline.world; },
      get events() { return thisPipeline.events; },
      get animalUnit() { return animalUnit; },
    }, mapped, effectiveTarget);

    return attachExileUnit({
      summary: {
        tally,
        target,
        ...mappedExileSummary(mapped, effectiveTarget),
        removed,
      },
      interrupted: false,
      removed,
      ...(animalUnit ? { animalUnit, animalRetaliation } : {}),
    }, exileUnit);
  }

  private async collectVotes(
    voters: EntityId[],
    requests: GameActionRequestFactory,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
    candidates?: EntityId[],
  ): Promise<Array<CollectedVote | null>> {
    // 在调用任何 Provider 之前捕获完整轮次；同步测试 Provider 也不能改变后续捕获的原生命。
    const voterLives = voters.map((voterId) => ({
      voterId,
      life: captureNightLife(this.world, voterId),
    }));
    const targetLives = new Map(
      (candidates ?? this.world.getAliveEntityIds()).flatMap((id) => {
        const life = captureNightLife(this.world, id);
        return life ? [[id, life] as const] : [];
      }),
    );
    return Promise.all(
      voterLives.map(({ voterId, life }) =>
        life
          ? this.collectVoterVote(
              voterId,
              life,
              targetLives,
              requests,
              actionProvider,
              options,
              candidates,
            )
          : null,
      ),
    );
  }

  private async collectVoterVote(
    voterId: EntityId,
    voterLife: NonNullable<ReturnType<typeof captureNightLife>>,
    targetLives: ReadonlyMap<EntityId, NonNullable<ReturnType<typeof captureNightLife>>>,
    requests: GameActionRequestFactory,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
    candidates?: EntityId[],
  ): Promise<CollectedVote | null> {
    const current = () => {
      const valid =
        options.isCurrent?.() !== false &&
        livingNightLife(this.world, voterLife) &&
        canVoteExile(this.world, voterId, options.day) &&
        !candidates?.includes(voterId);
      if (!valid && options.strictRequired) throw new Error("order_prince_revote_actor_stale");
      return valid;
    };
    const maxRetries = VotingPipeline.MAX_VOTE_RETRIES;
    let retryReason = "";
    const recordRetry = (attempt: number) =>
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_retry_requested",
        actorId: voterId,
        phase: Phase.Voting,
        status: "fallback",
        reason: retryReason,
        output: { attempt, max_retries: maxRetries },
      });

    for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
      if (!current()) return null;
      const baseRequest = requests.create({
        phase: Phase.Voting,
        actorId: voterId,
        allowedTools: ["vote"],
        stage: candidates
          ? "exile_pk_vote"
          : options.orderPrinceRevote
            ? "order_prince_revote"
            : "voting",
        requiresAction: true,
        summary: { key: "request.summary.exile_vote" },
        context: {
          ...(candidates ? { exile_candidates: candidates, round: 2, max_rounds: 2 } : {}),
          ...(options.strictRequired
            ? { action_failure_policy: "error", allow_fallback: false }
            : {}),
        },
      });
      const request =
        attempt === 1
          ? baseRequest
          : {
              ...baseRequest,
              context: {
                ...baseRequest.context,
                retry_attempt: attempt - 1,
                retry_max: maxRetries,
                retry_reason: retryReason,
                retry_notice_message: { key: "request.retry.exile_vote" as const },
              },
            };
      if (!current()) return null;
      const action = await actionProvider.getAction(request);
      if (!current()) return null;
      if (action?.name !== "vote") {
        retryReason = "no_valid_vote_tool_call";
        if (attempt <= maxRetries) {
          recordRetry(attempt);
          continue;
        }
        break;
      }

      const result = this.toolGateway.validateAndSanitize(this.world, voterId, action, {
        phase: Phase.Voting,
        day: options.day,
        exileCandidates: candidates,
      });
      if (
        !result.ok ||
        !result.sanitizedCall ||
        (!result.sanitizedCall.args.abstain &&
          (!targetLives.get(result.sanitizedCall.args.target_id!) ||
            !livingNightLife(this.world, targetLives.get(result.sanitizedCall.args.target_id!)!)))
      ) {
        retryReason = "invalid_vote_arguments";
        if (attempt <= maxRetries) {
          recordRetry(attempt);
          continue;
        }
        break;
      }
      return {
        voterId,
        targetId: result.sanitizedCall.args.target_id,
        abstain: result.sanitizedCall.args.abstain === true,
        fallback: attempt > 1,
        voterLife,
        ...(result.sanitizedCall.args.target_id !== null
          ? { targetLife: targetLives.get(result.sanitizedCall.args.target_id) }
          : {}),
      };
    }

    if (!current()) return null;
    if (options.strictRequired) throw new Error("order_prince_revote_action_missing_or_invalid");
    // 重试耗尽后仍需原网关接受，才将缺失行动修复为明确弃票。
    const repaired = this.toolGateway.validateAndSanitize(
      this.world,
      voterId,
      { name: "vote", args: { target_id: null, abstain: true } },
      { phase: Phase.Voting, day: options.day, exileCandidates: candidates },
    );
    if (repaired.ok && repaired.sanitizedCall) {
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_repaired_to_abstain",
        actorId: voterId,
        phase: Phase.Voting,
        status: "ok",
        reason: retryReason || "vote_retry_exhausted",
      });
      return { voterId, targetId: null, abstain: true, fallback: true, voterLife };
    }
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "vote_rejected",
      actorId: voterId,
      phase: Phase.Voting,
      status: "rejected",
      reason: retryReason || "vote_retry_exhausted",
    });
    return null;
  }

  private recordVotesInSeatOrder(
    votes: Array<CollectedVote | null>,
    day: number,
    strictRequired = false,
  ): {
    tally: Record<number, number>;
    publicVotes: VoteRecord[];
  } {
    const tally: Record<number, number> = {};
    const publicVotes: VoteRecord[] = [];
    for (const vote of votes) {
      if (!vote) continue;
      const { voterId } = vote;
      if (
        !livingNightLife(this.world, vote.voterLife) ||
        (!vote.abstain && (!vote.targetLife || !livingNightLife(this.world, vote.targetLife))) ||
        !canVoteExile(this.world, voterId, day) ||
        (!vote.abstain && vote.targetId !== null && !canBeExiled(this.world, vote.targetId))
      ) {
        if (strictRequired) throw new Error("order_prince_revote_ballot_stale");
        continue;
      }
      let weight = 0;
      if (!vote.abstain && vote.targetId !== null) {
        const voting = this.world.getComponent(voterId, COMPONENT.VotingRight);
        weight = voting?.weight ?? 1;
        tally[vote.targetId] = (tally[vote.targetId] ?? 0) + weight;
      }
      this.events.push({
        timestamp: Date.now(),
        type: "vote_cast",
        payload: {
          actorId: voterId,
          targetId: vote.targetId,
          abstain: vote.abstain,
          weight,
          ...(vote.fallback ? { fallback: true } : {}),
        },
      });
      publicVotes.push({
        actorId: voterId,
        targetId: vote.targetId,
        abstain: vote.abstain,
        weight,
      });
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_cast",
        actorId: voterId,
        phase: Phase.Voting,
        status: "ok",
        output: { target_id: vote.targetId, abstain: vote.abstain, weight },
      });
    }
    return { tally, publicVotes };
  }

  /**
   * 依据计票结果选出放逐目标，平票按编号最小值决议。
   */
  private pickMajorityTarget(
    tally: Record<number, number>,
    strategy: TieBreakerStrategy,
  ): EntityId | null {
    const entries = Object.entries(tally);
    if (entries.length === 0) {
      return null;
    }

    entries.sort((a, b) => {
      const voteDiff = b[1] - a[1];
      if (voteDiff !== 0) {
        return voteDiff;
      }
      if (strategy === "min_seat") {
        const aId = Number(a[0]);
        const bId = Number(b[0]);
        const aSeat = this.world.getComponent(aId, COMPONENT.Identity)?.seat ?? aId;
        const bSeat = this.world.getComponent(bId, COMPONENT.Identity)?.seat ?? bId;
        return aSeat - bSeat;
      }
      return Number(a[0]) - Number(b[0]);
    });

    if (entries.length >= 2 && entries[0][1] === entries[1][1]) {
      if (strategy === "no_elimination") {
        return null;
      }
    }

    return Number(entries[0][0]);
  }
}

/**
 * 负责从明确的引擎要求构造公共回合约束数据。输入为必须行动标识、允许工具、可选摘要和动作上限；
 * 输出保留原默认值、可选字段及字符串／中立消息引用的区别，不在这里渲染文案。
 * 这些字段描述请求要求，不是已经提交的行动、真实库存、期限或运行凭据；实际准入与完成仍归原所有者。
 * 本模块不读 World、不持玩家状态或授权，不增加参数 schema／有限数校验或修复既有非法输入。
 */
import type { MessageRef } from "@ai-werewolf-arena/game-contract";
import { ToolName, TurnConstraints } from "../../core/domain/model";

/**
 * 构造统一的 turn_constraints 上下文字段。
 * 默认按“单主动作”生成：必须行动的 min 为 1，可选窗口为 0，默认上限为 1。
 * 只有必须行动才复制 required_any_tools；可选窗口输出空数组，不据工具名字新增角色资格。
 * max 仍执行原取整／Math.max，不额外保证有限数；消费端另按原契约解析和检查实际动作。
 */
export function buildTurnConstraintContext(input: {
  /** 原布尔字段在 min 和 required_any_tools 处分别读取；不把两次 getter 合成快照。 */
  requiresAction: boolean;
  /** 必须行动时另复制此数组；不是对实际资源或具体机制当前性的授权。 */
  allowedTools: ToolName[];
  /** 非空字符串保持原字段；真值消息引用在原分支克隆，二者不合并成已渲染文案。 */
  summary?: string | MessageRef;
  /** 仅按原 nullish 默认及取整处理；未在此加入数值验证或新的拒绝政策。 */
  maxValidActions?: number;
}): TurnConstraints {
  const min = input.requiresAction ? 1 : 0;
  // max → 必须工具 → 摘要按原顺序求值；数组展开或消息 clone 失败仍传播，不能返回部分约束。
  return {
    min_valid_actions: min,
    max_valid_actions: Math.max(min, Math.floor(input.maxValidActions ?? 1)),
    required_any_tools: input.requiresAction ? [...input.allowedTools] : [],
    ...(typeof input.summary === "string"
      ? input.summary
        ? { summary: input.summary }
        : {}
      : input.summary
        ? { summary_message: structuredClone(input.summary) }
        : {}),
  };
}

/**
 * 负责完整行动接收预检：允许工具、首用 JSON schema、原参数修复、机制请求作用域和领域规则。
 * 输入为同一 World、原请求与外来工具参数；输出为脱离后的合法候选或原结构化拒绝。
 * 每实例只持有原 schema 缓存和不写第二 Tape 校验的 Gateway；schema 与具体 scope 仍按原时点晚读。
 * 本 owner 不消耗库存、提交领域动作或 settle 完成责任；选择／截止窗口由 AI ActionTurn 独立拥有。
 */
import { nobleBodyRequestScope } from "../mechanisms/roles/noble_secret_body/ports";
import { animalRequestScope } from "../mechanisms/roles/animal_dream/ports";
import { fragrantPairRequestScope } from "../mechanisms/roles/fragrant_pair_seer/ports";
import {
  demonWitchRequestTargetCurrent,
  demonWitchRequestCurrent,
  readDemonNativeNightTool,
  readDemonPotionTool,
} from "../mechanisms/roles/demon_hunter/ports";
import {
  demonHunterRequestScope,
  canSubmitDemonHunt,
  demonHunterActorId,
} from "../mechanisms/roles/demon_hunter/ports";
import { readDemonHuntTool } from "../mechanisms/roles/demon_hunter/ports";
import {
  ghostBrideRequestScope,
  weddingSetup,
} from "../mechanisms/roles/ghost_bride/ports";
import { readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import { lonelyGirlRequestScope } from "../mechanisms/roles/lonely_girl/ports";
import { readLonelyGirlTool } from "../mechanisms/roles/lonely_girl/ports";
import { wildChildRequestScope } from "../mechanisms/roles/wild_child/ports";
import { readWildChildTool } from "../mechanisms/roles/wild_child/ports";
import { shapeshifterRequestScope } from "../mechanisms/roles/shapeshifter/ports";
import { thiefRequestScope } from "../mechanisms/roles/thief/ports";
import { readThiefChoice } from "../mechanisms/roles/thief/ports";
import { wallRequestScope } from "../mechanisms/events/wall_notes/ports";
import { z, type ZodType } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { readWallTool } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import {
  DEATH_SHOT_STAGES,
  type ActionRequest,
  type ToolCall,
  type ToolName,
} from "../../core/domain";
import { World } from "../../core/domain/world";
import { ActionValidator } from "./action_validator";
import { ToolGateway } from "./tool_gateway";
import {
  getDefaultToolCallRepairRegistry,
  getDefaultToolValidationRuleRegistry,
  type ToolCallRepairRegistry,
  type ToolValidationRuleRegistry,
} from "../mechanisms";
import {
  getDefaultToolSpecRegistry,
  type ToolSpecRegistry,
} from "../mechanisms/registries/tool_spec_registry";
import { evaluateTurnConstraints, resolveTurnConstraints } from "./turn-constraints";
import type { Locale } from "@ai-werewolf-arena/game-contract";

/** 只描述预检结果，不表示领域已付款或生效；可选回合字段保留原拒绝结构接受集合。 */
export type GameActionValidation =
  | { ok: true; action: ToolCall }
  | {
      ok: false;
      error: string;
      message: string;
      details?: string[];
      expected_turn_id?: string;
      received_turn_id?: unknown;
    };

/**
 * 选择窗口的类型接口只声明原 locale 与预检函数，不提供写方法或领域完成接口。
 * 运行对象仍是原接收器和 World；这是消费契约，不是新的进程隔离或运行权限屏障。
 */
export interface ActionPreflightPort {
  readonly world: { readonly locale: Locale };
  validate(request: ActionRequest, name: string, rawArgs: unknown): GameActionValidation;
}
type Validation = GameActionValidation;

/** 预检只形成候选；实际应用与资源消费仍由引擎和具体机制提交。 */
export class ActionReception {
  private readonly schemas = new Map<ToolName, ZodType>();
  private readonly gateway: ToolGateway;

  constructor(
    readonly world: World,
    private readonly repair: ToolCallRepairRegistry = getDefaultToolCallRepairRegistry(),
    private readonly specs: ToolSpecRegistry = getDefaultToolSpecRegistry(),
    rules: ToolValidationRuleRegistry = getDefaultToolValidationRuleRegistry(),
  ) {
    // 这里仍关闭领域校验的 Tape 记录，避免接收预检制造第二次 validation 操作。
    this.gateway = new ToolGateway(new ActionValidator(rules, false));
  }

  validate(request: ActionRequest, name: string, rawArgs: unknown): Validation {
    const fail = (code: string) => toolFailure(this.world.locale, code);
    if (!request.allowedTools.includes(name as ToolName) || name === "report_bug") {
      return fail("tool_not_allowed_in_this_turn");
    }
    const tool = name as ToolName;
    const spec = this.specs.get(tool);
    if (!spec || rawArgs === null || typeof rawArgs !== "object" || Array.isArray(rawArgs)) {
      return fail("invalid_tool_arguments");
    }
    // 同一工具只在首个合法参数形态的调用建立 schema；建图失败不先写缓存，后续 properties 仍原位读取。
    let schema = this.schemas.get(tool);
    if (!schema) {
      schema = z.fromJSONSchema(spec.parameters);
      this.schemas.set(tool, schema);
    }
    // 保留原数字字符串修复；不把布尔／文本按 truthiness 或 String() 宽转，也不补缺少的必填参数。
    const wallCall = tool === "write_note" ? readWallTool({ name: tool, args: rawArgs }) : null;
    if (tool === "write_note" && !wallCall) return fail(RuleError.WallNoteText);
    const initialChoice = tool === "choose_thief_card" || tool === "choose_shapeshifter_card";
    const thiefSlot = initialChoice ? readThiefChoice(rawArgs) : undefined;
    if (initialChoice && thiefSlot === undefined)
      return fail(
        tool === "choose_thief_card" ? RuleError.ThiefChoice : RuleError.ShapeshifterChoice,
      );
    if (tool === "choose_admired_player" && !readLonelyGirlTool({ name: tool, args: rawArgs }))
      return fail(RuleError.LonelyGirlChoice);
    const wildCall =
      tool === "choose_wild_model" ? readWildChildTool({ name: tool, args: rawArgs }) : null;
    if (tool === "choose_wild_model" && !wildCall) return fail(RuleError.WildChildChoice);
    const weddingTool =
      [
        "choose_bridegroom",
        "choose_wedding_witness",
        "speak_to_partner",
        "wedding_kill_vote",
      ].includes(tool) ||
      (tool === "kill_vote" && weddingSetup(this.world) !== null);
    const weddingCall = weddingTool ? readWeddingTool({ name: tool, args: rawArgs }) : null;
    if (weddingTool && !weddingCall) return fail(RuleError.GhostBrideChoice);
    const demonCall =
      name === "demon_hunt" ? readDemonHuntTool({ name: tool, args: rawArgs }) : null;
    if (
      name === "demon_hunt" &&
      (!demonCall ||
        !canSubmitDemonHunt(
          this.world,
          request.actorId,
          request.phase,
          request.context.day,
          demonHunterRequestScope(this.world, request),
          demonCall,
        ))
    )
      return fail(RuleError.ToolMismatch);
    const demonNative =
      (tool === "check_identity" || tool === "guard") && demonHunterActorId(this.world) !== null;
    const nativeCall = demonNative ? readDemonNativeNightTool({ name: tool, args: rawArgs }) : null;
    if (
      demonNative &&
      (!nativeCall ||
        !demonWitchRequestCurrent(this.world, request) ||
        (nativeCall.args.target_id !== null &&
          !demonWitchRequestTargetCurrent(this.world, request, nativeCall.args.target_id)))
    )
      return fail(RuleError.ToolMismatch);
    const demonWitch = tool === "use_potion" && demonHunterActorId(this.world) !== null;
    const potionCall = demonWitch ? readDemonPotionTool({ name: tool, args: rawArgs }) : null;
    if (
      demonWitch &&
      (!potionCall ||
        !demonWitchRequestTargetCurrent(this.world, request, potionCall.args.target_id))
    )
      return fail(RuleError.ToolMismatch);
    const input = (
      potionCall
        ? potionCall.args
        : demonCall
          ? demonCall.args
          : weddingCall
            ? weddingCall.args
            : wildCall
              ? wildCall.args
              : initialChoice
                ? { slot: thiefSlot }
                : wallCall
                  ? wallCall.args
                  : { ...rawArgs }
    ) as Record<string, unknown>;
    const properties = spec.parameters.properties as
      Record<string, { type?: string | string[] }> | undefined;
    for (const [key, value] of Object.entries(input)) {
      const type = properties?.[key]?.type;
      const numeric =
        type === "number" ||
        type === "integer" ||
        (Array.isArray(type) && (type.includes("number") || type.includes("integer")));
      if (numeric && typeof value === "string" && /^\d+$/.test(value)) input[key] = Number(value);
    }
    const parsed = schema.safeParse(input);
    if (!parsed.success) return fail("invalid_tool_arguments");
    const args = this.repair.coerceArgs(tool, parsed.data as Record<string, unknown>, {
      actorId: request.actorId,
    });
    if (!args || !schema.safeParse(args).success) return fail("invalid_tool_arguments");
    const call = { name: tool, args } as ToolCall;
    const deathStage =
      DEATH_SHOT_STAGES.includes(request.context.stage) ||
      request.context.stage === "last_words" ||
      request.context.stage === "sheriff_badge_choice";
    const deathTool =
      (tool === "choose_badge_successor" &&
        request.context.stage === "sheriff_badge_choice" &&
        request.context.trigger === "badge_handoff") ||
      (tool === "shoot" &&
        DEATH_SHOT_STAGES.includes(request.context.stage) &&
        request.context.trigger === "on_death") ||
      (tool === "speak" &&
        request.context.stage === "last_words" &&
        request.context.trigger === "last_words");
    if (
      deathStage &&
      (!deathTool ||
        !this.world.hasDeathAction(
          request.actorId,
          tool,
          request.phase,
          request.context.day,
          request.context.death_action_id,
          request.context.ability_id,
        ))
    ) {
      return fail(RuleError.DeathActionUnavailable);
    }
    // 机制 scope 按下面原字段顺序逐个读取；不提前缓存请求许可或绕过 Gateway 的提交前规则。
    const checked = this.gateway.validateAndSanitize(this.world, request.actorId, call, {
      phase: request.phase,
      day: request.context.day,
      thiefScope: thiefRequestScope(this.world, request),
      shapeshifterScope: shapeshifterRequestScope(this.world, request),
      lonelyGirlScope: lonelyGirlRequestScope(this.world, request),
      ghostBrideScope: ghostBrideRequestScope(this.world, request),
      demonHunterScope: demonHunterRequestScope(this.world, request),
      nobleBodyScope: nobleBodyRequestScope(this.world, request),
      fragrantPairScope: fragrantPairRequestScope(this.world, request),
      animalScope: animalRequestScope(this.world, request),
      wildChildScope: wildChildRequestScope(this.world, request),
      wallScope: wallRequestScope(this.world, request),
      wallId: request.context.wall_id,
      itemInstanceId: request.context.item_instance_id,
      debateId: request.context.debate_id,
      abilityId: request.context.ability_id,
      actionWindow: request.actionWindow,
      sheriffCandidates: request.context.sheriff_candidates,
      exileCandidates: request.context.exile_candidates,
      badgeCandidates: request.context.badge_candidates,
      allowSelfDestruct:
        request.allowedTools.includes("self_destruct") ||
        request.allowedTools.includes("self_destruct_with_target"),
      duelWindow: request.context.duel_window,
      allowKnightDuel:
        request.context.stage === request.context.duel_window &&
        request.allowedTools.includes("duel"),
      deathActionId: deathTool ? request.context.death_action_id : undefined,
    });
    if (!checked.ok || !checked.sanitizedCall) {
      return toolFailure(
        this.world.locale,
        checked.error ?? "invalid_tool_arguments",
        checked.message,
      );
    }
    const evaluation = evaluateTurnConstraints(
      { validActions: [checked.sanitizedCall] },
      resolveTurnConstraints(request),
      this.world.locale,
    );
    if (!evaluation.ok) {
      return { ...fail("turn_constraints_not_satisfied"), details: evaluation.errors };
    }
    // 已接受的是脱离的候选，不是领域 commit；库存、租约完成和实际效果仍要在原 owner 重验。
    return { ok: true, action: structuredClone(checked.sanitizedCall) };
  }
}

/**
 * 负责按演员生命、角色、可信行动窗口及已注册规则校验工具调用。输入为已清洗调用及校验上下文，输出为原规则结果与配置的校验 trace。
 * 领域预检通过不等于库存付款，本模块不以 schema 接受代替实际资源提交。
 */
import { RuleError, type RuleViolation } from "@ai-werewolf-arena/game-contract";
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { AliveComponent } from "../../core/domain/components/alive";
import { COMPONENT } from "../../core/domain/components/names";
import { RoleComponent } from "../../core/domain/components/role";
import {
  ActionWindow,
  EntityId,
  Phase,
  ToolCall,
  ToolValidationResult,
} from "../../core/domain/model";
import { getDefaultToolValidationRuleRegistry, ToolValidationRuleRegistry } from "../mechanisms";
import { safeRecordLogicOp } from "../../recording/session_recorder";
import { World } from "../../core/domain/world";

/**
 * 动作校验上下文。
 */
export interface ValidationContext {
  /** 有事务归属的 controller 只在实际提交后记录校验。 */
  deferOperation?: boolean;
  day?: number;
  thiefScope?: object;
  shapeshifterScope?: object;
  wildChildScope?: object;
  lonelyGirlScope?: object;
  ghostBrideScope?: object;
  demonHunterScope?: object;
  nobleBodyScope?: object;
  fragrantPairScope?: object;
  animalScope?: object;
  wallScope?: object;
  wallId?: string;
  itemInstanceId?: string;
  debateId?: string;
  abilityId?: string;
  phase: Phase;
  actionWindow?: ActionWindow;
  allowSelfDestruct?: boolean;
  duelWindow?: import("../../core/domain/identity").KnightDuelWindow;
  allowKnightDuel?: boolean;
  deathActionId?: number;
  sheriffCandidates?: readonly EntityId[];
  badgeCandidates?: readonly EntityId[];
  exileCandidates?: readonly EntityId[];
}

/**
 * ActionValidator 是“规则防线”。
 * 所有模型工具调用在落地前都必须通过这里，非法动作统一返回错误并要求重试。
 */
export class ActionValidator {
  constructor(
    private readonly ruleRegistry: ToolValidationRuleRegistry = getDefaultToolValidationRuleRegistry(),
    private readonly recordOperations = true,
  ) {}

  validate<T extends ToolCall>(
    world: World,
    actorId: EntityId,
    toolCall: T,
    context: ValidationContext,
  ): ToolValidationResult<T> {
    const reject = (violation: RuleViolation): ToolValidationResult<T> => {
      if (this.recordOperations && context.deferOperation !== true)
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId,
          phase: context.phase,
          status: "rejected",
          reason: violation.code,
          input: {
            tool: toolCall.name,
            args: (toolCall as any).args ?? {},
            action_window: context.actionWindow,
          },
        });
      return toolFailure(world.locale, violation.code, violation.message);
    };
    const accept = (): ToolValidationResult<T> => {
      if (this.recordOperations && context.deferOperation !== true)
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId,
          phase: context.phase,
          status: "ok",
          input: {
            tool: toolCall.name,
            args: (toolCall as any).args ?? {},
            action_window: context.actionWindow,
          },
        });
      return {
        ok: true,
        sanitizedCall: toolCall,
      };
    };

    const role = world.getComponent(actorId, COMPONENT.Role);
    const alive = world.getComponent(actorId, COMPONENT.Alive);

    if (!role || !alive) {
      return reject({ code: RuleError.ActorMissing });
    }

    const allowDeadAction = world.hasDeathAction(
      actorId,
      toolCall.name,
      context.phase,
      context.day,
      context.deathActionId,
      context.abilityId,
    );
    if (context.deathActionId !== undefined && (alive.alive || !allowDeadAction)) {
      return reject({ code: RuleError.DeathActionUnavailable });
    }
    if (!alive.alive && !allowDeadAction) {
      return reject({ code: RuleError.ActorDead });
    }
    if (toolCall.name === "choose_badge_successor" && (alive.alive || !allowDeadAction))
      return reject({ code: RuleError.DeathActionUnavailable });
    if (toolCall.name === "shoot" && (alive.alive || !allowDeadAction)) {
      return reject({ code: RuleError.ShootUnavailable });
    }

    const error = this.ruleRegistry.validate({
      world,
      actorId,
      role,
      toolCall,
      phase: context.phase,
      day: context.day,
      thiefScope: context.thiefScope,
      shapeshifterScope: context.shapeshifterScope,
      wildChildScope: context.wildChildScope,
      lonelyGirlScope: context.lonelyGirlScope,
      ghostBrideScope: context.ghostBrideScope,
      demonHunterScope: context.demonHunterScope,
      nobleBodyScope: context.nobleBodyScope,
      fragrantPairScope: context.fragrantPairScope,
      animalScope: context.animalScope,
      wallScope: context.wallScope,
      wallId: context.wallId,
      itemInstanceId: context.itemInstanceId,
      debateId: context.debateId,
      abilityId: context.abilityId,
      actionWindow: context.actionWindow,
      allowSelfDestruct: context.allowSelfDestruct,
      duelWindow: context.duelWindow,
      allowKnightDuel: context.allowKnightDuel,
      sheriffCandidates: context.sheriffCandidates,
      exileCandidates: context.exileCandidates,
      badgeCandidates: context.badgeCandidates,
    });
    if (error) {
      return reject(error);
    }

    return accept();
  }
}

/**
 * 负责行动提交前的发言文字清洗与领域预检；输入原 World、行动者、调用和上下文，输出原校验结果。
 * JSON Schema 由 ActionReception 持有；本入口按原清洗 → validator 顺序，不消费库存或提交动作。
 * 实例保存原校验器引用，两种发言分支产生浅副本，其它调用保原引用；不是快照、冻结或新许可。
 * getter、清洗与校验异常原样传播，不统一吞错、补偿或保证任意输入都能得到结构化拒绝。
 */
import { sanitizeSpeechText } from "../../utils/speech_text";
import { EntityId, ToolCall, ToolValidationResult } from "../../core/domain/model";
import { World } from "../../core/domain/world";
import { ActionValidator, type ValidationContext } from "./action_validator";

/**
 * 网关只形成清洗后的领域校验候选；预检通过不代表付款、请求完成或实际效果已发生。
 */
export class ToolGateway {
  private readonly validator: ActionValidator;

  constructor(validator: ActionValidator = new ActionValidator()) {
    this.validator = validator;
  }

  /** 先完成清洗再读取并调用原 validator；清洗抛错时不进入校验器，不提前读取 World 或上下文字段。 */
  validateAndSanitize<T extends ToolCall>(
    world: World,
    actorId: EntityId,
    toolCall: T,
    context: ValidationContext,
  ): ToolValidationResult<T> {
    const sanitizedCall = this.sanitize(toolCall);
    return this.validator.validate(world, actorId, sanitizedCall, context);
  }

  /** 按原 name 分支读取；仅两种发言造新外层／args 对象，不做其它工具的 schema 或权限校验。 */
  private sanitize<T extends ToolCall>(call: T): T {
    if (call.name === "speak") {
      const raw = call.args.text;
      // 仅清除开头的既有保留前缀并 trim；不删内嵌文字，也不把清洗当作身份认证。
      const text = sanitizeSpeechText(raw);
      // 清洗成功后再按原 spread 次序读取调用和 args；仅浅复制，原嵌套引用与 getter 轨迹保持。
      return {
        ...call,
        args: {
          ...call.args,
          text,
        },
      } as T;
    }
    if (call.name === "speak_to_wolves") {
      const raw = call.args.text;
      const text = sanitizeSpeechText(raw);
      return {
        ...call,
        args: {
          ...call.args,
          text,
          // end_chat 在原两个 spread 与 text 之后才读取，保 Boolean truthiness，不做严格布尔校验。
          end_chat: Boolean(call.args.end_chat),
        },
      } as T;
    }
    // 非发言工具不复制、不归一化参数；领域校验仍在上层的原 validator 调用点执行。
    return call;
  }
}

/**
 * 负责原回合约束的数据解析、完成条件检查和是否允许回退的只读政策。
 * 输入为原请求、有效行动列表及 locale；输出保留原 min／max、必需工具、摘要与错误顺序。
 * 摘要文本和 MessageRef 的缺省规则、所需工具数组身份及消息克隆保持原语义；不读 World、
 * 不关闭请求、消耗库存或执行 Agent，提示文案的组织仍属于 AI 玩家层。
 */
import { text, type MessageRef, type Locale } from "@ai-werewolf-arena/game-text";
import type { ActionRequest, ToolCall, ToolName } from "../../core/domain";

export interface ResolvedTurnConstraints {
  minValidActions: number;
  maxValidActions: number;
  requiredAnyTools: ToolName[];
  summary?: string;
  summaryMessage?: MessageRef;
}

export interface TurnConstraintState {
  validActions: ToolCall[];
}

export interface TurnConstraintEvaluation {
  ok: boolean;
  errors: string[];
}

/** 传输可按原策略重试；强制选择失败或显式禁止回退时，回退不能代补该行动。 */
export function allowsActionFallback(request: ActionRequest): boolean {
  return (
    request.context.action_failure_policy !== "error" && request.context.allow_fallback !== false
  );
}

/** 在原读取顺序解析引擎约束，保留摘要缺省、原数组引用和消息副本；不产生行动许可。 */
export function resolveTurnConstraints(request: ActionRequest): ResolvedTurnConstraints {
  const constraints = request.context.turn_constraints;
  const minValidActions = Math.max(0, Math.floor(constraints?.min_valid_actions ?? 0));
  const maxValidActions = Math.max(
    minValidActions,
    Math.floor(constraints?.max_valid_actions ?? 1),
  );
  const summary = constraints?.summary;
  return {
    minValidActions,
    maxValidActions,
    requiredAnyTools: constraints?.required_any_tools ?? [],
    ...(summary !== undefined ? { summary } : {}),
    ...(constraints?.summary_message
      ? { summaryMessage: structuredClone(constraints.summary_message) }
      : {}),
  };
}

/**
 * 校验当前回合是否满足结束条件。
 */
export function evaluateTurnConstraints(
  state: TurnConstraintState,
  constraints: ResolvedTurnConstraints,
  locale: Locale = "zh-CN",
): TurnConstraintEvaluation {
  const errors: string[] = [];
  if (state.validActions.length < constraints.minValidActions) {
    errors.push(text(locale, "turn.minimum", { count: constraints.minValidActions }));
  }
  if (state.validActions.length > constraints.maxValidActions) {
    errors.push(text(locale, "turn.maximum", { count: constraints.maxValidActions }));
  }
  if (constraints.requiredAnyTools.length > 0) {
    const used = new Set(state.validActions.map((action) => action.name));
    const hit = constraints.requiredAnyTools.some((tool) => used.has(tool));
    if (!hit) {
      errors.push(
        text(locale, "turn.required_tools", { tools: constraints.requiredAnyTools.join(", ") }),
      );
    }
  }
  return {
    ok: errors.length === 0,
    errors,
  };
}

/**
 * 负责适配既有 Agent 布尔可见性入口和显式自定义规则。输入为原 World、typed GameEvent 与玩家编号；
 * 输出为既有家族受众政策的布尔结果，不返回库存、请求许可或玩家字段投影。
 * 事件流授权消费 prepare 的一次家族事实，独立旧布尔入口仍按原时点读取 trusted 输入。
 * Node hostile ingress 仍归事件流入口；本模块不新增 unknown 零 trap 承诺。
 * 在原恶魔分支才读取 actor 身份；在原自定义分支才取规则并调用原 receiver 与参数。
 * 历史 audience 不随当前阵营补发或撤回；这里不裁剪第二份副本、不付款，也不授予行动写权限。
 */
import type { EntityId, GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../core/domain/world";
import { demonHunterActorId } from "../roles/demon_hunter/authority";
import {
  canViewAgentEvent,
  canViewPreparedAgentEvent,
} from "../../observation/agent-event-projection";
import type { PreparedAgentEvent } from "../../observation/agent-event-facts";

type AgentEventVisibilityRule = (world: World, event: GameEvent, actorId: EntityId) => boolean;
const DEFAULT_RULES: Record<string, AgentEventVisibilityRule> = {};

/** 默认未知事件不可见；自定义规则是已有显式 trusted 扩展，并非新玩家权限。 */
export class AgentEventVisibilityRegistry {
  constructor(private readonly rules: Record<string, AgentEventVisibilityRule> = DEFAULT_RULES) {}

  canView(world: World, event: GameEvent, actorId: EntityId): boolean {
    return canViewAgentEvent(event, actorId, {
      demonHunterActorId() {
        return demonHunterActorId(world);
      },
      custom: (event, actorId) => {
        const custom = this.rules[event.type];
        if (custom) return { handled: true, visible: custom(world, event, actorId) };
        return { handled: false };
      },
    });
  }

  /** 只消费已经解析的 Node 副本；自定义规则仍收到原副本而不是另一个字段对象。 */
  canViewPrepared(world: World, prepared: PreparedAgentEvent, actorId: EntityId): boolean {
    return canViewPreparedAgentEvent(prepared, actorId, {
      demonHunterActorId() {
        return demonHunterActorId(world);
      },
      custom: (event, actorId) => {
        // schema 规则按同一次快照的类型查找；可信回调仍收到原 source 副本。
        const custom = this.rules[prepared.projectionEvent.type];
        if (custom) return { handled: true, visible: custom(world, event, actorId) };
        return { handled: false };
      },
    });
  }
}

let defaultRegistry: AgentEventVisibilityRegistry | null = null;

export function getDefaultAgentEventVisibilityRegistry(): AgentEventVisibilityRegistry {
  if (!defaultRegistry) defaultRegistry = new AgentEventVisibilityRegistry();
  return defaultRegistry;
}

/**
 * 负责按当前角色和狼队权限核对广播受众。输入为 World 与受众身份；输出为狼队／角色可见性谓词。这些谓词只裁剪信息，不赋予玩家全知状态或行动权限。
 */
/** 文件说明：封装广播可见性判定逻辑。 */
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { Camp, EntityId, Role } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";

/** 广播受众身份视图。 */
export interface AudienceIdentity {
  role?: string;
  camp?: Camp | string;
}

/** 广播可见性判定注册器。 */
export class VisibilityRegistry {
  private readonly roleCatalog = getDefaultRoleCatalog();

  isWolfPlayer(world: World, actorId: EntityId): boolean {
    const roleComp = world.getComponent(actorId, COMPONENT.Role);
    return !!roleComp && world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Wolf;
  }

  isWolfAudience(identity: AudienceIdentity): boolean {
    if (identity.camp === Camp.Wolf || identity.camp === Camp.Wolf.toString()) {
      return true;
    }
    if (typeof identity.role !== "string") {
      return false;
    }
    if (!this.isRole(identity.role)) {
      return false;
    }
    return this.roleCatalog.getCamp(identity.role) === Camp.Wolf;
  }

  private isRole(role: string): role is Role {
    return (Object.values(Role) as string[]).includes(role);
  }
}

let defaultRegistry: VisibilityRegistry | null = null;

/** 获取默认广播可见性注册器实例。 */
export function getDefaultVisibilityRegistry(): VisibilityRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new VisibilityRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责查询放逐、投票和警长的公开参与资格。输入为玩家 ID、当前生命／投票权及角色目录；
 * 输出为原资格布尔值，放逐投票再按原顺序查询辩论封票。不提交票、修改票重、泄露秘密免疫或执行出局。
 */
import { COMPONENT, type RoleComponent, type World, type EntityId } from "../../../core/domain";
import { type RoleCatalog } from "../roles/catalog";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";

import { debateVoteBlocked } from "../roles/debater/authority";

export function canVoteExile(
  world: World,
  id: EntityId,
  day: number | undefined,
  catalog?: RoleCatalog,
): boolean {
  return canVote(world, id, catalog) && !debateVoteBlocked(world, id, day);
}

/** 只查公开放逐资格，不揭示秘密免疫或另一玩家的私态。 */
export function canBeExiled(
  world: World,
  id: EntityId,
  catalog: RoleCatalog = getDefaultRoleCatalog(),
): boolean {
  const role = world.getComponent(id, COMPONENT.Role);
  return (
    world.getComponent(id, COMPONENT.Alive)?.alive === true &&
    role !== undefined &&
    catalog.participation(role).canBeExiled
  );
}

export function canVote(
  world: World,
  id: EntityId,
  catalog: RoleCatalog = getDefaultRoleCatalog(),
): boolean {
  const role = world.getComponent(id, COMPONENT.Role);
  return (
    world.getComponent(id, COMPONENT.Alive)?.alive === true &&
    role !== undefined &&
    catalog.participation(role).canVote &&
    world.getComponent(id, COMPONENT.VotingRight)?.canVote === true
  );
}

export function canBeSheriff(
  world: World,
  id: EntityId,
  catalog: RoleCatalog = getDefaultRoleCatalog(),
): boolean {
  const role = world.getComponent(id, COMPONENT.Role);
  return (
    canVote(world, id, catalog) && role !== undefined && catalog.participation(role).canBeSheriff
  );
}

/**
 * 提供通用工具的原校验集合：匿名墙检查作者／窗口，辩论检查参与者／阶段，放逐票检查票权与候选。输入为网关上下文和工具参数；返回既有 RuleError 或 null，不在校验中提交资源或阶段。
 */
import { readWallTool } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import { authorizedWallAuthor } from "../events/wall_notes/authority";
import { prohibitsLoversVote } from "../roles/cupid/relation";
import { RuleError } from "@ai-werewolf-arena/game-contract";
/** 文件说明：定义通用工具的校验规则。 */
import { ToolRuleMap } from "../validation/contracts";
import { debateAuthority } from "../roles/debater/authority";
import { sameOriginalParticipant as sameDebateParticipant } from "../../../core/domain/original-participant";
import { Phase } from "../../../core/domain";
import { canBeExiled, canVoteExile } from "./participation";

/** 通用工具校验规则集合。 */
export const COMMON_VALIDATION_RULES: ToolRuleMap = {
  write_note: ({ world, actorId, day, phase, toolCall, wallScope, wallId, itemInstanceId }) => {
    if (
      day !== 1 ||
      phase !== Phase.Voting ||
      !authorizedWallAuthor(world, actorId, wallId, itemInstanceId, wallScope)
    )
      return { code: RuleError.WallNoteUnavailable };
    return readWallTool(toolCall) ? null : { code: RuleError.WallNoteText };
  },
  debate_vote: ({ world, actorId, day, phase, toolCall, debateId }) => {
    const a = debateAuthority(world, debateId),
      actor = a?.participants.get(actorId);
    if (toolCall.name !== "debate_vote") return { code: RuleError.ToolMismatch };
    if (
      !a ||
      !actor ||
      a.stage !== "ballot" ||
      a.day !== day ||
      phase !== Phase.Day ||
      !sameDebateParticipant(world, actor)
    )
      return { code: RuleError.DebateUnavailable };
    if (
      toolCall.args.support !== true &&
      toolCall.args.support !== false &&
      toolCall.args.support !== null
    )
      return { code: RuleError.DebateBallot };
    return null;
  },
  report_bug: ({ toolCall }) => {
    if (toolCall.name !== "report_bug") {
      return { code: RuleError.ToolMismatch };
    }
    const { category, severity, message } = toolCall.args;
    const categorySet = new Set(["flow", "rule", "state", "logging", "other"]);
    const severitySet = new Set(["low", "medium", "high", "critical"]);
    if (!categorySet.has(String(category))) {
      return { code: RuleError.ReportCategory };
    }
    if (!severitySet.has(String(severity))) {
      return { code: RuleError.ReportSeverity };
    }
    if (typeof message !== "string" || message.trim().length === 0) {
      return { code: RuleError.ReportMessageEmpty };
    }
    if (message.length > 300) {
      return { code: RuleError.ReportMessageLong };
    }
    return null;
  },
  speak: () => null,
  vote: ({ world, actorId, day, toolCall, roleCatalog, exileCandidates }) => {
    if (toolCall.name !== "vote") {
      return { code: RuleError.ToolMismatch };
    }
    if (exileCandidates?.includes(actorId)) return { code: RuleError.PkVoteEligibility };
    if (
      !toolCall.args.abstain &&
      exileCandidates &&
      !exileCandidates.includes(toolCall.args.target_id!)
    )
      return { code: RuleError.PkVoteTarget };
    if (!canVoteExile(world, actorId, day, roleCatalog)) {
      return { code: RuleError.VoteRight };
    }
    if (toolCall.args.abstain) {
      return null;
    }
    if (toolCall.args.target_id === null) {
      return { code: RuleError.VoteTarget };
    }
    if (prohibitsLoversVote(world, actorId, toolCall.args.target_id))
      return { code: RuleError.LoversVote };
    if (!canBeExiled(world, toolCall.args.target_id, roleCatalog)) {
      return { code: RuleError.VoteTarget };
    }
    return null;
  },
};

/**
 * 负责板子配置规范化器的数据与调用契约；输入和输出都是原 BoardConfig 结构。
 * 具体机制拥有删改规则，registry 只按顺序串接结果；返回值可以保原引用，也可以是新对象。
 * 该接口不承诺纯函数、深复制、冻结或回滚，不能把规范化当作完整配置校验或运行权限。
 */
import { BoardConfig } from "../../../core/domain/model";

/** 同一 normalizer 对象作为方法 receiver；输入是上一规范化器实际返回的配置。 */
export interface ConfigNormalizer {
  /** 机制提供的标识；当前 registry 不按 id 去重、排序或授予写权。 */
  id: string;
  /** 方法可读写原配置或抛错；失败传播且后续规范化器不再运行，此前副作用不回滚。 */
  normalize(config: BoardConfig): BoardConfig;
}

/**
 * 负责有序串接板子配置规范化；输入原配置与规范化器数组，输出最后一个实际返回值。
 * 默认依次执行女巫、警长、自爆规则；每次调用保 normalizer 方法 receiver 和前一步配置引用。
 * 抛错即停止后续处理，已发生的读取／写入不回滚；此 registry 不替具体机制重写规则或校验权限。
 */
import { BoardConfig } from "../../../core/domain/model";
import { ConfigNormalizer } from "./contracts";
import { SHERIFF_CONFIG_NORMALIZER } from "../sheriff/config_normalizer";
import { WITCH_CONFIG_NORMALIZER } from "../roles/witch/config_normalizer";
import { SELF_DESTRUCT_CONFIG_NORMALIZER } from "../self_destruct/config_normalizer";

/** 顺序固定为 Witch → Sheriff → SelfDestruct；规则对象是原模块引用，不在此复制其字段。 */
const DEFAULT_NORMALIZERS: ConfigNormalizer[] = [
  WITCH_CONFIG_NORMALIZER,
  SHERIFF_CONFIG_NORMALIZER,
  SELF_DESTRUCT_CONFIG_NORMALIZER,
];

/** 实例保传入数组同引用；readonly 仅限制字段重新赋值，不冻结数组或处理器。 */
export class ConfigNormalizerRegistry {
  constructor(private readonly normalizers: ConfigNormalizer[] = DEFAULT_NORMALIZERS) {}

  /**
   * 原 config 作为 reduce 初值；空数组原样返回。每次读取 normalize 后以该对象为 receiver 调用，
   * 参数是前一实际结果；getter／处理函数抛错原样传播，不运行后续项或做补偿。
   */
  normalize(config: BoardConfig): BoardConfig {
    return this.normalizers.reduce((current, normalizer) => normalizer.normalize(current), config);
  }
}

let defaultRegistry: ConfigNormalizerRegistry | null = null;

/** 首次调用才创建并缓存默认 registry；获取实例不执行规范化，失败时不会预先写入默认缓存。 */
export function getDefaultConfigNormalizerRegistry(): ConfigNormalizerRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ConfigNormalizerRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责定义机制工具、阶段提示和钩子的公共规格。输入为贡献方声明的工具名、参数 schema 与提示键；
 * 输出为装配方消费的类型约束。参数规格只描述校验，提示不授予库存／回合许可，本模块不运行工具或注册贡献。
 */
import type { MessageKey } from "@ai-werewolf-arena/game-text";
/** 文件说明：机制层公共规格类型定义。 */
import { ToolName } from "../../core/domain/model";

/** 工具规格定义。 */
export interface ToolSpec {
  name: ToolName;
  /** 只用于校验的 JSON Schema；玩家说明由共享本地化提示提供，不写进 schema。 */
  parameters: Record<string, unknown>;
  argHint: string;
  userPromptHint?: string;
  userPromptHintKey?: MessageKey;
}

/** 阶段提示词匹配规则。 */
export interface StageDirectiveRule {
  match: (allowedTools: ToolName[]) => boolean;
  text: string;
  messageKey?: MessageKey;
}

/** 阶段规格定义。 */
export interface StageSpec {
  id: string;
  phase: string;
  description?: string;
}

/** 钩子规格定义。 */
export interface HookSpec {
  id: string;
  event: "voted_out" | "death";
  description?: string;
}

/**
 * 负责持有匿名墙、原作者库存与请求绑定，按窗口和作者身份提交行动及派生别名。
 * 输入为原 World、作者与请求；输出为墙 scope、作者原记录及投影，写权只覆盖墙／作者库存和本地绑定。
 * 请求预算与已观察撤权归独立 RequestLease 实例；本模块仍晚复验墙、原参与者和 note 同引用。
 * 不变量：原墙、参与者、note／source 必须保持捕获关联，投影不授新权限。
 * 关闭先撤 active 权，再尝试标记存储过期；存储损坏不恢复权限，失败保留已发生的写入前缀。
 */
import { RequestLease } from "../../../../core/domain/request-lease";
import { readWallNoteData } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import {
  COMPONENT,
  Role,
  Phase,
  type World,
  type ActionRequest,
  type WallNoteComponent,
} from "../../../../core/domain";
import {
  captureOriginalParticipant as captureDebateParticipant,
  sameOriginalParticipant as sameDebateParticipant,
  type OriginalParticipant as DebateParticipant,
} from "../../../../core/domain/original-participant";
export const WALL_ROLES: readonly Role[] = [
  Role.Wolf,
  Role.Villager,
  Role.Seer,
  Role.Witch,
  Role.Hunter,
  Role.Guard,
  Role.Idiot,
];
export function supportsWallRoles(roles: readonly Role[]): boolean {
  return roles.every((role) => WALL_ROLES.includes(role));
}
/** 捕获原参与者与 note/source 同引用，并另持本地 remaining／closed；投影不会补回作者资格。 */
export interface WallAuthor {
  id: number;
  participant: DebateParticipant;
  note: WallNoteComponent;
  source: WallNoteComponent["source"];
  instanceId: string;
  remaining: 0 | 1;
  closed: boolean;
}
export interface WallAuthority {
  token: string;
  authors: Map<number, WallAuthor>;
  isCurrent: () => boolean;
}
const active = new WeakMap<World, WallAuthority>();
const commits = new WeakSet<World>();
const owned = new WeakMap<World, Map<number, WallAuthor>>();
/** 本实例持有请求及预算／关闭元数据；原 active/author/库存表仍归本 authority，入口不提前核阶段或当前作者。 */
const requestLease = RequestLease.item<World, WallAuthority, WallAuthor>(
  {
    active: (world) => active.get(world),
    authors: (scope) => scope.authors,
    token: (scope) => scope.token,
    instanceId: (author) => author.instanceId,
    phase: () => Phase.Voting,
    stage: () => "wall_notes",
    current: (world, scope, author) => sameWallAuthor(world, scope, author),
  },
  10,
);
export function bindWallRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function wallRequestScope(world: World, request: ActionRequest): WallAuthority | undefined {
  return requestLease.scope(world, request);
}
/** 每个作者 request 打开自己的完成身份，不以共享墙 scope 结算其他作者。 */
export function openWallRequestDelivery(world: World, request: ActionRequest) {
  return requestLease.openDelivery(world, request);
}
export function hasActiveWall(world: World): boolean {
  return active.has(world);
}
export function hasWallCommit(world: World): boolean {
  return commits.has(world);
}
export function openWall(world: World, isCurrent: () => boolean): WallAuthority {
  if (hasActiveWall(world)) throw new Error("wall_window_reentry");
  if (hasWallCommit(world)) throw new Error("wall_already_committed");
  commits.add(world);
  const a: WallAuthority = { token: "wall:1", authors: new Map(), isCurrent };
  active.set(world, a);
  return a;
}
export function grantWallNote(world: World, a: WallAuthority, id: number): WallAuthor | null {
  const participant = captureDebateParticipant(world, id);
  if (!participant) return null;
  const source: WallNoteComponent["source"] = {
    kind: "wall_event",
    eventId: "awa_wall_notes_v1",
    day: 1,
  };
  const note: WallNoteComponent = {
    instanceId: `wall:1:${id}`,
    source,
    remaining: 1,
    expired: false,
  };
  const author: WallAuthor = {
    id,
    participant,
    note,
    source,
    instanceId: note.instanceId,
    remaining: 1,
    closed: false,
  };
  world.addComponent(id, COMPONENT.WallNote, note);
  a.authors.set(id, author);
  owned.set(world, a.authors);
  return author;
}
export function sameWallAuthor(world: World, a: WallAuthority, author: WallAuthor): boolean {
  const n = author.note,
    data = readWallNoteData(n),
    source = Object.getOwnPropertyDescriptor(n, "source");
  const writable = ["remaining", "expired"].every((key) => {
    const field = Object.getOwnPropertyDescriptor(n, key);
    return field && Object.hasOwn(field, "value") && field.writable === true;
  });
  return (
    writable &&
    !!data &&
    active.get(world) === a &&
    a.isCurrent() &&
    sameDebateParticipant(world, author.participant) &&
    world.getComponent(author.id, COMPONENT.WallNote) === n &&
    source?.value === author.source &&
    data.instanceId === author.instanceId &&
    data.remaining === author.remaining &&
    data.expired === false
  );
}

export function authorizedWallAuthor(
  world: World,
  id: number,
  token: string | undefined,
  instanceId: string | undefined,
  scope: object | undefined,
): WallAuthor | null {
  const a = active.get(world),
    author = a?.authors.get(id);
  return a &&
    a === scope &&
    author &&
    a.token === token &&
    author.instanceId === instanceId &&
    author.remaining === 1 &&
    sameWallAuthor(world, a, author)
    ? author
    : null;
}
export function closeWall(world: World, a: WallAuthority): void {
  if (active.get(world) !== a) return;
  active.delete(world);
  for (const author of a.authors.values()) {
    author.closed = true;
    const field = Object.getOwnPropertyDescriptor(author.note, "expired");
    if (field && Object.hasOwn(field, "value") && field.writable)
      try {
        Object.defineProperty(author.note, "expired", { ...field, value: true });
      } catch {
        /* active 已先撤回；存储损坏或过期字段无法写入不会恢复运行权限。 */
      }
  }
}
export function projectWallNote(
  world: World,
  id: number,
): (WallNoteComponent & { effectiveRemaining: 0 | 1 }) | undefined {
  const a = active.get(world),
    author = a?.authors.get(id);
  const n = world.getComponent(id, COMPONENT.WallNote);
  const owner = owned.get(world)?.get(id);
  if (!owner || owner.note !== n) return;
  const data = readWallNoteData(n),
    source = n && Object.getOwnPropertyDescriptor(n, "source");
  if (
    !data ||
    source?.value !== owner.source ||
    data.instanceId !== owner.instanceId ||
    data.remaining !== owner.remaining
  )
    return;
  return {
    ...data,
    expired: owned.get(world)!.get(id)!.closed || data.expired,
    effectiveRemaining: a && author && sameWallAuthor(world, a, author) ? author.remaining : 0,
  };
}

/**
 * 开启已配置的匿名墙机会并收集原作者行动。输入为只读政策、World、Provider 及具名 RNG 工厂；输出为墙事实与窗口完成，库存与领域窗口关闭仍归 authority，请求完成由本窗口在付款后驱动；不改规则或取得其他能力。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Phase,
  type World,
  type ActionProvider,
  type GameEvent,
  type ToolCall,
} from "../../../../core/domain";
import { shuffled, type RandomSource } from "../../../../core/domain/random";
import { readWallTool } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import type { RequestLeaseTurn } from "../../../../core/domain/request-lease";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import { ToolGateway } from "../../../gateway/tool_gateway";
import {
  openWall,
  openWallRequestDelivery,
  closeWall,
  grantWallNote,
  sameWallAuthor,
  hasActiveWall,
  hasWallCommit,
  type WallAuthor,
} from "./authority";
export class WallNotesWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
    random: () => RandomSource,
  ): Promise<void> {
    if (hasActiveWall(this.world)) throw new Error("wall_window_reentry");
    if (
      config.events?.pack !== "awa_wall_notes_once_v1" ||
      day !== 1 ||
      hasWallCommit(this.world) ||
      !isCurrent()
    )
      return;
    const pack = config.events;
    const windowCurrent = () =>
      isCurrent() && config.events === pack && pack.pack === "awa_wall_notes_once_v1";
    const a = openWall(this.world, windowCurrent);
    const cancel = () => {
      if (isCurrent())
        this.events.push({
          timestamp: Date.now(),
          type: "wall_notes_canceled",
          payload: { day: 1, eventId: "awa_wall_notes_v1", reason: "scope_changed" },
        });
    };
    const change = (
      author: WallAuthor,
      operation: "granted" | "accepted" | "rejected" | "revoked" | "expired",
      text?: string,
    ) =>
      this.events.push({
        timestamp: Date.now(),
        type: "wall_note_changed",
        payload: {
          actorId: author.id,
          day: 1,
          eventId: "awa_wall_notes_v1",
          itemId: "anonymous_note",
          instanceId: author.instanceId,
          operation,
          remaining: author.remaining,
          expired: operation === "expired",
          ...(operation === "accepted" ? { text: text! } : {}),
        },
      });
    const base = { day: 1 as const, eventId: "awa_wall_notes_v1" as const };
    const deliveries: RequestLeaseTurn[] = [];
    let failed = false;
    try {
      this.events.push({ timestamp: Date.now(), type: "wall_notes_started", payload: base });
      const authors = this.world
        .getAliveEntityIds()
        .sort((x, y) => x - y)
        .flatMap((id) => {
          const author = grantWallNote(this.world, a, id);
          if (!author) return [];
          change(author, "granted");
          return [author];
        });
      const calls = authors.map((author) => {
        const request = requests.create({
          actorId: author.id,
          phase: Phase.Voting,
          allowedTools: ["write_note"],
          stage: "wall_notes",
          requiresAction: false,
          summary: { key: "request.summary.wall_notes" },
          context: { wall_id: a.token, item_instance_id: author.instanceId, allow_fallback: false },
        });
        // 每个原 request 各开完成身份；部分 calls 构造失败时已打开者也须在 finally 关闭。
        const delivery = openWallRequestDelivery(this.world, request);
        if (delivery) deliveries.push(delivery);
        return { author, request, delivery };
      });
      const results = await Promise.allSettled(
        calls.map(({ author, request, delivery }) =>
          sameWallAuthor(this.world, a, author) && delivery?.current() === true
            ? Promise.resolve().then(() =>
                sameWallAuthor(this.world, a, author) && delivery?.current() === true ? provider.getAction(request) : null,
              )
            : Promise.resolve(null),
        ),
      );
      const failure = results.find((result) => result.status === "rejected");
      if (failure?.status === "rejected") throw failure.reason;
      if (!windowCurrent()) {
        cancel();
        return;
      }
      const accepted: Array<{ author: WallAuthor; text: string }> = [];
      for (let i = 0; i < calls.length; i++) {
        const { author, delivery } = calls[i],
          result = results[i];
        if (!sameWallAuthor(this.world, a, author) || delivery?.current() !== true) {
          change(author, "revoked");
          continue;
        }
        const call = result.status === "fulfilled" ? readWallTool(result.value) : null;
        if (!call) {
          if (result.status === "fulfilled" && result.value !== null) change(author, "rejected");
          continue;
        }
        const valid = this.gateway.validateAndSanitize(this.world, author.id, call, {
          phase: Phase.Voting,
          day: 1,
          wallScope: a,
          wallId: a.token,
          itemInstanceId: author.instanceId,
        });
        if (!sameWallAuthor(this.world, a, author) || delivery?.current() !== true) {
          change(author, "revoked");
          continue;
        }
        if (!valid.ok) {
          change(author, "rejected");
          continue;
        }
        author.remaining = 0;
        author.note.remaining = 0;
        // 两个库存写均成功才付款完成；后续 accepted 事实／收集失败不重记 false。
        delivery.complete();
        change(author, "accepted", call.args.text);
        accepted.push({ author, text: call.args.text });
      }
      if (!windowCurrent()) {
        cancel();
        return;
      }
      const current = accepted.filter((row) => {
        if (sameWallAuthor(this.world, a, row.author)) return true;
        change(row.author, "revoked");
        return false;
      });
      const ordered = current.sort((x, y) =>
        x.text < y.text ? -1 : x.text > y.text ? 1 : x.author.id - y.author.id,
      );
      const final = shuffled(ordered, random());
      if (!windowCurrent() || final.some((row) => !sameWallAuthor(this.world, a, row.author))) {
        cancel();
        return;
      }
      this.events.push(
        {
          timestamp: Date.now(),
          type: "wall_note_order_recorded",
          payload: {
            ...base,
            rows: final.map(({ author, text }, rank) => ({
              actorId: author.id,
              instanceId: author.instanceId,
              text,
              rank,
            })),
          },
        },
        {
          timestamp: Date.now(),
          type: "wall_notes_published",
          payload: { ...base, texts: final.map((row) => row.text) },
        },
      );
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      try {
        closeWall(this.world, a);
        for (const author of a.authors.values()) change(author, "expired");
      } catch (error) {
        failed = true;
        throw error;
      } finally {
        // 局部关闭全体未完成作者；一人的通知抛错不能让其他 turn 继续开放，也不覆盖原 cleanup 错。
        let notificationFailed = false, notificationError: unknown;
        for (const delivery of deliveries) {
          try { delivery.close(); }
          catch (error) {
            if (!notificationFailed) { notificationFailed = true; notificationError = error; }
          }
        }
        if (!failed && notificationFailed) throw notificationError;
      }
    }
  }
}

/**
 * 负责声明既有死亡 hook 的具名运行扩展：在本次提案的原准备时点运行，实际标死之后发布本族事实。
 * 输入是同一死亡名单、死因、原体查询和夜间保护查询；输出只描述追加原因与公开可见性，
 * 并持有本族发布回调。具体绑定、领取回执、来源政策、夜间旗标和付款留在贡献所有者。
 * 这不是 JSON、权限品牌、资源账本或统一关系规则；失败时首异常向上传播，已经提交的前缀不回滚。
 */
import type {
  DeathCause,
  DeathSources,
  EntityId,
  GameEvent,
} from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../core/domain/world";

/** 查询在原表达式位置读取；World 的原身份供具体权威核对，不复制或冻结运行对象。 */
export interface DeathWaveContributionRuntime {
  readonly world: World;
  readonly events: GameEvent[];
  /** 目标也是惰性查询，保护方法的 callee／receiver 和 World 先读取，随后才读取目标。 */
  blocksNightLinkedDeath(target: () => EntityId): unknown;
}

/** 可信运行描述，不替代标死许可；原因与公开关联分别声明，不统一不同关系的来源政策。 */
export interface LinkedDeathDescription {
  readonly targetId: EntityId;
  readonly addedCauses: readonly DeathCause[];
  /** 额外纳入公开追加名单；false 不覆盖梦牵连或无枪来源等其它既有公开条件。 */
  readonly publicAdditionalDeath: boolean;
}

/** 原准备步骤完成后的关联；发布回调仍由本族核对实际原生命死亡与已领取回执。 */
export interface PreparedDeathWaveContribution {
  readonly linkedDeaths: readonly LinkedDeathDescription[];
  publishAfterDeaths(): void;
}

/** 同一 hook 的批量贡献，按原 proposal 顺序准备；不能推迟到全部 hooks 聚合完后才执行。 */
export interface DeathWaveContribution {
  prepare(
    runtime: DeathWaveContributionRuntime,
    proposed: EntityId[],
    proposedSources: DeathSources,
    nightTargets: EntityId[],
    allSources: DeathSources,
    nativeHunterShotTargets: ReadonlySet<EntityId>,
    seen: ReadonlySet<EntityId>,
  ): PreparedDeathWaveContribution;
}

/**
 * 负责原放逐／死亡动作分发，以及独立于可替换晚 hook 的必需整波贡献装配。
 * 输入为原 World、原名单／原因、日期／阶段和事件；输出保留免死结果或额外死亡提案。
 * 已提交整波贡献在实际标死之后、梦记录及遗言之前同步执行；榜样首次死亡由野孩子唯一绑定 owner 提交。
 * 这里不修改 Alive、选择阶段或回滚贡献已写事实；首失败原样传播，停止后续贡献并保留已付／已提交前缀。
 */
import {
  EntityId,
  GameEvent,
  type DeathSources,
  type Phase,
  type DeathShotSelection,
} from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import type { NightLifeScope } from "../../../core/domain/night_effects";
import type { DeathWaveContribution } from "./death-wave-contribution";
import { giftGunDeathHook } from "../roles/gift_gun_death_hook";
import { resolveWildChildDeathWave } from "../roles/wild_child/ports";

/** 已完成本批 Alive 提交后的具名扩展时点；不是可追加死亡或选择枪的晚 deathHook。 */
export type CommittedDeathWaveHook = (
  world: World,
  deadIds: readonly EntityId[],
  deathSources: DeathSources,
  day: number,
  phase: Phase,
  events: GameEvent[],
) => void;

/** 真实必需整波贡献装配；不属于调用方可替换的 votedOut／晚 deathHook 列表。 */
export function createCommittedDeathWaveContributions(): readonly CommittedDeathWaveHook[] {
  return [resolveWildChildDeathWave];
}

/** 放逐钩子返回结果。 */
export interface VotedOutResult {
  prevented: boolean;
  removed: EntityId[];
  reason: string;
}

/** 死亡钩子聚合结果。 */
export interface DeathHookResult {
  extraDeaths: EntityId[];
  extraDeathSources: DeathSources;
  nightEffectTargets?: EntityId[];
  pendingShots?: Array<{
    targetScope: NightLifeScope;
    event: GameEvent;
    isCurrent?: () => boolean;
  }>;
  /** 每 hook 同步消费的本族运行贡献；具体绑定／回执不属于通用结果。 */
  deathWaveContributions?: DeathWaveContribution[];
}
export interface DeathHookContext {
  readonly deathOriginPhase?: Phase;
  nativeHunterShotTargets?: ReadonlySet<EntityId>;
  day?: number;
  deferShotCommit?: boolean;
  nightEffect: boolean;
  blocksNightShot(targetId: EntityId): boolean;
  blocksNightCharm?: (targetId: EntityId) => boolean;
  eligibleDead?: ReadonlySet<EntityId>;
  isCurrent?: () => boolean;
}

/** 放逐钩子函数签名。 */
export type VotedOutHook = (
  world: World,
  targetId: EntityId,
  events: GameEvent[],
) => VotedOutResult | null;

/** 死亡钩子函数签名。 */
export type DeathHook = (
  world: World,
  deadIds: EntityId[],
  deathSources: DeathSources,
  chooseDeathShot: (actorId: EntityId, abilityId?: string) => Promise<DeathShotSelection>,
  events: GameEvent[],
  context?: DeathHookContext,
) => Promise<DeathHookResult>;

function buildDefaultVotedOutHooks(): VotedOutHook[] {
  return getDefaultRoleCatalog()
    .allRuntime()
    .map(({ runtime }) => runtime.votedOutHook)
    .filter((hook): hook is VotedOutHook => Boolean(hook));
}

function buildDefaultDeathHooks(): DeathHook[] {
  return getDefaultRoleCatalog()
    .allRuntime()
    .map(({ runtime }) => runtime.deathHook)
    .filter((hook): hook is DeathHook => Boolean(hook))
    .concat(giftGunDeathHook);
}

/** 钩子注册表：负责分发放逐钩子与死亡钩子。 */
export class HookRegistry {
  constructor(
    private readonly votedOutHooks: VotedOutHook[] = buildDefaultVotedOutHooks(),
    private readonly deathHooks: DeathHook[] = buildDefaultDeathHooks(),
  ) {}

  onVotedOut(world: World, targetId: EntityId, events: GameEvent[]): VotedOutResult | null {
    for (const hook of this.votedOutHooks) {
      const result = hook(world, targetId, events);
      if (result) {
        return result;
      }
    }
    return null;
  }

  async onDeath(
    world: World,
    deadIds: EntityId[],
    deathSources: DeathSources,
    chooseDeathShot: (actorId: EntityId, abilityId?: string) => Promise<DeathShotSelection>,
    events: GameEvent[],
    commitAdditionalDeaths?: (result: DeathHookResult) => void,
    context?: DeathHookContext,
  ): Promise<DeathHookResult> {
    const aggregated: DeathHookResult = {
      extraDeaths: [],
      extraDeathSources: {},
    };
    for (const hook of this.deathHooks) {
      if (context?.isCurrent && !context.isCurrent()) break;
      const result = await hook(world, deadIds, deathSources, chooseDeathShot, events, context);
      commitAdditionalDeaths?.(result);
      aggregated.extraDeaths.push(...result.extraDeaths);
      if (result.nightEffectTargets?.length)
        (aggregated.nightEffectTargets ??= []).push(...result.nightEffectTargets);
      if (result.pendingShots?.length)
        (aggregated.pendingShots ??= []).push(...result.pendingShots);
      if (result.deathWaveContributions?.length)
        (aggregated.deathWaveContributions ??= []).push(...result.deathWaveContributions);
      for (const [id, marks] of Object.entries(result.extraDeathSources)) {
        aggregated.extraDeathSources[Number(id)] = [
          ...new Set([...(aggregated.extraDeathSources[Number(id)] ?? []), ...marks]),
        ];
      }
    }
    return aggregated;
  }
}

let defaultRegistry: HookRegistry | null = null;

/** 获取默认钩子注册表实例。 */
export function getDefaultHookRegistry(): HookRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new HookRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责按遗言政策判定资格，并为已死亡玩家发表遗言授予事实。
 * 输入为死亡阶段、日期、原死因及可选初始波上下文；记录入口另接收 World 与待写事件数组。
 * 输出为资格布尔值和 last_words_granted 事件；实际生命仍在写入前检查，规则未知则拒绝。
 * 此机制不执行玩家发言、更新死亡波或判胜，发言与阶段推进归原调用流程。
 */
/** 文件说明：遗言规则与事件写入机制。 */
import type { LastWordsPolicy } from "../../../core/domain/board";
import { AliveComponent } from "../../../core/domain/components/alive";
import { COMPONENT } from "../../../core/domain/components/names";
import {
  EntityId,
  GameEvent,
  Phase,
  DeathCause,
  type DeathSources,
} from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { FRAGRANT_PAIR_POLICY } from "@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer";
export interface LastWordsGrantContext {
  policy: typeof FRAGRANT_PAIR_POLICY;
  initialWave: boolean;
}

/** 遗言机制：判定是否可遗言并写入遗言授权事件。 */
export class LastWordsMechanism {
  /** 这里只判来源阶段、日期与死因；基础政策是否初始波由调用方筛选，不凭资格布尔值直接开放发言。 */
  shouldGrantLastWords(
    deathPhase: Phase,
    day: number,
    sources: readonly DeathCause[],
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    context?: LastWordsGrantContext,
  ): boolean {
    // 具名政策要求全部原因已知，再允许白天／投票及首夜夜死；不借当前执行阶段猜测死亡来源。
    if (policy === "netease_2017_day_and_first_night_v1") {
      if (!sources.length || sources.some((source) => !Object.values(DeathCause).includes(source)))
        return false;
      return (
        deathPhase === Phase.Day ||
        deathPhase === Phase.Voting ||
        (deathPhase === Phase.Night && day === 1)
      );
    }
    if (policy !== "awa_initial_wave_v1") return false;
    if (
      sources.length === 0 ||
      sources.includes(DeathCause.SelfDestruct) ||
      sources.includes(DeathCause.WhiteWolfBlast)
    )
      return false;
    if (deathPhase === Phase.Day && sources.every((source) => source === DeathCause.DuelFailure))
      return true;
    return (
      (deathPhase === Phase.Night &&
        day === 1 &&
        sources.some(
          (source) =>
            source === DeathCause.WolfKill ||
            (source === DeathCause.FragrantLink &&
              context?.policy === FRAGRANT_PAIR_POLICY &&
              context.initialWave) ||
            source === DeathCause.AwakenedHiddenKnife ||
            source === DeathCause.Poison ||
            source === DeathCause.Dream ||
            source === DeathCause.FoxInspection ||
            source === DeathCause.MerchantBacklash ||
            source === DeathCause.BlackMarketBacklash,
        )) ||
      (deathPhase === Phase.Voting && sources.includes(DeathCause.Exile))
    );
  }

  /** 逐人再次核死因政策与实际死亡，只写授予事实；等待玩家、打开生命许可和记录发言归结算器。 */
  recordLastWordsGranted(
    world: World,
    deadIds: EntityId[],
    deathPhase: Phase,
    lastWordsPhase: Phase,
    day: number,
    events: GameEvent[],
    sources: DeathSources,
    deathPhases: Readonly<Record<EntityId, Phase>> = {},
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    context?: LastWordsGrantContext,
  ): void {
    for (const deadId of deadIds) {
      if (
        !this.shouldGrantLastWords(
          deathPhases[deadId] ?? deathPhase,
          day,
          sources[deadId] ?? [],
          policy,
          context,
        )
      ) {
        continue;
      }
      const alive = world.getComponent(deadId, COMPONENT.Alive);
      if (!alive || alive.alive) {
        continue;
      }
      events.push({
        timestamp: Date.now(),
        type: "last_words_granted",
        payload: {
          playerId: deadId,
          phase: lastWordsPhase,
          day,
        },
      });
    }
  }
}

let defaultMechanism: LastWordsMechanism | null = null;

/** 获取默认遗言机制实例。 */
export function getDefaultLastWordsMechanism(): LastWordsMechanism {
  if (!defaultMechanism) {
    defaultMechanism = new LastWordsMechanism();
  }
  return defaultMechanism;
}

/**
 * 负责完整遗言行动窗口：输入原死亡名单、来源／政策、执行阶段及当前性回调，输出已清洗的遗言事件。
 * 运行依赖保留 World、事件数组、状态、网关和原遗言机制引用，在原表达式处晚读；构造器端口必填且每次收集独立 new。
 * 政策与授予事实仍归 LastWordsMechanism，原生命许可由 World 唯一持有；本窗口不标死、推进阶段、判胜或消费枪／警徽。
 * 请求和回复只是数据；独立交付租约 pin 原信封／来源字段、隔离坏别名并共享最早期限，不能替代 World 许可。
 * 等待、网关及发表前均晚核租约，真正发表成功后才通知 true；开放后的退出仍关闭许可，原关闭错误优先。
 */
import type { ActionRequestFactoryConstructorPort } from "../../../core/domain/actions";
import type { LastWordsPolicy } from "../../../core/domain/board";
import type {
  ActionProvider,
  EntityId,
  GameEvent,
  Phase,
  RuntimeSnapshot,
  DeathSources,
} from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import { RequestLease, type RequestLeaseTurn } from "../../../core/domain/request-lease";
import type { ToolGateway } from "../../gateway/tool_gateway";
import type { LastWordsGrantContext, LastWordsMechanism } from "./last_words_mechanism";

/** 只声明原运行依赖的读口；readonly 不冻结原对象、拍摄状态快照或授予死亡行动。 */
export interface LastWordsWindowRuntime {
  readonly requestFactory: ActionRequestFactoryConstructorPort;
  readonly world: World;
  readonly events: GameEvent[];
  readonly state: RuntimeSnapshot;
  readonly toolGateway: ToolGateway;
  readonly lastWordsMechanism: LastWordsMechanism;
}

/** 每个真实请求独立持有捕获日次和晚域查询，不透明对象不进入提示，也不能由 death_action_id 重建。 */
interface LastWordsRequestScope {
  actorId: EntityId;
  phase: Phase;
  day: number;
  current(): boolean;
}

// 复用唯一请求租约 owner；三个来源字段只 pin 创建时值／引用，不校验深层 JSON 或创建第二死亡许可。
const lastWordsRequests = RequestLease.window<LastWordsRequestScope>({
  actorId: (scope) => scope.actorId,
  phase: (scope) => scope.phase,
  day: (scope) => scope.day,
  stage: () => "last_words",
  current: (scope) => scope.current(),
}, 130, ["trigger", "death_phase", "death_action_id"]);

/** 持有同一运行依赖对象；构造本窗口不查询其字段，真正的工厂构造保留在收集入口。 */
export class LastWordsWindow {
  constructor(private readonly runtime: LastWordsWindowRuntime) {}

  /** 授予事实不替代发言窗口；每位死者等待回复后复核阶段、日期、终局与原生命许可，再写发言。 */
  async collect(
    deadIds: EntityId[],
    phase: Phase,
    deathPhase: Phase,
    sources: DeathSources,
    actionProvider: ActionProvider,
    deathPhases: Readonly<Record<EntityId, Phase>>,
    scopeCurrent: () => boolean = () => true,
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    wordsContext?: LastWordsGrantContext,
  ): Promise<void> {
    // 构造器先查询，再按原顺序取 World／事件／第一次日期；构造完成后另读本次收集日期。
    const requests = new this.runtime.requestFactory(this.runtime.world, this.runtime.events, this.runtime.state.day);
    const day = this.runtime.state.day;
    for (const deadId of deadIds) {
      // 来源阶段与政策先于当前性和许可；不以授予事件或请求字段代替 World 的原生命绑定。
      const actualDeathPhase = deathPhases[deadId] ?? deathPhase;
      if (
        !this.runtime.lastWordsMechanism.shouldGrantLastWords(
          actualDeathPhase,
          day,
          sources[deadId] ?? [],
          policy,
          wordsContext,
        )
      )
        continue;
      if (
        !scopeCurrent() ||
        this.runtime.state.phase !== phase ||
        this.runtime.state.day !== day ||
        this.runtime.state.gameOver
      )
        return;
      // 开放抛错仍发生在 try 外；开放成功后，所有 return／continue 与原异常都经过 finally。
      const permit = this.runtime.world.openDeathAction(deadId, "speak", phase, day, scopeCurrent);
      let delivery: RequestLeaseTurn | undefined;
      let failed = false;
      try {
        const request = requests.create({
          phase,
          actorId: deadId,
          allowedTools: ["speak"],
          stage: "last_words",
          requiresAction: true,
          summary: { key: "request.summary.last_words" },
          context: {
            trigger: "last_words",
            death_phase: actualDeathPhase,
            death_action_id: permit.id,
          },
        });
        const requestScope: LastWordsRequestScope = {
          actorId: deadId,
          phase,
          day,
          // 新交付政策在 create 后也完整查阶段／日次／终局；查询仍按原 scope→状态→真实 permit 顺序。
          current: () =>
            scopeCurrent() &&
            this.runtime.state.phase === phase &&
            this.runtime.state.day === day &&
            !this.runtime.state.gameOver &&
            this.runtime.world.hasDeathAction(deadId, "speak", phase, day, permit.id),
        };
        lastWordsRequests.bind(requestScope, request);
        delivery = lastWordsRequests.openDelivery(requestScope, request);
        if (!delivery) return;
        // 先保原 provider callee／receiver，再准备新增调用口；最后守卫后只调用已准备函数，不能晚读 .apply。
        const getAction = actionProvider.getAction;
        const actionArguments: [typeof request] = [request];
        const invokeAction = Reflect.apply.bind(Reflect);
        if (!delivery.current()) return;
        const action = await invokeAction(getAction, actionProvider, actionArguments);
        if (!delivery.current()) return;
        if (action?.name !== "speak") {
          continue;
        }
        const validated = this.runtime.toolGateway.validateAndSanitize(this.runtime.world, deadId, action, {
          phase,
          day: this.runtime.state.day,
          deathActionId: permit.id,
        });
        if (!validated.ok || !validated.sanitizedCall) {
          continue;
        }
        if (!delivery.current()) return;
        // 保留 push callee→时间戳→日次→清洗后文字的读取序；新增调用准备也在末守卫前，发表失败不回滚前缀。
        const events = this.runtime.events;
        const publish = events.push;
        const publication: GameEvent = {
          timestamp: Date.now(),
          type: "last_words_spoken",
          payload: {
            playerId: deadId,
            phase,
            day: this.runtime.state.day,
            text: validated.sanitizedCall.args.text,
          },
        };
        const publicationArguments: [GameEvent] = [publication];
        const invokePublication = Reflect.apply.bind(Reflect);
        if (!delivery.current()) return;
        invokePublication(publish, events, publicationArguments);
        // 只以实际 push 正常返回确认完成；先终结租约再通知，true 回调晚错不撤事件或二次 false。
        delivery.complete();
      } catch (error) {
        failed = true;
        throw error;
      } finally {
        try {
          permit.close();
        } catch (error) {
          failed = true;
          throw error;
        } finally {
          // 原 close 仍覆盖正文错误；新增 false 通知只在没有旧错时传播，boolean 同样保 throw undefined。
          if (failed) {
            try { delivery?.close(); } catch { /* 保留正在传播的正文／许可关闭错误。 */ }
          } else {
            delivery?.close();
          }
        }
      }
    }
  }
}

/**
 * 负责定义工具参数修复与目标提示的公共数据契约；输入为原参数、行动者和 World／候选引用，
 * 输出契约为修复候选或提示文字。实际处理函数与目标规则由各 registry 拥有。
 * 可写字段与 readonly 候选类型不复制、冻结或验证输入；提示及修复结果不授予请求权限或库存。
 */
import { EntityId, Role, ToolName } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";

/** 修复只取得本次行动者编号；该字段本身不证明请求绑定、身份或当前行动资格。 */
export interface CoerceContext {
  actorId: EntityId;
}

/**
 * 接收可写的原参数记录与上下文，返回修复候选；null 表示没有候选，不表示已经接受或完成弃权。
 * 类型不限制处理器读取 getter、修改输入或抛错；接收器仍对结果校验 schema 和领域规则。
 */
export type CoerceHandler = (
  args: Record<string, unknown>,
  ctx: CoerceContext,
) => Record<string, unknown> | null;

/** 工具到处理器的可写稀疏表；同名注册保最后处理器值，无有效处理器时保原参数副本。 */
export interface ToolRepairPack {
  coerce: Partial<Record<ToolName, CoerceHandler>>;
}

/**
 * 目标提示按当前工具与候选来源选择编号，World 保原 live 引用；这里不持有提交回执或独立库存。
 * 可选字段由原调用方逐项求值，缺项处理与异常由具体目标规则决定，不统一补全或校验。
 */
export interface TargetHintContext {
  /** 学者修正／追加行动的提示候选；readonly 只限制类型写法，不是冻结后的许可名单。 */
  modifierCandidates?: readonly EntityId[];
  modifierBonusCandidates?: readonly EntityId[];
  /** 行动者及轮次用于原目标规则查询；缺省 day 的处理由具体规则选择。 */
  actorId: EntityId;
  day?: number;
  /** 提示层选择目标策略的角色标签，可来自能力实例；不能据此认定当前身份或真实阵营。 */
  actorRole?: Role;
  /** 能力实例标识只定位本次目标规则，不独立授予该实例的使用权。 */
  abilityId?: string;
  debateTargetId?: number;
  /** 原可写工具数组决定提示分支；是否可提交仍由真实请求、接收器和机制复验。 */
  allowedTools: ToolName[];
  /** 规则在原查询点读取组件、存活名单和 locale；此引用不是数据快照。 */
  world: World;
  roleCatalog?: import("../roles/catalog").RoleCatalog;
  /** 警长、徽章与放逐候选用于对应提示过滤，仍须按原参与规则核资格。 */
  sheriffCandidates?: readonly EntityId[];
  badgeCandidates?: readonly EntityId[];
  exileCandidates?: readonly EntityId[];
}

/** 返回提示文本或无提示；查询／本地化异常按实现传播，提示不等于动作准入结果。 */
export interface TargetHintRegistry {
  buildActionableIdsHint(ctx: TargetHintContext): string | undefined;
}

/**
 * 根据请求、角色和已注册目标规则生成可行动编号提示。输入为当前组件状态与候选上下文，
 * 输出为本地化提示；提示不授予行动权限，实际校验与提交仍由网关和具体机制负责。
 * 狼刀候选只消费公开目标查询，不取得狼人私有状态或狼刀提交权。
 */
import { nobleBodyChoiceTargets } from "../roles/noble_secret_body/authority";
import {
  shelterTargets,
  eclipseSwallowTargets,
  isRadiantEclipseBoard,
} from "../roles/radiant_eclipse/night_frame";
import { nightmareFearTargets } from "../roles/nightmare_shadow/ports";
import { magicianChoiceTargets } from "../roles/magician/night_frame";
import { bindWolfKnifeTargetQuery } from "../roles/wolf/ports";
import { prohibitsLoversVote } from "../roles/cupid/relation";
import { seerTargetAllowed } from "../roles/seer/ports";
import { guardTargetRepeated } from "../roles/guard/ports";
import { text } from "@ai-werewolf-arena/game-text";
import { Role, ToolName } from "../../../core/domain/model";
import { TargetHintContext, TargetHintRegistry } from "./contracts";
import { canBeExiled, canBeSheriff } from "../common/participation";
import { inspectionRepeats } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { getRoleInspectionState } from "../roles/role_inspection/ports";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { findNightAbility } from "../roles/abilities";
import { luckyTargetAllowed } from "../roles/night_action_history";
import { getAwakenedState } from "../roles/awakened_hidden_wolf/state";

interface TargetRule {
  /** 只决定提示是否保留自身编号；当前板子的实际目标限制仍由机制复验。 */
  allowSelf: boolean;
}

/**
 * 默认 target_id 提示注册器：
 * - 以工具规则为基线；
 * - 再按角色规则覆盖，便于角色机制独立扩展。
 */
export class DefaultTargetHintRegistry implements TargetHintRegistry {
  private readonly toolRules: Partial<Record<ToolName, TargetRule>> = {
    fox_distract: { allowSelf: true },
    bind_fragrant_pair: { allowSelf: true },
    check_pair: { allowSelf: true },
    choose_servant: { allowSelf: false },
    protect_secret_body: { allowSelf: true },
    kill_vote: { allowSelf: false },
    fear: { allowSelf: false },
    swap_targets: { allowSelf: true },
    guard: { allowSelf: false },
    check_identity: { allowSelf: false },
    inspect_role: { allowSelf: false },
    inspect_night_identity: { allowSelf: false },
    mimic_role: { allowSelf: false },
    mechanical_inspect: { allowSelf: false },
    awakened_mimic: { allowSelf: false },
    awakened_poison: { allowSelf: true },
    awakened_guard: { allowSelf: true },
    awakened_attack: { allowSelf: true },
    bestow_ability: { allowSelf: false },
    choose_exemplar: { allowSelf: false },
    mechanical_poison: { allowSelf: true },
    mechanical_guard: { allowSelf: true },
    mechanical_attack: { allowSelf: true },
    use_potion: { allowSelf: false },
    vote: { allowSelf: false },
    shoot: { allowSelf: false },
    black_market_trade: { allowSelf: false },
    self_destruct_with_target: { allowSelf: false },
    duel: { allowSelf: false },
    dream: { allowSelf: false },
    charm: { allowSelf: false },
    vote_for_sheriff: { allowSelf: false },
    choose_badge_successor: { allowSelf: false },
  };

  private readonly roleOverrides: Partial<Record<Role, Partial<Record<ToolName, TargetRule>>>> = {
    [Role.FragrantPhantom]: { kill_vote: { allowSelf: true } },
    [Role.NightNoble]: { kill_vote: { allowSelf: true } },
    [Role.Wolf]: {
      // 狼人策略中可允许自刀，提示层保留自己编号避免“无效 self target”误判。
      kill_vote: { allowSelf: true },
    },
    [Role.WolfKing]: { kill_vote: { allowSelf: true } },
    [Role.NightmareShadow]: { kill_vote: { allowSelf: true } },
    [Role.WolfWitch]: { kill_vote: { allowSelf: true } },
    [Role.WhiteWolfKing]: { kill_vote: { allowSelf: true } },
    [Role.HiddenWolf]: { kill_vote: { allowSelf: true } },
    [Role.Gargoyle]: { kill_vote: { allowSelf: true } },
    [Role.MechanicalWolf]: { kill_vote: { allowSelf: true } },
    [Role.AwakenedHiddenWolf]: { kill_vote: { allowSelf: true } },
    [Role.Witch]: {
      // 女巫可自救，提示层需包含自己。
      use_potion: { allowSelf: true },
    },
    [Role.Guard]: {
      // 守卫是否可自守由板子机制决定；提示层默认放开，避免误导模型。
      guard: { allowSelf: true },
    },
  };

  buildActionableIdsHint(ctx: TargetHintContext): string | undefined {
    if (
      ctx.allowedTools.includes("choose_servant") ||
      ctx.allowedTools.includes("protect_secret_body")
    ) {
      const ids = nobleBodyChoiceTargets(
        ctx.world,
        ctx.day ?? 1,
        ctx.allowedTools.includes("choose_servant") ? "noble" : "body",
      );
      return ids.length
        ? text(
            ctx.world.locale,
            ctx.allowedTools.includes("protect_secret_body")
              ? "prompt.targets.self"
              : "prompt.targets.others",
            { ids: ids.join(", ") },
          )
        : text(ctx.world.locale, "prompt.targets.none");
    }
    if (ctx.allowedTools.includes("cast_shelter") || ctx.allowedTools.includes("swallow_skill")) {
      const ids = ctx.allowedTools.includes("cast_shelter")
        ? shelterTargets(ctx.world, ctx.day ?? 1, ctx.actorId, ctx.abilityId!)
        : eclipseSwallowTargets(ctx.world, ctx.day ?? 1);
      return ids.length
        ? text(ctx.world.locale, "prompt.targets.others", { ids: ids.join(", ") })
        : text(ctx.world.locale, "prompt.targets.none");
    }
    if (ctx.allowedTools.includes("modify_skill") || ctx.allowedTools.includes("bonus_action")) {
      const candidates = ctx.allowedTools.includes("modify_skill")
        ? ctx.modifierCandidates
        : ctx.modifierBonusCandidates;
      if (candidates === undefined) throw new Error("scholar_mentor_candidates_missing");
      const alive = new Set(ctx.world.getAliveEntityIds()),
        ids = [...new Set(candidates)].filter((id) => alive.has(id)).sort((a, b) => a - b);
      return ids.length
        ? text(
            ctx.world.locale,
            ids.includes(ctx.actorId) ? "prompt.targets.self" : "prompt.targets.others",
            { ids: ids.join(", ") },
          )
        : text(ctx.world.locale, "prompt.targets.none");
    }
    if (ctx.allowedTools.includes("challenge") && ctx.debateTargetId !== undefined)
      return text(ctx.world.locale, "prompt.targets.debate", { target: ctx.debateTargetId });
    if (ctx.allowedTools.includes("choose_lovers"))
      return text(ctx.world.locale, "prompt.targets.lovers", {
        ids: ctx.world.getAliveEntityIds().join(", "),
      });
    const targetTools = ctx.allowedTools.filter((tool) => this.getRule(ctx.actorRole, tool));
    if (targetTools.length === 0) {
      return undefined;
    }
    const radiantSelf =
      isRadiantEclipseBoard(ctx.world) &&
      (ctx.allowedTools.includes("use_potion") ||
        ctx.allowedTools.includes("check_identity") ||
        ctx.allowedTools.includes("kill_vote"));
    const allowSelf =
      radiantSelf || targetTools.some((tool) => this.getRule(ctx.actorRole, tool)?.allowSelf);
    const inspection = getRoleInspectionState(
      ctx.world.getComponent(ctx.actorId, COMPONENT.Role)!,
      ctx.abilityId,
    );
    const ownRole = ctx.world.getComponent(ctx.actorId, COMPONENT.Role);
    const awakenedGuard = getAwakenedState(ownRole)?.learned?.skill;
    const luckyAllowed = (tool: ToolName, id: number) => {
      const kind =
        tool === "check_identity"
          ? "seer_check"
          : tool === "guard"
            ? "guard"
            : tool === "use_potion"
              ? "potion"
              : null;
      if (!kind) return true;
      const ability = findNightAbility(ownRole, kind, ctx.abilityId);
      if (!ability) return true;
      // 普通女巫仍可救这个目标，即使其毒药目标因该行动者的历史记录而被限制。
      if (
        ability.kind === "potion" &&
        ability.activation !== "lucky" &&
        ability.activation !== "black_market" &&
        ability.state.heal > 0
      )
        return true;
      if (ability.kind === "seer_check" && !seerTargetAllowed(ability.state, ctx.actorId, id))
        return false;
      if (ability.kind === "guard" && guardTargetRepeated(ability, ctx.day ?? 1, id)) return false;
      return luckyTargetAllowed(
        ctx.world,
        ctx.actorId,
        ability,
        ctx.day ?? 1,
        kind === "seer_check" ? "check" : kind === "guard" ? "guard" : "poison",
        id,
      );
    };
    const ids = ctx.world
      .getAliveEntityIds()
      .filter((id) =>
        targetTools.some(
          (tool) =>
            (radiantSelf || this.getRule(ctx.actorRole, tool)?.allowSelf || id !== ctx.actorId) &&
            luckyAllowed(tool, id) &&
            (tool !== "fear" ||
              nightmareFearTargets(ctx.world, ctx.actorId, ctx.day ?? 1).includes(id)) &&
            (tool !== "swap_targets" ||
              magicianChoiceTargets(ctx.world, ctx.day ?? 1).includes(id)) &&
            (tool !== "kill_vote" || bindWolfKnifeTargetQuery(ctx.world).allows(id)) &&
            (tool !== "inspect_night_identity" ||
              ctx.actorRole !== Role.WolfWitch ||
              (ctx.world.getComponent(id, COMPONENT.Role) &&
                ctx.world.getComponent(id, COMPONENT.Camp)?.camp) !== "wolf") &&
            (tool !== "awakened_guard" ||
              awakenedGuard?.kind !== "guard" ||
              awakenedGuard.lastGuardDay !== (ctx.day ?? 1) - 1 ||
              awakenedGuard.lastTarget !== id) &&
            (tool !== "vote" ||
              ((ctx.exileCandidates === undefined || ctx.exileCandidates.includes(id)) &&
                canBeExiled(ctx.world, id, ctx.roleCatalog) &&
                !prohibitsLoversVote(ctx.world, ctx.actorId, id))) &&
            (tool !== "inspect_role" ||
              !inspection ||
              inspectionRepeats(inspection) ||
              !inspection.history.some((report) => report.targetId === id)) &&
            (tool !== "choose_badge_successor" ||
              (ctx.badgeCandidates?.includes(id) &&
                canBeSheriff(ctx.world, id, ctx.roleCatalog))) &&
            (tool !== "vote_for_sheriff" ||
              (ctx.sheriffCandidates?.includes(id) &&
                canBeSheriff(ctx.world, id, ctx.roleCatalog))),
        ),
      )
      .sort((a, b) => a - b);
    const potion = findNightAbility(ownRole, "potion", ctx.abilityId);
    if (
      targetTools.length === 1 &&
      targetTools[0] === "use_potion" &&
      potion?.activation === "lucky"
    ) {
      return text(ctx.world.locale, "prompt.targets.lucky_poison", {
        ids: ids.join(", ") || text(ctx.world.locale, "common.none"),
        actor: ctx.actorId,
      });
    }
    if (ids.length === 0) {
      return text(ctx.world.locale, "prompt.targets.none");
    }
    if (allowSelf) {
      return text(ctx.world.locale, "prompt.targets.self", { ids: ids.join(", ") });
    }
    return text(ctx.world.locale, "prompt.targets.others", { ids: ids.join(", ") });
  }

  private getRule(role: Role | undefined, tool: ToolName): TargetRule | undefined {
    const roleRule = role !== undefined ? this.roleOverrides[role]?.[tool] : undefined;
    return roleRule ?? this.toolRules[tool];
  }
}

let defaultTargetHintRegistry: TargetHintRegistry | null = null;

/** 获取默认 target_id 提示注册器。 */
export function getDefaultTargetHintRegistry(): TargetHintRegistry {
  if (!defaultTargetHintRegistry) {
    defaultTargetHintRegistry = new DefaultTargetHintRegistry();
  }
  return defaultTargetHintRegistry;
}

/**
 * 负责聚合通用、警长与角色运行贡献的参数修复规则。输入为原修复包及回合上下文；
 * 输出为原 coercion 结果或原参数副本。注册保持顺序和最后处理函数引用；
 * 本索引不接受动作、消耗库存或授予当前请求权限。
 */
import { ToolName } from "../../../core/domain/model";
import { COMMON_LLM_REPAIR_PACK } from "../common/llm_repair";
import { RoleCatalog } from "../roles/catalog";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { SHERIFF_LLM_REPAIR_PACK } from "../sheriff/llm_repair";
import { CoerceContext, ToolRepairPack } from "./contracts";

function buildDefaultPacks(roleProfileRegistry: RoleCatalog): ToolRepairPack[] {
  const packs: ToolRepairPack[] = [COMMON_LLM_REPAIR_PACK, SHERIFF_LLM_REPAIR_PACK];
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.llmRepair) {
      packs.push(profile.llmRepair);
    }
  }
  return packs;
}

/** LLM 工具调用修复注册表。 */
export class ToolCallRepairRegistry {
  private readonly coerceHandlers = new Map<ToolName, ToolRepairPack["coerce"][ToolName]>();

  constructor(
    packs?: ToolRepairPack[],
    roleProfileRegistry: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    const effectivePacks = packs ?? buildDefaultPacks(roleProfileRegistry);
    for (const pack of effectivePacks) {
      for (const [name, handler] of Object.entries(pack.coerce)) {
        this.coerceHandlers.set(name as ToolName, handler);
      }
    }
  }

  coerceArgs(
    tool: ToolName,
    rawArgs: Record<string, unknown>,
    ctx: CoerceContext,
  ): Record<string, unknown> | null {
    const handler = this.coerceHandlers.get(tool);
    if (!handler) {
      return { ...rawArgs };
    }
    return handler(rawArgs, ctx);
  }
}

let defaultRegistry: ToolCallRepairRegistry | null = null;

/** 获取默认 LLM 工具调用修复注册表实例。 */
export function getDefaultToolCallRepairRegistry(): ToolCallRepairRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ToolCallRepairRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责查询既有有限板子的夜死是否先于白天结算。输入为只读板子参数；输出为原时点布尔值。
 * 这里只检查对应配置的真值，不推进阶段、结算伤害或安装角色状态。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type {} from "../../core/domain/board";
/** 这些有限板子在进入白天管线前提交夜死；这里只选择时点，不执行提交。 */
export function settlesNightBeforeDay(config: ReadonlyBoardConfig): boolean {
  return !!(config.pureWhite || config.evilKnight || config.demonHunter || config.ghostBride);
}

/**
 * 负责通用、警长和角色运行贡献的领域工具索引，以及有序本地化提示和指令。输入为原规格与指令数组；输出为同一规格和展示文字，不授予行动权限。重复的自有数据 schema 必须完全一致；兼容或不透明覆盖保留最后原引用与原文。参数 getter 和 schema 解析仍延迟至 ActionReception 首次使用；不合并 SDK／MCP 三项传输工具或写入领域状态。
 */
import { text, type Locale } from "@ai-werewolf-arena/game-text";
import { registerToolSpecs } from "../../../rulesets/tool-spec-registration";
import { ToolName } from "../../../core/domain/model";
import { COMMON_TOOL_SPECS } from "../common/tool_specs";
import { StageDirectiveRule, ToolSpec } from "../contracts";
import { RoleCatalog } from "../roles/catalog";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { SHERIFF_TOOL_SPECS } from "../sheriff/tool_specs";

function buildDefaultSpecs(roleProfileRegistry: RoleCatalog): ToolSpec[] {
  const specs: ToolSpec[] = [...COMMON_TOOL_SPECS, ...SHERIFF_TOOL_SPECS];
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.toolSpecs) {
      specs.push(...profile.toolSpecs);
    }
  }
  return specs;
}

function buildDefaultStageDirectives(roleProfileRegistry: RoleCatalog): StageDirectiveRule[] {
  const directives: StageDirectiveRule[] = [];
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.stageDirectives) {
      directives.push(...profile.stageDirectives);
    }
  }
  return directives;
}

/** 工具规格注册表。 */
export class ToolSpecRegistry {
  private readonly specByName = new Map<ToolName, ToolSpec>();
  private readonly stageDirectives: StageDirectiveRule[];

  constructor(
    specs?: ToolSpec[],
    stageDirectives?: StageDirectiveRule[],
    roleProfileRegistry: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    const effectiveSpecs = specs ?? buildDefaultSpecs(roleProfileRegistry);
    const effectiveDirectives = stageDirectives ?? buildDefaultStageDirectives(roleProfileRegistry);
    registerToolSpecs(this.specByName, effectiveSpecs);
    this.stageDirectives = [...effectiveDirectives];
  }

  get(name: ToolName): ToolSpec | undefined {
    return this.specByName.get(name);
  }

  getArgHint(name: ToolName): string | null {
    return this.specByName.get(name)?.argHint ?? null;
  }

  getUserPromptHint(name: ToolName, locale: Locale = "zh-CN"): string | null {
    const spec = this.specByName.get(name);
    return (
      spec?.userPromptHint ??
      (spec?.userPromptHintKey ? text(locale, spec.userPromptHintKey) : null)
    );
  }

  getStageDirective(allowedTools: ToolName[], locale: Locale = "zh-CN"): string | null {
    const matched = this.stageDirectives.find((rule) => rule.match(allowedTools));
    if (!matched) return null;
    // 调用方可以复制内建规则后覆盖原文；只在原文仍等于内建字节时采用对应翻译。
    return matched.messageKey && matched.text === text("zh-CN", matched.messageKey)
      ? text(locale, matched.messageKey)
      : matched.text;
  }

  getApplicableUserPromptHints(allowedTools: ToolName[], locale: Locale = "zh-CN"): string[] {
    return allowedTools
      .map((name) => this.getUserPromptHint(name, locale))
      .filter((item): item is string => Boolean(item));
  }
}

let defaultRegistry: ToolSpecRegistry | null = null;

/** 获取默认工具规格注册表实例。 */
export function getDefaultToolSpecRegistry(): ToolSpecRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ToolSpecRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责胜利条件规格索引和具名评估委托。输入为原规格、World、条件与检查点，输出原判定或 null，未知条件保原错误。
 * 索引唯一持有规格 Map，允许检查点才调用原 evaluate；本注册表不推进阶段或封盘。
 */
import type { VictoryCheckpoint } from "@ai-werewolf-arena/game-contract";
/** 文件说明：管理胜利条件规格与评估入口。 */
import { WinDecision, WinCondition } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { DEFAULT_WIN_CONDITION_SPECS } from "../win_conditions/default_specs";
import { WinConditionSpec } from "../win_conditions/contracts";

/** 胜利条件注册表。 */
export class WinConditionRegistry {
  private readonly specById = new Map<WinCondition, WinConditionSpec>();

  constructor(specs: WinConditionSpec[] = DEFAULT_WIN_CONDITION_SPECS) {
    for (const spec of specs) {
      this.specById.set(spec.id, spec);
    }
  }

  get(condition: WinCondition): WinConditionSpec | undefined {
    return this.specById.get(condition);
  }

  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null {
    const spec = this.specById.get(condition);
    if (!spec) {
      throw new Error(`Unknown win condition: ${condition}`);
    }
    if (spec.checkpoints && (checkpoint === undefined || !spec.checkpoints.includes(checkpoint)))
      return null;
    return spec.evaluate(world, checkpoint);
  }

  all(): WinConditionSpec[] {
    return Array.from(this.specById.values());
  }
}

let defaultRegistry: WinConditionRegistry | null = null;

/** 获取默认胜利条件注册表实例。 */
export function getDefaultWinConditionRegistry(): WinConditionRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new WinConditionRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责普通夜能力唯一库存的数据复制、查询、原生安装和通用 metadata 提交。
 * 输入为原角色、捕获实例、已准备 payload 与明确日期；输出保留原字典／实例引用和能力变化事实。
 * 本 owner 写 abilities、retiredAbilityIds 及通用启停／次数／到期字段；原生 payload 准备仍归 ability_changes，
 * 授予／转移的来源与状态政策仍归 night-ability-grants，具体瓶数、梦历史、借用抑制及 Demon 审计另有原权威。
 * 字典创建、退休 ID 修订和逐字段提交保原求值顺序；发表或后续写入失败不回滚已完成前缀。
 * 数据复制不新增严格 live schema、JSON 档案接受或行动许可；readonly 视图仍是同一对象，不是冻结或第二库存。
 * F05a 只在 active／授予／转移执行入口拒永久退休身份，纯库存、状态、原生安装、已付写入与清理不据此过滤。
 */

