/**
 * 负责动物梦境完整死亡波贡献：装配实际运行端口、过滤白猫、公布事实、猫到期及提交事实。
 * 输入为原名单、可写原因表和来源阶段，以及保原晚读的运行／权威／事实端口；
 * 输出为原有效死亡名单、原因表修改及初／追加波事实。运行装配不向玩家暴露 World 或库存写权。
 * 已公布猫事实与已删原因属于原失败前缀，后续到期或记录失败不回滚，也不修改 Alive 或扩展其他关系。
 * 规则依据：docs/rules/awa-animal-dream-twelve-v1.md。
 */
import { Phase, DeathCause, type EntityId, type DeathSources } from "../../../../core/domain/model";
import {
  filterAnimalLethalWave,
  animalAuthoritySnapshot,
  isAnimalDreamBoard,
  prepareAnimalCatExpiry,
} from "./authority";
import { appendAnimalFact } from "./facts";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Role, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";

/** 只捕获结算器；每个 World／事件读取仍在原规则或事实参数位置，不缓存生命／权威快照。 */
export interface AnimalDeathWaveRuntime {
  readonly world: World;
  readonly events: GameEvent[];
}
import type { AnimalDreamPayloadMap } from "@ai-werewolf-arena/game-contract/facts/animal-dream";

type PreparationFact =
  "animal_wave_prepared" | "animal_cat_revealed" | "animal_cat_expiry_prepared";
/** 每个 thunk 在旧 World/事件参数之后才读取 unit 或构造 payload，避免 getter 提前。 */
interface AnimalDeathWavePorts {
  filter(
    day: number,
    phase: "night" | "day" | "voting",
    ids: EntityId[],
    sources: DeathSources,
    scope: () => object | (() => boolean),
  ): ReturnType<typeof filterAnimalLethalWave>;
  authority(): ReturnType<typeof animalAuthoritySnapshot>;
  prepareExpiry(unit: () => object): number | null;
  appendFact<T extends PreparationFact>(type: T, payload: () => AnimalDreamPayloadMap[T]): void;
}

export class AnimalDeathWavePreparation {
  constructor(
    private readonly ownsAnimal: boolean,
    private readonly resolutionDay: number,
    private readonly nightEffects: { animalUnit?: object } | undefined,
    private readonly isCurrent: () => boolean,
    private readonly ports: AnimalDeathWavePorts,
    private readonly runtime?: AnimalDeathWaveRuntime,
  ) {}

  /** 实际生产装配由动物 owner 完成；旧显式端口构造仅保留已有子系统调用契约。 */
  static fromRuntime(
    runtime: AnimalDeathWaveRuntime,
    resolutionDay: number,
    nightEffects: { animalUnit?: object } | undefined,
    isCurrent: () => boolean,
  ): AnimalDeathWavePreparation {
    const ownsAnimal = isAnimalDreamBoard(runtime.world);
    return new AnimalDeathWavePreparation(
      ownsAnimal,
      resolutionDay,
      nightEffects,
      isCurrent,
      {
        filter: (day, phase, ids, sources, scope) =>
          filterAnimalLethalWave(runtime.world, day, phase, ids, sources, scope()),
        authority: () => animalAuthoritySnapshot(runtime.world),
        prepareExpiry: (unit) => prepareAnimalCatExpiry(runtime.world, unit()),
        appendFact: (type, payload) =>
          appendAnimalFact(runtime.world, runtime.events, type, payload()),
      },
      runtime,
    );
  }

  /** 与原开局谓词同一次判断；后续仍由 prepare 和具体权威验证当前性，不增加镜像。 */
  get enabled(): boolean {
    return this.ownsAnimal;
  }

  /** 初波已实际标死且原公开通知已执行；河豚底牌先于整波事实，失败不回滚死亡或前一事实。 */
  recordInitialWave(pending: EntityId[], allSources: DeathSources, deathPhase: Phase): void {
    const resolutionDay = this.resolutionDay;
    for (const id of pending)
      if (
        this.runtime!.world.getComponent(id, COMPONENT.Role)?.role === Role.Pufferfish &&
        (allSources[id] ?? []).includes(DeathCause.WolfKill)
      )
        appendAnimalFact(this.runtime!.world, this.runtime!.events, "animal_puffer_revealed", {
          policy: "awa_animal_dream_v1",
          day: resolutionDay,
          actorId: id,
          reason: "knife_death",
        });
    appendAnimalFact(this.runtime!.world, this.runtime!.events, "animal_wave_committed", {
      policy: "awa_animal_dream_v1",
      day: resolutionDay,
      phase: deathPhase as "night" | "day" | "voting",
      deaths: [...pending],
      deathSources: Object.fromEntries(
        pending.map((id) => [String(id), [...(allSources[id] ?? [])]]),
      ),
    });
  }

  /** 追加目标标死后立即记录同一来源集合；随后才进入原 shot 发布、关系通知和继承顺序。 */
  recordAdditionalDeath(id: EntityId, allSources: DeathSources, sourcePhase: Phase): void {
    const resolutionDay = this.resolutionDay;
    appendAnimalFact(this.runtime!.world, this.runtime!.events, "animal_wave_committed", {
      policy: "awa_animal_dream_v1",
      day: resolutionDay,
      phase: sourcePhase as "night" | "day" | "voting",
      deaths: [id],
      deathSources: { [String(id)]: [...(allSources[id] ?? [])] },
    });
  }

  prepare(ids: EntityId[], waveSources: DeathSources, sourcePhase: Phase): EntityId[] {
    const { ownsAnimal, resolutionDay, nightEffects, isCurrent, ports } = this;
    if (!ownsAnimal) return ids;
    const proposed = [...ids],
      filtered = ports.filter(
        resolutionDay,
        sourcePhase as "night" | "day" | "voting",
        ids,
        waveSources,
        () => nightEffects?.animalUnit ?? isCurrent,
      );
    ports.appendFact("animal_wave_prepared", () => ({
      policy: "awa_animal_dream_v1",
      day: resolutionDay,
      phase: sourcePhase as "night" | "day" | "voting",
      proposedIds: proposed,
      blockedCatId: filtered.blockedCatId,
    }));
    if (filtered.revealedCatId !== null)
      ports.appendFact("animal_cat_revealed", () => ({
        policy: "awa_animal_dream_v1",
        day: resolutionDay,
        actorId: filtered.revealedCatId!,
      }));
    // 白猫首次挡死只留历史；到期仅沿用本单位新的放逐／河豚来源，不恢复首次死因枪权。
    const actual = [...filtered.deaths],
      cat = filtered.blockedCatId,
      currentCatSources =
        cat === null
          ? []
          : (waveSources[cat] ?? []).filter(
              (c) => c === DeathCause.Exile || c === DeathCause.PufferRetaliation,
            );
    // 原揭示事实先公布；之后删被过滤猫的原因，后续到期失败不回滚这个前缀。
    if (cat !== null) delete waveSources[cat];
    if (nightEffects?.animalUnit && !ports.authority()!.unit!.expiryPrepared) {
      // 必须先读原 World，再读取当次 unit；不能提前缓存两次 animalUnit getter。
      const expiry = ports.prepareExpiry(() => nightEffects.animalUnit!);
      if (expiry !== null) {
        const u = ports.authority()!.unit!;
        ports.appendFact("animal_cat_expiry_prepared", () => ({
          policy: "awa_animal_dream_v1",
          day: resolutionDay,
          actorId: expiry,
          unit: u.number,
          unitKind: u.kind,
        }));
        if (!actual.includes(expiry)) actual.push(expiry);
        // 按旧原因→本单位原因→到期原因合并，Set 只去重，不重新排序。
        waveSources[expiry] = [
          ...new Set([
            ...(waveSources[expiry] ?? []),
            ...currentCatSources,
            DeathCause.WhiteCatExpiry,
          ]),
        ];
      }
    }
    return actual;
  }
}

/**
 * 负责发表动物梦境已验证事实，并拥有按 World 隔离的事件时点知识日志。
 * 输入为原权威事实、演员与事件数组；输出为不可变追加事实及对应玩家已知数据。
 * 不变量：仅成功发表才能更新知识，覆盖 push 不得冒充提交；God 资源查询和复制视图
 * 不消费库存、推进日志或揭示未提交结果。
 */
import { readAnimalDreamFact, animalDreamFactAudience, type AnimalDreamEventType, type AnimalDreamPayloadMap, type AnimalBeautyKnowledge } from "@ai-werewolf-arena/game-contract/facts/animal-dream";
import { ANIMAL_DREAM_POLICY } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../../core/domain/world";
import { types } from "node:util";
import type { GameEvent } from "../../../../core/domain/events";
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import { Camp } from "../../../../core/domain/identity";
import { getWolfBeautyState } from "../wolf_beauty/ports";
import { animalOriginalRolePlayer, animalOriginalPlayer } from "./roster";
import {
  animalBeautyCharmAllowed,
  animalBeautyLinkBlocked,
  animalPackKnifeBlocked,
  animalAuthoritySnapshot,
} from "./authority";
interface Knowledge {
  fox: Map<
    number,
    { remaining: 0 | 1; lastChoice: { day: number; targetId: number | null } | null }
  >;
  puffer: Map<
    number,
    { remaining: 0 | 1; lastDecision: { day: number; activate: boolean } | null }
  >;
  cats: Set<number>;
  beauty: Map<number, AnimalBeautyKnowledge>;
  bear: Array<{ day: number; roared: boolean }>;
}
const known = new WeakMap<World, Knowledge>();
const now = Date.now.bind(Date);
function freezeFactData(value: object): void {
  for (const child of Object.values(value))
    if (child !== null && typeof child === "object") freezeFactData(child);
  Object.freeze(value);
}
function journal(world: World): Knowledge {
  let k = known.get(world);
  if (!k) {
    k = { fox: new Map(), puffer: new Map(), cats: new Set(), beauty: new Map(), bear: [] };
    known.set(world, k);
  }
  return k;
}
/** 仅成功追加的事实推进知识；God 资源查询不推进。 */
export function appendAnimalFact<K extends AnimalDreamEventType>(
  world: World,
  events: GameEvent[],
  type: K,
  payload: AnimalDreamPayloadMap[K],
): void {
  const fact = readAnimalDreamFact(type, snapshotPlainData(payload));
  if (!fact) throw Error("animal_fact_invalid");
  if (
    types.isProxy(events) ||
    !Array.isArray(events) ||
    Object.getPrototypeOf(events) !== Array.prototype ||
    !Object.isExtensible(events) ||
    !Object.getOwnPropertyDescriptor(events, "length")?.writable
  )
    throw Error("animal_fact_log_invalid");
  freezeFactData(fact.payload);
  const visibility = animalDreamFactAudience(fact.type),
    actorId = "actorId" in fact.payload ? fact.payload.actorId : undefined,
    event = {
      timestamp: now(),
      type: fact.type,
      payload: fact.payload,
      ...(visibility === "actor"
        ? { audience: Object.freeze([actorId!]) }
        : visibility === "god"
          ? { audience: Object.freeze([]) }
          : {}),
    } as GameEvent;
  Object.freeze(event);
  // 经数组 own data 槽发表，覆盖的 push 不能冒充发表成功。
  Object.defineProperty(events, events.length, {
    value: event,
    writable: true,
    enumerable: true,
    configurable: true,
  });
  const k = journal(world);
  if (fact.type === "animal_fox_chosen") {
    const p = fact.payload,
      old = k.fox.get(p.actorId);
    k.fox.set(p.actorId, {
      remaining: p.targetId === null ? (old?.remaining ?? 1) : 0,
      lastChoice: { day: p.day, targetId: p.targetId },
    });
  }
  if (fact.type === "animal_puffer_decided") {
    const p = fact.payload,
      old = k.puffer.get(p.actorId);
    k.puffer.set(p.actorId, {
      remaining: p.activate ? 0 : (old?.remaining ?? 1),
      lastDecision: { day: p.day, activate: p.activate },
    });
  }
  if (fact.type === "animal_cat_revealed") k.cats.add(fact.payload.actorId);
  if (fact.type === "animal_beauty_notified") {
    const { policy: _policy, day: _day, actorId, ...view } = fact.payload;
    k.beauty.set(actorId, view);
  }
}
export function animalFoxKnowledge(world: World, id: number) {
  return structuredClone(journal(world).fox.get(id) ?? { remaining: 1 as const, lastChoice: null });
}
export function animalPufferKnowledge(world: World, id: number) {
  return structuredClone(
    journal(world).puffer.get(id) ?? { remaining: 1 as const, lastDecision: null },
  );
}
export function animalCatKnowledge(world: World, id: number) {
  return { revealed: journal(world).cats.has(id) };
}
export function animalBeautyKnowledge(world: World, id: number): AnimalBeautyKnowledge {
  return structuredClone(
    journal(world).beauty.get(id) ?? {
      charmAllowed: true,
      linkAllowed: true,
      targetId: null,
      lastActedDay: null,
      history: [],
    },
  );
}
export function animalBearKnowledge(world: World) {
  return { history: structuredClone(journal(world).bear) };
}
/** BearNightFrame 真正追加公开事件后、任何后续请求前调用。 */
export function noteAnimalBearPublication(
  world: World,
  events: readonly GameEvent[],
  fromIndex: number,
): void {
  const k = journal(world);
  for (const e of events.slice(fromIndex))
    if (e.type === "bear_roared" && !k.bear.some((r) => r.day === e.payload.day))
      k.bear.push({ day: e.payload.day, roared: e.payload.roared });
}
export function appendAnimalBeautyNotice(world: World, events: GameEvent[], day: number): void {
  const actor = animalOriginalRolePlayer(world, "wolf_beauty");
  if (!actor || !actor.scope.life.alive) return;
  const state = getWolfBeautyState(actor.scope.role)!;
  appendAnimalFact(world, events, "animal_beauty_notified", {
    policy: ANIMAL_DREAM_POLICY,
    day,
    actorId: actor.scope.id,
    charmAllowed: animalBeautyCharmAllowed(world, day),
    linkAllowed: !animalBeautyLinkBlocked(world, day),
    targetId: state.targetId,
    lastActedDay: state.lastActedDay,
    history: state.history.map((row) => ({ ...row })),
  });
}
export function appendAnimalKnifeNotices(world: World, events: GameEvent[], day: number): void {
  const blocked = animalPackKnifeBlocked(world),
    snapshot = animalAuthoritySnapshot(world);
  if (!snapshot) throw Error("animal_authority_revoked");
  for (const id of world.entityIds()) {
    const actor = animalOriginalPlayer(world, id);
    if (actor?.scope.campValue === Camp.Wolf)
      appendAnimalFact(world, events, "animal_knife_notified", {
        policy: ANIMAL_DREAM_POLICY,
        day,
        actorId: id,
        eligible: !blocked,
      });
  }
}

/**
 * 负责动物梦境每次夜间执行的获取、开夜事实与终止关闭。输入为惰性委托的原 World／events、
 * 实际夜数和当前性回调；先开 authority，再标记 acquired，最后发布开夜事实。
 * 只有已获取且未正常关闭的单元才尝试 abort；发布失败保留原 authority 前缀，不退款狐狸选择、
 * 推进阶段或改变猫／河豚死亡及实际放逐单元。
 */
import type { World } from "../../../../core/domain/world";
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
import { beginAnimalNight, closeAnimalNight } from "./authority";
import { appendAnimalFact } from "./facts";

export interface AnimalNightRuntime {
  readonly world: World;
  readonly events: GameEvent[];
}
export class AnimalNightUnit {
  private acquired = false;
  private closed = false;
  constructor(
    private readonly runtime: AnimalNightRuntime,
    private readonly day: number,
  ) {}
  open(isCurrent: () => boolean): void {
    const ctx = this.runtime,
      day = this.day;
    beginAnimalNight(ctx.world, day, isCurrent);
    this.acquired = true;
    appendAnimalFact(ctx.world, ctx.events, "animal_night_opened", {
      policy: "awa_animal_dream_v1",
      day,
    });
  }
  closeNormally(): void {
    closeAnimalNight(this.runtime.world, this.day, "normal");
    this.closed = true;
  }
  abortIfOwned(): void {
    if (this.acquired && !this.closed) closeAnimalNight(this.runtime.world, this.day, "aborted");
  }
}

/**
 * 负责子狐既有夜行动与刀／魅惑通知的有序执行。
 * 输入为当前夜上下文、原 actor／scope 和 Provider 行动；输出为提交回执后的选择及效果
 * 事实，再按原阶段资格发表通知。权限与资源归动物 authority，网关校验先于回执提交。
 * 请求始终在 finally 关闭，阶段失效后不发表后续通知，不回滚已付历史。
 */
import { ANIMAL_DREAM_POLICY } from "@ai-werewolf-arena/game-contract";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { animalFoxChoiceActor, animalFoxChoiceCandidates, animalFoxEffect } from "./authority";
import {
  openAnimalRequest,
  animalRequestScope,
  readAnimalTool,
  commitAnimalRequest,
  closeAnimalRequest,
} from "./requests";
import { appendAnimalFact, appendAnimalKnifeNotices, appendAnimalBeautyNotice } from "./facts";
export const ANIMAL_FOX_STAGE: NightStageHandler = {
  id: "fox_distract",
  priority: 150,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = animalFoxChoiceActor(ctx.world, day);
    if (actorId !== null) {
      const request = ctx.makeRequest(actorId, ["fox_distract"], {
          stage: "fox_distract",
          requiresAction: true,
          allow_fallback: false,
          action_failure_policy: "error",
          fox_candidates: animalFoxChoiceCandidates(ctx.world, day),
        }),
        scope = openAnimalRequest(ctx.world, request);
      try {
        const raw = await ctx.actionProvider.getAction(request),
          call = readAnimalTool(raw);
        if (animalRequestScope(ctx.world, request) !== scope || call?.name !== "fox_distract")
          throw Error("animal_required_action_invalid");
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, call, {
          phase: Phase.Night,
          day,
          animalScope: scope,
          deferOperation: true,
        });
        if (!valid.ok || !valid.sanitizedCall) throw Error("animal_required_action_invalid");
        const receipt = commitAnimalRequest(ctx.world, scope, valid.sanitizedCall);
        if (!("targetId" in receipt)) throw Error("animal_receipt_invalid");
        appendAnimalFact(ctx.world, ctx.events, "animal_fox_chosen", {
          policy: ANIMAL_DREAM_POLICY,
          actorId,
          ...receipt,
        });
        const effect = animalFoxEffect(ctx.world);
        if (effect)
          appendAnimalFact(ctx.world, ctx.events, "animal_fox_effect", {
            policy: ANIMAL_DREAM_POLICY,
            actorId,
            ...effect,
          });
      } finally {
        closeAnimalRequest(scope);
      }
    }
    if (!ctx.isCurrent()) throw Error("animal_night_revoked");
    appendAnimalKnifeNotices(ctx.world, ctx.events, day);
    appendAnimalBeautyNotice(ctx.world, ctx.events, day);
  },
};

