/**
 * 负责觉醒隐狼的工具资格校验贡献。输入为原工具参数、角色状态及可信窗口，输出原规则拒绝或通过。
 * 当前原体、学习／盾／刀资格仍归实际机制，本校验不执行学习、消费库存或提交死亡。
 */
import { AWAKENED_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { isAliveTarget, type ToolRule, type ToolRuleMap } from "../../validation/contracts";
import { canAwakenedKnife } from "./inheritance";
import { currentAwakenedNight } from "./night_scope";
import {
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  getAwakenedState,
} from "./state";

const validateAwakened: ToolRule = ({ world, actorId, role, phase, day, toolCall }) => {
  const state = getAwakenedState(role);
  if (
    role.role !== Role.AwakenedHiddenWolf ||
    world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf ||
    !state ||
    day === undefined ||
    currentAwakenedNight(world, role) !== day ||
    isRoleExecutionRetired(role)
  )
    return { code: RuleError.AwakenedUnavailable };
  // 这是未付款工具预检；墓碑只拒绝新动作，已付效果和知识读器不用这张规则表。
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "awakened_mimic") {
    if (!canAwakenedMimic(state, day)) return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  const skill = awakenedSkillForNight(state, day);
  if (toolCall.name === "awakened_attack") {
    if (!canAwakenedKnife(role, world, () => world.getComponent(actorId, COMPONENT.Camp)) || !canAwakenedExtraKnife(state, day))
      return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  if (toolCall.name === "awakened_poison" && skill?.kind === "poison")
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  if (toolCall.name === "awakened_guard" && skill?.kind === "guard") {
    if (toolCall.args.target_id !== null && !isAliveTarget(world, toolCall.args.target_id))
      return { code: RuleError.AwakenedTarget };
    if (
      toolCall.args.target_id !== null &&
      skill.lastTarget === toolCall.args.target_id &&
      skill.lastGuardDay === day - 1
    )
      return { code: RuleError.AwakenedGuardRepeat };
    return null;
  }
  return { code: RuleError.AwakenedUnavailable };
};
export { AWAKENED_TOOL_NAMES } from "./tool_names";
export const AWAKENED_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  AWAKENED_TOOL_NAMES.map((name) => [name, validateAwakened]),
);

/**
 * 负责觉醒隐狼的学习模板、所属槽安装、激活／技能资源提交和玩家投影。输入为原角色、状态与实际夜；
 * 输出保留激活、技能和原存储引用，公开 DTO 类型独立归公共契约。
 * 未付提交可传捕获拒绝回调，在原 getter／参数读取后且首写前调用；无回调仍是原纯数据转换，不授予行动。
 * 只写 awakened_hidden_wolf 及其学习资源，不扩大角色容器写权、重抽模板、退款或授予请求许可。
 * 激活与主动技能生效夜分别保存；次数／关窗和字段提交保持原顺序，失败保留已写前缀。
 */
import type {
  AwakenedSkill,
  AwakenedActiveSkill,
  AwakenedTemplateRole,
  AwakenedLearning,
  AwakenedState,
  AwakenedReadSkill,
  AwakenedReadActiveSkill,
  AwakenedReadLearning,
  AwakenedReadState,
} from "@ai-werewolf-arena/game-contract";

import type { PlayerAwakenedState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { RoleId } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "../../../../core/domain/identity";
import { copyAbilityData } from "../abilities";
import { createLearnedNativeGun, armAwakenedNativeGun } from "../native-death-gun-resources";

const validDay = (day: number) =>
  Number.isSafeInteger(day) && day >= 1 && day < Number.MAX_SAFE_INTEGER;
const validTarget = (id: number) => Number.isSafeInteger(id) && id >= 1;
export function freshAwakenedState(): AwakenedState {
  return {
    learned: null,
    mimicClosedDay: null,
    skillClosedDay: null,
    hasInheritedKnife: false,
    firstKnifeNight: null,
  };
}
export function getAwakenedState(role: RoleComponent | undefined): AwakenedReadState | undefined {
  return (
    role as { readonly privateState: { readonly awakened_hidden_wolf?: unknown } } | undefined
  )?.privateState.awakened_hidden_wolf as AwakenedReadState | undefined;
}
/** 复制数据后安装到原私有槽；请求许可和原体证明另有所有者，不随此数据复制。 */
export function setAwakenedState(role: RoleComponent, state: AwakenedState): AwakenedReadState {
  const owned = copyAbilityData(state);
  (role.privateState as { awakened_hidden_wolf: AwakenedState }).awakened_hidden_wolf = owned;
  return owned;
}

export function awakenedLearning(targetId: EntityId, role: RoleId, day: number): AwakenedLearning {
  if (!validDay(day) || !validTarget(targetId)) throw new Error("awakened_learning_input_invalid");
  let skill: AwakenedSkill;
  switch (role) {
    case "villager":
      skill = { kind: "villager" };
      break;
    case "mirror_girl":
      skill = { kind: "inspection", abilityId: null };
      break;
    case "witch":
      skill = { kind: "poison", remaining: 1 };
      break;
    case "guard":
      skill = { kind: "guard", lastTarget: null, lastGuardDay: null };
      break;
    case "hunter":
      skill = createLearnedNativeGun();
      break;
    case "wolf":
      skill = { kind: "wolf", extraKnife: "available" };
      break;
    default:
      throw new Error("awakened_learning_role_not_supported");
  }
  return { targetId, role, day, activationNight: null, activeFromNight: null, skill };
}
export function canAwakenedMimic(state: AwakenedReadState, day: number): boolean {
  return (
    validDay(day) &&
    state.learned === null &&
    (state.mimicClosedDay === null || state.mimicClosedDay < day)
  );
}
export function closeAwakenedMimic(state: AwakenedReadState, day: number, mayCommit?: () => boolean): boolean {
  if (!canAwakenedMimic(state, day)) return false;
  if (mayCommit && !mayCommit()) return false;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}
export function learnAwakenedRole(
  state: AwakenedReadState,
  targetId: EntityId,
  role: RoleId,
  day: number,
  mayCommit?: () => boolean,
): boolean {
  if (!canAwakenedMimic(state, day)) return false;
  const learned = awakenedLearning(targetId, role, day);
  if (mayCommit && !mayCommit()) return false;
  (state as { learned: AwakenedReadState["learned"] }).learned = learned;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

/** 只在实际夜末提交激活；选择模板或进入以后日次不会补造激活夜。 */
export function activateAwakenedLearning(
  state: AwakenedReadState,
  night: number,
  mirrorAbilityId?: string,
): boolean;
export function activateAwakenedLearning(
  state: AwakenedReadState,
  night: number,
  mirrorAbilityId: string | undefined,
  mayCommit: (() => boolean) | undefined,
): boolean | "retired";
export function activateAwakenedLearning(
  state: AwakenedReadState,
  night: number,
  mirrorAbilityId?: string,
  mayCommit?: () => boolean,
): boolean | "retired" {
  const learned = state.learned;
  if (!learned || !validDay(night) || night < learned.day || learned.activationNight !== null)
    return false;
  if (
    learned.skill.kind === "inspection" &&
    (typeof mirrorAbilityId !== "string" || !mirrorAbilityId.length)
  )
    return false;
  if (learned.skill.kind !== "inspection" && mirrorAbilityId !== undefined) return false;
  // 仅首写前调用捕获拒绝条件；一旦字段／武装提交，后续激活字段不再被墓碑取消。
  let committed = false;
  const firstWrite = () => {
    if (committed) return true;
    if (mayCommit && !mayCommit()) return false;
    committed = true;
    return true;
  };
  if (learned.skill.kind === "inspection") {
    const skill = learned.skill as { abilityId: string | null };
    if (!firstWrite()) return "retired";
    skill.abilityId = mirrorAbilityId!;
  }
  if (mayCommit) {
    if (!armAwakenedNativeGun(learned, firstWrite)) return "retired";
  } else armAwakenedNativeGun(learned);
  if (!firstWrite()) return "retired";
  (learned as { activationNight: number | null }).activationNight = night;
  (learned as { activeFromNight: number | null }).activeFromNight = night + 1;
  return true;
}

/** 被动猎人枪的可用性从枪自身读取；主动技能要在实际激活后的生效夜查询。 */
export function awakenedSkillForNight(
  state: AwakenedReadState,
  night: number,
): AwakenedReadActiveSkill | undefined {
  const learned = state.learned;
  if (
    !validDay(night) ||
    !learned ||
    learned.activationNight === null ||
    learned.activeFromNight === null ||
    night < learned.activeFromNight ||
    (state.skillClosedDay !== null && state.skillClosedDay >= night)
  )
    return undefined;
  if (learned.skill.kind === "poison" && learned.skill.remaining === 0) return undefined;
  if (learned.skill.kind === "wolf" && learned.skill.extraKnife === "spent") return undefined;
  return learned.skill.kind === "poison" ||
    learned.skill.kind === "guard" ||
    learned.skill.kind === "wolf"
    ? learned.skill
    : undefined;
}
export function closeAwakenedSkill(state: AwakenedReadState, night: number, mayCommit?: () => boolean): boolean {
  if (!awakenedSkillForNight(state, night)) return false;
  if (mayCommit && !mayCommit()) return false;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

/** 装配／死亡检查点一次提交继承；它不依赖学习或技能选择，不消费学习资源。 */
export function recordAwakenedInheritance(state: AwakenedReadState, day: number): boolean {
  if (!validDay(day) || state.hasInheritedKnife) return false;
  (state as { hasInheritedKnife: boolean }).hasInheritedKnife = true;
  (state as { firstKnifeNight: number | null }).firstKnifeNight = Math.max(2, day + 1);
  return true;
}
export function awakenedKnifeReady(state: AwakenedReadState, night: number): boolean {
  return (
    validDay(night) &&
    state.hasInheritedKnife &&
    state.firstKnifeNight !== null &&
    night >= state.firstKnifeNight
  );
}
/** 调用方还核对当前原持有者与唯一活狼许可；这里的字段条件不单独授予刀权。 */
export function canAwakenedExtraKnife(state: AwakenedReadState, night: number): boolean {
  const skill = awakenedSkillForNight(state, night);
  return (
    awakenedKnifeReady(state, night) && skill?.kind === "wolf" && skill.extraKnife === "available"
  );
}
/** 空刀只关闭本夜机会；实际非空攻击才花费整局一次的额外刀库存。 */
export function chooseAwakenedAttack(
  state: AwakenedReadState,
  targetId: EntityId | null,
  night: number,
  mayCommit?: () => boolean,
): boolean {
  if (!canAwakenedExtraKnife(state, night) || (targetId !== null && !validTarget(targetId)))
    return false;
  const skill = state.learned!.skill;
  if (skill.kind !== "wolf") return false;
  if (mayCommit && !mayCommit()) return false;
  if (targetId !== null) (skill as { extraKnife: "available" | "spent" }).extraKnife = "spent";
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

export function chooseAwakenedGuard(
  state: AwakenedReadState,
  targetId: EntityId | null,
  night: number,
  mayCommit?: () => boolean,
): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (
    skill?.kind !== "guard" ||
    (targetId !== null && !validTarget(targetId)) ||
    (targetId !== null && skill.lastTarget === targetId && skill.lastGuardDay === night - 1)
  )
    return false;
  if (mayCommit && !mayCommit()) return false;
  (skill as { lastTarget: EntityId | null }).lastTarget = targetId;
  (skill as { lastGuardDay: number | null }).lastGuardDay = night;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}
/** 合法的无工具等待也按空目标结束本夜守护，打断连续守同一编号的历史。 */
export function skipAwakenedSkill(state: AwakenedReadState, night: number, mayCommit?: () => boolean): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (!skill) return false;
  if (skill.kind === "guard") return chooseAwakenedGuard(state, null, night, mayCommit);
  if (skill.kind === "wolf") return chooseAwakenedAttack(state, null, night, mayCommit);
  return closeAwakenedSkill(state, night, mayCommit);
}
export function useAwakenedPoison(state: AwakenedReadState, night: number, mayCommit?: () => boolean): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (skill?.kind !== "poison" || skill.remaining !== 1) return false;
  // 库存 getter 先完成，未付拒绝在 remaining 首写前；付款后仍完成原关闭字段。
  if (mayCommit && !mayCommit()) return false;
  (skill as { remaining: 0 | 1 }).remaining = 0;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

/** 只投影列出的玩家字段；魔镜查验历史与库存由其能力实例唯一拥有，不复制进学习模板。 */
export function projectAwakenedState(state: AwakenedReadState): PlayerAwakenedState {
  const learned = state.learned;
  let skill: AwakenedSkill | undefined;
  if (learned)
    switch (learned.skill.kind) {
      case "villager":
        skill = { kind: "villager" };
        break;
      case "inspection":
        skill = { kind: "inspection", abilityId: learned.skill.abilityId };
        break;
      case "poison":
        skill = { kind: "poison", remaining: learned.skill.remaining };
        break;
      case "guard":
        skill = {
          kind: "guard",
          lastTarget: learned.skill.lastTarget,
          lastGuardDay: learned.skill.lastGuardDay,
        };
        break;
      case "hunter":
        skill = { kind: "hunter", armed: learned.skill.armed, canShoot: learned.skill.canShoot };
        break;
      case "wolf":
        skill = { kind: "wolf", extraKnife: learned.skill.extraKnife };
        break;
    }
  return {
    learned:
      learned && skill
        ? {
            targetId: learned.targetId,
            role: learned.role,
            day: learned.day,
            activationNight: learned.activationNight,
            activeFromNight: learned.activeFromNight,
            skill,
          }
        : null,
    mimicClosedDay: state.mimicClosedDay,
    skillClosedDay: state.skillClosedDay,
    hasInheritedKnife: state.hasInheritedKnife,
    firstKnifeNight: state.firstKnifeNight,
  };
}

/**
 * 负责列出觉醒隐狼的静态工具名。输入为类型层工具名约束；输出为原有序名称数组。
 * 数组的只读类型不等于运行冻结，也不持角色状态、库存、请求绑定或执行权限。
 */
import type { ToolName } from "../../../../core/domain/model";

/** 静态名称不依赖运行私态；具体技能可用性仍由实际实例和阶段判断。 */
export const AWAKENED_TOOL_NAMES = [
  "awakened_mimic",
  "awakened_poison",
  "awakened_guard",
  "awakened_attack",
] as const satisfies readonly ToolName[];

/**
 * 负责熊的夜间采样 frame 与延迟到天亮的发布。阵营只读实际 Camp；默认只核值，黎明政策保原组件引用撤权。输入为原相邻玩家和采样吼声；只有匹配原 frame 时才产生历史与天亮事件。不重复发布同一夜，不以复活或替换相邻身体继续旧采样；关闭和失败保持原前缀。
 */
import {
  recordBearRoar,
  bearDataField as ownData,
  bearDataArrayAppendable as appendable,
  bearHistoryUnpublished as unpublishedHistory,
  recordDawnBearRoar,
} from "./state";

import type { BearReadState as BearState } from "@ai-werewolf-arena/game-contract";

import {
  AliveComponent,
  aliveLifeVersion,
  aliveLifeDescriptor,
} from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { IdentityComponent } from "../../../../core/domain/entities/player";
import { Camp, Role, type GameEvent, type EntityId } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { RoleCatalog } from "../catalog";
import { getDefaultRoleCatalog } from "../role-catalog-assembly";
import { getBearState } from "./state";
import { BEAR_SIGNAL_POLICIES, type BearSignalPolicy } from "@ai-werewolf-arena/game-contract";
import {
  captureOriginalPlayer,
  originalPlayerSameLife,
  type OriginalPlayerScope,
} from "../original_player_scope";
import type { CampComponent } from "../../../../core/domain/components/camp";
/** 同一 World／夜号的黎明发表状态：checking 只允许当前尝试，重入会撤销它；
 * 成功后 published，未完成则 finally 置 revoked。清空原 state.history 不恢复这一原发布许可。 */
const dawnPublications = new WeakMap<
  World,
  Map<number, { status: "checking" | "published" | "revoked" }>
>();
const now = Date.now.bind(Date);

function sampleRoar(world: World, actorId: EntityId, catalog: RoleCatalog): boolean {
  const ring = world
      .getAliveEntityIds()
      .sort(
        (a, b) =>
          (world.getComponent(a, COMPONENT.Identity)?.seat ?? a) -
            (world.getComponent(b, COMPONENT.Identity)?.seat ?? b) || a - b,
      ),
    index = ring.indexOf(actorId),
    neighbors =
      index < 0 || ring.length < 2
        ? []
        : [
            ...new Set([
              ring[(index + ring.length - 1) % ring.length],
              ring[(index + 1) % ring.length],
            ]),
          ];
  return neighbors.some((id) => {
    const target = world.getComponent(id, COMPONENT.Role);
    return (
      !!target && world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf &&
      (catalog.runtime(target.role)?.detectableByBear?.(world, target) ?? true)
    );
  });
}

/** 快照由 manager 持有，不放在玩家 component 或 DTO 中。 */
export class BearNightFrame {
  /** 保留原 World、Role、state、Alive／Camp 与名单的实例引用及生命版本，不克隆为玩家 DTO。
   * 默认政策捕获夜初吼声；显式黎明政策保留原体名单和 catalog，在真正发表时才重新采样并复验。 */
  private constructor(
    private readonly owner: World,
    private readonly day: number,
    private readonly actorId: EntityId,
    private readonly role: RoleComponent,
    private readonly state: BearState,
    private readonly life: AliveComponent,
    private readonly lifeVersion: number,
    private readonly wasAlive: boolean,
    private readonly sampledRoar: boolean,
    private readonly signalPolicy: BearSignalPolicy,
    private readonly catalog: RoleCatalog,
    private readonly originals: readonly OriginalPlayerScope[],
    private readonly camp: CampComponent | undefined,
  ) {}

  static capture(
    world: World,
    day: number,
    catalog: RoleCatalog = getDefaultRoleCatalog(),
    signalPolicy: BearSignalPolicy = "awa_night_open_v1",
  ): BearNightFrame | null {
    if (!BEAR_SIGNAL_POLICIES.includes(signalPolicy)) throw Error("bear_signal_policy_invalid");
    const bears = world
      .entityIds()
      .filter((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Bear);
    if (bears.length > 1) throw new Error("bear_count_exceeds_limit");
    const actorId = bears[0];
    if (actorId === undefined) return null;
    const role = world.getComponent(actorId, COMPONENT.Role)!,
      state = getBearState(role),
      life = world.getComponent(actorId, COMPONENT.Alive),
      version = life && aliveLifeVersion(life);
    if (world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good || !state || !life || version === undefined) return null;
    const originals =
        signalPolicy === "netease_dawn_live_v1"
          ? world.getAliveEntityIds().map((id) => captureOriginalPlayer(world, id))
          : [],
      camp = world.getComponent(actorId, COMPONENT.Camp);
    if (
      originals.some((p) => p === null) ||
      (signalPolicy === "netease_dawn_live_v1" && camp?.camp !== Camp.Good)
    )
      return null;
    const roared =
      signalPolicy === "awa_night_open_v1" ? sampleRoar(world, actorId, catalog) : false;
    return new BearNightFrame(
      world,
      day,
      actorId,
      role,
      state,
      life,
      version,
      life.alive,
      roared,
      signalPolicy,
      catalog,
      originals as OriginalPlayerScope[],
      camp,
    );
  }

  /** 完整夜死亡波后、该波判胜前发表。 */
  publish(world: World, events: GameEvent[], isCurrent: () => boolean): void {
    if (this.signalPolicy === "netease_dawn_live_v1") {
      this.publishDawn(world, events, isCurrent);
      return;
    }
    if (
      world !== this.owner ||
      !isCurrent() ||
      world.getComponent(this.actorId, COMPONENT.Role) !== this.role ||
      this.role.role !== Role.Bear ||
      world.getComponent(this.actorId, COMPONENT.Camp)?.camp !== Camp.Good ||
      getBearState(this.role) !== this.state ||
      world.getComponent(this.actorId, COMPONENT.Alive) !== this.life ||
      aliveLifeVersion(this.life) !==
        this.lifeVersion + (this.wasAlive && !this.life.alive ? 1 : 0) ||
      this.state.history.some((report) => report.day === this.day)
    )
      return;
    const report = { day: this.day, roared: this.life.alive && this.wasAlive && this.sampledRoar };
    recordBearRoar(this.state, report);
    events.push({ timestamp: Date.now(), type: "bear_roared", payload: { ...report } });
  }
  private dawnBodyCurrent(world: World): boolean {
    const factory = aliveLifeDescriptor(this.life);
    if (!factory) return false;
    const actual = Object.getOwnPropertyDescriptor(this.life, "alive"),
      history = ownData(this.state, "history");
    return (
      actual?.get === factory.get &&
      actual?.set === factory.set &&
      world.getComponent(this.actorId, COMPONENT.Role) === this.role &&
      ownData(this.role, "role") === Role.Bear &&
      ownData(this.camp, "camp") === Camp.Good &&
      ownData(ownData(this.role, "privateState"), "bear") === this.state &&
      world.getComponent(this.actorId, COMPONENT.Alive) === this.life &&
      aliveLifeVersion(this.life) ===
        this.lifeVersion + (this.wasAlive && !this.life.alive ? 1 : 0) &&
      world.getComponent(this.actorId, COMPONENT.Camp) === this.camp &&
      ownData(this.camp, "camp") === Camp.Good &&
      this.originals.every((p) => originalPlayerSameLife(world, p, true)) &&
      world.getAliveEntityIds().every((id) => this.originals.some((p) => p.id === id)) &&
      unpublishedHistory(history, this.day)
    );
  }
  private publishDawn(world: World, events: GameEvent[], isCurrent: () => boolean): void {
    if (world !== this.owner) return;
    let publications = dawnPublications.get(world);
    if (!publications) {
      publications = new Map();
      dawnPublications.set(world, publications);
    }
    const prior = publications.get(this.day);
    if (prior) {
      if (prior.status === "checking") prior.status = "revoked";
      return;
    }
    const lease: { status: "checking" | "published" | "revoked" } = { status: "checking" };
    publications.set(this.day, lease);
    try {
      if (!isCurrent() || !this.dawnBodyCurrent(world)) return;
      const before = this.originals.map((p) => ({
          p,
          version: aliveLifeVersion(p.life),
          identity: world.getComponent(p.id, COMPONENT.Identity),
          seat: ownData(world.getComponent(p.id, COMPONENT.Identity), "seat"),
        })),
        sampled =
          this.life.alive && this.wasAlive ? sampleRoar(world, this.actorId, this.catalog) : false;
      if (
        !isCurrent() ||
        lease.status !== "checking" ||
        !this.dawnBodyCurrent(world) ||
        before.some(
          ({ p, version, identity, seat }) =>
            aliveLifeVersion(p.life) !== version ||
            world.getComponent(p.id, COMPONENT.Identity) !== identity ||
            ownData(identity, "seat") !== seat,
        )
      )
        return;
      const history = ownData(this.state, "history");
      if (history === events || !appendable(history) || !appendable(events)) return;
      const report = { day: this.day, roared: this.life.alive && this.wasAlive && sampled },
        event: GameEvent = { timestamp: now(), type: "bear_roared", payload: { ...report } };
      // 两个原受控数组按事件→历史写入；原生 defineProperty 不执行数组元素 setter。
      // 这不是事务：第二次写抛错时第一事件保留，finally 只撤销尚 checking 的发布状态，不回滚数组。
      Object.defineProperty(events, String(events.length), {
        value: event,
        enumerable: true,
        writable: true,
        configurable: true,
      });
      recordDawnBearRoar(history, report);
      lease.status = "published";
    } finally {
      if (lease.status === "checking") lease.status = "revoked";
    }
  }
}

/**
 * 负责 熊 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数与角色组件；输出为角色资料、配置解析、初始化和展示标识四项贡献，保留原引用与顺序。
 * 展示只登记 bear 标识，实际玩家知识投影归共同观察所有者；本模块不读取动物板知识、授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { BEAR_SIGNAL_POLICIES } from "@ai-werewolf-arena/game-contract";
import { Camp, Role } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { initializeBearState } from "./state";
const parameters = z.strictObject({ signalPolicy: z.enum(BEAR_SIGNAL_POLICIES).optional() });

export const BEAR_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Bear,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("bear"),
    skillBrief: text("zh-CN", "role.bear.brief"),
  },
  runtime: {
    init: initializeBearState,
    configuration: {
      schema: parameters,
      defaults: {},
      apply: (config, value) => {
        const p = parameters.parse(value);
        return p.signalPolicy ? { ...config, bear: { signalPolicy: p.signalPolicy } } : config;
      },
      serialize: (config) => parameters.parse(config.bear ?? {}),
    },
  },
  presentation: nativeRolePresentation("bear"),
};

/**
 * 负责熊的数据初始化、原私有槽读取／安装、两种历史写入及玩家投影；输入为原角色／状态／报告，安装和读取返回原引用，写入无返回值，玩家投影返回报告副本。
 * 状态安装先赋原槽再返回，读取只是类型断言，不执行 schema／Proxy／当前性检查或深冻结。
 * 数据契约属于共享包，名单、生命、实际吼叫判定、玩家知识和检查点编码仍归各实际所有者。
 * 普通发布取原 history.push；黎明受控历史写体也归本叶，事件／原体复验和发布租约仍归 frame，两种写入不合并。
 * 原安装／追加的 getter、push 或受控写失败传播；黎明历史快照查询失败沿原 false 分支，不保存镜像、退款或授予权限。
 */
import type { BearState, BearReadState } from "@ai-werewolf-arena/game-contract";

import type { PlayerBearState } from "@ai-werewolf-arena/game-contract/player-state-views";
import { playerDataField, positiveInteger, rows } from "../player-state-data";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { types } from "node:util";
import { snapshotPlainData } from "../../../../core/domain/plain_data";

/** 保留 privateState 的原 LHS 读取和同对象赋值；允许的状态形状仍由安装调用方负责。 */
export function setBearState(role: RoleComponent, state: BearState): BearReadState {
  (role.privateState as { bear: BearState })["bear"] = state;
  return state;
}

/** 返回原 live 引用；BearReadState 的 readonly 约束不代表运行时冻结或合法性验证。 */
export function getBearState(role: RoleComponent): BearReadState | undefined {
  return (role.privateState as { readonly bear?: unknown })["bear"] as BearReadState | undefined;
}

/** 普通发布先读取 history／push，再追加原报告对象；后错不回滚，黎明独立 writer 不经此命令。 */
export function recordBearRoar(state: BearReadState, report: BearState["history"][number]): void {
  (state.history as BearState["history"]).push(report);
}

/** 原初始化完整写体：先形成默认数据，再由原安装函数写同一 privateState 槽；不检查角色或创建许可。 */
export function initializeBearState(role: RoleComponent): void {
  setBearState(role, { history: [] });
}

/** 黎明数据反射保原 Node Proxy 拒绝及 own data 读取；这里只读形状，不授予 frame 许可。 */
export function bearDataField(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
/** 原黎明只接受非 Proxy、直接 Array.prototype 的数组，要求自有 length 可写、容量未满且可扩展。
 * 此检查不遍历元素、不借普通 push 的自定义行为；同一查询也用于事件数组，不提供发布权。 */
export function bearDataArrayAppendable(value: unknown): value is unknown[] {
  if (
    !Array.isArray(value) ||
    types.isProxy(value) ||
    Object.getPrototypeOf(value) !== Array.prototype
  )
    return false;
  const d = Object.getOwnPropertyDescriptor(value, "length");
  return (
    !!d?.writable &&
    Number.isSafeInteger(d.value) &&
    d.value < 4294967295 &&
    Object.isExtensible(value)
  );
}
/** 按原受控快照和本日字段判断是否尚未记录，不把不可读历史当空数组继续发表。
 * 快照或检查抛错沿原 catch 返回 false；不修改原历史、运行租约或普通 live getter 的接受面。 */
export function bearHistoryUnpublished(value: unknown, day: number): boolean {
  try {
    const rows = snapshotPlainData(value, new Set(), 0, 65536);
    return Array.isArray(rows) && !rows.some((report) => bearDataField(report, "day") === day);
  } catch {
    return false;
  }
}

/** 原 frame 已先写事件，此处再向受控 history 写原 report；不回滚首个写入或更新发布租约。 */
export function recordDawnBearRoar(
  history: unknown[],
  report: BearState["history"][number],
): void {
  Object.defineProperty(history, String(history.length), {
    value: report,
    enumerable: true,
    writable: true,
    configurable: true,
  });
}

/** 原玩家历史投影逐项读取自有 data 字段并保正整数／布尔过滤；新报告副本不替代 live 库存或黎明许可。 */
export function projectBearState(state: unknown): PlayerBearState {
  return {
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const day = playerDataField(row, "day"),
        roared = playerDataField(row, "roared");
      return positiveInteger(day) && typeof roared === "boolean" ? [{ day, roared }] : [];
    }),
  };
}

/**
 * 负责黑市商人在后置受赠行动之前选择交易。输入为原库存与已验证的技能／收货，输出为独立 gift／gun、反噬和事实。
 * 阵营保原捕获／复验点的实际 Camp 值，新请求和未付关窗／首付款之前拒绝退休源，不改变纯目标与知识名单。
 * ownerCurrent（含 paid 首死分支）保已付反噬的原身份／生命政策；Good 资源授予正常返回或 Wolf 首库存写后，
 * 其余库存、选择、记录和事实仍按原前缀完成，原异常传播且不退款，不给替换商人接续已付效果。
 */
import { closeBlackMarketTrade, recordBlackMarketTrade } from "./state";

import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule, type ToolCall } from "../../../../core/domain/model";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { grantDeathGun } from "../death_abilities";
import { recipientAbilityStage } from "../recipient_ability_stage";
import { canBlackMarketTrade, getBlackMarketState } from "./state";
const committed = new WeakMap<World, Set<number>>();
export function hasBlackMarketNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export const BLACK_MARKET_RECIPIENT_STAGE = recipientAbilityStage("black_market", 140);
export const BLACK_MARKET_TRADE_STAGE: NightStageHandler = {
  id: "black_market_merchant",
  priority: 130,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.BlackMarketMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getBlackMarketState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = (paid = false) =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.BlackMarketMerchant &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getBlackMarketState(role) === state &&
        (livingNightLife(ctx.world, life) ||
          (paid &&
            ctx.world.getComponent(actorId, COMPONENT.Alive) === life.life &&
            !life.life.alive &&
            aliveLifeVersion(life.life) === life.version + 1));
      // 先完成原体／库存的原有序复验，再否决新交易；纯 ownerCurrent 仍供已付反噬使用。
      const current = () => ownerCurrent() && canBlackMarketTrade(state, day) && !isRoleExecutionRetired(role);
      if (!current()) continue;
      const skip = () => {
        // null 或原无目标收尾都只是未付关窗；最后一次候选查询能退休源，故在关闭首写前单独拒绝。
        const closeTrade = closeBlackMarketTrade;
        if (isRoleExecutionRetired(role)) return;
        closeTrade(state, day);
        recordCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_skipped",
          payload: { actorId, day },
        });
      };
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        // 候选捕获的原 getter 已全部执行；退休源不再打开新的请求，目标名单本身不按墓碑过滤。
        if (isRoleExecutionRetired(role)) break;
        let action: ToolCall | null = null;
        if (targets.size) {
          // 保原 receiver／getAction callee → makeRequest callee → 请求实参的求值序；不提前要求原 callee 可调用。
          const provider = ctx.actionProvider,
            getAction = provider.getAction,
            makeRequest = ctx.makeRequest,
            requestArgs = [actorId, ["black_market_trade"], {
              stage: "black_market_merchant",
              requiresAction: false,
              action_failure_policy: "error",
              allow_fallback: false,
              ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
            }],
            invoke = Reflect.apply.bind(Reflect);
          // 新 Reflect／bind 查找与分配都先完成；末旗后只裸调用已准备 invoker，不再查方法属性。
          if (isRoleExecutionRetired(role)) break;
          const request = invoke(makeRequest, ctx, requestArgs), actionArgs = [request];
          // builder 已完成的请求前缀不回滚；它退休源时不再调用 provider，await 后仍走原 current。
          if (isRoleExecutionRetired(role)) break;
          action = await invoke(getAction, provider, actionArgs);
        }
        if (!current()) break;
        if (action === null) {
          skip();
          completed = true;
          break;
        }
        if (action.name !== "black_market_trade") continue;
        const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !validated.ok || validated.sanitizedCall?.name !== "black_market_trade")
          continue;
        const { target_id: targetId, skill } = validated.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        if (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
          throw new Error("black_market_target_camp_unsupported");
        const failed = target.camp === Camp.Wolf;
        // 原目标 getter／unsupported-Camp 错误仍先发生；只在 Wolf 首付或 Good 资源授予之前拒绝退休源。
        if (isRoleExecutionRetired(role)) break;
        if (!failed) {
          if (skill === "gun") {
            const grant = grantDeathGun,
              grantArgs: Parameters<typeof grantDeathGun> = [ctx.world, actorId, targetId, day, ctx.events],
              grantWorld = grantArgs[0], grantActor = grantArgs[1], grantTarget = grantArgs[2],
              grantDay = grantArgs[3], grantEvents = grantArgs[4];
            // 五个原实参含 World／events 的 getter 均先执行；源退休时不让另一 World 的 common 校验代替本旗。
            if (isRoleExecutionRetired(role)) break;
            grant(grantWorld, grantActor, grantTarget, grantDay, grantEvents);
          }
          else {
            const base = {
              id: "gift:black-market",
              activation: "black_market" as const,
              source: { kind: "gift" as const, actorId },
              sourceDisclosed: false,
              startsOnDay: day + 1,
              maxUses: 1,
            };
            if (skill === "check") {
              const grant = grantNightAbility,
                grantArgs: Parameters<typeof grantNightAbility<"seer_check">> = [
                  ctx.world,
                  targetId,
                  {
                    ...base,
                    kind: "seer_check",
                    state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
                  },
                  ctx.events,
                ],
                grantWorld = grantArgs[0], grantTarget = grantArgs[1], grantInput = grantArgs[2], grantEvents = grantArgs[3];
              // 原 callee 与全部 World／payload／events 实参已经求值；共同资源 owner 不能替代本阶段捕获源的末拒绝。
              if (isRoleExecutionRetired(role)) break;
              grant(grantWorld, grantTarget, grantInput, grantEvents);
            } else {
              const grant = grantNightAbility,
                grantArgs: Parameters<typeof grantNightAbility<"potion">> = [
                  ctx.world,
                  targetId,
                  {
                    ...base,
                    kind: "potion",
                    state: {
                      heal: 0,
                      poison: 1,
                      selfHealRule: WitchSelfHealRule.Disabled,
                      canSelfHeal: false,
                      healUsedThisNight: false,
                      poisonUsedThisNight: false,
                    },
                  },
                  ctx.events,
                ],
                grantWorld = grantArgs[0], grantTarget = grantArgs[1], grantInput = grantArgs[2], grantEvents = grantArgs[3];
              // 原 callee 与全部 World／payload／events 实参已经求值；共同资源 owner 不能替代本阶段捕获源的末拒绝。
              if (isRoleExecutionRetired(role)) break;
              grant(grantWorld, grantTarget, grantInput, grantEvents);
            }
          }
        }
        // Good gift／gun 正常返回后不再加墓碑；晚退休不能取消商人库存与已付反噬／通知完成前缀。
        const recordTrade = recordBlackMarketTrade;
        if (failed && isRoleExecutionRetired(role)) break;
        recordTrade(state, day, targetId, skill);
        recordCommit(ctx.world, day);
        const choice = state.choice!;
        if (failed)
          (ctx.state.blackMarketBacklashes ??= []).push({
            target: life,
            isCurrent: () =>
              ownerCurrent(true) &&
              state.choice === choice &&
              choice.day === day &&
              choice.targetId === targetId &&
              choice.skill === skill,
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failed ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) {
        if (ctx.world.getAliveEntityIds().some((id) => id !== actorId))
          throw new Error("black_market_valid_action_missing");
        skip();
      }
    }
  },
};

/**
 * 负责 黑市商人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import {
  getBlackMarketState,
  freshBlackMarketState,
  setBlackMarketState,
  projectBlackMarketState,
  canBlackMarketTrade,
} from "./state";
import { BLACK_MARKET_TRADE_STAGE, BLACK_MARKET_RECIPIENT_STAGE } from "./night_stage";
export const BLACK_MARKET_MERCHANT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.BlackMarketMerchant,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("black_market_merchant"),
    skillBrief: text("zh-CN", "role.black_market_merchant.brief"),
