  return choice;
}
export function closeDemonHunterTurn(scope: object): void {
  const t = turns.get(scope);
  if (t && t.night.turn === t) t.night.turn = null;
  settleRequestDelivery(scope, false);
}
/** 只由引擎实际选择派生，不从已记录的取消事实重建。 */
