 * Node 快照只在原入口拒绝外来 descriptor／Proxy，校验副本不替换运行槽；公共纯结构仍归契约包。
 * 原下一历史先编码，再 push 和更新 JSON；后续 actor 审计、夜选择、请求结算和 stock 写权仍归 authority。
 * 此 owner 不建镜像／第二 WeakMap、不冻结 live 数据或把类型／查询当许可；失败保原部分写入前缀。
 */
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core";
import { DEMON_HUNTER_POLICY, readDemonHunterState as readState, readDemonHuntTool as readTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
import type { DemonHunterState, DemonHuntTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
export { DEMON_HUNTER_POLICY };
export const DEMON_HUNTER_ROLE = "demon_hunter" as const;
export function ownDemonData(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  return descriptor && "value" in descriptor ? descriptor.value : undefined;
}
export function demonSnapshot(
  value: unknown,
  seen = new Set<object>(),
  depth = 0,
  arrayLimit = 256,
): unknown {
  return snapshotPlainData(value, seen, depth, arrayLimit, "demon_hunter_data_invalid");
}
export function demonJson(value: unknown): string | null {
  try {
    return JSON.stringify(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function exactDemonData(
  value: unknown,
  keys: readonly string[],
): value is Record<string, unknown> {
  return (
    !!value &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === keys.length &&
    keys.every((key) => Object.hasOwn(value, key))
  );
}
export function freshDemonHunterState(): DemonHunterState {
  return { policy: DEMON_HUNTER_POLICY, history: [] };
}
export function readDemonHunterState(value: unknown): DemonHunterState | null {
  try {
    return readState(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function getDemonHunterState(role: RoleComponent | undefined): DemonHunterState | undefined {
  const s = ownDemonData(ownDemonData(role, "privateState"), "demonHunter");
  // 复制只用于验证；成功后仍返回原 slot，不能让查询生成第二份 live 状态。
  return readDemonHunterState(s) ? (s as DemonHunterState) : undefined;
}
export function readDemonHuntTool(value: unknown): DemonHuntTool | null {
  try {
    return readTool(demonSnapshot(value));
  } catch {
    return null;
  }
}

/** 唯一 live state／history 和已提交 JSON 留在原 binding 对象，不复制第二份运行库存。 */
export interface DemonHunterStateSlot {
  state: DemonHunterState;
  history: DemonHunterState["history"];
  historyJson: string;
}

/** 初始化仍先求值左侧 privateState，再调用原 creator；没有 schema、授权或新冻结。 */
export function installDemonHunterStateSlot(role: RoleComponent): void {
  (role.privateState as { demonHunter: DemonHunterState }).demonHunter = freshDemonHunterState();
}

/** 原安装字段依次取 state、history，再给空历史 JSON；临时返回对象不成为第二份 live store。 */
export function captureDemonHunterStateSlot(state: DemonHunterState): DemonHunterStateSlot {
  return { state, history: state.history, historyJson: "[]" };
}

/** 数据当前性保持原历史引用优先、已校验历史 JSON 后查；原参与者与 World alias 仍由 authority 核对。 */
export function demonHunterHistoryCurrent(b: DemonHunterStateSlot, state: DemonHunterState): boolean {
  return ownDemonData(b.state, "history") === b.history && demonJson(state.history) === b.historyJson;
}

/**
 * 完整原历史写命令。各 history 与 n.day 均在原表达式处读取；不提前缓存夜时钟。
 * 下一历史 JSON 失败时尚未 push；push 后再写 historyJson，后续抛错保留原历史写入前缀。
 * 返回原冻结 choice；actor.auditPrivateJson、n.choice／turn 和请求结算必须仍由 authority 随后按原序提交。
 */
export function appendDemonHunterChoiceData(
  b: DemonHunterStateSlot,
  n: { readonly day: number },
  targetId: number | null,
): Readonly<DemonHunterState["history"][number]> | null {
  const length = Object.getOwnPropertyDescriptor(b.history, "length");
  if (!length?.writable || !Object.isExtensible(b.history) || (b.history.at(-1)?.day ?? 1) >= n.day)
    return null;
  const choice = Object.freeze({ day: n.day, targetId });
  const nextHistoryJson = demonJson([...b.history, choice]);
  if (nextHistoryJson === null) return null;
  b.history.push(choice);
  b.historyJson = nextHistoryJson;
  return choice;
}

/**
 * 负责一夜摄梦关系的原生命查询、保护及追加死亡闭包。输入为原 links、已付庇护和当前性回调，
 * 输出为目标、伤害扩展及事件；同一实例唯一持有 reasons／emitted，不复制关系或重新支付效果。
 * 运行接口区分查询和更新：连续／关联推导累计原因，expand 写调用方伤害，record 写去重与 events。
 * 原组件引用、回调和接收方保持，句柄不进入玩家知识或录制；本模块不标死、授予请求或推进阶段。
 */
import type { DreamNightEffects } from "../../../../core/domain/dream-night-effects";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { DeathCause, type EntityId, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import type { DamageResolutionResult } from "../../../../core/domain/systems/damage_resolution_system";
import type { NightImmunityClaim } from "../../../../core/domain/night_effects";

/**
 * 本夜关系持原行动者／目标组件引用与当时捕获版本；可选回调仍归已付效果所有者。
 * 字段和嵌套对象未深冻结，Frame 沿同数组读取；这些运行引用不是可序列化数据或行动许可。
 */
export interface DreamNightLink {
  actorId: EntityId;
  targetId: EntityId;
  day: number;
  abilityId?: string;
  consecutive: boolean;
  isCurrent?: () => boolean;
  protectionPolicy?: import("../../../../core/domain/board").DreamProtectionPolicy;
  actorLife: AliveComponent;
  actorVersion: number | undefined;
  targetLife: AliveComponent;
  targetVersion: number | undefined;
}
type DreamReason = Extract<GameEvent, { type: "dream_death" }>["payload"];
const committedNights = new WeakMap<World, Set<number>>();
export function markDreamNightCommitted(world: World, day: number): void {
  const days = committedNights.get(world) ?? new Set<number>();
  days.add(day);
  committedNights.set(world, days);
}
export function hasDreamNightCommit(world: World, day: number): boolean {
  return committedNights.get(world)?.has(day) === true;
}

/** 一夜效果保持同一运行实例；接口不把私有原因、去重或原生命结构变成 JSON 数据。 */
export class DreamNightFrame implements DreamNightEffects {
  private readonly reasons = new Map<EntityId, DreamReason[]>();
  private readonly emitted = new Set<string>();
  private readonly shelters: readonly NightImmunityClaim[];
  constructor(
    private readonly links: readonly DreamNightLink[],
    shelters: readonly NightImmunityClaim[] = [],
  ) {
    // 在原构造点捕获庇护目标；回调绑定原 claim 接收方，已付 owner 仍可在后续查询撤权。
    this.shelters = shelters.map((claim) => ({
      target: { id: claim.target.id, life: claim.target.life, version: claim.target.version },
      isCurrent: claim.isCurrent.bind(claim),
    }));
  }

  private sheltered(
    world: World,
    targetId: EntityId,
    eligibleDead: ReadonlySet<EntityId> = new Set(),
  ): boolean {
    return this.shelters.some(
      ({ target, isCurrent }) =>
        target.id === targetId &&
        isCurrent() &&
        world.getComponent(targetId, COMPONENT.Alive) === target.life &&
        (target.life.alive
          ? aliveLifeVersion(target.life) === target.version
          : eligibleDead.has(targetId) && aliveLifeVersion(target.life) === target.version + 1),
    );
  }

  private targetCurrent(world: World, link: DreamNightLink): boolean {
    return (
      world.getComponent(link.targetId, COMPONENT.Alive) === link.targetLife &&
      link.targetLife.alive &&
      link.targetVersion !== undefined &&
      aliveLifeVersion(link.targetLife) === link.targetVersion
    );
  }
  // 只接本波 eligible 集合中的同原目标首次死亡（版本仅 +1）；替换或复活后的生命不复用。
  private targetDeathCurrent(
    world: World,
    link: DreamNightLink,
    eligible: ReadonlySet<EntityId>,
  ): boolean {
    return (
      eligible.has(link.targetId) &&
      world.getComponent(link.targetId, COMPONENT.Alive) === link.targetLife &&
      !link.targetLife.alive &&
      link.targetVersion !== undefined &&
      aliveLifeVersion(link.targetLife) === link.targetVersion + 1
    );
  }
  // 已付梦允许同原行动者首死亡后的连锁，但仍检查回调、原组件和捕获版本，不无条件保留效果。
  private actorCurrent(world: World, link: DreamNightLink): boolean {
    return (
      (link.isCurrent?.() ?? true) &&
      world.getComponent(link.actorId, COMPONENT.Alive) === link.actorLife &&
      link.actorVersion !== undefined &&
      aliveLifeVersion(link.actorLife) === link.actorVersion + (link.actorLife.alive ? 0 : 1)
    );
  }
  protectedTargets(world: World): EntityId[] {
    return [
      ...new Set(
        this.links
          .filter((link) => this.targetCurrent(world, link) && this.actorCurrent(world, link))
          .map((link) => link.targetId),
      ),
    ];
  }
  immuneNightTargets(world: World): EntityId[] {
    return this.links
      .filter(
        (link) =>
          link.protectionPolicy === "netease_2026_night_immunity_v1" &&
          this.targetCurrent(world, link) &&
          this.actorCurrent(world, link),
      )
      .map((link) => link.targetId);
  }
  blocksNightShot(world: World, targetId: EntityId): boolean {
    return this.protectedTargets(world).includes(targetId);
  }
  blocksNightCharm(world: World, targetId: EntityId, eligibleDead: ReadonlySet<EntityId>): boolean {
    return this.links.some(
      (link) =>
        link.targetId === targetId &&
        this.actorCurrent(world, link) &&
        (this.targetCurrent(world, link) || this.targetDeathCurrent(world, link, eligibleDead)),
    );
  }

  consecutiveDeaths(world: World): EntityId[] {
    // 累计原因但不标死；后续 record 仍使用这一实例，不能另造 frame 丢失已发生前缀。
    const deaths = new Set<EntityId>();
    for (const link of this.links)
      if (
        link.consecutive &&
        this.targetCurrent(world, link) &&
        this.actorCurrent(world, link) &&
        !this.sheltered(world, link.targetId)
      ) {
        deaths.add(link.targetId);
        this.reason(link, "consecutive");
      }
    return [...deaths];
  }
  private reason(link: DreamNightLink, reason: DreamReason["reason"]): void {
    const facts = this.reasons.get(link.targetId) ?? [];
    if (
      !facts.some(
        (fact) =>
          fact.actorId === link.actorId &&
          fact.abilityId === link.abilityId &&
          fact.reason === reason,
      )
    )
      facts.push({
        actorId: link.actorId,
        targetId: link.targetId,
        day: link.day,
        reason,
        ...(link.abilityId ? { abilityId: link.abilityId } : {}),
      });
    this.reasons.set(link.targetId, facts);
  }
  linkedDeaths(
    world: World,
    nightDeaths: readonly EntityId[],
    eligibleDead: ReadonlySet<EntityId> = new Set(),
  ): EntityId[] {
    const deaths = new Set(nightDeaths),
      // 按原有限闭包顺序加入关联原因；允许本波已死亡的原目标，庇护和当前性仍现场查询。
      added = new Set<EntityId>();
    let changed = true;
    while (changed) {
      changed = false;
      for (const link of this.links)
        if (
          deaths.has(link.actorId) &&
          this.actorCurrent(world, link) &&
          !this.sheltered(world, link.targetId, eligibleDead) &&
          (this.targetCurrent(world, link) || this.targetDeathCurrent(world, link, eligibleDead))
        ) {
          added.add(link.targetId);
          this.reason(link, "linked");
          if (!deaths.has(link.targetId)) {
            deaths.add(link.targetId);
            changed = true;
          }
        }
    }
    return [...added];
  }
  expandInitialDamage(world: World, damage: DamageResolutionResult): void {
    for (const targetId of this.linkedDeaths(world, damage.deaths)) {
      if (!damage.deaths.includes(targetId)) damage.deaths.push(targetId);
      damage.deathSources[targetId] = [
        ...new Set([...(damage.deathSources[targetId] ?? []), DeathCause.Dream]),
      ];
    }
  }
  recordDeaths(deadIds: readonly EntityId[], events: GameEvent[]): void {
    for (const targetId of deadIds)
      for (const fact of this.reasons.get(targetId) ?? []) {
        const key = `${fact.actorId}:${fact.abilityId ?? "native"}:${fact.targetId}:${fact.reason}`;
        if (this.emitted.has(key)) continue;
        // 去重先于事件写入；push 失败保留原 emitted 前缀，不重发或回滚已记录身份。
        this.emitted.add(key);
        events.push({ timestamp: Date.now(), type: "dream_death", payload: { ...fact } });
      }
  }
}

/**
 * 负责摄梦人对当前能力及原目标生命的行动。
 * 输入为查询给出的 actor、夜请求和合法梦目标；输出保留历史与有来源梦保护。
 * 具体状态写入和共享 use 命令仍在原 commit 位置，资格／事实顺序不变。
 * 本阶段不执行死亡波或刷新已失效目标，也不回滚已付历史。
 */
import { DREAMER_STATE_SLOT } from "./ports";
import { isRadiantEclipseBoard, captureRadiantPaidEffect } from "../radiant_eclipse/paid-effect-ports";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Phase } from "../../../../core/domain/model";
import type { NightStageHandler } from "../../stages/night/contracts";
import { recordNightAbilityUse } from "../abilities";
import { captureNightAbilityScope } from "../ability_scope";
import { markDreamNightCommitted } from "./night_frame";
import { dreamNightLinksForAppend } from "./night-links";

export const DREAMER_NIGHT_STAGE: NightStageHandler = {
  id: "dreamer_action",
  priority: 150,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const { actorId, ability } of ctx.nightActors.actors("dream", day)) {
      if (!ctx.isCurrent()) return;
      const scope = captureNightAbilityScope(
        ctx.world,
        actorId,
        ability,
        day,
        () => ctx.isCurrent() && ctx.currentDay() === day,
      );
      if (!scope?.isEligible()) continue;
      const actorLife = scope.life.life,
        actorVersion = scope.life.version,
        state = ability.state;
      const targets = new Map(
        ctx.world
          .getAliveEntityIds()
          .filter((id) => id !== actorId)
          .map((id) => {
            const life = ctx.world.getComponent(id, COMPONENT.Alive)!;
            return [id, { life, version: aliveLifeVersion(life) }] as const;
          }),
      );
      if (targets.size === 0) continue;
      let applied = false;
      const current = () => scope.isEligible();
      for (let attempt = 1; attempt <= 3; attempt++) {
        if (!current()) {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_scope_stale");
          break;
        }
        const request = ctx.makeRequest(actorId, ["dream"], {
          stage: "dreamer",
          ability_id: ability.id,
          ...(attempt === 1 ? {} : { retry_attempt: attempt - 1, retry_max: 2 }),
        });
        if (!current()) {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_scope_stale");
          break;
        }
        const action = await ctx.actionProvider.getAction(request);
        if (!current()) {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_scope_stale");
          break;
        }
        if (action?.name !== "dream") {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_action_missing");
          continue;
        }
        const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
          abilityId: ability.id,
        });
        if (!current()) {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_scope_stale");
          break;
        }
        if (!validated.ok || validated.sanitizedCall?.name !== "dream") {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_action_invalid");
          continue;
        }
        const targetId = validated.sanitizedCall.args.target_id,
          target = targets.get(targetId);
        if (
          !target ||
          ctx.world.getComponent(targetId, COMPONENT.Alive) !== target.life ||
          !target.life.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.life) !== target.version
        )
          continue;
        const consecutive = state.lastDay === day - 1 && state.lastTarget === targetId;
        DREAMER_STATE_SLOT.allowedWrites.recordDreamSelection(state, targetId, day);
        recordNightAbilityUse(ability, day, true);
        markDreamNightCommitted(ctx.world, day);
        applied = true;
        // 历史、次数与开夜提交已经落下；先取本族同数组的 push，再构造原生命／已付效果条目。
        // 原已付 predicate 在这个字段位置才捕获；不能用仍开放的行动 scope 替代它或重付资源。
        dreamNightLinksForAppend(ctx.state).push({
          actorId,
          targetId,
          day,
          isCurrent: captureRadiantPaidEffect(ctx.world, day, actorId, ability, targetId),
          consecutive,
          protectionPolicy: state.protectionPolicy,
          actorLife,
          actorVersion,
          targetLife: target.life,
          targetVersion: target.version,
          ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "dream_applied",
          payload: {
            actorId,
            targetId,
            day,
            consecutive,
            ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
          },
        });
        break;
      }
      if (
        !applied &&
        current() &&
        [...targets].some(
          ([id, target]) =>
            ctx.world.getComponent(id, COMPONENT.Alive) === target.life &&
            target.life.alive &&
            target.version !== undefined &&
            aliveLifeVersion(target.life) === target.version,
        )
      )
        throw new Error("dream_required_action_missing");
    }
  },
};

/**
 * 负责 摄梦人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { DREAM_PROTECTION_POLICIES } from "../../../../core/domain/board";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { activeNightAbility } from "../abilities";
import { getDreamerState, setDreamerState } from "./ports";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import { DREAMER_NIGHT_STAGE } from "./night_stages";

const parameters = z.strictObject({
  protectionPolicy: z.enum(DREAM_PROTECTION_POLICIES).default("awa_night_damage_v1"),
});

export const DREAMER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Dreamer,
    camp: Camp.Good,
    goodSide: "god",
    label: roleName("dreamer"),
    skillBrief: text("zh-CN", "role.dreamer.brief"),
  },
  runtime: {
    init: (role, ctx) => {
      setDreamerState(role, {
        lastTarget: null,
        lastDay: null,
        history: [],
        ...(ctx.boardConfig?.dreamer?.protectionPolicy &&
        ctx.boardConfig.dreamer.protectionPolicy !== "awa_night_damage_v1"
          ? { protectionPolicy: ctx.boardConfig.dreamer.protectionPolicy }
          : {}),
      });
    },
    configuration: {
      schema: parameters,
      defaults: { protectionPolicy: "awa_night_damage_v1" },
      apply: (config, value) => ({ ...config, dreamer: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.dreamer ?? {}),
    },
    nightStages: [DREAMER_NIGHT_STAGE],
    toolSpecs: [
      {
        name: "dream",
        parameters: {
          type: "object",
          properties: { target_id: { type: "number" } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'dream args: {"target_id":number}',
        userPromptHintKey: "action.dream.hint",
      },
    ],
    validationRules: {
      dream: ({ world, actorId, role, toolCall, phase, day, abilityId }) => {
        if (!activeNightAbility(role, "dream", day ?? 1, abilityId))
          return { code: RuleError.DreamUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (
          toolCall.name !== "dream" ||
          toolCall.args.target_id === actorId ||
          !isAliveTarget(world, toolCall.args.target_id)
        )
          return { code: RuleError.DreamTarget };
        return null;
      },
    },
    stageDirectives: [
      {
        match: (tools) => tools.length === 1 && tools[0] === "dream",
        messageKey: "action.dream.directive",
        text: text("zh-CN", "action.dream.directive"),
      },
    ],
    llmRepair: {
      coerce: {
        dream: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
    baselineAction: (_role, request, pick) => {
      if (!request.allowedTools.includes("dream")) return null;
      const target = pick();
      return target === null ? null : { name: "dream", args: { target_id: target } };
    },
  },
  presentation: nativeRolePresentation("dreamer"),
};

/**
 * 负责摄梦人原生状态槽访问及 target/day/history 的具体写入。
 * 输入为原角色、能力或已捕获状态和接受目标；输出保留安装复制、原槽引用与部分写入顺序。
 * 数据／只读形状来自 contract；连续目标、租约、use 计数、梦效果和事实仍在原 caller 位置。
 * 本 owner 不制造状态镜像、回滚已付资源或新增资格重检。
 */
import type { DreamerState, DreamerReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "@ai-werewolf-arena/game-contract";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../abilities";

/** 初始化只复制原 JSON 并提交同一原生库存；连续目标和保护资格不是安装校验。 */
export function setDreamerState(roleComp: RoleComponent, state: DreamerState): DreamerReadState {
  return commitPreparedNativeAbility(roleComp, "dream", DREAMER_STATE_SLOT.create(state));
}

export function getDreamerState(
  roleComp: RoleComponent,
  abilityId?: string,
): DreamerReadState | undefined {
  return findNightAbility(roleComp, "dream", abilityId)?.state;
}

/** 目标／scope 检查、次数、梦效果与事实仍在 caller；history 失败不回滚已写 target/day。 */
export function recordDreamSelection(
  state: DreamerReadState,
  targetId: EntityId,
  day: number,
): void {
  // target/day 先落原槽，再读取 history 并 push；后段失败保留两项已写前缀。
  (state as DreamerState).lastTarget = targetId;
  (state as DreamerState).lastDay = day;
  (state as DreamerState).history.push({ day, targetId });
}

/** 原 stringify callee 先于 state／protectionPolicy 读取；只编码既有 scope 身份。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"dream">): string {
  return JSON.stringify([ability.state.protectionPolicy]);
}

/** JSON 创建／schema 沿用旧接受集合；读同一库存，明确写入不制造新 lease 或状态镜像。 */
export const DREAMER_STATE_SLOT = Object.freeze({
  create: copyAbilityData<DreamerState>,
  schema: copyAbilityData<DreamerState>,
  install: setDreamerState,
  get: getDreamerState,
  allowedWrites: Object.freeze({ recordDreamSelection }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 负责恶夜骑士一夜原体绑定 Map 的唯一存储及反射／夜枪运行查询。
 * 输入为原 NightStageState 身份与开夜捕获的同一 Map；输出为原 binding 或捕获同一 Map 的夜枪闭包。
 * 原 binding 包含生命、库存引用和当前性回调，不是玩家 DTO 或 JSON，也不因查询而获得反射付款权限。
 * 原体捕获／资格归 reflection，免疫提案归 night_frame，余量写入归 state-slot；本模块不查询 World、不复制 Map 或重抓角色。
 * 旧通用 map 属性／返回 map 注入接口退出；更换状态对象不接续旧 Map，已有结果闭包保原捕获引用。
 */
import type { EntityId } from "../../../../core/domain/identity";
import type { NightStageState } from "../../stages/night/contracts";
import type { captureEvilKnight } from "./reflection";

type EvilKnightNightBinding = NonNullable<ReturnType<typeof captureEvilKnight>>;
type EvilKnightNightBindings = Map<EntityId, EvilKnightNightBinding>;

// 只有本族这一份按夜间状态身份登记的 Map；免疫列表仍是原独立提案数组，不挂通用镜像。
const bindingsByNight = new WeakMap<NightStageState, EvilKnightNightBindings>();

/** 仅核原重入检查点是否已安装；不调用 binding.isCurrent 或推导资格。 */
export function hasEvilKnightNightBindings(state: NightStageState): boolean {
  return bindingsByNight.has(state);
}

/** 在原赋值点登记同一 Map；values 迭代或随后免疫写入失败仍保留已经安装的前缀。 */
export function installEvilKnightNightBindings(
  state: NightStageState,
  bindings: EvilKnightNightBindings,
): void {
  bindingsByNight.set(state, bindings);
}

/** 反射在原参数读取点取得原 binding；原付款命令继续负责当前性、来源和资源复核。 */
export function evilKnightNightBinding(
  state: NightStageState,
  targetId: EntityId,
): EvilKnightNightBinding | null {
  return bindingsByNight.get(state)?.get(targetId) ?? null;
}

/**
 * 在原输出字段点只捕获同一 Map，不读取 World／目标／政策。闭包调用时保持原 get、
 * isCurrent 再 shotPolicy 的短路顺序及 receiver；只返回夜枪保护，不暴露可替换的 Map。
 */
export function captureEvilKnightNightShotProtection(
  state: NightStageState,
): (targetId: EntityId) => boolean {
  const bindings = bindingsByNight.get(state);
  return (targetId) => {
    const binding = bindings?.get(targetId);
    return (
      !!binding && binding.isCurrent() && binding.state.shotPolicy === "night_shot_immune"
    );
  };
}

/**
 * 负责恶夜骑士固定名单的原体复验及本夜绑定捕获阶段。输入为原玩家、能力身份与当前夜状态；
 * 输出为原名单拒绝、同一 binding Map 与免疫提案。名单不在角色替换后重建，失效保原错误前缀。
 * 每次状态读取和原 capture／Map.set 顺序保持；本族登记 Map 后才展开免疫数组，后续失败不退款或撤销安装。
 * 捕获与反射资格归 reflection，实际余量写入归 state-slot；运行回调／生命引用不进入玩家观察或归档，也不授权行动。
 * 当前 Camp 在原字段点由实际 World 查询；保原值比较，不把同值组件替换改成新的引用撤权。
 */
import type { World } from "../../../../core/domain/world";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role } from "../../../../core/domain/identity";
import { captureNightLife } from "../../../../core/domain/night_effects";
import type { NightStageHandler } from "../../stages/night/contracts";
import { captureEvilKnight } from "./reflection";
import { hasEvilKnightNightBindings, installEvilKnightNightBindings } from "./night-bindings";
import type { NightAbilityReadView } from "../abilities";
type AbilityAuthority = {
  ability: NightAbilityReadView;
  state: NightAbilityReadView["state"];
  source: NightAbilityReadView["source"];
  identity: string;
};
function abilityIdentity(ability: NightAbilityReadView): string {
  const state = ability.state as unknown as Record<string, unknown>;
  return JSON.stringify([
    ability.id,
    ability.kind,
    ability.activation,
    ability.source,
    ability.sourceDisclosed,
    ability.startsOnDay,
    ability.expiresAfterDay,
    ability.maxUses,
    state.targetPolicy,
    state.actionPolicy,
    state.selfHealRule,
    state.knifeVisibility,
    state.potionPolicy,
    state.repeatPolicy,
    state.policy,
    state.inspectionPolicy,
    state.protectionPolicy,
  ]);
}
type RosterBinding = {
  id: number;
  role: RoleComponent;
  kind: Role;
  camp: Camp | undefined;
  state: RoleComponent["privateState"];
  refs: [string, unknown][];
  abilityRefs: [string, unknown][];
  authorities: AbilityAuthority[];
};
const installed = new WeakMap<World, RosterBinding[]>();
export function installEvilKnightBoard(world: World): void {
  if (installed.has(world)) throw new Error("evil_knight_board_reinstall");
  installed.set(
    world,
    world.entityIds().map((id) => {
      const role = world.getComponent(id, COMPONENT.Role);
      if (!role) throw new Error("evil_knight_roster_missing");
      return {
        id,
        role,
        kind: role.role,
        camp: world.getComponent(id, COMPONENT.Camp)?.camp,
        state: role.privateState,
        refs: Object.entries(role.privateState),
        abilityRefs: Object.entries(
          (role.privateState as { readonly abilities?: unknown }).abilities ?? {},
        ),
        authorities: Object.values(
          ((role.privateState as { readonly abilities?: unknown }).abilities ?? {}) as Record<
            string,
            NightAbilityReadView
          >,
        ).map((ability) => ({
          ability,
          state: ability.state,
          source: ability.source,
          identity: abilityIdentity(ability),
        })),
      };
    }),
  );
}
export function isEvilKnightBoard(world: World): boolean {
  return installed.has(world);
}
export function assertEvilKnightRosterCurrent(world: World): void {
  for (const entry of installed.get(world) ?? []) {
    if (
      world.getComponent(entry.id, COMPONENT.Role) !== entry.role ||
      entry.role.role !== entry.kind ||
      world.getComponent(entry.id, COMPONENT.Camp)?.camp !== entry.camp ||
      entry.role.privateState !== entry.state ||
      entry.refs.some(
        ([key, value]) => (entry.state as Readonly<Record<string, unknown>>)[key] !== value,
      ) ||
      entry.authorities.some(
        (a) =>
          a.ability.state !== a.state ||
          a.ability.source !== a.source ||
          abilityIdentity(a.ability) !== a.identity,
      ) ||
      Object.keys((entry.state as { readonly abilities?: unknown }).abilities ?? {}).length !==
        entry.abilityRefs.length ||
      entry.abilityRefs.some(
        ([key, value]) =>
          (
            (entry.state as { readonly abilities?: unknown }).abilities as
              Record<string, unknown> | undefined
          )?.[key] !== value,
      )
    )
      throw new Error("evil_knight_roster_revoked");
  }
}
export function assertEvilKnightNativeActor(world: World, actorId: number, expected: Role): void {
  if (!isEvilKnightBoard(world)) return;
  assertEvilKnightRosterCurrent(world);
  const role = world.getComponent(actorId, COMPONENT.Role);
  if (role?.role !== expected || world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good)
    throw new Error("evil_knight_actor_identity_revoked");
}
export const EVIL_KNIGHT_FRAME_STAGE: NightStageHandler = {
  id: "evil_knight_frame",
  priority: 50,
  async execute(ctx) {
    if (!isEvilKnightBoard(ctx.world)) return;
    assertEvilKnightRosterCurrent(ctx.world);
    if (hasEvilKnightNightBindings(ctx.state)) throw new Error("evil_knight_night_reentry");
    const bindings = new Map<number, NonNullable<ReturnType<typeof captureEvilKnight>>>();
    for (const id of ctx.world.getAliveEntityIds()) {
      const life = captureNightLife(ctx.world, id);
      const binding = life && captureEvilKnight(ctx.world, life);
      if (binding) bindings.set(id, binding);
    }
    installEvilKnightNightBindings(ctx.state, bindings);
    ctx.state.nightImmunities = [...bindings.values()];
  },
};

/**
 * 负责恶夜骑士公开的只读普通狼刀目标贡献，并提供原状态读取、资格校验及反射提交入口。
 * 输入是绑定原 World 的目标序号，或具体原体／查验上下文；输出保留原存活角色允许结果，
 * 包括未安装专用板子时的原政策。查询错误原样传播，绑定不提前读组件或授予生命、反射写权。
 * 名单复验向夜间规则组合及阶段检查点公开原函数，不读写库存或开启行动窗口。
 * 反射命令保留原来源校验与付款时点，余量只交本族槽写入；此公开出口不暴露数据槽写者。
 * 反射终态与失败前缀由状态命令维护，出口不拦截错误或尝试回滚。
 */
import { Role, type EntityId } from "../../../../core/domain/identity";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { World } from "../../../../core/domain/world";
export { isEvilKnightBoard, assertEvilKnightNativeActor, assertEvilKnightRosterCurrent } from "./night_frame";
export { commitEvilKnightReflection } from "./reflection";
/** 运行查询保原 binding／Map 捕获，不公开 Map 或增加库存／生命写权。 */
export { evilKnightNightBinding, captureEvilKnightNightShotProtection } from "./night-bindings";

export interface EvilKnightKnifeTargetQuery {
  allows(targetId: EntityId): boolean;
}

export function bindEvilKnightKnifeTargetQuery(world: World): EvilKnightKnifeTargetQuery {
  return Object.freeze({
    allows: (targetId: EntityId) =>
      world.getComponent(targetId, COMPONENT.Role)?.role !== Role.EvilKnight,
  });
}

export { getEvilKnightState, projectEvilKnightState } from "./state-slot";

/**
 * 负责 恶夜骑士 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Role, WinCondition } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { EVIL_KNIGHT_POLICY, EVIL_KNIGHT_STATE_SLOT, getEvilKnightState } from "./state-slot";
import { EVIL_KNIGHT_FRAME_STAGE } from "./night_frame";
const parameters = z.strictObject({
  policy: z.literal(EVIL_KNIGHT_POLICY).default(EVIL_KNIGHT_POLICY),
  shotPolicy: z.enum(["night_shot_immune", "hunter_shot_bypasses"]).default("night_shot_immune"),
});
export const EVIL_KNIGHT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.EvilKnight,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.EvilKnight,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
    ],
    label: roleName("evil_knight"),
    skillBrief: text("zh-CN", "role.evil_knight.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    canSelfDestruct: false,
    toolSpecs: (ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs ?? []).filter(
      (spec) => spec.name !== "self_destruct" && spec.name !== "self_destruct_with_target",
    ),
    init: (role, ctx) => {
      // 左值容器先读，原参数解析仍在 creator 的参数位置晚执行；失败不提前安装状态。
      EVIL_KNIGHT_STATE_SLOT.install(
        () => role.privateState,
        () => parameters.parse(ctx.boardConfig?.evilKnight ?? {}).shotPolicy,
      );
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, evilKnight: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.evilKnight ?? {}),
    },
    nightStages: [EVIL_KNIGHT_FRAME_STAGE, ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages ?? [])],
  },
  presentation: nativeRolePresentation("evil_knight"),
};

/**
 * 负责恶夜骑士原体／免疫捕获与一次反射的完整资格和付款顺序。
 * 输入是受信任 World、原生命绑定及来源当前性回调；输出为原 binding、免疫判断或反击运行效果。
 * World／回调和原状态引用不是玩家 DTO、JSON 或新授权；名单与夜 Map 仍归 frame 和 night-bindings。
 * 原 caster lookup 与来源判断先于付款；已付余量之后的字段读取／效果构造失败不退款，迟到撤权不返还资源。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { Camp, Role, type EntityId } from "../../../../core/domain/identity";
import { captureNightLife, livingNightLife, type NightLifeScope, type NightRetaliationAttack } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import { EVIL_KNIGHT_STATE_SLOT, getEvilKnightState } from "./state-slot";

/** 在等待其他玩家提交前绑定原体；每次提交仍校验生命、组件、私有容器与政策未被替换。 */
export function captureEvilKnight(world: World, target: NightLifeScope) {
  const role = world.getComponent(target.id, COMPONENT.Role);
  const state = getEvilKnightState(role, () => world.getComponent(target.id, COMPONENT.Camp));
  if (!role || !state || !livingNightLife(world, target)) return null;
  const privateState = role.privateState,
    shotPolicy = state.shotPolicy;
  const isCurrent = () =>
    livingNightLife(world, target) &&
    world.getComponent(target.id, COMPONENT.Role) === role &&
    role.privateState === privateState &&
    getEvilKnightState(role, () => world.getComponent(target.id, COMPONENT.Camp)) === state &&
    state.shotPolicy === shotPolicy;
  return { target, state, isCurrent };
}
export function evilKnightNightShotImmune(world: World, targetId: EntityId): boolean {
  const life = captureNightLife(world, targetId);
  const binding = life && captureEvilKnight(world, life);
  return !!binding && binding.state.shotPolicy === "night_shot_immune" && binding.isCurrent();
}
/** 仅在原生预言家查验或女巫毒药已被接受并付款后调用；反射本身不重复消耗原行动。 */
export function commitEvilKnightReflection(
  world: World,
  binding: ReturnType<typeof captureEvilKnight>,
  caster: NightLifeScope,
  trigger: "seer_check" | "poison",
  casterCurrent: () => boolean,
): NightRetaliationAttack | null {
  const casterRole = world.getComponent(caster.id, COMPONENT.Role);
  const expected = trigger === "seer_check" ? Role.Seer : Role.Witch;
  if (
    !binding ||
    !binding.isCurrent() ||
    binding.state.reflectionRemaining !== 1 ||
    !livingNightLife(world, caster) ||
    !casterCurrent() ||
    casterRole?.role !== expected ||
    world.getComponent(caster.id, COMPONENT.Camp)?.camp !== Camp.Good
  )
    return null;
  const privateState = casterRole.privateState;
  // 原私有容器已捕获后才付款；binding.state 在原写入点晚读，不能缓存或再次执行 schema。
  EVIL_KNIGHT_STATE_SLOT.allowedWrites.consumeReflection(() => binding.state);
  // 余量已经消费，再读原 target 构造效果；此后的异常或当前性失效均不退款。
  return {
    actorId: binding.target.id,
    target: caster,
    isCurrent: () =>
      binding.isCurrent() &&
      binding.state.reflectionRemaining === 0 &&
      livingNightLife(world, caster) &&
      casterCurrent() &&
      world.getComponent(caster.id, COMPONENT.Role) === casterRole &&
      casterRole.role === expected &&
      world.getComponent(caster.id, COMPONENT.Camp)?.camp === Camp.Good &&
      casterRole.privateState === privateState,
  };
}

/**
 * 负责恶夜骑士唯一 live 状态槽的创建、原字段校验、同引用读取及玩家字段副本。
 * 输入是原角色容器或明确枪政策；输出为原状态引用／新状态／纯数据副本，不提供生命或行动许可。
 * 安装与反射余量写入只收本族实际数据步骤；原体、夜窗口与付款资格仍由 frame／反射命令复核。
 * 方法表冻结不冻结状态或副本；仍接受原字段宽度，Proxy／访问器拒绝不等于严格档案 decoder。
 * 角色阵营渠道已退出；reader／project 以显式晚读 CurrentCampSource 获取实际 Camp，原 raw schema／写者不因此获得许可。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import type { EvilKnightShotPolicy, EvilKnightState, EvilKnightReadState } from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp } from "../../../../core/domain/identity";

export const EVIL_KNIGHT_ROLE = "evil_knight" as const;
export const EVIL_KNIGHT_POLICY = "awa_evil_knight_v1" as const;
function data(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
export function freshEvilKnightState(
  shotPolicy: EvilKnightShotPolicy = "night_shot_immune",
): EvilKnightState {
  return { policy: EVIL_KNIGHT_POLICY, shotPolicy, reflectionRemaining: 1 };
}
// 当前阵营只在原 camp 数据读取点取得；保本族自身 descriptor／Proxy 策略，不回退角色或目录。
export function getEvilKnightState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): EvilKnightReadState | undefined {
  if (data(role, "role") !== EVIL_KNIGHT_ROLE || data(currentCamp(), "camp") !== Camp.Wolf) return undefined;
  const state = data(data(role, "privateState"), "evilKnight");
  const shot = data(state, "shotPolicy"),
    remaining = data(state, "reflectionRemaining");
  return data(state, "policy") === EVIL_KNIGHT_POLICY &&
    (shot === "night_shot_immune" || shot === "hunter_shot_bypasses") &&
    (remaining === 0 || remaining === 1)
    ? (state as EvilKnightReadState)
    : undefined;
}
/** 字段裁剪由机制拥有；只返回纯数据副本，不把反射运行绑定带进玩家观察。 */
export function projectEvilKnightState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): EvilKnightState | undefined {
  const evilKnight = getEvilKnightState(role, currentCamp);
  if (evilKnight)
    return {
      policy: evilKnight.policy,
      shotPolicy: evilKnight.shotPolicy,
      reflectionRemaining: evilKnight.reflectionRemaining,
    };
}

/** 先求原左值容器，再调用原 creator 与读取／解析枪政策；任一 getter 或 setter 失败保原前缀。 */
function installEvilKnightState(
  privateState: () => Record<string, unknown>,
  shotPolicy: () => EvilKnightShotPolicy,
): void {
  privateState().evilKnight = freshEvilKnightState(shotPolicy());
}

