  } catch {
    return false;
  }
}
export function fragrantRoleKnifeEligible(world: World, role: PairTargetScope["role"]): boolean {
  const o = owners.get(world);
  return (
    !!o &&
    o.phantom.target.role === role &&
    !!o.active &&
    fragrantKnifeEligible(world, o.phantom.target.id, o.active.day)
