/** 只准备最终有效的存活死亡目标；preparation 不消耗资源。 */
export function prepareFragrantDeathWave(
  world: World,
  day: number,
  rootIds: unknown,
): FragrantWaveReceipt | null {
  const o = requireOwner(world),
    ids = snapshotPlainData(rootIds);
  if (
    !Array.isArray(ids) ||
    ids.some((id) => !Number.isSafeInteger(id) || Number(id) < 1) ||
    new Set(ids).size !== ids.length
  )
    throw Error("fragrant_death_wave_invalid");
  if (o.pendingWave) throw Error("fragrant_death_wave_pending");
  const paid = o.paid;
  if (!paid || paid.day !== day || o.fragrant.trigger) return null;
  if (!paid.targets.every((t) => pairTargetCurrent(world, t)))
    throw Error("fragrant_paid_targets_revoked");
  if (
    ids.some(
      (id) => !o.players.has(Number(id)) || !original(world, o.players.get(Number(id))!, true),
    )
  )
    throw Error("fragrant_death_wave_invalid");
  const rootId = ids.find((id) => paid.targets.some((t) => t.id === id));
  if (rootId === undefined) return null;
  const prefix = eventFeed(o.events),
    phases = prefix && phaseFacts(prefix);
  if (!prefix || !phases || (phases.at(-1)?.day ?? day) !== day)
    throw Error("fragrant_death_wave_invalid");
  const other = paid.targets.find((t) => t.id !== rootId)!,
    receipt = Object.freeze({
      day,
      rootId: Number(rootId),
      addedTargetId: ids.includes(other.id) ? null : other.id,
      pairIds: Object.freeze(normalizePair(paid.targets.map((t) => t.id))),
    });
  waves.set(receipt, {
    owner: o,
    paid,
    rootIds: ids as number[],
    json: o.fragrantJson,
    eventStart: prefix.length,
    prefix,
    phases,
    committed: false,
  });
  o.pendingWave = receipt;
  return receipt;
}
export function cancelFragrantDeathWave(world: World, receipt: FragrantWaveReceipt): void {
  const o = owners.get(world),
    p = waves.get(receipt);
  if (!o || !p || p.owner !== o || p.committed || o.pendingWave !== receipt)
    throw Error("fragrant_death_wave_revoked");
  o.pendingWave = null;
  waves.delete(receipt);
}
/** 结算器在提交此回执前同步标记整批已验证死亡波。 */
export function commitFragrantDeathWave(world: World, receipt: FragrantWaveReceipt): void {
  const o = requireOwner(world),
    p = waves.get(receipt);
  if (
    !p ||
    p.owner !== o ||
    p.committed ||
    o.pendingWave !== receipt ||
    o.paid !== p.paid ||
    o.fragrantJson !== p.json ||
    p.paid.targets.some((t) => !pairTargetOriginal(world, t, true) || t.life.alive) ||
    p.rootIds.some(
      (id) => !original(world, o.players.get(id)!) || o.players.get(id)!.target.life.alive,
    )
  )
    throw Error("fragrant_death_wave_revoked");
  commitFragrantStateSlot(
    o,
    triggerFragrantPair(o.fragrant, receipt.day, receipt.rootId, receipt.addedTargetId),
  );
  p.committed = true;
  o.pendingWave = null;
}
/** 只有已发出且实际提交的波及本局 feed 中公开事件才披露使用。 */
export function publishFragrantDeathWave(
  world: World,
  receipt: FragrantWaveReceipt,
  event: GameEvent,
): void {
  const o = requireOwner(world),
    p = waves.get(receipt),
    feed = eventFeed(o.events),
    index = feed ? feed.indexOf(event) : -1;
  if (
    !p ||
    p.owner !== o ||
    !p.committed ||
    !feed ||
    index < 0 ||
    (index < p.eventStart &&
      own(event, "type") !== "voted_out" &&
      own(event, "type") !== "wolf_self_destruct") ||
    p.prefix.some((e, i) => feed[i] !== e)
  )
    throw Error("fragrant_death_publication_invalid");
  const phases = phaseFacts(feed.slice(0, Math.max(index + 1, p.eventStart)));
  if (
    !phases ||
    (phases.at(-1)?.day ?? receipt.day) !== receipt.day ||
    (phaseFacts(feed.slice(0, index + 1))?.at(-1)?.day ?? receipt.day) !== receipt.day ||
    p.phases.some((fact, i) => JSON.stringify(phases[i]) !== JSON.stringify(fact))
  )
    throw Error("fragrant_death_publication_invalid");
  const fact = snapshotPlainData(event) as Record<string, unknown>,
    payload = fact.payload;
  if (
    Object.keys(fact).length !== 3 ||
    !Object.hasOwn(fact, "type") ||
    !Object.hasOwn(fact, "timestamp") ||
    !Object.hasOwn(fact, "payload") ||
    typeof fact.type !== "string" ||
    ![
      "night_resolved",
      "additional_deaths",
      "voted_out",
      "hunter_shot",
      "wolf_self_destruct",
    ].includes(fact.type) ||
    typeof fact.timestamp !== "number" ||
    !Number.isFinite(fact.timestamp) ||
    !payload ||
    typeof payload !== "object" ||
    Array.isArray(payload) ||
    (fact.type === "wolf_self_destruct"
      ? Object.keys(payload).length !== 2 ||
        !Object.hasOwn(payload, "wolfId") ||
        !Object.hasOwn(payload, "window") ||
        o.players.get(Number(own(payload, "wolfId")))?.target.roleId !== Role.Wolf ||
        (own(payload, "window") !== "on_pre_election" && own(payload, "window") !== "on_pre_vote")
      : fact.type === "hunter_shot"
        ? Object.keys(payload).length !== 2 ||
          !Object.hasOwn(payload, "hunterId") ||
          !Object.hasOwn(payload, "targetId") ||
          own(payload, "hunterId") !== o.players.get(Number(own(payload, "hunterId")))?.target.id ||
          o.players.get(Number(own(payload, "hunterId")))?.target.roleId !== Role.Hunter
        : Object.keys(payload).length !== 1 ||
          !Object.hasOwn(payload, fact.type === "voted_out" ? "target" : "deaths"))
  )
    throw Error("fragrant_death_publication_invalid");
  const publicPhase = phaseFacts(feed.slice(0, index + 1))?.at(-1)?.phase;
  if (
    (fact.type === "wolf_self_destruct" &&
      publicPhase !== (own(payload, "window") === "on_pre_election" ? Phase.Day : Phase.Voting)) ||
    (fact.type === "voted_out" && publicPhase !== Phase.Voting) ||
    (fact.type === "hunter_shot" && publicPhase !== Phase.Day && publicPhase !== Phase.Voting)
  )
    throw Error("fragrant_death_publication_invalid");
  const ids =
    fact.type === "wolf_self_destruct"
      ? [own(payload, "wolfId")]
      : fact.type === "voted_out"
        ? [own(payload, "target")]
        : fact.type === "hunter_shot"
          ? [own(payload, "targetId")]
          : (payload as { deaths: unknown }).deaths;
  if (
    !Array.isArray(ids) ||
    !ids.length ||
    new Set(ids).size !== ids.length ||
    ids.some(
      (id) =>
        !Number.isSafeInteger(id) ||
        !o.players.has(Number(id)) ||
        !original(world, o.players.get(Number(id))!) ||
        o.players.get(Number(id))!.target.life.alive,
    ) ||
    !receipt.pairIds.some((id) => ids.includes(id)) ||
    ((fact.type === "voted_out" ||
      fact.type === "hunter_shot" ||
      fact.type === "wolf_self_destruct") &&
      !ids.includes(receipt.rootId))
  )
    throw Error("fragrant_death_publication_invalid");
  o.knowledge = knowFragrantPublishedDeaths(o.knowledge, receipt.day, ids);
}
export function fragrantAuthoritySnapshot(world: World, complete = true) {
  // 失败检查点保留原 owner，即使槽替换已使完整检查点权限失效。
  const o = complete ? requireOwner(world) : owners.get(world);
  if (!o) throw Error("fragrant_owner_missing");
  return {
    phantomId: o.phantom.target.id,
    seerId: o.seer.target.id,
    fragrant: decodeFragrantState(() => o.fragrantJson),
    pairSeer: PAIR_STATE_SLOT_CONTRACT.checkpoint.decode(() => o.pairJson),
    known: readFragrantKnowledge(o.knowledge)!,
    nights: [...o.nights.values()].map((n) => ({
      day: n.day,
      status: n.status,
      knife: n.knife,
      bindCommitted: n.bind.committed,
      pairCommitted: n.pair.committed,
    })),
  };
}

/** 两个 owner 管理的私有槽仅从已提交收据还原，保留原归档字段及 JSON 拒绝位置。 */
export function fragrantCheckpointPrivateState(world: World, id: number, complete: boolean) {
  const o = owners.get(world);
  if (!o || (id !== o.phantom.target.id && id !== o.seer.target.id)) return undefined;
  if (complete) requireOwner(world);
  return id === o.phantom.target.id
    ? { fragrant: decodeFragrantState(() => o.fragrantJson) }
    : {
        abilities: { "native:pair_check": JSON.parse(o.pairAbilityJson) },
        pairSeer: PAIR_STATE_SLOT_CONTRACT.checkpoint.decode(() => o.pairJson),
      };
}

/**
 * 负责馥郁双生已提交死亡波的事实构造、必要记录和公开事件触发的披露。
 * 输入是原 receipt、死亡名单、原因与来源阶段，以及限定的行动者查询、日期/阶段/事件读取和发布端口；
 * 输出是原隐藏事实、记录条目及有公开根事件时的披露。receipt 是运行时权威凭据，不能当普通归档数据。
 * 本模块只构造原纯数据 payload；先追加全部事实，再执行可失败的发布与必要记录，保留已发生前缀。
 * 不修改 Alive，不准备、消费或取消双生绑定，也不扩展关系、请求遗言/警徽、处理枪或切换阶段。
 * 规则依据：docs/rules/awa-fragrant-pair-seer-twelve-v1.md。
 */
import { getSessionRecorder } from "../../../../recording/recording_context";
import { FRAGRANT_PAIR_POLICY } from "@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer";
import {
  Phase,
  type EntityId,
  type GameEvent,
  type DeathSources,
} from "../../../../core/domain/model";
import type { FragrantWaveReceipt } from "./authority";

/** 窄运行端口不暴露 World、原组件、库存或时钟；各 getter 在原表达式时点才读取。 */
interface FragrantDeathWaveRuntime {
  actorId(): EntityId;
  readonly phase: Phase;
  readonly day: number;
  readonly events: GameEvent[];
  publish(receipt: FragrantWaveReceipt, event: GameEvent): void;
}

export class FragrantDeathWavePublication {
  constructor(private readonly runtime: FragrantDeathWaveRuntime) {}

  // 所有事实先于可失败的记录；不能将发布或记录提前到事实之前。
  recordCommittedWave(
    receipt: FragrantWaveReceipt | null,
    ids: readonly number[],
    sources: DeathSources,
    origins: ReadonlyMap<number, Phase>,
    initialWave: boolean,
  ): void {
    const actorId = this.runtime.actorId(),
      phases: Record<string, "night" | "day" | "voting"> = {};
    for (const id of ids) {
      const origin = origins.get(id) ?? this.runtime.phase;
      if (origin === Phase.GameOver) throw Error("fragrant_death_origin_invalid");
      phases[String(id)] = origin;
    }
    const wave = {
      policy: FRAGRANT_PAIR_POLICY,
      actorId,
      day: this.runtime.day,
      deaths: [...ids],
      deathSources: Object.fromEntries(ids.map((id) => [String(id), [...(sources[id] ?? [])]])),
      deathPhases: phases,
      initialWave,
    };
    this.runtime.events.push({
      timestamp: Date.now(),
      type: "fragrant_wave_committed",
      payload: wave,
      audience: Object.freeze([]),
    });
    const rootPhase = receipt ? phases[String(receipt.rootId)]! : null,
      link = receipt && {
        policy: FRAGRANT_PAIR_POLICY,
        actorId,
        day: receipt.day,
        bindingId: `fragrant:night:${receipt.day}`,
        pairIds: receipt.pairIds,
        rootId: receipt.rootId,
        addedTargetId: receipt.addedTargetId,
        rootPhase: rootPhase!,
        initialWave,
      };
    if (link)
      this.runtime.events.push({
        timestamp: Date.now(),
        type: "fragrant_link_triggered",
        payload: link,
        audience: Object.freeze([]),
      });
    // 放逐公开根可以早于本波，枪击公开根可以早于记录；只在确实找到原事件后披露。
    if (receipt) {
      const publicRoot = [...this.runtime.events]
        .reverse()
        .find(
          (e) =>
            (e.type === "wolf_self_destruct" && e.payload.wolfId === receipt.rootId) ||
            (e.type === "voted_out" && e.payload.target === receipt.rootId) ||
            (e.type === "hunter_shot" && e.payload.targetId === receipt.rootId),
        );
      if (publicRoot) this.runtime.publish(receipt, publicRoot);
    }
    getSessionRecorder()?.recordRequiredLogicOp({
      scope: "resolution",
      op: "fragrant_wave_committed",
      phase: this.runtime.phase,
      status: "ok",
      output: wave,
    });
    if (link)
      getSessionRecorder()?.recordRequiredLogicOp({
        scope: "resolution",
        op: "fragrant_link_triggered",
        phase: this.runtime.phase,
        status: "ok",
        output: link,
      });
  }

  /**
   * 只选已存在的公开事件交给 authority 发布；与 pairIds 相交不是新的绑定或库存授权。
   * receipt 的有效性及重复披露由原 owner 检查，失败保留已产生的死亡与事实。
   */
  publishVisibleWave(receipt: FragrantWaveReceipt | null, event: GameEvent): void {
    if (
      receipt &&
      (event.type === "night_resolved" || event.type === "additional_deaths") &&
      event.payload.deaths.some((id) => receipt.pairIds.includes(id))
    )
      this.runtime.publish(receipt, event);
  }
}

/**
 * 负责寻香魅影完整数据槽的创建、原严格 schema、知识／绑定下一状态及原位提交。
 * 输入为原角色或 authority 已捕获的槽；输出保持同一 live 状态和已提交 JSON，
 * 原生命、roster、RNG、夜间租约、关系付款和死亡发布仍由 authority 拥有。
 * 初始化先求值 privateState 左值容器再调用 creator；提交先写全部原字段，再编码 JSON，
 * 编码失败保留已经写入的前缀，不回滚、不额外冻结或重新检查授权。内部 codec 保原位置，
 * 不是所有 private 扩展键的归档格式；状态知识和 public schema 不授予行动或资源写权限。
 */
import type { Pair } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import { FRAGRANT_PAIR_POLICY, normalizePair } from "./state";
import { positive, exact, pair, write } from "./owned-state-data";

/** 原绑定数据只记录期限／触发；实际原生命、关系消费和发布权限仍由 authority 证明。 */
export interface Binding {
  id: string;
  createdNight: number;
  expiresNight: number;
  pairIds: Pair;
  status: { kind: "pending" } | { kind: "expired" | "triggered"; day: number };
}
/** knownWolfId 与 knowledgeNight 是原首夜知识，不能据此重新推导玩家真实 Camp 或发放租约。 */
export interface FragrantState {
  policy: typeof FRAGRANT_PAIR_POLICY;
  knownWolfId: number | null;
  knowledgeNight: 1 | null;
  lastChoice: { day: number; pairIds: Pair | null } | null;
  bindings: readonly Binding[];
  trigger: { bindingId: string; day: number; rootId: number; addedTargetId: number | null } | null;
}
export function freshFragrantState(): FragrantState {
  return {
    policy: FRAGRANT_PAIR_POLICY,
    knownWolfId: null,
    knowledgeNight: null,
    lastChoice: null,
    bindings: [],
    trigger: null,
  };
}
export function readFragrantState(value: unknown): FragrantState | null {
  try {
    const v = snapshotPlainData(value, new Set(), 0, 65536);
    if (
      !exact(v, ["policy", "knownWolfId", "knowledgeNight", "lastChoice", "bindings", "trigger"]) ||
      v.policy !== FRAGRANT_PAIR_POLICY ||
      !Array.isArray(v.bindings)
    )
      return null;
    if (
      v.knownWolfId === null
        ? v.knowledgeNight !== null
        : !positive(v.knownWolfId) || v.knowledgeNight !== 1
    )
      return null;
    if (
      v.lastChoice !== null &&
      (!exact(v.lastChoice, ["day", "pairIds"]) ||
        !positive(v.lastChoice.day) ||
        (v.lastChoice.pairIds !== null && !pair(v.lastChoice.pairIds)))
    )
      return null;
    let previous = 0,
      pending = 0,
      triggered = 0;
    // 创建夜严格递增，到期夜固定为下一夜；状态日期在此核对，末次选择与绑定的关联随后完整复验。
    for (const b of v.bindings) {
      if (
        !exact(b, ["id", "createdNight", "expiresNight", "pairIds", "status"]) ||
        !positive(b.createdNight) ||
        b.createdNight <= previous ||
        b.expiresNight !== b.createdNight + 1 ||
        b.id !== `fragrant:night:${b.createdNight}` ||
        !pair(b.pairIds)
      )
        return null;
      previous = b.createdNight;
      if (exact(b.status, ["kind"]) && b.status.kind === "pending") pending++;
      else if (exact(b.status, ["kind", "day"]) && positive(b.status.day)) {
        if (b.status.kind === "expired" && b.status.day === b.expiresNight) {
        } else if (b.status.kind === "triggered" && b.status.day === b.createdNight) triggered++;
        else return null;
      } else return null;
    }
    if (pending > 1 || triggered > 1 || (pending && triggered)) return null;
    if (v.bindings.length && v.knowledgeNight !== 1) return null;
    if (
      pending &&
      (!exact(v.lastChoice, ["day", "pairIds"]) ||
        v.lastChoice.pairIds === null ||
        v.bindings.at(-1)?.status.kind !== "pending")
    )
      return null;
    if (
      triggered &&
      (v.bindings.at(-1)?.status.kind !== "triggered" ||
        !exact(v.lastChoice, ["day", "pairIds"]) ||
        v.lastChoice.day !== v.bindings.at(-1)?.createdNight)
    )
      return null;
    if (
      v.bindings.length &&
      (!v.lastChoice ||
        !exact(v.lastChoice, ["day", "pairIds"]) ||
        Number(v.lastChoice.day) < previous)
    )
      return null;
    if (v.bindings.length) {
      const latest = v.bindings.at(-1)!;
      if (!exact(v.lastChoice, ["day", "pairIds"])) return null;
      if (v.lastChoice.day === latest.createdNight) {
        if (
          v.lastChoice.pairIds === null ||
          JSON.stringify(v.lastChoice.pairIds) !== JSON.stringify(latest.pairIds)
        )
          return null;
      } else if (latest.status.kind !== "expired" || v.lastChoice.pairIds !== null) return null;
    } else if (
      v.lastChoice !== null &&
      exact(v.lastChoice, ["day", "pairIds"]) &&
      v.lastChoice.pairIds !== null
    )
      return null;
    // 回执必须对应唯一 triggered 绑定及原 pair 内的 root；追加目标可为 null，否则也须在 pair 内且不同于 root。
    if (v.trigger === null) {
      if (triggered) return null;
    } else {
      const r = v.trigger;
      if (
        !exact(r, ["bindingId", "day", "rootId", "addedTargetId"]) ||
        !positive(r.day) ||
        !positive(r.rootId) ||
        (r.addedTargetId !== null && !positive(r.addedTargetId))
      )
        return null;
      const b = v.bindings.find((b) => b.id === r.bindingId);
      if (
        !b ||
        triggered !== 1 ||
        b.status.kind !== "triggered" ||
        b.createdNight !== r.day ||
        !b.pairIds.includes(r.rootId) ||
        (r.addedTargetId !== null &&
          (r.addedTargetId === r.rootId || !b.pairIds.includes(r.addedTargetId)))
      )
        return null;
    }
    if (v.lastChoice !== null && v.knowledgeNight !== 1) return null;
    return v as unknown as FragrantState;
  } catch {
    return null;
  }
}
function valid(value: FragrantState): FragrantState {
  const s = readFragrantState(value);
  if (!s) throw Error("fragrant_state_invalid");
  return s;
}
export function commitKnownWolf(value: FragrantState, targetId: number): FragrantState {
  const s = valid(value);
  if (!positive(targetId) || s.knowledgeNight !== null)
    throw Error("fragrant_knowledge_already_committed");
  return { ...s, knownWolfId: targetId, knowledgeNight: 1 };
}
export function expireFragrantAtNightOpen(value: FragrantState, day: number): FragrantState {
  const s = valid(value);
  if (!positive(day) || (s.lastChoice && day <= s.lastChoice.day))
    throw Error("fragrant_night_invalid");
  return {
    ...s,
    bindings: s.bindings.map((b) =>
      b.status.kind === "pending" && b.expiresNight <= day
        ? { ...b, status: { kind: "expired" as const, day: b.expiresNight } }
        : b,
    ),
  };
}
export function chooseFragrantPair(
  value: FragrantState,
  day: number,
  targets: unknown,
): FragrantState {
  const s = valid(value);
  if (
    !positive(day) ||
    s.knowledgeNight !== 1 ||
    s.trigger ||
    s.bindings.some((b) => b.status.kind === "pending") ||
    (s.lastChoice && day <= s.lastChoice.day)
  )
    throw Error("fragrant_binding_unavailable");
  const pairIds = targets === null ? null : normalizePair(targets);
  return {
    ...s,
    lastChoice: { day, pairIds },
    bindings:
      pairIds === null
        ? s.bindings
        : [
            ...s.bindings,
            {
              id: `fragrant:night:${day}`,
              createdNight: day,
              expiresNight: day + 1,
              pairIds,
              status: { kind: "pending" },
            },
          ],
  };
}
/** 调用方证明真实原生命死亡；此纯回执不标记 World 或判胜。 */
export function triggerFragrantPair(
  value: FragrantState,
  day: number,
  rootId: number,
  addedTargetId: number | null,
): FragrantState {
  const s = valid(value),
    b = s.bindings.find((b) => b.status.kind === "pending");
  if (
    s.trigger ||
    !b ||
    day !== b.createdNight ||
    !b.pairIds.includes(rootId) ||
    (addedTargetId !== null && (addedTargetId === rootId || !b.pairIds.includes(addedTargetId)))
  )
    throw Error("fragrant_trigger_unavailable");
  return {
    ...s,
    bindings: s.bindings.map((row) =>
      row === b ? { ...row, status: { kind: "triggered" as const, day } } : row,
    ),
    trigger: { bindingId: b.id, day, rootId, addedTargetId },
  };
}

/** 原槽和已提交 JSON 仍是原 authority binding 的字段，不建立第二份 WeakMap 或影子状态。 */
export interface FragrantStateSlot {
  readonly fragrant: FragrantState;
  fragrantJson: string;
}
export interface FragrantStateSlotProof extends FragrantStateSlot {
  readonly phantom: { readonly privateState: object };
}

/** 完整原安装语句；写入左值容器先于 fresh callee 和新状态的创建。 */
export function installFragrantStateSlot(role: RoleComponent): void {
  (role.privateState as { fragrant: FragrantState }).fragrant = freshFragrantState();
}

/** 原 descriptor 写全部字段后才求 JSON callee／next；编码抛错保留已经完成的 live 字段写入。 */
export function commitFragrantStateSlot(o: FragrantStateSlot, next: FragrantState): void {
  write(o.fragrant, next);
  o.fragrantJson = JSON.stringify(next);
}

/** 使用 authority 原 own reader 和 sentinel，保持其参数读取与裸调用，不新增运行权限。 */
export function fragrantAliasesCurrent(
  o: FragrantStateSlotProof,
  own: (value: unknown, key: PropertyKey) => unknown,
): boolean {
  return own(o.phantom.privateState, "fragrant") === o.fragrant;
}

/** JSON callee 先于 schema callee、槽和已提交字段的读取；此数据比较仍在 Pair alias 检查之后。 */
export function fragrantDataCurrent(o: FragrantStateSlot): boolean {
  return JSON.stringify(readFragrantState(o.fragrant)) === o.fragrantJson;
}

/** 原安装已校验副本在原字段位置编码，不能把 schema 重新校验提前到付款点。 */
export function encodeFragrantState(state: FragrantState): string {
  return JSON.stringify(state);
}

/** 查找 JSON.parse callee 后才晚读原 JSON 字段，输出原可写副本；不生成新的行动原体。 */
export function decodeFragrantState(readJson: () => string): FragrantState {
  return JSON.parse(readJson()) as FragrantState;
}

/**
 * 维护香对预言家的玩家已知日志与纯知识更新。输入为已发表通知、已知狼／选择／死亡及 pair ID；输出按原序校验复制和更新，不推导隐藏触发凭据或授予阵容／行动权限。
