async function execute(ctx: NightStageContext, kind: "bind" | "pair") {
  const day = ctx.currentDay(),
    actorId = fragrantChoiceActor(ctx.world, day, kind);
  if (actorId === null) return;
  const name = kind === "bind" ? "bind_fragrant_pair" : "check_pair",
    candidates = fragrantChoiceCandidates(ctx.world, day),
    request = ctx.makeRequest(actorId, [name], {
      stage: kind === "bind" ? "fragrant_bind" : "pair_inspection",
      requiresAction: true,
      allow_fallback: false,
      action_failure_policy: "error",
      ...(kind === "bind"
        ? { fragrant_pair_candidates: candidates }
        : { pair_check_candidates: candidates, ability_id: "native:pair_check" }),
    }),
    scope = openFragrantPairRequest(ctx.world, day, kind, request);
  try {
    const raw = await ctx.actionProvider.getAction(request);
    if (fragrantPairRequestScope(ctx.world, request) !== scope)
      throw Error("fragrant_request_unavailable");
    const call = readFragrantPairTool(raw);
    if (!call || call.name !== name) throw Error("fragrant_required_action_invalid");
    const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, call, {
      phase: Phase.Night,
      day,
      fragrantPairScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall || fragrantPairRequestScope(ctx.world, request) !== scope)
      throw Error("fragrant_required_action_invalid");
    // 先由领域 choice 完整提交（含空选），再发布本人事实；finally 的关闭保原 JS 异常优先，不做补偿。
    const receipt = commitFragrantPairChoice(ctx.world, scope, valid.sanitizedCall);
    ctx.events.push(
      "pairIds" in receipt
        ? {
            timestamp: Date.now(),
            type: "fragrant_pair_chosen",
            payload: { policy: FRAGRANT_PAIR_POLICY, ...receipt },
            audience: Object.freeze([actorId]),
          }
        : {
            timestamp: Date.now(),
            type: "fragrant_pair_inspected",
            payload: { policy: FRAGRANT_PAIR_POLICY, ...receipt },
            audience: Object.freeze([actorId]),
          },
    );
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: kind === "bind" ? "fragrant_pair_chosen" : "fragrant_pair_inspected",
      actorId,
      phase: Phase.Night,
      status: "ok",
      output: { policy: FRAGRANT_PAIR_POLICY, ...receipt },
    });
  } finally {
    closeFragrantPairRequest(scope);
  }
}
export const FRAGRANT_BIND_STAGE: NightStageHandler = {
  id: "fragrant_bind",
  priority: 150,
  execute: (ctx) => execute(ctx, "bind"),
};
export const PAIR_INSPECTION_STAGE: NightStageHandler = {
  id: "pair_inspection",
  priority: 600,
  execute: (ctx) => execute(ctx, "pair"),
};

/**
 * 负责寻香魅影与原生成对查验共用的 descriptor 写入、JSON 副本和原数据谓词。
 * 输入为原捕获状态／能力与已验证下一数据；输出保留原严格字段错误、正整数／pair 接受集合与定义顺序。
 * write 先完整核原字段可写／可配置，再逐字段 defineProperty；中途失败保已写前缀，不提供事务或退款。
 * 这些数据工具仅服务本族两个槽，不运行控制器、创建存储、授予租约或结算请求。
 */
import type { Pair } from "@ai-werewolf-arena/game-contract";
import { snapshotPlainData } from "../../../../core/domain/plain_data";

export function plainJson(value: unknown): string | null {
  try {
    return JSON.stringify(snapshotPlainData(value, new Set(), 0, 65536));
  } catch {
    return null;
  }
}

export function assertWritable(value: object, next: object): void {
  if (
    Object.getPrototypeOf(value) !== Object.prototype ||
    Reflect.ownKeys(value).length !== Object.keys(next).length ||
    Object.keys(next).some((key) => {
      const d = Object.getOwnPropertyDescriptor(value, key);
      return !d || !("value" in d) || !d.writable || !d.configurable;
    })
  )
    throw Error("fragrant_state_write_revoked");
}

export function write<T extends object>(value: T, next: T): void {
  assertWritable(value, next);
  for (const key of Object.keys(next) as Array<keyof T>)
    Object.defineProperty(value, key, {
      ...Object.getOwnPropertyDescriptor(value, key),
      value: next[key],
    });
}

export const positive = (v: unknown): v is number =>
  typeof v === "number" && Number.isSafeInteger(v) && v > 0 && v < Number.MAX_SAFE_INTEGER - 1;
export function exact(v: unknown, names: readonly string[]): v is Record<string, unknown> {
  return (
    !!v &&
    typeof v === "object" &&
    !Array.isArray(v) &&
    Object.keys(v).length === names.length &&
    names.every((n) => Object.hasOwn(v, n))
  );
}
export function pair(v: unknown): v is Pair {
  return Array.isArray(v) && v.length === 2 && positive(v[0]) && positive(v[1]) && v[0] < v[1];
}

/**
 * 负责原生 Pair 完整 slot 契约、安装与已审查的查验写入前缀。
 * 输入为原角色或 authority 捕获的槽和已验证下一历史；输出保留 pairSeer/native 同状态引用。
 * 按原顺序写状态 JSON、提交共享 use metadata、再写 ability JSON；authority 随后才提交租约。
 * 安装槽的 LHS 仍先于原能力复制调用；不读时 clone、替换存储状态、退款或吞掉部分写入错误。
 * create/schema、唯一追加写命令、checkpoint codec 与别名／已提交 JSON 失效规则实际统一于本 owner。
 * codec 只在原 JSON 位置编码已验证数据，不把重新校验提前到付款或篡改普通 private 扩展键。
