    /** 保存引用；下方 base 的展开不会读取真正构造器。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (ghostBrideReady(this.world)) return true;
    const setup = weddingSetup(this.world);
    if (!setup || setup.status !== "pending" || day !== 1)
      throw new Error("ghost_bride_setup_unavailable");
    try {
      beginWeddingSetup(this.world, config, isCurrent);
      const base = {
        world: this.world,
        gateway: this.gateway,
        events: this.events,
        provider,
        day,
        isCurrent,
        // 普通数据字段仅传依赖对象；...base 不触发其 requestFactory getter。
        construction: this.construction,
      };
      await executeWeddingTurn({
        ...base,
        actorId: setup.actorId,
        kind: "bridegroom",
        tool: "choose_bridegroom",
        stage: "ghost_bride_groom",
      });
      const pair = weddingPair(this.world)!;
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "chat",
          tool: "speak_to_partner",
          stage: "ghost_bride_chat",
        });
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "witness",
          tool: "choose_wedding_witness",
          stage: "ghost_bride_witness",
        });
      if (!isCurrent() || !ghostBrideReady(this.world))
        throw new Error("ghost_bride_setup_revoked");
      return true;
    } finally {
      closeWeddingSetup(this.world, isCurrent() ? "failed" : "cancelled");
    }
  }
}

/**
 * 负责原生死亡钩子完成之后的赠与／转移死亡枪行动。输入为原死亡玩家、合格死因和当前首死枪；
 * 输出为追加死亡、来源、夜目标及立即／延期枪事件。请求后先核执行资格与死亡许可，消费先于保护和事实，
 * 执行权限由原 gun scope／死亡行动窗口核对，已付 pending 只保原 scope.isCurrent 原体复验；
 * 不重新授枪，晚事件失败不退款，也不让模型预检付款。
 */
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { DeathCause, permitsHunterShot } from "../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import type { DeathHook } from "../hooks/hook_registry";
import {
  activeDeathGun,
  allDeathGuns,
  captureDeathGun,
  consumeDeathGunShot,
} from "./death_abilities";

/** 原生角色死亡钩子依次返回之后，每名玩家读取其首个转移／赠与枪；不在此重新安装或补充库存。 */
export const giftGunDeathHook: DeathHook = async (world, ids, sources, choose, events, context) => {
  const result = {
    extraDeaths: [] as number[],
    extraDeathSources: {} as Record<number, DeathCause[]>,
    pendingShots: [] as NonNullable<
      import("../hooks/hook_registry").DeathHookResult["pendingShots"]
    >,
    nightEffectTargets: [] as number[],
  };
  for (const actorId of ids) {
    const current = () => context?.isCurrent?.() ?? true;
    if (!current()) break;
    const gun = allDeathGuns(world.getComponent(actorId, COMPONENT.Role))[0];
    if (!gun || !permitsHunterShot(sources[actorId] ?? [])) continue;
    const resolutionDay = context?.day;
    if (
      resolutionDay === null ||
      resolutionDay === undefined ||
      activeDeathGun(world, actorId, gun.id, resolutionDay, true) !== gun
    )
      continue;
    const scope = captureDeathGun(world, actorId, gun, resolutionDay, current),
      targets = new Map(world.getAliveEntityIds().map((id) => [id, captureNightLife(world, id)!]));
    const selected = await choose(actorId, gun.id);
    if (
      !scope.isEligible() ||
      selected.kind === "invalid" ||
      !world.isDeathActionOpen(actorId, "shoot", selected.deathActionId, gun.id)
    )
      continue;
    if (selected.kind === "pass") {
      consumeDeathGunShot(gun);
      continue;
    }
    const target = selected.targetScope ?? targets.get(selected.targetId);
    if (!target || target.id !== selected.targetId || !livingNightLife(world, target)) continue;
    // 此刻已消费；保护判断、提案与事件随后执行，pending.current 不能变回未付执行资格。
    consumeDeathGunShot(gun);
    if (context?.nightEffect && context.blocksNightShot(target.id)) {
      events.push({
        timestamp: Date.now(),
        type: "death_shot_blocked",
        payload: { actorId, targetId: target.id, reason: "night_protection" },
      });
      continue;
    }
    const event = {
      timestamp: Date.now(),
      type: "player_shot" as const,
      payload: { actorId, targetId: target.id },
    };
    result.extraDeaths.push(target.id);
    result.extraDeathSources[target.id] = [DeathCause.Shot];
    if (context?.nightEffect) result.nightEffectTargets.push(target.id);
    if (context?.deferShotCommit)
      result.pendingShots.push({ targetScope: target, event, isCurrent: scope.isCurrent });
    else events.push(event);
  }
  return result;
};

/**
 * 负责守墓人的放逐标签捕获与下一夜反馈交付。输入是原 World／目标／放逐日和原阶段上下文；
 * 输出是按当时查验政策形成的反馈副本，或写入原历史后发布的报告事件。
 * 普通板在标死前捕获已接受目标，动物板在死亡／关单位／事实后按生命门控捕获；真实放逐判定与时点仍归规则组合和经理。
 * 本阶段只交付前一日反馈，按原存活名单和接收日去重；不把查验标签等同于真实阵营，不改变死亡、付款或行动许可。
 * 历史成功写入后才发布事件，后续失败不回滚报告；本模块不替代期限、窗口或原体复验。
 */
import { recordExileFeedback } from "./state";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { World } from "../../../../core/domain/world";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Role, type EntityId, type ExileFeedback } from "../../../../core/domain/model";
import { RoleCatalog } from "../catalog";
import { getDefaultRoleCatalog } from "../role-catalog-assembly";
import { resolveInspection } from "../inspection";
import { getGravekeeperState } from "./state";
import type { NightStageHandler } from "../../stages/night/contracts";

/** 仅捕获此刻的 camp 查验标签，不自行核死亡／放逐资格；普通与动物路径各在原门控点调用。
 * 省略 catalog 时仍在原参数位置取得默认实例，结果再浅复制；下一夜交付沿用原反馈结果，不重新调用查验。 */
export function captureExileFeedback(
  world: World,
  targetId: EntityId,
  exileDay: number,
  catalog: RoleCatalog = getDefaultRoleCatalog(),
): ExileFeedback | null {
  const result = resolveInspection(world, targetId, "camp", catalog);
  return result ? { exileDay, targetId, result: { ...result } } : null;
}

export const GRAVEKEEPER_FEEDBACK_STAGE: NightStageHandler = {
  id: "gravekeeper_feedback",
  priority: 550,
  async execute(ctx) {
    const fact = ctx.previousExile,
      receivedDay = ctx.currentDay();
    // 先读取原反馈与日期，再按当前性／前一日短路；过期或无反馈不读取演员名单。
    if (!ctx.isCurrent() || !fact || fact.exileDay !== receivedDay - 1) return;
    for (const actorId of ctx.getAliveByRole(Role.Gravekeeper)) {
      if (!ctx.isCurrent()) return;
      const role = ctx.world.getComponent(actorId, COMPONENT.Role);
      const state = role?.role === Role.Gravekeeper ? getGravekeeperState(role) : undefined;
      // 每名演员仍先复验当前性与实际角色；原去重只看 receivedDay，不另加目标／放逐日规则。
      if (!state || state.history.some((report) => report.receivedDay === receivedDay)) continue;
      // 原历史提交先于 Date.now／事件复制与 push；发布失败保留已写报告，不能补交或退回历史。
      recordExileFeedback(state, fact, receivedDay);
      ctx.events.push({
        timestamp: Date.now(),
        type: "gravekeeper_reported",
        payload: { ...fact, actorId, receivedDay, result: { ...fact.result } },
      });
    }
  },
};

