const parameters = z.strictObject({
  repeatPolicy: z.enum(GUARD_REPEAT_POLICIES).default("awa_last_action_v1"),
});

/** 守卫角色配置。 */
export const GUARD_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Guard,
    camp: Camp.Good,
    label: roleName("guard"),
    skillBrief: text("zh-CN", "role.guard.brief"),
    goodSide: "god",
  },
  runtime: {
    configuration: {
      schema: parameters,
      defaults: { repeatPolicy: "awa_last_action_v1" },
      apply: (config, value) => ({ ...config, guard: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.guard ?? {}),
    },
    init: (roleComp, ctx) => {
      setGuardState(roleComp, {
        lastTarget: null,
        ...(ctx.boardConfig?.guard?.repeatPolicy === "netease_consecutive_nights_v1"
          ? { repeatPolicy: ctx.boardConfig.guard.repeatPolicy }
          : {}),
      });
    },
    toolSpecs: GUARD_TOOL_SPECS,
    validationRules: GUARD_VALIDATION_RULES,
    nightStages: GUARD_NIGHT_STAGES,
    llmRepair: {
      coerce: {
        guard: (args) => {
          const abstain = Boolean(args.abstain);
          if (abstain) return { target_id: null, abstain: true };
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target, abstain: false };
        },
      },
    },
    baselineAction: (roleComp, request, pickAliveNotSelf, _byCamp, _locale, world) => {
      if (!request.allowedTools.includes("guard")) {
        return null;
      }
      const ability = activeNightAbility(
        roleComp,
        "guard",
        request.context.day,
        request.context.ability_id,
      );
      const target =
        world && ability
          ? (world
              .getAliveEntityIds()
              .find(
                (id) =>
                  id !== request.actorId &&
                  !guardTargetRepeated(ability, request.context.day, id) &&
                  luckyTargetAllowed(
                    world,
                    request.actorId,
                    ability,
                    request.context.day,
                    "guard",
                    id,
                  ),
              ) ?? null)
          : pickAliveNotSelf();
      if (
        target !== null &&
        ability &&
        !guardTargetRepeated(ability, request.context.day, target)
      ) {
        return { name: "guard", args: { target_id: target, abstain: false } };
      }
      return { name: "guard", args: { target_id: null, abstain: true } };
    },
  },
  presentation: nativeRolePresentation("guard"),
};

/**
 * 负责守卫普通／受赠能力的原生安装、同槽读取与上次目标字段写入。输入为原角色、
 * 状态或已验证受赠目标；输出保持 nullable lastTarget 和 repeatPolicy，不复制读到的库存。
 * 受赠写入先捕获左侧 ability.state，再读取 target.id getter；普通写入只修改已捕获字段，
 * 守护印记、映射目标、次数及事实发表仍由 caller 按原顺序负责。JSON 复制不扩大旧拒绝集合；
 * prepared owner 安装原库存，政策身份字节仅作既有失效检查，不新增 lease 或档案形状。
 */
import type { GuardState, GuardReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "@ai-werewolf-arena/game-contract";

import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../abilities";

export function setGuardState(roleComp: RoleComponent, state: GuardState): GuardReadState {
  return commitPreparedNativeAbility(roleComp, "guard", GUARD_STATE_SLOT.create(state));
}

export function getGuardState(
  roleComp: RoleComponent,
  abilityId?: string,
): GuardReadState | undefined {
  return findNightAbility(roleComp, "guard", abilityId)?.state;
}

/** caller 保持原效果／发表和能力次数边界，此处只写捕获的目标字段。 */
export function recordGuardTarget(state: GuardReadState, targetId: EntityId | null): void {
  (state as { lastTarget: EntityId | null }).lastTarget = targetId;
}

/** 左侧先捕获原 state，再读取 target.id getter；后段失败仍保留原已提交前缀。 */
export function recordRecipientGuardTarget(
  ability: import("../abilities").NightAbilityReadView<"guard">,
  target: { readonly id: EntityId },
): void {
  const state = ability.state as { lastTarget: EntityId | null };
  state.lastTarget = target.id;
}

/** 原 JSON callee 先于全部状态字段读取；只迁政策身份字节，不新增 payload snapshot 或失效租约。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"guard">): string {
  return JSON.stringify([ability.state.repeatPolicy]);
}

/**
 * 本族完整契约引用原 JSON 复制函数和具体有序写入；create／schema 不改变旧接受集合。
 * install／get 与 caller 都消费同一实例库存，metadata 和 lease 保留唯一原所有者。
 * policyIdentity 是旧失效身份字节；checkpoint 归档并不调用新验证或改变原 privateState 形状。
 */
export const GUARD_STATE_SLOT = Object.freeze({
  create: copyAbilityData<GuardState>,
  schema: copyAbilityData<GuardState>,
  install: setGuardState,
  get: getGuardState,
  allowedWrites: Object.freeze({
    recordGuardTarget,
    recordRecipientGuardTarget,
  }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 负责隐狼原刀继承查询和刷新，输入为原槽、真实 World 与晚阵营 source。
 * 输出为原刀权资格与继承事实；原角色检查后才查阵营，再核继承状态与存活真狼，无 World 不授刀。
 * 持久继承来自实际提交，不改真实阵营，也不从拟议死亡授予权限。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { getHiddenWolfState, recordHiddenWolfKnifeInheritance } from "./state";

/** 当前刀权与已获得的历史继承分别查询；数据标记本身不能恢复权限。 */
export function canHiddenWolfKnife(role: RoleComponent, world: World | undefined, currentCamp: CurrentCampSource): boolean {
  if (
    !world ||
    role.role !== Role.HiddenWolf ||
    currentCamp()?.camp !== Camp.Wolf ||
    getHiddenWolfState(role)?.hasInheritedKnife !== true
  )
    return false;
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => {
      const role = world.getComponent(id, COMPONENT.Role);
      return !!role && world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf;
    });
  return wolves.length === 1 && world.getComponent(wolves[0]!, COMPONENT.Role) === role;
}

/** 仅开局装配或实际死亡 owner 提交此变化；先写标记，发表失败不回退。 */
export function refreshHiddenWolfInheritance(world: World, events: GameEvent[], day: number): void {
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => {
      const role = world.getComponent(id, COMPONENT.Role);
      return !!role && world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf;
    });
  if (wolves.length !== 1) return;
  const actorId = wolves[0]!,
    role = world.getComponent(actorId, COMPONENT.Role)!;
  const state = role.role === Role.HiddenWolf ? getHiddenWolfState(role) : undefined;
  if (!state || state.hasInheritedKnife) return;
  recordHiddenWolfKnifeInheritance(state);
  events.push({ timestamp: Date.now(), type: "hidden_wolf_awakened", payload: { actorId, day } });
}

/**
