}
export function authorizedInitialIdentityScope(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
  kind: InitialIdentityKind,
): InitialIdentityScope | null {
  const active = scopes.get(world);
  return active &&
    active === scope &&
    active.kind === kind &&
    actorId === active.actorId &&
    day === 1 &&
    phase === Phase.Night &&
    sameInitialIdentityScope(active)
    ? active
    : null;
}
export function bindInitialIdentityRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function initialIdentityRequestScope(
  world: World,
  request: ActionRequest,
): InitialIdentityScope | undefined {
  return requestLease.scope(world, request);
}
export function initialIdentityRequestChoices(
  world: World,
  actorId: number,
  kind: InitialIdentityKind,
) {
  const scope = scopes.get(world);
  if (
    !scope ||
    scope.kind !== kind ||
    scope.actorId !== actorId ||
    !sameInitialIdentityScope(scope)
  )
    return undefined;
  return {
    mustChoose: scope.required,
    allowedSlots: [...scope.allowedSlots],
    cards: scope.cards.map((card, slot) => ({
      slot: slot as InitialIdentitySlot,
      role: card.role,
    })),
  };
}
export class InitialIdentitySetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    private readonly kind: InitialIdentityKind,
    /** 保存装配端对象；原创建点才读取构造器，不提前捕获类或共享已创建的工厂。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (initialIdentityKind(this.world) !== this.kind) return true;
    if (hasActiveInitialIdentitySetup(this.world)) throw new Error(`${this.kind}_setup_reentry`);
    if (initialIdentitySetupReady(this.world)) return true;
    if (day !== 1 || initialIdentitySetupStatus(this.world) !== "pending" || !isCurrent())
      throw new Error(`${this.kind}_setup_unavailable`);
    const deal = openInitialIdentitySetup(this.world);
    let status: "complete" | "cancelled" | "failed" = "failed";
    let delivery: RequestLeaseTurn | undefined, failed = false;
    try {
      if (!pendingInitialIdentityDealValid(this.world)) {
        status = "cancelled";
        return false;
      }
      const actorIds = this.world
        .getAliveEntityIds()
        .filter(
          (id) =>
            this.world.getComponent(id, COMPONENT.Role)?.role === initialIdentityRole(this.kind),
        );
      if (actorIds.length === 0) {
        status = "complete";
        return true;
      }
      if (actorIds.length !== 1) throw new Error(`${this.kind}_actor_invalid`);
      const actorId = actorIds[0]!,
        actor = captureDebateParticipant(this.world, actorId),
        state = getInitialIdentityState(actor?.role, this.kind),
        camp = this.world.getComponent(actorId, COMPONENT.Camp),
        victory = this.world.getComponent(actorId, COMPONENT.Victory);
      const cards = deal.reserve.map((card) => {
        const data = readInitialIdentityCard(card);
        return data ? { card, ...data } : null;
      });
      const configJson = frozenJson(config),
        victoryJson = frozenJson(victory);
      if (
        !actor ||
        actor.camp !== Camp.Good ||
        !state ||
        !camp ||
        !victory ||
        cards.some((card) => !card) ||
        configJson === null ||
        victoryJson === null
      ) {
        status = "cancelled";
        return false;
      }
      const participants = this.world
        .entityIds()
        .map((id) => captureDebateParticipant(this.world, id));
      if (participants.some((p) => !p)) {
        status = "cancelled";
        return false;
      }
      const scope: InitialIdentityScope = {
        world: this.world,
        kind: this.kind,
        actorId,
        deal,
        reserve: deal.reserve,
        hands: deal.hands,
        cards: cards as [CardScope, CardScope],
        originalHand: deal.hands.get(actorId)!,
        participants: participants as DebateParticipant[],
        actor,
        state,
        camp,
        victory,
        victoryJson,
        config,
        configJson,
        isCurrent,
        required: initialIdentityChoiceRule(
          this.kind,
          cards.map((c) => c!.role),
        ).mustChoose,
        allowedSlots: initialIdentityChoiceRule(
          this.kind,
          cards.map((c) => c!.role),
        ).allowedSlots,
      };
      scopes.set(this.world, scope);
      if (!sameInitialIdentityScope(scope)) {
        status = "cancelled";
        return false;
      }
      // 原 scope 已安装并复验后才读取构造器；构造或 create 失败仍走下方原 finally 关闭。
      const request = new this.construction.requestFactory(this.world, this.events, 1).create({
        phase: Phase.Night,
        actorId,
        allowedTools: [initialIdentityTool(this.kind)],
        stage: this.kind,
        requiresAction: scope.required,
        summary: {
          key:
            this.kind === "shapeshifter"
              ? "turn.shapeshifter.required"
              : scope.required
                ? "turn.thief.required"
                : "turn.thief.optional",
        },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      // 绑定表不抢 guard；真实窗口在完整 create 返回后才打开自己的交付和完成身份。
      delivery = requestLease.openDelivery(this.world, request);
      if (!sameInitialIdentityScope(scope) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      const call = await provider.getAction(request);
      if (!sameInitialIdentityScope(scope) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      let slot: InitialIdentitySlot | null = null;
      if (call === null) {
        if (scope.required) throw new Error(`${this.kind}_required_choice_missing`);
      } else {
        const choiceCall = readInitialIdentityTool(call, this.kind);
        if (!choiceCall) throw new Error(`${this.kind}_choice_invalid`);
        const valid = this.gateway.validateAndSanitize(this.world, actorId, choiceCall, {
          phase: Phase.Night,
          day: 1,
          ...(this.kind === "thief" ? { thiefScope: scope } : { shapeshifterScope: scope }),
        });
        if (!sameInitialIdentityScope(scope) || delivery.current() !== true) {
          status = "cancelled";
          return false;
        }
        if (!valid.ok || !scope.allowedSlots.includes(choiceCall.args.slot))
          throw new Error(`${this.kind}_choice_invalid`);
        slot = choiceCall.args.slot;
      }
      const chosen = slot === null ? null : scope.cards[slot].card;
      const catalog = getDefaultRoleCatalog();
      // chosen 才准备实际 Camp；创建前移是明确输入政策，retained 路径不额外查询。
      const newCamp = chosen
        ? createCampComponent(catalog.getCamp(chosen.role), this.world.locale)
        : null;
      const newRole = chosen
        ? createRoleComponent(chosen.role, this.world.locale)
        : null;
      const currentCamp = () => this.world.getComponent(actorId, COMPONENT.Camp);
      if (newRole)
        catalog.applyRuntime(newRole, {
          boardConfig: config,
          locale: this.world.locale,
          world: this.world,
          initialCamp: newCamp!,
          currentCamp,
        });
      const newVictory = newRole
        ? createVictoryComponent([{ kind: "faction", faction: newCamp!.camp }])
        : null;
      if (!sameInitialIdentityScope(scope) || delivery.current() !== true) {
        status = "cancelled";
        return false;
      }
      // 物理交换与身份安装之间没有 await、Provider 回调或事件发表。
      if (chosen && slot !== null && newRole && newCamp && newVictory) {
        if (this.kind === "shapeshifter") {
          consumeShapeshifterState(state, slot);
        }
        selectInitialIdentityCard(this.world, actorId, slot);
        // 一旦候选身份开始安装，该核心段失败就永久撤销候选的执行授权；不在 catch 查询 World 或退休旧演员。
        try {
          this.world.addComponent(actorId, COMPONENT.Role, newRole);
          this.world.addComponent(actorId, COMPONENT.Camp, newCamp);
          this.world.addComponent(actorId, COMPONENT.Victory, newVictory);
        } catch (error) {
          retireRoleExecution(newRole);
          throw error;
        }
      } else {
        consumeRetainedInitialIdentityState(state);
        selectInitialIdentityCard(this.world, actorId, null);
      }
      status = "complete";
      closeInitialIdentitySetup(this.world, status);
      scopes.delete(this.world);
      // 物理换牌、全部组件安装与原关闭成功后才落 true；事实／通知晚抛不能再结算 false。
      delivery.complete();
      const data = {
        actorId,
        day: 1 as const,
        role: newRole?.role ?? initialIdentityRole(this.kind),
        camp: newRole ? (() => {
          // 完整安装／关闭已成功；晚字段读取失败保完成前缀，不落候选安装的退休 catch。
          const camp = currentCamp();
          if (!camp) throw new Error("role_current_camp_missing");
          return camp.camp;
        })() : Camp.Good,
      };
      this.events.push(
        this.kind === "shapeshifter"
          ? {
              timestamp: Date.now(),
              type: "shapeshifter_identity_chosen",
              payload: {
                ...data,
                slot: slot!,
                policy: "awa_netease_shapeshifter_two_extra_villagers_v1",
              },
            }
          : {
              timestamp: Date.now(),
              type: "thief_identity_chosen",
              payload: { ...data, slot, policy: "lui_meme_thief_two_extra_villagers_v1" },
            },
      );
      return true;
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      try {
      if (this.kind === "shapeshifter" && status !== "complete") {
        const original =
          scopes.get(this.world)?.state ??
          this.world
            .entityIds()
            .map((id) =>
              getInitialIdentityState(this.world.getComponent(id, COMPONENT.Role), this.kind),
            )
            .find(Boolean);
        cancelShapeshifterState(original);
      }
      scopes.delete(this.world);
      closeInitialIdentitySetup(this.world, status);
      } catch (error) {
        // 原 finally 的清理错误仍按旧 JS 优先于 body 错误；新 false 通知不得覆盖它。
        failed = true;
        throw error;
      } finally {
        if (failed) { try { delivery?.close(); } catch { /* 已有原错误时只完成关闭，保该错误。 */ } }
        else delivery?.close();
      }
    }
  }
}

/**
 * 负责按当前目标角色和运行查验标签形成披露结果。输入为目标编号及阵营／身份／组合查验类型；输出为对应结果或 null。结果不授予行动权限，披露标签可以不同于真实角色和阵营。
 */
import type { InspectionKind, InspectionResult } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { EntityId } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleCatalog } from "./catalog";

/** 只读规则投影，调用此查询不等于取得行动许可。 */
export function resolveInspection<K extends InspectionKind>(
  world: World,
  targetId: EntityId,
  kind: K,
  catalog: RoleCatalog,
): Extract<InspectionResult, { kind: K }> | null {
  const target = world.getComponent(targetId, COMPONENT.Role);
  if (!target) return null;
  const definition = catalog.runtime(target.role)?.inspectionLabels;
  const labels = typeof definition === "function" ? definition(target) : definition;
  const camp = labels?.camp ?? world.getComponent(targetId, COMPONENT.Camp)?.camp,
    role = labels?.role ?? target.role;
  // 两个原字段已按原序读取；身份结果不要求阵营，阵营／组合结果缺当前来源时明确返回 null。
  if (kind === "role") return { kind, role } as Extract<InspectionResult, { kind: K }>;
  if (camp === undefined) return null;
  const result: InspectionResult = kind === "camp" ? { kind, camp } : { kind, camp, role };
  return result as Extract<InspectionResult, { kind: K }>;
}

/**
 * 负责骑士决斗的本族资源消耗、公共事实和死亡提案。输入为原 World、所选编号、阶段与事件数组；
 * 输出为命中／未中提案或 null。按原序核角色、库存、双方存活和目标真实阵营，不以查验伪装代替阵营。
 * 先消费已读取的库存，再发表公共事件，后项失败保已写前缀；不标死、不推进日期或恢复资源。
 * 请求／窗口的原体复验仍由调用方持有，本函数不另建租约或缓存。
 */
import {
  Role,
  Camp,
  Phase,
  DeathCause,
  type KnightDuelSelection,
  type DeathSources,
  type GameEvent,
} from "../../../../core/domain/model";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { World } from "../../../../core/domain/world";
import { getKnightState, consumeKnightDuel } from "./state";

/** 只提交一次库存和事实并返回死亡提案；真正的生命写入仍由死亡结算器负责。 */
export function commitKnightDuel(
  world: World,
  choice: KnightDuelSelection,
  phase: Phase,
  events: GameEvent[],
): { deaths: number[]; sources: DeathSources; endsDay: boolean } | null {
  if (phase !== Phase.Day || choice.actorId === choice.targetId) return null;
  const actor = world.getComponent(choice.actorId, COMPONENT.Role),
    target = world.getComponent(choice.targetId, COMPONENT.Role);
  const state = actor ? getKnightState(actor) : undefined;
  if (
    actor?.role !== Role.Knight ||
    state?.canDuel !== true ||
    !target ||
    !world.getComponent(choice.actorId, COMPONENT.Alive)?.alive ||
    !world.getComponent(choice.targetId, COMPONENT.Alive)?.alive
  )
    return null;
  const hit = world.getComponent(choice.targetId, COMPONENT.Camp)?.camp === Camp.Wolf;
  // 使用本次已读的同一个槽；资源 setter 失败先于发表，发表失败不退还已付资源。
  consumeKnightDuel(state);
  events.push({
    timestamp: Date.now(),
    type: "knight_duel",
    payload: {
      actorId: choice.actorId,
      targetId: choice.targetId,
      result: hit ? "wolf" : "not_wolf",
    },
  });
  return hit
    ? {
        deaths: [choice.targetId],
        sources: { [choice.targetId]: [DeathCause.Duel] },
        endsDay: true,
      }
    : {
        deaths: [choice.actorId],
        sources: { [choice.actorId]: [DeathCause.DuelFailure] },
        endsDay: false,
      };
}

/**
 * 负责骑士白天决斗的完整选择窗口。输入为板子、原 World、请求构造端口、Provider、网关与提交回调；
 * 输出为原选择和是否结束白天，不在本窗口付款、标死或判胜。
 * 捕获演员和目标的存活组件、生命版本及角色／阵营字段，等待后按原顺序复验同一身体和库存。
 * 多骑士并发请求按编号尝试；网关预检两侧均复验，只有有效候选才要求提交回调。
 * 读取、Provider、网关及提交异常原样传播；已写前缀不回滚，缺少回调和明确 rejected 保留原分支。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import {
  Role,
  Phase,
  KnightDuelWindow as DuelWindow,
  type Camp,
  type ActionProvider,
  type KnightDuelSelection,
  type KnightDuelCommit,
} from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import { getKnightState } from "./state";

/** 本次窗口保留原组件引用与当时字段值；不是可序列化玩家资料，也不授予资源或死亡写权。 */
interface DuelParticipantSnapshot {
  // 生命版本记录活跃身体的变化；仅将 alive 改回 true 不恢复旧选择。
  life: AliveComponent;
  version: ReturnType<typeof aliveLifeVersion>;
  role: RoleComponent;
  // 角色保原引用，阵营在原值点晚查；同值 Camp 组件替换仍保持这个值快照，不加引用撤权。
  roleId: Role;
  camp: Camp | undefined;
}

/** 决斗收集保留原提交等待点；真实付款、事实和死亡提案仍归回调与后续经理结算。 */
export class KnightDuelWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: DuelWindow,
    isCurrent: () => boolean,
    commit?: (choice: KnightDuelSelection) => Promise<KnightDuelCommit>,
  ): Promise<{ selection: KnightDuelSelection | null; endsDay: boolean }> {
    // 原空结果在本次调用内共用；先查当前窗口，再按原配置或默认发言后机会筛选。
    const empty = { selection: null, endsDay: false };
    if (
      !isCurrent() ||
      !(config.knight?.enabledWindows ?? [DuelWindow.AfterSpeeches]).includes(window)
    )
      return empty;
    if (
      !this.world.getAliveEntityIds().some((id) => {
        const role = this.world.getComponent(id, COMPONENT.Role);
        return role?.role === Role.Knight && getKnightState(role)?.canDuel === true;
      })
    )
      return empty;
    // 先确认存在可决斗骑士，再完整捕获存活名单；不提前缓存配置、角色或库存。
    const snapshots = new Map<number, DuelParticipantSnapshot>(
      this.world.getAliveEntityIds().map((id) => {
        const life = this.world.getComponent(id, COMPONENT.Alive)!,
          role = this.world.getComponent(id, COMPONENT.Role)!;
        return [
          id,
          { life, version: aliveLifeVersion(life), role, roleId: role?.role, camp: role == null ? undefined : this.world.getComponent(id, COMPONENT.Camp)?.camp },
        ] as const;
      }),
    );
    // 每个演员在请求前读取同一库存，Promise.all 保持快照名单顺序，不以响应先后提交。
    const picks = await Promise.all(
      [...snapshots].map(async ([actorId, actor]) => {
        const state = actor.role?.role === Role.Knight ? getKnightState(actor.role) : undefined;
        if (state?.canDuel !== true) return null;
        const action = await provider.getAction(
          requests.create({
            phase: Phase.Day,
            actorId,
            allowedTools: ["duel"],
            stage: window,
            requiresAction: false,
            summary: { key: "request.summary.knight_duel" },
            context: { duel_window: window },
          }),
        );
        if (action?.name !== "duel") return null;
        return { actorId, actor, state, action, target: snapshots.get(action.args.target_id) };
      }),
    );
    // 原生命、组件、角色及阵营字段都需匹配；此查询不消费库存，也不修改捕获对象。
    const sameLife = (id: number, snapshot: DuelParticipantSnapshot) =>
      this.world.getComponent(id, COMPONENT.Alive) === snapshot.life &&
      snapshot.life.alive &&
      snapshot.version !== undefined &&
      aliveLifeVersion(snapshot.life) === snapshot.version &&
      this.world.getComponent(id, COMPONENT.Role) === snapshot.role &&
      snapshot.role?.role === snapshot.roleId &&
      (snapshot.role == null ? undefined : this.world.getComponent(id, COMPONENT.Camp)?.camp) === snapshot.camp;
    for (const pick of picks
      .filter((item): item is NonNullable<typeof item> => item !== null)
      .sort((a, b) => a.actorId - b.actorId)) {
      // 按编号排序后的每次尝试，均在网关前后复验阶段、同一库存和目标生命。
      const valid = () =>
        isCurrent() &&
        sameLife(pick.actorId, pick.actor) &&
        getKnightState(pick.actor.role) === pick.state &&
        pick.state.canDuel &&
        pick.target !== undefined &&
        sameLife(pick.action.args.target_id, pick.target);
      if (
        !valid() ||
        !this.gateway.validateAndSanitize(this.world, pick.actorId, pick.action, {
          phase: Phase.Day,
          duelWindow: window,
          allowKnightDuel: true,
        }).ok ||
        !valid()
      )
        continue;
      // 缺回调只在有效候选处报原错误；rejected 继续下一项，提交抛错不回滚已有写入。
      if (!commit) throw new Error("knight_duel_commit_missing");
      const selection = { actorId: pick.actorId, targetId: pick.action.args.target_id },
        outcome = await commit(selection);
      if (outcome === "rejected") continue;
      return { selection, endsDay: outcome === "night" || outcome === "terminal" };
    }
    return empty;
  }
}

/**
 * 负责 骑士 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Role, Camp, Phase, KnightDuelWindow } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { getKnightState, initializeKnightState } from "./state";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";

export const KNIGHT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Knight,
    camp: Camp.Good,
    goodSide: "god",
    label: roleName("knight"),
    skillBrief: text("zh-CN", "role.knight.brief"),
  },
  runtime: {
    init: initializeKnightState,
    configuration: {
      schema: z.strictObject({
        enabledWindows: z
          .array(z.enum(KnightDuelWindow))
          .refine((windows) => new Set(windows).size === windows.length)
          .default([KnightDuelWindow.AfterSpeeches]),
      }),
      defaults: { enabledWindows: [KnightDuelWindow.AfterSpeeches] },
      apply: (config, value) => ({
        ...config,
        knight: value as {
          enabledWindows: KnightDuelWindow[];
        },
      }),
      serialize: (config) => ({
        enabledWindows: [...(config.knight?.enabledWindows ?? [KnightDuelWindow.AfterSpeeches])],
      }),
    },
    toolSpecs: [
      {
        name: "duel",
        parameters: {
          type: "object",
          properties: { target_id: { type: "number" }, confirm: { type: "boolean" } },
          required: ["target_id", "confirm"],
          additionalProperties: false,
        },
        argHint: 'duel args: {"target_id":number,"confirm":true}',
        userPromptHintKey: "action.knight.hint",
      },
    ],
    validationRules: {
      duel: ({ world, actorId, role, toolCall, phase, duelWindow, allowKnightDuel }) => {
        if (role.role !== Role.Knight || getKnightState(role)?.canDuel !== true)
          return { code: RuleError.KnightDuelUnavailable };
        if (
          phase !== Phase.Day ||
          !allowKnightDuel ||
          duelWindow === undefined ||
          !Object.values(KnightDuelWindow).includes(duelWindow)
        )
          return { code: RuleError.KnightDuelWindow };
        if (toolCall.name !== "duel" || toolCall.args.confirm !== true)
          return { code: RuleError.KnightDuelConfirm };
        if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
          return { code: RuleError.KnightDuelTarget };
        return null;
      },
    },
    stageDirectives: [
      {
        match: (tools) => tools.length === 1 && tools[0] === "duel",
        messageKey: "action.knight.directive",
        text: text("zh-CN", "action.knight.directive"),
      },
    ],
    llmRepair: {
      coerce: {
        duel: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target, confirm: Boolean(args.confirm) };
        },
      },
    },
    baselineAction: () => null,
  },
  presentation: nativeRolePresentation("knight"),
};

/**
 * 负责骑士普通数据槽的安装、同引用读取、初始化、玩家投影与已捕获决斗库存消耗。
 * 输入为原角色组件／状态或已通过原提交检查的库存；输出为同一 live 引用、原写入结果或脱离的玩家库存数据。
 * 普通读取和安装不运行 schema，不拒绝原 getter／原型属性／Proxy，也不复制或冻结库存。
 * 消耗只写捕获 canDuel，资格、生命、窗口和事件仍归原 caller；后续发表失败不退还资源。
 * 共享数据类型的 readonly 不是运行权限；本族不另建镜像、租约或检查点协议。
 */
import type { KnightState, KnightReadState } from "@ai-werewolf-arena/game-contract";

import type { PlayerKnightState } from "@ai-werewolf-arena/game-contract/player-state-views";
import { playerDataField } from "../player-state-data";
import type { RoleComponent } from "../../../../core/domain/components/role";

export function setKnightState(roleComp: RoleComponent, state: KnightState): KnightReadState {
  (roleComp.privateState as { knight: KnightState })["knight"] = state;
  return state;
}

export function getKnightState(roleComp: RoleComponent): KnightReadState | undefined {
  return (roleComp.privateState as { readonly knight?: unknown })["knight"] as
    KnightReadState | undefined;
}

/** caller 已完成原决斗前检；只消费捕获的同一对象，不再读角色槽或复验许可。 */
export function consumeKnightDuel(state: KnightReadState): void {
  (state as { canDuel: boolean }).canDuel = false;
}

/** 原初始化完整写体：先形成默认数据，再由原安装函数写同一 privateState 槽；不检查角色或创建许可。 */
export function initializeKnightState(role: RoleComponent): void {
  setKnightState(role, { canDuel: true });
}

/** 原玩家投影只接受自有数据字段为 true，输出新对象；不消费库存或授予行动资格。 */
export function projectKnightState(state: unknown): PlayerKnightState {
  return { canDuel: playerDataField(state, "canDuel") === true };
}

/**
 * 负责孤独少女首夜选择、原参与者／生命与独立 Victory 归属，拥有原关系绑定及窗口时序。
 * 输入为原 World 参与者和首夜请求；输出为已接受选择、捕获目标阵营对应的成员关系及原准备结果。
 * 不变量：仅在原身份／资源仍匹配时提交；关闭或替换参与者使 scope 失效，包括期限别名。
 * 阵营捕获与晚复验只来自同一真实 Camp；保原组件引用与值检查，成员关系仍用捕获历史值。
 * 选择不改变演员的 Role／Camp，已选成员关系在双方死亡后仍保留；本模块不新增目标死亡结算。
 * 数据写由槽执行，失败窗口审计保留原授权身份，不读取外来 accessor 或恢复已消耗库存。
 * 请求记录及别名传播归独立公共实例；观察请求或原领域失配后许可不复活；付款/取消仍由本族执行，别名自身损坏不毒原请求。
 */
import type { LonelyGirlReadState } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RequestLease } from "../../../../core/domain/request-lease";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Camp,
  Role,
  Phase,
  createVictoryComponent,
  type World,
  type ActionRequest,
  type RoleComponent,
  type CampComponent,
  type VictoryComponent,
} from "../../../../core/domain";
import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import { freshLonelyGirlState, getLonelyGirlState, LONELY_GIRL_POLICY, lonelyData,
  consumeLonelyGirlState, cancelLonelyGirlState, projectLonelyGirlData } from "./state-slot";
interface Participant {
  id: number;
  life: AliveComponent;
  version: number;
  alive: PropertyDescriptor;
  role: RoleComponent;
  kind: Role;
  state: RoleComponent["privateState"];
  camp: CampComponent;
  campValue: Camp;
  privateSnapshot: Record<string, unknown>;
}
export interface LonelyGirlBinding {
  world: World;
  actorId: number;
  actor: Participant;
  participants: ReadonlyMap<number, Participant>;
  state: LonelyGirlReadState;
  config: ReadonlyBoardConfig;
  configJson: string;
  victory: VictoryComponent;
  affiliations: VictoryComponent["affiliations"];
  status: "pending" | "active" | "complete" | "failed" | "cancelled";
  choice: LonelyGirlReadState["choice"];
  membership: Camp | null;
  isCurrent: (() => boolean) | null;
}
const bindings = new WeakMap<World, LonelyGirlBinding>(),
  nights = new WeakMap<World, Set<number>>(),
  activeNights = new WeakSet<World>();
/** phase 先于 context 身份的原协议独立保留；不复制选择许可；公共 turn 记录已观察的永久撤权。 */
const requestLease = RequestLease.actorPhaseStageDay<World, LonelyGirlBinding>(
  {
    active: (world) => bindings.get(world),
    owner: (binding) => binding.world,
    actorId: (binding) => binding.actorId,
    phase: () => Phase.Night,
    stage: () => "lonely_girl",
    current: (binding) => validLonelyGirlChoice(binding),
  },
  40,
);
function safeJson(value: unknown): string | null {
  try {
    const p = copyEventData(value);
    return p === null ? null : JSON.stringify(p);
  } catch {
    return null;
  }
}
function capture(world: World, id: number): Participant | null {
  const life = world.getComponent(id, COMPONENT.Alive),
    role = world.getComponent(id, COMPONENT.Role),
    camp = world.getComponent(id, COMPONENT.Camp),
    version = life && aliveLifeVersion(life),
    alive = life && Object.getOwnPropertyDescriptor(life, "alive"),
    kind = lonelyData(role, "role"),
    capturedCamp = lonelyData(camp, "camp"),
    state = lonelyData(role, "privateState"),
    campValue = lonelyData(camp, "camp");
  if (
    !life ||
    version === undefined ||
    !alive ||
    life.alive !== true ||
    !role ||
    !camp ||
    typeof kind !== "string" ||
    !state ||
    typeof state !== "object" ||
    ![Camp.Good, Camp.Wolf].includes(capturedCamp as Camp) ||
    campValue !== capturedCamp
  )
    return null;
  return {
    id,
    life,
    version,
    alive,
    role,
    kind: kind as Role,
    state: state as RoleComponent["privateState"],
    camp,
    campValue: campValue as Camp,
    privateSnapshot: structuredClone(state) as Record<string, unknown>,
  };
}
function same(world: World, p: Participant): boolean {
  const d = Object.getOwnPropertyDescriptor(p.life, "alive");
  return (
    world.getComponent(p.id, COMPONENT.Alive) === p.life &&
    aliveLifeVersion(p.life) === p.version &&
    !!d &&
    d.get === p.alive.get &&
    d.set === p.alive.set &&
    d.value === p.alive.value &&
    p.life.alive === true &&
    world.getComponent(p.id, COMPONENT.Role) === p.role &&
    lonelyData(p.role, "role") === p.kind &&
    lonelyData(p.camp, "camp") === p.campValue &&
    lonelyData(p.role, "privateState") === p.state &&
    world.getComponent(p.id, COMPONENT.Camp) === p.camp &&
    lonelyData(p.camp, "camp") === p.campValue
  );
}
export function installLonelyGirl(world: World, config: ReadonlyBoardConfig): void {
  if (bindings.has(world)) throw new Error("lonely_girl_already_installed");
  const actorId = world
    .entityIds()
    .find((id) => lonelyData(world.getComponent(id, COMPONENT.Role), "role") === Role.LonelyGirl);
  if (actorId === undefined) return;
  const participants = new Map(world.entityIds().map((id) => [id, capture(world, id)] as const)),
    actor = participants.get(actorId),
    state = getLonelyGirlState(actor?.role),
    victory = world.getComponent(actorId, COMPONENT.Victory),
    affiliations = lonelyData(victory, "affiliations"),
    configJson = safeJson(config);
  if (
    !actor ||
    !state ||
    !victory ||
    !Array.isArray(affiliations) ||
    safeJson(affiliations) !== "[]" ||
    !configJson ||
    [...participants.values()].some((p) => !p)
  )
    throw new Error("lonely_girl_initial_state_invalid");
  bindings.set(world, {
    world,
    actorId,
    actor,
    participants: participants as Map<number, Participant>,
    state,
    config,
    configJson,
    victory,
    affiliations,
    status: "pending",
    choice: null,
    membership: null,
    isCurrent: null,
  });
}
export function lonelyGirlBinding(world: World): LonelyGirlBinding | undefined {
  return bindings.get(world);
}
function pendingOwner(b: LonelyGirlBinding): boolean {
  const rem = Object.getOwnPropertyDescriptor(b.state, "remaining"),
    choice = Object.getOwnPropertyDescriptor(b.state, "choice");
  return (
    bindings.get(b.world) === b &&
    b.participants.size === b.world.entityIds().length &&
    [...b.participants.values()].every((p) => same(b.world, p)) &&
    b.actor.kind === Role.LonelyGirl &&
    b.actor.campValue === Camp.Good &&
    getLonelyGirlState(b.actor.role) === b.state &&
    rem?.value === 1 &&
    rem.writable === true &&
    choice?.value === null &&
    choice.writable === true &&
    b.world.getComponent(b.actorId, COMPONENT.Victory) === b.victory &&
    lonelyData(b.victory, "affiliations") === b.affiliations &&
    safeJson(b.affiliations) === "[]" &&
    safeJson(b.config) === b.configJson
  );
}
export function lonelyGirlReady(world: World): boolean {
  const b = bindings.get(world);
  return b
    ? b.status === "complete"
    : !world
        .entityIds()
        .some(
          (id) => lonelyData(world.getComponent(id, COMPONENT.Role), "role") === Role.LonelyGirl,
        );
}
export function hasActiveLonelyGirl(world: World): boolean {
  return bindings.get(world)?.status === "active" || activeNights.has(world);
}
export function hasLonelyGirlNightCommit(world: World, day: number): boolean {
  return nights.get(world)?.has(day) ?? false;
}
export function openLonelyGirlChoice(b: LonelyGirlBinding, isCurrent: () => boolean): boolean {
  if (b.status !== "pending") throw new Error("lonely_girl_setup_unavailable");
  b.status = "active";
  b.isCurrent = isCurrent;
  return validLonelyGirlChoice(b);
}
export function validLonelyGirlChoice(b: LonelyGirlBinding): boolean {
  return b.status === "active" && b.isCurrent?.() === true && pendingOwner(b);
}
export function authorizedLonelyGirl(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
): boolean {
  const b = bindings.get(world);
  return (
    !!b &&
    b === scope &&
    b.actorId === actorId &&
    day === 1 &&
    phase === Phase.Night &&
    validLonelyGirlChoice(b)
  );
}
export function bindLonelyGirlRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function lonelyGirlRequestScope(
  world: World,
  request: ActionRequest,
): LonelyGirlBinding | undefined {
  return requestLease.scope(world, request);
}
/** 仅本族真实窗口打开交付，原 scope/资源仍由当前生命周期唯一复验。 */
export function openLonelyGirlRequestDelivery(world: World, request: ActionRequest) {
  return requestLease.openDelivery(world, request);
}

export function commitLonelyGirlChoice(b: LonelyGirlBinding, targetId: number): Camp | null {
  const target = b.participants.get(targetId);
  if (!target || targetId === b.actorId || !validLonelyGirlChoice(b)) return null;
  const choice = { day: 1 as const, targetId },
    membership = createVictoryComponent([{ kind: "faction", faction: target.campValue }]);
  // 最后权限检查后依次交数据所有者写库存与选择，再安装 Victory；两者之间没有 await。
  consumeLonelyGirlState(b, choice);
  b.world.addComponent(b.actorId, COMPONENT.Victory, membership);
  b.choice = Object.freeze({ ...choice });
  b.membership = target.campValue;
  b.status = "complete";
  b.isCurrent = null;
  return target.campValue;
}
export function closeLonelyGirlChoice(b: LonelyGirlBinding, status: "failed" | "cancelled"): void {
  if (b.status === "complete") return;
  b.status = status;
  b.isCurrent = null;
  cancelLonelyGirlState(b);
}
export function projectLonelyGirl(
  world: World,
  role: RoleComponent,
): LonelyGirlReadState | undefined {
  const b = bindings.get(world);
  if (!b || b.actor.role !== role) return undefined;
  return projectLonelyGirlData(b, () => pendingOwner(b));
}
export function projectLonelyGirlSetup(world: World) {
  const b = bindings.get(world);
  return b
    ? {
        policy: LONELY_GIRL_POLICY,
        status: b.status === "active" ? ("pending" as const) : b.status,
        actorId: b.actorId,
      }
    : undefined;
}
export function projectLonelyGirlVictory(
  world: World,
  actorId: number,
): VictoryComponent | undefined {
  const b = bindings.get(world);
  return b?.actorId === actorId
    ? createVictoryComponent(b.membership ? [{ kind: "faction", faction: b.membership }] : [])
    : undefined;
}
export function openLonelyGirlNight(world: World, day: number): () => void {
  if (!bindings.has(world)) return () => {};
  if (hasActiveLonelyGirl(world) || !lonelyGirlReady(world) || hasLonelyGirlNightCommit(world, day))
    throw new Error("lonely_girl_night_unavailable");
  const days = nights.get(world) ?? new Set<number>();
  days.add(day);
  nights.set(world, days);
  activeNights.add(world);
  return () => {
    activeNights.delete(world);
  };
}

/** 失败窗口审计使用原授权身份／资源，不读取 foreign accessor。 */
export function projectLonelyGirlAuditPlayer(world: World, id: number) {
  const b = bindings.get(world),
    p = b?.participants.get(id);
  if (!b || !p || (b.status !== "failed" && b.status !== "cancelled")) return undefined;
  const alive = p.alive.get ? p.alive.get.call(p.life) === true : p.alive.value === true;
  return {
    role: p.kind,
    camp: p.campValue,
    alive,
    privateState:
      id === b.actorId
        ? { lonelyGirl: { ...freshLonelyGirlState(), remaining: 0 } }
        : structuredClone(p.privateSnapshot),
  };
}

/**
 * 负责 孤独少女 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition } from "../../../../core/domain";
import type { NativeRoleContributions } from "../contracts";
import {
  LONELY_GIRL_POLICY,
  initializeLonelyGirlState,
  readLonelyGirlTool,
} from "./state-slot";
import { authorizedLonelyGirl, projectLonelyGirl } from "./lifecycle";
const parameters = z.strictObject({
  policy: z.literal(LONELY_GIRL_POLICY).default(LONELY_GIRL_POLICY),
});
export const LONELY_GIRL_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.LonelyGirl,
    camp: Camp.Good,
    goodSide: "villager",
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.LonelyGirl,
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Idiot,
    ],
    label: roleName("lonely_girl"),
    skillBrief: text("zh-CN", "role.lonely_girl.brief"),
  },
  runtime: {
    initialVictoryAffiliations: [],
    canSelfDestruct: false,
    init: (role) => {
      initializeLonelyGirlState(role);
    },
    configuration: {
