/**
 * 负责孤独少女首夜心仪对象选择及原失败／取消路径。
 * 输入为只读板子、原参与者、provider 和惰性构造依赖；输出为心仪对象提交成功或准备中断。
 * 先核准备状态再打开原窗口，await 两侧复验参与者；阵营归属、库存及 finally 关闭归原生命周期。
 * 已失败或关闭的选择不重写游戏参数，不重新开启准备，也不授予过期请求许可。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { Phase, type World, type GameEvent, type ActionProvider } from "../../../../core/domain";
import type { RequestLeaseTurn } from "../../../../core/domain/request-lease";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { LONELY_GIRL_POLICY, readLonelyGirlTool } from "./state-slot";
import {
  lonelyGirlBinding,
  lonelyGirlReady,
  hasActiveLonelyGirl,
  openLonelyGirlChoice,
  validLonelyGirlChoice,
  commitLonelyGirlChoice,
  closeLonelyGirlChoice,
  openLonelyGirlRequestDelivery,
} from "./lifecycle";
export class LonelyGirlSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    /** 只保存惰性构造依赖；不预建请求，原准备和权限检查仍先执行。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (hasActiveLonelyGirl(this.world)) throw new Error("lonely_girl_setup_reentry");
    if (lonelyGirlReady(this.world)) return true;
    const b = lonelyGirlBinding(this.world);
    if (!b || b.status !== "pending" || config !== b.config || day !== 1)
      throw new Error("lonely_girl_setup_unavailable");
    let status: "failed" | "cancelled" = "failed";
    let delivery: RequestLeaseTurn | undefined, failed = false;
    try {
      if (!openLonelyGirlChoice(b, isCurrent)) {
        status = "cancelled";
        return false;
      }
      // 原选择窗口已开后才取构造器，并用本次 World／事件／day 创建实例；失败仍按原 finally 关闭。
      const request = new this.construction.requestFactory(this.world, this.events, day).create({
        phase: Phase.Night,
        actorId: b.actorId,
        allowedTools: ["choose_admired_player"],
        stage: "lonely_girl",
        requiresAction: true,
        summary: { key: "turn.lonely_girl.required" },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      // create 完成后打开原 turn；域状态先按原时点复验，后读请求／预算许可。
      delivery = openLonelyGirlRequestDelivery(this.world, request);
      if (!validLonelyGirlChoice(b) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      const raw = await provider.getAction(request);
      if (!validLonelyGirlChoice(b) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      const call = readLonelyGirlTool(raw);
      if (!call) throw new Error("lonely_girl_required_choice_missing");
      const result = this.gateway.validateAndSanitize(this.world, b.actorId, call, {
        phase: Phase.Night,
        day,
        lonelyGirlScope: b,
      });
      if (!validLonelyGirlChoice(b) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      if (!result.ok) throw new Error("lonely_girl_choice_invalid");
      const camp = commitLonelyGirlChoice(b, call.args.target_id);
      if (!camp) throw new Error("lonely_girl_choice_invalid");
      // 完整领域 commit 已返回成功；通知或事实晚抛仍 true，不重新核已付款的 pending 状态。
      delivery.complete();
      this.events.push({
        timestamp: Date.now(),
        type: "lonely_girl_admired_chosen",
        payload: {
          policy: LONELY_GIRL_POLICY,
          actorId: b.actorId,
          day: 1,
          targetId: call.args.target_id,
          camp,
        },
      });
      return true;
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      try {
        closeLonelyGirlChoice(b, status);
      } catch (error) {
        failed = true;
        throw error;
      } finally {
        // 原 body／cleanup 错误优先；无旧错时新增 false 通知错误正常传播。
        if (failed) { try { delivery?.close(); } catch { /* 保已在传播的错误。 */ } }
        else delivery?.close();
      }
    }
  }
}

/**
 * 负责孤独少女三字段槽的创建／安装、原复制校验、同引用读取、消费／取消数据写入及知识结构投影。
 * 输入为原角色、数据绑定与已核选择；输出为原状态引用、逐字段提交前缀或脱离的玩家知识副本。
 * 复制校验只保原 policy／库存／首夜 choice 接受集合，不扩大 schema，也不把玩家投影当作实际阵营或许可。
 * 生命周期继续拥有参与者／生命、复制成员关系、Victory 安装和关闭；数据失败不会补回库存或吞异常。
 */
import type { LonelyGirlState, LonelyGirlReadState } from "@ai-werewolf-arena/game-contract";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import { LONELY_GIRL_POLICY } from "@ai-werewolf-arena/game-contract/facts/lonely-girl";
import type { RoleComponent } from "../../../../core/domain";
export {
  LONELY_GIRL_POLICY,
  readLonelyGirlChoiceTool as readLonelyGirlTool,
} from "@ai-werewolf-arena/game-contract/facts/lonely-girl";
export function freshLonelyGirlState(): LonelyGirlState {
  return { policy: LONELY_GIRL_POLICY, remaining: 1, choice: null };
}
export function lonelyData(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object") return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && Object.hasOwn(d, "value") ? d.value : undefined;
}
export function getLonelyGirlState(
  role: RoleComponent | undefined,
): LonelyGirlReadState | undefined {
  const value = lonelyData(lonelyData(role, "privateState"), "lonelyGirl");
  try {
    const p = copyEventData(value) as LonelyGirlReadState;
    if (
      !p ||
      Array.isArray(p) ||
      Object.keys(p).length !== 3 ||
      p.policy !== LONELY_GIRL_POLICY ||
      ![0, 1].includes(p.remaining) ||
      (p.choice !== null &&
        (typeof p.choice !== "object" ||
          Array.isArray(p.choice) ||
          Object.keys(p.choice).length !== 2 ||
          p.choice.day !== 1 ||
          !Number.isSafeInteger(p.choice.targetId) ||
          p.choice.targetId < 1 ||
          p.remaining !== 0))
    )
      return undefined;
    return value as LonelyGirlReadState;
  } catch {
    return undefined;
  }
}

import type { RoleInitializationComponent } from "../contracts";

/** 保原同引用查询、LHS 与 fresh callee 的先后；初始化不建立新的 World 或许可记录。 */
export function initializeLonelyGirlState(role: RoleInitializationComponent): void {
  if (!getLonelyGirlState(role)) role.privateState.lonelyGirl = freshLonelyGirlState();
}

/** 两项原资源写先于 lifecycle 的 Victory 安装；后者失败不回滚已消费槽。 */
export function consumeLonelyGirlState(b: { state: LonelyGirlReadState }, choice: NonNullable<LonelyGirlReadState["choice"]>): void {
  (b.state as Pick<LonelyGirlState, "remaining">).remaining = 0;
  (b.state as Pick<LonelyGirlState, "choice">).choice = choice;
}

/** 原关闭状态先写；只沿各自可写 data descriptor 逐项改值，第二项失败保留第一项。 */
export function cancelLonelyGirlState(b: { state: LonelyGirlReadState }): void {
  for (const [key, value] of [
    ["remaining", 0],
    ["choice", null],
  ] as const) {
    const d = Object.getOwnPropertyDescriptor(b.state, key);
    if (d && Object.hasOwn(d, "value") && d.writable)
      Object.defineProperty(b.state, key, { ...d, value });
  }
}

/** 投影只消费 lifecycle 的原状态／选择和当前性查询；不复制实际阵营或授予原窗口资格。 */
export function projectLonelyGirlData(
  b: { status: "pending" | "active" | "complete" | "failed" | "cancelled"; choice: LonelyGirlReadState["choice"] },
  pendingOwner: () => boolean,
): LonelyGirlReadState {
  return b.status === "complete"
    ? { ...freshLonelyGirlState(), remaining: 0, choice: b.choice && { ...b.choice } }
    : {
        ...freshLonelyGirlState(),
        remaining: (b.status === "pending" || b.status === "active") && pendingOwner() ? 1 : 0,
      };
}

/**
 * 负责由魔术师配置决定的三族共享清理移交。输入为调用处求值的配置布尔值和延迟 World 读取；
 * 输出为同一只读移交查询及魔术师正常关闭／中止调用。本单位拥有 transferred，狼术师和诡术师共读该视图。
 * 移交只按原布尔值赋值，不是配置原引用、成功开夜回执或行动授权；不开独立 acquired／closed 守卫。
 * priority=80 的开夜仍归阶段。经理每次传入当次 World／day，未移交时清理才晚读 runtime.world；
 * frame 保留关闭／中止和重复调用的原政策；查询或 World 读取失败原样传播，不承诺幂等或补偿前缀。
 * 本单位不映射目标、消费号码、退还历史或推进阶段。
 */
import type { World } from "../../../../core/domain/world";
import { closeMagicianNight, abortMagicianNight } from "./night_frame";

/** 只保存运行对象供需要中止时读取 World；构造不执行 world getter，也不复制玩家或捕获生命。 */
export interface MagicianNightRuntime {
  readonly world: World;
}

/** 三族共用的运行查询，每次读取原移交布尔值；它不提供移交命令、World 或请求许可。 */
export interface MagicianNightCleanupOwnership {
  readonly isTransferred: () => boolean;
}

/** 冻结的是终结方法表；每次用调用方当次参数交原 frame，不缓存夜间或增加关闭去重。 */
export const magicianNightTerminal = Object.freeze({
  closeNormally(world: World, day: number): void {
    closeMagicianNight(world, day);
  },
  abort(world: World): void {
    abortMagicianNight(world);
  },
});

export class MagicianNightUnit {
  /** 经理接收同一单位；字段保存终结表的原函数值，World／day 由当次调用传入而非构造时捕获。 */
  readonly closeNormally = magicianNightTerminal.closeNormally;
  readonly abort = magicianNightTerminal.abort;

  // 初始清理由流水线保有；该冻结视图只冻结方法表，闭包仍读取本单位当前 transferred。
  private transferred = false;
  readonly cleanupOwnership: MagicianNightCleanupOwnership = Object.freeze({
    isTransferred: () => this.transferred,
  });

  constructor(private readonly runtime: MagicianNightRuntime) {}

  /** 保原赋值，包括再次传 false；只记录调用方配置判断，不复验原体或建立新的清理许可。 */
  transferToManager(configured: boolean): void {
    this.transferred = configured;
  }

  /** 先判移交值；未移交才查原中止函数并晚读 World，失败按原调用栈传播，不增加重试。 */
  abortIfOwned(): void {
    if (!this.transferred) abortMagicianNight(this.runtime.world);
  }
}

/**
 * 负责魔术师夜间交换原体绑定、当前窗口和目标映射回执；输入为原玩家生命／身份和二人选择。
 * Camp 只在原字段点查询实际组件，名单保原值比较，不额外以同值新组件撤权。
 * 输出为仍当前的映射及原关闭／取消结果；boards 唯一拥有夜关系和状态身份检查点，state-slot
 * 只执行原数据读写／编码。当前性失败不修复原体或恢复已经使用的号码，不让旧交换续权。
 * 先校验原体，再写历史、刷新 expectedState、安装本夜 pair 并提交窗口；后续失败不回滚已写前缀。
 */
import type { MagicianReadState } from "@ai-werewolf-arena/game-contract";
import { isWolfSorcererBoard, resolveWolfSorcererNightTarget } from "../wolf_sorcerer/exchange-ports";
import { matchingExchangePairs } from "../trickster/exchange-ports";
import { types } from "node:util";
import { COMPONENT, type Camp, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import { getMagicianState, projectMagicianState, MAGICIAN_ROLE, MAGICIAN_STATE_SLOT } from "./state-slot";

interface OriginalPlayer {
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: Camp | undefined;
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface ExchangeNight {
  day: number;
  closed: boolean;
  committed: boolean;
  pair: readonly [number, number] | null;
  targets: ReadonlyMap<number, OriginalPlayer>;
}
/** state 是原 live 引用，expectedState 是原投影 JSON 身份；同内容替换 state 仍不能通过原体检查。 */
interface Board {
  actorId: number;
  state: MagicianReadState;
  expectedState: string;
  players: ReadonlyMap<number, OriginalPlayer>;
  night: ExchangeNight | null;
}
const boards = new WeakMap<World, Board>();
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(world.getComponent(p.id, COMPONENT.Camp), "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // 已提交交换可跨一次普通死亡保留；复活或换生命不能用同编号继续原关系。
  return p.life.alive ? version === p.version : version === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("magician_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("magician_original_state_revoked");
  const actor = b.players.get(b.actorId)!;
  if (getMagicianState(actor.role, () => world.getComponent(actor.id, COMPONENT.Camp)) !== b.state || MAGICIAN_STATE_SLOT.checkpoint.identity(actor.role, () => world.getComponent(actor.id, COMPONENT.Camp)) !== b.expectedState)
    throw new Error("magician_original_state_revoked");
  return b;
}
export function installMagicianBoard(world: World): void {
  if (boards.has(world)) throw new Error("magician_board_already_installed");
  const players = new Map<number, OriginalPlayer>();
  const seats = new Set<number>();
  let actorId: number | null = null;
  let state: MagicianReadState | undefined;
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (!role || !life || types.isProxy(life) || version === undefined)
      throw new Error("magician_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("magician_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(world.getComponent(id, COMPONENT.Camp), "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("magician_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("magician_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      id,
      role,
      roleName: role.role,
      camp: world.getComponent(id, COMPONENT.Camp)?.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });
    if (String(role.role) === MAGICIAN_ROLE) {
      if (actorId !== null) throw new Error("magician_original_roster_invalid");
      actorId = id;
      state = getMagicianState(role, () => world.getComponent(id, COMPONENT.Camp));
    }
  }
  if (actorId === null || !state || state.history.length !== 0)
    throw new Error("magician_original_roster_invalid");
  boards.set(world, {
    actorId,
    state,
    expectedState: MAGICIAN_STATE_SLOT.checkpoint.identity(players.get(actorId)!.role, () => world.getComponent(actorId, COMPONENT.Camp)),
    players,
    night: null,
  });
}
export function isMagicianBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}
export function beginMagicianNight(world: World, day: number): number | null {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day <= 0 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || day !== b.night.day + 1))
  )
    throw new Error("magician_night_invalid");
  const used = new Set<number>();
  for (const choice of projectMagicianState(b.players.get(b.actorId)!.role, () => world.getComponent(b.actorId, COMPONENT.Camp))!.history)
    if (choice.pair) {
      used.add(choice.pair[0]);
      used.add(choice.pair[1]);
    }
  const targets = new Map([...b.players].filter(([id, p]) => p.life.alive && !used.has(id)));
  const eligible =
    day >= b.state.firstNight && b.players.get(b.actorId)!.life.alive && targets.size >= 2;
  b.night = { day, closed: false, committed: !eligible, pair: null, targets };
  return eligible ? b.actorId : null;
}
export function magicianChoiceTargets(world: World, day: number): number[] {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.committed) return [];
  return [...n.targets.values()].filter((p) => p.life.alive).map((p) => p.id);
}
export function commitMagicianExchange(
  world: World,
  actorId: number,
  day: number,
  pair: readonly [number, number] | null,
): void {
  const b = requireBoard(world),
    n = b.night;
  if (
    !n ||
    n.day !== day ||
    n.closed ||
    n.committed ||
    b.actorId !== actorId ||
    !b.players.get(actorId)!.life.alive
  )
    throw new Error("magician_choice_scope_invalid");
  let chosen: [number, number] | null = null;
  if (pair !== null) {
    if (types.isProxy(pair) || !Array.isArray(pair))
      throw new Error("magician_choice_target_invalid");
    const descriptors: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      pair as object,
    );
    const a = descriptors["0"]?.value,
      z = descriptors["1"]?.value;
    if (
      Reflect.ownKeys(descriptors).length !== 3 ||
      descriptors.length?.value !== 2 ||
      !Number.isSafeInteger(a) ||
      !Number.isSafeInteger(z) ||
      a <= 0 ||
      z <= 0
    )
      throw new Error("magician_choice_target_invalid");
    if (a === z || !n.targets.get(a)?.life.alive || !n.targets.get(z)?.life.alive)
      throw new Error("magician_choice_target_invalid");
    chosen = a < z ? [a, z] : [z, a];
  }
  // 槽内仍先找 defineProperty callee，再两次晚读 state/history；成功写历史后才推进原 frame 检查点。
  MAGICIAN_STATE_SLOT.allowedWrites.appendHistory(() => b.state, day, chosen);
  b.expectedState = MAGICIAN_STATE_SLOT.checkpoint.identity(b.players.get(actorId)!.role, () => world.getComponent(actorId, COMPONENT.Camp));
  n.pair = chosen && Object.freeze([chosen[0], chosen[1]] as [number, number]);
  n.committed = true;
}
export interface MagicianResolvedTarget {
  readonly requestedId: number;
  readonly effectiveId: number;
  readonly scope: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export function resolveMagicianNightTarget(
  world: World,
  day: number,
  requestedId: number,
  kind: "night_action" | "death_shot" = "night_action",
): MagicianResolvedTarget {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed) throw new Error("magician_night_unsettled");
  const original = b.players.get(requestedId);
  if (!original || !original.life.alive) throw new Error("magician_target_invalid");
  const originalShot = kind === "death_shot" && b.state.deathShotTargetPolicy === "original";
  // 原复合映射先解狼术师 W(raw)，再解魔术师 M；交换的是位置中的占有者。
  // 公共绑定在此先识别板子再读映射；不提前缓存 World、政策或狼术师回执。
  // 夜间死亡枪链的中间占有者可能已死，不能提前按普通夜行动的目标生命拒绝。
  const second = isWolfSorcererBoard(world)
    ? resolveWolfSorcererNightTarget(
        world,
        day,
        requestedId,
        originalShot ? "original" : "intermediate",
      )
    : null;
  const intermediateId = second?.effectiveId ?? requestedId;
  const pair = originalShot ? null : n.pair;
  const effectiveId = pair
    ? intermediateId === pair[0]
      ? pair[1]
      : intermediateId === pair[1]
        ? pair[0]
        : intermediateId
    : intermediateId;
  const effective = b.players.get(effectiveId)!;
  if (kind === "night_action" && !effective.life.alive) throw new Error("magician_target_invalid");
  const nightPair = n.pair;
  const requestedVersion = aliveLifeVersion(original.life)!;
  const scope: NightLifeScope = Object.freeze({
    id: effectiveId,
    life: effective.life,
    version: aliveLifeVersion(effective.life)!,
  });
  return Object.freeze({
    requestedId,
    effectiveId,
    scope,
    isCurrent: () => {
      try {
        return (
          requireBoard(world) === b &&
          b.night === n &&
          n.pair === nightPair &&
          (!second || second.isCurrent()) &&
          !n.closed &&
          originalPlayer(world, original) &&
          originalPlayer(world, effective) &&
          original.life.alive &&
          aliveLifeVersion(original.life) === requestedVersion &&
          aliveLifeVersion(effective.life) === scope.version
        );
      } catch {
        return false;
      }
    },
  });
}
export function closeMagicianNight(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed) throw new Error("magician_night_unsettled");
  n.closed = true;
}

export function assertMagicianRosterCurrent(world: World): void {
  requireBoard(world);
}
export function magicianChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireBoard(world),
    n = b.night;
  return (
    b.actorId === actorId &&
    !!n &&
    n.day === day &&
    !n.closed &&
    !n.committed &&
    b.players.get(actorId)!.life.alive
  );
}

/** 仅封住已存在的夜窗口；不校验／修复撤权原体，也不制造选择或追回已消费号码。 */
export function abortMagicianNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n) n.closed = true;
}

/** 只取消当前匹配 pair 的映射，已经提交的号码消耗仍在历史中，不退款或改写状态槽。 */
export function cancelMagicianExchangeIfMatching(
  world: World,
  day: number,
  pair: readonly [number, number],
): boolean {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed) throw new Error("magician_night_unsettled");
  if (!n.pair || !matchingExchangePairs(n.pair, pair)) return false;
  // 原当前夜与同配对校验通过后只清 pair；双方历史／已用号码仍保留，不把取消视为退款。
  n.pair = null;
  return true;
}

/**
 * 负责在被映射的夜间行动之前请求魔术师交换；输入为已安装 frame、原请求和经预检的二人选择。
 * 输出为原交换提交及本人私有事实；等待前后仍复核原体／阶段／日次，不把提示候选当成付款或许可。
 * 数据校验归本族 state-slot，关系／窗口归 frame；本阶段保持先 commit 后发布的失败前缀，
 * 不提前通过提示执行目标映射，后续行动仍取得原映射回执。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getMagicianState } from "./state-slot";
import {
  assertMagicianRosterCurrent,
  beginMagicianNight,
  commitMagicianExchange,
  magicianChoiceTargets,
} from "./night_frame";
/** 按板子已配置角色集运行，包括魔术师已死亡时的原开夜路径；是否出请求仍由 frame 判断。 */
export const MAGICIAN_EXCHANGE_STAGE: NightStageHandler = {
  id: "magician_exchange",
  priority: 80,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = beginMagicianNight(ctx.world, day);
    if (actorId === null) return;
    const role = ctx.world.getComponent(actorId, COMPONENT.Role);
    if (!getMagicianState(role, () => ctx.world.getComponent(actorId, COMPONENT.Camp))) throw new Error("magician_actor_invalid");
    const request = ctx.makeRequest(actorId, ["swap_targets"], {
      stage: "magician_exchange",
      requiresAction: true,
      action_failure_policy: "error",
      allow_fallback: false,
      swap_candidates: magicianChoiceTargets(ctx.world, day),
    });
    assertMagicianRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertMagicianRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("magician_exchange_stale");
    if (action?.name !== "swap_targets") throw new Error("magician_exchange_action_missing");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertMagicianRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("magician_exchange_stale");
    if (!validated.ok || validated.sanitizedCall?.name !== "swap_targets")
      throw new Error("magician_exchange_action_invalid");
    const args = validated.sanitizedCall.args;
    const pair: [number, number] | null = args.abstain ? null : [args.first_id!, args.second_id!];
    commitMagicianExchange(ctx.world, actorId, day, pair);
    ctx.events.push({
      timestamp: Date.now(),
      type: "magician_exchange_committed",
      payload: {
        actorId,
        day,
        pair: pair && [Math.min(pair[0], pair[1]), Math.max(pair[0], pair[1])],
      },
      audience: Object.freeze([actorId]),
    });
  },
};

/**
 * 负责 魔术师 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 当前阵营通过调用方的晚读 source 传入；目录阵营仅为初值，不替代现场 Camp 或授予许可。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { MAGICIAN_POLICY, MAGICIAN_STATE_SLOT, getMagicianState } from "./state-slot";
import { magicianChoicePending, magicianChoiceTargets } from "./night_frame";
import { MAGICIAN_EXCHANGE_STAGE } from "./night_stages";
const parameters = z.strictObject({
  policy: z.literal(MAGICIAN_POLICY).default(MAGICIAN_POLICY),
  firstNight: z.union([z.literal(1), z.literal(2)]).default(1),
  deathShotTargetPolicy: z.enum(["original", "exchanged"]).default("original"),
});
export const MAGICIAN_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Magician,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.WolfSorcerer,
      Role.Psychic,
      Role.Trickster,
      Role.OrderPrince,
      Role.Wolf,
      Role.WolfKing,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Magician,
    ],
    label: roleName("magician"),
    skillBrief: text("zh-CN", "role.magician.brief"),
  },
  runtime: {
    init: (role, ctx) => {
      const value = parameters.parse(ctx.boardConfig?.magician ?? {});
      // 原左值容器先于 create 参数读取；仅移交这次赋值，不提前取状态或冻结初始化结果。
      MAGICIAN_STATE_SLOT.install(() => role.privateState, value);
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, magician: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.magician ?? {}),
    },
    toolSpecs: [
      {
        name: "swap_targets",
        parameters: {
          type: "object",
          properties: {
            first_id: { type: ["integer", "null"], minimum: 1 },
            second_id: { type: ["integer", "null"], minimum: 1 },
            abstain: { type: "boolean" },
          },
          required: ["first_id", "second_id", "abstain"],
          additionalProperties: false,
        },
        argHint:
          'swap_targets args: {"first_id":number|null,"second_id":number|null,"abstain":true|false}',
        userPromptHintKey: "action.swap_targets.hint",
      },
    ],
    stageDirectives: [
      {
        match: (tools) => tools.length === 1 && tools[0] === "swap_targets",
        messageKey: "action.swap_targets.directive",
        text: text("zh-CN", "action.swap_targets.directive"),
      },
    ],
    validationRules: {
      swap_targets: ({ world, role, actorId, day, phase, toolCall }) => {
        if (
          !getMagicianState(role, () => world.getComponent(actorId, COMPONENT.Camp)) ||
          day === undefined ||
          phase !== Phase.Night ||
          toolCall.name !== "swap_targets" ||
          !magicianChoicePending(world, actorId, day)
        )
          return { code: RuleError.MagicianUnavailable };
        const { first_id, second_id, abstain } = toolCall.args;
        if (abstain)
          return first_id === null && second_id === null
            ? null
            : { code: RuleError.MagicianTarget };
        const targets = magicianChoiceTargets(world, day);
        return first_id !== null &&
          second_id !== null &&
          first_id !== second_id &&
          targets.includes(first_id) &&
          targets.includes(second_id)
          ? null
          : { code: RuleError.MagicianTarget };
      },
    },
    nightStages: [MAGICIAN_EXCHANGE_STAGE],
    baselineAction: (role, request, _pick, _pickCamp, _locale, world, currentCamp) => {
      if (!request.allowedTools.includes("swap_targets") || !world || !getMagicianState(role, currentCamp))
        return null;
      const targets = magicianChoiceTargets(world, request.context.day);
      return targets.length >= 2
        ? {
            name: "swap_targets",
            args: { first_id: targets[0]!, second_id: targets[1]!, abstain: false },
          }
        : { name: "swap_targets", args: { first_id: null, second_id: null, abstain: true } };
    },
  },
  presentation: nativeRolePresentation("magician"),
};

/**
 * 负责魔术师唯一状态槽的创建、完整 live 校验、同引用读取、初始化／历史写入与原身份编码。
 * 输入为原角色、参数及晚读容器，输出为原状态引用、脱离知识副本或原明确拒绝；原完整字段、
 * descriptor、日次、排序及一次性号码校验不变。写权仅收走原赋值与历史追加，失败保留已写前缀。
 * frame 仍拥有原体生命、夜窗口、交换关系及 expectedState 检查点；此槽不另建立 shadow、
 * 退款、标死、关闭、付新资源或授予请求许可。身份 JSON 仅为原运行比对，档案 schema／核验仍归原 owner。
 * 角色阵营渠道已退出；reader／project 以显式晚读 CurrentCampSource 获取实际 Camp，原 raw schema／写者不因此获得许可。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import type {
  MagicianChoice,
  MagicianState,
  MagicianReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const MAGICIAN_ROLE = "magician" as const;
export const MAGICIAN_POLICY = "awa_magician_wolf_king_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}
/** 完整原 live 校验：仅读自身数据 descriptor，先拒绝 Proxy；不调用 Role／状态字段 getter、迭代器或数组方法。
 * 合法时返回原状态及历史引用，不克隆／冻结；readonly 是读方类型，不能替代 frame 原授权。 */
// 显式 Camp source 在原 camp 点晚调用，可以执行调用方代码并抛错；返回组件保本族 descriptor／Proxy 策略，不回退角色或目录。
export function getMagicianState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): MagicianReadState | undefined {
  if (field(role, "role") !== MAGICIAN_ROLE || field(currentCamp(), "camp") !== Camp.Good) return undefined;
  const state = field(field(role, "privateState"), "magician");
  if (!exact(state, ["policy", "firstNight", "deathShotTargetPolicy", "history"])) return undefined;
  const firstNight = field(state, "firstNight");
  if (field(state, "policy") !== MAGICIAN_POLICY || (firstNight !== 1 && firstNight !== 2))
    return undefined;
  const shot = field(state, "deathShotTargetPolicy");
  if (shot !== "original" && shot !== "exchanged") return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  // 历史日期严格递增；非空二人组保持原升序／全局号码一次使用，null 不消耗号码。
  let previous = 0;
  const used = new Set<number>();
  for (const entry of history) {
    if (!exact(entry, ["day", "pair"])) return undefined;
    const day = field(entry, "day"),
      rawPair = field(entry, "pair");
    if (!integer(day) || day < firstNight || day <= previous) return undefined;
    previous = day;
    if (rawPair === null) continue;
    const pair = arrayItems(rawPair);
    if (
      !pair ||
      pair.length !== 2 ||
      !integer(pair[0]) ||
      !integer(pair[1]) ||
      pair[0] >= pair[1] ||
      used.has(pair[0]) ||
      used.has(pair[1])
    )
      return undefined;
    used.add(pair[0]);
    used.add(pair[1]);
  }
  return state as MagicianReadState;
}
export function createMagicianState(
  firstNight: 1 | 2,
  deathShotTargetPolicy: "original" | "exchanged" = "original",
): MagicianState {
  return { policy: MAGICIAN_POLICY, firstNight, deathShotTargetPolicy, history: [] };
}
/** 按原 descriptor 逐行复制知识，嵌套二人组脱离；不使用 caller 数组 species 或解码为运行许可。 */
export function projectMagicianState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): MagicianState | undefined {
  const state = getMagicianState(role, currentCamp);
  if (!state) return undefined;
  const history: MagicianChoice[] = [];
  for (const row of arrayItems(field(state, "history"))!) {
    const rawPair = field(row, "pair");
    const values = rawPair === null ? null : arrayItems(rawPair)!;
    history.push({
      day: field(row, "day") as number,
      pair: values ? [values[0] as number, values[1] as number] : null,
    });
  }
  return {
    policy: MAGICIAN_POLICY,
    firstNight: field(state, "firstNight") as 1 | 2,
    deathShotTargetPolicy: field(state, "deathShotTargetPolicy") as "original" | "exchanged",
    history,
  };
}

/** 初始化只有原左值赋值：容器先于 create 的参数读取，setter 或创建失败不补写或回滚。 */
function installMagicianState(
  privateState: () => Record<string, unknown>,
  value: { firstNight: 1 | 2; deathShotTargetPolicy: "original" | "exchanged" },
): void {
  privateState().magician = createMagicianState(
    value.firstNight,
    value.deathShotTargetPolicy,
  );
}

/** 原准入仍由 frame 完成；先取 defineProperty，再两次晚读原状态，保 index／descriptor 写入顺序。 */
function appendMagicianHistory(
  state: () => MagicianReadState,
  day: number,
  chosen: [number, number] | null,
): void {
  Object.defineProperty(state().history, String(state().history.length), {
    value: { day, pair: chosen },
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/** 原 frame 的身份编码，不是严格档案 codec；先 project／拒绝，再找 JSON.stringify 并编码原副本。 */
function encodeMagicianStateIdentity(
  role: RoleComponent,
  currentCamp: CurrentCampSource,
): string {
  const view = projectMagicianState(role, currentCamp);
  if (!view) throw new Error("magician_original_state_revoked");
  return JSON.stringify(view);
}

/**
 * 本族唯一数据槽贡献：schema 与 get 是同一完整 live 校验，不另造更严格接受政策。
 * allowedWrites 保原初始化和历史 descriptor 写；frame 的 expectedState、pair、committed
 * 仍在原顺序更新。checkpoint 只提供原 JSON 身份编码，不存第二份状态或解析玩家许可。
 * 冻结的是贡献方法表，不冻结输入状态、历史或投影；录制仍完整克隆原 privateState。
 */
export const MAGICIAN_STATE_SLOT = Object.freeze({
  create: createMagicianState,
  schema: getMagicianState,
  get: getMagicianState,
  project: projectMagicianState,
  install: installMagicianState,
  allowedWrites: Object.freeze({ appendHistory: appendMagicianHistory }),
  checkpoint: Object.freeze({ identity: encodeMagicianStateIdentity }),
});

/**
 * 负责机械狼原学习枪贡献的装配。输入为原死亡波与晚查询；输出为同枪捕获 reader 和原枪击提案。
 * 捕获表每次 hook 独立创建；资源 owner 核原 state／learning／gun，不复制库存或复活已消费枪。
 * 查询函数在原 callee 点取得并裸调用；此装配不授许可、不标死或切换阶段，付款／失败由完整结算处理。
 * 在原有序死亡钩子时点只装配原读写贡献；许可与生命仍由结算复验，失败不补偿已付款库存。
 */
import { Role, permitsDeathShot } from "../../../../core/domain/model";
import type { DeathHook } from "../../hooks/hook_registry";
import { resolveNativeDeathShots } from "../native-death-shot-settlement";
import { getMechanicalState } from "./state";
import { createMechanicalGunReader } from "../native-death-gun-resources";

export const mechanicalDeathHook: DeathHook = (world, ids, sources, choose, events, context) => {
  const readGun = createMechanicalGunReader({ get getMechanicalState() { return getMechanicalState; } });
  return resolveNativeDeathShots(
    world,
    ids,
    sources,
    choose,
    events,
    {
      role: Role.MechanicalWolf,
      state: readGun,
      permits: permitsDeathShot,
      shotEvent: (actorId, targetId) => ({
        timestamp: Date.now(),
        type: "mechanical_shot",
        payload: { actorId, targetId },
      }),
    },
    context,
  );
};

/**
 * 负责机械狼当前刀继承资格与原继承事实；输入为实际存活名单、原槽和晚阵营 source。
 * 状态先按原点查询，再核角色／阵营／模式；无 World 时仍保守拒刀，不建立 Role 反向索引。
 * 输出为刀权资格或原继承事实；刷新不改复制技能或真实阵营，先写继承再发表，后续错误保留已写前缀。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { hasCurrentMechanicalKillMode } from "./night_scope";
import { getMechanicalState, mechanicalKnifeSelected, recordMechanicalInheritance } from "./state";

export interface MechanicalInheritanceFact {
  readonly actorId: EntityId;
  readonly day: number;
  readonly firstKnifeNight: number;
}

/** 只读资格保持保守分支，不创建继承，也不恢复已失效的本夜模式。 */
export function canMechanicalKnife(role: RoleComponent, world: World | undefined, currentCamp: CurrentCampSource): boolean {
  const state = getMechanicalState(role);
  if (
    !world ||
    role.role !== Role.MechanicalWolf ||
    currentCamp()?.camp !== Camp.Wolf ||
    !state ||
    !mechanicalKnifeSelected(state, state.mode?.day ?? 0) ||
    !hasCurrentMechanicalKillMode(world, role)
  )
    return false;
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => {
      const role = world.getComponent(id, COMPONENT.Role);
      return !!role && world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf;
    });
  return wolves.length === 1 && world.getComponent(wolves[0]!, COMPONENT.Role) === role;
}

/** 仅装配或死亡 owner 提交完整实际死亡后调用；事实副本不授当前刀权。 */
export function refreshMechanicalInheritance(
  world: World,
  day: number,
  events?: GameEvent[],
): MechanicalInheritanceFact[] {
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => {
      const role = world.getComponent(id, COMPONENT.Role);
      return !!role && world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf;
    });
  if (wolves.length !== 1) return [];
  const actorId = wolves[0]!,
    role = world.getComponent(actorId, COMPONENT.Role)!;
  if (role.role !== Role.MechanicalWolf) return [];
  const state = getMechanicalState(role);
  if (!state || !recordMechanicalInheritance(state, day)) return [];
  const fact = { actorId, day, firstKnifeNight: state.firstKnifeNight! };
  events?.push({ timestamp: Date.now(), type: "mechanical_awakened", payload: fact });
  return [fact];
}

/**
 * 负责机械狼原体、复制技能与已选模式范围，输入保原生命／槽／来源，输出为复验和实际本夜提交记录。
 * 原阵营表达式晚查当前值，不新增 Camp 引用撤权；替换模式／槽仍不能复用原学习或刀权。
 * 已付技能谓词保原资源独立性，不将行动退休混入原体复验或删除知识数据。
 */
import type {
  MechanicalMode,
  MechanicalReadState as MechanicalState,
  MechanicalReadSkill as MechanicalSkill,
} from "@ai-werewolf-arena/game-contract";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import { getMechanicalState } from "./state";

export interface MechanicalOwnerScope {
  readonly world: World;
  readonly actorId: EntityId;
  readonly role: RoleComponent;
  readonly state: MechanicalState;
  readonly life: NightLifeScope;
  isCurrent(): boolean;
  /** 仅未付执行的拒绝条件；调用方仍按原序检查当前性、阶段、资源和目标。 */
  canAct(): boolean;
}

/** 仅运行引用，不序列化进玩家 DTO 或 Tape，也不是状态副本的授权。 */
export function captureMechanicalOwner(
  world: World,
  actorId: EntityId,
  phaseCurrent: () => boolean,
): MechanicalOwnerScope | null {
  const role = world.getComponent(actorId, COMPONENT.Role);
  const state = getMechanicalState(role);
  const life = captureNightLife(world, actorId);
  if (
    !phaseCurrent() ||
    !role ||
    role.role !== Role.MechanicalWolf ||
    world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf ||
    !state ||
    !life
  )
    return null;
  const privateState = role.privateState;
  return {
    world,
    actorId,
    role,
    state,
    life,
    // 捕获原 Role，只读永久退休状态；不查 World／Camp，不污染已付 isCurrent。
    canAct: () => !isRoleExecutionRetired(role),
    isCurrent: () =>
      phaseCurrent() &&
      world.getComponent(actorId, COMPONENT.Role) === role &&
      role.role === Role.MechanicalWolf &&
      world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Wolf &&
      role.privateState === privateState &&
      getMechanicalState(role) === state &&
      livingNightLife(world, life),
  };
}

/** 已提交效果绑定原学习和所选模式；不按已经消费的库存取消效果。 */
export function bindMechanicalSkill(
  scope: MechanicalOwnerScope,
  day: number,
): {
  readonly skill: MechanicalSkill;
  isCurrent(): boolean;
} | null {
  const learned = scope.state.learned,
    mode = scope.state.mode;
  if (
    day < 2 ||
    !scope.isCurrent() ||
    !hasCurrentMechanicalMode(scope.world, scope.role, "skill") ||
    !learned ||
    learned.readyOnNight > day ||
    !mode ||
    mode.day !== day ||
    mode.kind !== "skill"
  )
    return null;
  const skill = learned.skill,
    kind = skill.kind;
  return {
    skill,
    isCurrent: () =>
      scope.isCurrent() &&
      hasCurrentMechanicalMode(scope.world, scope.role, "skill") &&
      scope.state.learned === learned &&
      learned.skill === skill &&
      skill.kind === kind &&
      scope.state.mode === mode &&
      mode.day === day &&
      mode.kind === "skill" &&
      learned.readyOnNight <= day,
  };
}

interface MechanicalModeScope {
  readonly owner: MechanicalOwnerScope;
  readonly mode: NonNullable<MechanicalState["mode"]>;
  readonly kind: MechanicalMode;
}
const modes = new WeakMap<
  World,
  { readonly day: number; readonly actors: Map<EntityId, MechanicalModeScope> }
>();
const committed = new WeakMap<World, Set<number>>();
export function hasMechanicalNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
export function recordMechanicalNightCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

/** 接受模式选择或原明确 skill 默认后才保存本夜 authority，失败不重建旧范围。 */
export function recordMechanicalModeScope(
  world: World,
  scope: MechanicalOwnerScope,
  day: number,
): boolean {
  const mode = scope.state.mode;
  if (scope.world !== world || day < 2 || !scope.isCurrent() || !mode || mode.day !== day)
    return false;
  let night = modes.get(world);
  if (night && night.day > day) return false;
  if (!night || night.day !== day) {
    night = { day, actors: new Map() };
    modes.set(world, night);
  }
  if (night.actors.has(scope.actorId)) return false;
  night.actors.set(scope.actorId, { owner: scope, mode, kind: mode.kind });
  return true;
}

/** 只读刀权查询；序列化模式事实不能恢复已经失效的原 authority。 */
export function hasCurrentMechanicalMode(
  world: World,
  role: RoleComponent,
  expectedKind: MechanicalMode,
): boolean {
  const night = modes.get(world);
  if (!night) return false;
  for (const { owner, mode, kind } of night.actors.values()) {
    if (
      owner.role === role &&
      owner.isCurrent() &&
      owner.state.mode === mode &&
      mode.day === night.day &&
      mode.kind === kind &&
      kind === expectedKind
    )
      return true;
  }
  return false;
}
export function hasCurrentMechanicalKillMode(world: World, role: RoleComponent): boolean {
  return hasCurrentMechanicalMode(world, role, "kill");
}

/**
 * 负责机械狼模式、学习、复制技能和额外刀阶段。
 * 输入为原 owner/mode/技能 scope 与已验证工具；输出为原已付事实及有来源的盾、刀、失败、原毒 intent。
 * intent 只复用原捕获 life/day/目标，不增加 World、时钟或 RNG 读取；原付款和记录次序保持。
 * 有效性仍由原 callback 决定，不合并不同技能资源或失败规则；运行时来源不写入归档。
 */
import {
  recordMechanicalInspection,
  consumeMechanicalPoison,
  closeMechanicalExtraKnife,
} from "./state";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase, StatusMark, type EntityId, type ToolName } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife, mechanicalNightIntent, originalPoisonIntent } from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { resolveInspection } from "../inspection";
import { canMechanicalKnife } from "./inheritance";
import {
  bindMechanicalSkill,
  captureMechanicalOwner,
  recordMechanicalModeScope,
  recordMechanicalNightCommit,
} from "./night_scope";
import {
  advanceMechanicalNight,
  canMechanicalMimic,
  canSelectMechanicalMode,
  chooseMechanicalGuard,
  closeMechanicalMimic,
  closeMechanicalSkill,
  learnMechanicalRole,
  mechanicalSkillForNight,
  selectMechanicalMode,
  canMechanicalExtraKnife,
} from "./state";

function owners(ctx: NightStageContext) {
  return ctx.world.getAliveEntityIds().flatMap((id) => {
    const owner = captureMechanicalOwner(ctx.world, id, ctx.isCurrent);
    return owner ? [owner] : [];
  });
}
function targets(ctx: NightStageContext, actorId: EntityId, excludeSelf: boolean) {
  return new Map(
    ctx.world
      .getAliveEntityIds()
      .filter((id) => !excludeSelf || id !== actorId)
      .map((id) => [id, captureNightLife(ctx.world, id)!] as const),
  );
}
function effects(ctx: NightStageContext) {
  return (ctx.state.mechanicalEffects ??= { shields: [], attacks: [], failures: [] });
}

const modeStage: NightStageHandler = {
  id: "mechanical_mode",
  priority: 250,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx)) {
      if (!owner.isCurrent()) continue;
      // 原已学习枪的武装／首刀到期是生命周期；退休只阻止后面的新模式，不跳过此前缀。
      advanceMechanicalNight(owner.state, day);
      if (!canSelectMechanicalMode(owner.state, day) || !owner.canAct()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!owner.isCurrent() || !canSelectMechanicalMode(owner.state, day) || !owner.canAct()) break;
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, ["mechanical_mode"], {
            stage: "mechanical_mode",
            requiresAction: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!owner.isCurrent() || !canSelectMechanicalMode(owner.state, day) || !owner.canAct()) break;
        let chosenMode: "skill" | "kill" = "skill";
        if (action !== null) {
          if (action.name !== "mechanical_mode") continue;
          const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
            phase: Phase.Night,
            day,
          });
          if (!owner.isCurrent() || !valid.ok || valid.sanitizedCall?.name !== "mechanical_mode" || !owner.canAct())
            continue;
          chosenMode = valid.sanitizedCall.args.mode;
        }
        // args.mode 等晚 getter 已读完；首个模式写入前只复验退休标记。
        if (!owner.canAct()) break;
        if (!selectMechanicalMode(owner.state, day, chosenMode, owner.canAct)) break;
        recordMechanicalModeScope(ctx.world, owner, day);
        recordMechanicalNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "mechanical_mode_selected",
          payload: { actorId: owner.actorId, day, mode: owner.state.mode!.kind },
        });
        completed = true;
        break;
      }
      if (!completed && owner.isCurrent() && canSelectMechanicalMode(owner.state, day) && owner.canAct())
        throw new Error("mechanical_mode_valid_action_missing");
    }
  },
};

const mimicStage: NightStageHandler = {
  id: "mechanical_mimic",
  priority: 580,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx)) {
      if (!canMechanicalMimic(owner.state, day)) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!owner.isCurrent() || !canMechanicalMimic(owner.state, day) || !owner.canAct()) break;
        const candidates = targets(ctx, owner.actorId, true);
        const targetRoles = new Map(
          [...candidates.keys()].map((id) => {
            const role = ctx.world.getComponent(id, COMPONENT.Role)!;
            return [id, { component: role, role: role.role }] as const;
          }),
        );
        if (!owner.canAct()) break;
        const action = candidates.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(owner.actorId, ["mimic_role"], {
                stage: "mechanical_mimic",
                requiresAction: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!owner.isCurrent() || !canMechanicalMimic(owner.state, day) || !owner.canAct()) break;
        if (action === null) {
          if (!closeMechanicalMimic(owner.state, day, owner.canAct)) break;
          recordMechanicalNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "mechanical_mimic_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "mimic_role") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (
          !owner.isCurrent() ||
          !valid.ok ||
          valid.sanitizedCall?.name !== "mimic_role" ||
          !canMechanicalMimic(owner.state, day) ||
          !owner.canAct()
        )
          continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = candidates.get(targetId),
          targetRole = targetRoles.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target) ||
          !targetRole ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== targetRole.component ||
          targetRole.component.role !== targetRole.role
        )
          continue;
        // 候选原体／生命 getter 仍先按原序执行，退休后不写入新的学习数据。
        if (!owner.canAct()) break;
        if (!learnMechanicalRole(owner.state, targetId, targetRole.role, day, owner.canAct)) continue;
        recordMechanicalNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "mechanical_mimicked",
          payload: {
            actorId: owner.actorId,
            day,
            targetId,
            role: owner.state.learned!.role,
            readyOnNight: day + 1,
          },
        });
        completed = true;
        break;
      }
      if (!completed && owner.isCurrent() && canMechanicalMimic(owner.state, day) && owner.canAct())
        throw new Error("mechanical_mimic_valid_action_missing");
    }
  },
};

const skillStage: NightStageHandler = {
  id: "mechanical_skill",
  priority: 650,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx)) {
      const skill = mechanicalSkillForNight(owner.state, day),
        bound = bindMechanicalSkill(owner, day);
      if (!skill || !bound || !["inspection", "poison", "guard"].includes(skill.kind)) continue;
      if (skill.kind === "poison" && skill.remaining === 0) continue;
      const tool: ToolName =
        skill.kind === "inspection"
          ? "mechanical_inspect"
          : skill.kind === "poison"
            ? "mechanical_poison"
            : "mechanical_guard";
      const current = () =>
        bound.isCurrent() &&
        mechanicalSkillForNight(owner.state, day) === skill &&
        (skill.kind !== "poison" || skill.remaining > 0) &&
        owner.canAct();
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, skill.kind === "inspection");
        if (!owner.canAct()) break;
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, [tool], {
            stage: "mechanical_skill",
            requiresAction: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!current()) break;
        if (action === null) {
          if (!closeMechanicalSkill(owner.state, day, owner.canAct)) break;
          recordMechanicalNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "mechanical_skill_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== tool) continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || !valid.sanitizedCall) continue;
        const call = valid.sanitizedCall;
        if (
          !["mechanical_inspect", "mechanical_poison", "mechanical_guard"].includes(call.name) ||
          !("target_id" in call.args)
        )
          continue;
        const targetId = call.args.target_id,
          target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (call.name === "mechanical_inspect" && skill.kind === "inspection" && target) {
          const result = resolveInspection(ctx.world, target.id, "role", ctx.roleCatalog);
          if (!result || !current() || !livingNightLife(ctx.world, target) || !owner.canAct()) continue;
          if (!recordMechanicalInspection(skill, day, target, result, owner.canAct)) break;
          ctx.events.push({
            timestamp: Date.now(),
            type: "role_inspected",
            payload: { actorId: owner.actorId, day, targetId: target.id, result: { ...result } },
          });
        } else if (call.name === "mechanical_poison" && skill.kind === "poison" && target) {
          // 首个 claim 写入之前拒绝晚退休；一旦开始原提交序列，不借墓碑撤销已写前缀。
          if (!owner.canAct()) break;
          (ctx.state.poisonClaims ??= []).push(originalPoisonIntent({ source: owner.life, target }, {
            family: "mechanical", day, stage: "mechanical_skill", actorLife: owner.life,
            requestedTargetId: targetId, abilityId: "learned:mechanical",
          }));
          ctx.ensureMarks(target.id).add(StatusMark.PoisonMark);
          consumeMechanicalPoison(skill);
          ctx.events.push({
            timestamp: Date.now(),
            type: "mechanical_poison_used",
            payload: { actorId: owner.actorId, day, targetId: target.id },
          });
        } else if (call.name === "mechanical_guard" && skill.kind === "guard") {
          if (!owner.canAct()) break;
          const chosen = chooseMechanicalGuard(skill, targetId, day, owner.canAct);
          if (!chosen) break;
          const { failed } = chosen;
          if (failed)
            effects(ctx).failures.push(mechanicalNightIntent("mechanical-failure", {
              actorId: owner.actorId,
              target: owner.life,
              isCurrent: bound.isCurrent,
            }, { family: "mechanical", day, stage: "mechanical_skill", actorLife: owner.life,
              requestedTargetId: targetId, abilityId: "learned:mechanical" }));
          else if (target)
            effects(ctx).shields.push(mechanicalNightIntent("mechanical-shield", {
              actorId: owner.actorId,
              target,
              isCurrent: bound.isCurrent,
            }, { family: "mechanical", day, stage: "mechanical_skill", actorLife: owner.life,
              requestedTargetId: targetId, abilityId: "learned:mechanical" }));
          ctx.events.push({
            timestamp: Date.now(),
            type: "mechanical_guard_chosen",
            payload: { actorId: owner.actorId, day, targetId, failed },
          });
        } else continue;
        closeMechanicalSkill(owner.state, day);
        recordMechanicalNightCommit(ctx.world, day);
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("mechanical_skill_valid_action_missing");
    }
  },
};

const attackStage: NightStageHandler = {
  id: "mechanical_attack",
  priority: 660,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx)) {
      const learned = owner.state.learned,
        mode = owner.state.mode;
      if (learned?.skill.kind !== "wolf" || !mode) continue;
      const skill = learned.skill;
      const effectCurrent = () =>
        owner.isCurrent() &&
        owner.state.learned === learned &&
        learned.skill === skill &&
        skill.kind === "wolf" &&
        owner.state.mode === mode &&
        mode.day === day &&
        mode.kind === "kill" &&
        canMechanicalKnife(owner.role, ctx.world, () => ctx.world.getComponent(owner.actorId, COMPONENT.Camp));
      const current = () => effectCurrent() && canMechanicalExtraKnife(owner.state, day) && owner.canAct();
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        if (!owner.canAct()) break;
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, ["mechanical_attack"], {
            stage: "mechanical_attack",
            requiresAction: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!current()) break;
        let targetId: number | null = null;
        if (action !== null) {
          if (action.name !== "mechanical_attack") continue;
          const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
            phase: Phase.Night,
            day,
          });
          if (!current() || !valid.ok || valid.sanitizedCall?.name !== "mechanical_attack")
            continue;
          targetId = valid.sanitizedCall.args.target_id;
        }
        const target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        // 额外刀的目标生命复验完成后才检查未付资格；effectCurrent 保持纯已付谓词。
        if (!owner.canAct()) break;
        if (target)
          effects(ctx).attacks.push(mechanicalNightIntent("mechanical-attack", { actorId: owner.actorId, target, isCurrent: effectCurrent }, {
            family: "mechanical", day, stage: "mechanical_attack", actorLife: owner.life,
            requestedTargetId: targetId, abilityId: "learned:mechanical",
          }));
        closeMechanicalExtraKnife(skill, target);
        recordMechanicalNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "mechanical_attack_chosen",
          payload: { actorId: owner.actorId, day, targetId },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("mechanical_attack_valid_action_missing");
    }
  },
};

export const MECHANICAL_NIGHT_STAGES = [modeStage, mimicStage, skillStage, attackStage];

/**
 * 负责 机械狼 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Camp, Role } from "../../../../core/domain/model";
