/**
 * 负责炼金魔女／狼鸦之爪的原角色、阵营、身份与生命授权，输入为 World、参与者和夜序。
 * 输出为原当前性检查、脱离知识与经授权的雾／蛇／额外刀提交；资源绑定及槽写入归 state-slot。
 * 阵营只取已捕获 Camp 的 own-data，组件替换／字段变化仍撤权，不向 Role 写镜像。
 * 不变量：原体、身份或生命撤权后禁止新付款；原首次死亡仅可读取已付款效果／保留知识。
 * 夜初 ravenChecked 先写再转换，后续失败不重开检查；不修补被替换的槽或重复保存库存。
 */
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import {
  readMistOwnData as own,
  selectMist,
  selectSnake,
  selectRavenKnife,
  unsealRaven,
  type AlchemistState,
  type RavenState,
} from "./state";

import { MistCasterStateSlot, type MistCasterKind as Caster, type MistCasterState as State } from "./state-slot";

/** 外层夜 owner 提供日次、目标与阶段作用域；本授权只保原参与者／生命，状态写权不反向拥有阶段。 */
export class MistCasterAuthority {
  private readonly role: RoleComponent;
  private readonly privateState: RoleComponent["privateState"];
  private readonly identity: unknown;
  private readonly identityFields: unknown[];
  private readonly life: AliveComponent;
  private readonly lifeVersion: number;
  private readonly camp: Camp;
  private readonly campComponent: unknown;
  private readonly key: "alchemist" | "ravenClaw";
  private readonly stateSlot: MistCasterStateSlot;
  private ravenChecked = false;

  constructor(
    private readonly world: World,
    readonly actorId: number,
    readonly day: number,
    readonly caster: Caster,
  ) {
    if (
      !Number.isSafeInteger(day) ||
      day < 1 ||
      day >= Number.MAX_SAFE_INTEGER ||
      !Number.isSafeInteger(actorId) ||
      actorId < 1 ||
      actorId >= Number.MAX_SAFE_INTEGER ||
      (caster !== "alchemist" && caster !== "raven_claw_wolf")
    )
      throw new Error("mist_caster_authority_invalid");
    const role = world.getComponent(actorId, COMPONENT.Role),
      campComponent = world.getComponent(actorId, COMPONENT.Camp),
      identity = world.getComponent(actorId, COMPONENT.Identity),
      life = world.getComponent(actorId, COMPONENT.Alive);
    this.camp = caster === "alchemist" ? Camp.Good : Camp.Wolf;
    this.key = caster === "alchemist" ? "alchemist" : "ravenClaw";
    if (
      !role ||
      own(role, "role") !== caster ||
      own(campComponent, "camp") !== this.camp ||
      own(campComponent, "camp") !== this.camp ||
      !life ||
      !this.factoryLife(life) ||
      !life.alive ||
      aliveLifeVersion(life) === undefined ||
      own(identity, "id") !== actorId ||
      typeof own(identity, "name") !== "string" ||
      typeof own(identity, "sessionId") !== "string" ||
      !Number.isSafeInteger(own(identity, "seat"))
    )
      throw new Error("mist_caster_authority_invalid");
    const privateState = own(role, "privateState");
    if (
      !privateState ||
      typeof privateState !== "object" ||
      types.isProxy(privateState) ||
      Array.isArray(privateState)
    )
      throw new Error("mist_caster_authority_invalid");
    this.role = role;
    this.campComponent = campComponent;
    this.privateState = privateState as RoleComponent["privateState"];
    this.identity = identity;
    this.identityFields = ["id", "seat", "name", "sessionId"].map((k) => own(identity, k));
    this.life = life;
    this.lifeVersion = aliveLifeVersion(life)!;
    // 原字段已赋值后才读取槽并建立绑定；查询 thunk 保持 caster／容器／key 在原调用点晚读。
    this.stateSlot = new MistCasterStateSlot(
      { caster: () => this.caster, privateState: () => this.privateState, key: () => this.key, assertCurrent: () => this.current() },
      own(privateState, this.key),
    );
  }

  private factoryLife(life: AliveComponent): boolean {
    const expected = aliveLifeDescriptor(life);
    if (!expected) return false;
    const d = Object.getOwnPropertyDescriptor(life, "alive");
    return (
      !!d &&
      d.get === expected.get &&
      d.set === expected.set &&
      d.enumerable === expected.enumerable &&
      d.configurable === expected.configurable
    );
  }
  isCurrent(allowFirstDeath = false): boolean {
    if (
      this.world.getComponent(this.actorId, COMPONENT.Role) !== this.role ||
      own(this.role, "role") !== this.caster ||
      own(this.campComponent, "camp") !== this.camp ||
      this.world.getComponent(this.actorId, COMPONENT.Camp) !== this.campComponent ||
      own(this.campComponent, "camp") !== this.camp ||
      own(this.role, "privateState") !== this.privateState ||
      this.world.getComponent(this.actorId, COMPONENT.Identity) !== this.identity ||
      !["id", "seat", "name", "sessionId"].every(
        (k, i) => own(this.identity, k) === this.identityFields[i],
      ) ||
      this.world.getComponent(this.actorId, COMPONENT.Alive) !== this.life ||
      !this.factoryLife(this.life) ||
      !(this.life.alive
        ? aliveLifeVersion(this.life) === this.lifeVersion
        : allowFirstDeath && aliveLifeVersion(this.life) === this.lifeVersion + 1)
    )
      return false;
    // 参与者／生命全部通过后才复验原槽及逐层引用，不能提前读取或用相同 JSON 新数组补权。
    return this.stateSlot.isCurrent();
  }
  private current(allowFirstDeath = false): State {
    if (!this.isCurrent(allowFirstDeath)) throw new Error("mist_caster_authority_revoked");
    return this.stateSlot.read();
  }
  /** 已付款效果／保留知识可在原身体首次死亡后读取；这不会开启新的资源提交。 */
  state(allowFirstDeath = false): State {
    return this.current(allowFirstDeath);
  }

  /** 仅 beginNight 真实开夜调用一次；权限查询不触发解封，检查标志在可能失败的转换前已写。 */
  checkRavenAtNightStart(livingWolfIds: readonly number[]): RavenState {
    if (this.caster !== "raven_claw_wolf" || this.ravenChecked)
      throw new Error("raven_night_start_reentry");
    const state = this.current() as RavenState;
    this.ravenChecked = true;
    this.stateSlot.install(unsealRaven(state, this.day, this.actorId, livingWolfIds));
    return this.current() as RavenState;
  }
  commitMist(targets: number[] | null, livingIds: readonly number[]): AlchemistState {
    if (this.caster !== "alchemist") throw new Error("mist_caster_kind_invalid");
    this.stateSlot.install(selectMist(this.current() as AlchemistState, this.day, targets, livingIds));
    return this.current() as AlchemistState;
  }
  commitSnake(target: number | null, legalTargets: readonly number[]): AlchemistState {
    if (this.caster !== "alchemist") throw new Error("mist_caster_kind_invalid");
    this.stateSlot.install(selectSnake(this.current() as AlchemistState, this.day, target, legalTargets));
    return this.current() as AlchemistState;
  }
  commitRavenKnife(target: number | null, livingIds: readonly number[]): RavenState {
    if (this.caster !== "raven_claw_wolf" || !this.ravenChecked)
      throw new Error("raven_night_start_required");
    this.stateSlot.install(
      selectRavenKnife(this.current() as RavenState, this.day, this.actorId, target, livingIds),
    );
    return this.current() as RavenState;
  }
}

/**
 * 负责炼金魔女／狼鸦之爪管线的开夜事实与清理责任交接。输入为惰性原 World／events 和实际夜数；
 * 输出保留 begin→通知事实及伤害捕获回执。捕获伤害不转移清理，只有原晚 transfer 点才交权。
 * 部分开夜失败仍按配置尝试 abort；经理正常关闭后仍读参数并发起重复 abort，由 frame 决定关闭规则。
 * 已付选择、蛇窗和资源仍归 frame／施法 authority，这里不退款、结算死亡或推进阶段。
 */
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../../core/domain/world";
import { beginMistNight, handOffMistNight, closeMistNight, abortMistNight } from "./night_frame";

export interface MistNightRuntime {
  readonly world: World;
  readonly events: GameEvent[];
}

export const mistNightTerminal = Object.freeze({
  closeNormally(world: World, day: number): void {
    closeMistNight(world, day);
  },
  abort(world: World): void {
    abortMistNight(world);
  },
});

export class MistNightUnit {
  /** 经理接收同一清理实例；终止函数仍使用调用时新求值的 World／day 参数。 */
  readonly closeNormally = mistNightTerminal.closeNormally;
  readonly abort = mistNightTerminal.abort;

  private transferred = false;
  constructor(
    private readonly runtime: MistNightRuntime,
    private readonly day: number,
  ) {}

  open(): void {
    const unsealed = beginMistNight(this.runtime.world, this.day);
    if (unsealed)
      this.runtime.events.push({
        timestamp: Date.now(),
        type: "raven_unsealed",
        payload: { ...unsealed, day: this.day, awakened: true },
        audience: Object.freeze([unsealed.actorId]),
      });
  }

  /** 调用方在原狼刀目标实参求值之前提供 World；捕获伤害本身不转移清理责任。 */
  captureDamage(world: World, day: number, wolfTarget: number | null) {
    return handOffMistNight(world, day, wolfTarget);
  }

  /** 只在真实晚交接点记录经理是否接管；captureDamage 的成功不提前改这个标志。 */
  transferToManager(ownsMist: boolean): void {
    this.transferred = ownsMist;
  }

  abortIfOwned(): void {
    if (!this.transferred) abortMistNight(this.runtime.world);
  }
}

/**
 * 负责炼金魔女／狼鸦之爪的阵容原体、雾目标选择与待交付夜间伤害。输入为原玩家和已接受施法选择；
 * 输出保留原生命目标、蛇窗及关闭／中止操作，付款仍由施法 authority 负责。
 * 实际 Camp 只在原 own-data 点读取，组件引用、原字段或生命版本改变按原规则撤权，不保 Role 阵营镜像。
 * 只有匹配的原夜间对象可交付捕获伤害；复活不恢复旧许可，失败保留已付前缀，不补交付。
 */
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import { MistCasterAuthority } from "./caster_authority";
import {
  createAlchemistState,
  createRavenState,
  type AlchemistState,
  type RavenState,
} from "./state";

const missing = Symbol("missing_mist_native_field"),
  invalid = Symbol("invalid_mist_native_field");
function data(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return invalid;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return !field ? missing : "value" in field ? field.value : invalid;
}
function plain(value: unknown): value is object {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}
function snakeTargetData(value: unknown): number[] | undefined {
  if (types.isProxy(value) || !Array.isArray(value)) return;
  const fields: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      value as object,
    ),
    length = fields.length?.value;
  if ((length !== 0 && length !== 1) || Reflect.ownKeys(fields).length !== length + 1) return;
  if (length === 0) return [];
  const first = fields["0"];
  return first &&
    "value" in first &&
    Number.isSafeInteger(first.value) &&
    first.value > 0 &&
    first.value < Number.MAX_SAFE_INTEGER
    ? [first.value]
    : undefined;
}
function factoryLife(life: AliveComponent): boolean {
  const original = aliveLifeDescriptor(life);
  if (!original) return false;
  const actual = Object.getOwnPropertyDescriptor(life, "alive");
  return (
    !!actual &&
    actual.get === original.get &&
    actual.set === original.set &&
    actual.enumerable === original.enumerable &&
    actual.configurable === original.configurable
  );
}
function bindNativeAbilities(privateState: object): () => boolean {
  const privatePrototype = Object.getPrototypeOf(privateState);
  const container = data(privateState, "abilities");
  if (container === missing || container === undefined)
    return () =>
      Object.getPrototypeOf(privateState) === privatePrototype &&
      data(privateState, "abilities") === container;
  if (!plain(container)) throw new Error("mist_native_abilities_invalid");
  const names = Reflect.ownKeys(container);
  const containerPrototype = Object.getPrototypeOf(container);
  const guards = names.map((key) => {
    const ability = data(container, key);
    if (!plain(ability)) throw new Error("mist_native_abilities_invalid");
    const abilityPrototype = Object.getPrototypeOf(ability);
    const fields = [
      "id",
      "kind",
      "activation",
      "source",
      "state",
      "startsOnDay",
      "expiresAfterDay",
      "maxUses",
      "disabled",
      "deathExpired",
      "sourceDisclosed",
    ];
    const values = fields.map((k) => data(ability, k));
    const source = data(ability, "source"),
      state = data(ability, "state");
    if (!plain(source) || !plain(state) || data(source, "kind") !== "native")
      throw new Error("mist_native_abilities_invalid");
    const sourcePrototype = Object.getPrototypeOf(source),
      statePrototype = Object.getPrototypeOf(state);
    const sourceFields = ["kind", "role", "actorId", "abilityId"],
      sourceValues = sourceFields.map((k) => data(source, k));
    const policyFields = ["targetPolicy", "actionPolicy", "protectionPolicy"],
      policyValues = policyFields.map((k) => data(state, k));
    if (
      values.includes(invalid) ||
      sourceValues.includes(invalid) ||
      policyValues.includes(invalid)
    )
      throw new Error("mist_native_abilities_invalid");
    return () =>
      data(container, key) === ability &&
      Object.getPrototypeOf(ability) === abilityPrototype &&
      Object.getPrototypeOf(source) === sourcePrototype &&
      Object.getPrototypeOf(state) === statePrototype &&
      fields.every((k, i) => data(ability, k) === values[i]) &&
      sourceFields.every((k, i) => data(source, k) === sourceValues[i]) &&
      policyFields.every((k, i) => data(state, k) === policyValues[i]);
  });
  return () =>
    Object.getPrototypeOf(privateState) === privatePrototype &&
    data(privateState, "abilities") === container &&
    Object.getPrototypeOf(container) === containerPrototype &&
    Reflect.ownKeys(container).length === names.length &&
    guards.every((guard) => guard());
}
/** 阵容快照固定组件／字段原值和首生命版本；允许原体首次死亡的复验不授予复活后的新行动。 */
interface OriginalPlayer {
  id: number;
  role: RoleComponent;
  roleName: unknown;
  camp: unknown;
  campComponent: unknown;
  privateState: object;
  identity: unknown;
  identityFields: unknown[];
  life: AliveComponent;
  version: number;
  abilitiesCurrent: () => boolean;
}
/** 选择和狼刀绑定当夜原生命；handedOff、蛇窗与验证重入位各自独立，不复制施法库存。 */
interface MistNight {
  day: number;
  closed: boolean;
  handedOff: boolean;
  delayEligible: boolean;
  lives: ReadonlyMap<number, NightLifeScope>;
  mistDecided: boolean;
  mistTargets: readonly NightLifeScope[] | null;
  extraDecided: boolean;
  extra: NightLifeScope | null;
  wolfTarget: number | null;
  snakeRequested: boolean;
  snakeDecided: boolean;
  snakeValidating: boolean;
  snakeWindow: {
    actorId: number;
    targets: readonly NightLifeScope[];
    isCurrent: () => boolean;
  } | null;
}
interface Board {
  originals: ReadonlyMap<number, OriginalPlayer>;
  alchemistId: number;
  ravenId: number;
  latestCasters: Map<number, MistCasterAuthority>;
  started: Set<number>;
  night: MistNight | null;
}
const boards = new WeakMap<World, Board>();
function originalCurrent(world: World, player: OriginalPlayer): boolean {
  return (
    world.getComponent(player.id, COMPONENT.Role) === player.role &&
    data(player.role, "role") === player.roleName &&
    data(player.campComponent, "camp") === player.camp &&
    data(player.role, "privateState") === player.privateState &&
    world.getComponent(player.id, COMPONENT.Camp) === player.campComponent &&
    data(player.campComponent, "camp") === player.camp &&
    world.getComponent(player.id, COMPONENT.Identity) === player.identity &&
    ["id", "seat", "name", "sessionId"].every(
      (k, i) => data(player.identity, k) === player.identityFields[i],
    ) &&
    world.getComponent(player.id, COMPONENT.Alive) === player.life &&
    factoryLife(player.life) &&
    aliveLifeVersion(player.life) === player.version + (player.life.alive ? 0 : 1) &&
    player.abilitiesCurrent()
  );
}
function board(world: World): Board {
  const b = boards.get(world);
  if (
    !b ||
    world.entityIds().length !== b.originals.size ||
    ![...b.originals.values()].every((p) => originalCurrent(world, p)) ||
    ![...b.latestCasters.values()].every((caster) => caster.isCurrent(true))
  )
    throw new Error("mist_original_roster_revoked");
  return b;
}
function night(world: World, day: number): { b: Board; n: MistNight } {
  const b = board(world),
    n = b.night;
  if (!n || n.day !== day || n.closed) throw new Error("mist_night_unavailable");
  return { b, n };
}
export function isMistRavenBoard(world: World): boolean {
  return boards.has(world);
}
export function assertMistRosterCurrent(world: World): void {
  board(world);
}
export function installMistRavenBoard(world: World): void {
  if (boards.has(world)) throw new Error("mist_board_already_installed");
  const originals = new Map<number, OriginalPlayer>();
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role),
      privateState = data(role, "privateState"),
      identity = world.getComponent(id, COMPONENT.Identity),
      campComponent = world.getComponent(id, COMPONENT.Camp),
      life = world.getComponent(id, COMPONENT.Alive);
    const camp = data(campComponent, "camp"),
      roleName = data(role, "role");
    if (
      !role ||
      !plain(privateState) ||
      !life ||
      !factoryLife(life) ||
      !life.alive ||
      aliveLifeVersion(life) === undefined ||
      data(campComponent, "camp") !== camp ||
      data(identity, "id") !== id ||
      typeof data(identity, "name") !== "string" ||
      typeof data(identity, "sessionId") !== "string" ||
      !Number.isSafeInteger(data(identity, "seat"))
    )
      throw new Error("mist_original_roster_invalid");
    originals.set(id, {
      id,
      role,
      roleName,
      camp,
      campComponent,
      privateState,
      identity,
      identityFields: ["id", "seat", "name", "sessionId"].map((k) => data(identity, k)),
      life,
      version: aliveLifeVersion(life)!,
      abilitiesCurrent: bindNativeAbilities(privateState),
    });
  }
  const expected: Record<string, { count: number; camp: Camp }> = {
    wolf: { count: 3, camp: Camp.Wolf },
    raven_claw_wolf: { count: 1, camp: Camp.Wolf },
    villager: { count: 4, camp: Camp.Good },
    alchemist: { count: 1, camp: Camp.Good },
    seer: { count: 1, camp: Camp.Good },
    dreamer: { count: 1, camp: Camp.Good },
    idiot: { count: 1, camp: Camp.Good },
  };
  if (
    originals.size !== 12 ||
    [...originals.values()].some(
      (p) =>
        typeof p.roleName !== "string" ||
        !Object.hasOwn(expected, p.roleName) ||
        expected[p.roleName]!.camp !== p.camp,
    ) ||
    Object.entries(expected).some(
      ([name, spec]) =>
        [...originals.values()].filter((p) => p.roleName === name).length !== spec.count,
    )
  )
    throw new Error("mist_original_roster_invalid");
  const id = (name: string) => [...originals.values()].find((p) => p.roleName === name)!.id;
  const initialCasters = new Map<number, MistCasterAuthority>([
    [id("alchemist"), new MistCasterAuthority(world, id("alchemist"), 1, "alchemist")],
    [
      id("raven_claw_wolf"),
      new MistCasterAuthority(world, id("raven_claw_wolf"), 1, "raven_claw_wolf"),
    ],
  ]);
  if (
    JSON.stringify(initialCasters.get(id("alchemist"))!.state()) !==
      JSON.stringify(createAlchemistState()) ||
    JSON.stringify(initialCasters.get(id("raven_claw_wolf"))!.state()) !==
      JSON.stringify(createRavenState())
  )
    throw new Error("mist_initial_caster_state_invalid");
  boards.set(world, {
    originals,
    alchemistId: id("alchemist"),
    ravenId: id("raven_claw_wolf"),
    latestCasters: initialCasters,
    started: new Set(),
    night: null,
  });
}
export function beginMistNight(
  world: World,
  day: number,
): { actorId: number; knownTeammateIds: number[] } | null {
  const b = board(world);
  if (
    !Number.isSafeInteger(day) ||
    day < 1 ||
    day >= Number.MAX_SAFE_INTEGER ||
    b.started.has(day) ||
    (b.night && !b.night.closed)
  )
    throw new Error("mist_night_reentry");
  // started先落；后续caster创建或状态读取失败仍保本夜已尝试，不用失败重开规避原一次性门控。
  b.started.add(day);
  const lives = new Map(
    world.getAliveEntityIds().map((id) => [id, Object.freeze(captureNightLife(world, id)!)]),
  );
  const alchemist = lives.has(b.alchemistId)
    ? new MistCasterAuthority(world, b.alchemistId, day, "alchemist")
    : null;
  if (alchemist) b.latestCasters.set(b.alchemistId, alchemist);
  let unsealed: { actorId: number; knownTeammateIds: number[] } | null = null;
  if (lives.has(b.ravenId)) {
    const raven = new MistCasterAuthority(world, b.ravenId, day, "raven_claw_wolf"),
      before = raven.state() as RavenState;
    b.latestCasters.set(b.ravenId, raven);
    const state = raven.checkRavenAtNightStart(
      [...lives.keys()].filter((id) => b.originals.get(id)!.camp === Camp.Wolf),
    );
    if (before.awakenedDay === null && state.awakenedDay !== null)
      unsealed = { actorId: b.ravenId, knownTeammateIds: [...state.knownTeammateIds] };
  }
  b.night = {
    day,
    closed: false,
    handedOff: false,
    delayEligible: !!alchemist && (alchemist.state() as AlchemistState).healRemaining === 1,
    lives,
    mistDecided: false,
    mistTargets: null,
    extraDecided: false,
    extra: null,
    wolfTarget: null,
    snakeRequested: false,
    snakeDecided: false,
    snakeValidating: false,
    snakeWindow: null,
  };
  return unsealed;
}
export function mistCasterId(world: World, kind: "alchemist" | "raven_claw_wolf"): number {
  const b = board(world);
  return kind === "alchemist" ? b.alchemistId : b.ravenId;
}
export function ravenKnownTeammates(world: World): number[] {
  const b = board(world),
    caster = b.latestCasters.get(b.ravenId);
  return caster ? [...(caster.state(true) as RavenState).knownTeammateIds] : [];
}
export function ravenAwakened(world: World): boolean {
  const b = board(world),
    caster = b.latestCasters.get(b.ravenId);
  return !!caster && (caster.state(true) as RavenState).awakenedDay !== null;
}
export function mistChoiceTargets(world: World, day: number): number[] {
  const { b, n } = night(world, day),
    caster = b.latestCasters.get(b.alchemistId);
  if (
    n.handedOff ||
    n.mistDecided ||
    !n.lives.has(b.alchemistId) ||
    !caster?.isCurrent() ||
    (caster.state() as AlchemistState).mistRemaining === 0
  )
    return [];
  return [...n.lives.values()]
    .filter((scope) => livingNightLife(world, scope))
    .map((scope) => scope.id);
}
export function commitMistChoice(world: World, day: number, targets: number[] | null): void {
  const { b, n } = night(world, day),
    legal = mistChoiceTargets(world, day);
  if (legal.length < 3) throw new Error("mist_choice_unavailable");
  const state = b.latestCasters.get(b.alchemistId)!.commitMist(targets, legal);
  const chosen = state.mistHistory.at(-1)!.targetIds;
  n.mistTargets = chosen === null ? null : Object.freeze(chosen.map((id) => n.lives.get(id)!));
  n.mistDecided = true;
}
export function mistKnifeTargets(world: World): number[] | null {
  const b = board(world),
    n = b.night;
  if (!n || n.closed || !n.mistTargets) return null;
  return n.mistTargets.filter((scope) => livingNightLife(world, scope)).map((scope) => scope.id);
}
export function originalMistTarget(world: World, day: number, id: number): NightLifeScope | null {
  const { n } = night(world, day),
    scope = n.lives.get(id);
  return scope && livingNightLife(world, scope) ? scope : null;
}
export function ravenKnifeTargets(world: World, day: number): number[] {
  const { b, n } = night(world, day),
    caster = b.latestCasters.get(b.ravenId);
  if (n.handedOff || n.extraDecided || !n.lives.has(b.ravenId) || !caster?.isCurrent()) return [];
  const state = caster.state() as RavenState;
  if (state.awakenedDay === null || state.extraRemaining === 0) return [];
  return [...n.lives.values()]
    .filter((scope) => scope.id !== b.ravenId && livingNightLife(world, scope))
    .map((scope) => scope.id);
}
export function commitRavenKnife(world: World, day: number, target: number | null): void {
  const { b, n } = night(world, day),
    legal = ravenKnifeTargets(world, day);
  if (!legal.length) throw new Error("raven_knife_unavailable");
  b.latestCasters.get(b.ravenId)!.commitRavenKnife(target, [b.ravenId, ...legal]);
  n.extra = target === null ? null : n.lives.get(target)!;
  n.extraDecided = true;
}
export function handOffMistNight(
  world: World,
  day: number,
  wolfTarget: number | null,
): { delayEligible: boolean; extra: NightLifeScope | null } {
  const { n } = night(world, day);
  if (n.handedOff) throw new Error("mist_night_reentry");
  if (mistChoiceTargets(world, day).length >= 3 || ravenKnifeTargets(world, day).length > 0)
    throw new Error("mist_night_choices_unsettled");
  if (wolfTarget !== null && !originalMistTarget(world, day, wolfTarget))
    throw new Error("mist_knife_target_stale");
  const circle = mistKnifeTargets(world);
  if (circle !== null && (wolfTarget === null ? circle.length > 0 : !circle.includes(wolfTarget)))
    throw new Error("mist_knife_outside_circle");
  // 全部选择及圈内刀口复验通过后才写目标→交付位；返回引用不自行完成清理交接。
  n.wolfTarget = wolfTarget;
  n.handedOff = true;
  return { delayEligible: n.delayEligible, extra: n.extra };
}
export function openSnakeWindow(
  world: World,
  day: number,
  targets: readonly number[],
  isCurrent: () => boolean,
): void {
  const { b, n } = night(world, day),
    caster = b.latestCasters.get(b.alchemistId);
  if (!n.handedOff || !n.delayEligible || n.snakeRequested || !caster?.isCurrent())
    throw new Error("snake_window_unavailable");
  // 先记录已请求，再验目标数组；目标无效会关夜，不能更换输入后再次请求。
  n.snakeRequested = true;
  const target = n.wolfTarget,
    expected =
      target !== null &&
      originalMistTarget(world, day, target) &&
      (target !== b.alchemistId || day === 1)
        ? [target]
        : [];
  const chosen = snakeTargetData(targets);
  if (!chosen || chosen.length !== expected.length || chosen.some((id, i) => id !== expected[i])) {
    n.closed = true;
    throw new Error("snake_window_target_invalid");
  }
  n.snakeWindow = {
    actorId: b.alchemistId,
    targets: Object.freeze(expected.map((id) => n.lives.get(id)!)),
    isCurrent,
  };
}
export function snakeWindowTargets(world: World, day: number, actorId: number): number[] {
  const { b, n } = night(world, day),
    window = n.snakeWindow;
  if (
    !window ||
    n.snakeValidating ||
    window.actorId !== actorId ||
    !b.latestCasters.get(actorId)?.isCurrent()
  )
    throw new Error("snake_window_revoked");
  // 外部current回调前置重入位，回调后再核board/night/window原引用；异常关夜并抛回同错误。
  n.snakeValidating = true;
  let current: boolean;
  try {
    current = window.isCurrent();
    if (
      board(world) !== b ||
      b.night !== n ||
      n.closed ||
      n.snakeWindow !== window ||
      !b.latestCasters.get(actorId)?.isCurrent()
    )
      current = false;
  } catch (error) {
    n.closed = true;
    n.snakeWindow = null;
    throw error;
  } finally {
    n.snakeValidating = false;
  }
  if (!current) {
    n.closed = true;
    n.snakeWindow = null;
    throw new Error("snake_window_revoked");
  }
  return window.targets.filter((scope) => livingNightLife(world, scope)).map((scope) => scope.id);
}
export function commitSnakeChoice(
  world: World,
  day: number,
  actorId: number,
  target: number | null,
): void {
  const { b, n } = night(world, day),
    legal = snakeWindowTargets(world, day, actorId);
  b.latestCasters.get(actorId)!.commitSnake(target, legal);
  n.snakeDecided = true;
  n.snakeWindow = null;
}
export function closeMistNight(world: World, day: number): void {
  const { n } = night(world, day);
  if (!n.handedOff || n.snakeWindow || (n.delayEligible && !n.snakeDecided))
    throw new Error("mist_night_unsettled");
  n.closed = true;
}
/** 清理只关旧夜／清蛇窗，不校验或修复私态，也不恢复资源或重开窗口。 */
export function abortMistNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n) {
    n.closed = true;
    n.snakeWindow = null;
  }
}

/**
 * 负责炼金魔女雾选择及狼鸦之爪额外刀的真实阶段。输入为当前 frame、候选和工具回复；
 * 输出为原提交及带来源刀口。请求前后、gateway 后保持原阵容与阶段复验，提交先于本人事实。
 * 这里不结算已交接伤害，也不接管较晚蛇窗；晚事实抛错保留已经消费／记录的选择。
 */
import type { NightStageHandler } from "../../stages/night/contracts";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Phase } from "../../../../core/domain/identity";
import type { RoleComponent } from "../../../../core/domain/components/role";
import {
  assertMistRosterCurrent,
  mistCasterId,
  mistChoiceTargets,
  commitMistChoice,
  ravenKnifeTargets,
  commitRavenKnife,
} from "./night_frame";
import { readAlchemistState, readRavenState } from "./state";

export const ALCHEMIST_MIST_STAGE: NightStageHandler = {
  id: "alchemist_mist",
  priority: 50,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = mistCasterId(ctx.world, "alchemist"),
      candidates = mistChoiceTargets(ctx.world, day);
    if (candidates.length < 3) {
      const state = readAlchemistState(
        (
          ctx.world.getComponent(actorId, COMPONENT.Role) as
            { readonly privateState: { readonly alchemist?: unknown } } | undefined
        )?.privateState.alchemist,
      );
      const reason = !ctx.world.getAliveEntityIds().includes(actorId)
        ? "dead"
        : state?.mistRemaining === 0
          ? "spent"
          : "no_targets";
      ctx.events.push({
        timestamp: Date.now(),
        type: "alchemist_mist_skipped",
        payload: { actorId, day, reason },
        audience: Object.freeze([actorId]),
      });
      return;
    }
    const request = ctx.makeRequest(actorId, ["cast_mist"], {
      stage: "alchemist_mist",
      requiresAction: true,
      allow_fallback: false,
      action_failure_policy: "error",
      mist_candidates: candidates,
    });
    assertMistRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertMistRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("mist_choice_stale");
    if (action?.name !== "cast_mist") throw new Error("mist_choice_action_missing");
    const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertMistRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || !result.ok || result.sanitizedCall?.name !== "cast_mist")
      throw new Error("mist_choice_action_invalid");
    // 先提交选择／历史（含不耗库存的空选）；之后重读state与push失败不撤回雾选择或补库存。
    commitMistChoice(ctx.world, day, result.sanitizedCall.args.target_ids);
    const state = readAlchemistState(
      (
        ctx.world.getComponent(actorId, COMPONENT.Role)!.privateState as {
          readonly alchemist?: unknown;
        }
      ).alchemist,
    )!;
    ctx.events.push({
      timestamp: Date.now(),
      type: "alchemist_mist_chosen",
      payload: { actorId, day, targetIds: state.mistHistory.at(-1)!.targetIds },
      audience: Object.freeze([actorId]),
    });
  },
};
export const RAVEN_KNIFE_STAGE: NightStageHandler = {
  id: "raven_knife",
  priority: 450,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = mistCasterId(ctx.world, "raven_claw_wolf"),
      candidates = ravenKnifeTargets(ctx.world, day);
    if (!candidates.length) {
      const state = readRavenState(
        (
          ctx.world.getComponent(actorId, COMPONENT.Role) as
            { readonly privateState: { readonly ravenClaw?: unknown } } | undefined
        )?.privateState.ravenClaw,
      );
      const reason = !ctx.world.getAliveEntityIds().includes(actorId)
        ? "dead"
        : state?.awakenedDay === null
          ? "sealed"
          : state?.extraRemaining === 0
            ? "spent"
            : "no_targets";
      ctx.events.push({
        timestamp: Date.now(),
        type: "raven_knife_skipped",
        payload: { actorId, day, reason },
        audience: Object.freeze([actorId]),
      });
      return;
    }
    const request = ctx.makeRequest(actorId, ["raven_knife"], {
      stage: "raven_knife",
      requiresAction: true,
      allow_fallback: false,
      action_failure_policy: "error",
      raven_candidates: candidates,
    });
    assertMistRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertMistRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("raven_knife_stale");
    if (action?.name !== "raven_knife") throw new Error("raven_knife_action_missing");
    const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertMistRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || !result.ok || result.sanitizedCall?.name !== "raven_knife")
      throw new Error("raven_knife_action_invalid");
    commitRavenKnife(ctx.world, day, result.sanitizedCall.args.target_id);
    ctx.events.push({
      timestamp: Date.now(),
      type: "raven_knife_chosen",
      payload: { actorId, day, targetId: result.sanitizedCall.args.target_id },
      audience: Object.freeze([actorId]),
    });
  },
};

/**
 * 负责雾鸦夜间伤害交接与有界蛇反应窗口。输入为原生命和脱离的待结算伤害；
 * 输出为已 claim 的反应和最终伤害。finish／abort 终止本次 pending，不替换任何目标原体。
 * 本模块不切换阶段或标死；延期副本保留真实毒因果，疗救和梦扩展仍用原政策。
 * 规则依据：docs/rules/awa-mist-raven-twelve-v1.md。
 */
import {
  AliveComponent,
  aliveLifeDescriptor,
  aliveLifeVersion,
} from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { DeathCause } from "../../../../core/domain/deaths";
import type { World } from "../../../../core/domain/world";
import { attachDamagePoisonEvidence, damagePoisonRoutes } from "../../../../core/domain/damage-evidence";
import type { DamageResolutionResult } from "../../../../core/domain/systems/damage_resolution_system";
import type { DreamNightEffects } from "../../../../core/domain/dream-night-effects";

type PendingStatus = "pending" | "committing" | "committed" | "aborted";
interface OriginalLife {
  readonly life: AliveComponent;
  readonly version: number;
}
function copyDamage(damage: DamageResolutionResult): DamageResolutionResult {
  const copy = {
    deaths: [...damage.deaths],
    deathSources: Object.fromEntries(
      damage.deaths.map((id) => [id, [...(damage.deathSources[id] ?? [])]]),
    ),
  };
  // 使用原复制时点的最终死因过滤证据；疗救或扩展不凭空制造原毒来源。
  return attachDamagePoisonEvidence(copy, damagePoisonRoutes(damage).filter(
    (route) => copy.deaths.includes(route.targetId) &&
      copy.deathSources[route.targetId]?.includes(DeathCause.Poison),
  ));
}
function factoryLife(life: AliveComponent): boolean {
  const original = aliveLifeDescriptor(life);
  if (!original) return false;
  const current = Object.getOwnPropertyDescriptor(life, "alive");
  return (
    !!original &&
    !!current &&
    current.get === original.get &&
    current.set === original.set &&
    current.enumerable === original.enumerable &&
    current.configurable === original.configurable
  );
}

/** 单次延期夜只归所属 PhaseManager；这里不提交阶段或死亡。 */
export class MistPendingNight {
  private currentStatus: PendingStatus = "pending";
  private readonly lives = new Map<number, OriginalLife>();
  private readonly directDamage: DamageResolutionResult;
  private finalDamage: DamageResolutionResult | undefined;
  private preparing = false;
  private finishing = false;
  private validating = false;

  constructor(
    private readonly world: World,
    readonly day: number,
    readonly wolfTarget: number | null,
    directDamage: DamageResolutionResult,
    private readonly dreams: DreamNightEffects,
  ) {
    if (!Number.isSafeInteger(day) || day < 1 || day >= Number.MAX_SAFE_INTEGER)
      throw new Error("mist_pending_night_invalid");
    // 后续梦关联目标未必在直接死亡名单中，原生命捕获仍覆盖潜在闭包。
    for (const id of world.entityIds()) {
      const life = world.getComponent(id, COMPONENT.Alive);
      if (!life) continue;
      if (!factoryLife(life)) throw new Error("mist_pending_life_invalid");
      const version = life && aliveLifeVersion(life);
      if (!life || version === undefined) throw new Error("mist_pending_life_invalid");
      if (life.alive) this.lives.set(id, Object.freeze({ life, version }));
    }
    if (
      (wolfTarget !== null && !this.lives.has(wolfTarget)) ||
      new Set(directDamage.deaths).size !== directDamage.deaths.length ||
      Object.keys(directDamage.deathSources).some(
        (key) => !directDamage.deaths.includes(Number(key)),
      ) ||
      directDamage.deaths.some(
        (id) =>
          !this.lives.has(id) ||
          !directDamage.deathSources[id]?.length ||
          directDamage.deathSources[id]!.some(
            (source) => !Object.values(DeathCause).includes(source),
          ),
      )
    )
      throw new Error("mist_pending_damage_invalid");
    this.directDamage = copyDamage(directDamage);
  }

  get status(): PendingStatus {
    return this.currentStatus;
  }

  private livingOriginal(id: number): boolean {
    const scope = this.lives.get(id);
    return (
      !!scope &&
      this.world.getComponent(id, COMPONENT.Alive) === scope.life &&
      factoryLife(scope.life) &&
      scope.life.alive &&
      aliveLifeVersion(scope.life) === scope.version
    );
  }

  /** 原刀口受保护或公开自爆死亡后仍保留原可知范围，不据当前角色重建刀源。 */
  snakeTargets(actorId: number): number[] {
    return this.wolfTarget !== null &&
      this.livingOriginal(this.wolfTarget) &&
      (this.wolfTarget !== actorId || this.day === 1)
      ? [this.wolfTarget]
      : [];
  }

  /** 包括自爆路径，均在警徽／蛇行动或其他 await 前同步领取这次延期，不能重入。 */
  claim(isCurrent: () => boolean): void {
    if (this.currentStatus !== "pending") throw new Error("mist_pending_night_reentry");
    this.currentStatus = "committing";
    this.requireCurrent(isCurrent);
  }

  private requireCurrent(isCurrent: () => boolean): void {
    let current: boolean;
    this.validating = true;
    try {
      current = isCurrent();
    } catch (error) {
      this.abort();
      throw error;
    } finally {
      this.validating = false;
    }
    if (!current || this.currentStatus !== "committing") {
      this.abort();
      throw new Error("mist_pending_night_stale");
    }
  }

  /** 只使用已解析的直接来源，不再次消费印记；疗救后在原时点展开梦关联。 */
  prepareFinalDamage(
    healedTarget: number | null,
    isCurrent: () => boolean,
  ): DamageResolutionResult {
    if (this.currentStatus !== "committing" || this.preparing || this.validating)
      throw new Error("mist_pending_night_reentry");
    this.preparing = true;
    this.requireCurrent(isCurrent);
    if (
      healedTarget !== null &&
      (healedTarget !== this.wolfTarget || !this.livingOriginal(healedTarget))
    ) {
      this.abort();
      throw new Error("mist_pending_heal_invalid");
    }
    const damage = copyDamage(this.directDamage);
    for (const id of damage.deaths) {
      if (!this.livingOriginal(id)) delete damage.deathSources[id];
      else if (id === healedTarget)
        damage.deathSources[id] = damage.deathSources[id]!.filter(
          (source) => source !== DeathCause.WolfKill,
        );
    }
    damage.deaths = damage.deaths.filter((id) => !!damage.deathSources[id]?.length);
    for (const id of Object.keys(damage.deathSources).map(Number))
      if (!damage.deaths.includes(id)) delete damage.deathSources[id];
    // 蛇行动结束后才扩展一次梦死因；梦的行动者／目标可能在直接死亡名单之外。
    for (const [id, scope] of this.lives) {
      if (this.world.getComponent(id, COMPONENT.Alive) === scope.life && !factoryLife(scope.life)) {
        this.abort();
        throw new Error("mist_pending_life_invalid");
      }
    }
    try {
      this.dreams.expandInitialDamage(this.world, damage);
    } catch (error) {
      this.abort();
      throw error;
    }
    if (this.currentStatus !== "committing") throw new Error("mist_pending_night_stale");
    this.finalDamage = copyDamage(damage);
    return copyDamage(damage);
  }

  /** 只在 DeathResolution 已提交准备的原生命之后完成本次延期。 */
  finish(isCurrent: () => boolean): void {
    if (
      this.currentStatus !== "committing" ||
      !this.finalDamage ||
      this.finishing ||
      this.validating
    )
      throw new Error("mist_pending_night_reentry");
    this.finishing = true;
    this.requireCurrent(isCurrent);
    if (
      this.finalDamage.deaths.some((id) => {
        const scope = this.lives.get(id);
        return (
          !scope ||
          this.world.getComponent(id, COMPONENT.Alive) !== scope.life ||
          !factoryLife(scope.life) ||
          scope.life.alive ||
          aliveLifeVersion(scope.life) !== scope.version + 1
        );
      })
    ) {
      this.abort();
      throw new Error("mist_pending_night_unsettled");
    }
    this.currentStatus = "committed";
  }

  abort(): void {
    if (this.currentStatus === "pending" || this.currentStatus === "committing")
      this.currentStatus = "aborted";
  }
}

/**
 * 负责从炼金魔女／狼鸦之爪的原角色数据读取既有政策校验后的独立玩家视图。
