    day = pending.day;
  const current = () => pending.status === "committing" && isCurrent();
  if (!current()) throw new Error("snake_window_stale");
  assertMistRosterCurrent(world);
  const candidates = pending.snakeTargets(actorId);
  openSnakeWindow(world, day, candidates, current);
  // 原蛇窗口先开放，再在原点读取构造器并独立 new；构造失败不在此关闭，外层经理原 abort 保留该前缀。
  const request = new construction.requestFactory(world, events, day).create({
    phase: Phase.Day,
    actorId,
    allowedTools: ["use_snake"],
    stage: "alchemist_snake",
    requiresAction: true,
    summary: { key: "request.summary.alchemist_snake" },
    context: {
      snake_target: pending.wolfTarget,
      snake_candidates: candidates,
      action_failure_policy: "error",
      allow_fallback: false,
    },
  });
  const action = await provider.getAction(request);
  assertMistRosterCurrent(world);
  if (!current()) throw new Error("snake_window_stale");
  if (action?.name !== "use_snake") throw new Error("snake_action_missing");
  const result = gateway.validateAndSanitize(world, actorId, action, { phase: Phase.Day, day });
  assertMistRosterCurrent(world);
  if (!current() || !result.ok || result.sanitizedCall?.name !== "use_snake")
    throw new Error("snake_action_invalid");
  const targetId = result.sanitizedCall.args.target_id;
  commitSnakeChoice(world, day, actorId, targetId);
  events.push({
    timestamp: Date.now(),
    type: "alchemist_snake_chosen",
    payload: { actorId, day, targetId },
    audience: Object.freeze([actorId]),
  });
  return targetId;
}

/**
 * 负责四族原生／学习死亡枪的数据创建、原槽安装、武装、捕获复验和库存消费。
 * 输入为原角色、原学习对象与晚取查询；输出保留同一槽／枪引用和原每次 hook 的捕获表。
 * 原生安装不克隆、不冻库存；学习模板仅创建自己的全新枪，已有整学习数据的复制仍由各族安装 owner 执行。
 * 本 owner 安装两个原生槽并写原枪字段，原体、生命、死因及请求许可仍在结算／具体权威复验；只读类型不是权限屏障。
 * 学习枪先晚取原查询并裸调用、读 skill，再在原阵营点调用显式 source；不存 Camp 引用。
 * 猎魔板子先捕获原审计库存，支付仍由同一权威执行；setter／编码或后续发表失败均不退款。
 */
import type { CurrentCampSource } from "../../../core/domain/components/camp";
import type {
  HunterState,
  HunterReadState,
  WolfKingState,
  WolfKingReadState,
  MechanicalReadState as MechanicalState,
  MechanicalReadLearning as MechanicalLearning,
  MechanicalReadSkill as MechanicalSkill,
  MechanicalReadState,
  AwakenedReadState as AwakenedState,
  AwakenedReadLearning as AwakenedLearning,
  AwakenedReadSkill as AwakenedSkill,
  AwakenedReadState,
} from "@ai-werewolf-arena/game-contract";
import { Camp, Role } from "../../../core/domain/model";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import type { RoleInitContext } from "./contracts";
import type { openDemonHunterStockFrame } from "./demon_hunter/native-gun-ports";

/** 创建仍逐次读取原配置 getter，不缓存 boardConfig／policy；分支保持原字段可选性。 */
export function createHunterState(ctx: Pick<RoleInitContext, "boardConfig">): HunterState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.hunter?.deathActionPolicy === "awa_knife_or_exile_v1"
      ? { deathActionPolicy: ctx.boardConfig.hunter.deathActionPolicy }
      : {}),
  };
}
export function createWolfKingState(ctx: Pick<RoleInitContext, "boardConfig">): WolfKingState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.wolfKing?.deathActionPolicy !== undefined &&
    ctx.boardConfig.wolfKing.deathActionPolicy !== "awa_qualified_sources_v1"
      ? { deathActionPolicy: ctx.boardConfig.wolfKing.deathActionPolicy }
      : {}),
  };
}

/** get 仍可调用原槽 getter；set 原左值赋入同对象，不新增 schema 或 descriptor 拒绝。 */
export function setHunterState(roleComp: RoleComponent, state: HunterState): HunterReadState {
  (roleComp.privateState as { hunter: HunterState })["hunter"] = state;
  return state;
}

export function getHunterState(roleComp: RoleComponent): HunterReadState | undefined {
  return (roleComp.privateState as { readonly hunter?: unknown })["hunter"] as
    HunterReadState | undefined;
}

export function setWolfKingState(roleComp: RoleComponent, state: WolfKingState): WolfKingReadState {
  (roleComp.privateState as { wolf_king: WolfKingState })["wolf_king"] = state;
  return state;
}

export function getWolfKingState(roleComp: RoleComponent): WolfKingReadState | undefined {
  return (roleComp.privateState as { readonly wolf_king?: unknown })["wolf_king"] as
    WolfKingReadState | undefined;
}

export type LearnedNativeGun = Extract<MechanicalSkill, { kind: "hunter" }>;
/** 学习得到新满库存模板，不从目标玩家复制已花费资源或原体许可。 */
export function createLearnedNativeGun(): { kind: "hunter"; canShoot: boolean; armed: boolean } {
  return { kind: "hunter", canShoot: true, armed: false };
}
/** 实际夜／激活检查仍由本族调用方先完成；只在原赋值点武装同一枪，不补偿其他字段。 */
function armLearnedNativeGun(gun: LearnedNativeGun): void {
  (gun as { armed: boolean }).armed = true;
}

/** 机械枪必须进入实际 ready 夜；保持 kind→ready→原 skill 左值读取，不因模式或查询补武装。 */
export function armMechanicalNativeGun(learned: MechanicalLearning, day: number): void {
  if (learned.skill.kind === "hunter" && day >= learned.readyOnNight)
    armLearnedNativeGun(learned.skill);
}
/** 觉醒枪仅在原整次激活通过后武装；activationNight／activeFromNight 仍在其后原点更新。 */
export function armAwakenedNativeGun(learned: AwakenedLearning): void;
export function armAwakenedNativeGun(learned: AwakenedLearning, mayCommit: () => boolean): boolean;
export function armAwakenedNativeGun(learned: AwakenedLearning, mayCommit?: () => boolean): boolean | void {
  if (learned.skill.kind === "hunter") {
    if (mayCommit) {
      // 原 callee→skill 引用先读取，再在首次 armed 赋值之前拒绝；不额外读取 armed。
      const arm = armLearnedNativeGun, gun = learned.skill;
      if (!mayCommit()) return false;
      arm(gun);
    } else armLearnedNativeGun(learned.skill);
  }
  // 原无回调调用保 void；机械已学习开夜武装与 paid reader 不使用此新入口。
  if (mayCommit) return true;
}

/** 生产每次 hook 独立持有原捕获表；这里不另验 World，换学习／原枪后返回 undefined。 */
export function createMechanicalGunReader(runtime: {
  readonly getMechanicalState: (role: RoleComponent | undefined) => MechanicalReadState | undefined;
}): (role: RoleComponent, currentCamp: CurrentCampSource) => LearnedNativeGun | undefined {
  const owners = new Map<
    RoleComponent,
    {
      state: MechanicalState;
      learning: MechanicalLearning;
      gun: Extract<MechanicalSkill, { kind: "hunter" }>;
    }
  >();
  return (role, currentCamp) => {
    const query = runtime.getMechanicalState;
    const state = query(role),
      learning = state?.learned,
      skill = learning?.skill;
    if (currentCamp()?.camp !== Camp.Wolf || !state || !learning || skill?.kind !== "hunter" || !skill.armed)
      return undefined;
    const prior = owners.get(role);
    if (prior && (state !== prior.state || learning !== prior.learning || skill !== prior.gun))
      return undefined;
    if (!prior) owners.set(role, { state, learning, gun: skill });
    return skill;
  };
}

/** 生产每次 hook 独立持有原捕获表；这里不另验 World，换学习／原枪后返回 undefined。 */
export function createAwakenedGunReader(runtime: {
  readonly getAwakenedState: (role: RoleComponent | undefined) => AwakenedReadState | undefined;
}): (role: RoleComponent, currentCamp: CurrentCampSource) => LearnedNativeGun | undefined {
  const owners = new Map<
    RoleComponent,
    {
      state: AwakenedState;
      learned: AwakenedLearning;
      gun: Extract<AwakenedSkill, { kind: "hunter" }>;
      targetId: number;
      role: AwakenedLearning["role"];
      day: number;
      activationNight: number;
      activeFromNight: number;
    }
  >();
  return (role, currentCamp) => {
    const query = runtime.getAwakenedState;
    const state = query(role),
      learned = state?.learned,
      gun = learned?.skill;
    if (
      currentCamp()?.camp !== Camp.Wolf ||
      !state ||
      !learned ||
      learned.role !== Role.Hunter ||
      learned.activationNight === null ||
      learned.activeFromNight === null ||
      gun?.kind !== "hunter" ||
      !gun.armed
    )
      return undefined;
    const prior = owners.get(role);
    if (
      prior &&
      (state !== prior.state ||
        learned !== prior.learned ||
        gun !== prior.gun ||
        learned.targetId !== prior.targetId ||
        learned.role !== prior.role ||
        learned.day !== prior.day ||
        learned.activationNight !== prior.activationNight ||
        learned.activeFromNight !== prior.activeFromNight)
    )
      return undefined;
    if (!prior)
      owners.set(role, {
        state,
        learned,
        gun,
        targetId: learned.targetId,
        role: learned.role,
        day: learned.day,
        activationNight: learned.activationNight,
        activeFromNight: learned.activeFromNight,
      });
    return gun;
  };
}

/** 晚取原猎魔命令；非 Hunter 分支不读命令，类型引用不会初始化 authority。 */
export interface NativeDeathGunStockQueries {
  readonly openHunterStock?: typeof openDemonHunterStockFrame;
}
export function captureNativeGunStock(
  kind: Role,
  queries: NativeDeathGunStockQueries,
  world: World,
  actorId: number,
  state: object,
): ReturnType<typeof openDemonHunterStockFrame> {
  if (kind !== "hunter") return null;
  const command = queries.openHunterStock!;
  return command(world, actorId, state);
}
/** 付款不补资格：原 stock 自验并写审计；普通分支只写原 canShoot。失败保原写入前缀。 */
export function consumeNativeDeathGun(
  state: { readonly canShoot: boolean },
  stock: ReturnType<typeof openDemonHunterStockFrame>,
): void {
  if (stock) stock.consume();
  else (state as { canShoot: boolean }).canShoot = false;
}

/**
 * 负责四族原生／学习枪的完整死亡结算：死因资格、选择等待、原体复验、付款与追加提案。
 * 输入是原 World、死因、选择回调、具体资源贡献和死亡上下文；输出保原对象的提案／延期事实。
 * await 后先核 current 与捕获 stock，再依原角色、学习、政策、来源及原生命复验，失效不付款。
 * pass／映射 miss／保护阻挡按原规则付款；消费先于保护与事实，后续失败保已付前缀。
 * 已退休 Role 只在未消费行动入口与等待后拒绝；原 stock 异常与完整原体检查先行。
 * state 只接晚取阵营 source，普通 Hunter／WolfKing 可忽略；原值比较不升级组件引用撤权。
 * 已消费延期提案保原 isCurrent，不因行动墓碑撤回已付前缀；本 owner 不开许可、标死或封盘。
 */
import type { CurrentCampSource } from "../../../core/domain/components/camp";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import {
  captureNativeGunStock,
  consumeNativeDeathGun,
  type NativeDeathGunStockQueries,
} from "./native-death-gun-resources";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { aliveLifeVersion } from "../../../core/domain/components/alive";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import {
  DeathCause,
  permitsDeathShot,
  type DeathActionPolicy,
  type EntityId,
  type GameEvent,
  type Role,
  type DeathSources,
  type DeathShotSelection,
} from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { DeathHookResult, DeathHookContext } from "../hooks/hook_registry";

export interface NativeDeathShotRules extends NativeDeathGunStockQueries {
  role: Role;
  state: (
    role: RoleComponent,
    currentCamp: CurrentCampSource,
  ) => { readonly canShoot: boolean; readonly deathActionPolicy?: DeathActionPolicy } | undefined;
  policy?: (state: {
    readonly canShoot: boolean;
    readonly deathActionPolicy?: DeathActionPolicy;
  }) => DeathActionPolicy;
  permits: (sources: readonly DeathCause[]) => boolean;
  shotEvent: (actorId: EntityId, targetId: EntityId) => GameEvent;
  poisonEvent?: (actorId: EntityId) => GameEvent;
}

/** 共用原单枪消费；实际目标死亡和最终判胜仍归中央结算。 */
export async function resolveNativeDeathShots(
  world: World,
  deadIds: EntityId[],
  deathSources: DeathSources,
  choose: (actorId: EntityId) => Promise<DeathShotSelection>,
  events: GameEvent[],
  rules: NativeDeathShotRules,
  context?: DeathHookContext,
): Promise<DeathHookResult> {
  const result: DeathHookResult = { extraDeaths: [], extraDeathSources: {} };
  for (const actorId of deadIds) {
    if (context?.isCurrent && !context.isCurrent()) break;
    const role = world.getComponent(actorId, COMPONENT.Role);
    const state = role ? rules.state(role, () => world.getComponent(actorId, COMPONENT.Camp)) : undefined;
    if (
      !role ||
      role.role !== rules.role ||
      !state ||
      world.getComponent(actorId, COMPONENT.Alive)?.alive !== false
    )
      continue;
    // 原角色／状态／死亡检查已通过，退休只拒未消费行动；不把纯 state 查询变成权限。
    if (isRoleExecutionRetired(role)) continue;
    // 先捕获原审计 stock 再读死因；普通／学习枪仍只写同一 canShoot，不建立影子库存。
    const stock = captureNativeGunStock(rules.role, rules, world, actorId, state);
    const consume = () => consumeNativeDeathGun(state, stock);
    const sources = deathSources[actorId] ?? [];
    if (sources.includes(DeathCause.Poison)) {
      if (isRoleExecutionRetired(role)) continue;
      consume();
      if (rules.poisonEvent) events.push(rules.poisonEvent(actorId));
      continue;
    }
    const policy = rules.policy?.(state);
    const deathPhase = context?.deathOriginPhase;
    const nightEffect = context?.nightEffect;
    const causeIdentity = JSON.stringify(sources);
    if (
      !state.canShoot ||
      !rules.permits(sources) ||
      (policy !== undefined && !permitsDeathShot(sources, policy, deathPhase))
    ) {
      if (isRoleExecutionRetired(role)) continue;
      consume();
      continue;
    }
    const actorLife = world.getComponent(actorId, COMPONENT.Alive)!;
    const actorVersion = aliveLifeVersion(actorLife);
    const camp = world.getComponent(actorId, COMPONENT.Camp)?.camp,
      privateState = role.privateState;
    const targets = new Map(
      world.getAliveEntityIds().map((id) => [id, captureNightLife(world, id)]),
    );
    const selected = await choose(actorId);
    if (context?.isCurrent && !context.isCurrent()) break;
    if (stock && !stock.isCurrent()) throw new Error("demon_hunter_native_hunter_stock_revoked");
    const currentRole = world.getComponent(actorId, COMPONENT.Role);
    if (
      currentRole !== role ||
      currentRole.role !== rules.role ||
      world.getComponent(actorId, COMPONENT.Camp)?.camp !== camp ||
      currentRole.privateState !== privateState ||
      rules.state(currentRole, () => world.getComponent(actorId, COMPONENT.Camp)) !== state ||
      rules.policy?.(state) !== policy ||
      context?.deathOriginPhase !== deathPhase ||
      context?.nightEffect !== nightEffect ||
      JSON.stringify(deathSources[actorId] ?? []) !== causeIdentity ||
      !rules.permits(deathSources[actorId] ?? []) ||
      (policy !== undefined &&
        !permitsDeathShot(deathSources[actorId] ?? [], policy, deathPhase)) ||
      !state.canShoot ||
      world.getComponent(actorId, COMPONENT.Alive) !== actorLife ||
      actorLife.alive ||
      aliveLifeVersion(actorLife) !== actorVersion
    )
      continue;
    // 保原 context→stock 撤权错误→完整原体复验的优先级，然后才拒退休演员，仍未消费。
    if (isRoleExecutionRetired(role)) continue;
    if (
      selected.kind === "invalid" ||
      !world.isDeathActionOpen(actorId, "shoot", selected.deathActionId)
    )
      continue;
    if (selected.kind === "pass") {
      if (isRoleExecutionRetired(role)) continue;
      consume();
      continue;
    }
    if (selected.mappingCurrent && !selected.mappingCurrent()) continue;
    const targetScope = selected.targetScope ?? targets.get(selected.targetId);
    if (selected.mappedMiss) {
      if (
        !selected.mappingCurrent ||
        !targetScope ||
        targetScope.id !== selected.targetId ||
        world.getComponent(targetScope.id, COMPONENT.Alive) !== targetScope.life ||
        targetScope.life.alive ||
        aliveLifeVersion(targetScope.life) !== targetScope.version
      )
        continue;
      if (isRoleExecutionRetired(role)) continue;
      consume();
      events.push({
        timestamp: Date.now(),
        type: "death_shot_missed",
        payload: { actorId, reason: "no_effect" },
      });
      continue;
    }
    if (
      !targetScope ||
      targetScope.id !== selected.targetId ||
      !livingNightLife(world, targetScope)
    )
      continue;
    // 原映射／目标回调可在复验中同步退休演员；全部原检查完成后、消费前再核同一 Role。
    if (isRoleExecutionRetired(role)) continue;
    consume();
    if (context?.nightEffect && context.blocksNightShot(selected.targetId)) {
      events.push({
        timestamp: Date.now(),
        type: "death_shot_blocked",
        payload: { actorId, targetId: selected.targetId, reason: "night_protection" },
      });
      continue;
    }
    result.extraDeaths.push(selected.targetId);
    if (context?.nightEffect) (result.nightEffectTargets ??= []).push(selected.targetId);
    result.extraDeathSources[selected.targetId] = [DeathCause.Shot];
    const event = rules.shotEvent(actorId, selected.targetId);
    if (context?.deferShotCommit)
      (result.pendingShots ??= []).push({
        targetScope,
        event,
        isCurrent: () =>
          (context.isCurrent?.() ?? true) &&
          world.getComponent(actorId, COMPONENT.Role) === role &&
          role.role === rules.role &&
          world.getComponent(actorId, COMPONENT.Camp)?.camp === camp &&
          role.privateState === privateState &&
          rules.state(role, () => world.getComponent(actorId, COMPONENT.Camp)) === state &&
          rules.policy?.(state) === policy &&
          context?.deathOriginPhase === deathPhase &&
          context?.nightEffect === nightEffect &&
          (policy === undefined ||
            permitsDeathShot(deathSources[actorId] ?? [], policy, deathPhase)) &&
          world.getComponent(actorId, COMPONENT.Alive) === actorLife &&
          !actorLife.alive &&
          aliveLifeVersion(actorLife) === actorVersion &&
          JSON.stringify(deathSources[actorId] ?? []) === causeIdentity &&
          world.isDeathActionOpen(actorId, "shoot", selected.deathActionId),
      });
    else events.push(event);
  }
  return result;
}

/**
 * 负责经受限名单与资格端口同步枚举夜间施法实例。输入为原存活 ID、已存能力引用、种类和 day；
 * 输出保留能力原引用及只读 payload，不生成档案 DTO 或可写库存。先对完整名单过滤恐惧，再过滤导师修饰，
 * 最后按原序读能力状态；绑定不查 World／时钟，查询不消费资源、不提交效果或随机选目标。
 */
import type { NightAbilityKind } from "@ai-werewolf-arena/game-contract";

import type { EntityId } from "../../../core/domain/model";
import { COMPONENT } from "../../../core/domain/components/names";
import type { World } from "../../../core/domain/world";
import { abilityStatus, allNightAbilities, type NightAbilityReadView } from "./abilities";
import {
  bindNightmareNightEligibility,
  type NightmareNightEligibility,
} from "./nightmare_shadow/ports";
import {
  bindScholarMentorNightEligibility,
  type ScholarMentorNightEligibility,
} from "./scholar_mentor/ports";

/** 名单端口只给原存活成员和已存实例序列；不提供库存写或资源提交方法。 */
export interface NightAbilityRosterPort {
  aliveIds(): EntityId[];
  abilitiesFor(actorId: EntityId): readonly NightAbilityReadView[];
}

/** 已绑定资格查询不接收 World、时钟、writer 或回执提交实参；内部仍按本族规则晚查询。 */
export interface NightActorEligibilityQuery {
  filterAliveActors(ids: readonly EntityId[], kind: NightAbilityKind, day: number): EntityId[];
}

export interface NightAbilityActorQuery {
  actors<K extends NightAbilityKind>(
    kind: K,
    day: number,
  ): Array<{ actorId: EntityId; ability: NightAbilityReadView<K> }>;
}

/** 保留先完整恐惧过滤、再完整修饰过滤的两次遍历，不逐人交错两族查询。 */
export function createNightActorEligibilityQuery(
  nightmare: NightmareNightEligibility,
  scholarMentor: ScholarMentorNightEligibility,
): NightActorEligibilityQuery {
  return Object.freeze({
    filterAliveActors(ids: readonly EntityId[], kind: NightAbilityKind, day: number) {
      return ids
        .filter((actorId) => !nightmare.blocks(actorId, day))
        .filter(
          (actorId) =>
            (kind !== "guard" && kind !== "seer_check") ||
            !scholarMentor.blocks(actorId, day, kind === "guard" ? "guard" : "check"),
        );
    },
  });
}

/** 在实际查询点同步生成列表；不冻结或复制选中的实例，readonly payload 仍是原引用。 */
export function createNightAbilityActorQuery(
  roster: NightAbilityRosterPort,
  eligibility: NightActorEligibilityQuery,
): NightAbilityActorQuery {
  return Object.freeze({
    actors<K extends NightAbilityKind>(kind: K, day: number) {
      return eligibility.filterAliveActors(roster.aliveIds(), kind, day).flatMap((actorId) =>
        roster
          .abilitiesFor(actorId)
          .filter(
            (ability): ability is NightAbilityReadView<K> =>
              ability.kind === kind && abilityStatus(ability, day) === "active",
          )
          .map((ability) => ({ actorId, ability })),
      );
    },
  });
}

/** 装配只捕获一个原 World 引用，绑定时不读取名单或能力；这些读取留到实际 actors 查询。 */
export function bindNightAbilityActorQuery(world: World): NightAbilityActorQuery {
  return createNightAbilityActorQuery(
    {
      aliveIds: () => world.getAliveEntityIds(),
      abilitiesFor: (actorId) => allNightAbilities(world.getComponent(actorId, COMPONENT.Role)),
    },
    createNightActorEligibilityQuery(
      bindNightmareNightEligibility(world),
      bindScholarMentorNightEligibility(world),
    ),
  );
}

/**
 * 负责夜能力变更共用的原角色查询与事实发布。输入为原 World／actor 或原实例／事件数组；
 * 输出为实际 Role 引用或追加的 ability_changed 事实。授予／转移和启停／死亡到期两个负责人共用此实现。
 * 角色缺失仍先报原错误；发布按原 push 方法、Date.now、字段和 source 克隆顺序执行，错误不撤回先前库存写入。
 * 不校验新 payload、寻找替代实例、授予行动权限或建立额外资源账本；本内部叶不经机制聚合出口公开。
 */
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { EntityId, GameEvent } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { NightAbilityReadView } from "./abilities";

export const roleOf = (world: World, actorId: EntityId): RoleComponent => {
  const role = world.getComponent(actorId, COMPONENT.Role);
  if (!role) throw new Error("ability_actor_missing");
  return role;
};

export const emit = (
  events: GameEvent[],
  actorId: EntityId,
  ability: NightAbilityReadView,
  operation: "granted" | "disabled" | "enabled" | "transferred_out",
) =>
  events.push({
    timestamp: Date.now(),
    type: "ability_changed",
    payload: {
      actorId,
      abilityId: ability.id,
      kind: ability.kind,
      operation,
      source: structuredClone(ability.source),
      sourceDisclosed: ability.sourceDisclosed,
      startsOnDay: ability.startsOnDay,
      ...(ability.expiresAfterDay === undefined
        ? {}
        : { expiresAfterDay: ability.expiresAfterDay }),
      maxUses: ability.maxUses,
    },
  });

/**
 * 负责普通夜能力授予、复制与明确转移的完整提交。输入为原 World、拥有者、安装数据与具体 statePolicy；
 * 输出为同一实际库存中的只读实例及原能力变化事实。校验、复制、来源复验和目标安装都由本模块负责。
 * 授予仍安装后发布；独立 F03 转移政策先完整预检，再由唯一库存 owner 先删源／退休、后安装目标／发布。
 * 转移拒绝共享或不稳定库存路径；异常保留已经发生的前缀和原 Error，不退款，记录 sink 不取得库存写权。
 * 字典安装／发布与删除／退休提交交唯一 abilities owner；本模块保完整来源政策，角色 payload、生命／租约和临时抑制仍有原负责人。
 * 数据复制仍消费唯一 copyAbilityData，原接受集合不加强；这不是全部角色状态 schema 或严格复盘 codec。
 * F05a 晚核本次捕获源／目标 Role 的永久退休；新增 sourceRole 输入是复验数据，不授许可或新增换体策略。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import type { AbilitySource, NightAbilityKind, NightAbilityStates } from "@ai-werewolf-arena/game-contract";
import { isDeepStrictEqual } from "node:util";
import { DREAM_PROTECTION_POLICIES } from "../../../core/domain/board";
import { COMPONENT } from "../../../core/domain/components/names";
import { type EntityId, type GameEvent } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleComponent } from "../../../core/domain/components/role";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { allNightAbilities, copyAbilityData, commitGrantedNightAbility, commitTransferredNightAbility, type NightAbility, type NightAbilityReadView } from "./abilities";
import { projectNightState } from "../../observation/night-ability-projection";
import { roleOf } from "./night-ability-change-runtime";

/** 安装数据只声明赠予／复制来源；日期和资源政策仍在原安装流程核对，不代表已有行动许可。 */
export interface AbilityGrant<K extends NightAbilityKind> {
  id: string;
  kind: K;
  state: NightAbilityStates[K];
  source: Extract<AbilitySource, { kind: "gift" | "copy" }>;
  startsOnDay: number;
  expiresAfterDay?: number;
  maxUses: number | null;
  sourceDisclosed?: boolean;
  activation?: "lucky" | "black_market";
}

/** 规则调用者明确提供状态／资源政策，不隐式复制目标历史或重置已付库存。 */
export function grantNightAbility<K extends NightAbilityKind>(
  world: World,
  actorId: EntityId,
  input: AbilityGrant<K>,
  events: GameEvent[],
): NightAbilityReadView<K> {
  if (input.kind === "pair_check") throw Error("ability_pair_native_only");
  if (input.source.kind !== "gift" && input.source.kind !== "copy")
    throw new Error("ability_grant_source_invalid");
  const ability = copyAbilityData({
    ...input,
    sourceDisclosed: input.sourceDisclosed ?? false,
    uses: 0,
    lastUsedDay: null,
    disabled: false,
  }) as unknown as NightAbility<K>;
  const { role, sourceRole } = validateAbilityInstall(world, actorId, ability);
  return commitGrantedNightAbility(role, actorId, ability, events, sourceRole) as NightAbilityReadView<K>;
}

/** 阵营政策在原值表达式晚读实际 Camp，不复制到 Role；原安装预检捕获目标及原读取点的源 Role；这两个数据引用只供提交复验永久退休，不是许可或新原体策略。 */
function validateAbilityInstall(
  world: World,
  actorId: EntityId,
  ability: NightAbility,
): { role: RoleComponent; sourceRole: RoleComponent } {
  const input = ability;
  if (input.kind === "pair_check") throw Error("ability_pair_native_only");
  if (input.kind === "role_check") roleInspectionPolicy(input.state);
  if (
    input.kind === "dream" &&
    input.state.protectionPolicy !== undefined &&
    !DREAM_PROTECTION_POLICIES.includes(input.state.protectionPolicy)
  )
    throw new Error("ability_dream_policy_invalid");
  const source = input.source;
  if (
    input.kind === "role_check" &&
    roleInspectionPolicy(input.state) === "mirror" &&
    source.kind !== "transfer" &&
    (Object.keys(input.state)
      .filter((key) => key !== "inspectionPolicy")
      .sort()
      .join() !== "history,lastDay,lastTarget,policy" ||
      input.state.lastTarget !== null ||
      input.state.lastDay !== null ||
      !Array.isArray(input.state.history) ||
      input.state.history.length !== 0 ||
      Object.keys(input.state.history).length !== 0 ||
      input.uses !== 0 ||
      input.lastUsedDay !== null ||
      input.disabled)
  )
    throw new Error("ability_mirror_initial_state_invalid");
  if (source.kind === "native") throw new Error("ability_grant_source_invalid");
  const role = roleOf(world, actorId);
  if (
    !/^[a-z][a-z0-9:_-]{0,127}$/.test(input.id) ||
    input.id.startsWith("native:") ||
    !Number.isSafeInteger(input.startsOnDay) ||
    input.startsOnDay < 1 ||
    (input.expiresAfterDay !== undefined &&
      (!Number.isSafeInteger(input.expiresAfterDay) ||
        input.expiresAfterDay < input.startsOnDay)) ||
    (input.maxUses !== null && (!Number.isSafeInteger(input.maxUses) || input.maxUses < 0))
  )
    throw new Error("ability_grant_invalid");
  const sourceRole = roleOf(world, source.actorId);
  if (
    input.activation === "black_market" &&
    (source.kind === "copy" ||
      input.sourceDisclosed !== false ||
      input.id !== "gift:black-market" ||
      world.getComponent(actorId, COMPONENT.Camp)?.camp !== "good" ||
      input.startsOnDay < 2)
  )
    throw new Error("ability_black_market_policy_invalid");
  const origin =
    source.kind === "copy"
      ? allNightAbilities(roleOf(world, source.actorId)).find(
          (ability) => ability.id === source.abilityId,
        )
      : undefined;
  if (origin?.activation === "lucky" || origin?.activation === "black_market")
    throw new Error("ability_copy_lucky_not_supported");
  if (
    input.activation !== undefined &&
    (!["lucky", "black_market"].includes(input.activation) ||
      !(
        input.activation === "black_market"
          ? ["seer_check", "potion"]
          : ["seer_check", "potion", "guard"]
      ).includes(input.kind) ||
      input.maxUses !== 1)
  )
    throw new Error("ability_lucky_policy_invalid");
  if (
    allNightAbilities(role).some((ability) => ability.id === input.id) ||
    (
      ((role.privateState as { readonly retiredAbilityIds?: unknown }).retiredAbilityIds ??
        []) as string[]
    ).includes(input.id)
  )
    throw new Error("ability_id_duplicate");
  if (
    source.kind !== "gift" &&
    !allNightAbilities(roleOf(world, source.actorId)).some(
      (ability) => ability.id === source.abilityId && ability.kind === input.kind,
    )
  )
    throw new Error("ability_source_mismatch");
  // 原来源／状态／重复编号政策全通过后才查捕获双端，拒绝不写库存或发布事实。
  if (isRoleExecutionRetired(role) || isRoleExecutionRetired(sourceRole))
    throw new Error("ability_actor_execution_retired");
  return { role, sourceRole };
}

/** 先完成原复制／资源／来源／目标预检；转移提交保计数和原夜时点，但失败不再留下两份合法有效库存。 */
export function transferNightAbility<K extends NightAbilityKind>(
  world: World,
  fromId: EntityId,
  toId: EntityId,
  id: string,
  targetId: string,
  events: GameEvent[],
  options: {
    kind: K;
    statePolicy: (state: Readonly<NightAbilityStates[K]>) => NightAbilityStates[K];
    sourceDisclosed?: boolean;
  },
): void {
  if (fromId === toId) throw new Error("ability_transfer_same_owner");
  const source = roleOf(world, fromId),
    ability = allNightAbilities(source).find((ability) => ability.id === id);
  if (!ability) throw new Error("ability_instance_missing");
  if (ability.kind === "pair_check") throw Error("ability_pair_native_only");
  if (!options || options.kind !== ability.kind || typeof options.statePolicy !== "function")
    throw new Error("ability_transfer_policy_required");
  const black = ability.activation === "black_market",
    target = roleOf(world, toId),
    fromLife = captureNightLife(world, fromId),
    toLife = captureNightLife(world, toId),
    originalState = ability.state,
    originalSource = ability.source,
    sourcePrivate = source.privateState,
    targetPrivate = target.privateState,
    originalRole = source.role,
    targetRole = target.role;
  if (
    black &&
    (!fromLife ||
      !toLife ||
      world.getComponent(fromId, COMPONENT.Camp)?.camp !== "good" ||
      world.getComponent(toId, COMPONENT.Camp)?.camp !== "good" ||
      targetId !== id ||
      options.sourceDisclosed === true)
  )
    throw new Error("ability_black_market_transfer_invalid");
  const before = black
    ? copyAbilityData({
        id: ability.id,
        kind: ability.kind,
        source: ability.source,
        startsOnDay: ability.startsOnDay,
        expiresAfterDay: ability.expiresAfterDay,
        maxUses: ability.maxUses,
        uses: ability.uses,
        lastUsedDay: ability.lastUsedDay,
        disabled: ability.disabled,
        deathExpired: ability.deathExpired,
        activation: ability.activation,
        sourceDisclosed: ability.sourceDisclosed,
        state: projectNightState(ability),
      })
    : undefined;
  // 政策回调消费独立数据；黑市随后复验原组件／生命／槽及规范化内容，不用复制结果恢复许可。
  const targetState = copyAbilityData(
    options.statePolicy(
      copyAbilityData(black ? projectNightState(ability) : ability.state) as NightAbilityStates[K],
    ),
  );
  if (
    black &&
    (options.kind !== ability.kind ||
      options.sourceDisclosed === true ||
      world.getComponent(fromId, COMPONENT.Role) !== source ||
      source.role !== originalRole ||
      world.getComponent(fromId, COMPONENT.Camp)?.camp !== "good" ||
      source.privateState !== sourcePrivate ||
      world.getComponent(toId, COMPONENT.Role) !== target ||
      target.role !== targetRole ||
      world.getComponent(toId, COMPONENT.Camp)?.camp !== "good" ||
      target.privateState !== targetPrivate ||
      !livingNightLife(world, fromLife!) ||
      !livingNightLife(world, toLife!) ||
      allNightAbilities(source).find((candidate) => candidate.id === id) !== ability ||
      ability.state !== originalState ||
      ability.source !== originalSource ||
      !isDeepStrictEqual(
        before,
        copyAbilityData({
          id: ability.id,
          kind: ability.kind,
          source: ability.source,
          startsOnDay: ability.startsOnDay,
          expiresAfterDay: ability.expiresAfterDay,
          maxUses: ability.maxUses,
          uses: ability.uses,
          lastUsedDay: ability.lastUsedDay,
          disabled: ability.disabled,
          deathExpired: ability.deathExpired,
          activation: ability.activation,
          sourceDisclosed: ability.sourceDisclosed,
          state: projectNightState(ability),
        }),
      ))
  )
    throw new Error("ability_black_market_transfer_revoked");
  if (
    (ability.activation === "lucky" || ability.activation === "black_market") &&
    !isDeepStrictEqual(targetState, black ? projectNightState(ability) : ability.state)
  )
    throw new Error("ability_transfer_lucky_state_changed");
  // 转移保持资源；seer_check 明确政策可重置知识，role_check 保留完整历史，其他政策不能补库存。
  if (
    ability.kind === "guard" &&
    (targetState as NightAbilityStates["guard"]).lastTarget !== ability.state.lastTarget
  )
    throw new Error("ability_transfer_resources_changed");
  if (
    ability.kind === "dream" &&
    ((targetState as NightAbilityStates["dream"]).lastTarget !== ability.state.lastTarget ||
      (targetState as NightAbilityStates["dream"]).lastDay !== ability.state.lastDay ||
      (targetState as NightAbilityStates["dream"]).protectionPolicy !==
        ability.state.protectionPolicy)
  )
    throw new Error("ability_transfer_resources_changed");
  if (
    ability.kind === "potion" &&
    [
      "heal",
      "poison",
      "selfHealRule",
      "canSelfHeal",
      "healUsedThisNight",
      "poisonUsedThisNight",
    ].some(
      (key) =>
        (targetState as unknown as Record<string, unknown>)[key] !==
        (ability.state as unknown as Record<string, unknown>)[key],
    )
  )
    throw new Error("ability_transfer_resources_changed");
  if (ability.kind === "role_check" && !isDeepStrictEqual(targetState, ability.state))
    throw new Error("ability_transfer_role_inspection_history_changed");
  const received = copyAbilityData({
    ...ability,
    state: targetState,
    id: targetId,
    sourceDisclosed: options.sourceDisclosed ?? false,
    source: { kind: "transfer", actorId: fromId, abilityId: id },
  }) as NightAbility;
  const { role: installationTarget } = validateAbilityInstall(world, toId, received);
  // 预检和复制全通过才交库存写权；F03 的源先退休政策不伪装成旧失败前缀等价。
  commitTransferredNightAbility(world, source, sourcePrivate, installationTarget, fromId, toId, id, ability, received, events);
}

/**
 * 负责按 World 隔离记录玩家自身已接受夜行动，并检查幸运儿／黑市受赠者的目标限制。
 * 输入为原 World、玩家、日次、行动种类与目标，输出为私有历史副本和目标可用判断。
 * 本模块唯一写入 WeakMap 账本；公共记录类型归数据契约，历史不代替许可、付款或公共事实。
 * 目标政策仍是行动者本地规则，保留实例过期／转移后的原历史影响，不读取他人行动。
 */
import type { EntityId } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleComponent } from "../../../core/domain/components/role";
import { COMPONENT } from "../../../core/domain/components/names";
import { allNightAbilities, type NightAbilityReadView } from "./abilities";
import type { NightActionKind, OwnNightAction } from "@ai-werewolf-arena/game-contract/night-ability-views";

const histories = new WeakMap<World, Map<EntityId, OwnNightAction[]>>();

/** 只记录调用方已接受的效果，不记尝试或他人目标；这次写入不证明实际付款／伤害完成。 */
export function recordOwnNightAction(
  world: World,
  actorId: EntityId,
  day: number,
  kind: NightActionKind,
  targetId: EntityId,
  lucky: boolean,
  recipientPolicy: "lucky" | "black_market" = "lucky",
): void {
  let actors = histories.get(world);
  if (!actors) {
    actors = new Map();
    histories.set(world, actors);
  }
  const previous = actors.get(actorId) ?? [];
  actors.set(actorId, [
    ...previous.filter((row) => row.day >= day - 1),
    { day, kind, targetId, lucky, ...(lucky ? { recipientPolicy } : {}) },
  ]);
}

export function ownNightActions(world: World, actorId: EntityId, day: number): OwnNightAction[] {
  // 保留原 day-1..day 过滤再逐行浅复制；不能把账本引用直接交给观察消费者或改写业务时钟。
  return (histories.get(world)?.get(actorId) ?? [])
    .filter((row) => row.day >= day - 1 && row.day <= day)
    .map((row) => ({ ...row }));
}

/** 即使原幸运实例过期、耗尽或已转移，目标限制仍按该行动者的原本地历史检查。 */
export function luckyTargetAllowed(
  world: World,
  actorId: EntityId,
  ability: NightAbilityReadView,
  day: number,
  kind: NightActionKind,
  targetId: EntityId,
): boolean {
  const history = ownNightActions(world, actorId, day);
  const role = world.getComponent(actorId, COMPONENT.Role);
  const abilityKind = kind === "check" ? "seer_check" : kind === "poison" ? "potion" : "guard";
  const hasPolicy =
    ability.activation === "lucky" ||
    ability.activation === "black_market" ||
    allNightAbilities(role).some(
      (a) =>
        a.kind === abilityKind && (a.activation === "lucky" || a.activation === "black_market"),
    ) ||
    history.some((row) => row.kind === kind && row.lucky);
  if (!hasPolicy) return true;
  if (
    (ability.activation === "lucky" || ability.activation === "black_market") &&
    kind === "check" &&
    targetId === actorId
  )
    return false;
  return !history.some(
    (row) =>
      row.kind === kind &&
      row.targetId === targetId &&
      (row.day === day || (kind === "guard" && row.day === day - 1)),
  );
}

/**
 * 负责噩梦之影原名单、生命绑定、夜窗口与恐惧效果授权；输入为原角色与已通过目标政策的选择。
 * 输出是当前恐惧／狼刀阻断查询和原提交结果；仅原名单参与，组件替换不能悄然重开夜。
 * 数据构造、校验、写入和身份编码归同族状态槽；本 frame 保留 expectedState 更新和夜字段提交顺序。
 * 失败保留已写前缀，不以玩家投影或恐惧文案替代原生命／能力复验，也不回滚历史或补做关闭。
 * 当前 Camp 在原字段点由实际 World 查询；保原值比较，不把同值组件替换改成新的引用撤权。
 */
import type {
  NightmareShadowReadState,
} from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import {
  aliveLifeVersion,
  aliveLifeDescriptor,
  type AliveComponent,
} from "../../../../core/domain/components/alive";

import type { World } from "../../../../core/domain/world";
import { Camp, type EntityId } from "../../../../core/domain/identity";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { NightAbilityReadView } from "../abilities";
import { getNightmareShadowState, NIGHTMARE_SHADOW_STATE_SLOT } from "./state-slot";
import { nightmareFearTargets } from "./targets";

function authority(ability: NightAbilityReadView): string {
  const state = ability.state as unknown as Record<string, unknown>;
  return JSON.stringify([
    ability.id,
    ability.kind,
    ability.activation,
    ability.source,
    ability.sourceDisclosed,
    ability.startsOnDay,
    ability.expiresAfterDay,
    ability.maxUses,
    ability.disabled,
    ability.deathExpired,
    state.targetPolicy,
    state.actionPolicy,
    state.selfHealRule,
    state.knifeVisibility,
    state.potionPolicy,
    state.repeatPolicy,
    state.policy,
    state.inspectionPolicy,
    state.protectionPolicy,
  ]);
}
function captureRole(world: World, id: EntityId) {
  const role = world.getComponent(id, COMPONENT.Role);
  if (!role) throw new Error("nightmare_roster_missing");
  const kind = role.role,
    camp = world.getComponent(id, COMPONENT.Camp)?.camp,
    privateState = role.privateState;
  const life = world.getComponent(id, COMPONENT.Alive);
  const descriptor = life && aliveLifeDescriptor(life);
  const version = life && aliveLifeVersion(life);
  if (!life || !descriptor || version === undefined)
    throw new Error("nightmare_roster_life_missing");
  const lifeCurrent = () => {
    const current = Object.getOwnPropertyDescriptor(life, "alive");
    return (
      world.getComponent(id, COMPONENT.Alive) === life &&
      current?.get === descriptor.get &&
      current?.set === descriptor.set &&
      (aliveLifeVersion(life) === version ||
        (aliveLifeVersion(life) === version + 1 && !life.alive))
    );
  };
  const refs = Object.entries(privateState);
  const slots = Object.entries((privateState as { readonly abilities?: unknown }).abilities ?? {});
  const abilities = Object.values(
    ((privateState as { readonly abilities?: unknown }).abilities ?? {}) as Record<
      string,
      NightAbilityReadView
    >,
  ).map((ability) => ({
    ability,
    state: ability.state,
    source: ability.source,
    identity: authority(ability),
  }));
  return {
    id,
    role,
    current: () =>
      lifeCurrent() &&
      world.getComponent(id, COMPONENT.Role) === role &&
      role.role === kind &&
      world.getComponent(id, COMPONENT.Camp)?.camp === camp &&
      role.privateState === privateState &&
      refs.every(
        ([key, value]) => (privateState as Readonly<Record<string, unknown>>)[key] === value,
      ) &&
      Object.keys((privateState as { readonly abilities?: unknown }).abilities ?? {}).length ===
        slots.length &&
      slots.every(
        ([key, value]) =>
          (
            (privateState as { readonly abilities?: unknown }).abilities as
              Record<string, unknown> | undefined
          )?.[key] === value,
      ) &&
      abilities.every(
        (a) =>
          a.ability.state === a.state &&
          a.ability.source === a.source &&
          authority(a.ability) === a.identity,
      ),
  };
}
type Board = {
  actorId: EntityId;
  state: NightmareShadowReadState;
  expectedState: string;
  roster: ReturnType<typeof captureRole>[];
  night: {
    day: number;
    required: boolean;
    committed: boolean;
    target: NightLifeScope | null;
    wolfBlocked: boolean;
  } | null;
};
const boards = new WeakMap<World, Board>();
export function installNightmareBoard(world: World): void {
  if (boards.has(world)) throw new Error("nightmare_board_reinstall");
  const roster = world.entityIds().map((id) => captureRole(world, id));
  const actors = roster.filter((row) => getNightmareShadowState(row.role, () => world.getComponent(row.id, COMPONENT.Camp)));
  if (actors.length !== 1) throw new Error("nightmare_actor_count");
  const state = getNightmareShadowState(actors[0].role, () => world.getComponent(actors[0].id, COMPONENT.Camp))!;
  boards.set(world, {
    actorId: actors[0].id,
    state,
    expectedState: NIGHTMARE_SHADOW_STATE_SLOT.checkpoint.identity(state),
    roster,
    night: null,
  });
}
export function isNightmareBoard(world: World): boolean {
  return boards.has(world);
}
export function assertNightmareRosterCurrent(world: World): void {
  const board = boards.get(world);
  if (!board) return;
  if (
    world.entityIds().length !== board.roster.length ||
    board.roster.some((row) => !row.current()) ||
    getNightmareShadowState(world.getComponent(board.actorId, COMPONENT.Role), () => world.getComponent(board.actorId, COMPONENT.Camp)) !== board.state ||
    NIGHTMARE_SHADOW_STATE_SLOT.checkpoint.identity(board.state) !== board.expectedState
  )
    throw new Error("nightmare_roster_revoked");
}
export function beginNightmareNight(world: World, day: number): EntityId | null {
  const board = boards.get(world);
  if (!board) return null;
  assertNightmareRosterCurrent(world);
  if (
    !Number.isSafeInteger(day) ||
    day !== (board.night?.day ?? 0) + 1 ||
    (board.night?.required && !board.night.committed)
  )
    throw new Error("nightmare_night_reentry");
  board.night = {
    day,
    required: world.getAliveEntityIds().includes(board.actorId),
    committed: false,
    target: null,
    wolfBlocked: false,
  };
  return world.getAliveEntityIds().includes(board.actorId) ? board.actorId : null;
}
export function nightmarePackReady(world: World): boolean {
  assertNightmareRosterCurrent(world);
  return boards.get(world)?.state.packReady ?? true;
}
export function commitNightmareFear(
  world: World,
  actorId: EntityId,
  day: number,
  targetId: EntityId | null,
): void {
  assertNightmareRosterCurrent(world);
  const board = boards.get(world),
    night = board?.night;
  if (
    !board ||
    !night ||
    board.actorId !== actorId ||
    night.day !== day ||
    night.committed ||
    !world.getAliveEntityIds().includes(actorId)
  )
    throw new Error("nightmare_fear_scope_invalid");
  const candidates = nightmareFearTargets(world, actorId, day);
  if (
    targetId === null
      ? board.state.fearActionPolicy === "required_when_legal" && candidates.length > 0
      : !candidates.includes(targetId)
  )
    throw new Error("nightmare_fear_target_invalid");
  const target = targetId === null ? null : captureNightLife(world, targetId);
  if (targetId !== null && !target) throw new Error("nightmare_fear_target_invalid");
  const wolfBlocked =
    targetId !== null && !!world.getComponent(targetId, COMPONENT.Role) &&
    world.getComponent(targetId, COMPONENT.Camp)?.camp === Camp.Wolf;
  NIGHTMARE_SHADOW_STATE_SLOT.allowedWrites.recordFear(() => board.state, day, targetId);
  board.expectedState = NIGHTMARE_SHADOW_STATE_SLOT.checkpoint.identity(board.state);
  night.committed = true;
  night.target = target;
  night.wolfBlocked = wolfBlocked;
}
/** 原正常首次死亡仍保留本夜禁言供死亡行动窗口使用；复活或生命替换不因此获得续权。 */
export function nightmareFearBlocks(
  world: World,
  id: EntityId,
  day: number,
  allowFirstDeath = false,
): boolean {
  assertNightmareRosterCurrent(world);
  const night = boards.get(world)?.night,
    target = night?.target;
  if (!night || night.day !== day || !target || target.id !== id) return false;
  if (livingNightLife(world, target)) return true;
  if (!allowFirstDeath) throw new Error("nightmare_target_life_revoked");
  return (
    world.getComponent(id, COMPONENT.Alive) === target.life &&
    !target.life.alive &&
    aliveLifeVersion(target.life) === target.version + 1
  );
}
export function nightmareKnifeBlocked(world: World, day?: number): boolean {
  assertNightmareRosterCurrent(world);
  const night = boards.get(world)?.night;
  return !!night && (day === undefined || night.day === day) && night.wolfBlocked;
}

export function nightmareFearPending(world: World, actorId: EntityId, day: number): boolean {
  assertNightmareRosterCurrent(world);
  const board = boards.get(world),
    night = board?.night;
  return (
    !!board &&
    !!night &&
    board.actorId === actorId &&
    night.day === day &&
    night.required &&
    !night.committed &&
    world.getAliveEntityIds().includes(actorId)
  );
}

/**
 * 负责在受影响的原生夜能力之前推进噩梦之影恐惧请求；输入是原 frame 与校验后的目标选择。
 * 输出为原恐惧提交和事件；Provider 等待前后及提交前按原顺序复验名单、日期与运行窗口。
 * 阻断资格仍由 frame 持有，不因模型拒绝、玩家状态形状或文案直接产生许可。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getNightmareShadowState } from "./state-slot";
import {
  assertNightmareRosterCurrent,
  beginNightmareNight,
  commitNightmareFear,
} from "./night_frame";

/** 原首次原生行动：恐惧成功提交之前不公开狼同伴知识；声明优先级不授予实际库存。 */
export const NIGHTMARE_FEAR_STAGE: NightStageHandler = {
  id: "nightmare_fear",
  priority: 90,
  async execute(ctx) {
    const day = ctx.currentDay();
    const actorId = beginNightmareNight(ctx.world, day);
    if (actorId === null) return;
    const role = ctx.world.getComponent(actorId, COMPONENT.Role);
    if (!getNightmareShadowState(role, () => ctx.world.getComponent(actorId, COMPONENT.Camp))) throw new Error("nightmare_fear_actor_invalid");
    const request = ctx.makeRequest(actorId, ["fear"], {
      stage: "nightmare_fear",
      requiresAction: true,
      action_failure_policy: "error",
      allow_fallback: false,
    });
    assertNightmareRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertNightmareRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("nightmare_fear_stale");
    if (action?.name !== "fear") throw new Error("nightmare_fear_action_missing");
    const args = action.args;
    if (
      !args ||
      typeof args.abstain !== "boolean" ||
      (args.abstain
        ? args.target_id !== null
        : typeof args.target_id !== "number" || !Number.isSafeInteger(args.target_id))
    )
      throw new Error("nightmare_fear_action_invalid");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertNightmareRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("nightmare_fear_stale");
    if (!validated.ok || validated.sanitizedCall?.name !== "fear")
      throw new Error("nightmare_fear_action_invalid");
    const targetId = validated.sanitizedCall.args.target_id;
    commitNightmareFear(ctx.world, actorId, day, targetId);
    ctx.events.push({
      timestamp: Date.now(),
      type: "nightmare_fear_committed",
      payload: { actorId, day, targetId },
      audience: Object.freeze([actorId]),
    });
  },
};

/**
 * 提供梦魇绑定的恐惧资格、普通狼刀目标及原状态读取查询。
 * 输入是玩家／日期、候选序号或原角色；输出保留原恐惧谓词、狼行动政策及同一可读状态绑定。
 * 绑定只捕获原 World 引用，不提前读组件或返回 World、状态写者、夜间开启或效果提交方法。
 * 名单复验与四参数恐惧查询公开同一原函数；死亡窗口仍由调用方明确传入允许首次死亡，不改原撤销；
 * 查询时仍传播原名单撤销与目标生命失败；板子谓词保持原只读绑定及调用方重复参数的读取顺序。
