export function openServantChoice(world: World, day: number) {
  const { owner, night, lease, eligible } = choiceLease(world, day, "noble");
  return Object.freeze({
    isCurrent: eligible,
    commit(targetId: number | null) {
      if (!eligible()) throw Error("night_noble_choice_revoked");
      const next = chooseServant(
        owner.stateSlot.nobleState,
        day,
        targetId,
        owner.noble.id,
        [...owner.players.values()].filter((p) => playerCurrent(world, p, true)).map((p) => p.id),
      );
      const target = targetId === null ? null : owner.players.get(targetId)!;
      owner.stateSlot.commitNoble(next);
      lease.committed = true;
      const created = next.contracts.find((c) => c.createdNight === day);
      owner.nobleKnowledge = copyNobleKnowledge({
        ...owner.nobleKnowledge,
        lastChoice: next.lastChoice,
        contracts: created
          ? [...owner.nobleKnowledge.contracts, created]
          : owner.nobleKnowledge.contracts,
      });
      if (target)
        owner.contracts.set(
          `servant:night:${day}`,
          Object.freeze({
            target,
            createdNight: day,
            expiresNight: day + 1,
            id: `servant:night:${day}`,
          }),
        );
      return Object.freeze({
        actorId: owner.noble.id,
        day,
        targetId,
        contractId: target ? `servant:night:${day}` : null,
      });
    },
  });
}
export function openSecretBodyChoice(world: World, day: number) {
  const { owner, night, lease, eligible } = choiceLease(world, day, "body");
  return Object.freeze({
    isCurrent: eligible,
    commit(targetId: number | null) {
      if (!eligible()) throw Error("secret_body_choice_revoked");
      const next = chooseBodyTarget(
        owner.stateSlot.bodyState,
        day,
        targetId,
        [...owner.players.values()].filter((p) => playerCurrent(world, p, true)).map((p) => p.id),
      );
      owner.stateSlot.commitBody(next);
      owner.bodyKnowledge = copySecretBodyKnowledge({
        ...owner.bodyKnowledge,
        lastChoice: next.lastChoice,
      });
      night.bodyTarget = targetId === null ? null : owner.players.get(targetId)!;
      lease.committed = true;
      return Object.freeze({ actorId: owner.body.id, day, targetId });
    },
  });
}
/** 猎魔资格归已交付猎魔行动；此同步例外只关闭原契约，不自行造成或取消其他伤害。 */
export function clearServantFromHunt(
  world: World,
  day: number,
  targetId: number,
): Readonly<{ contractId: string; targetId: number }> | null {
  const { owner } = requireNight(world, day),
    contract = owner.stateSlot.nobleState.contracts.find(
      (c) => c.status.kind === "pending" && c.targetId === targetId,
    );
  if (!contract) return null;
  const binding = owner.contracts.get(contract.id);
  if (!binding || !playerCurrent(world, binding.target, true))
    throw Error("night_noble_contract_revoked");
  owner.stateSlot.commitNoble(endServant(owner.stateSlot.nobleState, contract.id, day, "cleared"));
  return Object.freeze({ contractId: contract.id, targetId });
}
/** 调用方在实际夜伤前同时记录到期与返回提案；本函数只结束契约，不标记目标死亡。 */
export function expireServantAtNightEnd(
  world: World,
  day: number,
  nightUnit?: NightUnit,
): Readonly<{ contractId: string; targetId: number; cause: "servant_expiry" }> | null {
  const { owner, night } = requireNight(world, day);
  // 已绑定的新调用须消费同一真实夜；旧两参数API与未知元数据仍保原接受边界。
  const boundUnit = nightUnitOf(night);
  if (isNightUnit(nightUnit) && boundUnit && boundUnit !== nightUnit)
    throw Error("noble_body_night_unit_mismatch");
  if (night.expiryProcessed) throw Error("night_noble_expiry_already_processed");
  const contract = owner.stateSlot.nobleState.contracts.find(
    (c) => c.status.kind === "pending" && c.expiresNight === day,
  );
  if (!contract) {
    night.expiryProcessed = true;
    return null;
  }
  const binding = owner.contracts.get(contract.id);
  if (!binding || !playerCurrent(world, binding.target, true))
    throw Error("night_noble_contract_revoked");
  owner.stateSlot.commitNoble(endServant(owner.stateSlot.nobleState, contract.id, day, "expired"));
  night.expiryProcessed = true;
  return Object.freeze({
    contractId: contract.id,
    targetId: contract.targetId,
    cause: "servant_expiry" as const,
  });
}
/** 在原生命实际标死后、遗言或警徽 await 前关闭契约；状态槽写入不能替代这次生命提交。 */
export function closeServantForDeath(
  world: World,
  day: number,
  targetId: number,
): Readonly<{ contractId: string; targetId: number }> | null {
  const owner = requireOwner(world),
    contract = owner.stateSlot.nobleState.contracts.find(
      (c) => c.status.kind === "pending" && c.targetId === targetId,
    );
  if (!contract) return null;
  const binding = owner.contracts.get(contract.id);
  if (
    !binding ||
    !playerCurrent(world, binding.target) ||
    binding.target.life.alive ||
    aliveLifeVersion(binding.target.life) !== binding.target.version + 1
  )
    throw Error("night_noble_death_not_committed");
  owner.stateSlot.commitNoble(endServant(owner.stateSlot.nobleState, contract.id, day, "target_dead"));
  return Object.freeze({ contractId: contract.id, targetId });
}
/** 只有已付且匹配原体的选择能消费一次身体；控制方提供最终有效来源，并把返回回执与实际伤害配对。 */
export function resolveSecretBodyDamage(world: World, day: number, sources: SecretBodySources) {
  const originalOwner = owners.get(world),
    originalNight = originalOwner?.nights.get(day);
  // 回调递归不得消费或终止外层结算，仍在原 try 前拒绝。
  if (originalOwner?.checkingController) throw Error("noble_body_controller_reentry");
  try {
    const { owner, night } = requireNight(world, day, true);
    if (night.status !== "normal") throw Error("secret_body_damage_before_action_close");
    if (night.bodyResolved) throw Error("secret_body_damage_already_processed");
    if (!night.body.committed || owner.stateSlot.bodyState.body.kind !== "intact") {
      const unchanged = Object.freeze({ blocked: null, sources: copySecretBodySources(sources) });
      night.bodyResolved = true;
      return unchanged;
    }
    if (
      !playerCurrent(world, owner.body) ||
      (night.bodyTarget && !playerCurrent(world, night.bodyTarget))
    )
      throw Error("secret_body_paid_binding_revoked");
    const plan = planSecretBodyBlock(owner.body.id, night.bodyTarget?.id ?? null, sources);
    if (plan.blocked)
      owner.stateSlot.commitBody(spendBodyForNight(owner.stateSlot.bodyState, day, owner.body.id, plan.blocked));
    night.bodyResolved = true;
    return plan;
  } catch (error) {
    if (originalNight?.status === "normal" && !originalNight.bodyResolved)
      originalNight.status = "aborted";
    throw error;
  }
}
export function closeNobleBodyNight(world: World, day: number, status: "normal" | "aborted"): void {
  const owner = owners.get(world),
    night = owner?.nights.get(day);
  if (
    !owner ||
    owner.checkingController ||
    !night ||
    !["normal", "aborted"].includes(status) ||
    (night.status !== "open" &&
      !(
        status === "aborted" &&
        !night.bodyResolved &&
        ["normal", "aborted"].includes(night.status)
      ))
  )
    throw Error("noble_body_night_unavailable");
  if (
    status === "normal" &&
    (!night.expiryProcessed ||
      (night.requiresBody && !night.body.committed) ||
      (night.requiresNoble && !night.noble.committed))
  )
    throw Error("noble_body_night_incomplete");
  night.status = status;
  if (owner.active === night) owner.active = null;
}
/** 活人放逐资格归 VotingPipeline，并有独立翻牌发言；耗身保持原提交顺序，不作为死亡遗言。 */
export function consumeSecretBodyExile(
  world: World,
  day: number,
): Readonly<{ actorId: number; day: number }> {
  const owner = requireOwner(world),
    night = owner.nights.get(day);
  if (
    owner.active ||
    !night ||
    night.status !== "normal" ||
    !night.bodyResolved ||
    [...owner.nights.keys()].some((previous) => previous > day) ||
    !playerCurrent(world, owner.body, true)
  )
    throw Error("secret_body_exile_owner_revoked");
  owner.stateSlot.commitBody(revealBodyByExile(owner.stateSlot.bodyState, day));
  owner.bodyKnowledge = copySecretBodyKnowledge({
    ...owner.bodyKnowledge,
    resource: "exile_revealed",
    publicRevealDay: day,
  });
  return Object.freeze({ actorId: owner.body.id, day });
}
/** 玩家知识只从已告知数据投影；requireOwner仍复验原体和槽，不把真实库存或隐藏终态输出给玩家。 */
export function getNobleBodyPlayerState(world: World, actorId: number, phase: Phase) {
  const owner = requireOwner(world);
  if (actorId === owner.body.id)
    return {
      kind: "secret_body" as const,
      state: projectSecretBodyKnowledge(owner.bodyKnowledge, phase),
    };
  if (actorId === owner.noble.id)
    return {
      kind: "night_noble" as const,
      state: projectNobleKnowledge(owner.nobleKnowledge, phase),
    };
  return null;
}
/** 失败检查点逐属性解码已成功编码的槽影子；不读取替代库存，未完成编码仍保留原已记录影子。 */
export function checkpointNobleBodyAuthority(world: World, complete: boolean) {
  const owner = complete ? requireOwner(world) : owners.get(world);
  if (!owner) throw Error("noble_body_owner_unavailable");
  return {
    nobleId: owner.noble.id,
    bodyId: owner.body.id,
    noble: owner.stateSlot.decodeNobleShadow(),
    body: owner.stateSlot.decodeBodyShadow(),
    knowledge: {
      noble: copyNobleKnowledge(owner.nobleKnowledge),
      body: copySecretBodyKnowledge(owner.bodyKnowledge),
    },
    notices: owner.notices.map((n) =>
      n.kind === "night_noble"
        ? { ...n, known: copyNobleKnowledge(n.known) }
        : { ...n, known: copySecretBodyKnowledge(n.known) },
    ),
    nights: [...owner.nights.values()].map((n) => ({
      day: n.day,
      status: n.status,
      bodyChosen: n.body.committed,
      nobleChosen: n.noble.committed,
      expiryProcessed: n.expiryProcessed,
      bodyResolved: n.bodyResolved,
      revealOpened: n.revealOpened,
      revealCompleted: n.revealCompleted,
    })),
  };
}

export function snapshotNobleBodyAuthority(world: World) {
  return checkpointNobleBodyAuthority(world, true);
}
export function isNobleBodyBoard(world: World): boolean {
  return owners.has(world);
}
export function assertNobleBodyRosterCurrent(world: World): void {
  requireOwner(world);
}
export function nobleBodyChoiceActor(
  world: World,
  day: number,
  kind: "body" | "noble",
): number | null {
  const { owner, night } = requireNight(world, day);
  const lease = night[kind];
  return (kind === "body" ? night.requiresBody : night.requiresNoble) &&
    !lease.opened &&
    !lease.committed &&
    playerCurrent(world, owner[kind], true)
    ? owner[kind].id
    : null;
}
export function nobleBodyChoiceTargets(
  world: World,
  day: number,
  kind: "body" | "noble",
): readonly number[] {
  const { owner, night } = requireNight(world, day);
  if (
    !(kind === "body" ? night.requiresBody : night.requiresNoble) ||
    !playerCurrent(world, owner[kind], true)
  )
    throw Error("noble_body_choice_unavailable");
  const last = owner.stateSlot.bodyState.lastChoice;
  return Object.freeze(
    [...owner.players.values()]
      .filter(
        (p) =>
          playerCurrent(world, p, true) &&
          (kind === "noble"
            ? p.id !== owner.noble.id
            : !(
                owner.stateSlot.bodyState.protectionRepeatPolicy === "awa_nonconsecutive_nights_v1" &&
                last?.day === day - 1 &&
                last.targetId === p.id
              )),
      )
      .map((p) => p.id),
  );
}

export function abortNobleBodyNight(world: World, day: number): void {
  const owner = owners.get(world),
    night = owner?.nights.get(day);
  if (night && (night.status === "open" || (night.status === "normal" && !night.bodyResolved)))
    closeNobleBodyNight(world, day, "aborted");
}

export function openSecretBodyRevealSpeech(world: World, day: number, isCurrent: () => boolean) {
  const owner = requireOwner(world),
    night = owner.nights.get(day);
  const valid = () => {
    try {
      requireOwner(world);
      const available =
        !owner.active &&
        night?.status === "normal" &&
        night.bodyResolved &&
        !night.revealCompleted &&
        ![...owner.nights.keys()].some((d) => d > day) &&
        playerCurrent(world, owner.body, true) &&
        owner.stateSlot.bodyState.body.kind === "exile_revealed" &&
        owner.stateSlot.bodyState.body.day === day;
      if (!available || !checkController(owner, isCurrent)) return false;
      requireOwner(world);
      return (
        !owner.active &&
        night.status === "normal" &&
        !night.revealCompleted &&
        playerCurrent(world, owner.body, true)
      );
    } catch {
      return false;
    }
  };
  if (!night || night.revealOpened || !valid())
    throw Error("secret_body_reveal_speech_unavailable");
  night.revealOpened = true;
  return Object.freeze({
    actorId: owner.body.id,
    isCurrent: valid,
    commit(text: string) {
      if (!valid() || typeof text !== "string" || !text.trim() || text.length > 8192)
        throw Error("secret_body_reveal_speech_unavailable");
      night.revealCompleted = true;
      return Object.freeze({ actorId: owner.body.id, day, text });
    },
  });
}

/**
 * 负责秘密之身放逐免死、公开翻牌与必需活人发言的完整同步交接。
 * 输入为原运行对象的晚读查询和已映射目标；输出原行动请求以及是否已处理放逐，不输出 JSON 租约。
 * 身体付款先于公开事实和必需录制；失败保留已付／已发布前缀，不重试或回滚。原权威独占资源和许可。
 * 生成器仅在原 Provider 等待点交出请求；调用方负责原唯一 await，拒绝时必须 return 进入已打开的 finally。
 * 非本族或不触发路径同步结束，不增加等待；发言复验、提交和关闭仍按原顺序执行。
 */
import { Phase } from "../../../../core/domain/identity";
import type { ActionRequest, ToolCall } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import type { World } from "../../../../core/domain/world";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { checkpointNobleBodyAuthority, consumeSecretBodyExile } from "./authority";
import {
  openNobleBodyRevealRequest,
  nobleBodyRequestScope,
  commitNobleBodyRevealSpeech,
  closeNobleBodyRequest,
} from "./requests";
import { getSessionRecorder } from "../../../../recording/recording_context";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";

/** 原对象的只读视图；getter 在原表达式位置读取，不缓存 World、日次、回调或工厂方法，也不授予许可。 */
export interface SecretBodyExileRevealQueries {
  readonly enabled: ReadonlyBoardConfig["nobleSecretBody"];
  readonly world: World;
  readonly events: GameEvent[];
  readonly requests: ActionRequestConstructionPort;
  readonly toolGateway: Pick<ToolGateway, "validateAndSanitize">;
  readonly day: number;
  readonly isCurrent: (() => boolean) | undefined;
}

/** false 表示继续普通放逐；true 表示已完成翻牌。暂停时仅交原请求，不能据请求副本代替当前 scope。 */
export function* revealSecretBodyExile(
  queries: SecretBodyExileRevealQueries,
  effectiveTarget: number,
): Generator<ActionRequest, boolean, ToolCall | null> {
  if (queries.enabled) {
    const owned = checkpointNobleBodyAuthority(queries.world, true);
    if (effectiveTarget === owned.bodyId && owned.body.body.kind === "intact") {
      // 先耗身，再发布与必需录制；这些失败仍处于打开发言 scope 之前。
      const receipt = consumeSecretBodyExile(queries.world, queries.day),
        payload = { policy: "awa_noble_secret_body_v1" as const, ...receipt };
      queries.events.push({ timestamp: Date.now(), type: "secret_body_revealed", payload });
      getSessionRecorder()?.recordRequiredLogicOp({
        scope: "resolution",
        op: "secret_body_revealed",
        actorId: receipt.actorId,
        phase: Phase.Voting,
        status: "ok",
        output: payload,
      });
      const request = queries.requests.create({
          actorId: receipt.actorId,
          phase: Phase.Voting,
          allowedTools: ["speak"],
          stage: "awakened_idiot_reveal_speech",
          requiresAction: true,
          summary: { key: "request.summary.secret_body_reveal" },
          context: { allow_fallback: false, action_failure_policy: "error" },
        }),
        scope = openNobleBodyRevealRequest(
          queries.world,
          queries.day,
          request,
          queries.isCurrent ?? (() => true),
        );
      try {
        // 这里只暂停，不调用 Provider；恢复后先复验原 scope，再校验和提交。
        const action = yield request;
        if (nobleBodyRequestScope(queries.world, request) !== scope || action?.name !== "speak")
          throw Error("secret_body_reveal_speech_required");
        const valid = queries.toolGateway.validateAndSanitize(queries.world, receipt.actorId, action, {
          phase: Phase.Voting,
          day: queries.day,
          deferOperation: true,
        });
        if (
          !valid.ok ||
          !valid.sanitizedCall ||
          nobleBodyRequestScope(queries.world, request) !== scope
        )
          throw Error("secret_body_reveal_speech_required");
        const spoken = commitNobleBodyRevealSpeech(queries.world, scope, valid.sanitizedCall);
        queries.events.push({
          timestamp: Date.now(),
          type: "secret_body_reveal_speech",
          payload: { policy: "awa_noble_secret_body_v1", ...spoken },
        });
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId: receipt.actorId,
          phase: Phase.Voting,
          status: "ok",
          input: { tool: "speak", args: { text: spoken.text } },
        });
      } finally {
        // 成功／复验错误均关闭一次；Provider 拒绝由调用方 return 驱动这里，关闭错误沿原 finally 优先。
        closeNobleBodyRequest(scope);
      }
      return true;
    }
  }
  return false;
}

/**
 * 负责把夜之贵族／觉醒愚者秘密之身的原知识通知与契约结算回执发布为事实和必需录制。
 * 输入为原权威的通知／回执、事件数组与阶段；输出保留原载荷、受众冻结和记录失败前缀。
 * 知识与通知纯结构归公共契约，实际库存和付款仍归 authority；本模块不选择目标、
 * 重新判胜或授予租约，先检查权威回执再记录／发布的原顺序保持。
 */
import type { GameEvent } from "../../../../core/domain/events";
import { Phase } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import { getSessionRecorder } from "../../../../recording/recording_context";
import { checkpointNobleBodyAuthority } from "./authority";
import { NOBLE_SECRET_BODY_POLICY } from "./state";
import type { NobleBodyNightNotice } from "@ai-werewolf-arena/game-contract/facts/noble-secret-body";
export function appendNobleBodyNotices(
  events: GameEvent[],
  notices: readonly NobleBodyNightNotice[],
): void {
  for (const n of notices)
    events.push(
      n.kind === "night_noble"
        ? {
            timestamp: Date.now(),
            type: "noble_night_notified",
            payload: {
              policy: NOBLE_SECRET_BODY_POLICY,
              actorId: n.actorId,
              day: n.day,
              ...n.known,
            },
            audience: Object.freeze([n.actorId]),
          }
        : {
            timestamp: Date.now(),
            type: "secret_body_night_notified",
            payload: {
              policy: NOBLE_SECRET_BODY_POLICY,
              actorId: n.actorId,
              day: n.day,
              ...n.known,
            },
            audience: Object.freeze([n.actorId]),
          },
    );
}
export function recordNobleContractClosure(
  world: World,
  day: number,
  receipt: { contractId: string; targetId: number },
  phase: Phase,
) {
  const owned = checkpointNobleBodyAuthority(world, true),
    contract = owned.noble.contracts.find((c) => c.id === receipt.contractId);
  if (
    !contract ||
    contract.status.kind === "pending" ||
    contract.status.day !== day ||
    contract.targetId !== receipt.targetId
  )
    throw Error("noble_contract_fact_invalid");
  const payload = {
    policy: NOBLE_SECRET_BODY_POLICY,
    actorId: owned.nobleId,
    day,
    contractId: contract.id,
    targetId: contract.targetId,
    createdNight: contract.createdNight,
    expiresNight: contract.expiresNight,
    ...(contract.status.kind === "expired"
      ? { status: "expired" as const, proposedCause: "servant_expiry" as const }
      : { status: contract.status.kind }),
  };
  getSessionRecorder()?.recordRequiredLogicOp({
    scope: "resolution",
    op: "noble_contract_closed",
    actorId: owned.nobleId,
    phase,
    status: "ok",
    output: payload,
  });
  return Object.freeze(payload);
}

export function appendNobleContractClosure(
  world: World,
  day: number,
  receipt: { contractId: string; targetId: number },
  events: GameEvent[],
  phase: Phase,
): void {
  const payload = recordNobleContractClosure(world, day, receipt, phase);
  events.push({
    timestamp: Date.now(),
    type: "noble_contract_closed",
    payload,
    audience: Object.freeze([]),
  });
}

/**
 * 负责秘密之身最终来源折叠、原名单更新以及上帝事实与录制操作的顺序发布。
 * 输入为经过既有夜间来源检查的同一 sources／deaths 和晚读取的 World／事件；输出原地更新名单与事实。
 * 实际保护付款和唯一原体仍由 authority 拥有，本模块不标死、推进阶段或选择判胜检查点。
 * 先更新来源和名单，再发布事实及必需操作；必需录制失败原样传播，已经付款／写入的前缀不回滚。
 */
import { DeathCause, Phase, type DeathSources, type EntityId, type GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../../core/domain/world";
import { getSessionRecorder } from "../../../../recording/recording_context";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { resolveSecretBodyDamage, checkpointNobleBodyAuthority } from "./authority";
import type { SecretBodySources } from "./damage";

/** 保留原运行引用与晚 getter；字段只读不冻结事件数组，也不创建新的保护或死亡许可。 */
export interface NobleNightDamagePublicationRuntime {
  readonly world: World;
  readonly events: GameEvent[];
}

/** 只在原最终来源检查点同步执行；名单、来源字典和 fact 字段顺序保持原引用与顺序。 */
export function publishNobleNightDamage(
  runtime: NobleNightDamagePublicationRuntime,
  nightDay: number,
  sources: DeathSources,
  deaths: EntityId[],
): void {
  const final = resolveSecretBodyDamage(runtime.world, nightDay, sources as SecretBodySources);
  // 先原地替换来源再重建名单，保留调用方字典和数组身份；后续发布失败不恢复已付保护。
  for (const id of Object.keys(sources)) delete sources[Number(id)];
  for (const [id, causes] of Object.entries(final.sources))
    sources[Number(id)] = causes.map((c) => c as DeathCause);
  deaths.splice(0, deaths.length, ...Object.keys(sources).map(Number));
  if (final.blocked) {
    const actorId = checkpointNobleBodyAuthority(runtime.world, true).bodyId,
      payload = {
        policy: "awa_noble_secret_body_v1" as const,
        actorId,
        day: nightDay,
        ...final.blocked,
      };
    runtime.events.push({
      timestamp: Date.now(),
      type: "secret_body_blocked",
      payload,
      audience: Object.freeze([]),
    });
    getSessionRecorder()?.recordRequiredLogicOp({
      scope: "resolution",
      op: "secret_body_blocked",
      actorId,
      phase: Phase.Night,
      status: "ok",
      output: payload,
    });
  }
  // 上帝来源事实保留同一死因字典，死亡名单另取当时副本；玩家投影不能从空受众读取这份事实。
  const committed = {
    policy: "awa_noble_secret_body_v1" as const,
    actorId: checkpointNobleBodyAuthority(runtime.world, true).bodyId,
    day: nightDay,
    blocked: final.blocked,
    deaths: [...deaths],
    deathSources: sources,
  };
  runtime.events.push({
    timestamp: Date.now(),
    type: "noble_body_sources_committed",
    payload: committed,
    audience: Object.freeze([]),
  });
  getSessionRecorder()?.recordRequiredLogicOp({
    scope: "resolution",
    op: "noble_body_sources_committed",
    phase: Phase.Night,
    status: "ok",
    output: committed,
  });
  // 已发生的必需录制完成之后才写可选诊断；不能把必需录制错误降为可选失败。
  safeRecordLogicOp({
    scope: "resolution",
    op: "night_damage_resolved",
    phase: Phase.Night,
    status: "ok",
    output: { deaths: [...deaths], death_sources: sources },
  });
}

/**
 * 负责普通狼刀阶段末夜之贵族专用 God 事实与必需录制操作的完整同步发布。
 * 输入为原夜上下文的惰性查询与原未映射刀口；输出追加同一 payload 的事件和领域记录。
 * 先检查板子，再查原贵族编号和日次；events.push 方法先取得，再读时钟，事件先于必需记录。
 * 本模块不投票、映射、标死或付款；push／记录失败原样传播，保留此前印记、刀口和已发表前缀。
 */
import { Phase, type GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../../core/domain/world";
import { getSessionRecorder } from "../../../../recording/recording_context";
import { checkpointNobleBodyAuthority, isNobleBodyBoard } from "./authority";

/** 仅原 World／事件引用和日次方法；只读字段不冻结数组，也不是新增的运行授权或记录镜像。 */
export interface NobleNightKnifePublicationRuntime {
  readonly world: World;
  readonly events: GameEvent[];
  currentDay(): number;
}

/** 生产调用方的 context 闭包每次返回同一个 ctx；原 getter／currentDay receiver 在原字段点才读取。 */
export function publishNobleNightKnife(
  context: () => NobleNightKnifePublicationRuntime,
  targetId: number | null,
): void {
  if (isNobleBodyBoard(context().world)) {
    const actorId = checkpointNobleBodyAuthority(context().world, false).nobleId;
    const payload = {
      policy: "awa_noble_secret_body_v1" as const,
      actorId,
      day: context().currentDay(),
      targetId,
    };
    context().events.push({
      timestamp: Date.now(),
      type: "noble_body_knife_committed",
      payload,
      audience: Object.freeze([]),
    });
    // 事件已经追加；必需录制抛错不恢复此前刀口／印记或删除已发表事件。
    getSessionRecorder()?.recordRequiredLogicOp({
      scope: "phase_pipeline",
      op: "noble_body_knife_committed",
      phase: Phase.Night,
      status: "ok",
      output: payload,
    });
  }
}

/**
 * 负责贵族／夜仆夜间取得与经理交接，输入为延迟 World／事件、日期、current 与必要记录；
 * 输出保留原通知、取得先于发布及相同 receiver。真实夜间身份随同一 owner 交付并消费夜末到期。
 * 交接后 pipeline 不再正常开夜或终止；经理保原正常／abort 政策与 bodyResolved 检查。
 * World／day 在原调用点取值，不缓存替身世界；身份不进入请求、MCP、checkpoint 或 Tape。
 * 规则依据：docs/rules/awa-noble-secret-body-twelve-v1.md。
 */
import { types } from "node:util";
import type { NightUnit } from "../../../../core/domain/night-unit";
import type { World } from "../../../../core/domain/world";
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
