  beginNobleBodyNight,
  abortNobleBodyNight,
  closeNobleBodyNight,
  checkpointNobleBodyAuthority,
  expireServantAtNightEnd,
} from "./authority";
import { appendNobleBodyNotices } from "./facts";

export type NobleOpeningFact = {
  readonly policy: "awa_noble_secret_body_v1";
  readonly actorId: number;
  readonly day: number;
  readonly notifiedActorIds: number[];
};
export interface NobleNightRuntime {
  readonly world: World;
  readonly events: GameEvent[];
  recordOpening(payload: NobleOpeningFact): void;
}
export interface NobleNightAbortReceiver {
  abort(world: World, day: number): void;
}
export interface NobleNightReceiver extends NobleNightAbortReceiver {
  closeNormally(world: World, day: number): void;
}
const ownedResults = new WeakSet<object>();
const ownedReceivers = new WeakSet<object>();
const NOBLE_NIGHT_RECEIVER = Symbol("noble_night_receiver");

/** 取得前的中断接收方不读取 World／day／config，不生成成功开夜身份。 */
export function createNobleNightAbortReceiver(): NobleNightAbortReceiver {
  return Object.freeze({
    abort(world: World, day: number) {
      abortNobleBodyNight(world, day);
    },
  });
}

function createNobleNightReceiver(unit: () => NightUnit | undefined): NobleNightReceiver {
  const receiver = Object.freeze({
    closeNormally(world: World, day: number) {
      closeNobleBodyNight(world, day, "normal");
    },
    abort(world: World, day: number) {
      abortNobleBodyNight(world, day);
    },
    expire(world: () => World, day: () => number) {
      return expireServantAtNightEnd(world(), day(), unit());
    },
  });
  ownedReceivers.add(receiver);
  return receiver;
}

/** 只给后端结果关联运行时接收方；原可枚举字段、JSON 与展开复制保持。 */
export function attachNobleNightReceiver<T extends object>(
  result: T,
  receiver: NobleNightAbortReceiver,
): T {
  Object.defineProperty(result, NOBLE_NIGHT_RECEIVER, { value: receiver });
  ownedResults.add(result);
  return result;
}

export function nobleNightReceiver(result: { interrupted: false }): NobleNightReceiver;
export function nobleNightReceiver(result: object): NobleNightAbortReceiver;
export function nobleNightReceiver(result: object): NobleNightAbortReceiver {
  const receiver = Object.getOwnPropertyDescriptor(result, NOBLE_NIGHT_RECEIVER)?.value as
    NobleNightAbortReceiver | undefined;
  if (!receiver) throw new Error("noble_night_receiver_missing");
  return receiver;
}

/**
 * 夜末到期真正消费同一夜间接收方的身份。只读本owner创建的结果／receiver；
 * 外部旧对象与旧receiver继续原两参数到期路径，不新增Symbol或方法getter读取。
 */
export function expireNobleNight(result: object, world: () => World, day: () => number) {
  if (!ownedResults.has(result) || types.isProxy(result)) return expireServantAtNightEnd(world(), day());
  const receiver = (result as { readonly [NOBLE_NIGHT_RECEIVER]: NobleNightReceiver })[NOBLE_NIGHT_RECEIVER];
  if (!ownedReceivers.has(receiver)) return expireServantAtNightEnd(world(), day());
  return (receiver as NobleNightReceiver & { expire(world: () => World, day: () => number): ReturnType<typeof expireServantAtNightEnd> }).expire(world, day);
}

export class NobleNightUnit {
  private acquired = false;
  private transferred = false;
  readonly receiver = createNobleNightReceiver(() => this.nightUnit);
  constructor(
    private readonly runtime: NobleNightRuntime,
    private readonly day: number,
    private readonly nightUnit?: NightUnit,
  ) {}
  open(isCurrent: () => boolean): void {
    if (this.transferred) throw new Error("noble_night_pipeline_ownership_transferred");
    const ctx = this.runtime,
      day = this.day;
    const notices = beginNobleBodyNight(ctx.world, day, isCurrent, this.nightUnit);
    this.acquired = true;
    appendNobleBodyNotices(ctx.events, notices);
    const payload = {
      policy: "awa_noble_secret_body_v1" as const,
      actorId: checkpointNobleBodyAuthority(ctx.world, true).nobleId,
      day,
      notifiedActorIds: notices.map((n) => n.actorId),
    };
    ctx.events.push({
      timestamp: Date.now(),
      type: "noble_body_night_opened",
      payload,
      audience: Object.freeze([]),
    });
    ctx.recordOpening(payload);
  }
  transferToManager(): void {
    this.transferred = true;
  }
  abortIfOwned(): void {
    if (this.acquired && !this.transferred) abortNobleBodyNight(this.runtime.world, this.day);
  }
}

/**
 * 负责夜之贵族／觉醒愚者两段夜间选择流程。输入为当前上下文、原候选及必需工具回复；
 * 输出为领域回执、本人事实和安全录制。await 后及 gateway 后复验请求 scope，提交先于事实和录制；
 * finally 关闭请求，晚发布失败保留已付前缀。不接管契约、秘密之身或资源算法，这些写权仍由本族 authority 持有。
 */
import type { NightStageHandler, NightStageContext } from "../../stages/night/contracts";
import { Phase } from "../../../../core/domain/identity";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { nobleBodyChoiceActor, nobleBodyChoiceTargets } from "./authority";
import {
  openNobleBodyRequest,
  nobleBodyRequestScope,
  readNobleBodyTool,
  commitNobleBodyChoice,
  closeNobleBodyRequest,
} from "./requests";
import { NOBLE_SECRET_BODY_POLICY } from "./state";
async function execute(ctx: NightStageContext, kind: "body" | "noble") {
  const day = ctx.currentDay(),
    actorId = nobleBodyChoiceActor(ctx.world, day, kind);
  if (actorId === null) return;
  const name = kind === "body" ? "protect_secret_body" : "choose_servant",
    candidates = nobleBodyChoiceTargets(ctx.world, day, kind),
    request = ctx.makeRequest(actorId, [name], {
      stage: kind === "body" ? "secret_body" : "night_noble",
      requiresAction: true,
      allow_fallback: false,
      action_failure_policy: "error",
      ...(kind === "body"
        ? { secret_body_candidates: candidates }
        : { servant_candidates: candidates }),
    }),
    scope = openNobleBodyRequest(ctx.world, day, kind, request);
  try {
    const raw = await ctx.actionProvider.getAction(request);
    if (nobleBodyRequestScope(ctx.world, request) !== scope)
      throw Error("noble_body_request_unavailable");
    const call = readNobleBodyTool(raw);
    if (!call || call.name !== name) throw Error("noble_body_required_action_invalid");
    const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, call, {
      phase: Phase.Night,
      day,
      nobleBodyScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall || nobleBodyRequestScope(ctx.world, request) !== scope)
      throw Error("noble_body_required_action_invalid");
    // 领域commit返回后才发布事实／录制；finally沿原路径关请求，晚发布不退款或重选。
    const receipt = commitNobleBodyChoice(ctx.world, scope, valid.sanitizedCall);
    ctx.events.push(
      kind === "body"
        ? {
            timestamp: Date.now(),
            type: "secret_body_chosen",
            payload: { policy: NOBLE_SECRET_BODY_POLICY, actorId, day, targetId: receipt.targetId },
            audience: Object.freeze([actorId]),
          }
        : {
            timestamp: Date.now(),
            type: "noble_servant_chosen",
            payload: {
              policy: NOBLE_SECRET_BODY_POLICY,
              actorId,
              day,
              targetId: receipt.targetId,
              contractId: receipt.targetId === null ? null : `servant:night:${day}`,
            },
            audience: Object.freeze([actorId]),
          },
    );
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: kind === "body" ? "secret_body_choice_committed" : "noble_servant_choice_committed",
      actorId,
      phase: Phase.Night,
      status: "ok",
      output: { ...receipt, policy: NOBLE_SECRET_BODY_POLICY },
    });
  } finally {
    closeNobleBodyRequest(scope);
  }
}
export const SECRET_BODY_STAGE: NightStageHandler = {
  id: "secret_body_action",
  priority: 150,
  execute: (ctx) => execute(ctx, "body"),
};
export const NOBLE_CHOICE_STAGE: NightStageHandler = {
  id: "night_noble_action",
  priority: 450,
  execute: (ctx) => execute(ctx, "noble"),
};

/**
 * 负责从夜之贵族／觉醒愚者秘密之身的已知知识构造冻结玩家视图，结构类型直接来自契约包。
 * 输入为 known journal 与公开 phase；输出为复制的选择／契约／资源字段和 awaitingNightReport。
 * 日志所有者仍拥有知识更新；此模块仅投影，不付款或授予行动权限。标记取公开阶段
 * 与已知公开放逐状态，不能比较真实与已知库存来泄漏尚未通知的变化。
 */
import { Phase } from "../../../../core/domain/identity";
