  let previous = 0;
  let consumed = false;
  for (const row of history) {
    if (!exact(row, ["day", "activate"])) return undefined;
    const day = field(row, "day");
    const activate = field(row, "activate");
    if (!dayNumber(day) || day <= previous || typeof activate !== "boolean" || consumed)
      return undefined;
    previous = day;
    consumed = activate;
  }
  return state as OrderPrinceState;
}
export function createOrderPrinceState(): OrderPrinceState {
  return { policy: ORDER_PRINCE_POLICY, history: [] };
}
export function projectOrderPrinceState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): OrderPrinceState | undefined {
  const state = getOrderPrinceState(role, currentCamp);
  if (!state) return undefined;
  // 每行重新构造，保持原可写历史数组；调用者修改该知识不会改写原槽。
  const history: OrderPrinceChoice[] = [];
  for (const row of rows(field(state, "history"))!) {
    history.push({
      day: field(row, "day") as number,
      activate: field(row, "activate") as boolean,
    });
  }
  return { policy: ORDER_PRINCE_POLICY, history };
}
/** 准备独立下一状态；原 caller 重验 pending 与原生命后才提交，不写 live 槽。 */
export function nextOrderPrinceChoice(
  role: RoleComponent | undefined,
  day: number,
  activate: boolean,
  currentCamp: CurrentCampSource,
): OrderPrinceState | undefined {
  const state = projectOrderPrinceState(role, currentCamp);
  if (!state || !dayNumber(day) || typeof activate !== "boolean") return undefined;
  const last = state.history.at(-1);
  if (last && (last.activate || last.day >= day)) return undefined;
  state.history.push({ day, activate });
  return state;
}

/** 原初始化先读赋值左侧容器，再调用无参create／setter；失败不补写或回滚。 */
function installOrderPrinceState(privateState: () => Record<string, unknown>): void {
  privateState().orderPrince = createOrderPrinceState();
}

/** authority已完成原准入；此处保原容器receiver和next引用，不复制、再校验或提前编码。 */
function replaceOrderPrinceState(
  privateState: () => RoleComponent["privateState"],
  next: OrderPrinceState,
): void {
  (privateState() as { orderPrince: OrderPrinceState }).orderPrince = next;
}

/** 先查JSON.stringify callee，再晚读原role／投影；不增加undefined拒绝或把知识数据当权限。 */
function encodeOrderPrinceProjection(
  role: () => RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): string {
  return JSON.stringify(projectOrderPrinceState(role(), currentCamp));
}

/** 原next比对：authority先替换槽及绑定引用，再查JSON.stringify；错误保留前缀，不替代档案codec。 */
function encodeOrderPrinceNext(next: OrderPrinceState): string {
  return JSON.stringify(next);
}

/**
 * 唯一数据程序表：schema/get保同一原校验，next只准备独立副本；allowedWrites仅执行原槽替换。
 * 表冻结不深冻结原状态／知识；authority仍按原序更新b.state、expected和pending，不经数据表授予重投许可。
 */
export const ORDER_PRINCE_STATE_SLOT = Object.freeze({
  create: createOrderPrinceState,
  schema: getOrderPrinceState,
  get: getOrderPrinceState,
  project: projectOrderPrinceState,
  next: nextOrderPrinceChoice,
  install: installOrderPrinceState,
  allowedWrites: Object.freeze({ replace: replaceOrderPrinceState }),
  checkpoint: Object.freeze({ projection: encodeOrderPrinceProjection, next: encodeOrderPrinceNext }),
});

/**
 * 负责定序王子在原首轮票之后的重收票选择与必需发言。输入为原 World、日次、请求构造端口及 Provider；
 * 输出原是否重收票的结果和事实，放逐目标与 PK 仍由投票流水线拥有。
 * 每个等待后保留原当前性复验；选择提交先于发言，后续失败不回滚已提交前缀，finally 仍关闭本族窗口。
 * 构造端口不授予行动或资源权限，也不绕过网关及原体检查。
 */
import type { ActionProvider, GameEvent } from "../../../../core/domain/model";
import { Phase } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import {
  openOrderPrinceChoice,
  assertOrderPrinceCurrent,
  commitOrderPrinceChoice,
  closeOrderPrinceChoice,
} from "./authority";

/** 只在原首轮票之后、任何放逐或 PK 效果之前调用，重收票仍归同一投票流水线。 */
export async function runOrderPrinceChoice(
  world: World,
  requests: ActionRequestConstructionPort,
  provider: ActionProvider,
  gateway: ToolGateway,
  events: GameEvent[],
  day: number,
  isCurrent: () => boolean,
): Promise<boolean> {
  const actorId = openOrderPrinceChoice(world, day);
  if (actorId === null) return false;
  const current = () => {
    assertOrderPrinceCurrent(world, actorId);
    if (!isCurrent()) throw new Error("order_prince_choice_stale");
  };
  try {
    current();
    const choice = await provider.getAction(
      requests.create({
        phase: Phase.Voting,
        actorId,
        allowedTools: ["reset_exile_vote"],
        stage: "order_prince_choice",
        requiresAction: true,
        summary: { key: "request.summary.order_prince_choice" },
        context: { action_failure_policy: "error", allow_fallback: false },
      }),
    );
    current();
    if (choice?.name !== "reset_exile_vote") throw new Error("order_prince_choice_missing");
    const checked = gateway.validateAndSanitize(world, actorId, choice, {
      phase: Phase.Voting,
      day,
    });
    current();
    if (!checked.ok || checked.sanitizedCall?.name !== "reset_exile_vote")
      throw new Error("order_prince_choice_invalid");
    const activate = checked.sanitizedCall.args.activate;
    commitOrderPrinceChoice(world, actorId, day, activate);
    events.push({
      timestamp: Date.now(),
      type: "order_prince_choice_committed",
      payload: { actorId, day, activate },
      audience: Object.freeze([actorId]),
    });
    if (!activate) return false;
    events.push({
      timestamp: Date.now(),
      type: "order_prince_revote_started",
      payload: { actorId },
    });
    current();
    const speech = await provider.getAction(
      requests.create({
        phase: Phase.Voting,
        actorId,
        allowedTools: ["speak"],
        stage: "order_prince_speech",
        requiresAction: true,
        summary: { key: "request.summary.order_prince_speech" },
        context: { action_failure_policy: "error", allow_fallback: false },
      }),
    );
    current();
    if (speech?.name !== "speak") throw new Error("order_prince_speech_missing");
    const validated = gateway.validateAndSanitize(world, actorId, speech, {
      phase: Phase.Voting,
      day,
    });
    current();
    if (!validated.ok || validated.sanitizedCall?.name !== "speak")
      throw new Error("order_prince_speech_invalid");
    events.push({
      timestamp: Date.now(),
      type: "day_speech",
      payload: { actorId, text: validated.sanitizedCall.args.text },
    });
    return true;
  } finally {
    closeOrderPrinceChoice(world);
  }
}

/**
 * 负责捕获玩家原角色、阵营与工厂生命／版本引用。输入为 World 和玩家 ID，输出为原生命及仍当前的查询谓词。
 * 阵营只由真实 Camp 组件提供，保原 own-data／枚举与组件引用撤权；不退回角色镜像。
 * 运行范围不成为协议数据，也不替换已捕获组件；原体身份与当前性仍在实际查询时复核。
 */
import { types } from "node:util";
import type { World } from "../../../core/domain/world";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { CampComponent } from "../../../core/domain/components/camp";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../core/domain/components/alive";
import { COMPONENT } from "../../../core/domain/components/names";
import { isRoleId, type RoleId } from "@ai-werewolf-arena/game-contract";
import { Camp } from "../../../core/domain/identity";
export interface OriginalPlayerScope {
  readonly id: number;
  readonly life: AliveComponent;
  readonly version: number;
  readonly role: RoleComponent;
  readonly roleId: RoleId;
  readonly camp: CampComponent;
  readonly campValue: Camp;
}
const captured = new WeakMap<OriginalPlayerScope, World>();
function own(v: object, key: string): unknown {
  if (types.isProxy(v)) return undefined;
  const d = Object.getOwnPropertyDescriptor(v, key);
  return d && "value" in d ? d.value : undefined;
}
function safeAlive(v: AliveComponent | undefined): v is AliveComponent {
  if (!v || types.isProxy(v) || aliveLifeVersion(v) === undefined) return false;
  const original = aliveLifeDescriptor(v),
    actual = Object.getOwnPropertyDescriptor(v, "alive");
  return !!original && !!actual && actual.get === original.get && actual.set === original.set;
}
export function captureOriginalPlayer(world: World, id: number): OriginalPlayerScope | null {
  const life = world.getComponent(id, COMPONENT.Alive),
    role = world.getComponent(id, COMPONENT.Role),
    camp = world.getComponent(id, COMPONENT.Camp);
  if (!Number.isSafeInteger(id) || id < 1 || !safeAlive(life) || !life.alive || !role || !camp)
    return null;
  const roleId = own(role, "role"),
    campValue = own(camp, "camp");
  if (
    !isRoleId(roleId) ||
    !Object.values(Camp).includes(campValue as Camp)
  )
    return null;
  const scope = Object.freeze({
    id,
    life,
    version: aliveLifeVersion(life)!,
    role,
    roleId,
    camp,
    campValue: campValue as Camp,
  });
  captured.set(scope, world);
  return scope;
}
/** 已付效果可保留第一次原生命死亡，不可借组件替换或复活重新匹配。 */
export function originalPlayerSameLife(
  world: World,
  s: OriginalPlayerScope,
  allowFirstDeath = false,
): boolean {
  return (
    captured.get(s) === world &&
    world.getComponent(s.id, COMPONENT.Alive) === s.life &&
    safeAlive(s.life) &&
    (s.life.alive
      ? aliveLifeVersion(s.life) === s.version
      : allowFirstDeath && aliveLifeVersion(s.life) === s.version + 1) &&
    world.getComponent(s.id, COMPONENT.Role) === s.role &&
    world.getComponent(s.id, COMPONENT.Camp) === s.camp &&
    own(s.role, "role") === s.roleId &&
    own(s.camp, "camp") === s.campValue
  );
}
export function originalPlayerCurrent(world: World, s: OriginalPlayerScope): boolean {
  return originalPlayerSameLife(world, s);
}

/**
 * 负责按角色运行贡献生成领域工具许可注册表。输入为明确 Catalog，输出为角色与可用工具的原有序登记；公共工具与原贡献去重，不维护第二份角色资料或提示视图，也不授权具体行动租约。
 */
import { RoleRegistry } from "../../../core/domain/registries/role_registry";
import { COMMON_TOOL_SPECS } from "../common/tool_specs";
import { type RoleCatalog } from "./catalog";
import { getDefaultRoleCatalog } from "./role-catalog-assembly";

export function createDefaultRoleRegistry(
  catalog: RoleCatalog = getDefaultRoleCatalog(),
): RoleRegistry {
  const registry = new RoleRegistry();
  const commonTools = COMMON_TOOL_SPECS.map((spec) => spec.name);
  for (const { metadata, runtime: profile } of catalog.allRuntime()) {
    // 在原 register 参数求值点读取角色字段，保留自定义资料 getter 和可变角色标识的原轨迹。
    registry.registerAllowedTools(metadata.role, [
      ...new Set([...commonTools, ...(profile.toolSpecs ?? []).map((spec) => spec.name)]),
    ]);
  }
  return registry;
}

/**
 * 负责将角色／能力状态裁剪为已授权玩家可见 DTO；公共结构归 game-contract 的玩家视图契约。
 * 输入为现有状态读视图或显式事实字段；输出为独立投影，不泄露内部来源身份、库存写权或授权句柄。
 * 赠枪投影同时供原 transfer 制作安装数据，字段／status 求值顺序保持；本模块不授枪或转移资源。
 * 纯字段校验和复制只作用于数据，不读 World、时钟、RNG、文件或模型服务。
 */
import { playerDataField, positiveInteger, rows } from "./player-state-data";
import type { DeathGunReadView } from "@ai-werewolf-arena/game-contract";
import type {
  PlayerGuardState,
  PlayerHunterState,
  PlayerWolfKingState,
  PlayerDreamerState,
  PlayerWolfBeautyState,
  PlayerSeerState,
  PlayerWitchState,
  PlayerRoleInspectionState,
  PlayerDeathGun,
} from "@ai-werewolf-arena/game-contract/player-state-views";
import { WitchSelfHealRule } from "../../../core/domain/model";
import { readInspectionResult } from "@ai-werewolf-arena/replay-contract";

function positiveOrNull(value: unknown): number | null {
  return positiveInteger(value) ? value : null;
}
function stock(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : 0;
}
function nullableTarget(value: unknown): value is number | null {
  return value === null || positiveInteger(value);
}
function inspection(value: unknown) {
  const kind = playerDataField(value, "kind");
  return readInspectionResult(
    kind === "camp"
      ? { kind, camp: playerDataField(value, "camp") }
      : kind === "role"
        ? { kind, role: playerDataField(value, "role") }
        : kind === "combined"
          ? { kind, camp: playerDataField(value, "camp"), role: playerDataField(value, "role") }
          : null,
  );
}

export function projectGuardState(state: unknown): PlayerGuardState {
  const policy = playerDataField(state, "repeatPolicy");
  return {
    lastTarget: positiveOrNull(playerDataField(state, "lastTarget")),
    ...(policy === "awa_last_action_v1" || policy === "netease_consecutive_nights_v1"
      ? { repeatPolicy: policy }
      : {}),
  };
}
function projectGunState(state: unknown): PlayerHunterState {
  const policy = playerDataField(state, "deathActionPolicy");
  return {
    canShoot: playerDataField(state, "canShoot") === true,
    ...(policy === "awa_qualified_sources_v1" || policy === "awa_knife_or_exile_v1"
      ? { deathActionPolicy: policy }
      : {}),
  };
}
export function projectHunterState(state: unknown): PlayerHunterState {
  return projectGunState(state);
}
export function projectWolfKingState(state: unknown): PlayerWolfKingState {
  return {
    ...projectGunState(state),
    ...(playerDataField(state, "deathActionPolicy") === "awa_day_deaths_v1"
      ? { deathActionPolicy: "awa_day_deaths_v1" as const }
      : {}),
  };
}
export function projectDreamerState(state: unknown): PlayerDreamerState {
  const policy = playerDataField(state, "protectionPolicy");
  return {
    ...(policy === "awa_night_damage_v1" || policy === "netease_2026_night_immunity_v1"
      ? { protectionPolicy: policy }
      : {}),
    lastTarget: positiveOrNull(playerDataField(state, "lastTarget")),
    lastDay: positiveOrNull(playerDataField(state, "lastDay")),
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const day = playerDataField(row, "day"),
        targetId = playerDataField(row, "targetId");
      return positiveInteger(day) && positiveInteger(targetId) ? [{ day, targetId }] : [];
    }),
  };
}
export function projectWolfBeautyState(state: unknown): PlayerWolfBeautyState {
  const policy = playerDataField(state, "deathLinkPolicy");
  return {
    ...(policy === "awa_exile_poison_v1" || policy === "heroes_s7_2017_exile_hunter_v1"
      ? { deathLinkPolicy: policy }
      : {}),
    targetId: positiveOrNull(playerDataField(state, "targetId")),
    lastActedDay: positiveOrNull(playerDataField(state, "lastActedDay")),
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const day = playerDataField(row, "day"),
        targetId = playerDataField(row, "targetId");
      return positiveInteger(day) && nullableTarget(targetId) ? [{ day, targetId }] : [];
    }),
  };
}
export function projectSeerState(state: unknown): PlayerSeerState {
  const targetPolicy = playerDataField(state, "targetPolicy"),
    actionPolicy = playerDataField(state, "actionPolicy");
  const lastIsWerewolf = playerDataField(state, "lastIsWerewolf"),
    lastResult = playerDataField(state, "lastResult");
  return {
    ...(targetPolicy === "awa_alive_v1" || targetPolicy === "awa_fresh_others_v1"
      ? { targetPolicy }
      : {}),
    ...(actionPolicy === "awa_optional_v1" || actionPolicy === "awa_required_when_legal_v1"
      ? { actionPolicy }
      : {}),
    lastTarget: positiveOrNull(playerDataField(state, "lastTarget")),
    lastIsWerewolf: typeof lastIsWerewolf === "boolean" ? lastIsWerewolf : null,
    ...(lastResult === undefined
      ? {}
      : { lastResult: lastResult === null ? null : inspection(lastResult) }),
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const targetId = playerDataField(row, "targetId"),
        isWerewolf = playerDataField(row, "isWerewolf"),
        result = inspection(playerDataField(row, "result"));
      return positiveInteger(targetId) && typeof isWerewolf === "boolean"
        ? [{ targetId, isWerewolf, ...(result ? { result } : {}) }]
        : [];
    }),
  };
}
export function projectWitchState(state: unknown): PlayerWitchState {
  const rule = playerDataField(state, "selfHealRule");
  const knifeVisibility = playerDataField(state, "knifeVisibility"),
    potionPolicy = playerDataField(state, "potionPolicy");
  return {
    ...(knifeVisibility === "awa_with_heal_v1" || knifeVisibility === "awa_always_v1"
      ? { knifeVisibility }
      : {}),
    ...(potionPolicy === "awa_one_native_v1" || potionPolicy === "awa_both_native_experimental_v1"
      ? { potionPolicy }
      : {}),
    heal: stock(playerDataField(state, "heal")),
    poison: stock(playerDataField(state, "poison")),
    selfHealRule:
      rule === WitchSelfHealRule.Always || rule === WitchSelfHealRule.FirstNightOnly
        ? rule
        : WitchSelfHealRule.Disabled,
    canSelfHeal: playerDataField(state, "canSelfHeal") === true,
    healUsedThisNight: playerDataField(state, "healUsedThisNight") === true,
    poisonUsedThisNight: playerDataField(state, "poisonUsedThisNight") === true,
  };
}
export function projectRoleInspectionState(state: unknown): PlayerRoleInspectionState {
  const policy = playerDataField(state, "policy"),
    inspectionPolicy = playerDataField(state, "inspectionPolicy");
  return {
    ...(inspectionPolicy === "awa_unique_required_v1" ||
    inspectionPolicy === "awa_repeat_optional_v1" ||
    inspectionPolicy === "awa_unique_optional_v1"
      ? { inspectionPolicy }
      : {}),
    ...(policy === "gargoyle" ||
    policy === "psychic" ||
    policy === "mirror" ||
    policy === "pure_white" ||
    policy === "wolf_witch"
      ? { policy }
      : {}),
    lastTarget: positiveOrNull(playerDataField(state, "lastTarget")),
    lastDay: positiveOrNull(playerDataField(state, "lastDay")),
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const day = playerDataField(row, "day"),
        targetId = playerDataField(row, "targetId"),
        result = inspection(playerDataField(row, "result"));
      return positiveInteger(day) && positiveInteger(targetId) && result?.kind === "role"
        ? [{ day, targetId, result }]
        : [];
    }),
  };
}

export function projectDeathGun(gun: DeathGunReadView): PlayerDeathGun {
  return {
    id: gun.id,
    kind: "gun",
    source: { kind: gun.source.kind },
    sourceDisclosed: false,
    grantedNight: gun.grantedNight,
    armedOnNight: gun.armedOnNight,
    remaining: gun.remaining,
    disabled: gun.disabled,
    deathExpired: gun.deathExpired,
    status:
      gun.disabled || gun.deathExpired
        ? "disabled"
        : gun.remaining === 0
          ? "spent"
          : gun.armedOnNight === null
            ? "pending"
            : "active",
  };
}

/**
 * 负责 通灵师 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { inspectionConfiguration } from "../role_inspection/contribution-ports";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { inspectionLabel } from "@ai-werewolf-arena/game-presentation";
import { Camp, Role } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { getRoleInspectionState, setRoleInspectionState } from "../role_inspection/ports";
import { numberOrNull } from "../../llm/helpers";
import { PSYCHIC_INSPECTION_STAGE } from "../role_inspection/contribution-ports";
import {
  ROLE_INSPECTION_TOOL,
  validateRoleInspection,
  roleInspectionTargets,
} from "../role_inspection/contribution-ports";

export const PSYCHIC_ROLE_PROFILE: NativeRoleContributions = {
