/**
 * 定义纯白查验目标与对应工具校验。输入为当前 World 角色和请求目标；输出为政策允许
 * 的编号或结构化拒绝。目标枚举不提交查验或发表私密结果，原目标／来源及失败顺序不变。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Phase, Role, type EntityId } from "../../../../core/domain/model";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { World } from "../../../../core/domain/world";
import type { ToolRule } from "../../validation/contracts";
import type { RoleProfile } from "../contracts";
import { activeNightAbility } from "../abilities";

export function pureWhiteInspectionTargets(
  world: World,
  actorId: EntityId,
  policy: "pure_white" | "wolf_witch",
): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter((id) => {
      if (id === actorId) return false;
      if (policy === "pure_white") return true;
      const role = world.getComponent(id, COMPONENT.Role);
      // 原缺 Role 分支仍允许此目标且不读 Camp；不能借换来源新增角色存在门槛。
      return !role || world.getComponent(id, COMPONENT.Camp)?.camp !== Camp.Wolf;
    });
}
export const PURE_WHITE_INSPECTION_TOOL: NonNullable<RoleProfile["toolSpecs"]>[number] = {
  name: "inspect_night_identity",
  parameters: {
    type: "object",
    properties: {
      target_id: { type: ["integer", "null"], minimum: 1 },
      abstain: { type: "boolean" },
    },
    required: ["target_id", "abstain"],
    additionalProperties: false,
  },
  argHint: 'inspect_night_identity args: {"target_id":number|null,"abstain":boolean}',
  userPromptHintKey: "action.inspect_night_identity.hint",
};
export const validatePureWhiteInspection: ToolRule = ({
  world,
  actorId,
  role,
  day,
  phase,
  abilityId,
  toolCall,
}) => {
  const ability = activeNightAbility(role, "role_check", day ?? 1, abilityId);
  if (!ability) return { code: RuleError.RoleInspectUnavailable };
  const policy = roleInspectionPolicy(ability.state);
  if (policy !== "pure_white" && policy !== "wolf_witch")
    return { code: RuleError.RoleInspectUnavailable };
  const expected = policy === "pure_white" ? Role.PureWhiteGirl : Role.WolfWitch;
  if (
    role.role !== expected ||
    ability.source.kind !== "native" ||
    ability.source.role !== expected
  )
    return { code: RuleError.RoleInspectUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name !== "inspect_night_identity") return { code: RuleError.ToolMismatch };
  const { target_id, abstain } = toolCall.args;
  if (abstain === true && target_id === null) return null;
  if (
    abstain !== false ||
    target_id === null ||
    !Number.isSafeInteger(target_id) ||
    !pureWhiteInspectionTargets(world, actorId, policy).includes(target_id)
  )
    return { code: RuleError.RoleInspectTarget };
  return null;
};

/**
 * 黯月借用各原能力 kind 的独立安装数据 reader。输入为未知 source payload、kind 与日期；
 * 输出保留原库存、政策及 fresh history 的复制形状和 own-field／Proxy 拒绝集合。
 * 此 reader 不修改 live 能力、转移授权或退回来源库存；只有庇护 reader 的导入归属改变。
 */

import type {
  SeerState,
  WitchState,
  DreamerState,
  ShelterState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { WitchSelfHealRule } from "../../../../core/domain/identity";
import { readShelterState } from "./shelter-state";

interface BorrowedStates {
  seer_check: SeerState;
  potion: WitchState;
  dream: DreamerState;
  shelter: ShelterState;
}
export type BorrowedKind = keyof BorrowedStates;
function field(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    throw new Error("eclipse_borrow_state_invalid");
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    throw new Error("eclipse_borrow_state_invalid");
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  if (!descriptor) return undefined;
  if (!("value" in descriptor)) throw new Error("eclipse_borrow_state_invalid");
  return descriptor.value;
}
function stock(value: unknown): number {
  if (value !== 0 && value !== 1) throw new Error("eclipse_borrow_stock_invalid");
  return value;
}
function optionalPolicy(value: unknown, expected: string): void {
  if (value !== undefined && value !== expected) throw new Error("eclipse_borrow_policy_invalid");
}
export function snapshotBorrowedState<K extends BorrowedKind>(
  kind: K,
  raw: unknown,
  day: number,
): BorrowedStates[K];
export function snapshotBorrowedState(
  kind: BorrowedKind,
  raw: unknown,
  day: number,
): BorrowedStates[BorrowedKind] {
  if (!Number.isSafeInteger(day) || day < 2) throw new Error("eclipse_borrow_day_invalid");
  switch (kind) {
    case "seer_check":
      optionalPolicy(field(raw, "targetPolicy"), "awa_alive_v1");
      optionalPolicy(field(raw, "actionPolicy"), "awa_required_when_legal_v1");
      return {
        targetPolicy: "awa_alive_v1",
        actionPolicy: "awa_required_when_legal_v1",
        lastTarget: null,
        lastIsWerewolf: null,
        lastResult: null,
        history: [],
      };
    case "potion":
      if (field(raw, "selfHealRule") !== WitchSelfHealRule.Disabled)
        throw new Error("eclipse_borrow_policy_invalid");
      optionalPolicy(field(raw, "knifeVisibility"), "awa_with_heal_v1");
      optionalPolicy(field(raw, "potionPolicy"), "awa_one_native_v1");
      return {
        heal: stock(field(raw, "heal")),
        poison: stock(field(raw, "poison")),
        selfHealRule: WitchSelfHealRule.Disabled,
        knifeVisibility: "awa_with_heal_v1",
        potionPolicy: "awa_one_native_v1",
        canSelfHeal: false,
        healUsedThisNight: false,
        poisonUsedThisNight: false,
      };
    case "dream": {
      if (field(raw, "protectionPolicy") !== "netease_2026_night_immunity_v1")
        throw new Error("eclipse_borrow_policy_invalid");
      const lastTarget = field(raw, "lastTarget"),
        lastDay = field(raw, "lastDay");
      if (!(
        (lastTarget === null && lastDay === null) ||
        (typeof lastTarget === "number" &&
          Number.isSafeInteger(lastTarget) &&
          lastTarget > 0 &&
          typeof lastDay === "number" &&
          Number.isSafeInteger(lastDay) &&
          lastDay >= 1 &&
          lastDay < day)
      ))
        throw new Error("eclipse_borrow_dream_state_invalid");
      return {
        lastTarget: lastTarget as number | null,
        lastDay: lastDay as number | null,
        protectionPolicy: "netease_2026_night_immunity_v1",
        history: [],
      };
    }
    case "shelter": {
      const source = readShelterState(raw);
      if (!source || (source.lastDay !== null && source.lastDay >= day))
        throw new Error("eclipse_borrow_shelter_state_invalid");
      return source;
    }
  }
}

/**
 * 负责蚀日侍女的初态安装、完整严格历史读取／选择／玩家投影及唯一原状态身份编码。
 * 输入为原角色容器、数据与实际日次／候选；输出为原槽、独立历史副本或具名拒绝。
 * 运行绑定只持同一 raw 对象和原 normalized JSON 字符串，不保存第二份历史或借用权威；只读类型不冻结库存。
 * 原字段集合、descriptor／Proxy拒绝及连续目标规则保持；初始化先读左值容器，提交先 Object.assign 再编码。
 * 字段写入或后续 JSON 失败保留已写前缀及旧编码；World、生命、许可、借用／抑制／付款和夜间关闭仍归 frame。
 * 本地编码只核状态替换／内容变更，不是归档格式、sourceHash 或行动授权；流光伯爵庇护沿独立所有者。
 */
import type { EclipseState, EclipseSwallowedRole } from "@ai-werewolf-arena/game-contract/facts/radiant-eclipse";
import type { RoleComponent } from "../../../../core/domain/components/role";

import { types } from "node:util";
import { RADIANT_ECLIPSE_POLICY, record, positive } from "./state-data";
export { RADIANT_ECLIPSE_POLICY } from "./state-data";

const goodRoles = ["villager", "seer", "witch", "dreamer", "radiant_count"] as const;

function items(value: unknown): unknown[] | undefined {
  if (types.isProxy(value) || !Array.isArray(value)) return;
  const fields: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
    value as object,
  );
  const length: unknown = fields.length?.value;
  if (
    typeof length !== "number" ||
    !Number.isSafeInteger(length) ||
    length < 0 ||
    Reflect.ownKeys(fields).length !== length + 1
  )
    return;
  const out: unknown[] = [];
  for (let index = 0; index < length; index++) {
    const field = fields[String(index)];
    if (!field || !("value" in field)) return;
    out.push(field.value);
  }
  return out;
}

export const createEclipseState = (): EclipseState => ({
  policy: RADIANT_ECLIPSE_POLICY,
  history: [],
});

export function readEclipseState(value: unknown): EclipseState | undefined {
  const current = record(value, ["policy", "history"]);
  if (!current || current.policy !== RADIANT_ECLIPSE_POLICY) return;
  const entries = items(current.history);
  if (!entries) return;
  const history: EclipseState["history"] = [];
  let previous: EclipseState["history"][number] | undefined;
  for (const entry of entries) {
    const choice = record(entry, ["day", "targetId", "roleId", "abilityId"]);
    if (
      !choice ||
      !positive(choice.day) ||
      choice.day < 2 ||
      (previous && choice.day <= previous.day) ||
      (choice.targetId !== null && !positive(choice.targetId))
    )
      return;
    if (choice.targetId === null) {
      if (choice.roleId !== null || choice.abilityId !== null) return;
    } else {
      if (!(goodRoles as readonly unknown[]).includes(choice.roleId)) return;
      if (
        choice.roleId === "villager"
          ? choice.abilityId !== null
          : choice.abilityId !== `copy:eclipse:night:${choice.day}`
      )
        return;
      if (previous?.day === choice.day - 1 && previous.targetId === choice.targetId) return;
    }
    previous = {
      day: choice.day,
      targetId: choice.targetId as number | null,
      roleId: choice.roleId as EclipseSwallowedRole | null,
      abilityId: choice.abilityId as string | null,
    };
    history.push(previous);
  }
  return { policy: RADIANT_ECLIPSE_POLICY, history };
}
export function selectEclipse(
  state: EclipseState,
  day: number,
  targetId: unknown,
  goodIds: readonly number[],
  roleId: unknown,
): EclipseState {
  const current = readEclipseState(state),
    last = current?.history.at(-1);
  if (!current || !positive(day) || day < 2 || (last && day <= last.day))
    throw new Error("eclipse_swallow_unavailable");
  if (targetId === null) {
    if (roleId !== null) throw new Error("eclipse_swallow_target");
  } else if (
    !positive(targetId) ||
    !goodIds.includes(targetId) ||
    !(goodRoles as readonly unknown[]).includes(roleId) ||
    (last?.day === day - 1 && last.targetId === targetId)
  )
    throw new Error("eclipse_swallow_target");
  return {
    policy: RADIANT_ECLIPSE_POLICY,
    history: [
      ...current.history,
      {
        day,
