  const maid = [...players.values()].filter((p) => p.kind === Role.EclipseMaid),
    count = [...players.values()].filter((p) => p.kind === Role.RadiantCount);
  if (players.size !== 12 || maid.length !== 1 || count.length !== 1)
    throw new Error("radiant_roster_invalid");
