/**
 * 负责原生能力实例在本夜的蚀日抑制；输入原 World／能力／日次，输出同一 marker 与原体复验／关闭方法。
 * 阵营按原值点晚读实际 Camp 的 own-data，同值组件替换不新增引用撤权；关闭仍归原资源。
 * marker 只写原实例所属槽，持有运行引用不等于玩家数据或新的行动许可；永久 disabled 仍归原能力所有者。
 * 角色、生命、能力与政策被替换后不重新授权；close 先消费 closed，再核原资源与 marker，失败不恢复无关组件。
 * 允许第一次实际死亡的关闭仍只删除同一 marker，不退款、清空库存或改写原永久禁用字段。
 */
import type { EclipseSuppression } from "@ai-werewolf-arena/game-contract";

import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";

import {
  aliveLifeDescriptor,
  type AliveComponent,
  aliveLifeVersion,
} from "../../../../core/domain/components/alive";
import { captureNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightAbilityReadView } from "../abilities";
import { RADIANT_ECLIPSE_POLICY } from "./state-data";

export type SuppressibleAbility = NightAbilityReadView;
const invalid = Symbol("invalid_eclipse_binding");
function own(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return invalid;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return field && "value" in field ? field.value : field ? invalid : undefined;
}

function plain(value: unknown): value is object {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}
function factoryLife(value: AliveComponent | undefined): value is AliveComponent {
  if (!plain(value)) return false;
  const original = aliveLifeDescriptor(value as AliveComponent),
    actual = Object.getOwnPropertyDescriptor(value, "alive");
  return (
    !!original &&
    !!actual &&
    original.get === actual.get &&
    original.set === actual.set &&
    original.enumerable === actual.enumerable &&
    original.configurable === actual.configurable
  );
}
function canonicalSlot(value: object, key: string, expected: unknown): boolean {
  const field = Object.getOwnPropertyDescriptor(value, key);
  return (
    !!field &&
    "value" in field &&
    field.value === expected &&
    field.enumerable === true &&
    field.configurable === true &&
    field.writable === true
  );
}

/** 一个原生实例的临时抑制；永久 disabled 继续由现有能力所有者管理，不在这里改写。 */
export function openEclipseSuppression(
  world: World,
  actorId: number,
  ability: SuppressibleAbility,
  day: number,
) {
  const role = world.getComponent(actorId, COMPONENT.Role);
  const originalLife = world.getComponent(actorId, COMPONENT.Alive);
  if (!factoryLife(originalLife)) throw new Error("eclipse_native_suppression_invalid");
  const life = captureNightLife(world, actorId);
  const privateState = own(role, "privateState"),
    container = own(privateState, "abilities");
  const id = own(ability, "id"),
    kind = own(ability, "kind"),
    state = own(ability, "state"),
    source = own(ability, "source");
  const roleKind = own(role, "role"),
    camp = own(world.getComponent(actorId, COMPONENT.Camp), "camp");
  const identity = world.getComponent(actorId, COMPONENT.Identity);
  const identityFields = ["id", "seat", "name", "sessionId"] as const;
  const identityValues = identityFields.map((key) => own(identity, key));
  const disabled = own(ability, "disabled");
  if (
    !role ||
    !plain(ability) ||
    !plain(privateState) ||
    !plain(container) ||
    !plain(state) ||
    !plain(source) ||
    !life ||
    !Number.isSafeInteger(day) ||
    day < 2 ||
    typeof id !== "string" ||
    !id.startsWith("native:") ||
    own(container, id) !== ability ||
    own(source, "kind") !== "native" ||
    own(source, "role") !== roleKind ||
    own(ability, "nightSuppression") !== undefined ||
    typeof disabled !== "boolean" ||
    [privateState, container, kind, state, source, roleKind, camp, ...identityValues].includes(
      invalid,
    ) ||
    !identity
  )
    throw new Error("eclipse_native_suppression_invalid");
  const marker: EclipseSuppression = { policy: RADIANT_ECLIPSE_POLICY, day };
  Object.defineProperty(ability, "nightSuppression", {
    value: marker,
    writable: true,
    enumerable: true,
    configurable: true,
  });
  let closed = false;
  const sameResource = (allowFirstDeath = false) => {
    if (
      world.getComponent(actorId, COMPONENT.Role) !== role ||
      own(role, "privateState") !== privateState ||
      own(privateState, "abilities") !== container ||
      own(container, id) !== ability ||
      world.getComponent(actorId, COMPONENT.Alive) !== life.life
    )
      return false;
    const original = aliveLifeDescriptor(life.life),
      current = Object.getOwnPropertyDescriptor(life.life, "alive");
    if (
      !original ||
      !current ||
      current.get !== original.get ||
      current.set !== original.set ||
      current.configurable !== original.configurable ||
      current.enumerable !== original.enumerable
    )
      return false;
    const version = aliveLifeVersion(life.life);
    return (
      (version === life.version && life.life.alive) ||
      (allowFirstDeath && version === life.version + 1 && !life.life.alive)
    );
  };
  const sameInstance = () =>
    sameResource() &&
    plain(ability) &&
    plain(privateState) &&
    plain(container) &&
    plain(state) &&
    plain(source) &&
    own(role, "role") === roleKind &&
    own(world.getComponent(actorId, COMPONENT.Camp), "camp") === camp &&
    own(ability, "id") === id &&
    own(ability, "kind") === kind &&
    own(ability, "state") === state &&
    own(ability, "source") === source &&
    own(source, "kind") === "native" &&
    own(source, "role") === roleKind &&
    world.getComponent(actorId, COMPONENT.Identity) === identity &&
    identityFields.every((key, index) => own(identity, key) === identityValues[index]);
  return {
    actorId,
    day,
    ability,
    marker: marker as Readonly<EclipseSuppression>,
    isCurrent: () =>
      !closed &&
      sameInstance() &&
      own(ability, "disabled") === disabled &&
      canonicalSlot(ability, "nightSuppression", marker) &&
      Object.getPrototypeOf(marker) === Object.prototype &&
      Reflect.ownKeys(marker).length === 2 &&
      canonicalSlot(marker, "policy", RADIANT_ECLIPSE_POLICY) &&
      canonicalSlot(marker, "day", day),
    close(): boolean {
      if (closed) return false;
      closed = true;
      if (!sameResource(true) || own(ability, "nightSuppression") !== marker) return false;
      delete (ability as { nightSuppression?: Readonly<EclipseSuppression> }).nightSuppression;
      return true;
    },
  };
}

/**
 * 负责幸运儿或黑市受赠者的晚执行能力阶段。
 * 输入为捕获的受赠实例和已校验行动；输出保留效果、库存、次数与受赠提交的原顺序。
 * 原毒来源复用既有 abilityId／目标参数读取，不新增 getter、资格重检或资源回滚。
 * 查验先调用状态 owner 再追加咒狐提案；本模块不替换状态槽，原体／当前性句柄仅留原运行效果，不进入玩家知识。
 */
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { Camp, Phase, PotionType, StatusMark, type ToolName } from "../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  originalPoisonIntent,
  type NightLifeScope,
} from "../../../core/domain/night_effects";
import type { World } from "../../../core/domain/world";
import type { NightStageHandler } from "../stages/night/contracts";
import { allNightAbilities, abilityStatus, type NightAbilityReadView } from "./abilities";
import { recordNightAbilityUse } from "./abilities";
import { captureNightAbilityScope } from "./ability_scope";
import { luckyTargetAllowed, recordOwnNightAction } from "./night_action_history";
import { resolveInspection } from "./inspection";
import { SEER_STATE_SLOT } from "./seer/ports";
import { GUARD_STATE_SLOT } from "./guard/ports";
import { WITCH_STATE_SLOT } from "./witch/ports";

type RecipientPolicy = "lucky" | "black_market";
const committed = new WeakMap<World, Map<RecipientPolicy, Set<number>>>();
export function hasRecipientNightCommit(
  world: World,
  day: number,
  policy: RecipientPolicy,
): boolean {
  return committed.get(world)?.get(policy)?.has(day) ?? false;
}
export function recordRecipientNightCommit(
  world: World,
  day: number,
  policy: RecipientPolicy,
): void {
  const policies = committed.get(world) ?? new Map<RecipientPolicy, Set<number>>(),
    days = policies.get(policy) ?? new Set<number>();
  days.add(day);
  policies.set(policy, days);
  committed.set(world, policies);
}

import { captureInspectionIdentity, commitFoxInspection } from "./cursed_fox/inspection-ports";

type LuckyAbility = NightAbilityReadView<"seer_check" | "potion" | "guard">;
function isRecipient(
  ability: NightAbilityReadView,
  policy: RecipientPolicy,
): ability is LuckyAbility {
  return (
    ability.activation === policy &&
    (policy === "black_market"
      ? ["seer_check", "potion"]
      : ["seer_check", "potion", "guard"]
    ).includes(ability.kind)
  );
}

export function recipientAbilityStage(
  policy: RecipientPolicy,
  priority: number,
): NightStageHandler {
  return {
    id: policy === "lucky" ? "lucky_ability" : "black_market_recipient",
    priority,
    async execute(ctx) {
      const day = ctx.currentDay();
      for (const actorId of ctx.world.getAliveEntityIds()) {
        const role = ctx.world.getComponent(actorId, COMPONENT.Role);
        for (const ability of allNightAbilities(role).filter((ability) =>
          isRecipient(ability, policy),
        )) {
          if (abilityStatus(ability, day) !== "active") continue;
          const scope = captureNightAbilityScope(ctx.world, actorId, ability, day, ctx.isCurrent);
          if (!scope) continue;
          const current = () =>
            scope.isEligible() &&
            ability.activation === policy &&
            (ability.kind !== "potion" || ability.state.poison > 0);
          if (!current()) continue;
          const tool: ToolName =
            ability.kind === "seer_check"
              ? "check_identity"
              : ability.kind === "guard"
                ? "guard"
                : "use_potion";
          const kind =
            ability.kind === "seer_check" ? "check" : ability.kind === "guard" ? "guard" : "poison";
          const skip = () => {
            recordNightAbilityUse(ability, day, false);
            recordRecipientNightCommit(ctx.world, day, policy);
            ctx.events.push({
              timestamp: Date.now(),
              type: "lucky_ability_skipped",
              payload: { actorId, abilityId: ability.id, day, kind: ability.kind },
            });
          };
          let completed = false;
          for (let attempt = 0; attempt < 3; attempt++) {
            if (!current()) break;
            // 在原校验参数和目标查找位置捕获，避免来源信息再次读取行动 getter。
            let effectAbilityId: string;
            let effectRequestedTargetId: number | null = null;
            const targets = new Map(
              ctx.world
                .getAliveEntityIds()
                .filter((id) => luckyTargetAllowed(ctx.world, actorId, ability, day, kind, id))
                .map((id) => [id, captureNightLife(ctx.world, id)!] as const),
            );
            const identities = new Map(
              [...targets].map(([id, life]) => [id, captureInspectionIdentity(ctx.world, life)]),
            );
            if (ability.kind === "seer_check" && !targets.size) {
              skip();
              completed = true;
              break;
            }
            const action = await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, [tool], {
                stage: policy === "lucky" ? "lucky" : "black_market_recipient",
                requiresAction: false,
                ...(policy === "black_market"
                  ? { action_failure_policy: "error" as const, allow_fallback: false }
                  : {}),
                ability_id: ability.id,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            );
            if (!current()) break;
            if (action === null) {
              skip();
              completed = true;
              break;
            }
            if (action.name !== tool) continue;
            const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
              phase: Phase.Night,
              day,
              abilityId: (effectAbilityId = ability.id),
            });
            if (!current() || !result.ok || !result.sanitizedCall) continue;
            const call = result.sanitizedCall;
            if (
              (call.name === "guard" && call.args.abstain) ||
              (call.name === "use_potion" && call.args.potion_type === PotionType.None)
            ) {
              skip();
              completed = true;
              break;
            }
            if (
              !["guard", "use_potion", "check_identity"].includes(call.name) ||
              !("target_id" in call.args)
            )
              continue;
            const target =
              call.args.target_id === null
                ? undefined
                : targets.get((effectRequestedTargetId = call.args.target_id));
            if (!target || !livingNightLife(ctx.world, target)) continue;
            if (!luckyTargetAllowed(ctx.world, actorId, ability, day, kind, target.id)) continue;
            if (call.name === "check_identity" && ability.kind === "seer_check") {
              if (!identities.get(target.id)?.isCurrent()) continue;
              const result = resolveInspection(ctx.world, target.id, "camp", ctx.roleCatalog);
              if (
                !result ||
                !current() ||
                !identities.get(target.id)?.isCurrent() ||
                !livingNightLife(ctx.world, target) ||
                !luckyTargetAllowed(ctx.world, actorId, ability, day, kind, target.id)
              )
                continue;
              const isWerewolf = result.camp === Camp.Wolf;
              SEER_STATE_SLOT.allowedWrites.recordRecipientSeerInspection(ability, target, isWerewolf, result);
              commitFoxInspection(ctx.world, ctx.state, target, day, () =>
                scope.isOwnerCurrent(true),
              );
              ctx.state.seerChecks.push({
                seerId: actorId,
                targetId: target.id,
                isWerewolf,
                result: { ...result },
              });
              ctx.events.push({
                timestamp: Date.now(),
                type: "seer_checked",
                payload: {
                  actorId,
                  abilityId: ability.id,
                  targetId: target.id,
                  isWerewolf,
                  result: { ...result },
                },
              });
            } else if (call.name === "guard" && ability.kind === "guard") {
              const marks = ctx.ensureMarks(target.id);
              marks.add(StatusMark.GuardMark);
              (ctx.state.guardClaims ??= []).push({ target, marks });
              GUARD_STATE_SLOT.allowedWrites.recordRecipientGuardTarget(ability, target);
              ctx.events.push({
                timestamp: Date.now(),
                type: "guard_applied",
                payload: { actorId, abilityId: ability.id, abstain: false, targetId: target.id },
              });
            } else if (
              call.name === "use_potion" &&
              call.args.potion_type === PotionType.Poison &&
              ability.kind === "potion" &&
              ability.state.poison > 0
            ) {
              let effectSource: NightLifeScope;
              (ctx.state.poisonClaims ??= []).push(
                originalPoisonIntent(
                  {
                    source: (effectSource = scope.life),
                    target,
                    ...(policy === "black_market"
                      ? {
                          isCurrent: () =>
                            ctx.isCurrent() &&
                            ctx.currentDay() === day &&
                            scope.isOwnerCurrent(true),
                        }
                      : {}),
                  },
                  {
                    family: policy === "lucky" ? "lucky" : "black-market",
                    day,
                    stage: policy === "lucky" ? "lucky" : "black_market_recipient",
                    actorLife: effectSource,
                    requestedTargetId: effectRequestedTargetId,
                    abilityId: effectAbilityId,
                  },
                ),
              );
              ctx.ensureMarks(target.id).add(StatusMark.PoisonMark);
              WITCH_STATE_SLOT.allowedWrites.consumeRecipientPoison(ability);
              ctx.events.push({
                timestamp: Date.now(),
                type: "witch_potion_used",
                payload: {
                  actorId,
                  abilityId: ability.id,
                  targetId: target.id,
                  potionType: PotionType.Poison,
                },
              });
            } else continue;
            recordNightAbilityUse(ability, day, true);
            recordOwnNightAction(ctx.world, actorId, day, kind, target.id, true, policy);
            recordRecipientNightCommit(ctx.world, day, policy);
            completed = true;
            break;
          }
          if (!completed && current()) {
            if (
              ability.kind === "seer_check" &&
              !ctx.world
                .getAliveEntityIds()
                .some((id) => luckyTargetAllowed(ctx.world, actorId, ability, day, "check", id))
            )
              skip();
            else
              throw new Error(
                policy === "black_market"
                  ? "black_market_recipient_valid_action_missing"
                  : "lucky_valid_action_missing",
              );
          }
        }
      }
    },
  };
}

/**
 * 负责 赤月使徒 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { redMoonVotedOutHook } from "./voted_out_hook";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Role, WinCondition } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { RED_MOON_POLICY, RED_MOON_STATE_SLOT } from "./state-slot";
const parameters = z.strictObject({
  policy: z.literal(RED_MOON_POLICY).default(RED_MOON_POLICY),
  lastWolfBlastPolicy: z.enum(["ends_game", "forbidden"]).default("ends_game"),
});
/** 有限运行资料；完整发布验收由红月使徒规则契约跟踪。 */
export const RED_MOON_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.RedMoonApostle,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.RedMoonApostle,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.DemonHunter,
      Role.Idiot,
    ],
    label: roleName("red_moon_apostle"),
    skillBrief: text("zh-CN", "role.red_moon_apostle.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    votedOutHook: redMoonVotedOutHook,
    init: (role, ctx) => {
      // 延迟政策读取，保原左值容器先于 fresh／配置字段的顺序；安装仍归本族唯一数据槽。
      RED_MOON_STATE_SLOT.install(
        role,
        () => parameters.parse(ctx.boardConfig?.redMoon ?? {}).lastWolfBlastPolicy,
      );
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, redMoon: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.redMoon ?? {}),
    },
  },
  presentation: nativeRolePresentation("red_moon_apostle"),
};

/**
 * 负责赤月使徒的完整数据槽：原初态、五字段校验、同引用读取、玩家投影及三项有序提交。
 * 输入为原角色、原状态和调用方已经捕获的审计数据；输出保留原引用或原 JSON／浅副本，
 * 不改变旧接受集合。属性描述符校验允许原非枚举／只读数据字段，可写资格另由权威核对。
 * 状态提交只写 blastDay、exileDay、expirySettled；后项失败保留前项写入，不回滚或重读角色槽。
 * 内部审计编码函数 保留完整容器字段和 JSON 方法的原查找时点，不是严格档案读器 或复现授权。
 * 原生命、末狼、夜窗口、请求租约和完整容器失效／最终审计写入仍由恶魔猎手权威持有。
 * 角色阵营渠道已退出；reader／project 以显式晚读 CurrentCampSource 获取实际 Camp，原 raw schema／写者不因此获得许可。
 */
import type { CurrentCampSource } from "../../../../core/domain/components/camp";
import type {
  LastWolfBlastPolicy,
  RedMoonState,
  RedMoonReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { RoleInitializationComponent } from "../contracts";
import { Camp } from "../../../../core/domain/identity";

export const RED_MOON_ROLE = "red_moon_apostle" as const;
export const RED_MOON_POLICY = "awa_red_moon_demon_v1" as const;
function own(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return field && "value" in field ? field.value : undefined;
}
function day(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
export function freshRedMoonState(
  lastWolfBlastPolicy: LastWolfBlastPolicy = "ends_game",
): RedMoonState {
  return {
    policy: RED_MOON_POLICY,
    lastWolfBlastPolicy,
    blastDay: null,
    exileDay: null,
    expirySettled: false,
  };
}
/** 安装的左值先查原 privateState，再在原 fresh callee 后读取政策；初始化不复制或二次校验。 */
export function initializeRedMoonState(
  role: RoleInitializationComponent,
  readPolicy: () => LastWolfBlastPolicy,
): void {
  role.privateState.redMoon = freshRedMoonState(readPolicy());
}

/** 原五字段形状校验 返回输入本体；拒绝代理对象／访问器，不执行它们，也不补默认或加强可写要求。 */
export function readRedMoonPayload(state: unknown): RedMoonReadState | undefined {
  if (!state || typeof state !== "object" || types.isProxy(state)) return undefined;
  const expected = ["policy", "lastWolfBlastPolicy", "blastDay", "exileDay", "expirySettled"];
  const fields = Object.getOwnPropertyDescriptors(state);
  if (
    Reflect.ownKeys(fields).length !== expected.length ||
    !expected.every((key) => fields[key] && "value" in fields[key]!)
  )
    return undefined;
  const policy = own(state, "lastWolfBlastPolicy");
  const blast = own(state, "blastDay"),
    exile = own(state, "exileDay");
  const settled = own(state, "expirySettled");
  if (
    own(state, "policy") !== RED_MOON_POLICY ||
    (policy !== "ends_game" && policy !== "forbidden") ||
    (blast !== null && !day(blast)) ||
    (exile !== null && !day(exile)) ||
    (blast !== null && exile !== null) ||
    typeof settled !== "boolean" ||
    (settled && exile === null)
  )
    return undefined;
  return state as RedMoonReadState;
}

/** 原角色／阵营门槛先于容器与 payload 校验；不以合法副本替换所属 live 状态。 */
// 当前阵营只在原 camp 数据读取点取得；保本族自身 descriptor／Proxy 策略，不回退角色或目录。
export function getRedMoonState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): RedMoonReadState | undefined {
  if (own(role, "role") !== RED_MOON_ROLE || own(currentCamp(), "camp") !== Camp.Wolf) return undefined;
  const state = own(own(role, "privateState"), "redMoon");
  return readRedMoonPayload(state);
}

/** 机制自己决定玩家字段；校验失败仍为 undefined，不补默认政策或猜测到期结果。 */
export function projectRedMoonState(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): RedMoonState | undefined {
  const redMoon = getRedMoonState(role, currentCamp);
  if (redMoon)
    return {
      policy: redMoon.policy,
      lastWolfBlastPolicy: redMoon.lastWolfBlastPolicy,
      blastDay: redMoon.blastDay,
      exileDay: redMoon.exileDay,
      expirySettled: redMoon.expirySettled,
    };
}

/** JSON.parse 的方法查找先于 readJson；只解码原已持有审计字符串，不读取 live 容器。 */
export function readRedMoonShadow(readJson: () => string): Record<string, unknown> {
  return JSON.parse(readJson()) as Record<string, unknown>;
}

/** 在原状态校验后按原 spread 顺序生成候选；这是一次浅副本，不是第二份 live 库存。 */
export function copyRedMoonPayload(state: RedMoonReadState): RedMoonState {
  return { ...state };
}

/** 原完整私有容器保留其余字段；JSON.stringify 查找先于 spread，结果只供原同步审计比较。 */
export function encodeRedMoonShadow(original: Record<string, unknown>, next: RedMoonState): string {
  return JSON.stringify({ ...original, redMoon: next });
}

/** 调用方已完成原可写预检与 kind／夜政策；每次 next 字段读取仍紧邻对应写入，失败不补偿。 */
export function writeRedMoonTransition(state: RedMoonReadState, next: RedMoonState): void {
  (state as Pick<RedMoonState, "blastDay">).blastDay = next.blastDay;
  (state as Pick<RedMoonState, "exileDay">).exileDay = next.exileDay;
  (state as Pick<RedMoonState, "expirySettled">).expirySettled = next.expirySettled;
}

/**
 * 契约引用本族唯一实现；仅冻结声明，不冻结原运行状态。形状校验和失效读取沿用同一原校验，
 * 不新增 id／life／request 租约。checkpoint 是内部审计影子的原编码函数，未替代档案完整读器。
 */
export const RED_MOON_STATE_SLOT = Object.freeze({
  create: freshRedMoonState,
  schema: readRedMoonPayload,
  get: getRedMoonState,
  install: initializeRedMoonState,
  allowedWrites: Object.freeze({ transition: writeRedMoonTransition }),
  checkpoint: Object.freeze({
    read: readRedMoonShadow,
    prepare: copyRedMoonPayload,
    encode: encodeRedMoonShadow,
  }),
  invalidations: Object.freeze({ readCurrent: getRedMoonState }),
});

/**
 * 负责角色查验本夜提交和可选完成回执。输入为原 World、实际夜晚、石像鬼／查验完成选择；
 * 输出为每夜记账及已完成目标知识，不创建活跃能力或第二查验资源。状态族检查同 payload
 * 引用和政策；此 owner 仍在原顺序检查角色、生命版本、id、来源、激活、禁用及阶段当前性，
 * 替换或过期后不借合法 payload 恢复原回执。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import type { GargoyleReadState as GargoyleState } from "@ai-werewolf-arena/game-contract";

import type { RoleInspectionReadState } from "@ai-werewolf-arena/game-contract";

import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Role } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { findNightAbility, type NightAbilityReadView } from "../abilities";
import { getGargoyleState } from "../gargoyle/ports";

import { ROLE_INSPECTION_STATE_SLOT } from "./state-slot";

interface Completion {
  actorId: number;
  role: RoleComponent;
  privateState: RoleComponent["privateState"];
  state: GargoyleState;
  ability: NightAbilityReadView<"role_check">;
  abilityId: string;
  activation: NightAbilityReadView["activation"];
  inspection: RoleInspectionReadState;
  inspectionPolicy: RoleInspectionReadState["inspectionPolicy"];
  life: AliveComponent;
  version: number;
  isCurrent: () => boolean;
}
const nights = new WeakMap<World, { day: number; completed: Map<RoleComponent, Completion> }>();
const committed = new WeakMap<World, Set<number>>();
export function hasRoleInspectionNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
export function beginRoleInspectionNight(world: World, day: number): void {
  if (nights.get(world)?.day !== day) nights.set(world, { day, completed: new Map() });
}
export function recordRoleInspectionNightCommit(
  world: World,
  day: number,
  isCurrent: () => boolean,
): void {
  if (!isCurrent()) return;
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export function recordRoleInspectionCompletion(
  world: World,
  actorId: number,
  day: number,
  ability: NightAbilityReadView<"role_check">,
  isCurrent: () => boolean,
): void {
  if (!isCurrent()) return;
  recordRoleInspectionNightCommit(world, day, isCurrent);
  const role = world.getComponent(actorId, COMPONENT.Role),
    state = role && getGargoyleState(role),
    life = world.getComponent(actorId, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  if (
    roleInspectionPolicy(ability.state) !== "gargoyle" ||
    role?.role !== Role.Gargoyle ||
    !state ||
    !life?.alive ||
    version === undefined ||
    ability.source.kind !== "native" ||
    ability.source.role !== Role.Gargoyle
  )
    return;
  beginRoleInspectionNight(world, day);
  nights.get(world)!.completed.set(role, {
    actorId,
    role,
    privateState: role.privateState,
    state,
    ability,
    abilityId: ability.id,
    activation: ability.activation,
    inspection: ability.state,
    inspectionPolicy: ability.state.inspectionPolicy,
    life,
    version,
    isCurrent,
  });
}
export function completedGargoyleInspection(world: World, role: RoleComponent): boolean {
  const scope = nights.get(world)?.completed.get(role);
  if (
    !scope ||
    !scope.isCurrent() ||
    role.privateState !== scope.privateState ||
    getGargoyleState(role) !== scope.state ||
    role.role !== Role.Gargoyle ||
    scope.ability.id !== scope.abilityId ||
    scope.ability.activation !== scope.activation ||
    findNightAbility(role, "role_check", scope.abilityId) !== scope.ability ||
    scope.ability.source.kind !== "native" ||
    scope.ability.source.role !== Role.Gargoyle ||
    scope.ability.disabled ||
    ROLE_INSPECTION_STATE_SLOT.invalidations.payloadChanged(scope)
  )
    return false;
  return (
    world.getComponent(scope.actorId, COMPONENT.Role) === role &&
    world.getComponent(scope.actorId, COMPONENT.Alive) === scope.life &&
    scope.life.alive &&
    aliveLifeVersion(scope.life) === scope.version
  );
}

/**
 * 负责石像鬼、通灵师与魔镜少女的原角色查验阶段。
 * 输入为查询端口给出的活动实例与已验证目标；输出保留角色报告、次数和可选结束行为。
 * 共享资格查询先行，历史委托具体状态 owner，use metadata 委托实例 owner。
 * 各族失败、目标、学习、作用资格和事实发布顺序保持，不合并其不同规则。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import type { RoleInspectionPolicy } from "@ai-werewolf-arena/game-contract";

import { ROLE_INSPECTION_STATE_SLOT } from "./state-slot";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Phase, Role } from "../../../../core/domain/model";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { type NightAbilityReadView } from "../abilities";
import { recordNightAbilityUse } from "../abilities";
import { getGargoyleState } from "../gargoyle/ports";
import { resolveInspection } from "../inspection";
import {
  beginRoleInspectionNight,
  recordRoleInspectionCompletion,
  recordRoleInspectionNightCommit,
} from "./night_scope";
import { inspectionRequired } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { roleInspectionTargets } from "./rules";
import { captureNightAbilityScope } from "../ability_scope";
import { captureAwakenedMirrorScope } from "../awakened_hidden_wolf/mirror-scope-ports";

function finishOptionalInspection(
  ctx: NightStageContext,
  actorId: number,
  ability: NightAbilityReadView<"role_check">,
  day: number,
  reason: "passed" | "no_targets",
): void {
  recordNightAbilityUse(ability, day, false);
  ctx.events.push({
    timestamp: Date.now(),
    type: "role_inspection_skipped",
    payload: {
      actorId,
      ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
      day,
      reason,
    },
  });
  recordRoleInspectionNightCommit(ctx.world, day, ctx.isCurrent);
}
async function executeInspections(
  ctx: NightStageContext,
  policy: RoleInspectionPolicy,
): Promise<void> {
  const day = ctx.currentDay();
  if (policy === "gargoyle") beginRoleInspectionNight(ctx.world, day);
  for (const { actorId, ability } of ctx.nightActors.actors("role_check", day)) {
    if (!ctx.isCurrent()) return;
    if (roleInspectionPolicy(ability.state) !== policy) continue;
    const scope = captureNightAbilityScope(
      ctx.world,
      actorId,
      ability,
      day,
      () => ctx.isCurrent() && ctx.currentDay() === day,
    );
    if (!scope) continue;
    const role = scope.role,
      gargoyleState = getGargoyleState(role),
      state = ability.state,
      abilityId = ability.id;
    const source = ability.source,
      sourceKind = source.kind;
    const sourceOwner = source.kind === "native" ? source.role : source.actorId;
    const sourceAbilityId =
      source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined;
    // 只有原生觉醒隐狼来源捕获学习绑定；赠予／复制仍走原独立分支，不借公共入口扩大依赖或许可。
    const awakenedCurrent =
      source.kind === "native" && source.role === Role.AwakenedHiddenWolf
        ? captureAwakenedMirrorScope(
            ctx.world,
            actorId,
            ability,
            day,
            () => ctx.isCurrent() && ctx.currentDay() === day,
          )
        : () => true;
    const current = () =>
      awakenedCurrent?.() === true &&
      scope.isEligible() &&
      getGargoyleState(role) === gargoyleState &&
      roleInspectionPolicy(state) === policy &&
      ability.source === source &&
      source.kind === sourceKind &&
      (source.kind === "native" ? source.role : source.actorId) === sourceOwner &&
      (source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined) ===
        sourceAbilityId;
    const exhausted = () =>
      policy === "gargoyle"
        ? recordRoleInspectionCompletion(ctx.world, actorId, day, ability, ctx.isCurrent)
        : finishOptionalInspection(ctx, actorId, ability, day, "no_targets");
    if (!current()) continue;
    if (!roleInspectionTargets(ctx.world, actorId, state).length) {
      exhausted();
      continue;
    }
    let completed = false;
    for (let attempt = 0; attempt < 3; attempt++) {
      if (!current()) break;
      const targets = new Map(
        roleInspectionTargets(ctx.world, actorId, state).map((id) => {
          const target = ctx.world.getComponent(id, COMPONENT.Alive)!;
          return [id, { target, version: aliveLifeVersion(target) }] as const;
        }),
      );
      if (!targets.size) {
        exhausted();
        completed = true;
        break;
      }
      const request = ctx.makeRequest(actorId, ["inspect_role"], {
        stage:
          policy === "gargoyle"
            ? "role_inspection"
            : policy === "mirror"
              ? "mirror_girl"
              : "psychic",
        requiresAction: inspectionRequired(state),
        ability_id: abilityId,
        ...(sourceKind === "native" && sourceOwner === Role.AwakenedHiddenWolf
          ? { action_failure_policy: "error" as const, allow_fallback: false }
          : {}),
        ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
      });
      if (!current()) break;
      const action = await ctx.actionProvider.getAction(request);
      if (!current()) break;
      if (action === null && !inspectionRequired(state)) {
        finishOptionalInspection(ctx, actorId, ability, day, "passed");
        if (policy === "gargoyle")
          recordRoleInspectionCompletion(ctx.world, actorId, day, ability, ctx.isCurrent);
        completed = true;
        break;
      }
      if (action?.name !== "inspect_role") continue;
      const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
        phase: Phase.Night,
        day,
        abilityId,
      });
      if (!current() || !validated.ok || validated.sanitizedCall?.name !== "inspect_role") continue;
      const targetId = validated.sanitizedCall.args.target_id,
        target = targets.get(targetId);
      const targetCurrent = () =>
        !!target &&
        ctx.world.getComponent(targetId, COMPONENT.Alive) === target.target &&
        target.target.alive &&
        target.version !== undefined &&
        aliveLifeVersion(target.target) === target.version;
      if (!targetCurrent() || !roleInspectionTargets(ctx.world, actorId, state).includes(targetId))
        continue;
      const mapping = ctx.nativeNightTargets.mappedTarget(
        () => day,
        () => targetId,
      );
      const result = resolveInspection(
        ctx.world,
        mapping?.effectiveId ?? targetId,
        "role",
        ctx.roleCatalog,
      );
      if (
        !current() ||
        !targetCurrent() ||
        !result ||
        (mapping !== null && !mapping.isCurrent()) ||
        !roleInspectionTargets(ctx.world, actorId, state).includes(targetId)
      )
        continue;
      ROLE_INSPECTION_STATE_SLOT.allowedWrites.appendState(state, targetId, day, result);
      recordNightAbilityUse(ability, day, true);
      ctx.events.push({
        timestamp: Date.now(),
        type: "role_inspected",
        payload: {
          actorId,
          ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
          targetId,
          day,
          result: { ...result },
        },
      });
      if (policy === "gargoyle")
        recordRoleInspectionCompletion(ctx.world, actorId, day, ability, ctx.isCurrent);
      else recordRoleInspectionNightCommit(ctx.world, day, ctx.isCurrent);
      completed = true;
      break;
    }
    if (!completed && current()) {
      if (roleInspectionTargets(ctx.world, actorId, state).length)
        throw new Error(
          policy === "gargoyle"
            ? "role_inspection_required_action_missing"
            : "role_inspection_valid_action_missing",
        );
      exhausted();
    }
  }
}
export const ROLE_INSPECTION_STAGE: NightStageHandler = {
  id: "role_inspection",
  priority: 180,
  execute: (ctx) => executeInspections(ctx, "gargoyle"),
};
export const PSYCHIC_INSPECTION_STAGE: NightStageHandler = {
  id: "psychic_inspection",
  priority: 600,
  execute: (ctx) => executeInspections(ctx, "psychic"),
};

export const MIRROR_INSPECTION_STAGE: NightStageHandler = {
  id: "mirror_inspection",
  priority: 600,
  execute: (ctx) => executeInspections(ctx, "mirror"),
};

/**
 * 负责身份查验的原配置 schema 与政策文案。输入为实例只读政策字段、板子配置和语言；
 * 输出为已解析配置及翻译标签，默认解释、重复／必选纯查询归公共契约。
 * 配置与文案不写 live payload、不安装库存或授予行动权限，实际提交仍由机制复验。
 */
import { inspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import type { RoleInspectionReadState } from "@ai-werewolf-arena/game-contract";

import { z } from "zod";
import {
  INSPECTION_POLICIES,
  type BoardConfig,
  type InspectionPolicy,
} from "../../../../core/domain/board";

import type { RoleProfile } from "../contracts";
import { text, type Locale } from "@ai-werewolf-arena/game-text";

export function renderInspectionPolicy(
  state: Pick<RoleInspectionReadState, "policy" | "inspectionPolicy">,
  locale: Locale,
): string {
  return text(
    locale,
    inspectionPolicy(state) === "awa_repeat_optional_v1"
      ? "role.inspection.repeat_optional"
      : inspectionPolicy(state) === "awa_unique_required_v1"
        ? "role.inspection.unique_required"
        : "role.inspection.unique_optional",
  );
}
export function inspectionConfiguration(
  key: "gargoyle" | "psychic" | "mirrorGirl",
  defaultValue: InspectionPolicy,
): NonNullable<RoleProfile["configuration"]> {
  const schema = z.strictObject({
    inspectionPolicy: z.enum(INSPECTION_POLICIES).default(defaultValue),
  });
  return {
    schema,
    defaults: schema.parse({}),
    apply: (config, value) => ({ ...config, [key]: schema.parse(value) }),
    serialize: (config: BoardConfig) => schema.parse(config[key] ?? {}),
  };
}

/**
 * 负责角色查验的目标查询、工具 schema 与规则校验。输入为原只读查验历史、World 成员及待提交动作，输出合法 ID 或原拒绝代码。
 * 此业务叶不修改历史、消费库存或提交查验效果，当前许可仍由具体机制核对。
 */
import type { RoleInspectionReadState } from "@ai-werewolf-arena/game-contract";

import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Phase, type EntityId } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import type { ToolRule } from "../../validation/contracts";
import { isAliveTarget } from "../../validation/contracts";
import type { RoleProfile } from "../contracts";
import { activeNightAbility } from "../abilities";
import { inspectionRepeats } from "@ai-werewolf-arena/game-contract/role-inspection-policy";

export function roleInspectionTargets(
  world: World,
  actorId: EntityId,
  state: RoleInspectionReadState,
): EntityId[] {
  const repeat = inspectionRepeats(state);
  return world
    .getAliveEntityIds()
    .filter(
      (id) => id !== actorId && (repeat || !state.history.some((report) => report.targetId === id)),
    );
}
export const ROLE_INSPECTION_TOOL: NonNullable<RoleProfile["toolSpecs"]>[number] = {
  name: "inspect_role",
  parameters: {
    type: "object",
    properties: { target_id: { type: "number" } },
    required: ["target_id"],
    additionalProperties: false,
  },
  argHint: 'inspect_role args: {"target_id":number}',
  userPromptHintKey: "action.inspect_role.hint",
};
export const validateRoleInspection: ToolRule = ({
  world,
  actorId,
  role,
  day,
  phase,
  abilityId,
  toolCall,
}) => {
  const ability = activeNightAbility(role, "role_check", day ?? 1, abilityId);
  if (!ability) return { code: RuleError.RoleInspectUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name !== "inspect_role") return { code: RuleError.ToolMismatch };
  if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
    return { code: RuleError.RoleInspectTarget };
  if (
    !inspectionRepeats(ability.state) &&
    ability.state.history.some((report) => report.targetId === toolCall.args.target_id)
  )
    return { code: RuleError.RoleInspectRepeat };
  return null;
};

/**
 * 负责角色查验能力族的原生状态创建、既有政策校验、同实例访问及两条历史写入前缀。
 * 输入为原角色／能力引用与已验证报告；输出保留原 JSON 复制、policy 默认解释、原状态
 * 引用与局部 payload 失效规则。查验目标、次数、生命、来源、阶段与租约仍归原 owner。
 * 本族覆盖五种原生政策和觉醒隐狼晚学习，赠予／复制／转移仍使用共享实例库存；
 * 不复制第二仓库、不严格化旧 payload、退款或推导新权限。
 */
import type {
  RoleInspectionState,
  RoleInspectionReadState,
} from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "@ai-werewolf-arena/game-contract";
import type { InspectionResult } from "@ai-werewolf-arena/game-contract";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { commitPreparedNativeAbility } from "../abilities";

export function setRoleInspectionState(
  role: RoleComponent,
  state: RoleInspectionState,
): RoleInspectionReadState {
  return commitPreparedNativeAbility(role, "role_check", ROLE_INSPECTION_STATE_SLOT.create(state));
}

export function getRoleInspectionState(
  role: RoleComponent,
  abilityId?: string,
): RoleInspectionReadState | undefined {
  return findNightAbility(role, "role_check", abilityId)?.state;
}

/** 调用方保留全部预检，以及随后次数、效果和事件发布；此处仅写原 payload 历史前缀。 */
export function recordRoleInspection(
  state: RoleInspectionReadState,
  targetId: EntityId,
  day: number,
  result: Extract<InspectionResult, { kind: "role" }>,
): void {
  (state as RoleInspectionState).lastTarget = targetId;
  (state as RoleInspectionState).lastDay = day;
  (state as RoleInspectionState).history.push({ day, targetId, result: { ...result } });
}

/** 纯白／狼巫仍逐次读取 ability.state 三次，并只追加一次结果历史。 */
export function recordAbilityRoleInspection(
  ability: import("../abilities").NightAbilityReadView<"role_check">,
  targetId: EntityId,
  day: number,
  result: Extract<InspectionResult, { kind: "role" }>,
): void {
  (ability.state as RoleInspectionState).lastTarget = targetId;
  (ability.state as RoleInspectionState).lastDay = day;
  (ability.state as RoleInspectionState).history.push({ day, targetId, result: { ...result } });
}

/** 原生安装先按原 JSON 规则复制，再校验原 policy；不增加 history／目标形状拒绝政策。 */
function createRoleInspectionState(state: RoleInspectionState): RoleInspectionState {
  const ownedState = copyAbilityData(state);
  roleInspectionPolicy(ownedState);
  return ownedState;
}

/** 保持 JSON.stringify 方法查找先于两次 ability.state 读取，不提前捕获状态或政策字段。 */
function encodeRoleInspectionPolicy(ability: NightAbilityReadView<"role_check">): string {
  return JSON.stringify([ability.state.policy, ability.state.inspectionPolicy]);
}

/** 原完成回执仅捕获 payload 关联；生命、id、来源、激活、当前阶段和禁用仍归原夜间 owner。 */
interface CapturedInspectionPayload {
  readonly ability: NightAbilityReadView<"role_check">;
  readonly inspection: RoleInspectionReadState;
  readonly inspectionPolicy: RoleInspectionReadState["inspectionPolicy"];
}
function capturedInspectionPayloadChanged(scope: CapturedInspectionPayload): boolean {
  return (
    scope.ability.state !== scope.inspection ||
    scope.inspection.inspectionPolicy !== scope.inspectionPolicy ||
    roleInspectionPolicy(scope.inspection) !== "gargoyle"
  );
}

/**
 * 本族唯一状态槽贡献。create 使用原复制与政策校验；schema 只引用原既有政策验证器，
 * 不冒称已验证整个 history 或添加严格 schema。原 native／赠予／转移能力仍存在原 abilities。
 * 两条 append 入口分别保留捕获状态与三次实例 state 读取的旧轨迹，不合并次数提交。
 * checkpoint 仅编码原运行政策身份；归档仍由既有 checkpoint 完整克隆 privateState，
 * 本声明不创建第二 JSON 仓库、解码器或新 lease，不把 payload 当前性当作完整行动授权。
 */
export const ROLE_INSPECTION_STATE_SLOT = Object.freeze({
  create: createRoleInspectionState,
  schema: roleInspectionPolicy,
  install: setRoleInspectionState,
  get: getRoleInspectionState,
  allowedWrites: Object.freeze({
    appendState: recordRoleInspection,
    appendAbility: recordAbilityRoleInspection,
  }),
  checkpoint: Object.freeze({ policyIdentity: encodeRoleInspectionPolicy }),
  invalidations: Object.freeze({ payloadChanged: capturedInspectionPayloadChanged }),
});

/**
 * 负责本族加成效果运行记录的唯一数组，按原 NightStageState 对象身份保存。
 * 输入是夜间状态、原种类／领取回执／可选印记；输出是同一记录与数组引用，不复制、冻结或序列化运行句柄。
 * 记录字段保持原可写性，receipt／marks 保留原引用与各自写权；具体回执的冻结仍归 frame，只读数组视图不额外深冻结。
 * 追加口仅取得数组，不提交回执或授予库存／行动权限。
 * 首次追加才建立数组；换状态对象不会继续旧夜记录，不读取或采纳旧 modifierBonusEffects 属性及其 getter。
 * 付款、原生命与当前性重验仍归本族阶段／frame；记录存在不代表已付、有效或已经造成死亡。
 */
import type { StatusMarksComponent } from "../../../../core/domain/components/status_marks";
import type { NightStageState } from "../../stages/night/contracts";
import type { ModifierBonusKind, ModifierBonusReceipt } from "./night_frame";

/** 三个原字段保持原类型与可变性；receipt／marks 是运行引用，不能移入玩家 DTO。 */
export interface ScholarMentorBonusEffectRecord {
  kind: ModifierBonusKind;
  receipt: ModifierBonusReceipt;
  marks?: StatusMarksComponent;
}

// 同一实际状态只有这一份数组；不在通用 NightStageState 字段上挂镜像或第二份索引。
const recordsByState = new WeakMap<NightStageState, ScholarMentorBonusEffectRecord[]>();

/** 未追加时返回原语义的临时空视图；查询不为状态预建记录，也不调用回执。 */
export function readScholarMentorBonusEffectRecords(
  state: NightStageState,
): readonly ScholarMentorBonusEffectRecord[] {
  return recordsByState.get(state) ?? [];
}

/** 原追加点先取得数组和 push callee，再创建效果条目；不提前捕获状态、回执或 marks。 */
export function scholarMentorBonusEffectRecordsForAppend(
  state: NightStageState,
): ScholarMentorBonusEffectRecord[] {
  let records = recordsByState.get(state);
  if (!records) {
    records = [];
    recordsByState.set(state, records);
  }
  return records;
}

/**
 * 负责白昼学者／寂夜导师已记录加成效果的完整复验，供本族加成阶段及夜间规则检查点共用。
 * 输入为原阶段上下文和同一状态身份关联的运行记录；输出为通过或原首个失效错误，不付款或发布事实。
 * 先复验名单，再读记录；每条先取 target、执行 effectCurrent，之后按原短路核原生命／版本与 marks 引用。
 * 记录存在不代表效果仍有效；读取和回调失败原样传播，已付资源及记录不由这里关闭、删除或退款。
 * 原 receipt／生命／印记是运行句柄，数据副本不能替代；本模块不推进阶段或重新打开请求窗口。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { NightStageContext } from "../../stages/night/contracts";
import { assertScholarMentorRosterCurrent } from "./night_frame";
import { readScholarMentorBonusEffectRecords } from "./bonus-effect-records";

/** 只检查原已付效果的运行有效性；不调用 receipt.commit，也不把撤权后的同形目标重新捕获为新来源。 */
export function assertScholarMentorBonusEffects(ctx: NightStageContext): void {
  assertScholarMentorRosterCurrent(ctx.world);
  for (const effect of readScholarMentorBonusEffectRecords(ctx.state)) {
    const target = effect.receipt.target;
    if (
      !effect.receipt.effectCurrent() ||
      (target &&
        (ctx.world.getComponent(target.id, COMPONENT.Alive) !== target.life ||
          aliveLifeVersion(target.life) !== target.version)) ||
      (effect.marks &&
        target &&
        ctx.world.getComponent(target.id, COMPONENT.StatusMarks) !== effect.marks)
    )
      throw new Error("scholar_mentor_bonus_effect_stale");
  }
}

/**
 * 负责学者／导师管线清理交接及经理终止端口。输入为惰性原 World 与经理实际 World／day；
 * 输出保留原 grant 解析错误及 frame abort 写。开夜仍在优先级 50，配置清理即使未进该阶段也会运行，
 * 只有原晚 transfer 才抑制管线 abort。正常关闭后经理仍读 abort 参数，由 frame.closed 防止污染后夜。
 * 这里不授奖励、不付款、启动阶段或录制 I/O。
 */
import type { World } from "../../../../core/domain/world";
import { closeScholarMentorNight, abortScholarMentorNight } from "./night_frame";

export interface ScholarMentorNightRuntime {
  readonly world: World;
}

export const scholarMentorNightTerminal = Object.freeze({
  closeNormally(world: World, day: number): void {
    closeScholarMentorNight(world, day);
  },
  abort(world: World): void {
    abortScholarMentorNight(world);
  },
});

export class ScholarMentorNightUnit {
  /** 经理接收同一清理实例；终止函数仍使用调用时新求值的 World／day 参数。 */
  readonly closeNormally = scholarMentorNightTerminal.closeNormally;
  readonly abort = scholarMentorNightTerminal.abort;

  private transferred = false;
  constructor(private readonly runtime: ScholarMentorNightRuntime) {}

  transferToManager(configured: boolean): void {
    this.transferred = configured;
  }

  abortIfOwned(): void {
    if (!this.transferred) abortScholarMentorNight(this.runtime.world);
  }
}

/**
 * 负责白昼学者／寂夜导师的原 roster、生命／原生能力权威、夜选择许可和已结算加成。
 * 输入为原 World／day、选择与原生目标证据；输出保原 pending／selection、加成回执及有来源冲突死亡。
 * 状态 raw／库存／历史／JSON 绑定及实际数据写归本族 state-slot，有限板免疫与碰撞规则归 rules。
 * 不变量：槽提交成功才删 pending／追加 selection；普通已提交交换可跨一次正常死亡，不可跨复活或换生命。
 * 关闭仍要求原加成全处理，abort 只改原夜窗口；不为替换原体补授库存或复制运行回执。
 * 当前 Camp 在原字段点由实际 World 查询；保原值比较，不把同值组件替换改成新的引用撤权。
 */
import type {
  ModifierMode,
  CommittedModifier,
  ModifierResolution,
  ModifierReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { COMPONENT, Camp, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import {
  readModifierState,
  selectModifier,
  modifierOwnData as ownData,
  ScholarMentorStateSlot,
} from "./state-slot";
import { resolveModifiers } from "./rules";
// 原体／身份／生命与原生能力查询分开捕获；库存槽内容相同不能补回另一 Role 或生命的授权。
interface OriginalPlayer {
  abilityAuthority: () => boolean;
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: Camp | undefined;
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
export type ModifierBonusKind = "check" | "guard" | "poison" | "kill";
// 本夜额外机会不扣施法者槽的另一份库存；used／targetId 在原创建点或复验后的回执 commit 才写。
interface Grant {
  actorId: number;
  kind: ModifierBonusKind;
  used: boolean;
  targetId: number | null;
}
// pending 保未提交选择，selections 仅在槽写与 JSON 更新成功后追加；两者与 bonus grant 生命周期仍归 frame。
interface ModifierNight {
  day: number;
  closed: boolean;
  aborted: boolean;
  living: ReadonlySet<number>;
  pending: Set<number>;
  selections: CommittedModifier[];
  resolution: ModifierResolution | null;
  grants: Map<number, Grant>;
  nativeTargets: Map<string, number | null>;
}
interface Board {
  players: ReadonlyMap<number, OriginalPlayer>;
  casters: ReadonlyMap<number, ScholarMentorStateSlot>;
  night: ModifierNight | null;
}
const boards = new WeakMap<World, Board>();


const missingAbilityField = Symbol("missing_ability_field");
function boundAbilityData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value))
    throw new Error("scholar_mentor_original_abilities_invalid");
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  if (!descriptor) {
    if (key in value) throw new Error("scholar_mentor_original_abilities_invalid");
    return missingAbilityField;
  }
  if (!("value" in descriptor)) throw new Error("scholar_mentor_original_abilities_invalid");
  return descriptor.value;
}
function bindAbilities(role: RoleComponent): () => boolean {
  const container = boundAbilityData(role.privateState, "abilities");
  const prototype = Object.getPrototypeOf(role.privateState);
  if (container === missingAbilityField || container === undefined)
    return () =>
      Object.getPrototypeOf(role.privateState) === prototype &&
      boundAbilityData(role.privateState, "abilities") === container;
  if (
    !container ||
    typeof container !== "object" ||
    types.isProxy(container) ||
    Array.isArray(container)
  )
    throw new Error("scholar_mentor_original_abilities_invalid");
  const names = Reflect.ownKeys(container);
  const bindings = names.map((key) => {
    const ability = ownData(container, key);
    if (!ability || typeof ability !== "object" || types.isProxy(ability))
      throw new Error("scholar_mentor_original_abilities_invalid");
    const fields = [
      "id",
      "kind",
      "activation",
      "source",
      "state",
      "startsOnDay",
      "expiresAfterDay",
      "maxUses",
      "disabled",
      "deathExpired",
      "sourceDisclosed",
    ] as const;
    const values = fields.map((k) => boundAbilityData(ability, k)),
      source = ownData(ability, "source"),
      state = ownData(ability, "state");
    const sourceFields = ["kind", "role", "actorId", "abilityId"] as const,
      sourceValues = sourceFields.map((k) => boundAbilityData(source, k));
    const policyFields = [
        "targetPolicy",
        "actionPolicy",
        "selfHealRule",
        "knifeVisibility",
        "potionPolicy",
        "repeatPolicy",
      ] as const,
      policies = policyFields.map((k) => boundAbilityData(state, k));
    return () =>
      ownData(container, key) === ability &&
      fields.every((k, i) => boundAbilityData(ability, k) === values[i]) &&
      sourceFields.every((k, i) => boundAbilityData(source, k) === sourceValues[i]) &&
      policyFields.every((k, i) => boundAbilityData(state, k) === policies[i]);
  });
  return () =>
    Object.getPrototypeOf(role.privateState) === prototype &&
    boundAbilityData(role.privateState, "abilities") === container &&
    Reflect.ownKeys(container).length === names.length &&
    bindings.every((fn) => fn());
}

function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    !p.abilityAuthority() ||
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(world.getComponent(p.id, COMPONENT.Camp), "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // 已提交交换可跨一次普通死亡；复活或换生命仍撤权。
  return p.life.alive ? version === p.version : version === p.version + 1;
}

function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("scholar_mentor_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("scholar_mentor_original_state_revoked");
  for (const [id, c] of b.casters) {
    if (
      !c.matches(ownData(b.players.get(id)!.privateState, "scholarMentor"))
    )
      throw new Error("scholar_mentor_original_state_revoked");
  }
  return b;
}
export function installScholarMentorBoard(world: World): void {
  if (boards.has(world)) throw new Error("scholar_mentor_board_already_installed");
  const players = new Map<number, OriginalPlayer>(),
    seats = new Set<number>();
  const casters = new Map<number, ScholarMentorStateSlot>();
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (
      !role ||
      !life ||
      types.isProxy(life) ||
      version === undefined ||
      (world.getComponent(id, COMPONENT.Camp)?.camp !== Camp.Wolf && world.getComponent(id, COMPONENT.Camp)?.camp !== Camp.Good)
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(world.getComponent(id, COMPONENT.Camp), "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      abilityAuthority: bindAbilities(role),
      id,
      role,
      roleName: role.role,
      camp: world.getComponent(id, COMPONENT.Camp)?.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });

    if (String(role.role) === "day_scholar" || String(role.role) === "night_mentor") {
      const raw = ownData(role.privateState, "scholarMentor");
      const state = readModifierState(raw);
      if (!state || state.caster !== String(role.role) || state.history.length !== 0)
        throw new Error("scholar_mentor_original_roster_invalid");
      const original = raw as ModifierReadState;
      casters.set(id, new ScholarMentorStateSlot(original));
    }
  }
  resolveModifiers(
    [...players.values()].map((p) => ({
      id: p.id,
      role: String(p.roleName),
      camp: p.camp === Camp.Wolf ? "wolf" : "good",
      alive: true,
    })),
    [],
  );
  if (casters.size !== 2) throw new Error("scholar_mentor_original_roster_invalid");
  boards.set(world, { players, casters, night: null });
}
export function isScholarMentorBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}
export function assertScholarMentorRosterCurrent(world: World): void {
  if (boards.has(world)) requireBoard(world);
}
function night(world: World, day: number): { b: Board; n: ModifierNight } {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.aborted)
    throw new Error("scholar_mentor_night_unavailable");
  return { b, n };
}
function resolved(
  world: World,
  day: number,
): { b: Board; n: ModifierNight; r: ModifierResolution } {
  const { b, n } = night(world, day);
  if (!n.resolution) throw new Error("scholar_mentor_night_unsettled");
  return { b, n, r: n.resolution };
}
export function beginScholarMentorNight(world: World, day: number): number[] {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day < 1 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || b.night.aborted || day !== b.night.day + 1))
  )
    throw new Error("scholar_mentor_night_invalid");
  const living = new Set([...b.players.values()].filter((p) => p.life.alive).map((p) => p.id));
  const pending = new Set(
    [...b.casters]
      .filter(
        ([id, c]) =>
          day >= 2 && living.has(id) && c.state.remaining.enhance + c.state.remaining.weaken > 0,
      )
      .map(([id]) => id),
  );
  b.night = {
    day,
    closed: false,
    aborted: false,
    living,
    pending,
    selections: [],
    resolution: null,
    grants: new Map(),
    nativeTargets: new Map(),
  };
  return [...pending];
}
export function scholarMentorChoicePending(world: World, day: number, actorId: number): boolean {
  const { b, n } = night(world, day);
  return n.pending.has(actorId) && b.players.get(actorId)!.life.alive;
}
export function scholarMentorChoiceTargets(world: World, day: number, actorId: number): number[] {
  const { b, n } = night(world, day);
  return n.pending.has(actorId) ? [...n.living].filter((id) => b.players.get(id)!.life.alive) : [];
}
export function commitScholarMentorChoice(
  world: World,
  day: number,
  actorId: number,
  mode: ModifierMode | null,
  targetId: number | null,
): void {
  const { b, n } = night(world, day),
    c = b.casters.get(actorId);
  if (!c || !n.pending.has(actorId) || !b.players.get(actorId)!.life.alive || n.resolution)
    throw new Error("scholar_mentor_choice_scope_invalid");
  const next = selectModifier(
    c.state,
    day,
    mode,
    targetId,
    scholarMentorChoiceTargets(world, day, actorId),
  );
  c.commit(next);
  n.pending.delete(actorId);
  if (mode !== null)
    n.selections.push({ actorId, caster: c.state.caster, mode, targetId: targetId! });
}
export function settleScholarMentorChoices(world: World, day: number): ModifierResolution {
  const { b, n } = night(world, day);
  if (n.pending.size || n.resolution) throw new Error("scholar_mentor_choices_unsettled");
  const r = resolveModifiers(
    [...b.players.values()].map((p) => ({
      id: p.id,
      role: String(p.roleName),
      camp: p.camp === Camp.Wolf ? "wolf" : "good",
      alive: n.living.has(p.id),
    })),
    n.selections,
  );
  n.resolution = r;
  for (const effect of r.goodEffects)
    if (effect.mode === "enhance")
      n.grants.set(effect.targetId, {
        actorId: effect.targetId,
        kind: effect.role === "seer" ? "check" : effect.role === "witch" ? "poison" : "guard",
        used: false,
        targetId: null,
      });
  if (r.bonusKnifeActorId !== null)
    n.grants.set(r.bonusKnifeActorId, {
      actorId: r.bonusKnifeActorId,
      kind: "kill",
      used: false,
      targetId: null,
    });
  return structuredClone(r);
}
export function scholarMentorBlocks(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
): boolean {
  if (!boards.has(world)) return false;
  const { r } = resolved(world, day);
  if (kind === "kill") return r.blockWolfKnife;
  return r.goodEffects.some(
    (e) =>
      e.targetId === actorId &&
      e.mode === "weaken" &&
      ((e.role === "seer" && kind === "check") ||
        (e.role === "guard" && kind === "guard") ||
        (e.role === "witch" && kind === "poison")),
  );
}
export function scholarMentorKnifeEligible(world: World, day: number, actorId: number): boolean {
  const { b, n } = night(world, day),
    p = b.players.get(actorId);
  if (!p || !n.living.has(actorId) || !p.life.alive || p.camp !== Camp.Wolf) return false;
  if (String(p.roleName) === "wolf") return true;
  return (
    String(p.roleName) === "night_mentor" &&
    [...n.living].filter((id) => b.players.get(id)!.camp === Camp.Wolf).length === 1
  );
}
function nativeKey(actorId: number, kind: ModifierBonusKind): string {
  return kind === "kill" ? "pack:kill" : actorId + ":" + kind;
}
export function recordScholarMentorNativeTarget(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
  targetId: number | null,
): void {
  const { b, n } = resolved(world, day),
    key = nativeKey(actorId, kind),
    p = b.players.get(actorId);
  if (
    !p ||
    !n.living.has(actorId) ||
    !p.life.alive ||
    n.nativeTargets.has(key) ||
    (targetId !== null && (!n.living.has(targetId) || !b.players.get(targetId)?.life.alive))
  )
    throw new Error("scholar_mentor_native_target_invalid");
  const expected =
    kind === "check" ? "seer" : kind === "guard" ? "guard" : kind === "poison" ? "witch" : null;
  if (expected ? String(p.roleName) !== expected : !scholarMentorKnifeEligible(world, day, actorId))
    throw new Error("scholar_mentor_native_actor_invalid");
  n.nativeTargets.set(key, targetId);
}
export function scholarMentorBonusActors(
  world: World,
  day: number,
  kind: ModifierBonusKind,
): number[] {
  const { n } = resolved(world, day);
  return [...n.grants.values()].filter((g) => g.kind === kind && !g.used).map((g) => g.actorId);
}
export function scholarMentorBonusTargets(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
): number[] {
  const { b, n } = resolved(world, day),
    g = n.grants.get(actorId),
    key = nativeKey(actorId, kind);
  if (
    !g ||
    g.kind !== kind ||
    g.used ||
    !b.players.get(actorId)!.life.alive ||
    !n.nativeTargets.has(key)
  )
    return [];
  const native = n.nativeTargets.get(key);
  return [...n.living].filter((id) => id !== native && b.players.get(id)!.life.alive);
}
export interface ModifierBonusReceipt {
  readonly target: NightLifeScope | null;
  readonly source: NightLifeScope;
  readonly isCurrent: () => boolean;
  readonly effectCurrent: () => boolean;
  readonly commit: () => void;
}
export function captureScholarMentorBonus(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
  targetId: number | null,
): ModifierBonusReceipt {
  const { b, n } = resolved(world, day),
    g = n.grants.get(actorId),
    p = b.players.get(actorId),
    key = nativeKey(actorId, kind);
  if (
    !g ||
    g.kind !== kind ||
