export const SCHOLAR_MENTOR_POLICY = "awa_scholar_mentor_twelve_v1" as const;
function object(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !types.isProxy(value) && !Array.isArray(value);
}
function keys(value: Record<string, unknown>, allowed: string[]): boolean {
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === allowed.length &&
    allowed.every((key) => descriptors[key] !== undefined && "value" in descriptors[key]!)
  );
}
function arrayItems(value: unknown): unknown[] | undefined {
  if (!Array.isArray(value) || types.isProxy(value)) return undefined;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  const length: unknown = Object.getOwnPropertyDescriptor(value, "length")?.value;
  if (
    typeof length !== "number" ||
    !Number.isSafeInteger(length) ||
    length < 0 ||
    Reflect.ownKeys(descriptors).length !== length + 1
  )
    return undefined;
  const out: unknown[] = [];
  for (let index = 0; index < length; index++) {
    const descriptor = descriptors[String(index)];
    if (!descriptor || !("value" in descriptor)) return undefined;
    out.push(descriptor.value);
  }
  return out;
}
export function createModifierState(caster: ModifierCaster): ModifierState {
  if (caster !== "day_scholar" && caster !== "night_mentor")
    throw new Error("modifier_caster_invalid");
  return {
    policy: SCHOLAR_MENTOR_POLICY,
    caster,
    remaining: { enhance: 1, weaken: 1 },
    history: [],
  };
}
export function readModifierState(value: unknown): ModifierState | undefined {
  if (
    !object(value) ||
    !keys(value, ["policy", "caster", "remaining", "history"]) ||
    value.policy !== SCHOLAR_MENTOR_POLICY ||
    (value.caster !== "day_scholar" && value.caster !== "night_mentor") ||
    !object(value.remaining) ||
    !keys(value.remaining, ["enhance", "weaken"]) ||
    !Array.isArray(value.history)
  )
    return undefined;
  const items = arrayItems(value.history);
  if (!items) return undefined;
  // 由逐条历史重算两种一次库存；只接受原严格数据形状，返回可写脱离副本。
  let last = 1,
    enhance = 1,
    weaken = 1;
  const history: ModifierChoice[] = [];
  for (const item of items) {
    if (
      !object(item) ||
      !keys(item, ["day", "mode", "targetId"]) ||
      typeof item.day !== "number" ||
      !Number.isSafeInteger(item.day) ||
      item.day >= Number.MAX_SAFE_INTEGER ||
      item.day <= last ||
      (item.mode !== null && item.mode !== "enhance" && item.mode !== "weaken")
    )
      return undefined;
    if (
      item.mode === null
        ? item.targetId !== null
        : typeof item.targetId !== "number" ||
          !Number.isSafeInteger(item.targetId) ||
          item.targetId < 1
    )
      return undefined;
    if (item.mode === "enhance") enhance--;
    if (item.mode === "weaken") weaken--;
    if (enhance < 0 || weaken < 0) return undefined;
    last = item.day;
    history.push({ day: item.day, mode: item.mode, targetId: item.targetId as number | null });
  }
  if (value.remaining.enhance !== enhance || value.remaining.weaken !== weaken) return undefined;
  return {
    policy: SCHOLAR_MENTOR_POLICY,
    caster: value.caster,
    remaining: { enhance, weaken },
    history,
  };
}
/** 脱离选择只校验与扣减返回副本；不向施法者披露实际效果／碰撞，也不提交 live 库存。 */
export function selectModifier(
  state: ModifierReadState,
  day: number,
  mode: ModifierMode | null,
  targetId: number | null,
  livingIds: readonly number[],
): ModifierState {
  const next = readModifierState(state);
  if (
    !next ||
    !Number.isSafeInteger(day) ||
    day >= Number.MAX_SAFE_INTEGER ||
    day < 2 ||
    day <= (next.history.at(-1)?.day ?? 1)
  )
    throw new Error("modifier_choice_day_invalid");
  if (mode !== null && mode !== "enhance" && mode !== "weaken")
    throw new Error("modifier_mode_invalid");
  if (
    mode === null
      ? targetId !== null
      : targetId === null ||
        !Number.isSafeInteger(targetId) ||
        targetId < 1 ||
        !livingIds.includes(targetId)
  )
    throw new Error("modifier_target_invalid");
  if (mode !== null) {
    if (next.remaining[mode] !== 1) throw new Error("modifier_charge_spent");
    next.remaining[mode] = 0;
  }
  next.history.push({ day, mode, targetId });
  return next;
}

export function modifierOwnData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}

export function modifierStateIdentity(raw: unknown): string {
  const value = readModifierState(raw);
  if (!value) throw new Error("scholar_mentor_original_state_revoked");
  return JSON.stringify(value);
}
/** 原 LHS 在 caster 和工厂之前读取；parse 配置仍在调用方先完成，不提前缓存 privateState。 */
export function initializeScholarMentorState(
  privateState: () => RoleComponent["privateState"],
  caster: () => ModifierCaster,
): void {
  (privateState() as { scholarMentor?: ModifierState }).scholarMentor = createModifierState(caster());
}

/** raw、资源与历史的原引用不是脱离副本；expected 仅保存原 JSON 内容证据，不代表授权或 JSON schema。 */
export class ScholarMentorStateSlot {
  state: ModifierReadState;
  remaining: ModifierReadState["remaining"];
  history: ModifierReadState["history"];
  expected: string;

  constructor(state: ModifierReadState) {
    this.state = state;
    this.remaining = state.remaining;
    this.history = state.history;
    this.expected = modifierStateIdentity(state);
  }

  /** frame 先在原时点取 raw；逐层引用失败就短路，之后才读取／复制原 schema 并比 JSON。 */
  matches(raw: unknown): boolean {
    return (
      raw === this.state &&
      modifierOwnData(this.state, "remaining") === this.remaining &&
      modifierOwnData(this.state, "history") === this.history &&
      modifierStateIdentity(this.state) === this.expected
    );
  }

  /** next 已完成原选择验证；先两项库存赋值，再查 defineProperty、历史两读／length／最后条目，再更新 expected。
   * 任一步抛错保已写前缀，不补回库存；frame 在此成功之后才删除 pending 并追加 selection。
   */
  commit(next: ModifierState): void {
    (this.remaining as Pick<ModifierState["remaining"], "enhance">).enhance = next.remaining.enhance;
    (this.remaining as Pick<ModifierState["remaining"], "weaken">).weaken = next.remaining.weaken;
    Object.defineProperty(this.history, String(this.history.length), {
      value: next.history.at(-1)!,
      writable: true,
      enumerable: true,
      configurable: true,
    });
    this.expected = modifierStateIdentity(this.state);
  }
}

/** 只检查原角色／阵营和数据形状，返回原 raw 只读视图；不读取 board 或授予 modify_skill 权限。 */
// 先保原 role 读取，再无条件取得当前 Camp；即使身份随后拒绝，也不提前省略原 camp 点。
export function scholarMentorStateForRole(
  role: RoleComponent | undefined,
  currentCamp: CurrentCampSource,
): ModifierReadState | undefined {
  const name = modifierOwnData(role, "role"),
    camp = modifierOwnData(currentCamp(), "camp");
  if (
    (name !== "day_scholar" && name !== "night_mentor") ||
    camp !== (name === "day_scholar" ? Camp.Good : Camp.Wolf)
  )
    return undefined;
  const raw = modifierOwnData(modifierOwnData(role, "privateState"), "scholarMentor"),
    value = readModifierState(raw);
  return value?.caster === name ? (raw as ModifierReadState) : undefined;
}

/**
 * 负责普通预言家对捕获能力及目标权威的查验请求。
 * 输入为原夜上下文和校验行动；输出保留查验结果、状态、use 和事件效果。
 * 资格枚举走只读查询，具体 Seer 状态与公共 use 命令在原 commit 位置执行；映射与咒狐顺序不变。
 * Demon 封存原生控制器保持独立，不额外验证租约、退款或将原体信息写入玩家知识。
 */
import { SEER_STATE_SLOT } from "./ports";
/** 文件说明：预言家夜间查验阶段处理。 */
import { seerTargetAllowed } from "./ports";
import { COMPONENT } from "../../../../core/domain/components/names";
import { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { NightStageHandler } from "../../stages/night/contracts";
import { getSeerState } from "./ports";
import { resolveInspection } from "../inspection";
import { activeNightAbility } from "../abilities";
import { recordNightAbilityUse } from "../abilities";
import { captureNightAbilityScope } from "../ability_scope";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import { recordOwnNightAction, luckyTargetAllowed } from "../night_action_history";

import { captureInspectionIdentity, commitFoxInspection } from "../cursed_fox/inspection-ports";

const seerCheckStage: NightStageHandler = {
  id: "seer_check",
  priority: 600,
  async execute(ctx): Promise<void> {
    if (ctx.nativeNightFailure.usesDemonController()) {
      const { executeDemonNativeNight } = await ctx.nativeNightEffects.loadSealedNightController();
      await executeDemonNativeNight(ctx, "seer_check");
      return;
    }
    for (const { actorId: seerId, ability } of ctx.nightActors.actors(
      "seer_check",
      ctx.currentDay(),
    )) {
      if (ability.activation === "lucky" || ability.activation === "black_market") continue;
      ctx.nativeNightFailure.assertSeerSource(ability);
      ctx.nativeNightFailure.assertNativeActor(seerId, Role.Seer);
      const day = ctx.currentDay(),
        scope = captureNightAbilityScope(
          ctx.world,
          seerId,
          ability,
          day,
          () => ctx.isCurrent() && ctx.currentDay() === day,
        );
      if (!scope?.isEligible()) continue;
      const targets = new Map(
        ctx.world.getAliveEntityIds().map((id) => [id, captureNightLife(ctx.world, id)]),
      );
      const identities = new Map(
        [...targets].flatMap(([id, life]) =>
          life ? [[id, captureInspectionIdentity(ctx.world, life)] as const] : [],
        ),
      );
      if (
        !ctx.world.getAliveEntityIds().includes(seerId) ||
        activeNightAbility(
          ctx.world.getComponent(seerId, COMPONENT.Role),
          "seer_check",
          ctx.currentDay(),
          ability.id,
        ) !== ability
      )
        continue;
      const legalTargets = ctx.world
        .getAliveEntityIds()
        .filter(
          (id) =>
            seerTargetAllowed(ability.state, seerId, id) &&
            luckyTargetAllowed(ctx.world, seerId, ability, day, "check", id),
        );
      if (!legalTargets.length) continue;
      const req = ctx.makeRequest(seerId, ["check_identity"], {
        stage: "seer",
        ability_id: ability.id,
        requiresAction: ability.state.actionPolicy !== "awa_optional_v1",
      });
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      const action = await ctx.actionProvider.getAction(req);
      if (!ctx.isCurrent()) return;
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      if (action?.name !== "check_identity") {
        ctx.nativeNightFailure.actionMissing("seer");
        continue;
      }

      const result = ctx.toolGateway.validateAndSanitize(ctx.world, seerId, action, {
        phase: Phase.Night,
        day: ctx.currentDay(),
        abilityId: ability.id,
      });
      if (!ctx.isCurrent()) return;
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      if (!result.ok || !result.sanitizedCall) {
        ctx.nativeNightFailure.actionInvalid("seer");
        continue;
      }

      const targetId = result.sanitizedCall.args.target_id;
      const target = targets.get(targetId);
      if (!target || !livingNightLife(ctx.world, target) || !identities.get(targetId)?.isCurrent())
        continue;
      const mapping = ctx.nativeNightTargets.mappedTarget(
        () => day,
        () => targetId,
      );
      const receipt = ctx.nativeNightTargets.reflectedTarget(
        () => day,
        () => seerId,
        () => targetId,
        "check",
      );
      if (receipt && (ability.source.kind !== "native" || ability.source.role !== Role.Seer))
        throw new Error("time_consort_seer_source_invalid");
      const effectiveId = receipt?.effectiveId ?? mapping?.effectiveId ?? targetId;
      const effectiveIdentity = identities.get(effectiveId);
      if (mapping && (!mapping.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("magician_inspection_target_stale");
      const inspection = resolveInspection(ctx.world, effectiveId, "camp", ctx.roleCatalog);
      if (!ctx.isCurrent()) return;
      if (
        !scope.isEligible() ||
        !identities.get(targetId)?.isCurrent() ||
        !livingNightLife(ctx.world, target) ||
        !seerTargetAllowed(ability.state, seerId, targetId) ||
        !luckyTargetAllowed(ctx.world, seerId, ability, day, "check", targetId)
      )
        continue;
      if (mapping && (!mapping.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("magician_inspection_target_stale");
      if (!inspection) continue;
      const isWerewolf = inspection.camp === Camp.Wolf;
      const seerRole = ctx.world.getComponent(seerId, COMPONENT.Role);
      if (!activeNightAbility(seerRole, "seer_check", ctx.currentDay(), ability.id)) continue;
      const seerState = seerRole ? getSeerState(seerRole, ability.id) : undefined;
      if (receipt && (!receipt.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("time_consort_inspection_target_stale");
      ctx.nativeNightEffects.commitReflectedTarget(receipt, day, seerId, "check");
      if (seerState) {
        SEER_STATE_SLOT.allowedWrites.recordSeerInspection(seerState, targetId, isWerewolf, inspection);
      }

      // 原状态写入后才追加咒狐提案；仍传请求目标的原 life，随后 checks／use／效果与事实的失败不撤回此前前缀。
      commitFoxInspection(ctx.world, ctx.state, target, day, () => scope.isOwnerCurrent(true));
      ctx.state.seerChecks.push({ seerId, targetId, isWerewolf, result: { ...inspection } });
      recordNightAbilityUse(ability, ctx.currentDay(), true);
      ctx.nativeNightEffects.recordModifierTarget(day, seerId, "check", () => targetId);
      ctx.nativeNightEffects.commitNativeReflection(
        "seer_check",
        ability,
        targetId,
        () => scope.life,
        () => scope.isOwnerCurrent() && !ability.disabled && !ability.deathExpired,
      );
      recordOwnNightAction(ctx.world, seerId, day, "check", targetId, false);
      ctx.events.push({
        timestamp: Date.now(),
        type: "seer_checked",
        payload: {
          actorId: seerId,
          ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
          targetId,
          isWerewolf,
          result: { ...inspection },
        },
      });
    }
  },
};

/** 预言家夜间阶段列表。 */
export const SEER_NIGHT_STAGES: NightStageHandler[] = [seerCheckStage];

/**
 * 负责预言家资料、配置与运行贡献的声明装配，完整查验准入由具名规则组合提供。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { SEER_VALIDATION_RULES } from "../../../../rulesets/seer-tool-admission";
import { z } from "zod";
import {
  SEER_TARGET_POLICIES,
  SEER_ACTION_POLICIES,
  DEFAULT_SEER_ACTION_POLICY,
} from "../../../../core/domain/board";
import { seerTargetAllowed } from "./ports";
import { roleName, text, term } from "@ai-werewolf-arena/game-text";
import { inspectionLabel } from "@ai-werewolf-arena/game-presentation";
/** 文件说明：预言家角色 profile。 */
import { Camp, Role } from "../../../../core/domain/model";
import { NativeRoleContributions } from "../contracts";
import { getSeerState, setSeerState } from "./ports";
import { numberOrNull } from "../../llm/helpers";
import { SEER_NIGHT_STAGES } from "./night_stages";
import { SEER_TOOL_SPECS } from "./tool_specs";
import { activeNightAbility } from "../abilities";
import { luckyTargetAllowed } from "../night_action_history";

const parameters = z.strictObject({
  targetPolicy: z.enum(SEER_TARGET_POLICIES).default("awa_alive_v1"),
  actionPolicy: z.enum(SEER_ACTION_POLICIES).default(DEFAULT_SEER_ACTION_POLICY),
});
/** 预言家角色配置。 */
export const SEER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Seer,
    camp: Camp.Good,
    label: roleName("seer"),
    skillBrief: text("zh-CN", "role.seer.brief"),
    goodSide: "god",
  },
  runtime: {
    configuration: {
      schema: parameters,
      defaults: { targetPolicy: "awa_alive_v1", actionPolicy: DEFAULT_SEER_ACTION_POLICY },
      apply: (config, value) => ({ ...config, seer: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.seer ?? {}),
    },
    init: (roleComp, ctx) => {
      setSeerState(roleComp, {
        lastTarget: null,
        lastIsWerewolf: null,
        lastResult: null,
        history: [],
        ...(ctx.boardConfig?.seer?.targetPolicy === "awa_fresh_others_v1"
          ? { targetPolicy: ctx.boardConfig.seer.targetPolicy }
          : {}),
        ...(ctx.boardConfig?.seer?.actionPolicy === "awa_optional_v1"
          ? { actionPolicy: ctx.boardConfig.seer.actionPolicy }
          : {}),
      });
    },
    toolSpecs: SEER_TOOL_SPECS,
    validationRules: SEER_VALIDATION_RULES,
    nightStages: SEER_NIGHT_STAGES,
    llmRepair: {
      coerce: {
        check_identity: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
    baselineAction: (roleComp, request, pickAliveNotSelf, _byCamp, _locale, world) => {
      if (!request.allowedTools.includes("check_identity")) {
        return null;
      }
      const ability = activeNightAbility(
        roleComp,
        "seer_check",
        request.context.day,
        request.context.ability_id,
      );
      const target =
        world && ability
          ? (world
              .getAliveEntityIds()
              .find(
                (id) =>
                  id !== request.actorId &&
                  seerTargetAllowed(ability.state, request.actorId, id) &&
                  luckyTargetAllowed(
                    world,
                    request.actorId,
                    ability,
                    request.context.day,
                    "check",
                    id,
                  ),
              ) ?? null)
          : pickAliveNotSelf();
      return target !== null ? { name: "check_identity", args: { target_id: target } } : null;
    },
  },
  presentation: nativeRolePresentation("seer"),
};

/**
 * 负责预言家原生／受赠查验状态的创建、同实例读取与实际报告写入。输入为原角色、
 * 捕获状态及已验证目标／阵营结果；输出保留 lastTarget、lastIsWerewolf、lastResult 与历史
 * 的原有序写入。普通查验消费捕获 state，受赠查验分别读取四次 ability.state 和两次 target.id，
 * 不能缓存或合并为一次写入。JSON 复制不新增 payload 形状校验，native 库存安装归 prepared owner；
 * 目标、次数、生命与请求资格仍归原 caller／lease，政策身份字节不替代档案编码或新授权。
 */
import type { SeerState, SeerReadState } from "@ai-werewolf-arena/game-contract";

import type { EntityId, InspectionResult } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../abilities";

/** 安装保留原输入复制与返回 owned 引用；只在初始化入口写原生库存。 */
export function setSeerState(roleComp: RoleComponent, state: SeerState): SeerReadState {
  return commitPreparedNativeAbility(roleComp, "seer_check", SEER_STATE_SLOT.create(state));
}

/** 原生优先选择不按活跃／耗尽过滤；读取不创建或补充资源。 */
export function getSeerState(
  roleComp: RoleComponent,
  abilityId?: string,
): SeerReadState | undefined {
  return findNightAbility(roleComp, "seer_check", abilityId)?.state;
}

/** caller 仍拥有目标／scope 检查及写前、写后的效果；部分失败不回滚前缀。 */
export function recordSeerInspection(
  state: SeerReadState,
  targetId: EntityId,
  isWerewolf: boolean,
  inspection: InspectionResult,
): void {
  (state as SeerState).lastTarget = targetId;
  (state as SeerState).lastIsWerewolf = isWerewolf;
  (state as SeerState).lastResult = { ...inspection };
  (state as SeerState).history.push({ targetId, isWerewolf, result: { ...inspection } });
}

/** 受赠查验保留每次写入前的 state 读取，以及原两次 target.id 读取，不缓存它们。 */
export function recordRecipientSeerInspection(
  ability: NightAbilityReadView<"seer_check">,
  target: { readonly id: EntityId },
  isWerewolf: boolean,
  result: InspectionResult,
): void {
  (ability.state as SeerState).lastTarget = target.id;
  (ability.state as SeerState).lastIsWerewolf = isWerewolf;
  (ability.state as SeerState).lastResult = { ...result };
  (ability.state as SeerState).history.push({
    targetId: target.id,
    isWerewolf,
    result: { ...result },
  });
}

/** 原 JSON callee 先于全部状态字段读取；只迁政策身份字节，不新增 payload snapshot 或失效租约。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"seer_check">): string {
  return JSON.stringify([ability.state.targetPolicy, ability.state.actionPolicy]);
}

/**
 * 本族完整契约引用原 JSON 复制函数和具体有序写入；create／schema 不改变旧接受集合。
 * install／get 与 caller 都消费同一实例库存，metadata 和 lease 保留唯一原所有者。
 * policyIdentity 是旧失效身份字节；checkpoint 归档并不调用新验证或改变原 privateState 形状。
 */
export const SEER_STATE_SLOT = Object.freeze({
  create: copyAbilityData<SeerState>,
  schema: copyAbilityData<SeerState>,
  install: setSeerState,
  get: getSeerState,
  allowedWrites: Object.freeze({
    recordSeerInspection,
    recordRecipientSeerInspection,
  }),
