/**
 * 负责野孩子首夜榜样选择窗口，保留原参与者、只读板子和 provider；请求工厂由装配端晚提供。
 * 输入为已安装绑定、首夜日期及当前性回调；输出为榜样提交成功或准备中断。
 * 先核准备状态再开选择，await 两侧复验原生命和目标；选择、付款与失败关闭归原生命周期。
 * 窗口不修改板子参数、不重新发库存，也不把过期请求当成选择许可。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { Phase, type World, type GameEvent, type ActionProvider } from "../../../../core/domain";
import type { RequestLeaseTurn } from "../../../../core/domain/request-lease";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { readWildChildTool } from "./state-slot";
import {
  wildChildBinding,
  wildChildReady,
  openWildChildChoice,
  validWildChildChoice,
  commitWildChildChoice,
  closeWildChildChoice,
  openWildChildRequestDelivery,
  hasActiveWildChild,
} from "./lifecycle";
export class WildChildSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    /** 只保存惰性构造依赖；不预建请求，原准备和权限检查仍先执行。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (hasActiveWildChild(this.world)) throw new Error("wild_child_setup_reentry");
    if (wildChildReady(this.world)) return true;
    const b = wildChildBinding(this.world);
    if (!b || config !== b.config || day !== 1 || !isCurrent())
      throw new Error("wild_child_setup_unavailable");
    let status: "failed" | "cancelled" = "failed";
    let delivery: RequestLeaseTurn | undefined, failed = false;
    try {
      openWildChildChoice(b, isCurrent);
      // 原选择窗口已开后才取构造器，并用本次 World／事件／day 创建实例；失败仍按原 finally 关闭。
      const request = new this.construction.requestFactory(this.world, this.events, day).create({
        phase: Phase.Night,
        actorId: b.actorId,
        allowedTools: ["choose_wild_model"],
        stage: "wild_child",
        requiresAction: true,
        summary: { key: "turn.wild_child.required" },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      // create 完成后打开原 turn；域状态先按原时点复验，后读请求／预算许可。
      delivery = openWildChildRequestDelivery(this.world, request);
      if (!validWildChildChoice(b) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      const raw = await provider.getAction(request);
      if (!validWildChildChoice(b) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      const call = readWildChildTool(raw);
      if (!call) throw new Error("wild_child_required_choice_missing");
      const result = this.gateway.validateAndSanitize(this.world, b.actorId, call, {
        phase: Phase.Night,
        day,
        wildChildScope: b,
      });
      if (!validWildChildChoice(b) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      if (!result.ok || !commitWildChildChoice(b, call.args.target_id))
        throw new Error("wild_child_choice_invalid");
      // 完整领域 commit 已返回成功；通知或事实晚抛仍 true，不重新核已付款的 pending 状态。
      delivery.complete();
      this.events.push({
        timestamp: Date.now(),
        type: "wild_child_model_chosen",
        payload: { actorId: b.actorId, day: 1, targetId: call.args.target_id },
      });
      return true;
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      try {
        closeWildChildChoice(b, status);
      } catch (error) {
        failed = true;
        throw error;
      } finally {
        // 原 body／cleanup 错误优先；无旧错时新增 false 通知错误正常传播。
        if (failed) { try { delivery?.close(); } catch { /* 保已在传播的错误。 */ } }
        else delivery?.close();
      }
    }
  }
}

/**
 * 负责野孩子原槽创建／安装、宽只读查询、工具解析、选择／取消与转换数据写入和预期内容编码。
 * 输入为原数据绑定及生命周期已核参数；输出保持同一 raw 槽和原 expectedState 字符串，投影另作副本。
 * get 原本只取自有 data descriptor，不是完整 payload schema；不得借迁槽新增拒绝、冻结或复制 live 状态。
 * 榜样生命、阵营／Victory、时钟和已发布死亡事实仍归生命周期；槽数据和知识不是当前许可或档案协议。
 */
import type { WildChildState, WildChildReadState } from "@ai-werewolf-arena/game-contract";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
export const WILD_CHILD_POLICY = "awa_lui_meme_wild_child_v1" as const;
export function freshWildChildState(): WildChildState {
  return {
    policy: WILD_CHILD_POLICY,
    remaining: 1,
    status: "pending",
    choice: null,
    eligibleNight: null,
    activeFromNight: null,
  };
}
export function getWildChildState(role: RoleComponent | undefined): WildChildReadState | undefined {
  const container = role && Object.getOwnPropertyDescriptor(role, "privateState");
  const value =
    container &&
    Object.hasOwn(container, "value") &&
    container.value &&
    Object.getOwnPropertyDescriptor(container.value, "wildChild");
  return value && Object.hasOwn(value, "value") ? (value.value as WildChildReadState) : undefined;
}
export function readWildChildTool(
  value: unknown,
): { name: "choose_wild_model"; args: { target_id: number } } | null {
  try {
    const p = copyEventData(value) as Record<string, unknown> | null;
    const args = p?.args as Record<string, unknown> | undefined;
    return p &&
      Object.keys(p).length === 2 &&
      p.name === "choose_wild_model" &&
      args &&
      Object.keys(args).length === 1 &&
      Number.isSafeInteger(args.target_id) &&
      (args.target_id as number) > 0
      ? { name: "choose_wild_model", args: { target_id: args.target_id as number } }
      : null;
  } catch {
    return null;
  }
}

import type { RoleInitializationComponent } from "../contracts";

/** 保原同引用查询、LHS 与 fresh callee 的先后；初始化不建立新的 World 或许可记录。 */
export function initializeWildChildState(role: RoleInitializationComponent): void {
  if (!getWildChildState(role)) role.privateState.wildChild = freshWildChildState();
}

/** 原内部内容证据编码：复制或 stringify 失败仍只返回 invalid，不是归档 schema 或授权。 */
export function encodeWildChildData(value: unknown): string {
  try {
    return JSON.stringify(copyEventData(value));
  } catch {
    return "invalid";
  }
}

import type { NightLifeScope } from "../../../../core/domain/night_effects";
/** 直接使用原 lifecycle 绑定字段，不新增 store、镜像或绑定类；model 仍是原捕获生命引用。 */
interface WildChildDataBinding {
  state: WildChildReadState;
  expectedState: string;
  model: NightLifeScope | null;
}

/** 先核原可写字段，再消费与写 choice；model 的延迟读取夹在写槽与编码之间。 */
export function commitWildChildState(
  b: WildChildDataBinding,
  choice: NonNullable<WildChildReadState["choice"]>,
  model: () => NightLifeScope,
): boolean {
  if (
    !["remaining", "status", "choice"].every(
      (k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable,
    )
  )
    return false;
  (b.state as Pick<WildChildState, "remaining">).remaining = 0;
  (b.state as Pick<WildChildState, "status">).status = "chosen";
  (b.state as Pick<WildChildState, "choice">).choice = choice;
  b.model = model();
  b.expectedState = encodeWildChildData(b.state);
  return true;
}

/** lifecycle 先关闭原窗口；这里只执行原两字段可写短路及已写内容证据更新。 */
export function cancelWildChildState(b: Pick<WildChildDataBinding, "state" | "expectedState">): void {
  if (["remaining", "status"].every((k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable)) {
    (b.state as Pick<WildChildState, "remaining">).remaining = 0;
    (b.state as Pick<WildChildState, "status">).status = "closed";
    b.expectedState = encodeWildChildData(b.state);
  }
}

/** 原榜样事实、阵营和 Victory 已经提交后才写转换数据；错误保留那些已发布前缀。 */
export function transformWildChildState(b: Pick<WildChildDataBinding, "state" | "expectedState">, day: number): void {
  (b.state as Pick<WildChildState, "status">).status = "transformed";
  (b.state as Pick<WildChildState, "eligibleNight">).eligibleNight = day + 1;
  b.expectedState = encodeWildChildData(b.state);
}

/** 原夜资格与活跃标记先由 lifecycle 处理；编码失败仍按原 invalid 结果继续，不补新的清理。 */
export function activateWildChildState(b: Pick<WildChildDataBinding, "state" | "expectedState">, day: number): void {
  (b.state as Pick<WildChildState, "status">).status = "active";
  (b.state as Pick<WildChildState, "activeFromNight">).activeFromNight = day;
  b.expectedState = encodeWildChildData(b.state);
}

/** 先在原点查询 owner；不当前只显示关闭副本，正常状态仍完整克隆原槽。 */
export function projectWildChildData(b: Pick<WildChildDataBinding, "state">, current: () => boolean): WildChildReadState {
  if (!current()) return { ...freshWildChildState(), remaining: 0, status: "closed" };
  return structuredClone(b.state);
}

/**
 * 负责按实际板子角色配置规范女巫扩展。输入为原 BoardConfig；输出为同一配置或去掉 witch 的浅副本。
 * 存在正数量女巫或无真值 witch 时保原对象，不克隆嵌套值、不安装角色，也不替代配置 schema 校验。
 */
import { BoardConfig, Role } from "../../../../core/domain/model";
import { ConfigNormalizer } from "../../config/contracts";

/** 女巫配置规范化：仅当板子存在女巫时保留 `config.witch`。 */
export const WITCH_CONFIG_NORMALIZER: ConfigNormalizer = {
  id: "witch_config_normalizer",
  normalize(config: BoardConfig): BoardConfig {
    const hasWitch = config.roleSetups.some(
      (setup) => setup.role === Role.Witch && setup.count > 0,
    );
    if (hasWitch || !config.witch) {
      return config;
    }
    const { witch: _removedWitch, ...rest } = config;
    return rest;
  },
};

/**
 * 负责女巫工具参数的原修复规则。输入为原 args；输出为规范目标／瓶型对象或 null。
 * 先经 numberOrNull 读并转换目标，再核瓶型；转换可能执行 caller coercion 或抛错。
 * 修复成功不等于动作接受，不查询库存、刀口、当前请求或付款。
 */
import { PotionType } from "../../../../core/domain/model";
import { ToolRepairPack } from "../../llm/contracts";
import { numberOrNull } from "../../llm/helpers";

export const WITCH_LLM_REPAIR_PACK: ToolRepairPack = {
  coerce: {
    use_potion: (args) => {
      // 目标先转换；即使后面瓶型无效，先前getter／转换错误仍按原顺序传播。
      const target = numberOrNull(args.target_id);
      if (
        target === null ||
        ![PotionType.Heal, PotionType.Poison, PotionType.None].includes(
          args.potion_type as PotionType,
        )
      ) {
        return null;
      }
      return { target_id: target, potion_type: args.potion_type };
    },
  },
};

/**
 * 负责女巫每夜标记复位和原捕获瓶数/目标的用药选择。
 * 输入为当前 native/granted potion 与已验证行动；输出保留已付救/毒、跳过和历史。
 * 原毒 intent 从原 source/target/day 及原请求读取点捕获的 abilityId 生成，不增加时钟/World/RNG读取。
 * 付款、目标映射、第二次行动、角色专有失败和 poison-only 限制保持原位置。
 * 来源句柄只供运行时消费，不进入玩家信息或 schema2；瓶数／旗标归 Witch 状态 owner，公共次数归实例 owner。
 */
import { WITCH_STATE_SLOT } from "./ports";
/** 文件说明：女巫夜间用药阶段处理。 */
import {
  captureNightLife,
  livingNightLife,
  originalPoisonIntent,
} from "../../../../core/domain/night_effects";
import { COMPONENT } from "../../../../core/domain/components/names";
import { RoleComponent } from "../../../../core/domain/components/role";
