/**
 * 负责共享普通狼贡献的完整装配，供普通狼人及派生角色复用原资料、狼聊、狼刀、自爆与 mock。
 * 输入是原狼工具、阶段、校验、修复与提示定义；输出是唯一普通狼三贡献对象及原数组、handler 和回调引用。
 * 保留 metadata、runtime、presentation 的创建顺序及普通狼默认展示；实际 Catalog 注册仍由 wolf/profile 入口引用。
 * 派生角色在原字段读取／展开点读取这一可写对象，运行时替换 runtime 或 getter 仍按原时点生效，不提前缓存。
 * 本模块不建立通用角色基类，不推进阶段或付款，不授予生命、库存和租约写权；展示身份不构成行动许可。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Camp, Role } from "../../../../core/domain/model";
import { NativeRoleContributions } from "../contracts";
import { WOLF_LLM_REPAIR_PACK } from "./llm_repair";
import { WOLF_NIGHT_STAGES } from "./night_stages";
import { WOLF_TOOL_SPECS, WOLF_STAGE_DIRECTIVES } from "./tool_specs";
import { WOLF_VALIDATION_RULES } from "../../../../rulesets/wolf-tool-admission";
import { isMistRavenBoard, mistKnifeTargets } from "../mist_raven/ports";

/** 同一对象保留原四字段资料、完整运行贡献和最后创建的普通狼人展示；字段仍可写，不预取 runtime。 */
export const ORDINARY_WOLF_CONTRIBUTIONS: NativeRoleContributions = {
  metadata: {
    role: Role.Wolf,
    camp: Camp.Wolf,
    label: roleName("wolf"),
    skillBrief: text("zh-CN", "role.wolf.brief"),
  },
  runtime: {
    canSelfDestruct: true,
    wolfTeam: { recognizedByPack: true, recognizes: "pack", canChat: true, canVoteForKill: true },
    toolSpecs: WOLF_TOOL_SPECS,
    stageDirectives: WOLF_STAGE_DIRECTIVES,
    validationRules: WOLF_VALIDATION_RULES,
    nightStages: WOLF_NIGHT_STAGES,
    llmRepair: WOLF_LLM_REPAIR_PACK,
    baselineAction: (
      _roleComp,
      request,
      _pickAliveNotSelf,
      pickAliveByCamp,
      locale = "zh-CN",
      world,
    ) => {
      if (request.allowedTools.includes("speak_to_wolves")) {
        return {
          name: "speak_to_wolves",
          args: {
            text: text(locale, "fallback.wolf_chat"),
            end_chat: false,
          },
        };
      }
      if (request.allowedTools.includes("kill_vote")) {
        const circle = world && isMistRavenBoard(world) ? mistKnifeTargets(world) : null;
        if (circle !== null) {
          const target = circle[0] ?? null;
          return { name: "kill_vote", args: { target_id: target, abstain: target === null } };
        }
        const target = pickAliveByCamp("good");
        if (target !== null) {
          return { name: "kill_vote", args: { target_id: target, abstain: false } };
        }
        return { name: "kill_vote", args: { target_id: null, abstain: true } };
      }
      if (request.allowedTools.includes("self_destruct")) {
        // 自爆属于高风险动作：fallback 不应在“可选中断窗口”默认触发。
        return null;
      }
      return null;
    },
  },
  presentation: nativeRolePresentation("wolf"),
};

/**
 * 负责按原狼队权限执行夜聊轮次与刀票重试，捕获行动者与目标的原身体／生命版本。
 * 输入为原夜上下文、狼队资格和已校验工具；输出为夜聊、共识和带来源的刀口贡献。
 * 收票后由普通狼刀规则组合按原时点处理迷雾抽刀、映射和印记；贵族 God 刀口事实及必需记录归贵族发布 owner。
 * 原演员快照晚查实际阵营值，不增加 Camp 引用撤权；每个提交仍晚查现有狼队执行资格。
 * 不增加重试额度、重建已失效的身体或把发表事实当付款；首失败和已写前缀维持原边界。
 */
import { publishNobleNightKnife } from "../noble_secret_body/knife-ports";
import { isMistRavenBoard } from "../mist_raven/knife-ports";
import { resolveOrdinaryWolfKnife, type AcceptedWolfKnifeTarget } from "../../../../rulesets/ordinary-wolf-knife-routing";
import { nightmareKnifeBlocked } from "../nightmare_shadow/ports";
import { bindWolfKnifeTargetQuery } from "./ports";
/** 文件说明：狼人夜聊与刀人投票阶段处理。 */
import { EntityId, Phase } from "../../../../core/domain/model";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { NightStageHandler } from "../../stages/night/contracts";
import { wolfChatParticipants, wolfKnifeHolders, wolfTeamEvent } from "../wolf_team";
import { COMPONENT } from "../../../../core/domain/components/names";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { NightStageContext } from "../../stages/night/contracts";

const WOLF_DISCUSSION_MAX_ROUNDS = 3;
const WOLF_KILL_VOTE_MAX_RETRIES = 3;

/** 夜聊与刀票在原查询点读取具体板子的失败前缀，不缓存或改写首个错误。 */
function strictWolfFailurePrefix(ctx: NightStageContext): string | null {
  return ctx.nativeNightFailure.strictWolfFailurePrefix();
}

/** 捕获 Role、私有容器／顶层引用与原 Alive 版本；后续只复验同一身体，不复制或延长许可。 */
function captureActorScope(ctx: NightStageContext, actorId: EntityId): () => boolean {
  const role = ctx.world.getComponent(actorId, COMPONENT.Role),
    kind = role?.role,
    camp = role == null ? undefined : ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp,
    state = role?.privateState,
    refs = state ? Object.entries(state) : [];
  const life = ctx.world.getComponent(actorId, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  return () =>
    ctx.isCurrent() &&
    !!role &&
    ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
    role.role === kind &&
    ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === camp &&
    role.privateState === state &&
    refs.every(([key, value]) => (state! as Readonly<Record<string, unknown>>)[key] === value) &&
    !!life &&
    ctx.world.getComponent(actorId, COMPONENT.Alive) === life &&
    life.alive &&
    version !== undefined &&
    aliveLifeVersion(life) === version;
}

const wolfDiscussionStage: NightStageHandler = {
  id: "wolf_discussion",
  priority: 200,
  async execute(ctx): Promise<void> {
    const wolfIds = ctx.shuffleWolves(wolfChatParticipants(ctx.world, ctx.roleCatalog));
    ctx.state.wolfChatOrder = wolfIds;
    ctx.state.endedWolves = new Set<EntityId>();

    if (wolfIds.length > 0) {
      ctx.events.push(
        wolfTeamEvent(ctx.world, ctx.roleCatalog, {
          timestamp: Date.now(),
          type: "wolf_tactical_order",
          payload: { order: [...wolfIds] },
        }),
      );
    }

    // 轮转夜聊：每只狼最多发言 WOLF_DISCUSSION_MAX_ROUNDS 次，end_chat 后跳过后续轮次。
    for (let round = 1; round <= WOLF_DISCUSSION_MAX_ROUNDS; round++) {
      for (const wolfId of wolfIds) {
        if (!wolfChatParticipants(ctx.world, ctx.roleCatalog).includes(wolfId)) continue;
        if (ctx.state.endedWolves.has(wolfId)) {
          continue;
        }
        const actorCurrent = captureActorScope(ctx, wolfId);
        if (!actorCurrent() || !wolfChatParticipants(ctx.world, ctx.roleCatalog).includes(wolfId))
          continue;
        const req = ctx.makeRequest(wolfId, ["speak_to_wolves"], {
          stage: "wolf_discussion",
          round,
          max_rounds: WOLF_DISCUSSION_MAX_ROUNDS,
        });
        const action = await ctx.actionProvider.getAction(req);
        if (!ctx.isCurrent()) return;
        if (!actorCurrent() || !wolfChatParticipants(ctx.world, ctx.roleCatalog).includes(wolfId))
          continue;
        if (action?.name !== "speak_to_wolves") {
          if (strictWolfFailurePrefix(ctx))
            throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_chat_action_missing`);
          continue;
        }

        if (
          strictWolfFailurePrefix(ctx) &&
          (typeof action.args?.text !== "string" || typeof action.args?.end_chat !== "boolean")
        ) {
          throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_chat_action_invalid`);
        }
        const result = ctx.toolGateway.validateAndSanitize(ctx.world, wolfId, action, {
          phase: req.phase,
        });
        if (!ctx.isCurrent()) return;
        if (!actorCurrent() || !wolfChatParticipants(ctx.world, ctx.roleCatalog).includes(wolfId))
          continue;
        if (!result.ok || !result.sanitizedCall) {
          if (strictWolfFailurePrefix(ctx))
            throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_chat_action_invalid`);
          continue;
        }
        if (result.sanitizedCall.args.end_chat) {
          ctx.state.endedWolves.add(wolfId);
          ctx.events.push(
            wolfTeamEvent(ctx.world, ctx.roleCatalog, {
              timestamp: Date.now(),
              type: "wolf_discussion_ended",
              payload: {
                actorId: wolfId,
                reason: result.sanitizedCall.args.text,
                round,
              },
            }),
          );
        } else {
          ctx.events.push(
            wolfTeamEvent(ctx.world, ctx.roleCatalog, {
              timestamp: Date.now(),
              type: "wolf_discussion",
              payload: {
                actorId: wolfId,
                text: result.sanitizedCall.args.text,
                endChat: false,
                round,
              },
            }),
          );
        }
      }
      if (ctx.state.endedWolves.size === wolfIds.length) {
        break;
      }
    }
  },
};

const wolfKillVoteStage: NightStageHandler = {
  id: "wolf_kill_vote",
  priority: 400,
  async execute(ctx): Promise<void> {
    ctx.state.wolfVotes = {};
    if (nightmareKnifeBlocked(ctx.world, ctx.currentDay())) {
      ctx.state.wolfTarget = null;
      delete ctx.state.wolfTargetScope;
      ctx.state.wolfTargetVoters = [];
      return;
    }
    const acceptedTargets: AcceptedWolfKnifeTarget[] = [];
    // 顺序收集狼刀票，统一在阶段末做多数决结算，避免中途状态污染。
    const knifeHolders = wolfKnifeHolders(ctx.world, ctx.roleCatalog);
    // 保留普通狼队原次序；仅有刀权的角色在后半名单独立加入。
    const voteOrder = [
      ...ctx.state.wolfChatOrder.filter((id) => knifeHolders.includes(id)),
      ...knifeHolders.filter((id) => !ctx.state.wolfChatOrder.includes(id)),
    ];
    const mistVoteScopes = isMistRavenBoard(ctx.world)
      ? new Map(voteOrder.map((id) => [id, captureActorScope(ctx, id)] as const))
      : null;
    const explicitPasses = new Set<EntityId>();
    for (const wolfId of voteOrder) {
      if (!wolfKnifeHolders(ctx.world, ctx.roleCatalog).includes(wolfId)) {
        if (mistVoteScopes) throw new Error("mist_wolf_actor_stale");
        continue;
      }
      const actorCurrent = captureActorScope(ctx, wolfId);
      if (!actorCurrent()) {
        if (mistVoteScopes) throw new Error("mist_wolf_actor_stale");
        continue;
      }
      let voteResolved: {
        abstain: boolean;
        targetId: EntityId | null;
        fallback: boolean;
        targetLife?: { life: AliveComponent; version: number };
      } | null = null;
      let retryReason = "";
      for (let attempt = 1; attempt <= WOLF_KILL_VOTE_MAX_RETRIES + 1; attempt++) {
        if (!actorCurrent()) break;
        if (!wolfKnifeHolders(ctx.world, ctx.roleCatalog).includes(wolfId)) break;
        const req =
          attempt === 1
            ? ctx.makeRequest(wolfId, ["kill_vote"], { stage: "wolf_vote" })
            : ctx.makeRequest(wolfId, ["kill_vote"], {
                stage: "wolf_vote",
                retry_attempt: attempt - 1,
                retry_max: WOLF_KILL_VOTE_MAX_RETRIES,
                retry_reason: retryReason,
                retry_notice_message: { key: "request.retry.wolf_vote" },
              });
        const targetLives = new Map(
          ctx.world.getAliveEntityIds().map((id) => {
            const life = ctx.world.getComponent(id, COMPONENT.Alive)!;
            return [id, { life, version: aliveLifeVersion(life) }] as const;
          }),
        );
        const action = await ctx.actionProvider.getAction(req);
        if (!ctx.isCurrent()) return;
        if (!actorCurrent()) break;
        if (action?.name !== "kill_vote") {
          if (strictWolfFailurePrefix(ctx))
            throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_action_missing`);
          retryReason = "no_valid_kill_vote_tool_call";
          if (attempt <= WOLF_KILL_VOTE_MAX_RETRIES) {
            safeRecordLogicOp({
              scope: "phase_pipeline",
              op: "wolf_kill_vote_retry_requested",
              actorId: wolfId,
              phase: Phase.Night,
              status: "fallback",
              reason: retryReason,
              output: {
                attempt,
                max_retries: WOLF_KILL_VOTE_MAX_RETRIES,
              },
            });
            continue;
          }
          break;
        }

        const result = ctx.toolGateway.validateAndSanitize(ctx.world, wolfId, action, {
          phase: Phase.Night,
        });
        if (!ctx.isCurrent()) return;
        if (!actorCurrent()) break;
        const target = result.sanitizedCall?.args.target_id,
          snapshot = typeof target === "number" ? targetLives.get(target) : undefined;
        const targetCurrent =
          result.sanitizedCall?.args.abstain === true ||
          target === null ||
          (!!snapshot &&
            bindWolfKnifeTargetQuery(ctx.world).allows(target as number) &&
            ctx.world.getComponent(target as number, COMPONENT.Alive) === snapshot.life &&
            snapshot.life.alive &&
            snapshot.version !== undefined &&
            aliveLifeVersion(snapshot.life) === snapshot.version);
        if (!result.ok || !result.sanitizedCall || !targetCurrent) {
          if (strictWolfFailurePrefix(ctx))
            throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_action_invalid`);
          retryReason = "invalid_kill_vote_arguments";
          if (attempt <= WOLF_KILL_VOTE_MAX_RETRIES) {
            safeRecordLogicOp({
              scope: "phase_pipeline",
              op: "wolf_kill_vote_retry_requested",
              actorId: wolfId,
              phase: Phase.Night,
              status: "fallback",
              reason: retryReason,
              output: {
                attempt,
                max_retries: WOLF_KILL_VOTE_MAX_RETRIES,
              },
            });
            continue;
          }
          break;
        }

        voteResolved = {
          abstain: result.sanitizedCall.args.abstain === true,
          targetId: result.sanitizedCall.args.target_id,
          fallback: attempt > 1,
          ...(!result.sanitizedCall.args.abstain && snapshot && snapshot.version !== undefined
            ? { targetLife: { life: snapshot.life, version: snapshot.version } }
            : {}),
        };
        break;
      }
      if (!actorCurrent() || !wolfKnifeHolders(ctx.world, ctx.roleCatalog).includes(wolfId)) {
        if (mistVoteScopes) throw new Error("mist_wolf_actor_stale");
        continue;
      }
      if (!voteResolved) {
        if (strictWolfFailurePrefix(ctx))
          throw new Error(`${strictWolfFailurePrefix(ctx)}_wolf_action_missing`);
        voteResolved = {
          abstain: true,
          targetId: null,
          fallback: true,
        };
        safeRecordLogicOp({
          scope: "phase_pipeline",
          op: "wolf_kill_vote_repaired_to_abstain",
          actorId: wolfId,
          phase: Phase.Night,
          status: "ok",
          reason: retryReason || "wolf_kill_vote_retry_exhausted",
          output: {
            fallback_abstain: true,
          },
        });
      }

      const abstain = voteResolved.abstain;
      const targetId = voteResolved.targetId;
      if (abstain && targetId === null) explicitPasses.add(wolfId);
      if (!abstain && targetId !== null) {
        if (voteResolved.targetLife)
          acceptedTargets.push({ actorId: wolfId, targetId, ...voteResolved.targetLife });
      }
      ctx.events.push(
        wolfTeamEvent(ctx.world, ctx.roleCatalog, {
          timestamp: Date.now(),
          type: "wolf_kill_vote_cast",
          payload: {
            actorId: wolfId,
            abstain,
            targetId,
            ...(voteResolved.fallback ? { fallback: true } : {}),
          },
        }),
      );
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "wolf_kill_vote_cast",
        actorId: wolfId,
        phase: Phase.Night,
        status: "ok",
        output: { abstain, target_id: targetId },
      });
    }

    if (mistVoteScopes)
      for (const [id, current] of mistVoteScopes)
        if (!current() || !wolfKnifeHolders(ctx.world, ctx.roleCatalog).includes(id))
          throw new Error("mist_wolf_actor_stale");
    for (const target of acceptedTargets) {
      const current =
        ctx.world.getComponent(target.targetId, COMPONENT.Alive) === target.life &&
        target.life.alive &&
        aliveLifeVersion(target.life) === target.version &&
        bindWolfKnifeTargetQuery(ctx.world).allows(target.targetId);
      if (!current && mistVoteScopes) throw new Error("mist_wolf_target_stale");
      if (current)
        ctx.state.wolfVotes[target.targetId] = (ctx.state.wolfVotes[target.targetId] ?? 0) + 1;
    }
    const wolfTarget = resolveOrdinaryWolfKnife(ctx, acceptedTargets, voteOrder, explicitPasses);
    publishNobleNightKnife(() => ctx, wolfTarget);
  },
};

/** 狼人夜间阶段列表。 */
export const WOLF_NIGHT_STAGES: NightStageHandler[] = [wolfDiscussionStage, wolfKillVoteStage];

/**
 * 负责按原顺序组合四个机制的公开普通狼刀目标查询。
 * 输入为当前目标序号、狼刀圈／角色政策及存活名单；输出为原候选允许布尔值。
 * 依次读取雾鸦狼刀圈、夜之贵族政策、存活名单、恶夜骑士及梦魇，短路与查询失败原样保留。
 * 绑定只捕获原 World 引用，不提前读组件、生命、库存或随机源；查询不公开 World 与提交写权。
 * 表面冻结不冻结 World 或复制名单，现场候选允许结果也不是实际狼刀提交许可。
 */
import type { EntityId } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import { bindMistKnifeTargetQuery, type MistKnifeTargetQuery } from "../mist_raven/ports";
import { bindNobleKnifeTargetQuery, type NobleKnifeTargetQuery } from "../noble_secret_body/ports";
import {
  bindEvilKnightKnifeTargetQuery,
  type EvilKnightKnifeTargetQuery,
} from "../evil_knight/ports";
import {
  bindNightmareKnifeTargetQuery,
  type NightmareKnifeTargetQuery,
} from "../nightmare_shadow/ports";

/** 名单在 allows 内的原第三步才读取；返回原只读视图，不保存第二份阵容快照。 */
export interface WolfKnifeRosterQuery {
  aliveIds(): readonly EntityId[];
}
/** 仅提供目标谓词，不携带回合、能力实例或付款权限。 */
export interface WolfKnifeTargetQuery {
  allows(targetId: EntityId): boolean;
}

/** 固定组合顺序；保留每个查询的原 receiver 与短路，不新增可扩展规则图或角色回调注册器。 */
export function createWolfKnifeTargetQuery(
  roster: WolfKnifeRosterQuery,
  mist: MistKnifeTargetQuery,
  noble: NobleKnifeTargetQuery,
  evilKnight: EvilKnightKnifeTargetQuery,
  nightmare: NightmareKnifeTargetQuery,
): WolfKnifeTargetQuery {
  return Object.freeze({
    allows(targetId: EntityId) {
      const circle = mist.targets();
      return (
        (circle === null || circle.includes(targetId)) &&
        noble.allows(targetId) &&
        roster.aliveIds().includes(targetId) &&
        evilKnight.allows(targetId) &&
        nightmare.allows(targetId)
      );
    },
  });
}

/** 只捕获 World 参数引用，四个具体绑定仍按原顺序创建；所有现场查询延迟至 allows。 */
export function bindWolfKnifeTargetQuery(world: World): WolfKnifeTargetQuery {
  return createWolfKnifeTargetQuery(
    { aliveIds: () => world.getAliveEntityIds() },
    bindMistKnifeTargetQuery(world),
    bindNobleKnifeTargetQuery(world),
    bindEvilKnightKnifeTargetQuery(world),
    bindNightmareKnifeTargetQuery(world),
  );
}

/**
 * 负责狼美人原源死亡后的未领取牵连 proposal。
 * 输入为死亡原体、原因和 hook 上下文；输出持有批量运行贡献，具体绑定及原 nightEffect 旗标留在本族闭包。
 * 实际领取、梦阻断和死亡提交随后由 relation owner 在原结算时点执行，不能在 hook 提前付款。
 * 失效关系不发 proposal；不修改库存、标死或发布事实。规则见 docs/rules/awa-wolf-beauty-v1.md。
 */
import { getWolfBeautyState } from "./state";
import { Role, DeathCause } from "../../../../core/domain/model";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { DeathHook } from "../../hooks/hook_registry";
import { activeCharm, permitsCharm, attemptCharmTrigger, commitCharmDeath } from "./relation";
import { createWolfBeautyDeathContribution } from "./death-wave-publication";
import { animalBeautyLinkBlocked } from "../animal_dream/beauty-query-ports";

export const wolfBeautyDeathHook: DeathHook = async (
  world,
  ids,
  sources,
  _choose,
  events,
  context,
) => {
  const result: Awaited<ReturnType<DeathHook>> = { extraDeaths: [], extraDeathSources: {} };
  let proposals: Parameters<typeof createWolfBeautyDeathContribution>[0][number][] | undefined;
  for (const actorId of ids) {
    // 动物原阻断查询先于 hook 当前性与来源政策；这里只准备未领取提案，不把公开查询变成死亡许可。
    if (animalBeautyLinkBlocked(world, context?.day ?? 0)) continue;
    if (context?.isCurrent && !context.isCurrent()) break;
    if (
      world.getComponent(actorId, COMPONENT.Role)?.role !== Role.WolfBeauty ||
      !permitsCharm(
        sources[actorId] ?? [],
        getWolfBeautyState(world.getComponent(actorId, COMPONENT.Role)!)?.deathLinkPolicy,
        context?.nativeHunterShotTargets?.has(actorId) ?? false,
      )
    )
      continue;
    const binding = activeCharm(world, actorId);
    if (
      !binding ||
      binding.actorLife.alive ||
      (!binding.targetLife.alive && !context?.eligibleDead?.has(binding.targetId))
    )
      continue;
    (proposals ??= []).push({ binding, nightEffect: context?.nightEffect ?? false });
  }
  if (proposals) {
    // 只捕获命令查询；直到原准备／发布 callee 位置才获取同一 live binding。
    result.deathWaveContributions = [
      createWolfBeautyDeathContribution(proposals, {
        get attemptCharmTrigger() {
          return attemptCharmTrigger;
        },
        get commitCharmDeath() {
          return commitCharmDeath;
        },
      }),
    ];
  }
  return result;
};

/**
 * 负责狼美人夜间魅惑的请求、等待后原体复验、选择历史、关系绑定及公开／动物私密通知。
 * 输入为原夜上下文与经网关验证的可空目标；输出保留原历史、绑定与事件，拒绝或失效选择不安装新关系。
 * 动物准入与板子识别通过查询端口按原位置调用，通知通过独立事实端口发表，不能将已知数据当作现场权限。
 * 原状态依次写 targetId、lastActedDay、追加 history，再绑定关系、发表 charm_applied，最后追加动物通知；失败保已写前缀。
 * 目标和演员生命版本在原等待前后核对；未付魅惑另拒绝捕获角色的执行退休，不过滤目标或已付关系。
 * 首选择字段写后继续原绑定／事实前缀；本流程不提前领取死亡牵连，实际来源政策、保护与标死另归原 owner。
 */
import { recordCharmSelection } from "./state";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import { Role, Camp, Phase } from "../../../../core/domain/model";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getWolfBeautyState } from "./state";
import { bindCharm } from "./relation";
import { animalBeautyCharmAllowed, isAnimalDreamBoard } from "../animal_dream/beauty-query-ports";
import { appendAnimalBeautyNotice } from "../animal_dream/beauty-fact-ports";

export const WOLF_BEAUTY_CHARM_STAGE: NightStageHandler = {
  id: "wolf_beauty_charm",
  priority: 450,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (!animalBeautyCharmAllowed(ctx.world, day)) return;
    for (const actorId of ctx.getAliveByRole(Role.WolfBeauty)) {
      if (!ctx.isCurrent()) return;
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getWolfBeautyState(role),
        actorLife = ctx.world.getComponent(actorId, COMPONENT.Alive)!,
        actorVersion = aliveLifeVersion(actorLife),
        policy = state?.deathLinkPolicy;
      const canAct = () => !isRoleExecutionRetired(role);
      // 原阵营／槽／本夜库存资格先读取，再拒绝新的未付魅惑；名单本身仍是纯角色数据。
      if (ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf || !state || state.lastActedDay === day || !canAct()) continue;
      const targets = new Map(
        ctx.world
          .getAliveEntityIds()
          .filter((id) => id !== actorId)
          .map((id) => {
            const life = ctx.world.getComponent(id, COMPONENT.Alive)!;
            return [id, { life, version: aliveLifeVersion(life) }] as const;
          }),
      );
      // 原 Provider receiver／callee 先于 builder；目标捕获、callee 或参数准备导致退休时不建新请求。
      const provider = ctx.actionProvider,
        getAction = provider.getAction,
        makeRequest = ctx.makeRequest;
      const requestActor = actorId;
      const requestTools: Parameters<typeof makeRequest>[1] = ["charm"];
      const requestExtras: Parameters<typeof makeRequest>[2] = {
        stage: "wolf_beauty", requiresAction: false,
      };
      const requestArgs = [requestActor, requestTools, requestExtras];
      const invokeRequest = Reflect.apply.bind(Reflect);
      if (!canAct()) continue;
      const request: ReturnType<typeof makeRequest> = invokeRequest(makeRequest, ctx, requestArgs);
      const actionArgs = [request];
      const invokeAction = Reflect.apply.bind(Reflect);
      if (!canAct()) continue;
      const action: Awaited<ReturnType<typeof getAction>> = await invokeAction(getAction, provider, actionArgs);
      const current = () =>
        ctx.isCurrent() &&
        animalBeautyCharmAllowed(ctx.world, day) &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.WolfBeauty &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Wolf &&
        getWolfBeautyState(role) === state &&
        state.deathLinkPolicy === policy &&
        state.lastActedDay !== day &&
        ctx.world.getComponent(actorId, COMPONENT.Alive) === actorLife &&
        actorLife.alive &&
        actorVersion !== undefined &&
        aliveLifeVersion(actorLife) === actorVersion;
      if (!current() || !canAct()) continue;
      if (action !== null && action.name !== "charm") continue;
      let targetId = action === null ? null : action.args.target_id;
      if (action) {
        const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !result.ok || result.sanitizedCall?.name !== "charm" || !canAct()) continue;
        targetId = result.sanitizedCall.args.target_id;
      }
      if (targetId !== null) {
        const target = targets.get(targetId);
        if (
          !target ||
          ctx.world.getComponent(targetId, COMPONENT.Alive) !== target.life ||
          !target.life.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.life) !== target.version
        )
          continue;
      }
      // 原 nullable 目标／生命 getter 与提交 callee 先准备；只在首选择写前拒绝。
      // 选择已写即进入原完成段，后续 history／绑定／事实失败或晚退休不退款。
      const recordSelection = recordCharmSelection;
      if (!canAct()) continue;
      recordSelection(state, targetId, day);
      bindCharm(ctx.world, actorId, targetId);
      ctx.events.push({
        timestamp: Date.now(),
        type: "charm_applied",
        payload: { actorId, targetId, day },
      });
      if (isAnimalDreamBoard(ctx.world)) appendAnimalBeautyNotice(ctx.world, ctx.events, day);
    }
  },
};

/**
 * 负责 狼美人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
