/** 脚本渲染注册表。 */
export class ScriptEventRenderRegistry {
  toChatLine(event: GameEvent, locale: Locale = "zh-CN"): string | null {
    const handler = CHAT_HANDLERS[event.type];
    return handler
      ? (handler as (event: GameEvent, locale: Locale) => string | null)(event, locale)
      : null;
  }

  toJudgeLine(event: GameEvent, locale: Locale = "zh-CN"): string | null {
    const animal = animalDreamEventLabel(event.type, event.payload, locale);
    if (animal !== null) return animal;
    const fragrant = fragrantPairEventLabel(event.type, event.payload, locale);
    if (fragrant !== null) return fragrant;
    const noble = nobleSecretBodyEventLabel(event.type, event.payload, locale);
    if (noble !== null) return noble;
    const radiant = radiantEclipseEventLabel(event.type, event.payload, locale);
    if (radiant !== null) return radiant;
    const mist = mistRavenEventLabel(event.type, event.payload, locale);
    if (mist !== null) return mist;
    const modifier = scholarMentorEventLabel(event.type, event.payload, locale);
    if (modifier !== null) return modifier;
    const consort = timeConsortEventLabel(event.type, event.payload, locale);
    if (consort !== null) return consort;
    const sorcerer = wolfSorcererEventLabel(event.type, event.payload, locale);
    if (sorcerer !== null) return sorcerer;
    const trickster = tricksterEventLabel(event.type, event.payload, locale);
    if (trickster !== null) return trickster;
    const prince = orderPrinceEventLabel(event.type, event.payload, locale);
    if (prince !== null) return prince;
    const magician = magicianEventLabel(event.type, event.payload, locale);
    if (magician !== null) return magician;
    const redMoon = redMoonEventLabel(event.type, event.payload, locale);
    if (redMoon !== null) return redMoon;
    const nightmare = nightmareEventLabel(event.type, event.payload, locale);
    if (nightmare !== null) return nightmare;
    const demon = demonHunterEventLabel(event.type, event.payload, locale);
    if (demon !== null) return demon;
    const wedding = ghostBrideEventLabel(event.type, event.payload, locale);
    if (wedding !== null) return wedding;
    const lonely = lonelyGirlEventLabel(event.type, event.payload, locale);
    if (lonely) return lonely;
    const wild = wildChildEventLabel(event.type, event.payload, locale);
    if (wild !== null) return wild;
    const shape = shapeshifterEventLabel(event.type, event.payload, locale);
    if (shape !== null) return shape;
    const thief = thiefEventLabel(event.type, event.payload, locale);
    if (thief !== null) return thief;
    const black = blackMarketEventLabel(event.type, event.payload, locale);
    if (black !== null) return black;
    const deathAbility = deathAbilityEventLabel(event.type, event.payload, locale);
    if (deathAbility !== null) return deathAbility;
    const awakened = awakenedEventLabel(event.type, event.payload, locale);
    if (awakened !== null) return awakened;
    const wall = wallEventLabel(event.type, event.payload, locale);
    if (wall !== null) return wall;
    const debate = debateEventLabel(event.type, event.payload, locale);
    if (debate !== null) return debate;
    const cupid = cupidEventLabel(event.type, event.payload, locale);
    if (cupid !== null) return cupid;
    const hybrid = hybridEventLabel(event.type, event.payload, locale);
    if (hybrid !== null) return hybrid;
    const merchant = merchantEventLabel(event.type, event.payload, locale);
    if (merchant !== null) return merchant;
    const mechanical = mechanicalEventLabel(event.type, event.payload, locale);
    if (mechanical !== null) return mechanical;
    const handler = JUDGE_HANDLERS[event.type];
    return handler
      ? (handler as (event: GameEvent, locale: Locale) => string | null)(event, locale)
      : null;
  }

  toReplayStage(event: GameEvent): string {
    const handler = REPLAY_STAGE_HANDLERS[event.type];
    if (handler) {
      return (handler as (event: GameEvent) => string | null)(event) ?? event.type;
    }
    return event.type;
  }

  toLiveRender(
    event: GameEvent,
    printPrivateEvents: boolean,
    locale: Locale = "zh-CN",
  ): ScriptLiveRender[] {
    const animal = animalDreamEventLabel(event.type, event.payload, locale);
    if (animal !== null) {
      const visibility = animalDreamFactAudience(event.type as AnimalDreamEventType);
      return visibility === "public"
        ? [{ kind: "system", text: animal }]
        : printPrivateEvents
          ? [{ kind: visibility === "actor" ? "private" : "god", text: animal }]
          : [];
    }
    const fragrant = fragrantPairEventLabel(event.type, event.payload, locale);
    if (fragrant !== null)
      return printPrivateEvents
        ? [
            {
              kind: fragrantPairVisibility(event.type) === "actor" ? "private" : "god",
              text: fragrant,
            },
          ]
        : [];
    const noble = nobleSecretBodyEventLabel(event.type, event.payload, locale);
    if (noble !== null) {
      const visibility = nobleSecretBodyVisibility(event.type);
      return visibility === "public"
        ? [{ kind: "system", text: noble }]
        : printPrivateEvents
          ? [{ kind: visibility === "actor" ? "private" : "god", text: noble }]
          : [];
    }
    const radiant = radiantEclipseEventLabel(event.type, event.payload, locale);
    if (radiant !== null) return printPrivateEvents ? [{ kind: "god", text: radiant }] : [];
    const mist = mistRavenEventLabel(event.type, event.payload, locale);
    if (mist !== null) return printPrivateEvents ? [{ kind: "god", text: mist }] : [];
    const modifier = scholarMentorEventLabel(event.type, event.payload, locale);
    if (modifier !== null) return printPrivateEvents ? [{ kind: "god", text: modifier }] : [];
    const consort = timeConsortEventLabel(event.type, event.payload, locale);
    if (consort !== null) return [{ kind: "system", text: consort }];
    const sorcerer = wolfSorcererEventLabel(event.type, event.payload, locale);
    if (sorcerer !== null) return [{ kind: "system", text: sorcerer }];
    const trickster = tricksterEventLabel(event.type, event.payload, locale);
    if (trickster !== null) return [{ kind: "system", text: trickster }];
    const prince = orderPrinceEventLabel(event.type, event.payload, locale);
    if (prince !== null)
      return event.type === "order_prince_choice_committed"
        ? printPrivateEvents
          ? [{ kind: "god", text: prince }]
          : []
        : [{ kind: "system", text: prince }];
    const magician = magicianEventLabel(event.type, event.payload, locale);
    if (magician !== null)
      return event.type === "death_shot_missed"
        ? [{ kind: "system", text: magician }]
        : printPrivateEvents
          ? [{ kind: "god", text: magician }]
          : [];
    const nightmare = nightmareEventLabel(event.type, event.payload, locale);
    if (nightmare !== null) return printPrivateEvents ? [{ kind: "god", text: nightmare }] : [];
    const demon = demonHunterEventLabel(event.type, event.payload, locale);
    if (demon !== null) return printPrivateEvents ? [{ kind: "god", text: demon }] : [];
    const wedding = ghostBrideEventLabel(event.type, event.payload, locale);
    if (wedding !== null) return printPrivateEvents ? [{ kind: "god", text: wedding }] : [];
    const lonely = lonelyGirlEventLabel(event.type, event.payload, locale);
    if (lonely) return printPrivateEvents ? [{ kind: "god", text: lonely }] : [];
    const wild = wildChildEventLabel(event.type, event.payload, locale);
    if (wild !== null) return printPrivateEvents ? [{ kind: "god", text: wild }] : [];
    const shape = shapeshifterEventLabel(event.type, event.payload, locale);
    if (shape !== null) return printPrivateEvents ? [{ kind: "god", text: shape }] : [];
    const thief = thiefEventLabel(event.type, event.payload, locale);
    if (thief !== null) return printPrivateEvents ? [{ kind: "god", text: thief }] : [];
    const wall = wallEventLabel(event.type, event.payload, locale);
    if (wall !== null)
      return ["wall_note_changed", "wall_note_order_recorded"].includes(event.type)
        ? printPrivateEvents
          ? [{ kind: "god", text: wall }]
          : []
        : [{ kind: "system", text: wall }];
    const debate = debateEventLabel(event.type, event.payload, locale);
    if (debate !== null)
      return event.type === "debate_ballots_recorded"
        ? printPrivateEvents
          ? [{ kind: "god", text: debate }]
          : []
        : [{ kind: "system", text: debate }];
    const cupid = cupidEventLabel(event.type, event.payload, locale);
    if (cupid !== null)
      return printPrivateEvents
        ? [
            {
              kind: ["cupid_relation_resolved", "lovers_death"].includes(event.type)
                ? "god"
                : "private",
              text: cupid,
            },
          ]
        : [];
    const black = blackMarketEventLabel(event.type, event.payload, locale);
    if (black !== null)
      return printPrivateEvents
        ? [{ kind: event.type === "black_market_trade_resolved" ? "god" : "private", text: black }]
        : [];
    const awakened = awakenedEventLabel(event.type, event.payload, locale);
    if (awakened !== null) return printPrivateEvents ? [{ kind: "private", text: awakened }] : [];
    const hybrid = hybridEventLabel(event.type, event.payload, locale);
    if (hybrid !== null)
      return printPrivateEvents
        ? [{ kind: event.type === "hybrid_affiliation_resolved" ? "god" : "private", text: hybrid }]
        : [];
    const merchant = merchantEventLabel(event.type, event.payload, locale);
    if (merchant !== null)
      return printPrivateEvents
        ? [{ kind: event.type === "merchant_trade_resolved" ? "god" : "private", text: merchant }]
        : [];
    if (event.type === "lucky_ability_skipped")
      return printPrivateEvents
        ? [
            {
              kind: "private",
              text: text(locale, "console.lucky.skipped", {
                actor: event.payload.actorId,
                day: event.payload.day,
                ability: event.payload.abilityId,
              }),
            },
          ]
        : [];
    const mechanical = mechanicalEventLabel(event.type, event.payload, locale);
    if (mechanical !== null) {
      if (event.type === "mechanical_shot") return [{ kind: "action", text: mechanical }];
      return printPrivateEvents
        ? [
            {
              kind: event.type === "mechanical_poison_reflected" ? "god" : "private",
              text: mechanical,
            },
          ]
        : [];
    }
    const handler = LIVE_HANDLERS[event.type];
    if (handler) {
      const rendered = (
        handler as (
          event: GameEvent,
          printPrivateEvents: boolean,
          locale: Locale,
        ) => ScriptLiveRender[] | null
      )(event, printPrivateEvents, locale);
      if (rendered) {
        return rendered;
      }
    }
    const judge = this.toJudgeLine(event, locale);
    if (judge) {
      return [{ kind: "god", text: text(locale, "console.live.god", { line: judge }) }];
    }
    return [];
  }
}

let defaultRegistry: ScriptEventRenderRegistry | null = null;

/** 获取默认脚本渲染注册表实例。 */
export function getDefaultScriptEventRenderRegistry(): ScriptEventRenderRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ScriptEventRenderRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责提交普通狼／赤月和白狼王的已选自爆。输入为捕获玩家、已校验选择和当前窗口；输出为原资源、事件与死亡提案。退休仅拒演员执行，目标和已付前缀仍保原规则；不执行真实标死或阶段／胜负封盘。
 */
import { RED_MOON_ROLE } from "../roles/red_moon_apostle/ports";
import { commitDemonRedMoonBlast } from "../roles/demon_hunter/authority";
import { canRoleSelfDestruct } from "../roles/self_destruct_capability";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  swallowWeddingBadges,
} from "../roles/ghost_bride/authority";
import {
  ActionWindow,
  Phase,
  Role,
  DeathCause,
  type SelfDestructSelection,
  type DeathSources,
  type GameEvent,
} from "../../../core/domain/model";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import type { World } from "../../../core/domain/world";
import { getWhiteWolfKingState, consumeWhiteWolfDetonation } from "../roles/white_wolf_king/ports";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";

/** 仅提交本自爆能力的资源、事件和事实，返回死亡提案；实际死亡写入由结算器负责。 */
export function commitSelfDestructSelection(
  world: World,
  choice: SelfDestructSelection,
  window: ActionWindow,
  phase: Phase,
  events: GameEvent[],
): { deaths: number[]; sources: DeathSources } | null {
  if (
    !Object.values(ActionWindow).includes(window) ||
    phase !== (window === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day)
  )
    return null;
  const role = world.getComponent(choice.actorId, COMPONENT.Role);
  if (!role || !world.getComponent(choice.actorId, COMPONENT.Alive)?.alive) return null;
  const ownsWedding = weddingSetup(world) !== null;
  if (
    ownsWedding &&
    (!ghostBrideReady(world) ||
      role.role !== Role.Wolf ||
      weddingMember(world, role) ||
      ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window))
  )
    return null;
  const deaths = [choice.actorId],
    sources: DeathSources = { [choice.actorId]: [DeathCause.SelfDestruct] };
  if (choice.kind === "ordinary") {
    const redMoon = String(role.role) === RED_MOON_ROLE;
    if (
      choice.targetId !== null ||
      (redMoon
        ? ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window)
        : !canRoleSelfDestruct(role, getDefaultRoleCatalog(), () => world.getComponent(choice.actorId, COMPONENT.Camp)))
    )
      return null;
    // 原普通能力／赤月窗口资格已经读取；直接赤月旁路也须在实际权威付款前拒退休演员。
    if (isRoleExecutionRetired(role)) return null;
    const moon = redMoon ? commitDemonRedMoonBlast(world, choice.actorId) : null;
    if (redMoon && !moon) return null;
    if (ownsWedding) swallowWeddingBadges(world, events);
    events.push({
      timestamp: Date.now(),
      type: "wolf_self_destruct",
      payload: { wolfId: choice.actorId, window },
    });
    if (moon?.sealsNight)
      events.push({
        timestamp: Date.now(),
        type: "red_moon_night_sealed",
        payload: { actorId: choice.actorId, day: moon.day, night: moon.day + 1 },
      });
  } else if (choice.kind === "white_wolf_king") {
    const state = getWhiteWolfKingState(role);
    if (role.role !== Role.WhiteWolfKing || state?.canDetonate !== true) return null;
    if (choice.targetId !== null) {
      if (
        choice.targetId === choice.actorId ||
        !world.getComponent(choice.targetId, COMPONENT.Alive)?.alive
      )
        return null;
      deaths.push(choice.targetId);
      sources[choice.targetId] = [DeathCause.WhiteWolfBlast];
    }
    // 同一库存和原目标预检在先；退休不消费库存，不取消目标身体或回滚任何已付前缀。
    if (isRoleExecutionRetired(role)) return null;
    consumeWhiteWolfDetonation(state);
    events.push({
      timestamp: Date.now(),
      type: "white_wolf_king_self_destruct",
      payload: { actorId: choice.actorId, targetId: choice.targetId, window },
    });
  } else return null;
  return { deaths, sources };
}

/**
 * 负责规范自爆窗口配置的缺省表示。输入为原 BoardConfig；输出为原对象或去掉 selfDestruct 的浅副本。
 * enabledWindows 明确存在（包括空数组）即保原配置，缺失才删扩展；不打开窗口、校验行动或退款。
 */
import { BoardConfig } from "../../../core/domain/model";
import { ConfigNormalizer } from "../config/contracts";

/** 显式空窗口保留禁用表达；字段缺失则删除该扩展，让默认机制按原 owner 决定。 */
export const SELF_DESTRUCT_CONFIG_NORMALIZER: ConfigNormalizer = {
  id: "self_destruct_config_normalizer",
  normalize(config: BoardConfig): BoardConfig {
    if (config.selfDestruct?.enabledWindows !== undefined) {
      return config;
    }
    const { selfDestruct: _removedSelfDestruct, ...rest } = config;
    return rest;
  },
};

/**
 * 负责警徽授予、转移／销毁与票重提交。输入为原 World、警徽持有者、合格接任者及配置；
 * 输出为原警徽／VotingRight 写入和事件。先校验特殊板可读性，转移先销旧徽、重置旧票重，再安装接任状态、
 * 提交特殊 frame 和发表事实；晚失败保留此前前缀，不事务回滚或以替换组件自动恢复销毁警徽。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { openDemonBadgeFrame, assertDemonBadgeReadable } from "../roles/demon_hunter/authority";
import { weddingBadgeSwallowed } from "../roles/ghost_bride/authority";
/** 文件说明：警徽流转、销毁与授予逻辑。 */
import { AliveComponent } from "../../../core/domain/components/alive";
import { BadgeComponent } from "../../../core/domain/components/badge";
import { COMPONENT } from "../../../core/domain/components/names";
import { VotingRightComponent } from "../../../core/domain/components/voting_right";
import { IdentityComponent } from "../../../core/domain/entities/player";
import { EntityId, GameEvent } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { canBeSheriff } from "../common/participation";
import type { RoleCatalog } from "../roles/catalog";

const SHERIFF_VOTE_WEIGHT = 1.5;

export interface SheriffBadgeTransferResult {
  fromId: EntityId;
  toId: EntityId | null;
  destroyed: boolean;
}

export function assignSheriff(
  world: World,
  sheriffId: EntityId,
  config?: ReadonlyBoardConfig,
  catalog?: RoleCatalog,
): boolean {
  assertDemonBadgeReadable(world);
  if (weddingBadgeSwallowed(world) || !canBeSheriff(world, sheriffId, catalog)) return false;
  const frame = openDemonBadgeFrame(world);
  const weight = config?.sheriff?.voteWeight ?? SHERIFF_VOTE_WEIGHT;
  for (const id of world.getAliveEntityIds()) {
    const badge = world.getComponent(id, COMPONENT.Badge);
    if (badge) {
      badge.isSheriff = id === sheriffId;
      badge.destroyed = false;
      badge.voteWeight = weight;
      if (config?.sheriff?.badgePolicy === "awa_holder_choice_v1")
        badge.handoffPolicy = "awa_holder_choice_v1";
      else delete badge.handoffPolicy;
    }
    const voting = world.getComponent(id, COMPONENT.VotingRight);
    if (voting?.canVote) voting.weight = id === sheriffId ? weight : 1;
  }
  frame?.commit({
    kind: "assign",
    sheriffId,
    weight,
    policy:
      config?.sheriff?.badgePolicy === "awa_holder_choice_v1" ? "awa_holder_choice_v1" : undefined,
  });
  return true;
}

export function transferOrDestroySheriffBadge(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  catalog?: RoleCatalog,
): SheriffBadgeTransferResult | null {
  assertDemonBadgeReadable(world);
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return null;
  return commitSheriffBadgeChoice(
    world,
    fromId,
    reason,
    events,
    badge.handoffPolicy === "awa_holder_choice_v1"
      ? null
      : pickNextSheriffCandidate(world, fromId, catalog),
    catalog,
  );
}

/** 只把警徽交给当前合格目标；null／拒绝目标走销毁，旧徽与票重先写，晚错误不撤回。 */
export function commitSheriffBadgeChoice(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  targetId: EntityId | null,
  catalog?: RoleCatalog,
): SheriffBadgeTransferResult | null {
  assertDemonBadgeReadable(world);
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return null;
  const frame = openDemonBadgeFrame(world);
  const weight = badge.voteWeight ?? SHERIFF_VOTE_WEIGHT;
  const policy = badge.handoffPolicy;
  const nextSheriffId =
    targetId !== null && badgeSuccessorEligible(world, fromId, targetId, catalog) ? targetId : null;
  // 旧徽先销毁并复位票重；接任安装、特殊frame提交或事件失败都保留此前前缀。
  badge.isSheriff = false;
  badge.destroyed = true;
  resetVotingWeight(world, fromId);
  if (nextSheriffId === null) {
    frame?.commit({ kind: "handoff", fromId, toId: null, weight, policy });
    events.push({
      timestamp: Date.now(),
      type: "sheriff_badge_destroyed",
      payload: { targetId: fromId, reason },
    });
    return { fromId, toId: null, destroyed: true };
  }
  const nextBadge = world.getComponent(nextSheriffId, COMPONENT.Badge);
  if (nextBadge) {
    nextBadge.isSheriff = true;
    nextBadge.destroyed = false;
    nextBadge.voteWeight = weight;
    if (policy) nextBadge.handoffPolicy = policy;
    else delete nextBadge.handoffPolicy;
  }
  const nextVoting = world.getComponent(nextSheriffId, COMPONENT.VotingRight);
  if (nextVoting) nextVoting.weight = weight;
  frame?.commit({ kind: "handoff", fromId, toId: nextSheriffId, weight, policy });
  events.push({
    timestamp: Date.now(),
    type: "sheriff_badge_transferred",
    payload: { fromId, toId: nextSheriffId, reason },
  });
  return { fromId, toId: nextSheriffId, destroyed: false };
}

function resetVotingWeight(world: World, entityId: EntityId): void {
  const voting = world.getComponent(entityId, COMPONENT.VotingRight);
  if (voting) voting.weight = voting.canVote ? 1 : 0;
}

export function badgeSuccessorEligible(
  world: World,
  fromId: EntityId,
  id: EntityId,
  catalog?: RoleCatalog,
): boolean {
  assertDemonBadgeReadable(world);
  return (
    id !== fromId &&
    canBeSheriff(world, id, catalog) &&
    world.getComponent(id, COMPONENT.Alive)?.alive === true &&
    world.getComponent(id, COMPONENT.VotingRight)?.canVote === true &&
    world.getComponent(id, COMPONENT.Badge)?.destroyed === false
  );
}

function pickNextSheriffCandidate(
  world: World,
  fromId: EntityId,
  catalog?: RoleCatalog,
): EntityId | null {
  assertDemonBadgeReadable(world);
  const candidates = world
    .getAliveEntityIds()
    .filter((id) => badgeSuccessorEligible(world, fromId, id, catalog));
  candidates.sort((a, b) => {
    const aSeat = world.getComponent(a, COMPONENT.Identity)?.seat ?? a;
    const bSeat = world.getComponent(b, COMPONENT.Identity)?.seat ?? b;
    return aSeat - bSeat;
  });
  return candidates[0] ?? null;
}

export function findSheriffId(world: World, catalog?: RoleCatalog): EntityId | null {
  assertDemonBadgeReadable(world);
  return (
    world.getAliveEntityIds().find((id) => {
      const badge = world.getComponent(id, COMPONENT.Badge);
      return (
        badge?.isSheriff === true && badge.destroyed === false && canBeSheriff(world, id, catalog)
      );
    }) ?? null
  );
}

export function assignInitialSheriff(
  world: World,
  config: ReadonlyBoardConfig,
  playerIds: EntityId[],
): void {
  if (!config.enableSheriff || config.initialSheriffSeat === undefined) return;
  const sheriffId = playerIds.find(
    (id) => world.getComponent(id, COMPONENT.Identity)?.seat === config.initialSheriffSeat,
  );
  if (sheriffId !== undefined) assignSheriff(world, sheriffId, config);
}

/**
 * 负责死亡警长的警徽选择请求与回复复核。输入为原警徽、死者生命、阶段／日期、当前性回调及玩家／工具入口；
 * 输出为原转移或销毁结果，警徽写入仍由警徽所有者提交。请求选择和预检不提前改变警徽。
 * 死亡许可只覆盖本次选择；持有者与许可仍当前时，已选目标生命失效按原规则改为销毁。
 * 玩家异常不被伪装成一次有效选择；显式构造依赖仅在原 new 点读取，失败不补交警徽且仍关闭本次许可。
 */
import { aliveLifeVersion, type AliveComponent } from "../../../core/domain/components/alive";
import type { BadgeComponent } from "../../../core/domain/components/badge";
import type { RoleComponent } from "../../../core/domain/components/role";
import { COMPONENT } from "../../../core/domain/components/names";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import type { ActionProvider, EntityId, GameEvent, Phase } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { ActionRequestFactoryConstructorPort } from "../../../core/domain/actions";
import type { ToolGateway } from "../../gateway/tool_gateway";
import {
  badgeSuccessorEligible,
  commitSheriffBadgeChoice,
  transferOrDestroySheriffBadge,
} from "./badge";

/** 持徽死者只在引擎打开、绑定原生命版本的临时许可内选择；这不是复活后的新生命权限。 */
export async function resolveSheriffBadge(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  gateway: ToolGateway,
  provider: ActionProvider,
  phase: Phase,
  day: number,
  isCurrent: () => boolean,
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
): Promise<void> {
  if (!isCurrent()) return;
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return;
  if (badge.handoffPolicy !== "awa_holder_choice_v1") {
    transferOrDestroySheriffBadge(world, fromId, reason, events);
    return;
  }
  const life = world.getComponent(fromId, COMPONENT.Alive);
  const role = world.getComponent(fromId, COMPONENT.Role);
  const version = life && aliveLifeVersion(life);
  const weight = badge.voteWeight;
  // 警徽原体、政策／权重、角色与死亡生命必须仍相同；业务阶段当前性由传入回调核对。
  const current = () =>
    isCurrent() &&
    world.getComponent(fromId, COMPONENT.Badge) === badge &&
    badge.isSheriff &&
    !badge.destroyed &&
    badge.handoffPolicy === "awa_holder_choice_v1" &&
    badge.voteWeight === weight &&
    world.getComponent(fromId, COMPONENT.Role) === role &&
    world.getComponent(fromId, COMPONENT.Alive) === life &&
    life?.alive === false &&
    aliveLifeVersion(life) === version;
  if (!life || !role || !current()) return;
  const candidates = world
    .getAliveEntityIds()
    .filter((id) => badgeSuccessorEligible(world, fromId, id));
  if (!candidates.length) {
    commitSheriffBadgeChoice(world, fromId, reason, events, null);
    return;
  }
  // 固定本次候选的原生命，不能让等待期间复活的同编号替代原接收人。
  const scopes = new Map(candidates.map((id) => [id, captureNightLife(world, id)]));
  const permit = world.openDeathAction(fromId, "choose_badge_successor", phase, day, current);
  const authorized = () =>
    current() && world.hasDeathAction(fromId, "choose_badge_successor", phase, day, permit.id);
  try {
    if (!authorized()) return;
    // 许可已开启且原 authorized 通过后，才读取构造器并在原点 new；构造失败仍由 finally 关闭许可。
    const request = new construction.requestFactory(world, events, day).create({
      phase,
      actorId: fromId,
      allowedTools: ["choose_badge_successor"],
      stage: "sheriff_badge_choice",
      requiresAction: true,
      summary: { key: "request.summary.badge_choice" },
      context: {
        allow_fallback: false,
        trigger: "badge_handoff",
        death_action_id: permit.id,
        badge_candidates: candidates,
      },
    });
    if (!authorized()) return;
    const action = await provider.getAction(request);
    if (!authorized()) return;
    let target: EntityId | null = null;
    if (action?.name === "choose_badge_successor") {
      const checked = gateway.validateAndSanitize(world, fromId, action, {
        phase,
        day,
        deathActionId: permit.id,
        badgeCandidates: candidates,
      });
      if (!authorized()) return;
      if (checked.ok && checked.sanitizedCall) target = checked.sanitizedCall.args.target_id;
    }
    // 缺失／无效选择或已失效目标保留原 null 销毁政策；玩家入口抛错则直接进入 finally，不补提交。
    if (target !== null) {
      const scope = scopes.get(target);
      if (
        !scope ||
        !livingNightLife(world, scope) ||
        !badgeSuccessorEligible(world, fromId, target)
      )
        target = null;
    }
    if (authorized()) commitSheriffBadgeChoice(world, fromId, reason, events, target);
  } finally {
    permit.close();
  }
}

/**
 * 负责按警长开关规范 sheriff 配置及平票扩展。输入为原 BoardConfig；输出为原对象或原分支的浅展开结果。
 * 只按原真值条件处理字段，不深克隆、安装警徽或配置投票权；枚举／读取抛错仍传播，已执行转换不回滚。
 */
import { BoardConfig } from "../../../core/domain/model";
import { ConfigNormalizer } from "../config/contracts";

/** 警长配置规范化：警长关闭时移除 sheriff 相关扩展配置。 */
export const SHERIFF_CONFIG_NORMALIZER: ConfigNormalizer = {
  id: "sheriff_config_normalizer",
  normalize(config: BoardConfig): BoardConfig {
    if (config.enableSheriff) {
      return config;
    }
    const { sheriff: _removedSheriff, ...rest } = config;
    if (!rest.tieBreaker?.sheriffVote) {
      return rest;
    }
    const { sheriffVote: _removedSheriffTie, ...otherTie } = rest.tieBreaker;
    // 仅otherTie非空才覆写tieBreaker；空时展开仍保rest原字段，不在注释中扩称完整深清理。
    return {
      ...rest,
      ...(Object.keys(otherTie).length > 0 ? { tieBreaker: otherTie } : {}),
    };
  },
};

/**
 * 负责警长上警、竞选、退水和两轮选举的原有顺序；输入为当前座位、Provider、网关及惰性构造器，输出原选举证据与当选者。
 * 上警阶段先建立全部请求才并发调用，竞选按座位串行；退水／投票保原生命复验和事后写入前缀，PK不套用放逐或狼刀规则。
 * 请求在原存活名单确定之后才 new 一份本次选举工厂，全部竞选／退水／PK沿用它，不提前读取构造依赖。
 * 构造、玩家、校验或事件异常原样传播；已发事实不回滚，警徽赋权仍由警徽所有者提交，不以端口授予候选资格。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { weddingBadgeSwallowed } from "../roles/ghost_bride/authority";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { COMPONENT } from "../../../core/domain/components/names";
import { IdentityComponent } from "../../../core/domain/entities/player";
import {
  ActionProvider,
  EntityId,
  GameEvent,
  Phase,
  TieBreakerStrategy,
} from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { ToolGateway } from "../../gateway/tool_gateway";
import type { ActionRequestFactoryConstructorPort, ActionRequestConstructionPort } from "../../../core/domain/actions";
import { assignSheriff, findSheriffId } from "./badge";
import { canBeSheriff, canVote } from "../common/participation";
import type { RoleCatalog } from "../roles/catalog";

export interface SheriffElectionInput {
  world: World;
  events: GameEvent[];
  toolGateway: ToolGateway;
  actionProvider: ActionProvider;
  day: number;
  enableSheriff: boolean;
  config?: ReadonlyBoardConfig;
  roleCatalog?: RoleCatalog;
  isCurrent?: () => boolean;
  /** 装配端 getter 保原构造器读取点；字段仅声明依赖，未开启选举或预建请求。 */
  readonly requestFactory: ActionRequestFactoryConstructorPort;
}

/** 只存已接收的选票字段；生命与候选资格仍在各轮原检查点复验，不把票记录当授权。 */
interface SheriffVote {
  actorId: EntityId;
  targetId: EntityId | null;
  abstain: boolean;
}

export async function electSheriffIfNeeded(input: SheriffElectionInput): Promise<EntityId | null> {
  if (!current(input) || weddingBadgeSwallowed(input.world)) return null;
  const { world, events, day, enableSheriff, config } = input;
  const currentSheriff = findSheriffId(world, input.roleCatalog);
  if (!enableSheriff || day !== 1 || currentSheriff !== null) return currentSheriff;

  const aliveIds = world.getAliveEntityIds().filter((id) => canVote(world, id, input.roleCatalog));
  // 本次选举只在原点 new 一次；不复用白天发言工厂，构造失败时尚未建立上警请求。
  const requests = new input.requestFactory(world, events, day);
  const initialCandidates = await collectNominations(input, requests, aliveIds);
  if (!current(input)) return null;
  const candidateSet = new Set<EntityId>(initialCandidates);
  await collectCampaignSpeeches(input, requests, candidateSet);
  if (!current(input)) return null;
  const finalizedCandidates = await collectWithdrawals(input, requests, candidateSet);
  if (!current(input)) return null;
  const pk = config?.sheriff?.electionPolicy === "awa_nomination_offstage_pk_v1";
  const forbidden = pk ? new Set(initialCandidates) : candidateSet;
  let { tally, votes } =
    pk && finalizedCandidates.length === 1
      ? { tally: new Map([[finalizedCandidates[0], 0]]), votes: [] as SheriffVote[] }
      : await collectSheriffVotes(input, requests, aliveIds, finalizedCandidates, forbidden);
  if (!current(input)) return null;
  let round = 1;
  let eligible = finalizedCandidates.filter((id) => canBeSheriff(world, id, input.roleCatalog));
  const top = positiveLeaders(eligible, tally);
  if (pk && top.length > 1) {
    events.push({
      timestamp: Date.now(),
      type: "sheriff_vote_summary",
      payload: { votes, winnerId: null, round: 1 },
    });
    events.push({
      timestamp: Date.now(),
      type: "sheriff_pk_started",
      payload: { candidates: top },
    });
    await collectCampaignSpeeches(input, requests, new Set(top), "sheriff_pk_speech");
    if (!current(input)) return null;
    const tied = top.filter((id) => canBeSheriff(world, id, input.roleCatalog));
    ({ tally, votes } = await collectSheriffVotes(
      input,
      requests,
      aliveIds,
      tied,
      new Set(top),
      2,
    ));
    if (!current(input)) return null;
    eligible = tied.filter((id) => canBeSheriff(world, id, input.roleCatalog));
    round = 2;
  }
  let winner =
    pk && finalizedCandidates.length === 1 && eligible.length === 1
      ? eligible[0]
      : pickSheriffWinner(
          world,
          eligible,
          tally,
          pk ? "no_elimination" : (config?.tieBreaker?.sheriffVote ?? "min_seat"),
        );
  if (winner !== null && !assignSheriff(world, winner, config, input.roleCatalog)) winner = null;
  events.push({
    timestamp: Date.now(),
    type: "sheriff_vote_summary",
    payload: { votes, winnerId: winner, ...(pk ? { round } : {}) },
  });
  if (winner !== null) {
    events.push({
      timestamp: Date.now(),
      type: "sheriff_elected",
      payload: {
        winnerId: winner,
        candidates: finalizedCandidates,
        tally: Object.fromEntries(tally.entries()),
      },
    });
  }
  return winner;
}

async function collectNominations(
  input: SheriffElectionInput,
  requests: ActionRequestConstructionPort,
  aliveIds: EntityId[],
): Promise<EntityId[]> {
  const { world, events, toolGateway, actionProvider } = input;
  const candidates: EntityId[] = [];
  // 上警声明并行收集，避免顺序执行导致后手玩家读取前手“上警/退水”结果后被动调整。
  // 先建立全部请求，确保每位玩家读取同一批事件快照，再启动并行 Agent 调用。
  const nominationRequests = aliveIds
    .filter((id) => canBeSheriff(world, id, input.roleCatalog))
    .map((actorId) => ({
      actorId,
      life: captureNightLife(world, actorId),
      request: requests.create({
        phase: Phase.Day,
        actorId,
        allowedTools: ["run_for_sheriff"],
        stage: "sheriff_nomination",
        requiresAction: true,
        summary: { key: "request.summary.sheriff_nomination" },
        context: {},
      }),
    }));
  const nominationResults = await Promise.all(
    nominationRequests.map(async ({ actorId, request, life }) => {
      if (!current(input)) return null;
      const action = await actionProvider.getAction(request);
      if (
        !current(input) ||
        !life ||
        !livingNightLife(world, life) ||
        action?.name !== "run_for_sheriff"
      ) {
        return null;
      }
      const result = toolGateway.validateAndSanitize(world, actorId, action, {
        phase: Phase.Day,
      });
      if (!current(input) || !result.ok || !result.sanitizedCall) {
        return null;
      }
      return {
        actorId,
        run: result.sanitizedCall.args.run === true,
        life,
      };
    }),
  );
  if (!current(input)) return [];
  for (const item of nominationResults) {
    if (
      !item ||
      !livingNightLife(world, item.life) ||
      !canBeSheriff(world, item.actorId, input.roleCatalog)
    ) {
      continue;
    }
    events.push({
      timestamp: Date.now(),
      type: "sheriff_candidate_declared",
      payload: { actorId: item.actorId, run: item.run },
    });
    if (item.run) {
      candidates.push(item.actorId);
    }
  }

  const initialCandidates = sortBySeat(world, candidates);
  events.push({
    timestamp: Date.now(),
    type: "sheriff_nomination_summary",
    payload: { candidates: initialCandidates },
  });
  return initialCandidates;
}

async function collectCampaignSpeeches(
  input: SheriffElectionInput,
  requests: ActionRequestConstructionPort,
  candidateSet: Set<EntityId>,
  stage: "sheriff_campaign_speech" | "sheriff_pk_speech" = "sheriff_campaign_speech",
): Promise<void> {
  const { world, events, toolGateway, actionProvider } = input;
  const campaignOrder = sortBySeat(world, [...candidateSet]);
  // 上警发言：候选人按座位顺序发言。
  for (const candidateId of campaignOrder) {
    if (!current(input)) return;
    if (!candidateSet.has(candidateId) || !canBeSheriff(world, candidateId, input.roleCatalog)) {
      continue;
    }
    const life = captureNightLife(world, candidateId);
    if (!life) continue;
    const speechReq = requests.create({
      phase: Phase.Day,
      actorId: candidateId,
      allowedTools: ["speak"],
      stage,
      requiresAction: true,
      summary: { key: "request.summary.sheriff_campaign" },
      context: {
        sheriff_candidates: [...candidateSet],
      },
    });
    const speechAction = await actionProvider.getAction(speechReq);
    if (!current(input)) return;
    if (speechAction?.name === "speak") {
      const speechResult = toolGateway.validateAndSanitize(world, candidateId, speechAction, {
        phase: Phase.Day,
      });
      if (
        current(input) &&
        livingNightLife(world, life) &&
        speechResult.ok &&
        speechResult.sanitizedCall &&
        canBeSheriff(world, candidateId, input.roleCatalog)
      ) {
        events.push({
          timestamp: Date.now(),
          type: "day_speech",
          payload: {
            actorId: candidateId,
            text: speechResult.sanitizedCall.args.text,
          },
        });
      }
    }
  }
}

async function collectWithdrawals(
  input: SheriffElectionInput,
  requests: ActionRequestConstructionPort,
  candidateSet: Set<EntityId>,
): Promise<EntityId[]> {
  const { world, events, toolGateway, actionProvider } = input;
  // 发言结束后统一进入退水阶段，再进入警长投票。
  const orderedCandidates = sortBySeat(
    world,
    [...candidateSet].filter((id) => canBeSheriff(world, id, input.roleCatalog)),
  );
  const withdrawRequests = orderedCandidates.map((candidateId) => ({
    candidateId,
    life: captureNightLife(world, candidateId),
    request: requests.create({
      phase: Phase.Day,
      actorId: candidateId,
      allowedTools: ["run_for_sheriff"],
      stage: "sheriff_withdraw",
      requiresAction: true,
      summary: { key: "request.summary.sheriff_withdraw" },
      context: {
        sheriff_candidates: [...candidateSet],
      },
    }),
  }));
  const withdrawResults = await Promise.all(
    withdrawRequests.map(async ({ candidateId, request, life }) => {
      if (!current(input)) return null;
      const withdrawAction = await actionProvider.getAction(request);
      if (
        !current(input) ||
        !life ||
        !livingNightLife(world, life) ||
        withdrawAction?.name !== "run_for_sheriff"
      ) {
        return null;
      }
      const withdrawResult = toolGateway.validateAndSanitize(world, candidateId, withdrawAction, {
        phase: Phase.Day,
      });
      if (!current(input) || !withdrawResult.ok || !withdrawResult.sanitizedCall) {
        return null;
      }
      return {
        candidateId,
        keepRunning: withdrawResult.sanitizedCall.args.run === true,
        life,
      };
    }),
  );
  if (!current(input)) return [];
  const withdrawn: EntityId[] = [];
  for (const item of withdrawResults) {
    if (!item || !livingNightLife(world, item.life) || item.keepRunning) {
      continue;
    }
    candidateSet.delete(item.candidateId);
    withdrawn.push(item.candidateId);
    events.push({
      timestamp: Date.now(),
      type: "sheriff_candidate_declared",
      payload: { actorId: item.candidateId, run: false },
    });
  }
  events.push({
    timestamp: Date.now(),
    type: "sheriff_withdraw_summary",
    payload: { withdrawn: sortBySeat(world, withdrawn) },
  });

  for (const id of candidateSet)
    if (!canBeSheriff(world, id, input.roleCatalog)) candidateSet.delete(id);
  const finalizedCandidates = sortBySeat(world, [...candidateSet]);
  events.push({
    timestamp: Date.now(),
    type: "sheriff_candidates_finalized",
    payload: { candidates: finalizedCandidates },
  });
  return finalizedCandidates;
}

async function collectSheriffVotes(
  input: SheriffElectionInput,
  requests: ActionRequestConstructionPort,
  aliveIds: EntityId[],
  finalizedCandidates: EntityId[],
  candidateSet: Set<EntityId>,
  round = 1,
): Promise<{ tally: Map<EntityId, number>; votes: SheriffVote[] }> {
  const { world, events, toolGateway, actionProvider } = input;
  const tally = new Map<EntityId, number>();
  for (const id of finalizedCandidates) {
    tally.set(id, 0);
  }
  if (finalizedCandidates.length === 0) return { tally, votes: [] };

  // 规则：警长投票仅允许警下玩家（未在最终警上名单内）参与。
  const sheriffVoterIds = aliveIds.filter(
    (id) => !candidateSet.has(id) && canVote(world, id, input.roleCatalog),
  );
  // 警长投票同样并行收集，所有投票基于同一快照上下文。
  const candidateLives = new Map(
    finalizedCandidates.map((id) => [id, captureNightLife(world, id)]),
  );
  const sheriffVoteRequests = sheriffVoterIds.map((actorId) => ({
    actorId,
    life: captureNightLife(world, actorId),
    request: requests.create({
      phase: Phase.Day,
      actorId,
      allowedTools: ["vote_for_sheriff"],
      stage: round === 2 ? "sheriff_pk_vote" : "sheriff_vote",
      requiresAction: true,
      summary: { key: "request.summary.sheriff_vote" },
      context: {
        sheriff_candidates: finalizedCandidates,
        ...(round === 2 ? { round: 2, max_rounds: 2 } : {}),
      },
    }),
  }));
  const sheriffVoteResults = await Promise.all(
    sheriffVoteRequests.map(async ({ actorId, request, life }) => {
      if (!current(input)) return null;
      const action = await actionProvider.getAction(request);
      if (
        !current(input) ||
        !life ||
        !livingNightLife(world, life) ||
        action?.name !== "vote_for_sheriff"
      ) {
        return null;
      }
      const result = toolGateway.validateAndSanitize(world, actorId, action, {
        phase: Phase.Day,
        sheriffCandidates: finalizedCandidates,
      });
      if (!current(input) || !result.ok || !result.sanitizedCall) {
        return null;
      }

      const abstain = result.sanitizedCall.args.abstain === true;
      const targetId = result.sanitizedCall.args.target_id;
      return { actorId, targetId, abstain, life };
    }),
  );
  if (!current(input)) return { tally, votes: [] };
  const acceptedVotes: SheriffVote[] = [];
  for (const item of sheriffVoteResults) {
    if (
      !item ||
      !livingNightLife(world, item.life) ||
      !canVote(world, item.actorId, input.roleCatalog) ||
      candidateSet.has(item.actorId) ||
      (!item.abstain &&
        (item.targetId === null ||
          !finalizedCandidates.includes(item.targetId) ||
          !candidateLives.get(item.targetId) ||
          !livingNightLife(world, candidateLives.get(item.targetId)!) ||
          !canBeSheriff(world, item.targetId, input.roleCatalog)))
    ) {
      continue;
    }
    acceptedVotes.push({ actorId: item.actorId, targetId: item.targetId, abstain: item.abstain });
    events.push({
      timestamp: Date.now(),
      type: "sheriff_vote_cast",
      payload: {
        actorId: item.actorId,
        targetId: item.targetId,
        abstain: item.abstain,
      },
    });
    if (!item.abstain && item.targetId !== null) {
      tally.set(item.targetId, (tally.get(item.targetId) ?? 0) + 1);
    }
  }
  return { tally, votes: acceptedVotes };
}

function current(input: SheriffElectionInput): boolean {
  if (weddingBadgeSwallowed(input.world)) return false;
  return input.isCurrent?.() ?? true;
}

function pickSheriffWinner(
  world: World,
  candidates: EntityId[],
  tally: Map<EntityId, number>,
  strategy: TieBreakerStrategy,
): EntityId | null {
  if (candidates.length === 0) {
    return null;
  }
  const withSeat = candidates.map((id) => {
    const identity = world.getComponent(id, COMPONENT.Identity);
    return { id, seat: identity?.seat ?? id, score: tally.get(id) ?? 0 };
  });
  withSeat.sort((a, b) => {
    const diff = b.score - a.score;
    if (diff !== 0) {
      return diff;
    }
    if (strategy === "min_id") {
      return a.id - b.id;
    }
    return a.seat - b.seat;
  });
  if ((withSeat[0]?.score ?? 0) <= 0) return null;
  if (withSeat.length >= 2 && withSeat[0].score === withSeat[1].score) {
    if (strategy === "no_elimination" || strategy === "no_kill") {
      return null;
    }
  }
  return withSeat[0]?.id ?? null;
}

function sortBySeat(world: World, ids: EntityId[]): EntityId[] {
  return [...ids].sort((a, b) => {
    const aSeat = world.getComponent(a, COMPONENT.Identity)?.seat ?? a;
    const bSeat = world.getComponent(b, COMPONENT.Identity)?.seat ?? b;
    return aSeat - bSeat;
  });
}

function positiveLeaders(candidates: EntityId[], tally: Map<EntityId, number>): EntityId[] {
  const maximum = Math.max(0, ...candidates.map((id) => tally.get(id) ?? 0));
  return maximum > 0 ? candidates.filter((id) => (tally.get(id) ?? 0) === maximum) : [];
}

/**
 * 负责请求警长发言方向并形成原座位顺序。输入为 World、存活编号、请求构造依赖与原回复；输出默认顺时针或已校验方向、警长最后的原名单。
 * 未启警长或无警长保原早返回，不读取／创建工厂；有效持徽者之后才独立 new 本次方向工厂。
 * 请求、玩家或网关失败保原异常，方向事实在原回复处理之后发布；此模块不赋警徽、改生命或共享选举工厂。
 */
import { COMPONENT } from "../../../core/domain/components/names";
import { IdentityComponent } from "../../../core/domain/entities/player";
import { ActionProvider, EntityId, GameEvent, Phase } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { ToolGateway } from "../../gateway/tool_gateway";
import type { ActionRequestFactoryConstructorPort } from "../../../core/domain/actions";
import { findSheriffId } from "./badge";

export type SpeakerDirection = "clockwise" | "counter_clockwise";

export async function chooseSpeakerDirection(input: {
  world: World;
  events: GameEvent[];
  toolGateway: ToolGateway;
  actionProvider: ActionProvider;
  day: number;
  enableSheriff: boolean;
  readonly requestFactory: ActionRequestFactoryConstructorPort;
}): Promise<SpeakerDirection> {
  const { world, events, toolGateway, actionProvider, day, enableSheriff } = input;
  const defaultDirection: SpeakerDirection = "clockwise";
  if (!enableSheriff) {
    return defaultDirection;
  }

  const sheriffId = findSheriffId(world);
  if (sheriffId === null) {
    return defaultDirection;
  }

  let finalDirection: SpeakerDirection = defaultDirection;
  // 构造器 getter 到原 new 点才读取，default／无持徽者路径不触及它。
  const requests = new input.requestFactory(world, events, day);
  const req = requests.create({
    phase: Phase.Day,
    actorId: sheriffId,
    allowedTools: ["choose_direction"],
    stage: "sheriff_choose_direction",
    requiresAction: true,
    summary: { key: "request.summary.sheriff_direction" },
    context: {},
  });
  const action = await actionProvider.getAction(req);
  if (action?.name === "choose_direction") {
    const result = toolGateway.validateAndSanitize(world, sheriffId, action, {
      phase: Phase.Day,
    });
    if (result.ok && result.sanitizedCall) {
      finalDirection = result.sanitizedCall.args.direction;
    }
  }

  events.push({
    timestamp: Date.now(),
    type: "sheriff_direction_chosen",
    payload: {
      sheriffId,
      direction: finalDirection,
    },
  });

  return finalDirection;
}

export function buildSpeakerOrder(
  world: World,
  aliveIds: EntityId[],
  sheriffId: EntityId | null,
  direction: SpeakerDirection,
): EntityId[] {
  if (sheriffId === null) {
    return [...aliveIds];
  }

  // 按原读取点固定座位，警长最后；这里只生成顺序副本，不写座位或警徽。
  const seatMap = new Map<EntityId, number>();
  for (const id of aliveIds) {
    const identity = world.getComponent(id, COMPONENT.Identity);
    seatMap.set(id, identity?.seat ?? id);
  }

  const orderedBySeat = [...aliveIds].sort((a, b) => (seatMap.get(a) ?? a) - (seatMap.get(b) ?? b));
  const sheriffIndex = orderedBySeat.indexOf(sheriffId);
  if (sheriffIndex < 0) {
    return orderedBySeat;
  }

  if (direction === "clockwise") {
    return [...orderedBySeat.slice(sheriffIndex + 1), ...orderedBySeat.slice(0, sheriffIndex + 1)];
  }

  const counterClockwise: EntityId[] = [];
  for (let i = sheriffIndex - 1; i >= 0; i--) {
    counterClockwise.push(orderedBySeat[i]);
  }
  for (let i = orderedBySeat.length - 1; i > sheriffIndex; i--) {
    counterClockwise.push(orderedBySeat[i]);
  }
  counterClockwise.push(sheriffId);
  return counterClockwise;
}

/**
 * 负责按当前警徽和候选资格校验方向及接徽选择。输入为已清洗工具和可信警徽上下文，输出原规则拒绝或通过。
 * 本校验不转移、销毁或重新生成警徽，实际写入仍归警徽所有者。
 */
import { RuleError } from "@ai-werewolf-arena/game-contract";
/** 文件说明：警长机制工具校验规则。 */
import { Phase } from "../../../core/domain/model";
import { COMPONENT } from "../../../core/domain/components/names";
import { ToolRuleMap } from "../validation/contracts";
import { canBeSheriff, canVote } from "../common/participation";

/** 警长机制工具校验规则集合。 */
export const SHERIFF_VALIDATION_RULES: ToolRuleMap = {
  choose_badge_successor: ({ world, actorId, toolCall, badgeCandidates, roleCatalog }) => {
    const badge = world.getComponent(actorId, COMPONENT.Badge);
    if (!badge?.isSheriff || badge.destroyed || badge.handoffPolicy !== "awa_holder_choice_v1")
      return { code: RuleError.BadgeChoiceUnavailable };
    const target = toolCall.args as { target_id?: unknown };
    if (target.target_id === null) return null;
    if (
      !Number.isSafeInteger(target.target_id) ||
      !badgeCandidates?.includes(target.target_id as number) ||
      !canBeSheriff(world, target.target_id as number, roleCatalog) ||
      world.getComponent(target.target_id as number, COMPONENT.Badge)?.destroyed !== false
    )
      return { code: RuleError.BadgeChoiceTarget };
    return null;
  },
  run_for_sheriff: ({ world, actorId, phase, toolCall, roleCatalog }) => {
    if (phase !== Phase.Day) {
      return { code: RuleError.SheriffNominationPhase };
    }
    const args = toolCall.args as { run?: unknown };
    if (typeof args.run !== "boolean") {
      return { code: RuleError.SheriffRunBoolean };
    }
    if (!canBeSheriff(world, actorId, roleCatalog))
      return { code: RuleError.SheriffNominationEligibility };
    return null;
  },
  vote_for_sheriff: ({ world, actorId, phase, toolCall, roleCatalog, sheriffCandidates }) => {
    if (phase !== Phase.Day) {
      return { code: RuleError.SheriffVotePhase };
    }
    if (!canVote(world, actorId, roleCatalog) || sheriffCandidates?.includes(actorId))
      return { code: RuleError.SheriffVoteEligibility };
    const args = toolCall.args as { abstain?: unknown; target_id?: unknown };
    const abstain = Boolean(args.abstain);
    const targetId = args.target_id;
    if (abstain) {
      if (targetId !== null) {
        return { code: RuleError.AbstainTargetNull };
      }
      return null;
    }
    if (
      typeof targetId !== "number" ||
      !Number.isFinite(targetId) ||
      targetId <= 0 ||
      !sheriffCandidates?.includes(targetId) ||
      !canBeSheriff(world, targetId, roleCatalog)
    ) {
      return { code: RuleError.SheriffVoteTarget };
    }
    return null;
  },
  choose_direction: ({ world, actorId, phase, roleCatalog }) => {
    const badge = world.getComponent(actorId, COMPONENT.Badge);
    if (!badge?.isSheriff || badge.destroyed || !canBeSheriff(world, actorId, roleCatalog)) {
      return { code: RuleError.SheriffDirectionOnly };
    }
    if (phase !== Phase.Day) {
      return { code: RuleError.SheriffDirectionPhase };
    }
    return null;
  },
};

/**
 * 负责流水线与 handler 共享的夜间状态及执行端口契约。
