/**
 * 负责角色工具校验契约和存活目标查询。输入为可信 World／上下文与候选 ID，输出描述规则结果及生命资格。
 * 这些结构不保存第二份运行授权，也不执行提交的工具或付款。
 */
import type { RuleViolation } from "@ai-werewolf-arena/game-contract";
/** 文件说明：工具校验规则契约定义。 */
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionWindow, EntityId, Phase, ToolCall, ToolName } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import type { RoleCatalog } from "../roles/catalog";

/** 单次工具校验上下文。 */
export interface ValidationRuleContext {
  day?: number;
  thiefScope?: object;
  shapeshifterScope?: object;
  wildChildScope?: object;
  lonelyGirlScope?: object;
  ghostBrideScope?: object;
  demonHunterScope?: object;
  nobleBodyScope?: object;
  fragrantPairScope?: object;
  animalScope?: object;
  wallScope?: object;
  wallId?: string;
  itemInstanceId?: string;
  debateId?: string;
  abilityId?: string;
  roleCatalog: RoleCatalog;
  world: World;
  actorId: EntityId;
  role: RoleComponent;
  toolCall: ToolCall;
  phase: Phase;
  actionWindow?: ActionWindow;
  allowSelfDestruct?: boolean;
  duelWindow?: import("../../../core/domain/identity").KnightDuelWindow;
  allowKnightDuel?: boolean;
  sheriffCandidates?: readonly EntityId[];
  badgeCandidates?: readonly EntityId[];
  exileCandidates?: readonly EntityId[];
}

/** 工具校验规则函数签名。 */
export type ToolRule = (ctx: ValidationRuleContext) => RuleViolation | string | null;

/** 判断目标玩家是否存活。 */
export function isAliveTarget(world: World, targetId: EntityId): boolean {
  const alive = world.getComponent(targetId, COMPONENT.Alive);
  return alive?.alive === true;
}

/** 工具名到校验规则的映射表。 */
export type ToolRuleMap = Partial<Record<ToolName, ToolRule>>;

/**
 * 负责聚合通用、警长和角色运行校验贡献。输入为原上下文与工具调用；输出为首个规则拒绝或 null。
 * 有来源赠枪保留专属校验，普通角色在原时点读取当前规则；不提交动作、付款或执行结算。
 */
import { RuleError, type RuleViolation } from "@ai-werewolf-arena/game-contract";
import { ToolName } from "../../../core/domain/model";
import { COMMON_VALIDATION_RULES } from "../common/validation_rules";
import { RoleCatalog } from "../roles/catalog";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { SHERIFF_VALIDATION_RULES } from "../sheriff/validation_rules";
import { ToolRuleMap, ValidationRuleContext } from "./contracts";
import { validateGiftGun } from "../roles/death_abilities";

function buildDefaultRules(roleProfileRegistry: RoleCatalog): ToolRuleMap {
  const rules: ToolRuleMap = {
    ...COMMON_VALIDATION_RULES,
    ...SHERIFF_VALIDATION_RULES,
  };
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.validationRules) {
      Object.assign(rules, profile.validationRules);
    }
  }
  return rules;
}

/** 工具校验规则注册表。 */
export class ToolValidationRuleRegistry {
  private readonly rules: ToolRuleMap;
  private readonly useProfileRules: boolean;

  constructor(
    rules?: ToolRuleMap,
    private readonly roleProfileRegistry: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    this.rules = { ...(rules ?? buildDefaultRules(roleProfileRegistry)) };
    this.useProfileRules = rules === undefined;
  }

  validate(ctx: Omit<ValidationRuleContext, "roleCatalog">): RuleViolation | null {
    if (this.useProfileRules && ctx.toolCall.name === "shoot" && ctx.abilityId !== undefined)
      return validateGiftGun({ ...ctx, roleCatalog: this.roleProfileRegistry });
    // 同名工具可以归不同角色库存；在原调用点按当前角色读取规则，不能只靠全局索引授权。
    const rule =
      (this.useProfileRules
        ? this.roleProfileRegistry.runtime(ctx.role.role)?.validationRules?.[ctx.toolCall.name]
        : undefined) ?? this.rules[ctx.toolCall.name as ToolName];
    if (!rule) {
      return { code: RuleError.UnknownTool };
    }
    const result = rule({ ...ctx, roleCatalog: this.roleProfileRegistry });
    return !result
      ? null
      : typeof result === "string"
        ? { code: RuleError.CustomRuleError, message: result }
        : result;
  }
}

let defaultRegistry: ToolValidationRuleRegistry | null = null;

/** 获取默认工具校验规则注册表实例。 */
export function getDefaultToolValidationRuleRegistry(): ToolValidationRuleRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ToolValidationRuleRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责胜利条件规格的数据契约。结构包含条件 ID、可选检查点与原评估函数，输入为 World／检查点，输出为判定或 null。
 * 规格由注册表装配和持有，契约声明不存储另一份结果、不修改生命或决定阶段推进。
 */
import type { VictoryCheckpoint } from "@ai-werewolf-arena/game-contract";
/** 文件说明：胜利条件规格契约。 */
import { WinDecision, WinCondition } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";

/** 单个胜利条件规格定义。 */
export interface WinConditionSpec {
  id: WinCondition;
  checkpoints?: readonly VictoryCheckpoint[];
  evaluate: (world: World, checkpoint?: VictoryCheckpoint) => WinDecision | null;
}

/**
 * 负责按真实存活阵营统计定义配置的淘汰条件。输入为 World 与胜负配置；
 * 输出为屠城、屠边、狼半及既有特殊分支的候选结果，按原先后读取实际 Camp／角色元数据。
 * 配置工厂只替换两种淘汰条件的 evaluate，不修改缓存默认数组；未匹配规格保原引用。
 * 不封盘或执行死亡，判胜时点、关系领域和唯一终态仍由原 owner／引擎维护。
 */
import { ELIMINATION_PRIORITIES, type EliminationPriority } from "../../../core/domain/board";
import { demonHunterIsGod } from "../roles/demon_hunter/authority";
import { weddingFactionResult } from "../roles/ghost_bride/authority";
/** 文件说明：内置胜利条件规格实现。 */
import { cupidCityDecision } from "../roles/cupid/victory";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { Camp, type WinDecision, WinCondition } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { WinConditionSpec } from "./contracts";
import { victoryDecision } from "./results";

/** 只统计真实存活Camp；good再按角色元数据／Demon规则区分god和villager，成员归属不等于真实Camp。 */
interface AliveStat {
  wolves: number;
  gods: number;
  villagers: number;
  good: number;
}

function statAlive(world: World): AliveStat {
  const stat: AliveStat = {
    wolves: 0,
    gods: 0,
    villagers: 0,
    good: 0,
  };

  for (const id of world.getAliveEntityIds()) {
    const roleComp = world.getComponent(id, COMPONENT.Role);
    if (!roleComp) {
      continue;
    }

    // 两阵营分支各在原比较点晚读唯一Camp，缺失不以角色资料补成默认阵营。
    if (world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf) {
      stat.wolves += 1;
      continue;
    }

    if (world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Good) {
      stat.good += 1;
      const profile = getDefaultRoleCatalog().metadata(roleComp.role);
      if (profile?.goodSide === "god" || demonHunterIsGod(world, roleComp)) stat.gods += 1;
      else if (profile?.goodSide === "villager") stat.villagers += 1;
    }
  }

  return stat;
}

function evaluateSlaughterCity(
  world: World,
  priority: EliminationPriority = "awa_good_priority_v1",
): WinDecision | null {
  const cupid = cupidCityDecision(world);
  if (cupid) return cupid.decision;
  const stat = statAlive(world);
  if (priority === "awa_wolf_priority_v1" && stat.good === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "all_good_eliminated");
  }
  if (stat.wolves === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Good }, "all_wolves_eliminated");
  }
  if (stat.good === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "all_good_eliminated");
  }
  return null;
}

function evaluateSlaughterSide(
  world: World,
  priority: EliminationPriority = "awa_good_priority_v1",
): WinDecision | null {
  const stat = statAlive(world);
  if (priority === "awa_wolf_priority_v1" && (stat.gods === 0 || stat.villagers === 0)) {
    return victoryDecision(
      world,
      { kind: "faction", faction: Camp.Wolf },
      "slaughter_side_completed",
    );
  }
  if (stat.wolves === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Good }, "all_wolves_eliminated");
  }
  if (stat.gods === 0 || stat.villagers === 0) {
    return victoryDecision(
      world,
      { kind: "faction", faction: Camp.Wolf },
      "slaughter_side_completed",
    );
  }
  return null;
}

function evaluateWolfReachHalf(world: World): WinDecision | null {
  const stat = statAlive(world);
  if (stat.wolves === 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Good }, "all_wolves_eliminated");
  }
  if (stat.wolves >= stat.good && stat.good > 0) {
    return victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "wolves_reach_half");
  }
  return null;
}

/** 默认胜利条件规格集合。 */
export const DEFAULT_WIN_CONDITION_SPECS: WinConditionSpec[] = [
  {
    id: WinCondition.ThreeFactionsElimination,
    checkpoints: ["night_settled", "exile_settled", "day_interrupted"],
    evaluate: (world) => {
      const result = weddingFactionResult(world);
      if (!result) return null;
      return result.faction === null
        ? { winner: null, reason: "three_factions_all_dead", outcome: { kind: "no_winner" } }
        : victoryDecision(
            world,
            { kind: "faction", faction: result.faction },
            "three_factions_eliminated",
          );
    },
  },
  {
    id: WinCondition.SlaughterCity,
    evaluate: (world) => evaluateSlaughterCity(world),
  },
  {
    id: WinCondition.SlaughterSide,
    evaluate: (world) => evaluateSlaughterSide(world),
  },
  {
    id: WinCondition.WolfReachHalf,
    evaluate: evaluateWolfReachHalf,
  },
];

/** 创建每局淘汰政策规格，不改缓存默认数组；只替换两项对象，其他项保原引用，结果并未深冻结。 */
export function createEliminationWinConditionSpecs(
  priority: EliminationPriority,
): WinConditionSpec[] {
  if (!ELIMINATION_PRIORITIES.includes(priority)) throw new Error("elimination_priority_invalid");
  return DEFAULT_WIN_CONDITION_SPECS.map((spec) => {
    if (spec.id === WinCondition.SlaughterCity)
      return { ...spec, evaluate: (world: World) => evaluateSlaughterCity(world, priority) };
    if (spec.id === WinCondition.SlaughterSide)
      return { ...spec, evaluate: (world: World) => evaluateSlaughterSide(world, priority) };
    return spec;
  });
}

/**
 * 负责把已接受的胜利判定投影成结构化结果。输入为当前胜利归属、已判目标与原因，输出保留获胜成员和 claim 数据。
 * 本模块不重新选择屠边政策、不修改玩家组件；判胜仍由原胜利条件与检查点负责。
 */
import type { GameOutcome, VictoryClaim, VictoryTarget } from "@ai-werewolf-arena/game-contract";
import { COMPONENT, type WinDecision, type World } from "../../../core/domain";
import type { VictoryComponent } from "../../../core/domain/components/victory";
import { readGameOutcome } from "@ai-werewolf-arena/replay-contract";

/** 成员来自明确 Victory 组件，不根据角色或真实阵营推断。 */
export function victoryDecision(
  world: World,
  primary: VictoryTarget,
  reason: string,
  additional: readonly VictoryTarget[] = [],
): WinDecision {
  const claim = (target: VictoryTarget): VictoryClaim => {
    const winningPlayerIds = world.entityIds().filter((id) => {
      if (target.kind === "individual" && id !== target.playerId) return false;
      return (
        world
          .getComponent(id, COMPONENT.Victory)
          ?.affiliations.some(
            (member) =>
              (target.kind === "faction" &&
                member.kind === "faction" &&
                target.faction === member.faction) ||
              (target.kind === "individual" &&
                member.kind === "individual" &&
                target.goalId === member.goalId) ||
              (target.kind === "relationship" &&
                member.kind === "relationship" &&
                target.groupId === member.groupId),
          ) === true
      );
    });
    if (target.kind !== "faction" && winningPlayerIds.length === 0)
      throw new Error("victory_target_has_no_members");
    return { ...target, winningPlayerIds };
  };
  const first = claim(primary),
    others = additional.map(claim);
  const outcome: GameOutcome = {
    kind: "victory",
    primary: first,
    additional: others,
    winningPlayerIds: [
      ...new Set([first, ...others].flatMap((item) => item.winningPlayerIds)),
    ].sort((a, b) => a - b),
  };
  if (typeof reason !== "string" || reason.length === 0) throw new Error("victory_reason_invalid");
  return {
    winner: primary.kind === "faction" ? (primary.faction as WinDecision["winner"]) : null,
    reason,
    outcome: readGameOutcome(outcome, world.entityIds()),
  };
}

/**
 * 负责终局候选的完整结构、胜利成员和决定时点校验，输入为候选与当前世界／日期的晚读端口。
 * 输出为已核对的 winner、outcome 和 decidedAt 数据；不选择胜负规则、不写入终局或发布事件。
 * 成员按独立 Victory 归属重建，不由角色或实际阵营猜测；单人、关系及附加胜利保原顺序。
 * 结构拒绝、赢家／理由拒绝、成员拒绝、时点拒绝依次发生；调用方仍拥有必要死亡链及唯一封盘。
 */
import type {
  Camp,
  GameOutcome,
  Phase,
  VictoryCheckpoint,
  VictoryPoint,
  WinDecision,
} from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../core/domain/world";
import { readGameOutcome, readVictoryPoint } from "@ai-werewolf-arena/replay-contract";
import { victoryDecision } from "./results";

/** 校验结果尚未封盘；它不携带资源／行动权限，也不替代引擎的当前终态检查。 */
export interface ValidatedVictoryDecision {
  readonly winner: Camp | null;
  readonly outcome: GameOutcome;
  readonly decidedAt: VictoryPoint;
}

export function validateVictoryDecision(
  decision: WinDecision,
  checkpoint: VictoryCheckpoint,
  phase: Phase,
  world: () => World,
  day: () => number,
): ValidatedVictoryDecision {
  const outcome = readGameOutcome(decision.outcome, world().entityIds());
  const winner =
    outcome.kind === "victory" && outcome.primary.kind === "faction"
      ? (outcome.primary.faction as Camp)
      : null;
  if (
    winner !== decision.winner ||
    typeof decision.reason !== "string" ||
    decision.reason.length === 0
  )
    throw new Error("game_result_invalid");
  if (outcome.kind === "victory") {
    const targets = [outcome.primary, ...outcome.additional].map(
      ({ winningPlayerIds: _ids, ...target }) => target,
    );
    const expected = victoryDecision(
      world(),
      targets[0],
      decision.reason,
      targets.slice(1),
    ).outcome;
    if (JSON.stringify(expected) !== JSON.stringify(outcome))
      throw new Error("game_result_membership_invalid");
  }
  // 日期只在所有成员检查通过后读取，校验失败不提前观察或改写阶段状态。
  const decidedAt = readVictoryPoint({ day: day(), phase, checkpoint });
  return { winner, outcome, decidedAt };
}

/**
 * 负责公开组件展示的实际工厂装配与读取。输入为原工厂参数、组件和显示语言；输出
 * 保持原组件引用、原默认语言及 getter／方法的顺序。唯一 WeakMap 只保存语言绑定，
 * 不复制库存；领域不携带文案方法。原生印记先计数，非空才调用原 values 并逐项格式化，
 * 所有失败保留已读取前缀。提示不授予行动或修改状态。
 */
import type { Camp, Locale } from "@ai-werewolf-arena/game-contract";
import { formatComponentPart } from "@ai-werewolf-arena/game-presentation";
import { createAliveComponent as createAliveData, type AliveComponent } from "../../core/domain/components/alive";
import { createBadgeComponent as createBadgeData, type BadgeComponent } from "../../core/domain/components/badge";
import { createCampComponent as createCampData, type CampComponent } from "../../core/domain/components/camp";
import { createVotingRightComponent as createVotingData, type VotingRightComponent } from "../../core/domain/components/voting_right";
import { createStatusMarksComponent as createMarksData, statusMarksSize, type StatusMarksComponent } from "../../core/domain/components/status_marks";

const displayLocales = new WeakMap<object, Locale>();
function bindLocale<T extends object>(component: T, locale: Locale): T {
  displayLocales.set(component, locale);
  return component;
}
function localeOf(component: object, locale: Locale | undefined): Locale {
  return locale === undefined
    ? (displayLocales.has(component) ? displayLocales.get(component)! : "zh-CN")
    : locale;
}

export function createAliveComponent(alive: boolean = true, locale: Locale = "zh-CN"): AliveComponent {
  return bindLocale(createAliveData(alive), locale);
}
export function createBadgeComponent(isSheriff: boolean = false, destroyed: boolean = false, locale: Locale = "zh-CN"): BadgeComponent {
  return bindLocale(createBadgeData(isSheriff, destroyed), locale);
}
export function createCampComponent(camp: Camp, locale: Locale = "zh-CN"): CampComponent {
  return bindLocale(createCampData(camp), locale);
}
export function createVotingRightComponent(weight: number = 1, canVote: boolean = true, locale: Locale = "zh-CN"): VotingRightComponent {
  return bindLocale(createVotingData(weight, canVote), locale);
}
export function createStatusMarksComponent(locale: Locale = "zh-CN"): StatusMarksComponent {
  return bindLocale(createMarksData(), locale);
}

export function renderAlivePrompt(component: AliveComponent, locale?: Locale): string {
  const currentLocale = localeOf(component, locale);
  return formatComponentPart({ kind: "alive", alive: component.alive }, currentLocale);
}
export function renderCampPrompt(component: CampComponent, locale?: Locale): string {
  const currentLocale = localeOf(component, locale);
  return formatComponentPart({ kind: "camp", camp: component.camp }, currentLocale);
}
export function renderBadgePrompt(component: BadgeComponent, locale?: Locale): string {
  const currentLocale = localeOf(component, locale);
  if (component.destroyed) return formatComponentPart({ kind: "badge-destroyed" }, currentLocale);
  if (component.isSheriff)
    return formatComponentPart({ kind: "badge-held", weight: component.voteWeight }, currentLocale);
  return formatComponentPart({ kind: "badge-none" }, currentLocale);
}
export function renderVotingRightPrompt(component: VotingRightComponent, locale?: Locale): string {
  const currentLocale = localeOf(component, locale);
  if (!component.canVote) return formatComponentPart({ kind: "vote-none" }, currentLocale);
  return formatComponentPart({ kind: "vote-weight", weight: component.weight }, currentLocale);
}
export function renderStatusMarksPrompt(component: StatusMarksComponent, locale?: Locale): string {
  const currentLocale = localeOf(component, locale);
  if (statusMarksSize(component) === 0)
    return formatComponentPart({ kind: "marks-none" }, currentLocale);
  return formatComponentPart({
    kind: "marks",
    marks: component.values()
      .map((mark) => formatComponentPart({ kind: "mark", mark }, currentLocale))
      .join(" "),
  }, currentLocale);
}

