/**
 * 负责夜能力来源披露、七类 payload 裁剪和完整玩家能力 DTO。输入为原只读实例与明确日次，
 * 输出保持原字段／getter顺序的独立数据；来源未披露时仅返回 kind，不读取隐藏身份字段。
 * projectNightState 同时供黑市转移的复制与完整性检查使用，不能当作安装／付款或行动许可。
 * Pair 规范化、disabled 查询与 status 仍归能力／数据所有者；不复制规则、缓存字段、写库存，
 * 首个读取／投影错误保留调用前缀，不代替原生命、来源、阶段和租约复验。
 */
import type { AbilitySource, NightAbilityKind } from "@ai-werewolf-arena/game-contract";
import type {
  PlayerNightAbilityStates,
  PlayerNightAbility,
} from "@ai-werewolf-arena/game-contract/night-ability-views";
import type { EventPayloadMap } from "../../core/domain/model";
import {
  abilityStatus,
  nightAbilityDisabled,
  projectPairState,
  type NightAbilityReadView,
} from "../mechanisms/roles/abilities";
import { projectShelterState } from "../mechanisms/roles/radiant_eclipse/shelter-state";
import {
  projectDreamerState,
  projectGuardState,
  projectRoleInspectionState,
  projectSeerState,
  projectWitchState,
} from "../mechanisms/roles/player_state";

export function projectAbilitySource(
  origin: EventPayloadMap["ability_changed"]["source"],
  disclosed: boolean,
): EventPayloadMap["ability_changed"]["source"] | { kind: AbilitySource["kind"] } {
  return !disclosed
    ? { kind: origin.kind }
    : origin.kind === "native"
      ? { kind: origin.kind, role: origin.role }
      : origin.kind === "gift"
        ? { kind: origin.kind, actorId: origin.actorId }
        : { kind: origin.kind, actorId: origin.actorId, abilityId: origin.abilityId };
}

export function projectNightState(
  ability: NightAbilityReadView,
): PlayerNightAbilityStates[NightAbilityKind] {
  switch (ability.kind) {
    case "pair_check":
      return projectPairState(ability.state);
    case "shelter":
      return projectShelterState(ability.state);
    case "seer_check":
      return projectSeerState(ability.state);
    case "potion":
      return projectWitchState(ability.state);
    case "role_check":
      return projectRoleInspectionState(ability.state);
    case "guard":
      return projectGuardState(ability.state);
    case "dream":
      return projectDreamerState(ability.state);
  }
}

export function projectNightAbility(
  ability: NightAbilityReadView,
  day: number,
): PlayerNightAbility {
  // 原 metadata 先逐字段形成；disabled 与 status 各自重读，不把这些查询合并成许可快照。
  const metadata = {
    id: ability.id,
    source: projectAbilitySource(ability.source, ability.sourceDisclosed),
    startsOnDay: ability.startsOnDay,
    ...(ability.expiresAfterDay === undefined ? {} : { expiresAfterDay: ability.expiresAfterDay }),
    maxUses: ability.maxUses,
    uses: ability.uses,
    lastUsedDay: ability.lastUsedDay,
    disabled: nightAbilityDisabled(ability),
    ...(ability.activation === undefined ? {} : { activation: ability.activation }),
    ...(ability.deathExpired === undefined ? {} : { deathExpired: ability.deathExpired }),
    status: abilityStatus(ability, day),
  };
  switch (ability.kind) {
    case "pair_check":
      return { ...metadata, kind: "pair_check", state: projectPairState(ability.state) };
    case "shelter":
      return { ...metadata, kind: "shelter", state: projectShelterState(ability.state) };
    case "seer_check":
      return { ...metadata, kind: "seer_check", state: projectSeerState(ability.state) };
    case "potion":
      return { ...metadata, kind: "potion", state: projectWitchState(ability.state) };
    case "role_check":
      return { ...metadata, kind: "role_check", state: projectRoleInspectionState(ability.state) };
    case "guard":
      return { ...metadata, kind: "guard", state: projectGuardState(ability.state) };
    case "dream":
      return { ...metadata, kind: "dream", state: projectDreamerState(ability.state) };
  }
}

/**
 * 负责玩家提示开局公开角色配比的来源选择和完整聚合；输入为原初发牌、板子及角色查询。
 * 输出直接填入调用方已有的配比缓存，盗贼／千面人初发牌优先于板子，旧无板子调用按开局角色统计。
 * 本模块不创建第二份缓存、不选择身份或授予行动许可；公开人数的原先赋值仍由提示策略先完成。
 * 每次板子、角色和缓存查询保留原位置及接收方，失败保留此前已经写入的 Map 前缀，不回滚或补默认值。
 */
import type { EntityId, ReadonlyBoardConfig, Role } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../core/domain/components/role";
import type { World } from "../../core/domain/world";
import { initialIdentityCandidateCounts } from "../mechanisms/roles/initial_identity/deal";

/** 查询在原表达式处执行；缓存仍归调用方，role 查询保留其原方法的 receiver。 */
export interface PlayerInitialPublicCountQueries {
  world(): World;
  boardConfig(): ReadonlyBoardConfig | undefined;
  role(actorId: EntityId): RoleComponent | undefined;
  counts(): Map<Role, number>;
}

/** 填入构造时的公开配比，不读取手牌选择、当前许可或后续角色变化来刷新这份缓存。 */
export function collectPlayerInitialPublicCounts(queries: PlayerInitialPublicCountQueries): void {
  const thiefCounts = initialIdentityCandidateCounts(queries.world());
  if (thiefCounts) {
    for (const [role, count] of thiefCounts) queries.counts().set(role, count);
  } else if (queries.boardConfig()) {
    // 原条件和迭代器各读一次板子；! 只保类型，不把第二次缺失改成静默空配比。
    for (const { role, count } of queries.boardConfig()!.roleSetups) {
      queries.counts().set(role, (queries.counts().get(role) ?? 0) + count);
    }
  } else {
    // 旧无板子调用只在构造时查询；Role 字段在 set、get 参数处分别读取，不能提前缓存。
    for (const id of queries.world().entityIds()) {
      const role = queries.role(id);
      if (role) queries.counts().set(role.role, (queries.counts().get(role.role) ?? 0) + 1);
    }
  }
}

/**
 * 负责完整捕获玩家可获知的身份、机制知识、已发表死亡、行动历史与能力／枪信息。
 * 输入为原请求与按原时点执行的窄查询；输出是原字段集合的脱离冻结 PlayerObservation。
 * World 仅在此游戏侧 adapter 读取，不交给策略；已知存活依发布事实计算，不替换为真实存活名单。
 * 角色和队友方法在 actor 参数之前查找；每个 World 读取保原位置，机制知识／权限仍归各原 owner。
 * 结构观察不提交行动、不克隆完整私有库存，也不提前执行自定义人设或角色展示回调；失败前缀保持。
 */
import { getWhiteWolfKingState, projectWhiteWolfKingState } from "../mechanisms/roles/white_wolf_king/ports";
import { isAnimalDreamBoard } from "../mechanisms/roles/animal_dream/authority";
import {
  animalFoxKnowledge,
  animalPufferKnowledge,
  animalCatKnowledge,
  animalBeautyKnowledge,
  animalBearKnowledge,
} from "../mechanisms/roles/animal_dream/facts";
import {
  isNobleBodyBoard,
  getNobleBodyPlayerState,
} from "../mechanisms/roles/noble_secret_body/authority";
import {
  isFragrantPairBoard,
  fragrantPlayerKnowledge,
} from "../mechanisms/roles/fragrant_pair_seer/authority";
