/** 先保原版本／严格 envelope 准入，再按固定独立装配审核角色与板子；审核不执行游戏规则。 */
export function parseReproductionRecord(value: unknown): ReproductionRecord {
  // 新封装先按显式格式解包，历史裸 Tape 仍走下面原 schema 2／第一失败顺序。
  value = unwrapRecordingEnvelope(value, "strict_reproduction").payload;
  if (
    value &&
    typeof value === "object" &&
    "schemaVersion" in value &&
    value.schemaVersion !== REPRODUCTION_SCHEMA_VERSION
  )
    throw new Error("reproduction_schema_not_supported");
  const parsed = schema.safeParse(value);
  if (!parsed.success) throw new Error("reproduction_record_invalid");
  const result = parsed.data as unknown as ReproductionRecord;
  verifyReproductionMechanisms(result);
  return result;
}

/**
 * 负责单会话事件、玩家回合与诊断的原内存聚合；输入为录制数据，输出为原公开／玩家 schema 2 快照与清单。
 * 本 owner 写局部序号、原文片段、初始提示和操作计数；指定文本受字符上限约束，文件发布和严格身份仍由 manager／档案 codec 拥有。
 * 玩家规范化在原返回前作 canonical2 断言，保 timeline 同引用；不推进游戏或回收资源，序列化外的失败不回滚已发生的聚合前缀。
 */
import { assertReplayPlayerView, readVictoryResult, type CanonicalReplayPlayerView } from "@ai-werewolf-arena/replay-contract";
import { PlayerVisibleEvent } from "../core/domain/model";
import {
  ReplayDebugReport,
  ReplayFinalizeMeta,
  ReplayLlmRequestMessage,
  ReplayLogicOp,
  ReplayManifest,
  ReplayPhaseWindow,
  ReplayPhaseWindowsFile,
  ReplayPlayerDeltaMessage,
  ReplayPlayerEventEntry,
  ReplayPlayerView,
  ReplayPublicEvent,
  ReplayRecordDebugReportInput,
  ReplayRecordLogicOpInput,
  ReplayRecordPlayerEventInput,
  ReplayRecordPlayerRoundInput,
  ReplayRecordPublicEventInput,
  ReplaySessionMeta,
  ReplayTimelineIndexFile,
} from "./contracts";

const THINKING_MAX_CHARS = 4000;
const LLM_MESSAGE_MAX_CHARS = 8000;

function toIso(timestampMs: number): string {
  return new Date(timestampMs).toISOString();
}

/**
 * 原 JSON stringify／parse 复制，执行 getter／toJSON 且沿 JSON 规则丢弃／转换值；任何该过程失败返回普通 sentinel 数据。
 * sentinel 不验证 schema、不授予权限，也不撤回序列化前已经发生的副作用；其他时间转换／聚合调用不在此 catch 内。
 */
export function safeReplayJson(value: unknown): unknown {
  try {
    return JSON.parse(JSON.stringify(value));
  } catch {
    return { non_serializable: true };
  }
}

/** 每行新建并截取 content，按原真值条件保 tool_call_id；不在这里过滤玩家可见性或重写协议历史。 */
function normalizeRequestMessages(
  messages: ReplayLlmRequestMessage[] | undefined,
): ReplayLlmRequestMessage[] | undefined {
  if (!messages?.length) return undefined;
  return messages.map((message) => ({
    role: message.role,
    content: message.content.slice(0, LLM_MESSAGE_MAX_CHARS),
    ...(message.tool_call_id ? { tool_call_id: message.tool_call_id } : {}),
  }));
}

/** 保原行的其余字段引用，只有 content 截取、args／result 经 JSON helper；不是整行深隔离或行动接受验证。 */
function normalizeDeltaMessages(
  messages: ReplayPlayerDeltaMessage[] | undefined,
): ReplayPlayerDeltaMessage[] {
  return (messages ?? []).map((message) => ({
    ...message,
    ...(message.content ? { content: message.content.slice(0, LLM_MESSAGE_MAX_CHARS) } : {}),
    ...(message.args !== undefined
      ? { args: safeReplayJson(message.args) as Record<string, unknown> }
      : {}),
    ...(message.result !== undefined
      ? { result: safeReplayJson(message.result) as Record<string, unknown> | string }
      : {}),
  }));
}

/** 同一会话的内存聚合与投影边界；各序列只在自己的记录点追加，刷盘／关闭与严格归档仍归外层管理器。 */
export class ReplaySessionAggregate {
  private reproductionEnabled = false;

  enableReproduction(): void {
    this.reproductionEnabled = true;
  }
  // 公共事件与逻辑操作各有独立计数器；玩家 timeline 另用自身长度，turn_seq 又只计 turn，不能互换证据序号。
  private publicSeq = 0;
  private logicSeq = 0;
  private readonly publicEvents: ReplayPublicEvent[] = [];
  private readonly logicOps: ReplayLogicOp[] = [];
  private readonly debugReports: ReplayDebugReport[] = [];
  private readonly playerViews = new Map<number, ReplayPlayerView>();

  constructor(readonly sessionMeta: ReplaySessionMeta) {}

  // seq 先递增，再转换 timestamp／payload；时间转换等未捕获失败可消耗序号而尚未 append，不在这里补偿。
  recordPublicEvent(input: ReplayRecordPublicEventInput): void {
    this.publicEvents.push({
      seq: ++this.publicSeq,
      timestamp: toIso(input.timestampMs),
      phase: input.phase,
      day: input.day,
      ...(input.stage ? { stage: input.stage } : {}),
      type: input.type,
      payload: safeReplayJson(input.payload) as Record<string, unknown>,
    });
  }

  // 逻辑 seq 独立追加，event_count 仅保调用方传入的因果位置，不据此重新排序公开事件。
  recordLogicOp(input: ReplayRecordLogicOpInput): void {
    this.logicOps.push({
      seq: ++this.logicSeq,
      timestamp: toIso(Date.now()),
      scope: input.scope,
      op: input.op,
      ...(input.eventCount !== undefined ? { event_count: input.eventCount } : {}),
      ...(input.actorId !== undefined ? { actor_id: input.actorId } : {}),
      ...(input.phase ? { phase: input.phase } : {}),
      ...(input.input ? { input: safeReplayJson(input.input) as Record<string, unknown> } : {}),
      ...(input.output ? { output: safeReplayJson(input.output) as Record<string, unknown> } : {}),
      status: input.status,
      ...(input.reason ? { reason: input.reason } : {}),
    });
  }

  /**
   * 先取得／登记玩家 view，尚无初始提示才记录；之后规范化或派生消息再追加 turn，已有 view／提示不因后续抛错回滚。
   * 仅 delta 为空时派生默认消息；显式 delta 不被默认轨迹覆盖，turn_seq 与混合 event/turn 的局部 seq 分开。
   */
  recordPlayerRound(input: ReplayRecordPlayerRoundInput): void {
    const view = this.ensurePlayerView(input.playerId, input.role, input.camp);
    if (!view.initial_prompt) {
      view.initial_prompt = {
        day: input.day,
        phase: input.phase,
        stage: input.stage,
        request_id: input.requestId,
        timestamp: toIso(input.timestampMs ?? Date.now()),
        ...(input.initialPromptSystem
          ? { prompt_system: input.initialPromptSystem }
          : input.promptSystem
            ? { prompt_system: input.promptSystem }
            : {}),
        ...(input.initialBoardInfo ? { board_info: input.initialBoardInfo } : {}),
        ...(input.promptUserDelta ? { prompt_user: [...input.promptUserDelta] } : {}),
      };
    }
    const requestMessages = normalizeRequestMessages(input.llmRequestMessages);
    const thinkingText = input.thinkingText?.slice(0, THINKING_MAX_CHARS);
    const deltaMessages = normalizeDeltaMessages(input.deltaMessages);
    if (deltaMessages.length === 0) {
      this.deriveRoundDeltaMessages(deltaMessages, input, requestMessages, thinkingText);
    }
    view.timeline.push({
      seq: view.timeline.length + 1,
      kind: "turn",
      day: input.day,
      phase: input.phase,
      stage: input.stage,
      request_id: input.requestId,
      timestamp: toIso(input.timestampMs ?? Date.now()),
      turn_seq: view.timeline.filter((entry) => entry.kind === "turn").length + 1,
      delta_messages: deltaMessages,
    });
  }

  // source_event_seq 是可选公共来源关联；entry.seq 仍为该玩家自己的混合时间线位置，不在此重新检查可见性。
  recordPlayerEvent(input: ReplayRecordPlayerEventInput): void {
    const view = this.ensurePlayerView(input.playerId, input.role, input.camp);
    const entry: ReplayPlayerEventEntry = {
      seq: view.timeline.length + 1,
      kind: "event",
      day: input.day,
      phase: input.phase,
      stage: input.stage,
      request_id: input.requestId,
      timestamp: toIso(input.timestampMs ?? Date.now()),
      ...(input.sourceEventSeq === undefined ? {} : { source_event_seq: input.sourceEventSeq }),
      event: safeReplayJson(input.event) as unknown as PlayerVisibleEvent,
    };
    view.timeline.push(entry);
  }

  // 报告 ID 来自当前报告数量；证据数组浅复制、message 保原文，不在聚合点把上报判断为已确认 bug。
  recordDebugReport(input: ReplayRecordDebugReportInput): string {
    const reportId = `rb-${this.sessionMeta.sessionId}-${this.debugReports.length + 1}`;
    this.debugReports.push({
      report_id: reportId,
      timestamp: toIso(input.timestampMs ?? Date.now()),
      day: input.day,
      phase: input.phase,
      stage: input.stage,
      actor_id: input.actorId,
      actor_role: input.actorRole,
      actor_camp: input.actorCamp,
      category: input.category,
      severity: input.severity,
      message: input.message,
      evidence_event_seq: [...(input.evidenceEventSeq ?? [])],
      status: "open",
    });
    return reportId;
  }

  // 这些 payload 只新建外层包装，事件／操作／报告数组仍属同一聚合，不是深快照或冻结结果。
  publicTimelinePayload() {
    return { events: this.publicEvents };
  }
  logicOpsPayload() {
    return { ops: this.logicOps };
  }
  debugReportsPayload() {
    return {
      session_id: this.sessionMeta.sessionId,
      generated_at: new Date().toISOString(),
      reports: this.debugReports,
    };
  }
  playerIds(): number[] {
    return [...this.playerViews.keys()].sort((a, b) => a - b);
  }
  playerFiles(): string[] {
    return this.playerIds().map((id) => `players/player_${id}.json`);
  }
  normalizedPlayerView(playerId: number): CanonicalReplayPlayerView | undefined {
    const view = this.playerViews.get(playerId);
    return view ? this.normalizePlayerView(view) : undefined;
  }
  normalizedPlayerViews(): CanonicalReplayPlayerView[] {
    return this.playerIds().map((id) => this.normalizedPlayerView(id)!);
  }
  /** 只按原 scope 排除 llm_action_provider；这是本聚合的操作计数，不校验或复演每条业务因果。 */
  get reproductionOperationCount(): number {
    return this.logicOps.filter((op) => op.scope !== "llm_action_provider").length;
  }
  debugSummaryInput() {
    return {
      reports: this.debugReports,
      publicEvents: this.publicEvents,
      logicOps: this.logicOps,
      playerViews: this.normalizedPlayerViews(),
    };
  }

  // 先由原结果 reader 校验 decision 与成员，再比 winner；失败不生成清单，成功仍沿原默认时间和文件声明。
  buildManifest(meta?: ReplayFinalizeMeta): ReplayManifest {
    const decision =
      meta?.gameResult === undefined
        ? undefined
        : readVictoryResult(
            meta.gameResult,
            meta.players.map((player) => player.player_id),
          );
    if (decision && decision.winner !== meta?.winner)
      throw new Error("replay_result_winner_mismatch");
    return {
      session_id: this.sessionMeta.sessionId,
      board: this.sessionMeta.board,
      ...(this.sessionMeta.locale === undefined ? {} : { locale: this.sessionMeta.locale }),
      ...(this.sessionMeta.random ? { random: this.sessionMeta.random } : {}),
      started_at: this.sessionMeta.startedAtIso,
      ended_at: meta?.endedAtIso ?? this.sessionMeta.startedAtIso,
      winner: meta?.winner ?? null,
      finish_reason: meta?.finishReason ?? "in_progress",
      ...(decision ? { game_result: decision as ReplayManifest["game_result"] } : {}),
      players: meta?.players ?? [],
      files: {
        ...(this.reproductionEnabled ? { reproduction: "reproduction.json" } : {}),
        replay: "replay.json",
        phase_windows: "phase_windows.json",
        timeline_index: "timeline_index.json",
        logic_ops: "logic_ops.json",
        debug_reports: "debug_reports.json",
        debug_summary: "debug_summary.md",
        player_views: this.playerFiles(),
      },
    };
  }

  /** 按现有事件顺序合并连续同 day／phase 及 stage；不排序，不把同名但分离的窗口全局合并。 */
  phaseWindowsPayload(): ReplayPhaseWindowsFile {
    const windows: ReplayPhaseWindow[] = [];
    let current: ReplayPhaseWindow | null = null;
    for (const event of this.publicEvents) {
      const day = Number(event.day);
      const phase = String(event.phase);
      const seq = Number(event.seq);
      const stage = String(event.stage ?? event.type ?? "unknown");
      if (!current || current.day !== day || current.phase !== phase) {
        if (current) windows.push(current);
        current = {
          phase_id: `d${day}-${phase}`,
          day,
          phase,
          start_seq: seq,
          end_seq: seq,
          stages: [{ stage, start_seq: seq, end_seq: seq }],
        };
      } else {
        current.end_seq = seq;
        const last = current.stages.at(-1);
        if (last?.stage === stage) last.end_seq = seq;
        else current.stages.push({ stage, start_seq: seq, end_seq: seq });
      }
    }
    if (current) windows.push(current);
    return { session_id: this.sessionMeta.sessionId, windows };
  }

  /** 公开 min/max 用实际首尾 seq；玩家只报各自 timeline 数量，阶段数量从原窗口投影取得。 */
  timelineIndexPayload(): ReplayTimelineIndexFile {
    const count = this.publicEvents.length;
    const players: ReplayTimelineIndexFile["players"] = {};
    for (const [id, view] of this.playerViews) {
      players[String(id)] = { count: view.timeline.length };
    }
    return {
      session_id: this.sessionMeta.sessionId,
      public: {
        min_seq: count ? this.publicEvents[0].seq : 0,
        max_seq: count ? this.publicEvents.at(-1)!.seq : 0,
        count,
      },
      players,
      phases: { count: this.phaseWindowsPayload().windows.length },
    };
  }

  // 首次创建记录当时的 role／camp，后续原 view 保历史值，不跟随当前角色／阵营变化重写旧玩家文件元数据。
  private ensurePlayerView(playerId: number, role: string, camp: string): ReplayPlayerView {
    const existing = this.playerViews.get(playerId);
    if (existing) return existing;
    const view: ReplayPlayerView = {
      schemaVersion: 2,
      ...(this.sessionMeta.locale === undefined ? {} : { locale: this.sessionMeta.locale }),
      player_id: playerId,
      role,
      camp,
      timeline: [],
    };
    this.playerViews.set(playerId, view);
    return view;
  }

  // 新建 canonical2 包装但 timeline 保原数组；先补派生初始提示再断言，断言失败原样抛，不冻结或重写历史。
  private normalizePlayerView(view: ReplayPlayerView): CanonicalReplayPlayerView {
    const initialPrompt = view.initial_prompt ?? this.deriveInitialPrompt(view);
    const result: ReplayPlayerView = {
      schemaVersion: 2,
      ...(this.sessionMeta.locale === undefined ? {} : { locale: this.sessionMeta.locale }),
      player_id: view.player_id,
      role: view.role,
      camp: view.camp,
      ...(initialPrompt ? { initial_prompt: initialPrompt } : {}),
      timeline: view.timeline,
    };
    assertReplayPlayerView(result);
    return result;
  }

  /** 只从首个 turn 的首条真值 system 消息补提示；没有此消息就保持缺失，不猜测更早模型上下文。 */
  private deriveInitialPrompt(
    view: ReplayPlayerView,
  ): ReplayPlayerView["initial_prompt"] | undefined {
    const firstTurn = view.timeline.find((entry) => entry.kind === "turn");
    if (!firstTurn || firstTurn.kind !== "turn") return undefined;
    const system = firstTurn.delta_messages.find(
      (message) => message.role === "system" && message.content,
    );
    return system?.content
      ? {
          day: firstTurn.day,
          phase: firstTurn.phase,
          stage: firstTurn.stage,
          request_id: firstTurn.request_id,
          ...(firstTurn.timestamp ? { timestamp: firstTurn.timestamp } : {}),
          prompt_system: system.content,
        }
      : undefined;
  }

  /** 按原 prompt→重试／思考→tool call/result→行动摘要→fallback 次序派生；诊断 structuredClone 等未捕获失败保此前 target 前缀。 */
  private deriveRoundDeltaMessages(
    target: ReplayPlayerDeltaMessage[],
    input: ReplayRecordPlayerRoundInput,
    requestMessages: ReplayLlmRequestMessage[] | undefined,
    thinkingText: string | undefined,
  ): void {
    for (const message of requestMessages ?? []) {
      target.push({ role: message.role, kind: "prompt", content: message.content });
    }
    for (const item of input.retryTrace ?? []) {
      if (item.retryPrompt)
        target.push({
          role: "user",
          kind: "retry_prompt",
          attempt: item.attempt,
          content: item.retryPrompt,
        });
      if (item.assistantText)
        target.push({
          role: "assistant",
          kind: "assistant_output",
          attempt: item.attempt,
          content: item.assistantText,
        });
      if (item.reason)
        target.push({
          role: "meta",
          kind: item.status === "request_error" ? "request_error" : "constraint_warning",
          attempt: item.attempt,
          content: item.reason,
          ...(item.diagnostic ? { diagnostic: structuredClone(item.diagnostic) } : {}),
        });
    }
    if (thinkingText)
      target.push({ role: "assistant", kind: "assistant_output", content: thinkingText });
    for (const call of input.toolCalls) {
      target.push({
        role: "assistant",
        kind: "tool_call",
        name: call.name,
        ...(call.args !== undefined
          ? { args: safeReplayJson(call.args) as Record<string, unknown> }
          : {}),
        ...(call.accepted !== undefined ? { accepted: call.accepted } : {}),
      });
      if (call.result !== undefined)
        target.push({
          role: "tool",
          kind: "tool_result",
          name: call.name,
          result: safeReplayJson(call.result) as Record<string, unknown> | string,
        });
    }
    target.push({
      role: "meta",
      kind: "action_summary",
      content: JSON.stringify({
        action_mode: input.actionMode,
        final_action: input.finalAction !== undefined ? safeReplayJson(input.finalAction) : null,
      }),
    });
    if (input.fallback?.used)
      target.push({
        role: "meta",
        kind: "fallback",
        content: JSON.stringify(safeReplayJson(input.fallback)),
      });
  }
}

/**
 * 负责一个会话的复盘聚合、增量文件内容和终结发布；输入为事件、行动记录与结束元数据。
 * 输出为公开复盘、玩家视角和严格复现归档；聚合和存储仍由各自具体模块持有。
 * 生命周期模块唯一拥有定时器、队列、关闭与首次终结 Promise；本管理器保留必需失败账本。
 * 严格前缀写失败即登记，最终发布仍尝试完成；单个失败原样传播，多失败保持原顺序聚合。
 * 此处不控制游戏阶段或资源提交，不把可选诊断写入失败改成游戏错误。
 */
import type { Locale } from "@ai-werewolf-arena/game-text";
import { formatErrorDiagnostic } from "../utils/error_diagnostic";
import path from "path";
import type {
  DebugSummaryInput,
  ReplayFinalizeMeta,
  ReplayRecordDebugReportInput,
  ReplayRecordLogicOpInput,
  ReplayRecordPlayerEventInput,
  ReplayRecordPlayerRoundInput,
  ReplayRecordPublicEventInput,
  ReplaySessionMeta,
} from "./contracts";
import { currentRecordingIdentities, createPublicReplayArchive, createReproductionArchive, createManifestArchive, createPlayerViewArchive } from "./archive_identity";
import { createReplayDocument } from "./replay_document";
import { ReplayFileStore } from "./file_store";
import { ReplaySessionAggregate } from "./session_aggregate";
import { getSessionRecorder } from "./recording_context";
import { type ReproductionFailureScope, type ReproductionMetadata } from "./reproduction";
import { ReproductionTrace } from "./reproduction-trace";
import { SessionRecordingLifecycle } from "./session-recording-lifecycle";

/** 文件内容、严格失败及归档发布的唯一编排者；刷盘排程由具体生命周期实例持有。 */
export class SessionRecordManager {
  private readonly lifecycle = new SessionRecordingLifecycle(
    () => this.flushDirtyFiles(),
    (error) => {
      console.warn(
        `[observability] replay_flush_failed err=${formatErrorDiagnostic(error, this.displayLocale)}`,
      );
    },
  );
  private dirtyPublicTimeline = false;
  private dirtyLogicOps = false;
  private dirtyDebugReports = false;
  private readonly dirtyPlayers = new Set<number>();
  private reproduction?: ReproductionTrace;
  private dirtyReproduction = false;
  // 公开初始化档尚无严格来源；beginReproduction 后只捕获实际元数据，不向历史档补写当前身份。
  private recordingIdentities = currentRecordingIdentities();
  private replayEventCursor?: () => number;
  setReplayEventCursor(cursor: () => number): void {
    if (this.replayEventCursor || this.reproduction)
      throw Error("reproduction_event_cursor_already_bound");
    this.replayEventCursor = cursor;
  }
  get reproductionSettlementCount(): number {
    return this.reproduction?.settlementCount ?? 0;
  }
  get reproductionDecisionCount(): number {
    return this.reproduction?.decisionCount ?? 0;
  }
  private readonly mandatoryFlushFailures: unknown[] = [];

  private constructor(
    private readonly aggregate: ReplaySessionAggregate,
    private readonly store: ReplayFileStore,
    readonly displayLocale: Locale,
  ) {}

  static async create(
    sessionMeta: ReplaySessionMeta,
    recordRootDir: string,
    displayLocale: Locale = sessionMeta.locale ?? "zh-CN",
  ): Promise<SessionRecordManager> {
    const store = new ReplayFileStore(
      path.join(recordRootDir, sessionMeta.sessionId),
      displayLocale,
    );
    const manager = new SessionRecordManager(
      new ReplaySessionAggregate(sessionMeta),
      store,
      displayLocale,
    );
    await store.initialize();
    await manager.writeInitialFiles();
    return manager;
  }

  get sessionId(): string {
    return this.aggregate.sessionMeta.sessionId;
  }
  /** 严格复现实际序列化的领域操作数，不包含 AI 诊断操作。 */
  get reproductionOperationCount(): number {
    return this.aggregate.reproductionOperationCount;
  }
  get sessionDir(): string {
    return this.store.sessionDir;
  }

  beginReproduction(
    metadata: ReproductionMetadata,
    liveEvents?: () => readonly import("../core").GameEvent[],
  ): ReproductionTrace {
    if (this.lifecycle.isClosed || this.reproduction)
      throw new Error("reproduction_scope_already_started_or_closed");
    this.aggregate.enableReproduction();
    this.reproduction = new ReproductionTrace(
      metadata,
      () => {
        if (this.lifecycle.isClosed) return;
        this.dirtyReproduction = true;
        this.lifecycle.scheduleFlush();
      },
      liveEvents,
    );
    // 不以来源声明驱动新刷盘；下次原公开发布或最终发布自然携带已捕获身份。
    this.recordingIdentities = currentRecordingIdentities(this.reproduction.recordedMetadataIdentity());
    return this.reproduction;
  }

  noteReproductionFailure(scope: ReproductionFailureScope, error: unknown): void {
    this.reproduction?.noteFailure(scope, error);
  }

  recordPublicEvent(input: ReplayRecordPublicEventInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPublicEvent(input);
    this.dirtyPublicTimeline = true;
    this.lifecycle.scheduleFlush();
  }

  /** 必需因果输入在 closing 起即拒绝；普通诊断仍保留原有的关闭前追加语义。 */
  recordRequiredLogicOp(input: ReplayRecordLogicOpInput): void {
    if (this.lifecycle.isClosed || this.lifecycle.isClosing)
      throw new Error("mandatory_logic_op_recording_closed");
    this.recordLogicOp(input);
  }

  recordLogicOp(input: ReplayRecordLogicOpInput): void {
    if (this.lifecycle.isClosed) return;
    const eventCount = this.reproduction?.ownedEventCursor ?? this.replayEventCursor?.();
    this.aggregate.recordLogicOp(eventCount === undefined ? input : { ...input, eventCount });
    this.dirtyLogicOps = true;
    this.lifecycle.scheduleFlush();
  }

  recordPlayerRound(input: ReplayRecordPlayerRoundInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPlayerRound(input);
    this.dirtyPlayers.add(input.playerId);
    this.lifecycle.scheduleFlush();
  }

  recordPlayerEvent(input: ReplayRecordPlayerEventInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPlayerEvent(input);
    this.dirtyPlayers.add(input.playerId);
    this.lifecycle.scheduleFlush();
  }

  recordDebugReport(input: ReplayRecordDebugReportInput): string {
    if (this.lifecycle.isClosed) return "rb-closed";
    const reportId = this.aggregate.recordDebugReport(input);
    this.dirtyDebugReports = true;
    this.lifecycle.scheduleFlush();
    return reportId;
  }

  flushNow(): Promise<void> {
    return this.lifecycle.flushNow();
  }

  finalize(meta: ReplayFinalizeMeta): Promise<DebugSummaryInput> {
    return this.lifecycle.finalize(() => this.persistFinalRecord(meta));
  }

  writeDebugSummary(markdown: string): Promise<void> {
    return this.store.writeText("debug_summary.md", markdown);
  }

  private async persistFinalRecord(meta: ReplayFinalizeMeta): Promise<DebugSummaryInput> {
    // closing 在首个 await 前生效；前缀完成后关闭追加，再发布最终文件。
    await this.lifecycle.beginClosing(meta);
    this.lifecycle.markClosed();

    const manifest = this.aggregate.buildManifest(meta);
    const replayDocument = this.buildReplayArchive(meta);
    const reproducible = () => {
      const input = this.aggregate.debugSummaryInput();
      const operations = (input.logicOps ?? [])
        .filter((op) => op.scope !== "llm_action_provider")
        .map(({ seq: _seq, timestamp: _timestamp, ...op }) => op);
      return this.reproduction!.build({
        operations,
        termination: { reason: meta.finishReason, winner: meta.winner },
      });
    };
    const required = await Promise.allSettled([
      this.store.writeJsonStrict("manifest.json", createManifestArchive(manifest, this.recordingIdentities)),
      this.store.writeJsonStrict("replay.json", replayDocument),
      ...(this.reproduction
        ? [
            Promise.resolve().then(() =>
              this.store.writeJsonStrict("reproduction.json", createReproductionArchive(reproducible())),
            ),
          ]
        : []),
    ]);
    await Promise.all([
      this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
      this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload()),
      this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload()),
    ]);

    const playerViews = this.aggregate.normalizedPlayerViews();
    await Promise.all(
      playerViews.map((view) =>
        this.store.writeJson(`players/player_${view.player_id}.json`, createPlayerViewArchive(view, this.recordingIdentities)),
      ),
    );

    // 已失败的严格前缀先列出，再列本次必需终档失败；成功发布不撤销旧失败。
    const failures = [
      ...this.mandatoryFlushFailures,
      ...required
        .filter((result): result is PromiseRejectedResult => result.status === "rejected")
        .map((result) => result.reason),
    ];
    if (failures.length === 1) throw failures[0];
    if (failures.length) throw new AggregateError(failures, "session_record_finalization_failed");

    return {
      manifest,
      ...this.aggregate.debugSummaryInput(),
      sessionDir: this.sessionDir,
    };
  }

  private async writeInitialFiles(): Promise<void> {
    const results = await Promise.allSettled([
      this.store.writeJsonStrict("manifest.json", createManifestArchive(this.aggregate.buildManifest(), this.recordingIdentities)),
      this.store.writeJsonStrict("replay.json", this.buildReplayArchive()),
      this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
      this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload()),
      this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload()),
    ]);
    const failures = results
      .filter((result): result is PromiseRejectedResult => result.status === "rejected")
      .map((result) => result.reason);
    if (failures.length === 1) throw failures[0];
    if (failures.length) throw new AggregateError(failures, "session_record_initialization_failed");
  }

  private async flushDirtyFiles(): Promise<void> {
    if (this.lifecycle.isClosed) return;
    if (this.dirtyReproduction && this.reproduction) {
      // 先消费本次脏位；严格失败登记在账本，后续仍可发布终档并报告此前失败。
      this.dirtyReproduction = false;
      try {
        await this.store.writeJsonStrict("reproduction.json", createReproductionArchive(this.reproduction.build()));
      } catch (error) {
        this.mandatoryFlushFailures.push(error);
        this.reproduction.noteFailure("recording", error);
        throw error;
      }
    }
    if (this.dirtyPublicTimeline) {
      this.dirtyPublicTimeline = false;
      await Promise.all([
        this.store.writeJson(
          "replay.json",
          this.buildReplayArchive(this.lifecycle.finalMetadata ?? undefined),
        ),
        this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
        this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      ]);
    }
    if (this.dirtyLogicOps) {
      this.dirtyLogicOps = false;
      await this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload());
    }
    if (this.dirtyDebugReports) {
      this.dirtyDebugReports = false;
      await this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload());
    }
    if (this.dirtyPlayers.size > 0) {
      const playerIds = [...this.dirtyPlayers];
      this.dirtyPlayers.clear();
      await Promise.all(
        playerIds.map(async (playerId) => {
          const view = this.aggregate.normalizedPlayerView(playerId);
          if (view) await this.store.writeJson(`players/player_${playerId}.json`, createPlayerViewArchive(view, this.recordingIdentities));
        }),
      );
      await Promise.all([
        this.store.writeJson(
          "manifest.json",
          createManifestArchive(this.aggregate.buildManifest(this.lifecycle.finalMetadata ?? undefined), this.recordingIdentities),
        ),
        this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      ]);
    }
  }

  private buildReplayArchive(meta?: ReplayFinalizeMeta) {
    return createPublicReplayArchive(createReplayDocument({
      manifest: this.aggregate.buildManifest(meta),
      events: this.aggregate.publicTimelinePayload().events,
    }), this.recordingIdentities);
  }
}

export function resolveDefaultRecordRoot(cwd: string = process.cwd()): string {
  return path.basename(cwd) === "backend"
    ? path.resolve(cwd, "..", "record")
    : path.resolve(cwd, "record");
}

export function buildSessionId(now: number = Date.now()): string {
  return `session_${now}_${Math.random().toString(36).slice(2, 8)}`;
}

export function safeRecordLogicOp(input: ReplayRecordLogicOpInput): void {
  const active = getSessionRecorder();
  if (!active) return;
  try {
    active.recordLogicOp(input);
  } catch (error) {
    console.warn(
      `[observability] logic_op_record_failed op=${input.op} err=${formatErrorDiagnostic(error, active.displayLocale)}`,
    );
  }
}

/**
 * 负责有限角色及墙事件的请求绑定组合。输入为工厂已构造的原请求和延迟阶段／World 查询；
 * 输出是在原机制所有者中建立的请求关联，顺序为孤独少女、野孩子、初始身份、墙、鬼新娘。
 * 各分支独立判断，保留初始身份的短路和阶段重复读取；命中时才读取 World，失败不撤销前面的绑定。
 * 权限及期限别名仍归具体机制的原 WeakMap 和守卫；本组合不复制请求、创建库存或授予新许可。
 */
import type { ActionStage } from "@ai-werewolf-arena/game-contract";
import type { ActionRequest } from "@ai-werewolf-arena/game-contract/requests";
import type { World } from "../core/domain/world";
import { bindGhostBrideRequest } from "../game/mechanisms/roles/ghost_bride/authority";
import { bindLonelyGirlRequest } from "../game/mechanisms/roles/lonely_girl/lifecycle";
import { bindWildChildRequest } from "../game/mechanisms/roles/wild_child/lifecycle";
import { bindInitialIdentityRequest } from "../game/mechanisms/roles/initial_identity/setup";
import { bindWallRequest } from "../game/mechanisms/events/wall_notes/authority";

/** 查询保原表达式位置；工厂使用自己的输入与 World，阶段不能从请求快照反推。 */
export interface ActionRequestBindingQueries {
  stage(): ActionStage;
  world(): World;
}

/** 只组合已有绑定命令；请求、context 与具体机制状态保持原引用，异常继续沿原调用路径抛出。 */
export function bindRulesetActionRequest(
  request: ActionRequest,
  queries: ActionRequestBindingQueries,
): void {
  if (queries.stage() === "lonely_girl") bindLonelyGirlRequest(queries.world(), request);
  if (queries.stage() === "wild_child") bindWildChildRequest(queries.world(), request);
  if (queries.stage() === "thief" || queries.stage() === "shapeshifter")
    bindInitialIdentityRequest(queries.world(), request);
  // 墙分支原本就在初始身份与鬼新娘之间；不能为按角色分组而改变绑定及失败前缀。
  if (queries.stage() === "wall_notes") bindWallRequest(queries.world(), request);
  if (
    [
      "ghost_bride_groom",
      "ghost_bride_chat",
      "ghost_bride_witness",
      "ghost_bride_knife",
      "wolf_vote",
    ].includes(queries.stage())
  )
    bindGhostBrideRequest(queries.world(), request);
}

/**
 * 负责枪后追加波的完整夜梦、婚约、恋人／梦闭包和馥郁双生预约准备。
 * 输入为结算器同一提案／死因／夜来源／已见／下一波容器和晚读取的查询；输出为原双生回执及晚阶段查询。
 * 独立夜梦先于婚约，再展开恋人和派生梦，最后按原已见、已提交生命与存活过滤双生根；不统一各关系政策。
 * 各容器仍归结算器，具体关系和去重仍归机制；此步不标死、不更新 seen／next、不付款或提交／取消预约。
 * 关系事件或后续查询失败保留已发生前缀；来源阶段只在原逐目标提交点读取，未进入提交时不读当前 phase。
 */
import { DeathCause, type DeathSources, type EntityId, type GameEvent, type Phase } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../core/domain/components/names";
import type { World } from "../core/domain/world";
import type { DreamNightEffects } from "../core/domain/dream-night-effects";
import { expandLoversWave } from "../game/mechanisms/roles/cupid/death-ports";
import { prepareFragrantDeathWave } from "../game/mechanisms/roles/fragrant_pair_seer/ports";
import type { InitialWeddingExpansion } from "./initial-death-relations";

/** 只捕获结算器查询；调用时才取 World、事件、婚约实例和同一梦效果，不缓存状态或重建生命权威。 */
export interface AdditionalDeathRelationRuntime {
  world(): World;
  events(): GameEvent[];
  wedding(): InitialWeddingExpansion;
  dreams(): DreamNightEffects | undefined;
  isSettledLife(id: EntityId): boolean;
  phase(): Phase;
}

/** 原局部容器别名；linked 在调用方原分配点创建，追加准备只写该 Set，不建立第二份关系权威。 */
export interface AdditionalDeathRelationWave {
  readonly proposed: EntityId[];
  readonly proposedSources: DeathSources;
  readonly nightTargets: readonly EntityId[];
  readonly allSources: DeathSources;
  readonly next: ReadonlySet<EntityId>;
  readonly seen: ReadonlySet<EntityId>;
  readonly nightOrigin: Set<EntityId>;
  readonly linked: Set<EntityId>;
  readonly ownsFragrant: boolean;
  readonly resolutionDay: number;
  readonly sourcePhase: Phase;
}

/** 回执是原未提交预约，不是 JSON／付款证据；阶段方法由调用方在原写入参数位置晚调用。 */
export interface AdditionalDeathRelationPreparation {
  readonly fragrantGun: ReturnType<typeof prepareFragrantDeathWave>;
  originPhase(): Phase;
}

export function prepareAdditionalDeathRelations(
  runtime: AdditionalDeathRelationRuntime,
  wave: AdditionalDeathRelationWave,
): AdditionalDeathRelationPreparation {
  const { proposed, proposedSources, nightTargets, allSources, next, seen, nightOrigin, linked, ownsFragrant, resolutionDay, sourcePhase } = wave;
  // 原夜目标先登记来源，再取同一梦实例的方法；Dream 的独立根名单以原 allSources 编号为界。
  for (const id of nightTargets) nightOrigin.add(id);
  if (runtime.dreams() && nightTargets.length)
    for (const id of runtime.dreams()!.linkedDeaths(
      runtime.world(),
      nightTargets,
      new Set(Object.keys(allSources).map(Number)),
    )) {
      linked.add(id);
      if (!proposed.includes(id)) proposed.push(id);
      proposedSources[id] = [
        ...new Set([...(proposedSources[id] ?? []), DeathCause.Dream]),
      ];
      nightOrigin.add(id);
    }
  runtime.wedding().expand(proposed, proposedSources, seen, nightOrigin);
  expandLoversWave(
    runtime.world(),
    proposed,
    proposedSources,
    runtime.events(),
    nightOrigin,
    seen,
    runtime.dreams(),
  );
  const fragrantRoots = ownsFragrant
    ? proposed.filter(
        (id) =>
          !next.has(id) &&
          !seen.has(id) &&
          !runtime.isSettledLife(id) &&
          runtime.world().getComponent(id, COMPONENT.Alive)?.alive,
      )
    : [];
  const fragrantGun = ownsFragrant
    ? prepareFragrantDeathWave(runtime.world(), resolutionDay, fragrantRoots)
    : null;
  if (
    fragrantGun?.addedTargetId !== null &&
    fragrantGun?.addedTargetId !== undefined
  ) {
    // 原追加目标死因覆盖而非合并；预约尚未付款，commit/cancel仍由结算器原 try/finally 持有。
    proposed.push(fragrantGun.addedTargetId);
    proposedSources[fragrantGun.addedTargetId] = [DeathCause.FragrantLink];
  }
  return {
    fragrantGun,
    // 调用方已按原序登记 seen／allSources，才在 originPhases.set 的参数点查询；失败不撤销该前缀。
    originPhase: () => ownsFragrant ? runtime.phase() : sourcePhase,
  };
}

/**
 * 负责狼美人放逐定案的候选捕获、整侧完成核对及屠边覆盖数据，保留两个同步业务时点。
 * 输入为原有效放逐结果、晚读 World 和同一魅惑绑定；输出为原目标、可写候选或真实 Victory 成员判定。
 * 普通板在死亡波前捕获末狼和目标侧；波后仍需 applied、原体当前性及目标实际死亡，不能靠提案提前获胜。
 * 覆盖只供 exile_settled 的 slaughter_side 项，配置首命中顺序和唯一封盘仍归经理／条件注册表。
 * 本模块不持第二份关系、不领取牵连、不退款、不标死、不推进阶段；查询异常保留已提交死亡前缀。
 * 规则见 docs/rules/awa-wolf-beauty-v1.md；候选不进入玩家知识或档案，不授予行动权限。
 */
import { Camp, Role, WinCondition, type EntityId, type VotingSummary, type WinDecision } from "../core/domain/model";
import { COMPONENT } from "../core/domain/components/names";
import type { World } from "../core/domain/world";
import { activeCharm, isCharmBindingCurrent, type CharmBinding } from "../game/mechanisms/roles/wolf_beauty/ports";
import { getDefaultRoleCatalog } from "../game/mechanisms/roles/role-catalog-assembly";
import { victoryDecision } from "../game/mechanisms/win_conditions/results";

/** 仅读原结果字段；readonly 不冻结原数组，也不证明目标已经死亡或取得死亡许可。 */
export interface BeautyExileSelection {
  readonly summary: Pick<VotingSummary, "target" | "effectiveTarget">;
  readonly removed: readonly EntityId[];
}

/** 仍为原可写候选，绑定保同一运行引用；目标侧只在死亡波前捕获，不在波后重新推断。 */
export interface BeautyExileCandidate {
  actorId: EntityId;
  targetId: EntityId;
  side: "god" | "villager";
  binding: CharmBinding;
}
/**
 * 只在经理原普通放逐分支调用；effectiveTarget 有定义时保留原两次 getter 读取。
 * 先核非 null 和真实移除名单，之后才取得 World；不合格目标不捕获关系或查询隐藏狼数。
 */
export function prepareBeautyExileVictory(
  selection: BeautyExileSelection,
  world: () => World,
): { target: EntityId | null; candidate: BeautyExileCandidate | null } {
  const target =
    selection.summary.effectiveTarget === undefined
      ? selection.summary.target
      : selection.summary.effectiveTarget;
  const candidate = target !== null && selection.removed.includes(target)
    ? captureBeautyExile(world(), target)
    : null;
  return { target, candidate };
}

/** 仅在真实放逐已确定、完整死亡波尚未执行时捕获候选；实际Camp在各原比较点晚读，不提前封盘。 */
function captureBeautyExile(world: World, actorId: EntityId): BeautyExileCandidate | null {
  const actor = world.getComponent(actorId, COMPONENT.Role),
    binding = activeCharm(world, actorId);
  if (
    actor?.role !== Role.WolfBeauty ||
    world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf ||
    !binding ||
    !binding.targetLife.alive
  )
    return null;
  if (
    world
      .getAliveEntityIds()
      .some((id) => id !== actorId && !!world.getComponent(id, COMPONENT.Role) && world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Wolf)
  )
    return null;
  const target = world.getComponent(binding.targetId, COMPONENT.Role),
    side = target ? getDefaultRoleCatalog().metadata(target.role)?.goodSide : undefined;
  return target && world.getComponent(binding.targetId, COMPONENT.Camp)?.camp === Camp.Good && side
    ? { actorId, targetId: binding.targetId, side, binding }
    : null;
}
/**
 * 调用方已完成死亡波并通过原当前性守卫；已领取／被阻断仍不等于 applied。
 * 原绑定校验继续归 relation，同侧存活扫描之后才由共同结果 owner 捕获真实 Victory 成员。
 */
export function resolveBeautyExileVictory(
  world: World,
  candidate: BeautyExileCandidate | null,
): WinDecision | null {
  if (
    !candidate ||
    !candidate.binding.applied ||
    !isCharmBindingCurrent(world, candidate.binding) ||
    candidate.binding.targetLife.alive
  )
    return null;
  const sideAlive = world.getAliveEntityIds().some((id) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return (
      role && world.getComponent(id, COMPONENT.Camp)?.camp === Camp.Good &&
      getDefaultRoleCatalog().metadata(role.role)?.goodSide === candidate.side
    );
  });
  return sideAlive
    ? null
    : victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "wolf_beauty_last_exile");
}

/**
 * 在经理 checkAndSealResult 的第二实参位置生成覆盖，不能提前到 callee 或 checkpoint 读取之前。
 * 空结果仍返回原空对象；只覆盖屠边项，不绕过配置中排在前面的其它胜利条件。
 */
export function beautyExileVictoryOverrides(
  result: WinDecision | null,
): Partial<Record<WinCondition, WinDecision>> {
  return result ? { [WinCondition.SlaughterSide]: result } : {};
}

/**
 * 负责对一次周期与手动阶段跳转执行有限、有序的同步重入准入政策。
 * 输入为延迟读取的原 World 与 day/gameOver；输出为通过或首个原机制错误。
 * 提交证据、准备状态及活跃窗口仍由各机制拥有；拒绝不撤销已付效果，也不重开窗口。
 * 这里不推进阶段、不标记周期、不授予行动许可；终局返回、时钟和失败清理由阶段经理处理。
 */
import type { World } from "../core/domain/world";
import type { RuntimeSnapshot } from "@ai-werewolf-arena/game-contract";
import { hasRadiantNight } from "../game/mechanisms/roles/radiant_eclipse/ports";
import { hasDemonNightStarted } from "../game/mechanisms/roles/demon_hunter/ports";
import {
  weddingSetup, ghostBrideReady, hasActiveGhostBride, hasGhostBrideNightCommit,
} from "../game/mechanisms/roles/ghost_bride/ports";
import {
  lonelyGirlReady, hasActiveLonelyGirl, hasLonelyGirlNightCommit,
} from "../game/mechanisms/roles/lonely_girl/ports";
import {
  hasActiveWildChild, hasWildChildNightCommit,
} from "../game/mechanisms/roles/wild_child/ports";
import {
  hasActiveInitialIdentitySetup, hasActiveInitialIdentityNight,
  hasInitialIdentityNightCommit, initialIdentityKind,
} from "../game/mechanisms/roles/initial_identity/ports";
import { hasActiveWall } from "../game/mechanisms/events/wall_notes/ports";

/** 运行查询端口；readonly 约束字段赋值，不是数据快照或运行时授权屏障。 */
export interface CycleAdmissionRuntime {
  readonly world: World;
  readonly state: Readonly<Pick<RuntimeSnapshot, "day" | "gameOver">>;
}

/** 按原首错误次序读取现场状态；终局保留各原 gameOver 短路，仍核无条件活跃窗口。 */
export function assertCycleAdmission(runtime: CycleAdmissionRuntime): void {
  if (!runtime.state.gameOver && hasRadiantNight(runtime.world, runtime.state.day))
    throw new Error("radiant_night_reentry");
  if (!runtime.state.gameOver && hasDemonNightStarted(runtime.world, runtime.state.day))
    throw new Error("demon_hunter_cycle_reentry");
  const wedding = weddingSetup(runtime.world);
  if (
    hasActiveGhostBride(runtime.world) ||
    (wedding && wedding.status !== "pending" && !ghostBrideReady(runtime.world)) ||
    (!runtime.state.gameOver && hasGhostBrideNightCommit(runtime.world, runtime.state.day))
  )
    throw new Error("ghost_bride_cycle_reentry");
  if (
    hasActiveLonelyGirl(runtime.world) ||
    (!runtime.state.gameOver && hasLonelyGirlNightCommit(runtime.world, runtime.state.day))
  )
    throw new Error("lonely_girl_cycle_reentry");
  if (
    hasActiveWildChild(runtime.world) ||
    (!runtime.state.gameOver && hasWildChildNightCommit(runtime.world, runtime.state.day))
  )
    throw new Error("wild_child_cycle_reentry");
  if (hasActiveInitialIdentitySetup(runtime.world) || hasActiveInitialIdentityNight(runtime.world))
    throw new Error(`${initialIdentityKind(runtime.world) ?? "thief"}_setup_reentry`);
  if (!runtime.state.gameOver && hasInitialIdentityNightCommit(runtime.world, runtime.state.day))
    throw new Error(`${initialIdentityKind(runtime.world) ?? "thief"}_cycle_reentry_after_night`);
  if (hasActiveWall(runtime.world)) throw new Error("wall_window_reentry");
}

/** 跳转只核原三个机制；Mist 周期登记仍由经理在此前处理，阶段时钟在通过后推进。 */
export function assertPhaseJumpAdmission(runtime: CycleAdmissionRuntime): void {
  if (!runtime.state.gameOver && hasDemonNightStarted(runtime.world, runtime.state.day))
    throw new Error("demon_hunter_phase_reentry");
  if (
    hasActiveGhostBride(runtime.world) ||
    !ghostBrideReady(runtime.world) ||
    (!runtime.state.gameOver && hasGhostBrideNightCommit(runtime.world, runtime.state.day))
  )
    throw new Error("ghost_bride_phase_reentry");
  if (
    hasActiveLonelyGirl(runtime.world) ||
    !lonelyGirlReady(runtime.world) ||
    (!runtime.state.gameOver && hasLonelyGirlNightCommit(runtime.world, runtime.state.day))
  )
    throw new Error("lonely_girl_phase_reentry");
}

/**
 * 负责熊夜前捕获与黎明公开事实／动物板知识的完整同步发布组合。
 * 输入为晚读 World、配置与原事件数组、同一 nullable frame 和当前性回调；输出为原 frame 或原事实／知识前缀。
 * 捕获留在首夜准备与猎魔原体检查之后、夜流水线之前；发布留在完整死亡波与原清理／当前性检查之后。
 * 无 frame 仍先取事件起点；可选发布只短路其参数，动物配置仍按原顺序推进熊知识与狼美人通知。
 * 熊的采样、原体、历史、两政策和发布租约归 frame；知识唯一归 Animal facts，阶段、await 与判胜仍归经理。
 * 本模块不存镜像、标死、退款或授予行动许可；后项失败保已经发表的熊事实和已有知识前缀。
 * 规则见 docs/rules/awa-bear-v1.md 和 docs/rules/awa-animal-dream-twelve-v1.md。
 */
import type { BearSignalPolicy, ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { GameEvent } from "../core/domain/events";
import type { World } from "../core/domain/world";
import { BearNightFrame } from "../game/mechanisms/roles/bear/ports";
import { noteAnimalBearPublication, appendAnimalBeautyNotice } from "../game/mechanisms/roles/animal_dream/ports";

/** 每次在原表达式位置取真实引用；方法类型不是许可，不提前缓存 World、数组或配置。 */
export interface DawnKnowledgeRuntime {
  world(): World;
  events(): GameEvent[];
  signalPolicy(): BearSignalPolicy | undefined;
  animalDream(): ReadonlyBoardConfig["animalDream"];
}

/** 原 static callee 先于 World／policy 参数；undefined catalog 保留原默认初始化时点。 */
export function captureDawnKnowledge(
  runtime: Pick<DawnKnowledgeRuntime, "world" | "signalPolicy">,
  day: number,
): BearNightFrame | null {
  return BearNightFrame.capture(
    runtime.world(),
    day,
    undefined,
    runtime.signalPolicy(),
  );
}

/**
 * 同一 frame 保原 publish receiver，null 不读其 World／events 参数；Animal gate 与 frame 成功无关。
 * 先发表熊事件再扫描该起点之后的事实，随后才发狼美人通知；失败原样抛出，不捕获或回滚前项。
 */
export function publishDawnKnowledge(
  bearFrame: BearNightFrame | null,
  runtime: Pick<DawnKnowledgeRuntime, "world" | "events" | "animalDream">,
  day: number,
  isCurrent: () => boolean,
): void {
  const bearStart = runtime.events().length;
  bearFrame?.publish(runtime.world(), runtime.events(), isCurrent);
  if (runtime.animalDream()) {
    noteAnimalBearPublication(runtime.world(), runtime.events(), bearStart);
    appendAnimalBeautyNotice(runtime.world(), runtime.events(), day);
  }
}

/**
 * 负责白天自爆、骑士决斗和辩论窗口的有序装配及辩论重入政策。输入是调用方现场读取
 * World、角色注册、网关和事件的端口；输出为三个原窗口实例的窄视图与同步准入检查。
 * 构造顺序固定为自爆、决斗、辩论，首个读取／构造错误停止后续步骤，不回滚前缀。
 * 机制仍拥有许可、状态、付款与关闭；组合不缓存演员、改变配置、推进阶段或判断胜负。
 */
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../core/domain/world";
import type { RoleRegistry } from "../core/domain/registries/role_registry";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import type { DaytimeInterruptionComposition } from "../game/engine/daytime-interruption-contracts";
import { SelfDestructWindow } from "./self-destruct-window";
import { KnightDuelWindow } from "../game/mechanisms/roles/knight/ports";
import { DebaterWindow } from "../game/mechanisms/roles/debater/window";
import { hasActiveDebate } from "../game/mechanisms/roles/debater/authority";

/** 延迟读取保留每次原调用点；窗口捕获构造时引用，重入检查则读取执行时的 World。 */
export interface DaytimeInterruptionRuntime {
  world(): World;
  roleRegistry(): RoleRegistry;
  toolGateway(): ToolGateway;
  events(): GameEvent[];
}

export function createDaytimeInterruptionComposition(
  runtime: DaytimeInterruptionRuntime,
): DaytimeInterruptionComposition {
  // 每个 new 先查找原构造器，再依原顺序读取参数；不要先收齐一次 World／网关快照。
  const selfDestruct = new SelfDestructWindow(
    runtime.world(),
    runtime.roleRegistry(),
    runtime.toolGateway(),
  );
  const duel = new KnightDuelWindow(runtime.world(), runtime.toolGateway());
  const debate = new DebaterWindow(runtime.world(), runtime.toolGateway(), runtime.events());

  return {
    selfDestruct,
    duel,
    debate,
    assertEntry() {
      // 即使调用方已失效，仍先拒绝现场已开启辩论；没有新预约、撤销或已付效果回滚。
      if (hasActiveDebate(runtime.world())) throw new Error("debate_window_reentry");
    },
  };
}

/**
 * 负责死亡枪击请求、三次有界选择及等待后的原生命／交换目标复验。输入为结算器的延迟读取、
 * 原死亡来源和同一动作窗口；输出为未付款的选择，空枪同样持原许可编号。
 * 资格捕获、恐惧与交换政策归原机制；本组合不标死、不消费弹药、不关闭窗口或确定胜负。
 * World 唯一开许可，结算器仍在原提交回调与 finally 关闭同一 permits 数组；异常不退款已提交前缀。
 */
import {
  Phase,
  Role,
  type EntityId,
  type DeathSources,
  type GameEvent,
  type RuntimeSnapshot,
  type ReadonlyBoardConfig,
} from "@ai-werewolf-arena/game-contract";
import type { ActionProvider } from "../core/domain/actions";
import type { DeathShotSelection } from "../core/domain/deaths";
import type { World } from "../core/domain/world";
import { COMPONENT } from "../core/domain/components/names";
import { captureNightLife, livingNightLife } from "../core/domain/night_effects";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import { GameActionRequestFactory } from "../game/engine/action_request_factory";
import { captureDeathShotEligibility } from "../game/mechanisms/roles/death_abilities";
import {
  assertMagicianRosterCurrent,
  isMagicianBoard,
  resolveMagicianNightTarget,
} from "../game/mechanisms/roles/magician/ports";
import { nightmareFearBlocks } from "../game/mechanisms/roles/nightmare_shadow/ports";
import { demonHunterNativeGunCurrent } from "../game/mechanisms/roles/demon_hunter/ports";

/** 延迟读取原结算器；类型只声明所需成员，不是进程隔离或额外的运行权限屏障。 */
export interface DeathShotSelectionRuntime {
  readonly world: World;
  readonly events: GameEvent[];
  readonly toolGateway: ToolGateway;
  readonly state: Pick<RuntimeSnapshot, "phase" | "day" | "gameOver">;
  readonly config?: ReadonlyBoardConfig;
}

/** 一次角色死亡动作的窗口；所有 permit 在退出该回调时关闭，不跨波复用。 */
export interface DeathWaveActions {
  phase: Phase;
  day: number;
  permits: Array<ReturnType<World["openDeathAction"]>>;
  isCurrent: () => boolean;
}

/** 开原窗口后登记给外层持有；每次 await 和工具校验之后仍按原顺序复验资格与窗口。 */
export async function collectDeathShot(
  runtime: DeathShotSelectionRuntime,
  actorId: EntityId,
  deathPhase: Phase,
  deathOriginPhase: Phase,
  sources: DeathSources,
  actionProvider: ActionProvider,
  actions: DeathWaveActions,
  abilityId?: string,
  nightExchange: boolean = false,
): Promise<DeathShotSelection> {
  if (deathPhase === Phase.Night && nightmareFearBlocks(runtime.world, actorId, actions.day, true))
    return { kind: "invalid" };
  const isCurrent = () =>
    actions.isCurrent() &&
    runtime.state.phase === actions.phase &&
    runtime.state.day === actions.day &&
    !runtime.state.gameOver;
  // 只装配延迟查询，不提前读取 World／日期；资格所有者 在原 callee 和参数时点捕获。
  const resolution = runtime;
  const qualification = captureDeathShotEligibility(
    {
      get world() { return resolution.world; },
      get day() { return actions.day; },
      get demonHunterNativeGunCurrent() { return demonHunterNativeGunCurrent; },
    },
    actorId,
    abilityId,
    sources,
    deathOriginPhase,
    isCurrent,
  );
  if (!qualification) return { kind: "invalid" };
  const { nativePolicy, permissionCurrent, eligible } = qualification;
  if (!eligible()) return { kind: "invalid" };
  const permit = runtime.world.openDeathAction(
    actorId,
    "shoot",
    actions.phase,
    actions.day,
    permissionCurrent,
    abilityId,
  );
  actions.permits.push(permit);
  const requests = new GameActionRequestFactory(runtime.world, runtime.events, actions.day);
  for (let attempt = 1; attempt <= 3; attempt++) {
    // 每次重试重新捕获候选生命；同一编号复活或替换组件后，上一轮回复不能命中新生命。
    const targets = new Map(
      runtime.world.getAliveEntityIds().map((id) => [id, captureNightLife(runtime.world, id)]),
    );
    if (!eligible()) return { kind: "invalid" };
    const request = requests.create({
      phase: actions.phase,
      actorId: actorId,
      allowedTools: ["shoot"],
      stage:
        abilityId === undefined &&
        runtime.world.getComponent(actorId, COMPONENT.Role)?.role === Role.Hunter
          ? "hunter_shot"
          : "death_shot",
      requiresAction: true,
      summary: { key: "request.summary.death_shot" },
      context: {
        ...(runtime.config?.magician ||
        runtime.config?.evilKnight ||
        abilityId !== undefined ||
        runtime.world.getComponent(actorId, COMPONENT.Role)?.role === Role.AwakenedHiddenWolf
          ? { action_failure_policy: "error" as const, allow_fallback: false }
          : {}),
        ...(abilityId === undefined ? {} : { ability_id: abilityId }),
        trigger: "on_death",
        death_phase: deathPhase,
        ...(nativePolicy === "awa_day_deaths_v1" ? { death_origin_phase: deathOriginPhase } : {}),
        death_sources: [...(sources[actorId] ?? [])],
        death_action_id: permit.id,
        shoot_candidates: [...targets.keys()].filter((id) => id !== actorId),
        ...(attempt === 1 ? {} : { retry_attempt: attempt - 1, retry_max: 2 }),
      },
    });
    if (!eligible()) return { kind: "invalid" };
    if (runtime.config?.magician) assertMagicianRosterCurrent(runtime.world);
    const action = await actionProvider.getAction(request);
    if (runtime.config?.magician) assertMagicianRosterCurrent(runtime.world);
    if (
      !eligible() ||
      !runtime.world.hasDeathAction(
        actorId,
        "shoot",
        actions.phase,
        actions.day,
        permit.id,
        abilityId,
      )
    )
      return { kind: "invalid" };
    if (action?.name !== "shoot") {
      if (runtime.config?.magician) throw new Error("magician_shot_action_missing");
      if (runtime.config?.evilKnight) throw new Error("evil_knight_hunter_action_missing");
      continue;
    }
    const validated = runtime.toolGateway.validateAndSanitize(runtime.world, actorId, action, {
      phase: actions.phase,
      day: actions.day,
      deathActionId: permit.id,
      abilityId,
    });
    if (
      !eligible() ||
      !runtime.world.hasDeathAction(
        actorId,
        "shoot",
        actions.phase,
        actions.day,
        permit.id,
        abilityId,
      )
    )
      return { kind: "invalid" };
    if (!validated.ok || !validated.sanitizedCall) {
      if (runtime.config?.magician) throw new Error("magician_shot_action_invalid");
      if (runtime.config?.evilKnight) throw new Error("evil_knight_hunter_action_invalid");
      continue;
    }
    const targetId = validated.sanitizedCall.args.target_id;
    // 空枪也只是已授权选择，真正消耗留给随后处理该选择的角色钩子。
    if (targetId === null) return { kind: "pass", deathActionId: permit.id };
    const targetScope = targets.get(targetId);
    if (!targetScope || !livingNightLife(runtime.world, targetScope)) {
      if (runtime.config?.magician) throw new Error("magician_shot_target_stale");
      continue;
    }
    if (nightExchange && isMagicianBoard(runtime.world)) {
      const mapped = resolveMagicianNightTarget(runtime.world, actions.day, targetId, "death_shot");
      if (!mapped.isCurrent()) throw new Error("magician_shot_target_stale");
      return {
        kind: "shot",
        targetId: mapped.effectiveId,
        deathActionId: permit.id,
        targetScope: mapped.scope,
        mappingCurrent: mapped.isCurrent,
        ...(!mapped.scope.life.alive ? { mappedMiss: true as const } : {}),
      };
    }
    return { kind: "shot", targetId, deathActionId: permit.id, targetScope };
  }
  if (abilityId !== undefined && eligible()) throw new Error("gift_gun_valid_action_missing");
  return { kind: "invalid" };
}

/**
 * 负责投票后两种板子的死亡提案与守墓人放逐反馈准备，保留各自原名单、来源和读取时点。
 * 输入为原投票结果、晚读 World 的查询及已构造的来源表；输出是新提案容器或原查验政策的反馈。
 * 动物板先合并放逐／河豚来源，实际死亡、关单位和公开事实之后才捕获主放逐反馈；
 * 普通板按原有效目标在死亡波之前捕获反馈，再准备放逐来源。本模块不统一这两种提交政策。
 * 这里只准备数据，不标死、打开单位、付款、发布事实、推进阶段或判胜；异常保留调用方已提交前缀。
 */
import {
  DeathCause,
  type DeathSources,
  type EntityId,
  type ExileFeedback,
  type VotingSummary,
} from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../core/domain/components/names";
import type { World } from "../core/domain/world";
import { captureExileFeedback } from "../game/mechanisms/roles/gravekeeper/ports";

/** 只读原结果字段，不复制票表或冻结数组；提案容器不是死亡提交凭据或行动授权。 */
export interface ExileDeathSelection {
  readonly summary: Pick<VotingSummary, "target">;
  readonly removed: readonly EntityId[];
  readonly animalRetaliation?: readonly EntityId[];
}

/** 动物板的同一席位可同时有放逐和河豚来源；保留首次出现顺序，不把两来源折成单一死因。 */
export function prepareAnimalExileDeaths(selection: ExileDeathSelection) {
  const sources: DeathSources = {};
  for (const id of selection.removed) sources[id] = [DeathCause.Exile];
  for (const id of selection.animalRetaliation ?? [])
    sources[id] = [...new Set([...(sources[id] ?? []), DeathCause.PufferRetaliation])];
  const ids = [
    ...new Set([...selection.removed, ...(selection.animalRetaliation ?? [])]),
  ];
  return { sources, ids };
}

/** 调用方已经完成动物死亡波与原公告；仅读实际死亡的主放逐目标，不把河豚牵连当反馈。 */
export function captureAnimalExileFeedback(
  world: () => World,
  selection: Pick<ExileDeathSelection, "summary">,
  sources: DeathSources,
  exileDay: number,
): ExileFeedback | null {
  const target = selection.summary.target;
  return target !== null &&
    sources[target]?.includes(DeathCause.Exile) &&
    world().getComponent(target, COMPONENT.Alive)?.alive === false
      ? captureExileFeedback(world(), target, exileDay)
      : null;
}

/** 普通板在死亡波前捕获已接受放逐的披露标签；有效目标由经理在原点选定，不再要求已标死。 */
export function captureOrdinaryExileFeedback(
  world: () => World,
  selection: Pick<ExileDeathSelection, "removed">,
  target: EntityId | null,
  exileDay: number,
): ExileFeedback | null {
  return target !== null && selection.removed.includes(target)
    ? captureExileFeedback(world(), target, exileDay)
    : null;
}

/** 普通反馈完成之后才构造来源；保持原遍历和重复目标覆盖，不补入摘要中没有移除的目标。 */
export function prepareOrdinaryExileDeaths(selection: Pick<ExileDeathSelection, "removed">): DeathSources {
  const sources: DeathSources = {};
  for (const removedId of selection.removed) {
    sources[removedId] = [DeathCause.Exile];
  }
  return sources;
}

/**
 * 负责开局馥郁双生权威安装及首夜设置的确定序列：盗贼／千面人、野孩子、孤独少女、鬼魂新娘。
 * 输入为原配置与现场读取 World、事件、网关的查询；首夜序列另接原 provider、日期和唯一当前性回调；
 * 开局输出为安装完成或原异常；首夜输出为全部准备通过，或在首个未完成／失效步骤之后返回 false。
 * 组合装配原窗口及其惰性请求构造依赖，串行交还原执行 Promise；
 * 选择、库存、接受权限和 finally 关闭仍由各机制拥有，不把构造器或阶段标签当许可。
 * 开局安装只在原配置为真时按原World／事件／两角色查询顺序执行，首异常阻止后续构造，不发布事实或退款。
 * 不缓存 World 或提前读取构造参数；首夜序列成功末尾没有额外当前性查询，也不推进阶段或生成快照。
 */
import type { GameEvent, ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { ActionProvider } from "../core/domain/actions";
import type { World } from "../core/domain/world";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import { GameActionRequestFactory } from "../game/engine/action_request_factory";
import { Role } from "../core/domain/identity";
import { installFragrantPairAuthority } from "../game/mechanisms/roles/fragrant_pair_seer/setup-ports";
import {
  InitialIdentitySetupWindow,
  initialIdentitySetupReady,
  initialIdentityKind,
} from "../game/mechanisms/roles/initial_identity/ports";
import { wildChildReady } from "../game/mechanisms/roles/wild_child/ports";
import { WildChildSetupWindow } from "../game/mechanisms/roles/wild_child/setup-ports";
import { LonelyGirlSetupWindow, lonelyGirlReady } from "../game/mechanisms/roles/lonely_girl/ports";
import { GhostBrideSetupWindow, ghostBrideReady } from "../game/mechanisms/roles/ghost_bride/ports";

/** 查询只读取原调用点；事件数组与板子引用交给窗口，不产生新授权或状态镜像。 */
export interface GameSetupRuntime {
  world(): World;
  toolGateway(): ToolGateway;
  events(): GameEvent[];
  config(): ReadonlyBoardConfig;
}

export function* prepareGameSetup(
  runtime: GameSetupRuntime,
  actionProvider: ActionProvider,
  nightDay: number,
  nightIsCurrent: () => boolean,
): Generator<Promise<boolean>, boolean, boolean> {
  // 没有待设置窗口时同步结束；只在原 execute 的 Promise 处暂停，不增加 helper 完成等待。
  // 每个 new 先查找原类，再按原顺序读取参数；execute 仍使用该实例作为 receiver。
  if (!initialIdentitySetupReady(runtime.world())) {
    const ready = yield new InitialIdentitySetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
      initialIdentityKind(runtime.world())!,
      {
        // 装配只交付 getter；共享窗口到原 new 点才读取真实类，不在开局检查时捕获。
        get requestFactory() { return GameActionRequestFactory; },
      },
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    // false 先短路，不再查询当前性或推进其它设置；窗口的失败关闭仍由自己的 finally 完成。
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!wildChildReady(runtime.world())) {
    const ready = yield new WildChildSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
      { get requestFactory() { return GameActionRequestFactory; } },
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!lonelyGirlReady(runtime.world())) {
    const ready = yield new LonelyGirlSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
      { get requestFactory() { return GameActionRequestFactory; } },
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!ghostBrideReady(runtime.world())) {
    const ready = yield new GhostBrideSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
      { get requestFactory() { return GameActionRequestFactory; } },
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  return true;
}

/** 开局安装在原config门控后才读World／事件与两角色；本贡献不建立第二权威或新的许可。 */
export function installFragrantGameSetup(
  config: Pick<ReadonlyBoardConfig, "fragrantPairSeer">,
  runtime: Pick<GameSetupRuntime, "world" | "events">,
): void {
  if (config.fragrantPairSeer)
    installFragrantPairAuthority(
      runtime.world(),
      runtime.events(),
      runtime.world().getEntityIdsByRole(Role.FragrantPhantom)[0]!,
      runtime.world().getEntityIdsByRole(Role.AwakenedSeer)[0]!,
    );
}

/**
 * 负责白痴放逐的完整免死结果组合。输入为原 World、目标和可写事件数组；输出为免死结果或 null。
 * 规则集先查询猎魔板子的原生审计，原生库存提交仍归猎魔权威；普通分支按翻牌、票权、警徽、事件原序写入。
 * 本模块不标死、推进阶段或授予租约；已写前缀遇后续错误不回滚，重复翻牌不恢复票权。
 */
import { commitDemonIdiotReveal, demonIdiotRevealed } from "../game/mechanisms/roles/demon_hunter/reveal-ports";
import { AliveComponent } from "../core/domain/components/alive";
import { BadgeComponent } from "../core/domain/components/badge";
import { COMPONENT } from "../core/domain/components/names";
import { RoleComponent } from "../core/domain/components/role";
import { VotingRightComponent } from "../core/domain/components/voting_right";
import { EntityId, GameEvent, Role } from "../core/domain/model";
import { World } from "../core/domain/world";
import { VotedOutResult } from "../game/mechanisms/hooks/hook_registry";
import { transferOrDestroySheriffBadge } from "../game/mechanisms/sheriff/badge";
import { getIdiotState, setIdiotState } from "../game/mechanisms/roles/idiot/ports";

/** 同步决定本次放逐是否免死；原生命、阶段与后续死亡提交仍归引擎。 */
export function idiotVotedOutHook(
  world: World,
  targetId: EntityId,
  events: GameEvent[],
): VotedOutResult | null {
  const roleComp = world.getComponent(targetId, COMPONENT.Role);
  const aliveComp = world.getComponent(targetId, COMPONENT.Alive);
  if (!roleComp || !aliveComp || !aliveComp.alive) {
    return null;
  }
  if (roleComp.role !== Role.Idiot) {
    return null;
  }
  // 原生板子的审计查询先行；只有 null/undefined 才回退普通状态，异常不吞。
  if (demonIdiotRevealed(world, targetId) ?? getIdiotState(roleComp)?.revealed) {
    return { prevented: true, removed: [], reason: "idiot_already_revealed" };
  }

  // 原生提交拥有私有库存和审计；普通分支先翻牌，再依次关闭票权、清零票重。
  if (!commitDemonIdiotReveal(world, targetId)) {
    setIdiotState(roleComp, { revealed: true });
    const voting = world.getComponent(targetId, COMPONENT.VotingRight);
    if (voting) {
      voting.canVote = false;
      voting.weight = 0;
    }
  }

  // 后续警徽或事件失败不会退款已写的翻牌和票权；重复调用直接返回已翻牌结果。
  const badge = world.getComponent(targetId, COMPONENT.Badge);
  if (badge?.isSheriff) {
    transferOrDestroySheriffBadge(world, targetId, "idiot_revealed", events);
  }

  events.push({
    timestamp: Date.now(),
    type: "idiot_revealed",
    payload: { targetId },
  });

  return {
    prevented: true,
    removed: [],
    reason: "idiot_revealed",
  };
}

/**
 * 负责初始死亡波的完整婚约、恋人／梦与馥郁双生关系准备及原公开追加事实。
 * 输入为原可写名单／死因／已纳入席位／来源阶段容器和晚读取的运行查询；输出为同一双生回执与来源阶段 Map。
 * 婚约先于恋人／梦扩张，再登记来源阶段、准备双生回执并追加目标；死因仍在调用方同一容器原地覆盖或追加。
 * Night 的婚约关联不进入本步公开 additional_deaths，恋人关联及双生专用发布保持原政策和失败前缀。
 * 具体关系授权与已付绑定归各机制；本步不标死、付款、关闭许可、提交／取消回执、清理或确定胜负。
 * 准备回执只在结算器原 commit/cancel/finally 位置消费；运行关系／梦句柄不是 JSON 或玩家许可。
 */
import { Phase, DeathCause, type DeathSources, type EntityId, type GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../core/domain/world";
import type { DreamNightEffects } from "../core/domain/dream-night-effects";
import { expandLoversWave } from "../game/mechanisms/roles/cupid/death-ports";
import { prepareFragrantDeathWave } from "../game/mechanisms/roles/fragrant_pair_seer/ports";

/** 原具体婚约对象的窄方法视图；保留实例和 expand receiver，不创建第二个关系所有者。 */
export interface InitialWeddingExpansion {
  expand(ids: EntityId[], sources: DeathSources, seen: ReadonlySet<EntityId>, nightOrigin: Set<EntityId>): EntityId[];
}

/** 只在原表达式位置读取；装配时不取得 World、事件、日期、梦或具体婚约对象。 */
export interface InitialDeathRelationRuntime {
  world(): World;
  events(): GameEvent[];
  wedding(): InitialWeddingExpansion;
  phase(): Phase;
  resolutionDay(): number;
  ownsFragrant(): boolean;
  dreams(): DreamNightEffects | undefined;
}

/** 原双生准备回执不复制成授权数据，originPhases 用于原后续死亡波而非更改当前阶段。 */
export interface InitialDeathRelationPreparation {
  fragrantInitial: ReturnType<typeof prepareFragrantDeathWave>;
  originPhases: Map<EntityId, Phase>;
}

/** 同步准备完整初始关系；事件或后续字段读取失败时保留此前名单、来源与机制回执前缀。 */
export function prepareInitialDeathRelations(
  runtime: InitialDeathRelationRuntime,
  pending: EntityId[],
  allSources: DeathSources,
  seen: Set<EntityId>,
  nightOrigin: Set<EntityId>,
  initialPhases: Record<EntityId, Phase>,
): InitialDeathRelationPreparation {
  // 关系闭包先于标死、遗言和枪权判断；恋人／婚约追加的抑制死因不能等死亡 hook 后再补。
  const weddingInitial = runtime.wedding().expand(pending, allSources, seen, nightOrigin);
  const linkedInitial = expandLoversWave(
    runtime.world(),
    pending,
    allSources,
    runtime.events(),
    nightOrigin,
    seen,
    runtime.dreams(),
  );
  for (const id of [...linkedInitial, ...weddingInitial]) {
    seen.add(id);
    initialPhases[id] = nightOrigin.has(id) ? Phase.Night : runtime.phase();
  }
  const fragrantInitial = runtime.ownsFragrant()
    ? prepareFragrantDeathWave(runtime.world(), runtime.resolutionDay(), pending)
    : null;
  const fragrantRootPhase = fragrantInitial
    ? (initialPhases[fragrantInitial.rootId] ??
      (nightOrigin.has(fragrantInitial.rootId) ? Phase.Night : runtime.phase()))
    : runtime.phase();
  if (fragrantInitial?.addedTargetId !== null && fragrantInitial?.addedTargetId !== undefined) {
    const id = fragrantInitial.addedTargetId;
    pending.push(id);
    seen.add(id);
    // 原追加目标死因是覆盖而非合并；预约回执尚未提交，也不在这里付款或取消。
    allSources[id] = [DeathCause.FragrantLink];
    initialPhases[id] = fragrantRootPhase;
    if (fragrantRootPhase === Phase.Night) nightOrigin.add(id);
  }
  const originPhases = new Map(
    pending.map((id) => [id, initialPhases[id] ?? (nightOrigin.has(id) ? Phase.Night : runtime.phase())]),
  );
  // Night 婚约私密事实归具体机制；本步只沿原策略选择公开名单，不扩大披露范围。
  const publicLinkedInitial = [
    ...linkedInitial,
    ...(runtime.phase() === Phase.Night ? [] : weddingInitial),
  ];
  if (publicLinkedInitial.length && !runtime.ownsFragrant())
    runtime.events().push({
      timestamp: Date.now(),
      type: "additional_deaths",
      payload: { deaths: publicLinkedInitial },
    });
  return { fragrantInitial, originPhases };
}

/**
 * 负责骑士原白天提交和死亡前后日裁决的同步组合。输入为原运行查询与选择；输出为原裁决或同提案／元数据引用。
 * 当前性和夜已结算先短路，原资源与事件提交仍归骑士；无原型元数据仅含原execution，不隐式带夜保护。
 * 只有原提案成立才yield一次，经理在原点await真实死亡；失败不恢复，成功后才复查current、调用经理判胜并读endsDay。
 * 不标死、改阶段或缓存库存，也不添加Promise／许可；后项失败保已付资源和已发表事实。
 */
import { Phase, type KnightDuelSelection, type KnightDuelCommit, type GameEvent } from "../core/domain/model";
import type { World } from "../core/domain/world";
import { commitKnightDuel } from "../game/mechanisms/roles/knight/ports";

/** 原回调和成员在实际位置才读取；只声明所需接口，不把只读类型当运行权限隔离。 */
export interface KnightDaySettlementRuntime {
  readonly world: World;
  readonly events: GameEvent[];
  readonly isCurrent: () => boolean;
  readonly nightSettled: boolean;
  readonly dayRevision: number;
  checkResult(): boolean;
}

/** 只持原引用，不读duel字段、不复制或序列化；执行包保原null prototype和单一execution字段。 */
export interface KnightDayDeathStep {
  readonly duel: NonNullable<ReturnType<typeof commitKnightDuel>>;
  readonly duelMetadata: { execution: { phaseRevision: number } };
}

/** yield先于原DR等待；经理只在原resolve成功后恢复，current失败先于判胜和endsDay读取。 */
export function* settleKnightDay(
  runtime: KnightDaySettlementRuntime,
  choice: KnightDuelSelection,
): Generator<KnightDayDeathStep, KnightDuelCommit, void> {
  if (!runtime.isCurrent() || !runtime.nightSettled) return "rejected";
  const duel = commitKnightDuel(runtime.world, choice, Phase.Day, runtime.events);
  if (!duel) return "rejected";
  // 原决斗没有 nightEffects；新元数据包无原型，不让缺项读取继承的回调／保护 getter。
  const duelMetadata = Object.create(null) as { execution: { phaseRevision: number } };
  duelMetadata.execution = { phaseRevision: runtime.dayRevision };
  yield { duel, duelMetadata };
  if (!runtime.isCurrent()) return "terminal";
  if (runtime.checkResult()) return "terminal";
  return duel.endsDay ? "night" : "continue";
}

/**
 * 负责诡术师最终放逐映射、原事实发表、出局提案与公开字段的同步规则组合。
 * 输入为原目标、晚读 World／日期／事件与钩子 receiver、同一映射对象；输出为原有效目标、移除副本及摘要字段。
 * frame 唯一消费 exileResolved，映射对象仍作为事件 payload 同引用；发表失败不退回本次已付映射。
 * Noble 翻牌／必需发言仍由流水线在两业务块之间推进；missed 只抑制后续出局钩子，不跳过该窗口。
 * 票、PK、Animal 封票／河豚等待、放逐单位与阶段仍归原 owner；这里只准备提案和事实，不标死或授许可。
 * missed 与 effectiveId 在原点晚读，公开最终字段在摘要构造位置读取；异常保留已提交事件和钩子前缀。
 * 规则见 docs/rules/awa-trickster-exile-v1.md。
 */
import type { ReadonlyBoardConfig, EntityId, VotingSummary } from "@ai-werewolf-arena/game-contract";
import type { World } from "../core/domain/world";
import type { GameEvent } from "../core/domain/events";
import type { VotedOutResult } from "../game/mechanisms/hooks/hook_registry";
import { resolveTricksterExile } from "../game/mechanisms/roles/trickster/ports";

/** 原可写运行输出，不设新品牌或冻结；事件 payload 与后续查询必须仍指向同一对象。 */
export type MappedExile = ReturnType<typeof resolveTricksterExile>;

/** 属性由真实调用方 getter 延迟提供；readonly 不冻结 World、事件或政策，也不代表权限。 */
export interface MappedExilePreparationRuntime {
  readonly enabled: ReadonlyBoardConfig["trickster"];
  readonly world: World;
  readonly day: number;
  readonly events: GameEvent[];
}

/** 映射完成后先发表原对象，再读取 effectiveId；不可提前缓存以绕过原 push 回调。 */
export function prepareMappedExile(
  runtime: MappedExilePreparationRuntime,
  target: EntityId,
): { mapped: MappedExile | null; effectiveTarget: EntityId } {
  const mapped = runtime.enabled ? resolveTricksterExile(runtime.world, runtime.day, target) : null;
  if (mapped)
    runtime.events.push({ timestamp: Date.now(), type: "exile_target_mapped", payload: mapped });
  const effectiveTarget = mapped?.effectiveId ?? target;
  return { mapped, effectiveTarget };
}

/** 只公开本步实际需要的原钩子方法；方法仍用原对象 receiver，结构接口不是运行权限屏障。 */
export interface MappedExileResolutionRuntime {
  readonly world: World;
  readonly events: GameEvent[];
  readonly eventRegistry: {
    onVotedOut(world: World, targetId: EntityId, events: GameEvent[]): VotedOutResult;
  };
  readonly animalUnit: object | undefined;
}

/** 已完成原 Noble 交接后才执行；映射落空不退回原目标，Animal 仍抑制普通 voted_out 事实。 */
export function resolveMappedExile(
  runtime: MappedExileResolutionRuntime,
  mapped: MappedExile | null,
  effectiveTarget: EntityId,
): EntityId[] {
  const votedOut = mapped?.missed
    ? { removed: [] }
    : runtime.eventRegistry.onVotedOut(runtime.world, effectiveTarget, runtime.events);
  const removed = [...votedOut.removed];

  if (removed.includes(effectiveTarget) && !runtime.animalUnit) {
    // 只有原钩子返回真实移除提案才广播；白痴翻牌仍由原事件钩子单独发表。
    runtime.events.push({
      timestamp: Date.now(),
      type: "voted_out",
      payload: {
        target: effectiveTarget,
      },
    });
  }
  return removed;
}

/** 在原摘要展开位置再读 missed；上面的钩子／事件回调可修改同一映射，不缓存早期分类。 */
export function mappedExileSummary(
  mapped: MappedExile | null,
  effectiveTarget: EntityId,
): Pick<VotingSummary, "effectiveTarget"> {
  return mapped ? { effectiveTarget: mapped.missed ? null : effectiveTarget } : {};
}

/**
 * 负责雾鸦延迟夜的完整建立、领取、蛇选择及最终伤害准备／完成步骤。输入为经理的延迟原引用、
 * 同一待处理实例和当前性回调；输出同步步骤序列，原蛇 Promise 与准备伤害分别交回经理。
 * 经理唯一保存 pending，仍拥有阶段时钟、公开夜报、实际死亡提交、判胜和外层 abort；本组合不复制权威。
 * 原生命／伤害复制、疗救付款和窗口许可仍归本族原所有者。失败停在当前步骤，不退款、不自动完成或正常关闭。
 */
import type { EntityId, NightSummary } from "@ai-werewolf-arena/game-contract";
import type { ActionProvider } from "../core/domain/actions";
import type { GameEvent } from "../core/domain/events";
import type { World } from "../core/domain/world";
import type { AliveComponent } from "../core/domain/components/alive";
import { aliveLifeVersion } from "../core/domain/components/alive";
import { COMPONENT } from "../core/domain/components/names";
import type { DamageResolutionResult } from "../core/domain/systems/damage_resolution_system";
import type { DreamNightEffects } from "../core/domain/dream-night-effects";
import { Phase } from "@ai-werewolf-arena/game-contract";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import type { NightManagerLifecycle } from "./night-lifecycle-plan";
import { assertMistRosterCurrent } from "../game/mechanisms/roles/mist_raven/ports";
import { MistPendingNight } from "../game/mechanisms/roles/mist_raven/pending_night";
import { decideSnake } from "../game/mechanisms/roles/mist_raven/choice-ports";
import { GameActionRequestFactory } from "../game/engine/action_request_factory";
import { safeRecordLogicOp } from "../recording/session_recorder";

/** 只读取已交接的同一夜结果；原生命、梦句柄和伤害仍按各自所有者的既有规则处理。 */
export interface MistDelayedNightInput {
  deathLives: ReadonlyMap<EntityId, { life: AliveComponent; version: number | undefined }>;
  summary: Pick<NightSummary, "wolfTarget">;
  damage: DamageResolutionResult;
  dreamFrame: DreamNightEffects;
}

export interface MistDelayedNightOpening {
  readonly world: World;
  readonly cycleDay: number;
  readonly night: MistDelayedNightInput;
}

/** 先核名单／每个原生命，再构造唯一待处理实例；检查失败时经理原字段尚未被新实例替换。 */
export function prepareMistDelayedNight(runtime: MistDelayedNightOpening): MistPendingNight {
  assertMistRosterCurrent(runtime.world);
  for (const [id, scope] of runtime.night.deathLives) {
    if (
      runtime.world.getComponent(id, COMPONENT.Alive) !== scope.life ||
      !scope.life.alive ||
      scope.version === undefined ||
      aliveLifeVersion(scope.life) !== scope.version
    )
      throw new Error("mist_pending_life_stale");
  }
  return new MistPendingNight(
    runtime.world,
    runtime.cycleDay,
    runtime.night.summary.wolfTarget,
    runtime.night.damage,
    runtime.night.dreamFrame,
  );
}

/** 窄读取仍指向经理唯一字段；这里没有第二份 pending、阶段时钟或完成标志。 */
export interface MistDelayedNightSettlementRuntime {
  readonly pending: MistPendingNight | null;
  readonly world: World;
  readonly events: GameEvent[];
  readonly toolGateway: ToolGateway;
  readonly lifecycle: Pick<NightManagerLifecycle, "closeMistNormally">;
  readonly cycleDay: number;
}

/** 同一 current 闭包交给经理的真实死亡提交；这是运行数据，不是 JSON、许可或第二份状态。 */
export interface MistPreparedNightDamage {
  damage: DamageResolutionResult;
  current: () => boolean;
}

/** 两个 yield 都同步交回原对象；恢复协议仅用于这个具体延迟夜，不驱动其它角色或通用清理。 */
export function* settleMistDelayedNight(
  runtime: MistDelayedNightSettlementRuntime,
  actionProvider: ActionProvider,
  dayIsCurrent: () => boolean,
  alreadyClaimed: boolean,
): Generator<Promise<number | null> | MistPreparedNightDamage, void, number | null> {
  const pending = runtime.pending;
  if (!pending) throw new Error("mist_pending_night_missing");
  const current = () => dayIsCurrent() && pending === runtime.pending;
  if (!alreadyClaimed) pending.claim(current);
  // 第一次只交原蛇 Promise：经理在原位置等待，拒绝时不恢复下面的准备／完成步骤。
  const healed = yield decideSnake(
    runtime.world,
    runtime.events,
    runtime.toolGateway,
    actionProvider,
    pending,
    current,
    // 这里只捕获真实类的晚读取；窗口仍在原 roster／开窗之后 new，不提前创建请求或增加 await。
    { get requestFactory() { return GameActionRequestFactory; } },
  );
  const damage = pending.prepareFinalDamage(healed, current);
  safeRecordLogicOp({
    scope: "resolution",
    op: "night_damage_resolved",
    phase: Phase.Night,
    status: "ok",
    output: { deaths: damage.deaths, death_sources: damage.deathSources },
  });
  // 第二次交原伤害，经理同步发表夜报并等待真实 DeathResolution；成功之后才允许第三次 next。
  // 死亡提交失败不恢复这里，已付蛇和已发表／标死前缀保留，外层经理沿原路径 abort。
  yield { damage, current };
  assertMistRosterCurrent(runtime.world);
  pending.finish(current);
  runtime.lifecycle.closeMistNormally(runtime.cycleDay);
}

/**
 * 负责绑定原生已付效果命令与原延迟控制器。输入为原阶段上下文、回执／能力和延迟参数；
 * 输出保原付款前缀、增益事实及反射；命令绑定本身不读 World、事件、状态或来源，也不授权新资格。
 * 反射先取原提交 callee，再读取 World、本族同夜 binding、source 和种类；原状态命令负责资格与消费。
 * 原 context／receipt receiver 与每次读取点保持，不增加退款、复制或序列化运行句柄。
 */
import { Role } from "../core/domain/identity";
import type { NightLifeScope } from "../core/domain/night_effects";
import type { NightStageContext } from "../game/mechanisms/stages/night/contracts";
import type { NightAbilityReadView } from "../game/mechanisms/roles/abilities";
import {
  isScholarMentorBoard,
  recordScholarMentorNativeTarget,
  scholarMentorKnifeEligible,
} from "../game/mechanisms/roles/scholar_mentor/ports";
import {
  isEvilKnightBoard,
  commitEvilKnightReflection,
  evilKnightNightBinding,
} from "../game/mechanisms/roles/evil_knight/ports";
import {
  commitTimeConsortEffect,
  type TimeConsortReceipt,
} from "../game/mechanisms/roles/time_wolf_consort/ports";
import {
  loadDemonNativeNightController,
  loadDemonNativePotionController,
} from "../game/mechanisms/roles/demon_hunter/ports";
import type { NativeReflectedTarget } from "./native-night-target-policy";

export interface NativeNightEffects {
  commitReflectedTarget(
    receipt: NativeReflectedTarget | null,
    day: number,
    sourceId: number,
    kind: "check" | "guard" | "poison",
  ): void;
  recordModifierTarget(
    day: number,
    actorId: number,
    kind: "check" | "guard" | "poison",
    targetId: () => number | null,
  ): void;
  recordKnifeModifierTarget(targetId: () => number | null): void;
  commitNativeReflection(
    kind: "seer_check" | "poison",
    ability: NightAbilityReadView<"seer_check" | "potion">,
    targetId: number,
    source: () => NightLifeScope,
    isCurrent: () => boolean,
  ): void;
  loadSealedNightController: typeof loadDemonNativeNightController;
  loadSealedPotionController: typeof loadDemonNativePotionController;
}

/** 同一阶段上下文仍在原命令调用点交给已付效果命令，不复制引用或提前读取。 */
export function bindNativeNightEffects(context: () => NightStageContext): NativeNightEffects {
  return Object.freeze({
    commitReflectedTarget(
      receipt: NativeReflectedTarget | null,
      day: number,
      sourceId: number,
      kind: "check" | "guard" | "poison",
    ) {
      commitTimeConsortEffect(context(), receipt as TimeConsortReceipt | null, day, sourceId, kind);
    },
    recordModifierTarget(
      day: number,
      actorId: number,
      kind: "check" | "guard" | "poison",
      targetId: () => number | null,
    ) {
      if (isScholarMentorBoard(context().world))
        recordScholarMentorNativeTarget(context().world, day, actorId, kind, targetId());
    },
    recordKnifeModifierTarget(targetId: () => number | null) {
      if (isScholarMentorBoard(context().world)) {
        const actor = context()
          .world.getAliveEntityIds()
          .find((id) => scholarMentorKnifeEligible(context().world, context().currentDay(), id));
        if (actor !== undefined)
          recordScholarMentorNativeTarget(
            context().world,
            context().currentDay(),
            actor,
            "kill",
            targetId(),
          );
      }
    },
    commitNativeReflection(
      kind: "seer_check" | "poison",
      ability: NightAbilityReadView<"seer_check" | "potion">,
      targetId: number,
      source: () => NightLifeScope,
      isCurrent: () => boolean,
    ) {
      if (isEvilKnightBoard(context().world)) {
        if (
          ability.source.kind !== "native" ||
          ability.source.role !== (kind === "seer_check" ? Role.Seer : Role.Witch)
        )
          throw new Error(
            kind === "seer_check"
              ? "evil_knight_seer_source_invalid"
              : "evil_knight_witch_source_invalid",
          );
        const reflection = commitEvilKnightReflection(
          context().world,
          evilKnightNightBinding(context().state, targetId),
          source(),
          kind,
          isCurrent,
        );
        if (reflection) (context().state.retaliationAttacks ??= []).push(reflection);
      }
    },
    loadSealedNightController: loadDemonNativeNightController,
    loadSealedPotionController: loadDemonNativePotionController,
  });
}

/**
 * 负责组合原生夜间的失败政策与来源资格检查。输入为延迟 World 查询、阶段种类及活的只读能力引用，
 * 输出为原拒绝或继续；每次特性查询仍保留原短路及重复 World 读取。
 * 绑定函数不查询板子、actor、库存、时钟或请求；只读类型不复制或冻结引用。
 * 本策略不扣库存、不结算回执或发布事实，实际付款与效果提交仍归原所有者。
 */
import type { World } from "../core/domain/world";
import { Role } from "../core/domain/identity";
import type { NightAbilityReadView } from "../game/mechanisms/roles/abilities";
import { isRadiantEclipseBoard } from "../game/mechanisms/roles/radiant_eclipse/ports";
import { isScholarMentorBoard } from "../game/mechanisms/roles/scholar_mentor/ports";
import { isTimeConsortBoard } from "../game/mechanisms/roles/time_wolf_consort/ports";
import { isMagicianBoard } from "../game/mechanisms/roles/magician/ports";
import { isNightmareBoard } from "../game/mechanisms/roles/nightmare_shadow/ports";
import {
  isEvilKnightBoard,
  assertEvilKnightNativeActor,
} from "../game/mechanisms/roles/evil_knight/ports";
import { isFragrantPairBoard } from "../game/mechanisms/roles/fragrant_pair_seer/ports";
import { isNobleBodyBoard } from "../game/mechanisms/roles/noble_secret_body/ports";
import { isMistRavenBoard } from "../game/mechanisms/roles/mist_raven/ports";
import {
  isRedMoonBoard,
  demonHunterActorId,
  demonWitchRequiredThisNight,
} from "../game/mechanisms/roles/demon_hunter/ports";

export type NativeNightAction = "seer" | "guard" | "witch";

// 同一端口包含有序错误选择和来源校验；返回值／未抛错只说明该检查，不代表资源已付款。
export interface NativeNightFailurePolicy {
  scopeStale(kind: NativeNightAction): void;
  actionMissing(kind: NativeNightAction): void;
  actionInvalid(kind: NativeNightAction): void;
  strictWolfFailurePrefix(): string | null;
  usesDemonController(): boolean;
  requiresDemonPotionTurn(): boolean;
  assertNativeActor(actorId: number, role: Role): void;
  assertSeerSource(ability: NightAbilityReadView<"seer_check">): void;
  assertPotionSource(ability: NightAbilityReadView<"potion">): void;
  skipsEmptyBorrowedPotion(ability: NightAbilityReadView<"potion">): boolean;
}

/** 每次沿委托取得原 World 参数，不缓存 World，也不把一次板子命中当作后续许可。 */
export function bindNativeNightFailurePolicy(world: () => World): NativeNightFailurePolicy {
  const scopeStale = (kind: NativeNightAction): void => {
    if (kind !== "guard" && isRadiantEclipseBoard(world()))
      throw new Error(`radiant_eclipse_${kind}_scope_stale`);
    if (isScholarMentorBoard(world())) throw new Error(`scholar_mentor_${kind}_scope_stale`);
    if (isTimeConsortBoard(world())) throw new Error(`time_consort_${kind}_scope_stale`);
  };
  const actionRejected = (kind: NativeNightAction, reason: "missing" | "invalid"): void => {
    if (kind !== "guard" && isRadiantEclipseBoard(world()))
      throw new Error(`radiant_eclipse_${kind}_action_${reason}`);
    if (isScholarMentorBoard(world())) throw new Error(`scholar_mentor_${kind}_action_${reason}`);
    if (isTimeConsortBoard(world())) throw new Error(`time_consort_${kind}_action_${reason}`);
    if (kind === "guard") {
      if (isEvilKnightBoard(world())) throw new Error(`evil_knight_guard_action_${reason}`);
      return;
    }
    if (isMagicianBoard(world())) throw new Error(`magician_${kind}_action_${reason}`);
    if (isEvilKnightBoard(world()) || isNightmareBoard(world()))
      throw new Error(
        isNightmareBoard(world())
          ? `nightmare_${kind}_action_${reason}`
          : `evil_knight_${kind}_action_${reason}`,
      );
  };
  return Object.freeze({
    scopeStale,
    actionMissing: (kind: NativeNightAction) => actionRejected(kind, "missing"),
    actionInvalid: (kind: NativeNightAction) => actionRejected(kind, "invalid"),
    // 采用首个命中的严格板子前缀；每个查询都在该分支现场读取 World，不合并为缓存布尔值。
    strictWolfFailurePrefix() {
      if (isFragrantPairBoard(world())) return "fragrant_pair_seer";
      if (isNobleBodyBoard(world())) return "noble_secret_body";
      if (isRadiantEclipseBoard(world())) return "radiant_eclipse";
      if (isMistRavenBoard(world())) return "mist";
      if (isScholarMentorBoard(world())) return "scholar_mentor";
      if (isTimeConsortBoard(world())) return "time_consort";
      if (isNightmareBoard(world())) return "nightmare";
      if (isMagicianBoard(world())) return "magician";
      if (isRedMoonBoard(world())) return "red_moon";
      if (isEvilKnightBoard(world())) return "evil_knight";
      return null;
    },
    usesDemonController: () => demonHunterActorId(world()) !== null,
    requiresDemonPotionTurn: () => demonWitchRequiredThisNight(world()),
    assertNativeActor: (actorId: number, role: Role) =>
      assertEvilKnightNativeActor(world(), actorId, role),
    assertSeerSource(ability: NightAbilityReadView<"seer_check">) {
      if (
        isEvilKnightBoard(world()) &&
        (ability.source.kind !== "native" || ability.source.role !== Role.Seer)
      )
        throw new Error("evil_knight_seer_source_invalid");
    },
    assertPotionSource(ability: NightAbilityReadView<"potion">) {
      if (
        isEvilKnightBoard(world()) &&
        (ability.source.kind !== "native" || ability.source.role !== Role.Witch)
      )
        throw new Error("evil_knight_witch_source_invalid");
    },
    skipsEmptyBorrowedPotion: (ability: NightAbilityReadView<"potion">) =>
      isRadiantEclipseBoard(world()) &&
      ability.source.kind === "copy" &&
      ability.state.heal === 0 &&
      ability.state.poison === 0,
  });
}

/**
 * 负责组合原生夜间的目标映射、反射及药剂请求提示。输入为延迟的上下文、日次和目标读取，
 * 输出保留原目标与回执引用；类型视图不声明 commit，但不复制、冻结对象或移除其运行字段。
 * 板子检查与 resolver 参数仍在原时点求值；绑定时不选择 actor、快照库存或调用这些 getter。
 * 请求提示不授予权限，已付回执的消费仍归独立原生效果端口。
 */
import type { NightStageContext } from "../game/mechanisms/stages/night/contracts";
import type { NightLifeScope } from "../core/domain/night_effects";
import type { AliveComponent } from "../core/domain/components/alive";
import {
  isMagicianBoard,
  resolveMagicianNightTarget,
  type MagicianResolvedTarget,
} from "../game/mechanisms/roles/magician/ports";
import {
  isTimeConsortBoard,
  resolveTimeConsortTarget,
  type TimeConsortReceipt,
} from "../game/mechanisms/roles/time_wolf_consort/ports";
import {
  isScholarMentorBoard,
  scholarMentorBlocks,
} from "../game/mechanisms/roles/scholar_mentor/ports";

// readonly／Omit 仅限制此 TypeScript 查询视图；life、scope 与回执仍为原运行对象。
export type NativeTargetScope = Readonly<Omit<NightLifeScope, "life">> & {
  readonly life: Readonly<AliveComponent>;
};
export type NativeMappedTarget = Omit<MagicianResolvedTarget, "scope"> & {
  readonly scope: NativeTargetScope;
};
export type NativeReflectedTarget = Omit<TimeConsortReceipt, "commit" | "scope"> & {
  readonly scope: NativeTargetScope;
};

export interface NativeNightTargetPolicy {
  mappedTarget(day: () => number, targetId: () => number): NativeMappedTarget | null;
  reflectedTarget(
    day: () => number,
    sourceId: () => number,
    targetId: () => number,
    kind: "check" | "guard" | "poison",
  ): NativeReflectedTarget | null;
  potionModifierHints(actorId: number): { modifier_poison_blocked?: boolean };
  potionKnifeHints(): { wolf_targets?: number[] };
}

type TargetRuntime = Pick<NightStageContext, "world" | "currentDay" | "state">;

/** 即使日次或目标来自访问器，也只在对应板子分支命中后调用委托；绑定时不提前求值。 */
export function bindNativeNightTargetPolicy(context: () => TargetRuntime): NativeNightTargetPolicy {
  return Object.freeze({
    mappedTarget(day: () => number, targetId: () => number) {
      return isMagicianBoard(context().world)
        ? resolveMagicianNightTarget(context().world, day(), targetId())
        : null;
    },
    reflectedTarget(
      day: () => number,
      sourceId: () => number,
      targetId: () => number,
      kind: "check" | "guard" | "poison",
    ) {
      return isTimeConsortBoard(context().world)
        ? resolveTimeConsortTarget(context().world, day(), sourceId(), targetId(), kind)
        : null;
    },
    potionModifierHints(actorId: number) {
      return isScholarMentorBoard(context().world)
        ? {
            modifier_poison_blocked: scholarMentorBlocks(
              context().world,
              context().currentDay(),
              actorId,
              "poison",
            ),
          }
        : {};
    },
    // 仅学者导师板子读取原刀目标与附加刀；去重保首次出现次序，提示不消费伤害或回执。
    potionKnifeHints() {
      return isScholarMentorBoard(context().world)
        ? {
            wolf_targets: [
              ...new Set(
                [
                  context().state.wolfTarget,
                  ...(context().state.modifierKnifeTargets ?? []),
                ].filter((id): id is number => id !== null),
              ),
            ],
          }
        : {};
    },
  });
}

/**
 * 负责夜间有限机制组合的已提交重入准入；输入为原检查点现场读取的 World 和日次。
 * 输出为准入通过或原首个机制错误，十一项判断／十二个直接谓词调用点保持原固定顺序。
 * 提交证据仍归各机制，本模块不缓存 World、日次或演员，不写库存、重新开窗或撤销原已付效果。
 * 逐项查完才读取下一项，黑市交易与黑市受赠者保持原短路；失败不执行后续判断或新增清理策略。
 */
import type { World } from "../core/domain/world";
import { hasFoxInspectionNightCommit } from "../game/mechanisms/roles/cursed_fox/inspection_effect";
import { hasDreamNightCommit } from "../game/mechanisms/roles/dreamer/night_frame";
import { hasRoleInspectionNightCommit } from "../game/mechanisms/roles/role_inspection/night_scope";
import { hasMechanicalNightCommit } from "../game/mechanisms/roles/mechanical_wolf/night_scope";
import { hasBlackMarketNightCommit } from "../game/mechanisms/roles/black_market_merchant/night_stage";
import { hasRecipientNightCommit } from "../game/mechanisms/roles/recipient_ability_stage";
import { hasLuckyNightCommit } from "../game/mechanisms/roles/miracle_merchant/lucky_stage";
import { hasMerchantNightCommit } from "../game/mechanisms/roles/miracle_merchant/night_stage";
import { hasCupidNightCommit } from "../game/mechanisms/roles/cupid/relation";
import { hasHybridNightCommit } from "../game/mechanisms/roles/hybrid/night_stage";
import { hasAwakenedNightCommit } from "../game/mechanisms/roles/awakened_hidden_wolf/night_scope";
import { hasDeathAbilityActivationCommit } from "../game/mechanisms/roles/death_ability_activation";

/** 每个参数只在原谓词调用点读取；组合不提前收齐证据或替换机制自己的状态判断。 */
export interface NightCommitAdmissionRuntime {
  world(): World;
  day(): number;
}

/** 同步准入位于原开夜握手之后、起始记录和阶段推进之前；命中原当夜提交证据就拒绝重入，不撤销已付效果。 */
export function assertNightCommitAdmission(runtime: NightCommitAdmissionRuntime): void {
  if (hasFoxInspectionNightCommit(runtime.world(), runtime.day()))
    throw new Error("fox_inspection_night_reentry_after_commit");
  if (hasDreamNightCommit(runtime.world(), runtime.day()))
    throw new Error("dream_night_reentry_after_commit");
  if (hasRoleInspectionNightCommit(runtime.world(), runtime.day()))
    throw new Error("role_inspection_night_reentry_after_commit");
  if (hasMechanicalNightCommit(runtime.world(), runtime.day()))
    throw new Error("mechanical_night_reentry_after_commit");

  // 原黑市交易先判，已提交时不查询受赠者；两类提交归同一拒绝原因，不吞并幸运儿政策。
  if (
    hasBlackMarketNightCommit(runtime.world(), runtime.day()) ||
    hasRecipientNightCommit(runtime.world(), runtime.day(), "black_market")
  )
    throw new Error("black_market_night_reentry_after_commit");
  if (hasLuckyNightCommit(runtime.world(), runtime.day()))
    throw new Error("lucky_night_reentry_after_commit");
  if (hasMerchantNightCommit(runtime.world(), runtime.day()))
    throw new Error("merchant_night_reentry_after_commit");
  if (hasCupidNightCommit(runtime.world(), runtime.day()))
    throw new Error("cupid_night_reentry_after_commit");
  if (hasHybridNightCommit(runtime.world(), runtime.day()))
    throw new Error("hybrid_night_reentry_after_commit");
  if (hasAwakenedNightCommit(runtime.world(), runtime.day()))
    throw new Error("awakened_night_reentry_after_commit");
  if (hasDeathAbilityActivationCommit(runtime.world(), runtime.day()))
    throw new Error("death_ability_night_reentry_after_commit");
}

/**
 * 负责黎明前有限夜间效果的完整组合：封存明辉效果、创建原梦实例、核对白昼学者／寂夜导师增益，
 * 再按原字段顺序调用领域伤害结算；具名增益复验也供流水线在每次阶段 await 的原两侧调用。
 * 输入为原检查点的延迟参数，输出为同一梦句柄、原伤害结果或首个复验错误。
 * 具体效果仍持原生命／当前性回调；领域 DamageResolutionSystem 唯一折叠来源和消费印记。
 * resolve 的 callee／receiver 先于 World 和对象参数读取，角色查询 callee 也先于 Role 参数；
 * 本组合不提前收齐 input、不复制结果、不存第二份效果、不退款或隐藏已付／失败前缀。
 */
import { Role, type EntityId, type ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { World } from "../core/domain/world";
import type { DreamNightEffects } from "../core/domain/dream-night-effects";
import type { DamageResolutionSystem } from "../core/domain/systems/damage_resolution_system";
import type { NightStageContext, NightStageState } from "../game/mechanisms/stages/night/contracts";
import { DreamNightFrame } from "../game/mechanisms/roles/dreamer/night_frame";
import { readDreamNightLinks } from "../game/mechanisms/roles/dreamer/night-ports";
import { sealRadiantNightEffects } from "../game/mechanisms/roles/radiant_eclipse/ports";
import { assertScholarMentorBonusEffects } from "../game/mechanisms/roles/scholar_mentor/ports";

/** 只声明这一组合实际读取的原字段；这是同一阶段状态的类型视图，不创建或冻结副本。 */
type NightDamageClaims = Pick<
  NightStageState,
  | "modifierDeaths"
  | "poisonClaims"
  | "retaliationAttacks"
  | "nightImmunities"
  | "inspectionAttacks"
  | "foxInspections"
  | "guardClaims"
  | "merchantBacklashes"
  | "blackMarketBacklashes"
  | "mechanicalEffects"
  | "awakenedEffects"
>;

export interface NightDamageCompositionRuntime {
  ownsRadiant(): boolean;
  world(): World;
  day(): number;
  claims(): NightDamageClaims;
  config(): Pick<ReadonlyBoardConfig, "scholarMentor">;
  stageContext(): NightStageContext;
  solver(): Pick<DamageResolutionSystem, "resolve">;
  /** Role 参数延迟到原方法 callee 查找之后，不能在组合入口先取 enum 属性。 */
  aliveByRole(role: () => Role): EntityId[];
}

/** 同一规则门控在三个原检查点调用；只命中板子参数时才取原上下文，不提前读取或快照记录。 */
export function assertNightModifierBonusEffects(
  runtime: Pick<NightDamageCompositionRuntime, "config" | "stageContext">,
): void {
  if (runtime.config().scholarMentor) assertScholarMentorBonusEffects(runtime.stageContext());
}

/** 同步完成原四步组合，不改变前后记录／try-finally，也不重新打开已提交效果。 */
export function composeNightDamage(runtime: NightDamageCompositionRuntime): {
  dreamFrame: DreamNightEffects;
  damage: ReturnType<DamageResolutionSystem["resolve"]>;
} {
  const radiantEffects = runtime.ownsRadiant()
    ? sealRadiantNightEffects(runtime.world(), runtime.day())
    : undefined;
  // 保原 constructor callee、claims 与 shelters 参数顺序；读取同数组，不重建已付／原生命绑定。
  const dreamFrame = new DreamNightFrame(readDreamNightLinks(runtime.claims()), radiantEffects?.shelters);
  assertNightModifierBonusEffects(runtime);
  const damage = runtime.solver().resolve(runtime.world(), {
    intentNight: runtime.day(),
    radiantShelters: radiantEffects?.shelters,
    radiantBacklashes: radiantEffects?.backlashes,
    modifierDeaths: runtime.claims().modifierDeaths,
    protectedTargets: dreamFrame.protectedTargets(runtime.world()),
    immuneNightTargets: dreamFrame.immuneNightTargets(runtime.world()),
    consecutiveDeaths: dreamFrame.consecutiveDeaths(runtime.world()),
    poisonClaims: runtime.claims().poisonClaims,
    retaliationAttacks: runtime.claims().retaliationAttacks,
    nightImmunities: runtime.claims().nightImmunities,
    inspectionAttacks: runtime.claims().inspectionAttacks,
    foxInspections: runtime.claims().foxInspections,
    wolfImmuneTargets: runtime.aliveByRole(() => Role.CursedFox),
    guardClaims: runtime.claims().guardClaims,
    merchantBacklashes: runtime.claims().merchantBacklashes,
    blackMarketBacklashes: runtime.claims().blackMarketBacklashes,
    mechanicalEffects: runtime.claims().mechanicalEffects,
    awakenedEffects: runtime.claims().awakenedEffects,
  });
  return { dreamFrame, damage };
}

/**
 * 负责夜阶段前／后及伤害前的两种狼刀现场准入与过期清理。输入为原 World、stageState、婚约归属和日期的延迟读取；
 * 输出为原标记移除和目标清空，普通狼刀先执行，婚约存在才读取第二组参数。各子步骤 return 只结束本步。
 * 普通刀保原生命／版本／标记／目标政策，先移原 marks 再移现场 marks，随后才清 stage；婚约刀仅移原 marks。
 * 中途失败保原已写前缀，不补新刀、付款、回滚或关闭。运行 thunks 和 scope 引用不是 JSON、快照或行动许可。
 * 本组合不增加 await、current 检查或清理守卫；原投票、目标查询和婚约权威仍拥有各自政策与资源。
 */
import { bindWolfKnifeTargetQuery } from "../game/mechanisms/roles/wolf/ports";
import { weddingKnifeCurrent } from "../game/mechanisms/roles/ghost_bride/ports";
import { aliveLifeVersion } from "../core/domain/components/alive";
import { COMPONENT } from "../core/domain/components/names";
import { StatusMark } from "../core/domain/model";
import type { World } from "../core/domain/world";
import type { NightStageState } from "../game/mechanisms/stages/night/contracts";

/** 仅持有原表达式的延迟读取，不能序列化、预读或将阶段声明当作提交许可。 */
export interface NightKnifeAdmissionRuntime {
  readonly world: () => World;
  readonly state: () => NightStageState;
  readonly ownsWedding: () => boolean;
  readonly day: () => number;
}

/** 原普通刀历史票仍已记录；过期刀按原生命／marks／目标政策撤下，不伤害新生命。 */
function discardStaleWolfKnife(world: World, state: NightStageState): void {
  const scope = state.wolfTargetScope;
  if (!scope) return;
  if (
    world.getComponent(scope.targetId, COMPONENT.Alive) === scope.life &&
    scope.life.alive &&
    aliveLifeVersion(scope.life) === scope.version &&
    world.getComponent(scope.targetId, COMPONENT.StatusMarks) === scope.marks &&
    bindWolfKnifeTargetQuery(world).allows(scope.targetId)
  )
    return;
  scope.marks.remove(StatusMark.WolfKillMark);
  world.getComponent(scope.targetId, COMPONENT.StatusMarks)?.remove(StatusMark.WolfKillMark);
  state.wolfTarget = null;
  state.wolfTargetScope = undefined;
}

/** 婚约只复验原权威；即使当前 scope 为空，调用方仍先读取原 world／day／state 参数。 */
function discardStaleWeddingKnife(world: World, day: number, state: NightStageState): void {
  const scope = state.wolfTargetScope;
  if (!scope || weddingKnifeCurrent(world, day, scope.targetId)) return;
  scope.marks.remove(StatusMark.WolfKillMark);
  state.wolfTarget = null;
  state.wolfTargetScope = undefined;
}

/** 固定两个独立步骤的原先后顺序；前步无刀 return 不跳过婚约条件，false 不读取婚约参数。 */
export function discardStaleNightKnives(runtime: NightKnifeAdmissionRuntime): void {
  discardStaleWolfKnife(runtime.world(), runtime.state());
  if (runtime.ownsWedding()) discardStaleWeddingKnife(runtime.world(), runtime.day(), runtime.state());
}

