}

export class NightManagerLifecycle implements NightLifecycleHandoff {
  // 交接前保留原早失败终止入口；不是 acquired 回执，不给原无条件关闭增加守卫。
  private demon: Pick<DemonNightUnit, "close"> = demonNightTerminal;
  private wedding: Pick<WeddingNightUnit, "close"> = weddingNightTerminal;
  private magician: Pick<MagicianNightUnit, "closeNormally" | "abort"> = magicianNightTerminal;
  private sorcerer: Pick<WolfSorcererNightUnit, "closeNormally" | "abort"> =
    wolfSorcererNightTerminal;
  private trickster: Pick<TricksterNightUnit, "finishNormally" | "abort"> =
    tricksterNightTerminal;
  private time: Pick<TimeConsortNightUnit, "closeNormally" | "abort"> = timeConsortNightTerminal;
  private scholar: Pick<ScholarMentorNightUnit, "closeNormally" | "abort"> =
    scholarMentorNightTerminal;
  private mist: Pick<MistNightUnit, "closeNormally" | "abort"> = mistNightTerminal;

  constructor(private readonly runtime: NightManagerLifecycleRuntime) {}

  receiveDemon(unit: DemonNightUnit): void {
    this.demon = unit;
  }

  receiveWedding(unit: WeddingNightUnit): void {
    this.wedding = unit;
  }

  receiveExchange(
    magician: MagicianNightUnit,
    sorcerer: WolfSorcererNightUnit,
    trickster: TricksterNightUnit,
  ): void {
    this.magician = magician;
    this.sorcerer = sorcerer;
    this.trickster = trickster;
  }

  receiveTimeConsort(unit: TimeConsortNightUnit): void {
    this.time = unit;
  }

  receiveScholarMentor(unit: ScholarMentorNightUnit): void {
    this.scholar = unit;
  }

  receiveMist(unit: MistNightUnit): void {
    this.mist = unit;
  }

  /** 原夜末到期的 World 参数先求值，再读取当次 day；同一接收方保留实际 Night 身份。 */
  expireNobleAtNightEnd(result: { interrupted: false }, day: () => number) {
    return expireNobleNight(result, () => this.runtime.world, day);
  }

  closeNobleNormally(result: { interrupted: false }, day: number): void {
    nobleNightReceiver(result).closeNormally(this.runtime.world, day);
  }

  abortSpecialNight(result: object, day: number): void {
    if (this.runtime.config.nobleSecretBody)
      nobleNightReceiver(result).abort(this.runtime.world, day);
    this.demon.close(this.runtime.world);
    this.wedding.close(this.runtime.world);
  }

  /** 原顺序逐角色读取 config／current；前一关闭可能改变后一个资格，不能批量预算或并行。 */
  finishDay(day: number, isCurrent: () => boolean): void {
    if (this.runtime.config.trickster && isCurrent()) this.trickster.finishNormally(this.runtime.world, day);
    if (this.runtime.config.wolfSorcerer && isCurrent()) this.sorcerer.closeNormally(this.runtime.world, day);
    if (this.runtime.config.magician && isCurrent()) this.magician.closeNormally(this.runtime.world, day);
    if (this.runtime.config.timeConsort && isCurrent()) this.time.closeNormally(this.runtime.world, day);
    if (this.runtime.config.scholarMentor && isCurrent()) this.scholar.closeNormally(this.runtime.world, day);
    if (this.runtime.config.mistRaven && isCurrent()) this.mist.closeNormally(this.runtime.world, day);
  }

  closeMistNormally(day: number): void {
    this.mist.closeNormally(this.runtime.world, day);
  }

  abortInner(): void {
    if (this.runtime.config.mistRaven) this.mist.abort(this.runtime.world);
    if (this.runtime.config.trickster) this.trickster.abort(this.runtime.world);
    if (this.runtime.config.wolfSorcerer) this.sorcerer.abort(this.runtime.world);
    if (this.runtime.config.magician) this.magician.abort(this.runtime.world);
    if (this.runtime.config.timeConsort) this.time.abort(this.runtime.world);
    if (this.runtime.config.scholarMentor) this.scholar.abort(this.runtime.world);
  }

  abortOnError(): void {
    if (this.runtime.config.animalDream) abortAnimalGame(this.runtime.world);
  }

  abortCycle(completed: boolean): void {
    if (this.runtime.config.animalDream && !completed) abortAnimalGame(this.runtime.world);
    if (this.runtime.config.mistRaven) {
      this.runtime.abortMistPending();
      this.mist.abort(this.runtime.world);
    }
    if (this.runtime.config.timeConsort) this.time.abort(this.runtime.world);
    if (this.runtime.config.scholarMentor) this.scholar.abort(this.runtime.world);
    if (this.runtime.config.wolfSorcerer) this.sorcerer.abort(this.runtime.world);
    if (this.runtime.config.magician) this.magician.abort(this.runtime.world);
  }
}

export interface NightPipelineLifecycleRuntime {
  readonly world: World;
  readonly events: import("@ai-werewolf-arena/game-contract").GameEvent[];
  readonly random: RandomSource;
}

/** 保持 try 之前的开夜和每个具体构造函数的原位置，失败不回滚已发生前缀。 */
export function prepareNightPipelineLifecycle(
  runtime: NightPipelineLifecycleRuntime,
  config: ReadonlyBoardConfig,
  day: number,
  handoff?: () => NightLifecycleHandoff | undefined,
  expectedParameters?: BoardParameters,
) {
    // setup/current 门禁已通过；准备中的早开夜或失败仍属于这次真实尝试。
    const nightUnit = openNightUnit(day);
    // 先在原参数位置捕获 World，再绑定参数；身份检查不会增加一次 World getter 读取。
    let parameterWorld: World;
    let parameters: BoardParameters;
    const closeLonelyGirlNight = openLonelyGirlNight(
      ((parameterWorld = runtime.world),
      (config = (parameters = bindBoardParameters(parameterWorld, config)).board),
      (expectedParameters && parameters !== expectedParameters
        ? (() => { throw new Error("rule_plan_parameter_mismatch"); })()
        : undefined),
      parameterWorld),
      day,
    );
    const closeWildChildNight = openWildChildNight(runtime.world, day, runtime.events);
    const closeThiefNight = openInitialIdentityNight(runtime.world, day);
    const ownsWedding = weddingSetup(runtime.world) !== null;
    const ownsDemon = demonHunterActorId(runtime.world) !== null;
    const magicianNight = new ConcreteMagicianNightUnit({
      get world() {
        return pipeline.world;
      },
    });
    const wolfSorcererNight = new ConcreteWolfSorcererNightUnit(
      {
        get world() {
          return pipeline.world;
        },
      },
      magicianNight.cleanupOwnership,
    );
    const tricksterNight = new ConcreteTricksterNightUnit(
      {
        get world() {
          return pipeline.world;
        },
      },
      magicianNight.cleanupOwnership,
    );
    const timeConsortNight = new ConcreteTimeConsortNightUnit({
      get world() {
        return pipeline.world;
      },
    });
    const scholarMentorNight = new ConcreteScholarMentorNightUnit({
      get world() {
        return pipeline.world;
      },
    });
    const ownsNoble = config.nobleSecretBody !== undefined;
    const ownsFragrant = config.fragrantPairSeer !== undefined;
    const ownsAnimal = config.animalDream !== undefined;
    const pipeline = runtime;
    const animalNight = new AnimalNightUnit(
      {
        get world() {
          return pipeline.world;
        },
        get events() {
          return pipeline.events;
        },
      },
      day,
    );
    const fragrantNight = new FragrantNightUnit(
      {
        get world() {
          return pipeline.world;
        },
        get events() {
          return pipeline.events;
        },
        drawKnowledge() {
          return randomDraws(pipeline.random.fork("fragrant-known-wolf"));
        },
        recordOpening(day, notice) {
          getSessionRecorder()?.recordRequiredLogicOp({
            scope: "phase_pipeline",
            op: "fragrant_night_opened",
            phase: Phase.Night,
            status: "ok",
            output: {
              policy: FRAGRANT_PAIR_POLICY,
              day,
              notice,
              knowledgeDrawCount: day === 1 ? 1 : 0,
            },
          });
        },
      },
      day,
    );
    const nobleNight = new NobleNightUnit(
      {
        get world() {
          return pipeline.world;
        },
        get events() {
          return pipeline.events;
        },
        recordOpening(payload) {
          getSessionRecorder()?.recordRequiredLogicOp({
            scope: "phase_pipeline",
            op: "noble_body_night_opened",
            phase: Phase.Night,
            status: "ok",
            output: payload,
          });
        },
      },
      day,
      nightUnit,
    );
    const ownsRadiant = config.radiantEclipse !== undefined;
    const radiantNight = new RadiantNightUnit(
      {
        get world() {
          return pipeline.world;
        },
        get events() {
          return pipeline.events;
        },
      },
      day,
    );
    const ownsMist = config.mistRaven !== undefined;
    const mistNight = new ConcreteMistNightUnit(
      {
        get world() {
          return pipeline.world;
        },
        get events() {
          return pipeline.events;
        },
      },
      day,
    );
    const demonNight = new ConcreteDemonNightUnit({
      get world() {
        return pipeline.world;
      },
    });
    const weddingNight = new ConcreteWeddingNightUnit(
      {
        get world() {
          return pipeline.world;
        },
        get events() {
          return pipeline.events;
        },
      },
      ownsWedding,
    );
  return {
    nightUnit, config, parameters, ownsWedding, ownsDemon, ownsNoble, ownsFragrant, ownsAnimal, ownsRadiant, ownsMist,
    animalNight, fragrantNight, nobleNight, radiantNight, mistNight,
    demonNight, weddingNight, magicianNight, wolfSorcererNight, tricksterNight,
    timeConsortNight, scholarMentorNight,
    open(isCurrent: () => boolean) {
      if (ownsAnimal) animalNight.open(isCurrent);
      if (ownsFragrant) fragrantNight.open(isCurrent);
      if (ownsNoble) nobleNight.open(isCurrent);
      if (ownsRadiant) radiantNight.open();
      if (ownsDemon) demonNight.open(day, isCurrent);
      if (ownsMist) mistNight.open();
    },
    // 正常关闭后逐项 transfer，handoff 仍晚读取；中途失败不撤销已发生的所有权交接。
    finishPipeline() {
      if (ownsRadiant) radiantNight.closeNormally();
      if (ownsAnimal) animalNight.closeNormally();
      if (ownsFragrant) fragrantNight.closeNormally();
      if (ownsNoble) nobleNight.transferToManager();
      weddingNight.transferToManager(ownsWedding);
      handoff?.()?.receiveWedding(weddingNight);
      demonNight.transferToManager(ownsDemon);
      handoff?.()?.receiveDemon(demonNight);
      magicianNight.transferToManager(config.magician !== undefined);
      handoff?.()?.receiveExchange(magicianNight, wolfSorcererNight, tricksterNight);
      timeConsortNight.transferToManager(config.timeConsort !== undefined);
      handoff?.()?.receiveTimeConsort(timeConsortNight);
      scholarMentorNight.transferToManager(config.scholarMentor !== undefined);
      handoff?.()?.receiveScholarMentor(scholarMentorNight);
      mistNight.transferToManager(ownsMist);
      handoff?.()?.receiveMist(mistNight);
    },
    // 各具体单位按自身 acquired／owned 规则清理；Demon 失败 open 与 Wedding 失败 capture 语义不同。
    abortPipeline() {
      animalNight.abortIfOwned();
      fragrantNight.abortIfOwned();
      nobleNight.abortIfOwned();
      radiantNight.abortIfAcquired();
      if (ownsMist) mistNight.abortIfOwned();
      if (config.trickster) tricksterNight.abortIfOwned();
      if (config.wolfSorcerer) wolfSorcererNight.abortIfOwned();
      if (config.magician) magicianNight.abortIfOwned();
      if (config.timeConsort) timeConsortNight.abortIfOwned();
      if (config.scholarMentor) scholarMentorNight.abortIfOwned();
      demonNight.abortIfOwned();
      weddingNight.abortIfOwned();
      closeThiefNight();
      closeWildChildNight();
      closeLonelyGirlNight();
    },
  };
}

/**
 * 负责夜间设置准入与逐检查点的名单可读性组合。输入为原 World、已捕获的机制归属和板子参数查询；
 * 输出为通过或按原顺序抛出的首个错误。设置在取消检查前校验，名单在开夜后及行动 await 两侧复验。
 * 各机制权威拥有原体、生命、库存和失效状态；本组合不缓存名单、不写资源、不新建窗口或改变阶段。
 * 所有查询仍在原表达式处读取，命中失败立即停止；猎魔 marks 保原逐编号短路，不把合法数据当许可。
 */
import type { World } from "../core/domain/world";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { hasActiveGhostBride, ghostBrideReady } from "../game/mechanisms/roles/ghost_bride/ports";
import { hasActiveLonelyGirl, lonelyGirlReady } from "../game/mechanisms/roles/lonely_girl/ports";
import { hasActiveWildChild, wildChildReady } from "../game/mechanisms/roles/wild_child/ports";
import { hasActiveInitialIdentitySetup, initialIdentitySetupReady, initialIdentityKind } from "../game/mechanisms/roles/initial_identity/ports";
import { animalAuthoritySnapshot } from "../game/mechanisms/roles/animal_dream/ports";
import { fragrantAuthoritySnapshot } from "../game/mechanisms/roles/fragrant_pair_seer/ports";
import { assertNobleBodyRosterCurrent } from "../game/mechanisms/roles/noble_secret_body/ports";
import { assertRadiantRosterCurrent } from "../game/mechanisms/roles/radiant_eclipse/ports";
import { assertMistRosterCurrent } from "../game/mechanisms/roles/mist_raven/ports";
import { assertTricksterRosterCurrent } from "../game/mechanisms/roles/trickster/ports";
import { assertWolfSorcererRosterCurrent } from "../game/mechanisms/roles/wolf_sorcerer/ports";
import { assertTimeConsortRosterCurrent } from "../game/mechanisms/roles/time_wolf_consort/ports";
import { assertScholarMentorRosterCurrent } from "../game/mechanisms/roles/scholar_mentor/ports";
import { assertMagicianRosterCurrent } from "../game/mechanisms/roles/magician/ports";
import { assertNightmareRosterCurrent } from "../game/mechanisms/roles/nightmare_shadow/ports";
import { assertEvilKnightRosterCurrent } from "../game/mechanisms/roles/evil_knight/ports";
import { assertDemonNightReadable } from "../game/mechanisms/roles/demon_hunter/ports";
import { demonWitchMarksSafe } from "../game/mechanisms/roles/demon_hunter/ports";

/** 只在原位置读取实际 World；不在创建查询对象时启动任何设置或反射玩家组件。 */
export interface NightSetupRuntime { world(): World; }

/** 归属是本次生命周期已捕获的值，参数仍来自原局部 config；不是可序列化的授权或新库存快照。 */
export interface NightReadabilityRuntime extends NightSetupRuntime {
  config(): Pick<ReadonlyBoardConfig, "trickster" | "wolfSorcerer" | "timeConsort" | "scholarMentor" | "magician">;
  ownsAnimal(): boolean;
  ownsFragrant(): boolean;
  ownsNoble(): boolean;
  ownsRadiant(): boolean;
  ownsMist(): boolean;
  ownsDemon(): boolean;
}

export function assertNightSetupReady(runtime: NightSetupRuntime): void {
  if (hasActiveGhostBride(runtime.world()) || !ghostBrideReady(runtime.world()))
    throw new Error("ghost_bride_setup_before_night_required");
  if (hasActiveLonelyGirl(runtime.world()) || !lonelyGirlReady(runtime.world()))
    throw new Error("lonely_girl_setup_before_night_required");
  if (hasActiveWildChild(runtime.world()) || !wildChildReady(runtime.world()))
    throw new Error("wild_child_setup_before_night_required");
  if (hasActiveInitialIdentitySetup(runtime.world()) || !initialIdentitySetupReady(runtime.world()))
    throw new Error(`${initialIdentityKind(runtime.world()) ?? "thief"}_setup_before_night_required`);
}

/** 每个检查点重新遍历既有权威；关闭与失败清理由流水线及生命周期 owner 负责。 */
export function assertNightReadable(runtime: NightReadabilityRuntime): void {
  if (runtime.ownsAnimal() && !animalAuthoritySnapshot(runtime.world()))
    throw new Error("animal_authority_revoked");
  if (runtime.ownsFragrant()) fragrantAuthoritySnapshot(runtime.world());
  if (runtime.ownsNoble()) assertNobleBodyRosterCurrent(runtime.world());
  if (runtime.ownsRadiant()) assertRadiantRosterCurrent(runtime.world());
  if (runtime.ownsMist()) assertMistRosterCurrent(runtime.world());
  if (runtime.config().trickster) assertTricksterRosterCurrent(runtime.world());
  if (runtime.config().wolfSorcerer) assertWolfSorcererRosterCurrent(runtime.world());
  if (runtime.config().timeConsort) assertTimeConsortRosterCurrent(runtime.world());
  if (runtime.config().scholarMentor) assertScholarMentorRosterCurrent(runtime.world());
  if (runtime.config().magician) assertMagicianRosterCurrent(runtime.world());
  assertNightmareRosterCurrent(runtime.world());
  assertEvilKnightRosterCurrent(runtime.world());
  if (!runtime.ownsDemon()) return;
  assertDemonNightReadable(runtime.world());
  if (!runtime.world().entityIds().every((id) => demonWitchMarksSafe(runtime.world(), id)))
    throw new Error("demon_hunter_unreadable_marks");
}

/**
 * 负责普通伤害结算之前猎魔夜的完整来源交付：原救／毒 token、狼刀来源闭包与守护封存。
 * 输入是同一夜状态、原 World／日次及本次归属的延迟查询；输出为原运行 token 和保护视图。
 * 先封存已付用药，再复制原投票者与捕获刀口，逐条封存原守护贡献，最后创建原五字段保护。
 * 库存、proof、原体及付款仍由具体权威持有；本组合不新增当前性、回合、schema、清理或提交许可。
 * guardCurrent 在普通伤害清除 marks 之后现场查询；原生撤权不能抹掉独立／未知守护。
 * 这些闭包、token、原组件和贡献只供运行时后续折叠，不是玩家知识或可编码的 JSON 数据。
 */
import {
  sealNativeGuardContribution,
  lateUnknownGuardContribution,
} from "../game/mechanisms/roles/demon_hunter/guard_contribution";
import {
  demonOriginalWolfSourceCurrent,
  demonOriginalWolfTargetCurrent,
  type DemonKnifeProtection,
} from "../game/mechanisms/roles/demon_hunter/ports";
import { sealDeliveredDemonWitchSources } from "../game/mechanisms/roles/demon_hunter/native_potion_controller";
import { COMPONENT } from "../core/domain/components/names";
import { StatusMark } from "../core/domain/model";
import { statusMarkSnapshot } from "../core/domain/components/status_marks";
import { livingNightLife } from "../core/domain/night_effects";
import type { World } from "../core/domain/world";
import type { NightStageState } from "../game/mechanisms/stages/night/contracts";

/** 同一阶段状态的窄类型视图；数组、刀口和原生命引用不复制成另一个授权 store。 */
type NightSourceClaims = Pick<NightStageState, "wolfTargetVoters" | "wolfTargetScope" | "guardClaims">;

/** 查询在原表达式位置执行；world／day 仍由返回的来源闭包晚读，不在入口批量缓存。 */
export interface NightSourceDeliveryRuntime {
  ownsDemon(): boolean;
  world(): World;
  day(): number;
  claims(): NightSourceClaims;
}

/** 原三项交付是运行句柄；五字段保护复用本族唯一声明，不公开原库存、proof 或可写 Map。 */
export interface NightSourceDelivery {
  demonSources: object | undefined;
  demonWolfSourceCurrent: ((targetId: number) => boolean) | undefined;
  demonKnifeProtection: DemonKnifeProtection | undefined;
}

/** 同步保持原封存前缀；后续 claim／snapshot 失败不撤销已经成功封存的原 token 或贡献。 */
export function prepareNightSourceDelivery(runtime: NightSourceDeliveryRuntime): NightSourceDelivery {
  const demonSources = runtime.ownsDemon() ? sealDeliveredDemonWitchSources(runtime.world(), runtime.day()) : undefined;
  const demonWolfActors = [...(runtime.claims().wolfTargetVoters ?? [])];
  const knifeScope = runtime.claims().wolfTargetScope;
  const demonWolfTarget = knifeScope?.targetId;
  const demonWolfSourceCurrent = runtime.ownsDemon()
    ? (targetId: number) =>
        targetId === demonWolfTarget &&
        demonOriginalWolfSourceCurrent(runtime.world(), runtime.day(), demonWolfActors) &&
        demonOriginalWolfTargetCurrent(runtime.world(), runtime.day(), targetId)
    : undefined;
  // 守护贡献逐条先封存，普通伤害尚未清印记；后条失败保留前条和用药 token 已封存的前缀。
  const demonGuardSources = runtime.ownsDemon()
    ? (runtime.claims().guardClaims ?? []).flatMap((claim) =>
        claim.contribution
          ? [{ claim, sealed: sealNativeGuardContribution(claim.contribution) }]
          : [],
      )
    : [];
  // 即使不归属猎魔夜，也保持原刀口印记读取；独立守护知识不能被原生资格撤销抹掉。
  const demonUnknownGuard =
    knifeScope && statusMarkSnapshot(knifeScope.marks, StatusMark.GuardMark)?.present === true;
  const demonKnifeProtection =
    runtime.ownsDemon() && knifeScope
      ? Object.freeze({
          targetId: knifeScope.targetId,
          wolf: statusMarkSnapshot(knifeScope.marks, StatusMark.WolfKillMark)?.present === true,
          guard:
            statusMarkSnapshot(knifeScope.marks, StatusMark.GuardMark)?.present === true &&
            (!(runtime.claims().guardClaims ?? []).some(
              (claim) => claim.target.id === knifeScope.targetId,
            ) ||
              (runtime.claims().guardClaims ?? []).some(
                (claim) =>
                  claim.target.id === knifeScope.targetId &&
                  claim.marks === knifeScope.marks &&
                  livingNightLife(runtime.world(), claim.target),
              )),
          guardCurrent: () => {
            const sources = demonGuardSources.filter(
              ({ claim }) => claim.target.id === knifeScope.targetId,
            );
            if (!sources.length)
              return (
                !!demonUnknownGuard ||
                statusMarkSnapshot(
                  runtime.world().getComponent(knifeScope.targetId, COMPONENT.StatusMarks),
                  StatusMark.GuardMark,
                )?.present === true
              );
            // 独立／迟到 unknown 先短路；只有原生贡献分支才晚复验原回调与目标生命。
            return sources.some(
              ({ claim, sealed }) =>
                sealed.unknown ||
                lateUnknownGuardContribution(claim.contribution!) ||
                (sealed.native &&
                  claim.isCurrent?.() === true &&
                  livingNightLife(runtime.world(), claim.target)),
            );
          },
          heal: statusMarkSnapshot(knifeScope.marks, StatusMark.HealMark)?.present === true,
        })
      : undefined;
  return { demonSources, demonWolfSourceCurrent, demonKnifeProtection };
}

/**
 * 负责：按原算法收集、去重和排序有限夜间阶段，并标记观察到的来源。
 * 输入：只读板子、角色目录与可选当前 World；输出：原 handler 和快照或不透明模式。
 * 默认贡献的成员及潜在能力元数据交给 RulePlan 固定；collector 本身不拥有整局规则。
 * 普通原生密集数组可冻结成员，虚方法、Proxy、访问器或惰性来源保留原晚拉取及失败前缀。
 * 描述器检查不额外执行 getter，原 handler、World 和能力实例均不冻结。
 * 共享注册与鬼魂新娘替换保留原对象及先后次序，来源信息不授予行动资格。
 */
import type { NightAbilityKind } from "@ai-werewolf-arena/game-contract";

import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { demonHunterActorId } from "../game/mechanisms/roles/demon_hunter/authority";
import { types } from "node:util";
import { DEMON_HUNTER_NIGHT_STAGE } from "../game/mechanisms/roles/demon_hunter/night_stages";
import {
  WEDDING_CHAT_STAGE,
