const unknownOverrideSources: readonly NightStageContributionSource[] = Object.freeze([
  Object.freeze({ kind: "unknown", reason: "override" } as const),
]);
const unknownReferenceSources: readonly NightStageContributionSource[] = Object.freeze([
  Object.freeze({ kind: "unknown", reason: "unobserved-reference" } as const),
]);

/** 只包装刚拉取的 handler，外部下一次拉取仍在其执行之后发生。 */
function opaqueExecutionEntries(
  source: Iterable<NightStageHandler>,
): Iterable<NightStageExecutionEntry> {
  return Object.freeze({
    *[Symbol.iterator]() {
      for (const handler of source)
        yield Object.freeze({ handler, sources: unknownOverrideSources });
    },
  });
}

/** 原 spread 完成后才用自有数字槽附加来源，不重读外部贡献字段。 */
function rememberAppendedSources(
  collected: readonly NightStageHandler[],
  start: number,
  source: NightStageContributionSource,
  sources: Map<NightStageHandler, NightStageContributionSource[]>,
): void {
  for (let index = start; index < collected.length; index++) {
    const handler = collected[index]!;
    const original = sources.get(handler) ?? [];
    original.push(source);
    sources.set(handler, original);
  }
}

/** 只查看普通数组的数字槽描述器，不拉取外部 iterator 或调用 index getter。 */
function snapshotMembers<T>(source: T[]): T[] | null {
  if (
    types.isProxy(source) ||
    !Array.isArray(source) ||
    Object.getPrototypeOf(source) !== Array.prototype ||
    Object.getOwnPropertyDescriptor(source, Symbol.iterator) !== undefined
  )
    return null;
  const iterator = Object.getOwnPropertyDescriptor(Array.prototype, Symbol.iterator),
    values = Object.getOwnPropertyDescriptor(Array.prototype, "values");
  if (
    !iterator ||
    !("value" in iterator) ||
    !values ||
    !("value" in values) ||
    typeof iterator.value !== "function" ||
    iterator.value !== values.value
  )
    return null;
  const length = Object.getOwnPropertyDescriptor(source, "length");
  if (!length || !("value" in length)) return null;
  const members: T[] = [];
  for (let index = 0; index < length.value; index++) {
    const entry = Object.getOwnPropertyDescriptor(source, String(index));
    if (!entry || !("value" in entry)) return null;
    members.push(entry.value);
  }
  return members;
}

function describeStage(stage: NightStageHandler, ordinal: number): NightStageMetadata {
  if (
    stage !== null &&
    (typeof stage === "object" || typeof stage === "function") &&
    !types.isProxy(stage)
  ) {
    const id = Object.getOwnPropertyDescriptor(stage, "id"),
      priority = Object.getOwnPropertyDescriptor(stage, "priority");
    if (
      id &&
      "value" in id &&
      typeof id.value === "string" &&
      priority &&
      "value" in priority &&
      typeof priority.value === "number"
    )
      return Object.freeze({ ordinal, kind: "data", id: id.value, priority: priority.value });
  }
  return Object.freeze({ ordinal, kind: "opaque" });
}

/** 只复制自有数据描述器；不调用额外 getter，自定义贡献协议明确保持不透明。 */
function supportedProfile(
  profile: unknown,
  role: unknown,
  pack: NightStageHandler[],
): SupportedNightDefinition["roles"][number] | null {
  if (!profile || typeof profile !== "object" || types.isProxy(profile) || typeof role !== "string")
    return null;
  const prototype = Object.getPrototypeOf(profile);
  if (prototype !== Object.prototype && prototype !== null) return null;
  const descriptors = Object.getOwnPropertyDescriptors(profile);
  for (const name of ["nightStages", "possibleNightAbilities", "possibleDeathAbilities"])
    if (descriptors[name] && !("value" in descriptors[name]!)) return null;
  const handlers = snapshotMembers(pack);
  const night = descriptors.possibleNightAbilities?.value ?? [];
  const death = descriptors.possibleDeathAbilities?.value ?? [];
  if (!Array.isArray(night) || !Array.isArray(death)) return null;
  const nightMembers = snapshotMembers(night),
    deathMembers = snapshotMembers(death);
  if (!handlers || !nightMembers || !deathMembers) return null;
  if (
    !nightMembers.every((kind) => typeof kind === "string") ||
    !deathMembers.every((kind) => kind === "gun")
  )
    return null;
  return Object.freeze({
    role,
    handlers: Object.freeze(handlers),
    night: Object.freeze(nightMembers as unknown as NightAbilityKind[]),
    death: Object.freeze(deathMembers as unknown as "gun"[]),
  });
}

/** 夜间阶段注册表。 */
export class NightStageRegistry {
  readonly roleCatalog: RoleCatalog;
  private readonly sourceByCollection = new WeakMap<
    object,
    Readonly<{
      sources: ReadonlyMap<NightStageHandler, readonly NightStageContributionSource[]>;
      definition: SupportedNightDefinition | null;
      builtIn: boolean;
    }>
  >();

  constructor(roleProfileRegistry: RoleCatalog = getDefaultRoleCatalog()) {
    this.roleCatalog = roleProfileRegistry;
  }

  /** 快照仅用于安全原生成员；虚方法覆盖和不透明惰性来源保留原时点。 */
  getPlan(config: ReadonlyBoardConfig, world?: World): NightStagePlan {
    const source = this.getStages(config, world),
      members = snapshotMembers(source);
    if (members === null)
      return Object.freeze({
        mode: "opaque",
        stages: source,
        entries: opaqueExecutionEntries(source),
        metadata: Object.freeze([]),
        definition: null,
        definitionScope: "injected",
      });
    const stages = Object.freeze(members);
    const metadata = Object.freeze(stages.map(describeStage));
    const collection = this.sourceByCollection.get(source);
    const sources = collection?.sources;
    const entries = Object.freeze(
      stages.map((handler) =>
        Object.freeze({
          handler,
          sources:
            sources?.get(handler) ?? (sources ? unknownReferenceSources : unknownOverrideSources),
        }),
      ),
    );
    return Object.freeze({
      mode: "snapshot",
      stages,
      entries,
      metadata,
      definition: metadata.every((row) => row.kind === "data")
        ? (collection?.definition ?? null)
        : null,
      definitionScope: collection?.builtIn ? "built-in" : "injected",
    });
  }

  getStages(config: ReadonlyBoardConfig, world?: World): NightStageHandler[] {
    const roleSet = new Set<Role>(config.roleSetups.map((item) => item.role));
    let hasRoleChecks = false;
    for (const role of [...roleSet])
      for (const kind of this.roleCatalog.runtime(role)?.possibleNightAbilities ?? []) {
        roleSet.add(abilityRole[kind]);
        if (kind === "role_check") hasRoleChecks = true;
      }
    for (const id of world?.entityIds() ?? [])
      for (const ability of allNightAbilities(world!.getComponent(id, COMPONENT.Role))) {
        roleSet.add(abilityRole[ability.kind]);
        if (ability.kind === "role_check") hasRoleChecks = true;
      }
    const collected: NightStageHandler[] = [];
    const sources = new Map<NightStageHandler, NightStageContributionSource[]>();
    // 在原 pack 读取及 spread 之后记录声明，不能为固定计划提前读取目录或玩家状态。
    const declarations: SupportedNightDefinition["roles"][number][] = [];
    let standardDefinition = this === defaultRegistry;
    if (world && demonHunterActorId(world) !== null) {
      const start = collected.length;
      collected.push(DEMON_HUNTER_NIGHT_STAGE);
      rememberAppendedSources(
        collected,
        start,
        Object.freeze({ kind: "compiler-reservation", reservation: "demon-native" }),
        sources,
      );
    }
    if (
      [...roleSet].some((role) =>
        this.roleCatalog.runtime(role)?.possibleDeathAbilities?.includes("gun"),
      ) ||
      world
        ?.getAliveEntityIds()
        .some((id) =>
          allDeathGuns(world.getComponent(id, COMPONENT.Role)).some(
            (gun) => gun.armedOnNight === null && !gun.disabled && !gun.deathExpired,
          ),
        )
    ) {
      const start = collected.length;
      collected.push(DEATH_ABILITY_ACTIVATION_STAGE);
      rememberAppendedSources(
        collected,
        start,
        Object.freeze({ kind: "compiler-reservation", reservation: "death-activation" }),
        sources,
      );
    }
    for (const role of roleSet.values()) {
      const profile = this.roleCatalog.runtime(role);
      const pack = profile?.nightStages ?? [];
      const start = collected.length;
      collected.push(...pack);
      if (standardDefinition) {
        const declaration = supportedProfile(profile, role, pack);
        if (declaration) declarations.push(declaration);
        else standardDefinition = false;
      }
      rememberAppendedSources(
        collected,
        start,
        Object.freeze(
          typeof role === "string"
            ? { kind: "role-profile", role }
            : { kind: "unknown", reason: "foreign-role" },
        ),
        sources,
      );
    }
    if (hasRoleChecks || collected.some((stage) => stage.id === "role_inspection")) {
      const start = collected.length;
      collected.push(ROLE_INSPECTION_STAGE, PSYCHIC_INSPECTION_STAGE, MIRROR_INSPECTION_STAGE);
      rememberAppendedSources(
        collected,
        start,
        Object.freeze({ kind: "compiler-reservation", reservation: "role-inspection" }),
        sources,
      );
    }
    if (
      world
        ?.entityIds()
        .some((id) =>
          allNightAbilities(world.getComponent(id, COMPONENT.Role)).some(
            (ability) => ability.activation === "lucky",
          ),
        )
    ) {
      const start = collected.length;
      collected.push(LUCKY_ABILITY_STAGE);
      rememberAppendedSources(
        collected,
        start,
        Object.freeze({ kind: "compiler-reservation", reservation: "lucky" }),
        sources,
      );
    }
    if (
      world
        ?.entityIds()
        .some((id) =>
          allNightAbilities(world.getComponent(id, COMPONENT.Role)).some(
            (ability) => ability.activation === "black_market",
          ),
        )
    ) {
      const start = collected.length;
      collected.push(BLACK_MARKET_RECIPIENT_STAGE);
      rememberAppendedSources(
        collected,
        start,
        Object.freeze({ kind: "compiler-reservation", reservation: "black-market" }),
        sources,
      );
    }
    const dedup = registerNightStages(collected);
    if (roleSet.has(Role.GhostBride)) {
      const changes = applyGhostBrideStageRegistration(
        dedup,
        WEDDING_CHAT_STAGE,
        WEDDING_KNIFE_STAGE,
      );
      for (const change of changes) {
        const prior = sources.get(change.original ?? change.handler) ?? [];
        sources.set(change.handler, [
          ...prior,
          Object.freeze({ kind: "ghost-replacement", operation: change.operation }),
        ]);
      }
    }
    const stages = Array.from(dedup.values()).sort((a, b) => {
      const diff = a.priority - b.priority;
      if (diff !== 0) {
        return diff;
      }
      return a.id.localeCompare(b.id);
    });
    const frozenSources = new Map<NightStageHandler, readonly NightStageContributionSource[]>();
    for (const [handler, contributions] of sources)
      frozenSources.set(handler, Object.freeze(contributions));
    this.sourceByCollection.set(
      stages,
      Object.freeze({
        sources: frozenSources,
        builtIn: this === defaultRegistry,
        definition: standardDefinition
          ? Object.freeze({
              roles: Object.freeze(declarations),
              // 预约仅补齐未来合法赠予/复制所需的定义，不增添当夜执行条目。
              reservations: Object.freeze([
                DEMON_HUNTER_NIGHT_STAGE,
                DEATH_ABILITY_ACTIVATION_STAGE,
                ROLE_INSPECTION_STAGE,
                PSYCHIC_INSPECTION_STAGE,
                MIRROR_INSPECTION_STAGE,
                LUCKY_ABILITY_STAGE,
                BLACK_MARKET_RECIPIENT_STAGE,
              ]),
            })
          : null,
      }),
    );
    return stages;
  }
}

let defaultRegistry: NightStageRegistry | null = null;

/** 获取默认夜间阶段注册表实例。 */
export function getDefaultNightStageRegistry(): NightStageRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new NightStageRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责猎魔人有限板子检查的 Node 输入边界。输入为未知候选值，
 * 输出为原支持布尔值；数据快照或判定抛错均转换为 false。
 * snapshotPlainData 在反射前拒绝 Proxy，保留深度 16、数组上限 256 与原错误码；
 * 之后的纯数据判定仍应用自身原有限边界，不安装状态、授予租约或支付资源。
 */
import { snapshotPlainData } from "../core/domain/plain_data";
import { isDemonHunterPreset as readPreset } from "./support";

export function isDemonHunterPreset(input: unknown): boolean {
  try {
    return readPreset(
      snapshotPlainData(input, new Set<object>(), 0, 256, "demon_hunter_data_invalid"),
    );
  } catch {
    return false;
  }
}

/**
 * 负责定序王子首轮票后的完整重收票政策：板子门控、原选择、严格选项替换、现场名单及复收票。
 * 输入为投票流水线的晚读引用和同一可变 options；输出原开票对象，未重启时同步返回 undefined。
 * 两个 yield 仅交回原 Promise，不增加未触发或末尾等待；选择／必需发言／窗口关闭仍由本族窗口拥有。
 * 严格闭包先复验原身份与生命，再调用原阶段回调；后续 PK 继续消费已替换选项，不复制授权或 actor。
 * 收票、目标生命、票权及开票仍由流水线执行；失败保留已付选择和已发表前缀，不退款、不自动补票。
 */
import type { EntityId, GameEvent, ReadonlyBoardConfig, VoteRecord } from "@ai-werewolf-arena/game-contract";
import { Role } from "@ai-werewolf-arena/game-contract";
import type { ActionProvider, ActionRequestConstructionPort } from "../core/domain/actions";
import type { World } from "../core/domain/world";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import type { VotingPipelineOptions } from "../game/engine/phase_pipeline/voting_pipeline";
import { canVoteExile } from "../game/mechanisms/common/participation";
import {
  assertOrderPrinceOriginalCurrent,
  runOrderPrinceChoice,
} from "../game/mechanisms/roles/order_prince/voting-ports";

/** 原开票结果引用；此知识不是下一票的许可，也不携带流水线内部原生命句柄。 */
export interface OrderPrinceRevoteBallots {
  tally: Record<number, number>;
  publicVotes: VoteRecord[];
}

/**
 * options 的 get/set 指向调用方同一个局部，原选择闭包和后续 PK 因而读取同一替换结果。
 * 两个具体回调在原调用点查流水线方法、以原 receiver 读实参；Votes 只透传原收票集合，不复制生命快照。
 * 原公开 options 类型仅 type import，不新增规则组合到引擎的运行加载边。
 */
export interface OrderPrinceRevoteRuntime<Votes> {
  readonly config: Pick<ReadonlyBoardConfig, "roleSetups">;
  readonly world: World;
  readonly requests: ActionRequestConstructionPort;
  readonly actionProvider: ActionProvider;
  readonly toolGateway: ToolGateway;
  readonly events: GameEvent[];
  options: VotingPipelineOptions;
  collectVotes(voters: EntityId[]): Promise<Votes>;
  recordVotes(votes: Votes): OrderPrinceRevoteBallots;
}

/** 恢复值只对应本次两个原等待点：第一次 boolean，激活后第二次为原 Votes，不驱动其它窗口。 */
export function* recollectOrderPrinceVotes<Votes>(
  runtime: OrderPrinceRevoteRuntime<Votes>,
): Generator<Promise<boolean> | Promise<Votes>, OrderPrinceRevoteBallots | undefined, boolean | Votes> {
  if (runtime.config.roleSetups.some((setup) => setup.role === Role.OrderPrince && setup.count > 0)) {
    const restarted = (yield runOrderPrinceChoice(
      runtime.world,
      runtime.requests,
      runtime.actionProvider,
      runtime.toolGateway,
      runtime.events,
      runtime.options.day,
      () => runtime.options.isCurrent?.() !== false,
    )) as boolean;
    if (restarted) {
      const previousCurrent = runtime.options.isCurrent;
      // 先捕获旧回调，再按原 spread 顺序读取字段并替换调用方选项；名单失败也不撤销严格模式。
      runtime.options = {
        ...runtime.options,
        strictRequired: true,
        orderPrinceRevote: true,
        isCurrent: () => {
          assertOrderPrinceOriginalCurrent(runtime.world);
          if (previousCurrent?.() === false) throw new Error("order_prince_revote_stale");
          return true;
        },
      };
      const freshVoters = runtime.world
        .getAliveEntityIds()
        .filter((id) => canVoteExile(runtime.world, id, runtime.options.day));
      const fresh = (yield runtime.collectVotes(freshVoters)) as Votes;
      if (runtime.options.isCurrent?.() === false) throw new Error("order_prince_revote_stale");
      // 原开票调用结束后才交回结果，流水线在原点解构；不早读结果字段或重新构造公开票据。
      return runtime.recordVotes(fresh);
    }
  }
  return undefined;
}

/**
 * 负责普通黎明的完整死亡提案与公开夜报名单选择。输入为同一夜伤害、原生命 Map、狐狸已付目标查询和可选白天自爆；
 * 输出为原序复制／合并的名单、死因、来源阶段及初始提交发布回调，不修改生命、库存或经理的完成标志。
 * 狐狸原因在实际 filter 点晚复验，原生命按引用、存活及版本匹配；普通板先公布，动物／双生板在原提交回调公布。
 * World、配置和夜字段仍在原表达式位置读取，发布入口先查经理 callee，再求名单；前项异常停止后项并保已发表前缀。
 * 经理保 nightSettled 首写、真实死亡 await、finish／abort finally、阶段当前性与唯一封盘；本组合没有第二份状态或通用死亡引擎。
 */
import { DeathCause, Phase, type EntityId, type DeathSources, type GameEvent } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../core/domain/components/names";
import { aliveLifeVersion } from "../core/domain/components/alive";
import type { World } from "../core/domain/world";
import type { NightFoxInspectionClaim } from "../core/domain/night_effects";
import type { DamageResolutionResult } from "../core/domain/systems/damage_resolution_system";
import type { DeathCommitReceipt, DeathOriginalLife } from "../game/engine/death-wave";

/** 只声明真实读取字段；伤害和已付 claim 原引用保留，不冻结回调或提前快照其当前性。 */
export interface OrdinaryNightDeathInput {
  readonly damage: DamageResolutionResult;
  readonly deathLives: ReadonlyMap<EntityId, DeathOriginalLife>;
  readonly foxInspections?: readonly NightFoxInspectionClaim[];
}

/** 名单 thunk 只为保原 publish callee→名单参数顺序；它不是许可或一次完成回执。 */
export interface OrdinaryNightDeathRuntime {
  readonly world: World;
  readonly night: OrdinaryNightDeathInput;
  readonly config: Pick<ReadonlyBoardConfig, "fragrantPairSeer" | "animalDream">;
  publishNightResolved(deaths: () => EntityId[]): GameEvent;
}

/** 自爆来源仍属于白天；同编号与夜死并存时保原首次名单位置和逐来源去重顺序。 */
export interface OrdinaryNightBlast {
  deaths: number[];
  sources: DeathSources;
}

/** 本步的局部可写副本；伤害与生命 Map 是原引用，空 filter 不额外取得 originalLives。 */
export interface OrdinaryNightDeathProposal {
  sourceDamage: DamageResolutionResult;
  originalLives: ReadonlyMap<EntityId, DeathOriginalLife> | undefined;
  retainedSources: DeathSources;
  nightDeaths: EntityId[];
  sources: DeathSources;
  deaths: EntityId[];
  deathPhases: Record<EntityId, Phase>;
}

/** 经理已在原点写 nightSettled；本步准备失败不标死、不退款，也不提前进入经理的 DR try/finally。 */
export function prepareOrdinaryNightDeaths(
  runtime: OrdinaryNightDeathRuntime,
  blast?: OrdinaryNightBlast,
): OrdinaryNightDeathProposal {
  let sourceDamage: DamageResolutionResult;
  let originalLives: ReadonlyMap<EntityId, DeathOriginalLife> | undefined;
  const retainedSources: DeathSources = Object.fromEntries(
    (sourceDamage = runtime.night.damage).deaths.map((id) => [
      id,
      (runtime.night.damage.deathSources[id] ?? []).filter(
        (source) =>
          source !== DeathCause.FoxInspection ||
          runtime.night.foxInspections?.some(
            (claim) => claim.target.id === id && claim.isTargetCurrent(),
          ),
      ),
    ]),
  );
  // 原每个候选位置才读 Map；先有保留原因，再查询 World 和原生命版本，不把当前席位的新生命替代旧提案。
  const nightDeaths = runtime.night.damage.deaths.filter((id) => {
    const scope = (originalLives = runtime.night.deathLives).get(id);
    return (
      scope &&
      retainedSources[id]?.length &&
      runtime.world.getComponent(id, COMPONENT.Alive) === scope.life &&
      scope.life.alive &&
      scope.version !== undefined &&
      aliveLifeVersion(scope.life) === scope.version
    );
  });
  if (!runtime.config.fragrantPairSeer && !runtime.config.animalDream)
    runtime.publishNightResolved(() => nightDeaths);
  const sources: DeathSources = Object.fromEntries(
    nightDeaths.map((id) => [id, [...(retainedSources[id] ?? [])]]),
  );
  const deaths = [...nightDeaths];
  const deathPhases: Record<EntityId, Phase> = {};
  if (blast !== undefined) {
    for (const id of blast.deaths) {
      if (!deaths.includes(id)) deaths.push(id);
      sources[id] = [...new Set([...(sources[id] ?? []), ...(blast.sources[id] ?? [])])];
      deathPhases[id] = Phase.Day;
    }
  }
  return { sourceDamage, originalLives, retainedSources, nightDeaths, sources, deaths, deathPhases };
}

/** 回调只在经理原 DR 参数展开点建立；动物／双生配置在该点选择，动物名单政策在真实发布时再次晚读。 */
export function ordinaryNightDeathPublication(
  runtime: OrdinaryNightDeathRuntime,
  nightDeaths: EntityId[],
  retainedSources: DeathSources,
): {
  onInitialWaveCommitted?: (
    actualIds: readonly number[],
    actualSources: DeathSources | undefined,
    receipt: DeathCommitReceipt,
  ) => GameEvent;
} {
  return runtime.config.fragrantPairSeer || runtime.config.animalDream
    ? {
        onInitialWaveCommitted: (
          actualIds: readonly number[],
          actualSources: DeathSources | undefined,
          receipt: DeathCommitReceipt,
        ) => {
          const event = runtime.publishNightResolved(() =>
            runtime.config.animalDream
              ? nightDeaths.filter(
                  (id) =>
                    actualIds.includes(id) &&
                    (retainedSources[id] ?? []).some((c) =>
                      (actualSources?.[id] ?? []).includes(c),
                    ),
                )
              : nightDeaths,
          );
          // 先写真实公开事件，再关联原完整 actualIds；回执失败不撤销事件，也不改变动物／双生 pending 筛选。
          receipt.recordPublication(event, actualIds);
          return event;
        },
      }
    : {};
}

/**
 * 负责普通狼刀收票之后的完整刀口路由组合。输入为原夜上下文、已接受的原生命引用、票序和弃票集合；
 * 输出为原多数／迷雾目标，并按原时点写刀口、投票者、映射后的印记和生命范围。
 * 炼金魔女的雾圈与原生命、魔术师映射和已付加成各由原本族所有者复验；此组合不持有库存或发放许可。
 * 狼阶段仍负责聊天、逐票复验、等待与末尾贵族事实发布；这里不增加等待、随机抽取、退款或失败清理。
 */
import { EntityId, Phase, StatusMark } from "../core/domain/model";
import { COMPONENT } from "../core/domain/components/names";
import { aliveLifeVersion } from "../core/domain/components/alive";
import { safeRecordLogicOp } from "../recording/session_recorder";
import { wolfTeamEvent } from "../game/mechanisms/roles/wolf_team";
import { bindWolfKnifeTargetQuery } from "../game/mechanisms/roles/wolf/ports";
import {
  isMistRavenBoard,
  mistKnifeTargets,
  originalMistTarget,
} from "../game/mechanisms/roles/mist_raven/knife-ports";
import type { NightStageContext, WolfKnifeTargetScope } from "../game/mechanisms/stages/night/contracts";

/** 已接受的票只携带原目标身体与生命版本，不是新的付款凭据或 JSON 快照。 */
export type AcceptedWolfKnifeTarget = Pick<WolfKnifeTargetScope, "targetId" | "life" | "version"> & {
  actorId: EntityId;
};

/** 只限制此组合实际使用的字段；调用方传原对象，各 getter 与方法 receiver 保留到原表达式点。 */
type WolfKnifeRoutingRuntime = Pick<
  NightStageContext,
  "world" | "state" | "roleCatalog" | "events" | "pickMajorityTarget" | "pickMistKnife" |
  "currentDay" | "nativeNightEffects" | "nativeNightTargets" | "ensureMarks"
>;

export function resolveOrdinaryWolfKnife(
  ctx: WolfKnifeRoutingRuntime,
  acceptedTargets: AcceptedWolfKnifeTarget[],
  voteOrder: EntityId[],
  explicitPasses: Set<EntityId>,
): EntityId | null {
  let wolfTarget = ctx.pickMajorityTarget(ctx.state.wolfVotes);
  let mistRandomScope: import("../core/domain/night_effects").NightLifeScope | null =
    null;
  // 先查询原板身份，再判断空刀；只有原雾圈可用且全部弃票时才使用一次原随机源。
  if (isMistRavenBoard(ctx.world) && wolfTarget === null) {
    const circle = mistKnifeTargets(ctx.world);
    if (circle !== null) {
      if (voteOrder.length === 0 || explicitPasses.size !== voteOrder.length)
        throw new Error("mist_knife_requires_explicit_passes");
      if (!ctx.pickMistKnife) throw new Error("mist_knife_rng_missing");
      wolfTarget = ctx.pickMistKnife(circle);
      mistRandomScope =
        wolfTarget === null ? null : originalMistTarget(ctx.world, ctx.currentDay(), wolfTarget);
      if (wolfTarget !== null && !mistRandomScope) throw new Error("mist_knife_target_stale");
      ctx.events.push(
        wolfTeamEvent(ctx.world, ctx.roleCatalog, {
          timestamp: Date.now(),
          type: "mist_knife_drawn",
          payload: { day: ctx.currentDay(), candidates: [...circle], targetId: wolfTarget },
        }),
      );
    }
  }
  // 抽刀事件先发布；随后刀口写入、加成命令、投票者与诊断依次执行，失败不回滚已写前缀。
  ctx.state.wolfTarget = wolfTarget;
  ctx.nativeNightEffects.recordKnifeModifierTarget(() => wolfTarget);
  ctx.state.wolfTargetVoters = acceptedTargets
    .filter((target) => target.targetId === wolfTarget)
    .map((target) => target.actorId);
  safeRecordLogicOp({
    scope: "phase_pipeline",
    op: "wolf_kill_vote_resolved",
    phase: Phase.Night,
    status: "ok",
    output: { tally: ctx.state.wolfVotes, wolf_target: wolfTarget },
  });
  if (wolfTarget !== null) {
    const target =
      (mistRandomScope
        ? { targetId: wolfTarget, life: mistRandomScope.life, version: mistRandomScope.version }
        : undefined) ??
      acceptedTargets.find(
        (item) =>
          item.targetId === wolfTarget &&
          ctx.world.getComponent(item.targetId, COMPONENT.Alive) === item.life &&
          item.life.alive &&
          aliveLifeVersion(item.life) === item.version &&
          bindWolfKnifeTargetQuery(ctx.world).allows(item.targetId),
      );
    if (target) {
      // 映射在原目标复验后读取；先核映射当前性，再加印记，最后保存原生命／映射生命的运行引用。
      const mapping = ctx.nativeNightTargets.mappedTarget(
        () => ctx.currentDay(),
        () => wolfTarget,
      );
      if (mapping && !mapping.isCurrent()) throw new Error("magician_knife_target_stale");
      const effectiveId = mapping?.effectiveId ?? wolfTarget;
      const marks = ctx.ensureMarks(effectiveId);
      marks.add(StatusMark.WolfKillMark);
      ctx.state.wolfTargetScope = mapping
        ? {
            ...target,
            targetId: effectiveId,
            life: mapping.scope.life,
            version: mapping.scope.version,
            marks,
          }
        : { ...target, marks };
    }
  }
  return wolfTarget;
}

/**
 * 负责普通用药工具的完整准入组合：能力／库存、自救、学者／导师削弱、目标映射与受赠目标限制。
 * 输入为原校验上下文和已清洗工具，输出为原首个结构化拒绝或通过；不执行用药或付款。
 * 读取同一实例和当前 settled frame，不因角色标签限定受赠／复制／转移能力，不建立库存快照。
 * 参数、短路及 getter 失败顺序保持；预检通过不替代实际提交时的原体、生命和来源复验。
 */
import { scholarMentorBlocks } from "../game/mechanisms/roles/scholar_mentor/ports";
import { isMagicianBoard, resolveMagicianNightTarget } from "../game/mechanisms/roles/magician/ports";
import { nativePotionsCanCombine } from "../game/mechanisms/roles/witch/ports";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { PotionType, Phase, WitchSelfHealRule, StatusMark } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../core/domain/components/names";
import { type ToolRuleMap, isAliveTarget } from "../game/mechanisms/validation/contracts";
import { activeNightAbility } from "../game/mechanisms/roles/abilities";
import { luckyTargetAllowed } from "../game/mechanisms/roles/night_action_history";

/** 保留原可写规则表；Catalog 仍晚读当前 callback，不把准入冻结为登记时的授权快照。 */
export const WITCH_VALIDATION_RULES: ToolRuleMap = {
  use_potion: ({ world, actorId, role, toolCall, day, abilityId, phase }) => {
    // 原库存选择也适用于受赠／复制／转移药剂；不新增 Witch 角色标签门槛。
    const ability = activeNightAbility(role, "potion", day ?? 1, abilityId);
    const witchState = ability?.state;
    if (!witchState) {
      return { code: RuleError.WitchOnly };
    }
    if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
    if (toolCall.name !== "use_potion") {
      return { code: RuleError.ToolMismatch };
    }
    if (
      ability?.activation === "lucky" &&
      toolCall.args.potion_type === PotionType.None &&
      toolCall.args.target_id !== actorId
    )
      return { code: RuleError.PoisonTarget };
    if (
      ability?.activation === "black_market" &&
      toolCall.args.potion_type === PotionType.None &&
      !isAliveTarget(world, toolCall.args.target_id)
    )
      return { code: RuleError.PoisonTarget };
    if (toolCall.args.potion_type === PotionType.Heal) {
      const canSelfHeal =
        day === undefined
          ? witchState.canSelfHeal
          : witchState.selfHealRule === WitchSelfHealRule.Always ||
            (witchState.selfHealRule === WitchSelfHealRule.FirstNightOnly && day === 1);
      if (!canSelfHeal && toolCall.args.target_id === actorId) {
        return { code: RuleError.SelfHeal };
      }
      if (witchState.heal <= 0 || witchState.healUsedThisNight) {
        return { code: RuleError.HealUnavailable };
      }
      if (witchState.poisonUsedThisNight && !nativePotionsCanCombine(ability!)) {
        return { code: RuleError.TwoPotions };
      }
      const requestedId = toolCall.args.target_id;
      if (!isAliveTarget(world, requestedId)) return { code: RuleError.HealTarget };
      // 自救先检查请求编号；这里才映射有效目标，缺失 day 的原默认是 0 而非库存查询的 1。
      const mapping = isMagicianBoard(world)
        ? resolveMagicianNightTarget(world, day ?? 0, requestedId)
        : null;
      if (mapping && !mapping.isCurrent()) return { code: RuleError.HealTarget };
      const targetId = mapping?.effectiveId ?? requestedId;
      if (
        !isAliveTarget(world, targetId) ||
        !world.getComponent(targetId, COMPONENT.Role) ||
        !world.getComponent(targetId, COMPONENT.StatusMarks)?.has(StatusMark.WolfKillMark)
      ) {
        return { code: RuleError.HealTarget };
      }
      return null;
    }
    if (toolCall.args.potion_type === PotionType.Poison) {
      // 削弱查询先于瓶数／目标；原 frame 错误原样传播，不转成库存不足或补读目标。
      if (scholarMentorBlocks(world, day ?? 1, actorId, "poison"))
        return { code: RuleError.ModifierUnavailable };
      if (witchState.poison <= 0 || witchState.poisonUsedThisNight) {
        return { code: RuleError.PoisonUnavailable };
      }
      if (witchState.healUsedThisNight && !nativePotionsCanCombine(ability!)) {
        return { code: RuleError.TwoPotions };
      }
      if (!isAliveTarget(world, toolCall.args.target_id)) {
        return { code: RuleError.PoisonTarget };
      }
      if (
        !luckyTargetAllowed(world, actorId, ability!, day ?? 1, "poison", toolCall.args.target_id)
      )
        return { code: RuleError.LuckyTargetRepeat };
      return null;
    }
    return null;
  },
};

/**
 * 负责赤月延迟到期的完整同步查询、到期前候选和死亡后提交发布。输入为原 World／registry／配置的晚读视图及原日期。
 * 输出仅交出需要追加死亡的原玩家编号，最后返回原胜负候选引用；无候选时才请求死亡，不创建 Promise 或标死。
 * 原生库存和审计仍归猎魔权威。经理持原追加死亡等待、可读性／当前性复验、夜报、封盘与 finally。
 * 只有经理成功完成死亡及复验后才恢复提交；恢复时先核已死，再提交到期、发布事件、记录操作，后项失败保原前缀不退款。
 */
import type { ReadonlyBoardConfig, VictoryCheckpoint, WinDecision } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../core/domain/components/names";
import { DeathCause, Phase, type EntityId, type GameEvent } from "../core/domain/model";
import type { World } from "../core/domain/world";
import type { ConditionRegistry } from "../core/domain/registries/condition_registry";
import { demonRedMoonExpiry, commitDemonRedMoonTransition } from "../game/mechanisms/roles/demon_hunter/ports";
import { TERMINAL_VICTORY_POLICY } from "./terminal-victory-policy";
import { safeRecordLogicOp } from "../recording/session_recorder";

/** 视图只声明晚读成员，保持原引用；不是冻结数据或额外的授权屏障。 */
export interface RedMoonExpiryRuntime {
  readonly world: World;
  readonly events: GameEvent[];
  readonly registry: ConditionRegistry;
  readonly config: ReadonlyBoardConfig;
  readonly checkpoint: VictoryCheckpoint;
}

/**
 * 只在确需到期死亡时 yield 一次原编号。DR 抛错或复验失效时，经理不恢复本序列；
 * 没有原生板子／到期者或已赢候选时直接同步完成，不增加任何 await 或结算回执。
 */
export function* settleRedMoonExpiry(
  runtime: RedMoonExpiryRuntime,
  ownsDemon: boolean,
  nightDay: number,
): Generator<EntityId, WinDecision | null, void> {
  const expiryActor = ownsDemon ? demonRedMoonExpiry(runtime.world, nightDay) : null;
  // 延期的最后一狼仍参与本次普通夜的胜负判断。
  const beforeExpiryResult =
    expiryActor === null
      ? null
      : runtime.registry.evaluateMany(
          runtime.world,
          TERMINAL_VICTORY_POLICY.conditions({ world: () => runtime.world, config: () => runtime.config }),
          runtime.checkpoint,
        );
  if (expiryActor !== null && !beforeExpiryResult) {
    yield expiryActor;
    if (runtime.world.getComponent(expiryActor, COMPONENT.Alive)?.alive !== false)
      throw new Error("red_moon_expiry_death_unsettled");
    if (!commitDemonRedMoonTransition(runtime.world, expiryActor, "expire", nightDay))
      throw new Error("red_moon_expiry_commit_revoked");
    const fact = { actorId: expiryActor, day: nightDay };
    runtime.events.push({
      timestamp: Date.now(),
      type: "red_moon_delay_expired",
      payload: fact,
    });
    safeRecordLogicOp({
      scope: "resolution",
      op: "red_moon_expiry_settled",
      phase: Phase.Night,
      status: "ok",
      output: { ...fact, cause: DeathCause.RedMoonExpiry },
    });
  }
  return beforeExpiryResult;
}

/**
 * 负责：拥有一次真实执行的规则计划及唯一 BoardParameters 引用。
 * 输入：已绑定参数、原时点采集的阶段贡献和延迟读取的夜间运行端口；
 * 输出：实际引擎使用的原 handler、原生策略、生命周期单位及脱离运行态的归档参数。
 * 默认自有数据贡献在首次晚收集时固定成员与顺序，后续变化明确拒绝隐式 revision。
 * 注入或不透明来源保留原 collector 和惰性拉取；不缓存 execute 函数、角色资格、
 * 玩家、目标、库存或 World，不新增 World 全局表或归档字段。
 */
import { assertCycleAdmission, assertPhaseJumpAdmission } from "./cycle-admission";
import { refreshWolfKnifeInheritanceAtCheckpoint } from "./wolf-knife-inheritance-plan";
import type { BoardParameters } from "./board-parameters";
import type { NightStageRegistry } from "./night-stage-plan";
import type { NightStagePlan, SupportedNightDefinition } from "./night-stage-plan-contracts";
import type { World } from "../core/domain/world";
import { types } from "node:util";
import { bindNativeNightFailurePolicy } from "./native-night-failure-policy";
import { bindNativeNightTargetPolicy } from "./native-night-target-policy";
import { bindNativeNightEffects } from "./native-night-effects";
import {
  NightManagerLifecycle,
  prepareNightPipelineLifecycle,
  type NightManagerLifecycleRuntime,
  type NightPipelineLifecycleRuntime,
  type NightLifecycleHandoff,
} from "./night-lifecycle-plan";

const constructionToken = Symbol("rule-plan-construction");
const checkpoints = Object.freeze({
  nightSettled: "night_settled",
  dayInterrupted: "day_interrupted",
  exileSettled: "exile_settled",
  maxDays: "max_days_reached",
} as const);

// 比较贡献序列和原 handler 身份，不读取或缓存 execute；角色实例仍在现场查询。
function sameDefinition(left: SupportedNightDefinition, right: SupportedNightDefinition): boolean {
  if (left.roles.length !== right.roles.length) return false;
  return left.roles.every((row, index) => {
    const other = right.roles[index]!;
    return row.role === other.role &&
      row.handlers.length === other.handlers.length &&
      row.handlers.every((handler, ordinal) => handler === other.handlers[ordinal]) &&
      row.night.length === other.night.length &&
      row.night.every((kind, ordinal) => kind === other.night[ordinal]) &&
      row.death.length === other.death.length &&
      row.death.every((kind, ordinal) => kind === other.death[ordinal]);
  });
}

/** 组合直接复用已存在的具体策略及单位，不另建执行框架。 */
export class RulePlan {
  readonly parameters: BoardParameters;
  readonly nativeNightFailure = bindNativeNightFailurePolicy;
  readonly nativeNightTargets = bindNativeNightTargetPolicy;
  readonly nativeNightEffects = bindNativeNightEffects;
  readonly checkpoints = checkpoints;
  /** 固定同步政策函数；不固定现场状态，每次准入沿调用方 getter 读取原查询点。 */
  readonly cycleAdmission = assertCycleAdmission;
  readonly phaseJumpAdmission = assertPhaseJumpAdmission;
  /** 同步继承贡献不持执行态，经理只在原初始检查点调用。 */
  readonly wolfKnifeInheritance = refreshWolfKnifeInheritanceAtCheckpoint;
  // 只在首次默认晚收集后固定有限贡献；actor、实例和资源始终由现场查询决定。
  #definition: SupportedNightDefinition | null = null;
  // 潜在阶段描述可保留未激活预约，实际 entries 仍使用原 collector 当夜选择。
  #metadata: NightStagePlan["metadata"] | null = null;
  // 记录已固定的标准来源身份；其转为 Proxy/访问器不能绕过 revision 检查。
  #standardRegistry: NightStageRegistry | null = null;

  private constructor(token: typeof constructionToken, parameters: BoardParameters) {
    if (token !== constructionToken) throw new Error("rule_plan_constructor_forbidden");
    this.parameters = parameters;
    Object.freeze(this);
  }

  /** 仅绑定同一参数 owner；不查询 World／registry，默认自有贡献在第一次 nightPlan 的原晚时点固定。 */
  static compile(parameters: BoardParameters): RulePlan {
    return new RulePlan(constructionToken, parameters);
  }

  /** 私有字段品牌先拒绝伪造别名；不执行调用方 getter 或 Proxy trap。 */
  static isOwned(input: unknown): input is RulePlan {
    return input !== null && typeof input === "object" && #definition in input;
  }

  createNightManagerLifecycle(runtime: NightManagerLifecycleRuntime): NightManagerLifecycle {
    return new NightManagerLifecycle(runtime);
  }

  prepareNightPipelineLifecycle(
    runtime: NightPipelineLifecycleRuntime,
    config: Parameters<typeof prepareNightPipelineLifecycle>[1],
    day: number,
    handoff?: () => NightLifecycleHandoff | undefined,
  ) {
    return prepareNightPipelineLifecycle(runtime, config, day, handoff, this.parameters);
  }

  /** 在原时点采集；不透明 iterator 不预先耗尽，下一项仍在前一 handler 提交后拉取。 */
  nightPlan(registry: NightStageRegistry, world: () => World): NightStagePlan {
    // 原调用先读取 getPlan 方法，再求值 World 参数；不能在跨 owner 时倒置 getter 前缀。
    const plan = registry.getPlan(this.parameters.board, world());
    if (plan.mode !== "snapshot") {
      if (registry === this.#standardRegistry)
        throw new Error("rule_plan_revision_not_supported");
      return plan;
    }
    if (plan.definition === null) {
      if (plan.definitionScope === "built-in" && this.#definition !== null)
        throw new Error("rule_plan_revision_not_supported");
      return plan;
    }
    if (this.#definition === null) {
      this.#definition = plan.definition;
      this.#standardRegistry = registry;
      const reserved = plan.definition.reservations.map((handler, ordinal) => {
        if (types.isProxy(handler)) return null;
        const id = Object.getOwnPropertyDescriptor(handler, "id"),
          priority = Object.getOwnPropertyDescriptor(handler, "priority");
        if (!id || !("value" in id) || typeof id.value !== "string" ||
          !priority || !("value" in priority) || typeof priority.value !== "number") return null;
        return Object.freeze({ kind: "data" as const, id: id.value, priority: priority.value, ordinal });
      });
      this.#metadata = Object.freeze([...plan.metadata, ...reserved.filter((entry) => entry !== null)]);
      return plan;
    }
    if (!sameDefinition(this.#definition, plan.definition))
      throw new Error("rule_plan_revision_not_supported");
    // 原体退役后，现场选择可以移除可选预约；固定定义只校验既有 ID/priority，
    // 不把潜在预约插入执行列表，避免多出原事件、record 或 RNG 操作。
    for (const item of plan.metadata) {
      if (item.kind !== "data") throw new Error("rule_plan_revision_not_supported");
      const previous = this.#metadata!.find((entry) => entry.kind === "data" && entry.id === item.id);
      if (!previous || previous.kind !== "data" || previous.priority !== item.priority)
        throw new Error("rule_plan_revision_not_supported");
    }
    return plan;
  }

  /** 归档只编码同一参数 owner 的脱离克隆，计划对象和 callback 不写入归档。 */
  encodeParameters() {
    return this.parameters.encode();
  }
}
Object.freeze(RulePlan.prototype);
Object.freeze(RulePlan);

/**
 * 负责白天自爆的有限规则组合：婚礼禁用、红月资格、普通自爆与白狼王库存共同约束选择。
 * 输入为原 World、角色工具表、请求构造端口、Provider、网关及窗口回调；输出为首个未被拒绝的选择或 null。
 * 并发请求保原 Promise.all 顺序；等待后按原体／生命版本／库存与目标复验，再按玩家编号尝试提交。
 * 捕获的存活组件和资源引用仅服务本次窗口；阶段 current、库存付款、死亡与最终判胜各归原 owner。安装失败的退休只拒演员，目标和纯数据仍保原查询。
 * commit 返回 false 只跳过该选择；读取、Provider 或提交失败沿原异常传播，不补提交或回滚已写前缀。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RED_MOON_ROLE } from "../game/mechanisms/roles/red_moon_apostle/ports";
import { demonRedMoonCanBlast } from "../game/mechanisms/roles/demon_hunter/ports";
import { canRoleSelfDestruct } from "../game/mechanisms/roles/self_destruct_capability";
import { getDefaultRoleCatalog } from "../game/mechanisms/roles/role-catalog-assembly";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
} from "../game/mechanisms/roles/ghost_bride/ports";
import { AliveComponent, aliveLifeVersion } from "../core/domain/components/alive";
import { COMPONENT } from "../core/domain/components/names";
import { RoleComponent } from "../core/domain/components/role";
import { isRoleExecutionRetired } from "../core/domain/role-execution-authority";
import {
  ActionProvider,
  ActionWindow,
  Phase,
  type SelfDestructSelection,
} from "../core/domain/model";
import { RoleRegistry } from "../core/domain/registries/role_registry";
import { World } from "../core/domain/world";
import { ToolGateway } from "../game/gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../core/domain/actions";
import { getWhiteWolfKingState } from "../game/mechanisms/roles/white_wolf_king/ports";

/** 并发收集选项，按编号升序复验并尝试提交；回调明确返回 false 时跳过该选项，返回首个未被拒绝的选择。 */
export class SelfDestructWindow {
  constructor(
    private readonly world: World,
    private readonly roleRegistry: RoleRegistry,
    private readonly toolGateway: ToolGateway,
  ) {}

  async execute(
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: ActionWindow,
    phase: Phase,
    isCurrent: () => boolean = () => true,
    commit?: (choice: SelfDestructSelection) => Promise<void | boolean>,
  ): Promise<SelfDestructSelection | null> {
    if (!isCurrent()) return null;
    // 先捕获所有原存活身体和生命版本；后续目标死后复活或换组件不能复用旧选择。
    const targets = new Map(
      this.world.getAliveEntityIds().map((id) => {
        const alive = this.world.getComponent(id, COMPONENT.Alive)!;
        return [id, { alive, version: aliveLifeVersion(alive) }] as const;
      }),
    );
    // 各玩家请求并发，结果排列仍由原存活名单决定；不以最早响应决定谁自爆。
    const picks = await Promise.all(
      this.world.getAliveEntityIds().map(async (actorId) => {
        const role = this.world.getComponent(actorId, COMPONENT.Role);
        if (!role) return null;
        if (
          weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, role))
        )
          return null;
        const tools = this.roleRegistry.getAllowedTools(role.role);
        const tool = tools.includes("self_destruct_with_target")
          ? "self_destruct_with_target"
          : tools.includes("self_destruct")
            ? "self_destruct"
            : null;
        if (!tool) return null;
        if (
          tool === "self_destruct" &&
          (String(role.role) === RED_MOON_ROLE
            ? !demonRedMoonCanBlast(this.world, actorId)
            : !canRoleSelfDestruct(role, getDefaultRoleCatalog(), () => this.world.getComponent(actorId, COMPONENT.Camp)))
        )
          return null;
        // 白狼王复验同一库存对象；这里不消费，实际消耗仍归提交函数。
        const resource =
          tool === "self_destruct_with_target" ? getWhiteWolfKingState(role) : undefined;
        if (tool === "self_destruct_with_target" && resource?.canDetonate !== true) return null;
        // 原特殊资格和库存读取先行，保其首错误；已退休演员不再建立新请求。
        if (isRoleExecutionRetired(role)) return null;
        const life = targets.get(actorId)!;
        const request = requests.create({
          phase,
          actionWindow: window,
          actorId,
          allowedTools: [tool],
          stage: window,
          requiresAction: false,
          summary: {
            key:
              phase === Phase.Voting
                ? "request.summary.self_destruct_pre_vote"
                : "request.summary.self_destruct",
          },
          context: {},
        });
        const action = await provider.getAction(request);
        if (
          action?.name !== tool ||
          (action.name !== "self_destruct" && action.name !== "self_destruct_with_target")
        )
          return null;
        const choice: SelfDestructSelection =
          action.name === "self_destruct"
            ? { kind: "ordinary", actorId, targetId: null }
            : { kind: "white_wolf_king", actorId, targetId: action.args.target_id };
        return { choice, action, role, resource, life };
      }),
    );
    if (!isCurrent()) return null;
    // 提交前重复检查原玩家、目标、生命版本及特殊规则；字段恢复不抹去生命版本变化。
    const stillCurrent = (pick: NonNullable<(typeof picks)[number]>) => {
      const { actorId, targetId } = pick.choice;
      if (
        !isCurrent() ||
        (weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, pick.role))) ||
        this.world.getComponent(actorId, COMPONENT.Role) !== pick.role ||
        this.world.getComponent(actorId, COMPONENT.Alive) !== pick.life.alive ||
        !pick.life.alive.alive ||
        pick.life.version === undefined ||
        aliveLifeVersion(pick.life.alive) !== pick.life.version
      )
        return false;
      if (String(pick.role.role) === RED_MOON_ROLE && !demonRedMoonCanBlast(this.world, actorId))
        return false;
      if (
        pick.choice.kind === "white_wolf_king" &&
        (getWhiteWolfKingState(pick.role) !== pick.resource || pick.resource?.canDetonate !== true)
      )
        return false;
      if (targetId !== null) {
        const target = targets.get(targetId);
        if (
          !target ||
          this.world.getComponent(targetId, COMPONENT.Alive) !== target.alive ||
          !target.alive.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.alive) !== target.version
        )
          return false;
      }
      // 等待后先完成原特殊权威、库存与目标复验；字段恢复不复活这个失败演员。
      return !isRoleExecutionRetired(pick.role);
    };
    // 网关预检前后均复验；预检成功只产生候选，不意味着库存付款或死亡已生效。
    const valid = picks.filter(
      (pick): pick is NonNullable<typeof pick> =>
        pick !== null &&
        stillCurrent(pick) &&
        this.toolGateway.validateAndSanitize(this.world, pick.choice.actorId, pick.action, {
          phase,
          actionWindow: window,
          allowSelfDestruct: true,
        }).ok &&
        stillCurrent(pick),
    );
    // 按玩家编号串行调用可选提交；false 跳过，异常停止并保留此前提交的前缀。
    for (const pick of valid.sort((a, b) => a.choice.actorId - b.choice.actorId)) {
      if (!isCurrent()) return null;
      if (!stillCurrent(pick)) continue;
      if ((await commit?.(pick.choice)) === false) continue;
      return pick.choice;
    }
    return null;
  }
}

/** 显式空窗口列表禁用全部机会；只有未配置列表才回退到原投票前默认窗口。 */
export function isSelfDestructWindowEnabled(
  config: ReadonlyBoardConfig,
  window: ActionWindow,
): boolean {
  return config.selfDestruct?.enabledWindows === undefined
    ? window === ActionWindow.OnPreVote
    : config.selfDestruct.enabledWindows.includes(window);
}

/**
 * 负责特殊夜初始死亡波的完整同步准备：可读性、故障／必需证据、原来源封存、保护、夜仆收尾与事实发布。
 * 输入为经理原夜结果、固定夜日、两项原归属和晚读取视图；输出同一待提交名单／来源、原生命表及链前活人快照。
 * World 仍是原运行对象，字段只读不构成写权限隔离；具体付款、原体、来源当前性和封存权仍归原机制所有者。
 * 故障、资源或事实写入后的失败保合法前缀，不退款、不重抓来源或吞必需记录。空名单不提前读取 deathLives。
 * 本组合不创建 Promise、标死、换阶段、判胜或关闭外层夜；经理保原 try/finally、初始死亡波 DR 等待与后续到期裁决。
 */
import { DeathCause, Phase, StatusMark, type EntityId, type DeathSources, type ReadonlyBoardConfig, type GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../core/domain/world";
import { COMPONENT } from "../core/domain/components/names";
import { aliveLifeVersion, type AliveComponent } from "../core/domain/components/alive";
import { statusMarkSnapshot } from "../core/domain/components/status_marks";
import type { DamageResolutionResult } from "../core/domain/systems/damage_resolution_system";
import type { DeathOriginalLife } from "../game/engine/death-wave";
import type { NightPipelineResult } from "../game/engine/phase_pipeline/night_pipeline";
import type { NightFaultPlan } from "../game/engine/fault_plan";
import type { NightManagerLifecycle } from "./night-lifecycle-plan";
import {
  appendDemonNightDamageSources,
  publishDemonNightDamageSources,
  committedDemonFaultBoundary,
} from "../game/mechanisms/roles/demon_hunter/ports";
import { freezeDeliveredDemonNightSources } from "../game/mechanisms/roles/demon_hunter/native_potion_controller";
import { appendNobleContractClosure, publishNobleNightDamage } from "../game/mechanisms/roles/noble_secret_body/ports";
import { weddingKnifeCurrent } from "../game/mechanisms/roles/ghost_bride/ports";
import { getSessionRecorder } from "../recording/recording_context";

/** getter 只闭包经理原对象；在每个原表达式才读字段。assertReadable 仍晚查经理原 private 方法与 receiver。 */
export interface SpecialNightDamageRuntime {
  readonly world: World;
  readonly config: ReadonlyBoardConfig;
  readonly events: GameEvent[];
  readonly nightFaultPlan: Pick<NightFaultPlan, "applyBeforeNightSourceFreeze"> | undefined;
  assertReadable(): void;
}

/** 非序列化运行结果；字段及数组／Map 不克隆或冻结，sourceDamage 保原毒来源证据关联。 */
export interface PreparedSpecialNightDamage {
  deaths: EntityId[];
  sources: DeathSources;
  originalLives: ReadonlyMap<EntityId, DeathOriginalLife> | undefined;
  sourceDamage: DamageResolutionResult;
  livingBeforeChain: Map<EntityId, { life: AliveComponent; version: number | undefined }>;
}

/** 四项是否进入特殊夜仍在经理 try 之前判定；这里只组合已进入分支的原同步工作，不增加等待点。 */
export function prepareSpecialNightDamage(
  runtime: SpecialNightDamageRuntime,
  night: Extract<NightPipelineResult, { interrupted: false }>,
  nightDay: number,
  ownsWedding: boolean,
  ownsDemon: boolean,
  lifecycle: Pick<NightManagerLifecycle, "expireNobleAtNightEnd" | "closeNobleNormally">,
): PreparedSpecialNightDamage {
  runtime.assertReadable();

  // 原故障驱动可先换生命并消费计划；必需记录失败保此前前缀，不能跳过回调继续封存。
  const faults =
    runtime.nightFaultPlan?.applyBeforeNightSourceFreeze(
      nightDay,
      committedDemonFaultBoundary(runtime.world),
      (fault) => {
        // 开启录制时这是必需写入；写入失败不能生成缺少证据却标记成功的 Tape。
        getSessionRecorder()?.recordRequiredLogicOp({
          scope: "resolution",
          op: "fault_applied",
          phase: Phase.Night,
          status: "ok",
          input: { version: "awa_fault_plan_v1", step: fault.step },
          output: {
            originalVersion: fault.originalVersion,
            replacementVersion: fault.replacementVersion,
          },
        });
      },
    ) ?? [];
  const demon = ownsDemon
    ? freezeDeliveredDemonNightSources(runtime.world, night.demonSources!, faults[0] ?? null)
    : null;
  let sourceDamage: DamageResolutionResult;
  let originalLives: ReadonlyMap<EntityId, DeathOriginalLife> | undefined;
  const proposedSources: DeathSources = Object.fromEntries(
    (sourceDamage = night.damage).deaths.map((id) => [
      id,
      [...(night.damage.deathSources[id] ?? [])],
    ]),
  );
  const guardOverrides: Array<{ targetId: number; guard: boolean }> = [];
  if (demon) {
    const manager = runtime;
    appendDemonNightDamageSources({
      get knifeProtection() { return night.demonKnifeProtection; },
      healMarkPresent(target) {
        return statusMarkSnapshot(
          manager.world.getComponent(target(), COMPONENT.StatusMarks),
          StatusMark.HealMark,
        )?.present === true;
      },
      wolfSourceCurrent(target) { return night.demonWolfSourceCurrent?.(target()); },
    }, demon, proposedSources, guardOverrides);
  }
  if (runtime.config.nobleSecretBody) {
    if (demon?.hunt.servantCleared)
      runtime.events.push({
        timestamp: Date.now(),
        type: "noble_contract_closed",
        payload: demon.hunt.servantCleared,
        audience: Object.freeze([]),
      });
    const expiry = lifecycle.expireNobleAtNightEnd(night, () => nightDay);
    if (expiry) {
      appendNobleContractClosure(runtime.world, nightDay, expiry, runtime.events, Phase.Night);
      (proposedSources[expiry.targetId] ??= []).push(DeathCause.ServantExpiry);
    }
    lifecycle.closeNobleNormally(night, nightDay);
  }
  // 每目标才读取原 deathLives；空来源不读取它，originalLives 保留 undefined，不预抓新的生命。
  const deaths = Object.keys(proposedSources)
    .map(Number)
    .filter((id) => {
      const scope = (originalLives = night.deathLives).get(id);
      return (
        scope &&
        runtime.world.getComponent(id, COMPONENT.Alive) === scope.life &&
        scope.life.alive &&
        aliveLifeVersion(scope.life) === scope.version
      );
    });
  const sources: DeathSources = Object.fromEntries(
    deaths.map((id) => [
      id,
      proposedSources[id]!.filter(
        (cause) =>
          (cause !== DeathCause.WolfKill ||
            (ownsWedding
              ? weddingKnifeCurrent(runtime.world, nightDay, id)
              : ownsDemon
                ? night.demonWolfSourceCurrent?.(id) === true
                : true)) &&
          (cause !== DeathCause.EvilKnightReflection ||
            night.retaliationAttacks?.some(
              (attack) => attack.target.id === id && attack.isCurrent(),
            ) === true) &&
          ((cause !== DeathCause.PureWhiteInspection &&
            cause !== DeathCause.WolfWitchInspection) ||
            night.inspectionAttacks?.some(
              (attack) =>
                attack.target.id === id && attack.cause === cause && attack.isCurrent(),
            ) === true),
      ),
    ]),
  );
  for (let i = deaths.length - 1; i >= 0; i--)
    if (!sources[deaths[i]!]!.length) deaths.splice(i, 1);
  if (runtime.config.nobleSecretBody) {
    const manager = runtime;
    publishNobleNightDamage({
      get world() { return manager.world; },
      get events() { return manager.events; },
    }, nightDay, sources, deaths);
  }
  if (demon) {
    const manager = runtime;
    publishDemonNightDamageSources({
      get events() { return manager.events; },
    }, demon, nightDay, guardOverrides, deaths, sources);
  }
  // 先完成原保护、夜仆和事实发布，再捕获活人生命；这里只准备，真实标死与追加波仍归经理的 DR。
  const livingBeforeChain = new Map(
    runtime.world.getAliveEntityIds().map((id) => {
      const life = runtime.world.getComponent(id, COMPONENT.Alive)!;
      return [id, { life, version: aliveLifeVersion(life) }] as const;
    }),
  );
  return { deaths, sources, originalLives, sourceDamage: sourceDamage!, livingBeforeChain };
}

/**
 * 负责终局候选的配置选择、咒狐结果改写接线与婚约封盘前检查。
 * 输入为原配置／世界的晚读查询及已判候选；输出为原条件数组、原或改写的候选及经原领域校验的数据。
 * 婚约只接受三阵营规则；其它板子依次沿用多条件原引用、旧单条件与屠城默认，不缓存或规范化配置。
 * 本入口只选择条件；评估时点、具体到期组合和阶段检查点由实际规则组合／经理负责；咒狐只在原已完成死亡波的位置改写阵营候选。
 * 封盘前先验证婚约分配，再验证结构／成员，日期最后读取；失败不写终态、不发布事件或恢复已付资源。
 */
import {
  WinCondition,
  type ReadonlyBoardConfig,
  type Phase,
  type VictoryCheckpoint,
  type WinDecision,
} from "@ai-werewolf-arena/game-contract";
import type { World } from "../core/domain/world";
import { weddingSetup, weddingAssignment } from "../game/mechanisms/roles/ghost_bride/ports";
import { replaceWithFoxVictory } from "../game/mechanisms/roles/cursed_fox/victory-ports";
import { validateVictoryDecision } from "../game/mechanisms/win_conditions/validated-victory";

/** 查询只捕获调用方；每个原读取位置才取配置／世界，不持有第二份执行配置或生命状态。 */
export interface TerminalVictoryRuntime {
  world(): World;
  config(): ReadonlyBoardConfig;
}

function resolveConfiguredVictoryConditions(runtime: TerminalVictoryRuntime): readonly WinCondition[] {
  if (weddingSetup(runtime.world())) {
    const conditions =
      runtime.config().winConditions ?? (runtime.config().winCondition ? [runtime.config().winCondition!] : []);
    if (conditions.length !== 1 || conditions[0] !== WinCondition.ThreeFactionsElimination)
      throw new Error("ghost_bride_win_condition_invalid");
    return [WinCondition.ThreeFactionsElimination];
  }
  if (Array.isArray(runtime.config().winConditions) && runtime.config().winConditions!.length > 0) {
    return runtime.config().winConditions!;
  }
  if (runtime.config().winCondition) {
    return [runtime.config().winCondition!];
  }
  // 不把空多条件数组当成终局不可判：保留原旧字段和最后屠城兜底。
  return [WinCondition.SlaughterCity];
}

function validateTerminalCandidate(
  decision: WinDecision,
  checkpoint: VictoryCheckpoint,
  phase: Phase,
  world: () => World,
  day: () => number,
) {
  if (weddingSetup(world())) weddingAssignment(world());
  // 婚约拒绝先于结果结构／成员，原校验器只在最后取 day；此处尚未封盘或付款。
  return validateVictoryDecision(decision, checkpoint, phase, world, day);
}

/** 三个实际候选能力；狐狸直接保原函数绑定，不叠加转发或新的胜利条件 registry。 */
export const TERMINAL_VICTORY_POLICY = Object.freeze({
  conditions: resolveConfiguredVictoryConditions,
  replaceFactionResult: replaceWithFoxVictory,
  validateCandidate: validateTerminalCandidate,
});

/**
 * 负责在原初始装配或已提交追加死亡波检查点，按固定顺序装配四类狼人刀权继承贡献。
 * 输入是原 World、事件与日期的延迟读取端口，输出为各机制的原继承事实和事件前缀。
 * 隐狼、石像鬼、机械狼、觉醒隐狼分别判断真实名单与自身资源；本组合不预先收齐名单、
 * 合并政策、缓存演员或拥有状态。首个错误原样传播并停止后续检查，不回滚已写继承，
 * 不增加 await、阶段变化、判胜、RNG、lease 或通用事件／清理框架。
 */
import { Role, type GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../core/domain/world";
import { refreshHiddenWolfInheritance } from "../game/mechanisms/roles/hidden_wolf/ports";
import { refreshGargoyleInheritance } from "../game/mechanisms/roles/gargoyle/ports";
import { refreshMechanicalInheritance } from "../game/mechanisms/roles/mechanical_wolf/ports";
import { refreshAwakenedInheritance } from "../game/mechanisms/roles/awakened_hidden_wolf/ports";

/** 只有检查点调用方提供现场读取；贡献对象本身不保存 World、演员或生命版本。 */
export interface WolfKnifeInheritanceRuntime {
  world(): World;
  events(): GameEvent[];
  day(): number;
}

interface WolfKnifeInheritanceContribution {
  readonly role: Role;
  check(runtime: WolfKnifeInheritanceRuntime): void;
}

// 原调用参数顺序有两种，不能统一成一次预读或重排：前两项 W/E/D，后两项 W/D/E。
const contributions: readonly WolfKnifeInheritanceContribution[] = Object.freeze([
  Object.freeze({
    role: Role.HiddenWolf,
    check: (runtime: WolfKnifeInheritanceRuntime) =>
      refreshHiddenWolfInheritance(runtime.world(), runtime.events(), runtime.day()),
  }),
  Object.freeze({
    role: Role.Gargoyle,
    check: (runtime: WolfKnifeInheritanceRuntime) =>
      refreshGargoyleInheritance(runtime.world(), runtime.events(), runtime.day()),
  }),
  Object.freeze({
    role: Role.MechanicalWolf,
    check: (runtime: WolfKnifeInheritanceRuntime) => {
      refreshMechanicalInheritance(runtime.world(), runtime.day(), runtime.events());
    },
  }),
  Object.freeze({
    role: Role.AwakenedHiddenWolf,
    check: (runtime: WolfKnifeInheritanceRuntime) =>
      refreshAwakenedInheritance(runtime.world(), runtime.day(), runtime.events()),
  }),
]);

/** 实际初始／死亡检查点共用同一有序贡献，逐项完成后才读取下一项的现场参数。 */
export function refreshWolfKnifeInheritanceAtCheckpoint(
  runtime: WolfKnifeInheritanceRuntime,
): void {
  for (const contribution of contributions) contribution.check(runtime);
}

/**
 * 负责普通狼狼聊、狼刀和自爆的完整工具准入组合，供共享普通狼装配及派生角色引用。
 * 输入为当前角色运行政策、原 World、阶段／窗口和工具上下文；输出为原首个拒绝或 null。
 * 婚礼狼刀先由鬼魂新娘原权威复验，否则依次检查狼队刀权、阶段、工具、pass 与只读目标贡献。
 * 同一可写规则表保留 callback 引用；派生展开与晚读取仍发生在原 profile／Registry 调用点。
 * 准入不执行工具、付款、开启窗口或授予租约；候选允许结果不能代替真正提交时的权限复验。
 */
import { canRoleSelfDestruct } from "../game/mechanisms/roles/self_destruct_capability";
import { bindWolfKnifeTargetQuery } from "../game/mechanisms/roles/wolf/ports";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  canSubmitWeddingTool,
} from "../game/mechanisms/roles/ghost_bride/ports";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { ActionWindow, Phase } from "../core/domain/model";
import type { ToolRuleMap } from "../game/mechanisms/validation/contracts";
import { wolfTeamPermissions } from "../game/mechanisms/roles/wolf_team";
import { COMPONENT } from "../core/domain/components/names";

/** 三工具保原首失败顺序；actorId仅在原Camp读取点的source内取得，常量能力不新增查询。 */
export const WOLF_VALIDATION_RULES: ToolRuleMap = {
  speak_to_wolves: (ctx) => {
    const { world, role, roleCatalog, phase } = ctx;
    if (!wolfTeamPermissions(role, roleCatalog, () => world.getComponent(ctx.actorId, COMPONENT.Camp), world).canChat) {
      return { code: RuleError.WolfChatPermission };
    }
    if (phase !== Phase.Night) return { code: RuleError.WolfChatPhase };
    return null;
  },
  kill_vote: ({ world, actorId, day, ghostBrideScope, role, roleCatalog, toolCall, phase }) => {
    // 婚礼分支优先；缺省日次仍为 0，不继续读取普通狼队政策或候选。
    if (weddingSetup(world))
      return canSubmitWeddingTool(world, actorId, phase, day ?? 0, ghostBrideScope, toolCall)
        ? null
        : { code: RuleError.GhostBrideUnavailable };
    if (!wolfTeamPermissions(role, roleCatalog, () => world.getComponent(actorId, COMPONENT.Camp), world).canVoteForKill) {
      return { code: RuleError.WolfKillPermission };
    }
    if (phase !== Phase.Night) return { code: RuleError.WolfKillPhase };
    if (toolCall.name !== "kill_vote") {
      return { code: RuleError.ToolMismatch };
    }
    // 原 pass 先于目标查询；非 pass 且首个目标非 null 时，保留三次 args 与两次 target_id 的现场读取。
    if (toolCall.args.abstain) {
      return null;
    }
    if (
      toolCall.args.target_id === null ||
      !bindWolfKnifeTargetQuery(world).allows(toolCall.args.target_id)
    ) {
      return { code: RuleError.KillTarget };
    }
    return null;
  },
  self_destruct: (ctx) => {
    const {
    world,
    role,
    roleCatalog,
    phase,
    actionWindow,
    allowSelfDestruct,
    toolCall,
    } = ctx;
    // 原婚礼成员排除先于角色自爆能力；阶段与窗口关系通过后检查已取出的 allowSelfDestruct，再读工具名／confirm。
    if (weddingSetup(world) && (!ghostBrideReady(world) || weddingMember(world, role)))
      return { code: RuleError.WolfBlastOnly };
    if (!canRoleSelfDestruct(role, roleCatalog, () => world.getComponent(ctx.actorId, COMPONENT.Camp))) {
      return { code: RuleError.WolfBlastOnly };
    }
    if (phase !== Phase.Day && phase !== Phase.Voting) {
      return { code: RuleError.BlastPhase };
    }
    if (actionWindow === undefined || !Object.values(ActionWindow).includes(actionWindow)) {
      return { code: RuleError.BlastWindow };
    }
    if (phase !== (actionWindow === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day))
      return { code: RuleError.BlastPhase };
    if (!allowSelfDestruct) {
      return { code: RuleError.BlastDisabled };
    }
    if (toolCall.name !== "self_destruct" || toolCall.args.confirm !== true) {
      return { code: RuleError.BlastConfirm };
    }
    return null;
  },
};

/**
 * 负责校验和规范化公开板子格式。输入为纯公开 JSON 与已登记角色声明；输出为原 BoardConfig、诊断和反向序列化配置。解析拥有字段／默认值规范化，规则集拥有有限支持裁决；不读取认证、执行对局或授予行动租约。
 */
import { boardPresetViolation } from "../../rulesets";
/** 唯一公开板子格式；未知字段和未注册角色保持原拒绝。 */
import { supportsWallRoles } from "../../game/mechanisms/events/wall_notes/authority";
import { z } from "zod";
import { RULESET } from "@ai-werewolf-arena/game-catalog";
import { ROLE_IDS, isRoleId } from "@ai-werewolf-arena/game-contract";
import { ActionWindow, Camp, Role, WinCondition, type BoardConfig } from "../../core/domain/model";
import { getDefaultRoleCatalog } from "../../game/mechanisms/roles/role-catalog-assembly";
import {
  EVENT_PACK_IDS,
  DEATH_REVEAL_POLICIES,
  LAST_WORDS_POLICIES,
  SHERIFF_BADGE_POLICIES,
  SHERIFF_ELECTION_POLICIES,
  EXILE_VOTE_POLICIES,
} from "../../core/domain/board";
import { boardConfigSchema } from "../../core/domain/board_schema";

export const CONFIG_ID_PATTERN = /^[a-z][a-z0-9_-]*$/;
export const MAX_BOARD_PLAYERS = 128;
export const boardIdSchema = z.string().regex(CONFIG_ID_PATTERN);
const safePositive = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
const hooks = z.strictObject({
  onDaybreak: z.boolean(),
  onPreElection: z.boolean(),
  onPreVote: z.boolean(),
  onPerSpeechGap: z.boolean(),
});
const schema = z.strictObject({
  version: z.literal(2),
  id: boardIdSchema,
  ruleset: z.strictObject({ id: z.literal(RULESET.id), version: z.literal(RULESET.version) }),
  board: z.strictObject({
    size: safePositive.max(MAX_BOARD_PLAYERS),
    roleSetups: z
      .array(
        z.strictObject({
          role: z.enum(ROLE_IDS as [string, ...string[]]),
          count: safePositive.max(MAX_BOARD_PLAYERS),
        }),
      )
      .min(1),
  }),
  rules: z.strictObject({ winConditions: z.array(z.enum(WinCondition)).min(1), hooks }),
  mechanisms: z.strictObject({
    eventPack: z.enum(EVENT_PACK_IDS).optional(),
    disclosure: z
      .strictObject({ deathRevealPolicy: z.enum(DEATH_REVEAL_POLICIES).default("awa_hidden_v1") })
      .default({ deathRevealPolicy: "awa_hidden_v1" }),
    lastWords: z
      .strictObject({ policy: z.enum(LAST_WORDS_POLICIES).default("awa_initial_wave_v1") })
      .default({ policy: "awa_initial_wave_v1" }),
    sheriff: z.strictObject({
      enabled: z.boolean(),
      electionPolicy: z.enum(SHERIFF_ELECTION_POLICIES).default("awa_final_candidates_v1"),
      badgePolicy: z.enum(SHERIFF_BADGE_POLICIES).default("awa_next_seat_v1"),
      initialSeat: safePositive.optional(),
      voteWeight: z.number().finite().positive().default(1.5),
      tieBreaker: z.enum(["min_id", "min_seat", "no_elimination"]).default("min_seat"),
    }),
    voting: z
      .strictObject({ exilePolicy: z.enum(EXILE_VOTE_POLICIES).default("awa_direct_v1") })
      .default({ exilePolicy: "awa_direct_v1" }),
    selfDestruct: z.strictObject({ enabledWindows: z.array(z.enum(ActionWindow)) }),
    tieBreaker: z.strictObject({
      exileVote: z.enum(["min_id", "no_elimination"]),
      wolfKillVote: z.enum(["min_id", "no_kill"]),
    }),
  }),
  roles: z.record(z.string(), z.unknown()).default({}),
});

export type BoardDefinition = z.infer<typeof schema>;
export interface ResolvedBoardDefinition {
  definition: BoardDefinition;
  config: BoardConfig;
  sourceFile?: string;
  fieldSources: Readonly<Record<string, "explicit" | "default">>;
}

export class BoardConfigurationError extends Error {
  constructor(
    readonly code: string,
    readonly fieldPath: string,
  ) {
    super(`${code}: ${fieldPath}`);
  }
}
function fail(code: string, path: string): never {
  throw new BoardConfigurationError(code, path);
}

export function parseBoardDefinition(raw: unknown, expectedId?: string): ResolvedBoardDefinition {
  const result = schema.safeParse(raw);
  if (!result.success) {
    const issue = result.error.issues[0];
    const key = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
    fail(
      "board_config_invalid_field",
      [...issue.path, ...(key ? [key] : [])].join(".") || "document",
    );
  }
  const definition = result.data;
  if (expectedId !== undefined && definition.id !== expectedId)
    fail("board_config_id_mismatch", "id");
  const catalog = getDefaultRoleCatalog();
  const seen = new Set<string>();
  let total = 0;
  for (const [index, entry] of definition.board.roleSetups.entries()) {
    if (!isRoleId(entry.role) || !catalog.metadata(entry.role as Role))
      fail("board_config_role_not_implemented", `board.roleSetups.${index}.role`);
    if (seen.has(entry.role)) fail("board_config_duplicate_role", `board.roleSetups.${index}.role`);
    const maximum = catalog.requireMetadata(entry.role as Role).maxCount;
    if (maximum !== undefined && entry.count > maximum)
      fail("board_config_invalid_field", `board.roleSetups.${index}.count`);
    seen.add(entry.role);
    total += entry.count;
  }
  if (total !== definition.board.size) fail("board_config_role_count_mismatch", "board.roleSetups");
  if (
    definition.board.roleSetups.some((row) => row.role === "shapeshifter") &&
    (definition.board.size < 6 ||
      definition.board.roleSetups
        .filter((row) => row.role === "wolf")
        .reduce((n, row) => n + row.count, 0) < 2 ||
      !definition.board.roleSetups.some(
        (row) => row.role !== "shapeshifter" && catalog.getCamp(row.role as Role) === Camp.Good,
      ))
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  if (definition.board.roleSetups.some((row) => row.role === "thief")) {
    const wolves = definition.board.roleSetups
        .filter((row) => row.role === "wolf")
        .reduce((n, row) => n + row.count, 0),
      good = definition.board.roleSetups
        .filter((row) => row.role !== "thief" && catalog.getCamp(row.role as Role) === Camp.Good)
        .reduce((n, row) => n + row.count, 0);
    if (wolves < 2 || good < 2)
      fail("board_config_role_combination_not_supported", "board.roleSetups");
  }
  if (
    definition.board.roleSetups.some((row) => row.role === "wild_child") &&
    !definition.board.roleSetups.some(
      (row) => row.role !== "wild_child" && catalog.getCamp(row.role as Role) === Camp.Good,
    )
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  if (
    definition.board.roleSetups.some((row) => row.role === "lonely_girl") &&
    (definition.board.size < 6 ||
      !definition.board.roleSetups.some((row) => row.role === "wolf") ||
      !definition.board.roleSetups.some(
        (row) => row.role !== "lonely_girl" && catalog.getCamp(row.role as Role) === Camp.Good,
      ))
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  const profiles = definition.board.roleSetups.map((entry) =>
    catalog.requireMetadata(entry.role as Role),
  );
  for (const profile of profiles) {
    if (
      profile.supportedBoardRoles &&
      definition.board.roleSetups.some(
        (entry) => !profile.supportedBoardRoles!.includes(entry.role as Role),
      )
    ) {
      fail("board_config_role_combination_not_supported", "board.roleSetups");
    }
  }
  if (
    !profiles.some((item) => item.camp === Camp.Wolf) ||
    !profiles.some((item) => item.camp === Camp.Good)
  ) {
    fail("board_config_requires_good_and_wolf", "board.roleSetups");
  }
  for (const profile of profiles)
    if (
      profile.supportedWinConditions &&
      definition.rules.winConditions.some(
        (condition) => !profile.supportedWinConditions!.includes(condition),
      )
    )
      fail("board_config_role_win_condition_not_supported", "rules.winConditions");
  if (new Set(definition.rules.winConditions).size !== definition.rules.winConditions.length)
    fail("board_config_duplicate_win_condition", "rules.winConditions");
  if (
    definition.mechanisms.eventPack &&
    !supportsWallRoles(definition.board.roleSetups.map((e) => e.role as Role))
  )
    fail("board_config_role_combination_not_supported", "mechanisms.eventPack");
  const sheriff = definition.mechanisms.sheriff;
  if (sheriff.initialSeat && sheriff.initialSeat > total)
    fail("board_config_seat_out_of_range", "mechanisms.sheriff.initialSeat");
  if (
    !sheriff.enabled &&
    (sheriff.initialSeat ||
      sheriff.voteWeight !== 1.5 ||
      sheriff.tieBreaker !== "min_seat" ||
      sheriff.electionPolicy !== "awa_final_candidates_v1" ||
      sheriff.badgePolicy !== "awa_next_seat_v1")
  ) {
    fail("board_config_disabled_mechanism_parameters", "mechanisms.sheriff");
  }
  const windows = definition.mechanisms.selfDestruct.enabledWindows;
  if (new Set(windows).size !== windows.length)
    fail("board_config_duplicate_window", "mechanisms.selfDestruct.enabledWindows");
  const windowHooks = {
    [ActionWindow.OnPreVote]: "onPreVote",
    [ActionWindow.OnDaybreak]: "onDaybreak",
    [ActionWindow.OnPreElection]: "onPreElection",
    [ActionWindow.OnPerSpeechGap]: "onPerSpeechGap",
  } as const;
  for (const window of windows)
    if (!definition.rules.hooks[windowHooks[window]])
      fail("board_config_window_hook_disabled", `rules.hooks.${windowHooks[window]}`);
  if (definition.rules.winConditions.includes(WinCondition.SlaughterSide)) {
    if (
      !profiles.some((item) => item.goodSide === "god") ||
      !profiles.some((item) => item.goodSide === "villager")
    ) {
      fail("board_config_slaughter_side_requires_both_sides", "rules.winConditions");
    }
  }
  let config: BoardConfig = {
    boardSize: total,
    roleSetups: definition.board.roleSetups.map((entry) => ({
      role: entry.role as Role,
      count: entry.count,
    })),
    winConditions: [...definition.rules.winConditions],
    hooks: { ...definition.rules.hooks },
    enableSheriff: sheriff.enabled,
    ...(sheriff.initialSeat ? { initialSheriffSeat: sheriff.initialSeat } : {}),
    ...(sheriff.enabled
      ? {
          sheriff: {
            voteWeight: sheriff.voteWeight,
            electionPolicy: sheriff.electionPolicy,
            badgePolicy: sheriff.badgePolicy,
          },
        }
      : {}),
    selfDestruct: { enabledWindows: [...windows] },
    ...(definition.mechanisms.eventPack
      ? { events: { pack: definition.mechanisms.eventPack } }
      : {}),
    voting: { ...definition.mechanisms.voting },
    disclosure: { ...definition.mechanisms.disclosure },
    lastWords: { ...definition.mechanisms.lastWords },
    tieBreaker: {
      ...definition.mechanisms.tieBreaker,
      ...(sheriff.enabled ? { sheriffVote: sheriff.tieBreaker } : {}),
    },
  };
  for (const [id, value] of Object.entries(definition.roles)) {
    if (!seen.has(id)) fail("board_config_role_parameters_without_role", `roles.${id}`);
    const contribution = catalog.requireRuntime(id as Role).configuration;
    if (!contribution) fail("board_config_role_parameters_not_supported", `roles.${id}`);
    const parsed = contribution.schema.safeParse(value);
    if (!parsed.success) {
      const issue = parsed.error.issues[0];
      const unknown = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
      fail(
        "board_config_invalid_field",
        ["roles", id, ...issue.path, ...(unknown ? [unknown] : [])].join("."),
      );
    }
    definition.roles[id] = parsed.data;
    config = contribution.apply(config, parsed.data);
  }
  for (const id of seen) {
    const contribution = catalog.requireRuntime(id as Role).configuration;
    if (contribution && !(id in definition.roles)) {
      const defaults = contribution.schema.parse(contribution.defaults);
      definition.roles[id] = defaults;
      config = contribution.apply(config, defaults);
    }
  }
  const presetViolation = boardPresetViolation(config);
  if (presetViolation) fail(`board_config_${presetViolation}`, "board");
  const fieldSources: Record<string, "explicit" | "default"> = {};
  const recordSources = (value: unknown, original: unknown, prefix: string) => {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      for (const [key, entry] of Object.entries(value)) {
        const prior =
          original && typeof original === "object"
            ? (original as Record<string, unknown>)[key]
            : undefined;
        recordSources(entry, prior, prefix ? `${prefix}.${key}` : key);
      }
    } else fieldSources[prefix] = original === undefined ? "default" : "explicit";
  };
  recordSources(definition, raw, "");
  return { definition, config, fieldSources };
}

/** 公开板子只含实际角色的参数；Tape 仍保留完整内部板子。 */
export function boardDefinitionFromConfig(id: string, config: BoardConfig): BoardDefinition {
  const valid = boardConfigSchema.safeParse(config);
  if (!valid.success) {
    const issue = valid.error.issues[0];
    const key = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
    fail("board_config_invalid_field", ["config", ...issue.path, ...(key ? [key] : [])].join("."));
  }
  const catalog = getDefaultRoleCatalog();
  const roles: Record<string, unknown> = {};
  for (const entry of config.roleSetups.filter((entry) => entry.count > 0)) {
    const contribution = catalog.requireRuntime(entry.role).configuration;
    if (contribution) roles[entry.role] = contribution.serialize(config);
  }
  const conditions = config.winConditions?.length
    ? config.winConditions
    : [config.winCondition ?? WinCondition.SlaughterCity];
  return parseBoardDefinition({
    version: 2,
    id,
    ruleset: RULESET,
    board: {
      size: config.boardSize,
      roleSetups: config.roleSetups.filter((entry) => entry.count > 0),
    },
    rules: { winConditions: conditions, hooks: config.hooks },
    mechanisms: {
      ...(config.events ? { eventPack: config.events.pack } : {}),
      disclosure: { deathRevealPolicy: config.disclosure?.deathRevealPolicy ?? "awa_hidden_v1" },
      lastWords: { policy: config.lastWords?.policy ?? "awa_initial_wave_v1" },
      sheriff: {
        enabled: config.enableSheriff,
        ...(config.enableSheriff
          ? {
              ...(config.initialSheriffSeat !== undefined
                ? { initialSeat: config.initialSheriffSeat }
                : {}),
              voteWeight: config.sheriff?.voteWeight ?? 1.5,
              electionPolicy: config.sheriff?.electionPolicy ?? "awa_final_candidates_v1",
              badgePolicy: config.sheriff?.badgePolicy ?? "awa_next_seat_v1",
              tieBreaker: config.tieBreaker?.sheriffVote ?? "min_seat",
            }
          : {}),
      },
      voting: { exilePolicy: config.voting?.exilePolicy ?? "awa_direct_v1" },
      selfDestruct: {
        enabledWindows: (config.selfDestruct?.enabledWindows ?? [ActionWindow.OnPreVote]).filter(
          (window) =>
            ({
              [ActionWindow.OnPreVote]: config.hooks.onPreVote,
              [ActionWindow.OnDaybreak]: config.hooks.onDaybreak,
              [ActionWindow.OnPreElection]: config.hooks.onPreElection,
              [ActionWindow.OnPerSpeechGap]: config.hooks.onPerSpeechGap,
            })[window],
        ),
      },
      tieBreaker: {
        exileVote: config.tieBreaker?.exileVote ?? "min_id",
        wolfKillVote: config.tieBreaker?.wolfKillVote ?? "min_id",
      },
    },
    roles,
  }).definition;
}

/**
 * 显式将旧板子覆盖转换为版本化 BoardDefinition，输出定义及有序迁移警告；正常加载不调用旧格式回退。
 * 已带版本的输入直接交给当前解析器；旧输入先按指定历史基板解析，再保存其实际生效参数。
 * 本模块只生成转换数据，不读写文件、运行对局或改归档指纹；默认值、裁掉的窗口及无效角色参数通过稳定警告码说明。
 */
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
  type BoardDefinition,
} from "./board_definition";
import { ActionWindow } from "../../core/domain/model";
import {
  parseBoardOverride,
  resolveBoardConfig,
  type BoardName,
} from "../scenarios/board_config_resolver";

export const MIGRATION_WARNING_CODES = [
  "legacy_defaults_resolved_explicitly",
  "legacy_single_win_condition_shadowed_by_effective_win_conditions",
  "legacy_empty_windows_used_default_pre_vote_window",
  "legacy_windows_with_disabled_hooks_removed_explicitly",
  "legacy_unused_witch_parameters_removed_explicitly",
  "legacy_unsupported_windows_removed_explicitly",
] as const;
export type MigrationWarningCode = (typeof MIGRATION_WARNING_CODES)[number];
/** warnings 描述显式归一产生的差异；它们是迁移说明，不能当作运行时规则或通用容错授权。 */
export interface BoardMigration {
  definition: BoardDefinition;
  warnings: MigrationWarningCode[];
}

export function convertLegacyBoard(
  raw: unknown,
  boardId: string,
  legacyBase?: BoardName,
): BoardMigration {
  if (raw && typeof raw === "object" && "version" in raw) {
    return { definition: parseBoardDefinition(raw, boardId).definition, warnings: [] };
  }
  const base = legacyBase ?? boardId;
  if (base !== "six_player_mvp" && base !== "twelve_player_standard") {
    throw new Error("board_config_legacy_base_unknown");
  }
  const override = parseBoardOverride(raw, (legacyBase ?? boardId) as BoardName);
  if (!override) throw new Error("board_config_legacy_shape_invalid");
  const historical = { ...override };
  // 空自爆窗口在旧执行中触发默认窗口；先按旧语义展开，再转换，不能把空数组解释为新禁用政策。
  if (historical.selfDestruct?.enabledWindows.length === 0) delete historical.selfDestruct;
  const effective = resolveBoardConfig(base as BoardName, historical);
  // 当前版本只保留既有可执行的 OnPreVote 窗口；移除其它旧项时明确报警，不静默改变旧档来源。
  const unsupported =
    effective.selfDestruct?.enabledWindows.filter((window) => window !== ActionWindow.OnPreVote) ??
    [];
  if (unsupported.length)
    effective.selfDestruct = {
      enabledWindows: effective.selfDestruct!.enabledWindows.filter(
        (window) => window === ActionWindow.OnPreVote,
      ),
    };
  const warnings: MigrationWarningCode[] = ["legacy_defaults_resolved_explicitly"];
  if (unsupported.length) warnings.push("legacy_unsupported_windows_removed_explicitly");
  // 警告顺序固定，单一旧判胜项被实际生效的列表覆盖时也保留解释，定义只序列化最终配置。
  if (override.winCondition && effective.winConditions?.length)
    warnings.push("legacy_single_win_condition_shadowed_by_effective_win_conditions");
  if (override.selfDestruct?.enabledWindows.length === 0 && effective.hooks.onPreVote)
    warnings.push("legacy_empty_windows_used_default_pre_vote_window");
  const windowHooks = {
    [ActionWindow.OnPreVote]: effective.hooks.onPreVote,
    [ActionWindow.OnDaybreak]: effective.hooks.onDaybreak,
    [ActionWindow.OnPreElection]: effective.hooks.onPreElection,
    [ActionWindow.OnPerSpeechGap]: effective.hooks.onPerSpeechGap,
  };
  if (
    [...unsupported, ...(effective.selfDestruct?.enabledWindows ?? [])].some(
      (window) => !windowHooks[window],
    )
  )
    warnings.push("legacy_windows_with_disabled_hooks_removed_explicitly");
  if (
    override.witch &&
    !effective.roleSetups.some((entry) => entry.role === "witch" && entry.count > 0)
  )
    warnings.push("legacy_unused_witch_parameters_removed_explicitly");
  return { definition: boardDefinitionFromConfig(boardId, effective), warnings };
}

/**
 * 负责合并已解析配置、运行参数和座位／角色 Agent 选择。输入为公开配置与 CLI 覆盖；
 * 输出为完整对局设置、逐玩家配置和语言回退诊断。仅选择已登记角色，不创建对局、
 * 读取认证或授予行动权限；名字和人格保留原文，不参与模型选择。
 */
import type { BoardConfig } from "../../core";
import type {
  GameConfig,
  GameAgentSelection,
  ResolvedAgentRuntimeProfile,
  ResolvedAuditConfig,
  RuntimeConfig,
  PlayerConfig,
} from "./contracts";
import type { Locale } from "@ai-werewolf-arena/game-contract";
import {
  resolveBoardConfig,
  type BoardName,
  type BoardOverride,
} from "../scenarios/board_config_resolver";
import { type ResolvedBoardDefinition } from "./board_definition";
import { getDefaultRoleCatalog } from "../../game/mechanisms/roles/role-catalog-assembly";
import { Role } from "../../core/domain/identity";

export interface RunGameOptions {
  board: string;
  maxDays: number;
  maxRuntimeMs: number;
  llmTimeoutMs: number;
  trace: boolean;
  printAllEvents: boolean;
  printChat: boolean;
  streamEvents: boolean;
  color: boolean;
  printLlmIo: boolean;
  printThinking: boolean;
  printPrivateEvents: boolean;
  recordRootDir?: string;
}

export interface GameSetupWarning {
  code: "locale_prompt_fallback";
  path: string;
  requestedLocale: Locale;
  fallbackLocale: Locale;
}

export interface ResolvedPlayerConfig {
  name?: string;
  profile?: ResolvedAgentRuntimeProfile;
  personalityPrompt?: string | null;
}

/** runner 的完整输入：已解析板子、逐玩家／角色 profile 与可选审计；不携带运行句柄或已分配身份。 */
export interface ResolvedGameSetup {
  options: RunGameOptions;
  boardConfig: BoardConfig;
  defaultProfile: ResolvedAgentRuntimeProfile;
  playerProfiles: Readonly<Record<string, ResolvedAgentRuntimeProfile>>;
  roleProfiles: Readonly<Record<string, ResolvedAgentRuntimeProfile>>;
  audit: ResolvedAuditConfig | null;
  boardDefinition?: ResolvedBoardDefinition;
  context: { locale: Locale; displayLocale: Locale; seed?: string };
  players: Readonly<Record<string, ResolvedPlayerConfig>>;
  warnings: readonly GameSetupWarning[];
}

/** 分配身份后按 players 显式 Agent→playerAgents→roleAgents→默认值选择；独立人格最后覆盖，null 清除继承。 */
export function resolvePlayerProfile(
  setup: ResolvedGameSetup,
  actorId: number,
  role?: Role,
): ResolvedAgentRuntimeProfile {
  const player = setup.players[String(actorId)];
  const selected =
    player?.profile ??
    setup.playerProfiles[String(actorId)] ??
    (role ? setup.roleProfiles[role] : undefined) ??
    setup.defaultProfile;
  return player?.personalityPrompt !== undefined
    ? { ...selected, personalityPrompt: player.personalityPrompt ?? undefined }
    : selected;
}

export function resolveGameBoard(
  runtime: RuntimeConfig,
  overrides: Partial<RunGameOptions> = {},
): string {
  const board = overrides.board ?? runtime.game.board ?? "six_player_mvp";
  if (!/^[a-z][a-z0-9_-]*$/.test(board)) {
    throw new Error(`runtime_config_board_invalid: ${board}`);
  }
  return board;
}

export function resolveAgentProfileByName(
  runtime: RuntimeConfig,
  agentName?: string,
): ResolvedAgentRuntimeProfile {
  const selected = agentName ?? runtime.agents.default;
  const entry = runtime.agents.items[selected];
  if (!entry) throw new Error(`runtime_config_agent_not_found: ${selected}`);
  const provider = runtime.providers.items[entry.provider];
  if (!provider)
    throw new Error(
      `runtime_config_agent_provider_not_found: agent=${selected} provider=${entry.provider}`,
    );
  if (entry.kind === "acp") {
    return {
      name: selected,
      providerName: entry.provider,
      provider,
      kind: "acp",
      spawnArgs: entry.spawnArgs,
      sessionReuse: entry.sessionReuse,
      actionTransport: entry.actionTransport ?? "mcp",
      personalityPrompt: entry.personalityPrompt,
    };
  }
  return {
    name: selected,
    providerName: entry.provider,
    provider,
    kind: "llm",
    model: entry.model,
    temperature: entry.temperature,
    maxTokens: entry.maxTokens,
    reasoningEffort: entry.reasoningEffort,
    thinkingEnabled: entry.thinkingEnabled,
    personalityPrompt: entry.personalityPrompt,
  };
}

function resolveSelections(
  runtime: RuntimeConfig,
  selections: Record<string, GameAgentSelection> | undefined,
): Record<string, ResolvedAgentRuntimeProfile> {
  return Object.fromEntries(
    Object.entries(selections ?? {}).map(([key, selection]) => {
      const name = typeof selection === "string" ? selection : selection.agent;
      const profile = resolveAgentProfileByName(runtime, name);
      const spawnArgs = typeof selection === "object" ? selection.spawnArgs : undefined;
      const personalityPrompt =
        typeof selection === "object" ? selection.personalityPrompt : undefined;
      return [
        key,
        {
          ...profile,
          ...(profile.kind === "acp" && spawnArgs?.length
            ? { spawnArgs: [...(profile.spawnArgs ?? []), ...spawnArgs] }
            : {}),
          ...(personalityPrompt !== undefined ? { personalityPrompt } : {}),
        },
      ];
    }),
  );
}

export function resolveGameSetup(
  runtime: RuntimeConfig,
  overrides: Partial<RunGameOptions> = {},
  boardOverride: BoardOverride | ResolvedBoardDefinition | null = null,
): ResolvedGameSetup {
  if (
    !runtime.providers.items[runtime.providers.default] ||
    !runtime.agents.items[runtime.agents.default]
  ) {
    throw new Error("runtime_config_missing_provider_or_agent_defaults");
  }
  const game = runtime.game;
  // 空值合并让显式 false 保持有效；CLI 覆盖只作用于这里声明的运行选项，语言和 seed 仍由 game 提供。
  const options: RunGameOptions = {
    board: resolveGameBoard(runtime, overrides),
    maxDays: overrides.maxDays ?? game.maxDays ?? 10,
    maxRuntimeMs: overrides.maxRuntimeMs ?? game.maxRuntimeMs ?? 30000,
    llmTimeoutMs: overrides.llmTimeoutMs ?? game.llmTimeoutMs ?? 30000,
    trace: overrides.trace ?? game.trace ?? false,
    printAllEvents: overrides.printAllEvents ?? game.printAllEvents ?? false,
    printChat: overrides.printChat ?? game.printChat ?? false,
    streamEvents: overrides.streamEvents ?? game.streamEvents ?? true,
    color: overrides.color ?? game.color ?? true,
    printLlmIo: overrides.printLlmIo ?? game.printLlmIo ?? false,
    printThinking: overrides.printThinking ?? game.printThinking ?? false,
    printPrivateEvents: overrides.printPrivateEvents ?? game.printPrivateEvents ?? true,
    recordRootDir: overrides.recordRootDir ?? game.recordRootDir,
  };
  const auditConfig = runtime.debugSummary?.agent;
  for (const key of ["maxDays", "maxRuntimeMs", "llmTimeoutMs"] as const) {
    if (!Number.isSafeInteger(options[key]) || options[key] <= 0)
      throw new Error(`runtime_config_positive_integer_invalid: game.${key}`);
  }
  // 具名定义必须与选定板子一致；没有定义时只接受原两项内置板子，不由 runner 猜测支持组合。
  const boardDefinition =
    boardOverride && "definition" in boardOverride ? boardOverride : undefined;
  if (boardDefinition && boardDefinition.definition.id !== options.board)
    throw new Error("runtime_config_board_definition_mismatch");
  if (
    !boardDefinition &&
    options.board !== "six_player_mvp" &&
    options.board !== "twelve_player_standard"
  ) {
    throw new Error(`runtime_config_board_definition_required: ${options.board}`);
  }
  const boardConfig =
    boardDefinition?.config ??
    resolveBoardConfig(options.board as BoardName, boardOverride as BoardOverride | null);
  validateGameBindings(game, boardConfig);
  const locale = game.locale ?? "zh-CN";
  const warnings: GameSetupWarning[] = [];
  const players = resolvePlayers(runtime, game.players, locale, warnings);
  return {
    options,
    boardConfig,
    ...(boardDefinition ? { boardDefinition } : {}),
    context: {
      locale,
      displayLocale: game.displayLocale ?? locale,
      ...(game.seed ? { seed: game.seed } : {}),
    },
    players,
    warnings,
    defaultProfile: resolveAgentProfileByName(runtime, game.agent),
    playerProfiles: resolveSelections(runtime, game.playerAgents),
    roleProfiles: resolveSelections(runtime, game.roleAgents),
    // 只有显式 enabled:false 才关闭审计；省略配置保原默认值，创建与失败处理留给运行／审计 owner。
    audit:
      auditConfig?.enabled === false
        ? null
        : {
            profile: resolveAgentProfileByName(runtime, auditConfig?.agentName ?? game.agent),
            timeoutMs: auditConfig?.timeoutMs ?? 15000,
            maxAttempts: Math.max(1, auditConfig?.maxAttempts ?? 2),
            concurrency: Math.max(1, auditConfig?.concurrency ?? 4),
            publicMaxItems: Math.max(60, auditConfig?.publicMaxItems ?? 200),
            maxItems: Math.max(50, auditConfig?.maxItems ?? 200),
            playerMaxItems: Math.max(60, auditConfig?.playerMaxItems ?? 120),
          },
  };
}

export function validateGameBindings(game: GameConfig, board: BoardConfig): void {
  const catalog = getDefaultRoleCatalog();
  for (const entry of board.roleSetups) catalog.requireMetadata(entry.role);
  const present = new Set(
    board.roleSetups.filter((entry) => entry.count > 0).map((entry) => entry.role),
  );
  for (const key of Object.keys(game.roleAgents ?? {})) {
    if (!catalog.metadata(key as Role) || !present.has(key as Role))
      throw new Error(`runtime_config_role_binding_invalid: ${key}`);
  }
  for (const key of Object.keys(game.playerAgents ?? {})) {
    if (
      !/^[1-9]\d*$/.test(key) ||
      Number(key) > board.boardSize ||
      !Number.isSafeInteger(Number(key))
    ) {
      throw new Error(`runtime_config_player_binding_invalid: ${key}`);
    }
  }
  // 同一座位同时出现于新 players 和旧 playerAgents 会拒绝，避免隐式优先级掩盖配置冲突。
  for (const key of Object.keys(game.players ?? {})) {
    if (
      !/^[1-9]\d*$/.test(key) ||
      Number(key) > board.boardSize ||
      !Number.isSafeInteger(Number(key))
    )
      throw new Error(`runtime_config_player_binding_invalid: ${key}`);
    if (game.playerAgents && key in game.playerAgents)
      throw new Error(`runtime_config_player_binding_conflict: ${key}`);
  }
}

function resolvePlayers(
  runtime: RuntimeConfig,
  entries: Record<string, PlayerConfig> | undefined,
  locale: Locale,
  warnings: GameSetupWarning[],
): Record<string, ResolvedPlayerConfig> {
  return Object.fromEntries(
    Object.entries(entries ?? {}).map(([seat, entry]) => {
      let profile = entry.agent ? resolveAgentProfileByName(runtime, entry.agent) : undefined;
      if (profile?.kind === "acp" && entry.spawnArgs?.length)
        profile = { ...profile, spawnArgs: [...(profile.spawnArgs ?? []), ...entry.spawnArgs] };
      let personalityPrompt: string | null | undefined =
        entry.personalityPrompt === null ? null : undefined;
      if (typeof entry.personalityPrompt === "string") personalityPrompt = entry.personalityPrompt;
      // 语言表优先本语言，再优先中文、最后英文；只产生回退诊断，不翻译用户人格文本。
      else if (entry.personalityPrompt) {
        if (entry.personalityPrompt[locale]) personalityPrompt = entry.personalityPrompt[locale];
        else {
          const fallback = entry.personalityPrompt["zh-CN"] ? "zh-CN" : "en";
          personalityPrompt = entry.personalityPrompt[fallback];
          warnings.push({
            code: "locale_prompt_fallback",
            path: `players.${seat}.personalityPrompt`,
            requestedLocale: locale,
            fallbackLocale: fallback,
          });
        }
      }
      return [
        seat,
        {
          ...(entry.name !== undefined ? { name: entry.name } : {}),
          ...(profile ? { profile } : {}),
          ...(personalityPrompt !== undefined ? { personalityPrompt } : {}),
        },
      ];
    }),
  );
}

/**
 * 负责终端游戏事件、结果与 ACP 增量输出。输入为已投影事件、运行摘要、ACP 更新与输出选项；输出为原文本和着色日志。仅持有文本片段与工具显示状态，不落盘、不推进阶段或提交游戏行动。分段和去重保留原顺序，失败不改游戏事实。
 */
import { formatErrorDiagnostic } from "../utils/error_diagnostic";
import { text, dictionaries, type MessageKey, type Locale } from "@ai-werewolf-arena/game-text";
import {
  outcomeLabel,
  outcomeWinnersLabel,
  victoryPointLabel,
} from "@ai-werewolf-arena/game-presentation";
import { getDefaultScriptEventRenderRegistry } from "../game";
import type { GameEvent, RuntimeSnapshot } from "../core";
import { colorize, isAnsiEnabled } from "../utils/ansi";

export type ConsoleTone = "muted" | "info" | "ok" | "warn" | "error" | "accent" | "god";
export type ConsoleLog = (text: string, tone?: ConsoleTone) => void;

export function toChatLines(events: readonly GameEvent[], locale: Locale = "zh-CN"): string[] {
  const registry = getDefaultScriptEventRenderRegistry();
  return events.flatMap((event) => {
    const line = registry.toChatLine(event, locale);
    return line ? [line] : [];
  });
}

export function createConsoleLog(color: boolean): ConsoleLog {
  const enabled = isAnsiEnabled(color);
  return (text, tone = "info") => console.log(colorize(text, tone, enabled));
}

export function presentStreamEvents(
  events: readonly GameEvent[],
  printPrivateEvents: boolean,
  log: ConsoleLog,
  locale: Locale = "zh-CN",
): void {
  const registry = getDefaultScriptEventRenderRegistry();
  for (const event of events) {
    for (const render of registry.toLiveRender(event, printPrivateEvents, locale)) {
      const tone =
        render.kind === "chat"
          ? "accent"
          : render.kind === "private"
            ? "warn"
            : render.kind === "action"
              ? "info"
              : render.kind === "god"
                ? "god"
                : "ok";
      log(render.text, tone);
    }
  }
}

export function presentGameResult(input: {
  locale?: Locale;
  board: string;
  snapshot: RuntimeSnapshot;
  events: readonly GameEvent[];
  timedOut: boolean;
  printAllEvents: boolean;
  printChat: boolean;
  streamEvents: boolean;
  log: ConsoleLog;
}): void {
  const { board, snapshot, events, timedOut, log } = input;
  log(
    `[run_game] done board=${board} gameOver=${snapshot.gameOver} day=${snapshot.day} winner=${snapshot.result?.winner ?? "none"} timedOut=${timedOut} · ${text(input.locale ?? "zh-CN", "runtime.done")}`,
    "ok",
  );
  log(
    `[run_game] events=${events.length} · ${text(input.locale ?? "zh-CN", "runtime.event_count")}`,
    "info",
  );
  if (snapshot.result) {
    const locale = input.locale ?? "zh-CN";
    log(
      `[result] ${outcomeLabel(snapshot.result.outcome, locale)} · ${outcomeWinnersLabel(snapshot.result.outcome, locale)} · ${victoryPointLabel(snapshot.result.decidedAt, locale)}`,
      "ok",
    );
  }
  if (input.printAllEvents) console.log(JSON.stringify(events, null, 2));
  if (input.printChat && !input.streamEvents) {
    for (const line of toChatLines(events, input.locale)) console.log(line);
  }
}

type AcpUpdateRecord = Record<string, unknown>;
function asRecord(value: unknown): AcpUpdateRecord | null {
  return value && typeof value === "object" ? (value as AcpUpdateRecord) : null;
}
function updateText(value: unknown): string {
  if (typeof value === "string") return value;
  const record = asRecord(value);
  return typeof record?.text === "string" ? record.text : "";
}
function compact(value: string, maxLength = 500): string {
  const normalized = value.replace(/\s+/g, " ").trim();
  return normalized.length > maxLength ? `${normalized.slice(0, maxLength)}…` : normalized;
}

export interface AcpConsoleLogger {
  (update: unknown): void;
  flush(): void;
}

export function createAcpConsoleLogger(
  actorId: number,
  log: ConsoleLog,
  locale: Locale = "zh-CN",
  options: { printThinking: boolean; printLlmIo: boolean } = {
    printThinking: true,
    printLlmIo: false,
  },
): AcpConsoleLogger {
  const textLabel = (key: MessageKey) => text(locale, key);
  // 每个 logger 只服务一个玩家；按文本类别和 messageId 合并增量，工具状态仅用于显示去重。
  let pending: { kind: "message" | "thought"; id: string; text: string } | null = null;
  const toolStates = new Map<string, { label: string; status?: string; error: string }>();
  const emitText = (kind: "message" | "thought", value: string) => {
    if (kind === "thought" ? !options.printThinking : !options.printThinking && !options.printLlmIo)
      return;
    const text = compact(value, Infinity);
    if (text && !/^\*?conversation interrupted\*?$/i.test(text)) {
      log(
        `[acp][${actorId}][${kind}] ${kind === "thought" ? textLabel("runtime.acp.thought") : textLabel("runtime.acp.message")}: ${text}`,
        "muted",
      );
    }
  };
  const flush = () => {
    const previous = pending;
    pending = null;
    if (previous) emitText(previous.kind, previous.text);
  };
  const observer = (update: unknown) => {
    const event = asRecord(update);
    if (!event || typeof event.sessionUpdate !== "string") return;
    const type = event.sessionUpdate;
    if (type === "agent_message_chunk" || type === "agent_thought_chunk") {
      const kind = type === "agent_message_chunk" ? "message" : "thought";
      if (
        kind === "thought" ? !options.printThinking : !options.printThinking && !options.printLlmIo
      ) {
        flush();
        return;
      }
      const messageId = typeof event.messageId === "string" ? event.messageId : "unknown";
      if (pending && (pending.kind !== kind || pending.id !== messageId)) flush();
      if (!pending) pending = { kind, id: messageId, text: "" };
      pending.text += updateText(event.content);
      // ACP 片段是增量文本；按原分段边界合并后输出，保留文字并限制缓冲长度。
      while (pending.text.length) {
        const newline = pending.text.search(/[\r\n]/);
        let end = newline >= 0 && newline <= 500 ? newline : 500;
        if (newline < 0 && pending.text.length <= 500) break;
        const hasNewline = end === newline;
        // 分段边界不能切断 UTF-16 代理对，否则中文或 emoji 会损坏。
        if (!hasNewline && /[\uD800-\uDBFF]/.test(pending.text[end - 1])) end--;
        emitText(kind, pending.text.slice(0, end));
        pending.text = pending.text.slice(end + (hasNewline ? 1 : 0));
      }
      return;
    }
    flush();
    if (!options.printThinking) return;
    if (type === "tool_call") {
      const rawInput = asRecord(event.rawInput);
      const server = typeof rawInput?.server === "string" ? rawInput.server : undefined;
      const tool = typeof rawInput?.tool === "string" ? rawInput.tool : undefined;
      const title = typeof event.title === "string" ? compact(event.title, 180) : "tool";
      const label = server && tool ? `${server}.${tool}` : title;
      const toolCallId = typeof event.toolCallId === "string" ? event.toolCallId : undefined;
      if (toolCallId)
        toolStates.set(toolCallId, {
          label,
          status: typeof event.status === "string" ? event.status : undefined,
          error: "",
        });
      log(`[acp][${actorId}][tool] start ${label} · ${textLabel("runtime.acp.start")}`, "muted");
      return;
    }
    if (type === "tool_call_update") {
      const toolCallId = typeof event.toolCallId === "string" ? event.toolCallId : undefined;
      const previous = toolCallId ? toolStates.get(toolCallId) : undefined;
      const label =
        typeof event.title === "string" ? compact(event.title, 180) : (previous?.label ?? "tool");
      const status = typeof event.status === "string" ? event.status : undefined;
      const error =
        event.error === undefined || event.error === null || event.error === ""
          ? ""
          : formatErrorDiagnostic(event.error, locale);
      // 部分更新可只补充输入或内容；保留其显示元数据，仅在状态改变或出现新错误时打印。
      const changed =
        (status !== undefined && status !== previous?.status) ||
        (error !== "" && error !== previous?.error);
      if (toolCallId)
        toolStates.set(toolCallId, {
          label,
          status: status ?? previous?.status,
          error: error || previous?.error || "",
        });
      if (!changed) return;
      const displayStatus = status ?? previous?.status ?? "error";
      const statusKey = `runtime.acp.${displayStatus}` as MessageKey;
      const explanation = Object.hasOwn(dictionaries[locale], statusKey)
        ? textLabel(statusKey)
        : displayStatus;
      log(
        `[acp][${actorId}][tool] ${displayStatus} ${label} · ${explanation}${error ? ` error=${error}` : ""}`,
        error || status === "failed" ? "warn" : "muted",
      );
    }
  };
  return Object.assign(observer, {
    flush: () => {
      flush();
      toolStates.clear();
    },
  });
}

/**
 * 负责把新增领域事件与当时获授权的玩家视图交给会话记录器，返回完成处理的展示增量。
 * 输入为本局原 World 和事件序列；输出为 God／玩家记录，最终落盘归会话记录器。
 * 本模块拥有事件游标、记录日期／阶段和玩家局部序号，不推进游戏阶段或选择行动。
 * 记录失败向调用方传播并保留已追加前缀；领域提交与受众授权仍由各自所有者负责。
 * 游标不是跨失败重放的事务保证，不能把一次中途异常当成整条事件从未记录。
 */
import type { World } from "../core/domain/world";
import type { GameEvent } from "@ai-werewolf-arena/game-contract/events";
import { COMPONENT, RoleComponent } from "../core";
import { buildAgentVisibleEvent } from "../game/engine/agent_visible_event_feed";
import { getDefaultScriptEventRenderRegistry } from "../game";
import type { SessionRecordManager } from "../recording/session_recorder";

/** 持有同一局的领域读取入口与记录入口，不创建第二份状态或自行管理记录器关闭。 */
export interface GameEventRecorderOptions {
  world: World;
  replayManager: SessionRecordManager;
}

export class GameEventRecorder {
  private recordedEventIndex = 0;
  // 每位玩家只为可见事件递增序号，不能用 God 事件索引泄漏隐藏行动数量。
  private readonly playerVisibleEventSeq = new Map<number, number>();
  // 这是复盘记录的标签游标；只随 phase_changed 更新，不写回领域阶段。
  private replayDayCursor = 1;
  private replayPhaseCursor: string;

  constructor(
    private readonly options: GameEventRecorderOptions,
    initialPhase: string,
  ) {
    this.replayPhaseCursor = initialPhase;
  }

  /** 从事件游标处理新增事实；只有当前事件全部处理完成后才推进该游标。 */
  flush(events: readonly GameEvent[]): GameEvent[] {
    const delta: GameEvent[] = [];
    const stageRegistry = getDefaultScriptEventRenderRegistry();
    for (let i = this.recordedEventIndex; i < events.length; i += 1) {
      const event = events[i];
      const stage = stageRegistry.toReplayStage(event);
      if (event.type === "phase_changed") {
        this.replayDayCursor = Number(event.payload.day ?? this.replayDayCursor);
        this.replayPhaseCursor = String(event.payload.phase ?? this.replayPhaseCursor);
      }
      // God 记录先追加，随后逐玩家投影；后续失败不撤销先前已追加的记录。
      this.options.replayManager.recordPublicEvent({
        type: event.type,
        timestampMs: event.timestamp,
        day: this.replayDayCursor,
        phase: this.replayPhaseCursor,
        stage,
        payload: { ...event.payload },
      });
      for (const playerId of this.options.world.entityIds()) {
        const nextVisibleSeq = (this.playerVisibleEventSeq.get(playerId) ?? 0) + 1;
        const visibleEvent = buildAgentVisibleEvent(
          this.options.world,
          event,
          playerId,
          nextVisibleSeq,
        );
        if (!visibleEvent) continue;
        // 按原顺序先占用局部序号再追加玩家记录；写入抛错时序号与前缀不会回滚。
        this.playerVisibleEventSeq.set(playerId, nextVisibleSeq);
        const roleComp = this.options.world.getComponent(playerId, COMPONENT.Role);
        this.options.replayManager.recordPlayerEvent({
          playerId,
          role: roleComp?.role ?? "unknown",
          camp: (roleComp && this.options.world.getComponent(playerId, COMPONENT.Camp)?.camp) ?? "unknown",
          day: this.replayDayCursor,
          phase: this.replayPhaseCursor,
          stage: visibleEvent.type === "player_shot" ? "death_shot" : stage,
          requestId: `${this.replayDayCursor}-${this.replayPhaseCursor}-${playerId}-event-${nextVisibleSeq}`,
          timestampMs: event.timestamp,
          // 玩家来源序号属于自己的视图；全局索引会暴露隐藏 God 事件的数量。
          sourceEventSeq: nextVisibleSeq,
          event: visibleEvent,
        });
      }
      // 全部玩家视图处理完才推进主游标；中途失败不伪造原子提交或自动去重。
      this.recordedEventIndex = i + 1;
      delta.push(event);
    }
    return delta;
  }
}

/**
 * 负责装配一局游戏、收缩绝对期限、关闭运行资源并汇总失败。
 * 输入为已解析的对局设置与本次执行依赖；输出为记录结果和可选审计摘要。
 * 请求别名与原体权限仍由机制所有者校验；本模块保留停止、关闭、等待与落盘的顺序，
 * 后续失败不回滚已提交的动作，也不把可选摘要失败升级为对局失败。
 * Agent 与复现记录共用本局板子来源；maxDays 在原元数据读取处捕获，循环复用该值。
 */
import { deriveBoundedRequest } from "../core/domain/request_delivery";
import {
  animalOriginalAuditIds,
  animalOriginalAuditPlayer,
} from "../game/mechanisms/roles/animal_dream/roster";
import { aliveLifeDescriptor } from "../core/domain/components/alive";
import { initialPlayerIdentity } from "../core/domain/initial_roster";
import { initialIdentityDeal } from "../game/mechanisms/roles/initial_identity/deal";
import { text } from "@ai-werewolf-arena/game-text";
import { formatErrorDiagnostic } from "../utils/error_diagnostic";
/** 本局资源、期限、失败汇总与最终复盘由下方 runner 持有；导入不装配对局。 */
import path from "node:path";
import { bootstrapGame } from "../app/bootstrap";
import {
  COMPONENT,
  type ActionProvider,
  type ActionRequest,
  type AliveComponent,
  type RoleComponent,
  type RuntimeSnapshot,
  type ToolCall,
  type World,
  type IdentityComponent,
  createRandom,
} from "../core";
import type { ResolvedAgentRuntimeProfile } from "./config/contracts";
import type { ResolvedGameSetup } from "./config/resolve_game_setup";
import { resolvePlayerProfile } from "./config/resolve_game_setup";
import {
  createAcpConsoleLogger,
  createConsoleLog,
  presentGameResult,
  presentStreamEvents,
} from "./console_presenter";
import { GameEventRecorder } from "./game_event_recorder";
import {
  buildSessionId,
  resolveDefaultRecordRoot,
  SessionRecordManager,
} from "../recording/session_recorder";
import { runWithSessionRecorder } from "../recording/recording_context";
import { buildDebugSummaryMarkdown } from "../audit/debug_summary_generator";
