  currentEngineVersion,
} from "./simulation/reproduction_context";

/** 仅返回最终运行快照与领域事件总数；完整回放由会话记录器持久化。 */
export interface GameRunResult {
  snapshot: RuntimeSnapshot;
  eventCount: number;
}
/**
 * 每局独立的执行依赖，不进入玩家 DTO 或 JSON 配置。
 * 期限选择回调返回绝对时间，只参与取最小值；关闭观察回调接收脱离副本，异常归清理失败。
 */
export interface GameRunDependencies {
  selectRequestDeadline?: (
    request: Readonly<{
      actorId: number;
      day: number;
      stage: ActionRequest["context"]["stage"];
      ordinal: number;
      actorOrdinal: number;
      retryAttempt: number;
      nowMs: number;
    }>,
  ) => number | undefined;
  onRuntimeClosed?: (state: PlayerAgentRuntime["runtimeState"]) => void;
}

class DeadlineAwareActionProvider implements ActionProvider {
  private ordinal = 0;
  private readonly actors = new Map<number, number>();
  // 同一玩家／日期／stage 的重试沿用已记录预算；新尝试仍受全局与原请求期限限制。
  private readonly budgets = new Map<string, number>();
  constructor(
    private readonly delegate: ActionProvider,
    private readonly deadlineAtMs: number,
    private readonly timeoutMs: number,
    private readonly selectDeadline?: GameRunDependencies["selectRequestDeadline"],
  ) {}

  getAction(request: ActionRequest): Promise<ToolCall | null> {
    const nowMs = Date.now(),
      actorOrdinal = (this.actors.get(request.actorId) ?? 0) + 1;
    this.actors.set(request.actorId, actorOrdinal);
    const ordinal = ++this.ordinal;
    const retryAttempt = request.context.retry_attempt ?? 0;
    const selected = this.selectDeadline?.({
      actorId: request.actorId,
      day: request.context.day,
      stage: request.context.stage,
      ordinal,
      actorOrdinal,
      retryAttempt,
      nowMs,
    });
    if (selected !== undefined && !Number.isFinite(selected))
      throw new RangeError("game_request_deadline_invalid");
    const key = `${request.actorId}/${request.context.day}/${request.context.stage}`;
    // 期限只取最早绝对时间，重试不重置整份超时；运行时授权随原请求一起派生。
    const deadline = Math.min(
      this.deadlineAtMs,
      request.deadlineAtMs ?? Infinity,
      nowMs + this.timeoutMs,
      selected ?? Infinity,
      retryAttempt > 0 ? (this.budgets.get(key) ?? Infinity) : Infinity,
    );
    this.budgets.set(key, deadline);
    const timed = deriveBoundedRequest(request, deadline);
    return this.delegate.getAction(timed);
  }
}

/** 调用方先完成设置解析；这里装配并执行对局，不读取配置来源文件。 */
export async function runGame(
  setup: ResolvedGameSetup,
  dependencies: GameRunDependencies = {},
): Promise<GameRunResult> {
  const context = bootstrapGame(setup.boardConfig, {
    random: createRandom(setup.context.seed),
    locale: setup.context.locale,
    playerNames: Object.fromEntries(
      Object.entries(setup.players).flatMap(([seat, entry]) =>
        entry.name !== undefined ? [[seat, entry.name]] : [],
      ),
    ),
  });
  const profilesByActor = selectPlayerProfiles(context.world, setup);
  const sessionId = buildSessionId();
  const recordRoot = setup.options.recordRootDir ?? resolveDefaultRecordRoot();
  const replayManager = await SessionRecordManager.create(
    {
      sessionId,
      locale: setup.context.locale,
      board: setup.options.board,
      startedAtIso: new Date().toISOString(),
      random: context.random.metadata,
    },
    recordRoot,
    setup.context.displayLocale,
  );

  return runWithSessionRecorder(replayManager, async () => {
    const { options } = setup;
    const log = createConsoleLog(options.color);
    const startedAt = Date.now();
    const deadlineAtMs = startedAt + options.maxRuntimeMs;
    // 对局／记录失败统一汇总；并发动作和关闭失败暂存，收尾时按原顺序补入。
    const failures: unknown[] = [];
    const eventRecorder = new GameEventRecorder(
      {
        world: context.world,
        replayManager,
      },
      context.phaseManager.getSnapshot().phase,
    );
    const flushEvents = () => {
      const delta = eventRecorder.flush(context.phaseManager.getEvents());
      if (options.streamEvents)
        presentStreamEvents(delta, options.printPrivateEvents, log, setup.context.displayLocale);
    };
    let agentRuntime: PlayerAgentRuntime | undefined;
    let heartbeat: NodeJS.Timeout | undefined;
    let streamTimer: NodeJS.Timeout | undefined;
    let timedOut = false;
    // stopping 立即拒绝新动作和迟到回复；closing 合并关闭调用，inFlight 单独负责等待结算。
    let stopping = false;
    let closing: Promise<void> | undefined;
    const stopReason = new DOMException("game_actions_stopped", "AbortError");
    const inFlight = new Set<Promise<ToolCall | null>>();
    const actionFailures: unknown[] = [];
    const cleanupFailures: unknown[] = [];
    let maxDays: number;
    // 先撤运行入口，再异步关闭 Agent；关闭异常暂存，不能覆盖触发停止的原始失败。
    const closeRuntime = (): Promise<void> => {
      stopping = true;
      closing ??= Promise.resolve()
        .then(() => agentRuntime?.close())
        .catch((error) => {
          cleanupFailures.push(error);
        });
      return closing;
    };
    const drainActions = async () => {
      while (inFlight.size) await Promise.allSettled([...inFlight]);
    };

    try {
      const reproduction = beginGameReproduction(replayManager, context, {
        engine: await currentEngineVersion(),
        boardId: options.board,
        locale: context.world.locale,
        maxDays: (maxDays = options.maxDays),
        profiles: profilesByActor,
      });
      agentRuntime = await createPlayerAgentRuntime({
        world: context.world,
        boardConfig: context.boardConfig,
        profilesByActor,
        acpWorkspaceRoot: path.join(recordRoot, sessionId, "acp-workspaces"),
        llmTimeoutMs: options.llmTimeoutMs,
        trace: options.trace,
        displayLocale: setup.context.displayLocale,
        colorizeLogs: options.color,
        printLlmIo: options.printLlmIo,
        printThinking: options.printThinking,
        createAcpUpdateObserver:
          options.printThinking || options.printLlmIo
            ? (actorId) =>
                createAcpConsoleLogger(actorId, log, setup.context.displayLocale, {
                  printThinking: options.printThinking,
                  printLlmIo: options.printLlmIo,
                })
            : undefined,
      });
      const selectedProvider: ActionProvider = {
        async getAction(request) {
          if (stopping) throw stopReason;
          const action = await agentRuntime!.provider.getAction(request);
          if (stopping) throw stopReason;
          return action;
        },
      };
      const decisionProvider: ActionProvider = {
        getAction: (request) => {
          const decision = reproduction.decide(request, selectedProvider);
          let tracked!: Promise<ToolCall | null>;
          tracked = decision.then(
            (action) => {
              inFlight.delete(tracked);
              return action;
            },
            (error) => {
              inFlight.delete(tracked);
              if (error !== stopReason) actionFailures.push(error);
              // 保留记录器已写的决策前缀，再开始取消其它动作，保留原异常的因果先后。
              void closeRuntime();
              throw error;
            },
          );
          inFlight.add(tracked);
          return tracked;
        },
      };
      const provider = new DeadlineAwareActionProvider(
        decisionProvider,
        deadlineAtMs,
        options.llmTimeoutMs,
        dependencies.selectRequestDeadline,
      );
      log(
        `[run_game] start board=${options.board} replay_session_id=${sessionId} record_dir=${replayManager.sessionDir} · ${text(setup.context.displayLocale, "runtime.start")}`,
        "info",
      );

      if (options.trace) {
        heartbeat = setInterval(() => {
          const snapshot = context.phaseManager.getSnapshot();
          log(
            `[run_game] heartbeat day=${snapshot.day} phase=${snapshot.phase} gameOver=${snapshot.gameOver} elapsed_ms=${Date.now() - startedAt} · ${text(setup.context.displayLocale, "runtime.heartbeat")}`,
            "muted",
          );
        }, 5000);
      }
      streamTimer = setInterval(() => {
        try {
          flushEvents();
        } catch (error) {
          failures.push(error);
          replayManager.noteReproductionFailure("recording", error);
          void closeRuntime();
          if (streamTimer) clearInterval(streamTimer);
        }
      }, 1000);

      let cycle = 0;
      while (!context.phaseManager.getSnapshot().gameOver && failures.length === 0) {
        const elapsed = Date.now() - startedAt;
        if (elapsed >= options.maxRuntimeMs) {
          timedOut = true;
          log(
            `[run_game] runtime_timeout elapsed_ms=${elapsed} · ${text(setup.context.displayLocale, "runtime.timeout")}`,
            "warn",
          );
          break;
        }
        cycle++;
        let complete = false;
        let cycleFailure: unknown;
        try {
          await context.phaseManager.runSingleCycle(provider, maxDays);
          complete = true;
        } catch (error) {
          cycleFailure = error;
          if (error !== stopReason) failures.push(error);
          replayManager.noteReproductionFailure("cycle", error);
          await closeRuntime();
          await drainActions();
        }
        // 无论周期成功或失败都保存实际结算前缀；失败周期先关闭并等待已在途动作。
        try {
          reproduction.checkpoint(
            captureCheckpoint(
              context.world,
              context.phaseManager.getSnapshot(),
              cycle,
              complete,
              context.phaseManager.getEvents().length,
              cycleFailure,
            ),
            context.phaseManager.getEvents(),
          );
        } catch (error) {
          failures.push(error);
          reproduction.invalidate();
          replayManager.noteReproductionFailure("recording", error);
        }
        if (failures.length) break;
        const snapshot = context.phaseManager.getSnapshot();
        log(
          `[run_game] cycle day=${snapshot.day} phase=${snapshot.phase} gameOver=${snapshot.gameOver} elapsed_ms=${Date.now() - startedAt} · ${text(setup.context.displayLocale, "runtime.cycle")}`,
          "info",
        );
      }
    } catch (error) {
      failures.push(error);
      replayManager.noteReproductionFailure("initialization", error);
    } finally {
      // 先停定时任务并补事件，再关闭／等待动作；最终记录只在这些原收尾步骤之后发布。
      if (heartbeat) clearInterval(heartbeat);
      if (streamTimer) clearInterval(streamTimer);
      try {
        flushEvents();
      } catch (error) {
        failures.push(error);
        replayManager.noteReproductionFailure("recording", error);
      }
      await closeRuntime();
      await drainActions();
      if (agentRuntime && dependencies.onRuntimeClosed) {
        try {
          dependencies.onRuntimeClosed(structuredClone(agentRuntime.runtimeState));
        } catch (error) {
          cleanupFailures.push(error);
        }
      }
      // 取消标记不列为独立动作错误；原异常按引用去重，清理失败仍按发生顺序追加。
      for (const error of actionFailures)
        if (!failures.includes(error)) {
          failures.push(error);
          replayManager.noteReproductionFailure("controller", error);
        }
      for (const error of cleanupFailures) {
        failures.push(error);
        replayManager.noteReproductionFailure("cleanup", error);
      }
      try {
        const snapshot = context.phaseManager.getSnapshot();
        const summaryInput = await replayManager.finalize({
          endedAtIso: new Date().toISOString(),
          winner: snapshot.result?.winner ?? null,
          ...(snapshot.result ? { gameResult: snapshot.result } : {}),
          finishReason: failures.length
            ? "runtime_error"
            : (snapshot.result?.reason ?? (timedOut ? "runtime_timeout" : "completed")),
          players: replayPlayers(context.world),
        });
        // 核心终档失败进入汇总；诊断摘要为可选输出，其异常只写日志。
        try {
          await replayManager.writeDebugSummary(
            await buildDebugSummaryMarkdown(
              {
                ...summaryInput,
                locale: setup.context.locale,
                displayLocale: setup.context.displayLocale,
              },
              setup.audit,
            ),
          );
        } catch (error) {
          log(
            `[audit] debug_summary_failed err=${formatErrorDiagnostic(error, setup.context.displayLocale)}`,
            "warn",
          );
        }
      } catch (error) {
        failures.push(error);
      }
    }

    if (failures.length === 1) throw failures[0];
    if (failures.length > 1) throw new AggregateError(failures, "game_run_failed");
    const snapshot = context.phaseManager.getSnapshot();
    const events = context.phaseManager.getEvents();
    presentGameResult({
      locale: setup.context.displayLocale,
      board: options.board,
      snapshot,
      events,
      timedOut,
      printAllEvents: options.printAllEvents,
      printChat: options.printChat,
      streamEvents: options.streamEvents,
      log,
    });
    return { snapshot, eventCount: events.length };
  });
}

function selectPlayerProfiles(
  world: World,
  setup: ResolvedGameSetup,
): Map<number, ResolvedAgentRuntimeProfile> {
  const profiles = new Map<number, ResolvedAgentRuntimeProfile>();
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role)?.role;
    profiles.set(id, resolvePlayerProfile(setup, id, role));
  }
  return profiles;
}

/**
 * 构造 God 终档的身份记录，不复用玩家观察视图。
 * 动物梦境读取已捕获的原名单／身份与原生命；初始身份机制保留原发牌，普通局使用当前组件。
 */
function replayPlayers(world: World) {
  const originalIds = animalOriginalAuditIds(world);
  if (originalIds)
    return originalIds.map((id) => {
      const original = animalOriginalAuditPlayer(world, id)!,
        identity = JSON.parse(original.identityJson);
      return {
        player_id: id,
        role: original.scope.roleId,
        camp: original.scope.campValue,
        alive: aliveLifeDescriptor(original.scope.life)!.get!.call(original.scope.life),
        name: identity.name,
      };
    });
  // 原名单／开局牌组是历史数据；仅普通fallback在原字段位置查询当前Camp。
  const initial = initialIdentityDeal(world);
  return world.entityIds().map((id, index) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return {
      player_id: id,
      role: initialPlayerIdentity(world, id)?.role ?? initial?.[index] ?? role?.role ?? "unknown",
      camp:
        initialPlayerIdentity(world, id)?.camp ??
        (initial ? (initial[index] === "wolf" ? "wolf" : "good") : ((role && world.getComponent(id, COMPONENT.Camp)?.camp) ?? "unknown")),
      alive: world.getComponent(id, COMPONENT.Alive)?.alive === true,
      name: world.getComponent(id, COMPONENT.Identity)?.name,
    };
  });
}

/**
 * 负责按席位解析的 profile 与只读规则装配 LLM／ACP 玩家运行时。输入为原 World、板子视图及传输选项；输出为 provider、资源状态和原关闭操作。生产装配使用共同观察回退，不注入特权 Baseline；会话与进程由各 owner 关闭，本工厂不写规则、库存或游戏阶段。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { Locale } from "@ai-werewolf-arena/game-text";
import { promises as fs } from "node:fs";
import * as path from "node:path";
import { isDeepStrictEqual } from "node:util";
import { World } from "../core/domain/world";
import { ActionProvider } from "../core/domain/model";
import { AcpActionProvider, AcpProcessClient, LlmActionProvider } from "../ai";
import { AiSdkClient } from "../ai/integrations/llm/ai_sdk_client";
import type { ResolvedAgentRuntimeProfile } from "./config/contracts";

export interface PlayerAgentRuntime {
  kind: "llm" | "acp" | "mixed";
  provider: ActionProvider;
  close(): Promise<void>;
  readonly runtimeState: {
    closed: boolean;
    sdk?: LlmActionProvider["runtimeState"];
    acp?: AcpActionProvider["runtimeState"][];
  };
}

export interface PlayerAgentFactoryOptions {
  world: World;
  boardConfig: ReadonlyBoardConfig;
  profilesByActor: ReadonlyMap<number, ResolvedAgentRuntimeProfile>;
  acpWorkspaceRoot: string;
  llmTimeoutMs: number;
  trace: boolean;
  displayLocale?: Locale;
  colorizeLogs: boolean;
  printLlmIo: boolean;
  printThinking: boolean;
  createAcpUpdateObserver?: (actorId: number) => AcpUpdateObserver | undefined;
}

interface AcpUpdateObserver {
  (update: unknown): void;
  flush?(): void;
}

/** 根据统一 profile 创建玩家运行时；调用方无需感知 SDK/ACP 构造细节。 */
export async function createPlayerAgentRuntime(
  options: PlayerAgentFactoryOptions,
): Promise<PlayerAgentRuntime> {
  const profiles = new Map(
    [...options.profilesByActor].map(([actor, profile]) => [actor, structuredClone(profile)]),
  );
  if (!profiles.size) throw new Error("runtime_config_player_profiles_empty");
  const providerBindings = new Map<string, ResolvedAgentRuntimeProfile["provider"]>();
  for (const profile of profiles.values()) {
    const previous = providerBindings.get(profile.providerName);
    if (previous && !isDeepStrictEqual(previous, profile.provider))
      throw new Error("runtime_config_provider_binding_inconsistent");
    providerBindings.set(profile.providerName, profile.provider);
  }
  const sdkProfiles = new Map([...profiles].filter(([, profile]) => profile.kind === "llm"));
  const acpProfiles = new Map([...profiles].filter(([, profile]) => profile.kind === "acp"));
  const owned: PlayerAgentRuntime[] = [];
  let sdk: PlayerAgentRuntime | undefined, acp: PlayerAgentRuntime | undefined;
  try {
    if (sdkProfiles.size) {
      sdk = createLlmRuntime({ ...options, profilesByActor: sdkProfiles });
      owned.push(sdk);
    }
    if (acpProfiles.size) {
      acp = await createAcpRuntime({ ...options, profilesByActor: acpProfiles });
      owned.push(acp);
    }
  } catch (error) {
    const cleanup = await Promise.allSettled(owned.map((runtime) => runtime.close()));
    const failures = cleanup.flatMap((result) =>
      result.status === "rejected" ? [result.reason] : [],
    );
    if (failures.length)
      throw new AggregateError([error, ...failures], "player_runtime_initialization_failed");
    throw error;
  }
  let closed = false;
  return {
    kind: sdk && acp ? "mixed" : acp ? "acp" : "llm",
    provider: {
      getAction(request) {
        if (closed) return Promise.reject(new DOMException("player_runtime_closed", "AbortError"));
        const profile = profiles.get(request.actorId);
        const runtime = profile?.kind === "llm" ? sdk : profile?.kind === "acp" ? acp : undefined;
        if (!runtime)
          return Promise.reject(
            new Error(`runtime_config_agent_profile_missing_for_actor:${request.actorId}`),
          );
        return runtime.provider.getAction(request);
      },
    },
    get runtimeState() {
      return {
        closed,
        ...(sdk ? { sdk: sdk.runtimeState.sdk } : {}),
        ...(acp ? { acp: acp.runtimeState.acp } : {}),
      };
    },
    async close() {
      closed = true;
      const settled = await Promise.allSettled(owned.map((runtime) => runtime.close()));
      const failures = settled.flatMap((result) =>
        result.status === "rejected" ? [result.reason] : [],
      );
      if (failures.length) throw new AggregateError(failures, "player_runtime_close_failed");
    },
  };
}

async function createAcpRuntime(options: PlayerAgentFactoryOptions): Promise<PlayerAgentRuntime> {
  await fs.mkdir(options.acpWorkspaceRoot, { recursive: true });
  const observers = new Map<number, AcpUpdateObserver | undefined>();
  const providers = new Map<string, AcpActionProvider>();
  const groups = new Map<string, Map<number, ResolvedAgentRuntimeProfile>>();
  for (const [actor, profile] of options.profilesByActor) {
    if (profile.kind !== "acp" || profile.provider.type !== "acp")
      throw new Error(`runtime_config_acp_profile_missing_for_actor:${actor}`);
    const group =
      groups.get(profile.providerName) ?? new Map<number, ResolvedAgentRuntimeProfile>();
    group.set(actor, profile);
    groups.set(profile.providerName, group);
  }
  for (const [name, profiles] of groups) {
    const first = profiles.values().next().value!;
    const provider = new AcpActionProvider(options.world, {
      maxConcurrentRequests: first.provider.maxConcurrentRequests,
      sessionFactoryResolver: (actorId) => {
        const profile = profiles.get(actorId);
        if (!profile || profile.provider.type !== "acp")
          throw new Error(`runtime_config_acp_profile_missing_for_actor:${actorId}`);
        if (!observers.has(actorId))
          observers.set(actorId, options.createAcpUpdateObserver?.(actorId));
        return new AcpProcessClient({
          command: profile.provider.command,
          args: [...(profile.provider.args ?? []), ...(profile.spawnArgs ?? [])],
          env: profile.provider.env,
          sessionConfigOptions: profile.provider.sessionConfigOptions,
          initializeTimeoutMs: profile.provider.initializeTimeoutMs,
          cwd: profile.provider.cwd ?? path.join(options.acpWorkspaceRoot, `player-${actorId}`),
          onUpdate: ({ update }) => observers.get(actorId)?.(update),
          onPromptEnd: (actor) => observers.get(actor)?.flush?.(),
        });
      },
      personalityPromptResolver: (request) => profiles.get(request.actorId)?.personalityPrompt,
      boardConfig: options.boardConfig,
      turnTimeoutMs: options.llmTimeoutMs,
      trace: options.trace,
      displayLocale: options.displayLocale,
      colorizeLogs: options.colorizeLogs,
      printLlmIo: options.printLlmIo,
      printThinking: options.printThinking,
    });
    providers.set(name, provider);
  }
  let closed = false;
  return {
    kind: "acp",
    provider: {
      getAction(request) {
        if (closed) return Promise.reject(new DOMException("player_runtime_closed", "AbortError"));
        const profile = options.profilesByActor.get(request.actorId),
          provider = profile && providers.get(profile.providerName);
        if (!provider)
          return Promise.reject(
            new Error(`runtime_config_acp_profile_missing_for_actor:${request.actorId}`),
          );
        return provider.getAction(request);
      },
    },
    get runtimeState() {
      return { closed, acp: [...providers.values()].map((provider) => provider.runtimeState) };
    },
    async close() {
      closed = true;
      const settled = await Promise.allSettled(
        [...providers.values()].map((provider) => provider.close()),
      );
      const failures = settled.flatMap((result) =>
        result.status === "rejected" ? [result.reason] : [],
      );
      for (const observer of observers.values())
        try {
          observer?.flush?.();
        } catch (error) {
          failures.push(error);
        }
      if (failures.length) throw new AggregateError(failures, "acp_runtime_close_failed");
    },
  };
}

function createLlmRuntime(options: PlayerAgentFactoryOptions): PlayerAgentRuntime {
  const clientByActor = new Map<number, AiSdkClient>();
  for (const [actorId, profile] of options.profilesByActor) {
    if (profile.kind !== "llm" || profile.provider.type === "acp" || !profile.model) {
      throw new Error(`runtime_config_llm_profile_missing_for_actor:${actorId}`);
    }
    clientByActor.set(
      actorId,
      new AiSdkClient({
        providerType: profile.provider.type,
        providerName: profile.providerName,
        baseURL: profile.provider.baseURL,
        apiKey: profile.provider.apiKey,
        model: profile.model,
        userAgent: profile.provider.userAgent,
        temperature:
          profile.temperature ??
          (profile.reasoningEffort || profile.thinkingEnabled ? undefined : 0.2),
        maxTokens: profile.maxTokens ?? 512,
        reasoningEffort: profile.reasoningEffort,
        thinkingEnabled: profile.thinkingEnabled ?? false,
      }),
    );
  }
  const firstClient = clientByActor.values().next().value as AiSdkClient | undefined;
  if (!firstClient) throw new Error("runtime_config_llm_clients_empty");
  const profileFor = (actorId: number): ResolvedAgentRuntimeProfile => {
    const profile = options.profilesByActor.get(actorId);
    if (!profile) throw new Error(`runtime_config_agent_profile_missing_for_actor:${actorId}`);
    return profile;
  };
  const provider = LlmActionProvider.fromModelClient(options.world, firstClient, {
    clientResolver: (request) => {
      const client = clientByActor.get(request.actorId);
      if (!client)
        throw new Error(`runtime_config_llm_profile_missing_for_actor:${request.actorId}`);
      return client;
    },
    requestConcurrencyScopeResolver: (request) => profileFor(request.actorId).providerName,
    maxConcurrentRequestsResolver: (request) => {
      const profile = profileFor(request.actorId);
      return profile.provider.type === "acp" ? undefined : profile.provider.maxConcurrentRequests;
    },
    personalityPromptResolver: (request) => profileFor(request.actorId).personalityPrompt,
    trace: options.trace,
    displayLocale: options.displayLocale,
    maxPromptEvents: 20,
    llmTimeoutMs: options.llmTimeoutMs,
    colorizeLogs: options.colorizeLogs,
    printLlmIo: options.printLlmIo,
    printThinking: options.printThinking,
    boardConfig: options.boardConfig,
  });
  return {
    kind: "llm",
    provider,
    close: () => provider.close(),
    get runtimeState() {
      return { closed: provider.runtimeState.closed, sdk: provider.runtimeState };
    },
  };
}

/**
 * 负责两个旧内置板子的覆盖层解析与规范化。输入为旧平铺／结构化数据和板子标识，输出覆盖层或合并后的 BoardConfig。
 * 先按原分支校验，保 default 与板子层优先级；只显式复制已列数组／对象，不作为任意深克隆或版本化板子文件加载器。
 */
import { z } from "zod";
import {
  ActionWindow,
  BoardConfig,
  HookConfig,
  Role,
  WinCondition,
  WitchSelfHealRule,
} from "../../core/domain/model";
import { getDefaultConfigNormalizerRegistry } from "../../game/mechanisms";
import { sixPlayerMvpConfig } from "./six_player_mvp";
import { twelvePlayerStandardConfig } from "./twelve_player_standard";

/** 仅此旧兼容解析器的两个标识，不是全部可配置角色／版本化板子的支持目录。 */
export type BoardName = "six_player_mvp" | "twelve_player_standard";
type JsonObject = Record<string, unknown>;
export type BoardOverride = Omit<
  Partial<BoardConfig>,
  "hooks" | "sheriff" | "witch" | "tieBreaker" | "selfDestruct"
> & {
  hooks?: Partial<HookConfig>;
  sheriff?: NonNullable<BoardConfig["sheriff"]>;
  witch?: NonNullable<BoardConfig["witch"]>;
  tieBreaker?: NonNullable<BoardConfig["tieBreaker"]>;
  selfDestruct?: NonNullable<BoardConfig["selfDestruct"]>;
};

/** 旧结构化输入的分区数据；通过 schema 后映射到同一 BoardOverride，不授予执行许可。 */
type StructuredBoardConfig = {
  board?: {
    size?: number;
    roleSetups?: unknown;
  };
  rules?: {
    winCondition?: unknown;
    winConditions?: unknown;
    hooks?: Partial<HookConfig>;
  };
  mechanisms?: {
    sheriff?: {
      enabled?: boolean;
      initialSeat?: number;
      voteWeight?: number;
      tieBreaker?: unknown;
    };
    selfDestruct?: {
      enabledWindows?: unknown;
    };
    tieBreaker?: {
      exileVote?: unknown;
      wolfKillVote?: unknown;
    };
  };
  roles?: {
    witch?: {
      selfHeal?: unknown;
    };
  };
};

const tieBreaker = z.enum(["min_id", "min_seat", "no_elimination", "no_kill"]);
const hooks = z.strictObject({
  onDaybreak: z.boolean().optional(),
  onPreElection: z.boolean().optional(),
  onPreVote: z.boolean().optional(),
  onPerSpeechGap: z.boolean().optional(),
});
const flatOverride = z.strictObject({
  boardSize: z.number().int().positive().optional(),
  enableSheriff: z.boolean().optional(),
  initialSheriffSeat: z.number().int().positive().optional(),
  winCondition: z.enum(WinCondition).optional(),
  winConditions: z.array(z.enum(WinCondition)).optional(),
  hooks: hooks.optional(),
  selfDestruct: z.strictObject({ enabledWindows: z.array(z.enum(ActionWindow)) }).optional(),
  sheriff: z.strictObject({ voteWeight: z.number().positive().optional() }).optional(),
  witch: z.strictObject({ canSelfHeal: z.enum(WitchSelfHealRule).optional() }).optional(),
  tieBreaker: z
    .strictObject({
      exileVote: tieBreaker.optional(),
      wolfKillVote: tieBreaker.optional(),
      sheriffVote: tieBreaker.optional(),
    })
    .optional(),
  roleSetups: z
    .array(z.strictObject({ role: z.enum(Role), count: z.number().int().nonnegative() }))
    .optional(),
});
const structuredOverride = z.strictObject({
  board: z
    .strictObject({
      size: z.number().int().positive().optional(),
      roleSetups: flatOverride.shape.roleSetups,
    })
    .optional(),
  rules: z
    .strictObject({
      winCondition: flatOverride.shape.winCondition,
      winConditions: flatOverride.shape.winConditions,
      hooks: hooks.optional(),
    })
    .optional(),
  mechanisms: z
    .strictObject({
      sheriff: z
        .strictObject({
          enabled: z.boolean().optional(),
          initialSeat: z.number().int().positive().optional(),
          voteWeight: z.number().positive().optional(),
          tieBreaker: tieBreaker.optional(),
        })
        .optional(),
      selfDestruct: z
        .strictObject({ enabledWindows: z.array(z.enum(ActionWindow)).optional() })
        .optional(),
      tieBreaker: z
        .strictObject({ exileVote: tieBreaker.optional(), wolfKillVote: tieBreaker.optional() })
        .optional(),
    })
    .optional(),
  roles: z
    .strictObject({
      witch: z.strictObject({ selfHeal: z.enum(WitchSelfHealRule).optional() }).optional(),
    })
    .optional(),
});

function validateOverride(schema: z.ZodType, value: unknown): void {
  const result = schema.safeParse(value);
  if (!result.success) {
    const field = result.error.issues[0]?.path.join(".") || "document";
    throw new Error(`board_config_invalid_override_field: ${field}`);
  }
}

function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** 为旧基础板子复制下列可合并容器；未列字段仍按原 spread 引用保留，不承诺通用深克隆。 */
function cloneBoardConfig(config: BoardConfig): BoardConfig {
  return {
    ...config,
    roleSetups: config.roleSetups.map((item) => ({ ...item })),
    hooks: { ...config.hooks },
    ...(config.winConditions ? { winConditions: [...config.winConditions] } : {}),
    ...(config.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...config.selfDestruct.enabledWindows],
          },
        }
      : {}),
    ...(config.sheriff ? { sheriff: { ...config.sheriff } } : {}),
    ...(config.witch ? { witch: { ...config.witch } } : {}),
    ...(config.tieBreaker ? { tieBreaker: { ...config.tieBreaker } } : {}),
  };
}

/** 以 BoardConfig 语义合并覆盖项（保留数组/对象的显式拷贝）。 */
function mergeBoardConfig(base: BoardConfig, override: BoardOverride): BoardConfig {
  return {
    ...base,
    ...override,
    hooks: { ...base.hooks, ...(override.hooks ?? {}) },
    roleSetups: override.roleSetups
      ? override.roleSetups.map((item) => ({ ...item }))
      : base.roleSetups.map((item) => ({ ...item })),
    ...(override.winConditions ? { winConditions: [...override.winConditions] } : {}),
    ...(override.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...override.selfDestruct.enabledWindows],
          },
        }
      : base.selfDestruct
        ? {
            selfDestruct: {
              enabledWindows: [...base.selfDestruct.enabledWindows],
            },
          }
        : {}),
    sheriff: { ...(base.sheriff ?? {}), ...(override.sheriff ?? {}) },
    witch: { ...(base.witch ?? {}), ...(override.witch ?? {}) },
    tieBreaker: { ...(base.tieBreaker ?? {}), ...(override.tieBreaker ?? {}) },
  };
}

/** 以“覆盖层”语义合并 default + board 专属配置。 */
function mergeBoardOverride(base: BoardOverride, override: BoardOverride): BoardOverride {
  return {
    ...base,
    ...override,
    ...(base.hooks || override.hooks
      ? {
          hooks: {
            ...(base.hooks ?? {}),
            ...(override.hooks ?? {}),
          },
        }
      : {}),
    ...(base.sheriff || override.sheriff
      ? {
          sheriff: {
            ...(base.sheriff ?? {}),
            ...(override.sheriff ?? {}),
          },
        }
      : {}),
    ...(base.witch || override.witch
      ? {
          witch: {
            ...(base.witch ?? {}),
            ...(override.witch ?? {}),
          },
        }
      : {}),
    ...(base.tieBreaker || override.tieBreaker
      ? {
          tieBreaker: {
            ...(base.tieBreaker ?? {}),
            ...(override.tieBreaker ?? {}),
          },
        }
      : {}),
    ...(override.roleSetups
      ? {
          roleSetups: override.roleSetups.map((item) => ({ ...item })),
        }
      : base.roleSetups
        ? {
            roleSetups: base.roleSetups.map((item) => ({ ...item })),
          }
        : {}),
    ...(override.winConditions
      ? {
          winConditions: [...override.winConditions],
        }
      : base.winConditions
        ? {
            winConditions: [...base.winConditions],
          }
        : {}),
    ...(override.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...override.selfDestruct.enabledWindows],
          },
        }
      : base.selfDestruct
        ? {
            selfDestruct: {
              enabledWindows: [...base.selfDestruct.enabledWindows],
            },
          }
        : {}),
  };
}

/** 读取对应板子的内置默认配置。 */
function baseBoard(board: BoardName): BoardConfig {
  return board === "twelve_player_standard"
    ? cloneBoardConfig(twelvePlayerStandardConfig)
    : cloneBoardConfig(sixPlayerMvpConfig);
}

/** 判断对象是否为旧版平铺结构。 */
function isBoardOverrideShape(value: unknown): value is BoardOverride {
  if (!isJsonObject(value)) {
    return false;
  }
  const keys = Object.keys(value);
  const supported = new Set([
    "boardSize",
    "enableSheriff",
    "initialSheriffSeat",
    "winCondition",
    "winConditions",
    "hooks",
    "selfDestruct",
    "sheriff",
    "witch",
    "tieBreaker",
    "roleSetups",
  ]);
  return keys.some((key) => supported.has(key));
}

/** 判断对象是否为新版结构化配置。 */
function isStructuredBoardOverrideShape(value: unknown): value is StructuredBoardConfig {
  if (!isJsonObject(value)) {
    return false;
  }
  return ["board", "rules", "mechanisms", "roles"].some((key) => key in value);
}

/** 把新版 `board/rules/mechanisms/roles` 结构映射到 BoardConfig 覆盖层。 */
function parseStructuredBoardOverride(raw: StructuredBoardConfig): BoardOverride {
  const out: BoardOverride = {};

  if (isJsonObject(raw.board)) {
    if (typeof raw.board.size === "number") {
      out.boardSize = raw.board.size;
    }
    if (Array.isArray(raw.board.roleSetups)) {
      out.roleSetups = raw.board.roleSetups as BoardConfig["roleSetups"];
    }
  }

  if (isJsonObject(raw.rules)) {
    if (typeof raw.rules.winCondition === "string") {
      out.winCondition = raw.rules.winCondition as BoardConfig["winCondition"];
    }
    if (Array.isArray(raw.rules.winConditions)) {
      out.winConditions = raw.rules.winConditions as BoardConfig["winConditions"];
    }
    if (isJsonObject(raw.rules.hooks)) {
      out.hooks = {
        ...(typeof raw.rules.hooks.onDaybreak === "boolean"
          ? { onDaybreak: raw.rules.hooks.onDaybreak }
          : {}),
        ...(typeof raw.rules.hooks.onPreElection === "boolean"
          ? { onPreElection: raw.rules.hooks.onPreElection }
          : {}),
        ...(typeof raw.rules.hooks.onPreVote === "boolean"
          ? { onPreVote: raw.rules.hooks.onPreVote }
          : {}),
        ...(typeof raw.rules.hooks.onPerSpeechGap === "boolean"
          ? { onPerSpeechGap: raw.rules.hooks.onPerSpeechGap }
          : {}),
      } as HookConfig;
    }
  }

  if (isJsonObject(raw.mechanisms)) {
    if (isJsonObject(raw.mechanisms.sheriff)) {
      if (typeof raw.mechanisms.sheriff.enabled === "boolean") {
        out.enableSheriff = raw.mechanisms.sheriff.enabled;
      }
      if (typeof raw.mechanisms.sheriff.initialSeat === "number") {
        out.initialSheriffSeat = raw.mechanisms.sheriff.initialSeat;
      }
      if (typeof raw.mechanisms.sheriff.voteWeight === "number") {
        out.sheriff = {
          ...(out.sheriff ?? {}),
          voteWeight: raw.mechanisms.sheriff.voteWeight,
        };
      }
      if (typeof raw.mechanisms.sheriff.tieBreaker === "string") {
        // sheriff.tieBreaker 在新结构里归一到 tieBreaker.sheriffVote。
        out.tieBreaker = {
          ...(out.tieBreaker ?? {}),
          sheriffVote: raw.mechanisms.sheriff.tieBreaker as NonNullable<
            BoardConfig["tieBreaker"]
          >["sheriffVote"],
        };
      }
    }
    if (isJsonObject(raw.mechanisms.selfDestruct)) {
      if (Array.isArray(raw.mechanisms.selfDestruct.enabledWindows)) {
        out.selfDestruct = {
          enabledWindows: raw.mechanisms.selfDestruct.enabledWindows as NonNullable<
            BoardConfig["selfDestruct"]
          >["enabledWindows"],
        };
      }
    }
    if (isJsonObject(raw.mechanisms.tieBreaker)) {
      out.tieBreaker = {
        ...(out.tieBreaker ?? {}),
        ...(typeof raw.mechanisms.tieBreaker.exileVote === "string"
          ? {
              exileVote: raw.mechanisms.tieBreaker.exileVote as NonNullable<
                BoardConfig["tieBreaker"]
              >["exileVote"],
            }
          : {}),
        ...(typeof raw.mechanisms.tieBreaker.wolfKillVote === "string"
          ? {
              wolfKillVote: raw.mechanisms.tieBreaker.wolfKillVote as NonNullable<
                BoardConfig["tieBreaker"]
              >["wolfKillVote"],
            }
          : {}),
      };
    }
  }

  if (isJsonObject(raw.roles)) {
    if (isJsonObject(raw.roles.witch) && typeof raw.roles.witch.selfHeal === "string") {
      out.witch = {
        ...(out.witch ?? {}),
        canSelfHeal: raw.roles.witch.selfHeal as NonNullable<BoardConfig["witch"]>["canSelfHeal"],
      };
    }
  }

  return out;
}

/** 统一解析“单个配置块”成覆盖层（兼容新旧两种结构）。 */
function toBoardOverride(value: unknown): BoardOverride | null {
  // 先识别平铺再识别结构化；命中一种后按其严格字段集合验证，不在失败后换分支求通过。
  if (isBoardOverrideShape(value)) {
    validateOverride(flatOverride, value);
    return value as BoardOverride;
  }
  if (isStructuredBoardOverrideShape(value)) {
    validateOverride(structuredOverride, value);
    return parseStructuredBoardOverride(value);
  }
  return null;
}

/** 从 json 根对象提取目标板子的覆盖配置（含 boards/default 合并）。 */
export function parseBoardOverride(raw: unknown, board: BoardName): BoardOverride | null {
  const direct = toBoardOverride(raw);
  if (direct) {
    return direct;
  }
  if (!isJsonObject(raw)) {
    return null;
  }

  if ("boards" in raw || "default" in raw) {
    validateOverride(
      z.strictObject({
        boards: z
          .record(
            z.string().regex(/^[a-z][a-z0-9_-]*$/),
            z.union([flatOverride, structuredOverride]),
          )
          .optional(),
        default: z.union([flatOverride, structuredOverride]).optional(),
      }),
      raw,
    );
  } else {
    const allowed = new Set([board, "six_player_mvp", "twelve_player_standard"]);
    for (const [key, value] of Object.entries(raw)) {
      if (!allowed.has(key)) throw new Error("board_config_invalid_override_field: document");
      validateOverride(z.union([flatOverride, structuredOverride]), value);
    }
  }

  // boards 内目标优先，并仅在该分支叠加 default；根级同名板子的原分支不叠加 default。
  const boardsEntry = isJsonObject(raw.boards) ? raw.boards[board] : undefined;
  const boardOverride = toBoardOverride(boardsEntry);
  if (boardOverride) {
    const defaultOverride = toBoardOverride(raw.default);
    if (!defaultOverride) {
      return boardOverride;
    }
    return mergeBoardOverride(defaultOverride, boardOverride);
  }

  const keyedBoardOverride = toBoardOverride(raw[board]);
  if (keyedBoardOverride) {
    return keyedBoardOverride;
  }
  return null;
}

/** 合并并规范化板子配置；文件查找由加载层负责。 */
export function resolveBoardConfig(
  board: BoardName,
  override: BoardOverride | null = null,
): BoardConfig {
  const base = baseBoard(board);
  const merged = override ? mergeBoardConfig(base, override) : base;
  return getDefaultConfigNormalizerRegistry().normalize(merged);
}

/**
 * 负责向运行装配及场景调用方提供既有板子预设。
 * 接收两项已列政策参数，每次构造新的贵族秘身十二人配置；默认值只选其中一个组合。
 * 输入为本模块固定声明和显式政策参数，输出为原 BoardConfig 数据；不在此解析、验证或冻结配置。
 * 预设不代表任意角色组合受支持，也不创建 World、支付资源或授予行动权限；规范化与有限支持由调用方继续执行。
 */
import {
  ActionWindow,
  Role,
  WinCondition,
  WitchSelfHealRule,
  type BoardConfig,
} from "../../core/domain/model";
export function nobleSecretBodyTwelveConfig(
  wolfActionPolicy: "standard" | "no_blast_no_self_knife" = "standard",
  protectionRepeatPolicy:
    "awa_nonconsecutive_nights_v1" | "awa_repeat_v1" = "awa_nonconsecutive_nights_v1",
): BoardConfig {
  return {
    boardSize: 12,
    enableSheriff: true,
    nobleSecretBody: { policy: "awa_noble_secret_body_v1" },
    nightNoble: { wolfActionPolicy },
    awakenedIdiot: { protectionRepeatPolicy },
    demonHunter: { policy: "awa_netease_demon_hunter_v1" },
    winConditions: [WinCondition.SlaughterSide],
    seer: { targetPolicy: "awa_alive_v1", actionPolicy: "awa_required_when_legal_v1" },
    witch: {
      canSelfHeal: WitchSelfHealRule.Disabled,
      knifeVisibility: "awa_with_heal_v1",
      potionPolicy: "awa_one_native_v1",
    },
    hooks: { onDaybreak: false, onPreElection: true, onPreVote: true, onPerSpeechGap: false },
    selfDestruct: { enabledWindows: [ActionWindow.OnPreElection, ActionWindow.OnPreVote] },
    sheriff: {
      electionPolicy: "awa_nomination_offstage_pk_v1",
      badgePolicy: "awa_holder_choice_v1",
      voteWeight: 1.5,
    },
    tieBreaker: {
