/** 即使引擎存在未提交改动，真实源码／lock 指纹仍明确控制重放兼容。 */
export async function currentEngineVersion(
  sourceRoot: string = path.resolve(__dirname, "../../../.."),
): Promise<EngineVersion> {
  const root = path.resolve(sourceRoot);
  const { sourceHash, lockHash } = await fingerprintEngine(root);
  let commit: string | undefined;
  try {
    const value = execFileSync("git", ["rev-parse", "HEAD"], {
      cwd: root,
      stdio: ["ignore", "pipe", "ignore"],
    })
      .toString()
      .trim();
    if (/^[a-f0-9]{40}$/.test(value)) commit = value;
  } catch {
    /* 无 .git 的归档仍可使用源码／lock 指纹，不补造提交身份。 */
  }
  return {
    id: "awa-engine",
    sourceHash,
    lockHash,
    ...(commit ? { commit } : {}),
  };
}

export function captureCheckpoint(
  world: World,
  snapshot: RuntimeSnapshot,
  cycle: number,
  complete: boolean,
  eventCount: number,
  failure?: unknown,
  cursors?: { settlementCount: number; decisionCount: number },
): RecordedCheckpoint {
  const contributions = prepareCheckpointContributions(world, complete);
  return {
    ...captureCheckpointContributions(world, complete, contributions, cursors),
    cycle,
    complete,
    snapshot,
    eventCount,
    ...(!complete
      ? { failure: { name: recordedErrorName(failure), code: "cycle_failed" as const } }
      : {}),
    players: capturePlayerContributions(world, complete, contributions.animal),
  };
}

export function beginGameReproduction(
  manager: SessionRecordManager,
  context: BootstrapResult,
  options: {
    engine: EngineVersion;
    boardId: string;
    locale: Locale;
    maxDays: number;
    profiles?: ReadonlyMap<number, ResolvedAgentRuntimeProfile>;
  },
) {
  const parameters = requireBoardParameters(context.world);
  if (context.parameters !== parameters || context.boardConfig !== parameters.board)
    throw new Error("rule_parameters_context_mismatch");
  if (
    !RulePlan.isOwned(context.rulePlan) ||
    context.rulePlan !== context.phaseManager.getRulePlan() ||
    context.rulePlan.parameters !== parameters
  )
    throw new Error("rule_plan_context_mismatch");
  const initial = captureCheckpoint(
    context.world,
    context.phaseManager.getSnapshot(),
    0,
    true,
    context.phaseManager.getEvents().length,
  );
  const trace = manager.beginReproduction(
    {
      engine: options.engine,
      boardId: options.boardId,
      normalizedBoard: context.rulePlan.encodeParameters(),
      locale: options.locale,
      maxDays: options.maxDays,
      dealMode: context.dealMode,
      ...(context.phaseManager.getFaultPlan()
        ? { faultPlan: context.phaseManager.getFaultPlan() }
        : {}),
      ...(initialIdentityDeal(context.world)
        ? { initialDeal: [...initialIdentityDeal(context.world)!] }
        : {}),
      ruleset: RULESET,
      random: context.random.metadata,
      players: initial.players.map((player) => {
        const profile = options.profiles?.get(player.id);
        return {
          id: player.id,
          name: player.name,
          role: player.role,
          camp: player.camp,
          ...(profile
            ? {
                agent: {
                  kind: profile.kind,
                  name: profile.name,
                  ...(profile.model ? { model: profile.model } : {}),
                },
              }
            : {}),
        };
      }),
    },
    parameters.board.radiantEclipse ||
      parameters.board.nobleSecretBody ||
      parameters.board.fragrantPairSeer ||
      parameters.board.animalDream
      ? () => context.phaseManager.getEvents()
      : undefined,
  );
  trace.checkpoint(initial, context.phaseManager.getEvents());
  return trace;
}

/**
 * 负责用明确种子与 provider 装配执行模拟批次。输入为板子／运行选项和各独立对局，输出原报告、分支计数与录制证据。
 * 特权 baseline 不是玩家知识 oracle，也不作为独立规则预期；每局 RNG 顺序保持，受限观察与录制使用同一绑定规则。
 */
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";
import { bootstrapGame } from "../../app/bootstrap";
import {
  DEATH_SHOT_STAGES,
  createRandom,
  randomDraws,
  type ActionProvider,
  type GameEvent,
  type RuntimeSnapshot,
} from "../../core";
import { readFile } from "node:fs/promises";
import { ObservedBot, type BotStyle } from "../../ai/agents/providers/observed_bot";
import { ObservedPlayersActionProvider } from "../../app/observed-players-action-provider";
import type { ResolvedBoardDefinition } from "../config/board_definition";
import { SessionRecordManager } from "../../recording/session_recorder";
import { runWithSessionRecorder } from "../../recording/recording_context";
import { GameEventRecorder } from "../game_event_recorder";
import { COMPONENT, type RoleComponent } from "../../core";
import { getWitchState } from "../../game/mechanisms/roles/witch/ports";
import {
  beginGameReproduction,
  captureCheckpoint,
  currentEngineVersion,
} from "./reproduction_context";

export interface SimulationOptions {
  locale?: Locale;
  displayLocale?: Locale;
  seeds: readonly string[];
  recordRoot: string;
  maxDays?: number;
  styles?: readonly BotStyle[];
}

export interface SimulationReport {
  board: string;
  games: Array<{
    seed: string;
    recordDir: string;
    result: RuntimeSnapshot["result"];
    natural: boolean;
    branches: Record<string, number>;
    rejects: number;
    fallbacks: number;
  }>;
  branches: Record<string, number>;
  naturallyFinished: number;
  rejects: number;
  fallbacks: number;
}

/** 统计实际执行的技能结果，不仅按牌堆有某角色就算命中分支。 */
function branchCounts(events: readonly GameEvent[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const event of events) {
    const key =
      event.type === "witch_potion_used"
        ? `${event.type}.${event.payload.potionType}`
        : event.type === "guard_applied"
          ? `${event.type}.${event.payload.abstain ? "skip" : "protect"}`
          : event.type;
    counts[key] = (counts[key] ?? 0) + 1;
    if (event.type === "noble_servant_chosen" || event.type === "secret_body_chosen") {
      const choice = `${event.type}.${event.payload.targetId === null ? "pass" : "select"}`;
      counts[choice] = (counts[choice] ?? 0) + 1;
    }
    if (event.type === "noble_contract_closed") {
      const terminal = `${event.type}.${event.payload.status}`;
      counts[terminal] = (counts[terminal] ?? 0) + 1;
    }
    if (event.type === "secret_body_blocked") {
      const cause = `${event.type}.${event.payload.cause}`;
      counts[cause] = (counts[cause] ?? 0) + 1;
    }
    if (
      event.type === "radiant_shelter_chosen" ||
      event.type === "eclipse_swallowed" ||
      event.type === "alchemist_mist_chosen" ||
      event.type === "alchemist_snake_chosen" ||
      event.type === "raven_knife_chosen"
    ) {
      const spent =
        event.type === "alchemist_mist_chosen"
          ? event.payload.targetIds !== null
          : event.payload.targetId !== null;
      const outcome = `${event.type}.${spent ? "spend" : "pass"}`;
      counts[outcome] = (counts[outcome] ?? 0) + 1;
      if (spent && event.payload.day > 1) {
        const delayed = `${event.type}.later_spend`;
        counts[delayed] = (counts[delayed] ?? 0) + 1;
      }
    }
  }
  return counts;
}

/** 只有 controller 为断言／录制读取真值，受限策略消费 DTO；特权基线另有明确入口。 */
export async function simulateGames(
  board: ResolvedBoardDefinition,
  options: SimulationOptions,
): Promise<SimulationReport> {
  if (!options.seeds.length || new Set(options.seeds).size !== options.seeds.length)
    throw new Error("simulation_seeds_invalid");
  const locale = options.locale ?? "zh-CN";
  if (!isLocale(locale)) throw new Error("simulation_locale_invalid");
  const maxDays = options.maxDays ?? 30;
  if (!Number.isSafeInteger(maxDays) || maxDays < 1) throw new Error("simulation_max_days_invalid");
  const styles = options.styles ?? ["active", "conservative", "competitive", "random"];
  if (
    !styles.length ||
    styles.some((style) => !["active", "conservative", "competitive", "random"].includes(style))
  )
    throw new Error("simulation_styles_invalid");
  const report: SimulationReport = {
    board: board.definition.id,
    games: [],
    branches: {},
    naturallyFinished: 0,
    rejects: 0,
    fallbacks: 0,
  };
  const batchId = crypto.randomUUID();
  const engine = await currentEngineVersion();
  for (const [index, seed] of options.seeds.entries()) {
    const random = createRandom(seed);
    const context = bootstrapGame(board.config, { random, locale });
    const strategies = new Map(
      context.playerIds.map((id) => [
        id,
        new ObservedBot(
          randomDraws(random.fork("players").fork(`id:${id}`)),
          styles[Math.floor(random.fork("styles").fork(`id:${id}`).next() * styles.length)],
        ),
      ]),
    );
    const observed = new ObservedPlayersActionProvider(
      context.world,
      strategies,
    );
    const provider: ActionProvider = {
      async getAction(request) {
        if (context.phaseManager.getSnapshot().gameOver)
          throw new Error("simulation_action_after_game_over");
        if (
          !context.world.getAliveEntityIds().includes(request.actorId) &&
          request.context.stage !== "last_words" &&
          !DEATH_SHOT_STAGES.includes(request.context.stage) &&
          !(
            request.context.stage === "sheriff_badge_choice" &&
            request.allowedTools.includes("choose_badge_successor") &&
            context.world.hasDeathAction(
              request.actorId,
              "choose_badge_successor",
              request.phase,
              request.context.day,
              request.context.death_action_id,
            )
          )
        )
          throw new Error("simulation_unauthorized_dead_action");
        return observed.getAction(request);
      },
    };
    const manager = await SessionRecordManager.create(
      {
        sessionId: `simulation-${batchId}-${index}`,
        board: board.definition.id,
        locale: context.world.locale,
        startedAtIso: new Date().toISOString(),
        random: random.metadata,
      },
      options.recordRoot,
      options.displayLocale ?? locale,
    );
    const recorder = new GameEventRecorder(
      { world: context.world, replayManager: manager },
      context.phaseManager.getSnapshot().phase,
    );
    const summary = await runWithSessionRecorder(manager, async () => {
      const failures: unknown[] = [];
      const reproduction = beginGameReproduction(manager, context, {
        engine,
        boardId: board.definition.id,
        locale: context.world.locale,
        maxDays,
      });
      const recordedProvider: ActionProvider = {
        getAction: (request) => reproduction.decide(request, provider),
      };
      let cycle = 0;
      let priorAlive = context.world.getAliveEntityIds();
      const priorResources = new Map<number, { heal: number; poison: number }>();
      try {
        while (!context.phaseManager.getSnapshot().gameOver) {
          cycle++;
          let complete = false;
          let cycleFailure: unknown;
          try {
            await context.phaseManager.runSingleCycle(recordedProvider, maxDays);
            complete = true;
          } catch (error) {
            cycleFailure = error;
            failures.push(error);
            manager.noteReproductionFailure("cycle", error);
          }
          try {
            reproduction.checkpoint(
              captureCheckpoint(
                context.world,
                context.phaseManager.getSnapshot(),
                cycle,
                complete,
                context.phaseManager.getEvents().length,
                cycleFailure,
              ),
              context.phaseManager.getEvents(),
            );
          } catch (error) {
            failures.push(error);
            reproduction.invalidate();
            manager.noteReproductionFailure("recording", error);
          }
          if (failures.length) break;
          recorder.flush(context.phaseManager.getEvents());
          // 公开 controller 不变量不把隐藏真值反馈给决策。
          const alive = context.world.getAliveEntityIds();
          if (alive.some((id) => !priorAlive.includes(id)))
            throw new Error("simulation_unexpected_revival");
          priorAlive = alive;
          for (const id of context.world.entityIds()) {
            const role = context.world.getComponent(id, COMPONENT.Role);
            if (!role) throw new Error("simulation_missing_role");
            const witch = getWitchState(role);
            if (witch) {
              const prior = priorResources.get(id) ?? { heal: 1, poison: 1 };
              if (
                witch.heal < 0 ||
                witch.poison < 0 ||
                witch.heal > prior.heal ||
                witch.poison > prior.poison
              )
                throw new Error("simulation_invalid_resource_transition");
              priorResources.set(id, { heal: witch.heal, poison: witch.poison });
            }
          }
        }
      } catch (error) {
        failures.push(error);
        manager.noteReproductionFailure("controller", error);
      } finally {
        try {
          recorder.flush(context.phaseManager.getEvents());
        } catch (error) {
          failures.push(error);
        }
        try {
          const snapshot = context.phaseManager.getSnapshot();
          await manager.finalize({
            endedAtIso: new Date().toISOString(),
            winner: snapshot.result?.winner ?? null,
            ...(snapshot.result ? { gameResult: snapshot.result } : {}),
            finishReason: failures.length
              ? "runtime_error"
              : (snapshot.result?.reason ?? "incomplete"),
            players: context.playerIds.map((id) => {
              const role = context.world.getComponent(id, COMPONENT.Role)!;
              return {
                player_id: id,
                role: role.role,
                camp: context.world.getComponent(id, COMPONENT.Camp)!.camp,
                alive: context.world.getAliveEntityIds().includes(id),
              };
            }),
          });
        } catch (error) {
          failures.push(error);
        }
      }
      if (failures.length === 1) throw failures[0];
      if (failures.length) throw new AggregateError(failures, "simulation_game_failed");
      return manager;
    });
    // 落盘操作反映实际执行接受，不将策略的尝试冒充提交。
    const operations = JSON.parse(
      await readFile(`${summary.sessionDir}/logic_ops.json`, "utf8"),
    ) as { ops: Array<{ status: string }> };
    const branches = branchCounts(context.phaseManager.getEvents());
    const result = context.phaseManager.getSnapshot().result;
    const natural = result !== null && result.reason !== "max_days_reached";
    const rejects = operations.ops.filter((op) => op.status === "rejected").length;
    const fallbacks = operations.ops.filter((op) => op.status === "fallback").length;
    report.games.push({
      seed,
      recordDir: summary.sessionDir,
      result,
      natural,
      branches,
      rejects,
      fallbacks,
    });
    report.naturallyFinished += Number(natural);
    report.rejects += rejects;
    report.fallbacks += fallbacks;
    for (const [branch, count] of Object.entries(branches))
      report.branches[branch] = (report.branches[branch] ?? 0) + count;
  }
  return report;
}

/**
 * 负责独立审核猎魔人选择、原生结果及贵族／赤月联动证据。输入为归档配置、决定、事实与 checkpoint；
 * 输出为原一致性结果或明确拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import type { NobleRecordAudit } from "../noble-secret-body/validate";
import { validateRedMoonRecord } from "../red-moon/validate";
import { validateDemonNativeStocks } from "./native-stocks";
import { z } from "zod";
import {
  DEMON_HUNTER_POLICY,
  DEMON_HUNTER_EVENT_TYPES,
  readDemonHunterEventFact,
  readDemonHunterPlayerFact,
  readDemonHunterState,
  readDemonHuntTool,
} from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
import { isDemonHunterPreset } from "../../board-support";
import { Role, Camp, Phase, DeathCause } from "@ai-werewolf-arena/game-contract";
import { readFaultPlan } from "../../../core/domain/fault_plan";
import type { ReproductionRecord } from "../../../recording/reproduction";
const positive = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
const choice = z.strictObject({ day: positive.min(2), targetId: positive.nullable() });
const cancel = z.strictObject({
  policy: z.literal(DEMON_HUNTER_POLICY),
  actorId: positive,
  day: positive.min(2),
  targetId: positive,
  reason: z.literal("authority_revoked"),
  faultId: z.string().min(1).nullable(),
});
const immune = z.strictObject({
  policy: z.literal(DEMON_HUNTER_POLICY),
  actorId: positive,
  day: positive,
  witchId: positive,
});
const rootCauses = [
  DeathCause.WolfKill,
  DeathCause.Poison,
  DeathCause.DemonHunt,
  DeathCause.DemonHuntBacklash,
  DeathCause.ServantExpiry,
] as const;
const frozenSchema = z.strictObject({
  policy: z.literal(DEMON_HUNTER_POLICY),
  day: positive,
  hunt: z.strictObject({
    choice: choice.nullable(),
    damage: z
      .strictObject({ targetId: positive, cause: z.enum(["demon_hunt", "demon_hunt_backlash"]) })
      .nullable(),
    cancelled: cancel.nullable(),
    servantCleared: z.record(z.string(), z.json()).optional(),
  }),
  poison_immunities: z.array(immune).max(1),
  poison_overrides: z.array(z.strictObject({ targetId: positive, poison: z.boolean() })).max(1),
  heal_overrides: z.array(z.strictObject({ targetId: positive, heal: z.boolean() })).max(1),
  guard_overrides: z.array(z.strictObject({ targetId: positive, guard: z.boolean() })).max(1),
  deaths: z.array(positive),
  death_sources: z.record(z.string(), z.array(z.enum(rootCauses))),
});
function equal(a: unknown, b: unknown): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}
function assert(value: unknown): asserts value {
  if (!value) throw new Error("reproduction_demon_hunter_state_invalid");
}
const isFact = (type: string) => (DEMON_HUNTER_EVENT_TYPES as readonly string[]).includes(type);
/** 独立审核序列化因果；取消标签本身不能授权覆盖效果。 */
export function validateDemonHunterRecord(
  record: ReproductionRecord,
  noble: NobleRecordAudit | null = null,
): void {
  // 先核赤月再读猎魔人板子；贵族 audit 是装配先前原点传入的同一对象，
  // 不从 checkpoint 的自报字段重新制造预期，原拒绝优先级保持。
  const redMoon = validateRedMoonRecord(record);
  const board = record.metadata.normalizedBoard,
    owns = board.roleSetups.some((r) => r.role === Role.DemonHunter && r.count > 0),
    artifacts =
      record.metadata.faultPlan ||
      record.events.some((e) => isFact(e.type)) ||
      record.operations.some(
        (o) => o.op === "fault_applied" || o.op === "demon_hunter_sources_frozen",
      ) ||
      record.decisions.some(
        (d) => d.stage === "demon_hunter" || d.request.allowedTools.includes("demon_hunt"),
      ) ||
      record.checkpoints.some((c) =>
        c.players.some((p) => Object.hasOwn(p.privateState, "demonHunter")),
      );
  if (!owns) {
    assert(!artifacts && !board.demonHunter);
    return;
  }
  assert(isDemonHunterPreset(board) && !record.metadata.initialDeal);
  const players = record.metadata.players,
    ids = new Set(players.map((p) => p.id)),
    original = new Map(players.map((p) => [p.id, p])),
    demon = players.filter((p) => p.role === Role.DemonHunter),
    witch = players.filter((p) => p.role === Role.Witch);
  assert(
    players.length === board.boardSize &&
      ids.size === board.boardSize &&
      demon.length === 1 &&
      witch.length === 1,
  );
  const actorId = demon[0]!.id,
    witchId = witch[0]!.id;
  assert(
    board.roleSetups.every((r) => players.filter((p) => p.role === r.role).length === r.count),
  );
  for (const p of players)
    assert(
      p.camp ===
        ([Role.Wolf, Role.RedMoonApostle, Role.NightNoble].includes(p.role)
          ? Camp.Wolf
          : Camp.Good),
    );
  for (const cp of record.checkpoints) {
    assert(
      cp.players.length === ids.size && new Set(cp.players.map((p) => p.id)).size === ids.size,
    );
    for (const p of cp.players) {
      const initial = original.get(p.id);
      assert(
        initial &&
          p.role === initial.role &&
          p.camp === initial.camp &&
          equal(p.victory, { affiliations: [{ kind: "faction", faction: initial.camp }] }),
      );
      if (p.id !== actorId) assert(!Object.hasOwn(p.privateState, "demonHunter"));
    }
  }
  validateDemonNativeStocks(record, redMoon, noble);
  for (const decision of record.decisions) {
    for (const event of decision.request.context.visible_events) {
      if (!isFact(event.type)) continue;
      assert(event.type === "demon_hunter_chosen" && decision.actorId === actorId);
      const own = readDemonHunterPlayerFact(event.type, event.payload);
      assert(own && own.day <= decision.day);
      if (record.finalized)
        assert(
          record.events.some(
            (e) =>
              e.type === "demon_hunter_chosen" &&
              e.payload.actorId === actorId &&
              e.payload.day === own.day &&
              e.payload.targetId === own.targetId,
          ),
        );
    }
  }
  // 增量快照刻意省略领域操作，且可能先于下一份 checkpoint 发布。
  if (!record.finalized) return;
  const decisions = record.decisions.filter((d) => d.stage === "demon_hunter"),
    committed = decisions.filter((d) => d.outcome.kind === "action"),
    chosen = record.events.filter((e) => e.type === "demon_hunter_chosen"),
    cancelled = record.events.filter((e) => e.type === "demon_hunter_cancelled"),
    immunities = record.events.filter((e) => e.type === "demon_hunter_poison_immune"),
    accepted = record.operations.filter(
      (o) => o.op === "validate_tool_call" && o.input?.tool === "demon_hunt",
    );
  let previous = 1;
  for (const d of decisions) {
    assert(
      d.actorId === actorId &&
        d.day > previous &&
        d.turn === 1 &&
        d.request.phase === Phase.Night &&
        d.request.actorId === actorId &&
        d.request.context.day === d.day &&
        d.request.context.stage === "demon_hunter" &&
        equal(d.request.allowedTools, ["demon_hunt"]) &&
        d.request.context.allow_fallback === false &&
        d.request.context.action_failure_policy === "error" &&
        d.request.context.turn_constraints.min_valid_actions === 1 &&
        d.request.context.turn_constraints.max_valid_actions === 1 &&
        equal(d.request.context.turn_constraints.required_any_tools, ["demon_hunt"]),
    );
    const prior = record.checkpoints.find((cp) => cp.cycle === d.day - 1);
    assert(prior?.complete && prior.players.find((p) => p.id === actorId)?.alive);
    previous = d.day;
  }
  assert(chosen.length === committed.length && accepted.length === committed.length);
  const choices = new Map<number, { day: number; targetId: number | null }>();
  for (let index = 0; index < committed.length; index++) {
    const d = committed[index]!,
      call = readDemonHuntTool(d.outcome.kind === "action" ? d.outcome.action : null);
    assert(
      call &&
        (call.args.target_id === null ||
          (ids.has(call.args.target_id) && call.args.target_id !== actorId)),
    );
    const prior = record.checkpoints.find((cp) => cp.cycle === d.day - 1)!;
    if (call.args.target_id !== null)
      assert(prior.players.find((p) => p.id === call.args.target_id)?.alive);
    const c = { day: d.day, targetId: call.args.target_id },
      e = chosen[index]!,
      op = accepted[index]!;
    choices.set(d.day, c);
    assert(
      equal(e.payload, { policy: DEMON_HUNTER_POLICY, actorId, ...c }) &&
        equal(e.audience, [actorId]) &&
        op.scope === "gateway" &&
        op.phase === Phase.Night &&
        op.status === "ok" &&
        op.actor_id === actorId &&
        equal(op.input, { tool: "demon_hunt", args: call.args }),
    );
  }
  const plan = record.metadata.faultPlan ? readFaultPlan(record.metadata.faultPlan) : null,
    faults = record.operations.filter((o) => o.op === "fault_applied"),
    applied = new Map<number, string>();
  for (let index = 0; index < faults.length; index++) {
    const op = faults[index]!,
      step = plan?.steps[index],
      c = step && choices.get(step.at.day);
    assert(
      step &&
        c &&
        c.targetId !== null &&
        step.at.afterDecision.actorId === actorId &&
        [actorId, c.targetId].includes(step.mutation.playerId) &&
        op.scope === "resolution" &&
        op.phase === Phase.Night &&
        op.status === "ok" &&
        equal(op.input, { version: "awa_fault_plan_v1", step }) &&
        equal(op.output, { originalVersion: 0, replacementVersion: 0 }),
    );
    assert(!applied.has(step.at.day));
    applied.set(step.at.day, step.id);
  }
  const publicNights = new Map<number, { deaths: number[]; shots: number[] }>();
  let eventDay = 1,
    eventPhase: string = Phase.Night,
    shots: number[] = [];
  for (const e of record.events) {
    if (e.type === "phase_changed") {
      eventDay = Number(e.payload.day);
      eventPhase = String(e.payload.phase);
      if (eventPhase === Phase.Night) shots = [];
    }
    if (e.type === "hunter_shot" && eventPhase === Phase.Night) {
      assert(
        original.get(Number(e.payload.hunterId))?.role === Role.Hunter &&
          ids.has(Number(e.payload.targetId)),
      );
      shots.push(Number(e.payload.targetId));
    }
    if (e.type === "night_resolved") {
      assert(
        eventPhase === Phase.Night &&
          !publicNights.has(eventDay) &&
          Array.isArray(e.payload.deaths),
      );
      const deaths = e.payload.deaths as number[];
      assert(deaths.length === new Set(deaths).size && deaths.every((id) => ids.has(id)));
      publicNights.set(eventDay, { deaths, shots: [...shots] });
    }
  }
  const frozen = record.operations.filter((o) => o.op === "demon_hunter_sources_frozen"),
    expectedCancel: unknown[] = [],
    expectedImmunities: unknown[] = [];
  previous = 0;
  for (const op of frozen) {
    const parsed = frozenSchema.safeParse(op.output);
    assert(
      parsed.success &&
        op.scope === "resolution" &&
        op.phase === Phase.Night &&
        op.status === "ok" &&
        op.input === undefined,
    );
    const source = parsed.data,
      c = choices.get(source.day) ?? null,
      faultId = applied.get(source.day) ?? null;
    assert(source.day > previous && equal(source.hunt.choice, c));
    previous = source.day;
    const prior = record.checkpoints.find((cp) => cp.cycle === source.day - 1);
    assert(prior);
    const eligible =
      source.day >= 2 &&
      prior.players.find((p) => p.id === actorId)?.alive &&
      !redMoon?.sealedNights.has(source.day);
    assert(Boolean(c) === Boolean(eligible));
    if (faultId) {
      assert(
        c?.targetId !== null &&
          c &&
          equal(source.hunt.cancelled, {
            policy: DEMON_HUNTER_POLICY,
            actorId,
            ...c,
            reason: "authority_revoked",
            faultId,
          }) &&
          source.hunt.damage === null,
      );
      assert(
        record.operations.indexOf(faults.find((f) => (f.input?.step as any)?.id === faultId)!) <
          record.operations.indexOf(op),
      );
    } else {
      assert(source.hunt.cancelled === null);
      const damage =
        !c || c.targetId === null
          ? null
          : original.get(c.targetId)!.camp === Camp.Wolf
            ? { targetId: c.targetId, cause: "demon_hunt" }
            : { targetId: actorId, cause: "demon_hunt_backlash" };
      const n = noble?.nights.get(source.day);
      assert(equal(source.hunt.damage, n ? n.huntDamage : damage));
      assert(equal(source.hunt.servantCleared ?? null, n?.clear ?? null));
    }
    if (source.hunt.cancelled) expectedCancel.push(source.hunt.cancelled);
    assert(
      Object.keys(source.death_sources).every(
        (id) => /^(0|[1-9][0-9]*)$/.test(id) && ids.has(Number(id)),
      ),
    );
    if (!noble)
      assert(
        source.hunt.servantCleared === undefined &&
          !Object.values(source.death_sources).some((c) => c.includes(DeathCause.ServantExpiry)),
      );
    else assert(equal(source.death_sources, noble.nights.get(source.day)?.final));
    const roots = new Map(
      Object.entries(source.death_sources)
        .filter(([, causes]) => causes.length > 0)
        .map(([id, causes]) => [Number(id), causes]),
    );
    assert(
      source.deaths.length === new Set(source.deaths).size &&
        source.deaths.every((id) => ids.has(id) && roots.has(id)) &&
        roots.size === source.deaths.length,
    );
    for (const [id, causes] of roots) {
      assert(new Set(causes).size === causes.length);
      for (const cause of causes.filter(
        (x) => x === DeathCause.DemonHunt || x === DeathCause.DemonHuntBacklash,
      ))
        assert(
          source.hunt.damage &&
            id === source.hunt.damage.targetId &&
            cause ===
              (source.hunt.damage.cause === "demon_hunt"
                ? DeathCause.DemonHunt
                : DeathCause.DemonHuntBacklash),
        );
    }
    if (source.hunt.damage && !noble)
      assert(
        roots
          .get(source.hunt.damage.targetId)
          ?.includes(
            source.hunt.damage.cause === "demon_hunt"
              ? DeathCause.DemonHunt
              : DeathCause.DemonHuntBacklash,
          ),
      );
    const publicNight = publicNights.get(source.day);
    if (publicNight) {
      const completeDeaths = [
        ...new Set([
          ...source.deaths,
          ...publicNight.shots,
          ...(redMoon?.expiredNights.has(source.day)
            ? [redMoon.expiredNights.get(source.day)!]
            : []),
        ]),
      ].sort((a, b) => a - b);
      assert(
        equal(
          [...publicNight.deaths].sort((a, b) => a - b),
          completeDeaths,
        ),
      );
    } else
      assert(
        !record.checkpoints.at(-1)!.complete && source.day === record.checkpoints.at(-1)!.cycle,
      );
    const potion = record.decisions.find(
      (d) =>
        d.actorId === witchId &&
        d.day === source.day &&
        d.stage === "witch" &&
        d.outcome.kind === "action" &&
        d.outcome.action?.name === "use_potion" &&
        d.outcome.action.args.potion_type === "poison" &&
        d.outcome.action.args.target_id === actorId,
    );
    const appliedStep = faultId ? plan?.steps.find((step) => step.id === faultId) : undefined;
    const qualifiedPotion =
      potion && (!appliedStep || ![actorId, witchId].includes(appliedStep.mutation.playerId));
    assert(source.poison_immunities.length === (qualifiedPotion ? 1 : 0));
    for (const fact of source.poison_immunities) {
      assert(
        potion &&
          equal(fact, { policy: DEMON_HUNTER_POLICY, actorId, day: source.day, witchId }) &&
          !roots.get(actorId)?.includes(DeathCause.Poison),
      );
      expectedImmunities.push(fact);
    }
    for (const override of [
      ...source.poison_overrides,
      ...source.heal_overrides,
      ...source.guard_overrides,
    ])
      assert(ids.has(override.targetId));
  }
  assert([...publicNights.keys()].every((day) => frozen.some((o) => o.output?.day === day)));
  assert(
    equal(
      cancelled.map((e) => e.payload),
      expectedCancel,
    ) &&
      equal(
        immunities.map((e) => e.payload),
        expectedImmunities,
      ),
  );
  for (const e of [...chosen, ...cancelled, ...immunities])
    assert(
      readDemonHunterEventFact(e.type, e.payload) &&
        equal(e.audience, e.type === "demon_hunter_chosen" ? [actorId] : []),
    );
  const last = record.checkpoints.at(-1)!;
  if (last.complete) assert(!plan || faults.length === plan.steps.length);
  for (const cp of record.checkpoints) {
    const state = readDemonHunterState(
      cp.players.find((p) => p.id === actorId)!.privateState.demonHunter,
    );
    assert(state);
    const visible = record.events
      .slice(0, cp.eventCount)
      .filter((e) => e.type === "demon_hunter_chosen");
    assert(
      equal(
        state.history,
        visible.map((e) => ({ day: e.payload.day, targetId: e.payload.targetId })),
      ),
    );
    if (cp.cycle === 0) assert(cp.complete && state.history.length === 0);
    if (cp.complete)
      assert(
        !record.events.slice(0, cp.eventCount).some((e) => e.type === "demon_hunter_cancelled"),
      );
  }
}

/**
 * 负责独立重建光蚀夜请求的串行发表前缀。输入为原归档、日次、起始库存与席位；
 * 输出为带 release 次序的历史事实，沿原决定逐步核验而不执行实际夜阶段。
 * 失败／未完成前置只能结束当前前缀，不能开放后继；此账本不授予 live 许可或付款。
 * 原角色查询、能力副本字段及错误顺序保持，类型和值依赖仍由本族具体叶拥有。
 */
import type { RecordedDecision, RecordedGameEvent, ReproductionRecord } from "../../../recording/reproduction";
import { Role, Camp } from "../../../core/domain/identity";
import {
  radiantCheck as check,
  radiantEqual as equal,
  radiantBorrow,
  type RadiantAbility,
  type RadiantNightEvidence,
} from "./validate";
import { sanitizeSpeechText } from "../../../utils/speech_text";
export interface RadiantReleasedFact {
  event: Omit<RecordedGameEvent, "timestamp">;
  release: number;
}
/** 独立按序计算请求发表前缀；无效或未完成的前置不产生后继资格。 */
export function radiantNightRequestPrefix(
  record: ReproductionRecord,
  day: number,
  n: Pick<RadiantNightEvidence, "start" | "before" | "previousSwallow">,
  roster: ReadonlyMap<number, ReproductionRecord["metadata"]["players"][number]>,
): RadiantReleasedFact[] {
  const ds = record.decisions.filter((d) => d.day === day && d.request.phase === "night"),
    facts: RadiantReleasedFact[] = [];
  if (!ds.length) return facts;
  const actor = (role: Role) => [...roster.values()].find((p) => p.role === role)!.id,
    maid = actor(Role.EclipseMaid),
    count = actor(Role.RadiantCount);
  let cursor = 0,
    stopped = false,
    target: number | null = null,
    borrowed: RadiantAbility | undefined,
    lastRelease = Math.max(
      0,
      ...record.decisions.filter((d) => d.day < day).map((d) => d.settleOrder ?? 0),
    );
  const emit = (
    type: string,
    payload: Record<string, unknown>,
    release: number,
    audience?: readonly number[],
  ) =>
    facts.push({
      event: { type, payload, ...(audience ? { audience: [...audience] } : {}) },
      release,
    });
  emit("phase_changed", { phase: "night", day }, lastRelease);
  // 原决定按 cursor 消费；合法结束更新 release，pending／error／非法原回复
  // 必须是归档尾项并停止。只验证记录次序，不替阶段发起请求或标记付款。
  const step = (
    stage: string,
    id: number,
    tool: string,
    keys: string[],
    legal: (a: Record<string, any>) => boolean,
  ): { d: RecordedDecision; args: Record<string, any> } | null => {
    if (stopped) return null;
    const d = ds[cursor];
    if (!d) {
      stopped = true;
      return null;
    }
    check(d.stage === stage && d.actorId === id && d.openedAfterSettlement === lastRelease);
    cursor++;
    const a = d.outcome.kind === "action" ? d.outcome.action : null;
    const required = a?.name === tool && keys.every((k) => Object.hasOwn(a.args, k));
    if (required) check(Object.keys(a!.args).length === keys.length);
    if (
      d.outcome.kind === "pending" ||
      d.outcome.kind === "error" ||
      !a ||
      a.name !== tool ||
      !required ||
      !legal(a.args)
    ) {
      check(cursor === ds.length);
      stopped = true;
      return null;
    }
    check(d.settleOrder !== undefined);
    lastRelease = d.settleOrder;
    return { d, args: a.args };
  };
  if (day >= 2 && n.start.includes(maid)) {
    const result = step(
      "eclipse_swallow",
      maid,
      "swallow_skill",
      ["target_id"],
      (a) =>
        a.target_id === null ||
        (Number.isSafeInteger(a.target_id) &&
          n.start.includes(a.target_id) &&
          roster.get(a.target_id)!.camp === Camp.Good &&
          !(n.previousSwallow?.day === day - 1 && n.previousSwallow.targetId === a.target_id)),
    );
    if (!result) return facts;
    target = result.args.target_id;
    const source = target === null ? undefined : n.before.get(target);
    if (source) {
      borrowed = radiantBorrow(source, target!, day);
      emit(
        "ability_changed",
        {
          actorId: maid,
          abilityId: borrowed.id,
          kind: borrowed.kind,
          operation: "granted",
          source: borrowed.source,
          sourceDisclosed: true,
          startsOnDay: day,
          expiresAfterDay: day,
          maxUses: null,
        },
        lastRelease,
      );
    }
    emit(
      "eclipse_swallowed",
      {
        actorId: maid,
        day,
        targetId: target,
        roleId: target === null ? null : roster.get(target)!.role,
        abilityId: borrowed?.id ?? null,
      },
      lastRelease,
      [maid],
    );
    if (target !== null)
      emit("eclipse_native_suppressed", { playerId: target, day }, lastRelease, [target]);
  }
  const abilityActors = (kind: RadiantAbility["kind"]) =>
    n.start.flatMap((id) => {
      const a = id === maid ? borrowed : n.before.get(id);
      return a && a.kind === kind && day >= a.startsOnDay && (id === maid || id !== target)
        ? [{ id, a }]
        : [];
    });
  for (const { id, a } of day >= 2 ? abilityActors("shelter") : []) {
    const result = step(
      "radiant_shelter",
      id,
      "cast_shelter",
      ["target_id"],
      (x) =>
        x.target_id === null ||
        (Number.isSafeInteger(x.target_id) &&
          n.start.includes(x.target_id) &&
          x.target_id !== id &&
          !(a.state.lastDay === day - 1 && a.state.lastTarget === x.target_id)),
    );
    if (!result) return facts;
    emit(
      "radiant_shelter_chosen",
      { actorId: id, day, targetId: result.args.target_id, abilityId: a.id },
      lastRelease,
      [id],
    );
  }
  for (const { id, a } of abilityActors("dream").filter(({ id }) =>
    n.start.some((t) => t !== id),
  )) {
    const result = step(
      "dreamer",
      id,
      "dream",
      ["target_id"],
      (x) =>
        Number.isSafeInteger(x.target_id) && n.start.includes(x.target_id) && x.target_id !== id,
    );
    if (!result) return facts;
    emit(
      "dream_applied",
      {
        actorId: id,
        targetId: result.args.target_id,
        day,
        consecutive: a.state.lastDay === day - 1 && a.state.lastTarget === result.args.target_id,
        ...(id === maid ? { abilityId: a.id } : {}),
      },
      lastRelease,
    );
  }
  const wolves = n.start.filter((id) => roster.get(id)!.role === Role.Wolf),
    holders = wolves.length ? wolves : n.start.includes(maid) ? [maid] : [];
  const firstChat = ds.find((d) => d.stage === "wolf_discussion");
  if (wolves.length && !firstChat && cursor === ds.length) return facts;
  const feed = firstChat?.request.context.visible_events ?? [];
  let phaseIndex = -1,
    tacticalIndex = -1;
  for (const [index, event] of feed.entries()) {
    if (
      event.type === "phase_changed" &&
      event.payload.phase === "night" &&
      event.payload.day === day
    )
      phaseIndex = index;
    if (event.type === "wolf_tactical_order") tacticalIndex = index;
  }
  const order =
    tacticalIndex > phaseIndex ? (feed[tacticalIndex]!.payload.order as number[]) : undefined;
  if (wolves.length) {
    check(
      order &&
        equal(
          [...order].sort((a, b) => a - b),
          [...wolves].sort((a, b) => a - b),
        ),
    );
    emit("wolf_tactical_order", { order: [...order] }, lastRelease, holders);
  }
  const ended = new Set<number>();
  for (let round = 1; round <= 3; round++)
    for (const id of order ?? []) {
      if (ended.has(id)) continue;
      const result = step(
        "wolf_discussion",
        id,
        "speak_to_wolves",
        ["text", "end_chat"],
        (x) => typeof x.text === "string" && typeof x.end_chat === "boolean",
      );
      if (!result) return facts;
      check(result.d.turn === round);
      const end = result.args.end_chat;
      emit(
        end ? "wolf_discussion_ended" : "wolf_discussion",
        {
          actorId: id,
          [end ? "reason" : "text"]: sanitizeSpeechText(result.args.text),
          round,
          ...(end ? {} : { endChat: false }),
        },
        lastRelease,
        holders,
      );
      if (end) ended.add(id);
    }
  const tally = new Map<number, number>();
  for (const id of order ?? holders) {
    const result = step(
      "wolf_vote",
      id,
      "kill_vote",
      ["target_id", "abstain"],
      (x) =>
        typeof x.abstain === "boolean" &&
        (x.target_id === null || (Number.isSafeInteger(x.target_id) && x.target_id > 0)) &&
        (x.abstain || (x.target_id !== null && n.start.includes(x.target_id))),
    );
    if (!result) return facts;
    emit(
      "wolf_kill_vote_cast",
      { actorId: id, abstain: result.args.abstain, targetId: result.args.target_id },
      lastRelease,
      holders,
    );
    if (!result.args.abstain)
      tally.set(result.args.target_id, (tally.get(result.args.target_id) ?? 0) + 1);
  }
  const knife = [...tally].sort(([a, x], [b, y]) => y - x || a - b)[0]?.[0] ?? null;
  for (const { id, a } of abilityActors("potion")) {
    if (id === maid && !a.state.heal && !a.state.poison) continue;
    const result = step(
      "witch",
      id,
      "use_potion",
      ["target_id", "potion_type"],
      (x) =>
        Number.isSafeInteger(x.target_id) &&
        x.target_id > 0 &&
        (x.potion_type === "none" ||
          (x.potion_type === "heal" &&
            a.state.heal === 1 &&
            x.target_id !== id &&
            knife === x.target_id &&
            n.start.includes(x.target_id)) ||
          (x.potion_type === "poison" && a.state.poison === 1 && n.start.includes(x.target_id))),
    );
    if (!result) return facts;
    emit(
      result.args.potion_type === "none" ? "witch_potion_skipped" : "witch_potion_used",
      {
        actorId: id,
        targetId: result.args.target_id,
        potionType: result.args.potion_type,
        ...(id === maid ? { abilityId: a.id } : {}),
      },
      lastRelease,
    );
  }
  for (const { id, a } of abilityActors("seer_check")) {
    const result = step(
      "seer",
      id,
      "check_identity",
      ["target_id"],
      (x) => Number.isSafeInteger(x.target_id) && n.start.includes(x.target_id),
    );
    if (!result) return facts;
    const wolf = roster.get(result.args.target_id)!.camp === Camp.Wolf;
    emit(
      "seer_checked",
      {
        actorId: id,
        targetId: result.args.target_id,
        isWerewolf: wolf,
        result: { kind: "camp", camp: wolf ? "wolf" : "good" },
        ...(id === maid ? { abilityId: a.id } : {}),
      },
      lastRelease,
    );
  }
  check(cursor === ds.length);
  return facts;
}

/**
 * 负责独立核对光蚀归档的请求资格和观察者证据。输入为原席位、归档决定与夜账本；
 * 输出为原一致性结果或明确拒绝，事件／状态重建与请求证据分开验收。
 * 增量记录只从上一 checkpoint 推导尚未归档的夜前缀，不读取 live World 或重开资源。
 * 不创建运行租约、选择实际行动或改变截止时间；失败仅拒绝归档，不改变已付资源或关闭／重开真实窗口。
 */
import { radiantNightRequestPrefix } from "./night-request-prefix";
import { Camp, Phase, Role } from "../../../core/domain/identity";
import type { RecordedDecision, RecordedGameEvent, ReproductionRecord } from "../../../recording/reproduction";
import {
  radiantCheck as check,
  radiantEqual as equal,
  radiantBorrow,
  type RadiantAbility,
  type RadiantNightEvidence,
} from "./validate";
import {
  RADIANT_ECLIPSE_EVENT_TYPES,
  readRadiantEclipseFact,
  radiantEclipseAudience,
} from "@ai-werewolf-arena/game-contract/facts/radiant-eclipse";

const stageTools: Record<string, string[]> = {
  eclipse_swallow: ["swallow_skill"],
  radiant_shelter: ["cast_shelter"],
  dreamer: ["dream"],
  witch: ["use_potion"],
  seer: ["check_identity"],
  wolf_discussion: ["speak_to_wolves"],
  wolf_vote: ["kill_vote"],
  sheriff_nomination: ["run_for_sheriff"],
  sheriff_withdraw: ["run_for_sheriff"],
  sheriff_vote: ["vote_for_sheriff"],
  sheriff_pk_vote: ["vote_for_sheriff"],
  sheriff_speech: ["speak"],
  sheriff_campaign_speech: ["speak"],
  sheriff_pk_speech: ["speak"],
  sheriff_choose_direction: ["choose_direction"],
  sheriff_badge_choice: ["choose_badge_successor"],
  day_speech: ["speak"],
  last_words: ["speak"],
  voting: ["vote"],
  exile_pk_vote: ["vote"],
  exile_pk_speech: ["speak"],
  on_pre_election: ["self_destruct"],
  on_pre_vote: ["self_destruct"],
};
const stageKinds: Record<string, RadiantAbility["kind"]> = {
  radiant_shelter: "shelter",
  dreamer: "dream",
  witch: "potion",
  seer: "seer_check",
};
const publicEvents = new Set([
  "phase_changed",
  "day_speech",
  "night_resolved",
  "vote_summary",
  "voted_out",
  "game_over",
  "wolf_self_destruct",
  "last_words_granted",
  "last_words_spoken",
  "sheriff_nomination_summary",
  "sheriff_withdraw_summary",
  "sheriff_candidates_finalized",
  "sheriff_pk_started",
  "exile_pk_started",
  "sheriff_vote_summary",
  "sheriff_badge_transferred",
  "sheriff_badge_destroyed",
  "sheriff_direction_chosen",
]);
const actorEvents = new Set([
  "ability_changed",
  "seer_checked",
  "dream_applied",
  "witch_potion_used",
  "witch_potion_skipped",
]);
const packEvents = new Set([
  "wolf_tactical_order",
  "wolf_discussion",
  "wolf_discussion_ended",
  "wolf_kill_vote_cast",
]);
function project(e: RecordedGameEvent, actor: number): Record<string, unknown> | null {
  if ((RADIANT_ECLIPSE_EVENT_TYPES as readonly string[]).includes(e.type)) {
    const fact = readRadiantEclipseFact(e.type, e.payload);
    return fact && radiantEclipseAudience(e.type, fact).includes(actor) ? { ...fact } : null;
  }
  if (packEvents.has(e.type)) {
    if (!e.audience?.includes(actor)) return null;
    return { ...e.payload };
  }
  if (actorEvents.has(e.type) && e.payload.actorId !== actor) return null;
  if (!publicEvents.has(e.type) && !actorEvents.has(e.type)) return null;
  if (e.type === "ability_changed") {
    const { sourceDisclosed: _secret, ...p } = e.payload;
    return p;
  }
  if (e.type === "vote_summary") {
    const { tally: _derived, ...p } = e.payload;
    return p;
  }
  return { ...e.payload };
}
export function validateRadiantRequests(
  record: ReproductionRecord,
  context: {
    roster: ReadonlyMap<number, ReproductionRecord["metadata"]["players"][number]>;
    alive: ReadonlySet<number>;
    nights: ReadonlyMap<number, RadiantNightEvidence>;
    maid: number;
    count: number;
    seer: number;
    witch: number;
    dreamer: number;
  },
): void {
  const { roster, nights, maid } = context,
    last = record.checkpoints.at(-1)!;
  const inferred = new Map<
    number,
    {
      start: number[];
      before: Map<number, RadiantAbility | undefined>;
      previousSwallow: { day: number; targetId: number | null } | undefined;
    }
  >();
  const info = (day: number) => {
    const n = nights.get(day);
    if (n) return n;
    let value = inferred.get(day);
    if (value) return value;
    // Trace 的增量快照仍保留上一 checkpoint；尚未形成新 checkpoint 的请求只能
    // 从该历史前缀推导，不拿未发表的最终库存回填，也不声称请求已经完成。
    check(!record.finalized && day === last.snapshot.day);
    const before = new Map(
      last.players.map((p) => [
        p.id,
        structuredClone(
          Object.values((p.privateState.abilities ?? {}) as Record<string, RadiantAbility>).find(
            (a) => a.source.kind === "native",
          ),
        ),
      ]),
    );
    for (const a of before.values())
      if (a?.kind === "potion")
        Object.assign(a.state, {
          healUsedThisNight: false,
          poisonUsedThisNight: false,
          canSelfHeal: false,
        });
    const history = (
      last.players.find((p) => p.id === maid)!.privateState.eclipse as {
        history: Array<{ day: number; targetId: number | null }>;
      }
    ).history;
    value = {
      start: last.players.filter((p) => p.alive).map((p) => p.id),
      before,
      previousSwallow: history.at(-1),
    };
    inferred.set(day, value);
    return value;
  };
  const swallow = (day: number) => {
    const n = info(day),
      ds = record.decisions.filter(
        (d) => d.day === day && d.stage === "eclipse_swallow" && d.actorId === maid,
      ),
      d = ds[0];
    const a = d?.outcome.kind === "action" ? d.outcome.action : null;
    const target = a?.name === "swallow_skill" ? a.args.target_id : null;
    const legal =
      !!d &&
      d.settleOrder !== undefined &&
      a?.name === "swallow_skill" &&
      day >= 2 &&
      n.start.includes(maid) &&
      (target === null ||
        (n.start.includes(target) &&
          roster.get(target)!.camp === Camp.Good &&
          !(n.previousSwallow?.day === day - 1 && n.previousSwallow.targetId === target)));
    const original = legal && target !== null ? n.before.get(target) : undefined;
    return {
      d,
      legal,
      target,
      borrowed: original ? radiantBorrow(original, target!, day) : undefined,
    };
  };
  const settled = record.decisions
    .filter((d) => d.settleOrder !== undefined)
    .map((d) => d.settleOrder!)
    .sort((a, b) => a - b);
  check(settled.every((value, index) => value === index + 1));
  for (const d of record.decisions)
    check(
      d.settleOrder === undefined
        ? d.outcome.kind === "pending"
        : d.outcome.kind !== "pending" && d.openedAfterSettlement < d.settleOrder,
    );
  const prefixes = new Map(
    [
      ...new Set(record.decisions.filter((d) => d.request.phase === Phase.Night).map((d) => d.day)),
    ].map((day) => [day, radiantNightRequestPrefix(record, day, info(day), roster)]),
  );
  const speechCounts = new Map<string, number>();
  const exileRounds = new Map<number, number>();
  const release = (e: RecordedGameEvent, day: number) => {
    const n = prefixes
      .get(day)
      ?.find((f) => f.event.type === e.type && equal(f.event.payload, e.payload));
    if (n) return n.release;
    // 未结算请求以最大安全整数阻止相关事实提前释放，接受请求本身不能证明领域效果已提交。
    // 不同事件按其夜间、白天、选举或徽章决策前缀取证，不能共用整局最后一次结算。
    const max = (rows: RecordedDecision[]) =>
      Math.max(0, ...rows.map((d) => d.settleOrder ?? Number.MAX_SAFE_INTEGER));
    const night = record.decisions.filter((d) => d.day === day && d.request.phase === Phase.Night);
    if (e.type === "phase_changed")
      return e.payload.phase === Phase.Night
        ? max(record.decisions.filter((d) => d.day < Number(e.payload.day)))
        : e.payload.phase === Phase.Day
          ? max(night)
          : e.payload.phase === Phase.Voting
            ? max(record.decisions.filter((d) => d.day === day && d.request.phase === Phase.Day))
            : max(record.decisions.filter((d) => d.day <= day));
    if (e.type === "night_resolved")
      return Math.max(
        max(night),
        day === 1
          ? max(
              record.decisions.filter(
                (d) =>
                  d.day === 1 &&
                  [
                    "sheriff_nomination",
                    "sheriff_withdraw",
                    "sheriff_campaign_speech",
                    "sheriff_vote",
                    "sheriff_pk_vote",
                    "sheriff_pk_speech",
                    "on_pre_election",
                  ].includes(d.stage),
              ),
            )
          : 0,
      );
    if (e.type === "game_over") return max(record.decisions.filter((d) => d.day <= day));
    if (e.type === "eclipse_native_restored" || e.type === "eclipse_lease_closed")
      return max(night);
    const stages: Record<string, string[]> = {
      day_speech: ["day_speech", "sheriff_campaign_speech", "sheriff_pk_speech", "exile_pk_speech"],
      last_words_spoken: ["last_words"],
      sheriff_badge_transferred: ["sheriff_badge_choice"],
      sheriff_badge_destroyed: ["sheriff_badge_choice"],
      sheriff_direction_chosen: ["sheriff_choose_direction"],
      vote_summary: ["voting", "exile_pk_vote"],
      voted_out: ["voting", "exile_pk_vote"],
      sheriff_nomination_summary: ["sheriff_nomination"],
      sheriff_withdraw_summary: ["sheriff_nomination", "sheriff_withdraw"],
      sheriff_candidates_finalized: ["sheriff_nomination", "sheriff_withdraw"],
      sheriff_pk_started: ["sheriff_vote"],
      sheriff_vote_summary: [
        "sheriff_nomination",
        "sheriff_withdraw",
        "sheriff_vote",
        "sheriff_pk_vote",
      ],
    };
    if (e.type === "day_speech") {
      const key = day + "/" + e.payload.actorId,
        index = speechCounts.get(key) ?? 0;
      const candidates = record.decisions
        .filter(
          (d) =>
            d.day === day &&
            d.actorId === e.payload.actorId &&
            stages.day_speech!.includes(d.stage) &&
            d.outcome.kind === "action" &&
            d.outcome.action?.name === "speak",
        )
        .sort((a, b) => a.settleOrder! - b.settleOrder!);
      const selected = candidates[index];
      speechCounts.set(key, index + 1);
      check(
        selected?.outcome.kind === "action" &&
          selected.outcome.action?.name === "speak" &&
          selected.outcome.action.args.text.trim().length > 0,
      );
      check(
        selected.outcome.action.args.text
          .replace(/^(\s*\[(上帝|法官|系统|God|Judge|System)\]\s*)+/gi, "")
          .trim() === e.payload.text,
      );
      return selected.settleOrder!;
    }
    if (e.type === "sheriff_vote_summary")
      return max(
        record.decisions.filter(
          (d) =>
            d.day === day &&
            ((e.payload.round ?? 1) === 2
              ? d.stage === "sheriff_pk_vote"
              : ["sheriff_nomination", "sheriff_withdraw", "sheriff_vote"].includes(d.stage)),
        ),
      );
    if (e.type === "vote_summary" || e.type === "voted_out" || e.type === "exile_pk_started") {
      const round =
        e.type === "vote_summary" ? Number(e.payload.round ?? 1) : (exileRounds.get(day) ?? 1);
      const boundary = max(
        record.decisions.filter(
          (d) => d.day === day && d.stage === (round === 2 ? "exile_pk_vote" : "voting"),
        ),
      );
      if (e.type === "exile_pk_started") exileRounds.set(day, 2);
      return boundary;
    }
    const relevant = stages[e.type];
    if (relevant)
      return max(
        record.decisions.filter(
          (d) =>
            d.day === day &&
            relevant.includes(d.stage) &&
            (typeof (
              e.payload.actorId ??
              e.payload.playerId ??
              e.payload.fromId ??
              e.payload.sheriffId
            ) !== "number" ||
              d.actorId ===
                (e.payload.actorId ??
                  e.payload.playerId ??
                  e.payload.fromId ??
                  e.payload.sheriffId)),
        ),
      );
    if (e.type === "last_words_granted")
      return Math.max(
        max(night),
        day === 1
          ? max(
              record.decisions.filter(
                (d) =>
                  d.day === 1 &&
                  [
                    "sheriff_nomination",
                    "sheriff_withdraw",
                    "sheriff_campaign_speech",
                    "sheriff_vote",
                    "sheriff_pk_vote",
                    "sheriff_pk_speech",
                    "on_pre_election",
                  ].includes(d.stage),
              ),
            )
          : 0,
        e.payload.phase === Phase.Voting
          ? max(
              record.decisions.filter(
                (d) => d.day === day && ["voting", "exile_pk_vote"].includes(d.stage),
              ),
            )
          : 0,
      );
    if (e.type === "wolf_self_destruct")
      return max(record.decisions.filter((d) => d.day === day && d.stage === e.payload.window));
    return Number.MAX_SAFE_INTEGER;
  };
  const published = new Map(
    [...roster.keys()].map((id) => [
      id,
      [] as Array<{ type: string; payload: Record<string, unknown>; release: number; day: number }>,
    ]),
  );
  let eventDay = 1;
  for (const e of record.events) {
    if (e.type === "phase_changed") eventDay = Number(e.payload.day);
    const boundary = release(e, eventDay);
    for (const id of roster.keys()) {
      const p = project(e, id);
      if (p)
        published.get(id)!.push({ type: e.type, payload: p, release: boundary, day: eventDay });
    }
  }
  const used = new Set<string>();
  for (const d of record.decisions) {
    const key = `${d.actorId}/${d.day}/${d.stage}/${d.turn}`;
    check(!used.has(key));
    used.add(key);
    if (d.outcome.kind === "action" && d.outcome.action?.name === "speak")
      check(
        Object.keys(d.outcome.action.args).length === 1 &&
          Object.hasOwn(d.outcome.action.args, "text"),
      );
    check(
      roster.has(d.actorId) &&
        d.request.actorId === d.actorId &&
        d.request.context.day === d.day &&
        d.request.context.stage === d.stage &&
        stageTools[d.stage] &&
        equal(d.request.allowedTools, stageTools[d.stage]),
    );
    const ctx = d.request.context,
      isNight = [
        "eclipse_swallow",
        "radiant_shelter",
        "dreamer",
        "witch",
        "seer",
        "wolf_discussion",
        "wolf_vote",
      ].includes(d.stage);
    if (isNight) {
      const allowed = [
        "day",
        "stage",
        "visible_events",
        "turn_constraints",
        "allow_fallback",
        "action_failure_policy",
        ...(d.stage === "eclipse_swallow" ? ["swallow_candidates"] : []),
        ...(d.stage === "radiant_shelter" ? ["ability_id", "shelter_candidates"] : []),
        ...(["witch", "seer", "dreamer"].includes(d.stage) ? ["ability_id"] : []),
        ...(d.stage === "witch" ? ["wolf_target"] : []),
        ...(d.stage === "wolf_discussion" ? ["round", "max_rounds"] : []),
      ];
      check(Object.keys(ctx).every((key) => allowed.includes(key)));
      const n = info(d.day),
        s = swallow(d.day),
        kind = stageKinds[d.stage];
      check(
        d.request.phase === Phase.Night &&
          n.start.includes(d.actorId) &&
          ctx.allow_fallback === false &&
          ctx.action_failure_policy === "error",
      );
      check(
        ctx.turn_constraints.min_valid_actions === 1 &&
          ctx.turn_constraints.max_valid_actions === 1 &&
          equal(ctx.turn_constraints.required_any_tools, d.request.allowedTools),
      );
      if (d.stage === "eclipse_swallow") {
        check(d.day >= 2 && d.actorId === maid && d.turn === 1 && ctx.ability_id === undefined);
        const candidates = n.start.filter(
          (id) =>
            roster.get(id)!.camp === Camp.Good &&
            !(n.previousSwallow?.day === d.day - 1 && n.previousSwallow.targetId === id),
        );
        check(equal(ctx.swallow_candidates, candidates) && ctx.shelter_candidates === undefined);
      } else if (kind) {
        const a = d.actorId === maid ? s.borrowed : n.before.get(d.actorId);
        check(
          a &&
            a.kind === kind &&
            d.day >= a.startsOnDay &&
            ctx.ability_id === a.id &&
            d.turn === 1 &&
            (d.actorId === maid
              ? s.legal && s.d!.settleOrder! <= d.openedAfterSettlement
              : !s.legal || s.target !== d.actorId),
        );
        if (kind === "shelter") {
          const ids = n.start.filter(
            (id) =>
              id !== d.actorId && !(a.state.lastDay === d.day - 1 && a.state.lastTarget === id),
          );
          check(equal(ctx.shelter_candidates, ids));
        }
        if (kind === "potion") {
          check(d.actorId !== maid || a.state.heal > 0 || a.state.poison > 0);
          if (a.state.heal > 0) {
            const votes = record.decisions.filter(
                (x) =>
                  x.day === d.day &&
                  x.stage === "wolf_vote" &&
                  x.settleOrder !== undefined &&
                  x.settleOrder <= d.openedAfterSettlement,
              ),
              tally = new Map<number, number>();
            for (const v of votes) {
              const a = v.outcome.kind === "action" ? v.outcome.action : null;
              if (a?.name === "kill_vote" && !a.args.abstain && a.args.target_id !== null)
                tally.set(a.args.target_id, (tally.get(a.args.target_id) ?? 0) + 1);
            }
            const knife = [...tally].sort(([a, x], [b, y]) => y - x || a - b)[0]?.[0] ?? null;
            check(ctx.wolf_target === knife);
          } else check(!Object.hasOwn(ctx, "wolf_target"));
        }
      } else {
        const wolves = n.start.filter((id) => roster.get(id)!.role === Role.Wolf),
          holders = wolves.length ? wolves : n.start.includes(maid) ? [maid] : [];
        check(
          ctx.ability_id === undefined &&
            (d.stage === "wolf_discussion" ? wolves : holders).includes(d.actorId),
        );
        if (d.stage === "wolf_discussion") {
          check(d.turn <= 3 && ctx.round === d.turn && ctx.max_rounds === 3);
          for (const prior of record.decisions.filter(
            (x) =>
              x.day === d.day && x.stage === d.stage && x.actorId === d.actorId && x.turn < d.turn,
          )) {
            const a = prior.outcome.kind === "action" ? prior.outcome.action : null;
            check(
              a?.name === "speak_to_wolves" &&
                a.args.end_chat === false &&
                prior.settleOrder! <= d.openedAfterSettlement,
            );
          }
        } else check(d.turn === 1);
      }
      for (const name of ["shelter_candidates", "swallow_candidates"] as const)
        if (Object.hasOwn(ctx, name))
          check(
            d.stage === (name === "shelter_candidates" ? "radiant_shelter" : "eclipse_swallow"),
          );
    } else {
      check(
        ctx.ability_id === undefined &&
          !Object.hasOwn(ctx, "shelter_candidates") &&
          !Object.hasOwn(ctx, "swallow_candidates"),
      );
      if (d.stage === "on_pre_election" || d.stage === "on_pre_vote")
        check(
          roster.get(d.actorId)!.role === Role.Wolf &&
            d.request.phase === (d.stage === "on_pre_vote" ? Phase.Voting : Phase.Day),
        );
    }
    const visible = ctx.visible_events;
    check(visible.every((v, i) => v.seq === i + 1));
    const sources = published.get(d.actorId)!.filter((v) => v.release <= d.openedAfterSettlement);
    let expected = sources.map(({ release: _release, day: _day, ...v }) => v);
    if (!record.finalized) {
      const allPublished = published.get(d.actorId)!.filter((v) => v.day === d.day);
      const extra = (prefixes.get(d.day) ?? [])
        .filter((f) => f.release <= d.openedAfterSettlement)
        .flatMap((f) => {
          const p = project({ ...f.event, timestamp: 0 }, d.actorId);
          return p && !allPublished.some((v) => v.type === f.event.type && equal(v.payload, p))
            ? [{ type: f.event.type, payload: p }]
            : [];
        });
      expected = [...expected, ...extra];
    }
    check(
      equal(
        visible.map(({ seq: _seq, ...v }) => v),
        expected,
      ),
    );
    const latestPhase = [...visible].reverse().find((v) => v.type === "phase_changed");
    check(
      !!latestPhase &&
        latestPhase.payload.phase === d.request.phase &&
        latestPhase.payload.day === d.day,
    );
  }
}

/**
