  beginNobleBodyNight(fixture.world, 1, () => true);
  const request: ActionRequest = {
    actorId: 2,
    phase: Phase.Night,
    allowedTools: ["protect_secret_body"],
    context: {
      day: 1,
      stage: "secret_body",
      visible_events: [],
