                      return Response.json({
                        id: "gift-stop",
                        object: "chat.completion",
                        created: 1,
                        model: "synthetic",
                        choices: [
                          {
                            index: 0,
                            finish_reason: "stop",
                            message: { role: "assistant", content: "Stopped after refusals." },
                          },
                        ],
                        usage: { prompt_tokens: 1, completion_tokens: 1, total_tokens: 2 },
                      });
                    replied.add(turnId);
                    sdkPrompts.push(prompt);
                    consumed++;
                    if (locale === "en")
                      expect(JSON.stringify(body.messages)).not.toMatch(/\p{Script=Han}/u);
                    const actions = turn.invalidActions ?? [turn.action!];
                    return Response.json({
                      id: "gift-gun",
                      object: "chat.completion",
                      created: 1,
                      model: "synthetic",
                      choices: [
                        {
                          index: 0,
                          finish_reason: "tool_calls",
                          message: {
                            role: "assistant",
                            content: null,
                            tool_calls: actions.map((action, i) => ({
                              id: `gift-${consumed}-${i}`,
                              type: "function",
                              function: {
                                name: "submit_action",
                                arguments: JSON.stringify({
                                  turn_id: turnId,
                                  action: action.name,
                                  arguments: action.args,
