        await acpProvider.close();
        expect(sdkProvider.runtimeState.turns).toBe(0);
        expect(acpProvider.runtimeState.pool.sessions).toBe(0);
      } finally {
        await sdkProvider.close();
        await acpProvider.close();
        await client?.close();
        await control?.close({ force: true });
        server.stop(true);
      }
    });

