            },
          },
        };
      if (profile.metadata.role === Role.Villager)
        return {
          ...profile,
          runtime: {
            ...profile.runtime,
            wolfTeam: {
              recognizedByPack: false,
              recognizes: [Role.Seer],
              canChat: false,
              canVoteForKill: false,
            },
          },
