      p.vote(1, blocked ? [1, 2, 3, 4, 5, 6] : [1, 2, 4, 5, 6], 1);
      p.lastWords(1, 1);
      p.wolves(2, [4], 5);
      p.add(2, [5], "guard", {
        name: "guard",
        args: { target_id: blocked ? 6 : null, abstain: !blocked },
      });
      p.add(2, [2], "seer", { name: "check_identity", args: { target_id: 4 } });
      p.speech(2, blocked ? [2, 3, 4, 6] : [2, 4, 6]);
