      expect(
        game.replay.events
          .filter((event) => event.type === "night_resolved")
          .map((event) => event.payload.deaths),
      ).toEqual([blocked ? [] : [3], [5]]);
      const checks = [
        { actorId: 2, targetId: 1, isWerewolf: true, result: { kind: "camp", camp: "wolf" } },
        { actorId: 2, targetId: 4, isWerewolf: true, result: { kind: "camp", camp: "wolf" } },
