import { ObservedPlayersActionProvider } from "../../../../src/app/observed-players-action-provider";
import { scholarMentorStateForRole } from "../../../../src/game/mechanisms/roles/scholar_mentor/ports";
for (const variant of [
  "missing-wolf-chat",
  "invalid-wolf-chat",
  "missing-wolf-vote",
  "invalid-wolf-vote",
  "missing-choice",
  "invalid-mode",
  "invalid-target",
