function setup(campInspection?: HiddenWolfCampInspectionPolicy, locale: "en" | "zh-CN" = "en") {
  const board: BoardConfig = {
    ...sixPlayerMvpConfig,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
