  const seen: any[] = [];
  const provider = {
    async getAction(r: ActionRequest) {
      if (r.actorId === 1) {
        const toolErrors: unknown[] = [];
        if (r.context.stage === spec.stage) {
          const args =
            spec.kind === "potion"
