const setup = (
  g: SetupFixture,
  getAction: (r: ActionRequest) => Promise<ToolCall | null> = async () => choose(2),
  isCurrent = () => true,
) =>
  new WildChildSetupWindow(g.world, new ToolGateway(), g.events, { get requestFactory() { return GameActionRequestFactory; } }).execute(
    g.config,
