      const deaths = r.events.filter((e) => e.type === "night_resolved");
      expect(deaths.map((e) => e.payload.deaths)).toEqual(
        lastWolf ? [[11], [9], []] : raw ? [[], [11], [3, 7]] : [[5], [11], [3, 7]],
      );
