        const events = g.phaseManager.getEvents();
        expect(events.filter((e) => e.type === "red_moon_exile_delayed")).toHaveLength(1);
        expect(events.filter((e) => e.type === "red_moon_delay_expired")).toHaveLength(
          wins ? 0 : 1,
