        expect(events.some((e) => e.type === "voted_out" && e.payload.target === 4)).toBe(false);
        expect(
          seen.some(
            (r) =>
              r.actorId === 4 &&
              r.context.day === (wins ? 4 : 3) &&
              r.allowedTools.includes("kill_vote"),
