              return { name: "check_identity", args: { target_id: wolves[0]! } };
            if (stage === "sheriff_nomination")
              return { name: "run_for_sheriff", args: { run: false } };
            if (stage === "on_pre_election" || stage === "on_pre_vote") return null;
            if (stage === "voting") {
              const exiled = cycle === 1 ? wolves[2]! : wolves[1]!;
              return {
                name: "vote",
                args: {
                  target_id: r.actorId === exiled ? null : exiled,
                  abstain: r.actorId === exiled,
                },
              };
            }
            return native.getAction(r);
          },
        };
        await game.phaseManager.runSingleCycle(provider, 30);
        expect(game.world.getAliveEntityIds()).toContain(scholar);
        expect(game.world.getAliveEntityIds()).toContain(mentor);
        const before = game.phaseManager.getEvents().length;
        cycle = 2;
        await game.phaseManager.runSingleCycle(provider, 30);
        const events = game.phaseManager.getEvents().slice(before),
          night = events.find((e) => e.type === "night_resolved")!;
        expect(night).toBeDefined();
        const dead = night.payload.deaths as number[];
        const bonus = events.filter((e) => e.type === "modifier_bonus_resolved"),
          conflict = events.filter((e) => e.type === "modifier_conflict_resolved");
        const charge = scholarMentorStateForRole(
          game.world.getComponent(scholar, COMPONENT.Role), () => game.world.getComponent(scholar, COMPONENT.Camp)
        )!;
        expect(charge.history).toHaveLength(1);
        expect(charge.history[0]!.day).toBe(2);
        expect(charge.history[0]!.targetId).toBe(target);
        expect(charge.remaining[variant.startsWith("weaken") ? "weaken" : "enhance"]).toBe(0);
        if (variant === "same-good") {
          expect(dead).toContain(seer);
          expect(requests.filter((r) => r.context.stage === "seer")).toHaveLength(1);
          expect(conflict).toHaveLength(1);
          expect(bonus).toHaveLength(0);
        } else if (variant === "different-wolves") {
          expect(dead).toContain(mentor);
          expect(dead).not.toContain(wolves[0]!);
          expect(conflict).toHaveLength(1);
          expect(bonus).toHaveLength(0);
        } else if (variant === "weaken-wolf") {
          expect(dead).not.toContain(villagers[0]!);
          expect(requests.filter((r) => r.context.stage === "wolf_vote")).toHaveLength(0);
        } else if (variant === "weaken-witch-heal") {
          expect(dead).not.toContain(villagers[0]!);
          const wr = requests.find((r) => r.context.stage === "witch")!;
          expect(wr.context.modifier_poison_blocked).toBe(true);
        } else {
          expect(bonus).toHaveLength(1);
          expect(bonus[0]!.payload.actorId).toBe(target);
          if (variant === "enhance-guard") expect(dead).not.toContain(villagers[0]!);
          if (variant === "enhance-seer") {
            expect(bonus[0]!.payload.isWerewolf).toBe(false);
            expect(requests.filter((r) => r.context.stage === "seer")).toHaveLength(1);
          }
          if (variant === "enhance-spent-poison") expect(dead).toContain(wolves[0]!);
          if (variant === "enhance-knife") {
            expect(dead).toContain(villagers[0]!);
            expect(dead).not.toContain(villagers[1]!);
            const wr = requests.find((r) => r.context.stage === "witch")!;
            expect(wr.context.wolf_targets).toEqual(
              expect.arrayContaining([villagers[0]!, villagers[1]!]),
            );
          }
        }
        for (const e of events.filter(
          (e) => e.type === "modifier_choice_committed" || e.type === "modifier_bonus_resolved",
        ))
          expect(e.audience).toEqual([e.payload.actorId as number]);
        for (const e of conflict) expect(e.audience).toEqual([]);
      },
      120000,
    );

/**
 * 交互场景测试：验证时间狼妃原生效果 scope 在进行中撤权后不提交过期回执。输入为原角色／阶段／事件及修改矩阵的实际周期；来源错误、未发布及已付款前缀为明确预期，不把 scope 文件误认作纯 mock 测试。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { timeConsortTwelveConfig } from "../../../../src/runtime/scenarios/time_consort_twelve";
import {
  COMPONENT,
  Role,
  PotionType,
  createRandom,
  randomDraws,
  type RoleComponent,
  type ActionRequest,
  type ToolCall,
} from "../../../../src/core";
import { ObservedBot } from "../../../../src/ai/agents/providers/observed_bot";
import { ObservedPlayersActionProvider } from "../../../../src/app/observed-players-action-provider";
import { getTimeConsortState } from "../../../../src/game/mechanisms/roles/time_wolf_consort/ports";
for (const [role, stage, event] of [
  [Role.Guard, "guard", "guard_applied"],
  [Role.Seer, "seer", "seer_checked"],
  [Role.Witch, "witch", "witch_potion_used"],
] as const)
  for (const mutation of [
    "replace",
    "delete",
    "replace-state",
    "disable",
    "expire",
    "expiry-accessor",
    "activation-accessor",
    "death-accessor",
  ] as const)
    for (const timing of ["during-action", "before-stage"] as const)
      test(
        "Consort rejects asynchronous ability " + mutation + "/" + stage + "/" + timing,
        async () => {
          const config = structuredClone(timeConsortTwelveConfig),
            random = createRandom("consort-scope:" + stage + ":" + mutation);
          const game = bootstrapGame(config, { random });
          const id = (name: Role) =>
            game.playerIds.find(
              (id) => game.world.getComponent(id, COMPONENT.Role)?.role === name,
            )!;
          const actor = id(role),
            consort = id(Role.TimeWolfConsort),
            target = id(Role.Wolf);
          const strategies = new Map(
            game.playerIds.map((i) => [
              i,
              new ObservedBot(randomDraws(random.fork("players").fork("id:" + i)), "active"),
            ]),
          );
          const native = new ObservedPlayersActionProvider(game.world, strategies);
          let mutated = false;
          const provider = {
            async getAction(r: ActionRequest): Promise<ToolCall | null> {
              if (
                (timing === "during-action" && r.actorId === actor && r.context.stage === stage) ||
                (timing === "before-stage" && r.context.stage === "time_consort_lock")
              ) {
                const p = game.world.getComponent(actor, COMPONENT.Role)!;
                const abilities = (p.privateState as { readonly abilities?: unknown })
                    .abilities as Record<string, Record<string, unknown>>,
                  key = Object.keys(abilities)[0]!,
                  old = abilities[key]!;
                expect(old).toBeDefined();
                mutated = true;
                if (mutation === "replace") abilities[key] = { ...old };
                else if (mutation === "delete") delete abilities[key];
                else if (mutation === "replace-state")
                  old.state = { ...(old.state as Record<string, unknown>) };
                else if (mutation === "disable") old.disabled = true;
                else if (mutation === "expire") old.deathExpired = true;
                else if (mutation === "expiry-accessor")
                  Object.defineProperty(old, "expiresAfterDay", {
                    get: () => 0,
                    configurable: true,
                  });
                else if (mutation === "activation-accessor")
                  Object.defineProperty(old, "activation", {
                    get: () => "lucky",
                    configurable: true,
                  });
                else
                  Object.defineProperty(old, "deathExpired", {
                    get: () => true,
                    configurable: true,
                  });
                if (timing === "before-stage")
                  return { name: "lock_time", args: { target_id: target, abstain: false } };
                if (stage === "guard")
                  return { name: "guard", args: { target_id: target, abstain: false } };
                if (stage === "seer")
                  return { name: "check_identity", args: { target_id: target } };
                return {
                  name: "use_potion",
                  args: { target_id: target, potion_type: PotionType.Poison },
                };
              }
              if (r.context.stage === "time_consort_lock")
                return { name: "lock_time", args: { target_id: target, abstain: false } };
              if (r.context.stage === "guard")
                return { name: "guard", args: { target_id: null, abstain: true } };
              if (r.context.stage === "witch")
                return {
                  name: "use_potion",
                  args: { target_id: r.actorId, potion_type: PotionType.None },
                };
              return native.getAction(r);
            },
          };
          await expect(game.phaseManager.runSingleCycle(provider, 30)).rejects.toThrow(
            "time_consort",
          );
          expect(mutated).toBe(true);
          expect(
            game.phaseManager
              .getEvents()
              .some((e) => e.type === event && e.payload.actorId === actor),
          ).toBe(false);
          const state = getTimeConsortState(
            game.world.getComponent(consort, COMPONENT.Role), () => game.world.getComponent(consort, COMPONENT.Camp)
          )!;
          expect(state.history).toHaveLength(timing === "before-stage" ? 0 : 1);
          expect(state.triggeredDay).toBeNull();
        },
      );

for (const ownerRole of [Role.Villager, Role.TimeWolfConsort] as const)
  for (const mutation of ["getter", "inherited-getter", "undefined-field"] as const)
    test(
      "Consort rejects absent ability-container injection/" + ownerRole + "/" + mutation,
      async () => {
        const config = structuredClone(timeConsortTwelveConfig),
          random = createRandom("consort-container:" + ownerRole + ":" + mutation);
        const game = bootstrapGame(config, { random });
        const id = (name: Role) =>
          game.playerIds.find(
            (id) => game.world.getComponent(id, COMPONENT.Role)?.role === name,
          )!;
        const actor = id(ownerRole),
          guard = id(Role.Guard),
          target = id(Role.Wolf);
        const role = game.world.getComponent(actor, COMPONENT.Role)!;
        expect(Object.hasOwn(role.privateState, "abilities")).toBe(false);
        const donor = structuredClone(
          (
            game.world.getComponent(guard, COMPONENT.Role)!.privateState as {
              readonly abilities?: unknown;
            }
          ).abilities,
        );
        let reads = 0,
          mutated = false;
        const provider = {
          async getAction(request: ActionRequest): Promise<ToolCall | null> {
            if (request.context.stage !== "time_consort_lock") throw new Error("unexpected_stage");
            mutated = true;
            if (mutation === "getter")
              Object.defineProperty(role.privateState, "abilities", {
                configurable: true,
                get: () => {
                  reads++;
                  return donor;
                },
              });
            else if (mutation === "inherited-getter")
              Object.setPrototypeOf(role.privateState, {
                get abilities() {
                  reads++;
                  return donor;
                },
              });
            else
              Object.defineProperty(role.privateState, "abilities", {
                configurable: true,
                value: undefined,
              });
            return { name: "lock_time", args: { target_id: target, abstain: false } };
          },
        };
        await expect(game.phaseManager.runSingleCycle(provider, 30)).rejects.toThrow(
          "time_consort",
        );
        expect(mutated).toBe(true);
        expect(reads).toBe(0);
        expect(
          game.phaseManager
            .getEvents()
            .some(
              (e) =>
                e.type === "guard_applied" ||
                e.type === "seer_checked" ||
                e.type === "witch_potion_used",
            ),
        ).toBe(false);
      },
    );

/**
 * 交互场景测试：验证时间狼妃两种反射 scope 的救人、狼刀、跳过与重复控制。输入为原六种变体和有种子原生周期；回执、库存、反射效果及非法重复错误为字面预期，政策、RNG 和控制表保持原值。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { timeConsortTwelveConfig } from "../../../../src/runtime/scenarios/time_consort_twelve";
import {
  COMPONENT,
  Role,
  PotionType,
  createRandom,
  randomDraws,
  type RoleComponent,
  type ActionRequest,
  type ToolCall,
} from "../../../../src/core";
import { ObservedBot } from "../../../../src/ai/agents/providers/observed_bot";
import { ObservedPlayersActionProvider } from "../../../../src/app/observed-players-action-provider";
import { getTimeConsortState } from "../../../../src/game/mechanisms/roles/time_wolf_consort/ports";
for (const scope of ["whole_night", "first_effect"] as const)
  for (const variant of ["heal", "knife", "pass", "self", "repeat", "repeat-lock"] as const)
    test("Consort actual effect controls/" + scope + "/" + variant, async () => {
      const config = structuredClone(timeConsortTwelveConfig);
      config.timeConsort!.reflectionScope = scope;
      const random = createRandom("consort-controls:" + scope + ":" + variant),
        game = bootstrapGame(config, { random });
      const ids = (name: Role) =>
        game.playerIds.filter(
          (id) => game.world.getComponent(id, COMPONENT.Role)?.role === name,
        );
      const consort = ids(Role.TimeWolfConsort)[0]!,
        guard = ids(Role.Guard)[0]!,
        witch = ids(Role.Witch)[0]!,
        seer = ids(Role.Seer)[0]!,
        wolves = ids(Role.Wolf),
        villagers = ids(Role.Villager);
      const locked =
          variant === "self"
            ? guard
            : variant === "repeat" || variant === "repeat-lock"
              ? wolves[0]!
              : villagers[0]!,
        killed =
          variant === "self"
            ? guard
            : variant === "repeat" || variant === "repeat-lock"
              ? villagers[0]!
              : locked;
      const strategies = new Map(
        game.playerIds.map((i) => [
          i,
          new ObservedBot(randomDraws(random.fork("players").fork("id:" + i)), "active"),
        ]),
      );
      const native = new ObservedPlayersActionProvider(game.world, strategies);
      const provider = {
        async getAction(r: ActionRequest): Promise<ToolCall | null> {
          const stage = r.context.stage;
          if (stage === "time_consort_lock")
            return {
              name: "lock_time",
              args: { target_id: variant === "pass" ? null : locked, abstain: variant === "pass" },
            };
          if (stage === "guard")
            return {
              name: "guard",
              args: {
                target_id: variant === "self" || variant === "repeat" ? locked : null,
                abstain: variant !== "self" && variant !== "repeat",
              },
            };
          if (stage === "wolf_discussion")
            return { name: "speak_to_wolves", args: { text: "End", end_chat: true } };
          if (stage === "wolf_vote")
            return { name: "kill_vote", args: { target_id: killed, abstain: false } };
          if (stage === "witch")
            return {
              name: "use_potion",
              args: {
                target_id: variant === "heal" ? locked : witch,
                potion_type: variant === "heal" ? PotionType.Heal : PotionType.None,
              },
            };
          if (stage === "seer")
            return { name: "check_identity", args: { target_id: villagers[1]! } };
          if (stage === "order_prince_choice")
            return { name: "reset_exile_vote", args: { activate: false } };
          if (stage === "sheriff_nomination")
            return { name: "run_for_sheriff", args: { run: false } };
          if (stage === "on_pre_election" || stage === "on_pre_vote") return null;
          if (stage === "voting")
            return {
              name: "vote",
              args: {
                target_id: r.actorId === wolves[1] ? null : wolves[1]!,
                abstain: r.actorId === wolves[1],
              },
            };
          return native.getAction(r);
        },
      };
      await game.phaseManager.runSingleCycle(provider, 30);
      const state = getTimeConsortState(
        game.world.getComponent(consort, COMPONENT.Role), () => game.world.getComponent(consort, COMPONENT.Camp)
      )!;
      const reflected = game.phaseManager
        .getEvents()
        .filter((e) => e.type === "time_consort_reflected");
      expect(reflected).toHaveLength(variant === "self" || variant === "repeat" ? 1 : 0);
      expect(state.triggeredDay).toBe(variant === "self" || variant === "repeat" ? 1 : null);
      const dead = game.phaseManager.getEvents().find((e) => e.type === "night_resolved")!.payload
        .deaths as number[];
      expect(dead.includes(killed)).toBe(variant !== "heal" && variant !== "self");
      expect(state.history[0]!.targetId).toBe(variant === "pass" ? null : locked);
      expect(game.world.getComponent(seer, COMPONENT.Role)).toBeDefined();
      if (variant === "repeat-lock") {
        await expect(game.phaseManager.runSingleCycle(provider, 30)).rejects.toThrow(
          "time_consort_lock_action_invalid",
        );
        expect(state.history).toHaveLength(1);
        expect(state.triggeredDay).toBeNull();
      }
      if (variant === "repeat") {
        await expect(game.phaseManager.runSingleCycle(provider, 30)).rejects.toThrow(
          "time_consort_guard_action_invalid",
        );
        expect(
          game.phaseManager.getEvents().filter((e) => e.type === "guard_applied"),
        ).toHaveLength(1);
        expect(state.history).toHaveLength(1);
      }
    });

/**
 * 场景测试验证真实 DeathResolution 的标死→野孩子整波贡献→梦记录→遗言→晚 hook 顺序。
 * 输入为合法固定角色、原榜样选择、旧注入 duck HookRegistry 和字面狼刀；预期为手写状态／事件前缀。
 * 旧 registry 不提供新增整波方法，仍必须执行内建榜样转换；无完整游戏、模型或物理传输。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { foxBoard } from "../../../support/features/cursed-fox/builders/scenario";
import { Role, Camp, Phase, DeathCause, type GameEvent } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../src/core/domain/components/names";
import { WildChildSetupWindow } from "../../../../src/game/mechanisms/roles/wild_child/setup";
import { getWildChildState } from "../../../../src/game/mechanisms/roles/wild_child/state-slot";
import { DeathResolution } from "../../../../src/game/engine/death_resolution";
import { EventRegistry } from "../../../../src/game/engine/event_registry";
import type { HookRegistry } from "../../../../src/game/mechanisms/hooks/hook_registry";
import { DreamNightFrame } from "../../../../src/game/mechanisms/roles/dreamer/night_frame";
import { ToolGateway } from "../../../../src/game/gateway/tool_gateway";
import { GameActionRequestFactory } from "../../../../src/game/engine/action_request_factory";

test("mandatory committed-wave contributions survive a legacy custom hook registry before dream and last words", async () => {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter],
    { world, boardConfig: config } = bootstrapGame(foxBoard(roles), { fixedRoles: roles }),
    events: GameEvent[] = [],
    trace: string[] = [],
    gateway = new ToolGateway();
  expect(
    await new WildChildSetupWindow(world, gateway, events, { get requestFactory() { return GameActionRequestFactory; } }).execute(
      config,
      {
        async getAction() {
          return { name: "choose_wild_model", args: { target_id: 2 } };
        },
      },
      1,
      () => true,
    ),
  ).toBe(true);
  const legacyHooks = {
    onVotedOut() {
      return null;
    },
    async onDeath() {
      trace.push("late-hook");
      return { extraDeaths: [], extraDeathSources: {} };
    },
  } as unknown as HookRegistry;
  const resolver = new DeathResolution(
    world,
    events,
    gateway,
    new EventRegistry(legacyHooks),
    {
      day: 1,
      phase: Phase.Day,
      gameOver: false,
      result: null,
    },
    config,
  );
  const dreams = new DreamNightFrame([]);
  dreams.recordDeaths = () => {
    trace.push("dream");
    expect(world.getComponent(2, COMPONENT.Alive)?.alive).toBe(false);
    expect(world.getComponent(1, COMPONENT.Camp)?.camp).toBe(Camp.Wolf);
    expect(events.some((event) => event.type === "wild_child_transformed")).toBe(true);
  };
  await resolver.resolve(
    [2],
    { 2: [DeathCause.WolfKill] },
    {
      async getAction() {
        trace.push("last-words");
        expect(getWildChildState(world.getComponent(1, COMPONENT.Role)!)?.status).toBe(
          "transformed",
        );
        return { name: "speak", args: { text: "literal last words" } };
      },
    },
    Phase.Night,
    Phase.Day,
    {},
    {
      dreams,
    },
  );
  expect(trace).toEqual(["dream", "last-words", "late-hook"]);
  const types = events.map((event) => event.type);
  expect(types).toContain("wild_child_model_eliminated");
  expect(types).toContain("last_words_granted");
  expect(types.indexOf("wild_child_model_eliminated")).toBeLessThan(
    types.indexOf("wild_child_transformed"),
  );
  expect(types.indexOf("wild_child_transformed")).toBeLessThan(types.indexOf("last_words_granted"));
});

/**
 * 死亡行动场景测试：验证配置原生许可与赠予／复制枪经过实际 DeathResolution 执行。输入为原许可、库存与受控选择；原字面预期及因果事件断言保留，不生成新规则结果。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  COMPONENT,
  DeathCause,
  Phase,
  Role,
  type BoardConfig,
  type GameEvent,
  type RoleComponent,
  type DeathActionPolicy,
  type InspectionPolicy,
} from "../../../src/core";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
} from "../../../src/runtime/config/board_definition";
import { getHunterState } from "../../../src/game/mechanisms/roles/hunter/ports";
import { getWolfKingState } from "../../../src/game/mechanisms/roles/wolf_king/ports";
import { DeathResolution } from "../../../src/game/engine/death_resolution";
import { EventRegistry } from "../../../src/game/engine/event_registry";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";

const keys = {
  [Role.Gargoyle]: "gargoyle",
  [Role.Psychic]: "psychic",
  [Role.MirrorGirl]: "mirrorGirl",
  [Role.Hunter]: "hunter",
  [Role.WolfKing]: "wolfKing",
} as const;

function fixture(
  kind: keyof typeof keys,
  parameters?: { inspectionPolicy: InspectionPolicy } | { deathActionPolicy: DeathActionPolicy },
  locale: "zh-CN" | "en" = "en",
) {
  const roles = [kind, Role.Wolf, Role.Seer, Role.Witch, Role.Villager, Role.Villager];
  const raw: BoardConfig = {
    ...sixPlayerMvpConfig,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
      count: roles.filter((x) => x === role).length,
    })),
    ...(parameters ? { [keys[kind]]: parameters } : {}),
  };
  const config = parseBoardDefinition(boardDefinitionFromConfig("role_policy", raw)).config;
  return { ...bootstrapGame(config, { fixedRoles: roles, locale }), config };
}

for (const kind of [Role.Hunter, Role.WolfKing] as const)
  test(`${kind}: death request policy edit revokes real gateway permit and late selection`, async () => {
    const game = fixture(kind),
      role = game.world.getComponent(1, COMPONENT.Role)!,
      state = kind === Role.Hunter ? getHunterState(role)! : getWolfKingState(role)!;
    const events: GameEvent[] = [],
      snapshot = { ...game.phaseManager.getSnapshot(), phase: Phase.Day };
    let asks = 0;
    const resolver = new DeathResolution(
      game.world,
      events,
      new ToolGateway(),
      new EventRegistry(),
      snapshot,
    );
    await resolver.resolve(
      [1],
      { 1: [DeathCause.Shot] },
      {
        async getAction(request) {
          if (request.allowedTools.includes("shoot")) {
            asks++;
            (
              state as {
                deathActionPolicy:
                  | "awa_qualified_sources_v1"
                  | "awa_knife_or_exile_v1"
                  | "awa_day_deaths_v1"
                  | undefined;
              }
