    day: 2,
    night: [[4], [1]],
    extra: [],
  },
  wolves_netease: {
    alive: [1, 2, 3],
    winners: [1, 2, 3],
    group: false,
    phase: Phase.Voting as const,
    day: 1,
    night: [[4]],
    extra: [],
  },
  wolves_lui: {
