  },
  dream_chain: {
    alive: [5],
    winners: [1, 2, 4, 5],
    group: false,
    phase: Phase.Voting as const,
    day: 1,
    night: [[1]],
    extra: [[2, 4]],
  },
  shot_chain: {
    alive: [1, 6],
    winners: [6],
    group: false,
