for (const kind of CUPID_CASES)
  for (const transport of ["llm", "acp", "mixed"] as const)
    test(`${kind}/${transport}: complete bilingual SDK/ACP-MCP, private recognition, chain-final winners and strict Tape`, async () => {
      for (const locale of ["zh-CN", "en"] as const) {
        const run = await runTransportGame(cupidScenario(kind), transport, locale),
          oracle = manual[kind],
          events = run.replay.events;
        const wolfWin = kind.startsWith("wolves_") || kind === "shot_chain";
        expect(run.manifest.players.filter((p) => p.alive).map((p) => p.player_id)).toEqual(
          oracle.alive,
        );
        expect(
          events
            .filter((event) => event.type === "night_resolved")
            .map((event) => event.payload.deaths),
        ).toEqual(oracle.night);
        expect(
          events
            .filter((event) => event.type === "additional_deaths")
            .map((event) => event.payload.deaths),
        ).toEqual(oracle.extra);
        expect(run.result.snapshot.result).toEqual({
          winner: oracle.group ? null : wolfWin ? Camp.Wolf : Camp.Good,
          reason: oracle.group
            ? "cupid_lovers_only_survivors"
            : wolfWin
              ? "all_good_eliminated"
              : "all_wolves_eliminated",
          outcome: {
            kind: "victory",
            primary: oracle.group
              ? { kind: "relationship", groupId: "cupid_lovers", winningPlayerIds: oracle.winners }
              : {
                  kind: "faction",
                  faction: wolfWin ? Camp.Wolf : Camp.Good,
                  winningPlayerIds: oracle.winners,
                },
            additional: [],
            winningPlayerIds: oracle.winners,
          },
          decidedAt: {
            day: oracle.day,
            phase: oracle.phase,
            checkpoint: oracle.phase === Phase.Day ? "night_settled" : "exile_settled",
          },
        });
        expect(events.filter((event) => event.type === "game_over")).toHaveLength(1);
        expect(events.at(-1)!.type).toBe("game_over");
        expect(
          events.filter((event) => event.type === "hunter_shot").map((event) => event.payload),
        ).toEqual(
          ["root_hunter", "shot_chain"].includes(kind) ? [{ hunterId: 2, targetId: 3 }] : [],
        );
        expect(
          events.filter((event) => event.type === "wolf_king_shot").map((event) => event.payload),
        ).toEqual(kind === "shot_chain" ? [{ actorId: 3, targetId: 5 }] : []);
        if (kind === "shot_chain")
          expect(events.findIndex((event) => event.type === "wolf_king_shot")).toBeLessThan(
            events.findIndex((event) => event.type === "game_over"),
          );
        if (kind === "dream_chain")
          expect(
            events
              .filter((event) => event.type === "dream_death")
              .map((event) => event.payload.targetId),
          ).toEqual([4]);
        if (kind === "beauty_poison")
          expect(events.some((event) => event.type === "charm_death")).toBe(false);
        const relation = events.find((event) => event.type === "cupid_relation_resolved")!.payload;
        for (const view of run.views) {
          const visible = view.timeline.filter((entry) => entry.kind === "event");
          expect(JSON.stringify(visible)).not.toContain("pairCamps");
          expect(
            visible.some(
              (entry) =>
                entry.kind === "event" &&
                ["cupid_relation_resolved", "lovers_death"].includes(entry.event.type),
            ),
          ).toBe(false);
          const ownRecognition = visible.filter(
            (entry) => entry.kind === "event" && entry.event.type === "lover_recognized",
          );
          expect(ownRecognition).toHaveLength(
            (relation.pairIds as number[]).includes(view.player_id) ? 1 : 0,
          );
          for (const entry of ownRecognition)
            if (entry.kind === "event")
              expect(Object.keys(entry.event.payload).sort()).toEqual(["actorId", "partnerId"]);
        }
        const request = run.record.decisions.find(
          (decision) => decision.stage === "cupid",
        )!.request;
        expect(request.context.allow_fallback).toBe(false);
        expect(request.context.turn_constraints.min_valid_actions).toBe(1);
        expect(run.record.checkpoints.at(-1)!.players.find((p) => p.id === 1)!.lovers).toEqual(
          relation as any,
        );
        expect(run.rejected.size).toBe(0);
        expect(run.acpTraces.every((r) => r.trace.rejected === 0)).toBe(true);
        if (
          transport === "llm" &&
          ["mixed_netease", "mixed_lui", "root_hunter", "dream_chain"].includes(kind)
        )
          await fs.writeFile(
            `/tmp/awa-p8-cupid-${kind}-${locale}.replay.json`,
            JSON.stringify(run.replay),
          );
      }
    }, 30000);

/**
 * Reproduction scenarios verify Cursed Fox complete recorded games preserve inspection interactions and chain-final individual or faction victory.
 * Input: Original knife, inspection, dream, mirror, lucky and king-chain transport/locale matrices with a literal result table.
 * Output and oracle: Handwritten death/survivor/winner facts and private-view assertions remain causal with the actual replay; no engine run generates expected terminal data.
 */
import { expect, test } from "bun:test";
import { Camp, DeathCause, Phase } from "../../../../src/core";
import { FOX_CASES, foxScenario } from "../../../support/features/cursed-fox/builders/scenario";
import { runTransportGame } from "../../../support/drivers/transport/run-game";
import { promises as fs } from "node:fs";
const expectations = {
  knife: { night: [], alive: [1, 2, 4, 5, 6], foxWins: true },
  inspection: { night: [1], alive: [2, 4, 5, 6], foxWins: false },
  poison_inspection: { night: [1], alive: [2, 4, 5, 6], foxWins: false },
  dream: { night: [], alive: [1, 2, 4, 5, 6], foxWins: true },
  mirror: { night: [], alive: [1, 2, 4, 5, 6], foxWins: true },
  lucky: { night: [1], alive: [2, 4, 5, 6], foxWins: false },
  fox_lucky: { night: [], alive: [1, 2, 4, 5, 6], foxWins: true },
  king_chain: { night: [], alive: [2, 4, 5, 6], foxWins: false },
};
for (const kind of FOX_CASES)
  for (const transport of ["llm", "acp", "mixed"] as const)
    test(`${kind}/${transport}: actual bilingual SDK, ACP/MCP complete games and strict Tape keep Fox effects and chain-final individual winners`, async () => {
      const runs: Awaited<ReturnType<typeof runTransportGame>>[] = [];
      for (const locale of ["zh-CN", "en"] as const) {
        const run = await runTransportGame(foxScenario(kind), transport, locale);
        runs.push(run);
        const oracle = expectations[kind],
          events = run.replay.events;
        expect(
          events.filter((e) => e.type === "night_resolved").map((e) => e.payload.deaths),
        ).toEqual([oracle.night]);
        expect(run.manifest.players.filter((p) => p.alive).map((p) => p.player_id)).toEqual(
          oracle.alive,
        );
        expect(run.result.snapshot.result).toEqual({
          winner: oracle.foxWins ? null : Camp.Good,
          reason: oracle.foxWins
            ? "cursed_fox_survived_faction_elimination"
            : "all_wolves_eliminated",
          outcome: {
            kind: "victory",
            primary: oracle.foxWins
              ? {
                  kind: "individual",
                  goalId: "netease_cursed_fox_last_faction_v1",
                  playerId: 1,
                  winningPlayerIds: [1],
                }
              : { kind: "faction", faction: Camp.Good, winningPlayerIds: [2, 4, 5, 6] },
            additional: [],
            winningPlayerIds: oracle.foxWins ? [1] : [2, 4, 5, 6],
          },
          decidedAt: { day: 1, phase: Phase.Voting, checkpoint: "exile_settled" },
        });
        expect(events.filter((e) => e.type === "game_over")).toHaveLength(1);
        expect(events.at(-1)!.type).toBe("game_over");
        expect(
          events
            .filter((e) => e.type === "wolf_king_shot")
            .map((e) => [e.payload.actorId, e.payload.targetId]),
        ).toEqual(kind === "king_chain" ? [[3, 1]] : []);
        if (kind === "king_chain")
          expect(events.findIndex((e) => e.type === "wolf_king_shot")).toBeLessThan(
            events.findIndex((e) => e.type === "game_over"),
          );
        if (kind === "mirror")
          expect(events.find((e) => e.type === "role_inspected")?.payload.result).toEqual({
            kind: "role",
            role: "cursed_fox",
          });
        const checks = events.filter((e) => e.type === "seer_checked");
        if (kind !== "mirror")
          expect(checks[0]?.payload.result).toEqual({
            kind: "camp",
            camp: kind === "fox_lucky" ? Camp.Wolf : Camp.Good,
          });
        for (const view of run.views) {
          const visible = view.timeline.filter((e) => e.kind === "event");
          expect(JSON.stringify(visible)).not.toContain("fox_inspection");
          expect(
            visible.filter((e) => e.kind === "event" && e.event.type === "seer_checked"),
          ).toHaveLength(
            kind === "mirror"
              ? 0
              : view.player_id === (kind === "lucky" ? 6 : kind === "fox_lucky" ? 1 : 2)
                ? 1
                : 0,
          );
        }
        expect(run.rejected.size).toBe(0);
        expect(run.acpTraces.every((r) => r.trace.rejected === 0)).toBe(true);
        if (transport === "llm" && ["dream", "king_chain", "inspection"].includes(kind))
          await fs.writeFile(
            `/tmp/awa-p8-fox-${kind}-${locale}.replay.json`,
            JSON.stringify(run.replay),
          );
      }
      const neutral = (events: (typeof runs)[0]["replay"]["events"]) =>
        events.map(({ timestamp: _t, ...e }) => e);
      expect(runs[0].result).toEqual(runs[1].result);
      expect(neutral(runs[0].replay.events)).toEqual(neutral(runs[1].replay.events));
      expect(runs[0].record.checkpoints).toEqual(runs[1].record.checkpoints);
    }, 120000);

/**
 * Reproduction scenarios verify Debater complete recorded games preserve strict challenge ballots, blocked voters and terminal timing.
 * Input: Original six/twelve-player success/tie/abstain plans across transport and locale matrices.
 * Output and oracle: Literal ballot/support/abstention, privacy and declared terminal-day assertions retain the real recorded sequence; diagnostic temporary output stays unchanged.
 */
import { promises as fs } from "node:fs";
import { expect, test } from "bun:test";
import { Camp, Role, Phase } from "../../../../src/core";
import { debaterScenario } from "../../../support/features/debater/builders/scenario";
import { runTransportGame } from "../../../support/drivers/transport/run-game";
for (const size of [6, 12] as const)
  for (const outcome of ["success", "tie", "abstain"] as const)
    for (const transport of ["llm", "acp", "mixed"] as const)
      test(`${size}/${outcome}/${transport}: bilingual complete local transports and strict Tape`, async () => {
        for (const locale of ["zh-CN", "en"] as const) {
          const scenario = debaterScenario(size, outcome),
            run = await runTransportGame(scenario, transport, locale),
            actor = scenario.roles.indexOf(Role.Debater) + 1,
