        );
        expect(events.some((event) => event.type === "wolf_king_shot")).toBe(false);
        const winners = kind === "twelve" ? [5, 6, 7, 8, 9, 10, 11, 12] : [1, 3, 4, 5, 6];
        expect(run.result.snapshot.result).toEqual({
