            .filter((event) => event.type === "last_words_spoken")
            .map((event) => event.payload.playerId),
        ).toEqual(oracle.words);
        const abilities = run.record.checkpoints
          .at(-1)!
          .players.find((player) => player.id === actor)!.privateState.abilities as Record<
          string,
