      const neutral = (events: (typeof runs)[0]["replay"]["events"]) =>
        events.map(({ timestamp: _time, ...event }) => event);
      expect(runs[0].result).toEqual(runs[1].result);
      expect(neutral(runs[0].replay.events)).toEqual(neutral(runs[1].replay.events));
      expect(runs[0].record.checkpoints).toEqual(runs[1].record.checkpoints);
    }, 120000);

/**
 * 复现场景测试负责骑士完整录制对局的决斗窗口、命中／落空与死亡链时点。输入为原枚举窗口矩阵、额外落空／狼王／白狼王／十二人计划、传输和语言。
 * 输出用字面决斗载荷、存活、遗言、检查点和胜者断言核对；用例生成及声明的原预期保持。
 */
import type { VictoryPoint } from "@ai-werewolf-arena/game-contract";
import { Camp, DeathCause, KnightDuelWindow, Phase } from "../../../../src/core";
import { expect, test } from "bun:test";
import { writeFile } from "node:fs/promises";
import { knightScenario, type KnightScenario } from "../../../support/features/knight/builders/scenario";
import { runTransportGame } from "../../../support/drivers/transport/run-game";
const cases: Array<[KnightScenario, KnightDuelWindow]> = Object.values(KnightDuelWindow).map(
  (window) => ["hit", window],
);
for (const kind of ["miss", "last_god_miss", "king_hit", "white_hit", "twelve"] as KnightScenario[])
  cases.push([
    kind,
    kind === "last_god_miss" ? KnightDuelWindow.BeforeSpeeches : KnightDuelWindow.AfterSpeeches,
  ]);
for (const [kind, window] of cases)
  for (const transport of ["llm", "acp", "mixed"] as const)
    test(`${kind}/${window}/${transport}: actual bilingual Knight complete games preserve literal results, words and strict replay`, async () => {
      const runs: Awaited<ReturnType<typeof runTransportGame>>[] = [];
      for (const locale of ["zh-CN", "en"] as const) {
        const run = await runTransportGame(knightScenario(kind, window), transport, locale);
        runs.push(run);
        const events = run.replay.events;
        const actor = kind === "twelve" ? 7 : 1,
          target = kind === "miss" ? 4 : kind === "last_god_miss" ? 3 : kind === "twelve" ? 1 : 2,
          miss = kind === "miss" || kind === "last_god_miss";
        expect(
          events.filter((event) => event.type === "knight_duel").map((event) => event.payload),
        ).toEqual([{ actorId: actor, targetId: target, result: miss ? "not_wolf" : "wolf" }]);
        expect(
          events.filter(
            (event) =>
              event.type === "hunter_shot" ||
              event.type === "wolf_king_shot" ||
              event.type === "white_wolf_king_self_destruct",
          ),
        ).toEqual([]);
        const winners =
          kind === "twelve"
            ? [5, 6, 7, 8, 9, 10, 11, 12]
            : kind === "last_god_miss"
              ? [2]
              : [1, 3, 4, 5, 6];
        const point: VictoryPoint = {
          day: kind === "twelve" ? 3 : 1,
          phase: kind === "miss" || kind === "twelve" ? Phase.Voting : Phase.Day,
          checkpoint: kind === "miss" || kind === "twelve" ? "exile_settled" : "day_interrupted",
        };
        const faction = kind === "last_god_miss" ? Camp.Wolf : Camp.Good,
          reason = kind === "last_god_miss" ? "slaughter_side_completed" : "all_wolves_eliminated";
        expect(run.result.snapshot.result).toEqual({
          winner: faction,
          reason,
          outcome: {
            kind: "victory",
            primary: { kind: "faction", faction, winningPlayerIds: winners },
            additional: [],
            winningPlayerIds: winners,
          },
          decidedAt: point,
        });
        expect(
          run.manifest.players.filter((player) => player.alive).map((player) => player.player_id),
        ).toEqual(
          kind === "twelve"
            ? [6, 8, 9, 10, 11, 12]
            : kind === "miss"
              ? [3, 4, 6]
              : kind === "last_god_miss"
                ? [2, 3, 4, 6]
                : [1, 3, 4, 6],
        );
        expect(
          events
            .filter((event) => event.type === "last_words_spoken")
            .map((event) => event.payload.playerId),
        ).toEqual(
          kind === "twelve"
            ? [2, 3]
            : kind === "miss"
              ? [5, 1, 2]
              : kind === "last_god_miss"
                ? [5, 1]
                : [5],
        );
        expect(events.filter((event) => event.type === "game_over")).toHaveLength(1);
        expect(events.at(-1)!.type).toBe("game_over");
        expect(
          run.record.checkpoints.at(-1)!.players.find((player) => player.id === actor)!.privateState
            .knight,
        ).toEqual({ canDuel: false });
        expect(
          (run.rejected.get(actor) ?? 0) +
            (run.acpTraces.find((item) => item.actor === actor)?.trace.rejected ?? 0),
        ).toBe(1);
        if (kind === "miss" || kind === "last_god_miss") {
          expect(
            events
              .filter((event) => event.type === "sheriff_badge_transferred")
              .map((event) => [event.payload.fromId, event.payload.toId]),
          ).toEqual(
            kind === "miss"
              ? [
                  [1, 2],
                  [2, 3],
                ]
              : [[1, 2]],
          );
          expect(
            events.findIndex(
              (event) => event.type === "last_words_spoken" && event.payload.playerId === 1,
            ),
          ).toBeLessThan(events.findIndex((event) => event.type === "sheriff_badge_transferred"));
        }
        if (kind !== "miss" && kind !== "twelve")
          expect(events.some((event) => event.type === "vote_cast")).toBe(false);
        if (kind === "hit")
          expect(events.filter((event) => event.type === "day_speech").length).toBe(
            window === KnightDuelWindow.BeforeSpeeches
              ? 0
              : window === KnightDuelWindow.BetweenSpeeches
                ? 1
                : 5,
          );
        if (kind === "hit" && window === KnightDuelWindow.AfterSpeeches && transport === "llm")
          await writeFile(`/tmp/awa-p5-knight-${locale}.replay.json`, JSON.stringify(run.replay));
        if (kind === "miss" && transport === "llm")
          await writeFile(
            `/tmp/awa-p5-knight-miss-${locale}.replay.json`,
            JSON.stringify(run.replay),
          );
      }
      const neutral = (events: (typeof runs)[0]["replay"]["events"]) =>
        events.map(({ timestamp: _time, ...event }) => event);
      expect(runs[0].result).toEqual(runs[1].result);
      expect(neutral(runs[0].replay.events)).toEqual(neutral(runs[1].replay.events));
      expect(runs[0].record.checkpoints).toEqual(runs[1].record.checkpoints);
    }, 120000);

/**
 * 负责孤独少女完整录制对局中秘密胜利归属及私有倾慕历史的隔离。
 * 输入为原六人／十二人场景、传输与语言矩阵及同前缀归档变体；输出由原身份、归属、生存和胜利字面断言核对。
 * 复制的归档只作为变体，不充当独立规则 golden。
 */
import { expect, test } from "bun:test";
import { promises as fs } from "node:fs";
import { Role, Camp, type GameEvent } from "../../../../src/core";
import { LONELY_GIRL_CASES, lonelyGirlScenario } from "../../../support/features/lonely-girl/builders/scenario";
import { runTransportGame } from "../../../support/drivers/transport/run-game";
import { parseReproductionRecord } from "../../../../src/recording/reproduction";
import { ReproductionTrace } from "../../../../src/recording/reproduction-trace";
for (const size of [6, 12] as const)
  for (const kind of LONELY_GIRL_CASES.filter(
    (k) => size === 6 || ["good_alive", "wolf_alive", "wolf_win"].includes(k),
  ))
    for (const transport of ["llm", "acp", "mixed"] as const)
      test(`${size}/${kind}/${transport}: actual bilingual isolated affiliation, private archives and strict Tape`, async () => {
        for (const locale of ["zh-CN", "en"] as const) {
          const scenario = lonelyGirlScenario(kind, size, locale),
            run = await runTransportGame(scenario, transport, locale),
            record = run.record,
            final = record.checkpoints.at(-1)!;
          expect(record.metadata.players.map((p) => p.role)).toEqual([...scenario.roles]);
          expect(record.metadata.initialDeal).toBeUndefined();
          if (size === 6 && kind === "good_alive" && transport === "llm" && locale === "zh-CN") {
            const trace = new ReproductionTrace(record.metadata, () => {}),
              first = record.checkpoints[0]!;
            trace.checkpoint(first, record.events.slice(0, first.eventCount) as GameEvent[]);
            const decision = record.decisions[0]!;
            await trace.decide(decision.request, {
              async getAction() {
                return { name: "choose_admired_player", args: { target_id: scenario.targetId } };
              },
            });
            await trace.decide(record.decisions[1]!.request, {
              async getAction() {
                return null;
              },
            });
            expect(trace.build().finalized).toBe(false);
            expect(() =>
              trace.build({
                operations: [],
                termination: { reason: "strict_failure", winner: null },
              }),
            ).toThrow("reproduction_lonely_girl_state_invalid");
          }

          expect(record.decisions.filter((d) => d.stage === "lonely_girl")).toHaveLength(1);
          expect(
            record.events
              .filter((e) => e.type === "lonely_girl_admired_chosen")
              .map((e) => e.payload),
          ).toEqual([
            {
              policy: "awa_netease_lonely_girl_v1",
              actorId: scenario.actorId,
              day: 1,
              targetId: scenario.targetId,
              camp: scenario.faction,
            },
          ]);
          expect(final.snapshot.result?.winner).toBe(scenario.winner);
          const outcome = final.snapshot.result?.outcome;
          if (outcome?.kind !== "victory") throw new Error("expected_victory");
          expect(outcome.winningPlayerIds).toEqual(scenario.winners);
          expect(final.players.filter((p) => p.alive).map((p) => p.id)).toEqual(scenario.alive);
          expect(final.players.find((p) => p.id === scenario.actorId)).toMatchObject({
            role: Role.LonelyGirl,
            camp: Camp.Good,
            victory: { affiliations: [{ kind: "faction", faction: scenario.faction }] },
          });
          expect(final.lonelyGirlSetup).toEqual({
            policy: "awa_netease_lonely_girl_v1",
            status: "complete",
            actorId: scenario.actorId,
          });
          expect(
            record.decisions.some(
              (d) =>
                d.actorId === scenario.actorId &&
                ["wolf_discussion", "wolf_vote"].includes(d.stage),
            ),
          ).toBe(false);
          for (const view of run.views) {
            const own = view.timeline.filter(
              (e) => e.kind === "event" && e.event.type === "lonely_girl_admired_chosen",
            );
            expect(own).toHaveLength(view.player_id === scenario.actorId ? 1 : 0);
            if (own.length) {
              const e = own[0]!;
              if (e.kind !== "event") throw new Error("expected_choice");
              expect(e.event.payload).toEqual({
                policy: "awa_netease_lonely_girl_v1",
                actorId: scenario.actorId,
                day: 1,
                targetId: scenario.targetId,
              });
              expect(view.role).toBe(Role.LonelyGirl);
              expect(view.camp).toBe(Camp.Good);
            }
          }
          if (transport === "llm" && locale === "zh-CN") {
            await fs.writeFile(
              `/tmp/awa-p9-lonely-girl-${size}-${kind}.record.json`,
              JSON.stringify(record),
            );
            await fs.writeFile(
              `/tmp/awa-p9-lonely-girl-${size}-${kind}.replay.json`,
              JSON.stringify(run.replay),
            );
            await fs.writeFile(
              `/tmp/awa-p9-lonely-girl-${size}-${kind}.player.json`,
              JSON.stringify(run.views.find((v) => v.player_id === scenario.actorId)),
            );
          }
          if (size === 6 && kind === "good_alive" && transport === "llm" && locale === "zh-CN")
            for (const mutate of [
              (r: typeof record) => {
                r.decisions[0]!.request.actorId = 999;
              },
              (r: typeof record) => {
                r.decisions[0]!.request.context.stage = "seer";
              },
              (r: typeof record) => {
                r.decisions[0]!.request.context.day = 2;
              },
              (r: typeof record) => {
                const d = r.decisions[0]!;
                if (d.outcome.kind === "action")
                  d.outcome.action!.args = { ...(d.outcome.action!.args as any), extra: true };
              },
              (r: typeof record) => {
                r.checkpoints[0]!.lonelyGirlSetup!.status = "failed";
                (
                  r.checkpoints[0]!.players.find((p) => p.id === scenario.actorId)!.privateState
                    .lonelyGirl as any
                ).remaining = 0;
              },
              (r: typeof record) => {
                r.checkpoints[1]!.lonelyGirlSetup!.status = "pending";
                r.checkpoints[1]!.players.find(
                  (p) => p.id === scenario.actorId,
                )!.privateState.lonelyGirl = {
                  policy: "awa_netease_lonely_girl_v1",
                  remaining: 1,
                  choice: null,
                };
                r.checkpoints[1]!.players.find(
                  (p) => p.id === scenario.actorId,
                )!.victory.affiliations = [];
              },
              (r: typeof record) => {
                r.metadata.players.find((p) => p.id === scenario.targetId)!.camp = Camp.Wolf;
                const e = r.events.find((e) => e.type === "lonely_girl_admired_chosen")!;
                (e.payload as any).camp = Camp.Wolf;
                for (const cp of r.checkpoints.slice(1))
                  cp.players.find((p) => p.id === scenario.actorId)!.victory.affiliations = [
                    { kind: "faction", faction: Camp.Wolf },
                  ];
              },
              (r: typeof record) => {
                r.events.push({
                  timestamp: 1,
                  type: "hybrid_exemplar_chosen",
                  payload: { actorId: scenario.actorId, day: 1, targetId: scenario.targetId },
                });
              },
              (r: typeof record) => {
                r.checkpoints[0]!.players[0]!.privateState.hybrid = { remaining: 1, choice: null };
              },
            ]) {
              const bad = structuredClone(record);
              mutate(bad);
              expect(() => parseReproductionRecord(bad)).toThrow();
            }
        }
      }, 120000);

/**
 * Reproduction scenarios verify Mechanical Wolf complete recorded games preserve independent learned abilities, readiness and source authority.
 * Input: Original scenario/transport/locale matrices with handwritten learned-role, ready-day, survivor and last-word facts.
 * Output and oracle: Explicit private resource, knowledge, death and terminal assertions retain exact replay; no copy state or expected table is regenerated.
 */
import { Camp, DeathCause, Phase } from "../../../../src/core";
import { expect, test } from "bun:test";
import { writeFile } from "node:fs/promises";
import { MECHANICAL_CASES, mechanicalScenario, type MechanicalScenario } from "../../../support/features/mechanical-wolf/builders/scenario";
import { runTransportGame } from "../../../support/drivers/transport/run-game";

const facts: Record<
  MechanicalScenario,
  { alive: number[]; words: number[]; day: number; learned: string; ready: number }
> = {
  villager: { alive: [3, 4, 6], words: [2, 1], day: 2, learned: "villager", ready: 2 },
  inspection: { alive: [3, 4, 5], words: [2, 6, 1], day: 3, learned: "psychic", ready: 2 },
  poison: { alive: [4, 5, 6], words: [2, 1], day: 2, learned: "witch", ready: 2 },
  reflection: { alive: [3, 5, 6], words: [2, 1], day: 2, learned: "guard", ready: 2 },
  guard_failure: { alive: [3, 4, 5], words: [2, 6], day: 3, learned: "guard", ready: 2 },
  hunter: { alive: [3, 5], words: [2, 1], day: 2, learned: "hunter", ready: 2 },
  extra: { alive: [4, 5], words: [2, 1], day: 2, learned: "wolf", ready: 2 },
  late: { alive: [4, 5], words: [2, 3, 1], day: 3, learned: "witch", ready: 3 },
  twelve: { alive: [5, 10, 11, 12], words: [4, 9, 1], day: 3, learned: "hunter", ready: 2 },
};

for (const kind of MECHANICAL_CASES)
  for (const transport of ["llm", "acp", "mixed"] as const)
    test(`${kind}/${transport}: real bilingual mechanical games preserve independent skills, authority, privacy and strict Tape`, async () => {
      const runs: Awaited<ReturnType<typeof runTransportGame>>[] = [];
      for (const locale of ["zh-CN", "en"] as const) {
        const scenario = mechanicalScenario(kind),
          run = await runTransportGame(scenario, transport, locale);
        runs.push(run);
        const oracle = facts[kind],
          events = run.replay.events;
        expect(run.manifest.players.filter((p) => p.alive).map((p) => p.player_id)).toEqual(
          oracle.alive,
        );
        expect(
          events.filter((e) => e.type === "last_words_spoken").map((e) => e.payload.playerId),
        ).toEqual(oracle.words);
        expect(
          events
            .filter((e) => e.type === "mechanical_mimicked")
            .map((e) => [e.payload.role, e.payload.readyOnNight]),
        ).toEqual([[oracle.learned, oracle.ready]]);
        expect(
          events.filter((e) => e.type === "mechanical_awakened").map((e) => e.payload),
        ).toEqual([
          {
            actorId: 1,
            day: kind === "twelve" ? 2 : 1,
            firstKnifeNight: kind === "twelve" ? 3 : 2,
          },
        ]);
        const state = run.record.checkpoints.at(-1)!.players.find((p) => p.id === 1)!.privateState
          .mechanical_wolf as any;
        expect(state.learned.role).toBe(oracle.learned);
        expect(state.learned.readyOnNight).toBe(oracle.ready);
        if (kind === "inspection")
          expect(state.learned.skill.history).toEqual([
            { day: 2, targetId: 4, result: { kind: "role", role: "witch" } },
            { day: 3, targetId: 4, result: { kind: "role", role: "witch" } },
          ]);
        if (kind === "poison")
          expect(state.learned.skill).toEqual({ kind: "poison", remaining: 0 });
        if (kind === "late") {
          expect(state.learned.skill).toEqual({ kind: "poison", remaining: 1 });
          expect(
            events.filter((e) => e.type === "mechanical_mimic_skipped").map((e) => e.payload.day),
          ).toEqual([1]);
          expect(
            events.filter((e) => e.type === "mechanical_mode_selected").at(-1)!.payload.mode,
          ).toBe("skill");
          expect(
            events.filter((e) => e.type === "mechanical_skill_skipped").map((e) => e.payload.day),
          ).toEqual([3]);
        }
        if (kind === "reflection")
          expect(
            events.filter((e) => e.type === "mechanical_poison_reflected").map((e) => e.payload),
          ).toEqual([{ actorId: 1, day: 2, protectedTargetId: 3, casterId: 4 }]);
        if (kind === "guard_failure")
          expect(
            events.filter((e) => e.type === "mechanical_guard_chosen").map((e) => e.payload.failed),
          ).toEqual([false, true]);
        if (kind === "extra") {
          expect(state.learned.skill).toEqual({ kind: "wolf", extraKnife: "spent" });
          expect(
            events.filter((e) => e.type === "mechanical_attack_chosen").map((e) => e.payload),
          ).toEqual([{ actorId: 1, day: 2, targetId: 3 }]);
        }
        if (kind === "hunter" || kind === "twelve") {
          expect(state.learned.skill).toEqual({ kind: "hunter", canShoot: false, armed: true });
          expect(events.filter((e) => e.type === "mechanical_shot").map((e) => e.payload)).toEqual([
            { actorId: 1, targetId: kind === "twelve" ? 8 : 4 },
          ]);
        }
        const winners = kind === "twelve" ? [5, 6, 7, 8, 9, 10, 11, 12] : [3, 4, 5, 6],
          night = kind === "guard_failure";
        expect(run.result.snapshot.result).toEqual({
          winner: Camp.Good,
          reason: "all_wolves_eliminated",
          outcome: {
            kind: "victory",
            primary: { kind: "faction", faction: Camp.Good, winningPlayerIds: winners },
            additional: [],
            winningPlayerIds: winners,
          },
          decidedAt: {
            day: oracle.day,
            phase: night ? Phase.Day : Phase.Voting,
            checkpoint: night ? "night_settled" : "exile_settled",
          },
        });
        for (const view of run.views) {
          const projected = view.timeline
            .filter((row) => row.kind === "event")
            .map((row) => row.event);
          expect(projected.some((e) => e.type === "mechanical_poison_reflected")).toBe(false);
          expect(projected.filter((e) => e.type === "mechanical_mimicked")).toHaveLength(
            view.player_id === 1 ? 1 : 0,
          );
          if (view.player_id === 1)
            expect(
              projected.some((e) => ["wolf_discussion", "wolf_tactical_order"].includes(e.type)),
            ).toBe(false);
        }
        expect(run.rejected.size).toBe(0);
        expect(run.acpTraces.every((row) => row.trace.rejected === 0)).toBe(true);
        expect(events.filter((e) => e.type === "game_over")).toHaveLength(1);
        expect(events.at(-1)!.type).toBe("game_over");
        if (["reflection", "twelve", "guard_failure"].includes(kind) && transport === "llm")
          await writeFile(
            `/tmp/awa-p7-mechanical-${kind}-${locale}.replay.json`,
            JSON.stringify(run.replay),
          );
      }
      const neutral = (events: (typeof runs)[0]["replay"]["events"]) =>
        events.map(({ timestamp: _time, ...event }) => event);
      expect(runs[0].result).toEqual(runs[1].result);
      expect(neutral(runs[0].replay.events)).toEqual(neutral(runs[1].replay.events));
      expect(runs[0].record.checkpoints).toEqual(runs[1].record.checkpoints);
    }, 120000);

