          white = kind === "twelve" ? 2 : 1,
          pending = kind === "pending_poison" || kind === "pending_knife";
        const winners = kind === "twelve" ? [5, 6, 7, 8, 9, 10, 11, 12] : [3, 4, 5, 6];
        const point: VictoryPoint =
          kind === "none"
            ? { day: 2, phase: Phase.Day, checkpoint: "night_settled" }
