          kind === "twelve"
            ? [5, 6, 8, 9, 11, 12]
            : kind === "pending_poison"
              ? [3, 4, 6]
              : kind === "pending_knife"
                ? [3, 4, 5, 6]
                : kind === "wolf_king"
