        expect(
          run.manifest.players.filter((player) => player.alive).map((player) => player.player_id),
        ).toEqual(alive);
        expect(
          events
            .filter((event) => event.type === "white_wolf_king_self_destruct")
            .map((event) => event.payload),
        ).toEqual(
          pending
            ? []
            : [
                {
                  actorId: white,
                  targetId:
                    kind === "none" ? null : kind === "wolf_king" ? 2 : kind === "twelve" ? 10 : 4,
                  window,
                },
              ],
        );
        const guns =
          kind === "twelve"
