      for (const locale of ["zh-CN", "en"] as const) {
        const run = await runTransportGame(wolfKingScenario(scenario), transport, locale);
        results.push(run);
        const winners = scenario === "twelve" ? [5, 6, 7, 8, 9, 10, 11, 12] : [2, 3, 4, 5, 6];
        const point: VictoryPoint =
          scenario === "poison" || scenario === "shot_chain"
            ? { day: 1, phase: Phase.Day, checkpoint: "night_settled" }
            : scenario === "twelve" || scenario === "blast"
              ? {
                  day: scenario === "twelve" ? 2 : 1,
                  phase: Phase.Voting,
                  checkpoint: "day_interrupted",
                }
              : { day: 1, phase: Phase.Voting, checkpoint: "exile_settled" };
