        expect(
          events.filter((event) => event.type === "hunter_shot").map((event) => event.payload),
        ).toEqual(
          scenario === "blast"
            ? []
            : [
                {
                  hunterId: scenario === "twelve" ? 7 : 2,
                  targetId: scenario === "poison" ? 5 : scenario === "shot_chain" ? 1 : 3,
                },
              ],
