        expect(events.filter((event) => event.type === "game_over")).toHaveLength(1);
        expect(events.at(-1)!.type).toBe("game_over");
        if (scenario !== "blast")
          expect(events.findIndex((event) => event.type === "hunter_shot")).toBeLessThan(
            events.findIndex((event) => event.type === "game_over"),
          );
        const final = run.record.checkpoints.at(-1)!,
          kingState = final.players.find((player) => player.id === king)!;
        expect(kingState.privateState.wolf_king).toEqual({ canShoot: false });
        expect(kingState.privateState).not.toHaveProperty("hunter");
        if (scenario === "exile_chain") {
