          expect(events.findIndex((event) => event.type === "wolf_king_shot")).toBeLessThan(
            events.findIndex((event) => event.type === "hunter_shot"),
          );
        } else if (scenario === "poison") {
          expect(
            run.record.decisions.some(
              (decision) => decision.actorId === king && decision.stage === "death_shot",
            ),
          ).toBe(false);
          expect(
            events
              .filter((event) => event.type === "last_words_spoken")
