          ).toEqual([1, 2]);
          expect(
            events
              .filter((event) => event.type === "sheriff_badge_transferred")
              .map((event) => [event.payload.fromId, event.payload.toId]),
          ).toEqual([[1, 3]]);
        } else if (scenario === "twelve") {
          expect(
            events
              .filter((event) => event.type === "wolf_self_destruct")
              .map((event) => event.payload.wolfId),
          ).toEqual([1]);
          expect(
            events
              .filter((event) => event.type === "seer_checked")
              .map((event) => event.payload.targetId),
          ).toEqual([2, 1]);
          expect(
            run.views
              .find((view) => view.player_id === king)!
              .timeline.some(
                (entry) =>
                  entry.kind === "event" &&
                  entry.day === 2 &&
                  [
                    "wolf_tactical_order",
                    "wolf_discussion",
                    "wolf_discussion_ended",
                    "wolf_kill_vote_cast",
                  ].includes(entry.event.type),
              ),
          ).toBe(false);
        } else if (scenario === "shot_chain") {
          expect(
            events
              .filter((event) => event.type === "sheriff_badge_transferred")
              .map((event) => [event.payload.fromId, event.payload.toId]),
          ).toEqual([
            [1, 3],
            [3, 4],
          ]);
          expect(
            events
              .filter((event) => event.type === "last_words_spoken")
              .map((event) => event.payload.playerId),
          ).toEqual([2]);
          expect(events.findIndex((event) => event.type === "hunter_shot")).toBeLessThan(
            events.findIndex((event) => event.type === "wolf_king_shot"),
          );
          expect(
            run.record.decisions.find(
              (decision) => decision.actorId === king && decision.stage === "death_shot",
            )!.request.context.death_sources,
          ).toEqual([DeathCause.Shot]);
        } else {
          expect(
            run.record.decisions.some((decision) =>
              ["voting", "death_shot", "hunter_shot"].includes(decision.stage),
            ),
          ).toBe(false);
          expect(
            events
              .filter((event) => event.type === "wolf_self_destruct")
              .map((event) => event.payload.wolfId),
          ).toEqual([1]);
          expect(
            events
              .filter((event) => event.type === "last_words_spoken")
              .map((event) => event.payload.playerId),
          ).toEqual([5]);
          expect(
            events
              .filter((event) => event.type === "sheriff_badge_transferred")
              .map((event) => [event.payload.fromId, event.payload.toId]),
          ).toEqual([[1, 2]]);
        }
        const expectedRejections = scenario === "poison" || scenario === "blast" ? 0 : 1;
        expect(
          (run.rejected.get(king) ?? 0) +
            (run.acpTraces.find((item) => item.actor === king)?.trace.rejected ?? 0),
        ).toBe(expectedRejections);
        if (scenario === "exile_chain" && transport === "llm")
          await writeFile(
            `/tmp/awa-p5-wolf-king-${locale}.replay.json`,
            JSON.stringify(run.replay),
          );
      }
      const neutral = (events: (typeof results)[0]["replay"]["events"]) =>
        events.map(({ timestamp: _time, ...event }) => event);
      expect(neutral(results[0].replay.events)).toEqual(neutral(results[1].replay.events));
      expect(results[0].result).toEqual(results[1].result);
      expect(results[0].record.checkpoints).toEqual(results[1].record.checkpoints);
    }, 120000);

/**
