  replayReproduction,
} from "../../../src/runtime/simulation/replay_reproduction";
import { createTestTempDirectory } from "../../support/drivers/temp-directories";

test("revoked delivery on a real engine request records an error and reproduces the exact partial cycle without a replay clock", async () => {
  const root = await createTestTempDirectory("awa-delivery-failure-"),
    output = await createTestTempDirectory("awa-delivery-failure-replay-"),
    board = await loadBoardDefinition(
      path.resolve(import.meta.dir, "../../../../configs.example"),
      "six_player_mvp",
    ),
    runtime = parseRuntimeConfig({
      providers: {
        default: "synthetic",
        items: { synthetic: { type: "openai", apiKey: "synthetic-only" } },
      },
      agents: {
        default: "synthetic",
        items: { synthetic: { kind: "llm", provider: "synthetic", model: "synthetic" } },
      },
      game: { board: "six_player_mvp", seed: "delivery-failure", locale: "en" },
      debugSummary: { agent: { enabled: false } },
    }),
    setup = resolveGameSetup(
      runtime,
      {
        recordRootDir: root,
        maxDays: 3,
        maxRuntimeMs: 10_000,
        streamEvents: false,
        printThinking: false,
        color: false,
      },
      board,
    );
  let requests = 0;
  const create = spyOn(factory, "createPlayerAgentRuntime").mockImplementation(async () => {
    let closed = false;
    return {
      kind: "llm",
      provider: {
        async getAction(request) {
          requests++;
          expect(request.context.stage).toBe("wolf_discussion");
          bindRequestDeliveryGuard(request, () => false);
          return {
            name: "speak_to_wolves",
            args: { text: "synthetic delayed delivery", end_chat: true },
          };
        },
      },
      get runtimeState() {
        return { closed };
      },
      async close() {
        closed = true;
      },
    };
  });
  try {
    await expect(runGame(setup)).rejects.toThrow("action_request_delivery_authority_revoked");
    const [session] = await readdir(root),
      record = await readReproduction(path.join(root, session!, "reproduction.json"));
    expect(requests).toBe(1);
    expect(record.termination!.reason).toBe("runtime_error");
    expect(record.decisions).toHaveLength(1);
    expect(record.decisions[0]!.outcome).toEqual({
      kind: "error",
      code: "decision_failed",
      name: "Error",
    });
    expect(record.checkpoints.at(-1)!.complete).toBe(false);
    expect(record.events.some((e) => e.type === "wolf_discussion")).toBe(false);
    const replay = await replayReproduction(record, output);
    expect(replay.decisionCount).toBe(1);
    expect(replay.eventCount).toBe(record.events.length);
  } finally {
    create.mockRestore();
  }
});

/**
 * 模拟场景测试：负责执行六人／十二人猎魔人的两种胜利目标、双语及原一百二十五个种子的实际 World。输入保留原角色、种子和动作矩阵；初始身份／阵营／状态引用、公开死亡及手写阵营公式检查选择、免疫和终局，不替代 golden 或声称新增独立覆盖。
 */
import { expect, test } from "bun:test";
import { writeFile } from "node:fs/promises";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import {
  COMPONENT,
  Camp,
  Role,
  WinCondition,
  createRandom,
  randomDraws,
  type RoleComponent,
} from "../../../../src/core";
import { ObservedBot } from "../../../../src/ai/agents/providers/observed_bot";
import { ObservedPlayersActionProvider } from "../../../../src/app/observed-players-action-provider";
import { demonHunterBoard } from "../../../support/features/demon-hunter/builders/candidate-world";
for (const size of [6, 12] as const)
  for (const goal of [WinCondition.SlaughterCity, WinCondition.SlaughterSide])
    for (const locale of ["zh-CN", "en"] as const)
      test(`${size}/${goal}/${locale}: 125 independent unrecorded Worlds, original identity, public terminal deaths and victory`, async () => {
        const report = {
          games: 0,
          choices: 0,
          backlash: 0,
          hunts: 0,
          abstain: 0,
          immunity: 0,
          deadWinners: 0,
          good: 0,
          wolf: 0,
        };
        for (let n = 0; n < 125; n++) {
          const random = createRandom(`demon-world:${size}:${goal}:${n}`),
            config = demonHunterBoard(size, goal),
            game = bootstrapGame(config, { locale, random });
          const original = new Map(
            game.playerIds.map((id) => {
              const role = game.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                { ref: role, role: role.role, camp: game.world.getComponent(id, COMPONENT.Camp)!.camp, state: role.privateState },
              ];
            }),
          );
          const styles = ["active", "conservative", "competitive", "random"] as const;
          const strategies = new Map(
            game.playerIds.map((id) => [
              id,
              new ObservedBot(
                randomDraws(random.fork("players").fork(`id:${id}`)),
                styles[id % 4]!,
              ),
            ]),
          );
          const result = await game.phaseManager.runUntilGameOver(
              new ObservedPlayersActionProvider(game.world, strategies),
              30,
            ),
            events = game.phaseManager.getEvents();
          expect(result.gameOver).toBe(true);
          expect(result.result!.reason).not.toBe("max_days_reached");
          for (const [id, expected] of original) {
            const actual = game.world.getComponent(id, COMPONENT.Role)!;
            expect(actual).toBe(expected.ref);
            expect(actual.role).toBe(expected.role);
            expect(game.world.getComponent(id, COMPONENT.Camp)!.camp).toBe(expected.camp);
            expect(actual.privateState).toBe(expected.state);
          }
          const publicDead = new Set<number>();
          for (const e of events) {
            if (e.type === "night_resolved" || e.type === "additional_deaths")
              for (const id of e.payload.deaths as number[]) publicDead.add(id);
            if (e.type === "voted_out") publicDead.add(e.payload.target as number);
            if (e.type === "hunter_shot") publicDead.add(e.payload.targetId as number);
            if (e.type === "wolf_self_destruct") publicDead.add(e.payload.wolfId as number);
            if (e.type === "demon_hunter_poison_immune") report.immunity++;
            if (e.type === "demon_hunter_chosen") {
              report.choices++;
              const target = e.payload.targetId as number | null;
              if (target === null) report.abstain++;
              else if (original.get(target)!.camp === Camp.Wolf) report.hunts++;
              else report.backlash++;
              expect(e.audience).toEqual([e.payload.actorId as number]);
            }
          }
          const alive = game.world.getAliveEntityIds();
          expect(game.playerIds.filter((id) => !publicDead.has(id))).toEqual(alive);
          const wolves = alive.filter((id) => original.get(id)!.camp === Camp.Wolf),
            villagers = alive.filter((id) => original.get(id)!.role === Role.Villager),
            gods = alive.filter(
              (id) =>
                original.get(id)!.camp === Camp.Good && original.get(id)!.role !== Role.Villager,
            );
          const winner =
            wolves.length === 0
              ? Camp.Good
              : goal === WinCondition.SlaughterCity
                ? Camp.Wolf
                : villagers.length === 0 || gods.length === 0
                  ? Camp.Wolf
                  : null;
          expect(winner).not.toBeNull();
          if (winner === null) throw new Error("demon_world_premature_win");
          if (goal === WinCondition.SlaughterCity && wolves.length)
            expect(villagers.length + gods.length).toBe(0);
          expect(result.result!.winner).toBe(winner);
          const winners = game.playerIds.filter((id) => original.get(id)!.camp === winner);
          expect(result.result!.outcome).toEqual({
            kind: "victory",
            primary: { kind: "faction", faction: winner, winningPlayerIds: winners },
            additional: [],
            winningPlayerIds: winners,
          });
          report.deadWinners += winners.filter((id) => !alive.includes(id)).length;
          report[winner === Camp.Good ? "good" : "wolf"]++;
          report.games++;
        }
        expect(report.choices).toBeGreaterThan(0);
        expect(report.hunts + report.backlash).toBeGreaterThan(0);
        await writeFile(
          `/tmp/awa-p9-demon-world-${size}-${goal}-${locale}.json`,
          JSON.stringify(report),
        );
      }, 180000);

/**
 * 模拟场景测试验证原两个板子、各 25 个种子的重复及交错完整对局。输入为原基线动作
 * 与延迟回复；精确快照／事件和自然终局提供预期。板子、种子与交错矩阵保持，不调用模型。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import { createRandom } from "../../../src/core/domain/random";
import { BaselineBotActionProvider } from "../../../src/game/drivers/privileged-baseline";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";
import { twelvePlayerStandardConfig } from "../../../src/runtime/scenarios/twelve_player_standard";

for (const [board, config] of [
  ["six", sixPlayerMvpConfig],
  ["twelve", twelvePlayerStandardConfig],
] as const) {
  test(`${board}: 25 seeds reproduce complete engine games even with other games interleaved`, async () => {
    const run = async (seed: string, delayed: boolean) => {
      const context = bootstrapGame(config, { random: createRandom(seed) });
      // 原特权基线用作确定的控制器样本，T03 玩家模拟另有受限观察驱动。
      const baseline = new BaselineBotActionProvider(context.world);
      const provider = {
        async getAction(request: Parameters<typeof baseline.getAction>[0]) {
          if (delayed) await Promise.resolve();
          return baseline.getAction(request);
        },
      };
      const snapshot = await context.phaseManager.runUntilGameOver(provider, 30);
      return {
        snapshot,
        events: context.phaseManager
          .getEvents()
          .map(({ timestamp: _timestamp, ...event }) => event),
      };
    };
    for (let index = 0; index < 25; index++) {
      const seed = `${board}:rng:${index}`;
      const [first, other, replay] = await Promise.all([
        run(seed, false),
        run(`other:${seed}`, true),
        run(seed, true),
      ]);
      expect(first.snapshot.gameOver).toBe(true);
      expect(first.snapshot.result?.reason).not.toBe("max_days_reached");
      expect(other.snapshot.gameOver).toBe(true);
      expect(replay).toEqual(first);
    }
  }, 20000); // 每个板子执行 75 局，超时用于完成确定性验证，没有声明五秒性能预算。
}

