/**
 * Builds original shared test test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import type { PlannedTurn } from "../../transport/contracts";
import { ActionWindow } from "../../../../src/core";
import { PotionType } from "../../../../src/core";
import type { ActionStage } from "../../../../src/core";
import type { ToolCall } from "../../../../src/core";

export function foundationTransportPlan(size: 6 | 12, alternate = false) {
  const rows = new Map<number, PlannedTurn[]>(
    Array.from({ length: size }, (_, index) => [index + 1, []]),
  );
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((actor: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      rows
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const wolves = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End discussion", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const speech = (day: number, actors: number[]) =>
    add(day, actors, "day_speech", (actor) => ({
      name: "speak",
      args: { text: `Day ${day}, seat ${actor}` },
    }));
  const vote = (day: number, actors: number[], target: number) =>
    add(day, actors, "voting", { name: "vote", args: { target_id: target, abstain: false } });
  const last = (day: number, actor: number) =>
    add(day, [actor], "last_words", { name: "speak", args: { text: `Last words ${actor}` } });
  if (size === 6) {
    wolves(1, [1, 4], 3);
    add(1, [5], "guard", { name: "guard", args: { target_id: alternate ? 3 : 6, abstain: false } });
    add(1, [2], "seer", { name: "check_identity", args: { target_id: 1 } });
    if (!alternate) last(1, 3);
    const day1 = alternate ? [1, 2, 3, 4, 5, 6] : [1, 2, 4, 5, 6];
    speech(1, day1);
    vote(1, day1, 1);
    last(1, 1);
    wolves(2, [4], 5);
    add(2, [5], "guard", {
      name: "guard",
      args: { target_id: alternate ? 6 : null, abstain: !alternate },
    });
    add(2, [2], "seer", { name: "check_identity", args: { target_id: 4 } });
    const day2 = alternate ? [2, 3, 4, 6] : [2, 4, 6];
    speech(2, day2);
    vote(2, day2, 4);
    last(2, 4);
  } else {
    const all = Array.from({ length: 12 }, (_, index) => index + 1);
    wolves(1, [1, 2, 3, 4], 9);
    add(1, [6], "witch", {
      name: "use_potion",
      args: { target_id: 9, potion_type: PotionType.Heal },
    });
    add(1, [5], "seer", { name: "check_identity", args: { target_id: 1 } });
    add(1, all, "sheriff_nomination", (actor) => ({
      name: "run_for_sheriff",
      args: { run: actor === 8 || actor === 10 },
    }));
    add(1, [8, 10], "sheriff_campaign_speech", { name: "speak", args: { text: "Campaign" } });
    add(1, [8, 10], "sheriff_withdraw", (actor) => ({
      name: "run_for_sheriff",
      args: { run: actor === 8 },
    }));
    add(
      1,
      all.filter((id) => id !== 8),
      "sheriff_vote",
      { name: "vote_for_sheriff", args: { target_id: 8, abstain: false } },
    );
    add(1, [8], "sheriff_choose_direction", {
      name: "choose_direction",
      args: { direction: "clockwise" },
    });
    speech(1, all);
    add(1, [1, 2, 3, 4], ActionWindow.OnPreVote, null);
    vote(1, all, alternate ? 8 : 1);
    if (!alternate) last(1, 1);
    wolves(2, alternate ? [1, 2, 3, 4] : [2, 3, 4], 7);
    add(2, [6], "witch", {
      name: "use_potion",
      args: { target_id: 4, potion_type: PotionType.Poison },
    });
    add(2, [5], "seer", { name: "check_identity", args: { target_id: 2 } });
    add(2, [7], "hunter_shot", { name: "shoot", args: { target_id: 3 } });
    add(2, [alternate ? 1 : 8], "sheriff_choose_direction", {
      name: "choose_direction",
      args: { direction: "clockwise" },
    });
    speech(2, alternate ? [1, 2, 5, 6, 8, 9, 10, 11, 12] : [2, 5, 6, 8, 9, 10, 11, 12]);
    if (alternate) {
      add(2, [1, 2], ActionWindow.OnPreVote, null);
      vote(2, [1, 2, 5, 6, 9, 10, 11, 12], 1);
      last(2, 1);
      wolves(3, [2], 5);
      add(3, [6], "witch", {
        name: "use_potion",
        args: { target_id: 6, potion_type: PotionType.None },
      });
      add(3, [5], "seer", { name: "check_identity", args: { target_id: 2 } });
      add(3, [2], "sheriff_choose_direction", {
        name: "choose_direction",
        args: { direction: "clockwise" },
      });
      speech(3, [2, 6, 8, 9, 10, 11, 12]);
    }
    add(alternate ? 3 : 2, [2], ActionWindow.OnPreVote, {
      name: "self_destruct",
      args: { reason: "Final wolf", confirm: true },
    });
  }
  return rows;
}

/**
 * Builds original shared test test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { ActionWindow } from "../../../../src/core";
import type { ToolCall } from "../../../../src/core";
import type { PlannedTurn } from "../../transport/contracts";

export function selfDestructTransportPlan(window: ActionWindow): Map<number, PlannedTurn[]> {
  const rows = new Map<number, PlannedTurn[]>(
    Array.from({ length: 6 }, (_, index) => [index + 1, []]),
  );
  const add = (
    day: number,
    actors: number[],
    stage: PlannedTurn["stage"],
    action: ToolCall | null | ((actor: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      rows
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const wolves = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End discussion", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const speech = (day: number, actors: number[]) =>
    add(day, actors, "day_speech", (actor) => ({
      name: "speak",
      args: { text: `Day ${day}, seat ${actor}` },
    }));
  const explode = (day: number, actors: number[], winner: number) =>
    add(day, actors, window, (actor) =>
      actor === winner
        ? { name: "self_destruct", args: { reason: "Literal window decision", confirm: true } }
        : null,
    );
  wolves(1, [1, 4], 3);
  add(1, [5], "guard", { name: "guard", args: { target_id: null, abstain: true } });
  add(1, [2], "seer", { name: "check_identity", args: { target_id: 1 } });
  if (window === ActionWindow.OnPreElection) explode(1, [1, 4], 1);
  else {
    add(1, [1, 2, 3, 4, 5, 6], "sheriff_nomination", (actor) => ({
      name: "run_for_sheriff",
      args: { run: actor === 2 },
    }));
    add(1, [2], "sheriff_campaign_speech", { name: "speak", args: { text: "Campaign" } });
    add(1, [2], "sheriff_withdraw", { name: "run_for_sheriff", args: { run: true } });
    add(1, [1, 3, 4, 5, 6], "sheriff_vote", {
      name: "vote_for_sheriff",
      args: { target_id: 2, abstain: false },
    });
  }
  add(1, [3], "last_words", { name: "speak", args: { text: "Last words 3" } });
  if (window === ActionWindow.OnDaybreak) explode(1, [1, 4], 1);
  if (window === ActionWindow.OnPerSpeechGap || window === ActionWindow.OnPreVote) {
    add(1, [2], "sheriff_choose_direction", {
      name: "choose_direction",
      args: { direction: "clockwise" },
    });
    speech(1, window === ActionWindow.OnPerSpeechGap ? [4] : [4, 5, 6, 1, 2]);
    explode(1, [1, 4], 1);
  }
  wolves(2, [4], 5);
  add(2, [5], "guard", { name: "guard", args: { target_id: null, abstain: true } });
  add(2, [2], "seer", { name: "check_identity", args: { target_id: 4 } });
  if (window === ActionWindow.OnPreElection) {
    speech(2, [2, 4, 6]);
    add(2, [2, 4, 6], "voting", { name: "vote", args: { target_id: 4, abstain: false } });
    add(2, [4], "last_words", { name: "speak", args: { text: "Last words 4" } });
  } else {
    if (window !== ActionWindow.OnDaybreak) {
      add(2, [2], "sheriff_choose_direction", {
        name: "choose_direction",
        args: { direction: "clockwise" },
      });
      speech(2, window === ActionWindow.OnPerSpeechGap ? [4] : [4, 6, 2]);
    }
    explode(2, [4], 4);
  }
  return rows;
}

/**
 * Inert LLM test drivers deliver supplied action scripts through the existing client callbacks.
 * Inputs are literal outputs, tool arguments and caller-owned message assertions;
 * outputs retain original callback traces, captured messages and retry/error state.
 * Fixed protocol assertions remain literal in these clients; callers own gameplay
 * expectations and recording. No SDK request, network, model or game runs at import.
 */
import { expect } from "bun:test";
import { PotionType, type ActionProvider, type ActionRequest, type ToolCall } from "../../../../src/core";

export const REQUIRED_ACTION_CONSTRAINTS = {
  min_valid_actions: 1,
  max_valid_actions: 1,
};

export class AssertClient {
  constructor(
    private readonly output: string,
    private readonly assertFn: (messages: Array<{ role: string; content: string }>) => void,
  ) {}

  async chat(messages: Array<{ role: string; content: string }>): Promise<string> {
    this.assertFn(messages);
    return this.output;
  }

  async runToolLoop<T>(
    messages: Array<{ role: string; content: string }>,
    _tools: Array<{ name: string }>,
    callbacks: {
      onToolCall: (invocation: {
        id: string;
        name: string;
        args: Record<string, unknown>;
        rawArgs: string;
      }) => Promise<{
        toolResult: Record<string, unknown> | string;
        finalAction?: T;
        stop?: boolean;
      }>;
    },
  ): Promise<{ finalAction: T | null; assistantText: string }> {
    this.assertFn(messages);
    const invocation = JSON.parse(this.output) as { name: string; args: Record<string, unknown> };
    const handled = await callbacks.onToolCall({
      id: "assert_tool",
      name: invocation.name,
      args: invocation.args,
      rawArgs: this.output,
    });
    return { finalAction: (handled.finalAction ?? null) as T | null, assistantText: "assert_tool" };
  }
}

export class ToolLoopClient {
  public lastMessages: Array<{ role: string; content: string }> = [];

  constructor(
    private readonly toolName: string,
    private readonly args: Record<string, unknown>,
  ) {}

  async chat(): Promise<string> {
    return "";
  }

  async runToolLoop<T>(
    messages: Array<{ role: string; content: string }>,
    _tools: Array<{ name: string }>,
    callbacks: {
      onToolCall: (invocation: {
        id: string;
        name: string;
        args: Record<string, unknown>;
        rawArgs: string;
      }) => Promise<{
        toolResult: Record<string, unknown> | string;
        finalAction?: T;
        stop?: boolean;
      }>;
    },
  ): Promise<{ finalAction: T | null; assistantText: string }> {
    this.lastMessages = messages;
    const handled = await callbacks.onToolCall({
      id: "tool_1",
      name: this.toolName,
      args: this.args,
      rawArgs: JSON.stringify(this.args),
    });
    return {
      finalAction: (handled.finalAction ?? null) as T | null,
      assistantText: "sdk_tool_loop_assistant",
    };
  }
}

export class NoActionToolLoopClient {
  public lastMessages: Array<{ role: string; content: string }> = [];

  async chat(): Promise<string> {
