  const turns = new Map(ids.map((id) => [id, [] as PlannedTurn[]]));
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((id: number) => ToolCall | null),
  ) => {
    for (const id of actors)
      turns
        .get(id)!
        .push({ day, stage, action: typeof action === "function" ? action(id) : action });
  };
  for (const day of [1, 2]) {
    if (guard)
      add(day, [guard], "guard", { name: "guard", args: { target_id: null, abstain: true } });
    add(day, wolves, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "", end_chat: true },
    });
    add(day, wolves, "wolf_vote", {
      name: "kill_vote",
      args: {
        target_id: day === 2 && size === 12 ? hunter : null,
        abstain: !(day === 2 && size === 12),
      },
    });
    add(day, [witch], "witch", {
      name: "use_potion",
      args: {
        target_id: day === 1 ? demonId : witch,
        potion_type: day === 1 ? PotionType.Poison : PotionType.None,
      },
    });
    add(day, [seer], "seer", { name: "check_identity", args: { target_id: wolves[0]! } });
    if (day === 2)
      add(day, [demonId], "demon_hunter", {
        name: "demon_hunt",
        args: { target_id: wolves[0]!, abstain: false },
      });
    if (day === 2 && size === 12)
      add(day, [hunter], "hunter_shot", { name: "shoot", args: { target_id: wolves[2]! } });
    const alive =
      day === 1
        ? ids
        : ids.filter(
            (id) => id !== wolves[0] && !(size === 12 && [hunter, wolves[2]].includes(id)),
          );
    const pack = wolves.filter((id) => alive.includes(id));
    if (day === 1 && size === 12) {
      add(day, pack, ActionWindow.OnPreElection, null);
      add(day, alive, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
    }
    add(day, alive, "day_speech", { name: "speak", args: { text: "" } });
    add(day, pack, ActionWindow.OnPreVote, null);
    add(day, alive, "voting", (id) => ({
      name: "vote",
      args: {
        target_id: day === 1 || id === wolves[1] ? null : wolves[1]!,
        abstain: day === 1 || id === wolves[1],
      },
    }));
    if (day === 2) add(day, [wolves[1]!], "last_words", { name: "speak", args: { text: "" } });
  }
  return {
    seed,
    roles,
    turns,
    demonId,
    winner: Camp.Good,
    alive: ids.filter((id) => !wolves.includes(id) && !(size === 12 && id === hunter)),
    board: parseBoardDefinition(
      boardDefinitionFromConfig(`demon_transport_${size}_${goal}`, demonHunterBoard(size, goal)),
    ),
  };
}

export function demonHunterFailureScenario(
  size: 6 | 12,
  goal: WinCondition,
  failure: "missing" | "late",
): TransportGameScenario & { demonId: number } {
  const scenario = demonHunterTransportScenario(size, goal);
  const turns = new Map<number, PlannedTurn[]>();
  const before = new Set([
    "guard",
    "wolf_discussion",
    "wolf_vote",
    "witch",
    "seer",
    "demon_hunter",
  ]);
  for (const [actor, plan] of scenario.turns)
    turns.set(
      actor,
      plan
        .filter((t) => t.day === 1 || (t.day === 2 && before.has(t.stage)))
        .map((t) =>
          t.stage === "demon_hunter"
            ? { ...t, terminalFailure: failure, action: failure === "missing" ? null : t.action }
            : t,
        ),
    );
  return {
    ...scenario,
    turns,
    expectedFailure: { actorId: scenario.demonId, stage: "demon_hunter" },
  };
}

/**
 * Defines original demon-hunter planning data contracts for public test support. Inputs are explicitly
 * authored turn/actor/scenario data; outputs preserve the original nullable choices, source fields and
 * exact callback types. No game, model, filesystem, live permission or expected outcome is allocated or
 * computed here.
 */
import "../../../../src/app/bootstrap";
import { PotionType } from "../../../../src/core";

export interface DemonNightChoices {
  knife?: number | null;
  hunt?: number | null;
  guard?: number | null;
  potion?: { target: number; type: PotionType };
  shot?: number | null;
}

/**
 * Provides the original demon-hunter scripted action driver for tests.
 * Inputs are issued requests, explicit choices or captured game handles;
 * outputs are the same callbacks and literal ToolCalls/null decisions.
 * It keeps the original local reads and defaults, without running a model,
 * advancing a phase, changing stock or regenerating expected outcomes.
 */
import type { DemonNightChoices } from "../contracts";
import "../../../../../src/app/bootstrap";
import { PotionType } from "../../../../../src/core";
import type { ActionRequest } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import type { ToolName } from "../../../../../src/core";

export function demonNightChoice(
  request: ActionRequest,
  witchId: number,
  choices: DemonNightChoices = {},
): ToolCall | null {
  const tools = request.allowedTools;
  if (tools.includes("guard"))
    return {
      name: "guard",
      args: { target_id: choices.guard ?? null, abstain: choices.guard == null },
    };
  if (tools.includes("speak_to_wolves"))
    return { name: "speak_to_wolves", args: { text: "", end_chat: true } };
  if (tools.includes("kill_vote"))
    return {
      name: "kill_vote",
      args: { target_id: choices.knife ?? null, abstain: choices.knife == null },
    };
  if (tools.includes("use_potion"))
    return {
      name: "use_potion",
      args: {
        target_id: choices.potion?.target ?? witchId,
        potion_type: choices.potion?.type ?? PotionType.None,
      },
    };
  if (tools.includes("check_identity")) return { name: "check_identity", args: { target_id: 1 } };
  if ((tools as readonly string[]).includes("demon_hunt"))
    return {
      name: "demon_hunt" as ToolName,
      args: { target_id: choices.hunt ?? null, abstain: choices.hunt == null },
    } as ToolCall;
  if (tools.includes("shoot")) return { name: "shoot", args: { target_id: choices.shot ?? null } };
  if (tools.includes("speak")) return { name: "speak", args: { text: "" } };
  if (tools.includes("run_for_sheriff")) return { name: "run_for_sheriff", args: { run: false } };
  if (tools.includes("vote")) return { name: "vote", args: { target_id: null, abstain: true } };
  return null;
}

/**
 * Builds original dreamer test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { Role } from "../../../../../src/core";
import { WinCondition } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { sixPlayerMvpConfig } from "../../../../../src/runtime/scenarios/six_player_mvp";
