const cache = new Map<string, Promise<ReproductionRecord>>();

export interface MistRequestObservation {
  day: number;
  stage: ActionRequest["context"]["stage"];
  actorId: number;
  aliveIds: number[];
  sheriffIds: number[];
  gameOver: boolean;
  publishedTypes: string[];
}

export function mistRecording(
  variant: MistRecordVariant = "linked",
  locale: "en" | "zh-CN" = "en",
  seed = "mist-raven-real-runtime",
  observe?: (observation: MistRequestObservation) => void,
  artifactDirectory?: string,
): Promise<ReproductionRecord> {
  const key = variant + locale + seed;
  if (!observe && !artifactDirectory && cache.has(key)) return cache.get(key)!;
  const run = (async () => {
    const board = await mistBoard(),
      config = board.config;
    const game = bootstrapGame(config, {
      locale,
      random: createRandom(seed),
      fixedRoles: MIST_ROLES,
    });
    const root = await createTestTempDirectory("awa-mist-tape-");
    try {
      const manager = await SessionRecordManager.create(
        {
          sessionId: "game",
          board: board.definition.id,
          startedAtIso: new Date().toISOString(),
          locale,
          random: game.random.metadata,
        },
        root,
      );
      const events = new GameEventRecorder(
        { world: game.world, replayManager: manager },
        game.phaseManager.getSnapshot().phase,
      );
      let last: RecordedCheckpoint | undefined;
      const requestCounts = new Map<string, number>();
      await runWithSessionRecorder(manager, async () => {
        const trace = beginGameReproduction(manager, game, {
          engine: await currentEngineVersion(),
          boardId: board.definition.id,
          ...(void config, {}),
          locale,
          maxDays: 8,
        });
        for (let cycle = 1; cycle <= 8 && !game.phaseManager.getSnapshot().gameOver; cycle++) {
          let cycleFailure: unknown;
          try {
            await game.phaseManager.runSingleCycle(
              {
                getAction: (q) =>
                  trace.decide(q, {
                    async getAction(request) {
                      if (observe)
                        observe({
                          day: request.context.day,
                          stage: request.context.stage,
                          actorId: request.actorId,
                          aliveIds: game.world.getAliveEntityIds(),
                          sheriffIds: game.world
                            .getAliveEntityIds()
                            .filter(
                              (id) =>
                                game.world.getComponent(id, COMPONENT.Badge)
                                  ?.isSheriff,
                            ),
                          gameOver: game.phaseManager.getSnapshot().gameOver,
                          publishedTypes: game.phaseManager.getEvents().map((e) => e.type),
                        });
                      const key = `${request.actorId}/${request.context.day}/${request.context.stage}`;
                      const round = (requestCounts.get(key) ?? 0) + 1;
                      requestCounts.set(key, round);
                      return mistAction(request, variant, round);
                    },
                  }),
              },
              8,
            );
          } catch (error) {
            if (
              variant !== "last-god-illegal-self" ||
              cycle !== 3 ||
              !(error instanceof Error) ||
              error.message !== "snake_action_invalid"
            )
              throw error;
            cycleFailure = error;
            trace.noteFailure("cycle", error);
          }
          last = captureCheckpoint(
            game.world,
            game.phaseManager.getSnapshot(),
            cycle,
            cycleFailure === undefined,
            game.phaseManager.getEvents().length,
            cycleFailure,
          );
          trace.checkpoint(last, game.phaseManager.getEvents());
          events.flush(game.phaseManager.getEvents());
          if (cycleFailure) break;
        }
        const snapshot = game.phaseManager.getSnapshot();
        const failed = variant === "last-god-illegal-self";
        if (failed && (last?.complete || snapshot.gameOver))
          throw new Error("mist_fixture_failed_to_fail");
        if (!failed && (!snapshot.gameOver || snapshot.result?.reason === "max_days_reached"))
          throw new Error("mist_fixture_failed_to_end_naturally");
        await manager.finalize({
          endedAtIso: new Date().toISOString(),
          winner: snapshot.result?.winner ?? null,
          finishReason: failed ? "runtime_error" : snapshot.result!.reason,
          ...(snapshot.result ? { gameResult: snapshot.result } : {}),
          players: last!.players.map((p) => ({
            player_id: p.id,
            role: p.role,
            camp: p.camp,
            alive: p.alive,
          })),
        });
      });
      const record = parseReproductionRecord(
        JSON.parse(await readFile(manager.sessionDir + "/reproduction.json", "utf8")),
      );
      const replay = await replayReproduction(record, root);
      if (JSON.stringify(replay.snapshot) !== JSON.stringify(record.checkpoints.at(-1)!.snapshot))
        throw new Error("mist_fixture_replay_changed_snapshot");
      if (artifactDirectory) {
        const name = `mist-manual-${variant}-${locale}`;
        await mkdir(path.join(artifactDirectory, "player-views"), { recursive: true });
        await copyFile(
          path.join(manager.sessionDir, "replay.json"),
          path.join(artifactDirectory, name + ".replay.json"),
        );
        await writeFile(
          path.join(artifactDirectory, name + ".checkpoint.txt"),
          JSON.stringify(record.checkpoints.at(-1), null, 2) + "\n",
        );
        for (const [label, actor] of [
          ["alchemist", 1],
          ["raven", 9],
          ["pack", 10],
          ["villager", 5],
        ] as const)
          await copyFile(
            path.join(manager.sessionDir, `players/player_${actor}.json`),
            path.join(artifactDirectory, "player-views", `${name}-${label}.player.json`),
          );
      }
      return record;
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  })();
  if (!observe && !artifactDirectory) cache.set(key, run);
  return run;
}

/**
 * Builds original nightmare-shadow test input plans, fixed boards and explicit player/marker data. Inputs
 * are supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { ActionWindow } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { nightmareTwelveConfig } from "../../../../../src/runtime/scenarios/nightmare_twelve";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export function nightmareScenario(): TransportGameScenario & {
  nightmare: number;
  seer: number;
  hunter: number;
  alive: number[];
  winner: Camp;
} {
  const config = structuredClone(nightmareTwelveConfig),
    seed = "nightmare-transport-day-shot";
  config.nightmareShadow!.wolfActionPolicy = "no_blast_no_self_knife";
  const roles = shuffled(
    config.roleSetups.flatMap((r) => Array.from({ length: r.count }, () => r.role)),
    createRandom(seed).fork("deal"),
  );
  const ids = roles.map((_, i) => i + 1),
    id = (r: Role) => roles.indexOf(r) + 1;
  const nightmare = id(Role.NightmareShadow),
    seer = id(Role.Seer),
    witch = id(Role.Witch),
    hunter = id(Role.Hunter),
    dreamer = id(Role.Dreamer);
  const ordinary = ids.filter((i) => roles[i - 1] === Role.Wolf),
    villagers = ids.filter((i) => roles[i - 1] === Role.Villager);
  const wolves = [...ordinary, nightmare].sort((a, b) => a - b);
  const turns = new Map<number, PlannedTurn[]>(ids.map((i) => [i, []]));
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((actor: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      turns
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Words" } });
  const pack = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const speech = (day: number, alive: number[], exile: number, first: boolean) => {
    const blast = ordinary.filter((i) => alive.includes(i));
    if (first) {
      add(day, blast, ActionWindow.OnPreElection, null);
      add(day, alive, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
    }
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(day, blast, ActionWindow.OnPreVote, null);
    add(day, alive, "voting", (actor) => ({
      name: "vote",
      args: { target_id: actor === exile ? null : exile, abstain: actor === exile },
    }));
    words(day, [exile]);
  };
  add(1, [nightmare], "nightmare_fear", {
    name: "fear",
    args: { target_id: seer, abstain: false },
  });
  add(1, [dreamer], "dreamer", { name: "dream", args: { target_id: villagers[0]! } });
  pack(1, wolves, ordinary[2]!);
  add(1, [witch], "witch", {
    name: "use_potion",
    args: { target_id: ordinary[0]!, potion_type: PotionType.Poison },
  });
  add(1, ordinary, ActionWindow.OnPreElection, null);
  add(1, ids, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
  words(1, [ordinary[0]!, ordinary[2]!]);
  const alive1 = ids.filter((i) => i !== ordinary[0] && i !== ordinary[2]);
  speech(1, alive1, ordinary[1]!, false);
  const alive2 = alive1.filter((i) => i !== ordinary[1]);
  add(2, [nightmare], "nightmare_fear", {
    name: "fear",
    args: { target_id: hunter, abstain: false },
  });
  add(2, [dreamer], "dreamer", { name: "dream", args: { target_id: villagers[1]! } });
  pack(2, [nightmare], witch);
  add(2, [witch], "witch", {
    name: "use_potion",
    args: { target_id: witch, potion_type: PotionType.None },
  });
  add(2, [seer], "seer", { name: "check_identity", args: { target_id: villagers[0]! } });
  const day2 = alive2.filter((i) => i !== witch);
  speech(2, day2, hunter, false);
  add(2, [hunter], "hunter_shot", { name: "shoot", args: { target_id: nightmare } });
  return {
    board: parseBoardDefinition(boardDefinitionFromConfig("nightmare_transport_day_shot", config)),
    seed,
    roles,
    turns,
    nightmare,
    seer,
    hunter,
    alive: day2.filter((i) => i !== hunter && i !== nightmare),
    winner: Camp.Good,
  };
}

