export type NobleTransportPlanName = keyof typeof plans;

export function nobleTransportScenario(
  name: NobleTransportPlanName = "expiry",
  options: {
    wolf?: "standard" | "no_blast_no_self_knife";
    repeat?: "awa_nonconsecutive_nights_v1" | "awa_repeat_v1";
  } = {},
) {
  const config = nobleSecretBodyTwelveConfig(options.wolf, options.repeat),
    seed = "noble-body-transport-v1",
    board = parseBoardDefinition(boardDefinitionFromConfig("awa_noble_secret_body_12_v1", config)),
    original = config.roleSetups.flatMap((row) => Array<Role>(row.count).fill(row.role)),
    roles = shuffled(original, createRandom(seed).fork("deal")),
    ids = roles.map((_, i) => i + 1),
    used = new Map<Role, number>(),
    mapping = new Map<number, number>();
  for (let old = 1; old <= 12; old++) {
    const role = original[old - 1]!,
      matches = ids.filter((id) => roles[id - 1] === role),
      index = used.get(role) ?? 0;
    mapping.set(old, matches[index]!);
    used.set(role, index + 1);
  }
  const map = (old: number) => mapping.get(old)!,
    target = (old: number | null) => (old === null ? null : map(old)),
    list = (olds: readonly number[]) => olds.map(map).sort((a, b) => a - b),
    plan = plans[name],
    turns = new Map<number, PlannedTurn[]>(ids.map((id) => [id, []]));
  const add = (
    day: number,
    actors: readonly number[],
    stage: ActionStage,
    action: ToolCall | null | ((old: number) => ToolCall | null),
  ) => {
    for (const old of actors)
      turns
        .get(map(old))!
        .push({ day, stage, action: typeof action === "function" ? action(old) : action });
  };
  const wolves = [1, 10, 11, 12];
  const blast = "blast" in plan ? plan.blast : null,
    blastAction = (old: number): ToolCall | null =>
      old === blast?.actor
        ? { name: "self_destruct", args: { confirm: true, reason: "Literal window interruption." } }
        : null;
  let sheriff: number | null = plan.sheriff;
  for (let i = 0; i < plan.exile.length; i++) {
    const day = i + 1,
      start: readonly number[] =
        i === 0 ? Array.from({ length: 12 }, (_, i) => i + 1) : plan.alive[i - 1]!,
      pack = wolves.filter((id) => start.includes(id)),
      canBlast = pack.filter((id) => !(id === 1 && options.wolf === "no_blast_no_self_knife"));
    if (plan.bodyActive[i])
      add(day, [5], "secret_body", {
        name: "protect_secret_body",
        args: {
          target_id: target(
            name === "expiry" && options.repeat === "awa_repeat_v1" && day === 2
              ? 6
              : plan.body[i]!,
          ),
        },
      });
    add(day, pack, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End discussion", end_chat: true },
    });
    add(day, pack, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target(plan.knife[i]!), abstain: plan.knife[i] === null },
    });
    if (plan.nobleActive[i])
      add(day, [1], "night_noble", {
        name: "choose_servant",
        args: { target_id: target(plan.servant[i]!) },
      });
    const bottle =
      "potions" in plan
        ? plan.potions[i]
        : name === "two_sources" && day === 3
          ? (["poison", 6] as const)
          : null;
    if (start.includes(3))
      add(day, [3], "witch", {
        name: "use_potion",
        args: {
          target_id: bottle ? map(bottle[1]) : map(3),
          potion_type: bottle
            ? bottle[0] === "heal"
              ? PotionType.Heal
              : PotionType.Poison
            : PotionType.None,
        },
      });
    if (start.includes(2))
      add(day, [2], "seer", { name: "check_identity", args: { target_id: map(7) } });
    if (day >= 2 && start.includes(4))
      add(day, [4], "demon_hunter", {
        name: "demon_hunt",
        args: { target_id: target(plan.hunt[i]!), abstain: plan.hunt[i] === null },
      });
    const live = start.filter((id) => !(plan.deaths[i] as readonly number[]).includes(id));
    if (day === 1) {
      add(day, plan.deaths[i]!, "last_words", {
        name: "speak",
        args: { text: "Literal initial-wave last words" },
      });
      add(
        day,
        canBlast.filter((id) => live.includes(id)),
        ActionWindow.OnPreElection,
        blast?.day === day && blast.stage === "on_pre_election" ? blastAction : null,
      );
      if (blast?.day === day && blast.stage === "on_pre_election") continue;
      add(day, live, "sheriff_nomination", (old) => ({
        name: "run_for_sheriff",
        args: { run: old === sheriff },
      }));
      if (sheriff !== null) {
        add(day, [sheriff], "sheriff_campaign_speech", {
          name: "speak",
          args: { text: "Campaign" },
        });
        add(day, [sheriff], "sheriff_withdraw", { name: "run_for_sheriff", args: { run: true } });
      }
    }
    if (sheriff !== null)
      add(day, [sheriff], "sheriff_choose_direction", {
        name: "choose_direction",
        args: { direction: "clockwise" },
      });
    add(day, live, "day_speech", { name: "speak", args: { text: "Literal public speech" } });
    add(
      day,
      canBlast.filter((id) => live.includes(id)),
      ActionWindow.OnPreVote,
      blast?.day === day && blast.stage === "on_pre_vote" ? blastAction : null,
    );
    if (blast?.day === day && blast.stage === "on_pre_vote") continue;
    const exile = plan.exile[i]!;
    add(day, live, "voting", (old) => ({
      name: "vote",
      args: { target_id: old === exile ? null : map(exile), abstain: old === exile },
    }));
    if (name === "badge_reveal" && day === 1)
      add(day, [5], "awakened_idiot_reveal_speech", {
        name: "speak",
        args: { text: "My revealed role retains the vote and badge." },
      });
    else {
      add(day, [exile], "last_words", { name: "speak", args: { text: "Literal last words" } });
      if (sheriff === exile) {
        add(day, [exile], "sheriff_badge_choice", {
          name: "choose_badge_successor",
          args: { target_id: map(2) },
        });
        sheriff = 2;
      }
    }
  }
  const names: Partial<Record<Role, [string, string]>> = {
    [Role.NightNoble]: ["夜之贵族", "Night Noble"],
    [Role.AwakenedIdiot]: ["觉醒愚者", "Awakened Village Idiot"],
    [Role.Seer]: ["预言家", "Seer"],
    [Role.Witch]: ["女巫", "Witch"],
    [Role.DemonHunter]: ["猎魔人", "Demon Hunter"],
    [Role.Wolf]: ["狼人", "Werewolf"],
    [Role.Villager]: ["平民", "Villager"],
  };
  const scenario: TransportGameScenario = {
    board,
    seed,
    roles,
    turns,
    promptAssertions(actor, locale) {
      const role = roles[actor - 1]!;
      return {
        verifyGameWire: true,
        expectedIdentityMarker:
          locale === "en"
            ? `your true role is ${names[role]![1]}.`
            : `你的真实身份是${names[role]![0]}。`,
        expectedTeammateIds: [Role.Wolf, Role.NightNoble].includes(role)
          ? list(wolves).filter((id) => id !== actor)
          : [],
      };
    },
  };
  return {
    ...scenario,
    name,
    mapping,
    winner: Camp.Good,
    alive: list(plan.alive.at(-1)!),
    nightDeaths: plan.deaths.map(list),
    cycleAlive: plan.alive.map(list),
    plan,
  };
}

/**
 * 负责驱动夜贵族子系统的原 World fixture、有界夜选择、伤害和关闭。输入为脚本步骤、回调与资源请求，输出为原受控轨迹、句柄及边界响应。测试保留字面行动和失败预期；不运行完整对局或传输，也不引入付费模型。
 */
import { createAliveComponent, createCampComponent } from "../../../../../src/game/observation/component-presentation";
import { World } from "../../../../../src/core/domain/world";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { Role, Camp } from "../../../../../src/core/domain/identity";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";
import { type AliveComponent } from "../../../../../src/core/domain/components/alive";

import { createVictoryComponent } from "../../../../../src/core/domain/components/victory";
import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import {
  createNobleState,
  createSecretBodyState,
} from "../../../../../src/game/mechanisms/roles/noble_secret_body/state";
import {
  installNobleBodyAuthority,
  beginNobleBodyNight,
  openSecretBodyChoice,
  openServantChoice,
  expireServantAtNightEnd,
  resolveSecretBodyDamage,
  closeNobleBodyNight,
} from "../../../../../src/game/mechanisms/roles/noble_secret_body/authority";
/** 显式子系统夹具：既有替身身份验证原对象所有权与实际 Camp 槽；不注册额外角色或冒整局规则验收。 */
export function nobleBodyAuthorityFixture() {
  const world = new World(),
    roles = [];
  for (let id = 1; id <= 6; id++) {
    const actual = world.createEntity(),
      camp = id === 1 ? Camp.Wolf : Camp.Good,
      role = createRoleComponent(id === 1 ? Role.Wolf : Role.Villager);
    if (id === 1) (role.privateState as Record<string, unknown>).noble = createNobleState();
    if (id === 2)
      (role.privateState as Record<string, unknown>).secretBody = createSecretBodyState();
    world.addComponent(actual, COMPONENT.Role, role);
    world.addComponent(
      actual,
      COMPONENT.Identity,
      createIdentityComponent(actual, actual, `Synthetic ${actual}`),
    );
    world.addComponent(actual, COMPONENT.Camp, createCampComponent(camp));
    world.addComponent(
      actual,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: camp }]),
    );
    world.addComponent(actual, COMPONENT.Alive, createAliveComponent());
    roles.push(role);
  }
  installNobleBodyAuthority(world, 1, 2);
  const life = (id: number) => world.getComponent(id, COMPONENT.Alive)!;
  const finish = (day: number) => {
    expireServantAtNightEnd(world, day);
    closeNobleBodyNight(world, day, "normal");
    return resolveSecretBodyDamage(world, day, {});
  };
  const night = (
    day: number,
    bodyTarget: number | null = null,
    nobleTarget: number | null = null,
  ) => {
    beginNobleBodyNight(world, day, () => true);
    openSecretBodyChoice(world, day).commit(bodyTarget);
    if (day >= 2) openServantChoice(world, day).commit(nobleTarget);
  };
  return { world, roles, life, finish, night };
}

/**
 * 测试 driver：负责原贵族／不死之身受控执行及录制。输入为原固定角色、动作与局部 store；输出保留原请求和录制前缀，独立预期不由此 driver 生成，不调用模型。
 */
import { nobleLiteralPlans } from "../builders/literal-plans";
import { readFile } from "node:fs/promises";
import { rm } from "node:fs/promises";
import { bootstrapGame } from "../../../../../src/app/bootstrap";
import { COMPONENT } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import type { ActionRequest } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { nobleSecretBodyTwelveConfig } from "../../../../../src/runtime/scenarios/noble_secret_body_twelve";
import { SessionRecordManager } from "../../../../../src/recording/session_recorder";
import { runWithSessionRecorder } from "../../../../../src/recording/recording_context";
import { beginGameReproduction } from "../../../../../src/runtime/simulation/reproduction_context";
import { captureCheckpoint } from "../../../../../src/runtime/simulation/reproduction_context";
import { currentEngineVersion } from "../../../../../src/runtime/simulation/reproduction_context";
import { parseReproductionRecord } from "../../../../../src/recording/reproduction";
import { replayReproduction } from "../../../../../src/runtime/simulation/replay_reproduction";
import { demonNightChoice } from "../../demon-hunter/drivers/actions";
import { createTestTempDirectory } from "../../../drivers/temp-directories";

export async function recordNobleLiteral(
  name = "expiry",
  locale: "zh-CN" | "en" = "zh-CN",
  options: {
    wolf?: "standard" | "no_blast_no_self_knife";
    repeat?: "awa_nonconsecutive_nights_v1" | "awa_repeat_v1";
    failureStage?: string;
    failureDay?: number;
    badgeChoice?: "missing" | "invalid";
    blastDay?: number;
  } = {},
) {
  const config = nobleSecretBodyTwelveConfig(options.wolf, options.repeat),
    game = bootstrapGame(config, {
      locale,
      random: createRandom(`noble-literal:${name}`),
      fixedRoles: config.roleSetups.flatMap((r) => Array<Role>(r.count).fill(r.role)),
    }),
    root = await createTestTempDirectory("awa-noble-ledger-");
  let manager: SessionRecordManager | undefined;
  try {
    manager = await SessionRecordManager.create(
      {
        sessionId: "game",
        board: "awa_noble_secret_body_12_v1",
        startedAtIso: new Date().toISOString(),
        locale,
        random: game.random.metadata,
      },
      root,
    );
    const activeManager = manager;
    await runWithSessionRecorder(activeManager, async () => {
      const trace = beginGameReproduction(activeManager, game, {
        engine: await currentEngineVersion(),
        boardId: "awa_noble_secret_body_12_v1",
        ...(void config, {}),
        locale,
        maxDays: 8,
      });
      for (let cycle = 1; cycle <= 8 && !game.phaseManager.getSnapshot().gameOver; cycle++) {
        let failure: unknown;
        try {
          await game.phaseManager.runSingleCycle(
            {
              getAction: (q) =>
                trace.decide(q, {
                  async getAction(r: ActionRequest): Promise<ToolCall | null> {
                    const n = nobleLiteralPlans[name]![r.context.day - 1];
                    if (!n) throw Error("noble_literal_plan_exhausted");
                    if (
                      r.actorId === 1 &&
                      r.context.day === options.blastDay &&
                      r.context.stage === "on_pre_vote" &&
                      r.allowedTools.includes("self_destruct")
                    )
                      return {
                        name: "self_destruct",
                        args: { confirm: true, reason: "Literal skipped-vote restart." },
                      };
                    if (
                      r.context.day === (options.failureDay ?? 2) &&
                      r.context.stage === options.failureStage
                    )
                      return null;
                    if (r.allowedTools.includes("protect_secret_body"))
                      return { name: "protect_secret_body", args: { target_id: n.body } };
                    if (r.allowedTools.includes("choose_servant"))
                      return { name: "choose_servant", args: { target_id: n.servant } };
                    if (r.allowedTools.includes("check_identity"))
                      return { name: "check_identity", args: { target_id: 7 } };
                    if (r.allowedTools.includes("vote"))
                      return {
                        name: "vote",
                        args: {
                          target_id: r.actorId === n.exile ? null : n.exile,
                          abstain: n.exile === null || r.actorId === n.exile,
                        },
                      };
                    if (name === "badge_reveal") {
                      if (r.allowedTools.includes("run_for_sheriff"))
                        return { name: "run_for_sheriff", args: { run: r.actorId === 5 } };
                      if (r.allowedTools.includes("vote_for_sheriff"))
                        return { name: "vote_for_sheriff", args: { target_id: 5, abstain: false } };
                      if (r.allowedTools.includes("choose_badge_successor"))
                        return options.badgeChoice === "missing"
                          ? null
                          : {
                              name: "choose_badge_successor",
                              args: { target_id: options.badgeChoice === "invalid" ? 999 : 2 },
                            };
                    }
                    if (r.allowedTools.includes("choose_direction"))
                      return { name: "choose_direction", args: { direction: "clockwise" } };
                    if (r.allowedTools.includes("speak"))
                      return {
                        name: "speak",
                        args: {
                          text: locale === "en" ? "Literal role evidence." : "字面角色证据。",
                        },
                      };
                    return demonNightChoice(r, 3, {
                      knife: n.knife,
                      hunt: n.hunt,
                      potion: n.potion,
                    });
                  },
                }),
            },
            8,
          );
        } catch (error) {
          failure = error;
          trace.noteFailure("cycle", error);
          if (!options.failureStage) throw error;
        }
        trace.checkpoint(
          captureCheckpoint(
            game.world,
            game.phaseManager.getSnapshot(),
            cycle,
            failure === undefined,
            game.phaseManager.getEvents().length,
            failure,
          ),
          game.phaseManager.getEvents(),
        );
        trace.build();
        if (failure) break;
      }
      const snapshot = game.phaseManager.getSnapshot();
      if (
        !options.failureStage &&
        (!snapshot.gameOver || snapshot.result?.reason === "max_days_reached")
      )
        throw Error("noble_literal_not_natural");
      await activeManager.finalize({
        endedAtIso: new Date().toISOString(),
        winner: snapshot.result?.winner ?? null,
        finishReason: options.failureStage ? "runtime_error" : snapshot.result!.reason,
        ...(snapshot.result ? { gameResult: snapshot.result } : {}),
        players: game.world.entityIds().map((id) => ({
          player_id: id,
          role: game.world.getComponent(id, COMPONENT.Role)!.role,
          camp: game.world.getComponent(id, COMPONENT.Camp)!.camp,
          alive: game.world.getComponent(id, COMPONENT.Alive)!.alive,
        })),
      });
    });
    const record = parseReproductionRecord(
        JSON.parse(await readFile(manager.sessionDir + "/reproduction.json", "utf8")),
      ),
      replay = await replayReproduction(record, root + "/tape");
    return { record, replay };
  } finally {
    await manager
      ?.finalize({
        endedAtIso: new Date().toISOString(),
        winner: game.phaseManager.getSnapshot().result?.winner ?? null,
        finishReason: "runtime_error",
        players: [],
      })
      .catch(() => undefined);
    await rm(root, { recursive: true, force: true });
  }
}

/**
 * Builds original order-prince test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { ActionWindow } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { orderPrinceTwelveConfig } from "../../../../../src/runtime/scenarios/order_prince_twelve";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export function orderPrinceScenario(
  variant: "day1" | "day2" | "pk" = "day1",
): TransportGameScenario & { prince: number; alive: number[]; winner: Camp } {
  const config = structuredClone(orderPrinceTwelveConfig),
    seed = "order-prince-transport";
  const roles = shuffled(
    config.roleSetups.flatMap((r) => Array.from({ length: r.count }, () => r.role)),
    createRandom(seed).fork("deal"),
  );
  const ids = roles.map((_, i) => i + 1),
    id = (r: Role) => roles.indexOf(r) + 1;
  const prince = id(Role.OrderPrince),
    seer = id(Role.Seer),
    witch = id(Role.Witch);
  const wolves = ids.filter((i) => roles[i - 1] === Role.Wolf),
    villagers = ids.filter((i) => roles[i - 1] === Role.Villager);
  const turns = new Map<number, PlannedTurn[]>(ids.map((i) => [i, []]));
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((actor: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      turns
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Words" } });
  const pack = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const ballot = (day: number, alive: number[], target: number, stage: ActionStage) =>
    add(day, alive, stage, (actor) => ({
      name: "vote",
      args: { target_id: actor === target ? null : target, abstain: actor === target },
    }));
  const daylight = (day: number, alive: number[], target: number) => {
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(
      day,
      wolves.filter((id) => alive.includes(id)),
      ActionWindow.OnPreVote,
      null,
    );
    const activate = (variant !== "day2" && day === 1) || (variant === "day2" && day === 2);
    ballot(day, alive, activate ? prince : target, "voting");
    if (day === 1 || (variant === "day2" && day === 2))
      add(day, [prince], "order_prince_choice", { name: "reset_exile_vote", args: { activate } });
    if (activate) {
      add(day, [prince], "order_prince_speech", {
        name: "speak",
        args: { text: "Restart this ballot." },
      });
      if (variant === "pk") {
        const candidates = [wolves[1]!, wolves[2]!],
          voters = alive.filter((id) => !candidates.includes(id));
        add(day, alive, "order_prince_revote", (actor) => ({
          name: "vote",
          args: {
            target_id: candidates.includes(actor)
              ? null
              : candidates[voters.indexOf(actor) < 4 ? 0 : 1]!,
            abstain: candidates.includes(actor),
          },
        }));
        add(day, candidates, "exile_pk_speech", { name: "speak", args: { text: "PK speech." } });
        ballot(day, voters, target, "exile_pk_vote");
      } else ballot(day, alive, target, "order_prince_revote");
    }
    words(day, [target]);
  };
  pack(1, wolves, villagers[0]!);
  add(1, [witch], "witch", {
    name: "use_potion",
    args: { target_id: wolves[0]!, potion_type: PotionType.Poison },
  });
  add(1, [seer], "seer", { name: "check_identity", args: { target_id: wolves[1]! } });
  add(1, wolves, ActionWindow.OnPreElection, null);
  add(1, ids, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
  words(1, [villagers[0]!, wolves[0]!]);
  const alive1 = ids.filter((id) => id !== villagers[0] && id !== wolves[0]);
  daylight(1, alive1, wolves[1]!);
  pack(2, [wolves[2]!, wolves[3]!], witch);
  add(2, [witch], "witch", {
    name: "use_potion",
    args: { target_id: witch, potion_type: PotionType.None },
  });
  add(2, [seer], "seer", { name: "check_identity", args: { target_id: wolves[2]! } });
  const alive2 = alive1.filter((id) => id !== wolves[1] && id !== witch);
  daylight(2, alive2, wolves[2]!);
  pack(3, [wolves[3]!], villagers[1]!);
  add(3, [seer], "seer", { name: "check_identity", args: { target_id: wolves[3]! } });
  const alive3 = alive2.filter((id) => id !== wolves[2] && id !== villagers[1]);
  daylight(3, alive3, wolves[3]!);
  return {
    board: parseBoardDefinition(
      boardDefinitionFromConfig("order_prince_transport_" + variant, config),
    ),
    seed,
    roles,
    turns,
    prince,
    alive: alive3.filter((id) => id !== wolves[3]),
    winner: Camp.Good,
  };
}

/**
 * Builds original psychic test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { PotionType } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { WinCondition } from "../../../../../src/core";
import type { BoardConfig } from "../../../../../src/core";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { sixPlayerMvpConfig } from "../../../../../src/runtime/scenarios/six_player_mvp";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export const PSYCHIC_CASES = [
  "six_skip",
  "six_repeat",
  "six_good",
  "twelve",
  "king_link",
  "hidden_mask",
] as const;

export type PsychicScenario = (typeof PSYCHIC_CASES)[number];

export function psychicScenario(kind: PsychicScenario): TransportGameScenario {
  const large = kind === "twelve",
    king = kind === "king_link",
    hidden = kind === "hidden_mask";
  const roles = large
    ? [
        Role.Wolf,
        Role.Wolf,
        Role.Wolf,
        Role.Wolf,
        Role.Psychic,
        Role.Witch,
        Role.Hunter,
        Role.Guard,
        Role.Villager,
        Role.Villager,
        Role.Villager,
        Role.Villager,
      ]
    : king
      ? [Role.WolfKing, Role.Wolf, Role.Psychic, Role.Bear, Role.Villager, Role.Villager]
      : [
          Role.Wolf,
          hidden ? Role.HiddenWolf : Role.Wolf,
          Role.Psychic,
          Role.Witch,
          Role.Villager,
          Role.Villager,
        ];
  const config: BoardConfig = {
    ...sixPlayerMvpConfig,
    boardSize: roles.length,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
      count: roles.filter((r) => r === role).length,
    })),
    winConditions: [WinCondition.SlaughterSide],
    enableSheriff: large,
    selfDestruct: { enabledWindows: [] },
  };
  const turns = new Map<number, PlannedTurn[]>(roles.map((_, i) => [i + 1, []]));
  const add = (
    day: number,
    actors: number[],
    stage: PlannedTurn["stage"],
    action: PlannedTurn["action"],
  ) => actors.forEach((actor) => turns.get(actor)!.push({ day, stage, action }));
  const knife = (day: number, actors: number[], target: number) =>
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  const pack = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    knife(day, actors, target);
  };
  const inspect = (day: number, actor: number, target: number | null) =>
    add(
      day,
      [actor],
      "psychic",
      target === null ? null : { name: "inspect_role", args: { target_id: target } },
    );
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Authorized words" } });
  const speech = (day: number, actors: number[]) =>
    add(day, actors, "day_speech", { name: "speak", args: { text: "Public speech" } });
  const vote = (day: number, actors: number[], target: number) =>
    add(day, actors, "voting", { name: "vote", args: { target_id: target, abstain: false } });
  if (large) {
    const all = Array.from({ length: 12 }, (_, i) => i + 1);
    add(1, [8], "guard", { name: "guard", args: { target_id: 10, abstain: false } });
    pack(1, [1, 2, 3, 4], 9);
    add(1, [6], "witch", {
      name: "use_potion",
      args: { target_id: 9, potion_type: PotionType.Heal },
    });
    inspect(1, 5, 6);
    all.forEach((actor) =>
      add(1, [actor], "sheriff_nomination", {
        name: "run_for_sheriff",
        args: { run: actor === 5 || actor === 10 },
      }),
    );
    add(1, [5, 10], "sheriff_campaign_speech", { name: "speak", args: { text: "Campaign" } });
    add(1, [5], "sheriff_withdraw", { name: "run_for_sheriff", args: { run: true } });
    add(1, [10], "sheriff_withdraw", { name: "run_for_sheriff", args: { run: false } });
    add(
      1,
      all.filter((id) => id !== 5),
      "sheriff_vote",
      { name: "vote_for_sheriff", args: { target_id: 5, abstain: false } },
    );
    add(1, [5], "sheriff_choose_direction", {
      name: "choose_direction",
      args: { direction: "clockwise" },
    });
    speech(1, all);
    vote(1, all, 4);
    words(1, [4]);
    add(2, [8], "guard", { name: "guard", args: { target_id: 11, abstain: false } });
    pack(2, [1, 2, 3], 7);
    add(2, [6], "witch", {
      name: "use_potion",
      args: { target_id: 3, potion_type: PotionType.Poison },
    });
    inspect(2, 5, 1);
    add(2, [7], "hunter_shot", { name: "shoot", args: { target_id: 2 } });
    add(2, [5], "sheriff_choose_direction", {
      name: "choose_direction",
      args: { direction: "clockwise" },
    });
    const alive2 = [1, 5, 6, 8, 9, 10, 11, 12];
    speech(2, alive2);
    vote(2, alive2, 9);
    words(2, [9]);
    add(3, [8], "guard", { name: "guard", args: { target_id: 10, abstain: false } });
    pack(3, [1], 6);
    add(3, [6], "witch", {
      name: "use_potion",
      args: { target_id: 6, potion_type: PotionType.None },
    });
    inspect(3, 5, 1);
    add(3, [5], "sheriff_choose_direction", {
      name: "choose_direction",
      args: { direction: "clockwise" },
    });
    const alive3 = [1, 5, 8, 10, 11, 12];
    speech(3, alive3);
    vote(3, alive3, 1);
    words(3, [1]);
  } else if (king) {
    pack(1, [1, 2], 1);
    inspect(1, 3, 1);
    words(1, [1]);
    add(1, [1], "death_shot", { name: "shoot", args: { target_id: 3 } });
    speech(1, [2, 4, 5, 6]);
    vote(1, [2, 4, 5, 6], 2);
    words(1, [2]);
  } else {
    pack(1, hidden ? [1] : [1, 2], hidden ? 5 : 3);
    add(1, [4], "witch", {
      name: "use_potion",
      args: { target_id: hidden ? 5 : 3, potion_type: PotionType.Heal },
    });
    inspect(1, 3, 2);
    speech(1, [1, 2, 3, 4, 5, 6]);
    vote(1, [1, 2, 3, 4, 5, 6], 1);
    words(1, [1]);
    if (hidden) knife(2, [2], 5);
    else pack(2, [2], 5);
    add(2, [4], "witch", {
      name: "use_potion",
      args: { target_id: 4, potion_type: PotionType.None },
    });
    inspect(2, 3, kind === "six_skip" ? null : 2);
    speech(2, [2, 3, 4, 6]);
    vote(2, [2, 3, 4, 6], kind === "six_skip" || kind === "six_repeat" ? 6 : 2);
    words(2, [kind === "six_skip" || kind === "six_repeat" ? 6 : 2]);
  }
  let latest: PlannedTurn["roleInspectionLatest"] = null;
  for (const turn of turns.get(large ? 5 : 3)!) {
    turn.roleInspectionLatest = latest;
    if (turn.action?.name === "inspect_role") {
      const target = turn.action.args.target_id;
      latest = {
        targetId: target,
        roleLabel:
          large && turn.day === 1
            ? ["女巫", "Witch"]
            : king
              ? ["狼王", "Wolf King"]
              : hidden
                ? turn.day === 1
                  ? ["平民", "Villager"]
                  : ["隐狼", "Hidden Wolf"]
                : ["狼人", "Werewolf"],
      };
    }
  }
  if (hidden)
    for (const turn of turns.get(2)!)
      turn.hiddenWolfStatus = {
        inherited: turn.day > 1,
        active: turn.day > 1 && turn.stage !== "last_words",
      };
  const family = large ? "twelve" : king ? "king" : hidden ? "hidden" : "six",
    seeds: Record<string, string> = {
      six: "psychic-six:465",
      king: "psychic-king:435",
      hidden: "psychic-hidden:256",
      twelve: "psychic-twelve:731742",
    },
    wolves = roles.flatMap((r, i) => ([Role.Wolf, Role.WolfKing].includes(r) ? [i + 1] : [])),
    psychic = large ? 5 : 3;
  return {
    board: parseBoardDefinition(
      boardDefinitionFromConfig(`${large ? "twelve" : "six"}_player_psychic_${kind}`, config),
    ),
    seed: seeds[family],
    roles,
    turns,
    promptAssertions: (actor, locale) => ({
      expectedTeammateIds:
        actor === 2 && hidden
          ? [1]
          : wolves.includes(actor)
            ? wolves.filter((id) => id !== actor)
            : [],
      ...(actor === psychic
        ? {
            expectedIdentityMarker:
              locale === "en" ? "your true role is Spirit Seer." : "真实身份是通灵师。",
            requiredCurrentMarkers: [
              locale === "en" ? "Your role is Spirit Seer," : "你的底牌是【通灵师】",
            ],
          }
        : {
            forbiddenCurrentMarkers: [
              locale === "en" ? "Your role is Spirit Seer," : "你的底牌是【通灵师】",
            ],
          }),
    }),
  };
}

/**
 * Builds original pure-white-girl test input plans, fixed boards and explicit player/marker data. Inputs
 * are supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { roleName } from "@ai-werewolf-arena/game-text";
import { ActionWindow } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { pureWhiteTwelveConfig } from "../../../../../src/runtime/scenarios/pure_white_twelve";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export function pureWhiteScenario(kind: "wolf" | "good"): TransportGameScenario & {
  pure: number;
  wolfWitch: number;
  wolves: number[];
  dead: number[];
  alive: number[];
  winner: Camp;
} {
  const config = structuredClone(pureWhiteTwelveConfig),
    seed = "pure-white-transport:" + kind;
  const deck = config.roleSetups.flatMap((row) =>
    Array.from({ length: row.count }, () => row.role),
  );
  const roles = shuffled(deck, createRandom(seed).fork("deal")),
    ids = roles.map((_, i) => i + 1);
  const id = (role: Role) => roles.indexOf(role) + 1;
  const pure = id(Role.PureWhiteGirl),
    wolfWitch = id(Role.WolfWitch),
    witch = id(Role.Witch),
    hunter = id(Role.Hunter),
    guard = id(Role.Guard),
    ordinary = ids.filter((id) => roles[id - 1] === Role.Wolf),
    villagers = ids.filter((id) => roles[id - 1] === Role.Villager),
    wolves = [...ordinary, wolfWitch].sort((a, b) => a - b);
  const turns = new Map<number, PlannedTurn[]>(ids.map((id) => [id, []]));
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((id: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      turns
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const inspect = (day: number, actor: number, target: number) =>
    add(day, [actor], actor === pure ? "pure_white_girl" : "wolf_witch", {
      name: "inspect_night_identity",
      args: { target_id: target, abstain: false },
    });
  const pack = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Words" } });
  add(1, [guard], "guard", { name: "guard", args: { target_id: null, abstain: true } });
  pack(1, wolves, kind === "wolf" ? guard : villagers[0]!);
  add(1, [witch], "witch", {
    name: "use_potion",
    args: { target_id: kind === "wolf" ? hunter : ordinary[0]!, potion_type: PotionType.Poison },
  });
  inspect(1, pure, wolfWitch);
  inspect(1, wolfWitch, pure);
  const firstDeaths = kind === "wolf" ? [guard, hunter] : [villagers[0]!, ordinary[0]!];
  words(1, firstDeaths);
  const aliveDay = ids.filter((id) => !firstDeaths.includes(id));
  const packDay = wolves.filter((id) => aliveDay.includes(id));
  add(1, packDay, ActionWindow.OnPreElection, null);
  add(1, aliveDay, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
  add(1, aliveDay, "day_speech", { name: "speak", args: { text: "Speech" } });
  add(1, packDay, ActionWindow.OnPreVote, null);
  const exile = kind === "wolf" ? witch : ordinary[1]!;
  add(1, aliveDay, "voting", (actor) => ({
    name: "vote",
    args: { target_id: actor === exile ? null : exile, abstain: actor === exile },
  }));
  words(1, [exile]);
  const aliveNight = aliveDay.filter((id) => id !== exile);
  if (kind === "good")
    add(2, [guard], "guard", { name: "guard", args: { target_id: null, abstain: true } });
  pack(
    2,
    wolves.filter((id) => aliveNight.includes(id)),
    kind === "wolf" ? villagers[0]! : hunter,
  );
  if (kind === "good")
    add(2, [witch], "witch", {
      name: "use_potion",
      args: { target_id: witch, potion_type: PotionType.None },
    });
  inspect(2, pure, kind === "wolf" ? wolfWitch : ordinary[2]!);
  inspect(2, wolfWitch, pure);
  if (kind === "good")
    add(2, [hunter], "hunter_shot", { name: "shoot", args: { target_id: wolfWitch } });
  const dead =
    kind === "wolf" ? [villagers[0]!, pure, wolfWitch] : [hunter, pure, ordinary[2]!, wolfWitch];
  for (const actor of [pure, wolfWitch]) {
    let latest: PlannedTurn["roleInspectionLatest"] = null;
    for (const turn of turns.get(actor)!) {
      turn.roleInspectionLatest = latest;
      if (turn.action?.name === "inspect_night_identity" && turn.action.args.target_id !== null) {
        const target = turn.action.args.target_id,
          role = roles[target - 1]!;
        latest = { targetId: target, roleLabel: [roleName(role, "zh-CN"), roleName(role, "en")] };
      }
    }
  }
  return {
    board: parseBoardDefinition(boardDefinitionFromConfig("pure_white_transport_" + kind, config)),
    seed,
    roles,
    turns,
    pure,
    wolfWitch,
    wolves,
    dead,
    alive: aliveNight.filter((id) => !dead.includes(id)),
    winner: kind === "wolf" ? Camp.Wolf : Camp.Good,
    promptAssertions: (actor) => ({
      expectedTeammateIds: wolves.includes(actor) ? wolves.filter((id) => id !== actor) : [],
    }),
  };
}

/**
 * 测试 builder：负责按辉光／蚀月公开板子与语言构造原运行 fixture。输入为原配置、角色及受控组件；输出保留原对象和装配顺序，预期仍由独立字面测试提供，不执行模型或替换 oracle。
 */
import { Role } from "../../../../../src/core";
