export async function radiantFixture(locale: "zh-CN" | "en" = "zh-CN") {
  const raw = JSON.parse(
    await readFile(
      new URL("../../../../../../configs.example/boards/awa_radiant_eclipse_12_v1.json", import.meta.url),
      "utf8",
    ),
  );
  const board = parseBoardDefinition(raw),
    game = bootstrapGame(board.config, {
      locale,
      fixedRoles: radiantRoles,
      random: createRandom("radiant-eclipse-manual"),
    });
  const events: GameEvent[] = [],
    requests: ActionRequest[] = [];
  const role = (id: number) => game.world.getComponent(id, COMPONENT.Role)!;
  const native = (id: number) =>
    allNightAbilities(role(id)).find((a) => a.source.kind === "native")!;
  const pipeline = new NightPipeline({
    world: game.world,
    toolGateway: new ToolGateway(),
    damageResolutionSystem: new DamageResolutionSystem(),
    events,
    random: createRandom("radiant-pipeline"),
  });
  return {
    ...game,
    board,
    raw,
    events,
    requests,
    role,
    native,
    pipeline,
    borrowed: () => allNightAbilities(role(1)).find((a) => a.id === "copy:eclipse:night:2"),
  };
}

/**
 * Owns Radiant/Eclipse transport test input construction from a handwritten plan.
 * Inputs are the tracked public configs.example board JSON and original plan name;
 * outputs retain deterministic role remapping, action turns, prompt markers and
 * scenario expectations derived from that supplied literal plan. The original
 * public readFile/JSON/board parse and input callbacks stay intact. This builder
 * starts no server or model and invokes no production settlement or game cycle.
 */
import { readFile } from "node:fs/promises";
import { ActionWindow } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import { radiantRoles } from "./runtime-game";
import { radiantFullPlans } from "../oracles/literal-plans";
import type { RadiantFullPlanName } from "../oracles/literal-plans";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export async function radiantTransportScenario(
  name: RadiantFullPlanName = "independent-stock-card16-card17",
) {
  const board = parseBoardDefinition(
      JSON.parse(
        await readFile(
          new URL(
            "../../../../../../configs.example/boards/awa_radiant_eclipse_12_v1.json",
            import.meta.url,
          ),
          "utf8",
        ),
      ),
    ),
    seed = "radiant-eclipse-transport-v1";
  const roles = shuffled(
    board.config.roleSetups.flatMap((row) => Array.from({ length: row.count }, () => row.role)),
    createRandom(seed).fork("deal"),
  );
  const ids = roles.map((_, i) => i + 1),
    plan = radiantFullPlans.find((p) => p.name === name)!,
    mapping = new Map<number, number>();
  const used = new Map<Role, number>();
  for (let old = 1; old <= 12; old++) {
    const role = radiantRoles[old - 1]!,
      matches = ids.filter((id) => roles[id - 1] === role),
      index = used.get(role) ?? 0;
    mapping.set(old, matches[index]!);
    used.set(role, index + 1);
  }
  const map = (old: number) => mapping.get(old)!,
    list = (old: readonly number[]) => old.map(map).sort((a, b) => a - b);
  const turns = new Map<number, PlannedTurn[]>(ids.map((id) => [id, []]));
  const add = (
    day: number,
    oldActors: readonly number[],
    stage: ActionStage,
    action: ToolCall | null | ((old: number) => ToolCall | null),
    markers?: string[],
  ) => {
    for (const old of oldActors)
      turns.get(map(old))!.push({
        day,
        stage,
        action: typeof action === "function" ? action(old) : action,
        ...(markers ? { requiredPromptMarkers: markers } : {}),
      });
  };
  let dreamLast: { target: number | null; day: number | null } = { target: null, day: null };
  let shelterLast: { target: number | null; day: number | null } = { target: null, day: null };
  let originalStock = { heal: 1, poison: 1 },
    sheriff: number | null = plan.sheriff;
  const originalWolves = [10, 11, 12],
    sourceState = (id: number) => (id === 4 ? { ...originalStock } : undefined);
  const nightDeaths: number[][] = [];
  for (let index = 0; index < plan.nights.length; index++) {
    const day = index + 1,
      n = plan.nights[index]!,
      start =
        index === 0 ? Array.from({ length: 12 }, (_, i) => i + 1) : [...plan.alive[index - 1]!];
    const borrow = day >= 2 && start.includes(1) ? n.swallow : null;
    if (day >= 2 && start.includes(1))
      add(day, [1], "eclipse_swallow", {
        name: "swallow_skill",
        args: { target_id: borrow === null ? null : map(borrow) },
      });
    if (day >= 2 && start.includes(2) && borrow !== 2)
      add(day, [2], "radiant_shelter", {
        name: "cast_shelter",
        args: { target_id: n.shelter === null ? null : map(n.shelter) },
      });
    if (borrow === 2)
      add(
        day,
        [1],
        "radiant_shelter",
        { name: "cast_shelter", args: { target_id: n.shelter === null ? null : map(n.shelter) } },
        [`copy:eclipse:night:${day}`],
      );
    if (start.includes(5) && borrow !== 5) {
      add(day, [5], "dreamer", { name: "dream", args: { target_id: map(n.dream) } });
    }
    if (borrow === 5)
      add(day, [1], "dreamer", { name: "dream", args: { target_id: map(n.dream) } }, [
        `copy:eclipse:night:${day}`,
      ]);
    const pack = originalWolves.filter((id) => start.includes(id)),
      knife = pack.length ? pack : start.includes(1) ? [1] : [];
    add(day, pack, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(day, knife, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: map(n.knife), abstain: false },
    });
    const bottle = "potion" in n ? n.potion : undefined;
    const use = (old: number) =>
      ({
        name: "use_potion",
        args: {
          target_id: bottle ? map(bottle[1]) : map(old),
          potion_type:
            bottle?.[0] === "heal"
              ? PotionType.Heal
              : bottle?.[0] === "poison"
                ? PotionType.Poison
                : PotionType.None,
        },
      }) as const;
    if (start.includes(4) && borrow !== 4) {
      add(day, [4], "witch", use(4));
      if (bottle) originalStock[bottle[0]]--;
    }
    if (borrow === 4 && (originalStock.heal || originalStock.poison))
      add(day, [1], "witch", use(1), [
        `copy:eclipse:night:${day}`,
        `"heal":${originalStock.heal}`,
        `"poison":${originalStock.poison}`,
      ]);
    if (start.includes(3) && borrow !== 3)
      add(day, [3], "seer", {
        name: "check_identity",
        args: { target_id: map("seer" in n ? n.seer : 1) },
      });
    if (borrow === 3)
      add(
        day,
        [1],
        "seer",
        { name: "check_identity", args: { target_id: map("seer" in n ? n.seer : 1) } },
        [`copy:eclipse:night:${day}`],
      );
    if (borrow !== null && borrow !== 6 && [2, 3, 4, 5].includes(borrow)) {
      const borrowed = turns
        .get(map(1))!
        .find(
          (t) =>
            t.day === day &&
            t.stage ===
              (
                { 2: "radiant_shelter", 3: "seer", 4: "witch", 5: "dreamer" } as Record<
                  number,
                  string
                >
              )[borrow],
        );
      if (borrowed)
        borrowed.radiantBorrow = {
          id: `copy:eclipse:night:${day}`,
          state:
            borrow === 2
              ? {
                  policy: "awa_radiant_eclipse_v1",
                  lastTarget: shelterLast.target,
                  lastDay: shelterLast.day,
                }
              : borrow === 3
                ? {
                    targetPolicy: "awa_alive_v1",
                    actionPolicy: "awa_required_when_legal_v1",
                    lastTarget: null,
                    lastIsWerewolf: null,
                    lastResult: null,
                    history: [],
                  }
                : borrow === 4
                  ? {
                      ...originalStock,
                      selfHealRule: "disabled",
                      knifeVisibility: "awa_with_heal_v1",
                      potionPolicy: "awa_one_native_v1",
                      canSelfHeal: false,
                      healUsedThisNight: false,
                      poisonUsedThisNight: false,
                    }
                  : {
                      lastTarget: dreamLast.target,
                      lastDay: dreamLast.day,
                      protectionPolicy: "netease_2026_night_immunity_v1",
                      history: [],
                    },
        };
    }
    if (day >= 2 && start.includes(2) && borrow !== 2)
      shelterLast = { target: n.shelter === null ? null : map(n.shelter), day };
    if (start.includes(5) && borrow !== 5) dreamLast = { target: map(n.dream), day };
    const linked: number[] = plan.dreamDeaths
        .filter((d) => d.day === day && d.reason === "linked")
        .map((d) => d.targetId),
      direct = plan.nightDeaths[index]!.filter((id) => !linked.includes(id));
    const deaths = [...list(direct), ...linked.map(map).filter((id) => !list(direct).includes(id))];
    nightDeaths.push(deaths);
    if (day === 1) {
      add(day, pack, ActionWindow.OnPreElection, null);
      add(day, start, "sheriff_nomination", (old) => ({
        name: "run_for_sheriff",
        args: { run: old === sheriff },
      }));
      if (sheriff !== null) {
        add(day, [sheriff], "sheriff_campaign_speech", {
          name: "speak",
          args: { text: "Campaign" },
        });
        add(day, [sheriff], "sheriff_withdraw", { name: "run_for_sheriff", args: { run: true } });
      }
      add(day, plan.nightDeaths[index]!, "last_words", { name: "speak", args: { text: "Words" } });
    }
    if (sheriff !== null && (plan.nightDeaths[index]! as readonly number[]).includes(sheriff)) {
      add(day, [sheriff], "sheriff_badge_choice", {
        name: "choose_badge_successor",
        args: { target_id: map(2) },
      });
      sheriff = 2;
    }
    if (index === plan.nights.length - 1 && plan.phase === "day") continue;
    const alive = start.filter(
      (id) => !(plan.nightDeaths[index]! as readonly number[]).includes(id),
    );
    if (sheriff !== null)
      add(day, [sheriff], "sheriff_choose_direction", {
        name: "choose_direction",
        args: { direction: "clockwise" },
      });
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(
      day,
      originalWolves.filter((id) => alive.includes(id)),
      ActionWindow.OnPreVote,
      null,
    );
    add(day, alive, "voting", (old) => ({
      name: "vote",
      args: {
        target_id: old === n.exile || n.exile === null ? null : map(n.exile),
        abstain: n.exile === null || old === n.exile,
      },
    }));
    if (n.exile !== null)
      add(day, [n.exile], "last_words", { name: "speak", args: { text: "Words" } });
  }
  const ordinary = list(originalWolves),
    maid = map(1),
    count = map(2);
  for (const turn of turns.get(maid)!) turn.currentTeammateIds = [...ordinary];
  const names: Partial<Record<Role, [string, string]>> = {
    [Role.Wolf]: ["狼人", "Werewolf"],
    [Role.Villager]: ["平民", "Villager"],
    [Role.Seer]: ["预言家", "Seer"],
    [Role.Witch]: ["女巫", "Witch"],
    [Role.Dreamer]: ["摄梦人", "Dreamer"],
    [Role.RadiantCount]: ["流光伯爵", "Radiant Count"],
    [Role.EclipseMaid]: ["蚀日侍女", "Eclipse Maid"],
  };
  const scenario: TransportGameScenario = {
    board,
    seed,
    roles,
    turns,
    promptAssertions(actor, locale) {
      const role = roles[actor - 1]!;
      return {
        expectedIdentityMarker:
          locale === "en"
            ? `your true role is ${names[role]![1]}.`
            : `你的真实身份是${names[role]![0]}。`,
        requiredCurrentMarkers:
          role === Role.EclipseMaid
            ? [
                locale === "en"
                  ? "Current role: Eclipse Maid; alignment: Werewolves."
                  : "本轮身份：蚀日侍女；阵营：狼人。",
              ]
            : [],
        expectedTeammateIds:
          role === Role.EclipseMaid
            ? ordinary
            : role === Role.Wolf
              ? ordinary.filter((id) => id !== actor)
              : [],
        requiredSystemMarkers:
          role === Role.EclipseMaid
            ? [
                locale === "en"
                  ? "Borrowed stocks are independent and never written back"
                  : "借用库存独立、不写回原主",
              ]
            : role === Role.RadiantCount
              ? [
                  locale === "en"
                    ? "A suppressed night is not a recorded pass"
                    : "被封禁的夜晚不算一次放弃",
                ]
              : [],
      };
    },
  };
  return {
    ...scenario,
    name,
    mapping,
    maid,
    count,
    ordinary,
    nightDeaths,
    alive: list(plan.alive.at(-1)!),
    winner: plan.winner === "good" ? Camp.Good : Camp.Wolf,
    plan,
  };
}

/**
 * Provides the original radiant-eclipse scripted action driver for tests.
 * Inputs are issued requests, explicit choices or captured game handles;
 * outputs are the same callbacks and literal ToolCalls/null decisions.
 * It keeps the original local reads and defaults, without running a model,
 * advancing a phase, changing stock or regenerating expected outcomes.
 */
import { PotionType } from "../../../../../src/core";
import type { ActionRequest } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";

export interface RadiantChoices {
  swallow?: number | null;
  shelter?: number | null;
  dream?: number;
  knife?: number | null;
  potion?: { target_id: number; potion_type: "heal" | "poison" | "none" };
}

export function radiantProvider(
  requests: ActionRequest[],
  choices: RadiantChoices = {},
  override?: (
    r: ActionRequest,
  ) => ToolCall | null | undefined | Promise<ToolCall | null | undefined>,
) {
  return {
    async getAction(r: ActionRequest): Promise<ToolCall | null> {
      requests.push(structuredClone(r));
      const value = await override?.(r);
      if (value !== undefined) return value;
      switch (r.context.stage) {
        case "eclipse_swallow":
          return { name: "swallow_skill", args: { target_id: choices.swallow ?? null } };
        case "radiant_shelter":
          return { name: "cast_shelter", args: { target_id: choices.shelter ?? null } };
        case "dreamer":
          return { name: "dream", args: { target_id: choices.dream ?? 9 } };
        case "wolf_discussion":
          return { name: "speak_to_wolves", args: { text: "End", end_chat: true } };
        case "wolf_vote":
          return {
            name: "kill_vote",
            args: { target_id: choices.knife ?? null, abstain: choices.knife == null },
          };
        case "witch":
          return {
            name: "use_potion",
            args: {
              target_id: choices.potion?.target_id ?? r.actorId,
              potion_type:
                choices.potion?.potion_type === "heal"
                  ? PotionType.Heal
                  : choices.potion?.potion_type === "poison"
                    ? PotionType.Poison
                    : PotionType.None,
            },
          };
        case "seer":
          return { name: "check_identity", args: { target_id: 10 } };
        case "sheriff_nomination":
          return { name: "run_for_sheriff", args: { run: false } };
        case "voting":
          return { name: "vote", args: { target_id: null, abstain: true } };
      }
      if (r.allowedTools.includes("self_destruct"))
        return { name: "self_destruct", args: { confirm: false, reason: "Synthetic pass" } };
      if (r.allowedTools.includes("speak")) return { name: "speak", args: { text: "Synthetic" } };
      throw new Error(`unexpected_radiant_request:${r.context.stage}`);
    },
  };
}

/**
 * Provides the original radiant-eclipse scripted action driver for tests.
 * Inputs are issued requests, explicit choices or captured game handles;
 * outputs are the same callbacks and literal ToolCalls/null decisions.
 * It keeps the original local reads and defaults, without running a model,
 * advancing a phase, changing stock or regenerating expected outcomes.
 */
import { radiantFullPlans } from "../oracles/literal-plans";
import type { RadiantFullPlanName } from "../oracles/literal-plans";
import { PotionType } from "../../../../../src/core";
import type { ActionRequest } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";

export function radiantManualAction(
  q: ActionRequest,
  planName?: RadiantFullPlanName,
): ToolCall | undefined {
  if (planName) {
    const plan = radiantFullPlans.find((p) => p.name === planName)!,
      night = plan.nights[q.context.day - 1];
    if (!night) throw Error("radiant_full_plan_exhausted");
    switch (q.context.stage) {
      case "eclipse_swallow":
        return { name: "swallow_skill", args: { target_id: night.swallow } };
      case "radiant_shelter":
        return { name: "cast_shelter", args: { target_id: night.shelter } };
      case "dreamer":
        return { name: "dream", args: { target_id: night.dream } };
      case "wolf_vote":
        return { name: "kill_vote", args: { target_id: night.knife, abstain: false } };
      case "witch": {
        const bottle = "potion" in night ? night.potion : undefined;
        return {
          name: "use_potion",
          args: {
            target_id: bottle?.[1] ?? q.actorId,
            potion_type:
              bottle?.[0] === "heal"
                ? PotionType.Heal
                : bottle?.[0] === "poison"
                  ? PotionType.Poison
                  : PotionType.None,
          },
        };
      }
      case "seer":
        return { name: "check_identity", args: { target_id: "seer" in night ? night.seer : 1 } };
      case "sheriff_nomination":
      case "sheriff_withdraw":
        return { name: "run_for_sheriff", args: { run: q.actorId === plan.sheriff } };
      case "sheriff_vote":
      case "sheriff_pk_vote":
        return {
          name: "vote_for_sheriff",
          args: { target_id: plan.sheriff, abstain: plan.sheriff === null },
        };
      case "sheriff_choose_direction":
        return { name: "choose_direction", args: { direction: "clockwise" } };
      case "sheriff_badge_choice":
        return { name: "choose_badge_successor", args: { target_id: 2 } };
      case "voting":
        return {
          name: "vote",
          args: {
            target_id: q.actorId === night.exile ? null : night.exile,
            abstain: night.exile === null || q.actorId === night.exile,
          },
        };
    }
    return undefined;
  }
  const day = q.context.day;
  switch (q.context.stage) {
    case "eclipse_swallow":
      return { name: "swallow_skill", args: { target_id: day === 2 ? 4 : day === 3 ? 2 : 5 } };
    case "radiant_shelter":
      return { name: "cast_shelter", args: { target_id: day === 2 ? 6 : day === 3 ? 5 : 7 } };
    case "dreamer":
      return {
        name: "dream",
        args: { target_id: day === 1 ? 6 : day === 2 ? 8 : day === 3 ? 1 : 7 },
      };
    case "wolf_vote":
      return {
        name: "kill_vote",
        args: { target_id: day === 1 ? 10 : day === 2 ? 8 : day === 3 ? 5 : 7, abstain: false },
      };
    case "witch":
      return {
        name: "use_potion",
        args:
          day === 1
            ? { target_id: 10, potion_type: PotionType.Heal }
            : day === 2
              ? { target_id: 6, potion_type: PotionType.Poison }
              : day === 3
                ? { target_id: 1, potion_type: PotionType.Poison }
                : { target_id: q.actorId, potion_type: PotionType.None },
      };
    case "seer":
      return { name: "check_identity", args: { target_id: 1 } };
    case "voting": {
      const target = day === 1 ? 10 : day === 2 ? 11 : day === 3 ? 12 : 1;
      return {
        name: "vote",
        args: { target_id: q.actorId === target ? null : target, abstain: q.actorId === target },
      };
    }
  }
  return undefined;
}

/**
 * Owns original test driver radiant-eclipse controlled execution and recording support. Inputs are literal action plans
 * and original fixture handles; outputs preserve driver callbacks, traces, caches and cleanup. Concrete
 * transport/replay or scripted actions retain their original lifetimes; supplied handwritten oracles own
 * expected outcomes, and no billed model or production state writer is introduced.
 */
import type { RadiantFullPlanName } from "../oracles/literal-plans";
import type { BootstrapResult } from "../../../../../src/app/bootstrap";
import type { ActionProvider } from "../../../../../src/core";
import type { ActionRequest } from "../../../../../src/core";
import { radiantManualAction } from "./manual-actions";
import { readFile } from "node:fs/promises";
import { rm } from "node:fs/promises";
import { mkdir } from "node:fs/promises";
import { copyFile } from "node:fs/promises";
import path from "node:path";
import { bootstrapGame } from "../../../../../src/app/bootstrap";
import { createRandom } from "../../../../../src/core";
import { radiantRoles } from "../builders/runtime-game";
import { radiantProvider } from "./actions";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import { SessionRecordManager } from "../../../../../src/recording/session_recorder";
import { runWithSessionRecorder } from "../../../../../src/recording/recording_context";
import { parseReproductionRecord } from "../../../../../src/recording/reproduction";
import type { RecordedCheckpoint } from "../../../../../src/recording/reproduction";
import type { ReproductionRecord } from "../../../../../src/recording/reproduction";
import { beginGameReproduction } from "../../../../../src/runtime/simulation/reproduction_context";
import { captureCheckpoint } from "../../../../../src/runtime/simulation/reproduction_context";
import { currentEngineVersion } from "../../../../../src/runtime/simulation/reproduction_context";
import { replayReproduction } from "../../../../../src/runtime/simulation/replay_reproduction";
import { GameEventRecorder } from "../../../../../src/runtime/game_event_recorder";
import { createTestTempDirectory } from "../../../drivers/temp-directories";

export interface RadiantRecordingOptions {
  locale?: "zh-CN" | "en";
  planName?: RadiantFullPlanName;
  seed?: string;
  failureStage?: ActionRequest["context"]["stage"];
  failureMode?: "missing" | "error";
  artifactDirectory?: string;
  provider?: (
    game: BootstrapResult,
    manual: ActionProvider,
  ) => Promise<ActionProvider> | ActionProvider;
}

export async function radiantRecording(
  options: RadiantRecordingOptions = {},
): Promise<ReproductionRecord> {
  const locale = options.locale ?? "en",
    seed = options.seed ?? "radiant-eclipse-real-recording";
  const board = parseBoardDefinition(
    JSON.parse(
      await readFile(
        new URL("../../../../../../configs.example/boards/awa_radiant_eclipse_12_v1.json", import.meta.url),
        "utf8",
      ),
    ),
  );
  const game = bootstrapGame(board.config, {
    locale,
    fixedRoles: radiantRoles,
    random: createRandom(seed),
  });
  const root = await createTestTempDirectory("awa-radiant-tape-");
  try {
    const manager = await SessionRecordManager.create(
      {
        sessionId: "game",
        board: board.definition.id,
        startedAtIso: new Date().toISOString(),
        locale,
        random: game.random.metadata,
      },
      root,
    );
    const recorder = new GameEventRecorder(
      { world: game.world, replayManager: manager },
      game.phaseManager.getSnapshot().phase,
    );
    const manual = radiantProvider([], {}, (q) => {
      if (q.context.day === 2 && q.context.stage === options.failureStage) {
        if (options.failureMode === "error") throw new Error("synthetic_radiant_provider_failure");
        return null;
      }
      return radiantManualAction(q, options.planName);
    });
    const provider = options.provider ? await options.provider(game, manual) : manual;
    let last: RecordedCheckpoint | undefined;
    await runWithSessionRecorder(manager, async () => {
      const trace = beginGameReproduction(manager, game, {
        engine: await currentEngineVersion(),
        boardId: board.definition.id,
        ...(void board.config, {}),
        locale,
        maxDays: 6,
      });
      for (let cycle = 1; cycle <= 6 && !game.phaseManager.getSnapshot().gameOver; cycle++) {
        let failure: unknown;
        try {
          await game.phaseManager.runSingleCycle(
            { getAction: (q) => trace.decide(q, provider) },
            6,
          );
        } catch (error) {
          if (!options.failureStage) throw error;
          failure = error;
          trace.noteFailure("cycle", error);
        }
        last = captureCheckpoint(
          game.world,
          game.phaseManager.getSnapshot(),
          cycle,
          failure === undefined,
          game.phaseManager.getEvents().length,
          failure,
        );
        trace.checkpoint(last, game.phaseManager.getEvents());
        recorder.flush(game.phaseManager.getEvents());
        if (failure) break;
      }
      const snapshot = game.phaseManager.getSnapshot();
      if (options.failureStage) {
        if (last?.complete || snapshot.gameOver) throw Error("radiant_fixture_failed_to_fail");
      } else if (!snapshot.gameOver || snapshot.result?.reason === "max_days_reached")
        throw Error("radiant_fixture_failed_to_end_naturally");
      await manager.finalize({
        endedAtIso: new Date().toISOString(),
        winner: snapshot.result?.winner ?? null,
        finishReason: options.failureStage ? "runtime_error" : snapshot.result!.reason,
        ...(snapshot.result ? { gameResult: snapshot.result } : {}),
        players: last!.players.map((p) => ({
          player_id: p.id,
          role: p.role,
          camp: p.camp,
          alive: p.alive,
        })),
      });
    });
    const record = parseReproductionRecord(
      JSON.parse(await readFile(path.join(manager.sessionDir, "reproduction.json"), "utf8")),
    );
    const replay = await replayReproduction(record, root);
    if (JSON.stringify(replay.snapshot) !== JSON.stringify(record.checkpoints.at(-1)!.snapshot))
      throw Error("radiant_fixture_replay_changed_snapshot");
    if (options.artifactDirectory) {
      await mkdir(options.artifactDirectory, { recursive: true });
      for (const name of [
        "reproduction.json",
        "replay.json",
        "manifest.json",
        "phase_windows.json",
        "timeline_index.json",
      ])
        await copyFile(
          path.join(manager.sessionDir, name),
          path.join(options.artifactDirectory, name),
        );
      await mkdir(path.join(options.artifactDirectory, "players"), { recursive: true });
      for (let actor = 1; actor <= 12; actor++)
        await copyFile(
          path.join(manager.sessionDir, `players/player_${actor}.json`),
          path.join(options.artifactDirectory, `players/player_${actor}.json`),
        );
    }
    return record;
  } finally {
    await rm(root, { recursive: true, force: true });
  }
}

/**
 * 测试 driver：负责执行原受控赤月对局并推导后续传输计划。输入为固定角色和明确回复；输出为实际已执行前缀及传输输入，期望保留在外部字面 oracle，不调用模型。
 */
import { bootstrapGame } from "../../../../../src/app/bootstrap";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { COMPONENT } from "../../../../../src/core";
import type { RoleComponent } from "../../../../../src/core";
import type { ActionRequest } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { redMoonTwelveConfig } from "../../../../../src/runtime/scenarios/red_moon_twelve";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import { demonNightChoice } from "../../demon-hunter/drivers/actions";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export async function redMoonScenario(
  mode: "expire" | "knife" | "blast",
  policy: "ends_game" | "forbidden" = "ends_game",
): Promise<
  TransportGameScenario & {
    red: number;
    winner: Camp;
    alive: number[];
    ordered: Array<{ actorId: number; turn: PlannedTurn }>;
  }
> {
  const config = structuredClone(redMoonTwelveConfig);
  config.redMoon!.lastWolfBlastPolicy = policy;
  const seed = "red-moon-transport:" + mode + ":" + policy;
  const game = bootstrapGame(config, { random: createRandom(seed) });
  const roles = game.playerIds.map(
    (id) => game.world.getComponent(id, COMPONENT.Role)!.role,
  );
  const id = (r: Role) => roles.indexOf(r) + 1;
  const red = id(Role.RedMoonApostle),
    witch = id(Role.Witch),
    seer = id(Role.Seer);
  const ordinary = game.playerIds.filter((id) => roles[id - 1] === Role.Wolf),
    villagers = game.playerIds.filter((id) => roles[id - 1] === Role.Villager);
  const turns = new Map<number, PlannedTurn[]>(game.playerIds.map((id) => [id, []]));
  const ordered: Array<{ actorId: number; turn: PlannedTurn }> = [];
  const action = (r: ActionRequest): ToolCall | null => {
    const day = r.context.day;
    if (
      mode === "blast" &&
      r.actorId === red &&
      day === 1 &&
      r.allowedTools.includes("self_destruct")
    )
      return { name: "self_destruct", args: { reason: "Golden blast", confirm: true } };
    if (r.allowedTools.includes("vote"))
      return {
        name: "vote",
        args: {
          target_id:
            mode === "blast"
              ? day === 2
                ? ordinary[0]!
                : ordinary[1]!
              : day === 1
                ? ordinary[1]!
                : day === 2
                  ? mode === "knife"
                    ? villagers[2]!
                    : red
                  : red,
          abstain: false,
        },
      };
    if (r.allowedTools.includes("check_identity"))
      return { name: "check_identity", args: { target_id: villagers[3]! } };
    return demonNightChoice(r, witch, {
      knife:
        day === 1
          ? villagers[0]!
          : day === 2
            ? villagers[1]!
            : mode === "knife"
              ? day === 3
                ? seer
                : villagers[3]!
              : villagers[2]!,
      potion:
        mode !== "blast" && day === 1
          ? { target: ordinary[0]!, type: PotionType.Poison }
          : undefined,
      hunt: mode === "blast" ? (day === 3 ? ordinary[2]! : null) : day === 2 ? ordinary[2]! : null,
    });
  };
  const result = await game.phaseManager.runUntilGameOver(
    {
      async getAction(r) {
        const value = action(r);
        const turn: PlannedTurn = { day: r.context.day, stage: r.context.stage, action: value };
        turns.get(r.actorId)!.push(turn);
        ordered.push({ actorId: r.actorId, turn });
        return value;
      },
    },
    8,
  );
  if (!result.gameOver || result.result?.winner !== (mode === "knife" ? Camp.Wolf : Camp.Good))
    throw new Error("red_moon_transport_plan_not_terminal");
  return {
    board: parseBoardDefinition(
      boardDefinitionFromConfig("red_moon_transport_" + mode + "_" + policy, config),
    ),
    seed,
    roles,
    turns,
    ordered,
    red,
    winner: result.result!.winner as Camp,
    alive: game.world.getAliveEntityIds(),
  };
}

/**
 * 构造蚀日者有界机制测试的显式 World、组件、Catalog 与初始座位。输入为原配置、组件及调用方字段，输出为原 fixture；手写断言和身份快照由测试持有，不运行完整对局、传输或生产规则验证器。
 */
import {
  createAliveComponent,
  createBadgeComponent,
  createCampComponent,
  createStatusMarksComponent,
  createVotingRightComponent,
} from "../../../../../src/game/observation/component-presentation";
import type { LastWolfBlastPolicy } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../../../src/core/domain/world";
import { Role } from "../../../../../src/core/domain/identity";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";

import { createVictoryComponent } from "../../../../../src/core/domain/components/victory";
import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import { installInitialRoster } from "../../../../../src/core/domain/initial_roster";
import { RoleCatalog } from "../../../../../src/game/mechanisms/roles/catalog";
import {
  getDefaultRoleCatalog,
  getDefaultRoleContributions,
  createRoleCatalog,
} from "../../../../../src/game/mechanisms/roles/role-catalog-assembly";
import { RED_MOON_ROLE_PROFILE } from "../../../../../src/game/mechanisms/roles/red_moon_apostle/profile";
import { installDemonHunter } from "../../../../../src/game/mechanisms/roles/demon_hunter/authority";
import { redMoonTwelveConfig } from "../../../../../src/runtime/scenarios/red_moon_twelve";

export function redMoonCandidateWorld(policy: LastWolfBlastPolicy = "ends_game") {
  const world = new World();
  const config = structuredClone(redMoonTwelveConfig);
  config.redMoon!.lastWolfBlastPolicy = policy;
  const catalog = createRoleCatalog({
    contributions: [
      ...getDefaultRoleContributions().filter(
        (p) => String(p.metadata.role) !== "red_moon_apostle",
      ),
      RED_MOON_ROLE_PROFILE,
    ],
  });
  const roles = config.roleSetups.flatMap((row) => Array<Role>(row.count).fill(row.role));
  const ids = roles.map((kind, i) => {
    const id = world.createEntity();
    const initialCamp = createCampComponent(catalog.getCamp(kind), world.locale);
    const role = createRoleComponent(kind, world.locale);
    const currentCamp = () => world.getComponent(id, COMPONENT.Camp);
    catalog.applyRuntime(role, { boardConfig: config, locale: world.locale, world, initialCamp, currentCamp });
    world.addComponent(id, COMPONENT.Identity, createIdentityComponent(id, i + 1, "player-" + id));
    world.addComponent(id, COMPONENT.Role, role);
    world.addComponent(id, COMPONENT.Camp, initialCamp);
    world.addComponent(
      id,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: initialCamp.camp }]),
    );
    world.addComponent(id, COMPONENT.Alive, createAliveComponent(true, world.locale));
    world.addComponent(id, COMPONENT.StatusMarks, createStatusMarksComponent(world.locale));
    world.addComponent(
      id,
      COMPONENT.VotingRight,
      createVotingRightComponent(1, true, world.locale),
    );
    world.addComponent(id, COMPONENT.Badge, createBadgeComponent(false, false, world.locale));
    return id;
  });
  installInitialRoster(world);
  installDemonHunter(world, config);
  return { world, config, ids, catalog };
}

/**
 * Builds original scholar-mentor test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { ActionWindow } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { scholarMentorTwelveConfig } from "../../../../../src/runtime/scenarios/scholar_mentor_twelve";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export function scholarMentorScenario(
  variant: "enhance" | "same-good" | "both-wolves" | "early-heal" = "enhance",
): TransportGameScenario & {
  scholar: number;
  mentor: number;
  seer: number;
  knifeActor: number;
  winner: Camp;
  alive: number[];
} {
  const enhanced = variant === "enhance" || variant === "early-heal";
  const config = structuredClone(scholarMentorTwelveConfig),
    seed = "scholar-mentor-transport";
  const roles = shuffled(
    config.roleSetups.flatMap((row) => Array.from({ length: row.count }, () => row.role)),
    createRandom(seed).fork("deal"),
  );
  const ids = roles.map((_, i) => i + 1),
    id = (role: Role) => roles.indexOf(role) + 1;
  const scholar = id(Role.DayScholar),
    mentor = id(Role.NightMentor),
    seer = id(Role.Seer),
    guard = id(Role.Guard),
    witch = id(Role.Witch);
  const ordinary = ids.filter((i) => roles[i - 1] === Role.Wolf),
    wolves = [...ordinary, mentor].sort((a, b) => a - b),
    villagers = ids.filter((i) => roles[i - 1] === Role.Villager);
  const turns = new Map<number, PlannedTurn[]>(ids.map((i) => [i, []]));
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((actor: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      turns
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Words" } });
  const pack = (day: number, actors: number[], target: number) => {
    add(
      day,
      actors.filter((i) => i !== mentor),
      "wolf_discussion",
      { name: "speak_to_wolves", args: { text: "End", end_chat: true } },
    );
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const dayVote = (day: number, alive: number[], target: number) => {
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(
      day,
      ordinary.filter((i) => alive.includes(i)),
      ActionWindow.OnPreVote,
      null,
    );
    add(day, alive, "voting", (actor) => ({
      name: "vote",
      args: { target_id: actor === target ? null : target, abstain: actor === target },
    }));
    words(day, [target]);
  };
  add(1, [guard], "guard", { name: "guard", args: { target_id: villagers[3]!, abstain: false } });
  pack(1, ordinary, villagers[0]!);
  add(1, [witch], "witch", {
    name: "use_potion",
    args: {
      target_id: variant === "both-wolves" ? witch : ordinary[0]!,
      potion_type: variant === "both-wolves" ? PotionType.None : PotionType.Poison,
    },
  });
  add(1, [seer], "seer", { name: "check_identity", args: { target_id: mentor } });
  add(1, ordinary, ActionWindow.OnPreElection, null);
  add(1, ids, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
  words(1, variant === "both-wolves" ? [villagers[0]!] : [villagers[0]!, ordinary[0]!]);
  let alive = ids.filter(
    (i) => i !== villagers[0] && (variant === "both-wolves" || i !== ordinary[0]),
  );
  dayVote(1, alive, ordinary[1]!);
  alive = alive.filter((i) => i !== ordinary[1]);
  add(2, [scholar], "scholar_mentor_choice", {
    name: "modify_skill",
    args: { mode: "enhance", target_id: variant === "both-wolves" ? ordinary[0]! : seer },
  });
  add(2, [mentor], "scholar_mentor_choice", {
    name: "modify_skill",
    args: { mode: "enhance", target_id: variant === "same-good" ? seer : ordinary[2]! },
  });
  add(2, [guard], "guard", { name: "guard", args: { target_id: villagers[1]!, abstain: false } });
  pack(
    2,
    ordinary.filter((id) => alive.includes(id)),
    villagers[1]!,
  );
  if (enhanced)
    add(2, [ordinary[2]!], "scholar_mentor_bonus", {
      name: "bonus_action",
      args: { kind: "kill", target_id: villagers[2]!, abstain: false },
    });
  add(2, [witch], "witch", {
    name: "use_potion",
    args: {
      target_id: variant === "early-heal" ? villagers[2]! : witch,
      potion_type: variant === "early-heal" ? PotionType.Heal : PotionType.None,
    },
  });
  add(2, [seer], "seer", { name: "check_identity", args: { target_id: mentor } });
  if (enhanced)
    add(2, [seer], "scholar_mentor_bonus", {
      name: "bonus_action",
      args: { kind: "check", target_id: ordinary[2]!, abstain: false },
    });
  alive = alive.filter(
    (i) =>
      variant === "early-heal" ||
      i !== (enhanced ? villagers[2] : variant === "same-good" ? seer : mentor),
  );
  dayVote(2, alive, ordinary[2]!);
  alive = alive.filter((i) => i !== ordinary[2]);
  add(3, [scholar], "scholar_mentor_choice", {
    name: "modify_skill",
    args: { mode: "weaken", target_id: guard },
  });
  if (alive.includes(mentor))
    add(3, [mentor], "scholar_mentor_choice", {
      name: "modify_skill",
      args: { mode: "weaken", target_id: witch },
    });
  pack(
    3,
    wolves.filter((id) => alive.includes(id)),
    villagers[3]!,
  );
  add(3, [witch], "witch", {
    name: "use_potion",
    args: {
      target_id: variant === "early-heal" ? witch : villagers[3]!,
      potion_type: variant === "early-heal" ? PotionType.None : PotionType.Heal,
    },
  });
  if (alive.includes(seer))
    add(3, [seer], "seer", {
      name: "check_identity",
      args: { target_id: variant === "both-wolves" ? ordinary[0]! : mentor },
    });
  if (variant === "early-heal") alive = alive.filter((i) => i !== villagers[3]);
  const lastWolf = variant === "both-wolves" ? ordinary[0]! : mentor;
  dayVote(3, alive, lastWolf);
  alive = alive.filter((i) => i !== lastWolf);
  for (const actor of wolves)
    for (const turn of turns.get(actor)!)
      turn.currentTeammateIds = actor === mentor ? [] : wolves.filter((i) => i !== actor);
  return {
    board: parseBoardDefinition(
      boardDefinitionFromConfig("scholar_mentor_transport_" + variant, config),
    ),
    promptAssertions: (_actor, locale) => ({
      requiredSystemMarkers:
        locale === "en"
          ? [
              "apply immunity before conflicts",
              "Both casters are immune",
              "Villagers have no skill",
              "Seer one extra inspection",
              "Guard one extra guard",
              "one independent bonus poison",
              "one individual extra knife",
              "blocks only poison and preserves heal",
              "blocks the entire pack knife",
              "still spends its charge",
              "cancel both effects and cause death at dawn",
              "kill the Mentor at dawn",
              "does not overwrite native previous-target history",
            ]
          : [
              "先判定免疫再判定冲突",
              "两名施法者均免疫",
              "村民没有可增减的技能",
              "增强预言家增加一次查验",
              "增强守卫增加一次守护",
              "独立额外毒药",
              "该狼人独自追加一刀",
              "只禁毒药，保留解药",
              "封锁全队本夜狼刀",
              "合法施法仍消耗次数",
              "两效果取消但原生行动照常",
              "导师黎明死亡",
              "也不改写该历史",
            ],
    }),
    seed,
    roles,
    turns,
    scholar,
    mentor,
    seer,
    knifeActor: ordinary[2]!,
    winner: Camp.Good,
    alive,
  };
}

/**
 * Builds original shapeshifter test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { text } from "@ai-werewolf-arena/game-text";
import { roleName } from "@ai-werewolf-arena/game-text";
import { term } from "@ai-werewolf-arena/game-text";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { foxBoard } from "../../cursed-fox/builders/scenario";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export const SHAPESHIFTER_CASES = [
  "both0",
  "both1",
  "one1",
  "wolf",
  "seer",
  "witch",
  "hunter",
  "guard",
  "idiot",
  "villager",
  "bottom",
] as const;

export type ShapeshifterCase = (typeof SHAPESHIFTER_CASES)[number];

export function shapeshifterScenario(
  kind: ShapeshifterCase,
  size: 6 | 12 = 6,
  locale: "zh-CN" | "en" = "zh-CN",
): TransportGameScenario & {
  initialDeal: Role[];
  actorId: number;
  slot: 0 | 1 | null;
  finalRoles: Role[];
} {
  const replacement =
    kind === "guard"
      ? Role.Guard
      : kind === "idiot"
        ? Role.Idiot
        : kind === "villager"
          ? Role.Villager
          : Role.Hunter;
  const deck = [
    Role.Shapeshifter,
    ...Array<Role>(size === 6 ? 2 : 4).fill(Role.Wolf),
    Role.Seer,
    Role.Witch,
    replacement,
    ...Array<Role>(size === 6 ? 0 : 4).fill(Role.Villager),
  ];
  const config = foxBoard(deck),
    fullDeck = [...deck, Role.Villager, Role.Villager];
  const wanted =
    kind === "both0" || kind === "both1"
      ? [Role.Wolf, Role.Wolf]
      : kind === "one1"
        ? [Role.Seer, Role.Wolf]
        : kind === "wolf"
          ? [Role.Wolf, Role.Seer]
          : kind === "bottom"
            ? [Role.Shapeshifter, Role.Villager]
            : [kind as Role, Role.Villager];
  let seed = "",
    initialDeal: Role[] = [];
  for (let i = 0; i < 200000; i++) {
    seed = `shapeshifter-${size}-${kind}:${i}`;
    initialDeal = shuffled(fullDeck, createRandom(seed).fork("deal"));
    if (
      initialDeal.slice(size).join(",") === wanted.join(",") &&
      (kind === "bottom" || initialDeal.slice(0, size).includes(Role.Shapeshifter))
    )
      break;
    if (i === 199999) throw new Error("fixture_shapeshifter_seed_not_found");
  }
  const roles = initialDeal.slice(0, size),
    actorId = roles.indexOf(Role.Shapeshifter) + 1,
    slot = kind === "bottom" ? null : kind === "both1" || kind === "one1" ? 1 : 0,
    finalRoles = [...roles];
  if (actorId && slot !== null) finalRoles[actorId - 1] = initialDeal[size + slot]!;
  const ids = roles.map((_, i) => i + 1),
    turns = new Map(ids.map((id) => [id, [] as PlannedTurn[]])),
    dead = new Set<number>();
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((id: number) => ToolCall | null),
  ) => {
    for (const id of actors)
      turns
        .get(id)!
        .push({ day, stage, action: typeof action === "function" ? action(id) : action });
  };
  if (actorId)
    add(
      1,
      [actorId],
      "shapeshifter",
      slot === null ? null : { name: "choose_shapeshifter_card", args: { slot } },
    );
  const wolves = ids.filter((id) => finalRoles[id - 1] === Role.Wolf),
    seer = finalRoles.indexOf(Role.Seer) + 1,
    witch = finalRoles.indexOf(Role.Witch) + 1,
    guard = finalRoles.indexOf(Role.Guard) + 1;
  let day = 1;
  while (wolves.some((id) => !dead.has(id))) {
    const liveWolves = wolves.filter((id) => !dead.has(id)),
      shoot = kind === "hunter" && day === 1;
    add(day, liveWolves, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "Done", end_chat: true },
    });
    add(day, liveWolves, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: shoot ? actorId : null, abstain: !shoot },
    });
    if (guard)
      add(day, [guard], "guard", {
        name: "guard",
        args: { target_id: day % 2 ? guard : null, abstain: day % 2 === 0 },
      });
    if (seer)
      add(day, [seer], "seer", { name: "check_identity", args: { target_id: liveWolves[0] } });
    if (witch)
      add(day, [witch], "witch", {
        name: "use_potion",
        args: { target_id: witch, potion_type: PotionType.None },
      });
    if (shoot) {
      add(day, [actorId], "last_words", { name: "speak", args: { text: "First-night Hunter" } });
      add(day, [actorId], "hunter_shot", { name: "shoot", args: { target_id: liveWolves[0] } });
      dead.add(actorId);
      dead.add(liveWolves[0]!);
    }
    const remaining = wolves.filter((id) => !dead.has(id));
    if (!remaining.length) break;
    const alive = ids.filter((id) => !dead.has(id)),
      target = remaining[0]!;
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(day, alive, "voting", (id) => ({
      name: "vote",
      args: { target_id: id === target ? null : target, abstain: id === target },
    }));
    add(day, [target], "last_words", { name: "speak", args: { text: "Exile" } });
    dead.add(target);
    day++;
  }
  for (const [id, rows] of turns)
    for (const turn of rows) {
      const current = turn.stage === "shapeshifter" ? Role.Shapeshifter : finalRoles[id - 1]!;
      turn.requiredPromptMarkers = [
        text(locale, "ability.identity", {
          role: roleName(current, locale),
          camp: term("camp", current === Role.Wolf ? "wolf" : "good", locale),
        }),
      ];
    }
  return {
    board: parseBoardDefinition(boardDefinitionFromConfig(`shapeshifter_${size}_${kind}`, config)),
    seed,
    roles,
    eventRoles: finalRoles,
    turns,
    initialDeal,
    actorId,
    slot,
    finalRoles,
  };
}

/**
 * Builds original thief test input plans, fixed boards and explicit player/marker data. Inputs are supplied
 * variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured identities.
 * Existing dealing may construct input identities, while handwritten expected outcomes remain supplied
 * data. It runs no game or model and changes no oracle algorithm.
 */
import { text } from "@ai-werewolf-arena/game-text";
import { roleName } from "@ai-werewolf-arena/game-text";
import { term } from "@ai-werewolf-arena/game-text";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { foxBoard } from "../../cursed-fox/builders/scenario";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export const THIEF_CASES = [
  "both0",
  "both1",
  "keep",
  "wolf",
  "seer",
  "witch",
  "hunter",
  "guard",
  "idiot",
  "villager",
  "bottom",
] as const;

export type ThiefCase = (typeof THIEF_CASES)[number];

export function thiefScenario(
  kind: ThiefCase,
  size: 6 | 12 = 6,
  locale: "zh-CN" | "en" = "zh-CN",
): TransportGameScenario & {
  initialDeal: Role[];
  actorId: number;
  slot: 0 | 1 | null;
  finalRoles: Role[];
} {
  const replacement =
    kind === "guard"
      ? Role.Guard
      : kind === "idiot"
        ? Role.Idiot
        : kind === "villager"
          ? Role.Villager
          : Role.Hunter;
  const deck = [
    Role.Thief,
    ...Array<Role>(size === 6 ? 2 : 4).fill(Role.Wolf),
    Role.Seer,
    Role.Witch,
    replacement,
    ...Array<Role>(size === 6 ? 0 : 4).fill(Role.Villager),
  ];
  const config = foxBoard(deck),
    fullDeck = [...deck, Role.Villager, Role.Villager];
  const wanted =
    kind === "both0" || kind === "both1"
      ? [Role.Wolf, Role.Wolf]
      : kind === "keep" || kind === "wolf"
        ? [Role.Wolf, Role.Seer]
        : kind === "bottom"
          ? [Role.Thief, Role.Villager]
          : [kind as Role, Role.Villager];
  let seed = "",
    initialDeal: Role[] = [];
  for (let i = 0; i < 200000; i++) {
    seed = `thief-${size}-${kind}:${i}`;
    initialDeal = shuffled(fullDeck, createRandom(seed).fork("deal"));
    if (
      initialDeal.slice(size).join(",") === wanted.join(",") &&
      (kind === "bottom" || initialDeal.slice(0, size).includes(Role.Thief))
    )
      break;
    if (i === 199999) throw new Error("fixture_thief_seed_not_found");
  }
  const roles = initialDeal.slice(0, size),
    actorId = roles.indexOf(Role.Thief) + 1,
    slot = kind === "keep" || kind === "bottom" ? null : kind === "both1" ? 1 : 0,
    finalRoles = [...roles];
  if (actorId && slot !== null) finalRoles[actorId - 1] = initialDeal[size + slot]!;
  const ids = roles.map((_, i) => i + 1),
    turns = new Map(ids.map((id) => [id, [] as PlannedTurn[]])),
    dead = new Set<number>();
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((id: number) => ToolCall | null),
  ) => {
    for (const id of actors)
      turns
        .get(id)!
        .push({ day, stage, action: typeof action === "function" ? action(id) : action });
  };
  if (actorId)
    add(
      1,
      [actorId],
      "thief",
      slot === null ? null : { name: "choose_thief_card", args: { slot } },
    );
  const wolves = ids.filter((id) => finalRoles[id - 1] === Role.Wolf),
    seer = finalRoles.indexOf(Role.Seer) + 1,
    witch = finalRoles.indexOf(Role.Witch) + 1,
    guard = finalRoles.indexOf(Role.Guard) + 1;
  let day = 1;
  while (wolves.some((id) => !dead.has(id))) {
    const liveWolves = wolves.filter((id) => !dead.has(id)),
      shoot = kind === "hunter" && day === 1;
    add(day, liveWolves, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "Done", end_chat: true },
    });
    add(day, liveWolves, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: shoot ? actorId : null, abstain: !shoot },
    });
    if (guard)
      add(day, [guard], "guard", {
        name: "guard",
        args: { target_id: day % 2 ? guard : null, abstain: day % 2 === 0 },
      });
    if (seer)
      add(day, [seer], "seer", { name: "check_identity", args: { target_id: liveWolves[0] } });
    if (witch)
      add(day, [witch], "witch", {
        name: "use_potion",
        args: { target_id: witch, potion_type: PotionType.None },
      });
    if (shoot) {
      add(day, [actorId], "last_words", { name: "speak", args: { text: "First-night Hunter" } });
      add(day, [actorId], "hunter_shot", { name: "shoot", args: { target_id: liveWolves[0] } });
      dead.add(actorId);
      dead.add(liveWolves[0]!);
    }
    const remaining = wolves.filter((id) => !dead.has(id));
    if (!remaining.length) break;
    const alive = ids.filter((id) => !dead.has(id)),
      target = remaining[0]!;
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(day, alive, "voting", (id) => ({
      name: "vote",
      args: { target_id: id === target ? null : target, abstain: id === target },
    }));
    add(day, [target], "last_words", { name: "speak", args: { text: "Exile" } });
    dead.add(target);
    day++;
  }
  for (const [id, rows] of turns)
    for (const turn of rows) {
      const current = turn.stage === "thief" ? Role.Thief : finalRoles[id - 1]!;
      turn.requiredPromptMarkers = [
        text(locale, "ability.identity", {
          role: roleName(current, locale),
          camp: term("camp", current === Role.Wolf ? "wolf" : "good", locale),
        }),
      ];
    }
  return {
    board: parseBoardDefinition(boardDefinitionFromConfig(`thief_${size}_${kind}`, config)),
    seed,
    roles,
    eventRoles: finalRoles,
    turns,
    initialDeal,
    actorId,
    slot,
    finalRoles,
  };
}

/**
 * Builds original time-wolf-consort test input plans, fixed boards and explicit player/marker data. Inputs
 * are supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { ActionWindow } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { timeConsortTwelveConfig } from "../../../../../src/runtime/scenarios/time_consort_twelve";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export function timeConsortScenario(
  scope: "whole_night" | "first_effect" = "whole_night",
): TransportGameScenario & {
  consort: number;
  seer: number;
  guard: number;
  witch: number;
  locked: number;
  winner: Camp;
  alive: number[];
} {
  const config = structuredClone(timeConsortTwelveConfig),
    seed = "time-consort-transport";
  config.timeConsort!.reflectionScope = scope;
  const roles = shuffled(
    config.roleSetups.flatMap((row) => Array.from({ length: row.count }, () => row.role)),
    createRandom(seed).fork("deal"),
  );
  const ids = roles.map((_, i) => i + 1),
    id = (role: Role) => roles.indexOf(role) + 1;
  const consort = id(Role.TimeWolfConsort),
    seer = id(Role.Seer),
    guard = id(Role.Guard),
    witch = id(Role.Witch);
  const ordinary = ids.filter((i) => roles[i - 1] === Role.Wolf),
    wolves = [...ordinary, consort].sort((a, b) => a - b),
    villagers = ids.filter((i) => roles[i - 1] === Role.Villager),
    locked = ordinary[0]!;
  const turns = new Map<number, PlannedTurn[]>(ids.map((i) => [i, []]));
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((actor: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      turns
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Words" } });
  const pack = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const dayVote = (day: number, alive: number[], target: number) => {
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(
      day,
      wolves.filter((i) => alive.includes(i)),
      ActionWindow.OnPreVote,
      null,
    );
    add(day, alive, "voting", (actor) => ({
      name: "vote",
      args: { target_id: actor === target ? null : target, abstain: actor === target },
    }));
    if (alive.includes(id(Role.OrderPrince)))
      add(day, [id(Role.OrderPrince)], "order_prince_choice", {
        name: "reset_exile_vote",
        args: { activate: false },
      });
    words(day, [target]);
  };
  add(1, [consort], "time_consort_lock", {
    name: "lock_time",
    args: { target_id: locked, abstain: false },
  });
  add(1, [guard], "guard", { name: "guard", args: { target_id: locked, abstain: false } });
  pack(1, wolves, villagers[0]!);
  add(1, [witch], "witch", {
    name: "use_potion",
    args: { target_id: locked, potion_type: PotionType.Poison },
  });
  add(1, [seer], "seer", { name: "check_identity", args: { target_id: locked } });
  add(1, wolves, ActionWindow.OnPreElection, null);
  add(1, ids, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
  const poisonDeath = scope === "whole_night" ? witch : locked;
  words(1, [villagers[0]!, poisonDeath]);
  let alive = ids.filter((i) => i !== villagers[0] && i !== poisonDeath);
  dayVote(1, alive, ordinary[1]!);
  alive = alive.filter((i) => i !== ordinary[1]);
  for (let day = 2; day <= 3; day++) {
    const killed = day === 2 ? villagers[2]! : villagers[1]!;
    add(day, [guard], "guard", {
      name: "guard",
      args: { target_id: day === 2 ? villagers[1]! : guard, abstain: false },
    });
    pack(
      day,
      wolves.filter((i) => alive.includes(i)),
      killed,
    );
    if (alive.includes(witch))
      add(day, [witch], "witch", {
        name: "use_potion",
        args: { target_id: witch, potion_type: PotionType.None },
      });
    add(day, [seer], "seer", { name: "check_identity", args: { target_id: consort } });
    alive = alive.filter((i) => i !== killed);
    const voted = day === 2 ? ordinary[2]! : consort;
    dayVote(day, alive, voted);
    alive = alive.filter((i) => i !== voted);
  }
  if (scope === "whole_night") {
    add(4, [guard], "guard", { name: "guard", args: { target_id: seer, abstain: false } });
    pack(4, [locked], guard);
    add(4, [seer], "seer", { name: "check_identity", args: { target_id: locked } });
    alive = alive.filter((i) => i !== guard);
    dayVote(4, alive, locked);
    alive = alive.filter((i) => i !== locked);
  }
  for (const actor of wolves)
    for (const turn of turns.get(actor)!)
      turn.currentTeammateIds = wolves.filter((i) => i !== actor);
  return {
    board: parseBoardDefinition(
      boardDefinitionFromConfig("time_consort_transport_" + scope, config),
    ),
    seed,
    roles,
    turns,
    consort,
    seer,
    guard,
    witch,
    locked,
    winner: Camp.Good,
    alive,
  };
}

/**
 * Builds original trickster test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { ActionWindow } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { tricksterTwelveConfig } from "../../../../../src/runtime/scenarios/trickster_twelve";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export function tricksterScenario(
  variant: "mapped" | "cancel" | "pk" = "mapped",
): TransportGameScenario & { trickster: number; prince: number; alive: number[]; winner: Camp } {
  const config = structuredClone(tricksterTwelveConfig),
    seed = "trickster-transport";
  const roles = shuffled(
    config.roleSetups.flatMap((r) => Array.from({ length: r.count }, () => r.role)),
    createRandom(seed).fork("deal"),
  );
  const ids = roles.map((_, i) => i + 1),
    id = (r: Role) => roles.indexOf(r) + 1;
  const prince = id(Role.OrderPrince),
    trickster = id(Role.Trickster),
    magician = id(Role.Magician),
    seer = id(Role.Seer),
    witch = id(Role.Witch);
  const ordinary = ids.filter((i) => roles[i - 1] === Role.Wolf),
    wolves = [...ordinary, trickster].sort((a, b) => a - b),
    villagers = ids.filter((i) => roles[i - 1] === Role.Villager);
  const turns = new Map<number, PlannedTurn[]>(ids.map((i) => [i, []]));
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((actor: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      turns
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Words" } });
  const pack = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const ballot = (day: number, alive: number[], target: number, stage: ActionStage) =>
    add(day, alive, stage, (actor) => ({
      name: "vote",
      args: { target_id: actor === target ? null : target, abstain: actor === target },
    }));

  const exchange = (
    day: number,
    actor: number,
    tool: "swap_targets" | "swap_exile_targets",
    pair: [number, number] | null,
  ): void => {
    const args = {
      first_id: pair?.[0] ?? null,
      second_id: pair?.[1] ?? null,
      abstain: pair === null,
    };
    const action: ToolCall =
      tool === "swap_targets"
        ? { name: "swap_targets", args }
        : { name: "swap_exile_targets", args };
    add(day, [actor], tool === "swap_targets" ? "magician_exchange" : "trickster_exchange", action);
  };
  const daylight = (day: number, alive: number[], raw: number, actual: number | null) => {
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(
      day,
      wolves.filter((id) => alive.includes(id)),
      ActionWindow.OnPreVote,
      null,
    );
    ballot(day, alive, day === 1 ? prince : raw, "voting");
    if (day === 1) {
      add(day, [prince], "order_prince_choice", {
        name: "reset_exile_vote",
        args: { activate: true },
      });
      add(day, [prince], "order_prince_speech", {
        name: "speak",
        args: { text: "Restart this ballot." },
      });
      if (variant === "pk") {
        const candidates = [prince, ordinary[2]!],
          voters = alive.filter((id) => !candidates.includes(id));
        add(day, alive, "order_prince_revote", (actor) => ({
          name: "vote",
          args: {
            target_id: candidates.includes(actor)
              ? null
              : candidates[voters.indexOf(actor) < 4 ? 0 : 1]!,
            abstain: candidates.includes(actor),
          },
        }));
        add(day, candidates, "exile_pk_speech", { name: "speak", args: { text: "PK speech" } });
        ballot(day, voters, raw, "exile_pk_vote");
      } else ballot(day, alive, raw, "order_prince_revote");
    }
    if (actual !== null) words(day, [actual]);
  };
  exchange(1, magician, "swap_targets", variant === "cancel" ? [prince, ordinary[1]!] : null);
  exchange(1, trickster, "swap_exile_targets", [ordinary[1]!, prince]);
  pack(1, wolves, villagers[0]!);
  add(1, [witch], "witch", {
    name: "use_potion",
    args: { target_id: ordinary[0]!, potion_type: PotionType.Poison },
  });
  add(1, [seer], "seer", { name: "check_identity", args: { target_id: ordinary[1]! } });
  add(1, wolves, ActionWindow.OnPreElection, null);
  add(1, ids, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
  words(1, [villagers[0]!, ordinary[0]!]);
  const alive1 = ids.filter((id) => id !== villagers[0] && id !== ordinary[0]);
  daylight(1, alive1, variant === "cancel" ? ordinary[1]! : prince, ordinary[1]!);
  exchange(2, magician, "swap_targets", null);
  exchange(2, trickster, "swap_exile_targets", [witch, ordinary[2]!]);
  pack(
    2,
    [ordinary[2]!, trickster].sort((a, b) => a - b),
    witch,
  );
  add(2, [witch], "witch", {
    name: "use_potion",
    args: { target_id: witch, potion_type: PotionType.None },
  });
  add(2, [seer], "seer", { name: "check_identity", args: { target_id: ordinary[2]! } });
  const alive2 = alive1.filter((id) => id !== ordinary[1] && id !== witch);
  daylight(2, alive2, ordinary[2]!, null);
  exchange(3, magician, "swap_targets", null);
  exchange(3, trickster, "swap_exile_targets", null);
  pack(
    3,
    [ordinary[2]!, trickster].sort((a, b) => a - b),
    villagers[1]!,
  );
  add(3, [seer], "seer", { name: "check_identity", args: { target_id: trickster } });
  const alive3 = alive2.filter((id) => id !== villagers[1]);
  daylight(3, alive3, trickster, trickster);
  exchange(4, magician, "swap_targets", null);
  pack(4, [ordinary[2]!], seer);
  add(4, [seer], "seer", { name: "check_identity", args: { target_id: ordinary[2]! } });
  const alive4 = alive3.filter((id) => id !== trickster && id !== seer);
  daylight(4, alive4, ordinary[2]!, ordinary[2]!);
  for (const [index, turn] of turns.get(trickster)!.entries()) {
    turn.currentTeammateIds = index === 0 ? [] : [...ordinary].sort((a, b) => a - b);
  }
  return {
    board: parseBoardDefinition(
      boardDefinitionFromConfig("trickster_transport_" + variant, config),
    ),
    seed,
    roles,
    turns,
    trickster,
    prince,
    alive: alive4.filter((id) => id !== ordinary[2]),
    winner: Camp.Good,
  };
}

/**
 * Builds original wall-notes test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { foxBoard } from "../../cursed-fox/builders/scenario";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export function wallScenario(size: 6 | 12, mode: "write" | "skip"): TransportGameScenario {
  const deck = [
    ...Array<Role>(size === 6 ? 2 : 4).fill(Role.Wolf),
    Role.Seer,
    Role.Witch,
    Role.Hunter,
    ...Array<Role>(size === 6 ? 1 : 5).fill(Role.Villager),
  ];
  const config = { ...foxBoard(deck), events: { pack: "awa_wall_notes_once_v1" as const } },
    seed = `wall-${size}-${mode}`,
    roles = shuffled(deck, createRandom(seed).fork("deal")),
    ids = roles.map((_, i) => i + 1),
    wolves = ids.filter((id) => roles[id - 1] === Role.Wolf),
    villagers = ids.filter((id) => roles[id - 1] === Role.Villager),
    seer = roles.indexOf(Role.Seer) + 1,
    witch = roles.indexOf(Role.Witch) + 1;
  const turns = new Map(ids.map((id) => [id, [] as PlannedTurn[]])),
    dead = new Set<number>();
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((id: number) => ToolCall | null),
  ) => {
    for (const id of actors)
      turns
        .get(id)!
        .push({ day, stage, action: typeof action === "function" ? action(id) : action });
  };
  for (let day = 1; day <= wolves.length; day++) {
    const liveWolves = wolves.filter((id) => !dead.has(id)),
      knife = villagers[Math.max(0, day - 2)]!;
    add(day, liveWolves, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "Done", end_chat: true },
    });
    add(day, liveWolves, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: knife, abstain: false },
    });
    add(day, [seer], "seer", { name: "check_identity", args: { target_id: liveWolves[0] } });
    add(
      day,
      [witch],
      "witch",
      day === 1
        ? { name: "use_potion", args: { target_id: knife, potion_type: PotionType.Heal } }
        : { name: "use_potion", args: { target_id: witch, potion_type: PotionType.None } },
    );
    if (day > 1) dead.add(knife);
    const alive = ids.filter((id) => !dead.has(id));
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(day, alive, "voting", (id) => ({
      name: "vote",
      args: {
        target_id: id === liveWolves[0] ? null : liveWolves[0],
        abstain: id === liveWolves[0],
      },
    }));
    add(day, [liveWolves[0]], "last_words", { name: "speak", args: { text: "Exile last" } });
    dead.add(liveWolves[0]);
    if (day === 1)
      add(
        day,
        ids.filter((id) => !dead.has(id)),
        "wall_notes",
        (id) =>
          mode === "skip"
            ? null
            : {
                name: "write_note",
                args: { text: id % 2 ? "  [God] secret 💌  " : "Anonymous note" },
              },
      );
  }
  return {
    board: parseBoardDefinition(boardDefinitionFromConfig(`wall_${size}_${mode}`, config)),
    seed,
    roles,
    turns,
  };
}

/**
 * Builds original white-wolf-king test input plans, fixed boards and explicit player/marker data. Inputs
 * are supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { PotionType } from "../../../../../src/core";
import { oracle } from "../oracles/prompt-plan";
import { ActionWindow } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { WinCondition } from "../../../../../src/core";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import { sixPlayerMvpConfig } from "../../../../../src/runtime/scenarios/six_player_mvp";
import { twelvePlayerStandardConfig } from "../../../../../src/runtime/scenarios/twelve_player_standard";
import { foundationTransportPlan } from "../../../builders/transport/foundation-plan";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export type WhiteWolfScenario =
  "hunter" | PotionType.None | "pending_poison" | "pending_knife" | "wolf_king" | "twelve";

const whiteAction = (target_id: number | null) => ({
  name: "self_destruct_with_target" as const,
  args: { reason: "Chosen public action", confirm: true, target_id },
});

export function whiteWolfScenario(
  kind: WhiteWolfScenario,
  window: ActionWindow = ActionWindow.OnPreVote,
): TransportGameScenario {
  if (kind === "twelve") {
    const turns = foundationTransportPlan(12);
    for (const [actor, rows] of turns)
      turns.set(
        actor,
        rows.filter(
          (row) =>
            !(row.day === 1 && (row.stage === "voting" || row.stage === "last_words")) &&
            !(actor === 10 && row.day === 2) &&
            !(actor === 2 && row.day === 2),
        ),
      );
    turns.get(2)!.find((row) => row.stage === ActionWindow.OnPreVote)!.action = whiteAction(10);
    const cast = turns.get(2)!.find((row) => row.stage === ActionWindow.OnPreVote)!;
    cast.invalidActions = [whiteAction(999)];
    cast.expectedInvalidError = "white_wolf_blast_target";
    for (const row of turns.get(5)!.filter((row) => row.stage === "seer"))
      row.action = { name: "check_identity", args: { target_id: row.day === 1 ? 2 : 1 } };
    // Remaining ordinary wolf 1 survives the first interruption and replaces old wolf 2's second-night/final-blast script.
    turns.set(1, [
      ...turns.get(1)!,
      ...foundationTransportPlan(12)
        .get(2)!
        .filter((row) => row.day === 2),
    ]);
    const roles = [
      Role.Wolf,
      Role.WhiteWolfKing,
      Role.Wolf,
      Role.Wolf,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Idiot,
      Role.Villager,
      Role.Villager,
      Role.Villager,
      Role.Villager,
    ];
    const definition = boardDefinitionFromConfig("twelve_player_white_wolf_king", {
      ...twelvePlayerStandardConfig,
      roleSetups: [
        { role: Role.WhiteWolfKing, count: 1 },
        { role: Role.Wolf, count: 3 },
        ...twelvePlayerStandardConfig.roleSetups.slice(1),
      ],
    });
    return oracle({
      board: parseBoardDefinition(definition),
      seed: "foundation-twelve:124680",
      roles,
      turns,
    });
  }
  const pending = kind === "pending_poison" || kind === "pending_knife";
  const roles = pending
    ? [Role.WhiteWolfKing, Role.Wolf, Role.Seer, Role.Witch, Role.Villager, Role.Villager]
    : kind === "wolf_king"
      ? [Role.WhiteWolfKing, Role.WolfKing, Role.Seer, Role.Hunter, Role.Villager, Role.Villager]
      : [Role.WhiteWolfKing, Role.Wolf, Role.Seer, Role.Hunter, Role.Villager, Role.Villager];
  const counts = roles
    .map((role) => ({ role, count: roles.filter((item) => item === role).length }))
    .filter((row, index, all) => all.findIndex((entry) => entry.role === row.role) === index);
  const actualWindow = pending ? ActionWindow.OnPreElection : window;
  const definition = boardDefinitionFromConfig(
    kind === "wolf_king" ? "six_player_white_wolf_king_chain" : "six_player_white_wolf_king",
    {
      ...sixPlayerMvpConfig,
      roleSetups: counts,
      winConditions: [WinCondition.SlaughterSide],
      enableSheriff: true,
      sheriff: { voteWeight: 2.25 },
      hooks: { onPreElection: true, onDaybreak: true, onPreVote: true, onPerSpeechGap: true },
      selfDestruct: { enabledWindows: [actualWindow] },
    },
  );
  const turns = new Map<number, PlannedTurn[]>(roles.map((_, index) => [index + 1, []]));
  const add = (
    day: number,
    actors: number[],
    stage: PlannedTurn["stage"],
    action: PlannedTurn["action"],
  ) => actors.forEach((actor) => turns.get(actor)!.push({ day, stage, action }));
  add(1, [1, 2], "wolf_discussion", {
    name: "speak_to_wolves",
    args: { text: "End", end_chat: true },
  });
  add(1, [1, 2], "wolf_vote", {
    name: "kill_vote",
    args: { target_id: kind === "pending_knife" ? 1 : 5, abstain: false },
  });
  add(1, [3], "seer", { name: "check_identity", args: { target_id: 1 } });
  if (pending)
    add(1, [4], "witch", {
      name: "use_potion",
      args: {
        target_id: 1,
        potion_type: kind === "pending_poison" ? PotionType.Poison : PotionType.None,
      },
    });
  if (actualWindow !== ActionWindow.OnPreElection) {
    add(1, [1, 2, 3, 4, 5, 6], "sheriff_nomination", {
      name: "run_for_sheriff",
      args: { run: false },
    });
    add(1, [5], "last_words", { name: "speak", args: { text: "Night last words" } });
    if (actualWindow === ActionWindow.OnPerSpeechGap)
      add(1, [1], "day_speech", { name: "speak", args: { text: "First normal speech" } });
    if (actualWindow === ActionWindow.OnPreVote)
      add(1, [1, 2, 3, 4, 6], "day_speech", { name: "speak", args: { text: "Public speech" } });
  }
  const target = kind === PotionType.None ? null : pending ? 3 : kind === "wolf_king" ? 2 : 4;
  add(1, [1], actualWindow, whiteAction(target));
  turns.get(1)!.at(-1)!.invalidActions = [whiteAction(999)];
  turns.get(1)!.at(-1)!.expectedInvalidError = "white_wolf_blast_target";
  add(
    1,
    [2],
    actualWindow,
    pending
      ? { name: "self_destruct", args: { reason: "Higher valid candidate", confirm: true } }
      : null,
  );
  if (actualWindow === ActionWindow.OnPreElection) {
    add(1, pending ? (kind === "pending_knife" ? [1] : [1, 5]) : [5], "last_words", {
      name: "speak",
      args: { text: "Night last words" },
    });
  }
  if (kind === "hunter") add(1, [4], "hunter_shot", { name: "shoot", args: { target_id: 2 } });
  if (kind === "wolf_king") {
    add(1, [2], "death_shot", { name: "shoot", args: { target_id: 4 } });
    add(1, [4], "hunter_shot", { name: "shoot", args: { target_id: 3 } });
  }
  if (kind === PotionType.None) {
    add(2, [2], "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(2, [2], "wolf_vote", { name: "kill_vote", args: { target_id: 4, abstain: false } });
    add(2, [3], "seer", { name: "check_identity", args: { target_id: 2 } });
    add(2, [4], "hunter_shot", { name: "shoot", args: { target_id: 2 } });
  }
  return oracle({
    board: parseBoardDefinition(definition),
    roles,
    turns,
    seed: pending
      ? "white-wolf-pending_poison:798"
      : kind === "wolf_king"
        ? "white-wolf-wolf_king:336"
        : "white-wolf-hunter:641",
  }); // Frozen role-specific seed is installed below.
}

/**
 * Owns original test oracle white-wolf-king handwritten expected data and bounded contract assertions. Inputs are
 * supplied plans or observed tuples; outputs preserve literal stock, identity, marker and error
 * expectations. No expected game result is regenerated from production settlement; this owner performs no
 * game, model or transport execution.
 */
import { Role } from "../../../../../src/core";
import type { TransportGameScenario } from "../../../transport/contracts";

export function oracle(scenario: TransportGameScenario): TransportGameScenario {
  return {
    ...scenario,
    promptAssertions: (actor, locale) =>
      scenario.roles[actor - 1] === Role.WhiteWolfKing
        ? {
            expectedIdentityMarker:
              locale === "en" ? "your true role is White Wolf King." : "真实身份是白狼王。",
            requiredCurrentMarkers:
              locale === "en"
                ? ["Your role is White Wolf King.", "Self-destruct opportunities remaining: 1."]
                : ["你的底牌是【白狼王】", "自爆机会剩余：1。"],
          }
        : {
            forbiddenCurrentMarkers: [
              locale === "en" ? "Self-destruct opportunities remaining:" : "自爆机会剩余：",
            ],
          },
  };
}

/**
 * Builds original wild-child test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { text } from "@ai-werewolf-arena/game-text";
import { roleName } from "@ai-werewolf-arena/game-text";
import { term } from "@ai-werewolf-arena/game-text";
import { Role } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { ActionWindow } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { foxBoard } from "../../cursed-fox/builders/scenario";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export const WILD_CHILD_CASES = [
  "wolf_exile",
  "good_knife",
  "poison",
  "hunter_chain",
  "same_wave",
  "self_destruct",
  "model_alive",
] as const;

export type WildChildCase = (typeof WILD_CHILD_CASES)[number];

export function wildChildScenario(
  kind: WildChildCase,
  size: 6 | 12 = 6,
  locale: "zh-CN" | "en" = "zh-CN",
): TransportGameScenario & {
  actorId: number;
  modelId: number;
  transformed: boolean;
  active: boolean;
} {
  const deck = [
    Role.WildChild,
    ...Array<Role>(size === 6 ? 2 : 4).fill(Role.Wolf),
    Role.Seer,
    Role.Witch,
    Role.Hunter,
    ...Array<Role>(size === 6 ? 0 : 4).fill(Role.Villager),
  ];
  const seed = `wild-child:${size}:${kind}`,
    roles = shuffled(deck, createRandom(seed).fork("deal")),
    ids = roles.map((_, i) => i + 1),
    child = roles.indexOf(Role.WildChild) + 1,
    seer = roles.indexOf(Role.Seer) + 1,
    witch = roles.indexOf(Role.Witch) + 1,
    hunter = roles.indexOf(Role.Hunter) + 1,
    originalWolves = ids.filter((id) => roles[id - 1] === Role.Wolf);
  const model = ["wolf_exile", "poison", "self_destruct"].includes(kind)
    ? originalWolves[0]!
    : kind === "good_knife" && size === 12
      ? roles.indexOf(Role.Villager) + 1
      : hunter;
  const transformed = kind !== "same_wave" && kind !== "model_alive",
    active = transformed && kind !== "hunter_chain";
  const config = {
    ...foxBoard(deck),
    ...(kind === "self_destruct"
      ? {
          selfDestruct: { enabledWindows: [ActionWindow.OnPreVote] },
          hooks: { ...foxBoard(deck).hooks, onPreVote: true },
        }
      : {}),
  };
  const turns = new Map(ids.map((id) => [id, [] as PlannedTurn[]])),
    dead = new Set<number>();
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((id: number) => ToolCall | null),
  ) => {
    for (const id of actors)
      turns
        .get(id)!
        .push({ day, stage, action: typeof action === "function" ? action(id) : action });
  };
  add(1, [child], "wild_child", { name: "choose_wild_model", args: { target_id: model } });
  let day = 1,
    converted = false;
  for (;;) {
    const wolves = [...originalWolves, ...(converted && active ? [child] : [])].filter(
      (id) => !dead.has(id),
    );
    add(day, wolves, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "Raw pack", end_chat: true },
    });
    const knife =
      day === 1 && ["good_knife", "hunter_chain", "same_wave"].includes(kind) ? model : null;
    add(day, wolves, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: knife, abstain: knife === null },
    });
    if (!dead.has(seer))
      add(day, [seer], "seer", {
        name: "check_identity",
        args: { target_id: day === 1 ? model : !dead.has(child) ? child : wolves[0] },
      });
    if (!dead.has(witch))
      add(day, [witch], "witch", {
        name: "use_potion",
        args: {
          target_id:
            day === 1 && kind === "poison"
              ? model
              : day === 1 && kind === "same_wave"
                ? child
                : witch,
          potion_type:
            day === 1 && ["poison", "same_wave"].includes(kind)
              ? PotionType.Poison
              : PotionType.None,
        },
      });
    const nightDead =
      day === 1
        ? [
            ...(knife === null ? [] : [model]),
            ...(kind === "poison" ? [model] : kind === "same_wave" ? [child] : []),
          ]
        : [];
    for (const id of nightDead) dead.add(id);
    if (nightDead.includes(model)) converted = transformed;
    add(
      day,
      [...new Set(nightDead)].sort((a, b) => a - b),
      "last_words",
      { name: "speak", args: { text: "Night last words" } },
    );
    if (nightDead.includes(hunter)) {
      add(day, [hunter], "hunter_shot", {
        name: "shoot",
        args: { target_id: kind === "hunter_chain" ? child : null },
      });
      if (kind === "hunter_chain") dead.add(child);
    }
    const alive = ids.filter((id) => !dead.has(id));
    add(day, alive, "day_speech", { name: "speak", args: { text: "Raw speech" } });
    if (kind === "self_destruct") {
      const candidates = originalWolves.filter((id) => !dead.has(id)).sort((a, b) => a - b);
      if (day === 1) {
        add(day, candidates, ActionWindow.OnPreVote, (id) =>
          id === model
            ? { name: "self_destruct", args: { reason: "Raw blast", confirm: true } }
            : null,
        );
        dead.add(model);
        converted = true;
        day++;
        continue;
      }
      add(day, candidates, ActionWindow.OnPreVote, null);
    }
    const target =
      originalWolves.find((id) => !dead.has(id)) ??
      (converted && !dead.has(child) ? child : undefined);
    if (target === undefined) throw new Error("fixture_unexpected_early_end");
    add(day, alive, "voting", (id) => ({
      name: "vote",
      args: { target_id: id === target ? null : target, abstain: id === target },
    }));
    add(day, [target], "last_words", { name: "speak", args: { text: "Raw exile" } });
    dead.add(target);
    if (target === model) converted = transformed;
    if (!originalWolves.some((id) => !dead.has(id)) && (!converted || dead.has(child))) break;
    day++;
  }
  for (const [id, rows] of turns)
    for (const turn of rows) {
      let faction = roles[id - 1] === Role.Wolf ? Camp.Wolf : Camp.Good;
      if (
        id === child &&
        transformed &&
        (turn.day > 1 ||
          (turn.day === 1 &&
            ["good_knife", "poison", "hunter_chain"].includes(kind) &&
            ["day_speech", "voting"].includes(turn.stage)))
      )
        faction = Camp.Wolf;
      turn.requiredPromptMarkers = [
        text(locale, "ability.identity", {
          role: roleName(roles[id - 1]!, locale),
          camp: term("camp", faction, locale),
        }),
      ];
    }
  return {
    board: parseBoardDefinition(boardDefinitionFromConfig(`wild_child_${size}_${kind}`, config)),
    seed,
    roles,
    turns,
    eventRoles: roles.map((role, id) => (role === Role.WildChild && active ? Role.Wolf : role)),
    actorId: child,
    modelId: model,
    transformed,
    active,
  };
}

/**
 * Builds original wolf-beauty test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { PotionType } from "../../../../../src/core";
import { KnightDuelWindow } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { WinCondition } from "../../../../../src/core";
import type { BoardConfig } from "../../../../../src/core";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { sixPlayerMvpConfig } from "../../../../../src/runtime/scenarios/six_player_mvp";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export const BEAUTY_CASES = [
  "exile",
  PotionType.Poison,
  "duel",
  "night_dream_block",
  "night_dream_chain",
  "same_wave",
  "last_god",
  "last_villager",
  "city_first",
  "side_first",
  "skip",
  "twelve",
] as const;

export type BeautyScenario = (typeof BEAUTY_CASES)[number];

export function wolfBeautyScenario(kind: BeautyScenario): TransportGameScenario {
  const twelve = kind === "twelve",
    special = ["last_god", "city_first", "side_first"].includes(kind),
    dream = kind.startsWith("night_dream");
  const roles = twelve
    ? [
        Role.WolfBeauty,
        Role.Wolf,
        Role.Wolf,
        Role.Wolf,
        Role.Seer,
        Role.Witch,
        Role.Guard,
        Role.Knight,
        Role.Villager,
        Role.Villager,
        Role.Villager,
        Role.Villager,
      ]
    : special
      ? [Role.WolfBeauty, Role.Witch, Role.Knight, Role.Villager, Role.Villager, Role.Villager]
      : kind === "last_villager"
        ? [Role.WolfBeauty, Role.Witch, Role.Knight, Role.Knight, Role.Seer, Role.Villager]
        : [
            Role.WolfBeauty,
            Role.Wolf,
            Role.Witch,
            dream ? Role.Dreamer : Role.Knight,
            kind === "same_wave" ? Role.Hunter : Role.Villager,
            Role.Villager,
          ];
  const config: BoardConfig = {
    ...sixPlayerMvpConfig,
    boardSize: roles.length,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
      count: roles.filter((r) => r === role).length,
    })),
    enableSheriff: twelve,
    winConditions:
      kind === "city_first"
        ? [WinCondition.SlaughterCity, WinCondition.SlaughterSide]
        : kind === "side_first"
          ? [WinCondition.SlaughterSide, WinCondition.SlaughterCity]
          : [WinCondition.SlaughterSide],
    selfDestruct: { enabledWindows: [] },
    knight: { enabledWindows: [KnightDuelWindow.AfterSpeeches] },
  };
  const turns = new Map<number, PlannedTurn[]>(roles.map((_, index) => [index + 1, []]));
  const add = (
    day: number,
    actors: number[],
    stage: PlannedTurn["stage"],
    action: PlannedTurn["action"],
  ) => actors.forEach((actor) => turns.get(actor)!.push({ day, stage, action }));
  const night = (day: number, actors: number[], target: number | null) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: target === null },
    });
  };
  const charm = (day: number, target: number | null) =>
    add(day, [1], "wolf_beauty", { name: "charm", args: { target_id: target } });
  const potion = (day: number, actor: number, target: number, type: PotionType = PotionType.None) =>
    add(day, [actor], "witch", {
      name: "use_potion",
      args: { target_id: target, potion_type: type },
    });
  const speech = (day: number, actors: number[]) =>
    add(day, actors, "day_speech", { name: "speak", args: { text: "Public speech" } });
  const vote = (day: number, actors: number[], target: number | null) =>
    add(day, actors, "voting", {
      name: "vote",
      args: { target_id: target, abstain: target === null },
    });
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Authorized words" } });
  const knight = (day: number, actors: number[], target?: number) =>
    add(
      day,
      actors,
      KnightDuelWindow.AfterSpeeches,
      target === undefined ? null : { name: "duel", args: { target_id: target, confirm: true } },
    );
  if (twelve) {
    const all = Array.from({ length: 12 }, (_, i) => i + 1);
    for (const day of [1, 2, 3]) {
      if (day !== 3)
        add(day, [7], "guard", {
          name: "guard",
          args: { target_id: day === 2 ? 12 : 10, abstain: false },
        });
      night(day, day === 1 ? [1, 2, 3, 4] : day === 2 ? [1, 3, 4] : [1], day === 2 ? 7 : 9);
      charm(day, day === 1 ? null : day === 2 ? 11 : 12);
      potion(
        day,
        6,
        day === 1 ? 9 : day === 2 ? 3 : 6,
        day === 1 ? PotionType.Heal : day === 2 ? PotionType.Poison : PotionType.None,
      );
      add(day, [5], "seer", {
        name: "check_identity",
        args: { target_id: day === 1 ? 2 : day === 2 ? 4 : 1 },
      });
      if (day === 1)
        add(day, all, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
      const alive =
        day === 1 ? all : day === 2 ? [1, 4, 5, 6, 8, 9, 10, 11, 12] : [1, 5, 6, 8, 10, 11, 12];
      speech(day, alive);
      knight(day, [8]);
      vote(day, alive, day === 1 ? 2 : day === 2 ? 4 : 1);
      words(day, [day === 1 ? 2 : day === 2 ? 4 : 1]);
    }
  } else if (special || kind === "last_villager") {
    night(1, [1], 3);
    charm(1, special ? 2 : 6);
    potion(1, 2, 2);
    if (!special) add(1, [5], "seer", { name: "check_identity", args: { target_id: 1 } });
    words(1, [3]);
    speech(1, [1, 2, 4, 5, 6]);
    if (!special) knight(1, [4]);
    vote(1, [1, 2, 4, 5, 6], 1);
    words(1, [1]);
  } else if (kind === "skip") {
    for (const day of [1, 2, 3]) {
      night(day, day === 3 ? [1] : [1, 2], day === 3 ? 6 : null);
      charm(day, day === 2 ? null : 5);
      if (day === 2) {
        const turn = turns.get(1)!.at(-1)!;
        turn.invalidActions = [{ name: "charm", args: { target_id: 5 } }];
        turn.expectedInvalidError = "charm_repeat";
      }
      potion(day, 3, 3);
      const alive = day === 1 || day === 2 ? [1, 2, 3, 4, 5, 6] : [1, 3, 4, 5];
      speech(day, alive);
      knight(day, [4]);
      vote(day, alive, day === 1 ? null : day === 2 ? 2 : 1);
      if (day !== 1) words(day, [day === 2 ? 2 : 1]);
    }
  } else {
    if (dream) add(1, [4], "dreamer", { name: "dream", args: { target_id: 5 } });
    night(1, [1, 2], kind === "same_wave" ? 5 : 6);
    charm(1, kind === "duel" ? 3 : kind === "night_dream_chain" ? 4 : 5);
    potion(
      1,
      3,
      kind === PotionType.Poison || dream || kind === "same_wave" ? 1 : 3,
      kind === PotionType.Poison || dream || kind === "same_wave"
        ? PotionType.Poison
        : PotionType.None,
    );
    words(1, kind === PotionType.Poison || dream ? [1, 6] : kind === "same_wave" ? [1, 5] : [6]);
    if (kind !== PotionType.Poison && kind !== "night_dream_chain") {
      const alive =
        kind === "night_dream_block"
          ? [2, 3, 4, 5]
          : kind === "same_wave"
            ? [2, 3, 4, 6]
            : [1, 2, 3, 4, 5];
      speech(1, alive);
      if (!dream) knight(1, [4], kind === "duel" ? 1 : undefined);
      if (kind === "duel") {
        night(2, [2], 2);
        potion(2, 3, 3);
      } else {
        vote(1, alive, kind === "night_dream_block" || kind === "same_wave" ? 2 : 1);
        words(1, [kind === "night_dream_block" || kind === "same_wave" ? 2 : 1]);
      }
    }
  }
  // Static role/state assertions; transport scripts receive no World or RNG capability.
  let latest: NonNullable<PlannedTurn["charmLatest"]> = { day: null, targetId: null };
  for (const turn of turns.get(1)!) {
    turn.charmLatest = latest;
    if (turn.action?.name === "charm")
      latest = { day: turn.day, targetId: turn.action.args.target_id };
  }
  const family = twelve
      ? "twelve"
      : special
        ? "god"
        : kind === "last_villager"
          ? "villager"
          : kind === "same_wave"
            ? "hunter"
            : dream
              ? "dream"
              : "exile",
    seeds = {
      twelve: "beauty-twelve:4020350",
      god: "beauty-god:141",
      villager: "beauty-villager:57",
      hunter: "beauty-hunter:662",
      dream: "beauty-dream:618",
      exile: "beauty-exile:414",
    };
  return {
    board: parseBoardDefinition(
      boardDefinitionFromConfig(`${twelve ? "twelve" : "six"}_player_wolf_beauty_${kind}`, config),
    ),
    roles,
    turns,
    seed: seeds[family],
    promptAssertions: (actor, locale) =>
      actor === 1
        ? {
            expectedIdentityMarker:
              locale === "en" ? "your true role is Wolf Beauty." : "真实身份是狼美人。",
            requiredCurrentMarkers: [
              locale === "en" ? "Your role is Wolf Beauty," : "你的底牌是【狼美人】",
              locale === "en"
                ? "configured victory conditions still use their first matching order"
                : "配置的胜利条件仍按先命中顺序判断",
            ],
          }
        : {
            forbiddenCurrentMarkers: [locale === "en" ? "Current charm target:" : "当前魅惑目标："],
          },
  };
}

/**
 * Builds original wolf-king test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { PotionType } from "../../../../../src/core";
import { withPromptOracle } from "../oracles/prompt-plan";
import { ActionWindow } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { WinCondition } from "../../../../../src/core";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import { foundationTransportPlan } from "../../../builders/transport/foundation-plan";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";
import { sixPlayerMvpConfig } from "../../../../../src/runtime/scenarios/six_player_mvp";
import { twelvePlayerStandardConfig } from "../../../../../src/runtime/scenarios/twelve_player_standard";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";

export type WolfKingScenario =
  "exile_chain" | PotionType.Poison | "twelve" | "blast" | "shot_chain";

export function wolfKingScenario(kind: WolfKingScenario): TransportGameScenario {
  if (kind === "twelve") {
    // Frozen seed maps the first old wolf card to seat 2. Permute only literal wolf IDs 1/2.
    const ids = (id: number) => (id === 1 ? 2 : id === 2 ? 1 : id);
    const turns = new Map<number, PlannedTurn[]>();
    for (const [actor, rows] of foundationTransportPlan(12))
      turns.set(
        ids(actor),
        rows
          .filter((row) => !(actor === 10 && row.day === 2))
          .map((row) => ({
            ...row,
            action:
              row.action && "target_id" in row.action.args && row.action.args.target_id !== null
                ? ({
                    ...row.action,
                    args: { ...row.action.args, target_id: ids(row.action.args.target_id) },
                  } as typeof row.action)
                : row.action,
          })),
      );
    turns.get(2)!.push({
      day: 1,
      stage: "death_shot",
      action: { name: "shoot", args: { target_id: 10 } },
      invalidActions: [{ name: "shoot", args: { target_id: 999 } }],
    });
    const definition = boardDefinitionFromConfig("twelve_player_wolf_king", {
      ...twelvePlayerStandardConfig,
      roleSetups: [
        { role: Role.WolfKing, count: 1 },
        { role: Role.Wolf, count: 3 },
        ...twelvePlayerStandardConfig.roleSetups.slice(1),
      ],
    });
    return withPromptOracle({
      board: parseBoardDefinition(definition),
      seed: "foundation-twelve:124680",
      roles: [
        Role.Wolf,
        Role.WolfKing,
        Role.Wolf,
        Role.Wolf,
        Role.Seer,
        Role.Witch,
        Role.Hunter,
        Role.Idiot,
        Role.Villager,
        Role.Villager,
        Role.Villager,
        Role.Villager,
      ],
      turns,
    });
  }
  const roles =
    kind === PotionType.Poison
      ? [Role.WolfKing, Role.Hunter, Role.Seer, Role.Witch, Role.Villager, Role.Villager]
      : [Role.WolfKing, Role.Hunter, Role.Seer, Role.Villager, Role.Villager, Role.Villager];
  const counts = roles
    .map((role) => ({ role, count: roles.filter((item) => item === role).length }))
    .filter((entry, index, array) => array.findIndex((item) => item.role === entry.role) === index);
  const board = parseBoardDefinition(
    boardDefinitionFromConfig(
      kind === PotionType.Poison ? "six_player_wolf_king_poison" : "six_player_wolf_king",
      {
        ...sixPlayerMvpConfig,
        winConditions: [WinCondition.SlaughterSide],
        roleSetups: counts,
        enableSheriff: true,
        initialSheriffSeat: 1,
        sheriff: { voteWeight: 2.25 },
        hooks: { ...sixPlayerMvpConfig.hooks, onPreVote: kind === "blast" },
        selfDestruct: { enabledWindows: kind === "blast" ? [ActionWindow.OnPreVote] : [] },
      },
    ),
  );
  const turns = new Map<number, PlannedTurn[]>(roles.map((_, index) => [index + 1, []]));
  const add = (actors: number[], stage: PlannedTurn["stage"], action: PlannedTurn["action"]) =>
    actors.forEach((actor) => turns.get(actor)!.push({ day: 1, stage, action }));
  add([1], "wolf_discussion", {
    name: "speak_to_wolves",
    args: { text: "End discussion", end_chat: true },
  });
  add([1], "wolf_vote", {
    name: "kill_vote",
    args: {
      target_id: kind === PotionType.Poison || kind === "shot_chain" ? 2 : 5,
      abstain: false,
    },
  });
  add([3], "seer", { name: "check_identity", args: { target_id: 1 } });
  if (kind === PotionType.Poison) {
    add([4], "witch", {
      name: "use_potion",
      args: { target_id: 1, potion_type: PotionType.Poison },
    });
    add([1, 2], "last_words", { name: "speak", args: { text: "First night last words" } });
    add([2], "hunter_shot", { name: "shoot", args: { target_id: 5 } });
  } else if (kind === "shot_chain") {
    add([2], "last_words", { name: "speak", args: { text: "First night last words" } });
    add([2], "hunter_shot", { name: "shoot", args: { target_id: 1 } });
    add([1], "death_shot", { name: "shoot", args: { target_id: 3 } });
    turns.get(1)!.at(-1)!.invalidActions = [{ name: "shoot", args: { target_id: 999 } }];
  } else {
    add([5], "last_words", { name: "speak", args: { text: "First night last words" } });
    add([1], "sheriff_choose_direction", {
      name: "choose_direction",
      args: { direction: "clockwise" },
    });
    add([1, 2, 3, 4, 6], "day_speech", { name: "speak", args: { text: "Exile the wolf king" } });
    if (kind === "blast")
      add([1], ActionWindow.OnPreVote, {
        name: "self_destruct",
        args: { reason: "Ordinary blast", confirm: true },
      });
    else {
      add([1, 2, 3, 4, 6], "voting", { name: "vote", args: { target_id: 1, abstain: false } });
      add([1], "last_words", { name: "speak", args: { text: "Exile last words" } });
      add([1], "death_shot", { name: "shoot", args: { target_id: 2 } });
      turns.get(1)!.at(-1)!.invalidActions = [{ name: "shoot", args: { target_id: 999 } }];
      add([2], "hunter_shot", { name: "shoot", args: { target_id: 3 } });
    }
  }
  return withPromptOracle({
    board,
    roles,
    turns,
    seed: kind === PotionType.Poison ? "wolf-king-poison:225" : "wolf-king-exile:91",
  });
}

/**
 * Owns original test oracle wolf-king handwritten expected data and bounded contract assertions. Inputs are supplied
 * plans or observed tuples; outputs preserve literal stock, identity, marker and error expectations. No
 * expected game result is regenerated from production settlement; this owner performs no game, model or
 * transport execution.
 */
import { Role } from "../../../../../src/core";
import type { TransportGameScenario } from "../../../transport/contracts";

export function withPromptOracle(scenario: TransportGameScenario): TransportGameScenario {
  return {
    ...scenario,
    promptAssertions: (actor, locale) =>
      scenario.roles[actor - 1] === Role.WolfKing
        ? {
            expectedIdentityMarker:
              locale === "en" ? "your true role is Wolf King." : "真实身份是狼王。",
            requiredCurrentMarkers:
              locale === "en"
                ? ["Your role is Wolf King.", "Shots remaining: 1."]
                : ["你的底牌是【狼王】", "剩余枪：1。"],
          }
        : { forbiddenCurrentMarkers: [locale === "en" ? "Shots remaining:" : "剩余枪："] },
  };
}

/**
 * Builds original wolf-sorcerer test input plans, fixed boards and explicit player/marker data. Inputs are
 * supplied variant/locale/seed choices; outputs retain the same arrays, stock parameters and configured
 * identities. Existing dealing may construct input identities, while handwritten expected outcomes remain
 * supplied data. It runs no game or model and changes no oracle algorithm.
 */
import { ActionWindow } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { Role } from "../../../../../src/core";
import { PotionType } from "../../../../../src/core";
import { createRandom } from "../../../../../src/core";
import { shuffled } from "../../../../../src/core";
import type { ActionStage } from "../../../../../src/core";
import type { ToolCall } from "../../../../../src/core";
import { wolfSorcererTwelveConfig } from "../../../../../src/runtime/scenarios/wolf_sorcerer_twelve";
import { boardDefinitionFromConfig } from "../../../../../src/runtime/config/board_definition";
import { parseBoardDefinition } from "../../../../../src/runtime/config/board_definition";
import type { PlannedTurn } from "../../../transport/contracts";
import type { TransportGameScenario } from "../../../transport/contracts";

export function wolfSorcererScenario(
  variant: "overlap" | "cancel" | "disjoint" = "overlap",
): TransportGameScenario & {
  sorcerer: number;
  psychic: number;
  hunter: number;
  wolfTarget: number;
  inspectionRole: Role;
  alive: number[];
  winner: Camp;
} {
  const config = structuredClone(wolfSorcererTwelveConfig),
    seed = "wolf-sorcerer-transport";
  config.magician!.deathShotTargetPolicy = "exchanged";
  const roles = shuffled(
    config.roleSetups.flatMap((row) => Array.from({ length: row.count }, () => row.role)),
    createRandom(seed).fork("deal"),
  );
  const ids = roles.map((_, i) => i + 1),
    id = (role: Role) => roles.indexOf(role) + 1;
  const sorcerer = id(Role.WolfSorcerer),
    magician = id(Role.Magician),
    psychic = id(Role.Psychic),
    witch = id(Role.Witch),
    hunter = id(Role.Hunter);
  const ordinary = ids.filter((i) => roles[i - 1] === Role.Wolf),
    wolves = [...ordinary, sorcerer].sort((a, b) => a - b),
    villagers = ids.filter((i) => roles[i - 1] === Role.Villager);
  const turns = new Map<number, PlannedTurn[]>(ids.map((i) => [i, []]));
  const add = (
    day: number,
    actors: number[],
    stage: ActionStage,
    action: ToolCall | null | ((actor: number) => ToolCall | null),
  ) => {
    for (const actor of actors)
      turns
        .get(actor)!
        .push({ day, stage, action: typeof action === "function" ? action(actor) : action });
  };
  const words = (day: number, actors: number[]) =>
    add(day, actors, "last_words", { name: "speak", args: { text: "Words" } });
  const pack = (day: number, actors: number[], target: number) => {
    add(day, actors, "wolf_discussion", {
      name: "speak_to_wolves",
      args: { text: "End", end_chat: true },
    });
    add(day, actors, "wolf_vote", {
      name: "kill_vote",
      args: { target_id: target, abstain: false },
    });
  };
  const dayVote = (day: number, alive: number[], target: number) => {
    add(day, alive, "day_speech", { name: "speak", args: { text: "Speech" } });
    add(
      day,
      wolves.filter((i) => alive.includes(i)),
      ActionWindow.OnPreVote,
      null,
    );
    add(day, alive, "voting", (actor) => ({
      name: "vote",
      args: { target_id: actor === target ? null : target, abstain: actor === target },
    }));
    words(day, [target]);
  };
  pack(1, ordinary, villagers[0]!);
  add(1, [witch], "witch", {
    name: "use_potion",
    args: { target_id: ordinary[0]!, potion_type: PotionType.Poison },
  });
  add(1, [psychic], "psychic", { name: "inspect_role", args: { target_id: sorcerer } });
  add(1, wolves, ActionWindow.OnPreElection, null);
  add(1, ids, "sheriff_nomination", { name: "run_for_sheriff", args: { run: false } });
  words(1, [villagers[0]!, ordinary[0]!]);
  const alive1 = ids.filter((i) => i !== villagers[0] && i !== ordinary[0]);
  dayVote(1, alive1, ordinary[1]!);
  add(2, [magician], "magician_exchange", {
    name: "swap_targets",
    args: { first_id: psychic, second_id: hunter, abstain: false },
  });
  const pair =
    variant === "cancel"
      ? [psychic, hunter]
      : variant === "disjoint"
        ? [ordinary[2]!, villagers[1]!]
        : [hunter, villagers[1]!];
  add(2, [sorcerer], "wolf_sorcerer_exchange", {
    name: "swap_night_seats",
    args: { first_id: pair[0]!, second_id: pair[1]!, abstain: false },
  });
  pack(
    2,
    [ordinary[2]!, sorcerer].sort((a, b) => a - b),
    variant === "cancel" ? hunter : psychic,
  );
  add(2, [witch], "witch", {
    name: "use_potion",
    args: { target_id: witch, potion_type: PotionType.None },
  });
  add(2, [psychic], "psychic", { name: "inspect_role", args: { target_id: hunter } });
  add(2, [hunter], "hunter_shot", {
    name: "shoot",
    args: { target_id: variant === "disjoint" ? villagers[1]! : ordinary[2]! },
  });
  const alive2 = alive1.filter((i) => i !== ordinary[1] && i !== hunter && i !== ordinary[2]);
  dayVote(2, alive2, sorcerer);
  for (const actor of wolves)
    for (const turn of turns.get(actor)!) {
      turn.currentTeammateIds =
        actor === sorcerer && turn.stage === "wolf_sorcerer_exchange"
          ? []
          : turn.day === 1
            ? actor === sorcerer
              ? []
              : ordinary.filter((i) => i !== actor)
            : wolves.filter((i) => i !== actor);
    }
  return {
    board: parseBoardDefinition(
      boardDefinitionFromConfig("wolf_sorcerer_transport_" + variant, config),
    ),
    seed,
    roles,
    turns,
    sorcerer,
    psychic,
    hunter,
    wolfTarget: ordinary[2]!,
    inspectionRole:
      variant === "cancel" ? Role.Hunter : variant === "disjoint" ? Role.Psychic : Role.Villager,
    alive: alive2.filter((i) => i !== sorcerer),
    winner: Camp.Good,
  };
}

