    getGuardState(guarded.world.getComponent(5, COMPONENT.Role)!)! as {
      lastTarget: number | null;
    }
  ).lastTarget = 2;
  expect(
    new ActionReception(guarded.world).validate(request(5, ["guard"], "guard"), "guard", {
      target_id: 2,
      abstain: false,
    }),
  ).toMatchObject({ ok: false, error: "guard_repeat" });
