    test(`${tool}/${style}: unknown or empty candidate list does not fall back to known alive players`, async () => {
      expect(await decide(tool, style)).toEqual({ name: tool, args: { target_id: null } });
      expect(await decide(tool, style, [])).toEqual({ name: tool, args: { target_id: null } });
    });

