  ],
  [
    "self heal",
    (c) => {
      c.witch!.canSelfHeal = WitchSelfHealRule.FirstNightOnly;
    },
  ],
  [
    "different victory",
    (c) => {
      c.winConditions = [WinCondition.SlaughterCity];
    },
  ],
  [
    "dream immunity",
    (c) => {
      c.dreamer!.protectionPolicy = "netease_2026_night_immunity_v1";
    },
  ],
  [
    "optional seer",
    (c) => {
      c.seer!.actionPolicy = "awa_optional_v1";
