type OriginalPlayerWall = OriginalWall & { effectiveRemaining: 0 | 1 };
type Equal<A, B> =
  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Expect<T extends true> = T;
export type PublicShapeChecks = [
  Expect<Equal<EclipseSwallowedRole, OriginalSwallowedRole>>,
  Expect<Equal<EclipseState, OriginalEclipse>>,
  Expect<Equal<WallNoteComponent, OriginalWall>>,
  Expect<Equal<WorldWallNote, OriginalWall>>,
  Expect<Equal<ReturnType<typeof projectEclipseState>, OriginalEclipse | undefined>>,
  Expect<Equal<ReturnType<typeof readWallNoteData>, OriginalWall | null>>,
  Expect<Equal<PlayerObservation["ownState"]["eclipse"], OriginalEclipse | undefined>>,
  Expect<Equal<PlayerObservation["ownState"]["wallNote"], OriginalPlayerWall | undefined>>,
  Expect<EclipseState extends OriginalEclipse ? true : false>,
  Expect<OriginalEclipse extends EclipseState ? true : false>,
  Expect<WallNoteComponent extends OriginalWall ? true : false>,
  Expect<OriginalWall extends WallNoteComponent ? true : false>,
];

/** 仅编译原 nested 可写／null／literal；不写实际原体或对局库存。 */
export function originalWritableData(
  eclipse: EclipseState,
  wall: WallNoteComponent,
  playerWall: OriginalPlayerWall,
): void {
  eclipse.history = [{ day: 2, targetId: null, roleId: null, abilityId: null }];
  eclipse.history.push({ day: 3, targetId: 4, roleId: "seer", abilityId: "copy:eclipse:night:3" });
  eclipse.history[0]!.targetId = 2;
  eclipse.history[0]!.roleId = "villager";
  eclipse.history[0]!.abilityId = null;
  wall.instanceId = "wall:1:2";
  wall.source = { kind: "wall_event", eventId: "awa_wall_notes_v1", day: 1 };
  wall.source.day = 1;
  wall.remaining = 0;
  wall.expired = true;
  playerWall.effectiveRemaining = 1;
  // @ts-expect-error 公开history无live ability payload或租约。
  eclipse.lease;
  // @ts-expect-error 有限角色联合不包括普通狼人。
  eclipse.history[0]!.roleId = "wolf";
  // @ts-expect-error 原source严格首日literal，不扩为任意日次。
  wall.source.day = 2;
  // @ts-expect-error 原库存类型是0或1。
  wall.remaining = 2;
  // @ts-expect-error 玩家有效余量仍有原字段与0或1边界。
  playerWall.effectiveRemaining = 2;
}

/**
 * 单元测试：验证 World 类型槽与原引用／生命所有权。输入为十一种组件名、原对象和死亡许可修订，字面顺序、对象身份及版本为预期；编译正反例检查统一槽推断与旧任意泛型拒绝，不更改角色规则、传输或序列化句柄。
 */
import { createAliveComponent, createCampComponent } from "../../../src/game/observation/component-presentation";
import { expect, test } from "bun:test";
import { COMPONENT, Camp, Phase, Role, World, aliveLifeVersion, createIdentityComponent, type AliveComponent, type CampComponent, type ComponentMap, type ComponentName, type RoleComponent } from "../../../src/core";
import { createRoleComponent } from "../../../src/game/observation/role-presentation";

function compilerExamples(world: World, actorId: number) {
  const alive = createAliveComponent(),
    camp = createCampComponent(Camp.Good),
    role = createRoleComponent(Role.Villager);
  world.addComponent(actorId, COMPONENT.Alive, alive);
  world.addComponent(actorId, COMPONENT.Camp, { ...camp, customExtra: { original: true } });
  world.addComponent(actorId, COMPONENT.Role, { ...role, customExtra: "unchanged width" });
  const inferred: AliveComponent | undefined = world.getComponent(actorId, COMPONENT.Alive);
  if (inferred) {
    const aliveFlag: boolean = inferred.alive;
    // @ts-expect-error Alive 槽不携带角色私有容器。
    inferred.privateState;
    void aliveFlag;
  }
  // @ts-expect-error 错误槽不能从值反向推断出任意组件类型。
  world.addComponent(actorId, COMPONENT.Alive, camp);
  // @ts-expect-error Camp 不能满足 Role 的完整组件结构。
  world.addComponent(actorId, COMPONENT.Role, camp);
  // @ts-expect-error Role 的独有字段不能装入 Camp 槽。
  world.addComponent(actorId, COMPONENT.Camp, role);
  // @ts-expect-error 缺少必需字段不能退回任意类型重载。
  world.addComponent(actorId, COMPONENT.Role, { role: Role.Wolf });
  // @ts-expect-error 接收变量的类型不能把 Alive 槽改成 Camp。
  const wrong: CampComponent | undefined = world.getComponent(actorId, COMPONENT.Alive);
  const unionName: typeof COMPONENT.Role | typeof COMPONENT.Camp =
    actorId > 1 ? COMPONENT.Role : COMPONENT.Camp;
  // @ts-expect-error 值推断不能把具名槽联合扩成 Alive 槽。
  world.addComponent(actorId, unionName, alive);
  // @ts-expect-error 实体 ID 仍是数字，任意实体参数不能进入槽。
  world.addComponent("actor", COMPONENT.Alive, alive);
  // @ts-expect-error 未知来源对象不能成为实体 ID。
  world.getComponent({ actorId }, COMPONENT.Role);
  // @ts-expect-error 机器槽名仍是闭合的十一种名称。
  world.getComponent(actorId, "ForeignComponent");
  // @ts-expect-error 旧调用方任意 RoleComponent 泛型不再能覆盖 Camp 槽。
  const legacy: RoleComponent | undefined = world.getComponent<RoleComponent>(
    actorId,
    COMPONENT.Camp,
  );
  // @ts-expect-error 旧单一任意组件泛型不能绕过具名槽写入约束。
  world.addComponent<RoleComponent>(actorId, COMPONENT.Camp, role);
  type SameKeys = keyof ComponentMap extends ComponentName
    ? ComponentName extends keyof ComponentMap
      ? true
      : false
    : false;
  const closedMap: SameKeys = true;
  void [wrong, legacy, closedMap];
}
void compilerExamples;

