/**
 * 单元测试验证真实毒接受分支与延期副本保留同一因果证据。
 * 输入为内存 World、字面原体、独立毒及盾；预期死因与目标由手写常量给出。
 * 验证保护抑制、同目标直接／反射区别、legacy Proxy 和原序列化形状，不运行整局或模型。
 */
import { createAliveComponent } from "../../../src/game/observation/component-presentation";
import { expect, test } from "bun:test";
import { World } from "../../../src/core/domain/world";
import { COMPONENT } from "../../../src/core/domain/components/names";

import { StatusMarksComponent } from "../../../src/core/domain/components/status_marks";
import { StatusMark, DeathCause } from "../../../src/core/domain/model";
import {
  captureNightLife, originalPoisonIntent, mechanicalNightIntent,
} from "../../../src/core/domain/night_effects";
import { damagePoisonRoutes } from "../../../src/core/domain/damage-evidence";
import { DamageResolutionSystem } from "../../../src/core/domain/systems/damage_resolution_system";
import { MistPendingNight } from "../../../src/game/mechanisms/roles/mist_raven/pending_night";
import { DreamNightFrame } from "../../../src/game/mechanisms/roles/dreamer/night_frame";

function fixture() {
  const world = new World();
  for (let i = 0; i < 3; i++) {
    const id = world.createEntity();
    world.addComponent(id, COMPONENT.Alive, createAliveComponent());
    world.addComponent(id, COMPONENT.StatusMarks, new StatusMarksComponent());
  }
  return { world, source: captureNightLife(world, 1)!, target: captureNightLife(world, 2)!, shieldOwner: captureNightLife(world, 3)! };
}
function poison(f: ReturnType<typeof fixture>, target = f.target) {
  return originalPoisonIntent({ source: f.source, target }, {
    family: "scholar-mentor", stage: "scholar_mentor_bonus", day: 2,
    actorLife: f.source, requestedTargetId: target.id, abilityId: "bonus:poison",
  });
}
function shield(f: ReturnType<typeof fixture>) {
  return mechanicalNightIntent("mechanical-shield", {
    actorId: f.shieldOwner.id, target: f.target, isCurrent: () => true,
  }, {
    family: "mechanical", stage: "mechanical_skill", day: 2,
    actorLife: f.shieldOwner, requestedTargetId: 2, abilityId: "learned:guard",
  });
}

test("two accepted poisons preserve independent causes and original result fields", () => {
  const f = fixture(), a = poison(f), b = poison(f);
  f.world.getComponent(2, COMPONENT.StatusMarks)!.add(StatusMark.PoisonMark);
  const result = new DamageResolutionSystem().resolve(f.world, { intentNight: 2, poisonClaims: [a, b] });
  expect(result.deaths).toEqual([2]);
  expect(result.deathSources).toEqual({ 2: [DeathCause.Poison] });
  const routes = damagePoisonRoutes(result);
  expect(routes.map(r => r.origin.causeId)).toEqual([a.origin.causeId, b.origin.causeId]);
  expect(a.origin.causeId).not.toBe(b.origin.causeId);
  expect(routes[0]!.target).toBe(f.target);
  expect(Object.isFrozen(routes)).toBe(true);
  expect(Object.keys(result)).toEqual(["deaths", "deathSources"]);
  expect(JSON.stringify(result)).toBe('{"deaths":[2],"deathSources":{"2":["poison"]}}');
});

test("dream protection does not turn a folded route into accepted lethal evidence", () => {
  const f = fixture();
  f.world.getComponent(2, COMPONENT.StatusMarks)!.add(StatusMark.PoisonMark);
  const result = new DamageResolutionSystem().resolve(f.world, {
    intentNight: 2, poisonClaims: [poison(f)], protectedTargets: [2],
  });
  expect(result.deaths).toEqual([]);
  expect(result.deathSources).toEqual({});
  expect(damagePoisonRoutes(result)).toEqual([]);
});

test("reflected poison reaches the caster without attributing an unmarked direct poison there", () => {
  const f = fixture(), reflected = poison(f), unmarkedDirect = poison(f, f.source);
  f.world.getComponent(2, COMPONENT.StatusMarks)!.add(StatusMark.PoisonMark);
  const result = new DamageResolutionSystem().resolve(f.world, {
    intentNight: 2, poisonClaims: [reflected, unmarkedDirect],
    mechanicalEffects: { shields: [shield(f)], attacks: [], failures: [] },
  });
  expect(result.deaths).toEqual([1]);
  expect(result.deathSources).toEqual({ 1: [DeathCause.Poison] });
  const routes = damagePoisonRoutes(result);
  expect(routes).toHaveLength(1);
  expect(routes[0]!.origin.causeId).toBe(reflected.origin.causeId);
  expect(routes[0]!.target).toBe(f.source);
  expect(routes[0]!.route).toBe("reflected");
});

test("delayed Mist copies carry the same accepted source without new enumerable fields", () => {
  const f = fixture(), claim = poison(f);
  f.world.getComponent(2, COMPONENT.StatusMarks)!.add(StatusMark.PoisonMark);
  const result = new DamageResolutionSystem().resolve(f.world, { intentNight: 2, poisonClaims: [claim] });
  const pending = new MistPendingNight(f.world, 2, 2, result, new DreamNightFrame([]));
  pending.claim(() => true);
  const final = pending.prepareFinalDamage(2, () => true);
  expect(final.deaths).toEqual([2]);
  expect(final.deathSources).toEqual({ 2: [DeathCause.Poison] });
  expect(final).not.toBe(result);
  expect(damagePoisonRoutes(final)[0]!.origin).toBe(claim.origin);
  expect(damagePoisonRoutes(final)[0]!.target).toBe(f.target);
  expect(Object.keys(final)).toEqual(["deaths", "deathSources"]);
});

test("old external result Proxy is not inspected for new metadata", () => {
  let reads = 0;
  const result = new Proxy({ deaths: [], deathSources: {} }, {
    get() { reads++; throw new Error("legacy_damage_getter_unused"); },
  });
  expect(damagePoisonRoutes(result)).toEqual([]);
  expect(reads).toBe(0);
});

/**
 * 单元测试用字面带来源死亡声明与已撤销权限验证查验伤害。精确独立死因、免疫与当前生命断言
 * 验证伤害结算，不重新解释普通守护／救药。输入及字面／不可变 fixture 预期保持原样，不运行模型或完整对局。
 */
import { createAliveComponent } from "../../../src/game/observation/component-presentation";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import { COMPONENT } from "../../../src/core/domain/components/names";
import { type AliveComponent } from "../../../src/core/domain/components/alive";
import type { RoleComponent } from "../../../src/core/domain/components/role";
import type { StatusMarksComponent } from "../../../src/core/domain/components/status_marks";
import { DeathCause } from "../../../src/core/domain/deaths";
import { Role, StatusMark } from "../../../src/core/domain/identity";
import {
  captureNightLife,
  type NightInspectionAttack,
} from "../../../src/core/domain/night_effects";
import { DamageResolutionSystem } from "../../../src/core/domain/systems/damage_resolution_system";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";

function fixture(cause: NightInspectionAttack["cause"]) {
  const { world } = bootstrapGame(sixPlayerMvpConfig);
  const actorId = world
    .entityIds()
    .find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Seer)!;
  const targetId = world
    .entityIds()
    .find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Wolf)!;
  const target = captureNightLife(world, targetId)!;
  let current = true;
  const attack: NightInspectionAttack = { actorId, target, cause, isCurrent: () => current };
  const marks = world.getComponent(targetId, COMPONENT.StatusMarks)!;
  return {
    world,
    actorId,
    targetId,
    attack,
    marks,
    revoke: () => {
      current = false;
    },
  };
}

const matrix = [
  { name: "no ordinary marks", marks: [], other: [] },
  { name: "guard", marks: [StatusMark.GuardMark], other: [] },
  { name: "heal", marks: [StatusMark.HealMark], other: [] },
  { name: "guard and heal", marks: [StatusMark.GuardMark, StatusMark.HealMark], other: [] },
  { name: "guarded knife", marks: [StatusMark.GuardMark, StatusMark.WolfKillMark], other: [] },
  { name: "healed knife", marks: [StatusMark.HealMark, StatusMark.WolfKillMark], other: [] },
  {
    name: "conflicting guard and heal with knife",
    marks: [StatusMark.GuardMark, StatusMark.HealMark, StatusMark.WolfKillMark],
    other: [DeathCause.WolfKill],
  },
  { name: "independent poison", marks: [StatusMark.PoisonMark], other: [DeathCause.Poison] },
] as const;

for (const cause of [DeathCause.PureWhiteInspection, DeathCause.WolfWitchInspection] as const) {
  for (const row of matrix) {
    test(`${cause}/${row.name}: sourced inspection ignores ordinary guard and heal, retaining independent causes`, () => {
      const f = fixture(cause);
      for (const mark of row.marks) f.marks.add(mark);
      const damage = new DamageResolutionSystem().resolve(f.world, {
        inspectionAttacks: [f.attack],
      });
      expect(damage.deaths).toEqual([f.targetId]);
      expect([...damage.deathSources[f.targetId]!].sort()).toEqual([cause, ...row.other].sort());
      expect(f.world.getComponent(f.targetId, COMPONENT.Alive)?.alive).toBe(true);
    });
  }
  test(`${cause}: revoked original authority cannot contribute a death`, () => {
    const f = fixture(cause);
    f.revoke();
    expect(
      new DamageResolutionSystem().resolve(f.world, { inspectionAttacks: [f.attack] }).deaths,
    ).toEqual([]);
  });
  test(`${cause}: a dead and revived target is not the captured life`, () => {
    const f = fixture(cause);
    const life = f.world.getComponent(f.targetId, COMPONENT.Alive)!;
    life.alive = false;
    life.alive = true;
    expect(
      new DamageResolutionSystem().resolve(f.world, { inspectionAttacks: [f.attack] }).deaths,
    ).toEqual([]);
  });
}

for (const cause of [DeathCause.PureWhiteInspection, DeathCause.WolfWitchInspection] as const) {
  test(`${cause}: replacing the target life revokes the original attack`, () => {
    const f = fixture(cause);
    const replacement = createAliveComponent();
    f.world.addComponent(f.targetId, COMPONENT.Alive, replacement);
    const damage = new DamageResolutionSystem().resolve(f.world, { inspectionAttacks: [f.attack] });
    expect(damage.deaths).toEqual([]);
    expect(damage.deathSources[f.targetId]).toBeUndefined();
    expect(replacement.alive).toBe(true);
  });
  test(`${cause}: inspection without a status component still stages a death`, () => {
    const f = fixture(cause);
    f.world.removeComponent(f.targetId, COMPONENT.StatusMarks);
    const damage = new DamageResolutionSystem().resolve(f.world, { inspectionAttacks: [f.attack] });
    expect(damage.deaths).toEqual([f.targetId]);
    expect([...damage.deathSources[f.targetId]!]).toEqual([cause]);
    expect(f.world.getComponent(f.targetId, COMPONENT.Alive)?.alive).toBe(true);
  });
}

test("both inspection sources are preserved once while marking no player dead prematurely", () => {
  const f = fixture(DeathCause.PureWhiteInspection);
  const other: NightInspectionAttack = { ...f.attack, cause: DeathCause.WolfWitchInspection };
  const damage = new DamageResolutionSystem().resolve(f.world, {
    inspectionAttacks: [f.attack, f.attack, other],
  });
  expect(damage.deaths).toEqual([f.targetId]);
  expect([...damage.deathSources[f.targetId]!].sort()).toEqual(
    [DeathCause.PureWhiteInspection, DeathCause.WolfWitchInspection].sort(),
  );
  expect(f.world.getComponent(f.targetId, COMPONENT.Alive)?.alive).toBe(true);
});

/**
 * 单元测试用字面毒素／反射声明与当前躯体验证机械伤害。精确原来源、合并死亡及单次处理断言
 * 验证非递归护盾结算。输入及字面／不可变 fixture 预期保持原样，不运行模型或完整对局。
 */
import { createAliveComponent } from "../../../src/game/observation/component-presentation";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import { Role, COMPONENT, StatusMark, DeathCause, type BoardConfig } from "../../../src/core";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";
import {
  captureNightLife,
  planMechanicalDamage,
  type NightMechanicalEffects,
  type NightPoisonClaim,
} from "../../../src/core/domain/night_effects";
import { StatusMarksComponent } from "../../../src/core/domain/components/status_marks";

import { DamageResolutionSystem } from "../../../src/core/domain/systems/damage_resolution_system";
import { permitsDeathShot } from "../../../src/core/domain/deaths";
const roles = [Role.Wolf, Role.Witch, Role.Seer, Role.Guard, Role.Villager, Role.Villager],
  config: BoardConfig = {
    ...sixPlayerMvpConfig,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
      count: roles.filter((r) => r === role).length,
    })),
  };
const fixture = () => bootstrapGame(config, { fixedRoles: roles }),
  scope = (game: ReturnType<typeof fixture>, id: number) => captureNightLife(game.world, id)!;
const effects = (): {
  shields: NightMechanicalEffects["shields"][number][];
  attacks: NightMechanicalEffects["attacks"][number][];
  failures: NightMechanicalEffects["failures"][number][];
} => ({ shields: [], attacks: [], failures: [] });
const marks = (game: ReturnType<typeof fixture>, id: number, ...values: StatusMark[]) => {
  const m = new StatusMarksComponent(values);
  game.world.addComponent(id, COMPONENT.StatusMarks, m);
};
test("every claimed toxin is reflected once to its original source, with one merged death per current body", () => {
  const game = fixture(),
    frame = effects();
  frame.shields.push({ actorId: 1, target: scope(game, 5), isCurrent: () => true });
  const claims: NightPoisonClaim[] = [
    { source: scope(game, 2), target: scope(game, 5) },
    { source: scope(game, 3), target: scope(game, 5) },
  ];
  marks(game, 5, StatusMark.PoisonMark);
  const plan = planMechanicalDamage(game.world, frame, claims);
  expect(plan.reflections).toEqual([
    { actorId: 1, protectedTargetId: 5, casterId: 2 },
    { actorId: 1, protectedTargetId: 5, casterId: 3 },
  ]);
  expect([...plan.reflectedPoisonTargets]).toEqual([2, 3]);
  expect(
    new DamageResolutionSystem().resolve(game.world, {
      mechanicalEffects: frame,
      poisonClaims: claims,
    }),
  ).toEqual({
    deaths: [2, 3],
    deathSources: { 2: [DeathCause.Poison], 3: [DeathCause.Poison] },
    poisonReflections: [
      { actorId: 1, protectedTargetId: 5, casterId: 2 },
      { actorId: 1, protectedTargetId: 5, casterId: 3 },
    ],
  });
  expect(game.world.getAliveEntityIds()).toEqual([1, 2, 3, 4, 5, 6]);
});
test("reflection is not recursively fed through another mechanical shield; self-poison obeys the same one-reflection rule", () => {
  for (const self of [false, true]) {
    const game = fixture(),
      frame = effects(),
      caster = self ? 5 : 2;
