        throw Error("should_not_reflect");
      },
      ownKeys() {
        trace.push("keys");
        throw Error("should_not_reflect");
      },
    },
  ) as GameEvent;
  expect(buildAgentVisibleEvent(world, accessor, 1, 1)).toBeNull();
  expect(buildAgentVisibleEvent(world, proxy, 1, 1)).toBeNull();
  expect(trace).toEqual([]);
  const event: GameEvent = {
