    expect(ctx.currentCamp()).toBe(ctx.initialCamp);
    expect(world.getComponent(1, COMPONENT.Camp)?.camp).toBe(Camp.Wolf);
    expect(world.getComponent(1, COMPONENT.Victory)?.affiliations).toEqual([
