import { bootstrapGame } from "../../../src/app/bootstrap";
import { COMPONENT } from "../../../src/core/domain/components/names";
import type { AliveComponent } from "../../../src/core/domain/components/alive";
import type { RoleComponent } from "../../../src/core/domain/components/role";
import { Camp, Role, WinCondition } from "../../../src/core/domain/identity";
import { ELIMINATION_PRIORITIES, type EliminationPriority } from "../../../src/core/domain/board";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";
import {
  createEliminationWinConditionSpecs,
  DEFAULT_WIN_CONDITION_SPECS,
} from "../../../src/game/mechanisms/win_conditions/default_specs";
import {
  WinConditionRegistry,
  getDefaultWinConditionRegistry,
} from "../../../src/game/mechanisms/registries/win_condition_registry";

const cases = [
  { name: "no goal", dead: [], side: [null, null], city: [null, null] },
  {
    name: "wolves eliminated",
    dead: [Role.Wolf],
    side: [Camp.Good, Camp.Good],
    city: [Camp.Good, Camp.Good],
  },
  {
    name: "gods eliminated",
    dead: [Role.Seer, Role.Witch],
    side: [Camp.Wolf, Camp.Wolf],
    city: [null, null],
  },
  {
    name: "villagers eliminated",
    dead: [Role.Villager],
    side: [Camp.Wolf, Camp.Wolf],
    city: [null, null],
  },
  {
    name: "last wolf and last god",
    dead: [Role.Wolf, Role.Seer, Role.Witch],
    side: [Camp.Good, Camp.Wolf],
    city: [Camp.Good, Camp.Good],
  },
  {
    name: "last wolf and last villager",
    dead: [Role.Wolf, Role.Villager],
    side: [Camp.Good, Camp.Wolf],
    city: [Camp.Good, Camp.Good],
  },
  {
    name: "all good eliminated",
    dead: [Role.Seer, Role.Witch, Role.Villager],
    side: [Camp.Wolf, Camp.Wolf],
    city: [Camp.Wolf, Camp.Wolf],
  },
  {
    name: "everyone eliminated",
    dead: [Role.Wolf, Role.Seer, Role.Witch, Role.Villager],
    side: [Camp.Good, Camp.Wolf],
    city: [Camp.Good, Camp.Wolf],
  },
] as const;

for (const locale of ["zh-CN", "en"] as const) {
  for (const scenario of cases) {
    for (const [index, priority] of ELIMINATION_PRIORITIES.entries()) {
      test(`${locale}/${priority}/${scenario.name}: explicit elimination priority has a handwritten result`, () => {
        const { world } = bootstrapGame(
          {
            ...sixPlayerMvpConfig,
            roleSetups: [
              { role: Role.Wolf, count: 2 },
              { role: Role.Villager, count: 2 },
              { role: Role.Seer, count: 1 },
              { role: Role.Witch, count: 1 },
            ],
          },
          { locale },
        );
        const members = new Map(
          world
            .entityIds()
            .map((id) => [id, world.getComponent(id, COMPONENT.Role)!]),
        );
        for (const [id, role] of members) {
          if ((scenario.dead as readonly Role[]).includes(role.role)) {
            world.getComponent(id, COMPONENT.Alive)!.alive = false;
          }
        }
        const registry = new WinConditionRegistry(createEliminationWinConditionSpecs(priority));
        for (const [condition, expected] of [
          [WinCondition.SlaughterSide, scenario.side[index]],
          [WinCondition.SlaughterCity, scenario.city[index]],
        ] as const) {
          const decision = registry.evaluate(world, condition);
          expect(decision?.winner ?? null).toBe(expected);
          if (expected === null) {
            expect(decision).toBeNull();
          } else {
            expect(decision?.outcome).toMatchObject({
              winningPlayerIds: [...members]
                .filter(([id]) => world.getComponent(id, COMPONENT.Camp)!.camp === expected)
                .map(([id]) => id)
                .sort((a, b) => a - b),
            });
          }
        }
        // A configured registry never changes the shared legacy default.
        expect(
          getDefaultWinConditionRegistry().evaluate(world, WinCondition.SlaughterSide)?.winner ??
            null,
        ).toBe(scenario.side[0]);
        expect(
          getDefaultWinConditionRegistry().evaluate(world, WinCondition.SlaughterCity)?.winner ??
            null,
        ).toBe(scenario.city[0]);
      });
    }
  }
}

test("priority creation rejects unknown values and preserves unrelated victory specifications", () => {
  expect(() => createEliminationWinConditionSpecs("wolf" as EliminationPriority)).toThrow(
    "elimination_priority_invalid",
  );
  for (const priority of ELIMINATION_PRIORITIES) {
    const configured = createEliminationWinConditionSpecs(priority);
    expect(configured.map((spec) => spec.id)).toEqual(
      DEFAULT_WIN_CONDITION_SPECS.map((spec) => spec.id),
    );
    for (const id of [WinCondition.ThreeFactionsElimination, WinCondition.WolfReachHalf]) {
      expect(configured.find((spec) => spec.id === id)).toBe(
        DEFAULT_WIN_CONDITION_SPECS.find((spec) => spec.id === id),
      );
    }
  }
});

/**
 * 单元测试：验证内存放逐、中毒及被枪击的角色 hook。输入为原事件与角色；生命、票权和枪的字面结果为预期，不推进完整对局。
 */
import { bootstrapGame } from "../../../src/app/bootstrap";
import { COMPONENT } from "../../../src/core/domain/components/names";
import { AliveComponent } from "../../../src/core/domain/components/alive";
import { RoleComponent } from "../../../src/core/domain/components/role";
import { Role, DeathCause, Phase } from "../../../src/core/domain/model";
import { EventRegistry } from "../../../src/game/engine/event_registry";
import { twelvePlayerStandardConfig } from "../../../src/runtime/scenarios/twelve_player_standard";

describe("EventRegistry hooks", () => {
  test("idiot voted out survives and loses voting right", () => {
    const { world } = bootstrapGame(twelvePlayerStandardConfig);
    const events = [] as any[];
    const eventRegistry = new EventRegistry();

    const idiotId = world
      .getAliveEntityIds()
      .find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Idiot);

    expect(idiotId).toBeDefined();

    const result = eventRegistry.onVotedOut(world, idiotId!, events);
    const alive = world.getComponent(idiotId!, COMPONENT.Alive)!;
    const voting = world.getComponent(idiotId!, COMPONENT.VotingRight)!;

    expect(result.prevented).toBe(true);
    expect(alive.alive).toBe(true);
    expect(voting.canVote).toBe(false);
    expect(voting.weight).toBe(0);
  });

  test("hunter poisoned cannot shoot", async () => {
    const { world } = bootstrapGame(twelvePlayerStandardConfig);
    const events = [] as any[];
    const eventRegistry = new EventRegistry();

    const hunterId = world
      .getAliveEntityIds()
      .find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Hunter)!;
    const targetId = world.getAliveEntityIds().find((id) => id !== hunterId)!;

    const hunterAlive = world.getComponent(hunterId, COMPONENT.Alive)!;
    hunterAlive.alive = false;

    const result = await eventRegistry.onDeath(
      world,
      [hunterId],
      { [hunterId]: [DeathCause.Poison] },
      async () => ({ kind: "invalid" as const }),
      events,
    );

    const targetAlive = world.getComponent(targetId, COMPONENT.Alive)!;

    expect(result.extraDeaths).toHaveLength(0);
    expect(targetAlive.alive).toBe(true);
  });

  test("hunter normal death returns a sourced proposal without owning Alive", async () => {
    const { world } = bootstrapGame(twelvePlayerStandardConfig);
    const events = [] as any[];
    const eventRegistry = new EventRegistry();

    const hunterId = world
      .getAliveEntityIds()
      .find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Hunter)!;
    const targetId = world.getAliveEntityIds().find((id) => id !== hunterId)!;

    const hunterAlive = world.getComponent(hunterId, COMPONENT.Alive)!;
    hunterAlive.alive = false;

    const permit = world.openDeathAction(hunterId, "shoot", Phase.Day, 1);
    const result = await eventRegistry.onDeath(
      world,
      [hunterId],
      { [hunterId]: [DeathCause.Exile] },
      async () => ({ kind: "shot" as const, targetId, deathActionId: permit.id }),
      events,
    );

    permit.close();
    const targetAlive = world.getComponent(targetId, COMPONENT.Alive)!;

    expect(result.extraDeaths).toContain(targetId);
    expect(targetAlive.alive).toBe(true);
  });
});

/**
 * Unit tests: Event snapshot authority uses mutable/replaced payloads and detached facts;
 * literal single-source projection assertions check that visibility never rereads foreign
 * payload state. Inputs and expected outcomes remain the original literal or
 * immutable-fixture oracle; these module assertions invoke no model or complete-game
 * driver.
 */
import { test, expect } from "bun:test";
import { World, type GameEvent } from "../../../src/core";
import { buildAgentVisibleEvent } from "../../../src/game/engine/agent_visible_event_feed";
const canary = "PRIVATE_OTHER_PLAYER_STATE_CANARY";
const cases: Array<[string, Record<string, unknown>, number, number[], Record<string, unknown>?]> =
  [
    ["modifier_choice_committed", { actorId: 1, day: 2, mode: "enhance", targetId: 2 }, 2, [1]],
    ["modifier_choice_skipped", { actorId: 1, day: 1, reason: "first_night" }, 2, [1]],
    [
      "modifier_bonus_resolved",
      { actorId: 1, day: 2, kind: "kill", targetId: 2, abstain: false },
      2,
      [1],
    ],
    ["time_consort_lock_committed", { actorId: 1, day: 1, targetId: 2 }, 2, [1]],
    ["time_consort_lock_skipped", { actorId: 1, day: 2, reason: "exhausted" }, 2, [1]],
    ["wolf_sorcerer_exchange_committed", { actorId: 1, day: 2, pair: [2, 3] }, 4, [1]],
    ["wolf_sorcerer_exchange_skipped", { actorId: 1, day: 1, reason: "not_started" }, 4, [1]],
    ["trickster_exchange_committed", { actorId: 1, day: 1, pair: [2, 3] }, 4, [1]],
    ["trickster_exchange_skipped", { actorId: 1, day: 2, reason: "exhausted" }, 4, [1]],
    ["order_prince_choice_committed", { actorId: 1, day: 1, activate: true }, 4, [1]],
    ["order_prince_revote_started", { actorId: 1 }, 2, []],
    ["exile_target_mapped", { requestedId: 2, effectiveId: 3, missed: false }, 4, []],
    ["death_shot_missed", { actorId: 1, reason: "no_effect" }, 4, []],
    ["cupid_lovers_chosen", { actorId: 1, day: 1, pairIds: [2, 3] }, 2, []],
    ["lover_recognized", { actorId: 1, partnerId: 2 }, 2, []],
    ["debate_started", { actorId: 1, targetId: 2, day: 1 }, 2, []],
    ["nightmare_fear_committed", { actorId: 1, day: 1, targetId: 2 }, 4, [1], { targetId: canary }],
  ];
for (const [type, base, swapAt, audience, lateFields] of cases)
  test("detached fact must be the only source of " + type, () => {
    const event: any = {
      timestamp: 1,
      type,
      payload: null,
      ...(audience.length ? { audience } : {}),
    };
    let calls = 0;
    event.payload = new Proxy(
      { ...base },
      {
        ownKeys(target) {
          calls++;
          if (calls === swapAt)
            event.payload = { ...base, ...(lateFields ?? { privateCanary: canary }) };
          return Reflect.ownKeys(target);
        },
      },
    );
    const result = buildAgentVisibleEvent(new World(), event as GameEvent, 1, 1);
    expect(calls).toBe(0);
    expect(result).toBeNull();
    expect(JSON.stringify(result)).not.toContain(canary);
  });
test("current Mist detached fact branch does not reread the replaced payload", () => {
  const base = { actorId: 1, day: 1, targetIds: [1, 2, 3] },
    event: any = { timestamp: 1, type: "alchemist_mist_chosen", audience: [1], payload: null };
  let calls = 0;
  event.payload = new Proxy(
    { ...base },
    {
      ownKeys(target) {
        if (++calls === 2) event.payload = { ...base, privateCanary: canary };
        return Reflect.ownKeys(target);
      },
    },
  );
  const result = buildAgentVisibleEvent(new World(), event, 1, 1);
  expect(calls).toBe(0);
  expect(result).toBeNull();
  expect(JSON.stringify(result)).not.toContain(canary);
});

