  expect(projected.state.history).toEqual([{ day: 1, targetId: 5 }]);
  expect(projected.state.history).not.toBe(ability.state.history);
  expect(reads).toBe(0);
  expect(projectNightAbility(ability, 2).kind).toBe("dream");
