  const log = new Proxy([], {
    get() {
      traps++;
      throw Error("getter");
    },
    getPrototypeOf() {
      traps++;
      throw Error("proto");
    },
    defineProperty() {
      traps++;
      throw Error("define");
    },
    isExtensible() {
      traps++;
      throw Error("extensible");
    },
  });
  expect(() => appendAnimalFact(world, log, "animal_fox_chosen", foxPayload)).toThrow(
    "animal_fact_log_invalid",
  );
  expect(traps).toBe(0);
