type Family = "cupid" | "hybrid";
function fixture(family: Family) {
  const roles = family === "cupid"
    ? [Role.Cupid, Role.Hunter, Role.Wolf, Role.Villager, Role.Wolf, Role.Villager]
    : [Role.Hybrid, Role.Wolf, Role.HiddenWolf, Role.Seer, Role.Witch, Role.Villager];
  const config = { ...sixPlayerMvpConfig, boardSize: 6,
    roleSetups: [...new Set(roles)].map(role => ({ role, count: roles.filter(value => value === role).length })),
    winConditions: [WinCondition.SlaughterCity], enableSheriff: false, selfDestruct: { enabledWindows: [] },
    ...(family === "cupid" ? { cupid: { policy: "netease_2017_cupid_follows_lovers_v1" as const } } : {}),
  };
  const game = bootstrapGame(config, { fixedRoles: roles });
  const events: GameEvent[] = [], notifications: boolean[] = [], requests: ActionRequest[] = [];
  const actor = game.world.getComponent(1, COMPONENT.Role)!;
  const state = family === "cupid" ? getCupidState(actor)! : getHybridState(actor)!;
  const originalVictory = game.world.getComponent(1, COMPONENT.Victory)!;
  const factory = new GameActionRequestFactory(game.world, events, 1);
  const action: ToolCall = family === "cupid"
    ? { name: "choose_lovers", args: { first_id: 1, second_id: 3 } }
    : { name: "choose_exemplar", args: { target_id: 2 } };
  let current = true;
  const context = (provider: (request: ActionRequest) => Promise<ToolCall | null>, notify?: (accepted: boolean) => void) =>
    nightStageContext({ world: game.world, events, isCurrent: () => current,
      getAliveByRole: value => game.world.getAliveEntityIds().filter(id => game.world.getComponent(id, COMPONENT.Role)!.role === value),
      makeRequest: (actorId, allowedTools, extra) => factory.create({ actorId, allowedTools, phase: Phase.Night,
        stage: extra.stage, requiresAction: extra.requiresAction ?? true, summary: "Offline", context: extra }),
      actionProvider: { getAction: async request => {
        requests.push(request);
        expect(deferRequestDelivery(request, accepted => { notifications.push(accepted); notify?.(accepted); })).toBe(true);
        return provider(request);
      } },
    });
  return { family, game, events, state, originalVictory, notifications, requests, action, context,
    invalidate() { current = false; }, restore() { current = true; },
    execute(ctx: ReturnType<typeof context>) { return (family === "cupid" ? CUPID_STAGE : HYBRID_STAGE).execute(ctx); },
  };
}
function expectUnpaid(f: ReturnType<typeof fixture>) {
  expect(f.state.remaining).toBe(1);
  expect(f.state.choice).toBeNull();
  expect(f.game.world.getComponent(1, COMPONENT.Victory)).toBe(f.originalVictory);
  expect(loversRecord(f.game.world)).toBeNull();
  expect(f.events).toEqual([]);
}
function expectPaid(f: ReturnType<typeof fixture>) {
  expect(f.state.remaining).toBe(0);
  expect(f.state.choice).toEqual(f.family === "cupid" ? { day: 1, pairIds: [1, 3] } : { day: 1, targetId: 2 });
  expect(f.game.world.getComponent(1, COMPONENT.Victory)!.affiliations).toEqual(f.family === "cupid"
    ? [{ kind: "relationship", groupId: "cupid_lovers" }] : [{ kind: "faction", faction: Camp.Wolf }]);
  expect(f.family === "cupid" ? loversRecord(f.game.world)?.pairIds : hasHybridNightCommit(f.game.world, 1))
    .toEqual(f.family === "cupid" ? [1, 3] : true);
}

