async function run(
  g: Fixture,
  events: GameEvent[],
  getAction: (request: ActionRequest) => Promise<ToolCall | null>,
  isCurrent = () => true,
  day = 1,
) {
  return new DebaterWindow(g.world, new ToolGateway(), events).execute(
