  actorId = 1,
  tool = "choose_bridegroom",
  stage = "ghost_bride_groom",
  day = 1,
): WeddingRequest {
  return {
    actorId,
    phase: Phase.Night,
    allowedTools: [tool],
    context: {
      day,
      stage,
      allow_fallback: false,
      action_failure_policy: "error",
      turn_constraints: { min_valid_actions: 1, max_valid_actions: 1, required_any_tools: [tool] },
    },
  } as WeddingRequest;
}
function openWeddingTurn(
  world: World,
  kind: "bridegroom" | "chat" | "witness" | "knife",
  actorId: number,
  day: number,
  current: () => boolean,
): object {
  const scope = openRawWeddingTurn(world, kind, actorId, day, current),
    ordinary = kind === "knife" && weddingNightCapture(world, day)?.owner === "ordinary_pack",
    tool =
      kind === "bridegroom"
        ? "choose_bridegroom"
        : kind === "chat"
          ? "speak_to_partner"
          : kind === "witness"
            ? "choose_wedding_witness"
            : ordinary
              ? "kill_vote"
              : "wedding_kill_vote",
    stage =
      kind === "bridegroom"
        ? "ghost_bride_groom"
        : kind === "chat"
          ? "ghost_bride_chat"
          : kind === "witness"
            ? "ghost_bride_witness"
            : ordinary
              ? "wolf_vote"
              : "ghost_bride_knife";
  bindGhostBrideRequest(world, request(actorId, tool, stage, day));
  return scope;
}
