      { ...good, targetId: 0 },
      { ...good, targetId: 1.5 },
      { ...good, exileDay: 0 },
      { ...good, receivedDay: 3 },
      { ...good, receivedDay: Infinity },
      { ...good, role: "wolf_king" },
      accessor,
    ];
    for (const item of bad) {
