  const descriptor = Object.getOwnPropertyDescriptor(JSON, "stringify")!, stringify = JSON.stringify;
  const failure = new Error("literal_magician_identity_encoding_failure");
  let calls = 0;
  Object.defineProperty(JSON, "stringify", {
