  if (state.learned?.skill.kind !== "wolf") throw new Error("wrong fixture");
  state.learned.skill.extraKnife = "spent";
  expect(canMechanicalExtraKnife(state, 3)).toBe(false);
  advanceMechanicalNight(state, 4);
