  }) as typeof JSON.stringify;
  try {
    authority(p);
  } catch (error) {
    observed = error;
  } finally {
    JSON.stringify = stringify;
  }
  expect(observed).toBe(failure);
  expect((p.role.privateState as Record<string, unknown>).alchemist).toBe(p.raw);
  expect(authority(p).state()).toMatchObject({
