test("无原候选或未关闭的夜不读取事件方法、不消费延期", () => {
  const fixture = redMoonCandidateWorld(), trace: string[] = [];
  const events: GameEvent[] = [];
  Object.defineProperty(events, "push", {
    get(): never { trace.push("push"); throw new Error("literal_event_must_not_read"); },
  });
  expect(redMoonVotedOutHook(fixture.world, 5, events)).toBeNull();
  expect(redMoonVotedOutHook(fixture.world, 4, events)).toBeNull();
  beginDemonHunterNight(fixture.world, 1, () => true);
  freezeDemonHunt(fixture.world);
  expect(redMoonVotedOutHook(fixture.world, 4, events)).toBeNull();
  expect(trace).toEqual([]);
  expect(getRedMoonState(fixture.world.getComponent(4, COMPONENT.Role), () => fixture.world.getComponent(4, COMPONENT.Camp))!.exileDay).toBeNull();
  expect(fixture.world.getComponent(4, COMPONENT.Alive)!.alive).toBe(true);
});

test("延期提交后push查找失败保留审计与生命，重试不再次发布", () => {
  const fixture = closedLastWolf(), events: GameEvent[] = [], trace: string[] = [];
  const failure = new Error("literal_red_moon_push_lookup_failed");
  Object.defineProperty(events, "push", {
    get(): never { trace.push("push"); throw failure; },
  });
  expect(() => redMoonVotedOutHook(fixture.world, 4, events)).toThrow(failure);
  expect(getRedMoonState(fixture.world.getComponent(4, COMPONENT.Role), () => fixture.world.getComponent(4, COMPONENT.Camp))!.exileDay).toBe(1);
  expect(fixture.world.getComponent(4, COMPONENT.Alive)!.alive).toBe(true);
  // 检查完整原生审计仍接受已提交库存，不仅读某个公开字段；调用不发布事实。
  expect(demonHunterCheckpointPlayers(fixture.world, true)).toHaveLength(12);
  expect(redMoonVotedOutHook(fixture.world, 4, events)).toBeNull();
  expect(trace).toEqual(["push"]);
  expect(events).toHaveLength(0);
});

test("先取push再读时钟，时钟失败不调用已取方法且不退款", () => {
  const fixture = closedLastWolf(), events: GameEvent[] = [], trace: string[] = [];
  const failure = new Error("literal_red_moon_clock_failed");
  const descriptor = Object.getOwnPropertyDescriptor(Date, "now")!;
  Object.defineProperty(events, "push", {
    get() {
      trace.push("push_lookup");
      return function (this: GameEvent[], ..._events: GameEvent[]): number {
        trace.push("push_call");
        return this.length;
      };
    },
  });
  try {
    // 只在真实提交之后的事件表达式读取时钟；finally恢复全局描述符，不改变其它测试的时钟。
    Object.defineProperty(Date, "now", {
      configurable: true,
      get() {
        trace.push("clock_lookup");
        return function (): never { trace.push("clock_call"); throw failure; };
      },
    });
    expect(() => redMoonVotedOutHook(fixture.world, 4, events)).toThrow(failure);
  } finally {
    Object.defineProperty(Date, "now", descriptor);
  }
  expect(trace).toEqual(["push_lookup", "clock_lookup", "clock_call"]);
  expect(getRedMoonState(fixture.world.getComponent(4, COMPONENT.Role), () => fixture.world.getComponent(4, COMPONENT.Camp))!.exileDay).toBe(1);
  expect(fixture.world.getComponent(4, COMPONENT.Alive)!.alive).toBe(true);
  expect(demonHunterCheckpointPlayers(fixture.world, true)).toHaveLength(12);
  expect(events).toHaveLength(0);
});

/**
 * 单元测试负责验证赤月使徒独立基础契约：使用原内存 owner／frame／reader、回调控制及明确畸形修改。手写预期、身份快照和拒绝断言不变，不推进装配后的完整日夜或使用模型／实体传输。
 */
import { describe, expect, test } from "bun:test";
import { Camp } from "../../../../src/core/domain/identity";
import type { RoleComponent } from "../../../../src/core/domain/components/role";
import {
  freshRedMoonState,
  getRedMoonState,
  RED_MOON_ROLE,
} from "../../../../src/game/mechanisms/roles/red_moon_apostle/state-slot";
import { readRedMoonNextNightFact, readRedMoonExpiryFact, RED_MOON_BLAST_EVENT, RED_MOON_EXILE_EVENT, RED_MOON_EXPIRY_EVENT } from "@ai-werewolf-arena/game-contract/facts/red-moon";
// 测试自持当前 Camp，不经旧 Role 属性或隐藏映射提供阵营。
const fixtureCamp = { camp: Camp.Wolf };
const currentCamp = () => fixtureCamp;
function role(state: unknown = freshRedMoonState()): RoleComponent {
  return {
    role: RED_MOON_ROLE,
    privateState: { redMoon: state },
  } as unknown as RoleComponent;
}
describe("Red Moon finite state", () => {
  test("defaults and both named last-wolf policies are readable", () => {
    for (const policy of ["ends_game", "forbidden"] as const) {
      const state = freshRedMoonState(policy);
      expect(getRedMoonState(role(state), currentCamp)).toBe(state);
    }
  });
  test("blast and exile states are separate, expiry requires exile", () => {
    for (const changes of [
      { blastDay: 2 },
      { exileDay: 2 },
      { exileDay: 2, expirySettled: true },
    ]) {
      const state = { ...freshRedMoonState(), ...changes };
      expect(getRedMoonState(role(state), currentCamp)).toBe(state);
    }
    expect(
      getRedMoonState(role({ ...freshRedMoonState(), blastDay: 2, exileDay: 2 }), currentCamp),
    ).toBeUndefined();
    expect(getRedMoonState(role({ ...freshRedMoonState(), expirySettled: true }), currentCamp)).toBeUndefined();
  });
  test("malformed states and wrong authority fail closed", () => {
    for (const field of [
      { policy: "other" },
      { lastWolfBlastPolicy: "other" },
      { blastDay: 0 },
      { blastDay: -1 },
      { blastDay: 1.5 },
      { blastDay: Number.MAX_SAFE_INTEGER },
      { exileDay: NaN },
      { expirySettled: 1 },
      { extra: true },
    ])
      expect(getRedMoonState(role({ ...freshRedMoonState(), ...field }), currentCamp)).toBeUndefined();
    expect(getRedMoonState(role(), () => ({ camp: Camp.Good }))).toBeUndefined();
  });
  test("accessors and proxies are never evaluated", () => {
    let reads = 0;
    const state = freshRedMoonState();
    Object.defineProperty(state, "blastDay", {
      get() {
        reads++;
        throw new Error("getter");
      },
      enumerable: true,
    });
    expect(getRedMoonState(role(state), currentCamp)).toBeUndefined();
    expect(
      getRedMoonState(
        new Proxy(role(), {
          get() {
            reads++;
            throw new Error("proxy");
          },
        }), currentCamp
      ),
    ).toBeUndefined();
    const revoked = Proxy.revocable(freshRedMoonState(), {});
    revoked.revoke();
    expect(getRedMoonState(role(revoked.proxy), currentCamp)).toBeUndefined();
    expect(reads).toBe(0);
  });
});
describe("Red Moon public facts", () => {
  test("next-night facts are detached and require exact adjacent days", () => {
    for (const type of [RED_MOON_BLAST_EVENT, RED_MOON_EXILE_EVENT]) {
      const fact = { actorId: 7, day: 2, night: 3 };
      const read = readRedMoonNextNightFact(type, fact);
      expect(read).toEqual(fact);
      expect(read).not.toBe(fact);
      for (const patch of [
        { night: 2 },
        { night: 4 },
        { day: 0 },
        { actorId: 0 },
        { secret: true },
      ]) {
        expect(readRedMoonNextNightFact(type, { ...fact, ...patch })).toBeNull();
      }
    }
  });
  test("expiry fact cannot carry extra private state or use other event types", () => {
    expect(readRedMoonExpiryFact(RED_MOON_EXPIRY_EVENT, { actorId: 7, day: 3 })).toEqual({
      actorId: 7,
      day: 3,
    });
    expect(
      readRedMoonExpiryFact(RED_MOON_EXPIRY_EVENT, { actorId: 7, day: 3, camp: "wolf" }),
    ).toBeNull();
    expect(readRedMoonExpiryFact(RED_MOON_BLAST_EVENT, { actorId: 7, day: 3 })).toBeNull();
    expect(
      readRedMoonNextNightFact(RED_MOON_EXPIRY_EVENT, { actorId: 7, day: 2, night: 3 }),
    ).toBeNull();
  });
});

test("Red Moon fact readers reject accessors without invoking getters", () => {
  let reads = 0;
  const next = { actorId: 7, day: 2, night: 3 };
  Object.defineProperty(next, "night", {
    enumerable: true,
    get() {
      reads++;
      throw new Error("getter");
    },
  });
  expect(readRedMoonNextNightFact(RED_MOON_BLAST_EVENT, next)).toBeNull();
  const expiry = { actorId: 7, day: 3 };
  Object.defineProperty(expiry, "day", {
    enumerable: true,
    get() {
      reads++;
      throw new Error("getter");
    },
  });
  expect(readRedMoonExpiryFact(RED_MOON_EXPIRY_EVENT, expiry)).toBeNull();
  expect(reads).toBe(0);
});

