/**
 * 单元测试负责白昼学者／寂夜导师新槽边界的原左值读取、原引用撤销及写入失败前缀。
 * 输入是测试自有原状态、明确 setter／JSON 失败；输出按手写字面顺序、对象身份与库存／历史预期断言。
 * 测试直接调用内部槽写方法以定位 prefix，不将其视为 board、角色、生命或夜许可，也不运行模型／完整对局。
 */
import { expect, test } from "bun:test";
import {
