  });
  await expect(resolveNativeDeathShots(revoked.world, [revoked.actor], { [revoked.actor]: [DeathCause.Shot] },
    async () => { errorTrace.push("choose"); retireRoleExecution(revoked.role); return { kind: "pass", deathActionId: 0 }; },
