/** 真实 setup 使用已绑定的 canonical 配置；榜样首死保原 Alive 对象／版本，不伪造生命周期绑定。 */
async function prepared() {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter];
  const game = bootstrapGame(foxBoard(roles), { fixedRoles: roles });
  const events: GameEvent[] = [];
  const result = await new WildChildSetupWindow(game.world, new ToolGateway(), events, {
    get requestFactory() { return GameActionRequestFactory; },
  }).execute(game.boardConfig, {
    async getAction() { return { name: "choose_wild_model", args: { target_id: 2 } }; },
  }, 1, () => true);
  if (!result) throw new Error("literal_wild_setup_expected_success");
  const binding = wildChildBinding(game.world)!;
  recordWildChildDeathCommit(game.world, 2);
  game.world.getComponent(2, COMPONENT.Alive)!.alive = false;
  return { ...game, events, binding };
}

const contribute = (g: Awaited<ReturnType<typeof prepared>>) =>
  resolveWildChildDeathWave(g.world, [2], { 2: [DeathCause.Poison] }, 1, Phase.Night, g.events);

test("Camp installation failure keeps its prefix and restoring duplicate fields cannot revive the Wild owner", async () => {
  const g = await prepared(), b = g.binding;
  const role = b.actor.role, camp = b.camp, victory = b.victory;
  const state = structuredClone(b.state), expected = b.expectedState;
  const error = new Error("literal_wild_camp_install_failure"), writes: string[] = [];
  const original = g.world.addComponent;
  // 仅测试实例拦截原安装点；正常调用保原 receiver，不新增生产 hook 或补偿。
  g.world.addComponent = new Proxy(original, {
    apply(target, receiver, args) {
      if (args[0] === 1 && args[1] === COMPONENT.Camp) {
        writes.push("Camp:throw");
        throw error;
      }
      return Reflect.apply(target, receiver, args);
    },
  });
  let caught: unknown;
  try { contribute(g); } catch (e) { caught = e; } finally { g.world.addComponent = original; }
  expect(caught).toBe(error);
  expect(writes).toEqual(["Camp:throw"]);
  expect(g.world.getComponent(1, COMPONENT.Role)).toBe(role);
  // 原Camp安装未执行即抛，单一实际阵营仍是旧Good，已退休Role不因读数一致恢复。
  expect(camp.camp).toBe(Camp.Good);
  expect(g.world.getComponent(1, COMPONENT.Camp)).toBe(camp);
  expect(camp.camp).toBe(Camp.Good);
  expect(g.world.getComponent(1, COMPONENT.Victory)).toBe(victory);
  expect(b.state).toEqual(state);
  expect(b.expectedState).toBe(expected);
  expect(b.modelCommitted).toBe(true);
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated"]);
  expect(validWildChildOwner(b)).toBe(false);
  camp.camp = Camp.Wolf;
  camp.camp = Camp.Good;
  expect(validWildChildOwner(b)).toBe(false);
  expect(projectWildChild(g.world, role)?.status).toBe("closed");
  expect(wildChildPackKnown(role, g.world)).toBe(false);
  expect(wildChildPackActive(role, g.world)).toBe(false);
  contribute(g);
  const close = openWildChildNight(g.world, 2, g.events);
  close();
  expect(b.state).toEqual(state);
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated"]);
});

test("Victory installation failure keeps installed Wolf Camp while retiring only the Wild transformation owner", async () => {
  const g = await prepared(), b = g.binding;
  const camp = b.camp, victory = b.victory, state = structuredClone(b.state);
  const error = new Error("literal_wild_victory_install_failure"), writes: string[] = [];
  const original = g.world.addComponent;
  g.world.addComponent = new Proxy(original, {
    apply(target, receiver, args) {
      if (args[0] === 1 && args[1] === COMPONENT.Camp) writes.push("Camp:installed");
      if (args[0] === 1 && args[1] === COMPONENT.Victory) {
        writes.push("Victory:throw");
        throw error;
      }
      return Reflect.apply(target, receiver, args);
    },
  });
  let caught: unknown;
  try { contribute(g); } catch (e) { caught = e; } finally { g.world.addComponent = original; }
  expect(caught).toBe(error);
  expect(writes).toEqual(["Camp:installed", "Victory:throw"]);
  expect(g.world.getComponent(1, COMPONENT.Camp)).not.toBe(camp);
  expect(g.world.getComponent(1, COMPONENT.Camp)?.camp).toBe(Camp.Wolf);
  expect(g.world.getComponent(1, COMPONENT.Victory)).toBe(victory);
  expect(victory.affiliations).toEqual([{ kind: "faction", faction: Camp.Good }]);
  expect(g.world.getComponent(1, COMPONENT.Camp)!.camp).toBe(Camp.Wolf);
  expect(b.actor.camp).toBe(Camp.Good);
  expect(b.camp).toBe(camp);
  expect(b.state).toEqual(state);
  expect(validWildChildOwner(b)).toBe(false);
  // 恢复原组件和重复值仍不解锁失败标记；同值新引用的旧撤权规则没有在此改写。
  g.world.addComponent(1, COMPONENT.Camp, camp);
  g.world.getComponent(1, COMPONENT.Camp)!.camp = Camp.Wolf;
  g.world.getComponent(1, COMPONENT.Camp)!.camp = Camp.Good;
  expect(validWildChildOwner(b)).toBe(false);
  expect(projectWildChild(g.world, b.actor.role)?.status).toBe("closed");
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated"]);
});

test("transformed fact publication failure preserves a fully committed owner and following-night pack activation", async () => {
  const g = await prepared(), b = g.binding;
  const error = new Error("literal_wild_transformed_fact_failure");
  const original = g.events.push;
  g.events.push = new Proxy(original, {
    apply(target, receiver, args) {
      if (args.some((event: GameEvent) => event.type === "wild_child_transformed")) throw error;
      return Reflect.apply(target, receiver, args);
    },
  });
  let caught: unknown;
  try { contribute(g); } catch (e) { caught = e; } finally { g.events.push = original; }
  expect(caught).toBe(error);
  expect(g.world.getComponent(1, COMPONENT.Camp)?.camp).toBe(Camp.Wolf);
  expect(g.world.getComponent(1, COMPONENT.Victory)?.affiliations).toEqual([{ kind: "faction", faction: Camp.Wolf }]);
  expect(b.state.status).toBe("transformed");
  expect(b.state.eligibleNight).toBe(2);
  expect(b.expectedState).toBe(JSON.stringify(b.state));
  expect(validWildChildOwner(b)).toBe(true);
  expect(projectWildChild(g.world, b.actor.role)?.status).toBe("transformed");
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated"]);
  contribute(g);
  const close = openWildChildNight(g.world, 2, g.events);
  close();
  expect(b.state.status).toBe("active");
  expect(wildChildPackKnown(b.actor.role, g.world)).toBe(true);
  expect(wildChildPackActive(b.actor.role, g.world)).toBe(true);
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated", "wild_child_pack_activated"]);
});

test("a frozen public binding does not replace the original Camp error while private failure revocation remains permanent", async () => {
  const g = await prepared(), b = g.binding;
  const camp = b.camp, error = new Error("literal_frozen_binding_camp_failure");
  expect(validWildChildOwner(b)).toBe(true);
  const original = g.world.addComponent;
  g.world.addComponent = new Proxy(original, {
    apply(target, receiver, args) {
      if (args[0] === 1 && args[1] === COMPONENT.Camp) {
        // 原 modelCommitted 已写；在实际安装调用内冻结绑定，再抛本例同一错误。
        Object.freeze(b);
        throw error;
      }
      return Reflect.apply(target, receiver, args);
    },
  });
  let caught: unknown;
  try { contribute(g); } catch (e) { caught = e; } finally { g.world.addComponent = original; }
  expect(caught).toBe(error);
  expect(Object.isFrozen(b)).toBe(true);
  expect(g.world.getComponent(1, COMPONENT.Camp)).toBe(camp);
  // 此注入同样在原Camp写入之前抛；冻结binding不改变actual旧Good或原错误。
  expect(g.world.getComponent(1, COMPONENT.Camp)!.camp).toBe(Camp.Good);
  expect(validWildChildOwner(b)).toBe(false);
  g.world.getComponent(1, COMPONENT.Camp)!.camp = Camp.Wolf;
  g.world.getComponent(1, COMPONENT.Camp)!.camp = Camp.Good;
  expect(validWildChildOwner(b)).toBe(false);
  expect(projectWildChild(g.world, b.actor.role)?.status).toBe("closed");
});

/**
 * 单元测试验证女巫原生狼刀披露、双药政策、外来库存隔离与终结后的第二次行动关闭。
 * 输入保留原狼刀／库存／顺序／撤销／语言矩阵，只调用有界原生阶段 helper；手写请求、
 * 药瓶／使用计数和配置提示／DTO 边界是预期，不运行完整 NightPipeline 或 recorder。
 */
import { captureNativeRolePresentation } from "../../../../src/game/observation/native-role-presentation-capture";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import {
  COMPONENT,
  Phase,
  Role,
  PotionType,
  StatusMark,
  type BoardConfig,
  type ActionRequest,
  type GameEvent,
  type RoleComponent,
  type ToolCall,
  type StatusMarksComponent,
} from "../../../../src/core";
import { GameActionRequestFactory } from "../../../../src/game/engine/action_request_factory";
import { WITCH_NIGHT_STAGES } from "../../../../src/game/mechanisms/roles/witch/night_stages";
import { WITCH_ROLE_PROFILE } from "../../../../src/game/mechanisms/roles/witch/profile";
import {
  abilityStatus,
  findNightAbility,
} from "../../../../src/game/mechanisms/roles/abilities";
import { projectNightAbility } from "../../../../src/game/observation/night-ability-projection";
import { getDefaultConfigRenderRegistry } from "../../../../src/game/mechanisms/prompt/config_render_registry";
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
} from "../../../../src/runtime/config/board_definition";
import { sixPlayerMvpConfig } from "../../../../src/runtime/scenarios/six_player_mvp";
import { nightStageContext } from "../../../support/builders/night-stage-context";

const potionOrders: Array<Array<PotionType.Heal | PotionType.Poison>> = [
  [PotionType.Heal, PotionType.Poison],
  [PotionType.Poison, PotionType.Heal],
];

const roles = [Role.Wolf, Role.Witch, Role.Seer, Role.Villager, Role.Villager, Role.Villager];

const potion = (
  potion_type: PotionType,
  target_id = 3,
): Extract<ToolCall, { name: "use_potion" }> => ({
  name: "use_potion",
  args: { potion_type, target_id },
});

function setup(
  knifeVisibility: NonNullable<BoardConfig["witch"]>["knifeVisibility"] = "awa_with_heal_v1",
  potionPolicy: NonNullable<BoardConfig["witch"]>["potionPolicy"] = "awa_one_native_v1",
  locale: "zh-CN" | "en" = "en",
) {
  const config = parseBoardDefinition(
    boardDefinitionFromConfig("witch_policy", {
      ...sixPlayerMvpConfig,
      roleSetups: [...new Set(roles)].map((role) => ({
        role,
        count: roles.filter((x) => x === role).length,
      })),
      witch: { knifeVisibility, potionPolicy },
    }),
  ).config;
  const game = bootstrapGame(config, { fixedRoles: roles, locale });
  const ability = findNightAbility(
    game.world.getComponent(2, COMPONENT.Role),
    "potion",
  )!;
  game.world
    .getComponent(3, COMPONENT.StatusMarks)!
    .add(StatusMark.WolfKillMark);
  const events: GameEvent[] = [];
  const requests: ActionRequest[] = [];
  const act = async (
    actions: (ToolCall | null)[],
    mutate?: (request: ActionRequest, n: number) => void,
  ) => {
    const factory = new GameActionRequestFactory(game.world, events, 1);
    let index = 0;
    await WITCH_NIGHT_STAGES[1].execute(
      nightStageContext({
        world: game.world,
        events,
        state: {
          wolfChatOrder: [],
          endedWolves: new Set(),
          wolfVotes: {},
          wolfTarget: 3,
          seerChecks: [],
        },
        makeRequest: (actorId, allowedTools, extra) =>
          factory.create({
            actorId,
            allowedTools,
            phase: Phase.Night,
            stage: extra.stage,
            context: extra,
            requiresAction: true,
            summary: "Offline witch policy",
          }),
        actionProvider: {
          async getAction(request) {
            requests.push(request);
            const n = index++;
            mutate?.(request, n);
            return actions[n] ?? null;
          },
        },
      }),
    );
  };
  return { ...game, config, ability, events, requests, act };
}

for (const knife of ["awa_with_heal_v1", "awa_always_v1"] as const)
  for (const stock of [0, 1])
    test(`${knife}/heal=${stock}: actual request discloses only the configured knife information`, async () => {
      const game = setup(knife);
      (game.ability.state as { heal: number }).heal = stock;
      await game.act([potion(PotionType.None, 2)]);
      expect(Object.hasOwn(game.requests[0].context, "wolf_target")).toBe(
        knife === "awa_always_v1" || (knife === "awa_with_heal_v1" && stock > 0),
      );
      expect(game.config.witch?.knifeVisibility).toBe(knife);
      expect(
        parseBoardDefinition(boardDefinitionFromConfig("witch_policy", game.config)).config,
      ).toEqual(game.config);
      const projected = projectNightAbility(game.ability, 1);
      if (projected.kind !== "potion") throw new Error("expected_potion");
      expect(projected.state).not.toHaveProperty("potionTurnClosedDay");
      if (knife !== "awa_with_heal_v1") expect(projected.state.knifeVisibility).toBe(knife);
    });

for (const policy of ["awa_one_native_v1", "awa_both_native_experimental_v1"] as const)
  for (const order of potionOrders)
    test(`${policy}/${order.join("→")}: only the native opt-in opens exactly one second turn`, async () => {
      const game = setup("awa_with_heal_v1", policy);
      await game.act(order.map((kind) => potion(kind, kind === PotionType.Heal ? 3 : 4)));
      expect(game.requests).toHaveLength(policy === "awa_both_native_experimental_v1" ? 2 : 1);
      expect(game.events.filter((event) => event.type === "witch_potion_used")).toHaveLength(
        policy === "awa_both_native_experimental_v1" ? 2 : 1,
      );
      expect(game.ability.uses).toBe(policy === "awa_both_native_experimental_v1" ? 2 : 1);
      if (policy === "awa_both_native_experimental_v1") {
        expect(game.ability.state.heal).toBe(0);
        expect(game.ability.state.poison).toBe(0);
        expect(Object.hasOwn(game.requests[1].context, "wolf_target")).toBe(
          order[0] === PotionType.Poison,
        );
      }
      expect(abilityStatus(game.ability, 1)).toBe("used_this_night");
      await game.act([potion(PotionType.Heal)]);
      expect(game.requests).toHaveLength(policy === "awa_both_native_experimental_v1" ? 2 : 1);
    });

for (const first of [null, potion(PotionType.None, 2), potion(PotionType.Heal, 999)])
  test(`both policy: initial ${first?.args.potion_type ?? "no_action"}/${first?.args.target_id ?? ""} is terminal with no resource consumption`, async () => {
    const game = setup("awa_always_v1", "awa_both_native_experimental_v1");
    await game.act([first, potion(PotionType.Poison, 4)]);
    expect(game.requests).toHaveLength(1);
    expect(game.ability.state.heal).toBe(1);
    expect(game.ability.state.poison).toBe(1);
    expect(game.ability.uses).toBe(0);
    await game.act([potion(PotionType.Poison, 4)]);
    expect(game.requests).toHaveLength(1);
  });

test("passing the second native turn closes it without consuming the other bottle", async () => {
  const game = setup("awa_always_v1", "awa_both_native_experimental_v1");
  await game.act([potion(PotionType.Heal), potion(PotionType.None, 2)]);
  expect(game.ability.state.poison).toBe(1);
  expect(game.ability.uses).toBe(1);
  expect(abilityStatus(game.ability, 1)).toBe("used_this_night");
  await game.act([potion(PotionType.Poison, 4)]);
  expect(game.requests).toHaveLength(2);
});

for (const kind of ["copy", "transfer", "gift"] as const)
  test(`${kind}: native two-potion and always-disclose policies cannot widen a foreign resource`, async () => {
    const game = setup("awa_always_v1", "awa_both_native_experimental_v1");
    (
      game.ability as {
        source: import("@ai-werewolf-arena/game-contract").AbilitySource;
      }
    ).source =
      kind === "gift" ? { kind, actorId: 1 } : { kind, actorId: 1, abilityId: "foreign-potion" };
    (game.ability.state as { heal: number }).heal = 0;
    await game.act([potion(PotionType.Poison, 4), potion(PotionType.Heal)]);
    expect(game.requests).toHaveLength(1);
    expect(game.requests[0].context).not.toHaveProperty("wolf_target");
    expect(game.ability.uses).toBe(1);
  });

for (const revoked of ["disabled", "source", "day"] as const)
  test(`second turn ${revoked} revocation does not apply or consume`, async () => {
    const game = setup("awa_always_v1", "awa_both_native_experimental_v1");
    await game.act([potion(PotionType.Heal), potion(PotionType.Poison, 4)], (_request, n) => {
      if (n !== 1) return;
      if (revoked === "disabled") (game.ability as { disabled: boolean }).disabled = true;
      if (revoked === "source")
        (
          game.ability as {
            source: import("@ai-werewolf-arena/game-contract").AbilitySource;
          }
        ).source = { kind: "gift", actorId: 1 };
      if (revoked === "day") (game.ability as { startsOnDay: number }).startsOnDay = 2;
    });
    expect(game.requests).toHaveLength(2);
    expect(game.ability.state.poison).toBe(1);
    expect(game.ability.uses).toBe(1);
    expect(game.events.filter((event) => event.type === "witch_potion_used")).toHaveLength(1);
    expect(game.ability.state.potionTurnClosedDay).toBeUndefined();
  });

for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: role and board disclose both native policy boundaries`, () => {
    const game = setup("awa_always_v1", "awa_both_native_experimental_v1", locale);
    const role = game.world.getComponent(2, COMPONENT.Role)!;
    for (const prompt of [
      captureNativeRolePresentation(WITCH_ROLE_PROFILE.presentation!.id, role, locale, undefined, () => game.world.getComponent(2, COMPONENT.Camp)),
      getDefaultConfigRenderRegistry().renderBoardConfigPrompt(game.config, locale),
    ]) {
      expect(prompt).toContain(locale === "en" ? "even after heal is spent" : "解药耗尽");
      expect(prompt).toContain(locale === "en" ? "copied and gifted" : "复制/赠予");
    }
  });

/**
 * 单元测试用持有中的药瓶回复与演员／目标替换验证毒药生命 scope。原库存、当前躯体和拒绝
 * 提交断言验证 gateway 校验后的最终施加；输入及字面／不可变 fixture 预期保持原样，不运行模型或完整对局。
 */
import { createAliveComponent } from "../../../../src/game/observation/component-presentation";
import { nightStageContext } from "../../../support/builders/night-stage-context";
import { PotionType } from "../../../../src/core";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import {
  Role,
  Phase,
  COMPONENT,
  StatusMark,
  DeathCause,
  type RoleComponent,
  type GameEvent,
  type BoardConfig,
} from "../../../../src/core";
import { sixPlayerMvpConfig } from "../../../../src/runtime/scenarios/six_player_mvp";
import { WITCH_NIGHT_STAGES } from "../../../../src/game/mechanisms/roles/witch/night_stages";
import { findNightAbility } from "../../../../src/game/mechanisms/roles/abilities";
import { getDefaultRoleCatalog } from "../../../../src/game/mechanisms/roles/role-catalog-assembly";
import { GameActionRequestFactory } from "../../../../src/game/engine/action_request_factory";
import { ToolGateway } from "../../../../src/game/gateway/tool_gateway";

import { StatusMarksComponent } from "../../../../src/core/domain/components/status_marks";
import { DamageResolutionSystem } from "../../../../src/core/domain/systems/damage_resolution_system";
import type { NightStageContext } from "../../../../src/game/mechanisms/stages/night/contracts";
const roles = [Role.Wolf, Role.Witch, Role.Seer, Role.Guard, Role.Villager, Role.Villager],
  config: BoardConfig = {
    ...sixPlayerMvpConfig,
    roleSetups: [...new Set(roles)].map((role) => ({
      role,
      count: roles.filter((r) => r === role).length,
    })),
  },
  stage = WITCH_NIGHT_STAGES.find((s) => s.id === "witch_action")!;
const fixture = () => bootstrapGame(config, { fixedRoles: roles }),
  role = (game: ReturnType<typeof fixture>, id: number) =>
    game.world.getComponent(id, COMPONENT.Role)!;
function context(
  game: ReturnType<typeof fixture>,
  events: GameEvent[],
  getAction: NightStageContext["actionProvider"]["getAction"],
  clock = () => true,
) {
  const requests = new GameActionRequestFactory(game.world, events, 1);
  return nightStageContext({
    world: game.world,
    events,
    roleCatalog: getDefaultRoleCatalog(),
    toolGateway: new ToolGateway(),
    isCurrent: clock,
    currentDay: () => 1,
    actionProvider: { getAction },
    makeRequest: (actorId, allowedTools, extra) =>
      requests.create({
        summary: "Offline stage fixture",
        requiresAction: true,
        actorId,
        phase: Phase.Night,
        allowedTools,
        stage: extra.stage,
        context: extra,
      }),
    ensureMarks: (id) => {
      let marks = game.world.getComponent(id, COMPONENT.StatusMarks);
      if (!marks) {
        marks = new StatusMarksComponent();
        game.world.addComponent(id, COMPONENT.StatusMarks, marks);
      }
      return marks;
    },
    state: {
      wolfChatOrder: [],
      endedWolves: new Set(),
      wolfVotes: {},
      wolfTarget: null,
      seerChecks: [],
      poisonClaims: [],
    },
  });
}
for (const change of [
  "actor_revive",
  "target_revive",
  "target_replace",
  "disabled",
  "state",
  "clock",
] as const)
  test(`${change}: a late potion reply never commits into a replaced actor/target scope`, async () => {
    const game = fixture(),
      events: GameEvent[] = [],
      ability = findNightAbility(role(game, 2), "potion")!,
      old = ability.state;
    let current = true;
    const ctx = context(
      game,
      events,
      async () => {
        if (change === "actor_revive" || change === "target_revive") {
          const life = game.world.getComponent(
            change === "actor_revive" ? 2 : 5,
            COMPONENT.Alive,
          )!;
          life.alive = false;
          life.alive = true;
        }
        if (change === "target_replace")
          game.world.addComponent(5, COMPONENT.Alive, createAliveComponent());
        if (change === "disabled") (ability as { disabled: boolean }).disabled = true;
        if (change === "state")
          (
            ability as {
              state: import("@ai-werewolf-arena/game-contract").WitchReadState;
            }
          ).state = structuredClone(ability.state);
        if (change === "clock") current = false;
        return { name: "use_potion", args: { target_id: 5, potion_type: PotionType.Poison } };
      },
      () => current,
    );
    await stage.execute(ctx);
    expect(old.poison).toBe(1);
    expect(ability.uses).toBe(0);
    expect(ability.lastUsedDay).toBeNull();
    expect(ctx.state.poisonClaims).toEqual([]);
    expect(events).toEqual([]);
    expect(
      game.world
