    expect(
      new DamageResolutionSystem().resolve(game.world, {
        awakenedEffects: { shields: [shield], attacks: [attack] },
      }),
    ).toEqual({ deaths: [5], deathSources: { 5: [DeathCause.WolfKill] } });
  });

