test("normal extra knife uses ordinary gun permission and first-night last words, with forbidden compounds denied", () => {
  const cause = DeathCause.AwakenedHiddenKnife;
  expect(permitsDeathShot([cause])).toBe(true);
  expect(permitsDeathShot([cause, DeathCause.WolfKill, DeathCause.Shot])).toBe(true);
  for (const forbidden of [
    DeathCause.Poison,
    DeathCause.Dream,
    DeathCause.Charm,
    DeathCause.Duel,
    DeathCause.Ability,
    DeathCause.MechanicalGuardFailure,
    DeathCause.MerchantBacklash,
  ])
    expect(permitsDeathShot([cause, forbidden])).toBe(false);
  const words = new LastWordsMechanism();
  expect(words.shouldGrantLastWords(Phase.Night, 1, [cause])).toBe(true);
  expect(words.shouldGrantLastWords(Phase.Night, 2, [cause])).toBe(false);
});

/**
 * 单元测试验证借用实例公共 metadata 的具体退役写权与原描述符／方法读取顺序。
 * 输入为真实 native/grant 构造的内存实例、替换访问器和手写失败；预期是原引用、属性和错误前缀。
 * 只调用实例 owner，不验证整板资格、租约、付款、伤害或完整游戏；不生成规则 oracle。
 * 全局方法描述符在 finally 原样恢复，不使用模型、传输或文件。
 */
import { expect, test } from "bun:test";
import { Camp, Role } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../src/core/domain/world";
import { COMPONENT } from "../../../src/core/domain/components/names";
import { createRoleComponent } from "../../../src/game/observation/role-presentation";
import type { GameEvent } from "../../../src/core/domain/events";
import { installNativeAbility } from "../../../src/game/mechanisms/roles/ability_changes";
import { retireBorrowedNightAbility } from "../../../src/game/mechanisms/roles/abilities";
import { grantNightAbility } from "../../../src/game/mechanisms/roles/night-ability-grants";

function instance() {
  const world = new World(),
    sourceId = world.createEntity(),
    targetId = world.createEntity(),
    source = createRoleComponent(Role.Seer),
    target = createRoleComponent(Role.EclipseMaid),
    events: GameEvent[] = [];
  world.addComponent(sourceId, COMPONENT.Role, source);
  world.addComponent(sourceId, COMPONENT.Camp, { camp: Camp.Good });
  world.addComponent(targetId, COMPONENT.Role, target);
  world.addComponent(targetId, COMPONENT.Camp, { camp: Camp.Wolf });
  installNativeAbility(source, "seer_check", {
    lastTarget: null,
    lastIsWerewolf: null,
    history: [],
  });
  const ability = grantNightAbility(
    world,
    targetId,
    {
      id: "copy:eclipse:night:2",
      kind: "seer_check",
      state: { lastTarget: null, lastIsWerewolf: null, history: [] },
      source: { kind: "copy", actorId: sourceId, abilityId: "native:seer_check" },
      sourceDisclosed: true,
      startsOnDay: 2,
      expiresAfterDay: 2,
      maxUses: null,
    },
    events,
  );
  return { ability, target, events };
}

test("retiring a captured instance rewrites disabled data without invoking substituted accessors or relooking up its id", () => {
  const f = instance(),
    state = f.ability.state,
    source = f.ability.source,
    count = f.events.length;
  let reads = 0,
    writes = 0;
  Object.defineProperty(f.ability, "id", { value: "copy:changed" });
  Object.defineProperty(f.ability, "disabled", {
    configurable: true,
    enumerable: true,
    get() {
      reads++;
      return false;
    },
    set(_value: boolean) {
      writes++;
    },
  });
  retireBorrowedNightAbility(() => f.ability);
  expect([reads, writes]).toEqual([0, 0]);
  expect(Object.getOwnPropertyDescriptor(f.ability, "disabled")).toEqual({
    value: true,
    writable: true,
    enumerable: true,
    configurable: true,
  });
  expect(
    (f.target.privateState as { abilities: { "copy:eclipse:night:2": unknown } }).abilities[
      "copy:eclipse:night:2"
    ],
  ).toBe(f.ability);
  expect(f.ability.state).toBe(state);
  expect(f.ability.source).toBe(source);
  expect([
    f.ability.uses,
    f.ability.lastUsedDay,
    f.ability.startsOnDay,
    f.ability.expiresAfterDay,
  ]).toEqual([0, null, 2, 2]);
  expect(f.events.length).toBe(count);
});

test("retirement reads the defineProperty callee before the late captured target and preserves supplier errors", () => {
  const f = instance(),
    descriptor = Object.getOwnPropertyDescriptor(Object, "defineProperty")!,
    define = descriptor.value as typeof Object.defineProperty,
    trace: string[] = [],
    failure = Error("literal_borrowed_target_read_failed");
  let caught: unknown;
  try {
    define(Object, "defineProperty", {
      configurable: true,
      get() {
        trace.push("callee");
        return define;
      },
    });
    retireBorrowedNightAbility(() => {
      trace.push("target");
      return f.ability;
    });
    try {
      retireBorrowedNightAbility(() => {
        trace.push("failed-target");
        throw failure;
      });
    } catch (error) {
      caught = error;
    }
  } finally {
    define(Object, "defineProperty", descriptor);
  }
  expect(trace).toEqual(["callee", "target", "callee", "failed-target"]);
  expect(caught).toBe(failure);
  expect(f.ability.disabled).toBe(true);
});

test("a non-configurable disabled field rejects without rewriting payload or adding lifecycle events", () => {
  const f = instance(),
    state = f.ability.state,
    count = f.events.length;
  Object.defineProperty(f.ability, "disabled", {
    value: false,
    writable: false,
    configurable: false,
  });
  expect(() => retireBorrowedNightAbility(() => f.ability)).toThrow(TypeError);
  expect(f.ability.disabled).toBe(false);
  expect(f.ability.state).toBe(state);
  expect(f.ability.uses).toBe(0);
  expect(f.events.length).toBe(count);
});

/**
 * 单元测试负责四类狼继承名单的缺角色边界。输入为有原工厂生命和实际 Camp、但没有 Role 的实体；Camp 的读取刻意抛错。
 * 独立预期是没有继承事实、没有错误，也不查询 Camp 或调用其 getter；当前阵营单一来源不能扩大参与名单。
 * 每例独立 World 与局部查询探针，不改默认注册表、不推进对局或访问模型。
 */
import { expect, test } from "bun:test";
import { World } from "../../../src/core/domain/world";
import { COMPONENT } from "../../../src/core/domain/components/names";
import { createAliveComponent } from "../../../src/core/domain/components/alive";
import type { CampComponent } from "../../../src/core/domain/components/camp";
import type { GameEvent } from "../../../src/core/domain/events";
import { refreshHiddenWolfInheritance } from "../../../src/game/mechanisms/roles/hidden_wolf/inheritance";
import { refreshGargoyleInheritance } from "../../../src/game/mechanisms/roles/gargoyle/inheritance";
import { refreshMechanicalInheritance } from "../../../src/game/mechanisms/roles/mechanical_wolf/inheritance";
import { refreshAwakenedInheritance } from "../../../src/game/mechanisms/roles/awakened_hidden_wolf/inheritance";

// 四个真实公开刷新入口分别执行，不以通用名单实现或模拟角色状态替代它们。
const inputs = [
  ["hidden wolf", (world: World, events: GameEvent[]) => refreshHiddenWolfInheritance(world, events, 1)],
  ["gargoyle", (world: World, events: GameEvent[]) => refreshGargoyleInheritance(world, events, 1)],
  ["mechanical wolf", (world: World, events: GameEvent[]) => refreshMechanicalInheritance(world, 1, events)],
  ["awakened hidden wolf", (world: World, events: GameEvent[]) => refreshAwakenedInheritance(world, 1, events)],
] as const;

for (const [name, refresh] of inputs) test(`${name} inheritance ignores a live Camp-only entity without touching its Camp`, () => {
  const world = new World(), id = world.createEntity(), events: GameEvent[] = [];
  let campQueries = 0, campReads = 0;
  world.addComponent(id, COMPONENT.Alive, createAliveComponent(true));
  // 真实组件的访问器刻意抛错，证明 Role 缺失的原短路仍发生在新增 Camp 通道之前。
  const camp: CampComponent = { get camp(): never { campReads++; throw new Error("missing_role_camp_must_not_be_read"); } };
  world.addComponent(id, COMPONENT.Camp, camp);
  const original = world.getComponent;
  Object.defineProperty(world, "getComponent", { value: new Proxy(original, {
    apply(target, receiver, args) {
      if (args[1] === COMPONENT.Camp) campQueries++;
      return Reflect.apply(target, receiver, args);
    },
  }) });
  expect(() => refresh(world, events)).not.toThrow();
  expect(events).toEqual([]);
  expect(campQueries).toBe(0);
  expect(campReads).toBe(0);
});

