test("Lucky actual death permanently expires an unused gift, and neither revival, enable, transfer nor copying restores it", async () => {
  const game = fixture(),
    events: GameEvent[] = [],
    gift = grantNightAbility(
      game.world,
      6,
      {
        id: "gift:miracle",
        kind: "seer_check",
