        state: seer(),
        source: { kind: "gift", actorId: 3 },
        startsOnDay: 1,
        maxUses: 1,
      },
      events,
    );
  const state = { day: 2, phase: Phase.Day, gameOver: false, result: null };
  await new DeathResolution(
    game.world,
    events,
    new ToolGateway(),
    new EventRegistry(),
    state,
  ).resolve(
    [6],
