/**
 * Unit tests check concrete Demon/Wedding acquisition and cleanup ownership.
 * Inputs are original installed Worlds, explicit setup choices and instrumented
 * World/events getters; live scope authorization, literal traces and original
 * opening facts are the oracle. Failed begin and failed capture retain their
 * different cleanup policies. No phase cycle, model, recording or transport runs.
 */
import "../../../src/app/bootstrap";
import { expect, test } from "bun:test";
import { World, Phase, type GameEvent } from "../../../src/core";
import { bootstrapGame } from "../../../src/app/bootstrap";
import { DemonNightUnit, demonNightTerminal } from "../../../src/game/mechanisms/roles/demon_hunter/ports";
import { WeddingNightUnit, weddingNightTerminal } from "../../../src/game/mechanisms/roles/ghost_bride/ports";
import {
  authorizedDemonHunter,
  bindDemonHunterRequest,
  type DemonHunterRequest,
  openDemonHunterTurn,
} from "../../../src/game/mechanisms/roles/demon_hunter/authority";
import {
  beginWeddingSetup,
  bindGhostBrideRequest,
  openWeddingTurn,
  commitWeddingTool,
  closeWeddingTurn,
  takeWeddingChat,
  ghostBrideReady,
  authorizedWeddingTurn,
  weddingNightCapture,
} from "../../../src/game/mechanisms/roles/ghost_bride/authority";
import { demonHunterFixture } from "../../support/features/demon-hunter/builders/candidate-world";
import { ghostBrideBoard, ghostBrideDeck } from "../../support/features/ghost-bride/builders/scenario";

function boundWeddingTurn(world: World, kind: "bridegroom" | "chat" | "witness" | "knife", actorId: number) {
  const scope = openWeddingTurn(world, kind, actorId, 1, () => true);
  const tool = kind === "bridegroom" ? "choose_bridegroom" : kind === "chat" ? "speak_to_partner" : kind === "witness" ? "choose_wedding_witness" : "kill_vote";
  const stage = kind === "bridegroom" ? "ghost_bride_groom" : kind === "chat" ? "ghost_bride_chat" : kind === "witness" ? "ghost_bride_witness" : "wolf_vote";
  const request = {
    actorId, phase: Phase.Night, allowedTools: [tool],
    context: {
      day: 1, stage, allow_fallback: false, action_failure_policy: "error",
      turn_constraints: { min_valid_actions: 1, max_valid_actions: 1, required_any_tools: [tool] },
    },
  };
  bindGhostBrideRequest(world, request);
  return scope;
}

function weddingWorld() {
  const config = ghostBrideBoard();
  const { world, boardConfig } = bootstrapGame(config, { fixedRoles: ghostBrideDeck });
  beginWeddingSetup(world, boardConfig, () => true);
  const choose = (
    kind: "bridegroom" | "chat" | "witness",
    actor: number,
    call: unknown,
  ) => {
    const scope = boundWeddingTurn(world, kind, actor);
    expect(commitWeddingTool(scope, call)).toBe(true);
    if (kind === "chat") expect(takeWeddingChat(scope)).not.toBeNull();
    closeWeddingTurn(scope);
  };
  choose("bridegroom", 1, { name: "choose_bridegroom", args: { target_id: 2 } });
  for (const actor of [1, 2])
    choose("chat", actor, { name: "speak_to_partner", args: { text: "" } });
  for (const actor of [1, 2])
    choose("witness", actor, { name: "choose_wedding_witness", args: { target_id: 3 } });
  expect(ghostBrideReady(world)).toBe(true);
  return world;
}

function boundDemonTurn(world: World, actorId: number) {
  const scope = openDemonHunterTurn(world);
  const request: DemonHunterRequest = {
    actorId, phase: Phase.Night, allowedTools: ["demon_hunt"],
    context: {
      day: 2, stage: "demon_hunter", requiresAction: true,
      allow_fallback: false, action_failure_policy: "error",
      turn_constraints: { min_valid_actions: 1, max_valid_actions: 1, required_any_tools: ["demon_hunt"] },
    },
  };
  bindDemonHunterRequest(world, request);
  return scope;
}

