import type { NightAbilityStates } from "@ai-werewolf-arena/game-contract";

import "../../../src/app/bootstrap";
import { expect, test } from "bun:test";
import { Camp, Role, WitchSelfHealRule } from "@ai-werewolf-arena/game-contract";
