test("猎魔和婚礼构造getter失败仍关闭try内原许可而不补交选择", async () => {
  const game = demonHunterFixture(), events: GameEvent[] = [], trace: string[] = [], failure = new Error("literal_inside_factory_failure");
  const construction = { get requestFactory(): never { trace.push("factory"); throw failure; } };
  beginDemonHunterNight(game.world, 2, () => true);
  try {
    await expect(executeDemonHunterTurn({ world: game.world, gateway: game.gateway, events, provider: noProvider, day: 2, construction })).rejects.toBe(failure);
    const request = new GameActionRequestFactory(game.world, events, 2).create({ phase: Phase.Night, actorId: 6, allowedTools: ["demon_hunt"], stage: "demon_hunter", requiresAction: true, summary: { key: "request.summary.night_action" } });
    // 若原 finally 未关闭 turn，真实绑定会取得该scope；这里不伪造新的许可或成功选择。
    bindDemonHunterRequest(game.world, request);
    expect(demonHunterRequestScope(game.world, request)).toBeUndefined();
    expect(events).toEqual([]);
  } finally { closeDemonHunterNight(game.world); }
  const wedding = bootstrapGame(ghostBrideBoard(), { fixedRoles: ghostBrideDeck });
  const before = JSON.stringify(wedding.world.getComponent(1, COMPONENT.Role)!.privateState);
  beginWeddingSetup(wedding.world, wedding.boardConfig, () => true);
  try {
    await expect(executeWeddingTurn({ world: wedding.world, gateway: new ToolGateway(), events, provider: noProvider, day: 1, actorId: 1, kind: "bridegroom", tool: "choose_bridegroom", stage: "ghost_bride_groom", isCurrent: () => true, construction })).rejects.toBe(failure);
    // 同一原体能再次开原opaque turn，证明失败只关闭该turn；尚未提交配对或耗尽设置库存。
    const scope = openWeddingTurn(wedding.world, "bridegroom", 1, 1, () => true);
    closeWeddingTurn(scope);
    expect(JSON.stringify(wedding.world.getComponent(1, COMPONENT.Role)!.privateState)).toBe(before);
    expect(trace).toEqual(["factory", "factory"]);
    expect(events).toEqual([]);
  } finally { closeWeddingSetup(wedding.world, "failed"); }
});

