      {
        targets() {
          trace.push("mist");
          return row.stop === "mist" ? [2] : null;
        },
      },
      {
        allows() {
          trace.push("noble");
          return row.stop !== "noble";
        },
      },
      {
        allows() {
          trace.push("evil");
          return row.stop !== "evil";
