        return { id, name: String(id), role: role.role, camp: game.world.getComponent(id, COMPONENT.Camp)!.camp };
      }),
    },
    () => {},
  );
  recorder.checkpoint(
    captureCheckpoint(game.world, game.phaseManager.getSnapshot(), 0, true, 0),
    [],
  );
  return recorder.build();
}

