/**
 * 单元测试验证私有状态编码的普通整容器克隆和原 callee／getter 失败顺序。
 * 输入是独立手工角色、共享引用与合法 getter；字面引用关系、读取轨迹及同一错误是预期，
 * 不从另一个生产编码器生成答案。测试只控制自有状态及临时 clone 查找，finally 恢复全局字段；
 * 宽克隆结果不等于后续 JSON 归档接受或行动授权，不推进对局、不写档案或调用模型。
 */
import { expect, test } from "bun:test";
import { Role, Camp } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../src/core/domain/world";
import { createRoleComponent } from "../../../src/core/domain/components/role";
import { encodeCheckpointPrivateState } from "../../../src/recording/checkpoint/private-state-codec";

test("ordinary codec keeps full-container aliases, cycles, undefined and legal getter values", () => {
  const world = new World("en"),
    role = createRoleComponent(Role.Villager),
    shared = { amount: 2 },
    reads: string[] = [],
    container: Record<string, unknown> = {
      left: shared,
      right: shared,
      optional: undefined,
      get legal() {
        reads.push("legal-getter");
        return shared;
      },
    };
  container.self = container;
  Object.defineProperty(role, "privateState", { value: container });
  const result = encodeCheckpointPrivateState(world, 1, true, null, null, role, null);
  expect(reads).toEqual(["legal-getter"]);
  expect(result).not.toBe(container);
  expect(result.left).not.toBe(shared);
  expect(result.left).toBe(result.right);
  expect(result.legal).toBe(result.left);
  expect(result.self).toBe(result);
  expect(Object.hasOwn(result, "optional")).toBe(true);
  expect(result.optional).toBeUndefined();
  expect(result.left).toEqual({ amount: 2 });
});

test("ordinary codec finds clone callee before private-state getter and preserves its failure", () => {
  const world = new World("en"),
    role = createRoleComponent(Role.Villager),
    trace: string[] = [],
    failure = new Error("test_private_state_getter_failed"),
    cloneDescriptor = Object.getOwnPropertyDescriptor(globalThis, "structuredClone")!;
  Object.defineProperty(role, "privateState", {
    get() {
      trace.push("private-state");
      throw failure;
    },
  });
  // 只在本案例将原全局可配置字段换为查找探针；getter 抛错前不得进入 clone 调用。
  Object.defineProperty(globalThis, "structuredClone", {
    configurable: true,
    get() {
      trace.push("clone-callee");
      return () => {
        trace.push("clone-call");
        throw new Error("unexpected_clone_call");
      };
    },
  });
  let caught: unknown;
  try {
    encodeCheckpointPrivateState(world, 1, false, null, null, role, null);
  } catch (error) {
    caught = error;
  } finally {
    Object.defineProperty(globalThis, "structuredClone", cloneDescriptor);
  }
  expect(caught).toBe(failure);
  expect(trace).toEqual(["clone-callee", "private-state"]);
});

/**
 * 单元测试：验证赤月归档中自爆、封印及原生决定的因果事实。输入为原字面记录；事件相邻性与后续夜拒绝断言为预期，不执行模型或完整对局驱动。
 */
import { validateDemonHunterRecord } from "../../../src/verification/reproduction/demon-hunter/validate";
import { expect, test } from "bun:test";
import { redMoonCandidateWorld } from "../../support/features/red-moon/builders/candidate-world";
import { COMPONENT, type RoleComponent } from "../../../src/core";
import type { ReproductionRecord } from "../../../src/recording/reproduction";
import { validateRedMoonRecord } from "../../../src/verification/reproduction/red-moon/validate";
function fixture(policy: "ends_game" | "forbidden" = "ends_game"): any {
  const { world, config } = redMoonCandidateWorld(policy);
  return {
    finalized: true,
    metadata: {
      normalizedBoard: config,
      players: world.entityIds().map((id) => {
        const role = world.getComponent(id, COMPONENT.Role)!;
        return { id, role: role.role, camp: world.getComponent(id, COMPONENT.Camp)!.camp };
      }),
    },
    events: [],
    operations: [],
    decisions: [],
    checkpoints: [{ complete: true, players: [], eventCount: 0 }],
  };
}
function event(r: any, type: string, payload: any) {
  r.events.push({ type, payload });
}
function phase(r: any, day: number, value: string) {
  event(r, "phase_changed", { day, phase: value });
}
function frozen(r: any, day: number, deaths: number[]) {
  r.operations.push({ op: "demon_hunter_sources_frozen", output: { day, deaths } });
}
function deferred() {
  const r = fixture();
  phase(r, 1, "night");
  frozen(r, 1, [1, 2, 3]);
  event(r, "night_resolved", { deaths: [1, 2, 3] });
  phase(r, 1, "voting");
  event(r, "vote_summary", { target: 4 });
  event(r, "red_moon_exile_delayed", { actorId: 4, day: 1, night: 2 });
  phase(r, 2, "night");
  return r;
}
function expiry(r: any) {
  event(r, "red_moon_delay_expired", { actorId: 4, day: 2 });
  r.operations.push({
    op: "red_moon_expiry_settled",
    scope: "resolution",
    phase: "night",
    status: "ok",
    output: { actorId: 4, day: 2, cause: "red_moon_expiry" },
  });
}
test("Red Moon serialized blast requires the adjacent real blast and records only its following night", () => {
  const r = fixture();
  phase(r, 1, "day");
  event(r, "wolf_self_destruct", { wolfId: 4 });
  event(r, "red_moon_night_sealed", { actorId: 4, day: 1, night: 2 });
  const audit = validateRedMoonRecord(r as ReproductionRecord)!;
  expect([...audit.sealedNights]).toEqual([2]);
  expect(audit.stateAt(r.events.length).blastDay).toBe(1);
  r.events.splice(1, 1);
  expect(() => validateRedMoonRecord(r)).toThrow();
});
test("A sealed night cannot contain a good native decision", () => {
  const r = fixture();
  phase(r, 1, "day");
  event(r, "wolf_self_destruct", { wolfId: 4 });
  event(r, "red_moon_night_sealed", { actorId: 4, day: 1, night: 2 });
  r.decisions.push({ day: 2, stage: "seer", request: { context: { visible_events: [] } } });
  expect(() => validateRedMoonRecord(r)).toThrow();
});
test("Serialized deferred expiry requires ordinary settlement, remaining good sides and the exact late source", () => {
  const r = deferred();
  frozen(r, 2, [5]);
  expiry(r);
  event(r, "night_resolved", { deaths: [5, 4] });
  const audit = validateRedMoonRecord(r)!;
  expect(audit.expiredNights.get(2)).toBe(4);
  expect(audit.stateAt(r.events.length).expirySettled).toBe(true);
  r.operations.at(-1).output.actorId = 5;
  expect(() => validateRedMoonRecord(r)).toThrow();
});
test("An ordinary last knife ending the game skips expiry", () => {
  const r = deferred();
  frozen(r, 2, [5, 6, 7, 8]);
  event(r, "night_resolved", { deaths: [5, 6, 7, 8] });
  expect(validateRedMoonRecord(r)!.expiredNights.size).toBe(0);
  r.events.pop();
  expiry(r);
  event(r, "night_resolved", { deaths: [5, 6, 7, 8, 4] });
  expect(() => validateRedMoonRecord(r)).toThrow();
});
test("Missing expiry and duplicate death are rejected in completed night facts", () => {
  const r = deferred();
  frozen(r, 2, [5]);
  event(r, "night_resolved", { deaths: [5] });
  expect(() => validateRedMoonRecord(r)).toThrow();
  r.events.pop();
  expiry(r);
  event(r, "night_resolved", { deaths: [5, 4, 4] });
  expect(() => validateRedMoonRecord(r)).toThrow();
});
test("Ordinary damage already killing Red Moon does not require another expiry", () => {
  const r = deferred();
  frozen(r, 2, [4]);
  event(r, "night_resolved", { deaths: [4] });
  expect(validateRedMoonRecord(r)!.expiredNights.size).toBe(0);
