      Role.Villager, Role.Villager, Role.Villager, Role.Villager,
      Role.RavenClawWolf, Role.Wolf, Role.Wolf, Role.Wolf],
  });
  beginMistNight(game.world, 1);
  commitMistChoice(game.world, 1, [10, 11, 12]);
  const trace: string[] = [], failure = new Error("draw_publication_failure");
  const ctx = nightStageContext({ world: game.world, pickMajorityTarget: () => null });
  const state = ctx.state, votes = state.wolfVotes, events = ctx.events;
  Object.defineProperty(state, "wolfVotes", { get() { trace.push("votes:get"); return votes; } });
  Object.defineProperty(ctx, "pickMajorityTarget", { get() {
    trace.push("majority:get");
    return function (this: NightStageContext, input: Record<number, number>) {
      trace.push("majority:call"); expect(this).toBe(ctx); expect(input).toBe(votes); return null;
    };
  } });
  Object.defineProperty(ctx, "world", { get() { trace.push("world:get"); return game.world; } });
  Object.defineProperty(ctx, "pickMistKnife", { get() {
    trace.push("rng:get");
    return function (this: NightStageContext, circle: readonly number[]) {
      trace.push("rng:call"); expect(this).toBe(ctx); expect(circle).toEqual([10, 11, 12]); return 11;
    };
  } });
  ctx.currentDay = () => { trace.push("day:call"); return 1; };
  Object.defineProperty(ctx, "events", { get() { trace.push("events:get"); return events; } });
  Object.defineProperty(events, "push", { value() { trace.push("draw:push"); throw failure; } });
  let thrown: unknown;
  try { resolveOrdinaryWolfKnife(ctx, [], [10, 11, 12], new Set([10, 11, 12])); }
  catch (error) { thrown = error; }
  expect(thrown).toBe(failure);
  expect(trace).toEqual(["majority:get", "votes:get", "majority:call", "world:get", "world:get",
    "rng:get", "rng:get", "rng:call", "world:get", "day:call", "events:get", "world:get", "day:call", "draw:push"]);
