test("scope setter failure follows current mapping and real mark without refund", () => {
  const { ctx, world, accepted } = ordinary(), trace: string[] = [], state = ctx.state;
  const mappedId = world.createEntity(), mappedLife = createAliveComponent(), marks = new StatusMarksComponent();
  world.addComponent(mappedId, COMPONENT.Alive, mappedLife);
  const failure = new Error("scope_setter_failure"), add = marks.add;
  let marked = false, attempted: WolfKnifeTargetScope | undefined;
  Object.defineProperty(marks, "add", { value(this: StatusMarksComponent, mark: StatusMark) {
    trace.push("mark:add"); add.call(this, mark); marked = true;
  } });
  const effects = { ...ctx.nativeNightEffects, recordKnifeModifierTarget() { trace.push("effect"); } };
  Object.defineProperty(ctx, "nativeNightEffects", { value: effects });
  const mapping = {
    requestedId: 1, effectiveId: 2,
    get scope() { trace.push("mapping:scope"); return { id: mappedId, life: mappedLife, version: 0 }; },
    isCurrent() { trace.push("mapping:current"); expect(this).toBe(mapping); return true; },
  };
  const targets = { ...ctx.nativeNightTargets, mappedTarget(day: () => number, target: () => number) {
    trace.push("mapping:call"); expect(this).toBe(targets); trace.push(`day:${day()}`, `target:${target()}`); return mapping;
  } };
  Object.defineProperty(ctx, "nativeNightTargets", { get() { trace.push("mapping:get"); return targets; } });
  ctx.ensureMarks = function (id) { trace.push(`ensure:${id}`); expect(this).toBe(ctx); return marks; };
  Object.defineProperty(ctx, "state", { get() { if (marked) trace.push("state:lvalue"); return state; } });
  Object.defineProperty(state, "wolfTargetScope", { set(value: WolfKnifeTargetScope) {
    trace.push("scope:set"); attempted = value; throw failure;
  } });
  let thrown: unknown;
  try { resolveOrdinaryWolfKnife(ctx, accepted, [8], new Set()); }
  catch (error) { thrown = error; }
  expect(thrown).toBe(failure);
  expect(trace).toEqual(["effect", "mapping:get", "mapping:call", "day:1", "target:1", "mapping:current",
    "ensure:2", "mark:add", "state:lvalue", "mapping:scope", "mapping:scope", "scope:set"]);
  expect(marks.has(StatusMark.WolfKillMark)).toBe(true);
  expect(state.wolfTarget).toBe(1);
  expect(state.wolfTargetVoters).toEqual([8]);
  expect(attempted?.targetId).toBe(2);
  expect(attempted?.life).toBe(mappedLife);
  expect(attempted?.marks).toBe(marks);
});

